TEST(MobileDalvikJava, LargeDispatchPreservesBranchAndExactExceptionPC) {
  constexpr uint32_t Join = 3002;
  std::vector<Instruction> ops{
      op(0, "const/4", {0}, int64_t(0)), op(1, "if-eqz", {2}, {}, {}, Join)};
  for (uint32_t pc = 2; pc < Join; ++pc)
    ops.push_back(op(pc, "add-int/lit8", {0, 0}, int64_t(1)));
  ops.push_back(op(Join, "move", {0, 0}));
  ops.push_back(op(Join + 1, "div-int", {0, 0, 2}));
  ops.push_back(op(Join + 2, "return", {0}));
  ops.push_back(op(Join + 3, "move-exception", {1}));
  ops.push_back(op(Join + 4, "const/16", {0}, int64_t(77)));
  ops.push_back(op(Join + 5, "return", {0}));
  auto m = method("run", {"I"}, "I", 3, std::move(ops),
                  {{Join + 1, Join + 2,
                    {{std::string("Ljava/lang/ArithmeticException;"),
                      Join + 3}}}});
  auto report = recover({klass("Lfixture/Core;", {std::move(m)})});
  EXPECT_EQ(report.getInteger("unrecovered_method_count"), 0);
  const auto *units = report.getArray("source_units");
  ASSERT_NE(units, nullptr);
  ASSERT_EQ(units->size(), 1u);
  const auto source = units->front().getAsObject()->getString("source");
  ASSERT_TRUE(source.has_value());
  EXPECT_TRUE(source->contains("case 3002:"));
  EXPECT_TRUE(source->contains("pc = 3003;"));
  EXPECT_FALSE(source->contains("case 3003:"));
  EXPECT_TRUE(source->contains("case 3005:"));
}

