std::vector<Class> staticSuperAccessorClasses(bool Dependency, bool Range) {
  auto Ping = method("ping", {}, "V", 1, {op(0, "return-void")});
  Ping.access = {"public"};
  auto Conflict = Ping;
  Conflict.reference.name = "__neverdSuper0";
  Conflict.access.insert("final");
  auto Base = klass("Lfixture/Base;", {Ping, Conflict});
  auto Root = klass("Lfixture/Root;");
  Root.superclass = Base.name;
  auto Forward = method("access$ping", {"Lfixture/Host;"}, "V", 2,
                        {op(0, Range ? "invoke-super/range" : "invoke-super",
                            {1}, {}, MethodRef{Root.name, "ping", {}, "V"}),
                         op(1, "return-void")});
  Forward.access = {"public", "static", "final", "synthetic"};
  auto Host = klass("Lfixture/Host;", {Forward, Ping});
  Host.superclass = Root.name;
  if (Dependency) {
    Base.external = Root.external = true;
    for (auto &M : Base.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  }
  return {Host, Root, Base};
}

TEST(MobileDalvikJava,
     StaticSuperAccessorKeepsItsStaticEntryAndPrivateDispatch) {
  for (bool Dependency : {false, true})
    for (bool Range : {false, true})
      for (bool Linked : {false, true}) {
        auto Input = staticSuperAccessorClasses(Dependency, Range);
        Budget B;
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        std::string Text;
        for (const auto &Value : *R.getArray("source_units")) {
          const auto &Unit = *Value.getAsObject();
          if (Unit.getString("class") == "Lfixture/Host;")
            Text = Unit.getString("source")->str();
        }
        EXPECT_NE(Text.find("static final void access$ping(fixture.Host arg0)"),
                  std::string::npos);
        EXPECT_NE(Text.find("arg0.__neverdSuper1();"), std::string::npos);
        EXPECT_NE(Text.find("private void __neverdSuper1()"),
                  std::string::npos);
        EXPECT_NE(Text.find("super.ping();"), std::string::npos);
        const auto *Helpers = R.getArray("generated_source_helpers");
        ASSERT_NE(Helpers, nullptr);
        unsigned SuperHelpers = 0;
        for (const auto &Value : *Helpers) {
          const auto &Helper = *Value.getAsObject();
          if (Helper.getString("kind") == "super-dispatch-helper") {
            ++SuperHelpers;
            EXPECT_EQ(Helper.getString("class"), "Lfixture/Host;");
            EXPECT_EQ(Helper.getString("name"), "__neverdSuper1");
            EXPECT_EQ(Helper.getString("prototype"), "()V");
            EXPECT_EQ(Helper.getBoolean("static"), false);
          }
        }
        EXPECT_EQ(SuperHelpers, 1u);
        for (const auto &Value : *R.getArray("methods")) {
          const auto &Method = *Value.getAsObject();
          if (Method.getString("name") == "access$ping") {
            EXPECT_EQ(Method.getString("projection_kind"),
                      "static-super-accessor");
            EXPECT_EQ(Method.getString("source_identity"),
                      "Lfixture/Host;->access$ping(Lfixture/Host;)V");
            EXPECT_EQ(Method.getString("super_dispatch_helper"),
                      "Lfixture/Host;->__neverdSuper1()V");
            ASSERT_NE(Method.getArray("metadata_differences"), nullptr);
            EXPECT_EQ(Method.getArray("metadata_differences")->size(), 2u);
          }
        }
      }
}

TEST(MobileDalvikJava,
     StaticSuperAccessorRejectsUnprovedForwardingAndAncestry) {
  for (unsigned Mutation = 0; Mutation < 11; ++Mutation)
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(Mutation);
      auto Input = staticSuperAccessorClasses(false, false);
      auto &Forward = Input[0].methods[0];
      if (Mutation == 0)
        Forward.access.erase("synthetic");
      else if (Mutation == 1)
        Forward.reference.parameters = {Input[2].name};
      else if (Mutation == 2)
        Forward.instructions[0].registers = {0};
      else if (Mutation == 3) {
        Forward.instructions.push_back(op(2, "return-void"));
        ++Forward.code_end;
      } else if (Mutation == 4)
        Forward.access.insert("synchronized");
      else if (Mutation == 5) {
        Forward.instructions.push_back(op(2, "move-exception", {0}));
        Forward.instructions.push_back(op(3, "throw", {0}));
        Forward.code_end = 4;
        Forward.tries = {{0, 1, {{std::nullopt, 2}}}};
      } else if (Mutation == 6)
        Input.pop_back();
      else if (Mutation == 7) {
        auto &Target = Input[2].methods[0];
        Target.access.insert("abstract");
        Target.instructions.clear();
        Target.registers = Target.code_end = 0;
        Input[2].access.insert("abstract");
      } else if (Mutation == 8)
        Input[2].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 9)
        std::get<MethodRef>(Forward.instructions[0].reference).owner =
            Input[2].name;
      else
        Input[2].methods[0].generic_signature = "<T:Ljava/lang/Object;>()V";
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> interfaceDefaultAccessorClasses(const std::string &Type,
                                                   bool Range) {
  auto Work =
      method("work", {"J", "Ljava/lang/Object;"}, Type, 5,
             Type == "V"   ? std::vector<Instruction>{op(0, "return-void")}
             : Type == "J" ? std::vector<Instruction>{op(0, "return-wide", {2})}
             : Type == "I"
                 ? std::vector<Instruction>{op(0, "const/4", {0}, int64_t(7)),
                                            op(1, "return", {0})}
                 : std::vector<Instruction>{op(0, "return-object", {4})});
  Work.access = {"public"};
  auto Api = klass("Lfixture/DefaultApi;", {Work});
  Api.access = {"public", "interface", "abstract"};
  auto Forward =
      method("access$work$jd", {Api.name, "J", "Ljava/lang/Object;"}, Type, 5,
             {op(0, Range ? "invoke-super/range" : "invoke-super", {1, 2, 3, 4},
                 {}, Api.methods[0].reference)});
  Forward.access = {"public", "static", "synthetic"};
  if (Type != "V")
    Forward.instructions.push_back(op(1,
                                      Type == "J"   ? "move-result-wide"
                                      : Type == "I" ? "move-result"
                                                    : "move-result-object",
                                      {0}));
  Forward.instructions.push_back(
      op(Forward.instructions.size(),
         Type == "V"   ? "return-void"
         : Type == "J" ? "return-wide"
         : Type == "I" ? "return"
                       : "return-object",
         Type == "V" ? std::vector<unsigned>{} : std::vector<unsigned>{0}));
  Forward.code_end = Forward.instructions.size();
  Forward.reference.owner = Api.name;
  Api.methods.push_back(Forward);
  auto Impl = klass("Lfixture/DefaultImpl;", {Work});
  Impl.interfaces = {Api.name};
  return {Api, Impl};
}

