std::vector<Class> protectedAbstractIdentifierClasses(bool External, bool Range,
                                                      bool Symbolic) {
  const std::string Object = "Ljava/lang/Object;";
  auto Base = klass("Lapi/Base;");
  Base.external = External;
  auto Slot = method("choose-value", {Object, "J"}, "Z", 0, {});
  Slot.access = {"protected", "abstract"};
  auto Root = klass("Lapi/Root;", {Slot});
  Root.access = {"public", "abstract"};
  Root.superclass = Base.name;
  auto Run = method("run", {Object, "J"}, "Z", 5,
                    {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                        {1, 2, 3, 4}, {}, Root.methods[0].reference),
                     op(1, "move-result", {0}), op(2, "return", {0})});
  Run.access = {"public"};
  Run.reference.owner = Root.name;
  Root.methods.push_back(Run);
  Slot.access = {"protected", "final"};
  Slot.registers = 5;
  Slot.instructions = {op(0, "const/4", {0}, int64_t(0)), op(1, "return", {0})};
  Slot.code_end = 2;
  auto Left = klass("Limpl/Left;", {Slot});
  Left.superclass = Root.name;
  if (Symbolic)
    std::get<MethodRef>(Run.instructions[0].reference).owner = Left.name;
  Run.reference.owner = Left.name;
  Left.methods.push_back(Run);
  Slot.access.erase("final");
  Slot.instructions[0].literal = int64_t(1);
  auto Right = klass("Limpl/Right;", {Slot});
  Right.access = {"final"};
  Right.superclass = Root.name;
  Run.reference.owner = Right.name;
  std::get<MethodRef>(Run.instructions[0].reference).owner =
      Symbolic ? Right.name : Root.name;
  Right.methods.push_back(Run);
  auto Peer = method("call", {Root.name, Object, "J"}, "Z", 5,
                     {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                         {1, 2, 3, 4}, {}, Root.methods[0].reference),
                      op(1, "move-result", {0}), op(2, "return", {0})});
  return {Root, Left, Right, klass("Lapi/Peer;", {Peer}), Base};
}

TEST(MobileDalvikJava,
     ProtectedAbstractIdentifiersRetainCompleteVirtualFamily) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Symbolic : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input =
              protectedAbstractIdentifierClasses(External, Range, Symbolic);
          const auto Root = Input[0].methods[0].reference;
          std::set<std::string> Family;
          for (unsigned I = 0; I < 3; ++I)
            Family.insert(Input[I].methods[0].reference.identity());
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R = recoverJava(linkClasses(Input, B), B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 3);
          unsigned Count = 0;
          for (const auto &V : *R.getArray("methods")) {
            const auto &Row = *V.getAsObject();
            if (Row.getString("name") != Root.name)
              continue;
            ++Count;
            EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod0");
            EXPECT_EQ(Row.getString("source_name_declaration"),
                      Root.identity());
            ASSERT_NE(Row.getArray("source_name_family"), nullptr);
            std::set<std::string> Actual;
            for (const auto &F : *Row.getArray("source_name_family"))
              Actual.insert(F.getAsString()->str());
            EXPECT_EQ(Actual, Family);
          }
          EXPECT_EQ(Count, 3U);
          std::string Text;
          for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
            Text += source(R, I);
          if (!Symbolic)
            EXPECT_NE(Text.find("this.__neverdVirtualMethod0("), Text.npos);
          EXPECT_NE(Text.find("protected abstract boolean "
                              "__neverdVirtualMethod0("),
                    Text.npos);
        }
}

TEST(MobileDalvikJava, ProtectedAbstractIdentifiersRejectIncompleteContracts) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 11; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = protectedAbstractIdentifierClasses(true, false, true);
      auto &Root = Input[0], &Left = Input[1], &Right = Input[2];
      if (Mutation == 0)
        Root.external = true;
      else if (Mutation == 1) {
        Right.external = true;
        Right.methods.resize(1);
        Right.methods[0].instructions.clear();
        Right.methods[0].registers = Right.methods[0].code_end = 0;
      } else if (Mutation == 2)
        Left.superclass = "Lmissing/Parent;";
      else if (Mutation == 3)
        Left.interfaces.push_back("Lmissing/Contract;");
      else if (Mutation == 4)
        Right.methods[0].access = {"private"};
      else if (Mutation == 5)
        Right.methods[0].access.insert("static");
      else if (Mutation == 6) {
        auto Other = Left.methods[0];
        Other.reference.parameters = {"Ljava/lang/Object;"};
        Other.registers = 2;
        Left.methods.push_back(std::move(Other));
      } else if (Mutation == 7) {
        auto &Call = Left.methods[1];
        Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                         Root.name);
        ++Call.registers;
        Call.instructions[0].registers = {2, 3, 4, 5};
        std::get<MethodRef>(Call.instructions[0].reference).owner = Root.name;
      } else if (Mutation == 8) {
        auto Foreign = Input[3];
        Foreign.name = "Limpl/Foreign;";
        for (auto &M : Foreign.methods)
          M.reference.owner = Foreign.name;
        Input.push_back(std::move(Foreign));
      } else if (Mutation == 9)
        Root.methods[0].generic_signature = "<T:Ljava/lang/Object;>(TT;J)Z";
      else {
        auto Metadata = klass("Lapi/Metadata;");
        Metadata.external = true;
        Metadata.inner_class_present = true;
        Metadata.enclosing_method = Root.methods[0].reference;
        Input.push_back(std::move(Metadata));
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

