std::vector<Class> publicAbstractIdentifierClasses(bool External, bool Range,
                                                   bool Symbolic, bool Mixed) {
  auto Input = protectedAbstractIdentifierClasses(External, Range, Symbolic);
  for (auto &C : Input)
    for (auto &M : C.methods)
      if (M.reference.name == "choose-value") {
        M.access.erase("protected");
        M.access.insert("public");
      }
  if (Mixed) {
    auto Slot = Input[0].methods[0];
    auto Api = klass("Lapi/Other;", {Slot});
    Api.access = {"public", "abstract", "interface"};
    auto Body = Input[1].methods[0];
    Body.access.erase("final");
    auto Edge = klass("Limpl/Edge;", {Body});
    Edge.interfaces = {Api.name};
    Input.push_back(std::move(Api));
    Input.push_back(std::move(Edge));
  }
  return Input;
}

TEST(MobileDalvikJava, PublicAbstractIdentifiersRetainEachCompleteRoot) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Symbolic : {false, true})
        for (bool Mixed : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input = publicAbstractIdentifierClasses(External, Range,
                                                         Symbolic, Mixed);
            const auto Root = Input[0].methods[0].reference;
            const auto Other = Mixed ? Input[5].methods[0].reference : Root;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R = recoverJava(linkClasses(Input, B), B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), Mixed ? 5 : 3);
            unsigned Count = 0;
            for (const auto &V : *R.getArray("methods")) {
              const auto &Row = *V.getAsObject();
              if (Row.getString("name") != Root.name)
                continue;
              ++Count;
              EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod0");
              const auto Owner = Row.getString("class");
              const bool Interface =
                  Owner == "Lapi/Other;" || Owner == "Limpl/Edge;";
              EXPECT_EQ(Row.getString("source_name_declaration"),
                        (Interface ? Other : Root).identity());
              ASSERT_NE(Row.getArray("source_name_family"), nullptr);
              EXPECT_EQ(Row.getArray("source_name_family")->size(),
                        Mixed ? 5U : 3U);
            }
            EXPECT_EQ(Count, Mixed ? 5U : 3U);
          }
}

std::vector<Class> genericAbstractIdentifierClasses(bool External, bool Range,
                                                    bool Symbolic, bool Mixed,
                                                    unsigned Contracts) {
  auto Input =
      publicAbstractIdentifierClasses(External, Range, Symbolic, Mixed);
  if (Contracts & 1) {
    Input[4].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.access = {"public", "constructor"};
    Init.reference.owner = Input[4].name;
    if (External) {
      Init.instructions.clear();
      Init.registers = Init.code_end = 0;
    }
    Input[4].methods.push_back(Init);
    Input[0].generic_signature = "Lapi/Base<Lapi/Value;>;";
  }
  if (Contracts & 2)
    for (auto &C : Input)
      for (auto &M : C.methods) {
        for (auto &P : M.reference.parameters)
          if (P == "Ljava/lang/Object;")
            P = "Lapi/Box;";
        if (M.reference.name == "choose-value")
          M.generic_signature = "(Lapi/Box<+Lapi/Value;>;J)Z";
        for (auto &Op : M.instructions)
          if (auto *Ref = std::get_if<MethodRef>(&Op.reference))
            for (auto &P : Ref->parameters)
              if (P == "Ljava/lang/Object;")
                P = "Lapi/Box;";
      }
  auto Box = klass("Lapi/Box;");
  Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Box.external = External;
  auto Value = klass("Lapi/Value;");
  Value.external = External;
  Input.push_back(Box);
  Input.push_back(Value);
  return Input;
}

TEST(MobileDalvikJava, GenericAbstractNamesRetainCompletePublicContracts) {
  for (unsigned Contracts : {1u, 2u, 3u})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Symbolic : {false, true})
          for (bool Mixed : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(::testing::Message()
                           << Contracts << External << Range << Symbolic
                           << Mixed << Reverse);
              auto Input = genericAbstractIdentifierClasses(
                  External, Range, Symbolic, Mixed, Contracts);
              const auto Root = Input[0].methods[0].reference;
              const auto Other = Mixed ? Input[5].methods[0].reference : Root;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), Mixed ? 5 : 3);
              unsigned Count = 0;
              for (const auto &V : *R.getArray("methods")) {
                const auto &Row = *V.getAsObject();
                if (Row.getString("name") != Root.name)
                  continue;
                ++Count;
                EXPECT_EQ(Row.getString("source_name"),
                          "__neverdVirtualMethod0");
                const auto Owner = Row.getString("class");
                const bool Interface =
                    Owner == "Lapi/Other;" || Owner == "Limpl/Edge;";
                EXPECT_EQ(Row.getString("source_name_declaration"),
                          Interface ? Other.identity() : Root.identity());
                EXPECT_EQ(Row.getArray("source_name_family")->size(),
                          Mixed ? 5u : 3u);
              }
              EXPECT_EQ(Count, Mixed ? 5u : 3u);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
            }
}

TEST(MobileDalvikJava, GenericAbstractNamesRejectInvalidContractsAndAccess) {
  for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = genericAbstractIdentifierClasses(true, false, false, false, 3);
    auto &Root = Input[0];
    if (Mutation == 0)
      Root.external = true;
    else if (Mutation == 1)
      Root.generic_signature = "Lapi/Base<TMissing;>;";
    else if (Mutation == 2)
      Root.methods[0].generic_signature = "(Lapi/Box<+TMissing;>;J)Z";
    else if (Mutation == 3)
      Root.superclass = "Lapi/Missing;";
    else if (Mutation == 4)
      Root.methods[0].access.insert("final");
    else if (Mutation == 5)
      Root.methods[0].access.insert("synthetic");
    else if (Mutation == 6)
      Root.methods[0].access.insert("native");
    else if (Mutation == 7)
      Root.access.erase("abstract");
    else if (Mutation == 8) {
      for (auto &C : Input)
        for (auto &M : C.methods)
          if (M.reference.name == "choose-value") {
            M.access.erase("public");
            M.access.insert("protected");
          }
    } else {
      auto Metadata = klass("Lapi/Metadata;");
      Metadata.external = true;
      Metadata.enclosing_method = Root.methods[0].reference;
      Input.push_back(Metadata);
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

