std::vector<Class> boundedVoidCarrierClasses(bool External, bool Range,
                                             bool Wide) {
  auto Bound = klass("Lapi/Bound;");
  auto Context = klass("Lapi/Context;");
  auto Unit = klass("Lapi/Unit;");
  auto Marker = klass("Lapi/Marker;");
  auto Function = klass("Lapi/Function;");
  Function.access = {"public", "interface", "abstract"};
  Function.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  for (auto *C : {&Bound, &Context, &Unit, &Marker, &Function})
    C->external = External;
  const auto Tail = Wide ? "JD" : "II";
  const unsigned Words = Wide ? 10 : 8;
  std::vector<std::string> Parameters{
      Function.name, Marker.name, Function.name,    Function.name,
      Function.name, Marker.name, Wide ? "J" : "I", Wide ? "D" : "I"};
  auto Work = method("work", Parameters, "V", Words, {op(0, "return-void")});
  Work.generic_signature =
      std::string("<T:Lapi/Bound;>(Lapi/Function<-Lapi/Context;+TT;>;") +
      "Lapi/Marker;Lapi/Function<-TT;Lapi/Unit;>;" +
      "Lapi/Function<-TT;Lapi/Unit;>;Lapi/Function<-TT;Lapi/Unit;>;" +
      "Lapi/Marker;" + Tail + ")V";
  auto Provider = klass("Lfixture/Provider;", {Work});
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  std::vector<unsigned> Registers;
  for (unsigned I = 0; I < Words; ++I)
    Registers.push_back(I);
  auto Call = method("run", Parameters, "V", Words,
                     {op(0, Range ? "invoke-static/range" : "invoke-static",
                         Registers, {}, Provider.methods[0].reference),
                      op(1, "return-void")});
  return {klass("Lfixture/Client;", {Call}),
          Provider,
          Function,
          Bound,
          Context,
          Unit,
          Marker};
}

TEST(MobileDalvikJava, BoundedVoidCarriersKeepOneCompleteNominalFormal) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Wide : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = boundedVoidCarrierClasses(External, Range, Wide);
          const auto Target = Input[1].methods[0].reference;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plans.erased_generic_invocations.contains(Target));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getInteger("projected_method_count"));
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
        }
}

TEST(MobileDalvikJava, BoundedVoidCarriersRejectUnprovedBoundsAndScopes) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = boundedVoidCarrierClasses(External, false, false);
      auto &Provider = Input[1], &Function = Input[2], &Bound = Input[3];
      auto &Work = Provider.methods[0];
      if (Mutation == 0)
        Input.erase(Input.begin() + 3);
      else if (Mutation == 1)
        Bound.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 2)
        Function.generic_signature =
            "<A:Ljava/lang/Object;B:Lapi/Bound;>Ljava/lang/Object;";
      else if (Mutation == 3)
        Function.access.erase("public");
      else if (Mutation == 4)
        Work.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 5)
        Work.access.insert("varargs");
      else if (Mutation == 6)
        Work.access.insert("synthetic");
      else if (Mutation == 7) {
        Provider.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
      } else if (Mutation == 8) {
        auto &S = *Work.generic_signature;
        const auto At = S.find("<T:Lapi/Bound;>");
        S.replace(At, std::string("<T:Lapi/Bound;>").size(),
                  "<T:Lapi/Bound;U:Lapi/Bound;>");
      } else if (Mutation == 9) {
        auto &S = *Work.generic_signature;
        const auto At = S.find("+TT;");
        S.replace(At, 4, "+TX;");
      } else if (Mutation == 10)
        Input[4].access.erase("public");
      else
        Input[6].generic_signature = "<M:Ljava/lang/Object;>Ljava/lang/Object;";
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> recursiveRangeResultClasses(bool External, bool Range,
                                               bool SeedFirst) {
  auto Compare = method("compareTo", {"Ljava/lang/Object;"}, "I", 0, {});
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TE;)I";
  auto Comparable = klass("Ljava/lang/Comparable;", {Compare});
  Comparable.access = {"public", "interface", "abstract"};
  Comparable.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Comparable.external = true;
  auto Carrier = klass("Lfixture/Range;");
  Carrier.access = {"public", "interface", "abstract"};
  Carrier.generic_signature =
      "<E::Ljava/lang/Comparable<-TE;>;>Ljava/lang/Object;";
  Carrier.external = External;
  std::vector<std::string> Parameters =
      SeedFirst ? std::vector<std::string>{Comparable.name, Carrier.name}
                : std::vector<std::string>{Carrier.name, Comparable.name};
  auto Select = method("select", Parameters, Comparable.name, 2,
                       {op(0, "return-object", {SeedFirst ? 0u : 1u})});
  Select.generic_signature =
      std::string("<T::Ljava/lang/Comparable<-TT;>;>(") +
      (SeedFirst ? "TT;Lfixture/Range<TT;>;" : "Lfixture/Range<TT;>;TT;") +
      ")TT;";
  if (External) {
    Select.instructions.clear();
    Select.registers = Select.code_end = 0;
  }
  auto Provider = klass("Lfixture/Provider;", {Select});
  Provider.external = External;
  auto Call =
      method("call", Parameters, Comparable.name, 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Provider.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Client;", {Call}), Provider, Carrier, Comparable};
}

