std::vector<Class> fixedInputCallbackCompletionClasses(bool External,
                                                       bool Range) {
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature =
      "<I:Ljava/lang/Object;O:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Completion = klass("Lfixture/Completion;");
  Completion.access = Callback.access;
  Completion.generic_signature = "<O:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Closed = klass("Lfixture/Closed;");
  for (auto *C : {&Callback, &Completion, &Closed})
    C->external = External;
  auto Work =
      method("work", {Callback.name, Completion.name}, "Ljava/lang/Object;", 3,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Work.access = {"public", "static"};
  Work.generic_signature =
      "<R:Ljava/lang/Object;>(Lfixture/Callback<-Lfixture/Closed;+TR;>;"
      "Lfixture/Completion<-TR;>;)Ljava/lang/Object;";
  auto Provider = klass("Lfixture/Provider;", {Work});
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Call =
      method("call", {Callback.name, Completion.name}, "Ljava/lang/Object;", 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Provider.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.access = {"public", "static"};
  auto Client = klass("Lfixture/Client;", {Call});
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  return {Client, Provider, Callback, Completion, Closed, Object};
}

