std::vector<Class> producerPredicateCompletionClasses(bool External, bool Range,
                                                      bool Predicate) {
  auto Input = fixedInputCallbackCompletionClasses(External, Range);
  auto &Producer = Input[2];
  Producer.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Test = klass("Lfixture/Predicate;");
  Test.access = {"public", "interface", "abstract"};
  Test.external = External;
  Test.generic_signature =
      "<I:Ljava/lang/Object;C:Ljava/lang/Object;R:Ljava/lang/Object;>"
      "Ljava/lang/Object;";
  auto Boolean = klass("Ljava/lang/Boolean;");
  Boolean.external = true;
  auto &Work = Input[1].methods[0];
  Work.generic_signature = "<R:Ljava/lang/Object;>(Lfixture/Callback<+TR;>;"
                           "Lfixture/Completion<-TR;>;)Ljava/lang/Object;";
  if (Predicate) {
    Work.reference.parameters.insert(Work.reference.parameters.begin() + 1,
                                     Test.name);
    Work.generic_signature =
        "<R:Ljava/lang/Object;>(Lfixture/Callback<+TR;>;"
        "Lfixture/Predicate<-TR;-Lfixture/Completion<-Ljava/lang/Boolean;>;"
        "+Ljava/lang/Object;>;Lfixture/Completion<-TR;>;)Ljava/lang/Object;";
    if (!External)
      Work.registers = 4;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Work.reference.parameters;
  Call.registers = Predicate ? 4 : 3;
  Call.instructions[0].reference = Work.reference;
  Call.instructions[0].registers =
      Predicate ? std::vector<unsigned>{1, 2, 3} : std::vector<unsigned>{1, 2};
  Input.push_back(Test);
  Input.push_back(Boolean);
  return Input;
}

std::vector<Class> contextualProducerCompletionClasses(bool External,
                                                       bool Range,
                                                       unsigned PrefixCount,
                                                       bool Wide) {
  auto Input = producerPredicateCompletionClasses(External, Range, false);
  auto &Work = Input[1].methods[0];
  std::vector<std::string> Prefix;
  std::string SignaturePrefix;
  unsigned Words = 2;
  for (unsigned I = 0; I < PrefixCount; ++I) {
    const std::string Type = I == 1 && Wide ? "J"
                             : I == 2       ? "Z"
                                            : "Lfixture/Closed;";
    Prefix.push_back(Type);
    SignaturePrefix += Type;
    Words += Type == "J" ? 2 : 1;
  }
  Work.reference.parameters.insert(Work.reference.parameters.begin(),
                                   Prefix.begin(), Prefix.end());
  Work.generic_signature = "<R:Ljava/lang/Object;>(" + SignaturePrefix +
                           "Lfixture/Callback<+TR;>;"
                           "Lfixture/Completion<-TR;>;)Ljava/lang/Object;";
  if (!External)
    Work.registers = Words + 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Work.reference.parameters;
  Call.registers = Words + 1;
  Call.instructions[0].reference = Work.reference;
  Call.instructions[0].registers.clear();
  for (unsigned I = 1; I <= Words; ++I)
    Call.instructions[0].registers.push_back(I);
  return Input;
}

