TEST(MobileDalvikJava, PrivateProducerCompletionsRejectScopeAndContractDrift) {
  for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = privateProducerCompletionClasses(false, true, 2);
    auto &Owner = Input[0];
    auto &Work = Owner.methods[0];
    auto replace = [&](std::string From, std::string To) {
      auto &Signature = *Work.generic_signature;
      const auto At = Signature.find(From);
      ASSERT_NE(At, std::string::npos);
      Signature.replace(At, From.size(), To);
    };
    if (Mutation == 0) {
      auto Call = Owner.methods[1];
      Owner.methods.pop_back();
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 1) {
      auto Alias = klass("Lfixture/Alias;");
      Alias.superclass = Owner.name;
      std::get<MethodRef>(Owner.methods[1].instructions[0].reference).owner =
          Alias.name;
      Input.push_back(Alias);
    } else if (Mutation == 2) {
      auto Call = Owner.methods[1];
      Owner.external = true;
      Owner.methods.pop_back();
      Owner.methods[0].instructions.clear();
      Owner.methods[0].registers = Owner.methods[0].code_end = 0;
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 3)
      replace("Callback<+TR;", "Callback<-TR;");
    else if (Mutation == 4)
      replace("Predicate<-TR;", "Predicate<*");
    else if (Mutation == 5)
      replace("Completion<-Lfixture/Closed;", "Completion<+Lfixture/Closed;");
    else if (Mutation == 6) {
      auto &Signature = *Work.generic_signature;
      const auto At = Signature.rfind("Completion<-Lfixture/Closed;");
      Signature.replace(At, std::string("Completion<-Lfixture/Closed;").size(),
                        "Completion<-Ljava/lang/Boolean;");
    } else if (Mutation == 7)
      Work.access.insert("varargs");
    else if (Mutation == 8)
      Work.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 9)
      Owner.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 10)
      Work.instructions.clear();
    else if (Mutation == 11)
      Input[2].generic_signature = "<O:Lfixture/Closed;>Ljava/lang/Object;";
    else if (Mutation == 12)
      Input.erase(Input.begin() + 3);
    else if (Mutation == 13)
      replace("R:Ljava/lang/Object;>",
              "R:Ljava/lang/Object;U:Ljava/lang/Object;>");
    else
      Owner.methods[1].instructions[0].opcode = "invoke-direct/range";
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

