std::vector<Class> instanceFixedProducerClasses(bool Interface,
                                                bool ExternalTarget,
                                                bool ExternalContracts,
                                                bool Facade, bool Range,
                                                unsigned Variance) {
  auto Input = fixedInputCallbackCompletionClasses(false, Range);
  auto &Provider = Input[1];
  auto &Work = Provider.methods[0];
  Work.access = {"public"};
  ++Work.registers;
  Work.generic_signature =
      std::string("<R:Ljava/lang/Object;>(Lfixture/Callback<") +
      (Variance & 1 ? "" : "-") + "Lfixture/Closed;" +
      (Variance & 2 ? "" : "+") + "TR;>;Lfixture/Completion<" +
      (Variance & 4 ? "" : "-") + "TR;>;)Ljava/lang/Object;";
  if (Interface) {
    Provider.access = {"public", "abstract", "interface"};
    Work.access.insert("abstract");
  }
  Provider.external = ExternalTarget;
  if (Interface || ExternalTarget) {
    Work.instructions.clear();
    Work.registers = Work.code_end = 0;
  }
  for (size_t I : {2u, 3u, 4u})
    Input[I].external = ExternalContracts;
  const auto Receiver =
      Facade ? std::string("Lfixture/Facade;") : Provider.name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters.insert(Call.reference.parameters.begin(), Receiver);
  Call.registers = 4;
  Call.instructions[0].opcode =
      std::string(Interface ? "invoke-interface" : "invoke-virtual") +
      (Range ? "/range" : "");
  Call.instructions[0].registers = {1, 2, 3};
  std::get<MethodRef>(Call.instructions[0].reference).owner = Receiver;
  if (Facade) {
    auto Alias = klass(Receiver);
    if (Interface) {
      Alias.access = {"public", "abstract", "interface"};
      Alias.interfaces = {Provider.name};
    } else
      Alias.superclass = Provider.name;
    Input.push_back(Alias);
  }
  return Input;
}

TEST(MobileDalvikJava,
     InstanceFixedProducersKeepCompleteCallbackCompletionBinding) {
  for (bool Interface : {false, true})
    for (bool ExternalTarget : {false, true})
      for (bool ExternalContracts : {false, true})
        for (bool Facade : {false, true})
          for (bool Range : {false, true})
            for (unsigned Variance = 0; Variance < 8; ++Variance)
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{Interface, ExternalTarget, ExternalContracts,
                               Facade, Range, Variance, Route}));
                auto Input = instanceFixedProducerClasses(
                    Interface, ExternalTarget, ExternalContracts, Facade, Range,
                    Variance);
                const auto Ref = Input[1].methods[0].reference;
                const auto Signature = Input[1].methods[0].generic_signature;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Signature);
              }
}

TEST(MobileDalvikJava,
     InstanceFixedProducersRejectUnboundTypesAndWrongDispatch) {
  for (bool Interface : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Interface, Mutation, Route}));
        auto Input = instanceFixedProducerClasses(Interface, false, false,
                                                  false, true, 0);
        auto &Work = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &Signature = *Work.generic_signature;
          const auto At = Signature.find(From);
          ASSERT_NE(At, std::string::npos);
          Signature.replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          replace("<-Lfixture/Closed;", "<+Lfixture/Closed;");
          break;
        case 1:
          replace(";+TR;>", ";-TR;>");
          break;
        case 2:
          replace("Completion<-TR;>", "Completion<+TR;>");
          break;
        case 3:
          replace("Lfixture/Closed;", "Lfixture/Unknown;");
          break;
        case 4:
          Input[3].generic_signature = "<O:Lfixture/Closed;>Ljava/lang/Object;";
          break;
        case 5:
          Input[2].generic_signature =
              "<I:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 6:
          replace("R:Ljava/lang/Object;>",
                  "R:Ljava/lang/Object;S:Ljava/lang/Object;>");
          break;
        case 7:
          Work.access.insert("varargs");
          break;
        case 8:
          Work.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 9:
          Work.access.insert("bridge");
          break;
        case 10:
          Work.access.insert("native");
          Work.instructions.clear();
          Work.registers = Work.code_end = 0;
          break;
        case 11:
          Call.instructions[0].opcode =
              Interface ? "invoke-virtual/range" : "invoke-interface/range";
          break;
        case 12:
          Call.instructions[0].registers.pop_back();
          break;
        case 13:
          Work.reference.parameters[1] = "Ljava/lang/Object;";
          Call.instructions[0].reference = Work.reference;
          break;
        case 14:
          replace(")Ljava/lang/Object;", ")TUnknown;");
          break;
        case 15:
          Work.access.erase("public");
          Work.access.insert("private");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Route)
          EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                       std::runtime_error);
        else
          EXPECT_THROW(recover(Input), std::runtime_error);
      }
}

