std::vector<Class> nestedCompletionResultClasses(bool External, bool Range,
                                                 bool Facade, bool Initializer,
                                                 bool Checked,
                                                 bool GenericOwner,
                                                 unsigned Variance) {
  auto Input = scopedCompletionCallbackClasses(External, Range);
  auto Context = klass("Lfixture/Context;");
  auto &Work = Input[1].methods[0];
  Work.reference.parameters = {Context.name, Input[2].name};
  const std::string ScopeVariance = Variance & 1 ? "" : "-";
  const std::string NestedVariance = Variance & 2 ? "" : "-";
  const std::string OutputVariance = Variance & 1 ? "" : "+";
  Work.generic_signature =
      "<R:Ljava/lang/Object;>(Lfixture/Context;Lfixture/Callback<" +
      ScopeVariance + "Lfixture/Closed;" + NestedVariance +
      "Lfixture/Completion<-TR;>;" + OutputVariance +
      "Ljava/lang/Object;>;)TR;";
  if (!External) {
    Work.registers = 3;
    Work.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Work.code_end = 2;
  }
  if (Checked)
    Work.declared_throws = {"Ljava/lang/Exception;"};
  if (GenericOwner)
    Input[1].generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Ref = Work.reference;
  if (Facade) {
    auto Alias = klass("Lfixture/Facade;");
    Alias.superclass = Input[1].name;
    Ref.owner = Alias.name;
    Input.push_back(Alias);
  }
  Input.push_back(Context);
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.instructions[0].reference = Ref;
  if (Initializer) {
    Call.reference.name = "<clinit>";
    Call.reference.parameters.clear();
    Call.reference.returns = "V";
    Call.generic_signature.reset();
    Call.access = {"static", "constructor"};
    Call.registers = 2;
    Call.instructions = {
        op(0, "const/4", {0}, int64_t(0)), op(1, "const/4", {1}, int64_t(0)),
        op(2, Range ? "invoke-static/range" : "invoke-static", {0, 1}, {}, Ref),
        op(3, "move-result-object", {0}), op(4, "return-void")};
    Call.code_end = 5;
  }
  return Input;
}

TEST(MobileDalvikJava, NestedCompletionResultsKeepFormalAndCheckedContracts) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Facade : {false, true})
        for (bool Initializer : {false, true})
          for (bool Checked : {false, true})
            for (bool GenericOwner : {false, true})
              for (unsigned Variance = 0; Variance < 4; ++Variance)
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(External);
                  SCOPED_TRACE(Range);
                  SCOPED_TRACE(Facade);
                  SCOPED_TRACE(Initializer);
                  SCOPED_TRACE(Checked);
                  SCOPED_TRACE(GenericOwner);
                  SCOPED_TRACE(Variance);
                  SCOPED_TRACE(Route);
                  auto Input = nestedCompletionResultClasses(
                      External, Range, Facade, Initializer, Checked,
                      GenericOwner, Variance);
                  const auto Ref = Input[1].methods[0].reference;
                  const auto Signature = Input[1].methods[0].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
                  if (Checked)
                    EXPECT_TRUE(Plans.closed_declared_throws.contains(Ref));
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                            0);
                  EXPECT_EQ(R.getArray("generic_signature_projections"),
                            nullptr);
                  EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                            Signature);
                }
}

TEST(MobileDalvikJava, NestedCompletionResultsRejectIncompleteContracts) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(Mutation);
      SCOPED_TRACE(Route);
      auto Input = nestedCompletionResultClasses(false, false, false, false,
                                                 true, false, 0);
      auto &Work = Input[1].methods[0];
      auto &Signature = *Work.generic_signature;
      auto replace = [&](const std::string &From, const std::string &To) {
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("R:Ljava/lang/Object;>",
                "R:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 1)
        replace("R:Ljava/lang/Object;>", "R:Ljava/lang/Number;>");
      else if (Mutation == 2)
        replace("Completion<-TR;>", "Completion<-TU;>");
      else if (Mutation == 3)
        replace("Completion<-TR;>", "Completion<+TR;>");
      else if (Mutation == 4)
        replace("-Lfixture/Completion", "+Lfixture/Completion");
      else if (Mutation == 5)
        replace("-Lfixture/Closed;", "+Lfixture/Closed;");
      else if (Mutation == 6)
        replace("+Ljava/lang/Object;", "-Ljava/lang/Object;");
      else if (Mutation == 7)
        replace("+Ljava/lang/Object;", "+TR;");
      else if (Mutation == 8)
        replace("Completion<-TR;>", "Completion<*>");
      else if (Mutation == 9)
        Input[2].generic_signature =
            "<S:Ljava/lang/Object;C:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 10)
        Input[3].generic_signature = "<O:Lfixture/Closed;>Ljava/lang/Object;";
      else if (Mutation == 11)
        Work.access.erase("static");
      else if (Mutation == 12)
        Work.access = {"private", "static"};
      else if (Mutation == 13)
        Work.access.insert("varargs");
      else if (Mutation == 14) {
        Work.declared_throws = {"Lfixture/NotThrowable;"};
        Input.push_back(klass("Lfixture/NotThrowable;"));
      } else
        Signature += "^Ljava/lang/Exception;";
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      EXPECT_THROW(
          {
            if (Route)
              recoverJava(linkClasses(Input, B), B);
            else
              recover(Input);
          },
          std::runtime_error);
    }
}

