TEST(MobileDalvikJava, ScopedCompletionsRejectLeadingWordAndContractDrift) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = scalarScopedCompletionClasses(true, 0, false,
                                               Mutation == 6 ? "[J" : "J");
    auto &Work = Input[1].methods.front();
    auto &Signature = *Work.generic_signature;
    auto &Invoke = Input.front().methods.front().instructions.front();
    if (Mutation == 0)
      std::swap(Invoke.registers[0], Invoke.registers[1]);
    else if (Mutation == 1)
      Invoke.registers.pop_back();
    else if (Mutation == 2)
      Signature.replace(Signature.find("(J"), 2, "(TR;");
    else if (Mutation == 3)
      Work.access.insert("varargs");
    else if (Mutation == 4)
      Signature.replace(Signature.find("Completion<-TR;"), 15,
                        "Completion<+TR;");
    else if (Mutation == 5)
      Input[4].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 7)
      Signature.replace(Signature.rfind("Ljava/lang/Object;"), 18,
                        "Ljava/lang/String;");
    else if (Mutation == 8)
      Work.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 9)
      Work.access.insert("native");
    else if (Mutation == 10)
      Work.reference.parameters[0] = "I";
    else if (Mutation == 11)
      Input[2].generic_signature =
          "<S:Ljava/lang/Object;C:Ljava/lang/Object;O:Lfixture/Closed;>Ljava/"
          "lang/Object;";
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

