std::vector<Class> boundedGenericDefaultAccessorClasses(bool External,
                                                        bool Range) {
  auto Bound = klass("Lfixture/Bound;");
  auto Closed = klass("Lfixture/Closed;");
  auto Link = klass("Lfixture/Link;");
  Link.access = {"public", "interface", "abstract"};
  Link.generic_signature =
      "<T:Ljava/lang/Object;V:Lfixture/Bound;>Ljava/lang/Object;";
  auto Vector = klass("Lfixture/Vector;");
  Vector.generic_signature = "<V:Lfixture/Bound;>Ljava/lang/Object;";
  for (auto *C : {&Bound, &Closed, &Link, &Vector})
    C->external = External;
  auto Work =
      method("work", {Link.name}, Vector.name, 3,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Work.access = {"public"};
  Work.generic_signature =
      "<V:Lfixture/Bound;>(Lfixture/Link<Lfixture/Closed;TV;>;)"
      "Lfixture/Vector<TV;>;";
  auto Api = klass("Lfixture/DefaultApi;", {Work});
  Api.access = {"public", "interface", "abstract"};
  auto Forward =
      method("access$work$jd", {Api.name, Link.name}, Vector.name, 3,
             {op(0, Range ? "invoke-super/range" : "invoke-super", {1, 2}, {},
                 Api.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Forward.reference.owner = Api.name;
  Forward.access = {"public", "static", "synthetic"};
  Api.methods.push_back(Forward);
  return {Api, Bound, Closed, Link, Vector};
}

TEST(MobileDalvikJava,
     GenericDefaultAccessorsRetainBoundedInputResultAndHelperSignature) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = boundedGenericDefaultAccessorClasses(External, Range);
        const auto Target = Input[0].methods[0].reference;
        const auto Signature = *Input[0].methods[0].generic_signature;
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_TRUE(
            Plans.erased_bounded_converter_invocations.contains(Target));
        const auto Inheritance = planGenericInheritance(Classes, Plans, B);
        ASSERT_EQ(Inheritance.interface_default_accessors.size(), 1u);
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), 2);
        unsigned Helpers = 0;
        for (const auto &V : *R.getArray("generated_source_helpers"))
          if (V.getAsObject()->getString("kind") ==
              "interface-default-body-helper") {
            EXPECT_EQ(V.getAsObject()->getString("generic_signature"),
                      Signature);
            ++Helpers;
          }
        EXPECT_EQ(Helpers, 1u);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      }
}

std::vector<Class> closedDefaultAccessorClasses(unsigned Count, bool Nominal,
                                                bool External, bool Range) {
  auto Input = boundedGenericDefaultAccessorClasses(External, Range);
  auto &Target = Input[0].methods[0];
  Target.reference.parameters.assign(Count, Input[3].name);
  if (Count > 1)
    Target.reference.parameters[0] = Input[2].name;
  if (Nominal)
    Target.reference.returns = Input[2].name;
  Target.generic_signature = "(";
  for (const auto &type : Target.reference.parameters)
    *Target.generic_signature +=
        type == Input[2].name
            ? type
            : "Lfixture/Link<Lfixture/Closed;Lfixture/Bound;>;";
  *Target.generic_signature +=
      ")" + (Nominal ? Input[2].name : "Lfixture/Vector<Lfixture/Bound;>;");
  Target.registers = Count + 2;
  auto &Access = Input[0].methods[1];
  Access.reference.parameters = {Input[0].name};
  Access.reference.parameters.insert(Access.reference.parameters.end(),
                                     Target.reference.parameters.begin(),
                                     Target.reference.parameters.end());
  Access.reference.returns = Target.reference.returns;
  Access.registers = Count + 2;
  Access.instructions[0].reference = Target.reference;
  Access.instructions[0].registers.clear();
  for (unsigned i = 1; i <= Count + 1; ++i)
    Access.instructions[0].registers.push_back(i);
  return Input;
}

