TEST(MobileDalvikJava, SyntheticDefaultsRetainOriginalBodiesAndContracts) {
  for (unsigned Kind = 0; Kind < 6; ++Kind)
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Kind, External, Range, Reverse}));
          auto Input =
              Kind == 0 ? closedDefaultAccessorClasses(1, true, External, Range)
              : Kind == 1
                  ? closedDefaultAccessorClasses(4, false, External, Range)
                  : interfaceDefaultAccessorClasses(Kind == 2   ? "V"
                                                    : Kind == 3 ? "I"
                                                    : Kind == 4
                                                        ? "J"
                                                        : "Ljava/lang/Object;",
                                                    Range);
          if (Kind >= 2 && External) {
            Input[1].external = true;
            for (auto &M : Input[1].methods) {
              M.instructions.clear();
              M.registers = M.code_end = 0;
            }
          }
          Input[0].methods[0].access.insert("synthetic");
          const auto Target = Input[0].methods[0].reference;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R = recoverJava(linkClasses(Input, B), B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 2);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          bool Disclosed = false;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") != Target.identity())
              continue;
            EXPECT_EQ(Row->getString("projection_kind"),
                      "interface-default-body");
            for (const auto &Difference :
                 *Row->getArray("metadata_differences"))
              if (Difference.getAsString()->contains("synthetic access flag")) {
                Disclosed = true;
                EXPECT_FALSE(
                    Difference.getAsString()->contains("static descriptor"));
              }
          }
          EXPECT_TRUE(Disclosed);
        }
}

TEST(MobileDalvikJava, SyntheticDefaultsRejectUnprovedBodyAndDispatch) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = interfaceDefaultAccessorClasses("Ljava/lang/Object;", true);
    auto &Target = Input[0].methods[0];
    auto &Forward = Input[0].methods[1];
    Target.access.insert("synthetic");
    if (Mutation == 0)
      Target.access.insert("bridge");
    else if (Mutation == 1)
      Target.access.insert("native");
    else if (Mutation == 2)
      Target.access.insert("static");
    else if (Mutation == 3)
      Target.access.insert("abstract");
    else if (Mutation == 4)
      Target.access.insert("private");
    else if (Mutation == 5)
      Target.access.erase("public");
    else if (Mutation == 6)
      Target.instructions.clear();
    else if (Mutation == 7)
      Target.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 8)
      Forward.access.erase("synthetic");
    else if (Mutation == 9)
      Forward.instructions[0].registers[0] = 0;
    else if (Mutation == 10)
      Forward.instructions[0].opcode = "invoke-interface/range";
    else
      Target.generic_signature =
          "<T:Ljava/lang/Object;>(JLjava/lang/Object;)Ljava/lang/Object;";
    if (Mutation == 10) {
      // An ordinary virtual forwarder is valid but must not acquire the
      // direct-default receipt or its private body helper.
      Budget B;
      const auto Classes = linkClasses(Input, B);
      const auto Plans = validateGenericSignatures(Classes, B);
      EXPECT_TRUE(planGenericInheritance(Classes, Plans, B)
                      .interface_default_accessors.empty());
    } else
      EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

