std::vector<Class> ownerPairDefaultAccessorClasses(bool Range) {
  auto Work =
      method("same", {"Ljava/lang/Object;", "Ljava/lang/Object;"}, "Z", 4,
             {op(0, "const/4", {0}, int64_t{1}), op(1, "return", {0})});
  Work.access = {"public"};
  Work.generic_signature = "(TS;TS;)Z";
  auto Api = klass("Lfixture/PairApi;", {Work});
  Api.access = {"public", "interface", "abstract"};
  Api.generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Access =
      method("access$same$jd",
             {Api.name, "Ljava/lang/Object;", "Ljava/lang/Object;"}, "Z", 4,
             {op(0, Range ? "invoke-super/range" : "invoke-super", {1, 2, 3},
                 {}, Api.methods[0].reference),
              op(1, "move-result", {0}), op(2, "return", {0})});
  Access.reference.owner = Api.name;
  Access.access = {"public", "static", "synthetic"};
  Api.methods.push_back(Access);
  return {Api};
}

std::vector<Class> ownerVoidDefaultAccessorClasses(bool External, bool Range,
                                                   bool Array,
                                                   const std::string &Variance,
                                                   bool SecondFormal) {
  const std::string Object = "Ljava/lang/Object;";
  auto Invoke = method("invoke", {Object, Object}, Object, 0, {});
  Invoke.access = {"public", "abstract"};
  Invoke.generic_signature = "(TP;TQ;)TR;";
  auto Binary = klass("Lfixture/Binary;", {Invoke});
  Binary.access = {"public", "interface", "abstract"};
  Binary.generic_signature = "<P:Ljava/lang/Object;Q:Ljava/lang/Object;R:Ljava/"
                             "lang/Object;>Ljava/lang/Object;";
  Binary.external = External;
  const auto Input = Array ? "[Ljava/lang/Object;" : Object;
  auto Current = method("current", {}, Input, 0, {});
  Current.access = {"public", "abstract"};
  Current.generic_signature = Array ? "()[TN;" : "()TN;";
  auto Work = method(
      "work", {Binary.name, Object}, "V", 4,
      {op(0, "invoke-interface", {1}, {},
          MethodRef{"Lfixture/DefaultApi;", "current", {}, Input}),
       op(1, "move-result-object", {0}),
       op(2, "invoke-interface", {2, 0, 3}, {}, Binary.methods[0].reference),
       op(3, "return-void")});
  Work.access = {"public"};
  Work.generic_signature =
      "(Lfixture/Binary<" + Variance + (Array ? "[TN;" : "TN;") +
      (SecondFormal ? "-TM;" : "Ljava/lang/Object;") + "Ljava/lang/Object;>;" +
      (SecondFormal ? "TM;" : "Ljava/lang/Object;") + ")V";
  auto Api = klass("Lfixture/DefaultApi;", {Current, Work});
  Api.access = {"public", "interface", "abstract"};
  Api.generic_signature =
      SecondFormal
          ? "<N:Ljava/lang/Object;M:Ljava/lang/Object;>Ljava/lang/Object;"
          : "<N:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Access =
      method("access$work$jd", {Api.name, Binary.name, Object}, "V", 3,
             {op(0, Range ? "invoke-super/range" : "invoke-super", {0, 1, 2},
                 {}, Api.methods[1].reference),
              op(1, "return-void")});
  Access.access = {"public", "static", "synthetic"};
  Access.reference.owner = Api.name;
  Api.methods.push_back(Access);
  return {Api, Binary};
}

