TEST(MobileDalvikJava, OwnerVoidDefaultsRejectForeignScopeAndDispatchDrift) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{External, Mutation}));
      auto Input =
          ownerVoidDefaultAccessorClasses(External, true, false, "-", false);
      auto &Api = Input[0];
      auto &Work = Api.methods[1];
      auto &Access = Api.methods[2];
      switch (Mutation) {
      case 0:
        *Work.generic_signature =
            "<N:Ljava/lang/Object;>" + *Work.generic_signature;
        break;
      case 1:
        Work.reference.returns = "Ljava/lang/Object;";
        break;
      case 2:
        Work.generic_signature->replace(Work.generic_signature->find("TN;"), 3,
                                        "TF;");
        break;
      case 3:
        Input[1].generic_signature =
            "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 4:
        Input.pop_back();
        break;
      case 5:
        Access.access.erase("synthetic");
        break;
      case 6:
        Api.access.erase("interface");
        break;
      case 7:
        Work.access = {"private"};
        break;
      case 8:
        Work.access.insert("abstract");
        break;
      case 9:
        Work.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 10:
        Work.instructions[2].registers[0] = 1;
        break;
      case 11:
        Access.instructions[0].registers = {0, 2, 1};
        break;
      case 12:
        Access.instructions[0].registers[0] = Access.registers;
        break;
      case 13:
        std::get<MethodRef>(Access.instructions[0].reference).owner =
            Input[1].name;
        break;
      case 14:
        Work.generic_signature = "(Ljava/lang/Object;Ljava/lang/Object;)V";
        break;
      case 15:
        Access.instructions.insert(Access.instructions.begin(), op(0, "nop"));
        Access.instructions[1].pc = 1;
        Access.instructions[2].pc = 2;
        Access.code_end = 3;
        break;
      }
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

