std::vector<Class> objectOwnerDefaultAccessorClasses(bool Wide, bool Range,
                                                     bool Rename,
                                                     bool Collision) {
  auto Input = Wide ? boundedOwnerWideDefaultClasses(Range, true)
                    : boundedOwnerDefaultAccessorClasses(Range, true);
  auto &Api = Input[0];
  Api.generic_signature = Rename ? "<E:Ljava/lang/Object;>Ljava/lang/Object;"
                                 : "<V:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Work = Api.methods[0];
  Work.reference.parameters = std::vector<std::string>(3, "Ljava/lang/Object;");
  if (!Wide)
    Work.reference.returns = "Ljava/lang/Object;";
  Work.generic_signature =
      std::string(Rename ? "(TE;TE;TE;)" : "(TV;TV;TV;)") + (Wide     ? "J"
                                                             : Rename ? "TE;"
                                                                      : "TV;");
  auto &Access = Api.methods[1];
  Access.reference.parameters = {Api.name, "Ljava/lang/Object;",
                                 "Ljava/lang/Object;", "Ljava/lang/Object;"};
  Access.reference.returns = Work.reference.returns;
  Access.instructions[0].reference = Work.reference;
  Input[1].name = "Ljava/lang/Object;";
  Input[1].superclass.reset();
  if (Collision) {
    auto Existing =
        method("__neverdInterfaceDefault0", {}, "V", 0, {op(0, "return-void")});
    Existing.reference.owner = Api.name;
    Api.methods.push_back(Existing);
  }
  return Input;
}

