std::vector<Class> inheritedOwnerDefaultAccessorClasses(bool Range,
                                                        bool Intermediate) {
  auto Input = boundedOwnerDefaultAccessorClasses(Range, true);
  const auto Parent = Input[0];
  auto Child = Parent;
  Child.name = "Lfixture/ChildApi;";
  Child.interfaces = {Parent.name};
  Child.generic_signature =
      "<V:Lfixture/Vector;>Ljava/lang/Object;Lfixture/BoundedApi<TV;>;";
  Child.methods.erase(Child.methods.begin());
  auto &Access = Child.methods[0];
  Access.reference.owner = Child.name;
  Access.reference.parameters[0] = Child.name;
  std::get<MethodRef>(Access.instructions[0].reference).owner = Child.name;
  Input.push_back(Child);
  if (Intermediate) {
    auto Grand = Child;
    Grand.name = "Lfixture/GrandApi;";
    Grand.interfaces = {Child.name};
    Grand.generic_signature =
        "<V:Lfixture/Vector;>Ljava/lang/Object;Lfixture/ChildApi<TV;>;";
    Grand.methods[0].reference.owner = Grand.name;
    Grand.methods[0].reference.parameters[0] = Grand.name;
    std::get<MethodRef>(Grand.methods[0].instructions[0].reference).owner =
        Grand.name;
    Input.push_back(Grand);
  }
  return Input;
}

