std::vector<Class> checkedStaticSuperClasses(bool Dependency, bool Jumbo) {
  auto Input = staticSuperAccessorClasses(Dependency, false);
  auto Check = method("check", {"Ljava/lang/Object;", "Ljava/lang/String;"},
                      "V", 2, {op(0, "return-void")});
  auto Guard = klass("Lfixture/Guard;", {Check});
  Guard.external = Dependency;
  if (Dependency) {
    Guard.methods[0].instructions.clear();
    Guard.methods[0].code_end = Guard.methods[0].registers = 0;
  }
  auto &Forward = Input[0].methods[0];
  Forward.access = {"private", "static", "final"};
  for (auto &Op : Forward.instructions)
    Op.pc += 2;
  Forward.instructions.insert(
      Forward.instructions.begin(),
      {op(0, Jumbo ? "const-string/jumbo" : "const-string", {0},
          std::string("owned receiver")),
       op(1, "invoke-static", {1, 0}, {}, Guard.methods[0].reference)});
  Forward.code_end += 2;
  Input.push_back(std::move(Guard));
  return Input;
}

TEST(MobileDalvikJava, CheckedStaticSuperRetainsPrefixBeforeHelperDispatch) {
  for (bool Dependency : {false, true})
    for (bool Jumbo : {false, true})
      for (bool Linked : {false, true}) {
        auto Input = checkedStaticSuperClasses(Dependency, Jumbo);
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto Report =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(Report.getInteger("projected_method_count"), 1);
        std::string Text;
        for (const auto &Row : *Report.getArray("source_units"))
          if (Row.getAsObject()->getString("class") == "Lfixture/Host;")
            Text = Row.getAsObject()->getString("source")->str();
        const auto Start = Text.find("private static final void access$ping(");
        const auto Check = Text.find(".check(", Start);
        const auto Dispatch = Text.find(".__neverdSuper1();", Start);
        ASSERT_NE(Start, std::string::npos);
        ASSERT_NE(Check, std::string::npos);
        ASSERT_NE(Dispatch, std::string::npos);
        EXPECT_LT(Check, Dispatch);
        EXPECT_EQ(Text.find(".check(", Check + 1), std::string::npos);
        EXPECT_NE(Text.find("super.ping();"), std::string::npos);
        for (const auto &Row : *Report.getArray("methods"))
          if (Row.getAsObject()->getString("name") == "access$ping") {
            const auto *Differences =
                Row.getAsObject()->getArray("metadata_differences");
            ASSERT_NE(Differences, nullptr);
            EXPECT_EQ(Differences->size(), 1U);
          }
      }
}

