std::vector<Class> genericFinalFieldClasses(bool Array, bool Bounded) {
  auto Box = klass("Lfixture/Box;");
  const std::string Bound =
      Bounded ? "Ljava/lang/Number;" : "Ljava/lang/Object;";
  const std::string Type = (Array ? "[" : "") + Bound;
  const std::string Signature = Array ? "[TT;" : "TT;";
  Box.generic_signature = "<T:" + Bound + ">Ljava/lang/Object;";
  Field Value{FieldRef{Box.name, "value", Type}, {"public", "final"}, {}};
  Value.generic_signature = Signature;
  auto Init = method("<init>", {Type}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "iput-object", {1, 0}, {}, Value.reference),
                      op(2, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Box.name;
  Init.generic_signature = "(" + Signature + ")V";
  Box.fields.push_back(Value);
  Box.methods.push_back(Init);
  return {Box};
}

TEST(MobileDalvikJava, GenericFinalWritesRetainTheDeclaredSourceType) {
  for (bool Array : {false, true})
    for (bool Bounded : {false, true})
      for (bool Linked : {false, true}) {
        auto Input = genericFinalFieldClasses(Array, Bounded);
        Budget B;
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        const auto Text = source(R);
        EXPECT_NE(
            Text.find(Array ? "this.value = ((T[])" : "this.value = ((T)"),
            std::string::npos);
      }
}

