TEST(MobileDalvikJava, AnonymousStaticSelfAllocationUsesOneSharedDeclaration) {
  for (bool Reverse : {false, true}) {
    auto Input = localClasses();
    auto &Local = Input[1];
    Local.inner_name.reset();
    FieldRef Instance{Local.name, "INSTANCE", Local.name};
    Local.fields.push_back({Instance, {"public", "static", "final"}, {}});
    auto Init =
        method("<clinit>", {}, "V", 1,
               {op(0, "new-instance", {0}, {}, Local.name),
                op(1, "invoke-direct", {0}, {}, Local.methods[0].reference),
                op(2, "sput-object", {0}, {}, Instance), op(3, "return-void")});
    Init.reference.owner = Local.name;
    Init.access = {"static", "constructor"};
    Local.methods.push_back(Init);
    // Reading the singleton in just the enclosing method used to leave the
    // class local, where Java's static initializer cannot instantiate it.
    Input[0].methods[0].instructions[0] =
        op(0, "sget-object", {0}, {}, Instance);
    Input[0].methods[0].instructions[1] = op(1, "nop");
    if (Reverse)
      std::reverse(Input.begin(), Input.end());
    Budget B;
    const auto Classes = linkClasses(Input, B);
    const auto Plan = planSharedAnonymousClasses(Classes, B);
    ASSERT_EQ(Plan.size(), 1u);
    EXPECT_EQ(Plan.at(Instance.owner).source_owner, "Lfixture/Core;");
    auto Report = recoverJava(Classes, B);
    const auto *Bindings = Report.getArray("class_source_bindings");
    ASSERT_NE(Bindings, nullptr);
    ASSERT_EQ(Bindings->size(), 1u);
    EXPECT_EQ(Bindings->front().getAsObject()->getString("binding_kind"),
              "anonymous-to-shared-member");
    EXPECT_NE(source(Report).find("static class __neverdLocal1"),
              std::string::npos);
  }
}

