std::vector<Class> nestedAnonymousClasses() {
  const std::string OuterName = "Lfixture/Host$1;";
  const std::string InnerName = "Lfixture/Host$1$1;";
  MethodRef ObjectInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto OuterInit = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, ObjectInit), op(1, "return-void")});
  OuterInit.access = {"constructor"};
  FieldRef Capture{InnerName, "parent", OuterName};
  auto InnerInit = method("<init>", {OuterName}, "V", 2,
                          {op(0, "iput-object", {1, 0}, {}, Capture),
                           op(1, "invoke-direct", {0}, {}, ObjectInit),
                           op(2, "return-void")});
  InnerInit.access = {"constructor"};
  auto Parent = method(
      "parent", {}, OuterName, 2,
      {op(0, "iget-object", {0, 1}, {}, Capture), op(1, "return-object", {0})});
  Parent.access = {"public"};
  Class Inner = klass(InnerName, {InnerInit, Parent});
  Inner.fields.push_back({Capture, {"final"}, {}});
  auto Nested =
      method("nested", {}, "Ljava/lang/Object;", 2,
             {op(0, "new-instance", {0}, {}, InnerName),
              op(1, "invoke-direct", {0, 1}, {}, Inner.methods[0].reference),
              op(2, "return-object", {0})});
  Nested.access = {"public"};
  Class Outer = klass(OuterName, {OuterInit, Nested});
  auto Make =
      method("make", {}, "Ljava/lang/Object;", 1,
             {op(0, "new-instance", {0}, {}, OuterName),
              op(1, "invoke-direct", {0}, {}, Outer.methods[0].reference),
              op(2, "return-object", {0})});
  Class Host = klass("Lfixture/Host;", {Make});
  for (auto *C : {&Outer, &Inner}) {
    C->access.clear();
    C->inner_class_present = true;
  }
  Outer.enclosing_method = Host.methods[0].reference;
  Inner.enclosing_method = Outer.methods[1].reference;
  return {Host, Outer, Inner};
}

TEST(MobileDalvikJava, SharedAnonymousFieldReferencesRequireSamePackageAccess) {
  auto Input = nestedAnonymousClasses();
  auto Adapter = klass("Lfixture/Adapter;");
  Adapter.fields.push_back({{Adapter.name, "captured", Input[1].name}, {}, {}});
  Input.push_back(Adapter);
  Budget B;
  const auto Classes = linkClasses(Input, B);
  const auto Plan = planSharedAnonymousClasses(Classes, B);
  ASSERT_EQ(Plan.size(), 1u);
  EXPECT_TRUE(Plan.at(Input[1].name).declarations.contains(Adapter.name));
  EXPECT_NO_THROW(recoverJava(Classes, B));
  Input.back().name = "Lother/Adapter;";
  Input.back().fields[0].reference.owner = Input.back().name;
  rejected([&] { recover(Input); }, "local type is unavailable");
  Input[1].access.insert("public");
  EXPECT_NO_THROW(recover(Input));
  Input[0].access.erase("public");
  rejected([&] { recover(Input); }, "local type is unavailable");
}

std::vector<Class> defaultScopeClasses() {
  auto Input = nestedAnonymousClasses();
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {"I"};
  Make.registers = 2;
  Make.generic_signature = "<T:Ljava/lang/Object;>(I)Ljava/lang/Object;";
  Input[1].enclosing_method = Make.reference;
  auto Default = Make;
  Default.reference.name += "$default";
  Default.reference.parameters = {"I", "I", "Ljava/lang/Object;"};
  Default.registers = 4;
  Default.generic_signature.reset();
  Default.access.insert("synthetic");
  Input[2].enclosing_method = Default.reference;
  Input[0].methods.push_back(Default);
  Input[2].fields.push_back(
      {{Input[2].name, "token", "Ljava/lang/Object;"}, {"public"}, {}, "TT;"});
  auto Identity =
      method("identity", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
             {op(0, "return-object", {1})});
  Identity.reference.owner = Input[2].name;
  Identity.access = {"public"};
  Identity.generic_signature = "(TT;)TT;";
  Input[2].methods.push_back(Identity);
  return Input;
}

TEST(MobileDalvikJava, SyntheticDefaultScopesRequireAnExactGenericBodyWitness) {
  auto Input = defaultScopeClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto R = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    const auto *Projections = R.getArray("generic_signature_projections");
    ASSERT_NE(Projections, nullptr);
    EXPECT_EQ(Projections->size(), 2u);
    for (const auto &Projection : *Projections)
      for (const auto &Change :
           *Projection.getAsObject()->getArray("changes")) {
        const auto *Row = Change.getAsObject();
        EXPECT_EQ(Row->getString("kind"),
                  "synthetic-default-method-type-variable");
        EXPECT_EQ(Row->getString("scope_origin"),
                  Input[0].methods[0].reference.identity());
        EXPECT_EQ(Row->getString("source_type"), "Ljava/lang/Object;");
      }
    EXPECT_EQ(R.getString("status"), "partial");
  }
  // A direct static delegation is a second independent witness.
  auto &Default = Input[0].methods[1];
  const auto Original = Default;
  Default.instructions = {
      op(0, "invoke-static", {1}, {}, Input[0].methods[0].reference),
      op(1, "move-result-object", {0}), op(2, "return-object", {0})};
  Default.code_end = 3;
  EXPECT_NO_THROW(linkClasses(Input, B));
  // The enclosing method's T is absent from its runtime slots. The separate
  // unused-formal call receipt now permits this already-proven delegation;
  // the two captured scope projections remain explicit and unchanged.
  const auto Delegated = recover(Input);
  EXPECT_EQ(Delegated.getInteger("unrecovered_method_count"), 0);
  EXPECT_EQ(Delegated.getArray("generic_signature_projections")->size(), 2u);
  Default = Original;
  // The local method's own formal shadows the projected enclosing variable.
  Input[2].methods.back().generic_signature = "<T:Ljava/lang/Object;>(TT;)TT;";
  EXPECT_EQ(recover(Input).getArray("generic_signature_projections")->size(),
            1u);
}

TEST(MobileDalvikJava,
     SyntheticDefaultScopesRejectMissingOrConstrainedOrigins) {
  for (unsigned Mutation = 0; Mutation != 7; ++Mutation) {
    auto Input = defaultScopeClasses();
    auto &Default = Input[0].methods[1];
    switch (Mutation) {
    case 0:
      Default.access.erase("synthetic");
      break;
    case 1:
      Default.reference.name = "another";
      break;
    case 2:
      Default.reference.parameters[1] = "F";
      break;
    case 3:
      Default.instructions = {op(0, "const/4", {0}, int64_t(0)),
                              op(1, "return-object", {0})};
      Default.code_end = 2;
      break;
    case 4:
      Input[0].methods[0].generic_signature =
          "<T:Ljava/lang/Object;:Ljava/io/Serializable;>(I)Ljava/lang/Object;";
      break;
    case 5:
      Input[2].fields.back().generic_signature = "TU;";
      break;
    case 6:
      Input[0].methods[0].generic_signature.reset();
      break;
    }
    Input[2].enclosing_method = Default.reference;
    rejected([&] { recover(Input); }, "unbound type variable");
  }
}

std::vector<Class> syntheticCapturedScopeClasses() {
  const std::string Owner = "Lfixture/TypedHost;",
                    Name = "Lfixture/TypedHost$1;";
  const FieldRef Capture{Name, "callback", "Ljava/util/List;"};
  auto Constructor =
      method("<init>", {"Ljava/util/List;"}, "V", 2,
             {op(0, "iput-object", {1, 0}, {}, Capture),
              op(1, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(2, "return-void")});
  Constructor.access = {"constructor"};
  Constructor.generic_signature = "(Ljava/util/List<TT;>;)V";
  auto Local = klass(Name, {Constructor});
  Local.inner_class_present = true;
  Local.fields = {
      {Capture, {"final", "synthetic"}, {}, "Ljava/util/List<TT;>;"}};
  auto Target =
      method("run", {"Ljava/util/List;", "I"}, "V", 2, {op(0, "return-void")});
  Target.generic_signature = "<T:Ljava/lang/Object;>(Ljava/util/List<TT;>;I)V";
  auto Host = klass(Owner, {Target});
  auto Wrapper =
      method("run", {"Ljava/util/List;"}, "V", 3,
             {op(0, "move-object", {1, 2}), op(1, "const/4", {0}, int64_t(0)),
              op(2, "invoke-static", {1, 0}, {}, Host.methods[0].reference),
              op(3, "new-instance", {0}, {}, Name),
              op(4, "invoke-direct", {0, 1}, {}, Local.methods[0].reference),
              op(5, "return-void")});
  Wrapper.reference.owner = Owner;
  Wrapper.access.insert("synthetic");
  Local.enclosing_method = Wrapper.reference;
  Host.methods.push_back(Wrapper);
  return {Host, Local};
}

TEST(MobileDalvikJava, SyntheticCallScopesRequireMatchingCaptureValueAndType) {
  auto Input = syntheticCapturedScopeClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  const auto Plans = validateGenericSignatures(Linked, B);
  const auto &Field = Plans.fields.at(Input[1].fields[0].reference);
  ASSERT_EQ(Field.source_projections.size(), 1u);
  const auto &Change = Field.source_projections[0];
  EXPECT_EQ(Change.kind, "synthetic-call-capture-type-variable");
  EXPECT_EQ(Change.scope_origin, Input[0].methods[0].reference.identity());
  EXPECT_EQ(Change.original_type,
            Input[0].methods[1].reference.identity() + "::T");
  const auto &Ctor = Plans.methods.at(Input[1].methods[0].reference);
  ASSERT_EQ(Ctor.source_projections.size(), 1u);
  EXPECT_EQ(Ctor.source_projections[0].source_type, "Ljava/lang/Object;");
  EXPECT_EQ(*Input[1].methods[0].generic_signature, "(Ljava/util/List<TT;>;)V");
}

TEST(MobileDalvikJava, SyntheticCallScopesRejectUnprovenCaptureProvenance) {
  for (unsigned Mutation = 0; Mutation != 9; ++Mutation) {
    auto Input = syntheticCapturedScopeClasses();
    auto &Host = Input[0];
    auto &Wrapper = Host.methods[1];
    switch (Mutation) {
    case 0:
      Wrapper.access.erase("synthetic");
      break;
    case 1:
      Input[1].fields[0].access.erase("synthetic");
      break;
    case 2:
      Host.methods[0].generic_signature =
          "<T:Ljava/lang/Object;:Ljava/io/Serializable;>(Ljava/util/"
          "List<TT;>;I)V";
      break;
    case 3:
      Input[1].methods[0].generic_signature =
          "(Ljava/util/List<Ljava/lang/String;>;)V";
      break;
    case 4:
      Wrapper.reference.parameters.push_back("Ljava/util/List;");
      Wrapper.registers = 4;
      Wrapper.instructions[4].registers[1] = 3;
      break;
    case 5:
      Wrapper.instructions[0] = op(0, "const/4", {1}, int64_t(0));
      break;
    case 6:
      Wrapper.instructions[0] = op(0, "move-object", {1, 0});
      break;
    case 7:
      Host.methods[0].reference.name = "other";
      Wrapper.instructions[2].reference = Host.methods[0].reference;
      break;
    case 8:
      Wrapper.reference.parameters.push_back("Ljava/util/List;");
      Wrapper.registers = 4;
      // The target call sees the first input; the capture sees the second.
      Wrapper.instructions.insert(Wrapper.instructions.begin() + 3,
                                  op(3, "move-object", {1, 3}));
      for (size_t i = 0; i < Wrapper.instructions.size(); ++i)
        Wrapper.instructions[i].pc = i;
      Wrapper.code_end = Wrapper.instructions.size();
      break;
    }
    Input[1].enclosing_method = Wrapper.reference;
    Budget B;
    rejected([&] { linkClasses(Input, B); }, "unbound type variable");
  }
}

