TEST(MobileDalvikJava, RepeatedLocalTypeUsesReuseExactScopeFacts) {
  auto Input = nestedAnonymousClasses();
  auto Other = Input[0].methods[0];
  Other.reference.name = "other";
  Input[0].methods.push_back(Other);
  ClassMap Original;
  for (const auto &Cls : Input)
    Original.emplace(Cls.name, Cls);
  Budget B;
  const auto Expected = planSharedAnonymousClasses(Original, B);
  auto &Dense = Original.at(Input[0].name).methods.back();
  Dense.instructions.clear();
  for (unsigned Pair = 0; Pair < 3000; ++Pair) {
    Dense.instructions.push_back(
        op(Pair * 2, "new-instance", {0}, {}, Input[1].name));
    Dense.instructions.push_back(op(Pair * 2 + 1, "invoke-direct", {0}, {},
                                    Input[1].methods[0].reference));
  }
  Dense.instructions.push_back(op(6000, "return-object", {0}));
  Dense.code_end = 6001;
  Budget Limited;
  Limited.remaining = 10000;
  const auto Actual = planSharedAnonymousClasses(Original, Limited);
  ASSERT_EQ(Actual.size(), Expected.size());
  for (const auto &[Name, Plan] : Expected) {
    ASSERT_TRUE(Actual.contains(Name));
    EXPECT_EQ(Actual.at(Name).source_owner, Plan.source_owner);
    EXPECT_EQ(Actual.at(Name).reference_owner, Plan.reference_owner);
    EXPECT_EQ(Actual.at(Name).methods, Plan.methods);
    EXPECT_EQ(Actual.at(Name).declarations, Plan.declarations);
  }
  EXPECT_GT(Limited.remaining, 0u);
}

