      break;
    case 4:
      Make.generic_signature =
          "<T::Ljava/lang/Comparable<-[TT;>;>()Ljava/lang/Object;";
      break;
    case 5:
      Comparable.methods[0].reference.name = "other";
      break;
    case 6:
      Comparable.interfaces = {"Ljava/io/Serializable;"};
      Comparable.generic_signature =
          "<C:Ljava/lang/Object;>Ljava/lang/Object;Ljava/io/Serializable;";
