std::vector<Class> starComparableInvocationClasses(bool External, bool Range,
                                                   bool Facade) {
  auto Input = erasedComparisonInvocationClasses();
  auto &Owner = Input.back();
  auto &Compare = Owner.methods[0];
  Compare.generic_signature = "<K::Ljava/lang/Comparable<*>;>(TK;TK;)I";
  auto Call = Owner.methods[1];
  Owner.methods.pop_back();
  if (Facade) {
    Owner.access.erase("public");
    auto Public = klass("Lfixture/PublicCompare;");
    Public.superclass = Owner.name;
    std::get<MethodRef>(Call.instructions[0].reference).owner = Public.name;
    Public.external = External;
    Input.push_back(Public);
  }
  auto &Declaration = Input[Input.size() - (Facade ? 2 : 1)];
  if (External) {
    Declaration.external = true;
    Declaration.methods[0].instructions.clear();
    Declaration.methods[0].registers = Declaration.methods[0].code_end = 0;
  }
  Call.instructions[0].opcode = Range ? "invoke-static/range" : "invoke-static";
  Input.push_back(klass("Lfixture/Caller;", {Call}));
  return Input;
}

TEST(MobileDalvikJava, StarComparableCallsRetainTheExactErasedEntry) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Facade : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = starComparableInvocationClasses(External, Range, Facade);
          const auto Ref =
              Input[Input.size() - (Facade ? 3 : 2)].methods[0].reference;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                    "<K::Ljava/lang/Comparable<*>;>(TK;TK;)I");
        }
}

TEST(MobileDalvikJava, StarComparableCallsRejectIncompleteBoundContracts) {
  for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
    auto Input = starComparableInvocationClasses(false, true, false);
    auto &Owner = Input[Input.size() - 2];
    auto &Compare = Owner.methods[0];
    if (Mutation == 0)
      Compare.generic_signature =
          "<K::Ljava/lang/Comparable<*>;U:Ljava/lang/Object;>(TK;TK;)I";
    else if (Mutation == 1)
      Compare.generic_signature =
          "<K::Ljava/lang/Comparable<*>;:Ljava/io/Serializable;>(TK;TK;)I";
    else if (Mutation == 2)
      Compare.generic_signature = "<K::Ljava/lang/Comparable<TK;>;>(TK;TK;)I";
    else if (Mutation == 3)
      Compare.generic_signature =
          "<K::Ljava/lang/Comparable<*>;>(TK;Ljava/lang/Comparable;)I";
    else if (Mutation == 4)
      Compare.declared_throws = {"Ljava/lang/Throwable;"};
    else if (Mutation == 5)
      Owner.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 6)
      Compare.access = {"private", "static"};
    else if (Mutation == 7)
      Compare.access.insert("varargs");
    else {
      for (auto &C : Input)
        if (C.name == "Ljava/lang/Comparable;")
          C.fields.push_back(
              {{C.name, "unexpected", "I"}, {"public", "static"}, int64_t(1)});
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error)
        << Mutation;
  }
}

std::vector<Class> erasedResultInvocationClasses(bool Dependency,
                                                 bool Interface, bool Static,
                                                 bool Range,
                                                 bool FormalInput = false) {
  auto Bound = klass("Lfixture/Value;");
  if (Interface)
    Bound.access = {"public", "abstract", "interface"};
  auto Provider = klass("Lfixture/Provider;");
  Provider.external = Dependency;
  if (Interface && !Static)
    Provider.access = {"public", "abstract", "interface"};
  auto Read =
      method("read", {"Ljava/lang/Object;", "I", "J", "D"}, Bound.name, 8,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.reference.owner = Provider.name;
  Read.generic_signature = std::string("<T:") + (Interface ? ":" : "") +
                           Bound.name + ">(Ljava/lang/Object;IJD)TT;";
  if (FormalInput) {
    Read.reference.parameters[0] = Bound.name;
    Read.generic_signature = std::string("<T:") + (Interface ? ":" : "") +
                             Bound.name + ">(TT;IJD)TT;";
  }
  Read.access = {"public"};
  if (Static)
    Read.access.insert("static");
  else if (Interface) {
    Read.access.insert("abstract");
    Read.instructions.clear();
    Read.registers = Read.code_end = 0;
  }
  if (Dependency) {
    Read.instructions.clear();
    Read.registers = Read.code_end = 0;
  }
  Provider.methods = {Read};
  std::vector<std::string> Parameters = Read.reference.parameters;
  if (!Static)
    Parameters.insert(Parameters.begin(), Provider.name);
  std::vector<unsigned> Words;
  for (unsigned I = 1; I <= (Static ? 6 : 7); ++I)
    Words.push_back(I);
  auto Call =
      method("call", Parameters, Bound.name, Static ? 7 : 8,
             {op(0,
                 std::string(Static      ? "invoke-static"
                             : Interface ? "invoke-interface"
                                         : "invoke-virtual") +
                     (Range ? "/range" : ""),
                 Words, {}, Read.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Core;", {Call}), Provider, Bound};
}

std::vector<Class> closedCarrierSeedResultClasses(bool ExternalTarget,
                                                  bool ExternalCarrier,
                                                  bool Facade, bool Range,
                                                  bool FormalFirst, bool Lower,
                                                  unsigned Kind) {
  const bool Interface = Kind != 0;
  const std::string Carrier =
      Kind == 2 ? "Ljava/util/Collection;" : "Lfixture/Carrier;";
  const std::string Element =
      Kind == 2 ? "Ljava/lang/Character;" : "Lfixture/Element;";
  const std::string Context =
      Kind == 2 ? "Ljava/lang/CharSequence;" : "Lfixture/Context;";
  auto Bound = klass(Carrier);
  if (Interface)
    Bound.access = {"public", "abstract", "interface"};
  Bound.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Bound.external = ExternalCarrier;
  auto Leaf = klass(Element);
  Leaf.access.insert("final");
  Leaf.external = ExternalCarrier;
  auto Auxiliary = klass(Context);
  Auxiliary.external = ExternalCarrier;
  if (Kind == 2)
    Auxiliary.access = {"public", "abstract", "interface"};
  auto Collect =
      method("collect",
             FormalFirst ? std::vector<std::string>{Carrier, Context}
                         : std::vector<std::string>{Context, Carrier},
             Carrier, 2, {op(0, "return-object", {FormalFirst ? 0u : 1u})});
  Collect.generic_signature =
      "<R:" + std::string(Interface ? ":" : "") +
      Carrier.substr(0, Carrier.size() - 1) + "<" + (Lower ? "-" : "") +
      Element + ">;>(" + (FormalFirst ? "TR;" + Context : Context + "TR;") +
      ")TR;";
  auto Provider = klass("Lfixture/Provider;", {Collect});
  Provider.external = ExternalTarget;
  if (Facade)
    Provider.access.clear();
  if (ExternalTarget) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Alias = klass("Lfixture/Facade;");
  Alias.superclass = Provider.name;
  Alias.external = ExternalTarget;
  auto Ref = Provider.methods[0].reference;
  if (Facade)
    Ref.owner = Alias.name;
  auto Caller =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Carrier, 3,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {1, 2}, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return {Caller, Provider, Bound, Leaf, Auxiliary, Alias};
}

TEST(MobileDalvikJava, ClosedCarrierBoundsKeepExactOwnSeedAndResult) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarrier : {false, true})
      for (bool Facade : {false, true})
        for (bool Range : {false, true})
          for (bool FormalFirst : {false, true})
            for (bool Lower : {false, true})
              for (unsigned Kind = 0; Kind < 3; ++Kind)
                for (unsigned Route = 0; Route < 3; ++Route) {
                  auto Input = closedCarrierSeedResultClasses(
                      ExternalTarget, ExternalCarrier, Facade, Range,
                      FormalFirst, Lower, Kind);
                  const auto Ref = Input[1].methods[0].reference;
                  const auto Signature = Input[1].methods[0].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                  .erased_generic_invocations.contains(Ref));
                  EXPECT_EQ(recoverJava(Classes, B)
                                .getInteger("unrecovered_method_count"),
                            0);
                  EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                            Signature);
                }
}

TEST(MobileDalvikJava, ClosedCarrierBoundsRejectIncompleteTreesAndFrames) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarrier : {false, true})
      for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
          auto Input = closedCarrierSeedResultClasses(
              ExternalTarget, ExternalCarrier, false, true, false, true, 1);
          auto &Collect = Input[1].methods[0];
          auto replace = [&](const std::string &From, const std::string &To) {
            auto &Signature = *Collect.generic_signature;
            const auto At = Signature.find(From);
            ASSERT_NE(At, std::string::npos);
            Signature.replace(At, From.size(), To);
          };
          switch (Mutation) {
          case 0:
            replace("<-Lfixture/Element;>", "<+Lfixture/Element;>");
            break;
          case 1:
            Input[3].generic_signature =
                "<E:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 2:
            Input[4].generic_signature =
                "<E:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 3:
            Input[2].generic_signature =
                "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 4:
            Input[2].generic_signature =
                "<E:Ljava/lang/Number;>Ljava/lang/Object;";
            break;
          case 5:
            replace("<-Lfixture/Element;>", "<-TR;>");
            break;
          case 6:
            replace("<-Lfixture/Element;>", "<-TU;>");
            break;
          case 7:
            replace(")TR;", ")Lfixture/Carrier;");
            break;
          case 8:
            replace(";TR;)", ";Lfixture/Carrier;)");
            break;
          case 9:
            replace("(Lfixture/Context;TR;)", "(TR;TR;)");
            Collect.reference.parameters[0] =
                Input[0].methods[0].reference.parameters[0] =
                    "Lfixture/Carrier;";
            std::get<MethodRef>(Input[0].methods[0].instructions[0].reference)
                .parameters = Collect.reference.parameters;
            break;
          case 10:
            replace(">(", "U:Ljava/lang/Object;>(");
            break;
          case 11:
            replace(">(", ":Ljava/io/Serializable;>(");
            break;
          case 12:
            Collect.access.insert("native");
            break;
          case 13:
            Collect.access.insert("abstract");
            break;
          case 14:
            Collect.access.insert("varargs");
            break;
          case 15:
            Collect.access.insert("synthetic");
            break;
          case 16:
            Collect.access.insert("bridge");
            break;
          case 17:
            Collect.access = {"private", "static"};
            break;
          case 18:
            Collect.access.erase("static");
            break;
          case 19:
            Collect.declared_throws = {"Ljava/lang/Exception;"};
            break;
          case 20:
            Input[0].methods[0].instructions[0].registers.pop_back();
            break;
          case 21:
            Input[0].methods[0].instructions[1].opcode = "move-result";
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(
              [&] {
                if (Route)
                  recoverJava(linkClasses(Input, B), B);
                else {
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  recoverJava(Classes, B);
                }
              }(),
              std::runtime_error);
        }
}

TEST(MobileDalvikJava, ErasedBoundCallsKeepOneClosedBoundAndExactInputs) {
  for (bool FormalInput : {false, true})
    for (bool Dependency : {false, true})
      for (bool Interface : {false, true})
        for (bool Static : {false, true})
          for (bool Range : {false, true})
            for (bool Reverse : {false, true}) {
              auto Input = erasedResultInvocationClasses(
                  Dependency, Interface, Static, Range, FormalInput);
              const auto Ref = Input[1].methods[0].reference;
              const auto Original = Input[1].methods[0].generic_signature;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              for (bool Linked : {false, true}) {
                SCOPED_TRACE(::testing::Message()
                             << FormalInput << Dependency << Interface << Static
                             << Range << Reverse << Linked);
                ClassMap Classes;
                Budget B;
                if (Linked)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &Cls : Input)
                    Classes.emplace(Cls.name, Cls);
                const auto Plans = validateGenericSignatures(Classes, B);
                EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
                const auto Report = recoverJava(Classes, B);
                const auto *Helpers =
                    Report.getArray("generated_source_helpers");
                ASSERT_NE(Helpers, nullptr);
                EXPECT_TRUE(std::any_of(
                    Helpers->begin(), Helpers->end(), [](const auto &Item) {
                      const auto &Helper = *Item.getAsObject();
                      return Helper.getString("class") == "Lfixture/Core;" &&
                             Helper.getString("name") == "__neverdThrow" &&
                             Helper.getString("kind") == "throw-helper";
                    }));
                EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(
                    Report.getInteger("projected_method_count").value_or(0), 0);
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Original);
              }
            }
}

std::vector<Class> rawReceiverInvocationClasses(bool Dependency, bool Interface,
                                                bool Range, bool ExtraFormal) {
  auto Input =
      erasedResultInvocationClasses(Dependency, Interface, false, Range);
  auto &Provider = Input[1], &Value = Input[2];
  Provider.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Value.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Read = Provider.methods[0], &Call = Input[0].methods[0];
  Read.reference.parameters = {Value.name, "Ljava/lang/Object;", "J", "D"};
  Read.generic_signature =
      std::string(ExtraFormal ? "<U:Ljava/lang/Object;V:TU;>"
                              : "<U:Ljava/lang/Object;>") +
      "(Lfixture/Value<TU;>;TP;JD)Lfixture/Value<+TU;>;";
  Call.reference.parameters = Read.reference.parameters;
  Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                   Provider.name);
  Call.instructions[0].reference = Read.reference;
  return Input;
}

