TEST(MobileDalvikJava, ErasedBooleanCallsRejectUnprovedFormalAndResultShapes) {
  for (unsigned Mutation = 0; Mutation < 6; ++Mutation)
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(Mutation);
      auto Input = erasedBooleanInvocationClasses(true, true, false, false);
      auto &Read = Input[1].methods[0];
      if (Mutation == 0)
        Read.generic_signature =
            "<T:Lfixture/Unknown;>(Lfixture/Creator<Lfixture/Value;>;IJD)Z";
      else if (Mutation == 1)
        Read.generic_signature =
            "<T:Lfixture/Value;>(Lfixture/Creator<+TT;>;IJD)Z";
      else if (Mutation == 2) {
        Read.generic_signature->back() = 'I';
        Read.reference.returns = "I";
        Input[1].methods[1].reference.returns = "I";
        Input[1].methods[1].instructions[0].reference = Read.reference;
      } else if (Mutation == 3)
        Read.generic_signature = "<T:Lfixture/Value;U:Ljava/lang/Object;>"
                                 "(Lfixture/Creator<TT;>;IJD)Z";
      else if (Mutation == 4)
        Read.declared_throws = {"Ljava/lang/Exception;"};
      else {
        auto Caller = Input[1].methods.back();
        Caller.reference.owner = Input[0].name;
        Input[0].methods.push_back(Caller);
        Input[1].methods.pop_back();
      }
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

TEST(MobileDalvikJava, ErasedBooleanCallsFollowOriginalInheritedDeclarations) {
  for (bool Callback : {false, true})
    for (bool Range : {false, true})
      for (bool Linked : {false, true}) {
        auto Input =
            erasedBooleanInvocationClasses(false, Callback, false, Range);
        const auto Ref = Input[1].methods[0].reference;
        auto Alias = klass("Lfixture/Alias;");
        Alias.superclass = Ref.owner;
        std::get<MethodRef>(Input[1].methods[1].instructions[0].reference)
            .owner = Alias.name;
        Input.push_back(Alias);
        Budget B;
        ClassMap Classes;
        if (Linked) {
          std::reverse(Input.begin(), Input.end());
          Classes = linkClasses(Input, B);
        } else
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
        const auto Plan = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plan.erased_generic_invocations.contains(Ref));
        EXPECT_EQ(
            recoverJava(Classes, B).getInteger("unrecovered_method_count"), 0);
        Classes.at(Ref.owner).methods[0].access = {"private", "static"};
        Budget Private;
        // A candidate parent is not an original exact private call site.
        EXPECT_THROW(recoverJava(Classes, Private), std::runtime_error);
      }
}

TEST(MobileDalvikJava, ErasedResultCallsRequireTheirOwnGenericConstraintProof) {
  for (bool Dependency : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(::testing::Message() << Dependency << ":" << Mutation);
      auto Input =
          erasedResultInvocationClasses(Dependency, false, false, true);
      auto &Provider = Input[1];
      auto &Read = Provider.methods[0];
      switch (Mutation) {
      case 0:
        Read.generic_signature = "<T:Lfixture/Value;U:Ljava/lang/Object;>"
                                 "(Ljava/lang/Object;IJD)TT;";
        break;
      case 1:
        Read.generic_signature = "<T:Lfixture/Value;:Ljava/io/Serializable;>"
                                 "(Ljava/lang/Object;IJD)TT;";
        break;
      case 2:
        Read.generic_signature = "<T:Lfixture/Value;>([TT;IJD)TT;";
        Read.reference.parameters[0] = "[Lfixture/Value;";
        Input[0].methods[0].reference.parameters[1] = "[Lfixture/Value;";
        break;
      case 3:
        Provider.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 4:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)Lfixture/Value;";
        break;
      case 5:
        Input[2].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        Read.generic_signature = "<T:Lfixture/Value<Ljava/lang/Object;>;>"
                                 "(Ljava/lang/Object;IJD)TT;";
        break;
      case 6:
        Read.declared_throws = {"Ljava/lang/Throwable;"};
        break;
      case 7:
        Read.access.insert("bridge");
        Read.access.insert("synthetic");
        break;
      case 8:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)[TT;";
        Read.reference.returns = "[Lfixture/Value;";
        Input[0].methods[0].reference.returns = Read.reference.returns;
        break;
      case 9:
        Input[2].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        Read.generic_signature =
            "<T:Lfixture/Value;>(Lfixture/Value<TT;>;IJD)TT;";
        Read.reference.parameters[0] = "Lfixture/Value;";
        Input[0].methods[0].reference.parameters[1] = "Lfixture/Value;";
        break;
      }
      Input[0].methods[0].instructions[0].reference = Read.reference;
      ClassMap Classes;
      for (const auto &Cls : Input)
        Classes.emplace(Cls.name, Cls);
      Budget B;
      const auto Plans = validateGenericSignatures(Classes, B);
      EXPECT_FALSE(Plans.erased_generic_invocations.contains(Read.reference));
      if (Mutation == 3) {
        // This exact generic declaring receiver is raw in Body. Its separate
        // receipt erases the entire instance method type, including T.
        EXPECT_TRUE(Plans.raw_receiver_invocations.contains(Read.reference));
        EXPECT_NO_THROW(recoverJava(Classes, B));
      } else {
        EXPECT_FALSE(Plans.raw_receiver_invocations.contains(Read.reference));
        rejected([&] { recoverJava(Classes, B); },
                 "generic invocation requires");
      }
    }
}

std::vector<Class> erasedFactoryInvocationClasses(bool Dependency, bool Facade,
                                                  bool Invariant) {
  auto Factory = klass("Lfixture/Factory;");
  Factory.access = {"public", "abstract", "interface"};
  Factory.generic_signature = "<F:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Make =
      method("make", {Factory.name, "J"}, Box.name, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Factory<") +
      (Invariant ? "" : "+") + "TT;>;J)Lfixture/Box<TT;>;";
  auto Provider = klass("Lfixture/Provider;", {Make});
  Provider.external = Dependency;
  auto Middle = klass("Lfixture/Middle;");
  Middle.superclass = Provider.name;
  Middle.external = Dependency;
  auto Alias = klass("Lfixture/Facade;");
  Alias.superclass = Middle.name;
  Alias.external = Dependency;
  if (Facade) {
    Provider.access.clear();
    Middle.access.clear();
  }
  if (Dependency) {
    auto &M = Provider.methods[0];
    M.instructions.clear();
    M.registers = M.code_end = 0;
  }
  auto Ref = Provider.methods[0].reference;
  if (Facade)
    Ref.owner = Alias.name;
  auto Call =
      method("call", Ref.parameters, Ref.returns, 4,
             {op(0, "invoke-static", {1, 2, 3}, {}, Ref),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {
      klass("Lfixture/Client;", {Call}), Provider, Middle, Alias, Factory, Box};
}

std::vector<Class> genericOwnerCarrierClasses(bool External, bool Facade,
                                              bool Range, bool Rename,
                                              bool NumericOwner,
                                              unsigned Kind) {
  auto Input = erasedFactoryInvocationClasses(External, Facade, false);
  Input[4].external = Input[5].external = External;
  Input[1].generic_signature =
      std::string("<") + (Rename ? "C" : "T") + ":Ljava/lang/" +
      (NumericOwner ? "Number" : "Object") + ";>Ljava/lang/Object;";
  auto &Make = Input[1].methods[0];
  if (Kind == 1) {
    Make.reference.parameters = {Input[5].name};
    Make.generic_signature =
        "<T:Ljava/lang/Object;>(Lfixture/Box<TT;>;)Lfixture/Box<TT;>;";
    if (!External)
      Make.registers = 2;
  } else if (Kind >= 2) {
    Make.reference.parameters = {"Ljava/lang/Object;", "J"};
    Make.generic_signature = std::string("<T:Ljava/lang/Object;>(") +
                             (Kind == 2 ? "TT;" : "Ljava/lang/Object;") +
                             "J)Lfixture/Box<TT;>;";
  }
  if (Rename) {
    auto &Signature = *Make.generic_signature;
    const auto At = Signature.find("T:Ljava/lang/Object;");
    Signature.replace(At, std::string("T:Ljava/lang/Object;").size(),
                      "C:Ljava/lang/Object;");
    size_t Offset = 0;
    while ((Offset = Signature.find("TT;", Offset)) != std::string::npos) {
      Signature.replace(Offset, 3, "TC;");
      Offset += 3;
    }
  }
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.registers = Kind == 1 ? 2 : 4;
  Call.instructions[0].opcode = Range ? "invoke-static/range" : "invoke-static";
  Call.instructions[0].registers =
      Kind == 1 ? std::vector<unsigned>{1} : std::vector<unsigned>{1, 2, 3};
  Call.instructions[0].reference = Ref;
  auto Root = klass("Ljava/lang/Object;");
  Root.superclass.reset();
  Root.external = true;
  Input.push_back(Root);
  if (NumericOwner) {
    auto Number = klass("Ljava/lang/Number;");
    Number.access = {"public", "abstract"};
    Number.external = true;
    Input.push_back(Number);
  }
  return Input;
}

TEST(MobileDalvikJava, GenericOwnersKeepIndependentStaticCarrierFormals) {
  for (bool External : {false, true})
    for (bool Facade : {false, true})
      for (bool Range : {false, true})
        for (bool Rename : {false, true})
          for (bool NumericOwner : {false, true})
            for (unsigned Kind = 0; Kind < 4; ++Kind)
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{External, Facade, Range, Rename, NumericOwner,
                               Kind, Route}));
                auto Input = genericOwnerCarrierClasses(
                    External, Facade, Range, Rename, NumericOwner, Kind);
                const auto Ref = Input[1].methods[0].reference;
                const auto Original = Input[1].methods[0].generic_signature;
                const auto Owner = Input[1].generic_signature;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Original);
                EXPECT_EQ(Classes.at(Ref.owner).generic_signature, Owner);
              }
}

TEST(MobileDalvikJava, GenericOwnersDoNotSupplyUnprovedStaticMethodBindings) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input =
            genericOwnerCarrierClasses(External, false, true, false, false, 1);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        const auto Ref = Make.reference;
        if (Mutation >= 1 && Mutation <= 3)
          Input[1].generic_signature =
              "<T:Ljava/lang/Object;C:Ljava/lang/Object;>Ljava/lang/Object;";
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &Text = *Make.generic_signature;
          const auto At = Text.find(From);
          ASSERT_NE(At, std::string::npos);
          Text.replace(At, From.size(), To);
        };
        if (Mutation == 0) {
          Make.access.erase("static");
          if (!External)
            Make.registers = 3;
        } else if (Mutation == 1)
          replace("(Lfixture/Box<TT;>", "(Lfixture/Box<TC;>");
        else if (Mutation == 2)
          replace(")Lfixture/Box<TT;>", ")Lfixture/Box<TC;>");
        else if (Mutation == 3)
          replace("T:Ljava/lang/Object;", "T:TC;");
        else if (Mutation == 4)
          replace("T:Ljava/lang/Object;", "T:TUnknown;");
        else if (Mutation == 5)
          replace("T:Ljava/lang/Object;>",
                  "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        else if (Mutation == 6)
          replace("(Lfixture/Box<TT;>", "(Lfixture/Box<TT;TT;>");
        else if (Mutation == 7)
          replace(")Lfixture/Box<TT;>", ")Lfixture/Box<TT;TT;>");
        else if (Mutation == 8)
          Make.reference.returns = "Ljava/lang/Object;";
        else if (Mutation == 9)
          Make.reference.parameters[0] = "Ljava/lang/Object;";
        else if (Mutation == 10)
          Make.declared_throws = {"Ljava/lang/Exception;"};
        else if (Mutation == 11)
          *Make.generic_signature += "^TT;";
        else if (Mutation == 12)
          Make.access.insert("bridge");
        else if (Mutation == 13)
          Make.access = {"private", "static"};
        else if (Mutation == 14)
          Call.instructions[0].registers.clear();
        else if (Mutation == 15)
          Call.instructions[0].opcode = "invoke-virtual/range";
        else if (Mutation == 16)
          Call.instructions[1].opcode = "move-result-wide";
        else if (Mutation == 17)
          Input[1].generic_signature = "<C:Ljava/lang/Object;>I";
        else if (Mutation == 18)
          Call.instructions[0].registers[0] = Call.registers;
        else
          Input[1].generic_signature =
              "<S:Ljava/lang/Object;>Ljava/lang/Object;";
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Mutation == 0) {
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          EXPECT_FALSE(validateGenericSignatures(Classes, B)
                           .erased_generic_invocations.contains(Ref));
          continue;
        }
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

std::vector<Class> comparableSelectorCarrierClasses(bool ExternalTarget,
                                                    bool ExternalCarriers,
                                                    bool Facade, bool Range,
                                                    bool ShadowOwner,
                                                    unsigned Variance) {
  auto Input = erasedFactoryInvocationClasses(ExternalTarget, Facade, true);
  Input[4].generic_signature =
      "<I:Ljava/lang/Object;O:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[4].external = Input[5].external = ExternalCarriers;
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[5].name, Input[4].name};
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;K::Ljava/lang/Comparable<-TK;>;>(") +
      "Lfixture/Box<TT;>;Lfixture/Factory<" + (Variance & 1 ? "" : "-") +
      "TT;" + (Variance & 2 ? "" : "+") + "TK;>;)Lfixture/Box<TT;>;";
  if (ShadowOwner)
    Input[1].generic_signature = "<K:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.registers = 3;
  Call.instructions[0].opcode = Range ? "invoke-static/range" : "invoke-static";
  Call.instructions[0].registers = {1, 2};
  Call.instructions[0].reference = Ref;
  auto Compare = method("compareTo", {"Ljava/lang/Object;"}, "I", 0, {});
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TC;)I";
  auto Comparable = klass("Ljava/lang/Comparable;", {Compare});
  Comparable.access = {"public", "abstract", "interface"};
  Comparable.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Comparable.external = true;
  Input.push_back(Comparable);
  return Input;
}

std::vector<Class> producerCallbackCarrierClasses(bool ExternalTarget,
                                                  bool ExternalCarriers,
                                                  bool Facade, bool Range,
                                                  bool ShadowOwner,
                                                  unsigned Variance) {
  auto Input = erasedFactoryInvocationClasses(ExternalTarget, Facade, true);
  Input[4].generic_signature = "<A:Ljava/lang/Object;C:Ljava/lang/"
                               "Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[4].external = Input[5].external = ExternalCarriers;
  auto Completion = klass("Lfixture/Completion;");
  Completion.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Completion.external = ExternalCarriers;
  auto Closed = klass("Lfixture/Closed;");
  Closed.external = ExternalCarriers;
  auto Root = klass("Ljava/lang/Object;");
  Root.superclass.reset();
  Root.external = true;
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[5].name, Input[4].name};
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Box<") +
      (Variance & 1 ? "" : "+") + "TT;>;Lfixture/Factory<" +
      (Variance & 2 ? "" : "-") + "TT;" + (Variance & 4 ? "" : "-") +
      "Lfixture/Completion<" + (Variance & 8 ? "" : "-") +
      "Lfixture/Closed;>;" + (Variance & 16 ? "" : "+") +
      "Ljava/lang/Object;>;)Lfixture/Box<TT;>;";
  if (ShadowOwner)
    Input[1].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.registers = 3;
  Call.instructions[0].opcode = Range ? "invoke-static/range" : "invoke-static";
  Call.instructions[0].registers = {1, 2};
  Call.instructions[0].reference = Ref;
  Input.push_back(Completion);
  Input.push_back(Closed);
  Input.push_back(Root);
  return Input;
}

TEST(MobileDalvikJava, ProducerCallbackCarriersKeepCompleteClosedCompletion) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarriers : {false, true})
      for (bool Facade : {false, true})
        for (bool Range : {false, true})
          for (bool ShadowOwner : {false, true})
            for (unsigned Variance = 0; Variance < 32; ++Variance)
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{ExternalTarget, ExternalCarriers, Facade, Range,
                               ShadowOwner, Variance, Route}));
                auto Input = producerCallbackCarrierClasses(
                    ExternalTarget, ExternalCarriers, Facade, Range,
                    ShadowOwner, Variance);
                const auto Ref = Input[1].methods[0].reference;
                const auto Signature = Input[1].methods[0].generic_signature;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Signature);
              }
}

