std::vector<Class> checkedStarSuperClasses(unsigned BoundKind, bool Multiple,
                                           bool ReuseIncoming,
                                           unsigned InputKind,
                                           unsigned CopyForm, bool Range,
                                           bool External) {
  auto Element = klass("Lfixture/Element;");
  if (BoundKind == 2)
    Element.access = {"public", "abstract", "interface"};
  Element.external = External;
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.access = {"public", "abstract", "interface"};
  Carrier.external = External;
  Carrier.generic_signature = std::string("<E:") +
                              (BoundKind == 0   ? "Ljava/lang/Object;"
                               : BoundKind == 1 ? "Lfixture/Element;"
                                                : ":Lfixture/Element;") +
                              (Multiple ? "F:Ljava/lang/Object;" : "") +
                              ">Ljava/lang/Object;";
  const MethodRef RootInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Init =
      method("<init>", {Carrier.name}, "V", 2,
             {op(0, "invoke-direct", {0}, {}, RootInit), op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature =
      std::string("(Lfixture/Carrier<") + (Multiple ? "**" : "*") + ">;)V";
  auto Other =
      method("<init>", {"Ljava/lang/Object;"}, "V", 2,
             {op(0, "invoke-direct", {0}, {}, RootInit), op(1, "return-void")});
  Other.access = {"public", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init, Other});
  Parent.external = External;
  if (External)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const unsigned Self = ReuseIncoming ? 0 : Range ? 2 : 1;
  const bool Reordered = Range && ReuseIncoming;
  const unsigned Key = Self + (Reordered ? 2 : 1);
  const unsigned Left = Self + (Reordered ? 1 : 2);
  const unsigned Destination = Range           ? (ReuseIncoming ? Self + 1 : 1)
                               : ReuseIncoming ? Self + 2
                                               : 0;
  const unsigned Receiver = Range && !ReuseIncoming ? 0 : Self;
  const FieldRef First{"Lfixture/Child;", "first", "Ljava/lang/Object;"};
  const FieldRef Second{First.owner, "second", "Ljava/lang/Object;"};
  const auto Copy = std::array{"move-object", "move-object/from16",
                               "move-object/16"}[CopyForm];
  const auto InputType = InputKind ? Carrier.name : "Ljava/lang/Object;";
  auto ChildInit = method(
      "<init>",
      {Reordered ? "Ljava/lang/Object;" : InputType,
       Reordered ? InputType : "Ljava/lang/Object;", "Ljava/lang/Object;"},
      "V", Self + 4,
      {op(0, "iput-object", {Left, Self}, {}, First),
       op(1, "iput-object", {Self + 3, Self}, {}, Second),
       op(2, Copy, {Destination, Key}),
       InputKind == 2 ? op(3, "nop")
                      : op(3, "check-cast", {Destination}, {}, Carrier.name),
       op(4, Range ? "invoke-direct/range" : "invoke-direct",
          {Receiver, Destination}, {}, Parent.methods[0].reference),
       op(5, "return-void")});
  if (Range && !ReuseIncoming) {
    for (size_t I = 2; I < ChildInit.instructions.size(); ++I)
      ++ChildInit.instructions[I].pc;
    ChildInit.instructions.insert(ChildInit.instructions.begin() + 2,
                                  op(2, Copy, {Receiver, Self}));
    ++ChildInit.code_end;
  }
  ChildInit.access = {"public", "constructor"};
  auto Child = klass(First.owner, {ChildInit});
  Child.access = {"public", "final"};
  Child.superclass = Parent.name;
  Child.fields = {{First, {"public", "final"}, {}},
                  {Second, {"public", "final"}, {}}};
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Child, Parent, Carrier, Element, Object};
}

TEST(MobileDalvikJava,
     CheckedStarSuperConstructorsKeepCompleteReifiableBinding) {
  for (unsigned BoundKind = 0; BoundKind < 3; ++BoundKind)
    for (bool Multiple : {false, true})
      for (bool ReuseIncoming : {false, true})
        for (unsigned InputKind = 0; InputKind < 3; ++InputKind)
          for (unsigned CopyForm = 0; CopyForm < 3; ++CopyForm)
            for (bool Range : {false, true})
              for (bool External : {false, true})
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{BoundKind, Multiple, ReuseIncoming, InputKind,
                                 CopyForm, Range, External, Route}));
                  auto Input = checkedStarSuperClasses(
                      BoundKind, Multiple, ReuseIncoming, InputKind, CopyForm,
                      Range, External);
                  const auto Caller = Input[0].methods[0].reference;
                  const auto Target = Input[1].methods[0].reference;
                  const auto Signature = Input[1].methods[0].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(
                      Plans.superclass_calls.contains({Caller, Target}));
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                            0);
                  EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
                  EXPECT_EQ(
                      Classes.at(Target.owner).methods[0].generic_signature,
                      Signature);
                  EXPECT_FALSE(
                      Classes.at(Caller.owner).methods[0].generic_signature);
                }
}

TEST(MobileDalvikJava,
     CheckedStarSuperConstructorsRejectUnprovedCarriersAndFrames) {
  for (bool ReuseIncoming : {false, true})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(::testing::PrintToString(
            std::tuple{ReuseIncoming, Mutation, Route}));
        auto Input = checkedStarSuperClasses(2, false, ReuseIncoming, 0, 1,
                                             false, false);
        auto &M = Input[0].methods[0];
        const unsigned Self = ReuseIncoming ? 0 : 1;
        const unsigned Destination = ReuseIncoming ? Self + 2 : 0;
        if (Mutation == 0)
          M.instructions[3] = op(3, "nop");
        else if (Mutation == 1)
          M.instructions[3].reference = Input[3].name;
        else if (Mutation == 2)
          Input.erase(Input.begin() + 2);
        else if (Mutation == 3)
          Input.erase(Input.begin() + 3);
        else if (Mutation == 4)
          Input[2].generic_signature =
              "<E::Lmissing/Element;>Ljava/lang/Object;";
        else if (Mutation == 5)
          Input[2].generic_signature =
              "<E::Lfixture/Element;F:Ljava/lang/Object;>Ljava/lang/Object;";
        else if (Mutation == 6)
          Input[1].methods[0].generic_signature =
              "(Lfixture/Carrier<+Lfixture/Element;>;)V";
        else if (Mutation == 7)
          Input[1].methods[0].generic_signature =
              "(Lfixture/Carrier<Lfixture/Element;>;)V";
        else if (Mutation == 8)
          Input[1].methods[0].generic_signature =
              "<X:Ljava/lang/Object;>(Lfixture/Carrier<*>;)V";
        else if (Mutation == 9)
          Input[1].methods[0].access.insert("varargs");
        else if (Mutation == 10)
          Input[1].methods[1].access.insert("varargs");
        else if (Mutation == 11)
          Input[1].methods[0].generic_signature = "(Lfixture/Element;)V";
        else if (Mutation == 12)
          M.tries = {{0, 5, {{std::nullopt, 5}}}};
        else if (Mutation == 13)
          M.instructions[2].registers[1] = Self;
        else if (Mutation == 14) {
          M.instructions[2].registers[0] = Self;
          M.instructions[3].registers[0] = Self;
          M.instructions[4].registers[1] = Self;
        } else if (Mutation == 15)
          M.instructions[4].registers.pop_back();
        else if (Mutation == 16)
          M.instructions[4].opcode = "invoke-virtual";
        else if (Mutation == 17)
          M.instructions[2].reference = std::string("Ljava/lang/Object;");
        else if (Mutation == 18)
          M.instructions[2].target = 4;
        else
          M.instructions[2] =
              op(2, "move-wide/from16", {Destination, Self + 1});
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

