TEST(MobileDalvikJava, ComparableSelectorCarriersRejectIncompleteRelations) {
  for (unsigned Mutation = 0; Mutation < 18; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          comparableSelectorCarrierClasses(false, false, false, true, false, 0);
      auto &Make = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        replace("Comparable<-TK;>", "Comparable<+TK;>");
        break;
      case 1:
        replace("Comparable<-TK;>", "Comparable<-TT;>");
        break;
      case 2:
        replace("Factory<-TT;+TK;>", "Factory<-TK;+TT;>");
        break;
      case 3:
        replace("Box<TT;>;Lfixture/Factory", "Box<+TT;>;Lfixture/Factory");
        break;
      case 4:
        replace(")Lfixture/Box<TT;>;", ")Lfixture/Box<TK;>;");
        break;
      case 5:
        replace("Factory<-TT;+TK;>", "Factory<+TT;+TK;>");
        break;
      case 6:
        replace("Factory<-TT;+TK;>", "Factory<-TT;-TK;>");
        break;
      case 7:
        Input[4].generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 8:
        Input[5].generic_signature = "<B:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 9:
        Input.back().methods[0].generic_signature = "(Ljava/lang/Object;)I";
        break;
      case 10:
        Input.back().access.erase("public");
        break;
      case 11:
        Make.access.insert("varargs");
        break;
      case 12:
        Make.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 13:
        Make.access.insert("native");
        Make.instructions.clear();
        Make.registers = Make.code_end = 0;
        break;
      case 14:
        Make.access.insert("bridge");
        break;
      case 15:
        Input[0].methods[0].instructions[0].opcode = "invoke-virtual/range";
        break;
      case 16:
        Make.reference.parameters[1] = "Ljava/lang/Object;";
        Input[0].methods[0].instructions[0].reference = Make.reference;
        break;
      case 17:
        replace("T:Ljava/lang/Object;K::",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;K::");
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      if (Route)
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class>
comparableSelectorPredicateClasses(bool ExternalTarget, bool ExternalCarriers,
                                   bool Facade, bool Range, bool ShadowOwner,
                                   unsigned Variance, bool Value) {
  auto Input = comparableSelectorCarrierClasses(
      ExternalTarget, ExternalCarriers, Facade, Range, ShadowOwner, Variance);
  auto &Make = Input[1].methods[0];
  Make.reference.returns = "Z";
  auto &Signature = *Make.generic_signature;
  const std::string Before = ")Lfixture/Box<TT;>;";
  Signature.replace(Signature.find(Before), Before.size(), ")Z");
  if (!ExternalTarget) {
    Make.registers = 2;
    Make.instructions = {op(0, "const/4", {0}, int64_t(Value ? 1 : 0)),
                         op(1, "return", {0})};
    Make.code_end = 2;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.returns = "Z";
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Call.instructions[0].reference = std::move(Ref);
  Call.instructions[1].opcode = "move-result";
  Call.instructions[2].opcode = "return";
  return Input;
}

