std::vector<Class> privateUnaryFactoryClasses(bool Static, bool Invariant,
                                              bool ExternalCarriers,
                                              bool Range) {
  auto Input = erasedFactoryInvocationClasses(false, false, Invariant);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  Make.reference.parameters = {Input[4].name};
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Factory<") +
      (Invariant ? "" : "+") + "TT;>;)Lfixture/Box<TT;>;";
  Make.access = {"private", "final"};
  if (Static)
    Make.access.insert("static");
  Make.registers = 3;
  const auto Ref = Make.reference;
  auto Parameters = Ref.parameters;
  if (!Static)
    Parameters.insert(Parameters.begin(), Owner.name);
  auto Call = method(
      "call", Parameters, Ref.returns, Static ? 2 : 3,
      {op(0,
          std::string(Static ? "invoke-static" : "invoke-direct") +
              (Range ? "/range" : ""),
          Static ? std::vector<unsigned>{1} : std::vector<unsigned>{1, 2}, {},
          Ref),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.reference.owner = Owner.name;
  Owner.methods.push_back(Call);
  Input[4].external = Input[5].external = ExternalCarriers;
  Input.erase(Input.begin());
  return Input;
}

TEST(MobileDalvikJava, PrivateUnaryFactoriesRetainScopedCarrierRelations) {
  for (bool Static : {false, true})
    for (bool Invariant : {false, true})
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input =
                privateUnaryFactoryClasses(Static, Invariant, External, Range);
            const auto Ref = Input[0].methods[0].reference;
            const auto Signature = Input[0].methods[0].generic_signature;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto Classes = linkClasses(Input, B);
            ASSERT_TRUE(validateGenericSignatures(Classes, B)
                            .erased_generic_invocations.contains(Ref));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
            EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                      Signature);
          }
}

TEST(MobileDalvikJava, PrivateUnaryFactoriesRejectScopeAndContractDrift) {
  for (bool Static : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(Static);
      SCOPED_TRACE(Mutation);
      auto Input = privateUnaryFactoryClasses(Static, false, false, true);
      auto &Owner = Input[0];
      auto &Make = Owner.methods[0];
      auto replace = [&](std::string From, std::string To) {
        auto &Signature = *Make.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0) {
        // Keeping a valid local call must not grant a foreign caller access.
        auto Call = Owner.methods[1];
        Input.push_back(klass("Lfixture/Foreign;", {Call}));
      } else if (Mutation == 1) {
        std::get<MethodRef>(Owner.methods[1].instructions[0].reference).owner =
            Input[2].name;
      } else if (Mutation == 2)
        replace("<+TT;>", "<-TT;>");
      else if (Mutation == 3)
        replace("Box<TT;>", "Box<+TT;>");
      else if (Mutation == 4)
        replace("Box<TT;>", "Box<Ljava/lang/Object;>");
      else if (Mutation == 5)
        replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 6)
        Input[3].generic_signature.reset();
      else if (Mutation == 7)
        Input[4].generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 8)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 9)
        Make.access.insert("varargs");
      else if (Mutation == 10)
        Make.access.insert("bridge");
      else if (Mutation == 11) {
        Make.access.insert("native");
        Make.instructions.clear();
        Make.registers = Make.code_end = 0;
      } else if (Mutation == 12)
        Owner.methods[1].instructions[0].opcode = "invoke-virtual/range";
      else if (Mutation == 13)
        Input[3].access.clear();
      else if (Mutation == 14)
        Input[4].access.clear();
      else {
        auto Call = Owner.methods[1];
        Owner.external = true;
        Owner.methods.pop_back();
        Make.instructions.clear();
        Make.registers = Make.code_end = 0;
        Input.push_back(klass("Lfixture/Foreign;", {Call}));
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> nullaryCarrierFactoryClasses(bool Dependency, bool Facade,
                                                bool Range) {
  auto Input = erasedFactoryInvocationClasses(Dependency, Facade, true);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters.clear();
  Make.generic_signature = "<T:Ljava/lang/Object;>()Lfixture/Box<TT;>;";
  if (!Dependency)
    Make.registers = 1;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] = klass(
      "Lfixture/Client;",
      {method(
          "call", {}, Ref.returns, 1,
          {op(0, Range ? "invoke-static/range" : "invoke-static", {}, {}, Ref),
           op(1, "move-result-object", {0}), op(2, "return-object", {0})})});
  if (Dependency)
    for (size_t I = 4; I < Input.size(); ++I)
      Input[I].external = true;
  return Input;
}

std::vector<Class> privateNestedCarrierClasses(bool GenericOwner, bool External,
                                               bool Range, bool Frame,
                                               bool Rename) {
  auto Owner = klass("Lfixture/Owner;");
  const std::string Formal = Rename ? "V" : "T";
  if (GenericOwner)
    Owner.generic_signature =
        "<" + Formal + ":Ljava/lang/Object;>Ljava/lang/Object;";
  auto Atom = klass("Lfixture/Atom;");
  Atom.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Atom.external = External;
  auto Hidden = klass("Lfixture/Owner$Hidden;");
  Hidden.access = {"final"};
  Hidden.generic_signature = "<H:Ljava/lang/Object;>Ljava/lang/Object;";
  Hidden.enclosing = Owner.name;
  Hidden.inner_name = "Hidden";
  Hidden.inner_class_present = true;
  Hidden.inner_access = {"private", "static", "final"};
  auto Keep =
      method("keep", {Atom.name}, Atom.name, 1, {op(0, "return-object", {0})});
  Keep.reference.owner = Owner.name;
  Keep.access = {"private", "static"};
  const auto Carrier =
      "Lfixture/Atom<Lfixture/Owner$Hidden<T" + Formal + ";>;>;";
  Keep.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(" + Carrier + ")" + Carrier;
  auto Call =
      method("call", {Atom.name}, Atom.name, 2,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1}, {},
                 Keep.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.reference.owner = Owner.name;
  Owner.methods = {Keep, Call};
  if (Frame)
    for (auto &M : Owner.methods) {
      M.registers += 3;
      for (auto &Op : M.instructions)
        for (auto &Reg : Op.registers)
          Reg += 3;
    }
  return {Owner, Hidden, Atom};
}

TEST(MobileDalvikJava,
     PrivateNestedCarriersKeepMethodShadowingAndCompleteInvariantTrees) {
  for (bool GenericOwner : {false, true})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Frame : {false, true})
          for (bool Rename : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  GenericOwner, External, Range, Frame, Rename, Route}));
              auto Input = privateNestedCarrierClasses(GenericOwner, External,
                                                       Range, Frame, Rename);
              const auto Target = Input[0].methods[0].reference;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              EXPECT_NO_THROW({
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Target));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              });
            }
}

TEST(MobileDalvikJava, PrivateNestedCarriersRejectForeignScopesAndOpenTrees) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{External, Mutation}));
      auto Input =
          privateNestedCarrierClasses(true, External, true, false, false);
      auto &Owner = Input[0];
      auto &Hidden = Input[1];
      auto &Keep = Owner.methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        const auto At = Keep.generic_signature->find(From);
        ASSERT_NE(At, std::string::npos);
        Keep.generic_signature->replace(At, From.size(), To);
      };
      if (Mutation == 0)
        Hidden.external = true;
      else if (Mutation == 1)
        Hidden.inner_access.erase("static");
      else if (Mutation == 2)
        Hidden.enclosing = "Lfixture/Foreign;";
      else if (Mutation == 3)
        Hidden.inner_class_present = false;
      else if (Mutation == 4)
        Hidden.inner_name.reset();
      else if (Mutation == 5)
        Hidden.inner_access.erase("private");
      else if (Mutation == 6)
        Hidden.generic_signature = "<H:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 7)
        Input[2].generic_signature = "<A:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 8)
        Input[2].generic_signature.reset();
      else if (Mutation == 9)
        replace("<T:Ljava/lang/Object;>", "<V:Ljava/lang/Object;>");
      else if (Mutation == 10)
        replace("Hidden<TT;>", "Hidden<+TT;>");
      else if (Mutation == 11)
        replace("Hidden<TT;>", "Hidden<*>");
      else if (Mutation == 12)
        Keep.access = {"public", "static"};
      else if (Mutation == 13)
        Keep.access.erase("static");
      else if (Mutation == 14)
        Keep.access.insert("synthetic");
      else if (Mutation == 15)
        Keep.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 16) {
        auto ForeignCall = Owner.methods[1];
        ForeignCall.reference.owner = "Lfixture/Foreign;";
        Input.push_back(klass(ForeignCall.reference.owner, {ForeignCall}));
      } else
        Owner.methods[1].instructions[0].registers = {0};
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

