std::vector<Class> privateNullaryCarrierClasses(bool PublicCarrier,
                                                bool ExternalView, bool Range) {
  auto Input = nullaryCarrierFactoryClasses(false, false, Range);
  auto &Provider = Input[1];
  Provider.methods[0].access = {"private", "static", "final"};
  auto Call = Input[0].methods[0];
  Call.reference.owner = Provider.name;
  Provider.methods.push_back(Call);
  Input.erase(Input.begin());
  auto &Box = Input[4];
  Box.access = PublicCarrier ? std::set<std::string>{"public", "final"}
                             : std::set<std::string>{"final"};
  Box.generic_signature =
      "<E:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/View<TE;>;";
  Box.interfaces = {"Lfixture/View;"};
  auto View = klass("Lfixture/View;");
  View.access = {"public", "interface", "abstract"};
  View.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  View.external = ExternalView;
  Input.push_back(View);
  return Input;
}

