TEST(MobileDalvikJava,
     PrivateNullaryCarrierFactoriesRejectScopeAndResultDrift) {
  for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = privateNullaryCarrierClasses(false, false, true);
    auto &Owner = Input[0];
    auto &Make = Owner.methods[0];
    auto &Box = Input[4];
    auto replace = [&](std::string From, std::string To) {
      auto &Signature = *Make.generic_signature;
      const auto At = Signature.find(From);
      ASSERT_NE(At, std::string::npos);
      Signature.replace(At, From.size(), To);
    };
    if (Mutation == 0) {
      auto Call = Owner.methods[1];
      Owner.methods.pop_back();
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 1) {
      auto Alias = klass("Lfixture/Alias;");
      Alias.superclass = Owner.name;
      std::get<MethodRef>(Owner.methods[1].instructions[0].reference).owner =
          Alias.name;
      Input.push_back(Alias);
    } else if (Mutation == 2) {
      auto Call = Owner.methods[1];
      Owner.external = true;
      Owner.methods.pop_back();
      Owner.methods[0].instructions.clear();
      Owner.methods[0].registers = Owner.methods[0].code_end = 0;
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 3)
      Box.external = true;
    else if (Mutation == 4) {
      Box.name = "Lforeign/Box;";
      replace("Lfixture/Box<", "Lforeign/Box<");
      Make.reference.returns = Owner.methods[1].reference.returns = Box.name;
      std::get<MethodRef>(Owner.methods[1].instructions[0].reference).returns =
          Box.name;
    } else if (Mutation == 5)
      Box.access.insert("private");
    else if (Mutation == 6)
      Box.access.insert("protected");
    else if (Mutation == 7)
      Box.enclosing = Owner.name;
    else if (Mutation == 8)
      Box.generic_signature.reset();
    else if (Mutation == 9)
      replace("Box<TT;>", "Box<+TT;>");
    else if (Mutation == 10)
      replace("T:Ljava/lang/Object;>",
              "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
    else if (Mutation == 11)
      Box.generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
    else if (Mutation == 12)
      Make.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 13)
      Make.access.insert("varargs");
    else
      Make.access.erase("static");
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

TEST(MobileDalvikJava, NullaryCarrierFactoriesRejectChangedBoundsAndResults) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = nullaryCarrierFactoryClasses(External, true, true);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      if (Mutation == 0)
        replace("T:Ljava/lang/Object;>", "T:Ljava/lang/Number;>");
      else if (Mutation == 1)
        replace("Box<TT;>", "Box<+TT;>");
      else if (Mutation == 2)
        replace("Box<TT;>", "Box<Ljava/lang/Object;>");
      else if (Mutation == 3)
        replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 4)
        Input[5].generic_signature = "<B:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 5)
        replace("Box<TT;>", "Box<*>");
      else if (Mutation == 6)
        Input.pop_back();
      else if (Mutation == 7)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 8)
        Make.access = {"private", "static"};
      else if (Mutation == 9)
        Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 10) {
        Make.access.erase("static");
        if (!External)
          ++Make.registers;
        Call.reference.parameters = {Input[3].name};
        Call.registers = 2;
        Call.instructions[0].opcode = "invoke-virtual/range";
        Call.instructions[0].registers = {1};
      } else if (Mutation == 11)
        replace("Box<TT;>", "Box<[TT;>");
      else {
        // A direct formal result still needs the closed-bound proof. This
        // model has no Object declaration to supply that separate receipt.
        replace("Lfixture/Box<TT;>;", "TT;");
        Make.reference.returns = Call.reference.returns = "Ljava/lang/Object;";
        std::get<MethodRef>(Call.instructions[0].reference).returns =
            Make.reference.returns;
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> nullaryPairFactoryClasses(bool Dependency, bool Facade,
                                             bool Range, bool Swapped = false) {
  auto Input = nullaryCarrierFactoryClasses(Dependency, Facade, Range);
  Input[1].methods[0].generic_signature =
      std::string("<K:Ljava/lang/Object;V:Ljava/lang/Object;>()Lfixture/Box<") +
      (Swapped ? "TV;TK;>;" : "TK;TV;>;");
  Input[5].generic_signature =
      "<First:Ljava/lang/Object;Second:Ljava/lang/Object;>Ljava/lang/Object;";
  return Input;
}

std::vector<Class> reifiableCarrierFactoryClasses(bool SDK, bool Facade,
                                                  bool Range) {
  auto Input = nullaryCarrierFactoryClasses(SDK, Facade, Range);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[4].name};
  Make.generic_signature =
      "<T:Ljava/lang/Object;>(Lfixture/Factory<*>;)Lfixture/Box<TT;>;";
  if (!SDK)
    Make.registers = 2;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.registers = 2;
  Call.instructions[0].registers = {1};
  Call.instructions[0].reference = Ref;
  if (Facade) {
    Input[0].name = "Lother/Client;";
    Call.reference.owner = Input[0].name;
  }
  return Input;
}

