std::vector<Class> privateSeededPrimitiveClasses(const std::string &Returns,
                                                 bool Range, bool Alpha,
                                                 unsigned Gap, bool Final) {
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  const bool Wide = Returns == "J" || Returns == "D";
  const unsigned ResultWords = Wide ? 2 : 1;
  const unsigned Receiver = ResultWords + Gap;
  auto Select =
      method("select", {Callback.name, "Ljava/lang/Object;"}, Returns,
             ResultWords + Gap + 3,
             {op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
              op(Wide ? 2 : 1, Wide ? "return-wide" : "return", {0})});
  Select.reference.owner = "Lfixture/Subject;";
  Select.access = {"private", "final"};
  const std::string Formal = Alpha ? "Value" : "T";
  Select.generic_signature = "<" + Formal +
                             ":Ljava/lang/Object;>(Lfixture/Callback<-T" +
                             Formal + ";>;T" + Formal + ";)" + Returns;
  auto Call = method(
      "call", Select.reference.parameters, Returns, ResultWords + Gap + 3,
      {op(0, Range ? "invoke-direct/range" : "invoke-direct",
          {Receiver, Receiver + 1, Receiver + 2}, {}, Select.reference),
       op(3, Wide ? "move-result-wide" : "move-result", {0}),
       op(4, Wide ? "return-wide" : "return", {0})});
  Call.access = {"public"};
  auto Subject = klass("Lfixture/Subject;", {Select, Call});
  if (Final)
    Subject.access.insert("final");
  return {Subject, Callback};
}

std::vector<Class> privateDirectPrimitiveClasses(const std::string &Returns,
                                                 bool Range, bool Alpha,
                                                 unsigned Gap, bool Final,
                                                 bool FinalMethod = false) {
  auto Input = privateSeededPrimitiveClasses(Returns, Range, Alpha, Gap, Final);
  const unsigned ResultWords = Returns == "J" || Returns == "D" ? 2 : 1;
  const unsigned Receiver = ResultWords + Gap;
  auto &Select = Input[0].methods[0];
  Select.reference.parameters = {"Ljava/lang/Object;"};
  Select.access = FinalMethod ? Access{"private", "final"} : Access{"private"};
  const std::string Formal = Alpha ? "Value" : "T";
  Select.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(T" + Formal + ";)" + Returns;
  Select.registers = ResultWords + Gap + 2;
  auto &Call = Input[0].methods[1];
  Call.reference.parameters = Select.reference.parameters;
  Call.registers = Select.registers;
  Call.instructions[0].registers = {Receiver, Receiver + 1};
  Call.instructions[0].reference = Select.reference;
  Input[1] = klass("Lfixture/Tag;");
  return Input;
}

