TEST(MobileDalvikJava,
     PrivateDirectPrimitivesRejectMissingSeedsAndForeignAccess) {
  for (unsigned Mutation = 0; Mutation < 17; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = privateDirectPrimitiveClasses("I", true, false, 0, false);
    auto &Select = Input[0].methods[0];
    switch (Mutation) {
    case 0:
      Select.generic_signature = "<T:Ljava/lang/Number;>(TT;)I";
      break;
    case 1:
      Select.generic_signature = "<T:Ljava/lang/Object;>(Ljava/lang/Object;)I";
      break;
    case 2:
      Select.generic_signature = "<T:Ljava/lang/Object;>(TMissing;)I";
      break;
    case 3:
      Select.generic_signature =
          "<T:Ljava/lang/Object;U:Ljava/lang/Object;>(TT;)I";
      break;
    case 4:
      Select.declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 5:
      Select.access.insert("native");
      break;
    case 6:
      Input[0].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 7:
      Select.access.insert("varargs");
      break;
    case 8:
      Select.access.insert("synthetic");
      break;
    case 9:
      Select.generic_signature = "<T:Ljava/lang/Object;>(TT;)J";
      break;
    case 10:
      Select.reference.parameters = {"I"};
      break;
    case 11:
      Input[0].methods[1].instructions[1].opcode = "move-result-object";
      break;
    case 12:
    case 13: {
      auto Call = Input[0].methods[1];
      if (Mutation == 12)
        Input[0].methods.pop_back();
      Call.access = {"public", "static"};
      Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                       Input[0].name);
      Input.push_back(klass("Lfixture/Other;", {Call}));
      break;
    }
    case 14:
      Select.access = {"protected"};
      break;
    case 15:
      Select.instructions.clear();
      Select.registers = Select.code_end = 0;
      break;
    case 16:
      Select.generic_signature =
          "<T:Ljava/lang/Object;>(TT;)I^Ljava/lang/Exception;";
      break;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

