TEST(MobileDalvikJava,
     PrivateSeededPrimitivesRejectMissingSeedsUnprovedScopesAndForeignAccess) {
  for (unsigned Mutation = 0; Mutation != 14; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = privateSeededPrimitiveClasses("Z", false, false, 0, true);
    auto &Select = Input[0].methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      auto &Text = *Select.generic_signature;
      const auto At = Text.find(From);
      ASSERT_NE(At, std::string::npos);
      Text.replace(At, From.size(), To);
    };
    if (Mutation == 0)
      replace("T:Ljava/lang/Object;>", "T:Ljava/lang/Number;>");
    else if (Mutation == 1)
      replace(";TT;)Z", ";Ljava/lang/Object;)Z");
    else if (Mutation == 2)
      replace("Callback<-TT;>", "Callback<-TMissing;>");
    else if (Mutation == 3)
      replace("T:Ljava/lang/Object;>",
              "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
    else if (Mutation == 4)
      Select.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 5)
      Select.access.insert("native");
    else if (Mutation == 6)
      Input[0].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 7)
      Input[1].generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
    else if (Mutation == 8)
      Input[1].generic_signature.reset();
    else if (Mutation == 9)
      replace(")Z", ")I");
    else if (Mutation == 10)
      Input[1].access = {"private", "abstract", "interface"};
    else if (Mutation == 11)
      Select.reference.parameters[1] = "I";
    else if (Mutation == 12)
      Input[0].methods[1].instructions[1].opcode = "move-result-object";
    else {
      auto Call = Input[0].methods[1];
      Input[0].methods.pop_back();
      Call.access = {"public", "static"};
      Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                       Input[0].name);
      auto Foreign = klass("Lfixture/Other;", {Call});
      Foreign.methods[0].reference.owner = Foreign.name;
      Input.push_back(Foreign);
    }
    if (Mutation == 6) {
      // The declaring class is now generic. Its raw receiver erases the
      // complete method, while the consumer and scalar seed keep the same T.
      Budget B;
      const auto classes = linkClasses(Input, B);
      auto plans = validateGenericSignatures(classes, B);
      EXPECT_TRUE(plans.raw_receiver_invocations.contains(Select.reference));
      EXPECT_EQ(recoverJava(classes, B).getInteger("unrecovered_method_count"), 0);
    } else {
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
  }
}

std::vector<Class> closedAuxiliaryVoidClasses(bool SDK, bool Interface,
                                              bool Range, bool Alpha) {
  const std::string Formal = Alpha ? "Item" : "T";
  const std::string Auxiliary = "Lfixture/Callback<-Ljava/util/List<+Lfixture/"
                                "Carrier<*>;>;+Lfixture/Carrier<*>;>;";
  const std::string Signature = "<" + Formal +
                                ":Ljava/lang/Object;>(Lfixture/Token<T" +
                                Formal + ";>;" + Auxiliary + ")V";
  auto Consume = method("consume", {"Lfixture/Token;", "Lfixture/Callback;"},
                        "V", 3, {op(0, "return-void", {})});
  Consume.access = {"public"};
  Consume.generic_signature = Signature;
  auto Registry = klass("Lfixture/Registry;", {Consume});
  Registry.interfaces = {"Lfixture/Contract;"};
  auto Abstract = method("consume", Consume.reference.parameters, "V", 0, {});
  Abstract.access = {"public", "abstract"};
  Abstract.generic_signature = Signature;
  auto Contract = klass("Lfixture/Contract;", {Abstract});
  Contract.access = {"public", "abstract", "interface"};
  auto Token = klass("Lfixture/Token;");
  Token.access = {"public", "abstract", "interface"};
  Token.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.access = {"public", "abstract", "interface"};
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto List = klass("Ljava/util/List;");
  List.access = {"public", "abstract", "interface"};
  List.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  const auto Ref =
      Interface ? Contract.methods[0].reference : Registry.methods[0].reference;
  auto Call = method(
      "call", {Ref.owner, Token.name, Callback.name}, "V", 3,
      {op(0,
          Interface ? (Range ? "invoke-interface/range" : "invoke-interface")
                    : (Range ? "invoke-virtual/range" : "invoke-virtual"),
          {0, 1, 2}, {}, Ref),
       op(3, "return-void", {})});
  auto Core = klass("Lfixture/Core;", {Call});
  if (SDK) {
    Registry.external = Contract.external = Token.external = Callback.external =
        Carrier.external = List.external = true;
    Registry.methods[0].instructions.clear();
    Registry.methods[0].registers = Registry.methods[0].code_end = 0;
  }
  return {Core, Registry, Contract, Token, Callback, Carrier, List};
}

