std::vector<Class> nestedInvariantFactoryClasses(bool SDK, bool Facade,
                                                 bool Range, bool Alpha) {
  auto Input = nullaryCarrierFactoryClasses(SDK, Facade, Range);
  auto Inner = klass("Lfixture/Inner;");
  Inner.access = {"public", "abstract", "interface"};
  Inner.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Inner.external = SDK;
  const std::string Formal = Alpha ? "Item" : "T";
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[5].name};
  Make.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(Lfixture/Box<T" + Formal +
      ";>;)Lfixture/Box<Lfixture/Inner<T" + Formal + ";>;>;";
  if (!SDK)
    Make.registers = 2;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.registers = 2;
  Call.instructions[0].registers = {1};
  Call.instructions[0].reference = Ref;
  if (Facade) {
    Input[0].name = "Lother/Client;";
    Call.reference.owner = Input[0].name;
  }
  Input.push_back(Inner);
  return Input;
}

