std::vector<Class> instanceNestedFactoryClasses(bool SDK, bool Facade,
                                                bool Range, bool Alpha,
                                                unsigned Gap = 0,
                                                bool ClassResult = false) {
  auto Input = nestedInvariantFactoryClasses(SDK, Facade, Range, Alpha);
  Input[1].access = {"public"};
  auto &Make = Input[1].methods[0];
  Make.access = {"public"};
  if (!Facade)
    Make.access.insert("final");
  if (!SDK)
    Make.registers = 3;
  auto &Call = Input[0].methods[0];
  auto Ref = std::get<MethodRef>(Call.instructions[0].reference);
  Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                   Ref.owner);
  Call.registers = 3;
  Call.instructions[0].opcode =
      Range ? "invoke-virtual/range" : "invoke-virtual";
  Call.instructions[0].registers = {1, 2};
  if (ClassResult)
    Input.back().access = {"public"};
  for (auto &C : Input)
    for (auto &M : C.methods)
      if (!M.instructions.empty()) {
        M.registers += Gap;
        for (auto &O : M.instructions)
          for (auto &R : O.registers)
            R += Gap;
      }
  return Input;
}

