std::vector<Class> enclosingNestedFactoryClasses(bool SDK, bool Range,
                                                 bool Alpha, unsigned Gap = 0) {
  auto Input =
      instanceNestedFactoryClasses(false, false, Range, Alpha, Gap, true);
  auto Scope = Input[0];
  Scope.name = "Lfixture/Scope;";
  Scope.methods[0].reference.owner = Scope.name;
  auto Provider = Input[1];
  Provider.name = "Lfixture/Scope$Cell$Provider;";
  Provider.enclosing = "Lfixture/Scope$Cell;";
  Provider.inner_class_present = true;
  Provider.inner_name = "Provider";
  Provider.inner_access = {"public", "static"};
  auto &Make = Provider.methods[0];
  Make.reference.owner = Provider.name;
  auto &Signature = *Make.generic_signature;
  const auto At = Signature.find("Lfixture/Inner<");
  Signature.replace(At, std::string("Lfixture/Inner").size(),
                    "Lfixture/Scope$Cell");
  auto Cell = Input.back();
  Cell.name = "Lfixture/Scope$Cell;";
  Cell.access = {"final"};
  Cell.enclosing = Scope.name;
  Cell.inner_class_present = true;
  Cell.inner_name = "Cell";
  Cell.inner_access = {"private", "static", "final"};
  auto Carrier = Input[5];
  Carrier.external = SDK;
  auto &Call = Scope.methods[0];
  Call.reference.parameters[0] = Provider.name;
  Call.instructions[0].reference = Make.reference;
  return {Scope, Provider, Carrier, Cell};
}

