TEST(MobileDalvikJava,
     NullaryPairFactoriesRetainRawResultsAndRejectIncompleteContracts) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 23; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = nullaryPairFactoryClasses(External, true, true);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        replace("K:Ljava/lang/Object;", "K:Ljava/lang/Number;");
        break;
      case 1:
        replace("V:Ljava/lang/Object;", "V:Ljava/lang/Number;");
        break;
      case 2:
        replace("Box<TK;TV;>", "Box<+TK;TV;>");
        break;
      case 3:
        replace("Box<TK;TV;>", "Box<TK;-TV;>");
        break;
      case 4:
        replace("Box<TK;TV;>", "Box<Ljava/lang/Object;TV;>");
        break;
      case 5:
        replace("Box<TK;TV;>", "Box<TK;Ljava/lang/String;>");
        break;
      case 6:
        replace("Box<TK;TV;>", "Box<TK;TK;>");
        break;
      case 7:
        replace("Box<TK;TV;>", "Box<TV;TV;>");
        break;
      case 8:
        replace("V:Ljava/lang/Object;>",
                "V:Ljava/lang/Object;W:Ljava/lang/Object;>");
        break;
      case 9:
        replace("Box<TK;TV;>", "Box");
        break;
      case 10:
        Input[5].generic_signature =
            "<First:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 11:
        Input[5].generic_signature = "<First:Ljava/lang/Object;Second:Ljava/"
                                     "lang/Number;>Ljava/lang/Object;";
        break;
      case 12:
        Make.access.erase("static");
        if (!External)
          ++Make.registers;
        Call.reference.parameters = {Input[3].name};
        Call.registers = 2;
        Call.instructions[0].opcode = "invoke-virtual/range";
        Call.instructions[0].registers = {1};
        break;
      case 13:
        Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 14:
        Make.access = {"private", "static"};
        break;
      case 15:
        Make.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 16:
        Input.pop_back();
        break;
      case 17:
        replace("Box<TK;TV;>", "Box<[TK;TV;>");
        break;
      case 18:
        replace("Box<TK;TV;>", "Box<TK;[TV;>");
        break;
      case 19:
        replace("Box<TK;TV;>", "Box<TK;>");
        break;
      case 20:
        replace("V:Ljava/lang/Object;", "");
        replace("Box<TK;TV;>", "Box<TK;TK;>");
        break;
      case 21:
        replace("Lfixture/Box<TK;TV;>;", "TK;");
        Make.reference.returns = Call.reference.returns = "Ljava/lang/Object;";
        std::get<MethodRef>(Call.instructions[0].reference).returns =
            Make.reference.returns;
        break;
      case 22:
        replace("()", "(Ljava/lang/Object;)");
        Make.reference.parameters =
            Call.reference.parameters = {"Ljava/lang/Object;"};
        if (!External)
          ++Make.registers;
        std::get<MethodRef>(Call.instructions[0].reference).parameters =
            Make.reference.parameters;
        Call.registers = 2;
        Call.instructions[0].registers = {1};
        break;
      }
      Budget B;
      if (Mutation == 9) {
        // Both formals are unused when the original result is raw. Its
        // independent closed-slot proof preserves that exact declaration.
        const auto Signature = Make.generic_signature;
        const auto Classes = linkClasses(Input, B);
        EXPECT_TRUE(
            validateGenericSignatures(Classes, B)
                .erased_unused_formal_invocations.contains(Make.reference));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(Classes.at(Make.reference.owner).methods[0].generic_signature,
                  Signature);
      } else
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> pairedSeedFactoryClasses(bool Dependency, bool Facade,
                                            bool Range, bool SwapInputs = false,
                                            bool SwapResult = false) {
  auto Input = nullaryPairFactoryClasses(Dependency, Facade, Range, SwapResult);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {"Ljava/lang/Object;", "Ljava/lang/Object;"};
  auto &Signature = *Make.generic_signature;
  Signature.replace(Signature.find("()"), 2,
                    SwapInputs ? "(TV;TK;)" : "(TK;TV;)");
  if (!Dependency)
    Make.registers = 2;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, 3,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {1, 2}, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return Input;
}

