std::vector<Class> splitSeedFactoryClasses(bool External, bool Range) {
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Label = klass("Lfixture/Label;");
  auto Make =
      method("make",
             {Carrier.name, "Ljava/lang/Object;", "Ljava/lang/Object;",
              Label.name, "I"},
             Carrier.name, 5,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature =
      "<S:Ljava/lang/Object;T:Ljava/lang/Object;>(Lfixture/"
      "Carrier<TS;>;TT;TT;Lfixture/Label;I)Lfixture/Carrier<TT;>;";
  auto Provider = klass("Lfixture/Provider;", {Make});
  Provider.external = External;
  if (External)
    Provider.methods[0].instructions.clear();
  auto Call =
      method("call", Make.reference.parameters, Carrier.name, 5,
             {op(0, Range ? "invoke-static/range" : "invoke-static",
                 {0, 1, 2, 3, 4}, {}, Provider.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Client;", {Call}), Provider, Carrier, Label};
}

