TEST(MobileDalvikJava, DualSeedBoundedFactoriesRejectIncompleteContracts) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 17; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = dualSeedBoundedFactoryClasses(External, true);
      auto &Make = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Text = *Make.generic_signature;
        const auto At = Text.find(From);
        ASSERT_NE(At, std::string::npos);
        Text.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("(TT;", "(Ljava/lang/Object;");
      else if (Mutation == 1)
        replace("Link<TT;TV;>", "Link<+TT;TV;>");
      else if (Mutation == 2)
        replace("Link<TT;TV;>", "Link<TT;TT;>");
      else if (Mutation == 3)
        replace("Carrier<TT;>;TT;", "Carrier<+TT;>;TT;");
      else if (Mutation == 4)
        replace(")Lfixture/Carrier<TT;>;", ")Lfixture/Carrier<+TT;>;");
      else if (Mutation == 5)
        replace("Callback<-TT;Lfixture/Unit;>", "Callback<+TT;Lfixture/Unit;>");
      else if (Mutation == 6)
        replace("Callback<-TT;Lfixture/Unit;>", "Callback<-TV;Lfixture/Unit;>");
      else if (Mutation == 7)
        replace("Callback<-TT;Lfixture/Unit;>", "Callback<-TT;*>");
      else if (Mutation == 8)
        Input[6].generic_signature =
            "<A:Lfixture/Bound;R:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 9)
        Input[7].generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 10)
        Input[4].access.erase("public");
      else if (Mutation == 11)
        Input[5].generic_signature =
            "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 12)
        Make.access.insert("varargs");
      else if (Mutation == 13)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 14)
        Input[1].generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 15)
        replace("V:Lfixture/Bound;>", "V:Lfixture/Bound;W:Ljava/lang/Object;>");
      else
        Input[6].enclosing = "Lfixture/Missing;";
      Budget B;
      try {
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_FALSE(Plans.erased_generic_invocations.contains(Make.reference));
        EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
      } catch (const Error &) {
        // Malformed original bounds may fail before invocation planning.
      }
    }
}

