std::vector<Class> boundedConverterClasses(bool ExternalInputs, bool Private,
                                           bool Range) {
  auto Input = boundedPairConsumerClasses(false, Range);
  auto &Convert = Input[1].methods[0];
  Convert.reference.name = "convert";
  Convert.reference.parameters = {"Lfixture/Link;", "Ljava/lang/Object;"};
  Convert.reference.returns = "Lfixture/Bound;";
  Convert.generic_signature =
      "<T:Ljava/lang/Object;V:Lfixture/Bound;>(Lfixture/Link<TT;TV;>;TT;)TV;";
  Convert.access = {Private ? "private" : "public", "static"};
  Convert.instructions = {op(0, "const/4", {0}, int64_t{0}),
                          op(1, "return-object", {0})};
  auto Call = method(
      "access", Convert.reference.parameters, Convert.reference.returns, 2,
      {op(0, Range ? "invoke-static/range" : "invoke-static", {0, 1}, {},
          Convert.reference),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.reference.owner = Convert.reference.owner;
  Input[1].methods.push_back(Call);
  Input.erase(Input.begin());
  for (size_t i = 1; i < Input.size(); ++i)
    Input[i].external = ExternalInputs;
  return Input;
}

