TEST(MobileDalvikJava,
     UnusedNominalFormalsRetainClosedVoidBooleanAndFactories) {
  // These complete runtime slots no longer use the method formal. Its known
  // nominal bound has an independent receipt; an absent bound still fails.
  for (unsigned Shape = 0; Shape < 3; ++Shape)
    for (bool External : {false, true})
      for (bool Private : {false, true})
        for (bool Range : {false, true})
          for (bool Linked : {false, true})
            for (bool Reverse : {false, true}) {
              auto Input = Shape == 0 ? erasedCallbackInvocationClasses(
                                            Private, true, true, External)
                           : Shape == 1 ? erasedBooleanInvocationClasses(
                                              Private, true, External, Range)
                                        : boundedSeedScalarFactoryClasses(
                                              External, Private, Range);
              auto &Provider = Input[Shape == 2 ? 0 : 1];
              auto &Target = Provider.methods[0];
              auto &Call = Provider.methods[1];
              if (Shape == 0) {
                Target.generic_signature =
                    "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)V";
                Target.reference.parameters[0] = "Ljava/lang/Object;";
                Call.reference.parameters[0] = "Ljava/lang/Object;";
                if (Range)
                  Call.instructions[0].opcode += "/range";
              } else if (Shape == 1)
                Target.generic_signature = "<T:Lfixture/Value;>(Lfixture/"
                                           "Creator<Lfixture/Value;>;IJD)Z";
              else
                Target.generic_signature =
                    "<V:Lfixture/Bound;>(Lfixture/Bound;FF)Lfixture/Result;";
              Call.instructions[0].reference = Target.reference;
              const auto Ref = Target.reference;
              const auto Signature = Target.generic_signature;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              ClassMap Classes;
              Budget B;
              if (Linked)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.erased_generic_invocations.contains(Ref));
              ASSERT_TRUE(Plans.erased_unused_formal_invocations.contains(Ref));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                        Signature);
            }
}

std::vector<Class> boundedPairCallbackClasses(bool External, bool Range) {
  auto Input = boundedPairConsumerClasses(External, Range);
  auto Scope = Input.back();
  Scope.name = "Lfixture/Scope;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.external = true;
  Callback.generic_signature =
      "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Sink = klass("Lfixture/Sink;");
  Sink.external = true;
  Sink.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Unit = klass("Lfixture/Unit;");
  Unit.external = true;
  auto &Consume = Input[1].methods[0];
  Consume.reference.parameters = {"Lfixture/Link;", "Lfixture/State;", "J",
                                  Callback.name, Sink.name};
  Consume.reference.returns = "Ljava/lang/Object;";
  Consume.generic_signature =
      "<T:Ljava/lang/Object;V:Lfixture/Bound;>(Lfixture/Link<TT;TV;>;"
      "Lfixture/State<TT;TV;>;JLfixture/Callback<-Lfixture/Scope<TT;TV;>;"
      "Lfixture/Unit;>;Lfixture/Sink<-Lfixture/Unit;>;)Ljava/lang/Object;";
  Consume.registers = 6;
  if (!External)
    Consume.instructions = {op(0, "const/4", {0}, int64_t{0}),
                            op(1, "return-object", {0})};
  Input[0] = klass(
      "Lfixture/Client;",
      {method("call", Consume.reference.parameters, "Ljava/lang/Object;", 6,
              {op(0, Range ? "invoke-static/range" : "invoke-static",
                  {0, 1, 2, 3, 4, 5}, {}, Consume.reference),
               op(1, "move-result-object", {0}),
               op(2, "return-object", {0})})});
  Input.push_back(Scope);
  Input.push_back(Callback);
  Input.push_back(Sink);
  Input.push_back(Unit);
  return Input;
}

