TEST(MobileDalvikJava, BoundedPairCallbacksRejectIncompleteConsumerTrees) {
  for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = boundedPairCallbackClasses(false, false);
    auto &Consume = Input[1].methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      auto &s = *Consume.generic_signature;
      const auto at = s.find(From);
      ASSERT_NE(at, std::string::npos);
      s.replace(at, From.size(), To);
    };
    if (Mutation == 0)
      replace("Scope<TT;TV;>", "Scope<TT;+TV;>");
    else if (Mutation == 1)
      replace("Callback<-Lfixture/Scope", "Callback<+Lfixture/Scope");
    else if (Mutation == 2)
      replace("Sink<-Lfixture/Unit;>", "Sink<-Ljava/lang/Object;>");
    else if (Mutation == 3)
      replace("Lfixture/Unit;>;Lfixture/Sink", "TV;>;Lfixture/Sink");
    else if (Mutation == 4)
      Input[Input.size() - 3].generic_signature =
          "<E:Ljava/lang/Object;F:Lfixture/Bound;>Ljava/lang/Object;";
    else if (Mutation == 5)
      Input[Input.size() - 4].generic_signature =
          "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 6)
      Input.back().generic_signature =
          "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 7)
      Consume.access.insert("varargs");
    else if (Mutation == 8)
      Consume.declared_throws = {"Ljava/lang/Exception;"};
    else
      Input.erase(Input.end() - 4);
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

