std::vector<Class> boundedFrameConsumerClasses(bool External, bool Range,
                                               bool Private) {
  auto Input = boundedPairCallbackClasses(External, Range);
  auto &Consume = Input[1].methods[0];
  Consume.reference.parameters = {"Lfixture/Link;", "Lfixture/Callback;",
                                  "Lfixture/Sink;"};
  Consume.generic_signature =
      "<R:Ljava/lang/Object;T:Ljava/lang/Object;V:Lfixture/Bound;>"
      "(Lfixture/Link<TT;TV;>;Lfixture/Callback<-Ljava/lang/Long;+TR;>;"
      "Lfixture/Sink<-TR;>;)Ljava/lang/Object;";
  if (Private) {
    Input[1].external = false;
    Consume.access = {"private", "static"};
    Consume.registers = 4;
    Consume.instructions = {op(0, "const/4", {0}, int64_t{0}),
                            op(1, "return-object", {0})};
    Consume.code_end = 2;
  }
  auto Call =
      method("call", Consume.reference.parameters, "Ljava/lang/Object;", 4,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2, 3},
                 {}, Consume.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.access = {"public", "static"};
  if (Private) {
    Call.reference.owner = Input[1].name;
    Input[1].methods.push_back(Call);
    Input[0].methods.clear();
  } else
    Input[0] = klass("Lfixture/Client;", {Call});
  auto Long = klass("Ljava/lang/Long;");
  Long.external = true;
  Input.push_back(Long);
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  Input.push_back(Object);
  return Input;
}

