std::vector<Class> allocatingUnaryOwnerClasses(bool Dependency, bool Range) {
  auto Input = nullableOwnerConstructorClasses(Dependency, true, Range);
  auto &Mutable = Input[2];
  auto Init = Mutable.methods[0];
  Init.reference.parameters = {"Ljava/lang/Object;"};
  Init.generic_signature = "(TT;)V";
  Init.registers = 2;
  Mutable.methods = {Init};
  auto &Caller = Input[0].methods[1];
  Caller.reference.parameters[0] = "Ljava/lang/Object;";
  Caller.generic_signature = "(TS;Ljava/lang/String;)V";
  Caller.registers = 5;
  Caller.instructions = {op(0, "new-instance", {0}, {}, Mutable.name),
                         op(1, Range ? "invoke-direct/range" : "invoke-direct",
                            {0, 3}, {}, Mutable.methods[0].reference),
                         op(2, "check-cast", {0}, {}, Input[1].name),
                         op(3, "const/4", {1}, int64_t{0}),
                         op(4, Range ? "invoke-direct/range" : "invoke-direct",
                            {2, 0, 1, 4}, {}, Input[0].methods[0].reference),
                         op(5, "return-void")};
  Caller.code_end = 6;
  return Input;
}

