std::vector<Class> arrayConsumerCarrierClasses(bool External, bool Facade,
                                               bool Range, bool Swapped,
                                               bool Lower) {
  auto Input = arraySeedFactoryClasses(External, Facade, Range);
  auto &Make = Input[1].methods[0];
  const auto Consumer = Input[4].name;
  Make.reference.parameters =
      Swapped ? std::vector<std::string>{Consumer, "[Ljava/lang/Object;", "J"}
              : std::vector<std::string>{"[Ljava/lang/Object;", Consumer, "J"};
  const std::string Callback =
      "Lfixture/Factory<" + std::string(Lower ? "-" : "") + "TT;>;";
  Make.generic_signature = std::string("<T:Ljava/lang/Object;>(") +
                           (Swapped ? Callback + "[TT;" : "[TT;" + Callback) +
                           "J)Lfixture/Box<TT;>;";
  if (!External)
    Make.registers = 4;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, 5,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {1, 2, 3, 4}, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return Input;
}

TEST(MobileDalvikJava, ArrayConsumerCarriersKeepOneScopedComponentAndResult) {
  for (bool External : {false, true})
    for (bool Facade : {false, true})
      for (bool Range : {false, true})
        for (bool Swapped : {false, true})
          for (bool Lower : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{External, Facade, Range, Swapped, Lower, Route}));
              auto Input = arrayConsumerCarrierClasses(External, Facade, Range,
                                                       Swapped, Lower);
              const auto Ref = Input[1].methods[0].reference;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              EXPECT_NO_THROW({
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              });
            }
}

TEST(MobileDalvikJava, ArrayConsumerCarriersRejectLostScopesAndOpenSlots) {
  for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = arrayConsumerCarrierClasses(false, true, true, false, true);
      auto &Make = Input[1].methods[0];
      const auto replace = [&](const std::string &From, const std::string &To) {
        const auto At = Make.generic_signature->find(From);
        ASSERT_NE(At, std::string::npos);
        Make.generic_signature->replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("Factory<-TT;>", "Factory<+TT;>");
      else if (Mutation == 1)
        replace("Factory<-TT;>", "Factory<*>");
      else if (Mutation == 2)
        replace("Factory<-TT;>", "Factory<-TU;>");
      else if (Mutation == 3)
        replace("[TT;", "[Ljava/lang/Object;");
      else if (Mutation == 4)
        replace("[TT;", "[[TT;");
      else if (Mutation == 5)
        replace("Box<TT;>", "Box<+TT;>");
      else if (Mutation == 6)
        replace("Box<TT;>", "Box<*>");
      else if (Mutation == 7)
        replace("Box<TT;>", "Box<TU;>");
      else if (Mutation == 8)
        replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
      else if (Mutation == 9)
        replace("T:Ljava/lang/Object;",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;");
      else if (Mutation == 10)
        Input[4].generic_signature = "<F:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 11)
        Input[5].generic_signature = "<B:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 12)
        Make.access.insert("varargs");
      else if (Mutation == 13)
        Make.access.insert("synthetic");
      else if (Mutation == 14)
        Make.access.insert("native");
      else if (Mutation == 15)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 16)
        Input[4].access.erase("public");
      else if (Mutation == 17)
        Input[5].access.erase("public");
      else if (Mutation == 18)
        Input[0].methods[0].instructions[0].opcode = "invoke-virtual/range";
      else if (Mutation == 19)
        replace(";J)", ";I)");
      else if (Mutation == 20)
        Input[1].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
      else
        Input[0].methods[0].instructions[0].registers = {1, 2, 4, 3};
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      if (Route)
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

