std::vector<Class> arrayConsumerVoidClasses(bool ExternalTarget,
                                            bool ExternalCarrier, bool Facade,
                                            bool Range, bool ArrayFirst,
                                            bool Renamed, bool Standard,
                                            bool Lower) {
  auto Input = genericArrayVoidClasses(ExternalTarget, Facade, Range, true);
  const std::string Carrier =
      Standard ? "Ljava/util/Comparator;" : "Lfixture/Consumer;";
  const std::string Formal = Renamed ? "R" : "T";
  const std::string Array = "[T" + Formal + ";";
  const std::string Consumer = Carrier.substr(0, Carrier.size() - 1) + "<" +
                               (Lower ? "-" : "") + "T" + Formal + ";>;";
  auto &Apply = Input[1].methods[0];
  Apply.reference.name = "apply";
  Apply.reference.parameters =
      ArrayFirst
          ? std::vector<std::string>{"[Ljava/lang/Object;", Carrier, "I", "I"}
          : std::vector<std::string>{Carrier, "I", "[Ljava/lang/Object;", "I"};
  Apply.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(" +
      (ArrayFirst ? Array + Consumer + "II" : Consumer + "I" + Array + "I") +
      ")V";
  auto Compare = method("compare", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                        "I", 0, {});
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TE;TE;)I";
  auto Declaration = klass(Carrier, {Compare});
  Declaration.access = {"public", "abstract", "interface"};
  Declaration.external = ExternalCarrier;
  Declaration.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(std::move(Declaration));
  auto Ref = Apply.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, "V", 4,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {0, 1, 2, 3}, {}, Ref),
                     op(1, "return-void")})});
  return Input;
}

TEST(MobileDalvikJava, ArrayConsumerVoidsRetainCompleteScopedComponent) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarrier : {false, true})
      for (bool Facade : {false, true})
        for (bool Range : {false, true})
          for (bool ArrayFirst : {false, true})
            for (bool Renamed : {false, true})
              for (bool Standard : {false, true})
                for (bool Lower : {false, true})
                  for (unsigned Route = 0; Route < 3; ++Route) {
                    auto Input = arrayConsumerVoidClasses(
                        ExternalTarget, ExternalCarrier, Facade, Range,
                        ArrayFirst, Renamed, Standard, Lower);
                    const auto Ref = Input[1].methods[0].reference;
                    const auto Signature =
                        Input[1].methods[0].generic_signature;
                    if (Route == 2)
                      std::reverse(Input.begin(), Input.end());
                    Budget B;
                    ClassMap Classes;
                    if (Route)
                      Classes = linkClasses(Input, B);
                    else
                      for (const auto &C : Input)
                        Classes.emplace(C.name, C);
                    EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                    .erased_generic_invocations.contains(Ref));
                    const auto R = recoverJava(Classes, B);
                    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                    EXPECT_FALSE(R.getArray("generic_signature_projections"));
                    EXPECT_EQ(
                        Classes.at(Ref.owner).methods[0].generic_signature,
                        Signature);
                  }
}

TEST(MobileDalvikJava, ArrayConsumerVoidsRejectUnprovedRelationsAndCalls) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarrier : {false, true})
      for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
          auto Input =
              arrayConsumerVoidClasses(ExternalTarget, ExternalCarrier, false,
                                       true, true, false, false, true);
          auto &Apply = Input[1].methods[0];
          auto replace = [&](const std::string &From, const std::string &To) {
            auto &Signature = *Apply.generic_signature;
            const auto At = Signature.find(From);
            ASSERT_NE(At, std::string::npos);
            Signature.replace(At, From.size(), To);
          };
          switch (Mutation) {
          case 0:
            replace("<T:Ljava/lang/Object;>", "<T:Ljava/lang/String;>");
            break;
          case 1:
            replace(">(", "U:Ljava/lang/Object;>(");
            break;
          case 2:
            replace("<-TT;>", "<+TT;>");
            break;
          case 3:
            replace("<-TT;>", "<*>");
            break;
          case 4:
            replace("[TT;", "[Ljava/lang/Object;");
            break;
          case 5:
            replace("[TT;", "[[TT;");
            break;
          case 6:
            replace("<-TT;>", "<-TU;>");
            break;
          case 7:
            Input.back().generic_signature =
                "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 8:
            Input.back().generic_signature =
                "<E:Ljava/lang/Number;>Ljava/lang/Object;";
            break;
          case 9:
            Input.pop_back();
            break;
          case 10:
            Apply.access.insert("native");
            break;
          case 11:
            Apply.access.insert("varargs");
            break;
          case 12:
            Apply.access.insert("synthetic");
            break;
          case 13:
            Apply.declared_throws = {"Ljava/lang/Exception;"};
            break;
          case 14:
            Apply.access.erase("static");
            break;
          case 15:
            Apply.access = {"private", "static"};
            break;
          case 16:
            Input[0].methods[0].instructions[0].registers.pop_back();
            break;
          case 17:
            Input[0].methods[0].instructions[0].opcode = "invoke-virtual";
            break;
          case 18:
            replace("Consumer<-TT;>", "Consumer");
            break;
          case 19:
            replace("<-TT;>", "<-Lfixture/Box<TT;>;>");
            break;
          case 20:
            replace(";II)V", ";JI)V");
            break;
          case 21:
            replace(")V", ")I");
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(
              [&] {
                if (Route)
                  recoverJava(linkClasses(Input, B), B);
                else {
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  recoverJava(Classes, B);
                }
              }(),
              std::runtime_error);
        }
}

std::vector<Class> arrayConsumerPredicateClasses(
    bool ExternalTarget, bool ExternalCarrier, bool Facade, bool Range,
    bool ArrayFirst, bool Renamed, bool Standard, bool Lower, bool Value) {
  auto Input =
      arrayConsumerVoidClasses(ExternalTarget, ExternalCarrier, Facade, Range,
                               ArrayFirst, Renamed, Standard, Lower);
  auto &Apply = Input[1].methods[0];
  if (Standard) {
    const std::string Comparator = "Ljava/util/Comparator;";
    const std::string Collection = "Ljava/util/Collection;";
    for (auto &Parameter : Apply.reference.parameters)
      if (Parameter == Comparator)
        Parameter = Collection;
    auto &Signature = *Apply.generic_signature;
    const auto At = Signature.find("Ljava/util/Comparator");
    Signature.replace(At, std::string("Ljava/util/Comparator").size(),
                      "Ljava/util/Collection");
    Input.back().name = Collection;
    Input.back().methods.clear();
  }
  Apply.reference.returns = "Z";
  Apply.generic_signature->back() = 'Z';
  if (!ExternalTarget) {
    Apply.instructions = {op(0, "const/4", {0}, int64_t(Value)),
                          op(1, "return", {0})};
    Apply.code_end = 2;
  }
  auto Ref = Apply.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.reference.returns = "Z";
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          {0, 1, 2, 3}, {}, Ref),
                       op(1, "move-result", {0}), op(2, "return", {0})};
  Call.code_end = 3;
  return Input;
}

