std::vector<Class> inheritedCarrierArrayResultClasses(bool External) {
  auto Input = carrierArrayResultClasses(External, 2, true, false, true);
  auto Facade = klass("Lfixture/Facade;");
  Facade.access = {"public", "abstract", "interface"};
  Facade.external = External;
  Facade.interfaces = {Input[1].name};
  auto Read = Input[1].methods[0];
  Read.access = {"public"};
  Read.registers = 5;
  Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                       op(1, "return-object", {0})};
  Read.code_end = 2;
  auto Implementation = klass("Lfixture/Implementation;", {Read});
  Implementation.interfaces = {Facade.name};
  auto &Call = Input[0].methods[0];
  Call.reference.parameters[0] = Facade.name;
  std::get<MethodRef>(Call.instructions[0].reference).owner = Facade.name;
  Input.push_back(Facade);
  Input.push_back(Implementation);
  return Input;
}

