std::vector<Class> genericArrayElementTransferClasses(bool External,
                                                      bool Facade, bool Range,
                                                      unsigned Shape) {
  auto Input = genericArrayTransferClasses(External, Facade, Range);
  static const std::vector<std::vector<std::string>> Shapes{
      {"[TT;", "TT;"},
      {"TT;", "[TT;", "I"},
      {"[TT;", "TT;", "[TT;", "I", "I"},
      {"[TT;", "I", "TT;", "I", "[TT;"},
      {"TT;", "TT;", "[TT;", "I"},
      {"[TT;", "TT;", "[TT;", "[TT;"}};
  const auto &Slots = Shapes.at(Shape);
  auto &Move = Input[1].methods[0];
  Move.reference.parameters.clear();
  Move.generic_signature = "<T:Ljava/lang/Object;>(";
  unsigned FirstArray = Slots.size();
  for (unsigned I = 0; I < Slots.size(); ++I) {
    const auto &Slot = Slots[I];
    *Move.generic_signature += Slot;
    const bool Array = Slot.starts_with('[');
    Move.reference.parameters.push_back(Array           ? "[Ljava/lang/Object;"
                                        : Slot == "TT;" ? "Ljava/lang/Object;"
                                                        : Slot);
    if (Array && FirstArray == Slots.size())
      FirstArray = I;
  }
  *Move.generic_signature += ")[TT;";
  if (!External) {
    Move.registers = Slots.size();
    Move.instructions = {op(0, "return-object", {FirstArray})};
    Move.code_end = 1;
  }
  auto Ref = Move.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  std::vector<unsigned> Arguments;
  for (unsigned I = 0; I < Slots.size(); ++I)
    Arguments.push_back(I + 1);
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, Slots.size() + 1,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        Arguments, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return Input;
}

TEST(MobileDalvikJava, GenericArrayElementTransfersKeepOneScopedComponent) {
  for (bool External : {false, true})
    for (bool Facade : {false, true})
      for (bool Range : {false, true})
        for (unsigned Shape = 0; Shape < 6; ++Shape)
          for (bool Varargs : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              auto Input = genericArrayElementTransferClasses(External, Facade,
                                                              Range, Shape);
              auto &Move = Input[1].methods[0];
              if (Varargs) {
                if (!Move.reference.parameters.back().starts_with('['))
                  continue;
                Move.access.insert("varargs");
              }
              SCOPED_TRACE(External);
              SCOPED_TRACE(Facade);
              SCOPED_TRACE(Range);
              SCOPED_TRACE(Shape);
              SCOPED_TRACE(Varargs);
              SCOPED_TRACE(Route);
              const auto Ref = Move.reference;
              const auto Signature = Move.generic_signature;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              EXPECT_TRUE(validateGenericSignatures(Classes, B)
                              .erased_generic_invocations.contains(Ref));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
              EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                        Signature);
            }
  for (bool PublicClass : {false, true})
    for (bool Range : {false, true})
      for (unsigned Shape = 0; Shape < 6; ++Shape)
        for (unsigned Route = 0; Route < 3; ++Route) {
          auto Input =
              genericArrayElementTransferClasses(false, false, Range, Shape);
          Input[1].methods[0].access.erase("public");
          if (!PublicClass)
            Input[1].access.erase("public");
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        }
}

TEST(MobileDalvikJava, GenericArrayElementTransfersRejectUnprovenRelations) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(Mutation);
      SCOPED_TRACE(Route);
      auto Input = genericArrayElementTransferClasses(false, true, true, 0);
      auto &Move = Input[1].methods[0];
      if (Mutation == 0)
        Move.generic_signature = "<T:Ljava/lang/CharSequence;>([TT;TT;)[TT;";
      else if (Mutation == 1)
        Move.generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>([TT;TU;)[TT;";
      else if (Mutation == 2)
        Move.generic_signature = "<T:Ljava/lang/Object;>([TT;TU;)[TT;";
      else if (Mutation == 3)
        Move.generic_signature = "<T:Ljava/lang/Object;>([TT;TT;)[TU;";
      else if (Mutation == 4)
        Move.generic_signature = "<T:Ljava/lang/Object;>([TT;TT;)[[TT;";
      else if (Mutation == 5)
        Move.generic_signature =
            "<T:Ljava/lang/Object;>([Ljava/lang/Object;TT;)[TT;";
      else if (Mutation == 6)
        Move.generic_signature = "<T:Ljava/lang/Object;>([[TT;TT;)[TT;";
      else if (Mutation == 7)
        Move.generic_signature = "<T:Ljava/lang/Object;>([TT;[TT;)[TT;";
      else if (Mutation == 8)
        Move.access.erase("static");
      else if (Mutation == 9)
        Move.access = {"private", "static"};
      else if (Mutation == 10)
        Move.declared_throws = {"Ljava/lang/Exception;"};
      else {
        Move.access.erase("public");
        auto &Call = Input[0].methods[0];
        std::get<MethodRef>(Call.instructions[0].reference).owner =
            Move.reference.owner;
        Input[0].name = "Lother/Client;";
        Call.reference.owner = Input[0].name;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      EXPECT_THROW(
          {
            if (Route)
              recoverJava(linkClasses(Input, B), B);
            else
              recover(Input);
          },
          std::runtime_error);
    }
}

