          auto Input = flatPairTransferClasses(External, Facade, Range);
          auto &Signature = *Input[1].methods[0].generic_signature;
          unsigned Slot = 0;
          for (size_t i = 0; i < Signature.size(); ++i)
            if (Signature[i] == '+') {
              if (Variances & (1u << Slot))
                Signature.erase(i--, 1);
              ++Slot;
            }
          Budget B;
