TEST(MobileDalvikJava, FlatPairTransfersRejectChangedOrderOrIncompleteTypes) {
  for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = flatPairTransferClasses(false, false, false);
    auto &Make = Input[1].methods[0];
    auto &Signature = *Make.generic_signature;
    auto replace = [&](const std::string &from, const std::string &to) {
      const auto at = Signature.find(from);
      ASSERT_NE(at, std::string::npos);
      Signature.replace(at, from.size(), to);
    };
    if (Mutation == 0)
      replace("Input<+TK;+TV;>", "Input<+TK;+TK;>");
    else if (Mutation == 1)
      replace("Input<+TK;+TV;>", "Input<+TV;+TK;>");
    else if (Mutation == 2)
      replace("Input<+TK;+TV;>", "Input<-TK;+TV;>");
    else if (Mutation == 3)
      replace("Box<TK;TV;>", "Box<TK;TK;>");
    else if (Mutation == 4)
      Make.access.insert("varargs");
    else if (Mutation == 5)
      Input.back().access.erase("public");
    else if (Mutation == 6)
      Input.back().generic_signature =
          "<A:Ljava/lang/Object;B:Ljava/lang/CharSequence;>Ljava/lang/Object;";
    else if (Mutation == 7)
      Make.declared_throws = {"Ljava/lang/Exception;"};
    else
      Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

