TEST(MobileDalvikJava, NestedPairConsumersKeepCompleteCovariantInputScopes) {
  for (bool External : {false, true})
    for (bool Facade : {false, true})
      for (bool Range : {false, true})
        for (unsigned Variances = 0; Variances < 8; ++Variances)
          for (bool SwapResult : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              auto Input = nestedPairConsumerClasses(External, Facade, Range);
              auto &Make = Input[1].methods[0];
              auto &Signature = *Make.generic_signature;
              unsigned Slot = 0;
              for (size_t I = 0; I < Signature.size(); ++I)
                if (Signature[I] == '+') {
                  if (!(Variances & (1U << Slot)))
                    Signature.erase(I--, 1);
                  ++Slot;
                }
              if (SwapResult)
                Signature.replace(Signature.find("Box<TK;TV;>"), 11,
                                  "Box<TV;TK;>");
              if (Range)
                Make.access.insert("final");
              const auto Ref = Make.reference;
              const auto Original = Make.generic_signature;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              ClassMap Classes;
              Budget B;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              EXPECT_TRUE(validateGenericSignatures(Classes, B)
                              .erased_generic_invocations.contains(Ref));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
              EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                        Original);
              std::string Text;
              for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                Text += source(R, I);
              EXPECT_NE(Text.find(".make("), std::string::npos);
            }
}

TEST(MobileDalvikJava, NestedPairConsumersRejectUnprovedLayerContracts) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 24; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = nestedPairConsumerClasses(External, true, true);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        replace("Input<+", "Input<-");
        break;
      case 1:
        replace("Box<+TK;+TV;>", "Box<-TK;+TV;>");
        break;
      case 2:
        replace("Box<+TK;+TV;>", "Box<+TK;-TV;>");
        break;
      case 3:
        replace("Box<+TK;+TV;>", "Box<+TK;+TK;>");
        break;
      case 4:
        replace("Box<+TK;+TV;>", "Box<Ljava/lang/Object;+TV;>");
        break;
      case 5:
        replace("Box<TK;TV;>", "Box<+TK;TV;>");
        break;
      case 6:
        replace("Box<TK;TV;>", "Box<TK;-TV;>");
        break;
      case 7:
        replace("Box<TK;TV;>", "Box<TK;TK;>");
        break;
      case 8:
        replace("Box<TK;TV;>", "Box<TK;Ljava/lang/Object;>");
        break;
      case 9:
        replace("Input<+Lfixture/Box", "Input<+[Lfixture/Box");
        break;
      case 10:
        replace("Box<+TK;+TV;>", "Box<+TK;>");
        break;
      case 11:
        Input[5].generic_signature = "<First:Ljava/lang/Object;Second:Ljava/"
                                     "lang/Number;>Ljava/lang/Object;";
        break;
      case 12:
        Input[6].generic_signature = "<P:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 13:
        Input[5].access.erase("public");
        break;
      case 14:
        Input[6].access.erase("public");
        break;
      case 15:
        Input.pop_back();
        break;
      case 16:
        Input.erase(Input.begin() + 5);
        break;
      case 17: {
        replace("K:Ljava/lang/Object;",
                "K:Ljava/lang/Object;:Ljava/io/Serializable;");
        auto Marker = klass("Ljava/io/Serializable;");
        Marker.access = {"public", "interface", "abstract"};
        Marker.external = true;
        Input.push_back(Marker);
        break;
      }
      case 18:
        replace("V:Ljava/lang/Object;>",
                "V:Ljava/lang/Object;W:Ljava/lang/Object;>");
        break;
      case 19:
        Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 20:
        Make.access = {"private", "static"};
        break;
      case 21:
        Make.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 22:
        Make.access.erase("static");
        if (!External)
          ++Make.registers;
        Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                         Input[3].name);
        Call.registers = 3;
        Call.instructions[0].opcode = "invoke-virtual/range";
        Call.instructions[0].registers = {1, 2};
        break;
      case 23:
        replace("Lfixture/Input<+Lfixture/Box<+TK;+TV;>;>;", "TK;");
        Make.reference.parameters[0] = Call.reference.parameters[0] =
            "Ljava/lang/Object;";
        std::get<MethodRef>(Call.instructions[0].reference).parameters[0] =
            "Ljava/lang/Object;";
        break;
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

