TEST(MobileDalvikJava, EnumArrayFactoriesRejectWeakenedBoundsAndSlots) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 22; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = enumArrayFactoryClasses(External, true, true);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        replace("([TE;)", "([Ljava/lang/Enum;)");
        break;
      case 1:
        replace("Enum<TE;>", "Enum");
        break;
      case 2:
        replace("Enum<TE;>", "Enum<+TE;>");
        break;
      case 3:
        replace("Enum<TE;>", "Enum<*>");
        break;
      case 4:
        replace("Box<TE;>", "Box<+TE;>");
        break;
      case 5:
        replace("Box<TE;>", "Box<*>");
        break;
      case 6:
        Input[5].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 7:
        Input[5].generic_signature = "<P:Ljava/lang/Enum;>Ljava/lang/Object;";
        break;
      case 8:
        Input[6].generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 9:
        Input[6].access.erase("abstract");
        break;
      case 10:
        Input[6].access.insert("interface");
        break;
      case 11:
        Input[6].access.erase("public");
        break;
      case 12:
        Input[5].access.erase("public");
        break;
      case 13:
        Input.pop_back();
        break;
      case 14: {
        replace("Enum<TE;>;>", "Enum<TE;>;:Ljava/io/Serializable;>");
        auto Marker = klass("Ljava/io/Serializable;");
        Marker.access = {"public", "interface", "abstract"};
        Marker.external = true;
        Input.push_back(Marker);
        break;
      }
      case 15:
        replace("Enum<TE;>;>", "Enum<TE;>;U:Ljava/lang/Object;>");
        break;
      case 16:
        Input[1].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 17:
        Make.access = {"private", "static"};
        break;
      case 18:
        Make.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 19:
        Make.access.erase("static");
        if (!External)
          ++Make.registers;
        Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                         Input[3].name);
        Call.registers = 3;
        Call.instructions[0].opcode = "invoke-virtual/range";
        Call.instructions[0].registers = {1, 2};
        break;
      case 20:
        replace("([TE;)", "([[TE;)");
        Make.reference.parameters[0] = Call.reference.parameters[0] =
            "[[Ljava/lang/Enum;";
        std::get<MethodRef>(Call.instructions[0].reference).parameters[0] =
            Make.reference.parameters[0];
        break;
      case 21:
        replace("Box<TE;>", "Box<[TE;>");
        break;
      }
      Budget B;
      if (Mutation == 16) {
        // An unused owner formal does not bind an independently scoped static
        // method. Its complete Enum<Self> method/result proof stays intact.
        auto Classes = linkClasses(Input, B);
        EXPECT_TRUE(validateGenericSignatures(Classes, B)
                        .erased_generic_invocations.contains(Make.reference));
        const auto Report = recoverJava(Classes, B);
        EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(Report.getArray("generic_signature_projections"));
      } else {
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      }
    }
}

