std::vector<Class> carrierElementInvocationClasses(bool Dependency, bool Facade,
                                                   bool Invariant, bool Range,
                                                   bool Cast) {
  auto Input = erasedFactoryInvocationClasses(Dependency, Facade, Invariant);
  auto &Make = Input[1].methods[0];
  Make.reference.returns = "Ljava/lang/Object;";
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Factory<") +
      (Invariant ? "" : "+") + "TT;>;J)TT;";
  auto &Call = Input[0].methods[0];
  Call.reference.returns = Cast ? "Ljava/lang/String;" : "Ljava/lang/Object;";
  auto &Invoke = Call.instructions[0];
  std::get<MethodRef>(Invoke.reference).returns = Make.reference.returns;
  if (Range)
    Invoke.opcode = "invoke-static/range";
  if (Cast) {
    Call.instructions.back().pc = 3;
    Call.instructions.insert(
        Call.instructions.end() - 1,
        op(2, "check-cast", {0}, {}, std::string("Ljava/lang/String;")));
    Call.code_end = 4;
  }
  if (Dependency)
    Input[4].external = true;
  return Input;
}

