std::vector<Class> nestedCarrierInvocationClasses(bool Dependency, bool Facade,
                                                  bool Range) {
  auto Input = erasedFactoryInvocationClasses(Dependency, Facade, false);
  Input[4].generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;R:Ljava/lang/Object;>"
      "Ljava/lang/Object;";
  auto Port = klass("Lfixture/Port;");
  Port.access = {"public", "abstract", "interface"};
  Port.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Sink = klass("Lfixture/Sink;");
  Sink.access = Port.access;
  Sink.generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[1].methods[0].generic_signature =
      "<T:Ljava/lang/Object;>(Lfixture/Factory<-Lfixture/Port<-TT;>;"
      "-Lfixture/Sink<-Lfixture/Token;>;+Ljava/lang/Object;>;J)Lfixture/"
      "Box<TT;>;";
  if (Range)
    Input[0].methods[0].instructions[0].opcode = "invoke-static/range";
  Input.push_back(Port);
  Input.push_back(Sink);
  Input.push_back(klass("Lfixture/Token;"));
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  Input.push_back(Object);
  if (Dependency)
    for (size_t I = 4; I < Input.size(); ++I)
      Input[I].external = true;
  return Input;
}

TEST(MobileDalvikJava, NestedCarrierCallsRetainCompleteOriginalTypeArguments) {
  for (bool External : {false, true})
    for (bool Facade : {false, true})
      for (bool Range : {false, true})
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(External);
          SCOPED_TRACE(Facade);
          SCOPED_TRACE(Range);
          SCOPED_TRACE(Route);
          auto Input = nestedCarrierInvocationClasses(External, Facade, Range);
          const auto Ref = Input[1].methods[0].reference;
          const auto Original = Input[1].methods[0].generic_signature;
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          ClassMap Classes;
          Budget B;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Plan = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plan.erased_generic_invocations.contains(Ref));
          EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                    Original);
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
          std::string Text;
          for (const auto &Value : *R.getArray("source_units"))
            if (Value.getAsObject()->getString("class") == "Lfixture/Client;")
              Text = Value.getAsObject()->getString("source")->str();
          EXPECT_NE(Text.find(Facade ? "fixture.Facade) null).make("
                                     : "fixture.Provider) null).make("),
                    std::string::npos);
          EXPECT_NE(Text.find("((fixture.Factory)"), std::string::npos);
        }
}

