std::vector<Class> seededCarrierInvocationClasses(bool Dependency, bool Facade,
                                                  bool Range, bool SeedFirst) {
  auto Input = erasedFactoryInvocationClasses(Dependency, Facade, false);
  Input[4].generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Make = Input[1].methods[0];
  Make.reference.parameters =
      SeedFirst
          ? std::vector<std::string>{"Ljava/lang/Object;", Input[4].name, "J"}
          : std::vector<std::string>{Input[4].name, "Ljava/lang/Object;", "J"};
  Make.generic_signature = std::string("<T:Ljava/lang/Object;>(") +
                           (SeedFirst ? "TT;Lfixture/Factory<-TT;+TT;>;"
                                      : "Lfixture/Factory<-TT;+TT;>;TT;") +
                           "J)Lfixture/Box<TT;>;";
  if (!Dependency)
    Make.registers = 4;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, 5,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {1, 2, 3, 4}, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  if (Dependency)
    for (size_t I = 4; I < Input.size(); ++I)
      Input[I].external = true;
  return Input;
}

