std::vector<Class> erasedPairInvocationClasses(bool Dependency, unsigned Style,
                                               bool Range, bool Facade) {
  auto Factory = klass("Lfixture/Transform;");
  Factory.access = {"public", "abstract", "interface"};
  Factory.generic_signature =
      "<F:Ljava/lang/Object;G:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = Factory.access;
  Callback.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Make = method(
      "make", {Factory.name, Callback.name, "J"}, Box.name, Style ? 5 : 4,
      {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature =
      "<I:Ljava/lang/Object;O:Ljava/lang/Object;>"
      "(Lfixture/Transform<TI;TO;>;Lfixture/Callback<TO;>;J)Lfixture/Box<TI;>;";
  if (Style)
    Make.access.erase("static");
  if (Style == 2)
    Make.access.insert("abstract");
  if (Dependency || Style == 2) {
    Make.instructions.clear();
    Make.registers = Make.code_end = 0;
  }
  auto Provider = klass("Lfixture/Provider;", {Make});
  Provider.external = Dependency;
  if (Style == 2)
    Provider.access = Factory.access;
  auto Alias = klass("Lfixture/Facade;");
  if (Style != 2)
    Alias.superclass = Provider.name;
  Alias.external = Dependency;
  auto Ref = Provider.methods[0].reference;
  if (Facade && Style != 2)
    Ref.owner = Alias.name;
  auto Parameters = Ref.parameters;
  if (Style)
    Parameters.insert(Parameters.begin(), Ref.owner);
  std::vector<unsigned> Registers;
  for (unsigned N = 1; N <= (Style ? 5u : 4u); ++N)
    Registers.push_back(N);
  std::string Opcode = Style == 2 ? "invoke-interface"
                       : Style    ? "invoke-virtual"
                                  : "invoke-static";
  if (Range)
    Opcode += "/range";
  auto Call =
      method("call", Parameters, Ref.returns, Style ? 6 : 5,
             {op(0, Opcode, Registers, {}, Ref),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Client;", {Call}),
          Provider,
          Alias,
          Factory,
          Callback,
          Box};
}

TEST(MobileDalvikJava, ErasedPairCallsRetainIndependentFormalsAndDispatch) {
  for (bool Dependency : {false, true})
    for (unsigned Style : {0u, 1u, 2u})
      for (bool Range : {false, true})
        for (bool Facade : {false, true})
          for (bool Linked : {false, true}) {
            auto Input =
                erasedPairInvocationClasses(Dependency, Style, Range, Facade);
            const auto Ref = Input[1].methods[0].reference;
            const auto Original = Input[1].methods[0].generic_signature;
            ClassMap Classes;
            Budget B;
            if (Linked) {
              std::reverse(Input.begin(), Input.end());
              Classes = linkClasses(Input, B);
            } else
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            const auto Plan = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plan.erased_generic_invocations.contains(Ref));
            EXPECT_EQ(Plan.methods.at(Ref).type_parameters.size(), 2u);
            EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                      Original);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
            std::string Text;
            for (const auto &Value : *R.getArray("source_units")) {
              const auto &Unit = *Value.getAsObject();
              if (Unit.getString("class") == "Lfixture/Client;")
                Text = Unit.getString("source")->str();
            }
            EXPECT_NE(Text.find(".make("), std::string::npos);
            EXPECT_NE(Text.find(Style == 2 ? "fixture.Provider"
                                : Facade   ? "fixture.Facade"
                                           : "fixture.Provider"),
                      std::string::npos);
          }
}

TEST(MobileDalvikJava, ErasedPairCallsRejectIncompleteBoundsAndFormalBindings) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation)
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(Mutation);
      auto Input = erasedPairInvocationClasses(false, 1, false, true);
      auto &Make = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      if (Mutation == 0)
        replace("O:Ljava/lang/Object;>",
                "O:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 1) {
        replace("Transform<TI;TO;>", "Transform<TI;TI;>");
        replace("Callback<TO;>", "Callback<TI;>");
      } else if (Mutation == 2)
        replace("O:Ljava/lang/Object;", "O:Ljava/lang/Number;");
      else if (Mutation == 3)
        replace("Transform<TI;TO;>", "Transform<TI;-TO;>");
      else if (Mutation == 4)
        replace("Transform<TI;TO;>", "Transform<TI;+TO;>");
      else if (Mutation == 5)
        replace("Box<TI;>", "Box<+TI;>");
      else if (Mutation == 6)
        replace("Box<TI;>", "Box<Ljava/lang/Object;>");
      else if (Mutation == 7)
        Input[3].generic_signature =
            "<F:Ljava/lang/Object;G:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 8)
        replace("Transform<TI;TO;>", "Transform<TI;TO;TI;>");
      else if (Mutation == 9)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 10)
        Input[0].methods[0].instructions[0].opcode = "invoke-static";
      else if (Mutation == 11)
        Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
      else
        Input.erase(Input.begin() + 4);
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

TEST(MobileDalvikJava, ErasedPairCallsDoNotResolveUnrelatedDependencySlots) {
  for (unsigned Style : {0u, 1u, 2u})
    for (bool Linked : {false, true}) {
      auto Input = erasedPairInvocationClasses(true, Style, false, true);
      auto Foreign = Input[1];
      Foreign.name = "Lfixture/Unrelated;";
      auto &Method = Foreign.methods[0];
      Method.reference.owner = Foreign.name;
      Method.generic_signature =
          "<I:Ljava/lang/Object;O:Ljava/lang/Object;>"
          "(Lfixture/Transform<TI;TO;>;Lfixture/Callback<TO;>;J)"
          "Lfixture/Box<Lfixture/Unavailable<TI;>;>;";
      const auto Ref = Method.reference;
      Input.push_back(Foreign);
      Budget B;
      ClassMap Classes;
      if (Linked) {
        std::reverse(Input.begin(), Input.end());
        Classes = linkClasses(Input, B);
      } else
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
      const auto Plan = validateGenericSignatures(Classes, B);
      EXPECT_FALSE(Plan.erased_generic_invocations.contains(Ref));
      EXPECT_EQ(recoverJava(Classes, B).getInteger("unrecovered_method_count"),
                0);
      // The same unproved declaration must still fail when actually named by
      // an original invocation; filtering is not a fallback for missing types.
      auto &Call = Classes.at("Lfixture/Client;").methods[0];
      Call.instructions[0].reference = Ref;
      Budget Missing;
      EXPECT_THROW(recoverJava(Classes, Missing), std::runtime_error);
    }
}

std::vector<Class> pairedVoidCarrierClasses(bool Dependency, unsigned Style,
                                            bool Range, bool Facade,
                                            bool SeedFirst) {
  auto Input = erasedPairInvocationClasses(Dependency, Style, Range, Facade);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {"I",
                               SeedFirst ? "Ljava/lang/Object;" : Input[3].name,
                               SeedFirst ? Input[3].name : "Ljava/lang/Object;",
                               "Ljava/lang/Object;", "J"};
  Make.reference.returns = "V";
  Make.generic_signature =
      std::string("<I:Ljava/lang/Object;O:Ljava/lang/Object;>(I") +
      (SeedFirst ? "TI;Lfixture/Transform<TI;TO;>;"
                 : "Lfixture/Transform<TI;TO;>;TI;") +
      "Ljava/lang/Object;J)V";
  if (Style == 3) {
    Input[1].access = Input[2].access = {"public", "abstract"};
    Make.access = {"public", "abstract"};
  }
  Make.instructions.clear();
  Make.registers = Make.code_end = 0;
  if (!Dependency && Style < 2) {
    Make.instructions = {op(0, "return-void")};
    Make.registers = Style ? 7 : 6;
    Make.code_end = 1;
  }
  auto Ref = Make.reference;
  if (Facade && Style != 2)
    Ref.owner = Input[2].name;
  auto Parameters = Ref.parameters;
  if (Style)
    Parameters.insert(Parameters.begin(), Ref.owner);
  std::vector<unsigned> Registers;
  for (unsigned N = 0; N < (Style ? 7u : 6u); ++N)
    Registers.push_back(N);
  std::string Opcode = Style == 2 ? "invoke-interface"
                       : Style    ? "invoke-virtual"
                                  : "invoke-static";
  if (Range)
    Opcode += "/range";
  Input[0] = klass(
      "Lfixture/Client;",
      {method("call", Parameters, "V", Style ? 7 : 6,
              {op(0, Opcode, Registers, {}, Ref), op(1, "return-void")})});
  if (Dependency)
    for (size_t I = 3; I < Input.size(); ++I)
      Input[I].external = true;
  return Input;
}

std::vector<Class> unaryVoidCarrierClasses(bool External, unsigned Style,
                                           bool Range, bool Covariant) {
  auto Factory = klass("Lfixture/Factory;");
  Factory.access = {"public", "interface", "abstract"};
  Factory.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Factory.external = External;
  auto Send = method("send", {Factory.name}, "V", Style ? 2 : 1,
                     {op(0, "return-void")});
  Send.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Factory<") +
      (Covariant ? "+" : "") + "TT;>;)V";
  if (Style)
    Send.access = {"public"};
  auto Provider = klass("Lfixture/Provider;", {Send});
  if (Style == 2) {
    Provider.access = {"public", "interface", "abstract"};
    Provider.methods[0].access = {"public", "abstract"};
  }
  Provider.external = External;
  if (External || Style == 2) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  const auto Ref = Provider.methods[0].reference;
  auto Params = Ref.parameters;
  if (Style)
    Params.insert(Params.begin(), Provider.name);
  std::string Opcode = Style == 2 ? "invoke-interface"
                       : Style    ? "invoke-virtual"
                                  : "invoke-static";
  if (Range)
    Opcode += "/range";
  auto Client =
      klass("Lfixture/Client;", {method("call", Params, "V", Style ? 2 : 1,
                                        {op(0, Opcode,
                                            Style ? std::vector<unsigned>{0, 1}
                                                  : std::vector<unsigned>{0},
                                            {}, Ref),
                                         op(1, "return-void")})});
  return {Client, Provider, Factory};
}

TEST(MobileDalvikJava, UnaryVoidCarriersRetainExactFormalAndDispatch) {
  for (bool External : {false, true})
    for (unsigned Style = 0; Style < 3; ++Style)
      for (bool Range : {false, true})
        for (bool Covariant : {false, true})
          for (bool Linked : {false, true}) {
            auto Input =
                unaryVoidCarrierClasses(External, Style, Range, Covariant);
            const auto Ref = Input[1].methods[0].reference;
            Budget B;
            ClassMap Classes;
            if (Linked) {
              std::reverse(Input.begin(), Input.end());
              Classes = linkClasses(Input, B);
            } else {
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            }
            EXPECT_TRUE(validateGenericSignatures(Classes, B)
                            .erased_generic_invocations.contains(Ref));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
          }
}

TEST(MobileDalvikJava, UnaryVoidCarriersRejectChangedFormalRelations) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = unaryVoidCarrierClasses(External, 2, true, true);
      auto &Send = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        const auto At = Send.generic_signature->find(From);
        ASSERT_NE(At, std::string::npos);
        Send.generic_signature->replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("<+TT;>", "<-TT;>");
      else if (Mutation == 1)
        replace("<+TT;>", "<Ljava/lang/Object;>");
      else if (Mutation == 2)
        replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 3)
        Input[2].generic_signature =
            "<E:Ljava/lang/CharSequence;>Ljava/lang/Object;";
      else if (Mutation == 4)
        Input.pop_back();
      else if (Mutation == 5)
        Input[0].methods[0].instructions[0].opcode = "invoke-static/range";
      else if (Mutation == 6)
        Send.declared_throws = {"Ljava/lang/Exception;"};
      else
        Send.access.insert("bridge");
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class>
contextualVoidProducerClasses(bool ExternalTarget, bool ExternalCarrier,
                              bool Range, bool ObserverFirst, bool Covariant,
                              bool InterfaceObserver, bool Rename) {
  auto Input = unaryVoidCarrierClasses(ExternalTarget, 0, Range, Covariant);
  Input[2].external = ExternalCarrier;
  auto Observer = klass("Lfixture/Observer;");
  if (InterfaceObserver)
    Observer.access = {"public", "abstract", "interface"};
  Observer.external = ExternalCarrier;
  const std::string Formal = Rename ? "E" : "T";
  const auto Carrier = std::string("Lfixture/Factory<") +
                       (Covariant ? "+" : "") + "T" + Formal + ";>;";
  auto &Send = Input[1].methods[0];
  Send.reference.parameters =
      ObserverFirst ? std::vector<std::string>{Observer.name, Input[2].name}
                    : std::vector<std::string>{Input[2].name, Observer.name};
  Send.generic_signature = "<" + Formal + ":Ljava/lang/Object;>(" +
                           (ObserverFirst ? "Lfixture/Observer;" + Carrier
                                          : Carrier + "Lfixture/Observer;") +
                           ")V";
  if (!ExternalTarget)
    Send.registers = 2;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Send.reference.parameters;
  Call.registers = 2;
  Call.instructions[0].registers = {0, 1};
  Call.instructions[0].reference = Send.reference;
  auto Root = klass("Ljava/lang/Object;");
  Root.superclass.reset();
  Root.external = true;
  Input.push_back(Observer);
  Input.push_back(Root);
  return Input;
}

