TEST(MobileDalvikJava, ContextualVoidProducersRejectOpenObserversAndBadFrames) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 26; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = contextualVoidProducerClasses(External, External, true,
                                                   true, true, true, false);
        auto &Send = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &Text = *Send.generic_signature;
          const auto At = Text.find(From);
          ASSERT_NE(At, std::string::npos);
          Text.replace(At, From.size(), To);
        };
        if (Mutation == 0)
          Input.erase(Input.begin() + 3);
        else if (Mutation == 1)
          Input[3].generic_signature =
              "<O:Ljava/lang/Object;>Ljava/lang/Object;";
        else if (Mutation == 2)
          Input[3].access = {"private", "interface", "abstract"};
        else if (Mutation == 3)
          Input[3].enclosing = "Lfixture/Unknown;";
        else if (Mutation == 4)
          Input[2].generic_signature =
              "<E:Ljava/lang/Number;>Ljava/lang/Object;";
        else if (Mutation == 5)
          Input[2].generic_signature =
              "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
        else if (Mutation == 6)
          replace("Factory<+TT;>", "Factory<-TT;>");
        else if (Mutation == 7)
          replace("Factory<+TT;>", "Factory<TT;TT;>");
        else if (Mutation == 8)
          replace("T:Ljava/lang/Object;>",
                  "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        else if (Mutation == 9)
          replace("T:Ljava/lang/Object;>", "T:Ljava/lang/Number;>");
        else if (Mutation == 10)
          replace("Factory<+TT;>", "Factory<+TU;>");
        else if (Mutation == 11)
          replace("Factory<+TT;>", "Factory<+I>");
        else if (Mutation == 12)
          Send.declared_throws = {"Ljava/lang/Exception;"};
        else if (Mutation == 13)
          *Send.generic_signature += "^TT;";
        else if (Mutation == 14)
          Send.access.insert("bridge");
        else if (Mutation == 15)
          Send.access.insert("varargs");
        else if (Mutation == 16)
          Send.access.insert("synthetic");
        else if (Mutation == 17) {
          Send.access.insert("native");
          Send.instructions.clear();
          Send.registers = Send.code_end = 0;
        } else if (Mutation == 18) {
          Send.access.erase("public");
          Send.access.insert("protected");
        } else if (Mutation == 19)
          Send.access.erase("static");
        else if (Mutation == 20)
          Call.instructions[0].registers.pop_back();
        else if (Mutation == 21)
          Call.instructions[0].opcode = "invoke-interface/range";
        else if (Mutation == 22)
          Send.reference.returns = "I";
        else if (Mutation == 23)
          replace("Observer;", "Observer<*>;");
        else if (Mutation == 24)
          Call.instructions[0].registers[0] = Call.registers;
        else {
          Input[1].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          replace("<T:Ljava/lang/Object;>", "<T:TUnknown;>");
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

std::vector<Class> reifiableVoidSetterClasses(bool ExternalTarget,
                                              bool ExternalCarrier, bool Range,
                                              bool ReverseParameters,
                                              bool InterfaceObserver,
                                              bool Rename) {
  auto Input =
      contextualVoidProducerClasses(ExternalTarget, ExternalCarrier, Range,
                                    true, false, InterfaceObserver, Rename);
  auto Property = klass("Lfixture/Property;");
  Property.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Property.external = ExternalCarrier;
  const std::string Formal = Rename ? "E" : "T";
  std::vector<std::string> Types{"Lfixture/Observer;",
                                 "Lfixture/Factory<T" + Formal + ";>;",
                                 "Lfixture/Property<*>;", "T" + Formal + ";"};
  auto &Send = Input[1].methods[0];
  Send.reference.parameters = {Input[3].name, Input[2].name, Property.name,
                               "Ljava/lang/Object;"};
  if (ReverseParameters) {
    std::reverse(Types.begin(), Types.end());
    std::reverse(Send.reference.parameters.begin(),
                 Send.reference.parameters.end());
  }
  std::string Signature = "<" + Formal + ":Ljava/lang/Object;>(";
  for (const auto &Type : Types)
    Signature += Type;
  Send.generic_signature = Signature + ")V";
  if (!ExternalTarget)
    Send.registers = 4;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Send.reference.parameters;
  Call.registers = 4;
  Call.instructions[0].registers = {0, 1, 2, 3};
  Call.instructions[0].reference = Send.reference;
  Input.push_back(Property);
  return Input;
}

