std::vector<Class> directSeedVoidClasses(bool External, bool Facade,
                                         bool Rename, bool Swap, bool Nested,
                                         bool Final, bool Range, bool Wide) {
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  auto State = klass("Lfixture/State;");
  State.external = true;
  auto Number = klass("Ljava/lang/Number;");
  Number.external = true;
  const std::string A = Rename ? "Left" : "A";
  const std::string B = Rename ? "Right" : "B";
  std::vector<std::string> Parameters{State.name, "I", Object.name, "I",
                                      Object.name};
  if (Wide)
    Parameters.push_back("J");
  const uint32_t Words = Wide ? 7 : 5;
  auto Write = method("write", Parameters, "V", Words, {op(0, "return-void")});
  Write.access = {"public", "static"};
  if (Final)
    Write.access.insert("final");
  Write.generic_signature = "<" + A + ":Ljava/lang/Object;" + B +
                            ":Ljava/lang/Object;>(Lfixture/State;IT" +
                            (Swap ? B : A) + ";IT" + (Swap ? A : B) + ";" +
                            (Wide ? "J" : "") + ")V";
  auto Provider = klass(
      Nested ? "Lfixture/Outer$Provider;" : "Lfixture/Provider;", {Write});
  Provider.external = External;
  if (External)
    Provider.methods[0].instructions.clear();
  if (Nested) {
    Provider.enclosing = "Lfixture/Outer;";
    Provider.inner_class_present = true;
    Provider.inner_name = "Provider";
    Provider.inner_access = {"public", "static"};
  }
  auto Target = Provider.methods[0].reference;
  if (Facade)
    Target.owner = "Lfixture/Facade;";
  std::vector<uint32_t> Arguments;
  for (uint32_t Register = 0; Register < Words; ++Register)
    Arguments.push_back(Register);
  auto Call = method("call", Parameters, "V", Words,
                     {op(0, Range ? "invoke-static/range" : "invoke-static",
                         Arguments, {}, Target),
                      op(1, "return-void")});
  Call.access = {"public", "static"};
  std::vector<Class> Input{klass("Lfixture/Client;", {Call}), Provider, State,
                           Object, Number};
  if (Facade) {
    auto Middle = klass("Lfixture/Facade;");
    Middle.superclass = Provider.name;
    Middle.external = External;
    Input.push_back(std::move(Middle));
  }
  if (Nested) {
    auto Outer = klass("Lfixture/Outer;");
    Outer.external = External;
    Input.push_back(std::move(Outer));
  }
  return Input;
}

