TEST(MobileDalvikJava, PairedVoidCarriersRejectMissingOrVariantRelations) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = pairedVoidCarrierClasses(External, 1, true, true, false);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto Offset = Signature.find(From);
        ASSERT_NE(Offset, std::string::npos);
        Signature.replace(Offset, From.size(), To);
      };
      if (Mutation == 0)
        replace(">;TI;", ">;Ljava/lang/Object;");
      else if (Mutation == 1)
        replace("<TI;TO;>", "<TI;TI;>");
      else if (Mutation == 2)
        replace("<TI;TO;>", "<+TI;TO;>");
      else if (Mutation == 3)
        replace("O:Ljava/lang/Object;>",
                "O:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 4)
        replace("O:Ljava/lang/Object;>", "O:Ljava/lang/Number;>");
      else if (Mutation == 5)
        Input[3].generic_signature =
            "<F:Ljava/lang/Object;G:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 6)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 7)
        Make.access = {"private"};
      else if (Mutation == 8)
        Input[1].generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 9)
        Call.instructions[0].opcode = "invoke-interface/range";
      else if (Mutation == 10) {
        replace(">;TI;", ">;[TI;");
        Make.reference.parameters[2] = "[Ljava/lang/Object;";
        Call.reference.parameters[3] = "[Ljava/lang/Object;";
        std::get<MethodRef>(Call.instructions[0].reference).parameters =
            Make.reference.parameters;
      } else if (Mutation == 11)
        replace(";TI;Ljava/lang/Object;J)V", ";TI;TO;J)V");
      else {
        // Even beside a valid invariant pair, a producer/mapper variant
        // cannot borrow the return-carrier proof for a void result.
        replace("Ljava/lang/Object;J)V",
                "Ljava/lang/Object;Lfixture/Transform<-TI;+TO;>;J)V");
        Make.reference.parameters.insert(Make.reference.parameters.begin() + 4,
                                         Input[3].name);
        Call.reference.parameters.insert(Call.reference.parameters.begin() + 5,
                                         Input[3].name);
        std::get<MethodRef>(Call.instructions[0].reference).parameters =
            Make.reference.parameters;
        ++Call.registers;
        Call.instructions[0].registers.push_back(7);
        if (!External)
          ++Make.registers;
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> mappedCarrierInvocationClasses(bool Dependency,
                                                  unsigned Style, bool Range,
                                                  bool Facade,
                                                  bool CallbackFirst) {
  auto Input = erasedPairInvocationClasses(Dependency, Style, Range, Facade);
  auto &Make = Input[1].methods[0];
  Make.generic_signature =
      std::string("<I:Ljava/lang/Object;O:Ljava/lang/Object;>(") +
      (CallbackFirst
           ? "Lfixture/Transform<-TI;+TO;>;Lfixture/Callback<+TI;>;"
           : "Lfixture/Callback<+TI;>;Lfixture/Transform<-TI;+TO;>;") +
      "J)Lfixture/Box<TO;>;";
  if (!CallbackFirst) {
    std::swap(Make.reference.parameters[0], Make.reference.parameters[1]);
    auto &Call = Input[0].methods[0];
    const unsigned Offset = Style ? 1 : 0;
    std::swap(Call.reference.parameters[Offset],
              Call.reference.parameters[Offset + 1]);
    auto &Ref = std::get<MethodRef>(Call.instructions[0].reference);
    Ref.parameters = Make.reference.parameters;
  }
  if (Dependency)
    for (size_t I = 3; I < Input.size(); ++I)
      Input[I].external = true;
  return Input;
}

