TEST(MobileDalvikJava,
     MappedCarrierCallsRejectIncompleteOrCrossedTypeRelations) {
  for (bool External : {false, true})
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Linked);
        SCOPED_TRACE(Mutation);
        auto Input =
            mappedCarrierInvocationClasses(External, 1, true, true, false);
        auto &Make = Input[1].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &Signature = *Make.generic_signature;
          const auto Offset = Signature.find(From);
          ASSERT_NE(Offset, std::string::npos);
          Signature.replace(Offset, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          replace("Callback<+TI;>", "Callback<-TI;>");
          break;
        case 1:
          replace("Transform<-TI;+TO;>", "Transform<-TI;-TO;>");
          break;
        case 2:
          replace("Box<TO;>", "Box<TI;>");
          break;
        case 3:
          replace("Transform<-TI;+TO;>", "Transform<-TI;+TI;>");
          break;
        case 4:
          replace("Transform<-TI;+TO;>", "Transform<*+TO;>");
          break;
        case 5:
          replace("O:Ljava/lang/Object;>",
                  "O:Ljava/lang/Object;U:Ljava/lang/Object;>");
          break;
        case 6:
          Input[3].generic_signature =
              "<A:Ljava/lang/Number;R:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 7:
          Input[4].generic_signature =
              "<A:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 8:
          replace("O:Ljava/lang/Object;", "O:Ljava/lang/Number;");
          break;
        case 9:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 10:
          Input[1].generic_signature =
              "<P:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 11:
          Input[0].methods[0].instructions[0].opcode = "invoke-static";
          break;
        case 12:
          Input.erase(Input.begin() + 4);
          break;
        case 13:
          replace("Transform<-TI;+TO;>", "Transform<-TO;+TI;>");
          break;
        case 14:
          replace("Callback<+TI;>", "Callback<+TO;>");
          break;
        }
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> intersectionVoidInvocationClasses(bool Dependency,
                                                     bool ErasedSelf,
                                                     bool Range) {
  auto First = klass("Lfixture/First;");
  First.access = {"public", "abstract", "interface"};
  auto Second = klass("Lfixture/Second;");
  Second.access = First.access;
  auto Enable = method("enable", {First.name}, "V", 1, {op(0, "return-void")});
  Enable.generic_signature = "<T::Lfixture/First;:Lfixture/Second;>(TT;)V";
  auto Provider = klass("Lfixture/Provider;", {Enable});
  Provider.external = Dependency;
  if (Dependency) {
    auto &M = Provider.methods[0];
    M.instructions.clear();
    M.registers = M.code_end = 0;
  }
  auto Run = method("run", {}, "V", 2, {});
  Run.access = {"public"};
  if (ErasedSelf)
    Run.instructions = {op(0, "move-object", {0, 1}),
                        op(1, "check-cast", {0}, {}, First.name)};
  const auto PC = uint32_t(Run.instructions.size());
  Run.instructions.push_back(
      op(PC, Range ? "invoke-static/range" : "invoke-static",
         {ErasedSelf ? 0u : 1u}, {}, Provider.methods[0].reference));
  Run.instructions.push_back(op(PC + 1, "return-void"));
  Run.code_end = PC + 2;
  auto Host = klass("Lfixture/Host;", {Run});
  Host.interfaces = {First.name, Second.name};
  return {Host, Provider, First, Second};
}

std::vector<Class> intersectionCallbackClasses(bool External, bool ErasedSelf,
                                               bool Range) {
  auto Input = intersectionVoidInvocationClasses(External, false, Range);
  auto &Base = Input[2];
  Base.access = {"public"};
  auto Callback = klass("Lfixture/Callback;");
  Callback.external = true;
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Unit = klass("Lfixture/Unit;");
  Unit.external = true;
  auto &Enable = Input[1].methods[0];
  Enable.reference.parameters.push_back(Callback.name);
  Enable.generic_signature = "<T:Lfixture/First;:Lfixture/Second;>(TT;Lfixture/"
                             "Callback<Lfixture/Unit;>;)V";
  if (!External)
    Enable.registers = 2;
  auto &Host = Input[0];
  Host.superclass = Base.name;
  Host.interfaces = {Input[3].name};
  auto &Run = Host.methods[0];
  Run.reference.parameters = {Callback.name};
  Run.registers = 5;
  auto Read = method("read", {Callback.name}, Callback.name, 1,
                     {op(0, "return-object", {0})});
  Read.access = {"public", "static"};
  auto Getter = klass("Lfixture/Getter;", {Read});
  Run.instructions.clear();
  if (ErasedSelf)
    Run.instructions = {op(0, "move-object", {0, 3}),
                        op(1, "check-cast", {0}, {}, Base.name)};
  uint32_t PC = Run.instructions.size();
  Run.instructions.push_back(
      op(PC++, "invoke-static", {4}, {}, Getter.methods[0].reference));
  Run.instructions.push_back(op(PC++, "move-result-object", {1}));
  Run.instructions.push_back(
      op(PC++, Range ? "invoke-static/range" : "invoke-static",
         ErasedSelf ? std::vector<unsigned>{0, 1} : std::vector<unsigned>{3, 4},
         {}, Enable.reference));
  Run.instructions.push_back(op(PC++, "return-void"));
  Run.code_end = PC;
  Input.push_back(Callback);
  Input.push_back(Unit);
  Input.push_back(Getter);
  return Input;
}

TEST(MobileDalvikJava, IntersectionCallbacksKeepClassInterfaceWitnessAndTail) {
  for (bool External : {false, true})
    for (bool ErasedSelf : {false, true})
      for (bool Range : {false, true}) {
        auto Input = intersectionCallbackClasses(External, ErasedSelf, Range);
        Budget B;
        const auto R = recoverJava(linkClasses(Input, B), B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      }
}

TEST(MobileDalvikJava, IntersectionCallbacksRejectUnprovedTailAndAlias) {
  for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
    auto Input = intersectionCallbackClasses(false, true, false);
    if (Mutation == 0)
      Input[0].interfaces.clear();
    else if (Mutation == 1)
      Input[5].generic_signature = "<U:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 2)
      Input[4].generic_signature =
          "<R:Ljava/lang/CharSequence;>Ljava/lang/Object;";
    else if (Mutation == 3)
      Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 4)
      Input[1].methods[0].access.insert("varargs");
    else if (Mutation == 5)
      Input[0].methods[0].instructions[2].registers[0] = 0;
    else
      Input[5].access.erase("public");
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

std::vector<Class> branchEntryIntersectionCallbackClasses(bool External,
                                                          bool Range) {
  auto Input = intersectionCallbackClasses(External, true, Range);
  auto &Run = Input.front().methods.front();
  Run.reference.parameters.push_back("Z");
  Run.registers = 6;
  for (auto &Op : Run.instructions)
    Op.pc += 2;
  auto Touch = method("touch", {}, "V", 0, {op(0, "return-void")});
  Touch.access = {"public", "static"};
  Touch.reference.owner = Input.back().name;
  Run.instructions.insert(Run.instructions.begin(),
                          {op(0, "if-eqz", {5}, {}, {}, 2),
                           op(1, "invoke-static", {}, {}, Touch.reference)});
  Run.code_end += 2;
  Input.back().methods.push_back(std::move(Touch));
  return Input;
}

