std::vector<Class> instanceIntersectionInvocationClasses(bool Dependency,
                                                         bool Interface,
                                                         bool ErasedArgument,
                                                         bool Range) {
  auto First = klass("Lfixture/First;");
  First.access = {"public", "abstract", "interface"};
  auto Second = klass("Lfixture/Second;");
  Second.access = First.access;
  auto Enable = method("enable", {First.name}, "V", 2, {op(0, "return-void")});
  Enable.access = {"public"};
  Enable.generic_signature = "<T::Lfixture/First;:Lfixture/Second;>(TT;)V";
  auto Provider = klass("Lfixture/Provider;", {Enable});
  Provider.external = Dependency;
  if (Interface) {
    Provider.access = First.access;
    Provider.methods[0].access.insert("abstract");
  }
  if (Dependency || Interface) {
    auto &M = Provider.methods[0];
    M.instructions.clear();
    M.registers = M.code_end = 0;
  }
  auto Child = klass("Lfixture/Child;");
  if (Interface) {
    Child.access = First.access;
    Child.interfaces = {Provider.name};
  } else
    Child.superclass = Provider.name;
  auto Run = method("run", {Child.name, "Lfixture/Host;"}, "V", 4, {});
  if (ErasedArgument)
    Run.instructions = {op(0, "move-object", {3, 3}),
                        op(1, "check-cast", {3}, {}, First.name)};
  auto Ref = Provider.methods[0].reference;
  Ref.owner = Child.name;
  const auto PC = uint32_t(Run.instructions.size());
  const std::string Invoke = Interface ? "invoke-interface" : "invoke-virtual";
  Run.instructions.push_back(
      op(PC, Invoke + (Range ? "/range" : ""), {2, 3}, {}, Ref));
  Run.instructions.push_back(op(PC + 1, "return-void"));
  Run.code_end = PC + 2;
  auto Host = klass("Lfixture/Host;", {Run});
  Host.interfaces = {First.name, Second.name};
  return {Host, Provider, First, Second, Child};
}

TEST(MobileDalvikJava,
     InstanceIntersectionCallsShareCanonicalBoundsAndOriginalArgumentWords) {
  for (bool Dependency : {false, true})
    for (bool Interface : {false, true})
      for (bool ErasedArgument : {false, true})
        for (bool Range : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::Message()
                         << Dependency << Interface << ErasedArgument << Range
                         << Route);
            auto Input = instanceIntersectionInvocationClasses(
                Dependency, Interface, ErasedArgument, Range);
            const auto Canonical = Input[1].methods[0].reference;
            const auto Signature = Input[1].methods[0].generic_signature;
            const auto Alias =
                std::get<MethodRef>(Input[0]
                                        .methods[0]
                                        .instructions[ErasedArgument ? 2 : 0]
                                        .reference);
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            ClassMap Classes;
            Budget B;
            if (Route)
              Classes = linkClasses(Input, B);
            else
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_EQ(Plans.intersection_invocations.size(), 1u);
            ASSERT_TRUE(Plans.intersection_invocations.contains(Canonical));
            EXPECT_FALSE(Plans.intersection_invocations.contains(Alias));
            EXPECT_EQ(
                Plans.intersection_invocations.at(Canonical).parameter_index,
                0u);
            EXPECT_EQ(Plans.intersection_invocations.at(Canonical).bounds,
                      (std::vector<std::string>{"Lfixture/First;",
                                                "Lfixture/Second;"}));
            EXPECT_TRUE(Plans.erased_generic_invocations.empty());
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
            EXPECT_EQ(Classes.at(Canonical.owner).methods[0].generic_signature,
                      Signature);
            std::string Text;
            for (const auto &Value : *R.getArray("source_units"))
              if (Value.getAsObject()->getString("class") == "Lfixture/Host;")
                Text = Value.getAsObject()->getString("source")->str();
            EXPECT_NE(Text.find(".enable(((fixture.Host)"), std::string::npos);
            EXPECT_NE(Text.find("o3"), std::string::npos);
            if (ErasedArgument)
              EXPECT_NE(Text.find("((fixture.First)"), std::string::npos);
          }
}

TEST(MobileDalvikJava,
     InstanceIntersectionCallsRejectLostWordsBoundsAndCompetingBindings) {
  for (bool Dependency : {false, true})
    for (bool Interface : {false, true})
      for (bool Linked : {false, true})
        for (unsigned Mutation = 0; Mutation < 21; ++Mutation) {
          SCOPED_TRACE(::testing::Message()
                       << Dependency << Interface << Linked << Mutation);
          auto Input = instanceIntersectionInvocationClasses(
              Dependency, Interface, true, false);
          auto &Run = Input[0].methods[0];
          auto &Call = Run.instructions[2];
          switch (Mutation) {
          case 0:
            Input[0].interfaces.pop_back();
            break;
          case 1:
            Run.reference.parameters[1] = Input[2].name;
            break;
          case 2:
            Call.registers = {2};
            break;
          case 3:
            Call.registers = {2, 3, 3};
            break;
          case 4:
            Call.registers = {2, 4};
            break;
          case 5:
            Call.registers = {3, 2};
            break;
          case 6:
            Call.opcode = "invoke-direct";
            break;
          case 7:
            Call.opcode = "invoke-super";
            break;
          case 8:
            Call.opcode = "invoke-static";
            break;
          case 9:
            Call.opcode = Interface ? "invoke-virtual" : "invoke-interface";
            break;
          case 10:
            Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
            break;
          case 11:
            Input[1].methods[0].generic_signature =
                "<T::Lfixture/First;:Lfixture/Second;U:Ljava/lang/"
                "Object;>(TT;)V";
            break;
          case 12:
            Input[3].access.erase("interface");
            break;
          case 13:
            Run.instructions[0] = op(0, "nop");
            break;
          case 14:
            Run.instructions[0] = op(0, "const/4", {3}, int64_t(0));
            break;
          default: {
            auto &Owner = Input[(Mutation - 15) / 3 == 0 ? 4 : 1];
            const auto Kind = (Mutation - 15) % 3;
            auto Overload =
                method("enable",
                       {Kind == 0   ? Input[0].name
                        : Kind == 1 ? "[" + Input[0].name
                                    : Input[3].name},
                       "V", Kind == 2 ? 1 : 2, {op(0, "return-void")});
            Overload.reference.owner = Owner.name;
            Overload.access = {"public"};
            if (Kind == 1)
              Overload.access.insert("varargs");
            if (Kind == 2) {
              Overload.access.insert("static");
              Overload.generic_signature =
                  "<U::Lfixture/Second;:Lfixture/First;>(TU;)V";
            } else if (Interface)
              Overload.access.insert("abstract");
            if (Owner.external || (Interface && Kind != 2)) {
              Overload.instructions.clear();
              Overload.registers = Overload.code_end = 0;
            }
            Owner.methods.push_back(Overload);
            break;
          }
          }
          Budget B;
          EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                              : recover(Input),
                       std::runtime_error);
        }
}

