std::vector<Class> genericAnonymousMemberClasses() {
  auto Contract = klass("Lfixture/Reader;");
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Read = method("read", {}, "Ljava/lang/Object;", 0, {});
  Read.reference.owner = Contract.name;
  Read.generic_signature = "()TR;";
  Read.access = {"public", "abstract"};
  Contract.methods = {Read};
  auto Owner = klass("Lfixture/Owner;");
  Owner.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  FieldRef Value{Owner.name, "value", "Ljava/lang/Object;"};
  Owner.fields.push_back({Value, {"public"}, {}, "TT;"});
  auto Member = klass("Lfixture/Owner$1;");
  Member.access.clear();
  Member.inner_class_present = true;
  Member.enclosing = Owner.name;
  Member.interfaces = {Contract.name};
  Member.generic_signature = "Ljava/lang/Object;Lfixture/Reader<TT;>;";
  FieldRef Capture{Member.name, "owner", Owner.name};
  Member.fields.push_back({Capture, {"final", "synthetic"}, {}});
  auto Init = method("<init>", {Owner.name}, "V", 2,
                     {op(0, "iput-object", {1, 0}, {}, Capture),
                      op(1, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(2, "return-void")});
  Init.reference.owner = Member.name;
  Init.access = {"constructor"};
  auto Body = method("read", {}, "Ljava/lang/Object;", 2,
                     {op(0, "iget-object", {0, 1}, {}, Capture),
                      op(1, "iget-object", {0, 0}, {}, Value),
                      op(2, "return-object", {0})});
  Body.reference.owner = Member.name;
  Body.access = {"public"};
  Body.generic_signature = "()TT;";
  auto Echo = method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                     {op(0, "return-object", {1})});
  Echo.reference.owner = Member.name;
  Echo.access = {"public"};
  Echo.generic_signature = "<T:Ljava/lang/Object;>(TT;)TT;";
  Member.methods = {Init, Body, Echo};
  return {Owner, Member, Contract};
}

TEST(MobileDalvikJava, AnonymousMembersProjectOnlyDirectParentObjectFormals) {
  auto Input = genericAnonymousMemberClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto R = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    unsigned Changes = 0;
    for (const auto &Row : *R.getArray("generic_signature_projections"))
      for (const auto &Change : *Row.getAsObject()->getArray("changes")) {
        const auto &Projection = *Change.getAsObject();
        EXPECT_EQ(Projection.getString("kind"),
                  "anonymous-member-type-variable");
        EXPECT_EQ(Projection.getString("original_type"), Input[0].name + "::T");
        EXPECT_EQ(Projection.getString("source_type"), "Ljava/lang/Object;");
        EXPECT_EQ(Projection.getString("scope_origin"), Input[0].name);
        ++Changes;
      }
    EXPECT_EQ(Changes, 2u);
    EXPECT_EQ(R.getString("status"), "partial");
    EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
    EXPECT_NE(source(R).find("fixture.Reader<java.lang.Object>"),
              std::string::npos);
    EXPECT_NE(source(R).find("T echo(T arg0)"), std::string::npos);
    EXPECT_EQ(Input[1].methods[2].generic_signature,
              "<T:Ljava/lang/Object;>(TT;)TT;");
    EXPECT_EQ(Input[1].methods[1].generic_signature, "()TT;");
  }
}

TEST(MobileDalvikJava, AnonymousMemberScopesRejectOtherBoundsAndEnclosures) {
  for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = genericAnonymousMemberClasses();
    switch (Mutation) {
    case 0:
      Input[0].generic_signature =
          "<T:Ljava/lang/Object;:Ljava/io/Serializable;>Ljava/lang/Object;";
      break;
    case 1:
      Input[1].inner_access = {"static"};
      break;
    case 2:
      Input[0].generic_signature =
          "<U:Ljava/lang/Object;T:TU;>Ljava/lang/Object;";
      break;
    case 3:
      Input[1].enclosing = "Lfixture/Other;";
      Input.push_back(klass("Lfixture/Other;"));
      break;
    case 4:
      Input[1].methods[1].generic_signature = "()TUnknown;";
      break;
    }
    rejected([&] { recover(Input); },
             Mutation == 1 || Mutation >= 3
                 ? "unbound type variable"
                 : "captures an enclosing type variable");
  }
}

