TEST(MobileDalvikJava,
     AllocationAllowsPurePreparationButRejectsObservableGaps) {
  auto Input = constructorPrologueClasses(false);
  const auto Init = Input[0].methods[0].reference;
  auto Make = method("make", {}, Input[0].name, 2,
                     {op(0, "new-instance", {0}, {}, Init.owner),
                      op(1, "const/4", {1}, int64_t(3)),
                      op(2, "invoke-direct", {0, 1}, {}, Init),
                      op(3, "return-object", {0})});
  Input[1] = klass("Lfixture/Core;", {Make});
  EXPECT_NE(source(recover(Input), 1).find("new fixture.Base(v1)"),
            std::string::npos);
  for (int Mutation = 0; Mutation != 4; ++Mutation) {
    Input[1].methods[0] = Make;
    auto &M = Input[1].methods[0];
    std::string Error;
    switch (Mutation) {
    case 0:
      M.instructions[1] = op(1, "move-object", {1, 0});
      // Copying a receiver is supported; consuming it as an original int
      // constructor argument still exposes an uninitialized object.
      Error = "uninitialized receiver";
      break;
    case 1:
      M.instructions[1] =
          op(1, "const-class", {1}, {}, std::string("Lfixture/Base;"));
      // Class literals are supported, but cannot supply the original int slot.
      Error = "undefined or incompatible register";
      break;
    case 2:
      M.instructions.push_back(op(4, "move-exception", {1}));
      M.instructions.push_back(op(5, "throw", {1}));
      M.code_end = 6;
      M.tries = {{0, 3, {{std::nullopt, 4}}}};
      break;
    case 3:
      M.registers = 3;
      M.reference.parameters = {"I"};
      for (auto &I : M.instructions)
        ++I.pc;
      M.instructions.insert(M.instructions.begin(),
                            op(0, "if-eqz", {2}, {}, {}, 2));
      M.code_end = 5;
      Error = "pure register preparation";
      break;
    }
    if (Mutation == 2) {
      // The shared allocation plan now proves this same-handler program.
      // Its handler replaces the deferred word with the original exception.
      const auto R = recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      const auto Text = source(R, 1);
      EXPECT_NE(Text.find("new fixture.Base("), std::string::npos);
      EXPECT_NE(Text.find("caught = failure; pc = 4"), std::string::npos);
      EXPECT_NE(Text.find("o1 = caught;"), std::string::npos);
      EXPECT_NE(Text.find("throw __neverdThrow((java.lang.Throwable)"),
                std::string::npos);
      continue;
    }
    rejected([&] { recover(Input); }, Error);
  }
}

std::vector<Class> allocationStaticCallClasses(bool Dependency, bool Cast,
                                               bool Range) {
  auto Init =
      method("<init>",
             {Cast ? "Ljava/lang/String;" : "Ljava/lang/Object;", "I"}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Base = klass("Lfixture/Base;", {Init});
  auto Check = method("check", {"Ljava/lang/Object;", "J", "D"},
                      "Ljava/lang/Object;", 5, {op(0, "return-object", {0})});
  auto Provider = klass("Lfixture/Provider;", {Check});
  Provider.external = Dependency;
  if (Dependency) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Make = method(
      "make", {"Ljava/lang/Object;", "J", "D"}, Base.name, 10,
      {op(0, "new-instance", {0}, {}, Base.name),
       op(1, Range ? "invoke-static/range" : "invoke-static", {5, 6, 7, 8, 9},
          {}, Provider.methods[0].reference),
       op(2, "move-result-object", {1}),
       Cast ? op(3, "check-cast", {1}, {}, std::string("Ljava/lang/String;"))
            : op(3, "nop"),
       op(4, "const/4", {2}, int64_t(9)),
       op(5, "invoke-direct", {0, 1, 2}, {}, Base.methods[0].reference),
       op(6, "return-object", {0})});
  return {Base, klass("Lfixture/Core;", {Make}), Provider};
}

TEST(MobileDalvikJava, AllocationEmbedsStaticCallsAfterOriginalNew) {
  for (bool Dependency : {false, true})
    for (bool Cast : {false, true})
      for (bool Range : {false, true})
        for (bool Reverse : {false, true})
          for (bool LinkedEntry : {false, true}) {
            SCOPED_TRACE(::testing::Message() << Dependency << Cast << Range
                                              << Reverse << LinkedEntry);
            auto Input = allocationStaticCallClasses(Dependency, Cast, Range);
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto Report = LinkedEntry
                                    ? recoverJava(linkClasses(Input, B), B)
                                    : recover(Input);
            const auto Text = source(Report, 1);
            const auto New = Text.find("new fixture.Base(");
            const auto Call = Text.find(".check(");
            ASSERT_NE(New, std::string::npos);
            ASSERT_NE(Call, std::string::npos);
            EXPECT_LT(New, Call);
            EXPECT_EQ(Text.find(".check(", Call + 1), std::string::npos);
            EXPECT_NE(Text.find("(o1 = (resultObject = ", New),
                      std::string::npos);
            if (Cast)
              EXPECT_NE(Text.find("java.lang.String) (o1 =", New),
                        std::string::npos);
            EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          }
}

TEST(MobileDalvikJava, AllocationStaticCallsShareExactMemberAccess) {
  for (const auto &Visibility : {"", "public", "protected", "private"})
    for (bool Own : {false, true})
      for (bool Dependency : {false, true})
        for (bool Foreign : {false, true})
          for (bool Range : {false, true}) {
            if (Own && (Dependency || Foreign))
              continue;
            SCOPED_TRACE(::testing::Message() << Visibility << Own << Dependency
                                              << Foreign << Range);
            auto Input = allocationStaticCallClasses(Dependency, true, Range);
            auto &Provider = Input[2];
            auto &Call = Provider.methods[0];
            Call.access = {"static"};
            if (std::string(Visibility) != "")
              Call.access.insert(Visibility);
            if (Own || Foreign) {
              Provider.name = Own ? Input[1].name : "Lother/Provider;";
              Call.reference.owner = Provider.name;
              Input[1].methods[0].instructions[1].reference = Call.reference;
            }
            if (Own) {
              Input[1].methods.push_back(Call);
              Input.pop_back();
            }
            if (!Own && (std::string(Visibility) == "private" ||
                         (Foreign && std::string(Visibility) != "public"))) {
              EXPECT_THROW(recover(Input), std::runtime_error);
              continue;
            }
            Budget B;
            const auto R =
                Range ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            const auto Text = source(R, 1);
            const auto New = Text.find("new fixture.Base(");
            const auto CallAt = Text.find(".check(");
            ASSERT_NE(New, std::string::npos);
            ASSERT_NE(CallAt, std::string::npos);
            EXPECT_LT(New, CallAt);
            EXPECT_EQ(Text.find(".check(", CallAt + 1), std::string::npos);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          }
}

TEST(MobileDalvikJava, AllocationCallsRequireProvenDataflowAndHandlers) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    // The value graph now proves this original result/input reuse below.
    if (Mutation == 3)
      continue;
    SCOPED_TRACE(Mutation);
    auto Input = allocationStaticCallClasses(false, true, true);
    auto &Make = Input[1].methods[0];
    auto &Code = Make.instructions;
    switch (Mutation) {
    case 0:
      Code[1].opcode = "invoke-virtual";
      break;
    case 1:
      Code[2].opcode = "move-result";
      break;
    case 2:
      Code[2].registers = {0};
      break;
    case 4:
      Code[4] = op(4, "const/4", {5}, int64_t(0));
      break;
    case 5:
      Code[3].registers = {4};
      break;
    case 6:
      Code[5].registers[1] = 5;
      break;
    case 7:
      Input[2].methods[0].access = {"private", "static"};
      break;
    case 8:
      Input.pop_back();
      break;
    case 9:
      Make.instructions.push_back(op(7, "move-exception", {3}));
      Make.instructions.push_back(op(8, "throw", {3}));
      Make.code_end = 9;
      Make.tries = {{0, 6, {{std::nullopt, 7}}}};
      break;
    case 10:
      Code[4] = op(4, "move-object", {3, 1});
      break;
    case 11:
      for (auto &Instruction : Code)
        ++Instruction.pc;
      Code.insert(Code.begin(), op(0, "if-eqz", {5}, {}, {}, 3));
      Make.code_end = 8;
      break;
    }
    if (Mutation == 9) {
      // Protection alone is not a changed effect: the value graph keeps the
      // original argument call inside new, and the fresh handler only rethrows.
      const auto R = recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      const auto Text = source(R, 1);
      const auto New = Text.find("new fixture.Base(");
      const auto Call = Text.find(".check(");
      ASSERT_NE(New, std::string::npos);
      ASSERT_NE(Call, std::string::npos);
      EXPECT_LT(New, Call);
      EXPECT_EQ(Text.find(".check(", Call + 1), std::string::npos);
      EXPECT_NE(Text.find("caught = failure; pc = 7"), std::string::npos);
      EXPECT_NE(Text.find("o3 = caught;"), std::string::npos);
      EXPECT_NE(Text.find("throw __neverdThrow((java.lang.Throwable)"),
                std::string::npos);
      continue;
    }
    rejected([&] { recover(Input); },
             Mutation == 0   ? "declared static/instance kind"
             : Mutation == 1 ? "move-result carrier"
             : Mutation == 5 || Mutation == 6 ? "undefined or incompatible"
                                             : "allocation");
  }
}

std::vector<Class> allocationCallAliasClasses(bool Dependency, bool Field,
                                              bool Cast, bool Range) {
  auto Input = allocationStaticCallClasses(Dependency, Cast, Range);
  auto &Make = Input[1].methods[0];
  Make.instructions[2].registers = {5};
  if (Cast)
    Make.instructions[3].registers = {5};
  Make.instructions[5].registers[1] = 5;
  if (Field) {
    auto Holder = klass("Lfixture/Holder;");
    const FieldRef Value{Holder.name, "value", "Ljava/lang/Object;"};
    Holder.fields.push_back({Value, {"public"}, {}});
    Make.reference.parameters[0] = Holder.name;
    Make.instructions.insert(Make.instructions.begin() + 1,
                             op(1, "iget-object", {5, 5}, {}, Value));
    for (size_t I = 2; I < Make.instructions.size(); ++I)
      ++Make.instructions[I].pc;
    ++Make.code_end;
    Input.push_back(std::move(Holder));
  }
  return Input;
}

TEST(MobileDalvikJava, AllocationCallsKeepOriginalValuesAcrossResultAliases) {
  for (bool Dependency : {false, true})
    for (bool Field : {false, true})
      for (bool Cast : {false, true})
        for (bool Range : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            auto Input =
                allocationCallAliasClasses(Dependency, Field, Cast, Range);
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            const auto Text = source(R, 1);
            const auto New = Text.find("new fixture.Base(");
            const auto Call = Text.find(".check(", New);
            ASSERT_NE(New, std::string::npos);
            ASSERT_NE(Call, std::string::npos);
            EXPECT_EQ(Text.find(".check(", Call + 1), std::string::npos);
            if (Field) {
              const auto Read = Text.find(".value", New);
              EXPECT_LT(Read, Call);
              EXPECT_EQ(Text.find(".value", Read + 1), std::string::npos);
            }
          }
}

TEST(MobileDalvikJava, AllocationCallAliasesRetainEntryAndValueGuards) {
  for (bool Dependency : {false, true})
    for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = allocationCallAliasClasses(Dependency, true, true, true);
      auto &Make = Input[1].methods[0];
      auto &Code = Make.instructions;
      if (Mutation == 0)
        Code[3].registers = {0};
      else if (Mutation == 1)
        Code[2].registers[0] = 0;
      else if (Mutation == 2)
        Code[2].registers[2] = 8;
      else if (Mutation == 3)
        Code[3].opcode = "move-result";
      else if (Mutation == 4)
        Input[2].methods[0].access = {"private", "static"};
      else if (Mutation == 5) {
        for (auto &Op : Code)
          ++Op.pc;
        Code.insert(Code.begin(), op(0, "if-eqz", {5}, {}, {}, 4));
        ++Make.code_end;
      } else {
        Code.push_back(op(8, "move-exception", {1}));
        Code.push_back(op(9, "throw", {1}));
        Make.code_end = 10;
        Make.tries = {{1, 4, {{std::nullopt, 8}}}};
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> allocationHandlerGapClasses(bool Gap, bool Range) {
  auto Init = method("<init>", {"Ljava/lang/Object;"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Node = klass("Lfixture/Node;", {Init});
  auto Make = method("make", {"Ljava/lang/Object;"}, Node.name, 4,
                     {op(0, "new-instance", {0}, {}, Node.name),
                      op(1, "move-object", {1, 3}),
                      op(2, Range ? "invoke-direct/range" : "invoke-direct",
                         {0, 1}, {}, Node.methods[0].reference),
                      op(3, "return-object", {0}), op(4, "move-exception", {2}),
                      op(5, "throw", {2})});
  Make.access = {"public", "static"};
  const std::vector<Handler> Catch{{"Ljava/lang/RuntimeException;", 4}};
  Make.tries = Gap ? std::vector<TryRegion>{{0, 1, Catch}, {2, 3, Catch}}
                   : std::vector<TryRegion>{{0, 3, Catch}};
  return {klass("Lfixture/Client;", {Make}), Node};
}

