std::vector<Class> allocationHandlerAdapterClasses(bool Dependency, bool Wide,
                                                   bool Range) {
  auto Init = method("<init>", {"Ljava/lang/Object;"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Node = klass("Lfixture/Node;", {Init});
  Node.external = Dependency;
  if (Dependency)
    Node.methods[0].instructions.clear();
  const std::string ValueType = Wide ? "J" : "Ljava/lang/Object;";
  auto Make = method(
      "make", {ValueType, ValueType, "Ljava/lang/Object;"}, ValueType, 12,
      {op(0, "new-instance", {0}, {}, Node.name),
       op(1, Wide ? "move-wide" : "move-object", {1, Wide ? 7u : 9u}),
       op(2, Range ? "invoke-direct/range" : "invoke-direct", {0, 11}, {},
          Node.methods[0].reference),
       op(3, Wide ? "return-wide" : "return-object", {Wide ? 7u : 9u}),
       op(4, "move-exception", {6}),
       op(5, Wide ? "move-wide" : "move-object", {3, Wide ? 7u : 9u}),
       op(6, "goto", {}, {}, {}, 10), op(7, "move-exception", {6}),
       op(8, Wide ? "move-wide" : "move-object", {3, 1}),
       op(9, "goto", {}, {}, {}, 10),
       op(10, Wide ? "return-wide" : "return-object", {3})});
  // Parameters occupy the final incoming words. Keep two independently
  // observable values, even though they have exactly the same verifier type.
  Make.access = {"public", "static"};
  Make.tries = {{0, 1, {{"Ljava/lang/RuntimeException;", 4}}},
                {2, 3, {{"Ljava/lang/RuntimeException;", 7}}}};
  return {klass("Lfixture/Client;", {Make}), Node};
}

