std::vector<Class>
constantAllocationHandlerAdapterClasses(bool Dependency, bool Wide, bool Range,
                                        const std::string &Opcode,
                                        int64_t Literal) {
  auto Input = allocationHandlerAdapterClasses(Dependency, Wide, Range);
  const std::string Value = Wide ? "J" : "Ljava/lang/Object;";
  auto Observe = method(
      "observe", {Value, Wide ? "J" : "I", "Ljava/lang/RuntimeException;"},
      Value, Wide ? 5 : 3,
      {op(0, Wide ? "return-wide" : "return-object", {0})});
  Observe.access = {"public", "static"};
  auto Cleanup = klass("Lfixture/Cleanup;", {Observe});
  Cleanup.external = Dependency;
  if (Dependency)
    Cleanup.methods[0].instructions.clear();
  auto &Make = Input[0].methods[0];
  auto &Code = Make.instructions;
  Code.resize(4);
  Code.insert(Code.end(),
              {op(4, "move-exception", {6}),
               op(5, Wide ? "move-wide" : "move-object", {3, Wide ? 7u : 9u}),
               op(6, Opcode, {0}, Literal), op(7, "goto", {}, {}, {}, 12),
               op(8, "move-exception", {6}),
               op(9, Wide ? "move-wide" : "move-object", {3, 1}),
               op(10, Wide ? "const-wide" : "const", {0}, Literal),
               op(11, "goto", {}, {}, {}, 12),
               op(12, "invoke-static",
                  Wide ? std::vector<unsigned>{3, 4, 0, 1, 6}
                       : std::vector<unsigned>{3, 0, 6},
                  {}, Cleanup.methods[0].reference),
               op(13, Wide ? "move-result-wide" : "move-result-object", {3}),
               op(14, Wide ? "return-wide" : "return-object", {3})});
  Make.tries[1].handlers[0].target = 8;
  Make.code_end = 15;
  Input.push_back(std::move(Cleanup));
  return Input;
}

