      if (Mutation == 0)
        Make.instructions[8].registers[1] = Wide ? 9 : 10;
      else if (Mutation == 1)
        Make.tries[1].handlers[0].type = "Ljava/lang/Exception;";
      else if (Mutation == 2)
        Make.instructions[9].target = 8;
      else if (Mutation == 3)
        Make.instructions[8] =
            op(8, "check-cast", {1}, {}, "Ljava/lang/String;");
      else if (Mutation == 4)
        Make.instructions[7] = op(7, "nop");
      else if (Mutation == 5)
        Make.instructions[8].registers[1] = 0;
      else if (Mutation == 6)
        Make.tries[1].handlers.clear();
      else
        Make.instructions[1].registers[1] = Wide ? 9 : 10;
