std::vector<Class> nestedAllocationClasses() {
  auto InnerInit =
      method("<init>", {"Ljava/lang/Object;"}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  InnerInit.access = {"public", "constructor"};
  auto Inner = klass("Lfixture/Inner;", {InnerInit});
  auto OuterInit =
      method("<init>", {Inner.name, "[B"}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  OuterInit.access = {"public", "constructor"};
  auto Outer = klass("Lfixture/Outer;", {OuterInit});
  auto Read =
      method("read", {}, "Ljava/lang/Object;", 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.access = {"public"};
  auto Bytes = method("bytes", {"I"}, "[B", 2,
                      {op(0, "new-array", {0, 1}, {}, std::string("[B")),
                       op(1, "return-object", {0})});
  auto Provider = klass("Lfixture/Provider;", {Read, Bytes});
  auto Make =
      method("make", {Provider.name, "I"}, Outer.name, 4,
             {op(0, "new-instance", {0}, {}, Outer.name),
              op(1, "new-instance", {1}, {}, Inner.name),
              op(2, "invoke-virtual", {2}, {}, Provider.methods[0].reference),
              op(3, "move-result-object", {2}),
              op(4, "invoke-direct", {1, 2}, {}, Inner.methods[0].reference),
              op(5, "invoke-static", {3}, {}, Provider.methods[1].reference),
              op(6, "move-result-object", {2}),
              op(7, "invoke-direct", {0, 1, 2}, {}, Outer.methods[0].reference),
              op(8, "return-object", {0})});
  return {klass("Lfixture/Core;", {Make}), Inner, Outer, Provider};
}

std::vector<Class> expressionLocalCallClasses(const std::string &Type,
                                              const std::string &Visibility,
                                              bool Own = false,
                                              bool Dependency = false,
                                              bool Range = false) {
  auto Input = nestedAllocationClasses();
  const bool Void = Type == "V";
  auto Read =
      method("localValue", {"I"}, Type, 1,
             Void ? std::vector<Instruction>{op(0, "return-void")}
                  : std::vector<Instruction>{
                        op(0, "const/4", {0}, int64_t(0)),
                        op(1, Type == "I" ? "return" : "return-object", {0})});
  Read.reference.owner = Own ? Input[0].name : Input[3].name;
  Read.access = {"static"};
  if (!Visibility.empty())
    Read.access.insert(Visibility);
  Input[1].methods[0].reference.parameters = {Void ? "I" : Type};
  auto &Code = Input[0].methods[0].instructions;
  Code[2] = op(2, Range ? "invoke-static/range" : "invoke-static", {3}, {},
               Read.reference);
  Code[3] =
      Void ? op(3, "const/4", {2}, int64_t(0))
           : op(3, Type == "I" ? "move-result" : "move-result-object", {2});
  Code[4].reference = Input[1].methods[0].reference;
  if (Own)
    Input[0].methods.push_back(std::move(Read));
  else
    Input[3].methods[0] = std::move(Read);
  if (Dependency) {
    Input[3].external = true;
    for (auto &M : Input[3].methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  }
  return Input;
}

TEST(MobileDalvikJava, ExpressionLocalCallsShareExactStaticAccessAndEffects) {
  for (const auto &Type : {"I", "Ljava/lang/Object;", "V"})
    for (const auto &Visibility : {"", "private", "protected", "public"})
      for (bool Own : {false, true})
        for (bool Dependency : {false, true})
          for (bool Range : {false, true})
            for (bool Linked : {false, true}) {
              auto Input = expressionLocalCallClasses(Type, Visibility, Own,
                                                      Dependency, Range);
              if (!Own && std::string(Visibility) == "private") {
                EXPECT_THROW(recover(Input), std::runtime_error);
                continue;
              }
              Budget B;
              const auto R = Linked ? recoverJava(linkClasses(Input, B), B)
                                    : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8),
                        std::string(Type) == "V" ? 14 : 8);
              const auto Text = source(R);
              const auto Outer = Text.find("new fixture.Outer(");
              const auto Inner = Text.find("new fixture.Inner(");
              const auto Call = Text.find(".localValue(");
              ASSERT_NE(Call, std::string::npos);
              EXPECT_LT(Outer, Inner);
              EXPECT_LT(Inner, Call);
              EXPECT_LT(Call, Text.find(".bytes(", Call));
              EXPECT_EQ(Text.find(".localValue(", Call + 1), std::string::npos);
            }
}

TEST(MobileDalvikJava, ExpressionLocalCallsRejectScopeAndProducerDrift) {
  for (unsigned Mutation = 0; Mutation != 8; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = expressionLocalCallClasses("I", "");
    auto &Code = Input[0].methods[0].instructions;
    auto &Provider = Input[3];
    if (Mutation == 0 || Mutation == 1) {
      Provider.name = "Lother/Provider;";
      for (auto &M : Provider.methods)
        M.reference.owner = Provider.name;
      Input[0].methods[0].reference.parameters[0] = Provider.name;
      Code[2].reference = Provider.methods[0].reference;
      Code[5].reference = Provider.methods[1].reference;
      if (Mutation == 1)
        Provider.methods[0].access.insert("protected");
    } else if (Mutation == 2) {
      auto Alias = klass("Lfixture/Alias;", {});
      Alias.superclass = Provider.name;
      std::get<MethodRef>(Code[2].reference).owner = Alias.name;
      Input.push_back(std::move(Alias));
    } else if (Mutation == 3)
      Code[2].registers = {0};
    else if (Mutation == 4)
      Code[3].registers = {0};
    else if (Mutation == 5)
      Provider.methods[0].access.insert("bridge");
    else if (Mutation == 6)
      Provider.methods[0].access.erase("static");
    else {
      // A scalar result is supported, but cannot change the original int
      // constructor slot into a floating-point argument.
      Provider.methods[0].reference.returns = "F";
      Code[2].reference = Provider.methods[0].reference;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

TEST(MobileDalvikJava,
     ExpressionInstanceCallsKeepExactPackageAccessAndDispatch) {
  for (bool Own : {false, true})
    for (bool Dependency : {false, true})
      for (bool Final : {false, true})
        for (const auto &Visibility : {"", "protected"})
          for (unsigned Route = 0; Route < 3; ++Route) {
            if (Own && Dependency)
              continue;
            SCOPED_TRACE(testing::PrintToString(
                std::make_tuple(Own, Dependency, Final, Visibility, Route)));
            auto Input = nestedAllocationClasses();
            auto Read = Input[3].methods[0];
            Read.access.clear();
            if (*Visibility)
              Read.access.insert(Visibility);
            if (Final)
              Read.access.insert("final");
            if (Own) {
              Read.reference.owner = Input[0].name;
              Input[0].methods[0].reference.parameters[0] = Input[0].name;
              Input[0].methods.push_back(Read);
            } else
              Input[3].methods[0] = Read;
            auto &Call = Input[0].methods[0].instructions[2];
            Call.reference = Read.reference;
            if (Route == 2)
              Call.opcode = "invoke-virtual/range";
            if (Dependency) {
              Input[3].external = true;
              for (auto &Method : Input[3].methods) {
                Method.instructions.clear();
                Method.registers = Method.code_end = 0;
              }
            }
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto Report =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
            const auto Text = source(Report);
            const auto Outer = Text.find("new fixture.Outer(");
            const auto Inner = Text.find("new fixture.Inner(");
            const auto Invoke = Text.find(".read(");
            ASSERT_NE(Invoke, std::string::npos);
            EXPECT_LT(Outer, Inner);
            EXPECT_LT(Inner, Invoke);
            EXPECT_EQ(Text.find(".read(", Invoke + 1), std::string::npos);
          }
}

TEST(MobileDalvikJava, ExpressionInstanceCallsRejectForeignAccessAndAliases) {
  for (unsigned Route = 0; Route < 3; ++Route)
    for (unsigned Mutation = 0; Mutation < 6; ++Mutation) {
      SCOPED_TRACE(Route);
      SCOPED_TRACE(Mutation);
      auto Input = nestedAllocationClasses();
      auto &Provider = Input[3];
      Provider.methods[0].access.clear();
      auto &Make = Input[0].methods[0];
      if (Mutation < 2) {
        Provider.name = "Lother/Provider;";
        for (auto &Method : Provider.methods)
          Method.reference.owner = Provider.name;
        Make.reference.parameters[0] = Provider.name;
        Make.instructions[2].reference = Provider.methods[0].reference;
        Make.instructions[5].reference = Provider.methods[1].reference;
        if (Mutation == 1)
          Provider.methods[0].access.insert("protected");
      } else if (Mutation == 2)
        Provider.methods[0].access.insert("private");
      else if (Mutation == 3)
        Provider.methods[0].access.insert("bridge");
      else if (Mutation == 4)
        Provider.methods[0].access.insert("static");
      else {
        // Same-package inherited spellings have a positive receipt. This
        // foreign intermediate cannot inherit the original package member.
        auto Alias = klass("Lother/Alias;");
        Alias.superclass = Provider.name;
        Make.reference.parameters[0] = Alias.name;
        std::get<MethodRef>(Make.instructions[2].reference).owner = Alias.name;
        Input.push_back(std::move(Alias));
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      if (Route)
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class>
allocationFieldChainClasses(const std::string &Visibility, unsigned Return = 0,
                            bool IntegerLeaf = false, bool Own = false,
                            bool Dependency = false, bool Range = false) {
  const std::string Leaf = IntegerLeaf ? "I" : "Ljava/lang/Object;";
  auto Init = method("<init>", {Leaf, "I"}, "V", 3,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"constructor"};
  if (!Visibility.empty())
    Init.access.insert(Visibility);
  auto Target = klass(Own ? "Lfixture/Core;" : "Lfixture/Target;", {Init});
  if (Dependency) {
    Target.external = true;
    Target.methods[0].instructions.clear();
    Target.methods[0].registers = Target.methods[0].code_end = 0;
  }
  auto Holder = klass("Lfixture/Holder;", {});
  auto Link = klass("Lfixture/Link;", {});
  const FieldRef Next{Holder.name, "link", Link.name};
  const FieldRef Value{Link.name, "value", Leaf};
  const FieldRef Count{Holder.name, "count", "I"};
  Holder.fields = {{Next, {"public", "volatile"}, {}},
                   {Count, {"public", "volatile"}, {}}};
  Link.fields = {{Value, {"public", "volatile"}, {}}};
  const std::string Result = Return == 0   ? Target.name
                             : Return == 1 ? Leaf
                             : Return == 2 ? "I"
                                           : Link.name;
  auto Make =
      method("make", {Holder.name}, Result, 5,
             {op(0, "new-instance", {0}, {}, Target.name),
              op(1, "iget-object", {1, 4}, {}, Next),
              Return == 3 ? op(2, "move-object", {3, 1}) : op(2, "nop"),
              op(3, IntegerLeaf ? "iget" : "iget-object", {1, 1}, {}, Value),
              op(4, "iget", {2, 4}, {}, Count),
              op(5, Range ? "invoke-direct/range" : "invoke-direct", {0, 1, 2},
                 {}, Target.methods[0].reference),
              op(6, Result == "I" ? "return" : "return-object", {Return})});
  auto Core = klass("Lfixture/Core;", {Make});
  if (Own)
    Core.methods.push_back(Target.methods[0]);
  std::vector<Class> Input{Core, Holder, Link};
  if (!Own)
    Input.push_back(std::move(Target));
  return Input;
}

TEST(MobileDalvikJava, AllocationFieldChainsKeepVersionsAndLocalConstructors) {
  for (const auto &Visibility : {"", "protected", "private", "public"})
    for (unsigned Return = 0; Return != 4; ++Return)
      for (bool IntegerLeaf : {false, true})
        for (bool Own : {false, true})
          for (bool Dependency : {false, true})
            for (bool Range : {false, true}) {
              if (Own && Dependency)
                continue;
              auto Input = allocationFieldChainClasses(
                  Visibility, Return, IntegerLeaf, Own, Dependency, Range);
              if (!Own && std::string(Visibility) == "private") {
                EXPECT_THROW(recover(Input), std::runtime_error);
                continue;
              }
              Budget B;
              const auto R = Range ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 8);
              const auto Text = source(R);
              const auto Allocation =
                  Text.find(Own ? "new fixture.Core(" : "new fixture.Target(");
              ASSERT_NE(Allocation, std::string::npos);
              for (const auto &Field : {".link", ".value", ".count"}) {
                const auto Read = Text.find(Field, Allocation);
                ASSERT_NE(Read, std::string::npos);
                EXPECT_EQ(Text.find(Field, Read + 1), std::string::npos);
              }
            }
}

TEST(MobileDalvikJava,
     AllocationFieldChainsRejectClobbersAndForeignConstructors) {
  for (unsigned Mutation = 0; Mutation != 9; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = allocationFieldChainClasses("protected");
    auto &M = Input[0].methods[0];
    auto &Code = M.instructions;
    if (Mutation == 0)
      Code[1].registers[1] = 0;
    else if (Mutation == 1)
      Code[3].registers[1] = 0;
    else if (Mutation == 2)
      Code[4].registers[1] = 0;
    else if (Mutation == 3) {
      Input[1].fields[1].reference.type = "J";
      Code[4].reference = Input[1].fields[1].reference;
    } else if (Mutation == 4)
      Input[3].methods[0].access = {"private", "constructor"};
    else if (Mutation == 5) {
      Input[3].name = "Lother/Target;";
      Input[3].methods[0].reference.owner = Input[3].name;
      M.reference.returns = Input[3].name;
      Code[0].reference = Input[3].name;
      Code[5].reference = Input[3].methods[0].reference;
    } else if (Mutation == 6)
      Code[5].registers[0] = 1;
    else if (Mutation == 7)
      Code[2] = op(2, "goto", {}, {}, {}, 3);
    else {
      for (auto &Op : Code)
        ++Op.pc;
      Code.insert(Code.begin(), op(0, "if-eqz", {4}, {}, {}, 4));
      ++M.code_end;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> allocationBooleanFieldClasses(bool Leaf, bool Live,
                                                 bool Dependency, bool Range) {
  auto Input = allocationFieldChainClasses("public", Live ? (Leaf ? 1 : 2) : 0,
                                           Leaf, false, Dependency, Range);
  auto &M = Input[0].methods[0];
  auto &Field = Leaf ? Input[2].fields[0] : Input[1].fields[1];
  Field.reference.type = "Z";
  auto &Read = M.instructions[Leaf ? 3 : 4];
  Read.opcode = "iget-boolean";
  Read.reference = Field.reference;
  Input[3].methods[0].reference.parameters[Leaf ? 0 : 1] = "Z";
  M.instructions[5].reference = Input[3].methods[0].reference;
  if (Live)
    M.reference.returns = "Z";
  return Input;
}

