std::vector<Class> fieldBeforeNestedAllocationClasses(bool StaticField,
                                                      bool Chained) {
  auto Input = nestedAllocationClasses();
  auto Holder = klass("Lfixture/Holder;", {});
  FieldRef Value{Holder.name, "input", "Ljava/lang/Object;"};
  FieldRef Source{Holder.name, "holder", Holder.name};
  Holder.fields = {{Value, {"public"}, {}}, {Source, {"public", "static"}, {}}};
  if (StaticField)
    Holder.fields[0].access.insert("static");
  auto &Outer = Input[2].methods[0];
  Outer.reference.parameters = {Input[1].name};
  Outer.registers = 2;
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {Holder.name};
  Make.registers = 4;
  Make.instructions = {
      op(0, "new-instance", {0}, {}, Input[2].name),
      Chained ? op(1, "sget-object", {1}, {}, Source) : op(1, "nop"),
      op(2, StaticField ? "sget-object" : "iget-object",
         StaticField ? std::vector<unsigned>{1}
                     : std::vector<unsigned>{1, Chained ? 1u : 3u},
         {}, Value),
      op(3, "new-instance", {2}, {}, Input[1].name),
      op(4, "invoke-direct", {2, 1}, {}, Input[1].methods[0].reference),
      op(5, "invoke-direct", {0, 2}, {}, Outer.reference),
      op(6, "return-object", {0})};
  Make.code_end = 7;
  Input.push_back(std::move(Holder));
  return Input;
}

TEST(MobileDalvikJava, NestedAllocationReadsFieldsBeforeInnerInitialization) {
  for (bool StaticField : {false, true})
    for (bool Chained : {false, true})
      for (bool Reverse : {false, true})
        for (bool Linked : {false, true}) {
          auto Input = fieldBeforeNestedAllocationClasses(StaticField, Chained);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Report =
              Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          const auto Text = source(Report);
          const auto Outer = Text.find("new fixture.Outer(");
          const auto Read = Text.find(".input", Outer);
          const auto Inner = Text.find("new fixture.Inner(", Outer);
          ASSERT_NE(Outer, std::string::npos);
          ASSERT_NE(Read, std::string::npos);
          ASSERT_NE(Inner, std::string::npos);
          EXPECT_LT(Outer, Read);
          EXPECT_LT(Read, Inner);
          EXPECT_EQ(Text.find(".input", Read + 1), std::string::npos);
          if (Chained) {
            const auto First = Text.find(".holder", Outer);
            ASSERT_NE(First, std::string::npos);
            EXPECT_LT(Outer, First);
            EXPECT_LT(First, Read);
            EXPECT_EQ(Text.find(".holder", First + 1), std::string::npos);
          }
        }
}

