std::vector<Class> allocationFieldPrefixClasses(bool Cast, bool StaticField,
                                                bool StaticCall) {
  auto Input = nestedAllocationClasses();
  auto Holder = klass("Lfixture/Holder;", {});
  FieldRef Member{Holder.name, "input", Input[3].name};
  Field Declaration{Member, {"public"}, {}};
  if (StaticField)
    Declaration.access.insert("static");
  Holder.fields.push_back(Declaration);
  auto &Read = Input[3].methods[0];
  if (StaticCall) {
    Read.access.insert("static");
    Read.reference.parameters = {Input[3].name};
  }
  auto &Inner = Input[1].methods[0];
  Inner.reference.parameters = {Input[3].name};
  auto &Outer = Input[2].methods[0];
  Outer.reference.parameters = {"Ljava/lang/Object;", Input[1].name};
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {Holder.name};
  Make.registers = 5;
  auto load = [&](uint32_t PC, unsigned Result) {
    return op(PC, StaticField ? "sget-object" : "iget-object",
              StaticField ? std::vector<unsigned>{Result}
                          : std::vector<unsigned>{Result, 4},
              {}, Member);
  };
  Make.instructions = {
      op(0, "new-instance", {0}, {}, Input[2].name),
      load(1, 1),
      op(2, StaticCall ? "invoke-static" : "invoke-virtual", {1}, {},
         Read.reference),
      op(3, "move-result-object", {1}),
      Cast ? op(4, "check-cast", {1}, {}, std::string("Ljava/lang/Object;"))
           : op(4, "nop"),
      op(5, "new-instance", {2}, {}, Input[1].name),
      load(6, 3),
      op(7, "invoke-direct", {2, 3}, {}, Inner.reference),
      op(8, "invoke-direct", {0, 1, 2}, {}, Outer.reference),
      op(9, "return-object", {0})};
  Make.code_end = 10;
  Input.push_back(std::move(Holder));
  return Input;
}

