        auto Input = allocationReferenceCopyClasses(Instance);
        if (External)
          for (size_t I = 1; I < Input.size(); ++I) {
            Input[I].external = true;
            for (auto &M : Input[I].methods) {
              M.instructions.clear();
              M.registers = M.code_end = 0;
            }
          }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
