std::vector<Class> monitorRegionClasses() {
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  auto Run = method("run", {}, "V", 0, {});
  Run.reference.owner = Callback.name;
  Run.access = {"public", "abstract"};
  Callback.methods.push_back(Run);
  auto Update = method("update", {"Ljava/lang/Object;", Callback.name}, "V", 3,
                       {op(0, "monitor-enter", {1}),
                        op(1, "invoke-interface", {2}, {}, Run.reference),
                        op(2, "monitor-exit", {1}), op(3, "return-void"),
                        op(4, "move-exception", {0}),
                        op(5, "monitor-exit", {1}), op(6, "throw", {0})},
                       {{1, 6, {{std::nullopt, 4}}}});
  return {klass("Lfixture/Core;", {Update}), Callback};
}

std::vector<Class> monitorAliasClasses(unsigned CopyForm, unsigned Reuse,
                                       bool Scoped, bool Loop, bool Range) {
  auto Input = monitorRegionClasses();
  auto &M = Input[0].methods[0];
  M.reference.parameters = {"I", "Ljava/lang/Object;", "Ljava/lang/Object;",
                            Input[1].name};
  M.registers = 10;
  const auto Copy = std::array{"move-object", "move-object/from16",
                               "move-object/16"}[CopyForm];
  const auto Call = Input[1].methods[0].reference;
  const auto Invoke = Range ? "invoke-interface/range" : "invoke-interface";
  M.instructions = {
      op(0, Copy, {1, 7}),
      op(1, "monitor-enter", {1}),
      op(2, "if-eqz", {6}, {}, {}, 5),
      op(3, Copy, {3, 1}),
      op(4, "goto", {}, {}, {}, 6),
      op(5, Copy, {3, 1}),
      op(6, Copy, {4, 3}),
      op(7, "const/4", {1}, int64_t(0)),
      op(8, "check-cast", {4}, {}, std::string("Ljava/lang/Object;")),
      op(9, Invoke, {9}, {}, Call),
      Loop ? op(10, "if-gez", {6}, {}, {}, 9) : op(10, "nop"),
      op(11, "monitor-exit", {4}),
      op(12, "return-void"),
      op(13, "move-exception", {0})};
  if (Reuse == 1)
    M.instructions[7] = op(7, "const-wide/16", {0}, int64_t(0));
  else if (Reuse == 2)
    M.instructions[7] = op(7, "const-wide/16", {1}, int64_t(0));
  else if (Reuse == 3)
    M.instructions[7] = op(7, Copy, {1, 8});
  else if (Reuse == 4)
    M.instructions[7] = op(7, "const/4", {3}, int64_t(0));
  M.tries = {{2, 12, {{std::nullopt, 13}}}};
  if (Scoped) {
    M.instructions.insert(
        M.instructions.end(),
        {op(14, Invoke, {9}, {}, Call), op(15, "goto", {}, {}, {}, 18),
         op(16, "move-exception", {0}), op(17, "nop"), op(18, Copy, {3, 4}),
         op(19, "monitor-exit", {3}), op(20, "throw", {0})});
    M.tries.push_back({14, 15, {{std::nullopt, 16}}});
    M.code_end = 21;
  } else {
    M.instructions.insert(M.instructions.end(),
                          {op(14, Copy, {3, 4}), op(15, "monitor-exit", {3}),
                           op(16, "throw", {0})});
    M.code_end = 17;
  }
  return Input;
}

TEST(MobileDalvikJava, MonitorAliasesKeepAcquiredIdentityAcrossRegisterReuse) {
  for (unsigned Copy = 0; Copy < 3; ++Copy)
    for (unsigned Reuse = 0; Reuse < 5; ++Reuse)
      for (bool Scoped : {false, true})
        for (bool Loop : {false, true})
          for (bool Range : {false, true})
            for (bool External : {false, true})
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Copy, Reuse, Scoped, Loop, Range, External, Route}));
                auto Input =
                    monitorAliasClasses(Copy, Reuse, Scoped, Loop, Range);
                Input[1].external = External;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                     : recover(Input);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                const auto Text = source(R, External ? 0 : 1);
                EXPECT_NE(Text.find("synchronized (((java.lang.Object) o1))"),
                          std::string::npos);
                EXPECT_NE(
                    Text.find("case 11: pc = 12; break __neverdMonitor1;"),
                    std::string::npos);
              }
}

TEST(MobileDalvikJava, MonitorAliasesRejectDifferentObjectsAndLostMustFacts) {
  for (bool Scoped : {false, true})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Scoped, Mutation, Route}));
        auto Input = monitorAliasClasses(1, 1, Scoped, true, true);
        auto &M = Input[0].methods[0];
        const unsigned Exit = Scoped ? 19 : 15;
        if (Mutation == 0)
          M.instructions[5].registers[1] = 8;
        else if (Mutation == 1)
          M.instructions[11].registers = {8};
        else if (Mutation == 2)
          M.instructions[Exit].registers = {8};
        else if (Mutation == 3)
          M.instructions[6].registers[1] = 8;
        else if (Mutation == 4)
          M.instructions[8] = op(8, "move-object", {4, 8});
        else if (Mutation == 5)
          M.instructions[8] = op(8, "const-wide/16", {3}, int64_t(0));
        else if (Mutation == 6)
          M.instructions[8] = op(8, "const-wide/16", {4}, int64_t(0));
        else if (Mutation == 7) {
          auto Get = Input[1].methods[0];
          Get.reference.name = "get";
          Get.reference.returns = "Ljava/lang/Object;";
          Input[1].methods.push_back(Get);
          M.instructions[9].reference = Get.reference;
          M.instructions[10] = op(10, "move-result-object", {4});
        } else if (Mutation == 8) {
          auto Provider = klass("Lfixture/Provider;");
          const FieldRef Value{Provider.name, "value", "Ljava/lang/Object;"};
          Provider.fields.push_back({Value, {"public", "static"}, {}});
          M.instructions[8] = op(8, "sget-object", {4}, {}, Value);
          Input.push_back(Provider);
        } else if (Mutation == 9) {
          M.instructions[13].registers = {4};
          M.instructions.back().registers = {4};
        } else if (Mutation == 10)
          M.instructions[11].registers = {1};
        else if (Mutation == 11)
          M.instructions[1].registers = {8};
        else if (Mutation == 12)
          M.instructions[5] = op(5, "nop");
        else if (Mutation == 13)
          M.instructions[10] = op(10, "goto", {}, {}, {}, 13);
        else if (Mutation == 14)
          M.tries.clear();
        else if (Mutation == 15)
          M.instructions[1].literal = int64_t(0);
        else if (Mutation == 16)
          M.instructions[11].reference = std::string("Ljava/lang/Object;");
        else if (Mutation == 17)
          M.instructions[Exit].targets = {12};
        else if (Mutation == 18)
          M.instructions[8] = op(8, "const/4", {4}, int64_t(0));
        else
          M.instructions[5] = op(5, "move-object", {3, 4});
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

