std::vector<Class>
sequentialMonitorClasses(bool SameLock, bool MultipleReleases, bool Bypass) {
  auto Input = monitorRegionClasses();
  auto &M = Input[0].methods[0];
  M.reference.parameters = {"I", "Ljava/lang/Object;", "Ljava/lang/Object;",
                            Input[1].name};
  M.registers = 5;
  const unsigned Second = SameLock ? 2 : 3;
  const auto Call = Input[1].methods[0].reference;
  M.instructions = {
      Bypass ? op(0, "if-ltz", {1}, {}, {}, 14) : op(0, "nop"),
      op(1, "monitor-enter", {2}),
      MultipleReleases ? op(2, "if-eqz", {1}, {}, {}, 6) : op(2, "nop"),
      op(3, "invoke-interface", {4}, {}, Call),
      op(4, "monitor-exit", {2}),
      MultipleReleases ? op(5, "return-void") : op(5, "goto", {}, {}, {}, 8),
      op(6, "invoke-interface", {4}, {}, Call),
      op(7, "monitor-exit", {2}),
      op(8, "invoke-interface", {4}, {}, Call),
      Bypass ? op(9, "if-eqz", {1}, {}, {}, 13) : op(9, "nop"),
      op(10, "monitor-enter", {Second}),
      op(11, "invoke-interface", {4}, {}, Call),
      op(12, "monitor-exit", {Second}),
      op(13, "invoke-interface", {4}, {}, Call),
      op(14, "return-void"),
      op(15, "move-exception", {0}),
      op(16, "monitor-exit", {Second}),
      op(17, "throw", {0}),
      op(18, "move-exception", {0}),
      op(19, "monitor-exit", {2}),
      op(20, "throw", {0})};
  // Keep the second first-region exit reachable even without an early return.
  if (!MultipleReleases)
    M.instructions[2] = op(2, "if-eqz", {1}, {}, {}, 6);
  M.code_end = 21;
  M.tries = {{2, 8, {{std::nullopt, 18}}}, {11, 13, {{std::nullopt, 15}}}};
  return Input;
}

TEST(MobileDalvikJava,
     SequentialMonitorsKeepIndependentCleanupAndUnlockedTails) {
  for (bool SameLock : {false, true})
    for (bool MultipleReleases : {false, true})
      for (bool Bypass : {false, true})
        for (unsigned Route = 0; Route < 3; ++Route) {
          auto Input =
              sequentialMonitorClasses(SameLock, MultipleReleases, Bypass);
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          std::string Text;
          for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
            if (source(R, I).find("__neverdMonitor1") != std::string::npos)
              Text = source(R, I);
          EXPECT_NE(Text.find("__neverdMonitor10"), std::string::npos);
          EXPECT_EQ(Text.find("caught = failure"), std::string::npos);
        }
}

TEST(MobileDalvikJava, SequentialMonitorsRejectUnprovedOwnershipAndEntries) {
  for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = sequentialMonitorClasses(false, true, true);
    auto &M = Input[0].methods[0];
    auto &C = M.instructions;
    if (Mutation == 0)
      C[11] = op(11, "move-object", {3, 2});
    else if (Mutation == 1)
      C[11] = op(11, "const-wide/16", {2}, int64_t(0));
    else if (Mutation == 2)
      C[12].registers = {2};
    else if (Mutation == 3)
      C[16].registers = {2};
    else if (Mutation == 4)
      M.tries[1].handlers[0].target = 18;
    else if (Mutation == 5)
      C[8] = op(8, "goto", {}, {}, {}, 11);
    else if (Mutation == 6)
      C[7] = op(7, "goto", {}, {}, {}, 10);
    else if (Mutation == 7)
      M.tries[1].start = 10;
    else if (Mutation == 8)
      M.tries[1].start = 12;
    else if (Mutation == 9)
      C[11] = op(11, "return-void");
    else if (Mutation == 10)
      C[6] = op(6, "monitor-enter", {3});
    else if (Mutation == 11)
      C[9] = op(9, "monitor-exit", {2});
    else if (Mutation == 12)
      C[17].registers = {4};
    else
      M.tries[1].handlers[0].type = "Ljava/lang/Throwable;";
    Budget B;
    rejected([&] { recoverJava(linkClasses(Input, B), B); }, "monitor");
  }
}

