std::vector<Class>
monitorArithmeticGapClasses(std::vector<Instruction> Preparation) {
  auto Input = monitorRegionClasses();
  auto &M = Input[0].methods[0];
  M.reference.parameters = {"Ljava/lang/Object;",
                            Input[1].name,
                            "I",
                            "I",
                            "J",
                            "J",
                            "F",
                            "F",
                            "D",
                            "D"};
  M.registers = 24;
  std::vector<Instruction> Code{op(0, "monitor-enter", {10})};
  for (auto I : Preparation) {
    I.pc = Code.size();
    Code.push_back(std::move(I));
  }
  const uint32_t Call = Code.size();
  Code.push_back(
      op(Call, "invoke-interface", {11}, {}, Input[1].methods[0].reference));
  Code.push_back(op(Call + 1, "monitor-exit", {10}));
  Code.push_back(op(Call + 2, "return-void"));
  Code.push_back(op(Call + 3, "move-exception", {9}));
  Code.push_back(op(Call + 4, "monitor-exit", {10}));
  Code.push_back(op(Call + 5, "throw", {9}));
  M.instructions = std::move(Code);
  M.code_end = M.instructions.size();
  M.tries = {{Call, Call + 1, {{std::nullopt, Call + 3}}}};
  return Input;
}

TEST(MobileDalvikJava, MonitorTotalOperationsShareOrdinaryExceptionSemantics) {
  std::vector<std::vector<Instruction>> Cases;
  for (const std::string Type : {"int", "long", "float", "double"}) {
    const unsigned First = Type == "int"     ? 12
                           : Type == "long"  ? 14
                           : Type == "float" ? 18
                                             : 20;
    const unsigned Second =
        First + (Type == "long" || Type == "double" ? 2 : 1);
    const std::string Move =
        Type == "long" || Type == "double" ? "move-wide" : "move";
    for (const std::string Name : {"add", "sub", "mul"}) {
      Cases.push_back({op(0, Name + "-" + Type, {0, First, Second})});
      Cases.push_back({op(0, Move, {0, First}),
                       op(1, Name + "-" + Type + "/2addr", {0, Second})});
    }
    Cases.push_back({op(0, "neg-" + Type, {0, First})});
    if (Type == "float" || Type == "double")
      for (const std::string Name : {"div", "rem"}) {
        Cases.push_back({op(0, Name + "-" + Type, {0, First, Second})});
        Cases.push_back({op(0, Move, {0, First}),
                         op(1, Name + "-" + Type + "/2addr", {0, Second})});
      }
    else {
      Cases.push_back({op(0, "not-" + Type, {0, First})});
      for (const std::string Name :
           {"and", "or", "xor", "shl", "shr", "ushr"}) {
        const unsigned Right =
            Name.ends_with("hr") || Name == "shl" ? 13 : Second;
        Cases.push_back({op(0, Name + "-" + Type, {0, First, Right})});
        Cases.push_back({op(0, Move, {0, First}),
                         op(1, Name + "-" + Type + "/2addr", {0, Right})});
      }
    }
  }
  for (const auto Name : {"add-int/lit8", "add-int/lit16", "xor-int/lit8",
                          "xor-int/lit16", "rsub-int/lit8"})
    Cases.push_back({op(0, Name, {0, 12}, int64_t(-7))});
  for (const std::string Name :
       {"cmp-long", "cmpl-float", "cmpg-float", "cmpl-double", "cmpg-double"}) {
    const unsigned First = Name.ends_with("long")    ? 14
                           : Name.ends_with("float") ? 18
                                                     : 20;
    Cases.push_back({op(0, Name, {0, First, First + (First == 18 ? 1u : 2u)})});
  }
  for (const auto Name : {"int-to-byte", "int-to-short", "int-to-char",
                          "int-to-long", "int-to-float", "int-to-double"})
    Cases.push_back({op(0, Name, {0, 12})});
  for (const auto &Preparation : Cases)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(Preparation.back().opcode);
      SCOPED_TRACE(Route);
      auto Input = monitorArithmeticGapClasses(Preparation);
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto R =
          Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      const auto Text = source(R, 1);
      for (size_t I = 0; I < Preparation.size(); ++I)
        EXPECT_NE(Text.find("case " + std::to_string(I + 1) + ":"),
                  std::string::npos);
    }
  for (const std::string Type : {"I", "J", "D", "Ljava/lang/Object;"}) {
    auto Input = monitorArithmeticGapClasses({op(0, "nop")});
    auto Value = method("value", {}, Type, 0, {});
    Value.access = {"public", "abstract"};
    Value.reference.owner = Input[1].name;
    Input[1].methods.push_back(Value);
    auto &M = Input[0].methods[0];
    M.instructions[1] = op(1, "invoke-interface", {11}, {}, Value.reference);
    M.instructions.insert(M.instructions.begin() + 2,
                          op(2,
                             Type == "J" || Type == "D" ? "move-result-wide"
                             : Type.starts_with('L')    ? "move-result-object"
                                                        : "move-result",
                             {0}));
    for (size_t I = 3; I < M.instructions.size(); ++I)
      ++M.instructions[I].pc;
    ++M.code_end;
    M.tries = {{1, 2, {{std::nullopt, 6}}}, {3, 4, {{std::nullopt, 6}}}};
    Budget B;
    EXPECT_EQ(recoverJava(linkClasses(Input, B), B)
                  .getInteger("unrecovered_method_count"),
              0);
  }
}

TEST(MobileDalvikJava, RegisterCopyEncodingIsCheckedWithoutMonitorContext) {
  for (const auto &Kind : {"move", "move-object", "move-wide"})
    for (const auto &Suffix : {"", "/from16", "/16"})
      for (bool Linked : {false, true}) {
        const std::string Type = std::string(Kind) == "move-object"
                                     ? "Ljava/lang/Object;"
                                 : std::string(Kind) == "move-wide" ? "J"
                                                                    : "I";
        const std::string Return =
            std::string(Kind) == "move-object" ? "return-object"
            : std::string(Kind) == "move-wide" ? "return-wide"
                                               : "return";
        auto Input = std::vector<Class>{
            klass("Lfixture/Core;",
                  {method("copy", {Type}, Type, Type == "J" ? 4 : 3,
                          {op(0, std::string(Kind) + Suffix, {0, 2}),
                           op(1, Return, {0})})})};
        auto run = [&](std::vector<Class> Classes) {
          Budget B;
          return Linked ? recoverJava(linkClasses(std::move(Classes), B), B)
                        : recover(std::move(Classes));
        };
        EXPECT_EQ(run(Input).getInteger("unrecovered_method_count"), 0);
        for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Kind, Suffix, Linked, Mutation}));
          auto Changed = Input;
          auto &Copy = Changed[0].methods[0].instructions[0];
          if (Mutation == 0)
            Copy.opcode = std::string(Kind) + "/unknown";
          else if (Mutation == 1)
            Copy.literal = int64_t(0);
          else if (Mutation == 2)
            Copy.reference = std::string("Ljava/lang/Object;");
          else if (Mutation == 3)
            Copy.target = 0;
          else if (Mutation == 4)
            Copy.targets = {1};
          else if (Mutation == 5)
            Copy.keys = {0};
          else if (Mutation == 6)
            Copy.data = {0};
          else if (Mutation == 7)
            Copy.element_width = 1;
          else if (Mutation == 8)
            Copy.registers.pop_back();
          else
            Copy.registers.push_back(0);
          EXPECT_THROW(run(std::move(Changed)), std::runtime_error);
        }
      }
}

TEST(MobileDalvikJava,
     MonitorExceptionClassificationKeepsThrowingAndInvalidGaps) {
  std::vector<Instruction> Throwing{
      op(0, "div-int", {0, 12, 13}),
      op(0, "rem-int", {0, 12, 13}),
      op(0, "div-long", {0, 14, 16}),
      op(0, "rem-long", {0, 14, 16}),
      op(0, "const-string", {0}, std::string("owned constant")),
      op(0, "const-class", {0}, {}, std::string("Ljava/lang/String;")),
      op(0, "instance-of", {0, 10}, {}, std::string("Ljava/lang/String;"))};
  // ART also marks INSTANCE_OF as kThrow: resolving its type may fail.
  // https://android.googlesource.com/platform/art/+/da1cdd0/runtime/dex/dex_instruction_list.h
  for (const auto &Gap : Throwing)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(Gap.opcode);
      SCOPED_TRACE(Route);
      auto Input = monitorArithmeticGapClasses({Gap});
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      rejected(
          [&] {
            if (Route)
              recoverJava(linkClasses(Input, B), B);
            else
              recover(Input);
          },
          "monitor");
    }
  for (unsigned Mutation = 0; Mutation < 3; ++Mutation) {
    auto Gap = op(0, "move-object", {0, 10});
    if (Mutation == 0)
      Gap.literal = int64_t(0);
    else if (Mutation == 1)
      Gap.reference = std::string("Ljava/lang/Object;");
    else
      Gap.target = 0;
    EXPECT_THROW(recover(monitorArithmeticGapClasses({Gap})),
                 std::runtime_error);
  }
  rejected(
      [&] {
        recover(monitorArithmeticGapClasses({op(0, "unsupported-owned-gap")}));
      },
      "unsupported");
}

