TEST(MobileDalvikJava,
     MonitorContinuationKeepsConditionalCallbacksOutsideLock) {
  for (unsigned Route = 0; Route < 3; ++Route) {
    auto Input = monitorContinuationClasses();
    if (Route == 2)
      std::reverse(Input.begin(), Input.end());
    Budget B;
    const auto R =
        Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    const auto Text = source(R, 1);
    EXPECT_NE(Text.find("synchronized (((java.lang.Object) o2))"),
              std::string::npos);
    const auto Exit = Text.find("case 3: pc = 4; break __neverdMonitor0;");
    ASSERT_NE(Exit, std::string::npos);
    const auto Continue = Text.find("pc = 4;", Exit);
    ASSERT_NE(Continue, std::string::npos);
    const auto Callback = Text.find("case 6:", Continue);
    ASSERT_NE(Callback, std::string::npos);
    EXPECT_GT(Callback, Continue);
    EXPECT_EQ(Text.find("caught = failure; pc = 9"), std::string::npos);
  }
}

