TEST(MobileDalvikJava, MonitorContinuationsRetainOrdinaryUnlockedCycles) {
  for (unsigned Shape = 0; Shape < 4; ++Shape)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(Shape);
      SCOPED_TRACE(Route);
      auto Input = monitorContinuationClasses();
      auto &M = Input[0].methods[0];
      if (Shape < 3) {
        M.instructions[5].target = Shape == 0 ? 4 : 5;
        if (Shape == 2)
          M.instructions[7] = op(7, "if-eqz", {3}, {}, {}, 4);
      } else {
        for (auto &I : M.instructions) {
          ++I.pc;
          if (I.target)
            ++*I.target;
        }
        M.instructions.insert(M.instructions.begin(),
                              op(0, "if-eqz", {3}, {}, {}, 0));
        ++M.code_end;
        for (auto &T : M.tries) {
          ++T.start;
          ++T.end;
          for (auto &H : T.handlers)
            ++H.target;
        }
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto R =
          Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      const auto Text = source(R, 1);
      EXPECT_NE(Text.find("synchronized"), std::string::npos);
      EXPECT_NE(Text.find(Shape == 3   ? "? 0 : 1"
                          : Shape == 0 ? "? 4 : 6"
                                       : "? 5 : 6"),
                std::string::npos);
    }
}

