TEST(MobileDalvikJava, MonitorCleanupPrecedesSharedUnlockedContinuation) {
  for (unsigned Route = 0; Route < 3; ++Route)
    for (unsigned Suffix = 0; Suffix < 3; ++Suffix)
      for (bool Dependency : {false, true}) {
        SCOPED_TRACE(Route);
        SCOPED_TRACE(Suffix);
        SCOPED_TRACE(Dependency);
        auto Input = monitorSharedContinuationClasses();
        auto &M = Input[0].methods[0];
        if (Suffix == 1) {
          M.instructions.back() =
              op(8, "invoke-interface", {2}, {}, Input[1].methods[0].reference);
          M.instructions.push_back(op(9, "return-void"));
          M.code_end = 10;
        } else if (Suffix == 2) {
          M.instructions.back() = op(8, "const/4", {1}, int64_t(0));
          M.instructions.push_back(op(9, "if-eqz", {1}, {}, {}, 11));
          M.instructions.push_back(op(10, "invoke-interface", {2}, {},
                                      Input[1].methods[0].reference));
          M.instructions.push_back(op(11, "return-void"));
          M.code_end = 12;
        }
        Input[1].external = Dependency;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        const auto Text = source(R, Dependency ? 0 : 1);
        EXPECT_NE(Text.find("case 3: pc = 4; break __neverdMonitor1;"),
                  std::string::npos);
        EXPECT_NE(Text.find("case 8:"), std::string::npos);
        EXPECT_EQ(Text.find("case 5:"), std::string::npos);
        EXPECT_EQ(Text.find("caught = failure; pc = 5"), std::string::npos);
      }
}

