std::vector<Class> discardedAllocationCallClasses(const std::string &Type,
                                                  bool Static, bool Range) {
  auto Input = nestedAllocationClasses();
  const bool Wide = Type == "J" || Type == "D";
  const bool Reference = Type.starts_with('L');
  auto Before =
      method("before", {}, Type, Wide ? 3 : 2,
             {op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
              op(1,
                 Reference ? "return-object"
                 : Wide    ? "return-wide"
                           : "return",
                 {0})});
  Before.reference.owner = Input[3].name;
  Before.access = Static ? std::set<std::string>{"public", "static"}
                         : std::set<std::string>{"public"};
  Input[3].methods.push_back(Before);
  Input[0].methods[0] =
      method("make", {Input[3].name}, Input[1].name, 2,
             {op(0, "new-instance", {0}, {}, Input[1].name),
              op(1,
                 std::string(Static ? "invoke-static" : "invoke-virtual") +
                     (Range ? "/range" : ""),
                 Static ? std::vector<unsigned>{} : std::vector<unsigned>{1},
                 {}, Before.reference),
              op(2, "invoke-direct", {0, 1}, {}, Input[1].methods[0].reference),
              op(3, "return-object", {0})});
  return Input;
}

TEST(MobileDalvikJava, AllocationCallsRetainDiscardedDeclaredResults) {
  for (const std::string Type :
       {"Ljava/lang/Object;", "Z", "B", "C", "S", "I", "F", "J", "D"})
    for (bool Static : {false, true})
      for (bool Range : {false, true})
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(Type);
          SCOPED_TRACE(Static);
          SCOPED_TRACE(Range);
          auto Input = discardedAllocationCallClasses(Type, Static, Range);
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Report =
              Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(Report.getInteger("minimum_java_release"), 14);
          const auto Text = source(Report);
          const auto New = Text.find("new fixture.Inner(");
          const auto Call = Text.find(".before(");
          ASSERT_NE(New, std::string::npos);
          ASSERT_NE(Call, std::string::npos);
          EXPECT_LT(New, Call);
          EXPECT_EQ(Text.find(".before(", Call + 1), std::string::npos);
          EXPECT_NE(Text.find(".before();"), std::string::npos);
        }
}

TEST(MobileDalvikJava, DiscardedAllocationCallsKeepResultAndEntryGuards) {
  for (bool Static : {false, true})
    for (unsigned Mutation = 0; Mutation < 4; ++Mutation) {
      SCOPED_TRACE(Static);
      SCOPED_TRACE(Mutation);
      auto Input =
          discardedAllocationCallClasses("Ljava/lang/Object;", Static, false);
      auto &Make = Input[0].methods[0];
      auto &Code = Make.instructions;
      if (Mutation == 0)
        Code.insert(Code.begin() + 2, op(0, "move-result-wide", {1}));
      else if (Mutation == 1)
        Code.insert(Code.begin() + 2, op(0, "move-result-object", {}));
      else if (Mutation == 2)
        Code.insert(Code.begin(), op(0, "if-eqz", {1}, {}, {}, 2));
      else {
        Code.insert(Code.begin() + 2, op(0, "nop"));
        Code.insert(Code.begin() + 3, op(0, "move-result-object", {1}));
      }
      for (size_t I = 0; I < Code.size(); ++I)
        Code[I].pc = I;
      Make.code_end = Code.size();
      rejected([&] { recover(Input); }, Mutation == 0 || Mutation == 3
                                            ? "move-result"
                                        : Mutation == 2 ? "nested allocation"
                                                        : "adjacent");
    }
}

