TEST(MobileDalvikJava, AllocationRejectsChangedFieldReceiversAndReadOrder) {
  for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = allocationInstanceReadClasses();
    auto &Make = Input[2].methods[0];
    auto &Code = Make.instructions;
    auto Target = Input[0].methods[0].reference;
    std::string Error = "exactly once in their original order";
    if (Mutation == 0) {
      Target.parameters = {"J", "I"};
      Code[3] = op(3, "invoke-direct", {0, 2, 3, 1}, {}, Target);
    } else if (Mutation == 1) {
      Target.parameters = {"I", "I", "J"};
      // Shared reads are legal; this frame still names an undeclared overload.
      Error = "referenced member has no proven local declaration";
      Code[3] = op(3, "invoke-direct", {0, 1, 1, 2, 3}, {}, Target);
    } else if (Mutation == 2) {
      Target.parameters = {"I"};
      // Shared reads are legal; this frame still names an undeclared overload.
      Error = "referenced member has no proven local declaration";
      Code[3] = op(3, "invoke-direct", {0, 1}, {}, Target);
    } else if (Mutation == 3 || Mutation == 4) {
      Code[2] = Mutation == 3 ? op(2, "const/4", {4}, int64_t(0))
                              : op(2, "const-wide/16", {3}, int64_t(0));
      Error = "field-read receiver cannot be overwritten";
    } else if (Mutation == 5) {
      Code[1].registers[0] = 4;
      Error = "undefined or incompatible register v4 for Lfixture/Owner;";
    } else {
      Code[2].registers[1] = 1;
      Error = "undefined or incompatible register v1 for Lfixture/Owner;";
    }
    rejected([&] { recover(Input); }, Error);
  }
}

std::vector<Class> scalarFieldCopyAllocationClasses(const std::string &Type,
                                                    bool Static, bool External,
                                                    bool Range, bool Chained) {
  const bool Wide = Type == "J" || Type == "D";
  const unsigned Second = Wide ? 3 : 2;
  auto Init = method("<init>", {Type, Type}, "V", Wide ? 5 : 3,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = klass("Lfixture/Target;", {Init});
  Target.external = External;
  if (External)
    Target.methods[0].instructions.clear();
  auto Owner = klass("Lfixture/Owner;");
  Owner.external = External;
  const FieldRef Field{Owner.name, "value", Type};
  Access FieldAccess{"public", "volatile"};
  if (Static)
    FieldAccess.insert("static");
  Owner.fields = {{Field, FieldAccess}};
  const auto Suffix = Type == "Z"   ? "-boolean"
                      : Type == "B" ? "-byte"
                      : Type == "C" ? "-char"
                      : Type == "S" ? "-short"
                      : Wide        ? "-wide"
                                    : "";
  std::vector<Instruction> Code{
      op(0, "new-instance", {0}, {}, Target.name),
      op(1, std::string(Static ? "sget" : "iget") + Suffix,
         Static ? std::vector<unsigned>{1} : std::vector<unsigned>{1, 8}, {},
         Field),
      op(2, Wide ? "move-wide/from16" : "move/from16",
         {Chained ? 5u : Second, 1})};
  if (Chained)
    Code.push_back(op(3, Wide ? "move-wide/16" : "move/16", {Second, 5}));
  std::vector<unsigned> Words = Wide ? std::vector<unsigned>{0, 1, 2, 3, 4}
                                     : std::vector<unsigned>{0, 1, 2};
  Code.push_back(op(Code.size(),
                    Range ? "invoke-direct/range" : "invoke-direct", Words, {},
                    Target.methods[0].reference));
  Code.push_back(op(Code.size(), Wide ? "return-wide" : "return", {Second}));
  auto Make = method("make",
                     Static ? std::vector<std::string>{}
                            : std::vector<std::string>{Owner.name},
                     Type, 9, Code);
  Make.access = {"public", "static"};
  return {Target, Owner, klass("Lfixture/Core;", {Make})};
}

TEST(MobileDalvikJava, ScalarFieldCopiesSelectTheSharedAllocationValueGraph) {
  for (const auto &Type : {"Z", "B", "C", "S", "I", "F", "J", "D"})
    for (bool Static : {false, true})
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (bool Chained : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(Type);
              auto Input = scalarFieldCopyAllocationClasses(
                  Type, Static, External, Range, Chained);
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              const auto R = recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              const auto Text = source(R, 0);
              EXPECT_NE(Text.find("new fixture.Target("), std::string::npos);
              const auto Read = Text.find(".value");
              ASSERT_NE(Read, std::string::npos);
              EXPECT_EQ(Text.find(".value", Read + 1), std::string::npos);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
            }
}

TEST(MobileDalvikJava, ScalarFieldCopiesKeepOriginalWordAndEffectValidation) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        scalarFieldCopyAllocationClasses("J", false, false, true, false);
    auto &Make = Input[2].methods[0];
    auto &Code = Make.instructions;
    if (Mutation == 0)
      Code[2].opcode = "move-object/from16";
    else if (Mutation == 1)
      Code[3].registers[2] = 4;
    else if (Mutation == 2)
      Code[2].registers[1] = 2;
    else if (Mutation == 3)
      Code[2].registers[0] = 0;
    else if (Mutation == 4)
      Code[1].registers[1] = 0;
    else if (Mutation == 5)
      std::get<FieldRef>(Code[1].reference).name = "missing";
    else if (Mutation == 6)
      Code[1].opcode = "sget-wide";
    else if (Mutation == 7)
      Input[0].methods[0].access = {"private", "constructor"};
    else if (Mutation == 8)
      Code[2].registers.push_back(4);
    else if (Mutation == 9)
      Code[2].opcode = "move/from16";
    else if (Mutation == 10)
      Code.insert(Code.begin() + 3, op(0, "const/4", {4}, int64_t(1)));
    else {
      Code.insert(Code.begin() + 3, op(0, "if-eqz", {8}, {}, {}, 4));
    }
    for (size_t I = 0; I < Code.size(); ++I)
      Code[I].pc = I;
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

std::vector<Class> receiverTransferAllocationClasses(const std::string &Type,
                                                     bool External,
                                                     bool Range) {
  const unsigned Width = Type == "J" || Type == "D" ? 2 : 1;
  auto Init = method("<init>", {Type, "Z"}, "V", Width + 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  if (External) {
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  auto Target = klass("Lfixture/Target;", {Init});
  Target.external = External;
  auto Owner = klass("Lfixture/Owner;");
  Owner.external = External;
  const FieldRef Flag{Owner.name, "flag", "Z"};
  Owner.fields.push_back({Flag, {"public", "volatile"}, {}});
  const unsigned Read = Width + 1, Receiver = Read + 1, Input = Receiver + 1;
  std::vector<unsigned> Arguments{0, 1};
  if (Width == 2)
    Arguments.push_back(2);
  Arguments.push_back(Read);
  auto Make = method("make", {Owner.name, Type}, Target.name, Input + Width,
                     {op(0, "new-instance", {0}, {}, Target.name),
                      op(1, "move-object/from16", {1, Receiver}),
                      op(2, "iget-boolean", {Read, 1}, {}, Flag),
                      op(3,
                         Type == "Ljava/lang/Object;" ? "move-object/from16"
                         : Width == 2                 ? "move-wide/from16"
                                                      : "move/from16",
                         {1, Input}),
                      op(4, Range ? "invoke-direct/range" : "invoke-direct",
                         Arguments, {}, Target.methods[0].reference),
                      op(5, "return-object", {0})});
  return {Target, Owner, klass("Lfixture/Core;", {Make})};
}

TEST(MobileDalvikJava, AllocationReceiverTransfersUseTheSharedValueGraph) {
  for (const auto &Type : {"Z", "I", "J", "F", "D", "Ljava/lang/Object;"})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Type, External, Range, Reverse}));
          auto Input = receiverTransferAllocationClasses(Type, External, Range);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R = recoverJava(linkClasses(Input, B), B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          std::string Text;
          for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
            Text += source(R, I);
          EXPECT_NE(Text.find("new fixture.Target("), std::string::npos);
          const auto Read = Text.find(".flag");
          ASSERT_NE(Read, std::string::npos);
          EXPECT_EQ(Text.find(".flag", Read + 1), std::string::npos);
        }
}

TEST(MobileDalvikJava, AllocationReceiverTransfersKeepTypedWordsAndEffects) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = receiverTransferAllocationClasses("I", false, true);
    auto &Make = Input[2].methods[0];
    auto &Code = Make.instructions;
    switch (Mutation) {
    case 0:
      Code[3].opcode = "move-object/from16";
      break;
    case 1:
      std::get<MethodRef>(Code[4].reference).parameters[0] = "J";
      break;
    case 2:
      Code[3].registers[0] = 0;
      break;
    case 3:
      Code[2].registers[1] = 0;
      break;
    case 4:
      std::get<FieldRef>(Code[2].reference).name = "missing";
      break;
    case 5:
      Code[2].opcode = "sget-boolean";
      break;
    case 6:
      Input[0].methods[0].access = {"private", "constructor"};
      break;
    case 7:
      Code[3].registers.pop_back();
      break;
    case 8:
      Code[3].registers[0] = Make.registers;
      break;
    case 9:
      Code[3].registers[1] = 0;
      break;
    case 10:
      Code[4].registers.pop_back();
      break;
    case 11:
      Input[1].fields[0].access.insert("static");
      break;
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

TEST(MobileDalvikJava, ConstructorLocalDeclarationsFollowParentInitialization) {
  auto Input = constructorPrologueClasses();
  auto &C = Input[1];
  C.access = {"final"};
  C.inner_access = {"final"};
  C.inner_class_present = true;
  auto Init =
      method("<init>", {"I"}, "V", 3,
             {op(0, "invoke-direct", {1}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "new-instance", {0}, {}, C.name),
              op(2, "invoke-direct", {0, 2}, {}, C.methods[0].reference),
              op(3, "return-void")});
  Init.access = {"public", "constructor"};
  auto Host = klass("Lfixture/Host;", {Init});
  C.enclosing_method = Host.methods[0].reference;
  Input.push_back(std::move(Host));
  auto R = recover(Input);
  auto S = source(R, 1);
  EXPECT_LT(S.find("super();"), S.find("class __neverdLocal1"));
  EXPECT_LT(S.find("class __neverdLocal1"), S.find("new __neverdLocal1(v2)"));
  const auto *Binding =
      R.getArray("class_source_bindings")->front().getAsObject();
  EXPECT_EQ(Binding->getString("enclosing_kind"), "constructor");
  EXPECT_EQ(R.getInteger("projected_method_count"), 2);
}

