  Ctor.instructions[2] = op(2, "invoke-direct", {0}, {},
                            MethodRef{"Lfixture/Token;", "<init>", {}, "V"});
  auto TokenCtor =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
