TEST(
    MobileDalvikJava,
    AllocatedTokenConstructorTransfersRejectLostTypesClobbersAndReceiverLeaks) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation != 20; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input = allocatedTokenConstructorTransferClasses(
          SDK, false, Mutation >= 16, false);
      auto &Transfer = Input.back();
      auto &Init = Transfer.methods[0];
      auto &Map = Transfer.methods[1];
      auto &Caller = Input[0].methods[1];
      if (Mutation == 0)
        Transfer.generic_signature = "<X:Lfixture/Bound;>Ljava/lang/Object;";
      else if (Mutation == 1)
        Map.generic_signature = "()Lfixture/Output<*>;";
      else if (Mutation == 2)
        Map.generic_signature = "()Lfixture/Output<+TX;>;";
      else if (Mutation == 3)
        Map.generic_signature = "()Lfixture/Output<TMissing;>;";
      else if (Mutation == 4)
        Init.generic_signature = "(Lfixture/Input<+TX;>;)V";
      else if (Mutation == 5)
        Init.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 6)
        Map.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 7)
        Init.generic_signature.reset();
      else if (Mutation == 8)
        Map.generic_signature.reset();
      else if (Mutation == 9)
        Transfer.access.erase("final");
      else if (Mutation == 10)
        Map.access.insert("static");
      else if (Mutation == 11)
        Map.access = {"private"};
      else if (Mutation == 12)
        Caller.instructions[10].registers[1] = 2;
      else if (Mutation == 13)
        Caller.instructions[7].registers[0] = 3;
      else if (Mutation == 14)
        Caller.instructions[5].registers[1] = 3;
      else if (Mutation == 15)
        Caller.instructions[6].registers[0] = 4;
      else if (Mutation == 16)
        Input.erase(Input.end() - 2);
      else if (Mutation == 17)
        Input[Input.size() - 2].generic_signature =
            "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 18)
        Input[Input.size() - 2].interfaces = {"Lfixture/Missing;"};
      else
        Input[Input.size() - 2].access = {"private", "interface", "abstract"};
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

