TEST(MobileDalvikJava,
     TypedTokenConstructorTransfersRejectLostRelationsAndReceiverLeaks) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input =
          typedTokenConstructorTransferClasses(SDK, true, true, false, false);
      auto &Map = Input[1].methods[0];
      auto &Caller = Input[0].methods[1];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Map.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("Output<TX;>", "Output<*>");
      else if (Mutation == 1)
        replace("Input<TX;>", "Input<+TX;>");
      else if (Mutation == 2)
        replace("Output<TX;>", "Output<+TX;>");
      else if (Mutation == 3) {
        replace("X:Ljava/lang/Object;>",
                "X:Ljava/lang/Object;Y:Ljava/lang/Object;>");
        replace("Output<TX;>", "Output<TY;>");
      } else if (Mutation == 4)
        replace("X:Ljava/lang/Object;>", "X:Lfixture/Bound;>");
      else if (Mutation == 5)
        replace("Output<TX;>", "Output");
      else if (Mutation == 6)
        Map.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 7) {
        Input[0].generic_signature =
            "<T:Lfixture/Bound;U:Lfixture/Bound;>Ljava/lang/Object;";
        auto &Signature = *Input[0].methods[0].generic_signature;
        const auto At = Signature.find("Output<TT;>");
        Signature.replace(At, std::string("Output<TT;>").size(), "Output<TU;>");
      } else if (Mutation == 8)
        Caller.instructions[4].registers = {5};
      else if (Mutation == 9)
        Caller.instructions[5].opcode = "move-result";
      else if (Mutation == 10)
        Caller.instructions[1].registers[0] = 3;
      else if (Mutation == 11)
        Caller.instructions[4].opcode = "invoke-virtual";
      else if (Mutation == 12)
        Caller.instructions[8].registers.pop_back();
      else if (Mutation == 13)
        Map.access = {"private", "static"};
      else if (Mutation == 14)
        Input[2].generic_signature = "<E:Lfixture/Bound;>Ljava/lang/Object;";
      else
        Map.generic_signature.reset();
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> closedCovariantDelegationClasses(bool SDK, bool Range,
                                                    bool Member, bool Alias) {
  const std::string Name = Member ? "Lfixture/Outer$Core;" : "Lfixture/Core;";
  auto Target = method("<init>", {"Ljava/lang/String;"}, "V", 2,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
  Target.reference.owner = Name;
  Target.access = {"public", "constructor"};
  auto Key =
      method("key", {"Lfixture/Carrier;"}, "Ljava/lang/String;", 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  auto Names = klass("Lfixture/Names;", {Key});
  auto Caller = method("<init>", {"Lfixture/Carrier;"}, "V", 5, {});
  Caller.access = Target.access;
  Caller.generic_signature = "(Lfixture/Carrier<+Lfixture/Bound;>;)V";
  Caller.instructions.push_back(op(0, "move-object", {0, 3}));
  if (Alias)
    Caller.instructions.push_back(op(1, "move-object", {2, 4}));
  auto PC = static_cast<uint32_t>(Caller.instructions.size());
  Caller.instructions.push_back(
      op(PC++, Range ? "invoke-static/range" : "invoke-static",
         {Alias ? 2u : 4u}, {}, Names.methods[0].reference));
  Caller.instructions.push_back(op(PC++, "move-result-object", {1}));
  Caller.instructions.push_back(
      op(PC++, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
         Target.reference));
  Caller.instructions.push_back(op(PC++, "return-void"));
  Caller.code_end = PC;
  auto Core = klass(Name, {Target, Caller});
  if (Member) {
    Core.enclosing = "Lfixture/Outer;";
    Core.inner_class_present = true;
    Core.inner_name = "Core";
    Core.inner_access = {"public", "static"};
  }
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<T:Lfixture/Bound;>Ljava/lang/Object;";
  auto Bound = klass("Lfixture/Bound;");
  Names.external = Carrier.external = Bound.external = SDK;
  if (SDK) {
    Names.methods[0].instructions.clear();
    Names.methods[0].registers = Names.methods[0].code_end = 0;
  }
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  std::vector<Class> Input{Core, Names, Carrier, Bound, Object, String};
  if (Member)
    Input.push_back(klass("Lfixture/Outer;"));
  return Input;
}

TEST(MobileDalvikJava,
     ClosedCovariantDelegationsKeepCompletePlainAndGenericOverloads) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Member : {false, true})
        for (bool Alias : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Member, Alias, Route}));
            auto Input =
                closedCovariantDelegationClasses(SDK, Range, Member, Alias);
            const auto Target = Input[0].methods[0].reference;
            const auto Caller = Input[0].methods[1].reference;
            const auto Signature = Input[0].methods[1].generic_signature;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            EXPECT_TRUE(validateGenericSignatures(Classes, B)
                            .constructor_calls.contains({Caller, Target}));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_EQ(Classes.at(Caller.owner).methods[1].generic_signature,
                      Signature);
          }
}

