std::vector<Class> arrayListConstructorDelegationClasses(bool SDK, bool Range) {
  const std::string Element = "Lfixture/Carrier<+Lfixture/Bound;>;";
  auto Selected =
      method("<init>", {"Lfixture/Config;", "Ljava/util/List;"}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Lfixture/Parent;", "<init>", {}, "V"}),
              op(1, "return-void")});
  Selected.access = {"public", "constructor"};
  Selected.reference.owner = "Lfixture/Core;";
  Selected.generic_signature =
      "(Lfixture/Config;Ljava/util/List<+" + Element + ">;)V";
  const MethodRef Factory{"Ljava/util/Arrays;",
                          "asList",
                          {"[Ljava/lang/Object;"},
                          "Ljava/util/List;"};
  auto FromArray = method(
      "<init>", {"Lfixture/Config;", "[Lfixture/Carrier;"}, "V", 4,
      {op(0, Range ? "invoke-static/range" : "invoke-static", {3}, {}, Factory),
       op(1, "move-result-object", {0}),
       op(2, "invoke-direct", {1, 2, 0}, {}, Selected.reference),
       op(3, "return-void")});
  FromArray.access = {"public", "constructor", "varargs"};
  FromArray.reference.owner = Selected.reference.owner;
  FromArray.generic_signature = "(Lfixture/Config;[" + Element + ")V";
  const FieldRef Default{"Lfixture/Config;", "DEFAULT", "Lfixture/Config;"};
  auto FromList =
      method("<init>", {"Ljava/util/List;"}, "V", 3,
             {op(0, "sget-object", {0}, {}, Default),
              op(1, "invoke-direct", {1, 0, 2}, {}, Selected.reference),
              op(2, "return-void")});
  FromList.access = {"public", "constructor"};
  FromList.generic_signature = "(Ljava/util/List<+" + Element + ">;)V";
  auto Forward =
      method("<init>", {"[Lfixture/Carrier;"}, "V", 3,
             {op(0, "sget-object", {0}, {}, Default),
              op(1, "invoke-direct", {1, 0, 2}, {}, FromArray.reference),
              op(2, "return-void")});
  Forward.access = FromArray.access;
  Forward.generic_signature = "([" + Element + ")V";
  auto Core =
      klass(Selected.reference.owner, {Selected, FromArray, FromList, Forward});
  Core.access.insert("final");
  Core.superclass = "Lfixture/Parent;";
  Core.generic_signature = "Lfixture/Parent<Lfixture/Bound;>;";
  auto List = klass("Ljava/util/List;");
  List.access = {"public", "interface", "abstract"};
  List.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  List.external = true;
  auto Make = method("asList", Factory.parameters, Factory.returns, 0, {});
  Make.access = {"public", "static", "varargs"};
  Make.generic_signature = "<X:Ljava/lang/Object;>([TX;)Ljava/util/List<TX;>;";
  auto Arrays = klass(Factory.owner, {Make});
  Arrays.external = true;
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Lfixture/Bound;>Ljava/lang/Object;";
  Carrier.external = SDK;
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = SDK;
  auto Config = klass("Lfixture/Config;");
  Config.external = SDK;
  Field Held;
  Held.reference = Default;
  Held.access = {"public", "static"};
  Config.fields.push_back(Held);
  auto Init = method("<init>", {}, "V", 0, {});
  Init.access = {"public", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.external = true;
  return {Core, Carrier, Bound, Config, List, Arrays, Parent};
}

