std::vector<Class> projectedClosedOwnerDelegationClasses(bool Dependency,
                                                         bool Nested,
                                                         bool PrivateTarget) {
  auto Input = closedOwnerDelegationClasses(Dependency, Nested, PrivateTarget);
  auto &Core = Input[0], &View = Input[5];
  auto Member = method("accept", {"Ljava/lang/Object;"}, "Z", 0, {});
  Member.reference.owner = View.name;
  Member.access = {"public", "abstract"};
  Member.generic_signature = "(TE;)Z";
  View.methods = {Member};
  View.external = true;
  auto Bridge = Member;
  Bridge.reference.owner = Core.name;
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.generic_signature.reset();
  Bridge.registers = 4;
  Bridge.instructions = {
      op(0, "new-instance", {0}, {},
         std::string("Ljava/lang/UnsupportedOperationException;")),
      op(1, "const-string", {1}, std::string("owned closed operation")),
      op(2, "invoke-direct", {0, 1}, {},
         MethodRef{"Ljava/lang/UnsupportedOperationException;",
                   "<init>",
                   {"Ljava/lang/String;"},
                   "V"}),
      op(3, "throw", {0})};
  Bridge.code_end = 4;
  auto Typed = Bridge;
  Typed.access = {"public"};
  Typed.reference.parameters = {Nested ? Input[1].name : Input[3].name};
  if (Nested)
    Typed.generic_signature = "(Lfixture/Token<Lfixture/Value;>;)Z";
  Core.methods.push_back(Bridge);
  Core.methods.push_back(Typed);
  return Input;
}

