std::vector<Class> constructorLocalAllocationClasses() {
  auto Input = allocatingThisConstructorClasses(false, false);
  auto &Core = Input[0];
  auto &Local = Input[1];
  Core.fields[0].reference.type = "Ljava/lang/Object;";
  Core.methods[0].reference.parameters = {"Ljava/lang/Object;", "I"};
  Core.methods[0].registers = 3;
  Core.methods[0].instructions[1].reference = Core.fields[0].reference;
  Core.methods[1].instructions.insert(Core.methods[1].instructions.end() - 1,
                                      op(3, "nop"));
  Core.methods[1].instructions[2].reference = Core.methods[0].reference;
  Core.methods[1].instructions.insert(Core.methods[1].instructions.begin() + 2,
                                      op(2, "const/4", {2}, int64_t{0}));
  Core.methods[1].instructions[3].registers = {1, 0, 2};
  for (size_t i = 0; i < Core.methods[1].instructions.size(); ++i)
    Core.methods[1].instructions[i].pc = i;
  Core.methods[1].code_end = Core.methods[1].instructions.size();
  Local.inner_class_present = true;
  Local.enclosing_method = Core.methods[1].reference;
  Local.access = {"final"};
  Local.methods[0].access = {"constructor"};
  const FieldRef Captured{Local.name, "captured", "Ljava/lang/Object;"};
  Local.fields.push_back({Captured, {"final", "synthetic"}, {}});
  Local.methods[0].instructions.insert(
      Local.methods[0].instructions.begin(),
      op(0, "iput-object", {1, 0}, {}, Captured));
  Local.methods[0].instructions[1].pc = 2;
  Local.methods[0].instructions[2].pc = 5;
  Local.methods[0].code_end = 6;
  auto Read = method("read", {}, "Ljava/lang/Object;", 2,
                     {op(0, "iget-object", {0, 1}, {}, Captured),
                      op(1, "return-object", {0})});
  Read.access = {"public"};
  Read.reference.owner = Local.name;
  Local.methods.push_back(Read);
  return Input;
}

TEST(MobileDalvikJava, ConstructorPrefixLocalsKeepDeclarationBeforeAllocation) {
  auto Input = constructorLocalAllocationClasses();
  Budget B;
  const auto R = recoverJava(linkClasses(Input, B), B);
  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
  std::string Text;
  for (size_t i = 0; i < R.getArray("source_units")->size(); ++i)
    Text += source(R, i);
  const auto Local = Text.find("class __neverdLocal");
  const auto Allocate = Text.find("__neverdCtorAllocation0 = new");
  ASSERT_NE(Local, std::string::npos);
  ASSERT_NE(Allocate, std::string::npos);
  EXPECT_LT(Local, Allocate);
  EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
}

