std::vector<Class> closedAccessMarkerClasses(bool SDK, bool Range,
                                             bool LocalWords, bool Public,
                                             bool Final) {
  const std::string Name = "Lfixture/Core;", MarkerName = "Lfixture/Core$1;";
  auto Target =
      method("<init>",
             {"Lfixture/Set;", "Lfixture/Context;", "Lfixture/Probe;"}, "V", 4,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  Target.reference.owner = Name;
  Target.access = {"private", "constructor"};
  Target.generic_signature =
      "(Lfixture/Set<Lfixture/Value;>;Lfixture/Context;Lfixture/Probe;)V";
  auto Parameters = Target.reference.parameters;
  Parameters.push_back(MarkerName);
  const unsigned Self = LocalWords ? 1 : 0;
  auto Access =
      method("<init>", Parameters, "V", 5 + Self,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                 {Self, Self + 1, Self + 2, Self + 3}, {}, Target.reference),
              op(1, "return-void")});
  Access.access = {"synthetic", "constructor"};
  if (Public)
    Access.access.insert("public");
  auto Core = klass(Name, {Target, Access});
  if (Final)
    Core.access.insert("final");
  auto Marker = klass(MarkerName);
  Marker.access = {"synthetic"};
  Marker.enclosing = Name;
  Marker.inner_class_present = true;
  Marker.inner_access = {"static", "synthetic"};
  auto Set = klass("Lfixture/Set;");
  Set.access = {"public", "abstract", "interface"};
  Set.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Value = klass("Lfixture/Value;");
  auto Context = klass("Lfixture/Context;");
  auto Probe = klass("Lfixture/Probe;");
  Set.external = Value.external = Context.external = Probe.external = SDK;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Core, Marker, Set, Value, Context, Probe, Object};
}

TEST(MobileDalvikJava,
     ClosedAccessMarkersKeepExactRawWordsAndSelectedClosedContract) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool LocalWords : {false, true})
        for (bool Public : {false, true})
          for (bool Final : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Range, LocalWords, Public, Final, Route}));
              auto Input = closedAccessMarkerClasses(SDK, Range, LocalWords,
                                                     Public, Final);
              const auto Caller = Input[0].methods[1].reference;
              const auto Target = Input[0].methods[0].reference;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
              if (Route)
                Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(Plans.constructor_calls.contains({Caller, Target}));
              EXPECT_FALSE(Plans.methods.contains(Caller));
              EXPECT_EQ(recoverJava(Classes, B)
                            .getInteger("unrecovered_method_count"),
                        0);
            }
}

TEST(MobileDalvikJava, ClosedAccessMarkersRejectFlagFrameScopeAndMarkerDrift) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = closedAccessMarkerClasses(false, true, true, false, true);
    auto &Caller = Input[0].methods[1];
    auto &Target = Input[0].methods[0];
    if (Mutation == 0)
      Caller.access.insert("private");
    else if (Mutation == 1)
      Caller.access.insert("static");
    else if (Mutation == 2)
      Caller.generic_signature = Caller.reference.signature();
    else if (Mutation == 3) {
      Caller.instructions.push_back(op(2, "nop"));
      ++Caller.code_end;
    } else if (Mutation == 4)
      Caller.instructions[0].registers.back() = 5;
    else if (Mutation == 5)
      Input.erase(Input.begin() + 1);
    else if (Mutation == 6)
      Input[1].enclosing = Input[4].name;
    else if (Mutation == 7)
      Input[1].generic_signature = "<M:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 8) {
      auto Init = method("<init>", {}, "V", 1, {op(0, "return-void")});
      Init.reference.owner = Input[1].name;
      Input[1].methods.push_back(Init);
    } else if (Mutation == 9)
      Input[1].fields.push_back(
          {{Input[1].name, "state", "I"}, {}, {}});
    else if (Mutation == 10)
      Input[0].generic_signature =
          "<X:Ljava/lang/Object;X:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 11)
      Target.generic_signature =
          "<X:Ljava/lang/Object;X:Ljava/lang/Object;>"
          "(Lfixture/Set<Lfixture/Value;>;Lfixture/Context;Lfixture/Probe;)V";
    else if (Mutation == 12)
      Target.access.insert("varargs");
    else if (Mutation == 13)
      Caller.instructions[0].registers[0] = 0;
    else if (Mutation == 14)
      Caller.instructions[0].registers[2] = Caller.instructions[0].registers[1];
    else
      Caller.instructions[0].literal = std::string("invalid call metadata");
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

