std::vector<Class> anonymousParameterClasses() {
  const std::string Owner = "Lfixture/ParameterHost;",
                    Name = "Lfixture/ParameterHost$1;";
  const FieldRef Offset{Name, "offset", "I"}, Time{Name, "time", "J"},
      Token{Name, "token", "Ljava/lang/Object;"};
  auto Ctor = method(
      "<init>", {"I", "Ljava/util/List;", "J", "Ljava/lang/Object;"}, "V", 6,
      {op(0, "iput", {1, 0}, {}, Offset), op(1, "iput-wide", {3, 0}, {}, Time),
       op(2, "iput-object", {5, 0}, {}, Token),
       op(3, "invoke-direct", {0}, {},
          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
       op(4, "return-void")});
  Ctor.access = {"public", "constructor"};
  Ctor.generic_signature = "(Ljava/util/List<Ljava/lang/String;>;)V";
  auto Local = klass(Name, {Ctor});
  Local.inner_class_present = true;
  for (const auto &Field : {Offset, Time, Token})
    Local.fields.push_back({Field, {"final", "synthetic"}, {}});
  auto Make = method("make", Ctor.reference.parameters, "Ljava/lang/Object;", 6,
                     {op(0, "new-instance", {0}, {}, Name),
                      op(1, "invoke-direct", {0, 1, 2, 3, 4, 5}, {},
                         Local.methods[0].reference),
                      op(2, "return-object", {0})});
  auto Host = klass(Owner, {Make});
  Local.enclosing_method = Host.methods[0].reference;
  return {Host, Local};
}

TEST(MobileDalvikJava, AnonymousConstructorSignaturesMapOnlyProvenCaptures) {
  auto Input = anonymousParameterClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto R = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    EXPECT_NE(source(R).find("int arg0, java.util.List<java.lang.String> arg1, "
                             "long arg2, java.lang.Object arg3"),
              std::string::npos);
    const llvm::json::Object *Row = nullptr;
    for (const auto &Method : *R.getArray("methods"))
      if (Method.getAsObject()->getString("name") == "<init>")
        Row = Method.getAsObject();
    ASSERT_NE(Row, nullptr);
    EXPECT_EQ(Row->getInteger("generic_signature_omitted_parameters"), 3);
    const auto *Indices = Row->getArray("generic_signature_parameter_indices");
    ASSERT_EQ(Indices->size(), 1u);
    EXPECT_EQ(Indices->front().getAsInteger(), 1);
  }
  Input.back().fields[1].access.erase("synthetic");
  rejected([&] { recover(Input); }, "constructor implicit parameter mapping");
  Input = anonymousParameterClasses();
  Input.back().methods[0].instructions[1].registers[0] = 4;
  rejected([&] { recover(Input); }, "constructor implicit parameter mapping");
  Input = anonymousParameterClasses();
  Input.back().methods[0].generic_signature = "()V";
  rejected([&] { recover(Input); }, "constructor implicit parameter mapping");
}

