TEST(MobileDalvikJava, CapturedInnerMappingRejectsUnprovenCaptureAndScope) {
  for (unsigned Mutation = 0; Mutation != 6; ++Mutation) {
    auto Input = capturedInnerClasses();
    auto &Inner = Input.back();
    switch (Mutation) {
    case 0:
      Inner.methods[0].instructions[0].registers[0] = 2;
      break;
    case 1:
      Inner.fields[0].access.erase("synthetic");
      break;
    case 2:
      Inner.fields[0].access.erase("final");
      break;
    case 3:
      Inner.fields[0].access.insert("static");
      break;
    case 4:
      Inner.methods[0].generic_signature = "()V";
      break;
    case 5:
      Inner.methods[0].instructions.erase(
          Inner.methods[0].instructions.begin());
      break;
    }
    rejected([&] { recover(Input); }, "constructor implicit parameter mapping");
  }
  auto Input = capturedInnerClasses();
  Input[0].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[1].fields.push_back(
      {{Input[1].name, "value", "Ljava/lang/Object;"}, {}, {}, "TT;"});
  auto Report = recover(Input);
  EXPECT_EQ(Report.getArray("generic_signature_projections")->size(), 1u);
  Input[0].generic_signature =
      "<T:Ljava/lang/Object;:Ljava/io/Serializable;>Ljava/lang/Object;";
  rejected([&] { recover(Input); }, "captures an enclosing type variable");
}

