TEST(MobileDalvikJava, ParameterizedOwnersHaveExplicitStaticInnerProjection) {
  auto Input = capturedInnerClasses();
  Input[0].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Get =
      method("get", {}, Input[1].name, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Get.reference.owner = Input[0].name;
  Get.access = {"public"};
  Get.generic_signature = "()Lfixture/Outer<TT;>.Member;";
  Input[0].methods.push_back(Get);
  Input[1].fields[0].generic_signature = "Lfixture/Outer<TT;>;";
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto R = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    EXPECT_NE(source(R).find("fixture.Outer.Member get()"), std::string::npos);
    EXPECT_NE(source(R).find("fixture.Outer<java.lang.Object> enclosure;"),
              std::string::npos);
    const auto *Rows = R.getArray("generic_signature_projections");
    ASSERT_NE(Rows, nullptr);
    EXPECT_EQ(Rows->size(), 2u);
  }
  Input[1].inner_access.insert("static");
  const auto CaptureSignature = Input[1].fields[0].generic_signature;
  Input[1].fields[0].generic_signature.reset();
  rejected([&] { recover(Input); }, "parameterized inner owner binding");
  Input[1].inner_access.erase("static");
  Input[1].fields[0].generic_signature = CaptureSignature;
  Input[1].inner_name = "Different";
  rejected([&] { recover(Input); }, "parameterized inner owner identity");
}

std::vector<Class> interfaceBoundedInnerClasses() {
  auto Input = capturedInnerClasses();
  auto &Outer = Input[0];
  auto &Inner = Input[1];
  auto Contract = klass("Lfixture/Item;");
  Contract.access = {"public", "abstract", "interface"};
  auto Get = method("get", {}, "Ljava/lang/Object;", 0, {});
  Get.reference.owner = Contract.name;
  Get.access = {"public", "abstract"};
  Contract.methods.push_back(Get);
  Outer.generic_signature = "<T::Lfixture/Item;>Ljava/lang/Object;";
  Inner.fields[0].generic_signature = "Lfixture/Outer<TT;>;";
  Inner.fields.push_back(
      {{Inner.name, "value", Contract.name}, {"public"}, {}, "TT;"});
  auto Choose = method("choose", {Contract.name}, Contract.name, 2,
                       {op(0, "return-object", {1})});
  Choose.reference.owner = Inner.name;
  Choose.access = {"public"};
  Choose.generic_signature = "(TT;)TT;";
  auto Use =
      method("use", {Contract.name}, "Ljava/lang/Object;", 2,
             {op(0, "invoke-interface", {1}, {}, Get.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Use.reference.owner = Inner.name;
  Use.access = {"public"};
  Use.generic_signature = "(TT;)Ljava/lang/Object;";
  auto Echo = method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                     {op(0, "return-object", {1})});
  Echo.reference.owner = Inner.name;
  Echo.access = {"public"};
  Echo.generic_signature = "<T:Ljava/lang/Object;>(TT;)TT;";
  Inner.methods.insert(Inner.methods.end(), {Choose, Use, Echo});
  Input.push_back(Contract);
  return Input;
}

TEST(MobileDalvikJava, StaticInnerCapturesRetainExactSoleInterfaceBounds) {
  auto Input = interfaceBoundedInnerClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto R = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    unsigned Changes = 0;
    for (const auto &Row : *R.getArray("generic_signature_projections"))
      for (const auto &Change : *Row.getAsObject()->getArray("changes")) {
        const auto &Projection = *Change.getAsObject();
        EXPECT_EQ(Projection.getString("kind"),
                  "static-inner-interface-upper-bound");
        EXPECT_EQ(Projection.getString("original_type"), Input[0].name + "::T");
        EXPECT_EQ(Projection.getString("source_type"), Input[2].name);
        EXPECT_EQ(Projection.getString("scope_origin"), Input[0].name);
        ++Changes;
      }
    EXPECT_EQ(Changes, 5u);
    EXPECT_EQ(R.getString("status"), "partial");
    EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
    EXPECT_NE(source(R, 1).find("fixture.Outer<fixture.Item> enclosure;"),
              std::string::npos);
    EXPECT_NE(source(R, 1).find("fixture.Item choose(fixture.Item arg0)"),
              std::string::npos);
    EXPECT_NE(source(R, 1).find("T echo(T arg0)"), std::string::npos);
    EXPECT_EQ(Input[1].methods[1].generic_signature, "(TT;)TT;");
    EXPECT_EQ(Input[1].methods[3].generic_signature,
              "<T:Ljava/lang/Object;>(TT;)TT;");
  }
}

TEST(MobileDalvikJava, StaticInnerInterfaceBoundsRejectOpenOrOtherScopes) {
  for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = interfaceBoundedInnerClasses();
    switch (Mutation) {
    case 0:
      Input[0].generic_signature =
          "<T::Lfixture/Item;:Ljava/io/Serializable;>Ljava/lang/Object;";
      break;
    case 1:
      Input[0].generic_signature = "<S::Lfixture/Item;T:TS;>Ljava/lang/Object;";
      Input[1].fields[0].generic_signature = "Lfixture/Outer<TS;TT;>;";
      break;
    case 2:
      Input[2].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 3:
      Input[2].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      Input[0].generic_signature =
          "<T::Lfixture/Item<Ljava/lang/String;>;>Ljava/lang/Object;";
      break;
    case 4:
      Input[1].inner_access.insert("static");
      break;
    case 5:
      Input[1].methods[1].generic_signature = "(TUnknown;)TT;";
      break;
    case 6:
      Input[1].enclosing = "Lfixture/Other;";
      Input[1].fields[0].reference.type = *Input[1].enclosing;
      Input[1].methods[0].reference.parameters[0] = *Input[1].enclosing;
      Input[1].methods[0].instructions[0].reference =
          Input[1].fields[0].reference;
      Input.push_back(klass(*Input[1].enclosing));
      break;
    }
    rejected([&] { recover(Input); },
             Mutation >= 4 ? "unbound type variable"
                           : "captures an enclosing type variable");
  }
}

