  Class C = klass("Lfixture/Core;");
  C.fields.push_back({{C.name, "java", "I"}, {"public", "static"}, {}});
  C.methods = {method("bad", {"I"}, "I", 1,
                      {op(0, "invoke-static", {0}, {},
                          MethodRef{"Ljava/lang/Math;", "abs", {"I"}, "I"}),
                       op(1, "move-result", {0}), op(2, "return", {0})})};
