std::vector<Class> erasedConstructorDelegationClasses() {
  auto Sink = klass("Lfixture/Sink;");
  Sink.access = {"public", "interface", "abstract"};
  Sink.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Marker = klass("Lfixture/Marker;");
  Marker.access.insert("final");
  Marker.external = true;
  auto Target = method("<init>", {"I", "J", Sink.name}, "V", 5,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
  Target.access = {"private", "constructor"};
  Target.generic_signature = "(IJLfixture/Sink<Ljava/lang/Object;>;)V";
  auto Forward = method(
      "<init>", {"I", "J", Sink.name, Marker.name}, "V", 8,
      {op(0, "invoke-direct/range", {2, 3, 4, 5, 6}, {}, Target.reference),
       op(1, "return-void")});
  Forward.access = {"public", "synthetic", "constructor"};
  auto Core = klass("Lfixture/Core;", {Target, Forward});
  Core.access.insert("final");
  return {Core, Sink, Marker};
}

std::vector<Class> scopedMaskConstructorClasses(bool External, bool Range) {
  auto Input = erasedConstructorDelegationClasses();
  auto &Core = Input[0];
  Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Target = Core.methods[0];
  Target.access = {"public", "constructor"};
  Target.generic_signature = "(IJLfixture/Sink<-TT;>;)V";
  Input[1].external = External;
  Input[2].name = "Lkotlin/jvm/internal/DefaultConstructorMarker;";
  auto Provider = klass("Lfixture/Provider;");
  Provider.external = true;
  Provider.fields.push_back({{Provider.name, "DEFAULT", Input[1].name},
                             {"public", "static"},
                             {},
                             "Lfixture/Sink<Ljava/lang/Object;>;"});
  auto Forward =
      method("<init>", {"I", "J", Input[1].name, "I", Input[2].name}, "V", 8,
             {op(0, "and-int/lit8", {0, 6}, int64_t(4)),
              op(1, "if-eqz", {0}, {}, {}, 4),
              op(2, "sget-object", {0}, {}, Provider.fields[0].reference),
              op(3, "goto", {}, {}, {}, 5), op(4, "move-object", {0, 5}),
              Range ? op(5, "move-object", {5, 0}) : op(5, "nop"),
              op(6, Range ? "invoke-direct/range" : "invoke-direct",
                 Range ? std::vector<unsigned>{1, 2, 3, 4, 5}
                       : std::vector<unsigned>{1, 2, 3, 4, 0},
                 {}, Target.reference),
              op(7, "return-void")});
  Forward.access = {"public", "synthetic", "constructor"};
  Forward.reference.owner = Core.name;
  Core.methods[1] = Forward;
  Input.push_back(Provider);
  return Input;
}

std::vector<Class> allocatedMaskConstructorClasses(bool External, bool Range) {
  auto Input = scopedMaskConstructorClasses(External, Range);
  auto DefaultInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  DefaultInit.access = {"public", "constructor"};
  auto Default = klass("Lfixture/Default;", {DefaultInit});
  Default.interfaces = {Input[1].name};
  Default.generic_signature =
      "Ljava/lang/Object;Lfixture/Sink<Ljava/lang/Object;>;";
  Default.external = External;
  if (External)
    Default.methods[0].instructions.clear();
  Input[3] = Default;
  auto &Core = Input[0];
  const FieldRef Callback{Core.name, "callback", Input[1].name};
  Core.fields.push_back(
      {Callback, {"public", "final"}, {}, "Lfixture/Sink<-TT;>;"});
  auto &Target = Core.methods[0];
  Target.instructions = {op(0, "invoke-direct", {0}, {},
                            MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                         op(1, "iput-object", {4, 0}, {}, Callback),
                         op(2, "return-void")};
  Target.code_end = 3;
  auto &Forward = Core.methods[1];
  Forward.registers = 7;
  Forward.instructions = {op(0, "and-int/lit8", {5, 5}, int64_t(4)),
                          op(1, "if-eqz", {5}, {}, {}, 4),
                          op(2, "new-instance", {4}, {}, Default.name),
                          op(3, Range ? "invoke-direct/range" : "invoke-direct",
                             {4}, {}, Default.methods[0].reference),
                          op(4, Range ? "invoke-direct/range" : "invoke-direct",
                             {0, 1, 2, 3, 4}, {}, Target.reference),
                          op(5, "return-void")};
  Forward.code_end = 6;
  return Input;
}

TEST(MobileDalvikJava, MaskAllocationsReplaceOnlyIncomingReferenceSlots) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = allocatedMaskConstructorClasses(External, Range);
        const auto Forward = Input[0].methods[1].reference;
        const auto Target = Input[0].methods[0].reference;
        Budget B;
        EXPECT_TRUE(constructorPrefixAllocation(Input[0].methods[1], 2));
        EXPECT_EQ(constructorPrefixAllocationEnd(Input[0].methods[1], 2, B),
                  3u);
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_TRUE(Plans.constructor_delegations.contains(Forward));
        EXPECT_EQ(Plans.constructor_delegations.at(Forward), Target);
        EXPECT_TRUE(Plans.constructor_calls.contains({Forward, Target}));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      }
  // Array inputs are references too, but the allocation's later type use is
  // still independently checked by Body.
  auto Input = allocatedMaskConstructorClasses(false, false);
  Input[0].methods[1].reference.parameters[2] = "[I";
  Budget B;
  EXPECT_TRUE(constructorPrefixAllocation(Input[0].methods[1], 2));
  EXPECT_EQ(constructorPrefixAllocationEnd(Input[0].methods[1], 2, B), 3u);
}

TEST(MobileDalvikJava, IncomingMaskAllocationsRejectSelfWordsAndBrokenRegions) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = allocatedMaskConstructorClasses(false, false);
    auto &Forward = Input[0].methods[1];
    if (Mutation < 5) {
      const unsigned Reg = Mutation < 4 ? Mutation : Forward.registers;
      Forward.instructions[2].registers = {Reg};
      Forward.instructions[3].registers = {Reg};
      Budget B;
      // Primitive words may hold a new value after earlier uses. These
      // particular clobbers still break the later delegation's typed input;
      // the complete recovery rejection below remains mandatory.
      if (Mutation >= 1 && Mutation <= 3) {
        EXPECT_TRUE(constructorPrefixAllocation(Forward, 2));
        EXPECT_EQ(constructorPrefixAllocationEnd(Forward, 2, B), 3u);
      } else {
        EXPECT_FALSE(constructorPrefixAllocation(Forward, 2));
        EXPECT_FALSE(constructorPrefixAllocationEnd(Forward, 2, B));
      }
    } else if (Mutation == 5) {
      Forward.instructions[3].registers.push_back(0);
      std::get<MethodRef>(Forward.instructions[3].reference)
          .parameters.push_back("Ljava/lang/Object;");
    } else if (Mutation == 6)
      Forward.instructions[1].target = 3;
    else if (Mutation == 7)
      Forward.instructions[0] = op(0, "move-object", {4, 0});
    else if (Mutation == 8)
      Input[3].methods.clear();
    else if (Mutation == 9)
      Forward.instructions[1].target = 5;
    else if (Mutation == 10)
      Forward.instructions[4].registers.back() = 0;
    else {
      Forward.instructions.insert(Forward.instructions.begin() + 3,
                                  op(0, "move-object", {6, 4}));
      for (size_t i = 0; i < Forward.instructions.size(); ++i)
        Forward.instructions[i].pc = i;
      Forward.instructions[1].target = 5;
      Forward.code_end = Forward.instructions.size();
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

std::vector<Class> rawLocalCovariantClasses(bool Range) {
  auto API = klass("Lfixture/Transform;");
  API.external = true;
  API.access = {"public", "interface", "abstract"};
  API.generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Apply =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Apply.access = {"public", "abstract"};
  Apply.reference.owner = API.name;
  Apply.generic_signature = "(TA;)TR;";
  API.methods = {Apply};
  auto Parent = klass("Lfixture/Adapter;");
  Parent.external = true;
  Parent.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto ParentInit = method("<init>", {"I"}, "V", 0, {});
  ParentInit.access = {"public", "constructor"};
  ParentInit.reference.owner = Parent.name;
  Parent.methods = {ParentInit};
  auto OuterInit =
      method("<init>", {}, "V", 2,
             {op(0, "invoke-direct", {1}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  OuterInit.access = {"public", "constructor"};
  auto Outer = klass("Lfixture/Owner;", {OuterInit});
  Outer.generic_signature = "<K:Ljava/lang/Object;>Ljava/lang/Object;";
  auto LocalInit =
      method("<init>", {}, "V", 2,
             {op(0, "const/4", {0}, int64_t(1)),
              op(1, "invoke-direct", {1, 0}, {}, ParentInit.reference),
              op(2, "return-void")});
  LocalInit.access = {"public", "constructor"};
  auto Target =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Void;", 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.access = {"public", "final"};
  Target.generic_signature = "(TK;)Ljava/lang/Void;";
  auto Local = klass("Lfixture/Owner$1;", {LocalInit, Target});
  Local.access = {"final"};
  Local.superclass = Parent.name;
  Local.interfaces = {API.name};
  Local.enclosing_method = Outer.methods[0].reference;
  Local.inner_class_present = true;
  auto Bridge =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 3,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2},
                 {}, Local.methods[1].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.reference.owner = Local.name;
  Local.methods.push_back(Bridge);
  auto Void = klass("Ljava/lang/Void;");
  Void.access.insert("final");
  Void.external = true;
  return {Outer, Local, Parent, API, Void};
}

TEST(MobileDalvikJava, RawLocalCovariantBridgesProveErasedSourceParameter) {
  for (bool Range : {false, true})
    for (bool Reverse : {false, true}) {
      auto Input = rawLocalCovariantClasses(Range);
      if (Reverse)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto Classes = linkClasses(Input, B);
      const auto Scopes = validateSourceScopes(Classes, B);
      const auto Plans =
          validateGenericSignatures(Classes, B, &Scopes.enums, &Scopes.shared);
      const MethodRef Target{"Lfixture/Owner$1;",
                             "apply",
                             {"Ljava/lang/Object;"},
                             "Ljava/lang/Void;"};
      const MethodRef Bridge{"Lfixture/Owner$1;",
                             "apply",
                             {"Ljava/lang/Object;"},
                             "Ljava/lang/Object;"};
      EXPECT_TRUE(Plans.raw_local_covariant_bridges.contains(Bridge));
      const auto *Source = sourceMethodSignature(Target, Plans);
      ASSERT_NE(Source, nullptr);
      EXPECT_EQ(Source->types.at(Source->parameters[0]).kind,
                GenericType::Kind::Class);
      EXPECT_EQ(Source->source_projections.size(), 1u);
      const auto Inheritance =
          planGenericInheritance(Classes, Plans, B, &Scopes.enums);
      EXPECT_TRUE(Inheritance.bridges.contains(Bridge));
    }
}

