TEST(MobileDalvikJava, ClosedParentMarkersRejectUnavailableOrChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = closedParentMarkerClasses(true, true, true);
    auto &Core = Input[0], &Local = Input.back();
    auto &Target = Core.methods[0], &Caller = Core.methods[1];
    if (Mutation == 0) {
      Local.name = "Lother/LocalToken;";
      for (auto &M : Local.methods)
        M.reference.owner = Local.name;
      Core.generic_signature = "Lfixture/Parent<Lother/LocalToken;>;";
    } else if (Mutation == 1) {
      Local.external = true;
      Local.methods[0].instructions.clear();
      Local.methods[0].registers = Local.methods[0].code_end = 0;
    } else if (Mutation == 2)
      Core.access.erase("final");
    else if (Mutation == 3)
      Core.generic_signature = "Lfixture/Parent<+Lfixture/LocalToken;>;";
    else if (Mutation == 4)
      Target.access.insert("varargs");
    else if (Mutation == 5)
      Target.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 6)
      Target.generic_signature =
          "<T:Ljava/lang/Object;>(IJLfixture/Sink<-Lfixture/Token;>;)V";
    else if (Mutation == 7)
      Caller.instructions[0].registers[1] = 0;
    else if (Mutation == 8)
      Core.generic_signature.reset();
    else {
      Caller.instructions[0].pc = 1;
      Caller.instructions[1].pc = 2;
      Caller.instructions.insert(Caller.instructions.begin(), op(0, "nop"));
      Caller.code_end = 3;
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

