std::vector<Class> boundedOwnerLabelConstructorClasses(bool External,
                                                       bool Range) {
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = true;
  auto Link = klass("Lfixture/Link;");
  Link.generic_signature =
      "<A:Ljava/lang/Object;B:Lfixture/Bound;>Ljava/lang/Object;";
  Link.external = External;
  auto Core = klass("Lfixture/Core;");
  Core.access = {"public", "final"};
  Core.generic_signature =
      "<T:Ljava/lang/Object;V:Lfixture/Bound;>Ljava/lang/Object;";
  auto Target = method("<init>",
                       {"Ljava/lang/Object;", Link.name, "Ljava/lang/Object;",
                        "Ljava/lang/String;"},
                       "V", 5,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
  Target.access = {"public", "constructor"};
  Target.reference.owner = Core.name;
  Target.generic_signature =
      "(TT;Lfixture/Link<TT;TV;>;TT;Ljava/lang/String;)V";
  auto Forward = method(
      "<init>", {"Ljava/lang/Object;", Link.name, "Ljava/lang/Object;"}, "V", 5,
      {op(0, "const-string", {4}, std::string("owned label")),
       op(1, Range ? "invoke-direct/range" : "invoke-direct", {0, 1, 2, 3, 4},
          {}, Target.reference),
       op(2, "return-void")});
  // r1 is the original receiver, followed by its three incoming arguments.
  // A range form copies them into a contiguous call frame using the label r0.
  Forward.registers = Range ? 10 : 5;
  if (Range) {
    Forward.instructions = {
        op(0, "const-string", {4}, std::string("owned label")),
        op(1, "move-object", {0, 6}),
        op(2, "move-object", {1, 7}),
        op(3, "move-object", {2, 8}),
        op(4, "move-object", {3, 9}),
        op(5, "invoke-direct/range", {0, 1, 2, 3, 4}, {}, Target.reference),
        op(6, "return-void")};
    Forward.code_end = 7;
  } else {
    Forward.instructions[0].registers = {0};
    Forward.instructions[1].registers = {1, 2, 3, 4, 0};
  }
  Forward.access = {"public", "constructor", "synthetic"};
  Forward.reference.owner = Core.name;
  Core.methods = {Target, Forward};
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  return {Core, Bound, Link, String};
}

