  Callback.methods = {Invoke};
  auto Get =
      method("get", {}, Callback.name, 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Get.access = {"public"};
  Get.generic_signature = "()Lfixture/Callback<TA;TB;>;";
