TEST(MobileDalvikJava, ErasedConstructorDelegationsKeepPrivateGenericTarget) {
  for (bool External : {false, true})
    for (unsigned Route = 0; Route < 3; ++Route) {
      auto Input = erasedConstructorDelegationClasses();
      Input[1].external = External;
      const auto Target = Input[0].methods[0].reference;
      const auto Forward = Input[0].methods[1].reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto R =
          Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("method_count"), 2);
      EXPECT_EQ(R.getInteger("projected_method_count"), 1);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getString("status"), "partial");
      EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 8);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
      bool Found = false;
      for (const auto &Value : *R.getArray("methods")) {
        const auto &Row = *Value.getAsObject();
        if (Row.getString("identity") == Forward.identity()) {
          Found = true;
          EXPECT_EQ(Row.getString("projection_kind"), "synthetic-constructor");
          EXPECT_EQ(Row.getString("source_identity"), Forward.identity());
          ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
          EXPECT_EQ(Row.getArray("metadata_differences")->size(), 1U);
        }
      }
      EXPECT_TRUE(Found);
      const auto Text = source(R);
      EXPECT_NE(Text.find("private Core(int arg0, long arg1, "
                          "fixture.Sink<java.lang.Object> arg2)"),
                std::string::npos);
      EXPECT_NE(Text.find("this(((int)"), std::string::npos);
      EXPECT_NE(Text.find("fixture.Sink<java.lang.Object>) "
                          "((fixture.Sink) arg2)"),
                std::string::npos);
    }
}

