std::vector<Class> typedConfigConstructorClasses(bool External, bool Range) {
  auto Config = klass("Lfixture/Config;");
  Config.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Config.external = External;
  auto View = klass("Lfixture/View;");
  View.access = {"public", "interface", "abstract"};
  View.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  View.external = External;
  auto Target = method("<init>", {Config.name}, "V", 2,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
  Target.access = {"public", "constructor"};
  Target.generic_signature = "(Lfixture/Config<TT;>;)V";
  auto Core = klass("Lfixture/Core;", {Target});
  Core.interfaces = {View.name};
  Core.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/View<TT;>;";
  FieldRef Bias{Core.name, "bias", "F"};
  Core.fields = {{{Bias}, {"public"}, {}}};
  auto Forward =
      method("<init>", {Config.name, "F"}, "V", 3,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
                 Core.methods[0].reference),
              op(1, "iput", {2, 0}, {}, Bias), op(2, "return-void")});
  Forward.reference.owner = Core.name;
  Forward.access = {"public", "constructor"};
  Forward.generic_signature = "(Lfixture/Config<TT;>;F)V";
  Core.methods.push_back(Forward);
  return {Core, Config, View};
}

