TEST(MobileDalvikJava, ConstructorFormalsRejectChangedScopesAndOrigins) {
  for (bool Array : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(Array);
      SCOPED_TRACE(Mutation);
      auto Input =
          formalInputConstructorClasses(true, false, Array, false, true);
      auto &Core = Input[0];
      auto &Target = Core.methods[0], &Caller = Core.methods[1];
      const std::string Prefix = Array ? "[" : "";
      if (Mutation == 0) {
        Core.generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Ljava/lang/Object;"
            "Lfixture/View<TT;>;";
        Caller.generic_signature = "(" + Prefix + "TU;F)V";
      } else if (Mutation == 1)
        Caller.generic_signature =
            "<T:Ljava/lang/Object;>" + *Caller.generic_signature;
      else if (Mutation == 2)
        Target.generic_signature =
            "<T:Ljava/lang/Object;>" + *Target.generic_signature;
      else if (Mutation == 3)
        Caller.generic_signature = "(" + Prefix + "Ljava/lang/Object;F)V";
      else if (Mutation == 4)
        Caller.instructions[2].registers[1] = 0;
      else if (Mutation == 5)
        Caller.instructions[1].opcode = "move";
      else if (Mutation == 6) {
        Target.access.insert("varargs");
        if (Array)
          Caller.instructions[1] = op(1, "move-object", {1, 4});
      } else if (Mutation == 7)
        Target.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 8)
        Caller.instructions[1] = op(1, "const/4", {1}, int64_t(1));
      else {
        auto Sibling = Target;
        Sibling.reference.parameters = {"Ljava/lang/String;"};
        Sibling.generic_signature =
            "<X:Ljava/lang/Object;>(Ljava/lang/String;)V";
        Core.methods.push_back(Sibling);
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> genericParentMarkerClasses(bool External, bool Range) {
  auto Input = unaryOwnerMarkerConstructorClasses(External, Range);
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"protected", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.external = External;
  if (External) {
    Parent.methods[0].instructions.clear();
    Parent.methods[0].registers = Parent.methods[0].code_end = 0;
  }
  auto &Core = Input[0];
  Core.interfaces.clear();
  Core.superclass = Parent.name;
  Core.generic_signature = "<T:Ljava/lang/Object;>Lfixture/Parent<TT;>;";
  Core.methods[0].instructions[0].reference = Parent.methods[0].reference;
  Input.push_back(Parent);
  return Input;
}

std::vector<Class> nestedParentMaskConstructorClasses(bool External,
                                                      bool Range) {
  auto Input = scopedMaskConstructorClasses(External, Range);
  auto View = klass("Lfixture/View;");
  View.access = {"public", "abstract", "interface"};
  View.external = External;
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = External;
  auto Middle = klass("Lfixture/Middle;");
  Middle.superclass = Bound.name;
  Middle.external = External;
  auto Local = klass("Lfixture/Local;");
  Local.access = {"final"};
  Local.superclass = Middle.name;
  Local.generic_signature = "<E:Ljava/lang/Object;>Lfixture/Middle;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"protected", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.access.insert("abstract");
  Parent.generic_signature =
      "<N:Lfixture/Bound;>Ljava/lang/Object;Lfixture/View;";
  Parent.interfaces = {View.name};
  Parent.external = External;
  if (External) {
    Parent.methods[0].instructions.clear();
    Parent.methods[0].registers = Parent.methods[0].code_end = 0;
  }
  auto &Core = Input[0];
  Core.access = {"final"};
  Core.superclass = Parent.name;
  Core.generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Parent<Lfixture/Local<TT;>;>;";
  Core.methods[0].instructions[0].reference = Parent.methods[0].reference;
  Input.insert(Input.end(), {View, Bound, Middle, Local, Parent});
  return Input;
}

