TEST(MobileDalvikJava, NestedParentMasksRejectUnprovedScopeAndBounds) {
  for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = nestedParentMaskConstructorClasses(true, true);
    auto &Core = Input[0], &Local = Input[Input.size() - 2];
    auto &Target = Core.methods[0], &Caller = Core.methods[1];
    if (Mutation == 0)
      Core.generic_signature = "<T:Ljava/lang/Object;>Lfixture/Parent<Lfixture/"
                               "Local<Ljava/lang/Object;>;>;";
    else if (Mutation == 1)
      Local.external = true;
    else if (Mutation == 2) {
      Local.name = "Lother/Local;";
      Core.generic_signature =
          "<T:Ljava/lang/Object;>Lfixture/Parent<Lother/Local<TT;>;>;";
    } else if (Mutation == 3)
      Local.generic_signature =
          "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Lfixture/Middle;";
    else if (Mutation == 4)
      Local.generic_signature = "<E:Lfixture/Bound;>Lfixture/Middle;";
    else if (Mutation == 5)
      Core.generic_signature =
          "<T:Ljava/lang/Object;>Lfixture/Parent<+Lfixture/Local<TT;>;>;";
    else if (Mutation == 6)
      Core.generic_signature =
          "<T:Ljava/lang/Object;>Lfixture/Parent<Lfixture/Local<+TT;>;>;";
    else if (Mutation == 7)
      Core.access.erase("final");
    else if (Mutation == 8)
      Target.generic_signature =
          "<U:Ljava/lang/Object;>(IJLfixture/Sink<-TU;>;)V";
    else if (Mutation == 9)
      Caller.reference.parameters[3] = "F";
    else if (Mutation == 10)
      Caller.instructions[6].registers[0] = 7;
    else if (Mutation == 11)
      Input[Input.size() - 3].superclass = "Lfixture/Missing;";
    else if (Mutation == 12)
      Local.access.insert("private");
    else
      Target.access.insert("varargs");
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

