std::vector<Class> capturedErasedConstructorClasses() {
  auto Input = erasedSuperclassConstructorClasses();
  auto &Base = Input[0];
  auto &Child = Input[1];
  auto &Target = Base.methods[0];
  Target.reference.parameters = {"I", "Lfixture/Sink;", "J"};
  Target.generic_signature = "(ILfixture/Sink<Ljava/lang/Object;>;J)V";
  Target.registers = 5;
  auto &Other = Base.methods[1];
  Other.reference.parameters = {"I", "Ljava/lang/Object;", "J"};
  Other.registers = 5;
  const FieldRef Capture{Child.name, "capture", "Ljava/lang/Object;"};
  Child.fields.push_back({Capture, {"public", "final"}, {}});
  auto &Init = Child.methods[0];
  Init.reference.parameters = {"Ljava/lang/Object;", "Lfixture/Sink;", "J"};
  Init.generic_signature =
      "(Ljava/lang/Object;Lfixture/Sink<-Lfixture/Child;>;J)V";
  Init.registers = 7;
  Init.instructions = {
      op(0, "iput-object", {3, 2}, {}, Capture),
      op(1, "const/4", {0}, int64_t(2)), op(2, "move-object/from16", {1, 4}),
      op(3, "invoke-direct", {2, 0, 1, 5, 6}, {}, Target.reference),
      op(4, "return-void")};
  Init.code_end = 5;
  auto Tag = klass("Lfixture/Tag;");
  Tag.access = {"public", "interface", "abstract"};
  Tag.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.interfaces = {Tag.name};
  Base.generic_signature =
      "Ljava/lang/Object;Lfixture/Tag<Ljava/lang/Object;>;";
  Child.interfaces = {Tag.name};
  Child.generic_signature = "Lfixture/Base;Lfixture/Tag<Ljava/lang/Object;>;";
  Input.push_back(Tag);
  return Input;
}

TEST(MobileDalvikJava, CapturedSuperclassConstructorsKeepEveryArgumentOrigin) {
  for (bool External : {false, true})
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Route);
      auto Input = capturedErasedConstructorClasses();
      if (External)
        for (auto &C : Input)
          if (C.name != "Lfixture/Child;") {
            C.external = true;
            for (auto &M : C.methods) {
              M.instructions.clear();
              M.registers = M.code_end = 0;
            }
          }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto R =
          Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
      std::string Text;
      for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
        Text += source(R, I);
      const auto Capture = Text.find("this.capture = ");
      ASSERT_NE(Capture, std::string::npos);
      const auto Super = Text.find("super(", Capture);
      EXPECT_LT(Capture, Super);
      EXPECT_NE(Text.find("fixture.Sink<java.lang.Object>)", Super),
                std::string::npos);
      EXPECT_NE(Text.find("fixture.Sink<? super fixture.Child> arg1"),
                std::string::npos);
    }
}

