std::vector<Class> inlinedCheckedInterfaceClasses(bool External, bool Copy,
                                                  std::string Result,
                                                  bool Self) {
  auto Required = method("read", {"Ljava/lang/Object;"}, Result, 0, {});
  Required.access = {"public", "abstract"};
  Required.generic_signature = "(TP;)" + Result;
  auto Api = klass("Lfixture/Api;", {Required});
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.external = External;
  const std::string Checked = Self ? "Lfixture/Core;" : "Lfixture/Box;";
  auto Box = klass(Checked);
  Box.access.insert("final");
  Box.fields.push_back({{Checked, "value", Result}, {"public"}, {}});
  const unsigned Argument = Copy ? 0 : 4;
  std::vector<Instruction> Code;
  if (Copy)
    Code.push_back(op(0, "move-object", {0, 4}));
  Code.push_back(op(1, "check-cast", {Argument}, {}, Checked));
  Code.push_back(op(2, Result == "I" ? "iget" : "iget-wide", {0, Argument}, {},
                    FieldRef{Checked, "value", Result}));
  Code.push_back(op(3, Result == "I" ? "return" : "return-wide", {0}));
  auto Bridge =
      method("read", {"Ljava/lang/Object;"}, Result, 5, std::move(Code));
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Bridge});
  Core.access.insert("final");
  Core.interfaces = {Api.name};
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Api<" + Checked + ">;";
  if (Self)
    Core.fields = std::move(Box.fields);
  std::vector<Class> Input = {Api, Core};
  if (!Self)
    Input.push_back(std::move(Box));
  return Input;
}

TEST(MobileDalvikJava, InlinedCheckedInterfaceBodiesKeepOriginalRuntimeSlots) {
  for (bool External : {false, true})
    for (bool Copy : {false, true})
      for (const std::string Result : {"I", "J", "D"})
        for (bool Self : {false, true})
          for (bool Link : {false, true})
            for (bool Reverse : {false, true}) {
              auto Input =
                  inlinedCheckedInterfaceClasses(External, Copy, Result, Self);
              const auto Bridge = Input[1].methods[0].reference;
              const auto Original = *Input[1].generic_signature;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R =
                  Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
              EXPECT_EQ(R.getInteger("method_count"), External ? 1 : 2);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getString("status"), "partial");
              const auto *Projections =
                  R.getArray("generic_signature_projections");
              ASSERT_NE(Projections, nullptr);
              ASSERT_EQ(Projections->size(), 1u);
              const auto *Projection = (*Projections)[0].getAsObject();
              ASSERT_NE(Projection, nullptr);
              EXPECT_EQ(Projection->getString("original_signature"), Original);
              const auto *Changes = Projection->getArray("changes");
              ASSERT_NE(Changes, nullptr);
              ASSERT_EQ(Changes->size(), 1u);
              EXPECT_EQ((*Changes)[0].getAsObject()->getString("kind"),
                        "checked-inlined-interface");
              EXPECT_EQ((*Changes)[0].getAsObject()->getString("scope_origin"),
                        Bridge.identity());
              const auto *Rows = R.getArray("methods");
              ASSERT_NE(Rows, nullptr);
              for (const auto &Value : *Rows) {
                const auto *Row = Value.getAsObject();
                ASSERT_NE(Row, nullptr);
                if (Row->getString("identity") == Bridge.identity()) {
                  EXPECT_EQ(Row->getString("projection_kind"),
                            "checked-inlined-interface-bridge");
                  EXPECT_EQ(Row->getString("source_identity"),
                            Bridge.identity());
                  EXPECT_EQ(Row->getString("inherited_contract"),
                            "Lfixture/Api;->read(Ljava/lang/Object;)" + Result);
                }
              }
            }
}

TEST(MobileDalvikJava, InlinedInterfaceContractsRequireExactOriginalEntryCast) {
  for (unsigned Mutation = 0; Mutation < 15; ++Mutation)
    for (bool External : {false, true})
      for (bool Link : {false, true}) {
        SCOPED_TRACE(Mutation);
        auto Input = inlinedCheckedInterfaceClasses(External, true, "I", false);
        auto &Api = Input[0];
        auto &Core = Input[1];
        auto &Bridge = Core.methods[0];
        if (Mutation == 0)
          Core.generic_signature =
              "Ljava/lang/Object;Lfixture/Api<Ljava/lang/String;>;";
        else if (Mutation == 1)
          Bridge.access.erase("bridge");
        else if (Mutation == 2)
          Bridge.access.erase("synthetic");
        else if (Mutation == 3)
          Core.access.erase("final");
        else if (Mutation == 4)
          Bridge.instructions[0].registers[1] = 3;
        else if (Mutation == 5)
          Bridge.instructions[1].registers[0] = 3;
        else if (Mutation == 6)
          Bridge.instructions[1].reference = std::string("Ljava/lang/String;");
        else if (Mutation == 7)
          Bridge.instructions[0] = op(0, "const", {0}, int64_t(0));
        else if (Mutation == 8) {
          auto Extra = method("extra", {}, "I", 0, {});
          Extra.access = {"public", "abstract"};
          Extra.reference.owner = Api.name;
          Api.methods.push_back(std::move(Extra));
        } else if (Mutation == 9)
          Api.methods[0].access.erase("abstract");
        else if (Mutation == 10)
          Api.methods[0].generic_signature = "<P:Ljava/lang/Object;>(TP;)I";
        else if (Mutation == 11)
          Api.methods[0].declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
        else if (Mutation == 12) {
          Input[2].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          Core.generic_signature = "Ljava/lang/Object;Lfixture/Api<Lfixture/"
                                   "Box<Ljava/lang/String;>;>;";
        } else if (Mutation == 13)
          Bridge.generic_signature = "(Ljava/lang/Object;)I";
        else {
          Core.access.insert("abstract");
          Bridge.instructions[1].target = 3;
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> checkedInlinedRecursiveBoundClasses(bool External, bool Copy,
                                                       std::string Variance) {
  auto Input = inlinedCheckedInterfaceClasses(External, Copy, "I", true);
  auto Holder = klass("Lfixture/Holder;");
  Holder.generic_signature =
      "<T::Lfixture/Api<" + Variance + "TT;>;>Ljava/lang/Object;";
  auto Identity = method("identity", {Holder.name}, Holder.name, 1,
                         {op(0, "return-object", {0})});
  Identity.generic_signature =
      "(Lfixture/Holder<Lfixture/Core;>;)Lfixture/Holder<Lfixture/Core;>;";
  auto Use = klass("Lfixture/Use;", {Identity});
  Field Value{{Use.name, "value", Holder.name}, {"public"}, {}};
  Value.generic_signature = "Lfixture/Holder<Lfixture/Core;>;";
  Use.fields.push_back(std::move(Value));
  Input.push_back(std::move(Holder));
  Input.push_back(std::move(Use));
  return Input;
}

