TEST(MobileDalvikJava, InheritedParentsRequireProvenSlotsAndFieldOwnership) {
  for (unsigned Mutation = 0; Mutation < 6; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = markerParentBridgeClasses();
    if (Mutation == 0) {
      auto M = method("extra", {}, "I", 0, {});
      M.access = {"public", "abstract"};
      M.reference.owner = Input[2].name;
      Input[2].methods.push_back(std::move(M));
    } else if (Mutation == 1) {
      Input[2].fields.push_back({{Input[2].name, "extra", "I"},
                                 {"public", "static", "final"},
                                 int64_t(1)});
    } else if (Mutation == 2) {
      auto Parent = klass("Lfixture/RootMarker;");
      Parent.access = {"public", "abstract", "interface"};
      Input[2].interfaces = {Parent.name};
      Input[2].generic_signature =
          "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/RootMarker;";
      // The raw ancestor is absent: no declaration proves an empty marker.
    } else if (Mutation == 3) {
      Input[1].generic_signature =
          "<U:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Contract<TU;>;";
    } else if (Mutation == 4) {
      Input[1].methods.pop_back();
    } else {
      Input[1].methods[1].instructions[0].reference =
          std::string("Ljava/lang/Integer;");
    }
    if (Mutation == 1) {
      // Static constants keep their declaring interface. The shared source
      // initializer owns their values and reports the extra compiler entry.
      for (bool Linked : {false, true}) {
        Budget B;
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), 3);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        const auto *Helpers = R.getArray("generated_source_helpers");
        ASSERT_NE(Helpers, nullptr);
        EXPECT_EQ(std::count_if(Helpers->begin(), Helpers->end(),
                                [&](const auto &Value) {
                                  const auto *Row = Value.getAsObject();
                                  return Row->getString("class") ==
                                             Input[2].name &&
                                         Row->getString("name") == "<clinit>" &&
                                         Row->getString("kind") ==
                                             "field-initializer";
                                }),
                  1);
      }
    } else
      rejected([&] { recover(Input); }, "generic");
  }
}

