TEST(MobileDalvikJava,
     ScopedPlainAncestorsRequireFullOriginalInheritanceProofs) {
  for (bool External : {false, true})
    for (bool Reverse : {false, true})
      for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Reverse);
        SCOPED_TRACE(Mutation);
        auto Input = genericParentScopedAncestorClasses(External, true);
        auto &Provided = Input[0].methods[1];
        auto &Inherited = Input[2].methods[0];
        if (Mutation == 0)
          Inherited.generic_signature =
              "<T:Ljava/lang/Object;>(Ljava/lang/Class<*>;TT;)TT;";
        else if (Mutation == 1)
          Provided.generic_signature =
              "<R:Ljava/lang/Object;>(Ljava/lang/Class<*>;TR;)TR;";
        else if (Mutation == 2)
          Input[2].methods[1].generic_signature =
              "(Lfixture/Carrier<Ljava/lang/String;Ljava/lang/Number;>;)"
              "Lfixture/Carrier<Ljava/lang/String;Ljava/lang/Number;>;";
        else if (Mutation == 3)
          Input[0].methods[2].generic_signature =
              "(Lfixture/Carrier<Ljava/lang/String;Ljava/lang/Number;>;)"
              "Lfixture/Carrier<Ljava/lang/String;Ljava/lang/Number;>;";
        else if (Mutation == 4)
          Inherited.access.insert("static");
        else if (Mutation == 5)
          Inherited.access.insert("final");
        else if (Mutation == 6)
          Provided.access = {"private"};
        else if (Mutation == 7)
          Inherited.generic_signature.reset();
        else if (Mutation == 8)
          Provided.generic_signature.reset();
        else if (Mutation == 9)
          Input[2].generic_signature =
              "<A:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/PlainApi;";
        else if (Mutation == 10)
          Input[2].interfaces = {"Lfixture/UnknownApi;"};
        else if (Mutation == 11) {
          Inherited.declared_throws = {"Ljava/lang/Exception;"};
          Inherited.generic_signature =
              *Inherited.generic_signature + "^Ljava/lang/Exception;";
        } else
          Input[1].methods.pop_back();
        if (Reverse) {
          std::reverse(Input.begin(), Input.end());
          for (auto &Owner : Input)
            std::reverse(Owner.methods.begin(), Owner.methods.end());
        }
        Budget B;
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      }
}

std::vector<Class> genericAncestorPlainContractClasses(bool External = false,
                                                       bool Default = false) {
  auto Input = genericAncestorMarkerChainClasses(External);
  auto Required = method("context", {}, "Ljava/lang/Object;", 0, {});
  Required.reference.owner = Input.back().name;
  Required.access = {"public", "abstract"};
  Input.back().methods.push_back(Required);
  Required.reference.owner = Input[1].name;
  Required.access = {"public"};
  Required.registers = 1;
  Required.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
  Required.code_end = 2;
  Input[1].methods.push_back(Required);
  if (Default) {
    auto Echo = method(
        "plainEcho", {"Ljava/lang/Object;"}, "Ljava/lang/Object;",
        External ? 0 : 2,
        External ? std::vector<Instruction>{}
                 : std::vector<Instruction>{op(0, "return-object", {1})});
    Echo.reference.owner = Input.back().name;
    Echo.access = {"public"};
    Input.back().methods.push_back(Echo);
  }
  return Input;
}

