TEST(MobileDalvikJava, GenericInterfaceAncestorsRequireProvenScopesAndEdges) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        transitiveInterfaceBridgeClasses(true, Mutation == 7 || Mutation == 12);
    auto &Root = Input[0];
    auto &Core = Input[1];
    auto &Middle =
        *std::find_if(Input.begin(), Input.end(), [](const Class &C) {
          return C.name == "Lfixture/Middle;";
        });
    switch (Mutation) {
    case 0:
      Core.methods.erase(Core.methods.begin() + 2);
      break;
    case 1:
      Core.methods[1].instructions[0].reference =
          std::string("Ljava/lang/String;");
      break;
    case 2:
      Root.methods[0].generic_signature = "<R:Ljava/lang/Object;>(TT;)TT;";
      break;
    case 3:
      Root.methods[0].access = {"public"};
      Root.methods[0].registers = 2;
      Root.methods[0].instructions = {op(0, "return-object", {1})};
      Root.methods[0].code_end = 1;
      Core.methods.erase(Core.methods.begin() + 1);
      break;
    case 4:
      Root.fields.push_back({{Root.name, "extra", "I"},
                             {"public", "static", "final"},
                             int64_t(1)});
      break;
    case 5:
      Middle.generic_signature =
          "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Ljava/lang/Object;"
          "Lfixture/Contract;";
      break;
    case 6:
      Middle.generic_signature =
          "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Ljava/lang/Object;"
          "Lfixture/Contract<TU;>;";
      break;
    case 7:
      Middle.generic_signature =
          "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Ljava/lang/Object;"
          "Lfixture/Left<TT;>;Lfixture/Right<TU;>;";
      break;
    case 8:
      Root.interfaces = {Middle.name};
      Root.generic_signature =
          "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Middle<TT;TT;>;";
      break;
    case 9:
      Input.erase(Input.begin());
      break;
    case 10:
      Root.access.erase("interface");
      break;
    case 11:
      Core.methods[0].generic_signature.reset();
      break;
    case 12:
      Root.interfaces = {"Lfixture/Right;"};
      Root.generic_signature =
          "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Right<TT;>;";
      for (auto &C : Input)
        if (has(C.access, "interface"))
          C.external = true;
      break;
    }
    if (Mutation == 4) {
      // Static constants keep their declaring interface. The shared source
      // initializer owns their values and reports the extra compiler entry.
      for (bool Linked : {false, true}) {
        Budget B;
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), 9);
        EXPECT_EQ(R.getInteger("projected_method_count"), 3);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        const auto *Helpers = R.getArray("generated_source_helpers");
        ASSERT_NE(Helpers, nullptr);
        EXPECT_EQ(std::count_if(Helpers->begin(), Helpers->end(),
                                [&](const auto &Value) {
                                  const auto *Row = Value.getAsObject();
                                  return Row->getString("class") == Root.name &&
                                         Row->getString("name") == "<clinit>" &&
                                         Row->getString("kind") ==
                                             "field-initializer";
                                }),
                  1);
      }
    } else
      rejected([&] { recover(Input); }, "generic");
  }
}

std::vector<Class> voidUnitBridgeClasses(bool Parameter = false) {
  auto Input = interfaceBridgeClasses();
  auto &Contract = Input[0];
  Contract.methods[0].reference.name = "invoke";
  if (!Parameter) {
    Contract.methods[0].reference.parameters.clear();
    Contract.methods[0].generic_signature = "()TT;";
  }
  auto &Core = Input[1];
  Core.access.insert("final");
  Core.generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Lkotlin/Unit;>;";
  auto &Target = Core.methods[0];
  Target.reference.name = "invoke";
  Target.reference.parameters = Parameter
                                    ? std::vector<std::string>{"Lkotlin/Unit;"}
                                    : std::vector<std::string>{};
  Target.reference.returns = "V";
  Target.instructions = {op(0, "return-void")};
  Target.code_end = 1;
  auto &Bridge = Core.methods[1];
  Bridge.reference.name = "invoke";
  if (!Parameter)
    Bridge.reference.parameters.clear();
  Bridge.registers = 3;
  Bridge.instructions =
      Parameter
          ? std::vector<Instruction>{op(0, "check-cast", {2}, {},
                                        std::string("Lkotlin/Unit;")),
                                     op(1, "invoke-virtual", {1, 2}, {},
                                        Target.reference),
                                     op(2, "sget-object", {0}, {},
                                        FieldRef{"Lkotlin/Unit;", "INSTANCE",
                                                 "Lkotlin/Unit;"}),
                                     op(3, "return-object", {0})}
          : std::vector<Instruction>{
                op(0, "invoke-virtual", {2}, {}, Target.reference),
                op(1, "sget-object", {0}, {},
                   FieldRef{"Lkotlin/Unit;", "INSTANCE", "Lkotlin/Unit;"}),
                op(2, "return-object", {0})};
  Bridge.code_end = Bridge.instructions.back().pc + 1;
  auto Unit = klass("Lkotlin/Unit;");
  Unit.external = true;
  Unit.access.insert("final");
  Unit.fields.push_back(
      {{Unit.name, "INSTANCE", Unit.name}, {"public", "static", "final"}, {}});
  Input.push_back(std::move(Unit));
  return Input;
}

std::vector<Class> rawReferenceUnitClasses(unsigned Count, bool External,
                                           bool Copy, bool Range,
                                           bool Signature) {
  auto Required =
      method("apply", std::vector<std::string>(Count, "Ljava/lang/Object;"),
             "Ljava/lang/Object;", 0, {});
  Required.access = {"public", "abstract"};
  std::string Formals = "<", Parameters = "(";
  for (unsigned I = 0; I < Count; ++I) {
    Formals += "P" + std::to_string(I) + ":Ljava/lang/Object;";
    Parameters += "TP" + std::to_string(I) + ";";
  }
  Required.generic_signature = Parameters + ")TR;";
  auto Api = klass("Lfixture/Api;", {Required});
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = Formals + "R:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.external = External;
  std::vector<std::string> Types;
  const std::vector<std::string> ReferenceTypes{
      "Ljava/lang/Throwable;", "Ljava/lang/Void;", "Lfixture/Context;"};
  for (unsigned I = 0; I < Count; ++I)
    Types.push_back(ReferenceTypes[I % ReferenceTypes.size()]);
  auto Target = method("apply", Types, "V", Count + 1, {op(0, "return-void")});
  Target.access = {"public", "final"};
  std::vector<Instruction> Code;
  const unsigned Self = Count + 1;
  if (Copy)
    Code.push_back(op(Code.size(), "move-object", {0, Self}));
  std::vector<unsigned> Words{Copy ? 0u : Self};
  for (unsigned I = 0; I < Count; ++I) {
    const unsigned Word = Copy ? I + 1 : Self + I + 1;
    if (Copy)
      Code.push_back(op(Code.size(), "move-object", {Word, Self + I + 1}));
    Code.push_back(op(Code.size(), "check-cast", {Word}, {}, Types[I]));
    Words.push_back(Word);
  }
  Code.push_back(op(Code.size(),
                    Range ? "invoke-virtual/range" : "invoke-virtual", Words,
                    {}, Target.reference));
  Code.push_back(op(Code.size(), "sget-object", {0}, {},
                    FieldRef{"Lkotlin/Unit;", "INSTANCE", "Lkotlin/Unit;"}));
  Code.push_back(op(Code.size(), "return-object", {0}));
  auto Bridge = method("apply", Required.reference.parameters,
                       "Ljava/lang/Object;", 2 * Count + 2, std::move(Code));
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Target, Bridge});
  Core.access.insert("final");
  Core.interfaces = {Api.name};
  if (Signature)
    Core.generic_signature = "Ljava/lang/Object;Lfixture/Api;";
  auto Unit = klass("Lkotlin/Unit;");
  Unit.external = true;
  Unit.access.insert("final");
  Unit.fields = {
      {{Unit.name, "INSTANCE", Unit.name}, {"public", "static", "final"}, {}}};
  auto Context = klass("Lfixture/Context;");
  auto Throwable = klass("Ljava/lang/Throwable;");
  auto Void = klass("Ljava/lang/Void;");
  Context.external = Throwable.external = Void.external = true;
  return {Api, Core, Unit, Context, Throwable, Void};
}

TEST(MobileDalvikJava, RawReferenceUnitBridgesKeepOriginalRawContracts) {
  for (unsigned Count : {1u, 3u, 22u})
    for (bool External : {false, true})
      for (bool Copy : {false, true})
        for (bool Range : {false, true})
          for (bool Signature : {false, true})
            for (bool Reverse : {false, true}) {
              if (Count > 4 && !Range)
                continue;
              SCOPED_TRACE(::testing::Message()
                           << Count << External << Copy << Range << Signature
                           << Reverse);
              auto Input = rawReferenceUnitClasses(Count, External, Copy, Range,
                                                   Signature);
              const auto Bridge = Input[1].methods[1].reference;
              const auto Target = Input[1].methods[0].reference;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto Classes = linkClasses(Input, B);
              const auto Generics = validateGenericSignatures(Classes, B);
              const auto Inheritance =
                  planGenericInheritance(Classes, Generics, B);
              ASSERT_TRUE(Inheritance.retained_plain_bridges.contains(Bridge));
              EXPECT_EQ(Inheritance.retained_plain_bridges.at(Bridge).target,
                        Target);
              EXPECT_FALSE(Inheritance.void_unit_targets.contains(Target));
              const auto Report = recoverJava(Classes, B);
              EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(Report.getInteger("projected_method_count"), 1);
              EXPECT_FALSE(Report.getArray("generic_signature_projections"));
              const auto *Rows = Report.getArray("methods");
              ASSERT_NE(Rows, nullptr);
              bool Found = false;
              for (const auto &Item : *Rows) {
                const auto *Row = Item.getAsObject();
                if (Row && Row->getString("identity") == Bridge.identity()) {
                  Found = true;
                  EXPECT_EQ(Row->getString("projection_kind"),
                            "raw-reference-unit-bridge");
                  EXPECT_EQ(Row->getString("source_identity"),
                            Bridge.identity());
                  EXPECT_EQ(Row->getString("bridge_target"), Target.identity());
                  EXPECT_EQ(Row->getString("result_field"),
                            "Lkotlin/Unit;->INSTANCE:Lkotlin/Unit;");
                }
              }
              EXPECT_TRUE(Found);
            }
}

TEST(MobileDalvikJava, RawReferenceUnitBridgesRejectIncompleteForwarding) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = rawReferenceUnitClasses(3, false, false, true, true);
    auto &Core = Input[1];
    auto &Target = Core.methods[0];
    auto &Bridge = Core.methods[1];
    if (Mutation == 0)
      Core.access.erase("final");
    else if (Mutation == 1)
      Bridge.access.erase("synthetic");
    else if (Mutation == 2)
      Bridge.instructions[0].reference = "Ljava/lang/Object;";
    else if (Mutation == 3)
      std::swap(Bridge.instructions[0].registers,
                Bridge.instructions[1].registers);
    else if (Mutation == 4)
      Bridge.instructions[3].registers[1] = Bridge.instructions[3].registers[2];
    else if (Mutation == 5)
      Bridge.instructions[4].reference =
          FieldRef{"Lkotlin/Unit;", "OTHER", "Lkotlin/Unit;"};
    else if (Mutation == 6) {
      std::swap(Bridge.instructions[3], Bridge.instructions[4]);
      Bridge.instructions[3].pc = 3;
      Bridge.instructions[4].pc = 4;
    } else if (Mutation == 7)
      Bridge.instructions.back().registers = {5};
    else if (Mutation == 8)
      Target.access.insert("static");
    else if (Mutation == 9)
      Target.declared_throws =
          std::vector<std::string>{"Ljava/lang/Exception;"};
    else if (Mutation == 10)
      Input[2].fields[0].access.erase("final");
    else if (Mutation == 11)
      Input[0].methods[0].generic_signature = "(TUnknown;TP1;TP2;)TR;";
    else
      Core.generic_signature =
          "Ljava/lang/Object;Lfixture/Api<Ljava/lang/Object;Ljava/lang/"
          "Object;Ljava/lang/Object;Ljava/lang/Object;>;";
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> mixedRawUnitClasses(unsigned Count, bool External, bool Copy,
                                       bool Range, bool Signature,
                                       unsigned Pattern) {
  auto Input = rawReferenceUnitClasses(Count, External, Copy, Range, Signature);
  auto &Target = Input[1].methods[0];
  auto &Bridge = Input[1].methods[1];
  for (unsigned I = 0; I < Count; ++I)
    if ((Pattern == 0 && I + 1 == Count) || (Pattern == 1 && I == 0) ||
        (Pattern == 2 && I % 2 == 1) || Pattern == 3)
      Target.reference.parameters[I] = "I";
  std::vector<Instruction> Code;
  const unsigned Self = Count + 1;
  if (Copy)
    Code.push_back(op(Code.size(), "move-object", {0, Self}));
  std::vector<unsigned> Words{Copy ? 0u : Self};
  for (unsigned I = 0; I < Count; ++I) {
    const unsigned Word = Copy ? I + 1 : Self + I + 1;
    if (Copy)
      Code.push_back(op(Code.size(), "move-object", {Word, Self + I + 1}));
    const auto &Type = Target.reference.parameters[I];
    Code.push_back(op(Code.size(), "check-cast", {Word}, {},
                      Type == "I" ? "Ljava/lang/Number;" : Type));
    if (Type == "I") {
      Code.push_back(
          op(Code.size(), Range ? "invoke-virtual/range" : "invoke-virtual",
             {Word}, {}, MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}));
      Code.push_back(op(Code.size(), "move-result", {Word}));
    }
    Words.push_back(Word);
  }
  Code.push_back(op(Code.size(),
                    Range ? "invoke-virtual/range" : "invoke-virtual", Words,
                    {}, Target.reference));
  Code.push_back(op(Code.size(), "sget-object", {0}, {},
                    FieldRef{"Lkotlin/Unit;", "INSTANCE", "Lkotlin/Unit;"}));
  Code.push_back(op(Code.size(), "return-object", {0}));
  Bridge.instructions = std::move(Code);
  Bridge.code_end = Bridge.instructions.size();
  auto IntValue = method("intValue", {}, "I", 0, {});
  IntValue.access = {"public", "abstract"};
  auto Number = klass("Ljava/lang/Number;", {IntValue});
  Number.access.insert("abstract");
  Number.external = true;
  auto Integer = klass("Ljava/lang/Integer;");
  Integer.access.insert("final");
  Integer.superclass = Number.name;
  Integer.external = true;
  Input.push_back(Number);
  Input.push_back(Integer);
  return Input;
}

TEST(MobileDalvikJava, MixedRawUnitBridgesShareCastUnboxAndSingletonProof) {
  for (unsigned Count : {3u, 22u})
    for (bool External : {false, true})
      for (bool Copy : {false, true})
        for (bool Range : {false, true})
          for (bool Signature : {false, true})
            for (unsigned Pattern = 0; Pattern < 4; ++Pattern)
              for (unsigned Route = 0; Route < 3; ++Route) {
                if (Count > 4 && !Range)
                  continue;
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Count, External, Copy, Range, Signature, Pattern, Route}));
                auto Input = mixedRawUnitClasses(Count, External, Copy, Range,
                                                 Signature, Pattern);
                const auto Target = Input[1].methods[0].reference;
                const auto Bridge = Input[1].methods[1].reference;
                std::set<size_t> Indices;
                for (size_t I = 0; I < Target.parameters.size(); ++I)
                  if (Target.parameters[I] == "I")
                    Indices.insert(I);
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                const auto Signatures = validateGenericSignatures(Classes, B);
                const auto Plan =
                    planGenericInheritance(Classes, Signatures, B);
                ASSERT_TRUE(Plan.retained_plain_bridges.contains(Bridge));
                const auto &Proof = Plan.retained_plain_bridges.at(Bridge);
                EXPECT_EQ(Proof.target, Target);
                EXPECT_TRUE(Proof.raw_unit_result.has_value());
                EXPECT_EQ(Proof.raw_indexed_parameters, Indices);
                EXPECT_EQ(
                    Proof.unbox_method,
                    (MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}));
                EXPECT_FALSE(Plan.void_unit_targets.contains(Target));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count"), 1);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              }
}

TEST(MobileDalvikJava,
     MixedRawUnitBridgesRejectChangedOriginsOrderAndConversions) {
  for (unsigned Mutation = 0; Mutation < 18; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = mixedRawUnitClasses(3, false, false, true, false, 0);
      auto &Target = Input[1].methods[0];
      auto &Bridge = Input[1].methods[1];
      auto &Code = Bridge.instructions;
      switch (Mutation) {
      case 0:
        Code[2].reference = "Ljava/lang/Integer;";
        break;
      case 1:
        std::get<MethodRef>(Code[3].reference).name = "longValue";
        break;
      case 2:
        std::get<MethodRef>(Code[3].reference).owner = "Ljava/lang/Integer;";
        break;
      case 3:
        Code[3].registers = {5};
        break;
      case 4:
        Code[4].opcode = "move-result-wide";
        break;
      case 5:
        Code[5].registers[3] = 5;
        break;
      case 6:
        Code[6].reference = FieldRef{"Lkotlin/Unit;", "OTHER", "Lkotlin/Unit;"};
        break;
      case 7:
        std::swap(Code[5], Code[6]);
        Code[5].pc = 5;
        Code[6].pc = 6;
        break;
      case 8:
        Code[0].reference = "Ljava/lang/Object;";
        break;
      case 9:
        std::swap(Code[0].registers, Code[1].registers);
        break;
      case 10:
        Code[7].registers = {4};
        break;
      case 11:
        Target.generic_signature = Target.reference.signature();
        break;
      case 12:
        Target.access.insert("static");
        break;
      case 13:
        Target.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 14:
        Bridge.access.erase("synthetic");
        break;
      case 15:
        Input.back().access.erase("final");
        break;
      case 16:
        Input[6].methods[0].access.insert("static");
        break;
      case 17:
        Input[2].fields[0].access.erase("final");
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      if (Route)
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> namedScopedVoidUnitClasses(std::string Name, bool External) {
  auto Input = voidUnitBridgeClasses(true);
  auto &Contract = Input[0];
  Contract.external = External;
  Contract.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;R:Ljava/lang/Object;>"
      "Ljava/lang/Object;";
  Contract.methods[0].reference.name = Name;
  Contract.methods[0].reference.parameters = {"Ljava/lang/Object;",
                                              "Ljava/lang/Object;"};
  Contract.methods[0].generic_signature = "(TA;TB;)TR;";
  auto &Core = Input[1];
  Core.superclass = "Lfixture/Parent;";
  Core.generic_signature =
      "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Lfixture/Parent<TT;>;"
      "Lfixture/Contract<TT;Ljava/lang/Throwable;Lkotlin/Unit;>;";
  auto &Target = Core.methods[0];
  Target.reference.name = Name;
  Target.reference.parameters = {"Ljava/lang/Object;", "Ljava/lang/Throwable;"};
  Target.generic_signature = "(TT;Ljava/lang/Throwable;)V";
  Target.registers = 3;
  auto &Bridge = Core.methods[1];
  Bridge.reference.name = Name;
  Bridge.reference.parameters = Contract.methods[0].reference.parameters;
  Bridge.registers = 4;
  Bridge.instructions = {
      op(0, "move-object", {0, 3}),
      op(1, "check-cast", {0}, {}, std::string("Ljava/lang/Throwable;")),
      op(2, "invoke-virtual", {1, 2, 0}, {}, Target.reference),
      op(3, "sget-object", {0}, {},
         FieldRef{"Lkotlin/Unit;", "INSTANCE", "Lkotlin/Unit;"}),
      op(4, "return-object", {0})};
  Bridge.code_end = 5;
  auto Forward = Target;
  Forward.reference.name = "forward";
  Forward.instructions = {
      op(0, "invoke-virtual", {0, 1, 2}, {}, Target.reference),
      op(1, "return-void")};
  Forward.code_end = 2;
  Core.methods.push_back(Forward);
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Collision =
      method("__neverdVoidBridgeTarget", {}, "V", 1, {op(0, "return-void")});
  Collision.access = {"public"};
  auto Parent = klass("Lfixture/Parent;", {Init, Collision});
  Parent.external = External;
  Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  if (External)
    for (auto &Member : Parent.methods) {
      Member.instructions.clear();
      Member.registers = Member.code_end = 0;
    }
  Init.reference.owner = Core.name;
  Init.instructions[0].reference = Parent.methods[0].reference;
  Core.methods.push_back(Init);
  Input.push_back(Parent);
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  Input.push_back(Throwable);
  return Input;
}

TEST(MobileDalvikJava,
     NamedScopedVoidUnitBridgesKeepCompleteCallAndResultProof) {
  for (const auto &Name :
       {"apply", "accept", "combine", "__neverdVoidBridgeTarget"})
    for (bool External : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = namedScopedVoidUnitClasses(Name, External);
          if (Reverse) {
            for (auto &Owner : Input)
              std::reverse(Owner.methods.begin(), Owner.methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 2);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          unsigned Projections = 0;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("status") != "source-projected")
              continue;
            ++Projections;
            EXPECT_NE(Row->getArray("metadata_differences"), nullptr);
            if (Row->getString("projection_kind") == "void-unit-target")
              EXPECT_EQ(Row->getString("bridge_source_name"),
                        "__neverdVoidBridgeTarget_");
          }
          EXPECT_EQ(Projections, 2u);
        }
}

TEST(MobileDalvikJava,
     NamedScopedVoidUnitBridgesRejectUnprovedNamesAndEffects) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
        SCOPED_TRACE(Mutation);
        auto Input = namedScopedVoidUnitClasses(
            Mutation == 11 ? "wait" : "apply", External);
        auto &Core = Input[1];
        auto &Target = Core.methods[0];
        auto &Bridge = Core.methods[1];
        if (Mutation == 0)
          Core.access.erase("final");
        else if (Mutation == 1)
          Target.generic_signature = "(TU;Ljava/lang/Throwable;)V";
        else if (Mutation == 2)
          Bridge.access.erase("synthetic");
        else if (Mutation == 3)
          Bridge.instructions[2].registers = {0, 2, 0};
        else if (Mutation == 4)
          Bridge.instructions[2].registers = {1, 0, 0};
        else if (Mutation == 5)
          Bridge.instructions[1].reference = std::string("Ljava/lang/String;");
        else if (Mutation == 6) {
          std::swap(Bridge.instructions[2], Bridge.instructions[3]);
          for (unsigned I = 0; I < Bridge.instructions.size(); ++I)
            Bridge.instructions[I].pc = I;
        } else if (Mutation == 7)
          Input[2].fields[0].access.erase("final");
        else if (Mutation == 8)
          Core.superclass = "Lfixture/Missing;";
        else if (Mutation == 9) {
          auto Conflicting = Target;
          Conflicting.reference.owner = Input[3].name;
          Conflicting.generic_signature = "(TP;Ljava/lang/Throwable;)V";
          if (External) {
            Conflicting.instructions.clear();
            Conflicting.registers = Conflicting.code_end = 0;
          }
          Input[3].methods.push_back(Conflicting);
        } else if (Mutation == 10)
          Target.generic_signature =
              "<M:Ljava/lang/Object;>(TM;Ljava/lang/Throwable;)V";
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava, VoidUnitBridgeKeepsFieldReadAndTypedCallsSeparate) {
  for (bool Parameter : {false, true}) {
    for (unsigned Variant = 0; Variant < 4; ++Variant) {
      const bool Link = Variant & 1;
      auto Input = voidUnitBridgeClasses(Parameter);
      const auto Target = Input[1].methods[0].reference;
      auto Params = Target.parameters;
      Params.insert(Params.begin(), Input[1].name);
      Input[1].methods.push_back(
          method("call", Params, "V", Parameter ? 2 : 1,
                 {op(0, "invoke-virtual",
                     Parameter ? std::vector<unsigned>{0, 1}
                               : std::vector<unsigned>{0},
                     {}, Target),
                  op(1, "return-void")}));
      Input[1].methods.back().reference.owner = Input[1].name;
      Input[1].methods.push_back(method("__neverdVoidBridgeTarget", {}, "V", 0,
                                        {op(0, "return-void")}));
      Input[1].methods.back().reference.owner = Input[1].name;
      if (Variant & 2)
        std::reverse(Input[1].methods.begin(), Input[1].methods.end());
      Budget B;
      auto R = Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("method_count"), 5);
      EXPECT_EQ(R.getInteger("projected_method_count"), 2);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      const auto Text = source(R, 1);
      EXPECT_NE(Text.find("void __neverdVoidBridgeTarget_("),
                std::string::npos);
      EXPECT_NE(Text.find("kotlin.Unit invoke("), std::string::npos);
      EXPECT_NE(Text.find(".__neverdVoidBridgeTarget_("), std::string::npos);
      EXPECT_NE(Text.find(".INSTANCE"), std::string::npos);
      const auto *Rows = R.getArray("methods");
      ASSERT_NE(Rows, nullptr);
      unsigned Projections = 0;
      for (const auto &Value : *Rows) {
        const auto *Row = Value.getAsObject();
        ASSERT_NE(Row, nullptr);
        if (Row->getString("status") == "source-projected") {
          ++Projections;
          EXPECT_TRUE(Row->getString("source_identity"));
          ASSERT_NE(Row->getArray("metadata_differences"), nullptr);
        }
      }
      EXPECT_EQ(Projections, 2u);
    }
  }
}

TEST(MobileDalvikJava, VoidUnitBridgeRejectsMissingProofAndChangedEffects) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    auto Input = voidUnitBridgeClasses();
    auto &Core = Input[1];
    auto &Bridge = Core.methods[1];
    if (Mutation == 0)
      Core.access.erase("final");
    else if (Mutation == 1)
      Input.pop_back();
    else if (Mutation == 2)
      Input[2].fields[0].access.erase("final");
    else if (Mutation == 3)
      Bridge.instructions[1].reference =
          FieldRef{"Lkotlin/Unit;", "OTHER", "Lkotlin/Unit;"};
    else if (Mutation == 4)
      Bridge.instructions[2].registers = {2};
    else if (Mutation == 5)
      std::swap(Bridge.instructions[0], Bridge.instructions[1]);
    else if (Mutation == 6)
      Core.methods[0].generic_signature = "<U:Ljava/lang/Object;>()V";
    else if (Mutation == 7) {
      auto Parent = klass("Lfixture/Parent;", {Core.methods[0]});
      Core.superclass = Parent.name;
      Core.generic_signature =
          "Lfixture/Parent;Lfixture/Contract<Lkotlin/Unit;>;";
      Input.push_back(std::move(Parent));
    } else if (Mutation == 8) {
      Bridge.instructions.insert(Bridge.instructions.begin(),
                                 op(0, "const", {0}, int64_t(1)));
      for (size_t I = 0; I < Bridge.instructions.size(); ++I)
        Bridge.instructions[I].pc = I;
      Bridge.code_end = Bridge.instructions.size();
    } else {
      auto Inherited = Core.methods[0];
      Inherited.reference.returns = Mutation == 12 ? "Ljava/lang/String;" : "V";
      Inherited.access = Mutation == 9    ? Access{"public", "static"}
                         : Mutation == 10 ? Access{"public", "final"}
                                          : Access{"public"};
      if (Mutation == 12) {
        Inherited.instructions = {op(0, "const", {0}, int64_t(0)),
                                  op(1, "return-object", {0})};
        Inherited.code_end = 2;
      }
      auto Parent = klass("Lfixture/Parent;", {Inherited});
      Core.superclass = Parent.name;
      Core.generic_signature =
          "Lfixture/Parent;Lfixture/Contract<Lkotlin/Unit;>;";
      Input.push_back(std::move(Parent));
    }
    rejected([&] { recover(Input); }, "generic");
  }
}

