std::vector<Class> parameterizedBridgeClasses(bool NestedMember = false) {
  auto Input = interfaceBridgeClasses();
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Core = Input[1];
  Core.generic_signature =
      NestedMember ? "Ljava/lang/Object;Lfixture/Contract<Ljava/lang/String;>;"
                   : "Ljava/lang/Object;Lfixture/Contract<Lfixture/Box<Ljava/"
                     "lang/String;>;>;";
  auto &Target = Core.methods[0];
  Target.reference.parameters = {Box.name};
  Target.reference.returns = Box.name;
  Target.generic_signature = "(Lfixture/Box<Ljava/lang/String;>;)"
                             "Lfixture/Box<Ljava/lang/String;>;";
  if (NestedMember) {
    Input[0].methods[0].reference.parameters = {Box.name};
    Input[0].methods[0].reference.returns = Box.name;
    Input[0].methods[0].generic_signature =
        "(Lfixture/Box<TT;>;)Lfixture/Box<TT;>;";
    Core.methods.pop_back();
  } else {
    Core.methods[1].instructions[0].reference = Box.name;
    Core.methods[1].instructions[1].reference = Target.reference;
  }
  Input.push_back(std::move(Box));
  return Input;
}

