TEST(MobileDalvikJava, OwnedClassArgumentsPreserveGenericOverrides) {
  for (unsigned Variant = 0; Variant < 4; ++Variant) {
    for (bool Link : {false, true}) {
      auto Input = ownedArgumentClasses();
      if (Variant == 1 || Variant == 2) {
        Input[0].methods[0].generic_signature =
            Variant == 1 ? "(TP;)Lfixture/Cell<TP;+TP;>;"
                         : "(TP;)Lfixture/Cell<TP;-TP;>;";
        Input[1].methods[0].generic_signature = "(TI;)Lfixture/Cell<TI;TI;>;";
      } else if (Variant == 3) {
        Input[0].methods[0].reference.returns = "[Lfixture/Cell;";
        Input[0].methods[0].generic_signature = "(TP;)[Lfixture/Cell<TP;*>;";
        Input[1].methods[0].reference.returns = "[Lfixture/Cell;";
        Input[1].methods[0].generic_signature = "(TI;)[Lfixture/Cell<TI;TO;>;";
      }
      Budget B;
      auto R = Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getString("status"), "recovered");
      EXPECT_EQ(R.getInteger("method_count"), 2);
      EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
      const auto Text = source(R, 2);
      EXPECT_NE(Text.find("implements fixture.Contract<I>"), std::string::npos);
      EXPECT_NE(Text.find("echo(I arg0)"), std::string::npos);
      EXPECT_NE(Text.find(Variant == 1 || Variant == 2 ? "fixture.Cell<I, I>"
                                                       : "fixture.Cell<I, O>"),
                std::string::npos);
    }
  }
}

