TEST(MobileDalvikJava, ScopedRawClassParametersRequireCompleteOriginalBridges) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Link);
        SCOPED_TRACE(Mutation);
        auto Input =
            scopedRawClassParameterClasses(External, false, Mutation >= 11);
        auto &Parent = Input[0];
        auto &Core = Input[1];
        auto &Target = Core.methods[1];
        auto &Bridge = Core.methods[2];
        if (Mutation == 0)
          Core.methods.pop_back();
        else if (Mutation == 1)
          Bridge.access.erase("synthetic");
        else if (Mutation == 2)
          Bridge.instructions[0].reference = std::string("Lfixture/View;");
        else if (Mutation == 3)
          Bridge.instructions[1].registers = {1, 4, 3, 2};
        else if (Mutation == 4)
          Target.access.insert("static");
        else if (Mutation == 5)
          Target.access = {"private"};
        else if (Mutation == 6)
          Parent.methods[1].access.insert("final");
        else if (Mutation == 7)
          Parent.methods[1].generic_signature =
              "<M:Ljava/lang/Object;>(Ljava/lang/Object;TP;Ljava/lang/"
              "Object;)Z";
        else if (Mutation == 8)
          Target.generic_signature =
              "(Ljava/lang/Object;TT;Ljava/lang/Object;)Z";
        else if (Mutation == 9)
          Target.declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
        else if (Mutation == 10)
          Input.erase(Input.begin() + 3);
        else if (Mutation == 11)
          Target.instructions[0].registers = {1, 4, 3, 2};
        else if (Mutation == 12) {
          for (auto &Instruction : Target.instructions)
            ++Instruction.pc;
          Target.instructions.insert(Target.instructions.begin(),
                                     op(0, "const/4", {2}, int64_t(0)));
          ++Target.code_end;
        } else {
          Target.instructions[0].registers[2] = 2;
        }
        if (Mutation == 8) {
          // A complete matching Signature is legal; use a full plain-parameter
          // change with the same runtime erasure instead of deleting metadata.
          Parent.methods[1].reference.parameters[0] = "Ljava/lang/Class;";
          Parent.methods[1].generic_signature =
              "(Ljava/lang/Class<*>;TP;Ljava/lang/Object;)Z";
          Target.reference.parameters[0] = "Ljava/lang/Class;";
          Target.generic_signature =
              "(Ljava/lang/Class<TT;>;TT;Ljava/lang/Object;)Z";
          Bridge.reference.parameters[0] = "Ljava/lang/Class;";
          Bridge.instructions[1].reference = Target.reference;
          auto ClassType = klass("Ljava/lang/Class;");
          ClassType.external = true;
          ClassType.generic_signature =
              "<C:Ljava/lang/Object;>Ljava/lang/Object;";
          Input.push_back(ClassType);
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

