std::vector<Class> upcastResultBridgeClasses() {
  auto Base = klass("Lfixture/Base;");
  Base.external = true;
  auto Leaf = klass("Lfixture/Leaf;");
  Leaf.external = true;
  Leaf.superclass = Base.name;
  auto Create = method("create", {}, Base.name, 0, {});
  Create.access = {"public", "abstract"};
  Create.generic_signature = "()TT;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init, Create});
  Parent.access.insert("abstract");
  Parent.generic_signature = "<T:Lfixture/Base;>Ljava/lang/Object;";
  auto Target =
      method("create", {}, Leaf.name, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.access = {"public"};
  auto Bridge = method("create", {}, Base.name, 2, {});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Target, Bridge});
  Core.superclass = Parent.name;
  Core.generic_signature = "Lfixture/Parent<Lfixture/Leaf;>;";
  Core.methods[1].instructions = {
      op(0, "invoke-virtual", {1}, {}, Core.methods[0].reference),
      op(1, "move-result-object", {0}), op(2, "check-cast", {0}, {}, Base.name),
      op(3, "return-object", {0})};
  Core.methods[1].code_end = 4;
  return {Parent, Core, Base, Leaf};
}

