std::vector<Class> superclassIntegerGetterClasses() {
  auto Input = superclassGetterResultClasses();
  for (auto &C : Input)
    for (auto &M : C.methods)
      if (M.reference.name != "<init>") {
        M.reference.returns = "I";
        M.generic_signature.reset();
        for (auto &Op : M.instructions) {
          if (auto *Call = std::get_if<MethodRef>(&Op.reference))
            Call->returns = "I";
          if (Op.opcode == "move-result-object")
            Op.opcode = "move-result";
          if (Op.opcode == "return-object")
            Op.opcode = "return";
        }
      }
  return Input;
}

