std::vector<Class> closedArraySuperConstructorClasses(bool Range = false,
                                                      bool External = false) {
  auto Init = method(
      "<init>", {"Ljava/lang/Object;", "I", "I", "[Ljava/lang/Object;"}, "V", 5,
      {op(0, "invoke-direct", {0}, {},
          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Ljava/lang/Object;II[TT;)V";
  auto Other = Init;
  Other.reference.parameters.back() = "Lfixture/List;";
  Other.generic_signature = "(Ljava/lang/Object;IILfixture/List<TT;>;)V";
  auto Parent = klass("Lfixture/Parent;", {Init, Other});
  Parent.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.external = External;
  if (External)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const FieldRef Capture{"Lfixture/Core;", "capture", "Ljava/lang/Object;"};
  auto Constructor = method(
      "<init>",
      Range
          ? std::vector<std::string>{"Ljava/lang/Object;", "I", "I",
                                     "[Lfixture/Token;", "Ljava/lang/Object;"}
          : std::vector<std::string>{"Ljava/lang/Object;", "Ljava/lang/Object;",
                                     "I", "I", "[Lfixture/Token;"},
      "V", 7,
      {op(0, "iput-object", {Range ? 6u : 2u, 1}, {}, Capture),
       op(1, Range ? "invoke-direct/range" : "invoke-direct",
          Range ? std::vector<unsigned>{1, 2, 3, 4, 5}
                : std::vector<unsigned>{1, 3, 4, 5, 6},
          {}, Parent.methods[0].reference),
       op(2, "return-void")});
  Constructor.access = {"public", "constructor"};
  auto Child = klass(Capture.owner, {Constructor});
  Child.superclass = Parent.name;
  Child.generic_signature = "Lfixture/Parent<Lfixture/Token;>;";
  Child.fields.push_back({Capture, {"public", "final"}, {}});
  auto Token = klass("Lfixture/Token;"), List = klass("Lfixture/List;");
  Token.access = List.access = {"public", "interface", "abstract"};
  List.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Parent, Child, Token, List};
}

