std::vector<Class> nominalSuperConstructorClasses(unsigned Dependencies,
                                                  unsigned Kind, unsigned Frame,
                                                  bool Wide, bool OtherArity) {
  auto Init = method("<init>",
                     Wide ? std::vector<std::string>{"Ljava/lang/Object;", "J"}
                          : std::vector<std::string>{"Ljava/lang/Object;"},
                     "V", Wide ? 4 : 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = Wide ? "(TT;J)V" : "(TT;)V";
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  if (OtherArity) {
    auto Other = method("<init>", {}, "V", 1, Init.instructions);
    Other.reference.owner = Parent.name;
    Other.access = Init.access;
    Parent.methods.push_back(Other);
  }
  Parent.external = Dependencies & 1;
  if (Parent.external)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const bool Range = Frame & 1, Copies = Frame & 2;
  const unsigned Self = (Range ? 32 : 0) + (Copies ? 4 : 0);
  std::vector<Instruction> Code;
  if (Copies) {
    Code.push_back(op(0, "move-object/from16", {0, Self}));
    Code.push_back(op(1, "move-object/from16", {1, Self + 1}));
    if (Wide)
      Code.push_back(op(2, "move-wide/from16", {2, Self + 2}));
  }
  const unsigned Receiver = Copies ? 0 : Self;
  std::vector<unsigned> Arguments{Receiver, Receiver + 1};
  if (Wide) {
    Arguments.push_back(Receiver + 2);
    Arguments.push_back(Receiver + 3);
  }
  Code.push_back(op(Code.size(),
                    Range ? "invoke-direct/range" : "invoke-direct", Arguments,
                    {}, Parent.methods[0].reference));
  Code.push_back(op(Code.size(), "return-void"));
  auto Caller = method("<init>",
                       Wide ? std::vector<std::string>{"Lfixture/Token;", "J"}
                            : std::vector<std::string>{"Lfixture/Token;"},
                       "V", Self + (Wide ? 4 : 2), Code);
  Caller.access = Init.access;
  auto Child = klass("Lfixture/Core;", {Caller});
  Child.superclass = Parent.name;
  Child.generic_signature = "Lfixture/Parent<Lfixture/Token;>;";
  auto Token = klass("Lfixture/Token;");
  if (Kind)
    Token.access.insert("abstract");
  if (Kind == 2)
    Token.access.insert("interface");
  Token.external = Dependencies & 2;
  return {Parent, Child, Token};
}

TEST(MobileDalvikJava, NominalSuperConstructorsKeepDescriptorOnlyBindings) {
  for (unsigned Dependencies = 0; Dependencies < 4; ++Dependencies)
    for (unsigned Kind = 0; Kind < 3; ++Kind)
      for (unsigned Frame = 0; Frame < 4; ++Frame)
        for (bool Wide : {false, true})
          for (bool OtherArity : {false, true})
            for (bool Linked : {false, true}) {
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  Dependencies, Kind, Frame, Wide, OtherArity, Linked}));
              auto Input = nominalSuperConstructorClasses(
                  Dependencies, Kind, Frame, Wide, OtherArity);
              const auto Caller = Input[1].methods[0].reference;
              const auto Target = Input[0].methods[0].reference;
              EXPECT_FALSE(Input[1].methods[0].generic_signature);
              if (Linked)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Linked)
                Classes = linkClasses(Input, B);
              else
                for (auto &C : Input) {
                  const auto Name = C.name;
                  Classes.emplace(Name, std::move(C));
                }
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
              EXPECT_EQ(Plans.superclass_call_declarations.at({Caller, Target}),
                        Target);
              EXPECT_FALSE(Plans.methods.contains(Caller));
              const auto &Contract =
                  Plans.superclass_calls.at({Caller, Target});
              ASSERT_EQ(Contract.parameters.size(), Wide ? 2u : 1u);
              EXPECT_EQ(Contract.types.at(Contract.parameters[0]).erasure,
                        "Lfixture/Token;");
              if (Wide)
                EXPECT_EQ(Contract.types.at(Contract.parameters[1]).erasure,
                          "J");
              EXPECT_FALSE(
                  Classes.at(Caller.owner).methods[0].generic_signature);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 8);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_FALSE(R.getArray("class_source_bindings"));
              EXPECT_NE(source(R).find("super(((fixture.Token)"),
                        std::string::npos);
            }
}

TEST(MobileDalvikJava, NominalSuperConstructorsRejectGuessedTypesAndOrigins) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
      for (bool Linked : {false, true}) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Linked}));
        auto Input =
            nominalSuperConstructorClasses(External ? 3 : 0, 0, 3, true, false);
        auto &Parent = Input[0], &Child = Input[1], &Token = Input[2];
        auto &Caller = Child.methods[0];
        auto &Code = Caller.instructions;
        switch (Mutation) {
        case 0:
          Caller.reference.parameters[0] = "Ljava/lang/Object;";
          break;
        case 1:
          Input.pop_back();
          break;
        case 2:
          Token.access.erase("public");
          break;
        case 3:
          Token.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 4:
          Token.inner_class_present = true;
          Token.inner_name = "Token";
          Token.enclosing = Child.name;
          break;
        case 5:
          Child.generic_signature = "Lfixture/Parent<Ljava/lang/String;>;";
          break;
        case 6:
          Parent.generic_signature =
              "<T:Ljava/lang/CharSequence;>Ljava/lang/Object;";
          break;
        case 7:
          Parent.generic_signature.reset();
          break;
        case 8:
          Parent.methods[0].generic_signature = "<X:Ljava/lang/Object;>(TX;J)V";
          break;
        case 9: {
          auto Other = Parent.methods[0];
          Other.reference.parameters[0] = "Ljava/lang/String;";
          Other.generic_signature.reset();
          Parent.methods.push_back(Other);
          break;
        }
        case 10:
          Parent.methods[0].access.insert("varargs");
          break;
        case 11: {
          auto Other = method("<init>", {"[Ljava/lang/Object;"}, "V", 0, {});
          Other.reference.owner = Parent.name;
          Other.access = {"public", "constructor", "varargs"};
          Parent.methods.push_back(Other);
          break;
        }
        case 12:
          Code[3].registers[0] = 1;
          break;
        case 13:
          Code[3].registers[1] = 0;
          break;
        case 14:
          Code[3].registers[3] = 2;
          break;
        case 15:
        case 16:
        case 17:
          for (size_t I = 3; I < Code.size(); ++I)
            ++Code[I].pc;
          Code.insert(Code.begin() + 3,
                      Mutation == 15 ? op(3, "const/4", {3}, int64_t(0))
                      : Mutation == 16
                          ? op(3, "check-cast", {1}, {}, Token.name)
                          : op(3, "const/4", {1}, int64_t(0)));
          ++Caller.code_end;
          break;
        case 18:
          Parent.methods[0].generic_signature = "(TU;J)V";
          break;
        case 19:
          Parent.methods[0].access = {"private", "constructor"};
          break;
        case 20:
          Parent.methods[0].declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
          break;
        case 21:
          Caller.generic_signature =
              "<X:Ljava/lang/Object;>(Lfixture/Token;J)V";
          break;
        case 22:
          Caller.reference.parameters[1] = "D";
          break;
        case 23:
          Code[1].opcode = "move/from16";
          break;
        }
        // The exact same raw token is now a supported direct nominal
        // substitution. Its declaration's unused formal supplies no element
        // evidence; preserve this original input as a positive compatibility.
        if (Mutation == 3) {
          const auto Ref = Caller.reference;
          const auto Target = Parent.methods[0].reference;
          const auto OriginalToken = Token.generic_signature;
          if (Linked)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          if (Linked)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plans.superclass_calls.contains({Ref, Target}));
          EXPECT_EQ(Plans.superclass_call_declarations.at({Ref, Target}),
                    Target);
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          EXPECT_FALSE(Classes.at(Ref.owner).methods[0].generic_signature);
          EXPECT_EQ(Classes.at("Lfixture/Token;").generic_signature,
                    OriginalToken);
          std::string Text;
          for (size_t I = 0; I < Report.getArray("source_units")->size(); ++I)
            Text += source(Report, I);
          EXPECT_NE(Text.find("super(((fixture.Token)"), std::string::npos);
          continue;
        }
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> genericSuperConstructorPrefixClasses() {
  auto Input = genericSuperConstructorClasses();
  auto Check =
      method("require", {"Lfixture/Input;", "Ljava/lang/String;"}, "V", 0, {});
  Check.access = {"public", "static"};
  auto Checks = klass("Lfixture/Checks;", {Check});
  Checks.external = true;
  auto &Init = Input[1].methods[0];
  Init.registers = 4;
  Init.instructions = {
      op(0, "const-string", {0}, std::string("owned argument")),
      op(1, "invoke-static", {3, 0}, {}, Checks.methods[0].reference),
      op(2, "invoke-direct", {2, 3}, {}, Input[0].methods[0].reference),
      op(3, "return-void")};
  Init.code_end = 4;
  Input.push_back(std::move(Checks));
  return Input;
}

std::vector<Class> genericConstructorUpcastClasses(bool External, bool Cast,
                                                   bool Range, bool Package) {
  auto BaseInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  BaseInit.access = {"public", "constructor"};
  auto Base = klass("Lfixture/InputBase;", {BaseInit});
  Base.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Derived = klass("Lfixture/InputDerived;", {BaseInit});
  Derived.superclass = Base.name;
  Derived.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Lfixture/InputBase<TA;TB;>;";
  Derived.methods[0].instructions[0].reference = Base.methods[0].reference;
  auto ParentInit = BaseInit;
  ParentInit.reference.parameters = {Base.name};
  ParentInit.generic_signature = "(Lfixture/InputBase<TP;TQ;>;)V";
  ParentInit.registers = 2;
  auto Parent = klass("Lfixture/Parent;", {ParentInit});
  Parent.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
  if (External) {
    Parent.external = true;
    Parent.methods[0].instructions.clear();
    Parent.methods[0].registers = Parent.methods[0].code_end = 0;
  }
  auto Check = method("require", {"Ljava/lang/Object;", "Ljava/lang/String;"},
                      "V", 0, {});
  auto Checks = klass("Lfixture/Checks;", {Check});
  Checks.external = true;
  auto Init =
      method("<init>", {Derived.name}, "V", 5,
             {op(0, "const-string", {2}, std::string("owned upcast check")),
              op(1, "invoke-static", {4, 2}, {}, Checks.methods[0].reference),
              op(2, "move-object", {1, 4}),
              Cast ? op(3, "check-cast", {1}, {}, Base.name) : op(3, "nop"),
              op(4, "move-object", {0, 3}),
              op(5, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
                 Parent.methods[0].reference),
              op(6, "iput-object", {4, 3}, {},
                 FieldRef{"Lfixture/Core;", "original", Derived.name}),
              op(7, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Lfixture/InputDerived<TK;TV;>;)V";
  auto Core = klass("Lfixture/Core;", {Init});
  Core.superclass = Parent.name;
  Core.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Lfixture/Parent<TK;TV;>;";
  Core.fields.push_back({{Core.name, "original", Derived.name},
                         {"public"},
                         {},
                         "Lfixture/InputDerived<TK;TV;>;"});
  if (Package)
    Core.access.erase("public");
  return {Core, Parent, Base, Derived, Checks};
}

