std::vector<Class> plainSuperclassCallClasses(bool Captured, unsigned Chain,
                                              bool External) {
  auto Input = genericSuperclassCallClasses(false);
  auto &Parent = Input[0], &Child = Input[1];
  Parent.generic_signature.reset();
  Child.generic_signature.reset();
  const std::string Box = "Lfixture/Box;";
  const std::string Closed = "Lfixture/Box<Ljava/lang/Object;>;";
  auto &Echo = Parent.methods[1], &Probe = Child.methods[1];
  Echo.reference.parameters = Probe.reference.parameters = {Box};
  Echo.reference.returns = Probe.reference.returns = Box;
  Echo.generic_signature = Probe.generic_signature =
      "(" + Closed + ")" + Closed;
  Probe.instructions[0].reference = Echo.reference;
  auto Middle = klass("Lfixture/CallMiddle;", {Parent.methods[0]});
  Middle.superclass = Parent.name;
  Middle.methods[0].instructions[0].reference = Parent.methods[0].reference;
  if (Chain) {
    Child.superclass = Middle.name;
    Child.methods[0].instructions[0].reference = Middle.methods[0].reference;
    auto Call = Echo.reference;
    Call.owner = Middle.name;
    Probe.instructions[0].reference = Call;
  }
  if (Chain == 2) {
    Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
    Echo.generic_signature = "(Lfixture/Box<TP;>;)Lfixture/Box<TP;>;";
    Middle.generic_signature = "Lfixture/CallParent<Ljava/lang/Object;>;";
  }
  if (External) {
    for (auto *Declaration : {&Parent, &Middle}) {
      Declaration->external = true;
      for (auto &M : Declaration->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  }
  auto Parameter = klass(Box);
  Parameter.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Parameter);
  if (Chain)
    Input.push_back(Middle);
  if (Captured) {
    auto Capture = capturedInnerClasses();
    auto Member = std::move(Capture[1]);
    Member.superclass = Input[1].superclass;
    Member.methods[0].instructions[1].reference =
        Input[1].methods[0].instructions[0].reference;
    auto Caller = Input[1].methods[1];
    Caller.reference.owner = Member.name;
    Member.methods.push_back(Caller);
    Input[1] = std::move(Member);
    Input.push_back(Capture[0]);
  }
  return Input;
}

