std::vector<Class> chainedCovariantReferenceGetterClasses(bool Extra = false) {
  auto Input = covariantReferenceGetterClasses();
  auto Init = Input[0].methods[0];
  Init.instructions[0].reference = MethodRef{Input[0].name, "<init>", {}, "V"};
  auto Middle = klass("Lfixture/Middle;", {Init});
  Middle.access.insert("abstract");
  Middle.superclass = Input[0].name;
  Middle.generic_signature =
      "<R:Ljava/lang/Object;U:Ljava/lang/Object;>Lfixture/Parent<TR;>;";
  Input[1].superclass = Middle.name;
  Input[1].generic_signature =
      "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Lfixture/Middle<TV;TS;>;";
  Input[1].methods[0].generic_signature = "()Lfixture/Leaf<TV;>;";
  Input.push_back(Middle);
  if (Extra) {
    Init.instructions[0].reference = MethodRef{Middle.name, "<init>", {}, "V"};
    auto Upper = klass("Lfixture/Upper;", {Init});
    Upper.access.insert("abstract");
    Upper.superclass = Middle.name;
    Upper.generic_signature =
        "<K:Ljava/lang/Object;L:Ljava/lang/Object;>Lfixture/Middle<TL;TK;>;";
    Input[1].superclass = Upper.name;
    Input[1].generic_signature =
        "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Lfixture/Upper<TS;TV;>;";
    Input.push_back(Upper);
  }
  return Input;
}

