TEST(MobileDalvikJava, GenericFinalOverloadsRemainInTheirParentDeclaration) {
  for (bool Link : {false, true}) {
    auto Input = ownedBoundedBridgeClasses();
    auto &Base = Input[0];
    Base.access.erase("interface");
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.access = {"public", "constructor"};
    Init.reference.owner = Base.name;
    Base.methods.push_back(Init);
    auto Final = method("echo", {"Ljava/lang/Object;", "I", "I"},
                        "Ljava/lang/Object;", 4, {op(0, "return-object", {1})});
    Final.reference.owner = Base.name;
    Final.access = {"public", "final"};
    Final.generic_signature = "(TT;II)TT;";
    Base.methods.push_back(Final);
    auto &Core = Input[1];
    Core.interfaces.clear();
    Core.superclass = Base.name;
    Core.generic_signature = "<I:Lfixture/Tag;>Lfixture/Contract<TI;>;";
    auto Overload = method("echo", {"Lfixture/Tag;", "I"}, "Lfixture/Tag;", 3,
                           {op(0, "return-object", {1})});
    Overload.generic_signature = "(TI;I)TI;";
    Overload.access = {"public"};
    Core.methods.push_back(Overload);
    Budget B;
    auto R = Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 6);
    EXPECT_EQ(R.getInteger("projected_method_count"), 1);
    EXPECT_NE(source(R).find("final T echo(T arg0, int arg1, int arg2)"),
              std::string::npos);
    EXPECT_NE(source(R, 1).find("extends fixture.Contract<I>"),
              std::string::npos);
    Base.methods[0].access = {"public", "final"};
    Base.methods[0].registers = 2;
    Base.methods[0].instructions = {op(0, "return-object", {1})};
    Base.methods[0].code_end = 1;
    rejected([&] { recover(Input); }, "final member cannot be overridden");
  }
}

std::vector<Class> parameterizedVoidUnitClasses() {
  auto Input = voidUnitBridgeClasses(true);
  auto &Contract = Input[0];
  Contract.generic_signature =
      "<P:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.methods[0].generic_signature = "(TP;)TR;";
  auto &Core = Input[1];
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Contract<"
                           "Lfixture/Box<+Ljava/lang/String;>;Lkotlin/Unit;>;";
  auto &Target = Core.methods[0];
  Target.reference.parameters = {"Lfixture/Box;"};
  Target.generic_signature = "(Lfixture/Box<Ljava/lang/String;>;)V";
  Core.methods[1].instructions[0].reference = std::string("Lfixture/Box;");
  Core.methods[1].instructions[1].reference = Target.reference;
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(std::move(Box));
  return Input;
}

TEST(MobileDalvikJava, ParameterizedVoidUnitTargetsRetainTheirSignature) {
  for (unsigned Variant = 0; Variant < 6; ++Variant) {
    for (bool Link : {false, true}) {
      auto Input = parameterizedVoidUnitClasses();
      if (Variant < 3)
        Input[1].generic_signature =
            Variant == 0   ? "Ljava/lang/Object;Lfixture/Contract<"
                             "Lfixture/Box<Ljava/lang/String;>;Lkotlin/Unit;>;"
            : Variant == 1 ? "Ljava/lang/Object;Lfixture/Contract<"
                             "Lfixture/Box<-Ljava/lang/String;>;Lkotlin/Unit;>;"
                           : "Ljava/lang/Object;Lfixture/Contract<"
                             "Lfixture/Box<*>;Lkotlin/Unit;>;";
      else if (Variant == 4) {
        Input[1].generic_signature =
            "<T:Ljava/lang/Object;>Ljava/lang/Object;"
            "Lfixture/Contract<Lfixture/Box<+TT;>;Lkotlin/Unit;>;";
        Input[1].methods[0].generic_signature = "(Lfixture/Box<TT;>;)V";
      } else if (Variant == 5) {
        Input[1].generic_signature = "Ljava/lang/Object;Lfixture/Contract<"
                                     "[Lfixture/Box<+Ljava/lang/String;>;"
                                     "Lkotlin/Unit;>;";
        Input[1].methods[0].reference.parameters = {"[Lfixture/Box;"};
        Input[1].methods[0].generic_signature =
            "([Lfixture/Box<Ljava/lang/String;>;)V";
        Input[1].methods[1].instructions[0].reference =
            std::string("[Lfixture/Box;");
        Input[1].methods[1].instructions[1].reference =
            Input[1].methods[0].reference;
      }
      Budget B;
      auto R = Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("projected_method_count"), 2);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
      const auto Text = source(R, 2);
      EXPECT_NE(Text.find("void __neverdVoidBridgeTarget("), std::string::npos);
      EXPECT_NE(Text.find(Variant == 4 ? "fixture.Box<T>"
                                       : "fixture.Box<java.lang.String>"),
                std::string::npos);
      EXPECT_NE(Text.find("kotlin.Unit invoke(fixture.Box"), std::string::npos);
      for (const auto &Value : *R.getArray("methods")) {
        const auto *Row = Value.getAsObject();
        if (Row->getString("projection_kind") == "void-unit-interface-bridge") {
          ASSERT_NE(Row->getArray("metadata_differences"), nullptr);
          EXPECT_EQ(Row->getArray("metadata_differences")->size(), 3u);
        }
      }
    }
  }
}

TEST(MobileDalvikJava, ParameterizedVoidUnitDoesNotGuessArgumentContracts) {
  for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
    auto Input = parameterizedVoidUnitClasses();
    auto &Target = Input[1].methods[0];
    if (Mutation == 0)
      Target.generic_signature.reset();
    else if (Mutation == 1)
      Target.generic_signature = "(Lfixture/Box<Ljava/lang/Integer;>;)V";
    else if (Mutation == 2)
      Target.generic_signature = "(Lfixture/Box<-Ljava/lang/String;>;)V";
    else if (Mutation == 3)
      Target.generic_signature = "(Lfixture/Box;)V";
    else if (Mutation == 4)
      Target.generic_signature =
          "<U:Ljava/lang/Object;>(Lfixture/Box<Ljava/lang/String;>;)V";
    else if (Mutation == 5)
      Input[1].access.erase("final");
    else if (Mutation == 6)
      Input[1].methods[1].instructions[1].registers = {1, 1};
    else {
      Target.declared_throws =
          std::vector<std::string>{"Ljava/lang/Exception;"};
      Target.generic_signature =
          "(Lfixture/Box<Ljava/lang/String;>;)V^Ljava/lang/Exception;";
    }
    rejected([&] { recover(Input); }, "generic");
  }
}

std::vector<Class> enclosedOpenArgumentClasses(bool ClassFormal = false) {
  auto Input = interfaceBridgeClasses();
  auto &Base = Input[0];
  Base.access.erase("interface");
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Base.name;
  Base.methods.push_back(Init);
  const std::string LocalName = "Lfixture/Factory$1Worker;";
  Init.reference.owner = LocalName;
  Init.instructions[0].reference = MethodRef{Base.name, "<init>", {}, "V"};
  auto Target = method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                       {op(0, "return-object", {1})});
  Target.access = {"public"};
  Target.generic_signature = "(TT;)TT;";
  auto Local = klass(LocalName, {Init, Target});
  Local.access = {"final"};
  Local.superclass = Base.name;
  Local.generic_signature = "Lfixture/Contract<TT;>;";
  Local.inner_class_present = true;
  auto Make = method("make", {}, Base.name, ClassFormal ? 2 : 1,
                     {op(0, "new-instance", {0}, {}, LocalName),
                      op(1, "invoke-direct", {0}, {}, Init.reference),
                      op(2, "return-object", {0})});
  Make.generic_signature = ClassFormal
                               ? "()Lfixture/Contract<TT;>;"
                               : "<T:Ljava/lang/Object;U:Ljava/lang/Object;>"
                                 "()Lfixture/Contract<TT;>;";
  if (ClassFormal)
    Make.access.erase("static");
  auto Factory = klass("Lfixture/Factory;", {Make});
  Factory.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Local.enclosing_method = Factory.methods[0].reference;
  Input[1] = std::move(Factory);
  Input.push_back(std::move(Local));
  return Input;
}

