std::vector<Class> nongenericAncestorBridgeClasses() {
  auto Input = ownedBoundedBridgeClasses();
  auto &Parent = Input[0];
  Parent.access = {"public"};
  Parent.methods[0].access = {"public"};
  Parent.methods[0].registers = 2;
  Parent.methods[0].instructions = {op(0, "return-object", {1})};
  Parent.methods[0].code_end = 1;
  auto RootInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  RootInit.access = {"public", "constructor"};
  auto Count =
      method("count", {}, "I", 2,
             {op(0, "const/4", {0}, int64_t(3)), op(1, "return", {0})});
  Count.access = {"public"};
  auto Root = klass("Lfixture/Root;", {RootInit, Count});
  auto Declaration = method("count", {}, "I", 0, {});
  Declaration.access = {"public", "abstract"};
  auto Counter = klass("Lfixture/Counter;", {Declaration});
  Counter.access = {"public", "abstract", "interface"};
  auto Init = RootInit;
  Init.reference.owner = Parent.name;
  Init.instructions[0].reference = MethodRef{Root.name, "<init>", {}, "V"};
  Parent.methods.push_back(Init);
  Parent.superclass = Root.name;
  Parent.interfaces = {Counter.name};
  Parent.generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Root;Lfixture/Counter;";
  Input[1].interfaces.clear();
  Input[1].superclass = Parent.name;
  Input[1].generic_signature = "<I:Lfixture/Tag;>Lfixture/Contract<TI;>;";
  Input.push_back(std::move(Root));
  Input.push_back(std::move(Counter));
  return Input;
}

std::vector<Class> crossPackageAncestorClasses(unsigned Kind = 0,
                                               bool SamePackage = false) {
  auto Input = nongenericAncestorBridgeClasses();
  auto &Parent = Input[0];
  auto &Root = Input[3];
  Root.name = SamePackage ? "Lfixture/Root;" : "Lancestor/Root;";
  for (auto &M : Root.methods)
    M.reference.owner = Root.name;
  Parent.superclass = Root.name;
  Parent.interfaces.clear();
  Parent.methods.back().instructions[0].reference =
      MethodRef{Root.name, "<init>", {}, "V"};
  if (Kind) {
    Root.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
    Parent.generic_signature = "<T:Ljava/lang/Object;>" +
                               Root.name.substr(0, Root.name.size() - 1) +
                               "<TT;>;";
  } else
    Parent.generic_signature = "<T:Ljava/lang/Object;>" + Root.name;
  auto Hidden = Parent.methods[0];
  Hidden.reference.owner = Root.name;
  Hidden.reference.name = "hidden";
  Hidden.access = {"final"};
  Hidden.generic_signature =
      Kind ? std::optional<std::string>("(TA;)TA;") : std::nullopt;
  Root.methods.push_back(Hidden);
  Hidden.reference.owner = Input[1].name;
  Hidden.access = {"public"};
  Hidden.generic_signature.reset();
  Input[1].methods.push_back(Hidden);
  auto Mode = method("mode", {"I"}, "I", 1, {op(0, "return", {0})});
  Mode.reference.owner = Root.name;
  Mode.access = {"static"};
  Root.methods.push_back(Mode);
  Mode.reference.owner = Input[1].name;
  Mode.access = {"public"};
  Mode.registers = 2;
  Mode.instructions = {op(0, "return", {1})};
  Input[1].methods.push_back(Mode);
  if (Kind == 2)
    for (unsigned Index : {0u, 3u}) {
      Input[Index].external = true;
      for (auto &M : Input[Index].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Input;
}

