TEST(MobileDalvikJava, GenericAncestorProofRejectsMissingOrChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 17; ++Mutation) {
    auto Input = nongenericAncestorBridgeClasses();
    if (Mutation == 0)
      Input.erase(Input.begin() + 3);
    else if (Mutation == 1)
      Input[3].generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 2)
      Input[3].methods[1].generic_signature = "<A:Ljava/lang/Object;>()I";
    else if (Mutation == 3)
      Input[3].superclass = Input[3].name;
    else if (Mutation == 4)
      Input[3].methods.pop_back();
    else if (Mutation == 5) {
      Input[1].methods.push_back(Input[3].methods[1]);
      Input[1].methods.back().reference.owner = Input[1].name;
      Input[1].methods.back().generic_signature = "<R:Ljava/lang/Object;>()I";
    } else if (Mutation == 6) {
      auto Final = Input[0].methods[0];
      Final.reference.owner = Input[3].name;
      Final.access.insert("final");
      Final.generic_signature.reset();
      Input[3].methods.push_back(Final);
    } else if (Mutation == 7) {
      Input[0].access.insert("abstract");
      Input[3].methods[1].access = {"public", "abstract"};
      Input[3].methods[1].instructions.clear();
      Input[3].methods[1].registers = Input[3].methods[1].code_end = 0;
    } else if (Mutation == 8 || Mutation == 9) {
      auto Count = Input[3].methods[1];
      Count.reference.owner = Input[0].name;
      if (Mutation == 8) {
        Count.access = {"public", "abstract"};
        Count.instructions.clear();
        Count.code_end = 0;
        Count.registers = 0;
      } else
        Count.access = {"private"};
      Input[0].methods.push_back(Count);
    } else if (Mutation == 10) {
      Input[0].superclass = Input[4].name;
      Input[0].generic_signature =
          "<T:Ljava/lang/Object;>Lfixture/Counter;Lfixture/Counter;";
    } else if (Mutation == 11)
      Input[4].generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
    else {
      auto Count = Input[3].methods[1];
      Count.reference.owner = Input[1].name;
      if (Mutation == 12) {
        Count.reference.returns = "J";
        Count.registers = 3;
        Count.instructions = {op(0, "const-wide/16", {0}, int64_t(3)),
                              op(1, "return-wide", {0})};
      } else if (Mutation == 13)
        Count.access = {"private"};
      else if (Mutation == 14)
        Count.declared_throws =
            std::vector<std::string>{"Ljava/lang/Exception;"};
      else if (Mutation == 15)
        Input[3].methods[1].access.insert("final");
      else
        Count.access.insert("static");
      Input[1].methods.push_back(Count);
    }
    rejected([&] { recover(Input); },
             Mutation == 3 ? "cyclic inherited superclass dependency"
                           : "generic inheritance");
  }
}

std::vector<Class> integerUnitBridgeClasses() {
  auto Input = voidUnitBridgeClasses(true);
  auto &Contract = Input[0];
  Contract.generic_signature =
      "<P:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.methods[0].generic_signature = "(TP;)TR;";
  auto &Core = Input[1];
  Core.generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Ljava/lang/Integer;Lkotlin/Unit;>;";
  auto &Target = Core.methods[0];
  Target.reference.parameters = {"I"};
  auto &Bridge = Core.methods[1];
  Bridge.instructions = {
      op(0, "check-cast", {2}, {}, std::string("Ljava/lang/Number;")),
      op(1, "invoke-virtual", {2}, {},
         MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}),
      op(2, "move-result", {0}),
      op(3, "invoke-virtual", {1, 0}, {}, Target.reference),
      op(4, "sget-object", {0}, {},
         FieldRef{"Lkotlin/Unit;", "INSTANCE", "Lkotlin/Unit;"}),
      op(5, "return-object", {0})};
  Bridge.code_end = 6;
  auto Getter = method("intValue", {}, "I", 0, {});
  Getter.access = {"public", "abstract"};
  auto Number = klass("Ljava/lang/Number;", {Getter});
  Number.external = true;
  Number.access.insert("abstract");
  auto Integer = klass("Ljava/lang/Integer;");
  Integer.external = true;
  Integer.access.insert("final");
  Integer.superclass = Number.name;
  Input.push_back(std::move(Number));
  Input.push_back(std::move(Integer));
  return Input;
}

std::vector<Class> rawIndexedScopeClasses(unsigned Count, bool Tail, bool Copy,
                                          bool Range, bool External) {
  auto Input = defaultScopedCovariantClasses(Range, false);
  auto &Core = Input[1];
  Core.superclass = "Ljava/lang/Object;";
  Core.methods[0].registers = 1;
  Core.methods[0].instructions = {
      op(0, "invoke-direct", {0}, {},
         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
      op(1, "return-void")};
  Core.methods[0].code_end = 2;
  auto &API = Input[3];
  API.external = External;
  API.generic_signature = "<";
  std::string Contract = "(";
  for (unsigned i = 0; i < Count; ++i) {
    *API.generic_signature += "A" + std::to_string(i) + ":Ljava/lang/Object;";
    Contract += "TA" + std::to_string(i) + ";";
  }
  *API.generic_signature += "R:Ljava/lang/Object;>Ljava/lang/Object;";
  API.methods[0].reference.parameters.assign(Count, "Ljava/lang/Object;");
  API.methods[0].generic_signature = Contract + ")TR;";
  auto &Target = Core.methods[1];
  Target.reference.parameters.assign(Count, "Ljava/lang/Object;");
  const unsigned Index = Tail ? Count - 1 : 0;
  Target.reference.parameters[Index] = "I";
  Target.generic_signature = "(";
  for (unsigned i = 0; i < Count; ++i)
    *Target.generic_signature += i == Index ? "I" : "TK;";
  *Target.generic_signature += ")Ljava/lang/Void;";
  Target.registers = Count + 2;
  auto &Bridge = Core.methods.back();
  Bridge.reference.parameters.assign(Count, "Ljava/lang/Object;");
  Bridge.registers = 2 * Count + 2;
  Bridge.instructions.clear();
  const unsigned Self = Count + 1;
  if (Copy) {
    Bridge.instructions.push_back(op(0, "move-object", {0, Self}));
    for (unsigned i = 0; i < Count; ++i)
      Bridge.instructions.push_back(
          op(0, "move-object", {i + 1, Self + i + 1}));
  }
  const unsigned Value = (Copy ? 1 : Self + 1) + Index;
  Bridge.instructions.push_back(
      op(0, "check-cast", {Value}, {}, std::string("Ljava/lang/Number;")));
  Bridge.instructions.push_back(
      op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {Value}, {},
         MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}));
  Bridge.instructions.push_back(op(0, "move-result", {Value}));
  std::vector<unsigned> Args{Copy ? 0u : Self};
  for (unsigned i = 0; i < Count; ++i)
    Args.push_back((Copy ? 1 : Self + 1) + i);
  Bridge.instructions.push_back(
      op(0, Range ? "invoke-virtual/range" : "invoke-virtual", Args, {},
         Target.reference));
  Bridge.instructions.push_back(op(0, "move-result-object", {0}));
  Bridge.instructions.push_back(op(0, "return-object", {0}));
  for (size_t i = 0; i < Bridge.instructions.size(); ++i)
    Bridge.instructions[i].pc = i;
  Bridge.code_end = Bridge.instructions.size();
  auto Numbers = integerUnitBridgeClasses();
  Input.push_back(Numbers[3]);
  Input.push_back(Numbers[4]);
  return Input;
}

TEST(MobileDalvikJava, RawIndexedScopeKeepsNumberConversionAndBothEntries) {
  for (unsigned Count : {2u, 4u})
    for (bool Tail : {false, true})
      for (bool Copy : {false, true})
        for (bool Range : {false, true})
          for (bool External : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(::testing::Message()
                           << Count << Tail << Copy << Range << External
                           << Reverse);
              auto Input =
                  rawIndexedScopeClasses(Count, Tail, Copy, Range, External);
              const auto Bridge = Input[1].methods.back().reference;
              const auto Target = Input[1].methods[1].reference;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto Classes = linkClasses(Input, B);
              const auto Scopes = validateSourceScopes(Classes, B);
              const auto Plans = validateGenericSignatures(
                  Classes, B, &Scopes.enums, &Scopes.shared);
              const auto Inheritance =
                  planGenericInheritance(Classes, Plans, B, &Scopes.enums);
              ASSERT_TRUE(Inheritance.retained_plain_bridges.contains(Bridge));
              const auto &Proof = Inheritance.retained_plain_bridges.at(Bridge);
              EXPECT_EQ(Proof.target, Target);
              EXPECT_EQ(Proof.raw_indexed_parameters,
                        (std::set<size_t>{Tail ? Count - 1u : 0u}));
              EXPECT_EQ(Proof.unbox_method,
                        (MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}));
              EXPECT_FALSE(Inheritance.bridges.contains(Bridge));
              const auto *Source = sourceMethodSignature(Target, Plans);
              ASSERT_NE(Source, nullptr);
              EXPECT_EQ(Source->source_projections.size(), Count - 1u);
            }
}

