TEST(MobileDalvikJava, IntegerUnitBridgePreservesBothOriginalBodiesAndNames) {
  for (bool Link : {false, true}) {
    auto Input = integerUnitBridgeClasses();
    const auto Bridge = Input[1].methods[1].reference;
    const auto Original = *Input[1].generic_signature;
    Budget B;
    auto R = Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 3);
    EXPECT_EQ(R.getInteger("projected_method_count"), 1);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    const auto Text = source(R, 1);
    EXPECT_NE(Text.find("void invoke(int arg0)"), std::string::npos);
    EXPECT_NE(Text.find("java.lang.Object invoke(java.lang.Object arg0)"),
              std::string::npos);
    EXPECT_NE(Text.find(".intValue()"), std::string::npos);
    EXPECT_NE(Text.find("implements fixture.Contract {"), std::string::npos);
    EXPECT_EQ(Text.find("__neverdVoidBridgeTarget"), std::string::npos);
    const auto *Projections = R.getArray("generic_signature_projections");
    ASSERT_NE(Projections, nullptr);
    ASSERT_EQ(Projections->size(), 1u);
    const auto *Projection = Projections->front().getAsObject();
    EXPECT_EQ(Projection->getString("original_signature"), Original);
    const auto *Changes = Projection->getArray("changes");
    ASSERT_NE(Changes, nullptr);
    ASSERT_EQ(Changes->size(), 1u);
    EXPECT_EQ(Changes->front().getAsObject()->getString("kind"),
              "checked-integer-unit-interface");
    EXPECT_EQ(Changes->front().getAsObject()->getString("scope_origin"),
              Bridge.identity());
  }
}

TEST(MobileDalvikJava, IntegerUnitBridgeRejectsUnprovenABIAndChangedOrder) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    auto Input = integerUnitBridgeClasses();
    auto &Core = Input[1];
    auto &Bridge = Core.methods[1];
    if (Mutation == 0)
      Input.erase(Input.begin() + 3);
    else if (Mutation == 1)
      Input.pop_back();
    else if (Mutation == 2)
      Input[3].methods[0].access.insert("static");
    else if (Mutation == 3)
      Bridge.instructions[0].reference = std::string("Ljava/lang/Integer;");
    else if (Mutation == 4)
      Bridge.instructions[1].reference =
          MethodRef{"Ljava/lang/Number;", "longValue", {}, "J"};
    else if (Mutation == 5)
      Bridge.instructions[1].registers = {1};
    else if (Mutation == 6) {
      Bridge.instructions.insert(Bridge.instructions.begin() + 3,
                                 Bridge.instructions[1]);
      for (size_t I = 0; I < Bridge.instructions.size(); ++I)
        Bridge.instructions[I].pc = I;
      Bridge.code_end = Bridge.instructions.size();
    } else if (Mutation == 7)
      Bridge.instructions[3].registers = {1, 2};
    else if (Mutation == 8)
      std::swap(Bridge.instructions[3], Bridge.instructions[4]);
    else if (Mutation == 9)
      Core.methods[0].generic_signature = "<U:Ljava/lang/Object;>(I)V";
    else if (Mutation == 10)
      Input[0].generic_signature =
          "<P:Ljava/lang/CharSequence;R:Ljava/lang/Object;>Ljava/lang/Object;";
    else
      Core.access.erase("final");
    rejected([&] { recover(Input); }, "generic");
  }
}

std::vector<Class>
standardNumericUnitBridgeClasses(const std::string &Primitive) {
  auto Input = integerUnitBridgeClasses();
  const std::string Wrapper = Primitive == "F"   ? "Float"
                              : Primitive == "D" ? "Double"
                                                 : "Long";
  const std::string Conversion = Primitive == "F"   ? "floatValue"
                                 : Primitive == "D" ? "doubleValue"
                                                    : "longValue";
  Input[1].generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Ljava/lang/" + Wrapper +
      ";Lkotlin/Unit;>;";
  Input[4].name = "Ljava/lang/" + Wrapper + ";";
  auto &Unbox = Input[3].methods[0];
  Unbox.reference.name = Conversion;
  Unbox.reference.returns = Primitive;
  auto &Target = Input[1].methods[0], &Bridge = Input[1].methods[1];
  Target.reference.parameters = {Primitive};
  Target.registers = Primitive == "F" ? 2 : 3;
  Bridge.registers = 4;
  Bridge.instructions = {
      op(0, "check-cast", {3}, {}, Input[3].name),
      op(1, "invoke-virtual", {3}, {}, Unbox.reference),
      op(2, Primitive == "F" ? "move-result" : "move-result-wide", {0}),
      op(3, "invoke-virtual",
         Primitive == "F" ? std::vector<unsigned>{2, 0}
                          : std::vector<unsigned>{2, 0, 1},
         {}, Target.reference),
      op(4, "sget-object", {0}, {}, Input[2].fields[0].reference),
      op(5, "return-object", {0})};
  Bridge.code_end = 6;
  return Input;
}

