std::vector<Class> valueCarrierBridgeClasses(bool Copies = true) {
  auto Declaration =
      method("invoke", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
             "Ljava/lang/Object;", 0, {});
  Declaration.access = {"public", "abstract"};
  Declaration.generic_signature = "(TP;TQ;)TR;";
  auto Contract = klass("Lfixture/Function;", {Declaration});
  Contract.access = {"public", "abstract", "interface"};
  Contract.external = true;
  Contract.generic_signature = "<P:Ljava/lang/Object;Q:Ljava/lang/"
                               "Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Getter = method("unwrap", {}, "J", 0, {});
  Getter.access = {"public"};
  auto A = klass("Lfixture/CarrierA;", {Getter});
  auto Factory = method("wrap", {"J"}, "Lfixture/CarrierB;", 0, {});
  auto B = klass("Lfixture/CarrierB;", {Getter, Factory});
  A.external = B.external = true;
  A.access.insert("final");
  B.access.insert("final");
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target =
      method("apply", {"J", "J"}, "J", 5, {op(0, "return-wide", {3})});
  Target.access = {"public", "final"};
  auto Bridge = method("invoke", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                       "Ljava/lang/Object;", 7, {});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.instructions = {
      op(0, "move-object", {0, 5}),
      op(1, "check-cast", {0}, {}, A.name),
      op(2, "invoke-virtual", {0}, {}, A.methods[0].reference),
      op(3, "move-result-wide", {0}),
      op(4, "move-object", {2, 6}),
      op(5, "check-cast", {2}, {}, B.name),
      op(6, "invoke-virtual", {2}, {}, B.methods[0].reference),
      op(7, "move-result-wide", {2}),
      op(8, "invoke-virtual", {4, 0, 1, 2, 3}, {}, Target.reference),
      op(9, "move-result-wide", {0}),
      op(10, "invoke-static", {0, 1}, {}, B.methods[1].reference),
      op(11, "move-result-object", {0}),
      op(12, "return-object", {0})};
  Bridge.code_end = 13;
  if (!Copies) {
    Bridge.instructions.erase(Bridge.instructions.begin() + 4);
    Bridge.instructions.erase(Bridge.instructions.begin());
    Bridge.instructions[0].registers = Bridge.instructions[1].registers = {5};
    Bridge.instructions[3].registers = Bridge.instructions[4].registers = {6};
  }
  auto Core = klass("Lfixture/Core;", {Init, Target, Bridge});
  Core.access.insert("final");
  Core.interfaces = {Contract.name};
  Core.generic_signature =
      "<S:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Function<Lfixture/CarrierA;Lfixture/CarrierB;"
      "Lfixture/CarrierB;>;";
  Core.methods[2].instructions[Copies ? 8 : 6].reference =
      Core.methods[1].reference;
  return {Core, Contract, A, B};
}

std::vector<Class> projectedInterfaceSuperConstructorClasses(bool External,
                                                             bool Range) {
  auto Input = valueCarrierBridgeClasses();
  auto Sink = klass("Lfixture/Sink;");
  Sink.access = {"public", "interface", "abstract"};
  Sink.external = External;
  Sink.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto BaseInit =
      method("<init>", {"I", Sink.name}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  BaseInit.access = {"public", "constructor"};
  BaseInit.generic_signature = "(ILfixture/Sink<Ljava/lang/Object;>;)V";
  auto Base = klass("Lfixture/Base;", {BaseInit});
  Base.external = External;
  if (External) {
    Base.methods[0].instructions.clear();
    Base.methods[0].registers = Base.methods[0].code_end = 0;
  }
  auto &Core = Input[0];
  Core.superclass = Base.name;
  *Core.generic_signature = "<S:Ljava/lang/Object;>Lfixture/Base;"
                            "Lfixture/Function<Lfixture/CarrierA;Lfixture/"
                            "CarrierB;Lfixture/CarrierB;>;";
  auto Init = method("<init>", {Sink.name}, "V", 3,
                     {op(0, "const/4", {0}, int64_t{2}),
                      op(1, Range ? "invoke-direct/range" : "invoke-direct",
                         {1, 0, 2}, {}, Base.methods[0].reference),
                      op(2, "return-void")});
  if (Range) {
    Init.registers = 5;
    Init.instructions = {
        op(0, "const/4", {1}, int64_t{2}), op(1, "move-object", {0, 3}),
        op(2, "move-object", {2, 4}),
        op(3, "invoke-direct/range", {0, 1, 2}, {}, Base.methods[0].reference),
        op(4, "return-void")};
    Init.code_end = 5;
  }
  Init.access = {"public", "constructor"};
  Init.reference.owner = Core.name;
  Init.generic_signature = "(Lfixture/Sink<-Lfixture/Core;>;)V";
  Core.methods[0] = Init;
  Input.push_back(Sink);
  Input.push_back(Base);
  return Input;
}

TEST(MobileDalvikJava,
     ProjectedInterfaceEdgesKeepUnchangedSelfConsumerSuperclassCall) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = projectedInterfaceSuperConstructorClasses(External, Range);
        const auto Caller = Input[0].methods[0].reference;
        const auto Target = Input.back().methods[0].reference;
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_TRUE(Plans.value_carrier_bridges.contains(
            Classes.at(Caller.owner).methods[2].reference));
        ASSERT_EQ(Plans.classes.at(Caller.owner).source_projections.size(), 1u);
        EXPECT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      }
}

