TEST(MobileDalvikJava, ValueCarrierBridgesRejectLivePairAndContractDrift) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    auto Input = valueCarrierBridgeClasses();
    auto &Bridge = Input[0].methods[2];
    if (Mutation == 0)
      Bridge.instructions[8].registers = {4, 2, 3, 0, 1};
    else if (Mutation == 1)
      Bridge.instructions[4].registers = {1, 6};
    else if (Mutation == 2)
      Bridge.instructions[7].registers = {1};
    else if (Mutation == 3)
      Bridge.instructions[5].reference = Input[2].name;
    else if (Mutation == 4)
      Input[2].methods[0].access.insert("static");
    else if (Mutation == 5)
      Input[3].methods[1].access.erase("static");
    else if (Mutation == 6)
      Input[0].methods[1].generic_signature = "<T:Ljava/lang/Object;>(JJ)J";
    else if (Mutation == 7)
      Input[1].methods[0].generic_signature = "(TQ;TP;)TR;";
    else if (Mutation == 8)
      Bridge.access.erase("synthetic");
    else if (Mutation == 9)
      Input[0].access.erase("final");
    else if (Mutation == 10)
      Bridge.instructions[10].registers = {2, 3};
    else {
      Bridge.instructions.insert(Bridge.instructions.begin() + 8,
                                 op(8, "const/4", {0}, int64_t(0)));
      for (size_t I = 0; I < Bridge.instructions.size(); ++I)
        Bridge.instructions[I].pc = I;
      Bridge.code_end = Bridge.instructions.size();
    }
    rejected([&] { recover(Input); }, "generic");
  }
}

std::vector<Class> shortComparisonCarrierClasses() {
  auto Compare = method("compare", {"Ljava/lang/Object;"}, "I", 0, {});
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TE;)I";
  auto Api = klass("Lfixture/Api;", {Compare});
  Api.access = {"public", "abstract", "interface"};
  Api.external = true;
  Api.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Core = klass("Lfixture/Core;");
  Core.access.insert("final");
  Core.interfaces = {Api.name};
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Api<Lfixture/Core;>;";
  FieldRef Value{Core.name, "value", "S"};
  Core.fields.push_back({Value, {"public"}, {}});
  auto Unbox =
      method("read", {}, "S", 2,
             {op(0, "iget-short", {0, 1}, {}, Value), op(1, "return", {0})});
  Unbox.reference.owner = Core.name;
  Unbox.access = {"public", "final"};
  auto Target = method("compareScalar", {"S"}, "I", 3, {op(0, "return", {2})});
  Target.reference.owner = Core.name;
  Target.access = {"public"};
  Compare.reference.owner = Core.name;
  Compare.generic_signature.reset();
  Compare.access = {"public", "bridge", "synthetic"};
  Compare.registers = 3;
  Compare.instructions = {op(0, "move-object", {0, 2}),
                          op(1, "check-cast", {0}, {}, Core.name),
                          op(2, "invoke-virtual", {0}, {}, Unbox.reference),
                          op(3, "move-result", {0}),
                          op(4, "invoke-virtual", {1, 0}, {}, Target.reference),
                          op(5, "move-result", {0}),
                          op(6, "return", {0})};
  Compare.code_end = 7;
  Core.methods = {Compare, Target, Unbox};
  return {Core, Api};
}

