std::vector<Class> referenceResultCarrierClasses() {
  auto Invoke = method("invoke", {}, "Ljava/lang/Object;", 0, {});
  Invoke.access = {"public", "abstract"};
  Invoke.generic_signature = "()TR;";
  auto Function = klass("Lfixture/Function;", {Invoke});
  Function.access = {"public", "abstract", "interface"};
  Function.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Payload = klass("Lfixture/Payload;");
  Payload.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  auto CarrierInit = method("<init>", {Payload.name}, "V", 2, {});
  CarrierInit.access = {"private", "constructor"};
  auto Factory = method("box", {Payload.name}, "Lfixture/Carrier;", 2, {});
  Factory.access = {"public", "static", "final"};
  auto Carrier = klass("Lfixture/Carrier;", {CarrierInit, Factory});
  Carrier.access.insert("final");
  Carrier.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
  FieldRef Storage{Carrier.name, "backing", Payload.name};
  Carrier.fields.push_back({Storage, {"private", "final"}, {}});
  Carrier.fields[0].generic_signature =
      "Lfixture/Payload<Ljava/lang/Object;Ljava/lang/Object;>;";
  Carrier.methods[0].instructions = {
      op(0, "invoke-direct", {0}, {},
         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
      op(1, "iput-object", {1, 0}, {}, Storage), op(2, "return-void")};
  Carrier.methods[0].code_end = 3;
  Carrier.methods[1].instructions = {
      op(0, "new-instance", {0}, {}, Carrier.name),
      op(1, "invoke-direct", {0, 1}, {}, Carrier.methods[0].reference),
      op(2, "return-object", {0})};
  Carrier.methods[1].code_end = 3;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target =
      method("storage", {}, Payload.name, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.access = {"public"};
  Target.generic_signature =
      "()Lfixture/Payload<Ljava/lang/Object;Ljava/lang/Object;>;";
  Invoke.access = {"public", "bridge", "synthetic"};
  Invoke.generic_signature.reset();
  Invoke.registers = 2;
  auto Core = klass("Lfixture/Core;", {Init, Target, Invoke});
  Core.access.insert("final");
  Core.interfaces = {Function.name};
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Function<Lfixture/"
                           "Carrier<Ljava/lang/Object;Lfixture/Tag;>;>;";
  Core.methods[2].instructions = {
      op(0, "invoke-virtual", {1}, {}, Core.methods[1].reference),
      op(1, "move-result-object", {0}),
      op(2, "invoke-static", {0}, {}, Carrier.methods[1].reference),
      op(3, "move-result-object", {0}), op(4, "return-object", {0})};
  Core.methods[2].code_end = 5;
  return {Core, Carrier, Function, Payload, klass("Lfixture/Tag;")};
}

TEST(MobileDalvikJava,
     ReferenceResultBoxKeepsFixedFullBackingTypeAndOriginalBody) {
  for (bool Link : {false, true}) {
    auto Input = referenceResultCarrierClasses();
    Budget B;
    const auto R =
        Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 6);
    EXPECT_EQ(R.getInteger("projected_method_count"), 1);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    bool Found = false;
    for (const auto &Value : *R.getArray("methods")) {
      const auto *Row = Value.getAsObject();
      if (Row->getString("identity") ==
          Input[0].methods[2].reference.identity()) {
        Found = true;
        EXPECT_EQ(Row->getString("box_method"),
                  Input[1].methods[1].reference.identity());
        EXPECT_EQ(Row->getString("representation_field"),
                  "Lfixture/Carrier;->backing:Lfixture/Payload;");
        EXPECT_EQ(Row->getString("representation_signature"),
                  "Lfixture/Payload<Ljava/lang/Object;Ljava/lang/Object;>;");
      }
    }
    EXPECT_TRUE(Found);
    EXPECT_NE(source(R, 1).find(".box("), std::string::npos);
  }
}

