std::vector<Class> boxedOnlyValueCarrierBridgeClasses(bool Scoped = true,
                                                      bool NoParams = false) {
  auto Input = valueCarrierBridgeClasses();
  Input.erase(Input.begin() + 2);
  auto &Contract = Input[1];
  Contract.generic_signature =
      "<P:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.methods[0].reference.parameters.resize(1);
  Contract.methods[0].generic_signature = "(TP;)TR;";
  auto &Core = Input[0];
  Core.generic_signature =
      "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Function<" +
      std::string(Scoped ? "TS;" : "Ljava/lang/Object;") +
      "Lfixture/CarrierB;>;";
  auto &Target = Core.methods[1];
  Target.reference.parameters = {"Ljava/lang/Object;"};
  Target.registers = 4;
  Target.instructions = {op(0, "const-wide/16", {0}, int64_t(27)),
                         op(1, "return-wide", {0})};
  Target.code_end = 2;
  if (Scoped)
    Target.generic_signature = "(TS;)J";
  auto &Bridge = Core.methods[2];
  Bridge.reference.parameters.resize(1);
  Bridge.registers = 4;
  Bridge.instructions = {
      op(0, "invoke-virtual", {2, 3}, {}, Target.reference),
      op(1, "move-result-wide", {0}),
      op(2, "invoke-static", {0, 1}, {}, Input[2].methods[1].reference),
      op(3, "move-result-object", {0}), op(4, "return-object", {0})};
  Bridge.code_end = 5;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  Input.push_back(std::move(Object));
  if (NoParams) {
    Input[1].generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
    Input[1].methods[0].reference.parameters.clear();
    Input[1].methods[0].generic_signature = "()TR;";
    Input[0].generic_signature =
        "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
        "Lfixture/Function<Lfixture/CarrierB;>;";
    Input[0].methods[1].reference.parameters.clear();
    Input[0].methods[1].generic_signature.reset();
    Input[0].methods[1].registers = 3;
    Input[0].methods[2].reference.parameters.clear();
    Input[0].methods[2].registers = 3;
    Input[0].methods[2].instructions[0].registers = {2};
    Input[0].methods[2].instructions[0].reference =
        Input[0].methods[1].reference;
  }
  return Input;
}

std::vector<Class> referenceOnlyValueCarrierBridgeClasses(bool Scoped = true) {
  auto Input = boxedOnlyValueCarrierBridgeClasses(Scoped);
  auto &Target = Input[0].methods[1];
  Target.reference.returns = "Lfixture/CarrierB;";
  Target.registers = 3;
  Target.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
  if (Scoped)
    Target.generic_signature = "(TS;)Lfixture/CarrierB;";
  auto &Bridge = Input[0].methods[2];
  Bridge.registers = 3;
  Bridge.instructions = {op(0, "invoke-virtual", {1, 2}, {}, Target.reference),
                         op(1, "move-result-object", {0}),
                         op(2, "return-object", {0})};
  Bridge.code_end = 3;
  return Input;
}

TEST(MobileDalvikJava,
     ReferenceOnlyCarrierBridgesRetainOriginalSlotsAndIdentity) {
  for (bool Scoped : {false, true})
    for (bool Reverse : {false, true})
      for (bool Link : {false, true}) {
        auto Input = referenceOnlyValueCarrierBridgeClasses(Scoped);
        const auto Original = *Input[0].generic_signature;
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), 3);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_NE(source(R).find(
                      Scoped ? "fixture.CarrierB apply(S arg0)"
                             : "fixture.CarrierB apply(java.lang.Object arg0)"),
                  std::string::npos);
        EXPECT_EQ(source(R).find(".wrap("), std::string::npos);
        EXPECT_EQ(source(R).find(".unwrap("), std::string::npos);
        const auto *Rows = R.getArray("methods");
        ASSERT_NE(Rows, nullptr);
        bool Found = false;
        for (const auto &Row : *Rows) {
          const auto *O = Row.getAsObject();
          if (O && O->getString("projection_kind") ==
                       "value-carrier-interface-bridge") {
            Found = true;
            EXPECT_EQ(
                O->getString("bridge_target"),
                "Lfixture/Core;->apply(Ljava/lang/Object;)Lfixture/CarrierB;");
            ASSERT_NE(O->getArray("unbox_methods"), nullptr);
            EXPECT_TRUE(O->getArray("unbox_methods")->empty());
            EXPECT_FALSE(O->getString("box_method").has_value());
          }
        }
        EXPECT_TRUE(Found);
        const auto *Projections = R.getArray("generic_signature_projections");
        ASSERT_NE(Projections, nullptr);
        ASSERT_EQ(Projections->size(), 1u);
        EXPECT_EQ(
            (*Projections)[0].getAsObject()->getString("original_signature"),
            Original);
      }
}

