std::vector<Class> inheritedClosedIntegerCarrierClasses(unsigned Arity) {
  const std::string Object = "Ljava/lang/Object;";
  auto Invoke =
      method("invoke", std::vector<std::string>(Arity, Object), Object, 0, {});
  Invoke.access = {"public", "abstract"};
  std::string Formals, Parameters, Arguments;
  for (unsigned I = 0; I < Arity; ++I) {
    const auto Name = "P" + std::to_string(I);
    Formals += Name + ":" + Object;
    Parameters += "T" + Name + ";";
    Arguments += I + 2 < Arity    ? Object
                 : I + 2 == Arity ? "Lfixture/Tag;"
                                  : "Ljava/lang/Integer;";
  }
  Invoke.generic_signature = "(" + Parameters + ")TR;";
  auto Function = klass("Lfixture/WideFunction;", {Invoke});
  Function.external = true;
  Function.access = {"public", "abstract", "interface"};
  Function.generic_signature = "<" + Formals + "R:" + Object + ">" + Object;
  auto Fixed = klass("Lfixture/FixedFunction;");
  Fixed.access = Function.access;
  Fixed.interfaces = {Function.name};
  Fixed.generic_signature =
      Object + "Lfixture/WideFunction<" + Arguments + Object + ">;";
  auto Conversion = method("intValue", {}, "I", 0, {});
  Conversion.access = {"public", "abstract"};
  auto Number = klass("Ljava/lang/Number;", {Conversion});
  Number.external = true;
  Number.access.insert("abstract");
  auto Integer = klass("Ljava/lang/Integer;");
  Integer.external = true;
  Integer.access.insert("final");
  Integer.superclass = Number.name;
  auto RuntimeInit = method("<init>", {}, "V", 0, {});
  RuntimeInit.access = {"public", "constructor"};
  auto RuntimeObject = klass(Object, {RuntimeInit});
  RuntimeObject.external = true;
  RuntimeObject.superclass.reset();
  auto Init = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto TypedParameters = std::vector<std::string>(Arity, Object);
  TypedParameters[Arity - 2] = "Lfixture/Tag;";
  TypedParameters[Arity - 1] = "I";
  auto Typed =
      method("invoke", TypedParameters, Object, Arity + 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = "Lfixture/IntegerActor;";
  Invoke.access = {"public", "bridge", "synthetic"};
  Invoke.generic_signature.reset();
  Invoke.registers = Arity + 3;
  std::vector<unsigned> TargetRegisters{2};
  for (unsigned I = 0; I + 2 < Arity; ++I)
    TargetRegisters.push_back(3 + I);
  TargetRegisters.insert(TargetRegisters.end(), {0, 1});
  Invoke.instructions = {
      op(0, "move-object", {0, Arity + 1}),
      op(1, "check-cast", {0}, {}, std::string("Lfixture/Tag;")),
      op(2, "move-object", {1, Arity + 2}),
      op(3, "check-cast", {1}, {}, Number.name),
      op(4, "invoke-virtual", {1}, {}, Number.methods[0].reference),
      op(5, "move-result", {1}),
      op(6, "invoke-virtual", TargetRegisters, {}, Typed.reference),
      op(7, "move-result-object", {0}),
      op(8, "return-object", {0})};
  Invoke.code_end = 9;
  auto Actor = klass(Typed.reference.owner, {Init, Typed, Invoke});
  Actor.access.insert("final");
  Actor.interfaces = {Fixed.name};
  return {Actor,
          Fixed,
          Function,
          Number,
          Integer,
          RuntimeObject,
          klass("Lfixture/Tag;")};
}

TEST(MobileDalvikJava,
     SignatureFreeOwnersKeepInheritedClosedIntegerCarrierContracts) {
  for (unsigned Arity : {2u, 3u, 21u})
    for (bool Link : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = inheritedClosedIntegerCarrierClasses(Arity);
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getString("status"), "partial");
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        const auto *Projections = R.getArray("generic_signature_projections");
        ASSERT_NE(Projections, nullptr);
        ASSERT_EQ(Projections->size(), 1u);
        EXPECT_EQ((*Projections)[0].getAsObject()->getString("declaration"),
                  "Lfixture/FixedFunction;");
        EXPECT_EQ((*Projections)[0]
                      .getAsObject()
                      ->getArray("changes")
                      ->front()
                      .getAsObject()
                      ->getString("kind"),
                  "checked-inherited-value-carrier-interface");
        for (const auto &C : Input)
          if (C.name == "Lfixture/IntegerActor;")
            EXPECT_FALSE(C.generic_signature);
      }
}

