  auto Make =
      method("make", {}, "Ljava/lang/Object;", 1,
             {op(0, "new-instance", {0}, {}, Core.name),
              op(1, "invoke-direct", {0}, {}, Core.methods[0].reference),
              op(2, "return-object", {0})});
  Make.generic_signature =
      "<S:Ljava/lang/Object;V:Ljava/lang/Object;>()Ljava/lang/Object;";
