  Classes[1].methods.push_back(method(
      "call", {Classes[1].name, "Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
      {op(0, "invoke-virtual", {0, 1}, {}, Bridge),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})}));
  auto Report = recover(Classes);
  EXPECT_EQ(Report.getInteger("method_count"), 4);
  EXPECT_EQ(Report.getInteger("recovered_method_count"), 2);
  EXPECT_EQ(Report.getInteger("projected_method_count"), 1);
  EXPECT_EQ(Report.getInteger("declaration_only_method_count"), 1);
  EXPECT_EQ(Report.getString("status"), "partial");
  auto Text = source(Report, 1);
  EXPECT_NE(Text.find("implements fixture.Contract<java.lang.String>"),
            std::string::npos);
  EXPECT_NE(Text.find("((fixture.Contract) ((fixture.Core) o0)).echo("),
            std::string::npos);
