std::vector<Class> inheritedDependentProviderClasses(bool ExternalApi,
                                                     bool ExternalProvider,
                                                     bool Encoded) {
  auto Input =
      inheritedDependentMethodFormalClasses(ExternalApi, false, true, Encoded);
  auto &Api = Input[0], &Provider = Input[1];
  Api.methods.resize(1);
  Provider.methods.resize(1);
  Provider.interfaces.clear();
  Provider.generic_signature =
      "<I:Ljava/lang/Object;J:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(3, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Provider.name;
  Provider.methods.push_back(Init);
  Provider.external = ExternalProvider;
  if (ExternalProvider)
    for (auto &Method : Provider.methods) {
      Method.instructions.clear();
      Method.registers = Method.code_end = 0;
    }
  Init.reference.owner = "Lfixture/Leaf;";
  Init.instructions[0].reference = Provider.methods[1].reference;
  auto Leaf = klass(Init.reference.owner, {Init});
  Leaf.superclass = Provider.name;
  Leaf.interfaces = {Api.name};
  Leaf.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;>" +
                           Provider.name.substr(0, Provider.name.size() - 1) +
                           "<TA;TB;>;" +
                           Api.name.substr(0, Api.name.size() - 1) + "<TA;>;";
  Input.push_back(Leaf);
  return Input;
}

