std::vector<Class> inheritedNominalMethodFormalClasses() {
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = true;
  auto Other = klass("Lfixture/OtherBound;");
  Other.external = true;
  Other.superclass = Bound.name;
  auto Box = klass("Lfixture/Pair;");
  Box.external = true;
  Box.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Make = method("make", {Box.name}, Box.name, 0, {});
  Make.access = {"public", "abstract"};
  Make.generic_signature =
      "<M:Lfixture/Bound;>(Lfixture/Pair<TC;TM;>;)Lfixture/Pair<TM;TM;>;";
  auto Contract = klass("Lfixture/Contract;", {Make});
  Contract.external = true;
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Make.access = {"public"};
  Make.registers = 3;
  Make.instructions = {op(0, "const/4", {0}, int64_t(0)),
                       op(1, "return-object", {0})};
  Make.code_end = 2;
  Make.generic_signature =
      "<R:Lfixture/Bound;>(Lfixture/Pair<TT;TR;>;)Lfixture/Pair<TR;TR;>;";
  auto Core = klass("Lfixture/Core;", {Make});
  Core.interfaces = {Contract.name};
  Core.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Contract<TT;>;";
  return {Core, Contract, Bound, Other, Box};
}

TEST(MobileDalvikJava, InheritedNominalMethodFormalsKeepCompleteBounds) {
  for (bool Link : {false, true}) {
    auto Input = inheritedNominalMethodFormalClasses();
    Budget B;
    const auto R =
        Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 1);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    EXPECT_EQ(R.getString("status"), "recovered");
    EXPECT_NE(source(R).find("<R extends fixture.Bound>"), std::string::npos);
    EXPECT_NE(source(R).find("fixture.Pair<T, R> arg0"), std::string::npos);
    EXPECT_NE(source(R).find("fixture.Pair<R, R> make("), std::string::npos);
  }
}

