std::vector<Class>
inheritedRecursiveClassMethodFormalClasses(bool Enum = false) {
  auto Input = inheritedNominalMethodFormalClasses();
  auto &Bound = Input[2];
  if (Enum) {
    Bound.name = "Ljava/lang/Enum;";
    Bound.access.insert("abstract");
    Bound.generic_signature = "<B:Ljava/lang/Enum<TB;>;>Ljava/lang/Object;";
    Input[3].superclass = Bound.name;
    Input[3].generic_signature = "Ljava/lang/Enum<Lfixture/OtherBound;>;";
  } else {
    Bound.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
    Input[3].generic_signature = "Lfixture/Bound<Ljava/lang/Object;>;";
  }
  const auto Name = Bound.name.substr(0, Bound.name.size() - 1);
  Input[1].methods[0].generic_signature =
      "<M:" + Name + "<TM;>;>(Lfixture/Pair<TC;TM;>;)Lfixture/Pair<TM;TM;>;";
  Input[0].methods[0].generic_signature =
      "<R:" + Name + "<TR;>;>(Lfixture/Pair<TT;TR;>;)Lfixture/Pair<TR;TR;>;";
  return Input;
}

std::vector<Class> specializedInterfaceCovarianceClasses(bool Parameters,
                                                         bool Dependency) {
  auto Get = method("get",
                    Parameters ? std::vector<std::string>{"Lfixture/Carrier;"}
                               : std::vector<std::string>{},
                    "Ljava/lang/Object;", 0, {});
  Get.access = {"public", "abstract"};
  Get.generic_signature =
      Parameters ? "(Lfixture/Carrier<TT;Ljava/lang/String;>;)TT;" : "()TT;";
  auto Contract = klass("Lfixture/Contract;", {Get});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.external = Dependency;
  auto Target = method(
      "get", Get.reference.parameters, "Ljava/lang/Byte;", Parameters ? 3 : 2,
      {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.access = {"public"};
  if (Parameters)
    Target.generic_signature = "(Lfixture/Carrier<Ljava/lang/Number;Ljava/lang/"
                               "String;>;)Ljava/lang/Byte;";
  auto Bridge = method(
      "get", Get.reference.parameters, "Ljava/lang/Object;", Parameters ? 3 : 2,
      {op(0, "invoke-virtual",
          Parameters ? std::vector<unsigned>{1, 2} : std::vector<unsigned>{1},
          {},
          MethodRef{"Lfixture/Core;", "get", Get.reference.parameters,
                    "Ljava/lang/Byte;"}),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Target, Bridge});
  Core.interfaces = {Contract.name};
  Core.generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Ljava/lang/Number;>;";
  auto Number = klass("Ljava/lang/Number;");
  Number.external = true;
  Number.access = {"public", "abstract"};
  auto Byte = klass("Ljava/lang/Byte;");
  Byte.external = true;
  Byte.access = {"public", "final"};
  Byte.superclass = Number.name;
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.external = true;
  Carrier.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Core, Contract, Number, Byte, Carrier};
}

TEST(MobileDalvikJava, SpecializedInterfaceResultsUseExactOriginalCovariance) {
  for (bool Parameters : {false, true})
    for (bool Dependency : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(Parameters);
          SCOPED_TRACE(Dependency);
          SCOPED_TRACE(Link);
          SCOPED_TRACE(Reverse);
          auto Input =
              specializedInterfaceCovarianceClasses(Parameters, Dependency);
          if (Reverse) {
            for (auto &Owner : Input)
              std::reverse(Owner.methods.begin(), Owner.methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          ClassMap Classes;
          for (const auto &Owner : Input)
            Classes.emplace(Owner.name, Owner);
          Budget B;
          const auto Signatures = validateGenericSignatures(Classes, B);
          const MethodRef Typed{
              "Lfixture/Core;", "get",
              Parameters ? std::vector<std::string>{"Lfixture/Carrier;"}
                         : std::vector<std::string>{},
              "Ljava/lang/Byte;"};
          auto Erased = Typed;
          Erased.returns = "Ljava/lang/Object;";
          auto Required = Erased;
          Required.owner = "Lfixture/Contract;";
          ASSERT_TRUE(Signatures.covariant_interface_returns.contains(
              {Typed, Required}));
          ASSERT_TRUE(Signatures.covariant_bridge_contracts.contains(
              {Erased, Required}));
          llvm::json::Object R;
          ASSERT_NO_THROW(R = Link ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input));
          EXPECT_EQ(R.getInteger("class_count"), Dependency ? 1 : 2);
          EXPECT_EQ(R.getInteger("method_count"), Dependency ? 2 : 3);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 1);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
        }
}

TEST(MobileDalvikJava, SpecializedCovarianceRejectsFullContractAndBridgeDrift) {
  for (bool Dependency : {false, true})
    for (bool Link : {false, true})
      for (bool Reverse : {false, true})
        for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
          SCOPED_TRACE(Dependency);
          SCOPED_TRACE(Link);
          SCOPED_TRACE(Reverse);
          SCOPED_TRACE(Mutation);
          auto Input = specializedInterfaceCovarianceClasses(true, Dependency);
          if (Mutation == 0)
            Input[0].methods.pop_back();
          else if (Mutation == 1)
            Input[0].methods[1].instructions[0].opcode = "invoke-direct";
          else if (Mutation == 2)
            Input[0].methods[1].instructions[0].registers = {1, 0};
          else if (Mutation == 3)
            Input[0].methods[1].access.erase("bridge");
          else if (Mutation == 4)
            Input[0].methods[0].generic_signature =
                "(Lfixture/Carrier<Ljava/lang/String;Ljava/lang/"
                "Number;>;)Ljava/lang/Byte;";
          else if (Mutation == 5)
            Input[3].superclass = "Ljava/lang/Object;";
          else if (Mutation == 6)
            Input[0].methods[0].generic_signature.reset();
          else if (Mutation == 7)
            Input[0].methods[1].instructions[2].registers = {1};
          else
            Input[0].methods[0].generic_signature =
                "<R:Ljava/lang/Object;>(Lfixture/Carrier<Ljava/lang/"
                "Number;Ljava/lang/String;>;)Ljava/lang/Byte;";
          if (Reverse) {
            for (auto &Owner : Input)
              std::reverse(Owner.methods.begin(), Owner.methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          Budget B;
          EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                       std::runtime_error);
        }
}

std::vector<Class> uncheckedCovariantParameterClasses(bool Dependency = false,
                                                      bool OwnResult = true,
                                                      bool Error = false) {
  auto Input = specializedInterfaceCovarianceClasses(true, Dependency);
  auto &Core = Input[0];
  auto &Root = Input[1];
  auto &Typed = Core.methods[0];
  auto &Bridge = Core.methods[1];
  if (OwnResult) {
    Core.generic_signature.reset();
    Root.generic_signature.reset();
    Root.methods[0].reference.returns = Root.name;
    Root.methods[0].generic_signature =
        "(Lfixture/Carrier<Ljava/lang/Number;Ljava/lang/String;>;)Lfixture/"
        "Contract;";
    Typed.reference.returns = Core.name;
    Typed.generic_signature = "(Lfixture/Carrier<Ljava/lang/Number;Ljava/lang/"
                              "String;>;)Lfixture/Core;";
    Bridge.reference.returns = Root.name;
    Bridge.instructions[0].reference = Typed.reference;
  }
  Typed.declared_throws = {"Lfixture/UncheckedLeaf;"};
  auto Leaf = klass("Lfixture/UncheckedLeaf;");
  Leaf.external = true;
  Leaf.superclass = "Lfixture/UncheckedMid;";
  auto Mid = klass("Lfixture/UncheckedMid;");
  Mid.external = true;
  Mid.superclass = Error ? "Ljava/lang/Error;" : "Ljava/lang/RuntimeException;";
  Input.push_back(Leaf);
  Input.push_back(Mid);
  return Input;
}

