TEST(MobileDalvikJava, FixedCovariantExceptionsRequireClosedOriginalContracts) {
  for (bool External : {false, true})
    for (bool Reverse : {false, true})
      for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Reverse);
        SCOPED_TRACE(Mutation);
        auto Input = fixedExceptionCovarianceClasses(External, false, true);
        auto &Required = Input[1].methods[0];
        auto &Typed = Input[0].methods[0];
        auto &Bridge = Input[0].methods[1];
        const auto RequiredRef = Required.reference;
        const auto TypedRef = Typed.reference;
        if (Mutation == 0)
          Typed.declared_throws = {"Ljava/lang/Throwable;"};
        else if (Mutation == 1)
          Typed.declared_throws->push_back("Ljava/lang/Exception;");
        else if (Mutation == 2)
          Required.generic_signature =
              *Required.generic_signature + "^Lfixture/First;";
        else if (Mutation == 3)
          Typed.generic_signature =
              *Typed.generic_signature + "^Lfixture/First;";
        else if (Mutation == 4)
          Typed.generic_signature = "(Lfixture/Carrier<Ljava/lang/String;Ljava/"
                                    "lang/Number;>;)Lfixture/Core;";
        else if (Mutation == 5)
          Bridge.declared_throws = {"Lfixture/Second;"};
        else if (Mutation == 6)
          Bridge.access.erase("bridge");
        else if (Mutation == 7)
          Bridge.instructions[0].registers = {1, 0};
        else if (Mutation == 8)
          Typed.declared_throws = {"Lfixture/UnknownFailure;"};
        else if (Mutation == 9)
          Required.declared_throws = {"Lfixture/UnknownFailure;"};
        else if (Mutation == 10)
          Required.generic_signature =
              "(Lfixture/Carrier<Ljava/lang/Number;Ljava/lang/String;>;)"
              "Lfixture/Parent<Ljava/lang/Number;>;";
        if (Reverse) {
          std::reverse(Input.begin(), Input.end());
          for (auto &Owner : Input)
            std::reverse(Owner.methods.begin(), Owner.methods.end());
        }
        Budget B;
        if (Mutation >= 11) {
          auto Classes = linkClasses(Input, B);
          auto Plans = validateGenericSignatures(Classes, B);
          ASSERT_EQ(Plans.closed_declared_throws.erase(
                        Mutation == 11 ? RequiredRef : TypedRef),
                    1u);
          EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                       std::runtime_error);
        } else
          EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                       std::runtime_error);
      }
}

std::vector<Class> parameterReturnCovarianceClasses(bool External = false,
                                                    bool Interface = false,
                                                    bool CarrierInput = false,
                                                    bool Error = false) {
  const std::vector<std::string> Erased{"Ljava/lang/Object;",
                                        CarrierInput ? "Lfixture/Carrier;"
                                                     : "Ljava/lang/Object;"};
  auto Required = method("put", Erased, "Ljava/lang/Object;", 3,
                         {op(0, "return-object", {2})});
  Required.access = {"public"};
  Required.generic_signature =
      CarrierInput ? "(TK;Lfixture/Carrier<TV;Ljava/lang/String;>;)TV;"
                   : "(TK;TV;)TV;";
  if (Interface) {
    Required.access.insert("abstract");
    Required.instructions.clear();
    Required.registers = Required.code_end = 0;
  }
  auto Root = klass("Lfixture/Root;", {Required});
  Root.external = External;
  Root.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Interface)
    Root.access = {"public", "abstract", "interface"};
  else {
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(3, "return-void")});
    Init.access = {"public", "constructor"};
    Init.reference.owner = Root.name;
    Root.methods.push_back(Init);
  }
  auto Typed = method("put", {"Ljava/lang/String;", Erased[1]},
                      "Lfixture/Core;", 3, {op(0, "return-object", {0})});
  Typed.access = {"public"};
  Typed.declared_throws = {"Lfixture/UncheckedLeaf;"};
  if (CarrierInput)
    Typed.generic_signature = "(Ljava/lang/String;Lfixture/Carrier<Ljava/lang/"
                              "Object;Ljava/lang/String;>;)Lfixture/Core;";
  auto Bridge =
      method("put", Erased, "Ljava/lang/Object;", 3,
             {op(0, "check-cast", {1}, {}, std::string("Ljava/lang/String;")),
              op(2, "invoke-virtual", {0, 1, 2}, {}, Typed.reference),
              op(5, "move-result-object", {1}), op(6, "return-object", {1})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Typed, Bridge});
  if (Interface) {
    Core.interfaces = {Root.name};
    Core.generic_signature = "Ljava/lang/Object;Lfixture/Root<Ljava/lang/"
                             "String;Ljava/lang/Object;>;";
  } else {
    Core.superclass = Root.name;
    Core.generic_signature =
        "Lfixture/Root<Ljava/lang/String;Ljava/lang/Object;>;";
  }
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{*Core.superclass, "<init>", {}, "V"}),
                      op(3, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Core.name;
  Core.methods.push_back(Init);
  if (External)
    for (auto &Method : Root.methods) {
      Method.instructions.clear();
      Method.registers = Method.code_end = 0;
    }
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.external = true;
  Carrier.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Leaf = klass("Lfixture/UncheckedLeaf;");
  Leaf.external = true;
  Leaf.superclass = "Lfixture/UncheckedMid;";
  auto Mid = klass("Lfixture/UncheckedMid;");
  Mid.external = true;
  Mid.superclass = Error ? "Ljava/lang/Error;" : "Ljava/lang/RuntimeException;";
  return {Core, Root, Carrier, Leaf, Mid};
}

