std::vector<Class> objectRootCovarianceClasses() {
  const std::string Name = "Lfixture/Core;";
  const std::string Exception = "Ljava/lang/CloneNotSupportedException;";
  auto ObjectClone = method("clone", {}, "Ljava/lang/Object;", 0, {});
  ObjectClone.access = {"protected", "native"};
  ObjectClone.declared_throws = {Exception};
  auto Object = klass("Ljava/lang/Object;", {ObjectClone});
  Object.external = true;
  Object.superclass.reset();
  auto Init = method("<init>", {}, "V", 0, {});
  Init.reference.owner = Object.name;
  Init.access = {"public", "constructor"};
  Object.methods.push_back(Init);
  auto Failure = klass(Exception);
  Failure.external = true;
  Failure.superclass = "Ljava/lang/Exception;";
  auto Marker = klass("Ljava/lang/Cloneable;");
  Marker.external = true;
  Marker.access = {"public", "abstract", "interface"};
  auto Target =
      method("clone", {}, Name, 2,
             {op(0, "invoke-super", {1}, {}, Object.methods[0].reference),
              op(3, "move-result-object", {0}),
              op(4, "check-cast", {0}, {}, Name), op(6, "return-object", {0})});
  Target.access = {"public"};
  Target.generic_signature = "()Lfixture/Core<TT;>;";
  Target.declared_throws = {Exception};
  auto Bridge =
      method("clone", {}, Object.name, 2,
             {op(0, "invoke-virtual", {1}, {}, Target.reference),
              op(3, "move-result-object", {0}), op(4, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.declared_throws = {Exception};
  Init.reference.owner = Name;
  Init.registers = 1;
  Init.instructions = {
      op(0, "invoke-direct", {0}, {}, Object.methods[1].reference),
      op(3, "return-void")};
  Init.code_end = 4;
  auto Core = klass(Name, {Init, Target, Bridge});
  Core.interfaces = {Marker.name};
  Core.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Ljava/lang/Cloneable;";
  auto Child = klass("Lfixture/Child;");
  Child.superclass = Name;
  Child.generic_signature = "<U:Ljava/lang/Object;>Lfixture/Core<TU;>;";
  Init.reference.owner = Child.name;
  Init.instructions[0].reference = Core.methods[0].reference;
  Child.methods = {Init};
  return {Core, Child, Object, Marker, Failure};
}

