TEST(MobileDalvikJava, NearerClassContractsDoNotHideMissingProofsOrFinalSlots) {
  for (bool Link : {false, true})
    for (bool Reverse : {false, true})
      for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
        SCOPED_TRACE(Link);
        SCOPED_TRACE(Reverse);
        SCOPED_TRACE(Mutation);
        auto Input = nearerGenericClassCovarianceClasses();
        if (Mutation == 0)
          Input[0].methods.pop_back();
        else if (Mutation == 1)
          Input[0].methods[1].instructions[0].opcode = "invoke-direct";
        else if (Mutation == 2)
          Input[2].methods[0].declared_throws = {"Ljava/lang/Exception;"};
        else if (Mutation == 3)
          Input[3].methods[0].access.insert("final");
        else if (Mutation == 4) {
          auto Override = Input[2].methods[0];
          Override.reference.owner = Input[1].name;
          Override.reference.returns = "Ljava/lang/String;";
          Input[1].methods.push_back(Override);
        } else if (Mutation == 5)
          Input[2].enclosing = "Lfixture/Unknown;";
        else if (Mutation == 6)
          Input[2].methods[0].access.insert("static");
        else
          Input[0].methods[1].access.erase("bridge");
        if (Reverse) {
          for (auto &Owner : Input)
            std::reverse(Owner.methods.begin(), Owner.methods.end());
          std::reverse(Input.begin(), Input.end());
        }
        Budget B;
        if (Mutation == 2) {
          // Empty result-bridge metadata is now supported and must disclose
          // the nearest declaration's regenerated exception, not the root's.
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          bool Found = false;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") !=
                "Lfixture/Core;->clone()Ljava/lang/Object;")
              continue;
            EXPECT_EQ(Row->getString("bridge_exception_source"),
                      "Lfixture/Middle;->clone()Ljava/lang/Object;");
            const auto *Throws = Row->getArray("source_bridge_declared_throws");
            ASSERT_NE(Throws, nullptr);
            ASSERT_EQ(Throws->size(), 1u);
            EXPECT_EQ((*Throws)[0].getAsString(), "Ljava/lang/Exception;");
            EXPECT_NE(Row->getArray("metadata_differences"), nullptr);
            Found = true;
          }
          EXPECT_TRUE(Found);
        } else
          EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                       std::runtime_error);
      }
}

std::vector<Class> originalMethodFormalParameterBridgeClasses(bool Enum) {
  auto Input = inheritedRecursiveClassMethodFormalClasses(Enum);
  const auto Bound = Input[2].name;
  auto &Contract = Input[1].methods[0];
  Contract.reference.name = "pick";
  Contract.reference.parameters = {"Ljava/lang/Class;", "Ljava/lang/Object;"};
  Contract.reference.returns = Bound;
  const auto Prefix = Bound.substr(0, Bound.size() - 1);
  Contract.generic_signature =
      "<M:" + Prefix + "<TM;>;>(Ljava/lang/Class<TM;>;TC;)TM;";
  auto &Target = Input[0].methods[0];
  Target.reference.name = "pick";
  Target.reference.parameters = {"Ljava/lang/Class;", "Ljava/lang/String;"};
  Target.reference.returns = Bound;
  Target.generic_signature =
      "<R:" + Prefix + "<TR;>;>(Ljava/lang/Class<TR;>;Ljava/lang/String;)TR;";
  Input[0].generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Ljava/lang/String;>;";
  auto Bridge =
      method("pick", {"Ljava/lang/Class;", "Ljava/lang/Object;"}, Bound, 3,
             {op(0, "check-cast", {2}, {}, std::string("Ljava/lang/String;")),
              op(1, "invoke-virtual", {0, 1, 2}, {}, Target.reference),
              op(2, "move-result-object", {1}), op(3, "return-object", {1})});
  Bridge.reference.owner = Input[0].name;
  Bridge.access = {"public", "bridge", "synthetic"};
  Input[0].methods.push_back(Bridge);
  auto ClassType = klass("Ljava/lang/Class;");
  ClassType.external = true;
  ClassType.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(ClassType);
  return Input;
}

