std::vector<Class> fixedParameterizedMethodClasses(bool Inherited) {
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Put = method("put", {Box.name}, "V", 0, {});
  Put.access = {"public", "abstract"};
  Put.generic_signature = "(Lfixture/Box<-Lfixture/Tag;>;)V";
  auto Root = klass("Lfixture/FixedRoot;", {Put});
  Root.access = {"public", "abstract", "interface"};
  auto Echo =
      method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Put.access;
  Echo.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  auto Child = klass("Lfixture/FixedChild;", {Echo});
  Child.access = Root.access;
  Child.interfaces = {Root.name};
  Put.access = {"public"};
  Put.registers = 2;
  Put.instructions = {op(0, "return-void")};
  Put.code_end = 1;
  Echo.access = Put.access;
  Echo.registers = 2;
  Echo.instructions = {op(0, "return-object", {1})};
  Echo.code_end = 1;
  auto Owner = klass("Lfixture/FixedOwner;", {Put, Echo});
  Owner.interfaces = {Inherited ? Child.name : Root.name};
  return {Root,
          Child,
          Owner,
          Box,
          klass("Lfixture/Tag;"),
          klass("Lfixture/Other;")};
}

