TEST(MobileDalvikJava, ScopedWildcardDefaultsRequireComposedSharedReceipts) {
  for (bool Closed : {false, true})
    for (bool Reverse : {false, true})
      for (unsigned Mutation = 0; Mutation < 4; ++Mutation) {
        SCOPED_TRACE(Closed);
        SCOPED_TRACE(Reverse);
        SCOPED_TRACE(Mutation);
        auto Input = scopedWildcardDefaultClasses(Closed, true);
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        auto Classes = linkClasses(Input, B);
        auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_EQ(Plans.source_default_contracts.size(), 1);
        if (Mutation == 0)
          Plans.source_default_contracts.clear();
        else {
          auto &Contract = Plans.source_default_contracts.begin()->second;
          if (Mutation == 1) {
            Contract.types.at(*Contract.result).kind =
                GenericType::Kind::Primitive;
            Contract.types.at(*Contract.result).primitive = 'I';
          } else if (Mutation == 2)
            Contract.types.at(Contract.parameters[0])
                .segments[0]
                .arguments[0]
                .variance = GenericTypeArgument::Variance::Super;
          else
            for (auto &Type : Contract.types)
              if (Type.kind == GenericType::Kind::TypeVariable)
                Type.variable_owner = "Lfixture/WrongOwner;";
        }
        EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                     std::runtime_error);
      }
}

std::vector<Class> rawSelfInterfaceDefaultClasses(bool External = true,
                                                  bool Range = false) {
  auto Required = method("compareTo", {"Ljava/lang/Object;"}, "I", 0, {});
  Required.access = {"public", "abstract"};
  Required.generic_signature = "(TX;)I";
  auto Parent = klass("Lfixture/Order;", {Required});
  Parent.external = External;
  Parent.access = {"public", "abstract", "interface"};
  Parent.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Target =
      method("compareTo", {"Lfixture/Self;"}, "I", 3,
             {op(0, "const/4", {0}, int64_t(7)), op(1, "return", {0})});
  Target.access = {"public"};
  auto Bridge = method(
      "compareTo", {"Ljava/lang/Object;"}, "I", 2,
      {op(0, "check-cast", {1}, {}, std::string("Lfixture/Self;")),
       op(1, Range ? "invoke-interface/range" : "invoke-interface", {0, 1}, {},
          MethodRef{"Lfixture/Self;", "compareTo", {"Lfixture/Self;"}, "I"}),
       op(2, "move-result", {1}), op(3, "return", {1})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Self = klass("Lfixture/Self;", {Target, Bridge});
  Self.access = {"public", "abstract", "interface"};
  Self.interfaces = {Parent.name};
  Self.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/"
                           "Order<Lfixture/Self<TT;>;>;";
  return {Self, Parent};
}

