std::vector<Class> originalRawParameterClasses(bool Inherited = false,
                                               bool Default = false) {
  auto Box = klass("Lfixture/RawParameterBox;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Accept =
      method("accept", {Box.name, "Lfixture/RawParameterTag;"}, "V", 0, {});
  Accept.access = {"public", "abstract"};
  Accept.generic_signature =
      "(Lfixture/RawParameterBox<*>;Lfixture/RawParameterTag;)V";
  if (Default) {
    Accept.access.erase("abstract");
    Accept.registers = 3;
    Accept.instructions = {op(0, "return-void")};
    Accept.code_end = 1;
  }
  auto Api = klass("Lfixture/RawParameterApi;", {Accept});
  Api.access = {"public", "abstract", "interface"};
  Accept.access = {"public", "final"};
  Accept.generic_signature.reset();
  Accept.registers = 3;
  Accept.instructions = {op(0, "return-void")};
  Accept.code_end = 1;
  auto Owner =
      klass("Lfixture/RawParameterOwner;",
            Inherited ? std::vector<Method>{} : std::vector<Method>{Accept});
  Owner.access = {"public", "final", "synthetic"};
  Owner.interfaces = {Api.name};
  auto Parent =
      klass("Lfixture/RawParameterParent;",
            Inherited ? std::vector<Method>{Accept} : std::vector<Method>{});
  if (Inherited)
    Owner.superclass = Parent.name;
  return {Api, Owner, Box, klass("Lfixture/RawParameterTag;"), Parent};
}

std::vector<Class> scopedOriginalRawParameterClasses(bool Inherited,
                                                     bool Local) {
  auto Input = originalRawParameterClasses(Inherited);
  auto &Api = Input[0];
  Api.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.methods[0].generic_signature =
      "(Lfixture/RawParameterBox<-TA;>;Lfixture/RawParameterTag;)V";
  auto &Owner = Input[1];
  Owner.generic_signature =
      std::string(Local ? "" : "<C:Ljava/lang/Object;D:Ljava/lang/Object;>") +
      (Inherited ? "Lfixture/RawParameterParent;" : "Ljava/lang/Object;") +
      "Lfixture/RawParameterApi<Lfixture/RawParameterBox<+TC;>;>;";
  if (Local) {
    auto Ctor = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{*Owner.superclass, "<init>", {}, "V"}),
                        op(1, "return-void")});
    Ctor.reference.owner = Owner.name;
    Ctor.access = {"constructor"};
    Owner.methods.push_back(Ctor);
    if (Inherited) {
      Ctor.reference.owner = Input[4].name;
      Ctor.access = {"public", "constructor"};
      Ctor.instructions[0].reference =
          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
      Input[4].methods.push_back(Ctor);
    }
    auto Make =
        method("make", {}, "Ljava/lang/Object;", 1,
               {op(0, "new-instance", {0}, {}, Owner.name),
                op(1, "invoke-direct", {0}, {}, Owner.methods.back().reference),
                op(2, "return-object", {0})});
    Make.generic_signature =
        "<C:Ljava/lang/Object;D:Ljava/lang/Object;>()Ljava/lang/Object;";
    auto Host = klass("Lfixture/RawParameterHost;", {Make});
    Owner.enclosing_method = Host.methods[0].reference;
    Owner.inner_class_present = true;
    Owner.inner_access = {"final", "static"};
    Input.push_back(Host);
  }
  return Input;
}

