std::vector<Class> nominalElementGetterClasses(bool Inherited) {
  auto List = klass("Ljava/util/List;");
  List.external = true;
  List.access = {"public", "abstract", "interface"};
  List.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Base = klass("Lfixture/ElementBase;");
  Base.access = List.access;
  auto Leaf = klass("Lfixture/ElementLeaf;");
  Leaf.interfaces = {Base.name};
  auto Get = method("get", {}, List.name, 0, {});
  Get.access = {"public", "abstract"};
  Get.generic_signature = "()Ljava/util/List<Lfixture/ElementBase;>;";
  auto Api = klass("Lfixture/ElementApi;", {Get});
  Api.access = Base.access;
  auto Echo =
      method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Get.access;
  Echo.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  auto Child = klass("Lfixture/ElementChild;", {Echo});
  Child.access = Api.access;
  Child.interfaces = {Api.name};
  const FieldRef Values{"Lfixture/ElementOwner;", "values", List.name};
  Get.access = {"public"};
  Get.generic_signature = "()Ljava/util/List<Lfixture/ElementLeaf;>;";
  Get.registers = 2;
  Get.instructions = {op(0, "iget-object", {0, 1}, {}, Values),
                      op(1, "return-object", {0})};
  Get.code_end = 2;
  Echo.access = Get.access;
  Echo.registers = 2;
  Echo.instructions = {op(0, "return-object", {1})};
  Echo.code_end = 1;
  auto Init =
      method("<init>", {List.name}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "iput-object", {1, 0}, {}, Values), op(2, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Ljava/util/List<Lfixture/ElementLeaf;>;)V";
  auto Owner = klass(Values.owner, {Get, Echo, Init});
  Owner.access = {"public", "final"};
  Owner.interfaces = {Inherited ? Child.name : Api.name};
  Owner.fields = {{Values,
                   {"private", "final"},
                   {},
                   "Ljava/util/List<Lfixture/ElementLeaf;>;"}};
  return {Api, Child, Owner, List, Base, Leaf, klass("Lfixture/OtherElement;")};
}

