        const auto *Projections = R.getArray("generic_signature_projections");
        ASSERT_NE(Projections, nullptr);
        ASSERT_EQ(Projections->size(), 1u);
        const auto *Change = (*Projections)[0]
                                 .getAsObject()
                                 ->getArray("changes")
                                 ->front()
                                 .getAsObject();
        EXPECT_EQ(Change->getString("kind"),
                  "inherited-nominal-getter-result-erasure");
        EXPECT_EQ(Change->getString("source_type"), "()Ljava/util/List;");
        for (const auto &C : Input)
          if (C.name == "Lfixture/ElementOwner;") {
            EXPECT_FALSE(C.generic_signature);
            EXPECT_EQ(C.methods[0].generic_signature,
                      "()Ljava/util/List<Lfixture/ElementLeaf;>;");
            EXPECT_EQ(C.fields[0].generic_signature,
                      "Ljava/util/List<Lfixture/ElementLeaf;>;");
          }
