std::vector<Class> plainBoxedGetterClasses(const std::string &Primitive) {
  const bool Wide = Primitive == "J" || Primitive == "D";
  const unsigned Words = Wide ? 2 : 1;
  auto Box = klass("Lfixture/ScalarBox;");
  Box.external = true;
  auto Boxing = method("box", {Primitive}, Box.name, 0, {});
  Boxing.reference.owner = Box.name;
  Box.methods.push_back(Boxing);
  auto Get = method("get", {}, "Ljava/lang/Object;", 0, {});
  Get.access = {"public", "abstract"};
  auto Echo =
      method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Get.access;
  Echo.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  auto Api = klass("Lfixture/ScalarApi;", {Get, Echo});
  Api.access = {"public", "abstract", "interface"};
  const FieldRef Value{"Lfixture/ScalarOwner;", "value", Primitive};
  auto Typed =
      method("readValue", {}, Primitive, Words + 1,
             {op(0, Wide ? "iget-wide" : "iget", {0, Words}, {}, Value),
              op(1, Wide ? "return-wide" : "return", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = Value.owner;
  Get.access = {"public", "bridge", "synthetic"};
  Get.registers = Words + 1;
  const std::vector<unsigned> Arguments =
      Wide ? std::vector<unsigned>{0, 1} : std::vector<unsigned>{0};
  Get.instructions = {op(0, "invoke-virtual", {Words}, {}, Typed.reference),
                      op(1, Wide ? "move-result-wide" : "move-result", {0}),
                      op(2, "invoke-static", Arguments, {}, Boxing.reference),
                      op(3, "move-result-object", {0}),
                      op(4, "return-object", {0})};
  Get.code_end = 5;
  Echo.access = {"public"};
  Echo.registers = 2;
  Echo.instructions = {op(0, "return-object", {1})};
  Echo.code_end = 1;
  auto Init = method("<init>", {Primitive}, "V", Words + 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, Wide ? "iput-wide" : "iput", {1, 0}, {}, Value),
                      op(2, "return-void")});
  Init.access = {"public", "constructor"};
  auto Owner = klass(Value.owner, {Typed, Get, Echo, Init});
  Owner.access = {"public", "final"};
  Owner.interfaces = {Api.name};
  Owner.fields = {{Value, {"private", "final"}, {}}};
  return {Api, Owner, Box};
}

std::vector<Class> comparablePredicateClasses(bool External, bool Copy,
                                              bool Second) {
  const std::string Character = "Ljava/lang/Character;";
  const std::string Comparable = "Ljava/lang/Comparable;";
  auto Api = klass("Lfixture/Predicate;");
  Api.access = {"public", "abstract", "interface"};
  Api.external = External;
  Api.generic_signature = "<T::Ljava/lang/Comparable<-TT;>;>Ljava/lang/Object;";
  auto Check = method("contains", {Comparable}, "Z", 0, {});
  Check.access = {"public", "abstract"};
  Check.generic_signature = "(TT;)Z";
  auto Get = method("get", {}, Comparable, 0, {});
  Get.access = Check.access;
  Get.generic_signature = "()TT;";
  Api.methods = {Check, Get};
  for (auto &M : Api.methods)
    M.reference.owner = Api.name;
  auto Target =
      method("contains", {"C"}, "Z", 3,
             {op(0, "const/4", {0}, int64_t{1}), op(1, "return", {0})});
  Target.access = {"public"};
  Target.reference.owner = "Lfixture/PredicateCore;";
  Check.reference.owner = Target.reference.owner;
  Check.access = {"public", "bridge", "synthetic"};
  Check.generic_signature.reset();
  Check.registers = 3;
  unsigned Argument = 2;
  if (Copy) {
    Check.instructions.push_back(op(0, "move-object", {0, Argument}));
    Argument = 0;
  }
  const unsigned At = Check.instructions.size();
  Check.instructions.insert(
      Check.instructions.end(),
      {op(At, "check-cast", {Argument}, {}, Character),
       op(At + 2, "invoke-virtual", {Argument}, {},
          MethodRef{Character, "charValue", {}, "C"}),
       op(At + 5, "move-result", {0}),
       op(At + 6, "invoke-virtual", {1, 0}, {}, Target.reference),
       op(At + 9, "move-result", {0}), op(At + 10, "return", {0})});
  Check.code_end = At + 11;
  auto TypedGet =
      method("get", {}, Character, 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  TypedGet.access = {"public"};
  TypedGet.reference.owner = Target.reference.owner;
  Get.access = {"public", "bridge", "synthetic"};
  Get.generic_signature.reset();
  Get.registers = 2;
  Get.instructions = {op(0, "invoke-virtual", {1}, {}, TypedGet.reference),
                      op(3, "move-result-object", {0}),
                      op(4, "return-object", {0})};
  Get.code_end = 5;
  auto Core = klass(Target.reference.owner, {Target, Check, TypedGet, Get});
  Core.access = {"public", "final"};
  Core.interfaces = {Api.name};
  Core.generic_signature =
      "Ljava/lang/Object;Lfixture/Predicate<Ljava/lang/Character;>;";
  auto Box = klass(Character, {method("charValue", {}, "C", 0, {})});
  Box.external = true;
  Box.access = {"public", "final"};
  Box.methods[0].access = {"public"};
  Box.interfaces = {Comparable};
  Box.generic_signature =
      "Ljava/lang/Object;Ljava/lang/Comparable<Ljava/lang/Character;>;";
  auto Bound = klass(Comparable);
  Bound.access = {"public", "abstract", "interface"};
  Bound.external = true;
  Bound.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  std::vector<Class> Input{Core, Api, Box, Bound};
  if (Second) {
    auto Other = Api;
    Other.name = "Lfixture/OtherPredicate;";
    for (auto &M : Other.methods)
      M.reference.owner = Other.name;
    Input[0].interfaces.push_back(Other.name);
    *Input[0].generic_signature +=
        "Lfixture/OtherPredicate<Ljava/lang/Character;>;";
    Input.push_back(Other);
  }
  return Input;
}

