std::vector<Class> comparableCarrierPredicateClasses(bool External, bool Copy,
                                                     bool Wide) {
  auto Input = comparableNumericPredicateClasses(External, Copy, true);
  const std::string Box = "Lfixture/ScalarBox;", Scalar = Wide ? "J" : "I";
  for (auto &Cls : Input) {
    if (Cls.generic_signature) {
      auto &Text = *Cls.generic_signature;
      for (size_t At = 0;
           (At = Text.find("Ljava/lang/Double;", At)) != std::string::npos;)
        Text.replace(At, std::string("Ljava/lang/Double;").size(), Box);
    }
  }
  auto &Core = Input[0];
  auto &Carrier = Input[2];
  Carrier.name = Box;
  Carrier.superclass = "Ljava/lang/Object;";
  Carrier.generic_signature =
      "Ljava/lang/Object;Ljava/lang/Comparable<Lfixture/ScalarBox;>;";
  auto Read = method("read", {}, Scalar, 0, {});
  Read.access = {"public"};
  Read.reference.owner = Box;
  auto Make = method("make", {Scalar}, Box, 0, {});
  Make.access = {"public", "static"};
  Make.reference.owner = Box;
  Carrier.methods = {Read, Make};
  for (size_t N : {0u, 4u}) {
    auto &Target = Core.methods[N];
    Target.reference.name += "Scalar";
    Target.reference.parameters.assign(Target.reference.parameters.size(),
                                       Scalar);
    if (!Wide)
      Target.registers -= Target.reference.parameters.size();
    auto &Bridge = Core.methods[N + 1];
    const unsigned Arity = Target.reference.parameters.size(),
                   Words = Wide ? 2 : 1;
    const unsigned Self = Words * Arity;
    Bridge.registers = Self + Arity + 1;
    Bridge.instructions.clear();
    uint32_t At = 0;
    std::vector<unsigned> Arguments{Self};
    for (unsigned I = 0; I < Arity; ++I) {
      unsigned Checked = Self + I + 1;
      if (Copy) {
        Bridge.instructions.push_back(
            op(At++, "move-object", {Words * I, Checked}));
        Checked = Words * I;
      }
      Bridge.instructions.push_back(op(At, "check-cast", {Checked}, {}, Box));
      Bridge.instructions.push_back(
          op(At + 2, "invoke-virtual", {Checked}, {}, Read.reference));
      Bridge.instructions.push_back(
          op(At + 5, Wide ? "move-result-wide" : "move-result", {Words * I}));
      At += 6;
      for (unsigned W = 0; W < Words; ++W)
        Arguments.push_back(Words * I + W);
    }
    Bridge.instructions.push_back(
        op(At, "invoke-virtual", Arguments, {}, Target.reference));
    Bridge.instructions.push_back(op(At + 3, "move-result", {0}));
    Bridge.instructions.push_back(op(At + 4, "return", {0}));
    Bridge.code_end = At + 5;
  }
  auto &Get = Core.methods[2], &Bridge = Core.methods[3];
  Get.reference.name = "readScalar";
  Get.reference.returns = Scalar;
  Get.registers = Wide ? 3 : 2;
  Get.instructions = {
      op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t{0}),
      op(2, Wide ? "return-wide" : "return", {0})};
  Get.code_end = 3;
  Bridge.registers = Wide ? 3 : 2;
  Bridge.instructions = {
      op(0, "invoke-virtual", {Wide ? 2u : 1u}, {}, Get.reference),
      op(3, Wide ? "move-result-wide" : "move-result", {0}),
      op(4, "invoke-static",
         Wide ? std::vector<unsigned>{0, 1} : std::vector<unsigned>{0}, {},
         Make.reference),
      op(7, "move-result-object", {0}), op(8, "return-object", {0})};
  Bridge.code_end = 9;
  Input.erase(Input.begin() +
              4); // The original boxed Number declaration is unused.
  return Input;
}

