std::vector<Class> projectedComparableCarrierClasses(bool External, bool Wide) {
  auto Input = comparableCarrierPredicateClasses(External, true, Wide);
  auto &Carrier = Input[2], &Comparable = Input[3];
  Carrier.external = false;
  auto &Read = Carrier.methods[0], &Make = Carrier.methods[1];
  Read.registers = Wide ? 3 : 2;
  Read.instructions = {
      op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t{0}),
      op(2, Wide ? "return-wide" : "return", {0})};
  Read.code_end = 3;
  Make.registers = Wide ? 3 : 2;
  Make.instructions = {op(0, "const/4", {0}, int64_t{0}),
                       op(1, "return-object", {0})};
  Make.code_end = 2;
  auto Compare =
      method("compareTo", {"Ljava/lang/Object;"}, "I", 3,
             {op(0, "check-cast", {2}, {}, Carrier.name),
              op(2, "const/4", {0}, int64_t{1}), op(3, "return", {0})});
  Compare.access = {"public", "bridge", "synthetic"};
  Compare.reference.owner = Carrier.name;
  Carrier.methods.push_back(Compare);
  Compare.reference.owner = Comparable.name;
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TT;)I";
  Compare.instructions.clear();
  Compare.registers = Compare.code_end = 0;
  Comparable.methods.push_back(Compare);
  return Input;
}

