std::vector<Class> guardedScalarParameterClasses(const std::string &Primitive,
                                                 bool External, bool Copy) {
  auto Api = klass("Lfixture/GuardApi;");
  Api.access = {"public", "abstract", "interface"};
  Api.external = External;
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Contains = method("contains", {"Ljava/lang/Object;"}, "Z", 0, {});
  Contains.access = {"public", "abstract"};
  auto Echo =
      method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Contains.access;
  Echo.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  Api.methods = {Contains, Echo};
  for (auto &M : Api.methods)
    M.reference.owner = Api.name;
  const bool Wide = Primitive == "J" || Primitive == "D";
  const unsigned Words = Wide ? 2 : 1;
  const FieldRef Value{"Lfixture/GuardBox;", "value", Primitive};
  const std::string Read = Primitive == "Z"   ? "iget-boolean"
                           : Primitive == "B" ? "iget-byte"
                           : Primitive == "S" ? "iget-short"
                           : Primitive == "C" ? "iget-char"
                           : Wide             ? "iget-wide"
                                              : "iget";
  auto Unbox = method("read", {}, Primitive, Words + 1,
                      {op(0, Read, {0, Words}, {}, Value),
                       op(1, Wide ? "return-wide" : "return", {0})});
  Unbox.access = {"public"};
  auto Box = klass(Value.owner, {Unbox});
  Box.access = {"public", "final"};
  Box.fields = {{Value, {"public"}, {}}};
  auto Target =
      method("checkScalar", {Primitive}, "Z", Words + 2,
             {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  Target.access = {"public"};
  Target.reference.owner = "Lfixture/GuardOwner;";
  Contains.access = {"public", "final", "bridge"};
  Contains.registers = Words + 2;
  Contains.instructions = {op(0, "instance-of", {0, Words + 1}, {}, Box.name),
                           op(1, "if-nez", {0}, {}, {}, 4),
                           op(2, "const/4", {0}, int64_t(0)),
                           op(3, "return", {0})};
  unsigned Checked = Words + 1;
  if (Copy) {
    Contains.instructions.push_back(op(4, "move-object", {0, Checked}));
    Checked = 0;
  }
  const uint32_t At = Contains.instructions.size();
  Contains.instructions.push_back(
      op(At, "check-cast", {Checked}, {}, Box.name));
  Contains.instructions.push_back(
      op(At + 1, "invoke-virtual", {Checked}, {}, Box.methods[0].reference));
  Contains.instructions.push_back(
      op(At + 2, Wide ? "move-result-wide" : "move-result", {0}));
  std::vector<unsigned> Arguments{Words};
  for (unsigned I = 0; I < Words; ++I)
    Arguments.push_back(I);
  Contains.instructions.push_back(
      op(At + 3, "invoke-virtual", Arguments, {}, Target.reference));
  Contains.instructions.push_back(op(At + 4, "move-result", {0}));
  Contains.instructions.push_back(op(At + 5, "return", {0}));
  Contains.code_end = At + 6;
  Echo.access = {"public"};
  Echo.registers = 2;
  Echo.instructions = {op(0, "return-object", {1})};
  Echo.code_end = 1;
  auto Owner = klass(Target.reference.owner, {Target, Contains, Echo});
  Owner.access = {"public", "final"};
  Owner.interfaces = {Api.name};
  Owner.generic_signature =
      "Ljava/lang/Object;Lfixture/GuardApi<Ljava/lang/String;>;";
  return {Api, Owner, Box};
}

