        SCOPED_TRACE(Mutation);
        auto Input = guardedScalarParameterClasses("J", External, true);
        auto &Owner = Input[1];
        auto &Bridge = Owner.methods[1];
        if (Mutation == 0)
          Bridge.instructions[0].registers[1] = 2;
        else if (Mutation == 1)
          Bridge.instructions[1].target = 5;
        else if (Mutation == 2)
          Bridge.instructions[2].literal = int64_t(1);
        else if (Mutation == 3)
          Bridge.instructions[4].registers[1] = 2;
        else if (Mutation == 4)
          Bridge.instructions[5].reference = "Ljava/lang/String;";
        else if (Mutation == 5)
          Bridge.instructions[6].registers = {3};
        else if (Mutation == 6)
          Bridge.instructions[7].opcode = "move-result";
        else if (Mutation == 7)
          Bridge.instructions[8].registers = {2, 1, 0};
        else if (Mutation == 8)
          Bridge.instructions[10].registers = {1};
        else if (Mutation == 9)
          Owner.methods[0].access.insert("static");
        else if (Mutation == 10)
          Input[2].methods[0].generic_signature = "<R:Ljava/lang/Object;>()J";
        else if (Mutation == 11)
          Bridge.instructions[9].reference = Owner.methods[0].reference;
        else if (Mutation == 12)
          Bridge.access.erase("final");
        else if (Mutation == 13)
          Owner.access.erase("final");
        else if (Mutation == 14) {
          auto Extra = Input[0].methods[0];
          Extra.reference.name = "other";
          Input[0].methods.push_back(Extra);
        } else if (Mutation == 15)
          Bridge.instructions[6].target = 10;
        else
          Bridge.generic_signature = "<R:Ljava/lang/Object;>(TR;)Z";
