std::vector<Class> localNominalScalarGuardClasses(const std::string &Primitive,
                                                  bool Integer, bool External,
                                                  bool Local) {
  auto Input = guardedScalarParameterClasses(Primitive, External, true);
  auto &Owner = Input[1];
  auto &Box = Input[2];
  auto Parent = Box;
  Parent.name = "Lfixture/GuardCarrier;";
  Parent.access = {"public"};
  Parent.methods[0].reference.owner = Parent.name;
  Parent.fields[0].reference.owner = Parent.name;
  Parent.methods[0].instructions[0].reference = Parent.fields[0].reference;
  Box.superclass = Parent.name;
  Box.fields.clear();
  Box.methods.clear();
  Owner.methods[0].reference.name = Owner.methods[1].reference.name;
  const unsigned At = 5;
  Owner.methods[1].instructions[At].reference = Parent.name;
  Owner.methods[1].instructions[At + 1].reference = Parent.methods[0].reference;
  Owner.methods[1].instructions[At + 3].reference = Owner.methods[0].reference;
  if (Integer) {
    for (auto *M : {&Input[0].methods[0], &Owner.methods[0], &Owner.methods[1]})
      M->reference.returns = "I";
    Owner.methods[1].instructions[2].literal = int64_t(-1);
    Owner.methods[1].instructions[At + 3].reference =
        Owner.methods[0].reference;
  }
  if (Local) {
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{Parent.name, "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.reference.owner = Box.name;
    Init.access = {"public", "constructor"};
    Box.methods.push_back(Init);
    auto ParentInit = Init;
    ParentInit.reference.owner = Parent.name;
    ParentInit.instructions[0].reference =
        MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
    Parent.methods.push_back(ParentInit);
    auto OwnerInit = ParentInit;
    OwnerInit.reference.owner = Owner.name;
    OwnerInit.access = {"constructor"};
    Owner.methods.push_back(OwnerInit);
    auto Make = method("make", {}, Input[0].name, 1,
                       {op(0, "new-instance", {0}, {}, Owner.name),
                        op(1, "invoke-direct", {0}, {}, OwnerInit.reference),
                        op(2, "return-object", {0})});
    Make.generic_signature = "()Lfixture/GuardApi<Ljava/lang/String;>;";
    auto Host = klass("Lfixture/GuardHost;", {Make});
    Owner.enclosing_method = Host.methods[0].reference;
    Owner.inner_class_present = true;
    Owner.inner_access = {"final", "static"};
    Input.push_back(Host);
  }
  Input.push_back(Parent);
  return Input;
}

