void useScalarGuardClassParent(std::vector<Class> &Input) {
  auto &Api = Input[0];
  auto &Owner = Input[1];
  Api.access = {"public", "abstract"};
  auto Init = method(
      "<init>", {}, "V", Api.external ? 0 : 1,
      Api.external ? std::vector<Instruction>{}
                   : std::vector<Instruction>{
                         op(0, "invoke-direct", {0}, {},
                            MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                         op(1, "return-void")});
  Init.reference.owner = Api.name;
  Init.access = {"public", "constructor"};
  Api.methods.push_back(Init);
  Owner.interfaces.clear();
  Owner.superclass = Api.name;
  Owner.generic_signature = "Lfixture/GuardApi<Ljava/lang/String;>;";
  if (Owner.methods.back().reference.name == "<init>")
    Owner.methods.back().instructions[0].reference = Init.reference;
}

