TEST(MobileDalvikJava,
     LocalNominalScalarGuardsRejectUnprovenParentScopeAndRuntimeSlots) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
        auto Input = localNominalScalarGuardClasses("J", true, External, true);
        auto &Owner = Input[1];
        auto &Box = Input[2];
        auto &Host = Input[3];
        auto &Parent = Input[4];
        switch (Mutation) {
        case 0:
          Box.superclass = "Ljava/lang/Object;";
          Box.methods[0].instructions[0].reference =
              MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
          break;
        case 1:
          Parent.access.insert("interface");
          break;
        case 2:
          Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 3:
          Parent.methods[0].access = {"protected"};
          break;
        case 4:
          Parent.methods[0].access.insert("static");
          break;
        case 5:
          Parent.methods[0].generic_signature = "<R:Ljava/lang/Object;>()J";
          break;
        case 6:
          Parent.access.insert("abstract");
          Parent.methods[0].access.insert("abstract");
          Parent.methods[0].instructions.clear();
          Parent.methods[0].registers = Parent.methods[0].code_end = 0;
          break;
        case 7:
          Owner.methods[1].instructions[6].registers = {2};
          break;
        case 8:
          Owner.methods[1].instructions[2].literal = int64_t(0);
          break;
        case 9:
          Host.methods[0].access.erase("static");
          break;
        case 10:
          Owner.enclosing_method->name = "unknown";
          break;
        case 11:
          Host.methods[0].generic_signature =
              "<T:Ljava/lang/Object;>()Lfixture/GuardApi<Ljava/lang/String;>;";
          Owner.fields.push_back({{Owner.name, "scoped", "Ljava/lang/Object;"},
                                  {"public"},
                                  {},
                                  std::optional<std::string>("TT;")});
          break;
        case 12:
          Owner.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;"
                                    "Lfixture/GuardApi<Ljava/lang/String;>;";
          break;
        case 13:
          useScalarGuardClassParent(Input);
          Input[0].methods[0].access.erase("abstract");
          Input[0].methods[0].access.insert("final");
          if (!External) {
            Input[0].methods[0].registers = 3;
            Input[0].methods[0].instructions = {
                op(0, "const/4", {0}, int64_t(-1)), op(1, "return", {0})};
            Input[0].methods[0].code_end = 2;
          }
          break;
        case 14:
          Owner.methods[0].generic_signature = "<R:Ljava/lang/Object;>(J)I";
          break;
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error)
            << "Mutation " << Mutation;
      }
}

std::vector<Class> namedScalarGetterClasses(const std::string &Primitive,
                                            bool External, bool Effects) {
  auto Input = plainBoxedGetterClasses(Primitive);
  Input.pop_back();
  auto &Api = Input[0];
  Api.external = External;
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.methods[0].reference.returns = Primitive;
  auto &Owner = Input[1];
  Owner.generic_signature =
      "Ljava/lang/Object;Lfixture/ScalarApi<Ljava/lang/String;>;";
  auto &Bridge = Owner.methods[1];
  const bool Wide = Primitive == "J" || Primitive == "D";
  Bridge.reference.returns = Primitive;
  Bridge.instructions = {Bridge.instructions[0], Bridge.instructions[1],
                         op(2, Wide ? "return-wide" : "return", {0})};
  Bridge.code_end = 3;
  if (Effects) {
    auto &Target = Owner.methods[0];
    const unsigned Self = Target.registers - 1;
    FieldRef Count{Owner.name, "calls", "I"};
    Owner.fields.push_back({Count, {"public"}, {}});
    Target.instructions = {op(0, "iget", {0, Self}, {}, Count),
                           op(1, "add-int/lit8", {0, 0}, int64_t(1)),
                           op(2, "iput", {0, Self}, {}, Count),
                           op(3, Wide ? "iget-wide" : "iget", {0, Self}, {},
                              Owner.fields[0].reference),
                           op(4, Wide ? "return-wide" : "return", {0})};
    Target.code_end = 5;
  }
  return Input;
}

