TEST(MobileDalvikJava, BoxedResultBindingRetainsCovariantInterfaceUpcast) {
  for (bool CastToInterface : {false, true}) {
    auto Input = boxedGenericResultClasses("J", false, false);
    const auto &Api = Input[0];
    auto &Owner = Input[1];
    const auto Box = Input[2].name;
    auto Boxed = Owner.methods[1];
    Boxed.reference.returns = Box;
    Boxed.access = {"public", "final"};
    Owner.methods.push_back(Boxed);

    auto Get = method("produce", {}, Api.name, 0, {});
    Get.access = {"public", "abstract"};
    auto Source = klass("Lfixture/Source;", {Get});
    Source.access = {"public", "interface", "abstract"};
    auto Provider = klass("Lfixture/Provider;");
    Provider.interfaces = {Source.name};
    auto Typed = method("produce", {}, Owner.name, 2,
                        {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
    Typed.reference.owner = Provider.name;
    Typed.access = {"public"};
    auto Erased = method("produce", {}, Api.name, 2,
                         {op(0, "invoke-virtual", {1}, {}, Typed.reference),
                          op(1, "move-result-object", {0}),
                          op(2, "check-cast", {0}, {}, CastToInterface ? Api.name : "Ljava/lang/Object;"),
                          op(3, "return-object", {0})});
    Erased.reference.owner = Provider.name;
    Erased.access = {"public", "bridge", "synthetic"};
    Provider.methods = {Typed, Erased};
    const auto Key = std::pair{Owner.methods[1].reference, Api.methods[0].reference};
    Input.push_back(std::move(Source));
    Input.push_back(std::move(Provider));
    Budget B;
    if (!CastToInterface) {
      EXPECT_THROW(validateGenericSignatures(linkClasses(Input, B), B), std::runtime_error);
      continue;
    }
    const auto Plans = validateGenericSignatures(linkClasses(Input, B), B);
    ASSERT_TRUE(Plans.boxed_interface_results.contains(Key));
    EXPECT_TRUE(Plans.boxed_interface_results.at(Key).preserve_typed_interface);
  }
}

