std::vector<Class> multiparamBoxedSuperclassClasses(const std::string &Carrier,
                                                    bool External,
                                                    bool Protected,
                                                    unsigned ResultIndex,
                                                    bool Second) {
  auto Input =
      Carrier.starts_with('[')
          ? boxedArraySuperclassClasses(Carrier, External, !Protected, true)
          : boxedSuperclassResultClasses(Carrier, External, !Protected);
  auto &Parent = Input[0];
  auto &Owner = Input[1];
  const std::array<std::string, 3> Formals = {"T:Ljava/lang/Object;",
                                              "A:Ljava/lang/Object;",
                                              "B:Lfixture/Holder<TT;>;"};
  const std::array<std::string, 3> Arguments = {
      "Lfixture/ScalarBox;", "Ljava/lang/String;",
      "Lfixture/Holder<Lfixture/ScalarBox;>;"};
  std::vector<unsigned> Order{1, 2};
  Order.insert(Order.begin() + ResultIndex, 0);
  std::string Declared = "<", Applied = "Lfixture/ScalarApi<";
  for (auto Index : Order) {
    Declared += Formals[Index];
    Applied += Arguments[Index];
  }
  Declared += ">Ljava/lang/Object;";
  if (!Protected)
    Declared += "Lfixture/BoxedResultApi<TT;>;";
  Parent.generic_signature = Declared;
  Owner.generic_signature =
      Applied + ">;Lfixture/ResultTag<Lfixture/ScalarBox;>;";
  Owner.interfaces = {"Lfixture/ResultTag;"};
  if (Protected) {
    Parent.methods[0].access = {"protected", "abstract"};
    Owner.methods[0].access = {"protected"};
  }
  if (Second) {
    auto Required = Parent.methods[0];
    Required.reference.name = "other";
    Parent.methods.push_back(Required);
    auto Bridge = Owner.methods[1];
    Bridge.reference.name = "other";
    Owner.methods.push_back(Bridge);
  }
  auto Holder = klass("Lfixture/Holder;", {});
  Holder.generic_signature = "<H:Ljava/lang/Object;>Ljava/lang/Object;";
  Holder.external = External;
  auto TagMethod =
      method("tag", {}, "I", 2,
             {op(0, "const/4", {0}, int64_t(7)), op(1, "return", {0})});
  TagMethod.access = {"public"};
  if (External) {
    TagMethod.instructions.clear();
    TagMethod.registers = TagMethod.code_end = 0;
  }
  auto Tag = klass("Lfixture/ResultTag;", {TagMethod});
  Tag.access = {"public", "abstract", "interface"};
  Tag.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
  Tag.external = External;
  Input.push_back(Holder);
  Input.push_back(Tag);
  return Input;
}

