TEST(MobileDalvikJava, BoxedSuperclassResultsRetainOriginalIndexedFactory) {
  for (const std::string Primitive : {"I", "F", "J", "D"})
    for (bool External : {false, true})
      for (bool Ancestry : {false, true})
        for (bool Link : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input =
                boxedSuperclassResultClasses(Primitive, External, Ancestry);
            const auto Bridge = Input[1].methods[1].reference;
            const auto Target = Input[1].methods[0].reference;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("method_count"),
                      External ? 4 : 7 + Ancestry);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            for (const auto &Value : *R.getArray("methods")) {
              const auto *Row = Value.getAsObject();
              if (Row->getString("identity") == Bridge.identity()) {
                EXPECT_EQ(Row->getString("projection_kind"),
                          "boxed-generic-superclass-result-bridge");
                EXPECT_EQ(Row->getString("source_identity"), Bridge.identity());
                EXPECT_EQ(Row->getString("bridge_target"), Target.identity());
                EXPECT_EQ(Row->getString("box_method"),
                          "Lfixture/ScalarBox;->box(" + Primitive +
                              ")Lfixture/ScalarBox;");
              }
            }
            const auto *Projections =
                R.getArray("generic_signature_projections");
            ASSERT_NE(Projections, nullptr);
            ASSERT_EQ(Projections->size(), 1u);
            const auto *Changes =
                (*Projections)[0].getAsObject()->getArray("changes");
            ASSERT_NE(Changes, nullptr);
            ASSERT_EQ(Changes->size(), 1u);
            EXPECT_EQ((*Changes)[0].getAsObject()->getString("kind"),
                      "boxed-superclass-result-argument");
            EXPECT_EQ((*Changes)[0].getAsObject()->getString("source_type"),
                      "Lfixture/ScalarApi<Ljava/lang/Object;>;");
          }
}

