TEST(MobileDalvikJava, BoxedSuperclassResultsRejectContractAndCallDrift) {
  for (unsigned Mutation = 0; Mutation < 18; ++Mutation)
    for (bool External : {false, true})
      for (bool Link : {false, true}) {
        SCOPED_TRACE(Mutation);
        auto Input = boxedSuperclassResultClasses("J", External, true);
        auto &Owner = Input[1];
        auto &Target = Owner.methods[0];
        auto &Bridge = Owner.methods[1];
        switch (Mutation) {
        case 0:
          Owner.access.erase("final");
          break;
        case 1:
          Bridge.access.erase("synthetic");
          break;
        case 2:
          Bridge.instructions[0].registers = {2, 1};
          break;
        case 3:
          Bridge.instructions[1].opcode = "move-result";
          break;
        case 4:
          Bridge.instructions[2].registers = {1, 2};
          break;
        case 5:
          Bridge.instructions[4].registers = {1};
          break;
        case 6:
          Target.access.insert("static");
          break;
        case 7:
          Target.access = {"private"};
          break;
        case 8:
          Target.generic_signature = "<R:Ljava/lang/Object;>(I)J";
          break;
        case 9:
          Input[2].methods[0].access.erase("static");
          break;
        case 10:
          Owner.generic_signature = "Lfixture/ScalarApi<Ljava/lang/String;>;";
          break;
        case 11:
          Input[3].methods[0].generic_signature = "(I)Ljava/lang/String;";
          break;
        case 12:
          Input[0].methods[0].access.insert("final");
          break;
        case 13:
          Bridge.instructions[0].target = 4;
          break;
        case 14:
          Bridge.instructions[3].reference = Target.reference;
          break;
        case 15: {
          auto Extra = Input[0].methods[0];
          Extra.reference.name = "other";
          Input[0].methods.push_back(Extra);
          break;
        }
        case 16: {
          auto Extra = Bridge;
          Extra.access = {"public"};
          Extra.reference.returns = Input[2].name;
          Owner.methods.push_back(Extra);
          break;
        }
        case 17:
          Target.declared_throws =
              std::vector<std::string>{"Ljava/lang/IllegalStateException;"};
          break;
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> rawGenericAncestorReturnClasses(bool External,
                                                   bool Abstract) {
  auto Read = method("read", {}, "Lfixture/Container;", 0, {});
  Read.access = {"public", "abstract"};
  Read.generic_signature = "()Lfixture/Container<TT;>;";
  auto Api = klass("Lfixture/RawApi;", {Read});
  Api.access = {"public", "abstract", "interface"};
  Api.external = External;
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Root = Api;
  Root.name = "Lfixture/RawRoot;";
  Root.methods[0].reference.owner = Root.name;
  Api.interfaces = {Root.name};
  Api.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/RawRoot<TT;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Read.generic_signature.reset();
  Read.access = {"public"};
  Read.registers = 2;
  Read.instructions = {op(0, "const/4", {0}, int64_t{0}),
                       op(1, "return-object", {0})};
  Read.code_end = 2;
  auto Parent = klass("Lfixture/RawParent;", {Init, Read});
  Parent.external = External;
  Parent.interfaces = {Root.name};
  if (External)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto Core = klass("Lfixture/RawChild;", {Init, Read});
  Core.superclass = Parent.name;
  Core.interfaces = {Api.name};
  Core.methods[0].instructions[0].reference = Parent.methods[0].reference;
  if (Abstract) {
    Core.access.insert("abstract");
    Core.methods[1].access.insert("abstract");
    Core.methods[1].instructions.clear();
    Core.methods[1].registers = Core.methods[1].code_end = 0;
  }
  auto Container = klass("Lfixture/Container;");
  Container.external = true;
  Container.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Core, Parent, Api, Root, Container};
}

