TEST(MobileDalvikJava,
     RawGenericAncestorsStillRejectIncompatibleImplementations) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Link);
        SCOPED_TRACE(Mutation);
        auto Input = rawGenericAncestorReturnClasses(External, false);
        auto &Read = Input[0].methods[1];
        if (Mutation == 0)
          Read.generic_signature =
              "<E:Ljava/lang/Object;>()Lfixture/Container<TE;>;";
        else if (Mutation == 1)
          Read.reference.returns = "Ljava/lang/Object;";
        else if (Mutation == 2)
          Read.access = {"private"};
        else if (Mutation == 3)
          Read.access.insert("static");
        else if (Mutation == 4)
          Input[0].superclass = "Lfixture/MissingAncestor;";
        else if (Mutation == 5) {
          Input[3].interfaces = {Input[2].name};
          Input[3].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/RawApi<TT;>;";
        } else if (Mutation == 6) {
          Input[0].methods.pop_back();
          Input[1].methods.pop_back();
        } else if (Mutation >= 8) {
          auto Narrow = klass("Lfixture/NarrowContainer;");
          Narrow.external = true;
          Narrow.superclass = Input[4].name;
          Read.reference.returns = Narrow.name;
          if (Mutation == 9) {
            Input[1].access.insert("abstract");
            Input[1].methods.pop_back();
          }
          Input.push_back(Narrow);
        } else {
          auto Far = Input[1];
          Far.name = "Lfixture/FarRawAncestor;";
          Far.interfaces.clear();
          for (auto &M : Far.methods)
            M.reference.owner = Far.name;
          Far.methods[1].access.insert("final");
          Input[1].superclass = Far.name;
          if (!External)
            Input[1].methods[0].instructions[0].reference =
                Far.methods[0].reference;
          Input[0].methods.pop_back();
          Input.push_back(Far);
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

