        SCOPED_TRACE(Link);
        SCOPED_TRACE(Mutation);
        auto Input = rawGenericCovariantAncestorClasses(External);
        auto &Bridge = Input[0].methods.back();
        if (Mutation == 0)
          Bridge.access.erase("synthetic");
        else if (Mutation == 1)
          std::get<MethodRef>(Bridge.instructions[0].reference).owner =
              Input[1].name;
        else if (Mutation == 2)
          Bridge.instructions[2].registers = {1};
        else if (Mutation == 3)
          Bridge.instructions[0].opcode = "invoke-super";
        else if (Mutation == 4)
          Input[0].methods.pop_back();
        else {
          Input[5].superclass = "Ljava/lang/Object;";
          Input[5].generic_signature =
              "<E:Ljava/lang/Object;>Ljava/lang/Object;";
        }
        Budget B;
