TEST(MobileDalvikJava, FinalVoidReturnSlotsKeepScalarAbiAndAvoidExistingNames) {
  for (const std::string Primitive : {"Z", "B", "S", "C", "I", "J", "F", "D"})
    for (bool External : {false, true})
      for (bool Middle : {false, true})
        for (bool Link : {false, true}) {
          SCOPED_TRACE(Primitive);
          auto Input = finalVoidReturnSlotClasses(External, Middle);
          auto &Required = Input[0].methods[0];
          auto &Scalar = Input[1].methods[1];
          Required.reference.returns = Scalar.reference.returns = Primitive;
          Required.generic_signature = Scalar.generic_signature =
              "(TE;)" + Primitive;
          Scalar.access.insert("final");
          if (!External) {
            const bool Wide = Primitive == "J" || Primitive == "D";
            Scalar.registers = Wide ? 4 : 3;
            Scalar.instructions = {
                op(0, Wide ? "const-wide/16" : "const", {0},
                   Primitive == "F" ? int64_t{0x3f800000} : int64_t{0}),
                op(1, Wide ? "return-wide" : "return", {0})};
            Scalar.code_end = 2;
          }
          auto Reserved =
              method("__neverdReturnSlot", {}, "V", 1, {op(0, "return-void")});
          Reserved.reference.owner = Input[2].name;
          Reserved.access = {"private"};
          Input[2].methods.push_back(Reserved);
          const auto Original = Input[2].methods[1].reference;
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("method_count"),
                    External ? 3 : (Middle ? 7 : 6));
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 1);
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") == Original.identity()) {
              EXPECT_NE(Row->getString("source_name"), "__neverdReturnSlot");
              ASSERT_NE(Row->getArray("conflicting_inherited_contracts"),
                        nullptr);
              EXPECT_EQ(
                  Row->getArray("conflicting_inherited_contracts")->size(), 1u);
            }
          }
        }
}

