TEST(MobileDalvikJava,
     RawInterfaceMethodFormalsRetainRuntimeBodyAndReportSourceErasure) {
  for (bool External : {false, true})
    for (bool Inherited : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(std::to_string(External) + ":" +
                       std::to_string(Inherited) + ":" + std::to_string(Link) +
                       ":" + std::to_string(Reverse));
          auto Input = rawMethodFormalMemberClasses(External, Inherited);
          const auto Slot = Input[1].methods[1].reference;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Known;
          for (const auto &Class : Input)
            Known.emplace(Class.name, Class);
          auto Plans = validateGenericSignatures(Known, B);
          ASSERT_EQ(Plans.raw_interface_method_sources.size(), 1u)
              << External << ":" << Inherited << ":" << Link << ":" << Reverse;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("method_count"), External ? 2 : 3);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 1);
          ASSERT_NE(R.getArray("generic_signature_projections"), nullptr);
          EXPECT_EQ(R.getArray("generic_signature_projections")->size(), 1u);
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") == Slot.identity()) {
              EXPECT_EQ(Row->getString("projection_kind"),
                        "raw-interface-method-formal-erasure");
              EXPECT_EQ(Row->getString("source_identity"), Slot.identity());
              EXPECT_EQ(Row->getString("inherited_class_contract"),
                        "Lfixture/RawMethodApi;->array([Ljava/lang/"
                        "Object;Ljava/lang/Object;)[Ljava/lang/Object;");
              EXPECT_EQ(Row->getString("source_generic_signature"),
                        Slot.signature());
            }
          }
        }
}

