std::vector<Class> nongenericNominalBridgeClasses() {
  auto Base = klass("Lfixture/NominalBase;");
  Base.external = true;
  Base.access = {"public", "abstract", "interface"};
  auto Leaf = klass("Lfixture/NominalLeaf;");
  Leaf.external = true;
  Leaf.interfaces = {Base.name};
  auto Get = method("get", {}, Base.name, 0, {});
  Get.access = {"public", "abstract"};
  auto Echo =
      method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Get.access;
  Echo.generic_signature = "<M:Ljava/lang/Object;>(TM;)TM;";
  auto Api = klass("Lfixture/NominalApi;", {Get, Echo});
  Api.access = Base.access;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Get.reference.returns = Leaf.name;
  Get.access = {"public"};
  Get.registers = 2;
  Get.instructions = {op(0, "const/4", {0}, int64_t(0)),
                      op(1, "return-object", {0})};
  Get.code_end = 2;
  Echo.access = {"public"};
  Echo.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  Echo.registers = 2;
  Echo.instructions = {op(0, "return-object", {1})};
  Echo.code_end = 1;
  auto Owner = klass("Lfixture/NominalOwner;", {Init, Get, Echo});
  Owner.access = {"public", "final"};
  Owner.interfaces = {Api.name};
  auto Bridge = method(
      "get", {}, Base.name, 2,
      {op(0, "invoke-virtual", {1}, {}, Owner.methods[1].reference),
       op(1, "move-result-object", {0}),
       op(2, "check-cast", {0}, {}, Base.name), op(3, "return-object", {0})});
  Bridge.reference.owner = Owner.name;
  Bridge.access = {"public", "bridge", "synthetic"};
  Owner.methods.push_back(Bridge);
  return {Owner, Api, Base, Leaf};
}

