std::vector<Class> genericDefaultClassBridgeClasses(bool External = false) {
  auto Callback = klass("Lfixture/Callback;");
  Callback.external = true;
  Callback.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Listener = method("listener", {Callback.name}, "Lfixture/Contract;", 2,
                         {op(0, "return-object", {0})});
  Listener.access = {"public"};
  Listener.generic_signature =
      "(Lfixture/Callback<TK;TV;>;)Lfixture/Contract<TK;TV;>;";
  auto Contract = klass("Lfixture/Contract;", {Listener});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = Callback.generic_signature;
  Contract.external = External;
  if (External) {
    Contract.methods[0].instructions.clear();
    Contract.methods[0].registers = Contract.methods[0].code_end = 0;
  }
  const auto constructor = [](const std::string &Parent) {
    auto Init = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    Init.access = {"public", "constructor"};
    return Init;
  };
  Listener.reference.returns = "Lfixture/Base;";
  Listener.generic_signature =
      "(Lfixture/Callback<TK;TV;>;)Lfixture/Base<TK;TV;>;";
  auto Base =
      klass("Lfixture/Base;", {constructor("Ljava/lang/Object;"), Listener});
  Base.access.insert("abstract");
  Base.interfaces = {Contract.name};
  Base.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Contract<TK;TV;>;";
  auto Bridge =
      method("listener", {Callback.name}, Contract.name, 2,
             {op(0, "invoke-virtual", {0, 1}, {}, Base.methods[1].reference),
              op(1, "move-result-object", {1}), op(2, "return-object", {1})});
  Bridge.reference.owner = Base.name;
  Bridge.access = {"public", "bridge", "synthetic"};
  Base.methods.push_back(Bridge);
  auto Middle = klass("Lfixture/Middle;", {constructor(Base.name)});
  Middle.superclass = Base.name;
  Middle.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Lfixture/Base<TA;TB;>;";
  auto Leaf = klass("Lfixture/Leaf;", {constructor(Middle.name)});
  Leaf.superclass = Middle.name;
  Leaf.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Lfixture/Middle<TX;TY;>;";
  auto Child = klass("Lfixture/Child;", {constructor(Leaf.name)});
  Child.superclass = Leaf.name;
  Child.generic_signature = "Lfixture/Leaf<Ljava/lang/String;[B>;";
  return {Callback, Contract, Base, Middle, Leaf, Child};
}

TEST(MobileDalvikJava, GenericDefaultsKeepInheritedCovariantClassBridges) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = genericDefaultClassBridgeClasses(External);
        const auto Bridge = Input[2].methods[2].reference;
        const auto Typed = Input[2].methods[1].reference;
        const auto Required = Input[1].methods[0].reference;
        if (Reverse) {
          std::reverse(Input.begin(), Input.end());
          for (auto &Cls : Input)
            std::reverse(Cls.methods.begin(), Cls.methods.end());
        }
        Budget B;
        ClassMap Classes;
        for (const auto &Cls : Input)
          Classes.emplace(Cls.name, Cls);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(
            Plans.covariant_interface_returns.contains({Typed, Required}));
        const auto Receipt =
            Plans.covariant_bridge_contracts.find({Bridge, Required});
        ASSERT_NE(Receipt, Plans.covariant_bridge_contracts.end());
        EXPECT_EQ(Receipt->second.target, Typed);
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), External ? 6 : 7);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      }
}

TEST(MobileDalvikJava, GenericDefaultClassBridgesRequireFullTypesAndBodies) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = genericDefaultClassBridgeClasses(External);
      auto &Typed = Input[2].methods[1];
      auto &Bridge = Input[2].methods[2];
      if (Mutation == 0)
        Typed.generic_signature =
            "(Lfixture/Callback<TV;TK;>;)Lfixture/Base<TK;TV;>;";
      else if (Mutation == 1)
        Typed.generic_signature =
            "(Lfixture/Callback<TK;TV;>;)Lfixture/Base<TV;TK;>;";
      else if (Mutation == 2)
        Bridge.instructions[0].registers = {1, 0};
      else if (Mutation == 3)
        Bridge.instructions[2].registers = {0};
      else if (Mutation == 4)
        Typed.access.insert("static");
      else if (Mutation == 5)
        Typed.access = {"private"};
      else if (Mutation == 6)
        Input[2].methods.pop_back();
      else if (Mutation == 7)
        Typed.generic_signature =
            "<K:Ljava/lang/Object;V:Ljava/lang/Object;>"
            "(Lfixture/Callback<TK;TV;>;)Lfixture/Base<TK;TV;>;";
      else if (Mutation == 8)
        Bridge.access.erase("synthetic");
      if (Mutation == 9) {
        Budget B;
        auto Classes = linkClasses(Input, B);
        auto Plans = validateGenericSignatures(Classes, B);
        Plans.covariant_bridge_contracts.clear();
        EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                     std::runtime_error);
      } else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> classFormalObjectReturnClasses(bool External = false,
                                                  bool Default = false) {
  auto Get = method("getSource", {}, "Ljava/lang/Object;", 0, {});
  Get.access = {"public", "abstract"};
  auto Echo =
      method("echo", {"Lfixture/Callback;"}, "Ljava/lang/Object;", 0, {});
  Echo.access = Get.access;
  Echo.generic_signature =
      "(Lfixture/Callback<Ljava/lang/String;[B>;)Ljava/lang/Object;";
  auto Source = klass("Lfixture/Source;", {Get, Echo});
  Source.access = {"public", "abstract", "interface"};
  Source.external = External;
  if (Default)
    for (auto &Member : Source.methods) {
      Member.access.erase("abstract");
      if (!External) {
        Member.registers = Member.reference.parameters.size() + 1;
        Member.instructions = {op(0, "const/4", {0}, int64_t(0)),
                               op(1, "return-object", {0})};
        Member.code_end = 2;
      }
    }
  auto Callback = klass("Lfixture/Callback;");
  Callback.external = true;
  Callback.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  const auto constructor = [](const std::string &Parent) {
    auto Init = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    Init.access = {"public", "constructor"};
    return Init;
  };
  Get.access = Echo.access = {"public"};
  Get.registers = 1;
  Echo.registers = 2;
  Get.instructions = Echo.instructions = {op(0, "const/4", {0}, int64_t(0)),
                                          op(1, "return-object", {0})};
  Get.code_end = Echo.code_end = 2;
  Get.generic_signature = "()TP;";
  Echo.generic_signature = "(Lfixture/Callback<Ljava/lang/String;[B>;)TP;";
  auto Base =
      klass("Lfixture/Base;", {constructor("Ljava/lang/Object;"), Get, Echo});
  Base.access.insert("abstract");
  Base.interfaces = {Source.name};
  Base.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Source;";
  auto Middle = klass("Lfixture/Middle;", {constructor(Base.name)});
  Middle.superclass = Base.name;
  Middle.generic_signature = "<Q:Ljava/lang/Object;>Lfixture/Base<TQ;>;";
  auto Child = klass("Lfixture/Child;", {constructor(Middle.name)});
  Child.superclass = Middle.name;
  Child.generic_signature =
      "Lfixture/Middle<Lfixture/Callback<Ljava/lang/String;[B>;>;";
  return {Source, Callback, Base, Middle, Child};
}

