      auto Input = classFormalObjectReturnClasses(External);
      auto &Get = Input[2].methods[1];
      if (Mutation == 0)
        Get.generic_signature = "<P:Ljava/lang/Object;>()TP;";
      else if (Mutation == 1)
        Input[2].methods[2].generic_signature =
            "(Lfixture/Callback<[BLjava/lang/String;>;)TP;";
      else if (Mutation == 2)
        Get.access.insert("static");
