std::vector<Class> plainNominalCovariantContractClasses() {
  auto Create = method("create", {}, "Lfixture/Result;", 0, {});
  Create.access = {"public", "abstract"};
  Create.generic_signature = "()Lfixture/Result<TA;>;";
  auto Api = klass("Lfixture/GenericApi;", {Create});
  Api.external = true;
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Result = klass("Lfixture/Result;");
  Result.external = true;
  Result.access = Api.access;
  Result.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Value = klass("Lfixture/BaseValue;", {Init});
  Value.interfaces = {Result.name};
  Value.generic_signature =
      "Ljava/lang/Object;Lfixture/Result<Ljava/lang/String;>;";
  auto Marker = Result;
  Marker.name = "Lfixture/Marker;";
  Init.instructions[0].reference = Value.methods[0].reference;
  auto Specific = klass("Lfixture/SpecificValue;", {Init});
  Specific.superclass = Value.name;
  Specific.interfaces = {Marker.name};
  Specific.generic_signature =
      "Lfixture/BaseValue;Lfixture/Marker<Ljava/lang/Integer;>;";
  Create.generic_signature.reset();
  Create.reference.returns = Value.name;
  auto Plain = klass("Lfixture/PlainApi;", {Create});
  Plain.access = Api.access;
  Plain.interfaces = {Api.name};
  Plain.generic_signature =
      "Ljava/lang/Object;Lfixture/GenericApi<Ljava/lang/String;>;";
  auto Erased =
      method("create", {}, Result.name, 2,
             {op(0, "invoke-interface", {1}, {}, Plain.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Erased.access = {"public", "bridge", "synthetic"};
  Erased.reference.owner = Plain.name;
  Plain.methods.push_back(Erased);
  auto ParentCreate = Api.methods[0];
  ParentCreate.access = {"public"};
  ParentCreate.generic_signature = "()Lfixture/Result<TP;>;";
  ParentCreate.registers = 2;
  ParentCreate.instructions = {op(0, "const/4", {0}, int64_t(0)),
                               op(1, "return-object", {0})};
  ParentCreate.code_end = 2;
  Init.instructions[0].reference =
      MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Parent = klass("Lfixture/Producer;", {Init, ParentCreate});
  Parent.interfaces = {Api.name};
  Parent.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/GenericApi<TP;>;";
  Create.reference.owner = "Lfixture/Receiver;";
  Create.reference.returns = Specific.name;
  Create.access = {"public"};
  Create.registers = 2;
  Create.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
  Create.code_end = 2;
  Init.instructions[0].reference = Parent.methods[0].reference;
  auto Receiver = klass(Create.reference.owner, {Init, Create});
  Receiver.superclass = Parent.name;
  Receiver.interfaces = {Plain.name};
  Receiver.generic_signature =
      "Lfixture/Producer<Ljava/lang/String;>;Lfixture/PlainApi;";
  for (const auto &Returns : {Value.name, Result.name}) {
    auto Bridge = method("create", {}, Returns, 2,
                         {op(0, "invoke-virtual", {1}, {}, Create.reference),
                          op(1, "move-result-object", {0}),
                          op(2, "check-cast", {0}, {}, Returns),
                          op(3, "return-object", {0})});
    Bridge.access = {"public", "bridge", "synthetic"};
    Bridge.reference.owner = Receiver.name;
    Receiver.methods.push_back(Bridge);
  }
  return {Api, Result, Marker, Value, Specific, Plain, Parent, Receiver};
}

