std::vector<Class> covariantParentContractClasses() {
  auto Input = plainNominalCovariantContractClasses();
  auto Root = klass("Lfixture/RootBox;", {Input[3].methods[0]});
  Root.interfaces = {Input[1].name};
  Root.generic_signature =
      "<B:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Result<TB;>;";
  Input[3].superclass = Root.name;
  Input[3].generic_signature = "Lfixture/RootBox<Ljava/lang/String;>;Lfixture/"
                               "Result<Ljava/lang/String;>;";
  Input[3].methods[0].instructions[0].reference = Root.methods[0].reference;
  auto &Parent = Input[6];
  Parent.methods[1].reference.returns = Root.name;
  Parent.methods[1].generic_signature = "()Lfixture/RootBox<TP;>;";
  auto ParentBridge =
      method("create", {}, Input[1].name, 2,
             {op(0, "invoke-virtual", {1}, {}, Parent.methods[1].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  ParentBridge.access = {"public", "bridge", "synthetic"};
  ParentBridge.reference.owner = Parent.name;
  Parent.methods.push_back(ParentBridge);
  auto Bridge = Input[7].methods[2];
  Bridge.reference.returns = Root.name;
  Bridge.instructions[2].reference = Root.name;
  Input[7].methods.push_back(Bridge);
  Input.push_back(Root);
  return Input;
}

std::vector<Class>
threeErasureSourceBridgeClasses(bool ExternalRoot = false,
                                bool InheritedMembers = false) {
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Parse =
      method("parse", {"Ljava/lang/String;"}, "Ljava/lang/Object;", 0, {});
  Parse.access = {"public", "abstract"};
  Parse.generic_signature = "(Ljava/lang/String;)TT;";
  auto Root = klass("Lfixture/ParseRoot;", {Init, Parse});
  Root.access.insert("abstract");
  Root.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Root.external = ExternalRoot;
  if (ExternalRoot) {
    Root.methods[0].instructions.clear();
    Root.methods[0].registers = Root.methods[0].code_end = 0;
  }
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  auto Value = klass("Lfixture/Value;");
  Value.interfaces = {Marker.name};
  Init.instructions[0].reference = Root.methods[0].reference;
  Parse.access = {"public"};
  Parse.reference.returns = Marker.name;
  Parse.generic_signature = "(Ljava/lang/String;)TP;";
  Parse.registers = 3;
  Parse.instructions = {op(0, "const/4", {0}, int64_t(0)),
                        op(1, "return-object", {0})};
  Parse.code_end = 2;
  auto Parent = klass("Lfixture/ParseParent;", {Init, Parse});
  Parent.superclass = Root.name;
  Parent.generic_signature = "<P::Lfixture/Marker;>Lfixture/ParseRoot<TP;>;";
  auto Forward = [&](const std::string &Owner, const std::string &Returns,
                     const MethodRef &Target) {
    auto Bridge =
        method("parse", {"Ljava/lang/String;"}, Returns, 3,
               {op(0, "invoke-virtual", {1, 2}, {}, Target),
                op(1, "move-result-object", {0}), op(2, "return-object", {0})});
    Bridge.reference.owner = Owner;
    Bridge.access = {"public", "bridge", "synthetic"};
    return Bridge;
  };
  Parent.methods.push_back(
      Forward(Parent.name, "Ljava/lang/Object;", Parent.methods[1].reference));
  Init.instructions[0].reference = Parent.methods[0].reference;
  Parse.reference.returns = Value.name;
  Parse.generic_signature = "(Ljava/lang/String;)TC;";
  auto Child = klass("Lfixture/ParseChild;", {Init, Parse});
  Child.superclass = Parent.name;
  Child.generic_signature = "<C:Lfixture/Value;>Lfixture/ParseParent<TC;>;";
  for (const auto &Returns : {Marker.name, std::string("Ljava/lang/Object;")})
    Child.methods.push_back(
        Forward(Child.name, Returns, Child.methods[1].reference));
  if (InheritedMembers) {
    auto Read = method("read", {"Ljava/lang/String;", "I"},
                       "Ljava/lang/Object;", 0, {});
    Read.reference.owner = Root.name;
    Read.access = {"public", "abstract"};
    Read.generic_signature = "(Ljava/lang/String;I)TT;";
    auto Write = method(
        "write", {"Ljava/lang/String;", "I", "Ljava/lang/Object;"}, "V", 0, {});
    Write.reference.owner = Root.name;
    Write.access = {"public", "abstract"};
    Write.generic_signature = "(Ljava/lang/String;ITT;)V";
    Root.methods.push_back(Read);
    Root.methods.push_back(Write);
    Read.reference.owner = Parent.name;
    Read.reference.returns = Marker.name;
    Read.access = {"public"};
    Read.generic_signature = "(Ljava/lang/String;I)TP;";
    Read.registers = 4;
    Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Read.code_end = 2;
    auto ReadBridge =
        method("read", {"Ljava/lang/String;", "I"}, "Ljava/lang/Object;", 4,
               {op(0, "invoke-virtual", {1, 2, 3}, {}, Read.reference),
                op(1, "move-result-object", {0}), op(2, "return-object", {0})});
    ReadBridge.reference.owner = Parent.name;
    ReadBridge.access = {"public", "bridge", "synthetic"};
    Write.reference.owner = Parent.name;
    Write.reference.parameters.back() = Marker.name;
    Write.access = {"public"};
    Write.generic_signature = "(Ljava/lang/String;ITP;)V";
    Write.registers = 4;
    Write.instructions = {op(0, "return-void")};
    Write.code_end = 1;
    auto WriteBridge = method(
        "write", {"Ljava/lang/String;", "I", "Ljava/lang/Object;"}, "V", 4,
        {op(0, "check-cast", {3}, {}, Marker.name),
         op(1, "invoke-virtual", {0, 1, 2, 3}, {}, Write.reference),
         op(2, "return-void")});
    WriteBridge.reference.owner = Parent.name;
    WriteBridge.access = {"public", "bridge", "synthetic"};
    Parent.methods.push_back(Read);
    Parent.methods.push_back(ReadBridge);
    Parent.methods.push_back(Write);
    Parent.methods.push_back(WriteBridge);
  }
  return {Root, Parent, Child, Marker, Value};
}

