TEST(MobileDalvikJava, InheritedTypedProviderCannotBypassOriginalBodyOrScope) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = threeErasureSourceBridgeClasses(false, true);
      auto &Parent = Input[1];
      if (Mutation == 0)
        Parent.methods[4].instructions[0].registers = {0, 2, 3};
      else if (Mutation == 1)
        Parent.methods[3].generic_signature =
            "(Ljava/lang/String;I)Lfixture/Marker;";
      else if (Mutation == 2) {
        Parent.methods[3].access.insert("abstract");
        Parent.methods[3].instructions.clear();
        Parent.methods[3].registers = Parent.methods[3].code_end = 0;
      } else if (Mutation == 3)
        Parent.methods[3].access = {"private"};
      else if (Mutation == 4)
        Parent.methods.erase(Parent.methods.begin() + 4);
      else if (Mutation == 5)
        Parent.methods[6].instructions[0].reference =
            std::string("Ljava/lang/String;");
      else if (Mutation == 6)
        Parent.methods[5].access.insert("static");
      else {
        Parent.external = true;
        for (auto &Member : Parent.methods) {
          Member.instructions.clear();
          Member.registers = Member.code_end = 0;
        }
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

