std::vector<Class> sourceInterfaceCovariantMethodClasses(bool OriginalBridge,
                                                         bool ChildFirst) {
  auto Input = boundedCovariantMethodClasses();
  const auto OldName = Input[0].name;
  Input[0].name = ChildFirst ? "Lfixture/ACore;" : "Lfixture/ZCore;";
  for (auto &Method : Input[0].methods) {
    Method.reference.owner = Input[0].name;
    for (auto &Op : Method.instructions)
      if (auto *Call = std::get_if<MethodRef>(&Op.reference);
          Call && Call->owner == OldName)
        Call->owner = Input[0].name;
  }
  Input[1].external = Input[8].external = false;
  if (OriginalBridge) {
    auto Bridge = Input[0].methods[1];
    Bridge.reference.owner = Input[1].name;
    Bridge.instructions[0].opcode = "invoke-interface";
    Bridge.instructions[0].reference = Input[1].methods[0].reference;
    Input[1].methods.push_back(std::move(Bridge));
  }
  return Input;
}

TEST(MobileDalvikJava, SourceInterfaceCovariantBridgesDiscloseCompilerSlots) {
  for (bool OriginalBridge : {false, true}) {
    for (bool ChildFirst : {false, true}) {
      for (bool Link : {false, true}) {
        auto Input =
            sourceInterfaceCovariantMethodClasses(OriginalBridge, ChildFirst);
        Budget B;
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), OriginalBridge ? 6 : 5);
        EXPECT_EQ(R.getInteger("projected_method_count"), 3);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getString("status"), "partial");
        const auto *Helpers = R.getArray("generated_source_helpers");
        ASSERT_NE(Helpers, nullptr);
        const auto Added = std::count_if(
            Helpers->begin(), Helpers->end(), [](const auto &Row) {
              return Row.getAsObject()->getString("kind") ==
                     "compiler-covariant-interface-bridge";
            });
        EXPECT_EQ(Added, OriginalBridge ? 0 : 1);
      }
    }
  }
}

TEST(MobileDalvikJava, SourceInterfaceCovariantBridgesRequireEveryParentProof) {
  for (unsigned Mutation = 0; Mutation < 4; ++Mutation) {
    auto Input = sourceInterfaceCovariantMethodClasses(true, true);
    auto &Bridge = Input[1].methods[1];
    if (Mutation == 0)
      Bridge.instructions[0].opcode = "invoke-virtual";
    else if (Mutation == 1)
      Bridge.instructions[2].registers = {1};
    else if (Mutation == 2)
      Input[1].methods[0].generic_signature =
          "<M:Lfixture/OtherBound;>(Lfixture/Pair<TC;TM;>;)Lfixture/"
          "ResultMid<TM;>;";
    else {
      Bridge.instructions[1].opcode = "const/4";
      Bridge.instructions[1].literal = int64_t(0);
    }
    rejected([&] { recover(Input); }, "generic");
  }
}

TEST(MobileDalvikJava, InheritedMethodFormalsKeepAlphaEquivalentArraySlots) {
  for (bool External : {false, true})
    for (bool Superclass : {false, true})
      for (bool ChildFirst : {false, true})
        for (bool ArrayOnly : {false, true})
          for (bool Link : {false, true}) {
            auto Input = inheritedMethodFormalClasses(External, Superclass,
                                                      ChildFirst, ArrayOnly);
            Budget B;
            const auto R =
                Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("method_count"),
                      External ? 2 : (Superclass ? 5 : 4));
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            const auto Text = source(R, External || ChildFirst ? 0 : 1);
            EXPECT_NE(Text.find(ArrayOnly ? "R[] toArray(R[] arg0)"
                                          : "A[] copy(A[] arg0, B arg1)"),
                      std::string::npos);
            EXPECT_NE(Text.find("I value(I arg0)"), std::string::npos);
          }
}

TEST(MobileDalvikJava, InheritedMethodFormalsRejectErasureOnlyMatches) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = inheritedMethodFormalClasses(true);
      auto &Target = Input[1].methods[0];
      switch (Mutation) {
      case 0:
        Target.generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>([TB;TB;)[TA;";
        break;
      case 1:
        Target.generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>([TA;TB;)[TB;";
        break;
      case 2:
        Target.generic_signature =
            "<A:Ljava/lang/Object;>([TA;Ljava/lang/Object;)[TA;";
        break;
      case 3:
        Target.generic_signature.reset();
        break;
      case 4:
        Target.generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>([TI;TB;)[TA;";
        break;
      case 5: {
        auto Marker = klass("Lfixture/Marker;");
        Marker.access = {"public", "abstract", "interface"};
        Target.generic_signature =
            "<A:Ljava/lang/Object;:Lfixture/Marker;B:Ljava/lang/Object;>"
            "([TA;TB;)[TA;";
        Input.push_back(Marker);
        break;
      }
      case 6:
        Target.declared_throws =
            std::vector<std::string>{"Ljava/lang/Exception;"};
        break;
      case 7:
        Target.access = {"private"};
        break;
      case 8:
        Input[0].methods[0].generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>"
            "([Ljava/lang/Object;Ljava/lang/Object;)[Ljava/lang/Object;";
        Target.generic_signature.reset();
        break;
      }
      Budget B;
      rejected(
          [&] {
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          },
          "generic");
    }
}

std::vector<Class>
sourceInterfaceSuperclassClasses(bool ChildFirst = true,
                                 bool ExternalDefault = false) {
  const std::string ParentName =
      ChildFirst ? "Lfixture/ZParent;" : "Lfixture/AParent;";
  const std::string ChildName =
      ChildFirst ? "Lfixture/AChild;" : "Lfixture/ZChild;";
  auto Declaration =
      method("value", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Declaration.access = {"public", "abstract"};
  Declaration.generic_signature = "(TT;)TT;";
  auto Contract = klass("Lfixture/Contract;", {Declaration});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  if (ExternalDefault) {
    Contract.external = true;
    auto Default = method("fallback", {"I"}, "I", 0, {});
    Default.reference.owner = Contract.name;
    Default.access = {"public"};
    Contract.methods.push_back(Default);
  }
  auto Value = method("value", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                      {op(0, "return-object", {1})});
  Value.access = {"public"};
  Value.generic_signature = "(TP;)TP;";
  auto Lookup =
      method("lookup", {"Ljava/lang/Object;"}, "Lfixture/Cell;", 2,
             {op(0, "const", {0}, int64_t(0)), op(1, "return-object", {0})});
  Lookup.access = {"protected"};
  Lookup.generic_signature = "(TP;)Lfixture/Cell<TP;TQ;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Parent = klass(ParentName, {Value, Lookup, Init});
  Parent.interfaces = {Contract.name};
  Parent.generic_signature = "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/"
                             "lang/Object;Lfixture/Contract<TP;>;";
  Value.generic_signature = "(TI;)TI;";
  Lookup.generic_signature = "(TI;)Lfixture/Cell<TI;TJ;>;";
  auto Child = klass(ChildName, {Value, Lookup});
  Child.superclass = Parent.name;
  Child.generic_signature = "<I:Ljava/lang/Object;J:Ljava/lang/Object;>" +
                            Parent.name.substr(0, Parent.name.size() - 1) +
                            "<TI;TJ;>;";
  auto Cell = klass("Lfixture/Cell;");
  Cell.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Contract, Parent, Child, Cell};
}

