TEST(MobileDalvikJava, SourceParentInterfaceProofsRejectGapsInEitherOrder) {
  for (bool ChildFirst : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      auto Input = sourceInterfaceSuperclassClasses(ChildFirst, Mutation >= 5);
      switch (Mutation) {
      case 0:
        Input[1].methods.erase(Input[1].methods.begin());
        break;
      case 1:
        Input[1].external = true;
        for (auto &M : Input[1].methods) {
          M.instructions.clear();
          M.code_end = 0;
        }
        break;
      case 2:
        Input[1].generic_signature =
            "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Contract;";
        break;
      case 3:
        Input[1].methods.pop_back();
        break;
      case 4:
        Input[2].methods[1].generic_signature = "(TJ;)Lfixture/Cell<TI;TJ;>;";
        break;
      case 5:
        Input[0].external = false;
        Input[0].methods[1].registers = 2;
        Input[0].methods[1].instructions = {op(0, "return", {1})};
        Input[0].methods[1].code_end = 1;
        Input[0].methods[1].generic_signature = "(Ljava/lang/Object;)I";
        break;
      case 6: {
        auto Override =
            method("fallback", {"I"}, "I", 2, {op(0, "return", {1})});
        Override.reference.owner = Input[1].name;
        Override.access = {"protected"};
        Input[1].methods.push_back(Override);
        break;
      }
      case 7: {
        auto Other = Input[0];
        Other.name = "Lfixture/Other;";
        Other.methods.erase(Other.methods.begin());
        for (auto &M : Other.methods)
          M.reference.owner = Other.name;
        Input[1].interfaces.push_back(Other.name);
        Input[1].generic_signature =
            "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;"
            "Lfixture/Contract<TP;>;Lfixture/Other<TP;>;";
        Input.push_back(Other);
        break;
      }
      }
      rejected([&] { recover(Input); }, "generic");
    }
}

