std::vector<Class> markerDefaultSuperclassClasses(bool ChildFirst = true,
                                                  bool Override = false) {
  auto Input = sourceInterfaceSuperclassClasses(ChildFirst, true);
  auto Root = klass("Lfixture/MappedMarker;");
  Root.external = true;
  Root.access = {"public", "abstract", "interface"};
  auto Marker = Root;
  Marker.name = "Lfixture/MutableMarker;";
  Marker.interfaces = {Root.name};
  Input[1].interfaces.push_back(Marker.name);
  *Input[1].generic_signature += Marker.name;
  if (Override) {
    auto Fallback = method("fallback", {"I"}, "I", 2, {op(0, "return", {1})});
    Fallback.reference.owner = Input[1].name;
    Fallback.access = {"public"};
    Input[1].methods.push_back(Fallback);
  }
  Input.push_back(Root);
  Input.push_back(Marker);
  return Input;
}

