TEST(MobileDalvikJava, RawMarkerAndDefaultProofsRejectChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
    auto Input = markerDefaultSuperclassClasses(true, true);
    switch (Mutation) {
    case 0:
      Input.pop_back();
      break;
    case 1:
      Input[4].methods.push_back(method("extra", {}, "I", 0, {}));
      Input[4].methods.back().reference.owner = Input[4].name;
      Input[4].methods.back().access = {"public", "abstract"};
      break;
    case 2:
      Input[4].interfaces = {Input[5].name};
      break;
    case 3:
      Input[5].generic_signature =
          "<M:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/MappedMarker;";
      break;
    case 4:
      Input[1].methods.back().access = {"private"};
      break;
    case 5:
      Input[1].methods.back().declared_throws =
          std::vector<std::string>{"Ljava/lang/Exception;"};
      break;
    case 6:
      Input[0].external = false;
      Input[0].methods.back().registers = 2;
      Input[0].methods.back().instructions = {op(0, "return", {1})};
      Input[0].methods.back().code_end = 1;
      Input[0].methods.back().generic_signature = "(Ljava/lang/Object;)I";
      break;
    case 7:
      Input[5].fields.push_back({{Input[5].name, "extra", "I"},
                                 {"public", "static", "final"},
                                 int64_t(1)});
      Input[5].methods.push_back(method("missing", {}, "I", 0, {}));
      Input[5].methods.back().reference.owner = Input[5].name;
      Input[5].methods.back().access = {"public", "abstract"};
      break;
    }
    rejected([&] { recover(Input); }, "generic");
  }
}

