std::vector<Class> sourceInterfaceDefaultClasses() {
  auto Echo = method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                     {op(0, "return-object", {1})});
  Echo.access = {"public"};
  Echo.generic_signature = "(TT;)TT;";
  auto Hidden =
      method("hidden", {}, "I", 2,
             {op(0, "const/4", {0}, int64_t(3)), op(1, "return", {0})});
  Hidden.access = {"private"};
  auto Scalar = method("scalar", {}, "I", 2,
                       {op(0, "invoke-direct", {1}, {},
                           MethodRef{"Lfixture/Root;", "hidden", {}, "I"}),
                        op(1, "move-result", {0}), op(2, "return", {0})});
  Scalar.access = {"public"};
  auto Identity =
      method("identity", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 1,
             {op(0, "return-object", {0})});
  auto Root = klass("Lfixture/Root;", {Echo, Hidden, Scalar, Identity});
  Root.access = {"public", "abstract", "interface"};
  Root.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Child = klass("Lfixture/Child;");
  Child.access = Root.access;
  Child.interfaces = {Root.name};
  Child.generic_signature =
      "<C:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Root<TC;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Receiver = klass("Lfixture/Receiver;", {Init});
  Receiver.interfaces = {Child.name};
  Receiver.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Child<TR;>;";
  return {Root, Child, Receiver};
}

