    EXPECT_NE(Text.find("public default int scalar()"), std::string::npos);
    EXPECT_NE(Text.find("private int hidden()"), std::string::npos);
    EXPECT_NE(
        Text.find(
            "public static java.lang.Object identity(java.lang.Object arg0)"),
        std::string::npos);
    EXPECT_EQ(source(R, 1).find(" echo("), std::string::npos);
    const auto *Helpers = R.getArray("generated_source_helpers");
    ASSERT_NE(Helpers, nullptr);
