TEST(MobileDalvikJava,
     FixedExceptionSubsetsRequireClosedReceiptsAndFullScopes) {
  for (bool External : {false, true})
    for (bool Subinterface : {false, true})
      for (bool MethodScope : {false, true})
        for (bool Reverse : {false, true})
          for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
            SCOPED_TRACE(External);
            SCOPED_TRACE(Subinterface);
            SCOPED_TRACE(MethodScope);
            SCOPED_TRACE(Reverse);
            SCOPED_TRACE(Mutation);
            auto Input = fixedExceptionSubsetClasses(External, Subinterface,
                                                     MethodScope, 1);
            auto &Provided = Input[0].methods[MethodScope ? 1 : 0];
            auto &Required = Input[1].methods[MethodScope ? 1 : 0];
            const auto ProvidedRef = Provided.reference,
                       RequiredRef = Required.reference;
            if (Mutation == 0)
              Provided.declared_throws = {"Ljava/lang/Throwable;"};
            else if (Mutation == 1)
              Provided.declared_throws->push_back("Ljava/lang/Exception;");
            else if (Mutation == 2)
              Provided.generic_signature =
                  Provided.generic_signature.value_or("(Ljava/lang/Object;)"
                                                      "Ljava/lang/Object;") +
                  "^Lfixture/First;";
            else if (Mutation == 3)
              Required.generic_signature =
                  Required.generic_signature.value_or("(Ljava/lang/Object;)"
                                                      "Ljava/lang/Object;") +
                  "^Lfixture/First;";
            else if (Mutation == 4) {
              if (MethodScope)
                Provided.generic_signature =
                    "<R:Ljava/lang/Object;>(Ljava/lang/Class<*>;TR;)TR;";
              else
                Provided.generic_signature = "<M:Ljava/lang/Object;>(Ljava/"
                                             "lang/Object;)Ljava/lang/Object;";
            } else if (Mutation == 5)
              Provided.access.insert("static");
            else if (Mutation == 6)
              Provided.access = {"private"};
            else if (Mutation == 7)
              Required.declared_throws = {"Lfixture/UnknownFailure;"};
            else if (Mutation == 8)
              Provided.declared_throws = {"Lfixture/UnknownFailure;"};
            else if (Mutation == 11)
              Provided.declared_throws->push_back("Lfixture/First;");
            else if (Mutation == 12)
              Required.declared_throws->push_back("Lfixture/First;");
            else if (Mutation == 13) {
              Provided.reference.returns = "V";
              Provided.generic_signature.reset();
            }
            if (Reverse) {
              std::reverse(Input.begin(), Input.end());
              for (auto &Owner : Input)
                std::reverse(Owner.methods.begin(), Owner.methods.end());
            }
            Budget B;
            if (Mutation == 9 || Mutation == 10) {
              auto Classes = linkClasses(Input, B);
              auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_EQ(Plans.closed_declared_throws.erase(
                            Mutation == 9 ? RequiredRef : ProvidedRef),
                        1u);
              EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                           std::runtime_error);
            } else
              EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                           std::runtime_error);
          }
}

