std::vector<Class> sourceRawInterfaceParentClasses() {
  auto Fold =
      method("fold", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Fold.access = {"public", "abstract"};
  Fold.generic_signature = "<M:Ljava/lang/Object;>(TM;)TM;";
  auto Root = klass("Lfixture/Root;", {Fold});
  Root.access = {"public", "abstract", "interface"};
  Fold.access = {"public"};
  Fold.registers = 2;
  Fold.instructions = {op(0, "return-object", {1})};
  Fold.code_end = 1;
  Fold.generic_signature = "<R:Ljava/lang/Object;>(TR;)TR;";
  auto Leaf = klass("Lfixture/Leaf;", {Fold});
  Leaf.access = Root.access;
  Leaf.interfaces = {Root.name};
  auto Elements = method("elements", {}, "Lfixture/Box;", 0, {});
  Elements.access = {"public", "abstract"};
  Elements.generic_signature = "()Lfixture/Box<Ljava/lang/Object;>;";
  auto View = klass("Lfixture/View;", {Elements});
  View.access = Root.access;
  Elements.access = {"public", "final"};
  Elements.registers = 2;
  Elements.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
  Elements.code_end = 2;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Make = method("make", {}, "Ljava/lang/Object;", 0, {});
  Make.access = {"public", "abstract"};
  Make.generic_signature = "()TP;";
  auto Parent = klass("Lfixture/Parent;", {Init, Elements, Make});
  Parent.access.insert("abstract");
  Parent.interfaces = {Leaf.name, View.name};
  Parent.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Leaf;Lfixture/View;";
  Make.access = {"public"};
  Make.registers = 2;
  Make.instructions = {op(0, "const/4", {0}, int64_t(0)),
                       op(1, "return-object", {0})};
  Make.code_end = 2;
  Make.generic_signature = "()TC;";
  auto Child = klass("Lfixture/Child;", {Make});
  Child.superclass = Parent.name;
  Child.generic_signature = "<C:Ljava/lang/Object;>Lfixture/Parent<TC;>;";
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Root, Leaf, View, Parent, Child, Box};
}

TEST(MobileDalvikJava, SourceGenericParentsRetainKnownRawInterfaceContracts) {
  for (bool Link : {false, true}) {
    auto Input = sourceRawInterfaceParentClasses();
    Budget B;
    const auto R =
        Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 7);
    EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    EXPECT_FALSE(R.getArray("generic_signature_projections"));
    EXPECT_NE(source(R, 1).find("R fold(R arg0)"), std::string::npos);
    EXPECT_NE(source(R, 1).find("public default"), std::string::npos);
    EXPECT_NE(source(R, 2).find("implements fixture.Leaf, fixture.View"),
              std::string::npos);
  }
}

std::vector<Class> deferredPlainCallbackClasses(bool External = false,
                                                bool MethodFormals = false) {
  auto Input = sourceRawInterfaceParentClasses();
  auto &Required = Input[0].methods[0];
  if (!MethodFormals) {
    Required.reference.name = "update";
    Required.reference.parameters = {"I", "Ljava/lang/Object;"};
    Required.reference.returns = "V";
    Required.generic_signature.reset();
  }
  auto Provided = Required;
  Provided.reference.owner = Input[4].name;
  Provided.access = {"public"};
  Provided.registers = MethodFormals ? 2 : 3;
  Provided.instructions =
      MethodFormals ? std::vector<Instruction>{op(0, "return-object", {1})}
                    : std::vector<Instruction>{op(0, "return-void")};
  Provided.code_end = 1;
  if (MethodFormals)
    Provided.generic_signature = "<N:Ljava/lang/Object;>(TN;)TN;";
  Input[4].methods.push_back(Provided);
  Input[1].methods.clear();
  Input[0].external = Input[1].external = External;
  return Input;
}

