std::vector<Class> deferredAbstractPlainChainClasses(bool External,
                                                     bool MethodFormals,
                                                     bool Redeclare) {
  auto Input = deferredPlainCallbackClasses(External, MethodFormals);
  auto &Middle = Input[4];
  Middle.access.insert("abstract");
  auto Provided = Middle.methods.back();
  Middle.methods.pop_back();
  if (Redeclare) {
    auto Required = Provided;
    Required.access = {"public", "abstract"};
    Required.instructions.clear();
    Required.registers = Required.code_end = 0;
    Middle.methods.push_back(Required);
  }
  auto Init = Input[3].methods[0];
  Init.reference.owner = Middle.name;
  Init.instructions[0].reference = Input[3].methods[0].reference;
  Middle.methods.push_back(Init);
  auto Concrete = klass("Lfixture/Concrete;", {Provided, Init});
  Concrete.superclass = Middle.name;
  Concrete.generic_signature = "<D:Ljava/lang/Object;>Lfixture/Child<TD;>;";
  Concrete.methods[1].instructions[0].reference = Init.reference;
  Input.push_back(Concrete);
  return Input;
}

