TEST(MobileDalvikJava, DeferredMethodBoundsRetainFullSameErasureContracts) {
  for (bool External : {false, true})
    for (bool Changed : {false, true}) {
      auto Input = deferredPlainCallbackClasses(External, true);
      Input[0].methods[0].generic_signature =
          "<M:Ljava/lang/Object;Q:Ljava/lang/Object;>(TM;)TM;";
      Input[4].methods.back().generic_signature =
          "<N:Ljava/lang/Object;U:Ljava/lang/Object;>(TN;)TN;";
      auto Fold = Input[0].methods[0];
      Fold.generic_signature =
          Changed ? "<R:Ljava/lang/Object;S:TR;>(TR;)TR;"
                  : "<R:Ljava/lang/Object;S:Ljava/lang/Object;>"
                    "(TR;)TR;";
      auto Other = klass("Lfixture/Other;", {Fold});
      Other.access = {"public", "abstract", "interface"};
      Other.external = External;
      Input[3].interfaces.push_back(Other.name);
      *Input[3].generic_signature += Other.name;
      Input.push_back(Other);
      Budget B;
      if (Changed)
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      else {
        const auto R = recoverJava(linkClasses(Input, B), B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      }
    }
}

TEST(MobileDalvikJava, AbstractPlainDeferralRejectsConcreteGapsAndConflicts) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
        SCOPED_TRACE(Mutation);
        auto Input = deferredAbstractPlainChainClasses(External, true, false);
        if (Mutation == 0)
          Input[4].access.erase("abstract");
        else if (Mutation == 1)
          Input[6].methods.erase(Input[6].methods.begin());
        else if (Mutation == 2)
          Input[6].methods[0].generic_signature =
              "<N:Ljava/lang/Object;>(TN;)Ljava/lang/Object;";
        else if (Mutation == 3) {
          auto Shadow = Input[0].methods[0];
          Shadow.reference.owner = Input[4].name;
          Shadow.access = {"public", "static"};
          Shadow.registers = 1;
          Shadow.instructions = {op(0, "return-object", {0})};
          Shadow.code_end = 1;
          Input[4].methods.push_back(Shadow);
        } else if (Mutation == 4)
          Input[6].methods[0].access = {"protected"};
        else if (Mutation == 5) {
          auto Wrong = Input[0].methods[0];
          Wrong.reference.returns = "I";
          Wrong.generic_signature = "<M:Ljava/lang/Object;>(TM;)I";
          auto Other = klass("Lfixture/Other;", {Wrong});
          Other.access = {"public", "abstract", "interface"};
          Other.external = External;
          Input[4].interfaces.push_back(Other.name);
          *Input[4].generic_signature += Other.name;
          Input.pop_back(); // No concrete descendant can mask this conflict.
          Input.push_back(Other);
        } else if (Mutation == 6) {
          auto Wrong = Input[0].methods[0];
          Wrong.reference.owner = Input[4].name;
          Wrong.generic_signature =
              "<M:Ljava/lang/Object;>(Ljava/lang/Object;)TM;";
          Input[4].methods.push_back(Wrong);
        } else {
          Input[3].interfaces.push_back("Lfixture/Missing;");
          *Input[3].generic_signature += "Lfixture/Missing;";
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava,
     DeferredMethodImplementationBridgesKeepOriginalScopesAndBodies) {
  for (bool External : {false, true})
    for (bool Synthetic : {false, true})
      for (bool Link : {false, true}) {
        auto Input = deferredPlainCallbackClasses(External, true);
        auto &Provided = Input[4].methods.back();
        Provided.access.insert("bridge");
        if (Synthetic)
          Provided.access.insert("synthetic");
        const auto Ref = Provided.reference;
        Budget B;
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        unsigned Found = 0;
        for (const auto &Value : *R.getArray("methods")) {
          const auto &Row = *Value.getAsObject();
          if (Row.getString("identity") != Ref.identity())
            continue;
          ++Found;
          EXPECT_EQ(Row.getString("projection_kind"),
                    "method-formal-implementation-bridge");
          EXPECT_EQ(Row.getString("generic_signature"),
                    "<N:Ljava/lang/Object;>(TN;)TN;");
          EXPECT_EQ(Row.getString("source_identity"), Ref.identity());
          EXPECT_FALSE(Row.getString("bridge_target"));
          ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
          EXPECT_FALSE(Row.getArray("metadata_differences")->empty());
        }
        EXPECT_EQ(Found, 1u);
      }
}

TEST(MobileDalvikJava,
     DeferredPlainCallbacksRequireCompleteConcreteChildSlots) {
  for (unsigned Mutation = 0; Mutation < 11; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = deferredPlainCallbackClasses(false, true);
    auto &Provided = Input[4].methods.back();
    if (Mutation == 0)
      Input[4].methods.pop_back();
    else if (Mutation == 1)
      Provided.access.insert("static");
    else if (Mutation == 2)
      Provided.access = {"private"};
    else if (Mutation == 3) {
      Provided.access.insert("abstract");
      Provided.instructions.clear();
      Provided.registers = Provided.code_end = 0;
    } else if (Mutation == 4) {
      Provided.access.insert("bridge");
      Provided.generic_signature.reset();
    } else if (Mutation == 5)
      Provided.generic_signature =
          "<N:Ljava/lang/Object;>(Ljava/lang/Object;)Ljava/lang/Object;";
    else if (Mutation == 6)
      Provided.generic_signature = "(TC;)TC;";
    else if (Mutation == 7)
      Input[3].access.erase("abstract");
    else if (Mutation == 8) {
      auto Shadow = Provided;
      Shadow.reference.owner = Input[3].name;
      Shadow.access = {"public", "static"};
      Input[3].methods.push_back(Shadow);
    } else if (Mutation == 9) {
      auto Shadow = Provided;
      Shadow.reference.owner = Input[3].name;
      Shadow.access = {"public", "final"};
      Input[3].methods.push_back(Shadow);
    } else
      Input[0].methods[0].generic_signature =
          "<M:Ljava/lang/Object;>(TM;)Ljava/lang/Object;";
    rejected([&] { recover(Input); }, "generic");
  }
}

