std::vector<Class> inheritedGenericEmptyThrowsClasses(bool External = false,
                                                      bool Middle = false,
                                                      bool Open = false) {
  auto Convert = method("convert", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                        "Ljava/lang/Object;", 0, {});
  Convert.access = {"public", "abstract"};
  Convert.generic_signature = "(Ljava/lang/Object;TT;)TT;";
  Convert.declared_throws = {"Ljava/lang/RuntimeException;"};
  auto Api = klass("Lfixture/ConvertApi;", {Convert});
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.external = External;
  const auto Init = [](const std::string &Owner, const std::string &Parent) {
    auto Method = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    Method.reference.owner = Owner;
    Method.access = {"public", "constructor"};
    return Method;
  };
  Convert.reference.owner = "Lfixture/ConvertParent;";
  Convert.access = {"public"};
  Convert.generic_signature = "(Ljava/lang/Object;TP;)TP;";
  Convert.declared_throws.reset();
  Convert.registers = 3;
  Convert.instructions = {op(0, "return-object", {2})};
  Convert.code_end = 1;
  auto Parent =
      klass(Convert.reference.owner,
            {Init(Convert.reference.owner, "Ljava/lang/Object;"), Convert});
  Parent.access.insert("abstract");
  Parent.interfaces = {Api.name};
  Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;"
                             "Lfixture/ConvertApi<TP;>;";
  auto Between = klass("Lfixture/ConvertMiddle;",
                       {Init("Lfixture/ConvertMiddle;", Parent.name)});
  Between.superclass = Parent.name;
  Between.generic_signature =
      "<N:Ljava/lang/Object;>Lfixture/ConvertParent<TN;>;";
  const auto Base = Middle ? Between.name : Parent.name;
  auto Child =
      klass("Lfixture/ConvertChild;", {Init("Lfixture/ConvertChild;", Base)});
  Child.superclass = Base;
  Child.generic_signature = (Open ? "<C:Ljava/lang/Object;>" : "") +
                            Base.substr(0, Base.size() - 1) +
                            (Open ? "<TC;>;" : "<Ljava/lang/Object;>;");
  std::vector<Class> Input{Api, Parent, Child};
  if (Middle)
    Input.push_back(Between);
  return Input;
}

