TEST(MobileDalvikJava,
     EmptyInheritedThrowsRequireCompleteGenericProviderProof) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = inheritedGenericEmptyThrowsClasses(true, true, true);
      auto &Required = Input[0].methods[0];
      auto &Provided = Input[1].methods[1];
      if (Mutation == 0)
        Provided.generic_signature =
            "(Ljava/lang/Object;Ljava/lang/Object;)TP;";
      else if (Mutation == 1)
        Provided.generic_signature =
            "(Ljava/lang/Object;TP;)Ljava/lang/Object;";
      else if (Mutation == 2)
        Provided.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 3)
        Provided.generic_signature =
            "(Ljava/lang/Object;TP;)TP;^Ljava/lang/RuntimeException;";
      else if (Mutation == 4)
        Required.generic_signature =
            "(Ljava/lang/Object;TT;)TT;^Ljava/lang/RuntimeException;";
      else if (Mutation == 5)
        Required.declared_throws = {"Lfixture/MissingFailure;"};
      else if (Mutation == 6)
        Required.declared_throws = {"Ljava/lang/String;"};
      else if (Mutation == 7)
        Input[1].methods.pop_back();
      else if (Mutation >= 8 && Mutation <= 10) {
        auto Shadow = Provided;
        Shadow.reference.owner = Input[3].name;
        Shadow.generic_signature = "(Ljava/lang/Object;TN;)TN;";
        if (Mutation == 8)
          Shadow.access.insert("static");
        else if (Mutation == 9)
          Shadow.access = {"private"};
        else {
          Input[3].access.insert("abstract");
          Shadow.access.insert("abstract");
          Shadow.instructions.clear();
          Shadow.registers = Shadow.code_end = 0;
        }
        Input[3].methods.push_back(Shadow);
      }
      Budget B;
      if (Mutation == 11) {
        auto Classes = linkClasses(Input, B);
        auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_EQ(Plans.closed_declared_throws.erase(Required.reference), 1u);
        EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                     std::runtime_error);
      } else
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
    }
}

TEST(MobileDalvikJava, PlainOverridesRetainEmptyThrowsNarrowing) {
  for (bool External : {false, true})
    for (bool MethodFormals : {false, true})
      for (bool Deferred : {false, true})
        for (bool Link : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input =
                emptyThrowsOverrideClasses(External, MethodFormals, Deferred);
            const auto Required = Input[0].methods[0].reference;
            const auto Provided =
                Input[Deferred ? 4 : 3].methods.back().reference;
            if (Reverse) {
              Input[Deferred ? 4 : 3].methods.back().declared_throws =
                  std::vector<std::string>{};
              std::reverse(Input.begin(), Input.end());
              for (auto &Cls : Input)
                std::reverse(Cls.methods.begin(), Cls.methods.end());
            }
            ClassMap Classes;
            for (const auto &Cls : Input)
              Classes.emplace(Cls.name, Cls);
            Budget B;
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_EQ(Plans.closed_declared_throws.at(Required),
                      std::vector<std::string>{"Ljava/lang/Throwable;"});
            EXPECT_FALSE(Plans.closed_declared_throws.contains(Provided));
            const auto R =
                Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("method_count"), External ? 6 : 7);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_EQ(Classes.at(Required.owner).methods[0].declared_throws,
                      std::optional<std::vector<std::string>>{
                          {"Ljava/lang/Throwable;"}});
          }
}

TEST(MobileDalvikJava, EmptyThrowsOverridesRequireClosedContractsAndReceipts) {
  for (bool External : {false, true})
    for (bool Deferred : {false, true})
      for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Deferred);
        SCOPED_TRACE(Mutation);
        auto Input = emptyThrowsOverrideClasses(External, true, Deferred);
        auto &Required = Input[0].methods[0];
        auto &Provided = Input[Deferred ? 4 : 3].methods.back();
        if (Mutation == 0)
          Required.declared_throws = {"Lfixture/MissingFailure;"};
        else if (Mutation == 1) {
          Required.declared_throws = {"Lfixture/NotThrowable;"};
          Input.push_back(klass("Lfixture/NotThrowable;"));
        } else if (Mutation == 2)
          Required.generic_signature =
              "<M:Ljava/lang/Object;E:Ljava/lang/Throwable;>(TM;)TM;^TE;";
        else if (Mutation == 3)
          Provided.declared_throws = {"Ljava/lang/Exception;"};
        else if (Mutation == 4)
          Provided.generic_signature =
              "<N:Ljava/lang/Object;>(Ljava/lang/Object;)Ljava/lang/Object;";
        else if (Mutation == 5)
          Provided.generic_signature = Deferred ? "(TC;)TC;" : "(TP;)TP;";
        else if (Mutation == 6)
          Required.declared_throws->push_back("Ljava/lang/Throwable;");
        else if (Mutation == 7)
          Required.generic_signature =
              "<M:Ljava/lang/Object;>(TM;)TM;^Ljava/lang/Throwable;";
        else if (Mutation == 9)
          Provided.declared_throws = {"Ljava/lang/Throwable;"};
        else if (Mutation == 10)
          Provided.access = {"private"};
        else if (Mutation == 11)
          Provided.access.insert("static");
        else if (Mutation == 12)
          Provided.access.insert("bridge");
        else if (Mutation == 13) {
          Provided.declared_throws = {"Ljava/lang/Throwable;"};
          Provided.generic_signature =
              "<N:Ljava/lang/Object;E:Ljava/lang/Throwable;>(TN;)TN;^TE;";
        } else if (Mutation == 14)
          Provided.declared_throws = {"Ljava/lang/Object;"};
        if (Mutation == 8) {
          Budget B;
          auto Classes = linkClasses(Input, B);
          auto Plans = validateGenericSignatures(Classes, B);
          ASSERT_EQ(Plans.closed_declared_throws.erase(Required.reference), 1u);
          EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                       std::runtime_error);
        } else if (Mutation == 3 || Mutation == 9) {
          // The complete comparator accepts matching fixed exceptions and
          // validated Exception-to-Throwable narrowing with the same original
          // method-owned alpha-equivalent scope. Object remains invalid.
          const auto R = recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
        } else
          rejected([&] { recover(Input); }, "generic");
      }
}

