std::vector<Class> inheritedExternalDefaultClasses(bool ChildFirst = true,
                                                   bool Override = false) {
  auto Input = sourceInterfaceSuperclassClasses(ChildFirst, true);
  auto Middle = klass("Lfixture/MiddleContract;");
  Middle.access = {"public", "abstract", "interface"};
  Middle.external = true;
  Middle.interfaces = {Input[0].name};
  Middle.generic_signature =
      "<M:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Contract<TM;>;";
  if (Override) {
    auto Default = Input[0].methods.back();
    Default.reference.owner = Middle.name;
    Middle.methods.push_back(Default);
  }
  auto Leaf = klass("Lfixture/LeafContract;");
  Leaf.access = {"public", "abstract", "interface"};
  Leaf.external = true;
  Leaf.interfaces = {Middle.name};
  Leaf.generic_signature =
      "<L:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/MiddleContract<TL;>;";
  Input[1].interfaces = {Leaf.name};
  Input[1].generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/LeafContract<TP;>;";
  Input.push_back(Middle);
  Input.push_back(Leaf);
  return Input;
}

