  Middle.generic_signature =
      "<M:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Child<TM;>;";
  Input[2].interfaces = {Middle.name, Input[1].name};
  Input[2].generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Middle<TR;>;"
      "Lfixture/Child<TR;>;";
