std::vector<Class> transitiveClassRootDefaultClasses() {
  auto Input = mixedSourceExternalDefaultClasses();
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.access.insert("abstract");
  Parent.interfaces = {Input[1].name};
  Parent.generic_signature =
      "<L:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Child<TR;>;";
  Input[2].superclass = Parent.name;
  Input[2].methods[0].instructions[0].reference = Parent.methods[0].reference;
  // Only the transitive Middle root is direct, so the redundant Child root
  // on Parent must use the complete interface closure and composed R binding.
  Input[2].interfaces.resize(1);
  Input[2].generic_signature =
      "<R:Ljava/lang/Object;U:Ljava/lang/Object;>Lfixture/Parent<TU;TR;>;"
      "Lfixture/Middle<TR;>;";
  Input.push_back(Parent);
  return Input;
}

