std::vector<Class> incompatibleSelfReturnClasses() {
  const std::string Object = "Ljava/lang/Object;";
  auto Remove = method("remove", {Object, Object}, "Z", 0, {});
  Remove.access = {"public"};
  auto Put = method("put", {Object}, Object, 0, {});
  Put.access = {"public", "abstract"};
  Put.generic_signature = "(TT;)TT;";
  auto Root = klass("Lfixture/RootBase;", {Remove, Put});
  Root.external = true;
  Root.access = {"public", "abstract", "interface"};
  Root.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Remove.reference.returns = "Lfixture/Persistent;";
  Remove.access.insert("abstract");
  Remove.generic_signature =
      "(Ljava/lang/Object;Ljava/lang/Object;)Lfixture/Persistent<TP;>;";
  Put.reference.returns = Remove.reference.returns;
  Put.generic_signature = "(TP;)Lfixture/Persistent<TP;>;";
  auto Persistent = klass("Lfixture/Persistent;", {Remove, Put});
  Persistent.access = Root.access;
  Persistent.interfaces = {Root.name};
  Persistent.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/RootBase<TP;>;";
  auto Leaf = klass("Lfixture/Leaf;");
  Leaf.access = Root.access;
  Leaf.interfaces = {Persistent.name};
  Leaf.generic_signature =
      "<L:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Persistent<TL;>;";
  auto Init = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Actor = klass("Lfixture/Actor;", {Init});
  Actor.interfaces = {Leaf.name};
  Actor.generic_signature =
      "<A:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Leaf<TA;>;";
  for (auto Original : Persistent.methods) {
    Original.reference.owner = Actor.name;
    Original.access = {"public"};
    Original.registers = Original.reference.parameters.size() + 1;
    Original.instructions = {op(0, "return-object", {0})};
    Original.code_end = 1;
    Original.generic_signature =
        Original.reference.name == "remove"
            ? "(Ljava/lang/Object;Ljava/lang/Object;)Lfixture/Persistent<TA;>;"
            : "(TA;)Lfixture/Persistent<TA;>;";
    Actor.methods.push_back(std::move(Original));
  }
  auto Existing =
      method("put", {Object}, Object, 2, {op(0, "return-object", {1})});
  Existing.reference.owner = Actor.name;
  Existing.access = {"public"};
  Existing.generic_signature = "(TA;)TA;";
  Actor.methods.push_back(Existing);
  auto Call = method(
      "callRemove", {Leaf.name, Object, Object}, Persistent.name, 4,
      {op(0, "invoke-interface", {1, 2, 3}, {},
          MethodRef{Leaf.name, "remove", {Object, Object}, Persistent.name}),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.reference.owner = Actor.name;
  Actor.methods.push_back(Call);
  auto Occupied =
      method("__neverdReturnSlot", {}, "I", 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return", {0})});
  Occupied.reference.owner = Actor.name;
  Actor.methods.push_back(Occupied);
  return {Root, Persistent, Leaf, Actor};
}

std::vector<Class> scopedSourceDefaultGetterClasses(bool External = false) {
  auto Get = method("getBox", {}, "Lfixture/Box;", 0, {});
  Get.access = {"public", "abstract"};
  Get.generic_signature = "()Lfixture/Box<TT;>;";
  auto Api = klass("Lfixture/Api;", {Get});
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.external = External;
  auto Box = klass("Lfixture/Box;");
  Box.access = Api.access;
  Box.generic_signature = Api.generic_signature;
  Box.external = External;
  Get.access = {"public"};
  Get.registers = 1;
  Get.instructions = {op(0, "return-object", {0})};
  Get.code_end = 1;
  Get.generic_signature = "()Lfixture/Box<TS;>;";
  auto Source = klass("Lfixture/Source;", {Get});
  Source.access = Api.access;
  Source.interfaces = {Api.name, Box.name};
  Source.generic_signature =
      "<S:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Api<TS;>;"
      "Lfixture/Box<TS;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Receiver = klass("Lfixture/Receiver;", {Init});
  Receiver.interfaces = {Source.name};
  Receiver.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Source<TR;>;";
  return {Api, Box, Source, Receiver};
}

