std::vector<Class> overridingSourceDefaultGetterClasses() {
  auto Input = inheritedSourceDefaultGetterClasses();
  auto Refined = Input[1];
  Refined.name = "Lfixture/Refined;";
  Refined.interfaces = {Input[1].name, Input[2].name};
  Refined.generic_signature = "Ljava/lang/Object;Lfixture/Getter;"
                              "Lfixture/Mirror<Ljava/lang/String;>;";
  Refined.methods.erase(Refined.methods.begin()); // read stays in its owner.
  for (auto &Member : Refined.methods) {
    Member.reference.owner = Refined.name;
    if (Member.reference.returns == "Ljava/lang/Object;")
      Member.instructions[0].reference = Refined.methods[0].reference;
  }
  Input[3].interfaces = {Refined.name, Input[2].name};
  Input[3].generic_signature =
      "<S:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Refined;"
      "Lfixture/Mirror<Ljava/lang/String;>;";
  Input.push_back(std::move(Refined));
  return Input;
}

