std::vector<Class> sourceDefaultWithDisjointClassRoots(bool WithSignature) {
  auto Input = overridingSourceDefaultGetterClasses();
  auto Event = method("event", {"I"}, "V", 0, {});
  Event.access = {"public", "abstract"};
  auto ObserverRoot = klass("Lfixture/ObserverRoot;", {Event});
  ObserverRoot.access = {"public", "abstract", "interface"};
  auto Observer = klass("Lfixture/Observer;");
  Observer.access = ObserverRoot.access;
  Observer.interfaces = {ObserverRoot.name};
  auto Parent = klass("Lfixture/Parent;", {Input[3].methods[0]});
  Parent.access = {"public", "abstract"};
  Parent.interfaces = {Observer.name};
  if (WithSignature)
    Parent.generic_signature = "Ljava/lang/Object;Lfixture/Observer;";
  Input[3].superclass = Parent.name;
  Input[3].generic_signature =
      "<S:Ljava/lang/Object;>Lfixture/Parent;Lfixture/Refined;"
      "Lfixture/Mirror<Ljava/lang/String;>;";
  Input[3].methods[0].instructions[0].reference = Parent.methods[0].reference;
  Event.reference.owner = Input[3].name;
  Event.access = {"public"};
  Event.registers = 2;
  Event.instructions = {op(0, "return-void")};
  Event.code_end = 1;
  Input[3].methods.push_back(Event);
  Input.push_back(Parent);
  Input.push_back(Observer);
  Input.push_back(ObserverRoot);
  return Input;
}

