std::vector<Class> inheritedWideConsumerClasses(bool External) {
  const std::string Object = "Ljava/lang/Object;", Token = "Lfixture/Token;";
  auto Write = method("write", {Token, Object}, "V", 0, {});
  Write.access = {"public", "abstract"};
  Write.generic_signature = "(Lfixture/Token;TT;)V";
  auto Read = method("read", {Token}, Object, 0, {});
  Read.access = Write.access;
  Read.generic_signature = "(Lfixture/Token;)TT;";
  auto Meta = method("meta", {}, Token, 0, {});
  Meta.access = Write.access;
  auto Consumer = klass("Lfixture/Consumer;", {Write, Meta});
  auto Producer = klass("Lfixture/Producer;", {Read, Meta});
  auto Api = klass("Lfixture/Api;", {Meta});
  for (auto *Cls : {&Consumer, &Producer, &Api}) {
    Cls->access = {"public", "abstract", "interface"};
    Cls->generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    Cls->external = External;
  }
  Api.interfaces = {Consumer.name, Producer.name};
  *Api.generic_signature += "Lfixture/Consumer<TT;>;Lfixture/Producer<TT;>;";
  auto Target = method("write", {Token, "J"}, "V", 4, {op(0, "return-void")});
  Target.access = {"public"};
  auto Bridge =
      method("write", {Token, Object}, "V", 5,
             {op(0, "move-object", {0, 4}),
              op(1, "check-cast", {0}, {}, std::string("Ljava/lang/Number;")),
              op(2, "invoke-virtual", {0}, {},
                 MethodRef{"Ljava/lang/Number;", "longValue", {}, "J"}),
              op(3, "move-result-wide", {0}),
              op(4, "invoke-virtual", {2, 3, 0, 1}, {}, Target.reference),
              op(5, "return-void")});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Getter =
      method("read", {Token}, "Ljava/lang/Long;", 3,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Getter.access = {"public"};
  auto GetterBridge =
      method("read", {Token}, Object, 3,
             {op(0, "invoke-virtual", {1, 2}, {}, Getter.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  GetterBridge.access = Bridge.access;
  Meta.access = {"public"};
  Meta.registers = 2;
  Meta.instructions = {op(0, "const/4", {0}, int64_t{0}),
                       op(1, "return-object", {0})};
  Meta.code_end = 2;
  auto Core =
      klass("Lfixture/Core;", {Target, Bridge, Getter, GetterBridge, Meta});
  Core.access.insert("final");
  Core.interfaces = {Api.name};
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Api<Ljava/lang/Long;>;";
  auto Unbox = method("longValue", {}, "J", 0, {});
  Unbox.access = {"public", "abstract"};
  auto Number = klass("Ljava/lang/Number;", {Unbox});
  Number.external = true;
  Number.access.insert("abstract");
  auto Box = klass("Ljava/lang/Long;");
  Box.external = true;
  Box.access.insert("final");
  Box.superclass = Number.name;
  return {Core, Api, Consumer, Producer, klass(Token), Number, Box};
}

std::vector<Class> inheritedNarrowConsumerClasses(bool External, bool Short) {
  auto Input = inheritedWideConsumerClasses(External);
  const std::string Primitive = Short ? "S" : "B";
  const std::string Box = Short ? "Ljava/lang/Short;" : "Ljava/lang/Byte;";
  const MethodRef Unbox{
      "Ljava/lang/Number;", Short ? "shortValue" : "byteValue", {}, Primitive};
  Input[0].generic_signature = "Ljava/lang/Object;Lfixture/Api<" + Box + ">;";
  auto &Target = Input[0].methods[0];
  Target.reference.parameters[1] = Primitive;
  Target.registers = 3;
  auto &Bridge = Input[0].methods[1];
  Bridge.instructions[2].reference = Unbox;
  Bridge.instructions[3].opcode = "move-result";
  Bridge.instructions[4].reference = Target.reference;
  Bridge.instructions[4].registers = {2, 3, 0};
  Input[0].methods[2].reference.returns = Box;
  Input[0].methods[3].instructions[0].reference = Input[0].methods[2].reference;
  Input[5].methods[0].reference = Unbox;
  Input[5].methods[0].access = {"public"};
  Input[6].name = Box;
  return Input;
}

std::vector<Class>
inheritedScalarCarrierConsumerClasses(bool External, bool Wide, bool Named) {
  auto Input = inheritedWideConsumerClasses(External);
  const std::string Carrier = "Lfixture/Carrier;", Primitive = Wide ? "J" : "I";
  auto &Target = Input[0].methods[0];
  Target.reference.name = Named ? "writeValue" : "write";
  Target.reference.parameters[1] = Primitive;
  Target.registers = Wide ? 4 : 3;
  auto &Bridge = Input[0].methods[1];
  Bridge.instructions[1].reference = Carrier;
  const MethodRef Unbox{Carrier, "readBits", {}, Primitive};
  Bridge.instructions[2].reference = Unbox;
  Bridge.instructions[3].opcode = Wide ? "move-result-wide" : "move-result";
  Bridge.instructions[4].reference = Target.reference;
  Bridge.instructions[4].registers =
      Wide ? std::vector<unsigned>{2, 3, 0, 1} : std::vector<unsigned>{2, 3, 0};
  Input[0].generic_signature =
      "Ljava/lang/Object;Lfixture/Api<Lfixture/Carrier;>;";
  Input[0].methods[2].reference.returns = Carrier;
  Input[0].methods[3].instructions[0].reference = Input[0].methods[2].reference;
  auto &Box = Input[5];
  Box.name = Carrier;
  Box.access = {"public", "final"};
  Box.external = External;
  Box.methods[0].reference = Unbox;
  Box.methods[0].access = {"public"};
  if (!External) {
    Box.methods[0].registers = Wide ? 3 : 2;
    Box.methods[0].instructions = {
        op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t{0}),
        op(1, Wide ? "return-wide" : "return", {0})};
    Box.methods[0].code_end = 2;
  }
  Input.pop_back();
  return Input;
}

std::vector<Class> inheritedScalarResultClasses(bool External, bool Wide,
                                                bool Range) {
  auto Input = inheritedScalarCarrierConsumerClasses(External, Wide, true);
  const std::string Primitive = Wide ? "J" : "I", Carrier = Input[5].name;
  auto &Target = Input[0].methods[2];
  Target.reference.name = "readValue";
  Target.reference.returns = Primitive;
  Target.registers = 4;
  Target.instructions = {
      op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t{0}),
      op(1, Wide ? "return-wide" : "return", {0})};
  Target.code_end = 2;
  auto Box =
      method("box", {Primitive}, Carrier, Wide ? 3 : 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Box.reference.owner = Carrier;
  Box.access = {"public", "static"};
  if (External) {
    Box.instructions.clear();
    Box.registers = 0;
    Box.code_end = 0;
  }
  Input[5].methods.push_back(Box);
  auto &Bridge = Input[0].methods[3];
  Bridge.registers = 4;
  Bridge.instructions = {
      op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {2, 3}, {},
         Target.reference),
      op(1, Wide ? "move-result-wide" : "move-result", {0}),
      op(2, Range ? "invoke-static/range" : "invoke-static",
         Wide ? std::vector<unsigned>{0, 1} : std::vector<unsigned>{0}, {},
         Box.reference),
      op(3, "move-result-object", {0}), op(4, "return-object", {0})};
  Bridge.code_end = 5;
  return Input;
}

std::vector<Class>
inheritedPrimitiveCarrierClasses(bool External, const std::string &Primitive,
                                 bool Range) {
  const bool Wide = Primitive == "J" || Primitive == "D";
  auto Input = inheritedScalarResultClasses(External, Wide, Range);
  auto &Write = Input[0].methods[0];
  Write.reference.parameters[1] = Primitive;
  auto &WriteBridge = Input[0].methods[1];
  auto &Unbox = Input[5].methods[0];
  Unbox.reference.returns = Primitive;
  WriteBridge.instructions[2].reference = Unbox.reference;
  WriteBridge.instructions[4].reference = Write.reference;
  auto &Read = Input[0].methods[2];
  Read.reference.returns = Primitive;
  auto &Factory = Input[5].methods[1];
  Factory.reference.parameters[0] = Primitive;
  auto &ReadBridge = Input[0].methods[3];
  ReadBridge.instructions[0].reference = Read.reference;
  ReadBridge.instructions[2].reference = Factory.reference;
  return Input;
}

std::vector<Class> arrayCarrierSuperclassClasses(const std::string &Array,
                                                 const std::string &Returns,
                                                 bool External,
                                                 bool Protected) {
  const std::string Carrier = "Lfixture/Carrier;", Token = "Lfixture/Token;";
  const bool Reference = Returns.starts_with('L') || Returns.starts_with('[');
  const bool Wide = Returns == "J" || Returns == "D";
  const std::string ErasedResult = Reference ? "Ljava/lang/Object;" : Returns;
  auto Required = method("apply", {Token, "Ljava/lang/Object;", "I", "J"},
                         ErasedResult, 0, {});
  Required.access = {Protected ? "protected" : "public", "abstract"};
  Required.generic_signature =
      "(Lfixture/Token;TC;IJ)" + (Reference ? std::string("TR;") : Returns);
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Parent = klass("Lfixture/Parent;", {Required, Init});
  Parent.access = {"public", "abstract"};
  Parent.generic_signature =
      "<C:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.external = External;
  if (External)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto Target =
      method("applyValue", {Token, Array, "I", "J"}, Returns, Wide ? 8 : 7, {});
  Target.access = {Protected ? "protected" : "public"};
  if (Returns == "V")
    Target.instructions = {op(0, "return-void")};
  else
    Target.instructions = {
        op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t{0}),
        op(1,
           Reference ? "return-object"
           : Wide    ? "return-wide"
                     : "return",
           {0})};
  Target.code_end = Target.instructions.size();
  const MethodRef Unbox{Carrier, "unbox", {}, Array};
  auto Bridge = method("apply", Required.reference.parameters, ErasedResult, 8,
                       {op(0, "move-object", {4, 4}),
                        op(1, "check-cast", {4}, {}, Carrier),
                        op(2, "invoke-virtual/range", {4}, {}, Unbox),
                        op(3, "move-result-object", {4}),
                        op(4, "invoke-virtual/range", {2, 3, 4, 5, 6, 7}, {},
                           Target.reference)});
  Bridge.access = {"public", "bridge", "synthetic"};
  if (Returns == "V")
    Bridge.instructions.push_back(op(5, "return-void"));
  else {
    Bridge.instructions.push_back(op(5,
                                     Reference ? "move-result-object"
                                     : Wide    ? "move-result-wide"
                                               : "move-result",
                                     {0}));
    Bridge.instructions.push_back(op(6,
                                     Reference ? "return-object"
                                     : Wide    ? "return-wide"
                                               : "return",
                                     {0}));
  }
  Bridge.code_end = Bridge.instructions.size();
  Init.instructions[0].reference = Parent.methods[1].reference;
  auto Core = klass("Lfixture/Core;", {Target, Bridge, Init});
  Core.access.insert("final");
  Core.superclass = Parent.name;
  Core.generic_signature = "Lfixture/Parent<Lfixture/Carrier;" +
                           (Reference ? Returns : Carrier) + ">;";
  auto Read =
      method("unbox", {}, Array, 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  Read.access = {"public"};
  auto Box = klass(Carrier, {Read});
  Box.access.insert("final");
  Box.external = External;
  if (External) {
    Box.methods[0].instructions.clear();
    Box.methods[0].registers = Box.methods[0].code_end = 0;
  }
  return {Core, Parent, Box, klass(Token)};
}

TEST(MobileDalvikJava,
     ArrayCarrierSuperclassEntriesPreserveCompleteCallsAndContracts) {
  for (const std::string Array : {"[Z", "[B", "[S", "[C", "[I", "[J", "[F",
                                  "[D", "[[B", "[Lfixture/Token;"})
    for (const std::string Returns :
         {"V", "I", "J", "D", "Lfixture/Carrier;", "[B"})
      for (bool External : {false, true})
        for (bool Protected : {false, true})
          for (bool Link : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(::testing::Message()
                           << Array << Returns << External << Protected << Link
                           << Reverse);
              auto Input = arrayCarrierSuperclassClasses(Array, Returns,
                                                         External, Protected);
              const auto Bridge = Input[0].methods[1].reference;
              auto Typed = Bridge;
              Typed.parameters[1] = Input[2].name;
              Typed.returns = Returns;
              if (Reverse) {
                for (auto &Owner : Input)
                  std::reverse(Owner.methods.begin(), Owner.methods.end());
                std::reverse(Input.begin(), Input.end());
              }
              Budget B;
              llvm::json::Object R;
              ASSERT_NO_THROW(R = Link ? recoverJava(linkClasses(Input, B), B)
                                       : recover(Input));
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              bool Found = false;
              for (const auto &Item : *R.getArray("methods")) {
                const auto &Row = *Item.getAsObject();
                if (Row.getString("identity") != Bridge.identity())
                  continue;
                Found = true;
                EXPECT_EQ(Row.getString("projection_kind"),
                          "array-carrier-superclass-bridge");
                EXPECT_EQ(Row.getString("source_identity"), Typed.identity());
                EXPECT_EQ(Row.getString("unbox_method"),
                          "Lfixture/Carrier;->unbox()" + Array);
              }
              EXPECT_TRUE(Found);
            }
}

