std::vector<Class> integerVoidConsumerClasses(bool External = false) {
  auto Required = method("accept", {"Ljava/lang/Object;"}, "V", 0, {});
  Required.access = {"public", "abstract"};
  Required.generic_signature = "(TT;)V";
  auto Contract = klass("Lfixture/Consumer;", {Required});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.external = External;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = method("accept", {"I"}, "V", 2, {op(0, "return-void")});
  Target.access = {"public"};
  auto Bridge = method("accept", {"Ljava/lang/Object;"}, "V", 3, {});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Init, Target, Bridge});
  Core.access.insert("final");
  Core.interfaces = {Contract.name};
  Core.generic_signature =
      "Ljava/lang/Object;Lfixture/Consumer<Ljava/lang/Integer;>;";
  Core.methods[2].instructions = {
      op(0, "move-object", {0, 2}),
      op(1, "check-cast", {0}, {}, std::string("Ljava/lang/Number;")),
      op(2, "invoke-virtual", {0}, {},
         MethodRef{"Ljava/lang/Number;", "intValue", {}, "I"}),
      op(3, "move-result", {0}),
      op(4, "invoke-virtual", {1, 0}, {}, Core.methods[1].reference),
      op(5, "return-void")};
  Core.methods[2].code_end = 6;
  auto Unbox = method("intValue", {}, "I", 0, {});
  Unbox.access = {"public", "abstract"};
  auto Number = klass("Ljava/lang/Number;", {Unbox});
  Number.external = true;
  Number.access.insert("abstract");
  auto Integer = klass("Ljava/lang/Integer;");
  Integer.access.insert("final");
  Integer.external = true;
  Integer.superclass = Number.name;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Core, Contract, Number, Integer, Object};
}

TEST(MobileDalvikJava, IntegerVoidConsumersRetainOriginalNarrowUnboxing) {
  for (bool External : {false, true})
    for (bool Signature : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = integerVoidConsumerClasses(External);
          const auto Original = *Input[0].generic_signature;
          if (Signature)
            Input[0].methods[1].generic_signature = "(I)V";
          if (Reverse) {
            std::reverse(Input.begin(), Input.end());
            for (auto &Cls : Input)
              std::reverse(Cls.methods.begin(), Cls.methods.end());
          }
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("method_count"), External ? 3 : 4);
          EXPECT_EQ(R.getInteger("projected_method_count"), 1);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_NE(source(R, External ? 0 : 1).find("void accept(int arg0)"),
                    std::string::npos);
          EXPECT_NE(source(R, External ? 0 : 1).find(".intValue()"),
                    std::string::npos);
          const auto *Projections = R.getArray("generic_signature_projections");
          ASSERT_NE(Projections, nullptr);
          ASSERT_EQ(Projections->size(), 1u);
          EXPECT_EQ(
              (*Projections)[0].getAsObject()->getString("original_signature"),
              Original);
          const auto *Rows = R.getArray("methods");
          ASSERT_NE(Rows, nullptr);
          unsigned Found = 0;
          for (const auto &Row : *Rows) {
            const auto *O = Row.getAsObject();
            if (O->getString("projection_kind") !=
                "value-carrier-interface-bridge")
              continue;
            ++Found;
            EXPECT_EQ(O->getString("bridge_target"),
                      "Lfixture/Core;->accept(I)V");
            EXPECT_EQ(O->getString("bridge_dispatch"),
                      "Lfixture/Consumer;->accept(Ljava/lang/Object;)V");
            EXPECT_FALSE(O->getString("box_method"));
            ASSERT_NE(O->getArray("unbox_methods"), nullptr);
            ASSERT_EQ(O->getArray("unbox_methods")->size(), 1u);
            EXPECT_EQ((*O->getArray("unbox_methods"))[0].getAsString(),
                      "Ljava/lang/Number;->intValue()I");
          }
          EXPECT_EQ(Found, 1u);
        }
}

TEST(MobileDalvikJava, IntegerVoidConsumersRejectContractAndConversionDrift) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = integerVoidConsumerClasses();
    auto &Target = Input[0].methods[1];
    auto &Bridge = Input[0].methods[2];
    if (Mutation == 0)
      Input[0].generic_signature =
          "<S:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Consumer<TS;>;";
    else if (Mutation == 1)
      Bridge.instructions[1].reference = std::string("Ljava/lang/Integer;");
    else if (Mutation == 2)
      Bridge.instructions[3].opcode = "move-result-wide";
    else if (Mutation == 3)
      Bridge.instructions[4].registers = {0, 1};
    else if (Mutation == 4)
      Bridge.instructions[0].registers = {0, 1};
    else if (Mutation == 5)
      Bridge.access.erase("bridge");
    else if (Mutation == 6)
      Input[0].access.erase("final");
    else if (Mutation == 7)
      Target.access.insert("static");
    else if (Mutation == 8)
      Target.generic_signature = "<M:Ljava/lang/Object;>(I)V";
    else if (Mutation == 9)
      Bridge.instructions[5].registers = {0};
    else if (Mutation == 10)
      Bridge.instructions[0].target = 5;
    else
      Input[2].methods[0].access.erase("public");
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

