std::vector<Class> inheritedRenamedReturnClasses(bool External = true) {
  auto Input = incompatibleSelfReturnClasses();
  Input[0].methods[0].access.insert("abstract");
  auto Init = Input[3].methods[0];
  auto Remove = Input[0].methods[0];
  Remove.access.erase("abstract");
  Remove.registers = 4;
  Remove.instructions = {op(0, "const/4", {0}, int64_t(1)),
                         op(1, "return", {0})};
  Remove.code_end = 2;
  auto Put = Input[0].methods[1];
  Put.access.erase("abstract");
  Put.registers = 2;
  Put.instructions = {op(0, "return-object", {1})};
  Put.code_end = 1;
  auto Parent = klass("Lfixture/ReturnParent;", {Init, Remove, Put});
  Parent.external = External;
  Parent.interfaces = {Input[0].name};
  Parent.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/RootBase<TT;>;";
  if (External)
    for (auto &M : Parent.methods) {
      M.instructions.clear();
      M.registers = 0;
      M.code_end = 0;
    }
  Input[3].superclass = Parent.name;
  Input[3].generic_signature =
      "<A:Ljava/lang/Object;>Lfixture/ReturnParent<TA;>;Lfixture/Leaf<TA;>;";
  Input[3].methods[0].instructions[0].reference =
      MethodRef{Parent.name, "<init>", {}, "V"};
  Input.push_back(Parent);
  return Input;
}

