        Input[4].external = false;
        Input[4].methods[0].access.insert("abstract");
        break;
      case 2:
        Input[4].interfaces = {Input[5].name};
        Input[4].generic_signature = "<M:Ljava/lang/Object;>Ljava/lang/"
                                     "Object;Lfixture/LeafContract<TM;>;";
        break;
