std::vector<Class> covariantExternalDefaultClasses() {
  auto Input = inheritedExternalDefaultClasses(true, true);
  auto Root = method("reverse", {}, Input[0].name, 0, {});
  Root.access = {"public"};
  Root.reference.owner = Input[0].name;
  Root.generic_signature = "()Lfixture/Contract<TT;>;";
  Input[0].methods.push_back(Root);
  auto Derived = Root;
  Derived.reference.owner = Input[4].name;
  Derived.reference.returns = Input[4].name;
  Derived.generic_signature = "()Lfixture/MiddleContract<TM;>;";
  Input[4].methods.push_back(Derived);
  Root.reference.owner = Input[4].name;
  Root.access = {"public", "bridge", "synthetic"};
  Root.generic_signature.reset();
  Input[4].methods.push_back(Root);
  Input[5].interfaces.push_back(Input[0].name);
  *Input[5].generic_signature += "Lfixture/Contract<TL;>;";
  return Input;
}

