std::vector<Class> inheritedObjectContractClasses(bool Overload = false) {
  auto Equals = method("equals", {"Ljava/lang/Object;"}, "Z", 0, {});
  auto Hash = method("hashCode", {}, "I", 0, {});
  auto Text = method("toString", {}, "Ljava/lang/String;", 0, {});
  for (auto *M : {&Equals, &Hash, &Text})
    M->access = {"public"};
  auto Object = klass("Ljava/lang/Object;", {Equals, Hash, Text});
  Object.superclass.reset();
  Object.external = true;
  auto Init = method("<init>", {}, "V", 0, {});
  Init.reference.owner = Object.name;
  Init.access = {"public", "constructor"};
  Object.methods.push_back(Init);
  for (auto *M : {&Equals, &Hash, &Text})
    M->access.insert("abstract");
  auto Contract = klass("Lfixture/Contract;", {Equals, Hash, Text});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Init.registers = 1;
  Init.instructions = {op(0, "invoke-direct", {0}, {}, Init.reference),
                       op(1, "return-void")};
  Init.code_end = 2;
  auto Core = klass("Lfixture/Core;", {Init});
  Core.interfaces = {Contract.name};
  Core.generic_signature =
      "<C:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Contract<TC;>;";
  if (Overload) {
    auto Extra =
        method("equals", {"Ljava/lang/String;"}, "Z", 2,
               {op(0, "const", {0}, int64_t(0)), op(1, "return", {0})});
    Extra.access = {"public"};
    Extra.reference.owner = Core.name;
    Core.methods.push_back(Extra);
  }
  return {Contract, Core, Object};
}

std::vector<Class> classAncestorObjectContractClasses(bool ExternalTail) {
  auto Input = inheritedObjectContractClasses(true);
  auto Init = Input[1].methods[0];
  Init.reference.owner = "Lfixture/ObjectRoot;";
  auto Root = klass(Init.reference.owner, {Init});
  Root.generic_signature =
      "<R:Ljava/lang/Object;S:Ljava/lang/Object;>Ljava/lang/Object;";
  if (ExternalTail) {
    Root.external = true;
    Root.methods[0].instructions.clear();
    Root.methods[0].registers = 0;
    Root.methods[0].code_end = 0;
  }
  Init.reference.owner = "Lfixture/ObjectMiddle;";
  Init.instructions[0].reference = Root.methods[0].reference;
  auto Middle = klass(Init.reference.owner, {Init});
  Middle.superclass = Root.name;
  Middle.generic_signature =
      "<M:Ljava/lang/Object;N:Ljava/lang/Object;>Lfixture/ObjectRoot<TM;TN;>;";
  Input[1].superclass = Middle.name;
  Input[1].generic_signature =
      "<C:Ljava/lang/Object;>Lfixture/ObjectMiddle<TC;Ljava/lang/"
      "String;>;Lfixture/Contract<TC;>;";
  Input[1].methods[0].instructions[0].reference = Middle.methods[0].reference;
  Input.push_back(Root);
  Input.push_back(Middle);
  return Input;
}

