TEST(MobileDalvikJava,
     InterfaceObjectSlotsRejectUnprovenOrChangedDeclarations) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = inheritedObjectContractClasses();
      switch (Mutation) {
      case 0:
        Input.pop_back();
        break;
      case 1:
        Input[2].external = false;
        for (auto &M : Input[2].methods) {
          M.registers = M.incomingWords();
          if (M.reference.name == "<init>")
            M.instructions = {op(0, "return-void")};
          else
            M.instructions = {op(0, "const", {0}, int64_t(0)),
                              op(1,
                                 M.reference.returns == "Ljava/lang/String;"
                                     ? "return-object"
                                     : "return",
                                 {0})};
          M.code_end = M.instructions.size();
        }
        break;
      case 2:
        Input[2].methods[0].access = {"protected"};
        break;
      case 3:
        Input[2].methods[0].access = {"public", "static"};
        break;
      case 4:
        Input[2].methods[0].declared_throws =
            std::vector<std::string>{"Ljava/lang/Exception;"};
        break;
      case 5:
        Input[2].methods.erase(Input[2].methods.begin());
        break;
      case 6: {
        auto Changed =
            method("equals", {"Ljava/lang/Object;"}, "I", 2,
                   {op(0, "const", {0}, int64_t(0)), op(1, "return", {0})});
        Changed.access = {"public"};
        Changed.reference.owner = Input[1].name;
        Input[1].methods.push_back(Changed);
        break;
      }
      case 7:
        Input[2].methods[0].access.insert("final");
        break;
      }
      Budget B;
      rejected(
          [&] {
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          },
          "generic");
    }
}

std::vector<Class> inheritedGenericClassContracts(bool ChildFirst = true,
                                                  bool Bounded = false,
                                                  bool Default = false) {
  auto Value =
      method("value", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Value.access = {"public", "abstract"};
  Value.generic_signature = "(TP;)TP;";
  auto Lookup =
      method("lookup", {"Ljava/lang/Object;"}, "Lfixture/Cell;", 0, {});
  Lookup.access = {"public", "abstract"};
  Lookup.generic_signature = "(TP;)Lfixture/Cell<TP;TQ;>;";
  auto Contract = klass("Lfixture/Contract;", {Value, Lookup});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Default) {
    Contract.external = true;
    Contract.methods[1].access = {"public"};
  }
  Value.access = {"public"};
  Value.generic_signature = "(TR;)TR;";
  Value.registers = 2;
  Value.instructions = {op(0, "return-object", {1})};
  Value.code_end = 1;
  Lookup.access = {"public"};
  Lookup.generic_signature = "(TR;)Lfixture/Cell<TR;TS;>;";
  Lookup.registers = 2;
  Lookup.instructions = {op(0, "const", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
  Lookup.code_end = 2;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Root = klass("Lfixture/Root;", {Value, Lookup, Init});
  Root.generic_signature =
      "<R:Ljava/lang/Object;S:Ljava/lang/Object;>Ljava/lang/Object;";
  Init.instructions[0].reference = MethodRef{Root.name, "<init>", {}, "V"};
  auto Middle = klass("Lfixture/Middle;", {Init});
  Middle.superclass = Root.name;
  Middle.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Lfixture/Root<TP;TQ;>;";
  Init.instructions[0].reference = MethodRef{Middle.name, "<init>", {}, "V"};
  auto Child =
      klass(ChildFirst ? "Lfixture/AChild;" : "Lfixture/ZChild;", {Init});
  Child.superclass = Middle.name;
  Child.interfaces = {Contract.name};
  Child.generic_signature =
      std::string(Bounded ? "<I:Lfixture/Tag;" : "<I:Ljava/lang/Object;") +
      "J:Ljava/lang/Object;>Lfixture/Middle<TI;TJ;>;Lfixture/Contract<TI;TJ;>;";
  auto Cell = klass("Lfixture/Cell;");
  Cell.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Ljava/lang/Object;";
  std::vector<Class> Input{Contract, Root, Middle, Child, Cell};
  if (Bounded)
    Input.push_back(klass("Lfixture/Tag;"));
  return Input;
}

