TEST(MobileDalvikJava, InheritedClassContractsRejectErasureOrProviderGaps) {
  for (bool Default : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
        SCOPED_TRACE(Mutation);
        auto Input = inheritedGenericClassContracts(true, false, Default);
        auto &Lookup = Input[1].methods[1];
        switch (Mutation) {
        case 0:
          Lookup.generic_signature = "(TS;)Lfixture/Cell<TR;TS;>;";
          break;
        case 1:
          Lookup.generic_signature = "(TR;)Lfixture/Cell<TS;TR;>;";
          break;
        case 2:
          Lookup.generic_signature.reset();
          break;
        case 3:
          Lookup.access = {"protected"};
          break;
        case 4:
          Lookup.access = {"public", "static"};
          break;
        case 5:
          Lookup.access.insert("abstract");
          Lookup.instructions.clear();
          Lookup.code_end = 0;
          Lookup.registers = 0;
          Input[1].access.insert("abstract");
          break;
        case 6: {
          auto Shadow = Lookup;
          Shadow.reference.owner = Input[2].name;
          Shadow.generic_signature = "(TP;)Lfixture/Cell<TP;TQ;>;";
          Shadow.access = {"private"};
          Input[2].methods.push_back(Shadow);
          break;
        }
        case 7:
          Input.erase(Input.begin() + 1);
          break;
        case 8:
          Lookup.declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
          break;
        }
        Budget B;
        rejected(
            [&] {
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            },
            "generic");
      }
}

std::vector<Class> deferredAbstractInterfaceClasses(bool External = false,
                                                    bool Duplicate = false) {
  auto Insert = method("insert", {"I", "Ljava/lang/Object;"}, "V", 0, {});
  Insert.access = {"public", "abstract"};
  Insert.generic_signature = "(ITP;)V";
  auto Value = method("value", {}, "Ljava/lang/Object;", 0, {});
  Value.access = {"public", "abstract"};
  Value.generic_signature = "()TP;";
  auto Contract = klass("Lfixture/Contract;", {Insert, Value});
  Contract.access = {"public", "abstract", "interface"};
  Contract.external = External;
  Contract.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Holder = klass("Lfixture/Holder;", {Init});
  Holder.access = {"public", "abstract"};
  Holder.interfaces = {Contract.name};
  Holder.generic_signature =
      "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Contract<TS;>;";
  std::vector<Class> Input{Contract, Holder};
  if (Duplicate) {
    auto Other = Contract;
    Other.name = "Lfixture/Other;";
    for (auto &M : Other.methods)
      M.reference.owner = Other.name;
    Input.push_back(Other);
    Input[1].interfaces.push_back(Other.name);
    *Input[1].generic_signature += "Lfixture/Other<TS;>;";
  }
  return Input;
}

