TEST(MobileDalvikJava,
     DeferredClosedExceptionsRequireCompleteScopesAndReceipts) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Link);
        SCOPED_TRACE(Mutation);
        auto Input = deferredAbstractInterfaceClasses(External, true);
        for (unsigned Index : {0u, 2u})
          Input[Index].methods[1].declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
        if (Mutation == 0)
          Input[0].methods[1].declared_throws =
              std::vector<std::string>{"Lfixture/UnknownFailure;"};
        else if (Mutation == 1) {
          auto Invalid = klass("Lfixture/NotThrowable;");
          Input[0].methods[1].declared_throws =
              std::vector<std::string>{Invalid.name};
          Input.push_back(Invalid);
        } else if (Mutation == 2)
          Input[0].methods[1].generic_signature =
              "<E:Ljava/lang/Exception;>()TP;^TE;";
        else if (Mutation == 3)
          Input[1].generic_signature =
              "<S:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
              "Lfixture/Contract<TS;>;Lfixture/Other<TV;>;";
        Budget B;
        if (Mutation == 4) {
          auto Classes = linkClasses(Input, B);
          auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plans.closed_declared_throws.erase(
              Input[0].methods[1].reference));
          EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                       std::runtime_error);
        } else
          EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                       std::runtime_error);
      }
}

