std::vector<Class> deferredClassAncestorInterfaces(bool External = false,
                                                   bool Provider = false) {
  auto Input = deferredAbstractInterfaceClasses(false, true);
  auto Init = Input[1].methods[0];
  auto Parent = klass("Lfixture/DeferredParent;", {Init});
  Parent.access = {"public", "abstract"};
  Parent.external = External;
  if (External) {
    Parent.methods[0].instructions.clear();
    Parent.methods[0].registers = 0;
    Parent.methods[0].code_end = 0;
  }
  Parent.generic_signature =
      "<L:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Provider) {
    auto Value = Input[0].methods[1];
    Value.reference.owner = Parent.name;
    Value.generic_signature = "()TR;";
    Parent.methods.push_back(Value);
  }
  Input[1].superclass = Parent.name;
  Input[1].generic_signature = "<S:Ljava/lang/Object;V:Ljava/lang/"
                               "Object;>Lfixture/DeferredParent<TV;TS;>;"
                               "Lfixture/Contract<TS;>;Lfixture/Other<TS;>;";
  Input[1].methods[0].instructions[0].reference =
      MethodRef{Parent.name, "<init>", {}, "V"};
  Input.push_back(Parent);
  return Input;
}

