std::vector<Class> closedGetterForwarderClasses(bool External, bool Final,
                                                bool ChildFirst) {
  auto Input = genericReferenceGetterClasses();
  auto &Api = Input[0], &Parent = Input[1];
  const std::string Signature = "()Lfixture/Box<Ljava/lang/Throwable;>;";
  Api.generic_signature.reset();
  Api.external = External;
  Api.methods[0].generic_signature = Signature;
  Parent.generic_signature.reset();
  Parent.interfaces.clear();
  Parent.methods[0].generic_signature.reset();
  Parent.methods[0].access = {"public", "bridge", "synthetic"};
  if (Final)
    Parent.methods[0].access.insert("final");
  Parent.methods[1].generic_signature = Signature;
  auto Contract = Api.methods[0];
  auto Init = Parent.methods[2];
  auto Base = klass("Lfixture/Base;", {Init, Contract});
  Base.access.insert("abstract");
  Base.external = External;
  if (External)
    for (auto &Member : Base.methods) {
      Member.instructions.clear();
      Member.registers = Member.code_end = 0;
    }
  Parent.superclass = Base.name;
  Parent.methods[2].instructions[0].reference = Base.methods[0].reference;
  Init.instructions[0].reference = Parent.methods[2].reference;
  auto Getter = Parent.methods[1];
  auto Child = klass(ChildFirst ? "Lfixture/AAChild;" : "Lfixture/ZZChild;",
                     {Init, Getter});
  Child.superclass = Parent.name;
  Child.interfaces = {Api.name};
  Input.push_back(Base);
  Input.push_back(Child);
  return Input;
}

