std::vector<Class> covariantGetterBridgeChainClasses(bool External = true) {
  auto Input = genericReferenceGetterClasses();
  Input[0].external = External;
  Input[2].access = {"public", "abstract", "interface"};
  auto Leaf = klass("Lfixture/Leaf;", {});
  Leaf.access = Input[2].access;
  Leaf.interfaces = {Input[2].name};
  Leaf.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Box<TP;>;";
  auto &Bridge = Input[1].methods[0], &Getter = Input[1].methods[1];
  for (auto *M : {&Bridge, &Getter}) {
    M->reference.returns = Leaf.name;
    M->generic_signature = "()Lfixture/Leaf<TT;>;";
  }
  Bridge.instructions[0].reference = Getter.reference;
  auto Erased = Bridge;
  Erased.reference.returns = Input[2].name;
  Erased.access = {"public", "bridge", "synthetic"};
  Erased.generic_signature.reset();
  Erased.instructions = {op(0, "invoke-virtual", {1}, {}, Bridge.reference),
                         op(1, "move-result-object", {0}),
                         op(2, "check-cast", {0}, {}, Input[2].name),
                         op(3, "return-object", {0})};
  Erased.code_end = 4;
  Input[1].methods.push_back(Erased);
  Input.push_back(Leaf);
  return Input;
}

