std::vector<Class> inheritedGetterBridgeClasses(bool Reference,
                                                bool ChildFirst = true) {
  auto Input =
      Reference ? genericReferenceGetterClasses() : plainIntegerBridgeClasses();
  auto &Parent = Input[1];
  Parent.name = ChildFirst ? "Lfixture/ZCounter;" : "Lfixture/ACounter;";
  for (auto &Method : Parent.methods) {
    Method.reference.owner = Parent.name;
    for (auto &Op : Method.instructions)
      if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
          Ref && Ref->name != "<init>")
        Ref->owner = Parent.name;
  }
  const auto Name = ChildFirst ? "Lfixture/AChild;" : "Lfixture/ZChild;";
  auto Getter = Parent.methods[1];
  Getter.reference.owner = Name;
  if (Reference)
    Getter.generic_signature = "()Lfixture/Box<TX;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{Parent.name, "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Child = klass(Name, {Getter, Init});
  Child.superclass = Parent.name;
  Child.interfaces = {Input[0].name};
  Child.generic_signature = "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>" +
                            Parent.name.substr(0, Parent.name.size() - 1) +
                            (Reference ? "<TX;TY;>;" : "<TX;>;") +
                            "Lfixture/CountView<TX;>;";
  Input.push_back(std::move(Child));
  return Input;
}

TEST(MobileDalvikJava, InheritedGetterBridgesRetainOriginalParentDeclarations) {
  for (bool Reference : {false, true})
    for (bool ChildFirst : {false, true})
      for (bool Link : {false, true}) {
        auto Input = inheritedGetterBridgeClasses(Reference, ChildFirst);
        Budget B;
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("method_count"), 5);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getString("status"), "partial");
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        const auto *Rows = R.getArray("methods");
        ASSERT_NE(Rows, nullptr);
        unsigned ParentBridges = 0, ChildMethods = 0;
        for (const auto &Value : *Rows) {
          const auto *Row = Value.getAsObject();
          ASSERT_NE(Row, nullptr);
          if (Row->getString("identity") ==
              Input[1].methods[0].reference.identity()) {
            ++ParentBridges;
            EXPECT_EQ(Row->getString("status"), "source-projected");
          }
          if (Row->getString("identity")
                  .value_or("")
                  .starts_with(Input.back().name + "->"))
            ++ChildMethods;
        }
        EXPECT_EQ(ParentBridges, 1u);
        // The child owns only its constructor and virtual getter override.
        EXPECT_EQ(ChildMethods, 2u);
      }
}

