std::vector<Class> indexedAbstractReferenceGetterAncestors(bool Source,
                                                           bool ExternalRoot,
                                                           bool FormalResult) {
  auto Input = inheritedGetterBridgeClasses(true);
  Input[0].external = !Source;
  auto &Parent = Input[1];
  Parent.access.insert("abstract");
  Parent.methods[1].access.insert("abstract");
  Parent.methods[1].instructions.clear();
  Parent.methods[1].registers = 0;
  Parent.methods[1].code_end = 0;
  for (auto &C : Input)
    for (auto &M : C.methods) {
      if (M.reference.name != "items" && M.reference.name != "getItems")
        continue;
      M.reference.parameters = {"I"};
      M.generic_signature = "(I)" + M.generic_signature->substr(2);
      if (FormalResult) {
        M.reference.returns = "Ljava/lang/Object;";
        M.generic_signature = C.name == Input[0].name ? "(I)TE;"
                              : C.name == Parent.name ? "(I)TT;"
                                                      : "(I)TX;";
      }
      if (!has(M.access, "abstract"))
        M.registers = 3;
    }
  Parent.methods[0].instructions[0].reference = Parent.methods[1].reference;
  Parent.methods[0].instructions[0].registers = {1, 2};
  auto Init = Parent.methods[2];
  auto Entry = Input[0].methods[0];
  Entry.access = {"public"};
  Entry.generic_signature = FormalResult ? "(I)TR;" : "(I)Lfixture/Box<TR;>;";
  Entry.instructions = {op(0, "const/4", {0}, int64_t(0)),
                        op(1, "return-object", {0})};
  Entry.registers = 3;
  Entry.code_end = 2;
  auto Root = klass("Lfixture/ReferenceRoot;", {Init, Entry});
  Root.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  Root.external = ExternalRoot;
  if (ExternalRoot)
    for (auto &M : Root.methods) {
      M.instructions.clear();
      M.registers = 0;
      M.code_end = 0;
    }
  Parent.superclass = Root.name;
  Parent.generic_signature =
      "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Lfixture/ReferenceRoot<TT;>;"
      "Lfixture/CountView<TT;>;";
  Parent.methods[2].instructions[0].reference = Root.methods[0].reference;
  Input.push_back(Root);
  return Input;
}

