TEST(MobileDalvikJava, RedundantClassDefaultsRejectChangedSlotsRootsAndScopes) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = redundantClassDefaultClasses();
      auto &Parent = Input[1], &Child = Input[2];
      switch (Mutation) {
      case 0:
        Child.generic_signature =
            "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>"
            "Lfixture/ZCounter<TX;>;Lfixture/CountView<TY;>;";
        break;
      case 1: {
        auto Other = Input[0];
        Other.name = "Lfixture/Other;";
        for (auto &Method : Other.methods)
          Method.reference.owner = Other.name;
        Parent.interfaces.push_back(Other.name);
        *Parent.generic_signature += "Lfixture/Other<TT;>;";
        Input.push_back(std::move(Other));
        break;
      }
      case 2:
        Parent.superclass = "Lfixture/Unknown;";
        Parent.generic_signature =
            "<T:Ljava/lang/Object;>Lfixture/Unknown;Lfixture/CountView<TT;>;";
        break;
      case 3:
      case 4: {
        auto Competing = Input[0].methods.back();
        Competing.reference.owner = Parent.name;
        Competing.access =
            Mutation == 3 ? Access{"public", "abstract"} : Access{"protected"};
        Competing.generic_signature = "(Ljava/lang/Object;TT;)TT;";
        if (Mutation == 3)
          Parent.access.insert("abstract");
        else {
          Competing.registers = 3;
          Competing.instructions = {op(0, "return-object", {2})};
          Competing.code_end = 1;
        }
        Parent.methods.push_back(std::move(Competing));
        break;
      }
      case 5:
        Parent.interfaces.push_back("Lfixture/Unknown;");
        *Parent.generic_signature += "Lfixture/Unknown;";
        break;
      case 6:
        Parent.generic_signature =
            "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/CountView;";
        break;
      }
      Budget B;
      rejected(
          [&] {
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          },
          "generic");
    }
}

std::vector<Class> capturedSiblingAncestorClasses(bool MethodFormal) {
  auto Input = capturedInnerClasses();
  auto &Outer = Input[0];
  Outer.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Parent = Input[1];
  Parent.inner_access = {"private"};
  Parent.access.clear();
  Parent.fields[0].generic_signature = "Lfixture/Outer<TT;>;";
  auto Read = method("hasNext", {}, "Z", 2,
                     {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  Read.access = {"public"};
  auto Next =
      method("next", {}, "Ljava/lang/Object;", 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Next.access = {"public"};
  Next.generic_signature = "()TT;";
  if (MethodFormal) {
    Next.reference.name = "echo";
    Next.reference.parameters = {"[Ljava/lang/Object;"};
    Next.reference.returns = "[Ljava/lang/Object;";
    Next.instructions = {op(0, "return-object", {1})};
    Next.code_end = 1;
    Next.generic_signature = "<T:Ljava/lang/Object;>([TT;)[TT;";
  }
  Parent.methods.push_back(Read);
  Parent.methods.push_back(Next);
  for (auto &M : Parent.methods)
    M.reference.owner = Parent.name;
  Read.instructions.clear();
  Read.registers = Read.code_end = 0;
  Read.access = {"public", "abstract"};
  Next.instructions.clear();
  Next.registers = Next.code_end = 0;
  Next.access = {"public", "abstract"};
  if (!MethodFormal)
    Next.generic_signature = "()TE;";
  auto Api = klass("Lfixture/Cursor;", {Read, Next});
  Api.access = {"public", "abstract", "interface"};
  Api.external = true;
  Api.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.interfaces = {Api.name};
  Parent.generic_signature = "Ljava/lang/Object;Lfixture/Cursor<TT;>;";
  auto Child = Parent;
  Child.name = "Lfixture/Outer$Child;";
  Child.inner_name = "Child";
  Child.superclass = Parent.name;
  Child.generic_signature = "Lfixture/Outer<TT;>.Member;Lfixture/Cursor<TT;>;";
  Child.methods.resize(1);
  Child.fields[0].reference.owner = Child.name;
  auto &Ctor = Child.methods[0];
  Ctor.reference.owner = Child.name;
  Ctor.registers = 3;
  Ctor.instructions = {
      op(0, "iput-object", {1, 0}, {}, Child.fields[0].reference),
      op(1, "invoke-direct", {0, 1, 2}, {}, Parent.methods[0].reference),
      op(2, "return-void")};
  Input.push_back(std::move(Child));
  Input.push_back(std::move(Api));
  return Input;
}

std::vector<Class> capturedSiblingConstructorClasses(bool External, bool Range,
                                                     bool Wide, bool Rename) {
  auto Input = capturedInnerClasses();
  auto &Outer = Input[0];
  auto &Parent = Input[1];
  const std::string First = Rename ? "Seed" : "T";
  const std::string Other = Rename ? "Other" : "U";
  const std::string Scalar = Wide ? "J" : "I";
  Outer.generic_signature = "<" + First + ":Ljava/lang/Object;" + Other +
                            ":Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.access = {"abstract"};
  Parent.inner_access = {"private", "abstract"};
  auto &BaseCtor = Parent.methods[0];
  BaseCtor.access = {"constructor"};
  BaseCtor.reference.parameters = {Outer.name, "Lfixture/Probe;", Scalar};
  BaseCtor.generic_signature =
      "(Lfixture/Probe<-T" + First + ";>;" + Scalar + ")V";
  BaseCtor.registers = Wide ? 5 : 4;
  auto Child = Parent;
  Child.name = "Lfixture/Outer$Child;";
  Child.inner_name = "Child";
  Child.access.clear();
  Child.inner_access = {"private", "final"};
  Child.superclass = Parent.name;
  Child.generic_signature =
      "Lfixture/Outer<T" + First + ";T" + Other + ";>.Member;";
  Child.fields[0].reference.owner = Child.name;
  auto &Ctor = Child.methods[0];
  Ctor.reference.owner = Child.name;
  std::vector<unsigned> Words;
  for (unsigned I = 0; I < Ctor.registers; ++I)
    Words.push_back(I);
  Ctor.instructions = {
      op(0, "iput-object", {1, 0}, {}, Child.fields[0].reference),
      op(1, Range ? "invoke-direct/range" : "invoke-direct", Words, {},
         BaseCtor.reference),
      op(2, "return-void")};
  auto Probe = klass("Lfixture/Probe;");
  Probe.access = {"public", "abstract", "interface"};
  Probe.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Probe.external = External;
  Input.push_back(std::move(Child));
  Input.push_back(std::move(Probe));
  return Input;
}

std::vector<Class> anchoredReifiableFactoryClasses(bool External, bool Range,
                                                   bool Rename, bool First,
                                                   bool OuterStar) {
  const std::string Formal = Rename ? "Seed" : "T";
  const std::string Token = "Lfixture/Token;", Context = "Lfixture/Context;",
                    Result = "Lfixture/Result;";
  const std::string Anchor = "Lfixture/Token<T" + Formal + ";>;";
  const std::string Auxiliary = OuterStar
                                    ? "Lfixture/Context<*>;"
                                    : "Lfixture/Context<+Lfixture/Leaf<*>;>;";
  const std::string Parameters =
      First ? Auxiliary + Anchor : Anchor + Auxiliary;
  auto Make = method(
      "make",
      First ? std::vector<std::string>{Context, Token}
            : std::vector<std::string>{Token, Context},
      Result, External ? 0 : 3,
      External ? std::vector<Instruction>{}
               : std::vector<Instruction>{op(0, "const/4", {0}, int64_t(0)),
                                          op(1, "return-object", {0})});
  Make.access = {"public", "static"};
  Make.generic_signature = "<" + Formal + ":Ljava/lang/Object;>(" + Parameters +
                           ")Lfixture/Result<T" + Formal + ";>;";
  Make.reference.owner = "Lfixture/Factory;";
  auto Factory = klass(Make.reference.owner, {Make});
  Factory.external = External;
  auto Call =
      method("call", Make.reference.parameters, Result, 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Make.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.access = {"public", "static"};
  if (Rename) {
    std::string CallerParameters = Parameters;
    const auto At = CallerParameters.find("TSeed;");
    CallerParameters.replace(At, 6, "TCaller;");
    Call.generic_signature = "<Caller:Ljava/lang/Object;>(" + CallerParameters +
                             ")Lfixture/Result<TCaller;>;";
  }
  std::vector<Class> Input{Factory, klass("Lfixture/Core;", {Call})};
  for (const auto &Name :
       std::vector<std::string>{Token, Context, "Lfixture/Leaf;", Result}) {
    auto Contract = klass(Name);
    Contract.access = {"public", "abstract", "interface"};
    Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    Contract.external = External;
    Input.push_back(std::move(Contract));
  }
  return Input;
}

TEST(MobileDalvikJava,
     AnchoredReifiableFactoriesKeepCompleteInputAndResultScopes) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Rename : {false, true})
        for (bool First : {false, true})
          for (bool OuterStar : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              auto Input = anchoredReifiableFactoryClasses(
                  External, Range, Rename, First, OuterStar);
              const auto Target = Input[0].methods[0].reference;
              Budget B;
              const auto Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.erased_generic_invocations.contains(Target));
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_EQ(R.getString("status"), "recovered");
            }
}

TEST(MobileDalvikJava,
     AnchoredReifiableFactoriesRejectUnprovedTreesAndBindings) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input =
          anchoredReifiableFactoryClasses(false, false, false, false, false);
      auto &Factory = Input[0];
      auto &Make = Factory.methods[0];
      switch (Mutation) {
      case 0:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Token<*>;Lfixture/"
            "Context<+Lfixture/Leaf<*>;>;)Lfixture/Result<TT;>;";
        break;
      case 1:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Token<+TT;>;Lfixture/"
            "Context<+Lfixture/Leaf<*>;>;)Lfixture/Result<TT;>;";
        break;
      case 2:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Token<-TT;>;Lfixture/"
            "Context<+Lfixture/Leaf<*>;>;)Lfixture/Result<TT;>;";
        break;
      case 3:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Token<TT;>;Lfixture/"
            "Context<+Lfixture/Leaf<*>;>;)Lfixture/Result<+TT;>;";
        break;
      case 4:
        Make.generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>(Lfixture/"
            "Token<TT;>;Lfixture/Context<+Lfixture/Leaf<*>;>;)Lfixture/"
            "Result<TT;>;";
        break;
      case 5:
        Make.generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>(Lfixture/"
            "Token<TT;>;Lfixture/Context<+Lfixture/Leaf<*>;>;)Lfixture/"
            "Result<TU;>;";
        break;
      case 6:
        Input[4].generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
        Input.push_back(klass("Ljava/lang/Number;"));
        Input.back().external = true;
        break;
      case 7:
        Input.erase(Input.begin() + 4);
        break;
      case 8:
        Factory.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 9:
        Make.access.insert("varargs");
        break;
      case 10:
        Make.access.erase("public");
        Make.access.insert("private");
        break;
      case 11:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Token<TT;>;Lfixture/"
            "Context<+Lfixture/Leaf<*>;>;)Lfixture/Result;";
        break;
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> privateSeededCarrierClasses(bool External, bool Range,
                                               bool Rename, bool StaticCaller) {
  const std::string Formal = Rename ? "Seed" : "T";
  const std::string CarrierName = "Lfixture/Carrier;";
  auto Make = method(
      "make", {"Ljava/lang/String;", "Z", "Ljava/lang/Object;"}, CarrierName, 5,
      {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.access = {"private", "final"};
  Make.generic_signature = "<" + Formal +
                           ":Ljava/lang/Object;>(Ljava/lang/String;ZT" +
                           Formal + ";)Lfixture/Carrier<T" + Formal + ";>;";
  Make.reference.owner = "Lfixture/Core;";
  auto Call =
      method("call", Make.reference.parameters, CarrierName, 5,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                 {1, 2, 3, 4}, {}, Make.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.access = {"public"};
  if (StaticCaller) {
    Call.access.insert("static");
    Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                     Make.reference.owner);
    Call.generic_signature =
        "<Result:Ljava/lang/Object;>(Lfixture/Core;Ljava/lang/String;Z"
        "Ljava/lang/Object;)Lfixture/Carrier<TResult;>;";
  }
  auto Core = klass(Make.reference.owner, {Make, Call});
  const FieldRef Value{"Lfixture/Base;", "value", "Ljava/lang/Object;"};
  auto BaseCtor = method(
      "<init>", {"Ljava/lang/Object;"}, "V", External ? 0 : 2,
      External
          ? std::vector<Instruction>{}
          : std::vector<Instruction>{
                op(0, "invoke-direct", {0}, {},
                   MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                op(1, "iput-object", {1, 0}, {}, Value), op(2, "return-void")});
  BaseCtor.access = {"public", "constructor"};
  BaseCtor.generic_signature = "(TA;)V";
  BaseCtor.reference.owner = Value.owner;
  auto Base = klass(Value.owner, {BaseCtor});
  Base.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.fields = {{Value, {"public"}, {}}};
  Base.fields[0].generic_signature = "TA;";
  Base.external = External;
  auto CarrierCtor =
      method("<init>", {"Ljava/lang/Object;"}, "V", External ? 0 : 2,
             External ? std::vector<Instruction>{}
                      : std::vector<Instruction>{op(0, "invoke-direct", {0, 1},
                                                    {}, BaseCtor.reference),
                                                 op(1, "return-void")});
  CarrierCtor.access = {"public", "constructor"};
  CarrierCtor.generic_signature = "(TE;)V";
  auto Carrier = klass(CarrierName, {CarrierCtor});
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Lfixture/Base<TE;>;";
  Carrier.superclass = Base.name;
  Carrier.external = External;
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  return {Core, Base, Carrier, String};
}

TEST(MobileDalvikJava, PrivateSeededCarriersRetainCompleteOwnSeedAndResult) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Rename : {false, true})
        for (bool StaticCaller : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            auto Input = privateSeededCarrierClasses(External, Range, Rename,
                                                     StaticCaller);
            const auto Target = Input[0].methods[0].reference;
            const auto Signature = Input[0].methods[0].generic_signature;
            Budget B;
            const auto Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plans.erased_generic_invocations.contains(Target));
            EXPECT_EQ(Classes.at(Target.owner).methods[0].generic_signature,
                      Signature);
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            const auto R =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getString("status"), "recovered");
          }
}

TEST(MobileDalvikJava, PrivateSeededCarriersRejectLostScopeBoundsAndAccess) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = privateSeededCarrierClasses(true, false, false, false);
      auto &Core = Input[0];
      auto &Make = Core.methods[0];
      switch (Mutation) {
      case 0:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Ljava/lang/String;ZLjava/lang/"
            "Object;)Lfixture/Carrier<TT;>;";
        break;
      case 1:
        Make.generic_signature =
            "<T:Ljava/lang/Object;U:Ljava/lang/Object;>(Ljava/lang/"
            "String;ZTT;)Lfixture/Carrier<TU;>;";
        break;
      case 2:
        Make.generic_signature = "<T:Ljava/lang/Object;>(Ljava/lang/"
                                 "String;ZTT;)Lfixture/Carrier<+TT;>;";
        break;
      case 3:
        Make.generic_signature =
            "<T:Ljava/lang/Object;>(Ljava/lang/String;ZTT;)Lfixture/Carrier;";
        break;
      case 4:
        Make.generic_signature = "<T:Ljava/lang/Object;>(Ljava/lang/"
                                 "String;Z[TT;)Lfixture/Carrier<TT;>;";
        break;
      case 5:
        Input[2].generic_signature =
            "<E:Ljava/lang/CharSequence;>Lfixture/Base<TE;>;";
        break;
      case 6:
        Input[2].generic_signature.reset();
        break;
      case 7:
        Make.access.insert("synthetic");
        break;
      case 8:
        Make.access.insert("static");
        break;
      case 9:
        Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 10: {
        auto Foreign = Core.methods[1];
        Core.methods.pop_back();
        Foreign.reference.parameters.insert(
            Foreign.reference.parameters.begin(), Core.name);
        Foreign.access.insert("static");
        Input.push_back(klass("Lother/Foreign;", {Foreign}));
        break;
      }
      case 11:
        Make.access.insert("varargs");
        break;
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> capturedConstructorSubsetClasses(bool External, bool Range,
                                                    bool Wide, bool Rename,
                                                    bool Before) {
  auto Input = capturedSiblingConstructorClasses(External, Range, Wide, Rename);
  auto &Child = Input[2];
  auto &Ctor = Child.methods[0];
  const size_t Index = Before ? 1 : Ctor.reference.parameters.size();
  Ctor.reference.parameters.insert(Ctor.reference.parameters.begin() + Index,
                                   "Ljava/lang/Object;");
  auto &Signature = *Ctor.generic_signature;
  Signature.insert(Before ? 1 : Signature.find(')'), "Ljava/lang/Object;");
  ++Ctor.registers;
  if (Before)
    for (auto &Reg : Ctor.instructions[1].registers)
      if (Reg >= 2)
        ++Reg;
  FieldRef Context{Child.name, "context", "Ljava/lang/Object;"};
  Child.fields.push_back({Context, {"final"}, {}});
  Ctor.instructions[2] =
      op(2, "iput-object", {Before ? 2u : Ctor.registers - 1, 0}, {}, Context);
  Ctor.instructions.push_back(op(3, "return-void"));
  Ctor.code_end = 4;
  return Input;
}

TEST(MobileDalvikJava,
     CapturedConstructorSubsetsKeepCompleteScopesAndIncomingOrigins) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Wide : {false, true})
        for (bool Rename : {false, true})
          for (bool Before : {false, true}) {
            if (Range && Before)
              continue;
            for (unsigned Route = 0; Route < 3; ++Route) {
              auto Input = capturedConstructorSubsetClasses(
                  External, Range, Wide, Rename, Before);
              const auto Caller = Input[2].methods[0].reference;
              const auto Target = Input[1].methods[0].reference;
              Budget B;
              const auto Plans =
                  validateGenericSignatures(linkClasses(Input, B), B);
              ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
              EXPECT_EQ(
                  Plans.superclass_calls.at({Caller, Target}).parameters.size(),
                  3u);
              EXPECT_EQ(Plans.parameter_indices.at(Caller),
                        (std::vector<size_t>{1, 2, 3}));
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
            }
          }
}

TEST(MobileDalvikJava,
     CapturedConstructorSubsetsRejectScopeAndPhysicalWordDrift) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input =
          capturedConstructorSubsetClasses(true, false, true, false, true);
      auto &Child = Input[2];
      auto &Ctor = Child.methods[0];
      auto &Call = Ctor.instructions[1];
      switch (Mutation) {
      case 0:
        Ctor.generic_signature = "(Ljava/lang/Object;Lfixture/Probe<-TU;>;J)V";
        break;
      case 1:
        Call.registers[2] = 2;
        break;
      case 2:
        Call.registers[1] = 2;
        break;
      case 3:
        Call.registers[4] = 4;
        break;
      case 4:
        Call.registers[0] = 2;
        break;
      case 5:
        Ctor.generic_signature = "(Ljava/lang/Object;Lfixture/Probe<+TT;>;J)V";
        break;
      case 6:
        Ctor.reference.parameters[1] = "Lfixture/Probe;";
        Ctor.generic_signature =
            "(Lfixture/Probe<-TU;>;Lfixture/Probe<-TT;>;J)V";
        Child.fields.back().reference.type = "Lfixture/Probe;";
        Ctor.instructions[2].reference = Child.fields.back().reference;
        Call.registers[2] = 2;
        break;
      case 7:
        Call.opcode = "invoke-direct/range";
        break;
      case 8:
        Input[1].methods[0].access.insert("varargs");
        break;
      case 9:
        Ctor.generic_signature =
            "<T:Ljava/lang/Object;>(Ljava/lang/Object;Lfixture/Probe<-TT;>;J)V";
        break;
      case 10:
        Ctor.instructions[0].registers[0] = 2;
        break;
      case 11:
        Call.registers.push_back(5);
        break;
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

