TEST(MobileDalvikJava,
     CapturedSiblingConstructorsRejectCollapsedScopesAndUnprovedCalls) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = capturedSiblingConstructorClasses(true, true, true, false);
      auto &Parent = Input[1];
      auto &Child = Input[2];
      auto &Ctor = Child.methods[0];
      switch (Mutation) {
      case 0:
        Ctor.generic_signature = "(Lfixture/Probe<-TU;>;J)V";
        break;
      case 1:
        Ctor.generic_signature = "(Lfixture/Probe<+TT;>;J)V";
        break;
      case 2:
        Ctor.generic_signature = "(Lfixture/Probe<TT;>;J)V";
        break;
      case 3:
        Parent.methods[0].generic_signature = "(Lfixture/Probe<-TU;>;J)V";
        break;
      case 4:
        Child.generic_signature = "Lfixture/Outer<TU;TT;>.Member;";
        break;
      case 5:
        Child.generic_signature =
            "Lfixture/Outer<Ljava/lang/Object;TU;>.Member;";
        break;
      case 6:
        Ctor.generic_signature.reset();
        break;
      case 7:
        Parent.methods[0].generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Probe<-TT;>;J)V";
        break;
      case 8:
        Parent.methods[0].access.insert("varargs");
        break;
      case 9: {
        auto Competing = Parent.methods[0];
        Competing.reference.parameters[1] = "Ljava/lang/Object;";
        Competing.generic_signature = "(Ljava/lang/Object;J)V";
        Parent.methods.push_back(std::move(Competing));
        break;
      }
      case 10:
        std::get<FieldRef>(Ctor.instructions[0].reference).owner = Parent.name;
        break;
      case 11:
        Ctor.instructions[0].registers[0] = 2;
        break;
      case 12:
        std::swap(Ctor.instructions[1].registers[1],
                  Ctor.instructions[1].registers[2]);
        break;
      case 13:
        Ctor.instructions[1].registers[4] = 3;
        break;
      case 14:
        std::get<MethodRef>(Ctor.instructions[1].reference).owner =
            Input[0].name;
        break;
      case 15:
        Parent.fields[0].access.erase("synthetic");
        break;
      case 16:
        Child.fields[0].access.erase("final");
        break;
      case 17:
        Parent.methods[0].declared_throws =
            std::vector<std::string>{"Ljava/lang/RuntimeException;"};
        break;
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

