TEST(MobileDalvikJava,
     CapturedSiblingDefaultsRejectCompetingSlotsAndIncompleteBindings) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
        auto Input = capturedSiblingDefaultClasses(External);
        auto &Parent = Input[1];
        auto &Child = Input[2];
        auto &Api = Input[3];
        if (Mutation < 3) {
          auto Slot = Api.methods.back();
          Slot.reference.owner = Parent.name;
          Slot.generic_signature = "([TT;)[TT;";
          Slot.access = Mutation == 0   ? Access{"public", "static"}
                        : Mutation == 1 ? Access{"private"}
                                        : Access{"public", "abstract"};
          if (Mutation == 2) {
            Parent.access.insert("abstract");
            Slot.instructions.clear();
            Slot.registers = Slot.code_end = 0;
          } else {
            Slot.registers = 2;
            Slot.instructions = {op(0, "return-object", {1})};
            Slot.code_end = 1;
          }
          Parent.methods.push_back(Slot);
        } else if (Mutation == 3) {
          auto Other = Api;
          Other.name = "Lfixture/OtherDefault;";
          for (auto &M : Other.methods)
            M.reference.owner = Other.name;
          Child.interfaces.push_back(Other.name);
          *Child.generic_signature += "Lfixture/OtherDefault<TT;>;";
          Input.push_back(Other);
        } else if (Mutation == 4) {
          auto Override = Api;
          Override.name = "Lfixture/AbstractDefault;";
          Override.interfaces = {Api.name};
          Override.generic_signature =
              "<E:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Cursor<TE;>;";
          Override.methods = {Api.methods.back()};
          Override.methods[0].reference.owner = Override.name;
          Override.methods[0].access.insert("abstract");
          Override.methods[0].instructions.clear();
          Override.methods[0].registers = Override.methods[0].code_end = 0;
          Child.interfaces = {Override.name};
          Child.generic_signature =
              "Lfixture/Outer<TT;>.Member;Lfixture/AbstractDefault<TT;>;";
          Input.push_back(Override);
        } else if (Mutation == 5)
          Child.generic_signature =
              "Lfixture/Outer<Ljava/lang/Object;>.Member;Lfixture/Cursor<TT;>;";
        else if (Mutation == 6)
          Child.generic_signature =
              "Lfixture/Outer.Member;Lfixture/Cursor<TT;>;";
        else if (Mutation == 7)
          Parent.generic_signature =
              "Ljava/lang/Object;Lfixture/Cursor<Ljava/lang/String;>;";
        else if (Mutation == 8) {
          auto Slot = Api.methods.back();
          Slot.reference.owner = Parent.name;
          Slot.generic_signature = "<R:Ljava/lang/Object;>([TR;)[TR;";
          Slot.registers = 2;
          Slot.instructions = {op(0, "return-object", {1})};
          Slot.code_end = 1;
          Parent.methods.push_back(Slot);
        } else
          Child.methods[0].instructions[0] = op(0, "nop");
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error)
            << "Mutation " << Mutation;
      }
}

std::vector<Class> capturedPlainAncestorClasses(bool MethodFormal) {
  auto Input = capturedInnerClasses();
  Input[0].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Read = MethodFormal ? method("echo", {"[Ljava/lang/Object;"},
                                    "[Ljava/lang/Object;", 0, {})
                           : method("isEmpty", {}, "Z", 0, {});
  Read.access = {"public", "abstract"};
  if (MethodFormal)
    Read.generic_signature = "<M:Ljava/lang/Object;>([TM;)[TM;";
  auto Contract = klass("Lfixture/Contract;", {Read});
  Contract.external = true;
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 0, {});
  Init.access = {"public", "constructor"};
  Read.access = {"public"};
  auto Root = klass("Lfixture/CapturedRoot;", {Init, Read});
  Root.external = true;
  Root.interfaces = {Contract.name};
  Root.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Contract<TR;>;";
  auto Middle = klass("Lfixture/CapturedMiddle;", {Init});
  Middle.external = true;
  Middle.superclass = Root.name;
  Middle.generic_signature =
      "<N:Ljava/lang/Object;>Lfixture/CapturedRoot<TN;>;";
  Input[1].superclass = Middle.name;
  Input[1].generic_signature = "Lfixture/CapturedMiddle<TT;>;";
  Input[1].methods[0].instructions[1].reference = Middle.methods[0].reference;
  Input.push_back(Contract);
  Input.push_back(Root);
  Input.push_back(Middle);
  return Input;
}

