std::vector<Class> guardedReferenceBridgeClasses(bool ChildFirst = true,
                                                 bool Synthetic = false,
                                                 bool PositiveFirst = false,
                                                 bool CopyArgument = true,
                                                 bool PredicateGuard = false) {
  auto Contains = method("contains", {"Ljava/lang/Object;"}, "Z", 0, {});
  Contains.access = {"public", "abstract"};
  auto Contract = klass("Lfixture/CountView;", {Contains});
  Contract.access = {"public", "abstract", "interface"};
  Contract.external = true;
  Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Element = klass("Lfixture/Element;", {Init});
  Element.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  const auto Name = ChildFirst ? "Lfixture/ACounter;" : "Lfixture/ZCounter;";
  auto Typed =
      method("contains", {Element.name}, "Z", 3,
             {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = Name;
  Typed.generic_signature = "(Lfixture/Element<TT;>;)Z";
  Contains.access = {"public", "final", "bridge"};
  if (Synthetic)
    Contains.access.insert("synthetic");
  Contains.registers = 3;
  Contains.instructions = {op(0, "instance-of", {0, 2}, {}, Element.name),
                           op(1, PositiveFirst ? "if-eqz" : "if-nez", {0})};
  auto Predicate =
      klass("Lfixture/Probe;",
            {method("accept", {"Ljava/lang/Object;"}, "Z", 0, {})});
  Predicate.external = true;
  const size_t Branch = PredicateGuard ? 2 : 1;
  if (PredicateGuard)
    Contains.instructions = {
        op(0, "invoke-static", {2}, {}, Predicate.methods[0].reference),
        op(1, "move-result", {0}),
        op(2, PositiveFirst ? "if-eqz" : "if-nez", {0})};
  const std::vector<Instruction> Negative{op(0, "const/4", {0}, int64_t(0)),
                                          op(0, "return", {0})};
  std::vector<Instruction> Positive;
  if (CopyArgument)
    Positive.push_back(op(0, "move-object", {0, 2}));
  const unsigned Checked = CopyArgument ? 0 : 2;
  Positive.push_back(op(0, "check-cast", {Checked}, {}, Element.name));
  Positive.push_back(
      op(0, "invoke-virtual", {1, Checked}, {}, Typed.reference));
  Positive.push_back(op(0, "move-result", {0}));
  Positive.push_back(op(0, "return", {0}));
  const auto Append = [&](const std::vector<Instruction> &Path) {
    Contains.instructions.insert(Contains.instructions.end(), Path.begin(),
                                 Path.end());
  };
  Append(PositiveFirst ? Positive : Negative);
  Contains.instructions[Branch].target = Contains.instructions.size();
  Append(PositiveFirst ? Negative : Positive);
  for (size_t I = 0; I < Contains.instructions.size(); ++I)
    Contains.instructions[I].pc = I;
  Contains.code_end = Contains.instructions.size();
  auto Counter = klass(Name, {Contains, Typed, Init});
  Counter.interfaces = {Contract.name};
  Counter.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/CountView<TT;>;";
  return {Contract, Counter, Element, Predicate};
}

std::vector<Class> guardedIntegerBridgeClasses(bool PositiveFirst = false,
                                               bool CopyArgument = true) {
  auto Input =
      guardedReferenceBridgeClasses(true, false, PositiveFirst, CopyArgument);
  Input[0].methods[0].reference.name = "indexOf";
  Input[0].methods[0].reference.returns = "I";
  for (size_t I = 0; I < 2; ++I) {
    auto &M = Input[1].methods[I];
    M.reference.name = "indexOf";
    M.reference.returns = "I";
    if (M.generic_signature)
      M.generic_signature = "(Lfixture/Element<TT;>;)I";
    for (auto &Op : M.instructions) {
      if (auto *Call = std::get_if<MethodRef>(&Op.reference)) {
        Call->name = "indexOf";
        Call->returns = "I";
      }
      if (I == 0 && std::holds_alternative<int64_t>(Op.literal))
        Op.literal = int64_t(-1);
    }
  }
  return Input;
}

std::vector<Class> capturedGuardedScalarClasses(bool Integer,
                                                bool PositiveFirst,
                                                bool CopyArgument) {
  auto Input = Integer
                   ? guardedIntegerBridgeClasses(PositiveFirst, CopyArgument)
                   : guardedReferenceBridgeClasses(true, true, PositiveFirst,
                                                   CopyArgument);
  auto &Counter = Input[1];
  const auto Original = Counter.name;
  auto Outer = klass("Lfixture/Outer;");
  Counter.name = "Lfixture/Outer$Counter;";
  Counter.enclosing = Outer.name;
  Counter.inner_class_present = true;
  Counter.inner_name = "Counter";
  Counter.inner_access = {"public"};
  for (auto &M : Counter.methods) {
    M.reference.owner = Counter.name;
    for (auto &Op : M.instructions)
      if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
          Ref && Ref->owner == Original)
        Ref->owner = Counter.name;
  }
  FieldRef Capture{Counter.name, "enclosure", Outer.name};
  Counter.fields.push_back({Capture, {"final", "synthetic"}, {}});
  auto &Init = Counter.methods[2];
  Init.reference.parameters = {Outer.name};
  Init.registers = 2;
  Init.instructions = {op(0, "iput-object", {1, 0}, {}, Capture),
                       op(1, "invoke-direct", {0}, {},
                          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                       op(2, "return-void")};
  Init.code_end = 3;
  Input.push_back(Outer);
  return Input;
}

