std::vector<Class> guardedClassAncestorBridgeClasses(bool ExternalRoot,
                                                     bool Integer) {
  auto Input =
      Integer ? guardedIntegerBridgeClasses() : guardedReferenceBridgeClasses();
  auto Init = Input[1].methods[2];
  auto Contains = Input[0].methods[0];
  Contains.access = {"public"};
  Contains.registers = 3;
  Contains.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return", {0})};
  Contains.code_end = 2;
  auto Root = klass("Lfixture/GuardRoot;", {Init, Contains});
  Root.interfaces = {Input[0].name};
  Root.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/CountView<TR;>;";
  Root.external = ExternalRoot;
  if (ExternalRoot)
    for (auto &M : Root.methods) {
      M.instructions.clear();
      M.registers = 0;
      M.code_end = 0;
    }
  Init.instructions[0].reference = Root.methods[0].reference;
  auto Middle = klass("Lfixture/GuardMiddle;", {Init});
  Middle.superclass = Root.name;
  Middle.generic_signature = "<M:Ljava/lang/Object;>Lfixture/GuardRoot<TM;>;";
  Input[1].superclass = Middle.name;
  Input[1].generic_signature = "<T:Ljava/lang/Object;>Lfixture/"
                               "GuardMiddle<TT;>;Lfixture/CountView<TT;>;";
  Input[1].methods[2].instructions[0].reference = Middle.methods[0].reference;
  Input.push_back(Root);
  Input.push_back(Middle);
  return Input;
}

