std::vector<Class> rawMarkerSuperclassClasses(bool ExternalRoot) {
  auto Marker = klass("Lfixture/Marker;");
  Marker.external = true;
  Marker.access = {"public", "abstract", "interface"};
  Marker.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Arity = method("arity", {}, "I", 0, {});
  Arity.access = {"public", "abstract"};
  auto ArityView = klass("Lfixture/ArityView;", {Arity});
  ArityView.external = true;
  ArityView.access = Marker.access;
  ArityView.interfaces = {Marker.name};
  ArityView.generic_signature =
      "<A:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Marker<TA;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto ArityBody =
      method("arity", {}, "I", 2,
             {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  ArityBody.access = {"public"};
  auto Root = klass("Lfixture/Root;", {Init, ArityBody});
  Root.external = ExternalRoot;
  Root.interfaces = {ArityView.name};
  Root.generic_signature =
      "<P:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/ArityView<TP;>;";
  auto Get = method("get", {}, "Ljava/lang/Object;", 0, {});
  Get.access = {"public", "abstract"};
  Get.generic_signature = "()TT;";
  auto Factory = klass("Lfixture/Factory;", {Get});
  Factory.external = true;
  Factory.access = Marker.access;
  Factory.interfaces = {Marker.name};
  Factory.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Marker<TT;>;";
  Init.instructions[0].reference = Root.methods[0].reference;
  auto Typed = method("get", {}, "Ljava/lang/String;", 2,
                      {op(0, "const-string", {0}, std::string("owned")),
                       op(1, "return-object", {0})});
  Typed.access = {"public"};
  auto Bridge = method(
      "get", {}, "Ljava/lang/Object;", 2,
      {op(0, "invoke-virtual", {1}, {},
          MethodRef{"Lfixture/Consumer;", "get", {}, "Ljava/lang/String;"}),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Consumer = klass("Lfixture/Consumer;", {Init, Typed, Bridge});
  Consumer.superclass = Root.name;
  Consumer.interfaces = {Factory.name};
  Consumer.generic_signature =
      "Lfixture/Root;Lfixture/Factory<Ljava/lang/String;>;";
  if (ExternalRoot)
    for (auto &M : Root.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  return {Marker, ArityView, Root, Factory, Consumer};
}

