std::vector<Class> anonymousGuardedSuperClasses(bool External, bool Integer,
                                                bool Static) {
  auto Input = scalarSuperAdapterClasses(External, Integer);
  auto &Child = Input[1];
  const auto Old = Child.name;
  Child.name = "Lfixture/GuardHost$1;";
  Child.access = {"public", "final"};
  Child.inner_class_present = true;
  Child.inner_access = {"final"};
  Child.generic_signature = "Lfixture/GuardMiddle<Ljava/lang/String;>;Lfixture/"
                            "CountView<Ljava/lang/String;>;";
  for (auto &M : Child.methods) {
    M.reference.owner = Child.name;
    if (M.generic_signature) {
      auto &Text = *M.generic_signature;
      for (size_t At = 0; (At = Text.find("TT;", At)) != std::string::npos;)
        Text.replace(At, 3, "Ljava/lang/String;");
    }
    for (auto &I : M.instructions)
      if (auto *Call = std::get_if<MethodRef>(&I.reference);
          Call && Call->owner == Old)
        Call->owner = Child.name;
  }
  const std::string HostName = "Lfixture/GuardHost;";
  const FieldRef Capture{Child.name, "outer", HostName};
  Child.fields.push_back({Capture, {"final", "synthetic"}, {}});
  auto &Init = Child.methods[2];
  const auto Super = std::get<MethodRef>(Init.instructions[0].reference);
  Init.access = {"constructor"};
  Init.reference.parameters = {HostName};
  Init.registers = 2;
  Init.instructions = {op(0, "iput-object", {1, 0}, {}, Capture),
                       op(2, "invoke-direct", {0}, {}, Super),
                       op(5, "return-void")};
  Init.code_end = 6;
  auto Make = method("make",
                     Static ? std::vector<std::string>{HostName}
                            : std::vector<std::string>{},
                     Input[0].name, 2,
                     {op(0, "new-instance", {0}, {}, Child.name),
                      op(2, "invoke-direct", {0, 1}, {}, Init.reference),
                      op(5, "return-object", {0})});
  Make.access = {"public"};
  if (Static)
    Make.access.insert("static");
  Make.generic_signature =
      Static ? "(Lfixture/GuardHost;)Lfixture/CountView<Ljava/lang/String;>;"
             : "()Lfixture/CountView<Ljava/lang/String;>;";
  auto Host = klass(HostName, {Make});
  Child.enclosing_method = Host.methods[0].reference;
  Input.push_back(Host);
  return Input;
}

