std::vector<Class> checkedReferenceSuperAdapterClasses(bool ExternalRoot) {
  auto Input = scalarSuperAdapterClasses(ExternalRoot, false);
  const std::string HolderName = "Lfixture/Holder;";
  const std::string HolderType = "Lfixture/Holder<TT;>;";
  auto Holder = klass(HolderName);
  Holder.external = true;
  Holder.generic_signature = "<H:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Api = Input[0].methods[0];
  Api.reference.name = "get";
  Api.reference.returns = "Ljava/lang/Object;";
  Api.generic_signature = "(Ljava/lang/Object;)TE;";
  auto &Root = Input[4].methods[1];
  Root.reference.name = "get";
  Root.reference.returns = "Ljava/lang/Object;";
  Root.generic_signature = "(Ljava/lang/Object;)TR;";
  if (!ExternalRoot) {
    Root.instructions[1].opcode = "return-object";
  }
  Input[1].generic_signature = "<T:Ljava/lang/Object;>Lfixture/GuardMiddle<" +
                               HolderType + ">;Lfixture/CountView<" +
                               HolderType + ">;";
  auto &Typed = Input[1].methods[1];
  Typed.reference.name = "get";
  Typed.reference.returns = HolderName;
  Typed.generic_signature = "(Lfixture/Element<TT;>;)" + HolderType;
  Typed.instructions = {op(0, "invoke-super", {1, 2}, {},
                           MethodRef{Input[5].name,
                                     "get",
                                     {"Ljava/lang/Object;"},
                                     "Ljava/lang/Object;"}),
                        op(1, "move-result-object", {0}),
                        op(2, "check-cast", {0}, {}, HolderName),
                        op(3, "return-object", {0})};
  Typed.code_end = 4;
  auto &Guard = Input[1].methods[0];
  Guard.reference.name = "get";
  Guard.reference.returns = HolderName;
  Guard.generic_signature = "(Ljava/lang/Object;)" + HolderType;
  for (auto &I : Guard.instructions) {
    if (I.opcode == "return")
      I.opcode = "return-object";
    if (I.opcode == "move-result")
      I.opcode = "move-result-object";
    if (auto *Call = std::get_if<MethodRef>(&I.reference))
      *Call = Typed.reference;
  }
  auto Erased = Guard;
  Erased.reference.returns = "Ljava/lang/Object;";
  Erased.access.insert("synthetic");
  Erased.generic_signature.reset();
  Input[1].methods.push_back(Erased);
  Input.push_back(Holder);
  return Input;
}

