std::vector<Class> classFormalImplementationBridgeClasses(bool External,
                                                          bool Bounded) {
  const std::string Descriptor =
      Bounded ? "Ljava/lang/Comparable;" : "Ljava/lang/Object;";
  const std::string BoundT =
      Bounded ? ":Ljava/lang/Comparable<-TT;>;" : "Ljava/lang/Object;";
  const std::string BoundU =
      Bounded ? ":Ljava/lang/Comparable<-TU;>;" : "Ljava/lang/Object;";
  const std::string BoundV =
      Bounded ? ":Ljava/lang/Comparable<-TV;>;" : "Ljava/lang/Object;";
  auto Check = method("contains", {Descriptor}, "Z", 0, {});
  Check.access = {"public", "abstract"};
  Check.generic_signature = "(TT;)Z";
  auto Api = klass("Lfixture/ScopedApi;", {Check});
  Api.access = {"public", "abstract", "interface"};
  Api.external = External;
  Api.generic_signature = "<T:" + BoundT + ">Ljava/lang/Object;";
  Check.access = {"public", "bridge"};
  Check.generic_signature = "(TU;)Z";
  Check.registers = 3;
  Check.instructions = {op(0, "const/4", {0}, int64_t{1}),
                        op(1, "return", {0})};
  Check.code_end = 2;
  auto Core = klass("Lfixture/ScopedCore;", {Check});
  Core.generic_signature = "<U:" + BoundU + "V:" + BoundV +
                           ">Ljava/lang/Object;Lfixture/ScopedApi<TU;>;";
  Core.interfaces = {Api.name};
  return {Core, Api};
}

