std::vector<Class> classFormalStaticPredicateClasses(bool External) {
  auto Input = classFormalImplementationBridgeClasses(External, true);
  Input.push_back(recursiveMethodSharedAnonymousClasses().back());
  auto Contains =
      method("contains", {Input[1].name, "Ljava/lang/Comparable;"}, "Z", 3,
             {op(0, "const/4", {0}, int64_t{1}), op(1, "return", {0})});
  Contains.access = {"public", "static"};
  Contains.generic_signature =
      "<K::Ljava/lang/Comparable<-TK;>;>(Lfixture/ScopedApi<TK;>;TK;)Z";
  auto Empty =
      method("empty", {Input[1].name}, "Z", 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return", {0})});
  Empty.access = Contains.access;
  Empty.generic_signature =
      "<K::Ljava/lang/Comparable<-TK;>;>(Lfixture/ScopedApi<TK;>;)Z";
  auto Dispatch = klass("Lfixture/ScopedDispatch;", {Contains, Empty});
  Dispatch.external = External;
  if (External)
    for (auto &M : Dispatch.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto &Bridge = Input[0].methods[0];
  Bridge.instructions = {
      op(0, "invoke-static", {1, 2}, {}, Dispatch.methods[0].reference),
      op(3, "move-result", {0}), op(4, "return", {0})};
  Bridge.code_end = 5;
  auto Required = method("isEmpty", {}, "Z", 0, {});
  Required.access = {"public", "abstract"};
  Required.reference.owner = Input[1].name;
  Input[1].methods.push_back(Required);
  Required.access = {"public", "bridge"};
  Required.registers = 2;
  Required.instructions = {
      op(0, "invoke-static", {1}, {}, Dispatch.methods[1].reference),
      op(3, "move-result", {0}), op(4, "return", {0})};
  Required.code_end = 5;
  Required.reference.owner = Input[0].name;
  Input[0].methods.push_back(Required);
  Input.push_back(Dispatch);
  return Input;
}

