std::vector<Class> fixedContractImplementationBridgeClasses() {
  auto Input = methodFormalInterfaceFieldClasses(true);
  Input[1].interfaces.push_back(Input[0].name);
  *Input[1].generic_signature += Input[0].name;
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<Z:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Fixed = method("fixed", {Box.name}, "Ljava/lang/Object;", 0, {});
  Fixed.generic_signature = "(Lfixture/Box<*>;)Ljava/lang/Object;";
  auto Plain =
      method("plain", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  for (auto Member : {Fixed, Plain}) {
    Member.access = {"public", "abstract"};
    Member.reference.owner = Input[0].name;
    Input[0].methods.push_back(Member);
    Member.access = {"public", "bridge"};
    Member.registers = 2;
    Member.instructions = {op(0, "return-object", {1})};
    Member.code_end = 1;
    Member.reference.owner = Input[1].name;
    Input[1].methods.push_back(Member);
  }
  Input.push_back(Box);
  auto Helper = method("plain", {Input[0].name, "Ljava/lang/Object;"},
                       "Ljava/lang/Object;", 2, {op(0, "return-object", {1})});
  Helper.access = {"public", "static"};
  auto Dispatch = klass("Lfixture/Dispatch;", {Helper});
  auto &PlainBody = Input[1].methods[3];
  PlainBody.registers = 3;
  PlainBody.instructions = {
      op(0, "invoke-static", {1, 2}, {}, Dispatch.methods[0].reference),
      op(1, "move-result-object", {0}), op(2, "return-object", {0})};
  PlainBody.code_end = 3;
  Input.push_back(Dispatch);
  return Input;
}

