std::vector<Class> integerStaticComparisonClasses(bool External, bool Nested) {
  const std::string ApiName = "Lfixture/CompareView;";
  auto Generic = method("compareTo", {"Ljava/lang/Object;"}, "I", 0, {});
  Generic.access = {"public", "abstract"};
  Generic.generic_signature = "(TT;)I";
  auto Comparable = klass("Ljava/lang/Comparable;", {Generic});
  Comparable.external = true;
  Comparable.access = {"public", "abstract", "interface"};
  Comparable.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Compare = method("compareTo", {ApiName}, "I", 0, {});
  Compare.access = {"public", "abstract"};
  auto Api = klass(ApiName, {Compare});
  Api.access = {"public", "abstract", "interface"};
  Api.interfaces = {Comparable.name};
  Api.generic_signature =
      "Ljava/lang/Object;Ljava/lang/Comparable<Lfixture/CompareView;>;";
  auto Call =
      method("compare", {ApiName, ApiName}, "I", 3,
             {op(0, "const/4", {0}, int64_t{-1}), op(1, "return", {0})});
  auto Helper = klass("Lfixture/CompareDispatch;", {Call});
  Helper.external = External;
  if (External)
    Helper.methods[0].instructions.clear();
  Compare.access = {"public", "bridge"};
  Compare.registers = 3;
  Compare.instructions = {
      op(0, "invoke-static", {1, 2}, {}, Helper.methods[0].reference),
      op(1, "move-result", {0}), op(2, "return", {0})};
  Compare.code_end = 3;
  auto Core =
      klass(Nested ? "Lfixture/Host$Core;" : "Lfixture/Core;", {Compare});
  Core.access.insert("final");
  Core.interfaces = {ApiName};
  Generic.reference.owner = Core.name;
  Generic.access = {"public", "bridge", "synthetic"};
  Generic.generic_signature.reset();
  Generic.registers = 3;
  Generic.instructions = {
      op(0, "move-object", {0, 2}), op(1, "check-cast", {0}, {}, ApiName),
      op(2, "invoke-virtual", {1, 0}, {}, Core.methods[0].reference),
      op(3, "move-result", {0}), op(4, "return", {0})};
  Generic.code_end = 5;
  Core.methods.push_back(Generic);
  Generic.reference.owner = ApiName;
  Generic.instructions[2].opcode = "invoke-interface";
  Generic.instructions[2].reference = Api.methods[0].reference;
  Api.methods.push_back(Generic);
  if (Nested) {
    Core.access = {"final"};
    Core.enclosing = "Lfixture/Host;";
    Core.inner_class_present = true;
    Core.inner_name = "Core";
    Core.inner_access = {"private", "static", "final"};
  }
  return {Core, Api, Comparable, Helper, klass("Lfixture/Host;")};
}

