TEST(MobileDalvikJava, FixedParameterInterfacesReportAbsentCompilerBridges) {
  for (bool External : {false, true})
    for (bool Nested : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = integerStaticComparisonClasses(External, Nested);
          Input[1].methods.pop_back();
          if (Reverse) {
            std::reverse(Input.begin(), Input.end());
            for (auto &Cls : Input)
              std::reverse(Cls.methods.begin(), Cls.methods.end());
          }
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 3);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          unsigned Added = 0;
          for (const auto &Value : *R.getArray("generated_source_helpers")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("kind") != "compiler-parameter-interface-bridge")
              continue;
            ++Added;
            EXPECT_EQ(Row->getString("prototype"), "(Ljava/lang/Object;)I");
            EXPECT_EQ(
                Row->getString("bridge_target"),
                "Lfixture/CompareView;->compareTo(Lfixture/CompareView;)I");
            EXPECT_EQ(Row->getString("bridge_dispatch"),
                      "Ljava/lang/Comparable;->compareTo(Ljava/lang/Object;)I");
          }
          EXPECT_EQ(Added, 1);
          unsigned Projected = 0;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("projection_kind") !=
                "interface-parameter-runtime-bridges")
              continue;
            ++Projected;
            EXPECT_TRUE(Row->getString("reason").has_value());
            ASSERT_NE(Row->getArray("generated_bridges"), nullptr);
            EXPECT_EQ(Row->getArray("generated_bridges")->size(), 1);
            EXPECT_TRUE(Row->getArray("metadata_differences"));
          }
          EXPECT_EQ(Projected, 1);
        }
}

