  Ready.registers = 2;
  Ready.instructions = {op(0, "invoke-static", {1}, {}, Helper.reference),
                        op(1, "move-result", {0}), op(2, "return", {0})};
  Ready.code_end = 3;
  Input[0].methods.push_back(Ready);
  Input.push_back(Middle);
  Input.push_back(Parent);
