std::vector<Class> copiedStaticReceiverClasses(unsigned Kind, bool External,
                                               bool Nested) {
  auto Input = Kind == 0 ? integerStaticComparisonClasses(External, Nested)
               : Kind == 1
                   ? fixedReferenceStaticReceiverClasses(External, Nested)
                   : inheritedStaticPredicateClasses(External, Nested);
  for (auto &Method : Input[0].methods) {
    if (Method.access != Access{"public", "bridge"} ||
        Method.instructions.size() != 3)
      continue;
    const auto *Call =
        std::get_if<MethodRef>(&Method.instructions[0].reference);
    if (!Call || Method.instructions[0].opcode != "invoke-static")
      continue;
    const auto First = Method.registers - Method.incomingWords();
    const auto Cast = Call->parameters[0];
    Method.instructions[0].registers[0] = 0;
    Method.instructions.insert(
        Method.instructions.begin(),
        {op(0, "move-object", {0, First}), op(1, "check-cast", {0}, {}, Cast)});
    for (size_t i = 0; i < Method.instructions.size(); ++i)
      Method.instructions[i].pc = i;
    Method.code_end = Method.instructions.size();
  }
  return Input;
}

