TEST(MobileDalvikJava, NominalBoxedResultsRejectFactoryPairAndContractDrift) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = nominalBoxedResultClasses(false, false);
      auto &Core = Input[0];
      std::vector<Method *> Bridges;
      for (auto &M : Core.methods)
        if (M.reference.name == "shift" && M.access.contains("bridge"))
          Bridges.push_back(&M);
      ASSERT_EQ(Bridges.size(), 2u);
      if (Mutation == 0)
        Bridges[0]->instructions[0].registers = {2, 4, 3};
      else if (Mutation == 1)
        Bridges[0]->instructions[2].registers = {1, 0};
      else if (Mutation == 2)
        Bridges[0]->instructions[2].registers = {0};
      else if (Mutation == 3)
        Bridges[1]->instructions.back().registers = {2};
      else if (Mutation == 4)
        Core.access.erase("final");
      else if (Mutation == 5)
        Core.methods.back().access.erase("static");
      else if (Mutation == 6)
        Core.methods[Core.methods.size() - 2].generic_signature =
            "<T:Ljava/lang/Object;>(J)J";
      else if (Mutation == 7) {
        auto Other = Core.methods.back();
        Other.reference.name = "otherBox";
        Bridges[1]->instructions[2].reference = Other.reference;
        Core.methods.push_back(Other);
      } else if (Mutation == 8)
        Bridges[0]->access.erase("synthetic");
      else {
        auto Required = Core.methods[Core.methods.size() - 2];
        Required.access = {"public", "abstract"};
        Required.instructions.clear();
        Required.registers = Required.code_end = 0;
        Required.reference.owner = Input.back().name;
        Input.back().methods.push_back(Required);
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> nonReturningBooleanResultClasses(bool Shared = false) {
  auto Add = method("add", {"Ljava/lang/Object;"}, "Z", 0, {});
  Add.access = {"public", "abstract"};
  Add.generic_signature = "(TE;)Z";
  auto Api = klass("Lfixture/Api;", {Add});
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Api.external = true;
  auto Entry = klass("Lfixture/Entry;");
  Entry.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Entry.external = true;
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.superclass = Throwable.name;
  Runtime.external = true;
  auto Init = method("<init>", {}, "V", 0, {});
  Init.access = {"public", "constructor"};
  auto Failure = klass("Lfixture/Failure;", {Init});
  Failure.superclass = Runtime.name;
  Failure.external = true;
  auto Cause =
      method("cause", {}, "Ljava/lang/Void;", 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Cause.access = {"public", "static"};
  auto Effects = klass("Lfixture/Effects;", {Cause});
  Add.reference.parameters = {Entry.name};
  Add.reference.returns = "Ljava/lang/Void;";
  Add.access = {"public"};
  Add.registers = 3;
  Add.generic_signature = "(Lfixture/Entry<TT;>;)Ljava/lang/Void;";
  Add.instructions = {
      op(0, "invoke-static", {}, {}, Effects.methods[0].reference),
      op(1, "new-instance", {0}, {}, Failure.name),
      op(2, "invoke-direct", {0}, {}, Failure.methods[0].reference),
      op(3, "throw", {0})};
  Add.code_end = 4;
  auto Bridge = method("add", {"Ljava/lang/Object;"}, "Z", 3, {});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Core = klass("Lfixture/Core;", {Add, Bridge});
  Core.access.insert("final");
  Core.interfaces = {Api.name};
  Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;"
                           "Lfixture/Api<Lfixture/Entry<TT;>;>;";
  Core.methods[1].instructions = {
      op(0, "move-object", {0, 2}),
      op(1, "check-cast", {0}, {}, Entry.name),
      op(2, "invoke-virtual", {1, 0}, {}, Core.methods[0].reference),
      op(3, "move-result-object", {0}),
      op(4, "check-cast", {0}, {}, std::string("Ljava/lang/Boolean;")),
      op(5, "invoke-virtual", {0}, {},
         MethodRef{"Ljava/lang/Boolean;", "booleanValue", {}, "Z"}),
      op(6, "move-result", {0}),
      op(7, "return", {0})};
  Core.methods[1].code_end = 8;
  if (Shared) {
    Api.methods[0].reference.parameters = {Entry.name};
    Api.methods[0].generic_signature = "(Lfixture/Entry<TE;>;)Z";
    Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;"
                             "Lfixture/Api<TT;>;";
    Core.methods[1].reference.parameters = {Entry.name};
    Core.methods[1].instructions.erase(Core.methods[1].instructions.begin(),
                                       Core.methods[1].instructions.begin() +
                                           2);
    Core.methods[1].instructions[0].registers = {1, 2};
    for (size_t i = 0; i < Core.methods[1].instructions.size(); ++i)
      Core.methods[1].instructions[i].pc = i;
    Core.methods[1].code_end = 6;
  }
  return {Core, Api, Entry, Effects, Failure, Runtime, Throwable};
}

