  Bridge.code_end = 6;
  auto Init =
      method("<init>", {"Ljava/lang/String;"}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "iput-object", {1, 0}, {}, Message), op(2, "return-void")});
  Init.reference.owner = Core.name;
