          SCOPED_TRACE(::testing::Message()
                       << External << Wide << Link << Reverse);
          auto Input = plainNonReturningVoidClasses(External, Wide);
          if (Reverse) {
            std::reverse(Input.begin(), Input.end());
            for (auto &Cls : Input)
              std::reverse(Cls.methods.begin(), Cls.methods.end());
          }
          Budget B;
