std::vector<Class> interfaceInitializerClasses() {
  const std::string ApiName = "Lfixture/Api;";
  const FieldRef First{ApiName, "zFirst", "Ljava/lang/String;"};
  const FieldRef Second{ApiName, "aSecond", "Ljava/lang/Object;"};
  const FieldRef Original{"Lfixture/Provider;", "value", "Ljava/lang/Object;"};
  const MethodRef Replace{
      "Ljava/lang/String;", "replace", {"C", "C"}, "Ljava/lang/String;"};
  auto Init = method(
      "<clinit>", {}, "V", 3,
      {op(0, "const/16", {0}, int64_t(36)), op(1, "const/16", {1}, int64_t(46)),
       op(2, "const-string", {2}, std::string("owned$source")),
       op(3, "invoke-virtual", {2, 0, 1}, {}, Replace),
       op(4, "move-result-object", {0}), op(5, "sput-object", {0}, {}, First),
       op(6, "sget-object", {1}, {}, Original),
       op(7, "sput-object", {1}, {}, Second), op(8, "return-void")});
  Init.access = {"static", "constructor"};
  auto Api = klass(ApiName, {Init});
  Api.access = {"public", "interface", "abstract"};
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  for (const auto &Ref : {Second, First}) {
    Field F;
    F.reference = Ref;
    F.access = {"public", "static", "final"};
    Api.fields.push_back(F);
  }
  auto Provider = klass(Original.owner);
  Field F;
  F.reference = Original;
  F.access = {"public", "static"};
  Provider.fields.push_back(F);
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  auto Call = method("replace", {"C", "C"}, "Ljava/lang/String;", 0, {});
  Call.reference = Replace;
  Call.access = {"public"};
  String.methods.push_back(Call);
  return {Api, Provider, String};
}

TEST(MobileDalvikJava, InterfaceInitializersKeepEffectsAndOriginalFieldOrder) {
  for (bool Reverse : {false, true})
    for (bool Link : {false, true}) {
      auto Input = interfaceInitializerClasses();
      if (Reverse) {
        std::reverse(Input[0].fields.begin(), Input[0].fields.end());
        std::reverse(Input.begin(), Input.end());
      }
      Budget B;
      const auto R =
          Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      const auto Text = source(R);
      EXPECT_LT(Text.find("zFirst ="), Text.find("aSecond ="));
      const auto Call = Text.find(".replace(");
      ASSERT_NE(Call, std::string::npos);
      EXPECT_EQ(Text.find(".replace(", Call + 1), std::string::npos);
      EXPECT_EQ(Text.find("static {"), std::string::npos);
      EXPECT_EQ(Text.find("__neverdThrow"), std::string::npos);
    }
}

TEST(MobileDalvikJava, InterfaceFieldsReuseResolvedStringLiteralsInOrder) {
  auto input = interfaceInitializerClasses();
  auto &api = input.front();
  auto &init = api.methods.front();
  // The first field calls replace() on the literal in v2. Subsequent fields
  // store that original reference after the first resolution has succeeded.
  auto &code = init.instructions;
  code.erase(code.begin() + 6, code.end());
  code.push_back(op(6, "sput-object", {2}, {}, api.fields[0].reference));
  for (unsigned i = 0; i < 256; ++i) {
    FieldRef field{api.name, "slot" + std::to_string(i), "Ljava/lang/Object;"};
    api.fields.push_back({field, {"public", "static", "final"}, {}});
    code.push_back(op(7 + i, "sput-object", {2}, {}, field));
  }
  code.push_back(op(263, "return-void"));
  init.code_end = 264;
  Budget b;
  auto report = recoverJava(linkClasses(input, b), b);
  EXPECT_EQ(report.getInteger("unrecovered_method_count"), 0);
  auto text = source(report);
  auto call = text.find(".replace(");
  ASSERT_NE(call, std::string::npos);
  EXPECT_EQ(text.find(".replace(", call + 1), std::string::npos);
  EXPECT_LT(call, text.find("aSecond ="));
  EXPECT_LT(text.find("aSecond ="), text.find("slot255 ="));
}

TEST(MobileDalvikJava, InterfaceInitializersRejectDuplicatedAndLostEffects) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = interfaceInitializerClasses();
      auto &Init = Input[0].methods[0];
      auto &Code = Init.instructions;
      if (Mutation == 0)
        Code[7].registers = {0}; // Drops the field read and repeats the call.
      else if (Mutation == 1)
        Input[2].methods[0].declared_throws =
            std::vector<std::string>{"Ljava/lang/Exception;"};
      else if (Mutation == 2) {
        Code[2].literal = std::string("unused original literal");
        Code.insert(Code.begin() + 3,
                    op(0, "const-string", {2}, std::string("replacement")));
      } else if (Mutation == 3) {
        Code[7].reference = Input[0].fields[1].reference;
        Input[0].fields.erase(Input[0].fields.begin());
      } else if (Mutation == 4)
        Code.insert(Code.begin(), op(0, "goto", {}, {}, {}, 2));
      else if (Mutation == 5)
        Input[0].fields[0].generic_signature = "Ljava/lang/Object;";
      else
        Code.insert(Code.begin(), op(0, "return-void"));
      for (size_t I = 0; I < Code.size(); ++I)
        Code[I].pc = I;
      Init.code_end = Code.size();
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> interfaceAllocationInitializerClasses(bool SDK, bool Range) {
  const std::string ApiName = "Lfixture/Api;";
  const FieldRef First{ApiName, "zFirst", ApiName},
      Second{ApiName, "aSecond", ApiName};
  auto Init =
      method("<clinit>", {}, "V", 1,
             {op(0, "new-instance", {0}, {}, std::string("Lfixture/First;")),
              op(1, Range ? "invoke-direct/range" : "invoke-direct", {0}, {},
                 MethodRef{"Lfixture/First;", "<init>", {}, "V"}),
              op(2, "sput-object", {0}, {}, First),
              op(3, "new-instance", {0}, {}, std::string("Lfixture/Second;")),
              op(4, Range ? "invoke-direct/range" : "invoke-direct", {0}, {},
                 MethodRef{"Lfixture/Second;", "<init>", {}, "V"}),
              op(5, "sput-object", {0}, {}, Second), op(6, "return-void")});
  Init.access = {"static", "constructor"};
  auto Api = klass(ApiName, {Init});
  Api.access = {"public", "abstract", "interface"};
  Api.fields = {{Second, {"public", "static", "final"}, {}},
                {First, {"public", "static", "final"}, {}}};
  std::vector<Class> Result{Api};
  for (const std::string Name : {"Lfixture/First;", "Lfixture/Second;"}) {
    auto Ctor =
        method("<init>", {}, "V", SDK ? 0 : 1,
               SDK ? std::vector<Instruction>{}
                   : std::vector<Instruction>{
                         op(0, "invoke-direct", {0}, {},
                            MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                         op(1, "return-void")});
    Ctor.access = {"public", "constructor"};
    auto C = klass(Name, {Ctor});
    C.external = SDK;
    C.interfaces = {ApiName};
    Result.push_back(C);
  }
  return Result;
}

TEST(MobileDalvikJava, InterfaceAllocationsKeepConstructorAndFieldOrder) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true}) {
        SCOPED_TRACE(::testing::PrintToString(std::tuple{SDK, Range, Reverse}));
        auto Input = interfaceAllocationInitializerClasses(SDK, Range);
        if (Reverse) {
          std::reverse(Input[0].fields.begin(), Input[0].fields.end());
          std::reverse(Input.begin(), Input.end());
        }
        Budget B;
        const auto R = recoverJava(linkClasses(Input, B), B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        std::string Text;
        for (const auto &Unit : *R.getArray("source_units"))
          if (Unit.getAsObject()->getString("class") == "Lfixture/Api;")
            Text = Unit.getAsObject()->getString("source")->str();
        EXPECT_LT(Text.find("zFirst ="), Text.find("aSecond ="));
        EXPECT_NE(Text.find("new fixture.First()"), std::string::npos);
        EXPECT_NE(Text.find("new fixture.Second()"), std::string::npos);
        EXPECT_EQ(Text.find("static {"), std::string::npos);
      }
}

TEST(MobileDalvikJava, InterfaceAllocationEvaluatesStringAfterNew) {
  auto input = interfaceAllocationInitializerClasses(true, false);
  auto &constructor = input[1].methods.front();
  constructor.reference.parameters = {"Ljava/lang/String;"};
  auto &init = input.front().methods.front();
  init.registers = 2;
  for (auto &instruction : init.instructions)
    if (instruction.pc != 0)
      ++instruction.pc;
  ++init.code_end;
  init.instructions[1].registers = {0, 1};
  init.instructions[1].reference = constructor.reference;
  init.instructions.insert(init.instructions.begin() + 1,
                           op(1, "const-string", {1}, std::string("argument")));
  Budget budget;
  auto report = recoverJava(linkClasses(input, budget), budget);
  EXPECT_EQ(report.getInteger("unrecovered_method_count"), 0);
  bool emitted = false;
  for (const auto &unit : *report.getArray("source_units")) {
    if (unit.getAsObject()->getString("class") != "Lfixture/Api;")
      continue;
    auto text = unit.getAsObject()->getString("source")->str();
    emitted = text.find("new fixture.First(") < text.find("\"argument\"") &&
              text.find("\"argument\"") < text.find("new fixture.Second(");
  }
  EXPECT_TRUE(emitted);
}

