    case 0:
      Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 1:
      Input[1].methods.clear();
      break;
    case 2:
      std::get<MethodRef>(M.instructions[1].reference).owner =
          "Lfixture/Second;";
      break;
    case 3:
      M.instructions[1].registers[0] = 1;
      break;
    case 4:
      M.instructions[1].opcode = "invoke-static";
      break;
    case 5:
      Input[1].access.insert("abstract");
      break;
    case 6:
      Input[1].methods[0].access = {"private", "constructor"};
      break;
    case 7:
      M.instructions[3] = op(3, "nop");
      M.instructions[4] = op(4, "nop");
      break;
    case 8:
      M.instructions[2].reference = Input[0].fields[0].reference;
      break;
    case 9:
      M.instructions[5].opcode = "sput";
      break;
    case 10:
      M.instructions[1] = op(1, "nop");
      break;
    case 11:
      Input[0].fields[1].generic_signature = "Lfixture/Api;";
      break;
    case 12:
      Input[1].enclosing = "Lfixture/Outer;";
      Input[1].inner_class_present = true;
      Input[1].inner_name = "First";
      Input[1].inner_access = {"public"};
      Input.push_back(klass("Lfixture/Outer;"));
