std::vector<Class> guardedDefaultResultClasses(bool ExternalRoot,
                                               bool ClassBody) {
  auto Input = checkedReferenceSuperAdapterClasses(ExternalRoot);
  const std::string Holder = "Lfixture/Holder;";
  const std::string Full = "Lfixture/Holder<TT;>;";
  auto &Api = Input[0].methods[0];
  Api.access = {"public"};
  Api.reference.name = "getOrDefault";
  Api.reference.parameters.push_back("Ljava/lang/Object;");
  Api.generic_signature = "(Ljava/lang/Object;TE;)TE;";
  auto &Root = Input[4].methods[1];
  Root.reference.name = "getOrDefault";
  Root.reference.parameters.push_back("Ljava/lang/Object;");
  Root.generic_signature = "(Ljava/lang/Object;TR;)TR;";
  if (!ExternalRoot) {
    Root.registers = 4;
    Root.instructions = {op(0, "return-object", {3})};
    Root.code_end = 1;
  }
  if (!ClassBody)
    Input[4].methods.pop_back();
  auto &Typed = Input[1].methods[1];
  Typed.reference.name = "getOrDefault";
  Typed.reference.parameters.push_back(Holder);
  Typed.generic_signature = "(Lfixture/Element<TT;>;" + Full + ")" + Full;
  Typed.registers = 4;
  Typed.instructions[0].registers = {1, 2, 3};
  Typed.instructions[0].reference =
      MethodRef{Input[5].name,
                "getOrDefault",
                {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                "Ljava/lang/Object;"};
  auto &Guard = Input[1].methods[0];
  Guard.reference.name = "getOrDefault";
  Guard.reference.parameters.push_back(Holder);
  Guard.generic_signature = "(Ljava/lang/Object;" + Full + ")" + Full;
  Guard.registers = 4;
  Guard.instructions = {op(0, "instance-of", {0, 2}, {}, Input[2].name),
                        op(1, "if-nez", {0}, {}, {}, 3),
                        op(2, "return-object", {3}),
                        op(3, "move-object", {0, 2}),
                        op(4, "check-cast", {0}, {}, Input[2].name),
                        op(5, "invoke-virtual", {1, 0, 3}, {}, Typed.reference),
                        op(6, "move-result-object", {0}),
                        op(7, "return-object", {0})};
  Guard.code_end = 8;
  auto &Erased = Input[1].methods.back();
  Erased.reference.name = "getOrDefault";
  Erased.reference.parameters.push_back("Ljava/lang/Object;");
  Erased.registers = 5;
  Erased.instructions = {
      op(0, "instance-of", {0, 3}, {}, Input[2].name),
      op(1, "if-nez", {0}, {}, {}, 3),
      op(2, "return-object", {4}),
      op(3, "move-object", {0, 3}),
      op(4, "check-cast", {0}, {}, Input[2].name),
      op(5, "move-object", {1, 4}),
      op(6, "check-cast", {1}, {}, Holder),
      op(7, "invoke-virtual", {2, 0, 1}, {}, Typed.reference),
      op(8, "move-result-object", {0}),
      op(9, "return-object", {0})};
  Erased.code_end = 10;
  return Input;
}

