TEST(MobileDalvikJava, GuardedDefaultsRetainSharedInterfaceContract) {
  for (bool ClassBody : {false, true}) {
    auto Input = guardedDefaultResultClasses(false, ClassBody);
    const auto &Api = Input[0];
    auto &Child = Input[1];
    auto &Middle = Input[5];
    auto Shared = klass("Lfixture/SharedView;");
    Shared.access = {"public", "abstract", "interface"};
    Shared.interfaces = {Api.name};
    const std::string Value = "Lfixture/Holder<Ljava/lang/Object;>;";
    Shared.generic_signature =
        "Ljava/lang/Object;Lfixture/CountView<" + Value + ">;";
    Middle.interfaces = {Api.name};
    *Middle.generic_signature += "Lfixture/CountView<TM;>;";
    Child.interfaces = {Shared.name};
    Child.generic_signature =
        "Lfixture/GuardMiddle<" + Value + ">;" + Shared.name;
    for (auto &M : Child.methods) {
      if (!M.generic_signature)
        continue;
      auto &Sig = *M.generic_signature;
      for (auto at = Sig.find("TT;"); at != Sig.npos; at = Sig.find("TT;"))
        Sig.replace(at, 3, "Ljava/lang/Object;");
    }
    const auto SharedName = Shared.name;
    Input.push_back(std::move(Shared));
    Budget B;
    const auto Report = recoverJava(linkClasses(Input, B), B);
    EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
    const auto *Projections = Report.getArray("generic_signature_projections");
    ASSERT_NE(Projections, nullptr);
    bool SharedAncestor = false;
    for (const auto &Entry : *Projections) {
      const auto *Row = Entry.getAsObject();
      if (Row->getString("declaration") == SharedName)
        for (const auto &Change : *Row->getArray("changes"))
          SharedAncestor |= Change.getAsObject()->getString("kind") ==
                            "guarded-default-shared-interface";
    }
    EXPECT_TRUE(SharedAncestor);

    Input.back().generic_signature =
        "Ljava/lang/Object;Lfixture/CountView<Ljava/lang/Object;>;";
    Budget Wrong;
    EXPECT_THROW(recoverJava(linkClasses(Input, Wrong), Wrong),
                 std::runtime_error);
  }
}

