std::vector<Class> nestedInvariantReturnClasses(bool ChildFirst = true) {
  auto Read = klass("Lfixture/Read;");
  Read.access = {"public", "abstract", "interface"};
  Read.external = true;
  Read.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Pair = klass("Lfixture/Pair;");
  Pair.external = true;
  Pair.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Values = method("values", {}, Read.name, 0, {});
  Values.access = {"public", "abstract"};
  Values.generic_signature = "()Lfixture/Read<TE;>;";
  auto Contract = klass("Lfixture/Contract;", {Values});
  Contract.access = {"public", "abstract", "interface"};
  Contract.external = true;
  Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Values.access = {"public"};
  Values.generic_signature = "()Lfixture/Read<Lfixture/Pair<TK;TV;>;>;";
  Values.registers = 2;
  Values.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
  Values.code_end = 2;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto View =
      klass(ChildFirst ? "Lfixture/AView;" : "Lfixture/ZView;", {Values, Init});
  View.access.insert("final");
  View.interfaces = {Contract.name};
  View.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Contract<Lfixture/Pair<+TK;+TV;>;>;";
  return {Contract, View, Read, Pair};
}

TEST(MobileDalvikJava,
     NestedInvariantReturnsProjectOnlyExactInheritedVariance) {
  for (bool ChildFirst : {false, true})
    for (bool Link : {false, true}) {
      auto Input = nestedInvariantReturnClasses(ChildFirst);
      Budget B;
      const auto R =
          Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("method_count"), 2);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      EXPECT_EQ(R.getString("status"), "partial");
      const auto *Projections = R.getArray("generic_signature_projections");
      ASSERT_NE(Projections, nullptr);
      ASSERT_EQ(Projections->size(), 1u);
      const auto *Projection = (*Projections)[0].getAsObject();
      ASSERT_NE(Projection, nullptr);
      const auto *Changes = Projection->getArray("changes");
      ASSERT_NE(Changes, nullptr);
      ASSERT_EQ(Changes->size(), 1u);
      const auto *Change = (*Changes)[0].getAsObject();
      ASSERT_NE(Change, nullptr);
      EXPECT_EQ(Change->getString("kind"), "inherited-nested-return-variance");
      EXPECT_EQ(Change->getString("source_type"),
                "()Lfixture/Read<Lfixture/Pair<+TK;+TV;>;>;");
      EXPECT_EQ(Change->getString("scope_origin"),
                Input[0].methods[0].reference.identity());
      EXPECT_NE(source(R).find(
                    "fixture.Read<fixture.Pair<? extends K, ? extends V>>"),
                std::string::npos);
      EXPECT_EQ(Input[1].methods[0].generic_signature,
                "()Lfixture/Read<Lfixture/Pair<TK;TV;>;>;");
    }
}

std::vector<Class> nestedObjectLowerReturnClasses(bool External, bool Default) {
  auto Input = nestedInvariantReturnClasses();
  auto &Api = Input[0];
  Api.external = External;
  if (Default) {
    Api.methods[0].access = {"public"};
    if (!External) {
      Api.methods[0].registers = 2;
      Api.methods[0].instructions = {op(0, "const/4", {0}, int64_t(0)),
                                     op(1, "return-object", {0})};
      Api.methods[0].code_end = 2;
    }
  }
  Input[1].generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Lfixture/Pair<-Ljava/lang/"
      "Object;-Ljava/lang/Object;>;>;";
  Input[1].methods[0].generic_signature =
      "()Lfixture/Read<Lfixture/Pair<Ljava/lang/Object;Ljava/lang/Object;>;>;";
  auto Init = Input[1].methods[1];
  Init.instructions.clear();
  Init.registers = Init.code_end = 0;
  auto Object = klass("Ljava/lang/Object;", {Init});
  Object.external = true;
  Object.superclass.reset();
  Input.push_back(Object);
  return Input;
}

