std::vector<Class> terminalThrowBridgeClasses(bool ChildFirst = true) {
  auto Input = nestedInvariantReturnClasses(ChildFirst);
  auto Add = method("add", {"Ljava/lang/Object;"}, "Z", 0, {});
  Add.access = {"public", "abstract"};
  Add.generic_signature = "(TE;)Z";
  Input[0] = klass("Lfixture/Contract;", {Add});
  Input[0].access = {"public", "abstract", "interface"};
  Input[0].external = true;
  Input[0].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Add.registers = 4;
  Add.access = {"public"};
  Add.reference.parameters = {"Lfixture/Pair;"};
  Add.generic_signature = "(Lfixture/Pair<+TK;+TV;>;)Z";
  Add.instructions = {
      op(0, "new-instance", {0}, {},
         std::string("Ljava/lang/UnsupportedOperationException;")),
      op(1, "const-string", {1}, std::string("owned immutable operation")),
      op(2, "invoke-direct", {0, 1}, {},
         MethodRef{"Ljava/lang/UnsupportedOperationException;",
                   "<init>",
                   {"Ljava/lang/String;"},
                   "V"}),
      op(3, "throw", {0})};
  Add.code_end = 4;
  auto Bridge = Add;
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.reference.parameters = {"Ljava/lang/Object;"};
  Bridge.generic_signature.reset();
  auto View = klass(Input[1].name, {Bridge, Add, Input[1].methods[1]});
  View.access = Input[1].access;
  View.generic_signature = Input[1].generic_signature;
  View.interfaces = Input[1].interfaces;
  Input[1] = std::move(View);
  return Input;
}

TEST(MobileDalvikJava, TerminalThrowBridgesRetainBodiesAndOriginalContracts) {
  for (bool ChildFirst : {false, true})
    for (bool Link : {false, true}) {
      auto Input = terminalThrowBridgeClasses(ChildFirst);
      Budget B;
      const auto R =
          Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("method_count"), 3);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("projected_method_count"), 1);
      EXPECT_EQ(R.getString("status"), "partial");
      const auto *Projections = R.getArray("generic_signature_projections");
      ASSERT_NE(Projections, nullptr);
      ASSERT_EQ(Projections->size(), 1u);
      const auto *Changes =
          (*Projections)[0].getAsObject()->getArray("changes");
      ASSERT_NE(Changes, nullptr);
      EXPECT_EQ((*Changes)[0].getAsObject()->getString("kind"),
                "terminal-throw-raw-interface");
      const auto *Rows = R.getArray("methods");
      ASSERT_NE(Rows, nullptr);
      bool Found = false;
      for (const auto &Value : *Rows) {
        const auto *Row = Value.getAsObject();
        ASSERT_NE(Row, nullptr);
        if (Row->getString("identity") !=
            Input[1].methods[0].reference.identity())
          continue;
        Found = true;
        EXPECT_EQ(Row->getString("projection_kind"),
                  "terminal-throw-interface-bridge");
        EXPECT_EQ(Row->getString("bridge_target"),
                  Input[1].methods[1].reference.identity());
        EXPECT_EQ(Row->getInteger("instruction_count"), 4);
      }
      EXPECT_TRUE(Found);
      const auto Text = source(R);
      EXPECT_NE(Text.find("implements fixture.Contract {"), std::string::npos);
      EXPECT_NE(Text.find("boolean add(java.lang.Object"), std::string::npos);
      EXPECT_NE(Text.find("boolean add(fixture.Pair<? extends K, ? extends V>"),
                std::string::npos);
    }
}

TEST(MobileDalvikJava, RawInterfaceKeepsThrowingOverloadAndCovariantBridge) {
  for (bool dependency : {false, true}) {
    auto input = terminalThrowBridgeClasses();
    auto &api = input[0];
    api.external = dependency;
    auto get = method("get", {}, "Ljava/lang/Object;", 0, {});
    get.access = {"public", "abstract"};
    get.generic_signature = "()TE;";
    get.reference.owner = api.name;
    api.methods.push_back(get);
    auto &cls = input[1];
    cls.generic_signature.reset();
    cls.methods[1].generic_signature.reset();
    cls.methods[1].reference.parameters = {"Ljava/lang/String;"};
    cls.interfaces = {api.name, "Lfixture/Marker;"};
    auto typed = method("get", {}, "Ljava/lang/String;", 1,
                        {op(0, "const-string", {0}, std::string("value")),
                         op(1, "return-object", {0})});
    typed.reference.owner = cls.name;
    typed.access = {"public"};
    auto bridge = method("get", {}, "Ljava/lang/Object;", 2,
                         {op(0, "invoke-virtual", {1}, {}, typed.reference),
                          op(1, "move-result-object", {0}),
                          op(2, "return-object", {0})});
    bridge.reference.owner = cls.name;
    bridge.access = {"public", "bridge", "synthetic"};
    cls.methods.push_back(typed);
    cls.methods.push_back(bridge);
    auto marker = klass("Lfixture/Marker;");
    marker.access = {"public", "abstract", "interface"};
    input.push_back(marker);
    Budget budget;
    const auto report = recoverJava(linkClasses(input, budget), budget);
    EXPECT_EQ(report.getInteger("unrecovered_method_count"), 0);
    const auto &rows = *report.getArray("methods");
    bool retained = false, regenerated = false;
    for (const auto &row : rows) {
      auto kind = row.getAsObject()->getString("projection_kind");
      retained |= kind == "terminal-throw-interface-bridge";
      regenerated |= row.getAsObject()->getString("identity") ==
                         bridge.reference.identity() &&
                     row.getAsObject()->getString("bridge_target") ==
                         typed.reference.identity();
    }
    EXPECT_TRUE(retained);
    EXPECT_TRUE(regenerated);
  }
}

