std::vector<Class> indexedTerminalThrowClasses(bool InheritedDefaults = false) {
  std::vector<Method> Contracts, Implementations;
  for (const auto &[Name, Parameters, Returns, Signature] :
       std::vector<std::tuple<std::string, std::vector<std::string>,
                              std::string, std::string>>{
           {"add", {"Ljava/lang/Object;"}, "Z", "(TE;)Z"},
           {"insert", {"I", "Ljava/lang/Object;"}, "V", "(ITE;)V"},
           {"replace",
            {"I", "Ljava/lang/Object;"},
            "Ljava/lang/Object;",
            "(ITE;)TE;"},
           {"remove", {"I"}, "Ljava/lang/Object;", "(I)TE;"},
           {"begin", {"Ljava/lang/Object;"}, "V", "(TE;)V"},
           {"first", {}, "Ljava/lang/Object;", "()TE;"}}) {
    auto Member = method(Name, Parameters, Returns, 0, {});
    Member.access = {"public", "abstract"};
    if (Name == "begin" || Name == "first")
      Member.access.erase("abstract");
    Member.generic_signature = Signature;
    Contracts.push_back(Member);
    auto Target = Member;
    Target.access = {"public"};
    Target.generic_signature.reset();
    for (auto &Type : Target.reference.parameters)
      if (Type == "Ljava/lang/Object;")
        Type = "Lfixture/Element;";
    if (Target.reference.returns == "Ljava/lang/Object;")
      Target.reference.returns = "Lfixture/Element;";
    Target.registers = 3 + Parameters.size();
    Target.instructions = {
        op(0, "new-instance", {0}, {},
           std::string("Ljava/lang/UnsupportedOperationException;")),
        op(1, "const-string", {1}, std::string("owned immutable operation")),
        op(2, "invoke-direct", {0, 1}, {},
           MethodRef{"Ljava/lang/UnsupportedOperationException;",
                     "<init>",
                     {"Ljava/lang/String;"},
                     "V"}),
        op(3, "throw", {0})};
    Target.code_end = 4;
    auto Bridge = Target;
    Bridge.reference.parameters = Parameters;
    Bridge.reference.returns = Returns;
    Bridge.access = {"public", "bridge", "synthetic"};
    Implementations.push_back(Bridge);
    Implementations.push_back(Target);
  }
  auto Contract = klass("Lfixture/Contract;", Contracts);
  Contract.access = {"public", "abstract", "interface"};
  Contract.external = true;
  Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto View = klass("Lfixture/View;", Implementations);
  View.access = {"public", "final"};
  View.interfaces = {Contract.name};
  View.generic_signature =
      "Ljava/lang/Object;Lfixture/Contract<Lfixture/Element;>;";
  auto Input = std::vector<Class>{Contract, View, klass("Lfixture/Element;")};
  if (InheritedDefaults) {
    auto Base = klass("Lfixture/Base;", {Contracts[4], Contracts[5]});
    Base.access = {"public", "abstract", "interface"};
    Base.external = true;
    Base.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    Input[0].interfaces = {Base.name};
    Input[0].generic_signature =
        "<E:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Base<TE;>;";
    Input.push_back(Base);
  }
  return Input;
}

std::vector<Class> erasedTerminalConsumerClasses(bool External, bool Rich) {
  auto Input = indexedTerminalThrowClasses();
  auto &Api = Input[0];
  Api.external = External;
  Api.methods.resize(1);
  auto &Owner = Input[1];
  Owner.methods.resize(1); // No original typed reference overload exists.
  auto Scalar = Owner.methods[0];
  Scalar.reference.name = "addScalar";
  Scalar.reference.parameters = {"I"};
  Scalar.access = {"public"};
  Owner.methods.push_back(Scalar);
  if (Rich) {
    auto Collection = klass("Lfixture/Bag;");
    Collection.external = true;
    Collection.access = {"public", "abstract", "interface"};
    Collection.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    for (const auto &[Name, Parameters, Returns, Full, Actual] :
         std::vector<std::tuple<std::string, std::vector<std::string>,
                                std::string, std::string, std::string>>{
             {"bulk",
              {Collection.name},
              "Z",
              "(Lfixture/Bag<+TE;>;)Z",
              "(Lfixture/Bag<+Lfixture/Element;>;)Z"},
             {"containsAll",
              {Collection.name},
              "Z",
              "(Lfixture/Bag<*>;)Z",
              "(Lfixture/Bag<*>;)Z"},
             {"echo",
              {"Ljava/lang/Object;"},
              "Ljava/lang/Object;",
              "<R:Ljava/lang/Object;>(TR;)TR;",
              "<R:Ljava/lang/Object;>(TR;)TR;"},
             {"array",
              {"[Ljava/lang/Object;"},
              "[Ljava/lang/Object;",
              "<R:Ljava/lang/Object;>([TR;)[TR;",
              "<R:Ljava/lang/Object;>([TR;)[TR;"},
             {"values",
              {},
              Collection.name,
              "()Lfixture/Bag<TE;>;",
              "()Lfixture/Bag<Lfixture/Element;>;"}}) {
      auto Member = method(Name, Parameters, Returns, 0, {});
      Member.reference.owner = Api.name;
      Member.access = {"public", "abstract"};
      Member.generic_signature = Full;
      Api.methods.push_back(Member);
      auto Body = Member;
      Body.reference.owner = Owner.name;
      Body.access = {"public"};
      Body.generic_signature = Actual;
      Body.registers = Parameters.size() + 2;
      if (Name == "bulk") {
        Body.registers = 4;
        Body.instructions = Scalar.instructions;
      } else if (Name == "echo" || Name == "array")
        Body.instructions = {op(0, "return-object", {Body.registers - 1})};
      else if (Name == "values")
        Body.instructions = {op(0, "const/4", {0}, int64_t(0)),
                             op(1, "return-object", {0})};
      else
        Body.instructions = {op(0, "const/4", {0}, int64_t(1)),
                             op(1, "return", {0})};
      Body.code_end = Body.instructions.back().pc + 1;
      Owner.methods.push_back(Body);
    }
    Input.push_back(Collection);
  }
  return Input;
}

TEST(MobileDalvikJava,
     ErasedTerminalConsumersKeepFullContractsAndRawSourceSlots) {
  for (bool External : {false, true})
    for (bool Rich : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input = erasedTerminalConsumerClasses(External, Rich);
          const auto Bridge = Input[1].methods[0].reference;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), Rich ? 5 : 1);
          for (const auto &Unit : *R.getArray("source_units")) {
            const auto Text =
                Unit.getAsObject()->getString("source").value_or("");
            EXPECT_EQ(Text.find("return ((R[])"), llvm::StringRef::npos);
            EXPECT_EQ(Text.find("return ((R)"), llvm::StringRef::npos);
          }

          EXPECT_EQ(R.getString("status"), "partial");
          const auto *Projections = R.getArray("generic_signature_projections");
          ASSERT_NE(Projections, nullptr);
          EXPECT_EQ(Projections->front()
                        .getAsObject()
                        ->getArray("changes")
                        ->front()
                        .getAsObject()
                        ->getString("kind"),
                    "erased-terminal-consumer-raw-interface");
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") == Bridge.identity()) {
              EXPECT_EQ(Row->getString("projection_kind"),
                        "erased-terminal-consumer-bridge");
              EXPECT_EQ(Row->getString("inherited_contract"),
                        "Lfixture/Contract;->add(Ljava/lang/Object;)Z");
            }
          }
        }
}

