TEST(MobileDalvikJava, GuardedOuterConstructorDelegationRejectsUnprovenPaths) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = guardedCapturedTerminalThrowClasses();
      auto &Default = Input[1].methods.back();
      switch (Mutation) {
      case 0:
        Default.instructions[11].registers[1] = 7;
        break;
      case 1:
        Default.instructions[3].registers[0] = 2;
        break;
      case 2:
        Default.instructions[8].target = 12;
        break;
      case 3:
        Default.instructions[7].opcode = "unsupported-scalar";
        break;
      case 4:
        Default.instructions[11].registers[4] = 1;
        break;
      case 5:
        Input[1].fields[0].access.erase("final");
        break;
      case 6:
        Default.instructions[8].target = 10;
        break;
      case 7:
        Default.instructions[5].target = 2;
        break;
      case 8:
        Default.access.erase("synthetic");
        break;
      }
      Budget B;
      ClassMap Classes;
      if (Link)
        Classes = linkClasses(Input, B);
      else
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
      ConstructorDelegations Delegations;
      const auto Captures = planConstructorCaptures(Classes, B, &Delegations);
      EXPECT_FALSE(Captures.contains(Default.reference));
      EXPECT_FALSE(Delegations.contains(Default.reference));
      EXPECT_FALSE(planCapturedInnerClasses(Classes, B, &Captures)
                       .contains(Default.reference.owner));
      EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
    }
}

