TEST(MobileDalvikJava,
     IndexedTerminalThrowsProveInputsAndResultsWithoutSignature) {
  for (bool Link : {false, true}) {
    for (bool InheritedDefaults : {false, true}) {
      auto Input = indexedTerminalThrowClasses(InheritedDefaults);
      Budget B;
      const auto R =
          Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getInteger("method_count"), 12);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("projected_method_count"), 6);
      unsigned Retained = 0, Regenerated = 0;
      for (const auto &Value : *R.getArray("methods")) {
        const auto *Row = Value.getAsObject();
        if (Row->getString("projection_kind") ==
            "terminal-throw-interface-bridge")
          ++Retained;
        if (Row->getString("projection_kind") ==
            "terminal-throw-result-bridge") {
          ++Regenerated;
          ASSERT_NE(Row->getArray("metadata_differences"), nullptr);
          EXPECT_TRUE(Row->getString("bridge_target") ==
                          "Lfixture/View;->remove(I)Lfixture/Element;" ||
                      Row->getString("bridge_target") ==
                          "Lfixture/View;->first()Lfixture/Element;");
        }
      }
      EXPECT_EQ(Retained, 4u);
      EXPECT_EQ(Regenerated, 2u);
      const auto Text = source(R, 1);
      EXPECT_NE(Text.find("fixture.Element remove(int"), std::string::npos);
      EXPECT_EQ(Text.find("java.lang.Object remove(int"), std::string::npos);
      EXPECT_NE(Text.find("java.lang.Object replace(int"), std::string::npos);
    }
  }
}

