std::vector<Class> objectWildcardContractClasses(bool ChildFirst = true,
                                                 bool ParentExplicit = false) {
  auto Input = inheritedErasedParameterClasses(ChildFirst);
  const auto Plain = "(Lfixture/Box<*>;)Z";
  const auto Explicit = "(Lfixture/Box<+Ljava/lang/Object;>;)Z";
  auto Contains = method("containsAll", {"Lfixture/Box;"}, "Z", 0, {});
  Contains.reference.owner = Input[0].name;
  Contains.access = {"public", "abstract"};
  Contains.generic_signature = ParentExplicit ? Explicit : Plain;
  Input[0].methods.push_back(Contains);
  Contains.reference.owner = Input[2].name;
  Contains.access = {"public"};
  Contains.generic_signature = ParentExplicit ? Plain : Explicit;
  Contains.registers = 3;
  Contains.instructions = {op(0, "const", {0}, int64_t(1)),
                           op(1, "return", {0})};
  Contains.code_end = 2;
  Input[2].methods.push_back(Contains);
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Box);
  return Input;
}

