std::vector<Class> sourceGenericChainClasses(bool ChildFirst = true,
                                             bool Nested = false) {
  auto Input = sourceInterfaceSuperclassClasses(ChildFirst, true);
  auto &Parent = Input[1];
  auto &Child = Input[2];
  auto RootInit = Parent.methods.back();
  auto Touch = method("touch", {"Lfixture/Cell;"}, "Lfixture/Cell;", 0, {});
  Touch.access = {"abstract"};
  Touch.generic_signature = "(Lfixture/Cell<TR;TS;>;)Lfixture/Cell<TR;TS;>;";
  auto Root = klass("Lfixture/Root;", {RootInit, Touch});
  Root.access.insert("abstract");
  Root.generic_signature =
      "<R:Ljava/lang/Object;S:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.access.insert("abstract");
  Parent.superclass = Root.name;
  Parent.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Lfixture/Root<TP;TQ;>;"
      "Lfixture/Contract<TP;>;";
  Parent.methods.back().instructions[0].reference =
      MethodRef{Root.name, "<init>", {}, "V"};
  Touch.reference.owner = Parent.name;
  Touch.access = {"public"};
  Touch.generic_signature = "(Lfixture/Cell<TP;TQ;>;)Lfixture/Cell<TP;TQ;>;";
  Touch.registers = 2;
  Touch.instructions = {op(0, "return-object", {1})};
  Touch.code_end = 1;
  Parent.methods.push_back(Touch);
  auto Advance = Touch;
  Advance.reference.name = "advance";
  Advance.access = {"abstract"};
  Advance.instructions.clear();
  Advance.registers = 0;
  Advance.code_end = 0;
  Parent.methods.push_back(Advance);
  Advance.reference.owner = Child.name;
  Advance.access.clear();
  Advance.generic_signature = "(Lfixture/Cell<TI;TJ;>;)Lfixture/Cell<TI;TJ;>;";
  Advance.registers = 2;
  Advance.instructions = {op(0, "return-object", {1})};
  Advance.code_end = 1;
  Child.methods.push_back(Advance);
  auto ChildInit = RootInit;
  ChildInit.reference.owner = Child.name;
  ChildInit.instructions[0].reference =
      MethodRef{Parent.name, "<init>", {}, "V"};
  Child.methods.push_back(ChildInit);
  Input.push_back(Root);
  if (Nested) {
    auto Outer = klass("Lfixture/Nest;");
    for (auto &C : Input) {
      if (C.external || C.name == "Lfixture/Cell;")
        continue;
      C.enclosing = Outer.name;
      C.inner_name = C.name.substr(9, C.name.size() - 10);
      C.inner_access = C.access;
      C.inner_access.insert("static");
      C.inner_class_present = true;
    }
    Input.push_back(Outer);
  }
  return Input;
}

