TEST(MobileDalvikJava, SourceGenericChainsRejectUnprovenOwnershipAndOverrides) {
  for (bool ChildFirst : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = sourceGenericChainClasses(ChildFirst, true);
      switch (Mutation) {
      case 0:
        Input.erase(Input.begin() + 4);
        break;
      case 1:
        Input[4].external = true;
        Input[4].methods[0].instructions.clear();
        Input[4].methods[0].code_end = 0;
        Input[4].inner_access.erase("static");
        break;
      case 2:
        Input[4].methods.erase(Input[4].methods.begin());
        break;
      case 3:
        Input[1].generic_signature =
            "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Lfixture/Root;"
            "Lfixture/Contract<TP;>;";
        break;
      case 4:
        Input[2].methods[2].generic_signature =
            "(Lfixture/Cell<TJ;TI;>;)Lfixture/Cell<TI;TJ;>;";
        break;
      case 5:
        Input[1].inner_access.erase("static");
        break;
      case 6: {
        auto Higher = Input[1].methods[3];
        Higher.reference.owner = Input[2].name;
        Higher.generic_signature =
            "(Lfixture/Cell<TJ;TI;>;)Lfixture/Cell<TI;TJ;>;";
        Input[2].methods.push_back(Higher);
        Input[1].methods.erase(Input[1].methods.begin() + 3);
        break;
      }
      case 7: {
        auto Default =
            method("fallback", {"I"}, "I", 2, {op(0, "return", {1})});
        Default.reference.owner = Input[4].name;
        Default.access = {"protected"};
        Input[4].methods.push_back(Default);
        break;
      }
      case 8:
        Input[4].superclass = Input[1].name;
        Input[4].generic_signature =
            "<R:Ljava/lang/Object;S:Ljava/lang/Object;>" +
            Input[1].name.substr(0, Input[1].name.size() - 1) + "<TR;TS;>;";
        break;
      case 9:
        Input[2].methods[2].access = {"private"};
        break;
      case 10:
      case 11: {
        auto Static = method("snapshot", {"I"}, "I", 1, {op(0, "return", {0})});
        Static.reference.owner = Input[1].name;
        if (Mutation == 11)
          Static.access.insert("final");
        Input[1].methods.push_back(Static);
        Static.reference.owner = Input[2].name;
        if (Mutation == 10) {
          Static.access = {"public"};
          Static.registers = 2;
          Static.instructions = {op(0, "return", {1})};
        } else {
          Static.access.erase("final");
        }
        Input[2].methods.push_back(Static);
        break;
      }
      }
      if (Mutation >= 10)
        rejected([&] { recover(Input); },
                 Mutation == 10 ? "static/instance" : "final member");
      else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> externalGenericChainClasses(bool ChildFirst = true,
                                               bool Bounded = false) {
  auto Input = sourceGenericChainClasses(ChildFirst);
  auto &Parent = Input[1];
  auto &Child = Input[2];
  auto &Root = Input[4];
  Parent.external = true;
  Root.external = true;
  Parent.methods.erase(Parent.methods.begin());
  Root.methods[1].access = {"public"};
  auto Value = Child.methods[0];
  Value.reference.owner = Root.name;
  Value.access = {"public", "abstract"};
  Value.generic_signature = "(TR;)TR;";
  Root.methods.push_back(Value);
  auto Size = method("size", {}, "I", 0, {});
  Size.reference.owner = Root.name;
  Size.access = {"public", "abstract"};
  Root.methods.push_back(Size);
  Size.reference.owner = Child.name;
  Size.access = {"public"};
  Size.registers = 2;
  Size.instructions = {op(0, "const", {0}, int64_t(3)), op(1, "return", {0})};
  Size.code_end = 2;
  Child.methods.push_back(Size);
  for (auto *C : {&Parent, &Root})
    for (auto &M : C->methods) {
      M.registers = 0;
      M.instructions.clear();
      M.code_end = 0;
    }
  if (Bounded) {
    Child.generic_signature = "<I:Lfixture/Tag;J:Ljava/lang/Object;>" +
                              Parent.name.substr(0, Parent.name.size() - 1) +
                              "<TI;TJ;>;";
    Child.methods[0].reference.parameters = {"Lfixture/Tag;"};
    Child.methods[0].reference.returns = "Lfixture/Tag;";
    auto Bridge = Child.methods[0];
    Bridge.reference.parameters = {"Ljava/lang/Object;"};
    Bridge.reference.returns = "Ljava/lang/Object;";
    Bridge.access = {"public", "bridge", "synthetic"};
    Bridge.generic_signature.reset();
    Bridge.instructions = {
        op(0, "check-cast", {1}, {}, std::string("Lfixture/Tag;")),
        op(1, "invoke-virtual", {0, 1}, {}, Child.methods[0].reference),
        op(2, "move-result-object", {0}), op(3, "return-object", {0})};
    Bridge.code_end = 4;
    Child.methods.erase(Child.methods.begin() + 1);
    Child.methods.push_back(Bridge);
    Input.push_back(klass("Lfixture/Tag;"));
  }
  return Input;
}

std::vector<Class>
externalAbstractInterfaceRootClasses(bool NearerSDK = false,
                                     bool ChildFirst = true) {
  auto Input = externalGenericChainClasses(ChildFirst);
  auto &Root = Input[4];
  Root.methods.erase(Root.methods.begin() + 2);
  Root.interfaces = {Input[0].name};
  Root.generic_signature =
      "<R:Ljava/lang/Object;S:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Contract<TR;>;";
  if (NearerSDK) {
    auto Provided = Input[2].methods[0];
    Provided.reference.owner = Input[1].name;
    Provided.generic_signature = "(TP;)TP;";
    Provided.registers = Provided.code_end = 0;
    Provided.instructions.clear();
    Input[1].methods.push_back(Provided);
    Input[2].methods.erase(Input[2].methods.begin());
  }
  return Input;
}

