              "Ljava/lang/Object;Lfixture/Base<Ljava/lang/String;"
              "Ljava/lang/Integer;Ljava/lang/String;>;";
          Worker.methods.back().instructions[0].reference =
              MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
          break;
        case 2:
