        case 6:
          Bridge.instructions[1].registers = {1, 1};
          break;
        case 7:
          Bridge.instructions[3].registers = {0};
          break;
        case 8:
          Bridge.instructions[1].opcode = "invoke-super";
          break;
        case 9:
          Bridge.instructions.insert(Bridge.instructions.begin(),
                                     op(0, "const/4", {0}, int64_t(0)));
          for (size_t I = 0; I < Bridge.instructions.size(); ++I)
            Bridge.instructions[I].pc = I;
          Bridge.code_end = Bridge.instructions.size();
          break;
        case 10:
          Worker.generic_signature =
              "Lfixture/Base<Ljava/lang/Integer;Ljava/lang/String;"
              "Ljava/lang/String;>;";
