std::vector<Class> packageGenericBridgeClasses(bool External, bool Getter) {
  if (!Getter) {
    auto Input = protectedArrayCallbackBridgeClasses(External);
    for (auto &C : Input)
      for (auto &M : C.methods)
        M.access.erase("protected");
    return Input;
  }
  auto Parent = klass("Lfixture/Base;");
  Parent.external = External;
  Parent.access.insert("abstract");
  Parent.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Get = method("get", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Get.reference.owner = Parent.name;
  Get.access = {"abstract"};
  Get.generic_signature = "(Ljava/lang/Object;)TT;";
  auto Set =
      method("set", {"Ljava/lang/Object;", "Ljava/lang/Object;"}, "V", 0, {});
  Set.reference.owner = Parent.name;
  Set.access = {"abstract"};
  Set.generic_signature = "(Ljava/lang/Object;TT;)V";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.reference.owner = Parent.name;
  Init.access = {"constructor"};
  if (External) {
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  Parent.methods = {Get, Set, Init};
  auto Worker = klass("Lfixture/Worker;");
  Worker.superclass = Parent.name;
  Worker.generic_signature = "Lfixture/Base<Ljava/lang/Boolean;>;";
  Get.reference.owner = Worker.name;
  Get.reference.returns = "Ljava/lang/Boolean;";
  Get.access.clear();
  Get.generic_signature.reset();
  Get.registers = 2;
  Get.instructions = {op(0, "const/4", {1}, int64_t(0)),
                      op(1, "return-object", {1})};
  Get.code_end = 2;
  auto GetBridge =
      method("get", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
             {op(0, "invoke-virtual", {0, 1}, {}, Get.reference),
              op(1, "move-result-object", {1}), op(2, "return-object", {1})});
  GetBridge.reference.owner = Worker.name;
  GetBridge.access = {"bridge", "synthetic"};
  Set.reference.owner = Worker.name;
  Set.reference.parameters[1] = "Ljava/lang/Boolean;";
  Set.access.clear();
  Set.generic_signature.reset();
  Set.registers = 3;
  Set.instructions = {op(0, "return-void")};
  Set.code_end = 1;
  auto SetBridge =
      method("set", {"Ljava/lang/Object;", "Ljava/lang/Object;"}, "V", 3,
             {op(0, "check-cast", {2}, {}, std::string("Ljava/lang/Boolean;")),
              op(1, "invoke-virtual", {0, 1, 2}, {}, Set.reference),
              op(2, "return-void")});
  SetBridge.reference.owner = Worker.name;
  SetBridge.access = {"bridge", "synthetic"};
  Init.reference.owner = Worker.name;
  Init.registers = 1;
  Init.instructions = {
      op(0, "invoke-direct", {0}, {}, Parent.methods[2].reference),
      op(1, "return-void")};
  Init.code_end = 2;
  Worker.methods = {Get, GetBridge, Set, SetBridge, Init};
  return {Parent, Worker};
}

TEST(MobileDalvikJava, PackageGenericMethodsKeepOriginalBridgeVisibility) {
  for (bool External : {false, true})
    for (bool Getter : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(::testing::Message()
                       << External << Getter << Link << Reverse);
          auto Input = packageGenericBridgeClasses(External, Getter);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("method_count"),
                    Getter ? (External ? 5 : 8) : (External ? 7 : 11));
          EXPECT_EQ(R.getInteger("projected_method_count"), Getter ? 2 : 3);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          std::string Text;
          for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
            Text += source(R, I);
          if (Getter) {
            EXPECT_NE(Text.find("java.lang.Boolean get(java.lang.Object"),
                      std::string::npos);
            EXPECT_EQ(Text.find("public java.lang.Boolean get("),
                      std::string::npos);
            EXPECT_EQ(Text.find("protected java.lang.Boolean get("),
                      std::string::npos);
          }
        }
}

TEST(MobileDalvikJava, PackageBridgesRejectUnprovenScopesFlagsAndForwarding) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
        SCOPED_TRACE(::testing::Message()
                     << External << Link << " mutation=" << Mutation);
        auto Input = packageGenericBridgeClasses(External, true);
        auto &Parent = Input[0];
        auto &Worker = Input[1];
        if (Mutation == 0)
          Parent.methods[0].access.insert("public");
        else if (Mutation == 1)
          Parent.methods[0].access.insert("protected");
        else if (Mutation == 2) {
          Parent.name = "Lforeign/Base;";
          for (auto &M : Parent.methods)
            M.reference.owner = Parent.name;
          Worker.superclass = Parent.name;
          Worker.generic_signature = "Lforeign/Base<Ljava/lang/Boolean;>;";
          Worker.methods[4].instructions[0].reference =
              Parent.methods[2].reference;
        } else if (Mutation == 3)
          Worker.methods[0].access.insert("private");
        else if (Mutation == 4)
          Worker.methods[1].access.erase("synthetic");
        else if (Mutation == 5)
          Worker.methods[3].instructions[0].reference =
              std::string("Ljava/lang/String;");
        else if (Mutation == 6)
          Worker.methods[3].instructions[1].registers = {0, 2, 2};
        else if (Mutation == 7)
          Worker.methods[1].instructions[0].registers = {1, 1};
        else if (Mutation == 8)
          Worker.generic_signature = "Lfixture/Base<Ljava/lang/String;>;";
        else if (Mutation == 9)
          Worker.methods[1].access.insert("final");
        else if (Mutation == 10) {
          Parent.access = {"public", "abstract", "interface"};
          Parent.methods.resize(2);
          for (auto &M : Parent.methods)
            M.access.insert("public");
          Worker.superclass = "Ljava/lang/Object;";
          Worker.interfaces = {Parent.name};
          Worker.generic_signature =
              "Ljava/lang/Object;Lfixture/Base<Ljava/lang/Boolean;>;";
          Worker.methods[4].instructions[0].reference =
              MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
        } else
          Worker.methods[2].access.insert("protected");
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

