std::vector<Class> protectedScopedVoidClasses(bool External) {
  const std::string Object = "Ljava/lang/Object;", Box = "Lfixture/Box;";
  auto Required = method("insert", {Object, "I", Object}, "V", 0, {});
  Required.access = {"protected", "abstract"};
  Required.generic_signature = "(TT;ITV;)V";
  auto Init = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Base = klass("Lfixture/Base;", {Required, Init});
  Base.access.insert("abstract");
  Base.generic_signature =
      "<T:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.external = External;
  if (External) {
    Base.methods[1].instructions.clear();
    Base.methods[1].registers = Base.methods[1].code_end = 0;
  }
  auto Target =
      method("insert", {Box, "I", Object}, "V", 4, {op(0, "return-void")});
  Target.access = {"protected"};
  Target.generic_signature = "(Lfixture/Box<TE;>;ITE;)V";
  auto Bridge =
      method("insert", {Object, "I", Object}, "V", 5,
             {op(0, "move-object", {0, 2}), op(1, "check-cast", {0}, {}, Box),
              op(2, "invoke-virtual", {1, 0, 3, 4}, {}, Target.reference),
              op(3, "return-void")});
  Bridge.access = {"public", "bridge", "synthetic"};
  Init.instructions[0].reference = MethodRef{Base.name, "<init>", {}, "V"};
  auto Core = klass("Lfixture/Core;", {Target, Bridge, Init});
  Core.access.insert("final");
  Core.superclass = Base.name;
  Core.generic_signature =
      "<E:Ljava/lang/Object;>Lfixture/Base<Lfixture/Box<TE;>;TE;>;";
  auto Value = klass(Box);
  Value.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Value.external = External;
  return {Core, Base, Value};
}

std::vector<Class> protectedScopedResultClasses(bool External, unsigned Shape) {
  auto Input = protectedScopedVoidClasses(External);
  auto &Target = Input[0].methods[0], &Bridge = Input[0].methods[1];
  auto &Required = Input[1].methods[0];
  const std::string Box = "Lfixture/Box;", Object = "Ljava/lang/Object;";
  const bool Getter = Shape == 0, Scalar = Shape == 1, Wildcard = Shape == 3;
  Target.reference.name = Bridge.reference.name = Required.reference.name =
      "read";
  Required.reference.parameters =
      Getter ? std::vector<std::string>{}
             : std::vector<std::string>{Wildcard ? Box : Object};
  Target.reference.parameters =
      Getter ? std::vector<std::string>{} : std::vector<std::string>{Box};
  Bridge.reference.parameters = Required.reference.parameters;
  Target.reference.returns = Scalar ? "I" : Box;
  Required.reference.returns = Bridge.reference.returns = Scalar ? "I" : Object;
  Required.generic_signature = Getter     ? "()TT;"
                               : Scalar   ? "(TT;)I"
                               : Wildcard ? "(Lfixture/Box<+TV;>;)TT;"
                                          : "(TT;)TT;";
  Target.generic_signature = Getter   ? "()Lfixture/Box<TE;>;"
                             : Scalar ? "(Lfixture/Box<TE;>;)I"
                             : Wildcard
                                 ? "(Lfixture/Box<+TE;>;)Lfixture/Box<TE;>;"
                                 : "(Lfixture/Box<TE;>;)Lfixture/Box<TE;>;";
  Target.registers = Getter ? 2 : 3;
  Target.instructions = {op(0, "const/4", {0}, int64_t{0}),
                         op(1, Scalar ? "return" : "return-object", {0})};
  Target.code_end = 2;
  Bridge.registers = Getter ? 2 : 3;
  Bridge.instructions.clear();
  if (!Getter && !Wildcard) {
    Bridge.instructions.push_back(op(0, "move-object", {0, 2}));
    Bridge.instructions.push_back(op(1, "check-cast", {0}, {}, Box));
  }
  Bridge.instructions.push_back(
      op(2, "invoke-virtual",
         Getter ? std::vector<unsigned>{1}
                : std::vector<unsigned>{1, Wildcard ? 2u : 0u},
         {}, Target.reference));
  Bridge.instructions.push_back(
      op(3, Scalar ? "move-result" : "move-result-object", {0}));
  Bridge.instructions.push_back(
      op(4, Scalar ? "return" : "return-object", {0}));
  Bridge.code_end = 5;
  return Input;
}

std::vector<Class> inheritedProtectedScopedProviderClasses(bool External) {
  auto Input = protectedScopedResultClasses(External, 2);
  auto &Provider = Input[0];
  const auto Original = Provider.name;
  Provider.name = "Lfixture/Provider;";
  Provider.access.erase("final");
  Provider.access.insert("abstract");
  Provider.generic_signature =
      "<E:Ljava/lang/Object;C:Lfixture/Box<TE;>;>Lfixture/Base<TC;TE;>;";
  for (auto &M : Provider.methods) {
    M.reference.owner = Provider.name;
    for (auto &I : M.instructions)
      if (auto *R = std::get_if<MethodRef>(&I.reference);
          R && R->owner == Original)
        R->owner = Provider.name;
  }
  Provider.methods[0].generic_signature = "(TC;)Lfixture/Box<TE;>;";
  Input[1].methods[0].reference.returns = "Lfixture/Box;";
  Input[1].methods[0].generic_signature = "(TT;)Lfixture/Box<TV;>;";
  Provider.methods[1].reference.returns = "Lfixture/Box;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{Provider.name, "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Core = klass("Lfixture/Core;", {Init});
  Core.access.insert("final");
  Core.superclass = Provider.name;
  Core.generic_signature =
      "<E:Ljava/lang/Object;>Lfixture/Provider<TE;Lfixture/NarrowBox<TE;>;>;";
  const auto BoxName = Input[2].name;
  Init.reference.owner = BoxName;
  Init.instructions[0].reference =
      MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"};
  if (External) {
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  Input[2].methods.push_back(Init);
  Init.reference.owner = "Lfixture/NarrowBox;";
  Init.instructions = {
      op(0, "invoke-direct", {0}, {}, MethodRef{BoxName, "<init>", {}, "V"}),
      op(1, "return-void")};
  Init.registers = 1;
  Init.code_end = 2;
  auto Narrow = klass(Init.reference.owner, {Init});
  Narrow.superclass = BoxName;
  Narrow.generic_signature = "<T:Ljava/lang/Object;>Lfixture/Box<TT;>;";
  Input.push_back(Core);
  Input.push_back(Narrow);
  return Input;
}

