std::vector<Class> protectedBoundedScopedClasses(bool External,
                                                 bool Interface) {
  auto Input = protectedScopedVoidClasses(External);
  const std::string Bound = "Lfixture/Container;";
  auto Container = klass(Bound);
  Container.external = External;
  Container.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Interface)
    Container.access = {"public", "abstract", "interface"};
  Input[1].generic_signature =
      std::string("<T:") + (Interface ? ":" : "") +
      "Lfixture/Container<TV;>;V:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[1].methods[0].reference.parameters[0] = Bound;
  Input[0].methods[1].reference.parameters[0] = Bound;
  if (Interface) {
    Input[2].interfaces = {Bound};
    *Input[2].generic_signature += "Lfixture/Container<TT;>;";
  } else {
    Input[2].superclass = Bound;
    Input[2].generic_signature =
        "<T:Ljava/lang/Object;>Lfixture/Container<TT;>;";
    auto Init = Input[1].methods[1];
    Init.reference.owner = Container.name;
    Container.methods.push_back(Init);
    Init.reference.owner = Input[2].name;
    if (!External)
      Init.instructions[0].reference = MethodRef{Bound, "<init>", {}, "V"};
    Input[2].methods.push_back(Init);
  }
  Input.push_back(Container);
  return Input;
}

