std::vector<Class> protectedVoidConsumerBridgeClasses(bool External,
                                                      bool Copied) {
  auto Input = protectedScalarArrayBridgeClasses("[I", External);
  auto &Core = Input[0];
  auto &Base = Input[1];
  Core.access.erase("final");
  Core.generic_signature =
      "<E:Ljava/lang/Object;>Lfixture/Base<Lfixture/Event;>;";
  Base.methods[0].reference.returns = "V";
  Base.methods[0].generic_signature = "(TT;)V";
  Base.access.erase("abstract");
  Base.methods[0].access = {"protected"};
  if (!External) {
    Base.methods[0].registers = 2;
    Base.methods[0].instructions = {op(0, "return-void")};
    Base.methods[0].code_end = 1;
  }
  auto &Target = Core.methods[0];
  Target.reference.parameters = {"Lfixture/Event;"};
  Target.reference.returns = "V";
  Target.instructions = {op(0, "return-void")};
  Target.code_end = 1;
  auto &Bridge = Core.methods[1];
  Bridge.reference.returns = "V";
  Bridge.instructions = {
      op(0, "check-cast", {2}, {}, std::string("Lfixture/Event;")),
      op(2, "invoke-virtual", {1, 2}, {}, Target.reference),
      op(5, "return-void")};
  if (Copied)
    Bridge.instructions = {
        op(0, "move-object", {0, 2}),
        op(1, "check-cast", {0}, {}, std::string("Lfixture/Event;")),
        op(3, "invoke-virtual", {1, 0}, {}, Target.reference),
        op(6, "return-void")};
  Bridge.code_end = Bridge.instructions.back().pc + 1;
  auto &Caller = Core.methods[2];
  Caller.reference.returns = "V";
  Caller.instructions = {op(0, "invoke-virtual", {2, 3}, {}, Bridge.reference),
                         op(3, "return-void")};
  Caller.code_end = 4;
  auto Init = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Base.name, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.reference.owner = Core.name;
  Init.access = {"public", "constructor"};
  Core.methods.push_back(Init);
  auto Child = klass("Lfixture/Child;");
  Child.superclass = Core.name;
  Child.generic_signature = "<S:Ljava/lang/Object;>Lfixture/Core<TS;>;";
  Init.reference.owner = Child.name;
  Init.instructions[0].reference = MethodRef{Core.name, "<init>", {}, "V"};
  Child.methods.push_back(Init);
  Input.push_back(std::move(Child));
  Input.push_back(klass("Lfixture/Event;"));
  return Input;
}

