  for (auto *Member : {&Target, &Bridge, &Required}) {
    Member->reference.name = "allocate";
    Member->reference.parameters = {"I"};
    Member->reference.returns = "[" + Member->reference.returns;
  }
  Required.generic_signature = "(I)[TS;";
  Target.registers = 3;
  Target.instructions = {
      op(0, "new-array", {0, 2}, {}, Target.reference.returns),
      op(1, "return-object", {0})};
