std::vector<Class> protectedMixedConsumerClasses(bool External, bool Bounded,
                                                 bool Wide, bool Copied) {
  const std::string Object = "Ljava/lang/Object;",
                    Builder = "Lfixture/Builder;",
                    Special = "Lfixture/Special;", Token = "Lfixture/Token;";
  const auto Erased = Bounded ? Builder : Object;
  std::vector<std::string> Parameters{Token, "I", Erased, "Z"};
  if (Wide) {
    Parameters.push_back("J");
    Parameters.push_back("D");
  }
  auto Required = method("read", Parameters, "V", 0, {});
  Required.access = {"protected", "abstract"};
  Required.generic_signature =
      "(Lfixture/Token;ITB;Z" + std::string(Wide ? "JD" : "") + ")V";
  auto Init = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  if (External) {
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  auto Base = klass("Lfixture/Base;", {Required, Init});
  Base.access.insert("abstract");
  Base.generic_signature = "<B:" + Erased + ">Ljava/lang/Object;";
  Base.external = External;
  auto Target = Required;
  Target.reference.parameters[2] = Special;
  Target.generic_signature.reset();
  Target.access = {"protected"};
  Target.registers = Wide ? 9 : 5;
  Target.instructions = {op(0, "return-void")};
  Target.code_end = 1;
  auto Core = klass("Lfixture/Core;", {Target});
  Core.access.insert("final");
  Core.superclass = Base.name;
  Core.generic_signature = "Lfixture/Base<Lfixture/Special;>;";
  auto Bridge = Required;
  Bridge.reference.owner = Core.name;
  Bridge.generic_signature.reset();
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.registers = Wide ? 10 : 6;
  unsigned PC = 0;
  if (Copied)
    Bridge.instructions.push_back(op(PC++, "move-object", {0, 4}));
  Bridge.instructions.push_back(
      op(PC++, "check-cast", {Copied ? 0u : 4u}, {}, Special));
  if (Copied && Wide)
    Bridge.instructions.push_back(op(PC++, "move-object", {4, 0}));
  std::vector<unsigned> Registers{1, 2, 3, Copied && !Wide ? 0u : 4u, 5};
  if (Wide)
    Registers.insert(Registers.end(), {6, 7, 8, 9});
  Bridge.instructions.push_back(
      op(PC++, Wide ? "invoke-virtual/range" : "invoke-virtual", Registers, {},
         Core.methods[0].reference));
  Bridge.instructions.push_back(op(PC++, "return-void"));
  Bridge.code_end = PC;
  Core.methods.push_back(Bridge);
  auto BuilderClass = klass(Builder), SpecialClass = klass(Special),
       TokenClass = klass(Token);
  BuilderClass.external = TokenClass.external = External;
  SpecialClass.superclass = Builder;
  return {Core, Base, BuilderClass, SpecialClass, TokenClass};
}

