std::vector<Class> protectedArrayGetterClasses(bool External,
                                               const std::string &Array,
                                               bool Final, bool Copied) {
  auto Input = protectedOpenGetterClasses(External, true, Copied);
  auto &Target = Input[0].methods[0];
  auto &Bridge = Input[0].methods[2];
  Input[1].generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[1].methods[0].reference.returns = "Ljava/lang/Object;";
  Input[0].generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Base<" + Array + ">;";
  Target.reference.returns = Array;
  Target.instructions = {op(0, "const/4", {0}, int64_t{0}),
                         op(1, "new-array", {0, 0}, {}, Array),
                         op(2, "return-object", {0})};
  Target.code_end = 3;
  Bridge.reference.returns = "Ljava/lang/Object;";
  for (auto &I : Bridge.instructions) {
    if (I.opcode == "invoke-virtual")
      I.reference = Target.reference;
    else if (I.opcode == "check-cast")
      I.reference = std::string("Ljava/lang/Object;");
  }
  std::vector<Class> Result{Input[0], Input[1]};
  if (Final)
    Result[0].access.insert("final");
  else
    Result.push_back(Input[4]);
  return Result;
}

std::vector<Class>
protectedArrayReferenceResultClasses(bool External, const std::string &Array,
                                     bool Copied) {
  auto Input = protectedArrayGetterClasses(External, Array, true, false);
  auto &Target = Input[0].methods[0];
  auto &Bridge = Input[0].methods[2];
  auto &Required = Input[1].methods[0];
  Input[1].generic_signature =
      "<S:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[0].generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Base<" + Array + "Lfixture/Result;>;";
  Required.reference.parameters =
      Bridge.reference.parameters = {"Ljava/lang/Object;"};
  Required.generic_signature = "(TS;)TR;";
  Target.reference.parameters = {Array};
  Target.reference.returns = "Lfixture/Result;";
  Target.registers = 3;
  Target.instructions = {op(0, "const/4", {0}, int64_t{0}),
                         op(1, "return-object", {0})};
  Target.code_end = 2;
  Bridge.registers = 3;
  Bridge.instructions.clear();
  unsigned PC = 0;
  if (Copied)
    Bridge.instructions.push_back(op(PC++, "move-object", {0, 2}));
  Bridge.instructions.push_back(
      op(PC++, "check-cast", {Copied ? 0u : 2u}, {}, Array));
  Bridge.instructions.push_back(
      op(PC++, "invoke-virtual", {1, Copied ? 0u : 2u}, {}, Target.reference));
  Bridge.instructions.push_back(op(PC++, "move-result-object", {0}));
  Bridge.instructions.push_back(op(PC++, "return-object", {0}));
  Bridge.code_end = PC;
  Input.push_back(klass("Lfixture/Result;"));
  return Input;
}

