std::vector<Class> protectedScopedArrayReturnClasses(bool External,
                                                     unsigned Rank,
                                                     bool FixedParameter) {
  auto Input = protectedScopedArrayResultClasses(External, Rank, false);
  const std::string Array =
      Rank ? std::string(Rank, '[') + "Ljava/lang/Object;" : "[I";
  const std::string ScopedArray = Rank ? std::string(Rank, '[') + "TT;" : "[I";
  Input[0].generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Base<Lfixture/Result<TT;>;" +
      ScopedArray + ">;";
  auto &Target = Input[0].methods[0];
  auto &Bridge = Input[0].methods[2];
  auto &Required = Input[1].methods[0];
  Target.reference.parameters = {"Lfixture/Result;"};
  Target.reference.returns = Array;
  Target.generic_signature = "(Lfixture/Result<TT;>;)" + ScopedArray;
  Bridge.instructions[1].reference = std::string("Lfixture/Result;");
  Bridge.instructions[2].reference = Target.reference;
  if (FixedParameter) {
    Input[0].generic_signature =
        "<T:Ljava/lang/Object;>Lfixture/Base<TT;" + ScopedArray + ">;";
    Required.reference.parameters = Bridge.reference.parameters =
        Target.reference.parameters;
    Required.generic_signature = "(Lfixture/Result<TS;>;)TR;";
    Bridge.instructions.erase(Bridge.instructions.begin() + 1);
    for (size_t i = 0; i < Bridge.instructions.size(); ++i)
      Bridge.instructions[i].pc = i;
    Bridge.code_end = Bridge.instructions.size();
  }
  return Input;
}

