std::vector<Class> protectedGenericResultClasses(bool External, bool Anonymous,
                                                 bool Cast) {
  const std::string Owner = Anonymous ? "Lfixture/Host$1;" : "Lfixture/Core;";
  const std::string Fn = "Lfixture/Fn;", Error = "Ljava/lang/Throwable;";
  const std::string Full =
      "Lfixture/Fn<-Ljava/lang/Throwable;+Ljava/lang/Throwable;>;";
  auto Abstract =
      method("compute", {"Ljava/lang/Class;"}, "Ljava/lang/Object;", 0, {});
  Abstract.access = {"protected", "abstract"};
  Abstract.generic_signature = "(Ljava/lang/Class<*>;)TS;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Base = klass("Lfixture/Base;", {Abstract, Init});
  Base.access.insert("abstract");
  Base.generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.external = External;
  if (External) {
    Base.methods[1].instructions.clear();
    Base.methods[1].registers = Base.methods[1].code_end = 0;
  }
  auto Target =
      method("compute", {"Ljava/lang/Class;"}, Fn, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.access = {"protected"};
  Target.generic_signature =
      "(Ljava/lang/Class<*>;)"
      "Lfixture/Fn<Ljava/lang/Throwable;Ljava/lang/Throwable;>;";
  Init.instructions[0].reference = Base.methods[1].reference;
  auto Core = klass(Owner, {Target, Init});
  Core.access.insert("final");
  Core.superclass = Base.name;
  Core.generic_signature = "Lfixture/Base<" + Full + ">;";
  auto Bridge =
      method("compute", {"Ljava/lang/Class;"}, "Ljava/lang/Object;", 3,
             {op(0, "invoke-virtual", {1, 2}, {}, Core.methods[0].reference),
              op(1, "move-result-object", {0})});
  Bridge.reference.owner = Owner;
  Bridge.access = {"public", "bridge", "synthetic"};
  if (Cast)
    Bridge.instructions.push_back(
        op(2, "check-cast", {0}, {}, std::string("Ljava/lang/Object;")));
  Bridge.instructions.push_back(
      op(Bridge.instructions.size(), "return-object", {0}));
  Bridge.code_end = Bridge.instructions.size();
  Core.methods.push_back(Bridge);
  auto Function = klass(Fn);
  Function.external = true;
  Function.access = {"public", "interface", "abstract"};
  Function.generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Apply =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Apply.reference.owner = Fn;
  Apply.access = {"public", "abstract"};
  Apply.generic_signature = "(TA;)TR;";
  Function.methods.push_back(Apply);
  auto Make =
      method("make", {}, Base.name, 1,
             {op(0, "new-instance", {0}, {}, Owner),
              op(1, "invoke-direct", {0}, {}, Core.methods[1].reference),
              op(2, "return-object", {0})});
  Make.generic_signature = "()Lfixture/Base<" + Full + ">;";
  auto Host = klass("Lfixture/Host;", {Make});
  if (Anonymous) {
    Core.inner_class_present = true;
    Core.inner_access = {"public", "static", "final"};
    Core.enclosing = Host.name;
    Core.methods[1].access = {"constructor"};
  }
  auto ClassType = klass("Ljava/lang/Class;");
  ClassType.external = true;
  ClassType.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Throwable = klass(Error);
  Throwable.external = true;
  return {Core, Base, Function, Host, ClassType, Throwable};
}

