std::vector<Class> plainDependencyDefaultAncestorClasses(bool External = true) {
  auto Contract = klass("Lfixture/Contract;");
  Contract.access = {"public", "interface", "abstract"};
  Contract.external = true;
  Contract.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Accept = method("accept", {"Ljava/lang/Object;"}, "V", 0, {});
  Accept.reference.owner = Contract.name;
  Accept.access = {"public", "abstract"};
  Accept.generic_signature = "(TE;)V";
  auto Compose = method("compose", {Contract.name}, Contract.name, 0, {});
  Compose.reference.owner = Contract.name;
  Compose.access = {"public"};
  Compose.generic_signature =
      "(Lfixture/Contract<-TE;>;)Lfixture/Contract<TE;>;";
  Contract.methods = {Accept, Compose};
  auto Parent = klass("Lfixture/State;");
  Parent.external = External;
  Parent.interfaces = {"Lfixture/Marker;"};
  auto Init = method("<init>", {}, "V", 0, {});
  Init.reference.owner = Parent.name;
  Init.access = {"public", "constructor"};
  auto State = method("state", {}, "Z", 0, {});
  State.reference.owner = Parent.name;
  State.access = {"public", "final"};
  auto Text = method("toString", {}, "Ljava/lang/String;", 0, {});
  Text.reference.owner = Parent.name;
  Text.access = {"public"};
  Parent.methods = {Init, State, Text};
  if (!External) {
    auto &Ctor = Parent.methods[0];
    Ctor.registers = 1;
    Ctor.instructions = {op(0, "invoke-direct", {0}, {},
                            MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                         op(1, "return-void")};
    Ctor.code_end = 2;
    Parent.methods[1].registers = 2;
    Parent.methods[1].instructions = {op(0, "const/4", {0}, int64_t(0)),
                                      op(1, "return", {0})};
    Parent.methods[1].code_end = 2;
    Parent.methods[2].registers = 2;
    Parent.methods[2].instructions = {
        op(0, "const-string", {0}, std::string("owned parent")),
        op(1, "return-object", {0})};
    Parent.methods[2].code_end = 2;
  }
  auto Marker = klass("Lfixture/Marker;");
  Marker.external = true;
  Marker.access = {"public", "abstract", "interface"};
  auto Worker = klass("Lfixture/Worker;");
  Worker.superclass = Parent.name;
  Worker.interfaces = {Contract.name};
  Worker.generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/State;Lfixture/Contract<TT;>;";
  Init.reference.owner = Worker.name;
  Init.registers = 1;
  Init.instructions = {
      op(0, "invoke-direct", {0}, {}, Parent.methods[0].reference),
      op(1, "return-void")};
  Init.code_end = 2;
  Accept.reference.owner = Worker.name;
  Accept.access = {"public"};
  Accept.generic_signature = "(TT;)V";
  Accept.registers = 2;
  Accept.instructions = {op(0, "return-void")};
  Accept.code_end = 1;
  Text.reference.owner = Worker.name;
  Text.registers = 2;
  Text.instructions = {op(0, "const-string", {0}, std::string("owned state")),
                       op(1, "return-object", {0})};
  Text.code_end = 2;
  Worker.methods = {Init, Accept, Text};
  return {Contract, Parent, Marker, Worker};
}

std::vector<Class> plainAncestorWithMemberSignatures(bool External) {
  auto Input = plainDependencyDefaultAncestorClasses(External);
  auto &Parent = Input[1];
  auto &Child = Input[3];
  const auto Contract = Input[0].name;
  const std::string Full = "Lfixture/Contract<Ljava/lang/String;>;";
  auto Meta =
      method("metadata", {}, Contract, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Meta.reference.owner = Parent.name;
  Meta.access = {"public"};
  Meta.generic_signature = "()" + Full;
  if (External) {
    Meta.instructions.clear();
    Meta.registers = Meta.code_end = 0;
  }
  Parent.methods.push_back(Meta);
  auto View = klass("Lfixture/View;");
  View.external = External;
  View.access = {"public", "abstract", "interface"};
  Meta.reference.owner = View.name;
  Meta.access = {"public", "abstract"};
  Meta.instructions.clear();
  Meta.registers = Meta.code_end = 0;
  View.methods.push_back(Meta);
  Parent.interfaces.push_back(View.name);
  auto PlainCtor = Parent.methods[0];
  auto &Ctor = Parent.methods[0];
  Ctor.reference.parameters = {Contract};
  Ctor.generic_signature = "(" + Full + ")V";
  if (!External) {
    Ctor.registers = 2;
    Ctor.instructions[0].registers = {0};
  }
  Child.methods[0].instructions[0].reference = PlainCtor.reference;
  auto Echo = method("echo", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                     {op(0, "return-object", {1})});
  Echo.reference.owner = Parent.name;
  Echo.access = {"public"};
  Echo.generic_signature = "<M:Ljava/lang/Object;>(TM;)TM;";
  if (External) {
    Echo.instructions.clear();
    Echo.registers = Echo.code_end = 0;
  }
  Parent.methods.push_back(Echo);
  Parent.methods.push_back(PlainCtor);
  if (!External)
    Parent.access.insert("abstract");
  Input.push_back(View);
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.reference.owner = Object.name;
  ObjectInit.access = {"public", "constructor"};
  Object.methods.push_back(ObjectInit);
  Input.push_back(Object);
  return Input;
}

