std::vector<Class> nestedPlainDefaultAncestorClasses(bool External,
                                                     bool PlainOwner) {
  auto Input = plainDependencyDefaultAncestorClasses(External);
  auto &Api = Input[0];
  Api.external = false;
  Api.generic_signature.reset();
  auto Echo = method("echo", {"Lfixture/Box;", "Lfixture/Value;"},
                     "Lfixture/Value;", 3, {op(0, "return-object", {2})});
  Echo.reference.owner = Api.name;
  Echo.access = {"public"};
  Echo.generic_signature = "<M:Lfixture/Value;>(Lfixture/Box<TM;>;TM;)TM;";
  Api.methods = {Echo};
  auto &Parent = Input[1];
  Parent.name = "Lfixture/Owner$State;";
  Parent.interfaces.clear();
  Parent.enclosing = "Lfixture/Owner;";
  Parent.inner_class_present = true;
  Parent.inner_name = "State";
  Parent.inner_access = {"public", "static"};
  for (auto &Member : Parent.methods)
    Member.reference.owner = Parent.name;
  auto &Worker = Input[3];
  Worker.superclass = Parent.name;
  Worker.methods.erase(Worker.methods.begin() + 1);
  Worker.methods[0].instructions[0].reference = Parent.methods[0].reference;
  Worker.generic_signature =
      "<T:Ljava/lang/Object;>Lfixture/Owner$State;Lfixture/Contract;";
  if (PlainOwner)
    Worker.generic_signature.reset();
  auto Owner = klass(*Parent.enclosing);
  Owner.external = External;
  Owner.generic_signature = "<O:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Value = klass("Lfixture/Value;");
  Value.external = true;
  Input.push_back(std::move(Owner));
  Input.push_back(std::move(Box));
  Input.push_back(std::move(Value));
  return Input;
}

