std::vector<Class> plainDefaultClassChainClasses(bool External, bool PlainOwner,
                                                 unsigned Depth) {
  auto Input = nestedPlainDefaultAncestorClasses(false, PlainOwner);
  auto &Marker = Input[2];
  auto RootState = method("rootState", {}, "I", 0, {});
  RootState.reference.owner = Marker.name;
  RootState.access = {"public", "abstract"};
  Marker.methods = {RootState};
  const auto MarkerName = Marker.name;
  for (unsigned I = 0; I < Depth; ++I) {
    auto Root = klass("Lfixture/Root" + std::to_string(I) + ";");
    Root.external = External;
    Root.superclass = I + 1 == Depth
                          ? "Ljava/lang/Object;"
                          : "Lfixture/Root" + std::to_string(I + 1) + ";";
    if (I + 1 == Depth)
      Root.interfaces = {MarkerName};
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{*Root.superclass, "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.reference.owner = Root.name;
    Init.access = {"public", "constructor"};
    auto Identity = Input[0].methods[0];
    Identity.reference.owner = Root.name;
    Identity.reference.name = "identity";
    Identity.generic_signature =
        "<N:Lfixture/Value;>(Lfixture/Box<TN;>;TN;)TN;";
    auto State = RootState;
    State.reference.owner = Root.name;
    State.access = {"public"};
    State.registers = 2;
    State.instructions = {op(0, "const/4", {0}, int64_t(3)),
                          op(1, "return", {0})};
    State.code_end = 2;
    Root.methods = {Init, Identity, State};
    if (External)
      for (auto &Member : Root.methods) {
        Member.instructions.clear();
        Member.registers = Member.code_end = 0;
      }
    Input.push_back(std::move(Root));
  }
  Input[1].superclass = Input[7].name;
  Input[1].methods[0].instructions[0].reference = Input[7].methods[0].reference;
  return Input;
}

