std::vector<Class> plainClassChainThrowsClasses(bool External, bool PlainOwner,
                                                bool Empty) {
  auto Input = plainDefaultClassChainClasses(External, PlainOwner, 1);
  const std::vector<std::string> Failures{"Lfixture/Failure;",
                                          "Lfixture/OtherFailure;"};
  Input[2].methods[0].declared_throws = Failures;
  Input[7].methods[2].declared_throws = Failures;
  auto Override = Input[7].methods[2];
  Override.reference.owner = Input[3].name;
  Override.registers = 2;
  Override.instructions = {op(0, "const/4", {0}, int64_t(3)),
                           op(1, "return", {0})};
  Override.code_end = 2;
  Override.declared_throws =
      Empty ? std::vector<std::string>{}
            : std::vector<std::string>{Failures[1], Failures[0]};
  Input[3].methods.push_back(std::move(Override));
  for (const auto &Name : Failures) {
    auto Failure = klass(Name);
    Failure.external = true;
    Failure.superclass = "Ljava/lang/Exception;";
    Input.push_back(std::move(Failure));
  }
  return Input;
}

