std::vector<Class> fixedDependencyClassPrefixClasses() {
  auto Base = klass("Lfixture/Base;");
  Base.external = true;
  Base.access.insert("abstract");
  Base.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 0, {});
  Init.reference.owner = Base.name;
  Init.access = {"public", "constructor"};
  auto Item = method("item", {}, "Ljava/lang/Object;", 0, {});
  Item.reference.owner = Base.name;
  Item.access = {"public", "abstract"};
  Item.generic_signature = "()TT;";
  Base.methods = {Init, Item};
  auto Fixed = klass("Lfixture/Fixed;");
  Fixed.external = true;
  Fixed.access.insert("abstract");
  Fixed.superclass = Base.name;
  Fixed.generic_signature = "Lfixture/Base<Ljava/lang/String;>;";
  Init.reference.owner = Fixed.name;
  Fixed.methods = {Init};
  auto Widget = klass("Lfixture/Widget;");
  Widget.external = true;
  Widget.superclass = Fixed.name;
  Init.reference.owner = Widget.name;
  Item.reference.owner = Widget.name;
  Item.reference.returns = "Ljava/lang/String;";
  Item.generic_signature.reset();
  Item.access = {"public"};
  auto Touch = method("touch", {"Ljava/lang/Object;"}, "V", 0, {});
  Touch.reference.owner = Widget.name;
  Touch.access = {"protected"};
  Widget.methods = {Init, Item, Touch};
  auto Api = klass("Lfixture/Api;");
  Api.external = true;
  Api.access = {"public", "abstract", "interface"};
  auto Accept = method("accept", {Base.name, "Ljava/lang/Object;"}, "V", 0, {});
  Accept.reference.owner = Api.name;
  Accept.access = {"public", "abstract"};
  Accept.generic_signature = "(Lfixture/Base<*>;Ljava/lang/Object;)V";
  Api.methods = {Accept};
  auto Reader = klass("Lfixture/Reader;");
  Reader.superclass = Widget.name;
  Reader.interfaces = {Api.name};
  Init.reference.owner = Reader.name;
  Init.registers = 1;
  Init.instructions = {
      op(0, "invoke-direct", {0}, {}, Widget.methods[0].reference),
      op(1, "return-void")};
  Init.code_end = 2;
  Accept.reference.owner = Reader.name;
  Accept.access = {"public"};
  Accept.generic_signature.reset();
  Accept.registers = 3;
  Accept.instructions = {op(0, "return-void")};
  Accept.code_end = 1;
  Touch.reference.owner = Reader.name;
  Touch.registers = 2;
  Touch.instructions = {op(0, "return-void")};
  Touch.code_end = 1;
  Reader.methods = {Init, Accept, Touch};
  return {Base, Fixed, Widget, Api, Reader};
}

std::vector<Class> abstractFixedDependencyPrefixClasses(bool Marker,
                                                        bool SecondPrefix) {
  auto Input = fixedDependencyClassPrefixClasses();
  auto Prefix = klass("Lfixture/Prefix;", {Input[2].methods[0]});
  Prefix.external = true;
  Prefix.access.insert("abstract");
  Prefix.superclass = Input[2].name;
  if (Marker) {
    auto Tag = klass("Lfixture/Tag;");
    Tag.external = true;
    Tag.access = {"public", "abstract", "interface"};
    Prefix.interfaces = {Tag.name};
    Input.push_back(Tag);
  }
  const auto PrefixName = Prefix.name;
  Input.push_back(Prefix);
  if (SecondPrefix) {
    Prefix.name = "Lfixture/OuterPrefix;";
    Prefix.superclass = PrefixName;
    for (auto &Member : Prefix.methods)
      Member.reference.owner = Prefix.name;
    Input.push_back(Prefix);
  }
  Input[4].superclass = Prefix.name;
  Input[4].methods[0].instructions[0].reference =
      MethodRef{Prefix.name, "<init>", {}, "V"};
  return Input;
}

