TEST(MobileDalvikJava, FixedDependencyClassPrefixesRejectIncompleteContracts) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 17; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = fixedDependencyClassPrefixClasses();
      if (Mutation == 0)
        Input[1].generic_signature.reset();
      else if (Mutation == 1)
        Input[1].generic_signature =
            "Lfixture/Base<Ljava/lang/String;Ljava/lang/String;>;";
      else if (Mutation == 2)
        Input[1].superclass = "Lfixture/Missing;";
      else if (Mutation == 3)
        Input[1].superclass = Input[2].name;
      else if (Mutation == 4)
        Input[1].external = false;
      else if (Mutation == 5)
        Input[2].methods.back().access.insert("final");
      else if (Mutation == 6)
        Input[4].methods.back().access.insert("static");
      else if (Mutation == 7)
        Input[4].methods.back().access = {"private"};
      else if (Mutation == 8)
        Input[1].generic_signature = "Lfixture/Base<+Ljava/lang/String;>;";
      else if (Mutation == 9 || Mutation == 15) {
        auto Bad = Input[0].methods[1];
        Bad.reference.owner = Input[4].name;
        Bad.access = {"public"};
        Bad.generic_signature.reset();
        if (Mutation == 15)
          Bad.reference.returns = "Ljava/lang/String;";
        Bad.registers = 2;
        Bad.instructions = {op(0, "const/4", {0}, int64_t(0)),
                            op(1, "return-object", {0})};
        Bad.code_end = 2;
        Input[4].methods.push_back(std::move(Bad));
      } else if (Mutation == 10)
        Input[2].access.insert("abstract");
      else if (Mutation == 11)
        Input[2].generic_signature = "<U:Ljava/lang/Object;>Lfixture/Fixed;";
      else if (Mutation == 12)
        Input[2].interfaces = {"Lfixture/Unknown;"};
      else if (Mutation == 13)
        Input[2].interfaces = {Input[0].name};
      else if (Mutation == 14)
        Input[2].methods.erase(Input[2].methods.begin());
      else if (Mutation == 16) {
        Input[0].generic_signature.reset();
        Input[0].methods[1].generic_signature.reset();
        Input[1].generic_signature.reset();
        auto Box = klass("Lfixture/Box;");
        Box.external = true;
        Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
        Input[3].methods[0].reference.parameters[0] = Box.name;
        Input[3].methods[0].generic_signature =
            "(Lfixture/Box<*>;Ljava/lang/Object;)V";
        Input[4].methods[1].reference.parameters[0] = Box.name;
        Input.push_back(std::move(Box));
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> plainAbstractDependencyParentClasses() {
  auto Input = fixedDependencyClassPrefixClasses();
  Input[0].generic_signature.reset();
  Input[0].methods[1].generic_signature.reset();
  Input[1].generic_signature.reset();
  Input[2].access.insert("abstract");
  auto &Item = Input[2].methods[1];
  Item.reference.returns = "Ljava/lang/Object;";
  Item.access = {"public", "abstract"};
  auto ConcreteTouch = Input[2].methods[2];
  ConcreteTouch.reference.owner = Input[0].name;
  Input[0].methods.push_back(ConcreteTouch);
  Input[2].methods[2].access.insert("abstract");
  auto Provided = Item;
  Provided.reference.owner = Input[4].name;
  Provided.access = {"public"};
  Provided.registers = 2;
  Provided.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
  Provided.code_end = 2;
  Input[4].methods.push_back(Provided);
  auto Identity =
      method("identity", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Identity.reference.owner = Input[0].name;
  Identity.access = {"public"};
  Identity.generic_signature = "<M:Ljava/lang/Object;>(TM;)TM;";
  Input[0].methods.push_back(Identity);
  Identity.reference.owner = Input[4].name;
  Identity.generic_signature = "<N:Ljava/lang/Object;>(TN;)TN;";
  Identity.registers = 2;
  Identity.instructions = {op(0, "return-object", {1})};
  Identity.code_end = 1;
  Input[4].methods.push_back(Identity);
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[3].methods[0].reference.parameters[0] = Box.name;
  Input[3].methods[0].generic_signature =
      "(Lfixture/Box<*>;Ljava/lang/Object;)V";
  Input[4].methods[1].reference.parameters[0] = Box.name;
  Input.push_back(std::move(Box));
  return Input;
}

