TEST(MobileDalvikJava, PlainAbstractDependencyParentsRequireCompleteProviders) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = plainAbstractDependencyParentClasses();
      auto &Child = Input[4];
      if (Mutation == 0)
        Child.methods.erase(Child.methods.begin() + 2);
      else if (Mutation == 1)
        Child.methods[2].access = {"private"};
      else if (Mutation == 2)
        Child.methods[2].access.insert("static");
      else if (Mutation == 3) {
        // A concrete class cannot retain an abstract declaration.
        Child.methods[2].access.insert("abstract");
        Child.methods[2].instructions.clear();
        Child.methods[2].registers = Child.methods[2].code_end = 0;
      } else if (Mutation == 4)
        Child.methods[2].generic_signature = "<M:Ljava/lang/Object;>(TM;)V";
      else if (Mutation == 5)
        Child.methods[3].reference.returns = "Ljava/lang/String;";
      else if (Mutation == 6)
        Child.methods[2].declared_throws = {"Ljava/lang/Throwable;"};
      else if (Mutation == 7)
        Child.methods.back().generic_signature =
            "<N:Ljava/lang/Object;Q:Ljava/lang/Object;>(TN;)TN;";
      else if (Mutation == 8)
        Input[1].superclass = "Lfixture/Unknown;";
      else
        Input[0].superclass = Input[2].name;
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> plainDeferredAbstractParentClasses(bool SourceParent,
                                                      bool Redeclare) {
  auto Input = plainAbstractDependencyParentClasses();
  auto &Parent = Input[2];
  if (SourceParent) {
    Parent.external = false;
    auto &Init = Parent.methods[0];
    Init.registers = 1;
    Init.instructions = {
        op(0, "invoke-direct", {0}, {}, Input[1].methods[0].reference),
        op(1, "return-void")};
    Init.code_end = 2;
  }
  auto &Child = Input[4];
  Child.access.insert("abstract");
  if (Redeclare) {
    for (unsigned Index : {2U, 3U}) {
      auto &Declaration = Child.methods[Index];
      Declaration.access.insert("abstract");
      Declaration.instructions.clear();
      Declaration.registers = Declaration.code_end = 0;
    }
  } else {
    Child.methods.erase(Child.methods.begin() + 3);
    Child.methods.erase(Child.methods.begin() + 2);
  }
  return Input;
}

