std::vector<Class> rawClassFormalInterfaceClasses() {
  auto Compare = method("compare", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                        "I", 0, {});
  Compare.access = {"public", "abstract"};
  Compare.generic_signature = "(TE;TE;)I";
  auto Api = klass("Lfixture/Order;", {Compare});
  Api.external = true;
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Compare.access = {"public", "final"};
  Compare.generic_signature = "(TT;TT;)I";
  Compare.registers = 3;
  Compare.instructions = {op(0, "const/4", {0}, int64_t(0)),
                          op(1, "return", {0})};
  Compare.code_end = 2;
  auto Reader = klass("Lfixture/OrderImpl;", {Init, Compare});
  Reader.access = {"public", "final"};
  Reader.interfaces = {Api.name};
  Reader.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Order;";
  return {Api, Reader};
}

TEST(MobileDalvikJava, RawInterfacesRecoverUniqueOwnedClassFormalArguments) {
  for (bool Link : {false, true})
    for (bool Reverse : {false, true}) {
      auto Input = rawClassFormalInterfaceClasses();
      if (Reverse) {
        for (auto &Owner : Input)
          std::reverse(Owner.methods.begin(), Owner.methods.end());
        std::reverse(Input.begin(), Input.end());
      }
      Budget B;
      llvm::json::Object R;
      ASSERT_NO_THROW(R = Link ? recoverJava(linkClasses(Input, B), B)
                               : recover(Input));
      EXPECT_EQ(R.getInteger("class_count"), 1);
      EXPECT_EQ(R.getInteger("method_count"), 2);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getString("status"), "partial");
      EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      const auto *Rows = R.getArray("generic_signature_projections");
      ASSERT_TRUE(Rows);
      ASSERT_EQ(Rows->size(), 1u);
      const auto *Row = (*Rows)[0].getAsObject();
      ASSERT_TRUE(Row);
      EXPECT_EQ(Row->getString("declaration"), "Lfixture/OrderImpl;");
      EXPECT_EQ(Row->getString("original_signature"),
                "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Order;");
      const auto *Changes = Row->getArray("changes");
      ASSERT_TRUE(Changes);
      ASSERT_EQ(Changes->size(), 1u);
      const auto *Change = (*Changes)[0].getAsObject();
      ASSERT_TRUE(Change);
      EXPECT_EQ(Change->getString("kind"), "raw-interface-owned-class-formal");
      EXPECT_EQ(Change->getString("original_type"), "Lfixture/Order;");
      EXPECT_EQ(Change->getString("source_type"), "Lfixture/Order<TT;>;");
      EXPECT_EQ(Change->getString("scope_origin"),
                "Lfixture/OrderImpl;->compare(Ljava/lang/Object;Ljava/lang/"
                "Object;)I");
      EXPECT_NE(source(R).find("fixture.Order<T>"), std::string::npos);
    }
}

