std::vector<Class> rawCapturedFormalInterfaceClasses(bool Dependency) {
  auto Input = capturedInnerClasses();
  Input[0].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Reader = Input[1];
  auto Api = rawClassFormalInterfaceClasses()[0];
  Api.external = Dependency;
  Reader.interfaces = {Api.name};
  Reader.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Order;";
  auto Compare = rawClassFormalInterfaceClasses()[1].methods[1];
  Compare.reference.owner = Reader.name;
  Reader.methods.push_back(Compare);
  Input.push_back(std::move(Api));
  return Input;
}

TEST(MobileDalvikJava, RawInterfacesUseExactCapturedAndOwnedFieldScopes) {
  for (bool Dependency : {false, true})
    for (bool Captured : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(Dependency);
          SCOPED_TRACE(Captured);
          SCOPED_TRACE(Link);
          SCOPED_TRACE(Reverse);
          auto Input = Captured ? rawCapturedFormalInterfaceClasses(Dependency)
                                : rawClassFormalInterfaceClasses();
          if (!Captured) {
            Input[0].external = Dependency;
            Input[1].fields.push_back(
                {{Input[1].name, "state", "I"}, {"public"}, {}});
          }
          if (Reverse) {
            for (auto &Owner : Input)
              std::reverse(Owner.methods.begin(), Owner.methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          Budget B;
          llvm::json::Object R;
          ASSERT_NO_THROW(R = Link ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input));
          EXPECT_EQ(R.getInteger("class_count"),
                    (Captured ? 3 : 2) - Dependency);
          EXPECT_EQ(R.getInteger("method_count"), 3 - Dependency);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          const auto *Rows = R.getArray("generic_signature_projections");
          ASSERT_TRUE(Rows);
          bool Argument = false;
          for (const auto &Value : *Rows)
            for (const auto &Change :
                 *Value.getAsObject()->getArray("changes")) {
              const auto Kind = Change.getAsObject()->getString("kind");
              Argument |=
                  Kind == (Captured ? "raw-interface-captured-formal"
                                    : "raw-interface-owned-class-formal");
            }
          EXPECT_TRUE(Argument);
        }
}

