TEST(MobileDalvikJava, OwnedDependencyMethodFormalsRequireExactContracts) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 11; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = ownedDependencyMethodFormalClasses();
      auto &Target = Input[4].methods.back();
      if (Mutation == 0)
        Target.generic_signature =
            "<N::Lfixture/Mark;>(Lfixture/Box<Lfixture/Mark;>;)TN;";
      else if (Mutation == 1)
        Target.generic_signature =
            "<N::Lfixture/Mark;>(Lfixture/Box<TN;>;)Lfixture/Mark;";
      else if (Mutation == 2)
        Target.generic_signature =
            "<N::Lfixture/Mark;Q:Ljava/lang/Object;>(Lfixture/Box<TN;>;)TN;";
      else if (Mutation == 3)
        Target.access.insert("static");
      else if (Mutation == 4)
        Target.access = {"private"};
      else if (Mutation == 5)
        Target.declared_throws = {"Ljava/lang/Throwable;"};
      else if (Mutation == 6)
        Input[3].methods.back().generic_signature =
            "<M::Lfixture/Mark;>(Lfixture/Box<TM;>;)TM;^Ljava/lang/Throwable;";
      else if (Mutation == 7)
        Target.generic_signature.reset();
      else {
        Input[3].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
        if (Mutation == 9) {
          auto Inherited = Target;
          Inherited.reference.owner = Input[0].name;
          Inherited.instructions.clear();
          Inherited.registers = 0;
          Inherited.code_end = 0;
          Input[0].methods.push_back(std::move(Inherited));
          Input[4].methods.pop_back();
        } else if (Mutation == 10) {
          Input[3].methods.erase(Input[3].methods.end() - 2);
          Input[4].methods.pop_back();
          Input[4].methods[1].generic_signature =
              "(Lfixture/Box<Lfixture/Mark;>;Ljava/lang/Object;)V";
        }
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> plainCovariantDependencyClassClasses() {
  auto Input = plainAbstractDependencyParentClasses();
  auto Value = klass("Lfixture/Value;");
  Value.external = true;
  auto Narrow = klass("Lfixture/Narrow;");
  Narrow.external = true;
  Narrow.superclass = Value.name;
  for (bool Protected : {false, true}) {
    auto Required =
        method(Protected ? "defaultValue" : "makeValue",
               Protected ? std::vector<std::string>{}
                         : std::vector<std::string>{"Ljava/lang/Object;"},
               Value.name, 0, {});
    Required.reference.owner = Input[2].name;
    Required.access =
        Protected ? Access{"protected"} : Access{"public", "abstract"};
    Input[2].methods.push_back(Required);
    auto Target = Required;
    Target.reference.owner = Input[4].name;
    Target.reference.returns = Narrow.name;
    Target.access = Protected ? Access{"protected"} : Access{"public"};
    Target.registers = Protected ? 2 : 3;
    Target.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
    Target.code_end = 2;
    Input[4].methods.push_back(Target);
    auto Bridge = Required;
    Bridge.reference.owner = Input[4].name;
    Bridge.access = Protected ? Access{"protected", "bridge", "synthetic"}
                              : Access{"public", "bridge", "synthetic"};
    Bridge.registers = Target.registers;
    Bridge.instructions = {
        op(0, "invoke-virtual",
           Protected ? std::vector<unsigned>{1} : std::vector<unsigned>{1, 2},
           {}, Target.reference),
        op(1, "move-result-object", {0}), op(2, "return-object", {0})};
    Bridge.code_end = 3;
    Input[4].methods.push_back(Bridge);
  }
  Input.push_back(Value);
  Input.push_back(Narrow);
  return Input;
}

