std::vector<Class> abstractClassCovariantDeclarations(bool External) {
  auto Identity =
      method("identity", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Identity.access = {"public", "abstract"};
  Identity.generic_signature = "<T:Ljava/lang/Object;>(TT;)TT;";
  auto Api = klass("Lfixture/Api;", {Identity});
  Api.access = {"public", "abstract", "interface"};
  Api.external = External;
  auto Get = method("get", {"Ljava/lang/Object;"}, "Lfixture/Root;", 0, {});
  Get.access = {"public", "abstract"};
  auto Protected = method("protectedGet", {}, "Lfixture/Root;", 0, {});
  Protected.access = {"protected", "abstract"};
  auto Root = klass("Lfixture/Root;", {Get, Protected});
  Root.access = {"public", "abstract"};
  Root.external = External;
  Get.reference.returns = Protected.reference.returns = "Lfixture/Middle;";
  Identity.generic_signature = "<U:Ljava/lang/Object;>(TU;)TU;";
  auto Middle = klass("Lfixture/Middle;", {Get, Protected, Identity});
  Middle.access = {"public", "abstract"};
  Middle.superclass = Root.name;
  Middle.interfaces = {Api.name};
  return {Api, Root, Middle};
}

