std::vector<Class>
abstractBoundedParameterClasses(bool External, bool Protected,
                                bool InterfaceBound,
                                bool ConcreteParent = false) {
  auto Container = klass("Lfixture/Container;");
  Container.generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
  if (InterfaceBound)
    Container.access = {"public", "abstract", "interface"};
  Container.external = External;
  auto Read = method(
      "read", {"Ljava/lang/String;", "I", "Ljava/lang/Object;", "J", "Z"}, "V",
      0, {});
  Read.access = {Protected ? "protected" : "public", "abstract"};
  Read.generic_signature = "(Ljava/lang/String;ITB;JZ)V";
  auto Root = klass("Lfixture/Root;", {Read});
  Root.access = {"public", "abstract"};
  Root.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  Root.external = External;
  auto Parent = klass("Lfixture/Parent;");
  Parent.access = {"public", "abstract"};
  Parent.superclass = Root.name;
  Parent.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Lfixture/Root<TX;TY;>;";
  Parent.external = External;
  if (ConcreteParent) {
    auto Body = Read;
    Body.reference.owner = Parent.name;
    Body.generic_signature = "(Ljava/lang/String;ITY;JZ)V";
    Body.access.erase("abstract");
    if (!External) {
      Body.registers = 7;
      Body.instructions = {op(0, "return-void")};
      Body.code_end = 1;
    }
    Parent.methods.push_back(std::move(Body));
  }
  Read.reference.parameters[2] = Container.name;
  Read.generic_signature = "(Ljava/lang/String;ITF;JZ)V";
  auto Middle = klass("Lfixture/Middle;", {Read});
  Middle.access = {"public", "abstract"};
  Middle.superclass = Parent.name;
  Middle.generic_signature =
      std::string("<E:Ljava/lang/Object;F:") + (InterfaceBound ? ":" : "") +
      "Lfixture/Container<TE;>;>Lfixture/Parent<TE;TF;>;";
  for (auto *Owner : {&Container, &Root, &Parent, &Middle}) {
    if (Owner->access.contains("interface"))
      continue;
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{*Owner->superclass, "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.access = {"public", "constructor"};
    Init.reference.owner = Owner->name;
    if (Owner->external) {
      Init.instructions.clear();
      Init.registers = Init.code_end = 0;
    }
    Owner->methods.push_back(std::move(Init));
  }
  return {Container, Root, Parent, Middle};
}

TEST(MobileDalvikJava, AbstractBoundedParametersDiscloseAbsentCompilerSlots) {
  for (bool External : {false, true})
    for (bool Protected : {false, true})
      for (bool InterfaceBound : {false, true})
        for (bool ConcreteParent : {false, true})
          for (bool Link : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(::testing::Message()
                           << External << Protected << InterfaceBound
                           << ConcreteParent << Link << Reverse);
              auto Input = abstractBoundedParameterClasses(
                  External, Protected, InterfaceBound, ConcreteParent);
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              llvm::json::Object R;
              ASSERT_NO_THROW(R = Link ? recoverJava(linkClasses(Input, B), B)
                                       : recover(Input));
              EXPECT_EQ(R.getInteger("class_count"), External ? 1 : 4);
              EXPECT_EQ(R.getInteger("method_count"),
                        External ? 2
                                 : ((InterfaceBound ? 5 : 6) +
                                    (ConcreteParent ? 1 : 0)));
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_EQ(R.getString("status"), "partial");
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              ASSERT_TRUE(R.getArray("generated_source_helpers"));
              unsigned Count = 0;
              for (const auto &Item : *R.getArray("generated_source_helpers")) {
                const auto &Row = *Item.getAsObject();
                if (Row.getString("kind") != "compiler-parameter-class-bridge")
                  continue;
                ++Count;
                EXPECT_EQ(Row.getString("class"), "Lfixture/Middle;");
                EXPECT_EQ(Row.getString("prototype"),
                          "(Ljava/lang/String;ILjava/lang/Object;JZ)V");
                ASSERT_TRUE(Row.getArray("access_flags"));
                EXPECT_EQ((*Row.getArray("access_flags"))[0].getAsString(),
                          Protected ? "protected" : "public");
              }
              EXPECT_EQ(Count, 1u);
            }
}

