TEST(MobileDalvikJava, PlainDependencyDefaultsRejectUnknownAndCompetingSlots) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
        SCOPED_TRACE(Mutation);
        auto Input = plainDependencyDefaultAncestorClasses(External);
        auto &Parent = Input[1];
        auto &Worker = Input[3];
        switch (Mutation) {
        case 0:
          Parent.superclass = "Lfixture/Unknown;";
          break;
        case 1:
          Parent.superclass = Parent.name;
          break;
        case 2:
          Parent.methods.push_back(Input[0].methods[1]);
          Parent.methods.back().reference.owner = Parent.name;
          break;
        case 3:
          Parent.interfaces.push_back("Lfixture/UnknownInterface;");
          break;
        case 4:
          Parent.methods[2].generic_signature = "<U:Ljava/lang/String;>()TU;";
          break;
        case 5:
          Worker.methods.push_back(Parent.methods[1]);
          Worker.methods.back().reference.owner = Worker.name;
          Worker.methods.back().registers = 2;
          Worker.methods.back().instructions = {
              op(0, "const/4", {0}, int64_t(0)), op(1, "return", {0})};
          Worker.methods.back().code_end = 2;
          break;
        case 6:
          Worker.methods[2].access = {"private"};
          break;
        case 7:
          Worker.methods[2].reference.returns = "Ljava/lang/Object;";
          break;
        case 8:
          Parent.access.insert("abstract");
          Parent.methods[1].access = {"public", "abstract"};
          Parent.methods[1].instructions.clear();
          Parent.methods[1].registers = Parent.methods[1].code_end = 0;
          break;
        }
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> inheritedExceptionBridgeClasses(bool External, bool Getter) {
  auto Input = interfaceBridgeClasses();
  auto &Api = Input[0];
  auto &Core = Input[1];
  Api.external = External;
  const std::vector<std::string> Failures{
      "Ljava/io/IOException;", "Ljava/lang/ReflectiveOperationException;"};
  Api.methods[0].declared_throws = Failures;
  Core.methods[1].declared_throws = Failures;
  if (Getter) {
    Api.methods[0].reference.parameters.clear();
    Api.methods[0].generic_signature = "()TT;";
    Core.methods[0].reference.parameters.clear();
    Core.methods[0].instructions = {op(0, "const/4", {0}, int64_t(0)),
                                    op(1, "return-object", {0})};
    Core.methods[0].code_end = 2;
    Core.methods[1].reference.parameters.clear();
    Core.methods[1].instructions = {
        op(0, "invoke-virtual", {1}, {}, Core.methods[0].reference),
        op(1, "move-result-object", {0}), op(2, "return-object", {0})};
    Core.methods[1].code_end = 3;
  }
  for (const auto &Name : Failures) {
    auto Failure = klass(Name);
    Failure.external = true;
    Failure.superclass = "Ljava/lang/Exception;";
    Input.push_back(Failure);
  }
  return Input;
}

TEST(MobileDalvikJava,
     InheritedExceptionBridgesRetainOriginalContractMetadata) {
  for (bool External : {false, true})
    for (bool Getter : {false, true})
      for (bool Reverse : {false, true})
        for (bool Link : {false, true}) {
          auto Input = inheritedExceptionBridgeClasses(External, Getter);
          const auto Original = Input[1].methods[1].declared_throws;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("method_count"), External ? 2 : 3);
          EXPECT_EQ(R.getInteger("projected_method_count"), 1);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
          const auto &Core =
              *std::find_if(Input.begin(), Input.end(), [](const Class &C) {
                return C.name == "Lfixture/Core;";
              });
          EXPECT_EQ(Core.methods[1].declared_throws, Original);
          EXPECT_FALSE(Core.methods[0].declared_throws);
          ClassMap OriginalClasses;
          for (const auto &C : Input)
            OriginalClasses.emplace(C.name, C);
          Budget Validation;
          const auto Plans =
              validateGenericSignatures(OriginalClasses, Validation);
          EXPECT_EQ(Plans.closed_declared_throws.at(Core.methods[1].reference),
                    (std::vector<std::string>{
                        "Ljava/io/IOException;",
                        "Ljava/lang/ReflectiveOperationException;"}));
        }
}

TEST(MobileDalvikJava, InheritedExceptionBridgesRejectContractAndBodyDrift) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
        SCOPED_TRACE(Mutation);
        auto Input = inheritedExceptionBridgeClasses(External, true);
        auto &Api = Input[0].methods[0];
        auto &Target = Input[1].methods[0];
        auto &Bridge = Input[1].methods[1];
        switch (Mutation) {
        case 0:
          Bridge.declared_throws = {"Ljava/io/IOException;"};
          break;
        case 1:
          std::reverse(Bridge.declared_throws->begin(),
                       Bridge.declared_throws->end());
          break;
        case 2:
          Bridge.declared_throws.reset();
          break;
        case 3:
          Api.declared_throws.reset();
          break;
        case 4:
          Target.declared_throws = {"Ljava/io/IOException;"};
          break;
        case 5:
          Bridge.instructions[0].registers = {0};
          break;
        case 6:
          Bridge.instructions[2].registers = {1};
          break;
        case 7:
          Api.generic_signature = "<E:Ljava/lang/Exception;>()TT;^TE;";
          Api.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 8:
          Input.back().superclass = "Ljava/lang/Object;";
          break;
        }
        Budget B;
        if (Mutation == 2) {
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          bool Found = false;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") != Bridge.reference.identity())
              continue;
            EXPECT_EQ(Row->getString("bridge_exception_source"),
                      Api.reference.identity());
            const auto *Throws = Row->getArray("source_bridge_declared_throws");
            ASSERT_NE(Throws, nullptr);
            ASSERT_EQ(Throws->size(), Api.declared_throws->size());
            for (size_t I = 0; I < Throws->size(); ++I)
              EXPECT_EQ((*Throws)[I].getAsString(), (*Api.declared_throws)[I]);
            EXPECT_NE(Row->getArray("metadata_differences"), nullptr);
            Found = true;
          }
          EXPECT_TRUE(Found);
        } else
          rejected(
              [&] {
                if (Link)
                  recoverJava(linkClasses(Input, B), B);
                else
                  recover(Input);
              },
              "generic");
      }
}

std::vector<Class> publicBoundedSelfGetterClasses(bool ResultCast) {
  auto Input = protectedClosedGetterBridgeClasses();
  auto &Core = Input[0];
  auto &Base = Input[1];
  Base.generic_signature = "<T:Lfixture/Base<TT;>;>Ljava/lang/Object;";
  Base.methods[0].reference.returns = Base.name;
  Core.generic_signature = "Lfixture/Base<Lfixture/Core;>;";
  auto &Target = Core.methods[0];
  Target.reference.returns = Core.name;
  Target.registers = 1;
  Target.instructions = {op(0, "return-object", {0})};
  Target.code_end = 1;
  auto &Bridge = Core.methods[1];
  Bridge.reference.returns = Base.name;
  Bridge.instructions[0].reference = Target.reference;
  if (ResultCast) {
    Bridge.instructions.insert(Bridge.instructions.begin() + 2,
                               op(2, "check-cast", {0}, {}, Base.name));
    Bridge.instructions.back().pc = 3;
    Bridge.code_end = 4;
  }
  Core.methods[2].reference.returns = Base.name;
  Core.methods[2].instructions[0].reference = Bridge.reference;
  return Input;
}

