TEST(MobileDalvikJava,
     PublicBoundedSelfGettersRejectNominalScopeAndResultDrift) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
      auto Input = publicBoundedSelfGetterClasses(true);
      auto &Core = Input[0];
      auto &Bridge = Core.methods[1];
      switch (Mutation) {
      case 0: {
        Core.access.erase("final");
        auto Child = klass("Lfixture/GetterChild;", {Core.methods[0]});
        Child.superclass = Core.name;
        Input.push_back(Child);
        break;
      }
      case 1:
        Bridge.instructions[2].reference = std::string("Ljava/lang/String;");
        break;
      case 2:
        Bridge.instructions[3].registers = {1};
        break;
      case 3:
        Bridge.instructions[0].registers = {0};
        break;
      case 4:
        Core.generic_signature = "Lfixture/Base<Ljava/lang/String;>;";
        break;
      case 5:
        Core.methods[0].generic_signature = "<U:Lfixture/Core;>()TU;";
        break;
      case 6:
        Input[1].generic_signature =
            "<T:Lfixture/Base<TT;>;U:Lfixture/Base<TU;>;>Ljava/lang/Object;";
        Core.generic_signature = "Lfixture/Base<Lfixture/Core;Lfixture/Core;>;";
        Core.methods[0].generic_signature = "<U:Lfixture/Core;>()TU;";
        break;
      }
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

