TEST(MobileDalvikJava, CheckedErasedParametersRetainDescriptorsAndBodyCasts) {
  auto Input = checkedErasedBridgeClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    auto Report = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    EXPECT_EQ(Report.getInteger("method_count"), 3);
    EXPECT_EQ(Report.getInteger("projected_method_count"), 1);
    EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
    EXPECT_EQ(Report.getString("status"), "partial");
    const auto Text = source(Report, 1);
    EXPECT_NE(Text.find("implements fixture.Contract<java.lang.Object, "
                        "java.lang.String>"),
              std::string::npos);
    EXPECT_NE(Text.find("java.lang.String echo(java.lang.Object arg0)"),
              std::string::npos);
    EXPECT_NE(Text.find("(java.lang.String) o0"), std::string::npos);
    const auto *Projections = Report.getArray("generic_signature_projections");
    ASSERT_NE(Projections, nullptr);
    EXPECT_EQ(Projections->size(), 2u);
    std::set<std::string> Kinds;
    for (const auto &Projection : *Projections)
      for (const auto &Change : *Projection.getAsObject()->getArray("changes"))
        Kinds.insert(Change.getAsObject()->getString("kind")->str());
    EXPECT_EQ(Kinds,
              (std::set<std::string>{"checked-erased-parameter",
                                     "checked-erased-interface-argument"}));
  }
  EXPECT_EQ(Input[1].methods[0].generic_signature,
            "(Ljava/lang/String;)Ljava/lang/String;");
}

