TEST(MobileDalvikJava, CheckedErasedReturnsRejectUnknownDefinitionsAndBridges) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = checkedErasedReturnClasses();
    auto &Core = Input[1];
    auto &Target = Core.methods[0];
    switch (Mutation) {
    case 0:
      Core.access.erase("final");
      break;
    case 1:
      Target.instructions[2].reference = std::string("Lfixture/Owner;");
      break;
    case 2:
      Target.instructions[0].literal = int64_t(1);
      break;
    case 3:
      Target.instructions[4].registers = {0, 3};
      break;
    case 4:
      Target.instructions[3].opcode = "nop";
      Target.instructions[3].registers.clear();
      Target.instructions[3].reference = {};
      break;
    case 5:
      Target.instructions[0].opcode = "const-wide/16";
      break;
    case 6:
      Target.instructions[1].target = 3;
      break;
    case 7:
      Core.methods[1].instructions[0].reference =
          std::string("Lfixture/Result;");
      break;
    case 8:
      Core.generic_signature = "Ljava/lang/Object;Lfixture/Contract<"
                               "Lfixture/Owner<*>;Lfixture/Owner<*>;>;";
      break;
    case 9:
      Core.generic_signature = "Ljava/lang/Object;Lfixture/Contract<"
                               "Lfixture/Owner<Ljava/lang/String;>;"
                               "Lfixture/Result;>;";
      break;
    case 10:
      Core.methods.pop_back();
      break;
    case 11:
      Input[3].methods.clear();
      break;
    }
    rejected([&] { recover(Input); },
             Mutation == 7 ? "generic bridge" : "return erasure mismatch");
  }
}

TEST(MobileDalvikJava, CheckedErasedReturnsRecheckAllInterfaceArgumentBounds) {
  for (const auto &Name : {"Lfixture/AContainer;", "Lfixture/ZContainer;"}) {
    auto Input = checkedErasedReturnClasses();
    auto Container = klass(Name);
    Container.generic_signature =
        "<F::Lfixture/Contract<Lfixture/Owner<*>;Lfixture/Result;>;>"
        "Ljava/lang/Object;";
    Field Held;
    Held.reference = {Container.name, "value", Container.name};
    Held.access = {"public"};
    Held.generic_signature =
        Container.name.substr(0, Container.name.size() - 1) +
        "<Lfixture/Core;>;";
    Container.fields = {Held};
    Input.push_back(Container);
    rejected([&] { recover(Input); }, "type argument bound is not proven");
  }
}

