std::vector<Class> directErasedInterfaceClasses() {
  const std::string InputType =
      "Lfixture/Pair<+Lfixture/Box<Ljava/lang/String;>;"
      "+Lfixture/Box<Ljava/lang/Object;>;>;";
  auto Map = method("map", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Map.access = {"public", "abstract"};
  Map.generic_signature = "(TP;)TR;";
  auto Items = method("items", {}, "Lfixture/Cursor;", 0, {});
  Items.access = {"public", "abstract"};
  Items.generic_signature = "()Lfixture/Cursor<TP;>;";
  auto Contract = klass("Lfixture/Contract;", {Map, Items});
  Contract.access = {"public", "interface", "abstract"};
  Contract.generic_signature =
      "<P:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Read = method("read", {}, "Ljava/lang/String;", 0, {});
  Read.access = {"public", "abstract"};
  auto Reader = klass("Lfixture/Reader;", {Read});
  Reader.access = {"public", "interface", "abstract"};
  auto Get =
      method("get", {}, Reader.name, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Get.access = {"public"};
  auto Pair = klass("Lfixture/Pair;", {Get});
  Pair.generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Cursor = klass("Lfixture/Cursor;");
  Cursor.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Target = method(
      "map", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 4,
      {op(0, "move-object", {0, 3}), op(1, "check-cast", {0}, {}, Pair.name),
       op(2, "invoke-virtual", {0}, {}, Pair.methods[0].reference),
       op(3, "move-result-object", {0}),
       op(4, "invoke-interface", {0}, {}, Reader.methods[0].reference),
       op(5, "move-result-object", {0}), op(6, "return-object", {0})});
  Target.access = {"public"};
  Target.generic_signature = "(" + InputType + ")Ljava/lang/String;";
  auto Source =
      method("items", {}, Cursor.name, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Source.access = {"public"};
  Source.generic_signature = "()Lfixture/Cursor<" + InputType + ">;";
  auto Core = klass("Lfixture/Core;", {Target, Source});
  Core.access.insert("final");
  Core.interfaces = {Contract.name};
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Contract<" + InputType +
                           "Ljava/lang/String;>;";
  return {Contract, Core, Pair, Box, Cursor, Reader};
}
