TEST(MobileDalvikJava,
     DirectErasedInterfaceMethodsRequireEveryContractAndBodyFact) {
  for (unsigned Mutation = 0; Mutation < 15; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = directErasedInterfaceClasses();
    auto &Core = Input[1];
    auto &Target = Core.methods[0];
    switch (Mutation) {
    case 0:
      Core.access.erase("final");
      break;
    case 1:
      Target.instructions[1].reference = Input[3].name;
      break;
    case 2:
      std::get<MethodRef>(Target.instructions[4].reference).returns =
          "Ljava/lang/Object;";
      break;
    case 3:
      Target.instructions.back().registers = {1};
      break;
    case 4:
      Core.generic_signature =
          "Ljava/lang/Object;Lfixture/Contract<"
          "Lfixture/Pair<Lfixture/Box<Ljava/lang/Object;>;"
          "Lfixture/Box<Ljava/lang/String;>;>;Ljava/lang/String;>;";
      break;
    case 5:
      Core.methods.pop_back();
      break;
    case 6:
      Core.methods[1].access.insert("static");
      break;
    case 7:
      Input[0].methods[1].reference.parameters = {"Ljava/lang/Object;"};
      Input[0].methods[1].generic_signature =
          "(Ljava/lang/Object;)Lfixture/Cursor<TP;>;";
      break;
    case 8:
      Core.interfaces.push_back(Input[5].name);
      break;
    case 9:
      Target.tries = {{0, 2, {{std::nullopt, 3}}}};
      break;
    case 10:
      Target.instructions[2].target = 5;
      break;
    case 11:
      Input[0].generic_signature =
          "<P:Ljava/lang/Object;R:Ljava/lang/String;>Ljava/lang/Object;";
      break;
    case 12:
      Input.pop_back();
      break;
    case 13:
      Target.instructions[5].opcode = "const-string";
      Target.instructions[5].literal = std::string("owned");
      break;
    case 14:
      Core.methods[1].generic_signature =
          "<E:Ljava/lang/Object;>" + *Core.methods[1].generic_signature;
      break;
    }
    rejected([&] { recover(Input); },
             Mutation == 8    ? "interface erasure mismatch"
             : Mutation == 11 ? "return erasure mismatch"
                              : "parameter erasure mismatch");
  }
}

