      "Ljava/lang/Object;Lfixture/Contract<Lfixture/Leaf;Lfixture/Leaf;>;";
  auto &Target = Core.methods[0];
  Target.reference.parameters = {Base.name};
  Target.reference.returns = Leaf.name;
  Target.generic_signature = "(Lfixture/Leaf;)Lfixture/Leaf;";
  Target.instructions[1].reference = Leaf.name;
  auto &Bridge = Core.methods[1];
  Bridge.instructions = {op(0, "check-cast", {2}, {}, Base.name),
                         op(1, "invoke-virtual", {1, 2}, {}, Target.reference),
                         op(2, "move-result-object", {0}),
                         op(3, "return-object", {0})};
  Bridge.code_end = 4;
  Input.push_back(Base);
  Input.push_back(Leaf);
