TEST(MobileDalvikJava,
     StaticCarrierScopeRejectsExtraStorageAndNonMarkerContracts) {
  for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto C = referenceCarrierClass();
    auto Marker = klass("Lfixture/Marker;", {});
    Marker.access = {"public", "interface", "abstract"};
    C.interfaces = {Marker.name};
    *C.generic_signature += Marker.name;
    switch (Mutation) {
    case 0:
      C.fields.push_back(
          {{C.name, "other", "Ljava/lang/Object;"}, {"private", "final"}, {}});
      break;
    case 1: {
      auto Contract = method("ping", {}, "V", 0, {});
      Contract.reference.owner = Marker.name;
      Contract.access = {"public", "abstract"};
      Marker.methods.push_back(Contract);
      break;
    }
    case 2:
      Marker.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 3:
      Marker.interfaces = {"Lfixture/MissingMarker;"};
      break;
    case 4:
      Marker.interfaces = {Marker.name};
      break;
    }
    Budget B;
    rejected(
        [&] {
          validateGenericSignatures({{C.name, C}, {Marker.name, Marker}}, B);
        },
        "unbound type variable T");
  }
}

TEST(MobileDalvikJava, StaticCarrierLocalsShareClassAndMethodScopeDecisions) {
  auto Carrier = referenceCarrierClass();
  Carrier.methods[3].generic_signature =
      "<R:Ljava/lang/Object;>(Ljava/lang/Object;Ljava/util/List<TT;>;)Ljava/"
      "lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Local = klass("Lfixture/Carrier$1;", {Init});
  Local.inner_class_present = true;
  Local.inner_access = {"static", "final"};
  Local.enclosing_method = Carrier.methods[3].reference;
  Local.fields = {{{Local.name, "classValues", "Ljava/util/List;"},
                   {},
                   {},
                   "Ljava/util/List<TT;>;"},
                  {{Local.name, "methodValues", "Ljava/util/List;"},
                   {},
                   {},
                   "Ljava/util/List<TR;>;"}};
  Budget B;
  const auto Linked = linkClasses({Carrier, Local}, B);
  auto Plans = validateGenericSignatures(Linked, B);
  const auto &ClassField = Plans.fields.at(Local.fields[0].reference);
  ASSERT_EQ(ClassField.source_projections.size(), 1u);
  EXPECT_EQ(ClassField.source_projections[0].kind,
            "static-carrier-type-variable");
  EXPECT_EQ(ClassField.source_projections[0].scope_origin, Carrier.name);
  const auto &MethodField = Plans.fields.at(Local.fields[1].reference);
  EXPECT_TRUE(MethodField.source_projections.empty());
  EXPECT_TRUE(std::any_of(MethodField.types.begin(), MethodField.types.end(),
                          [&](const GenericType &Type) {
                            return Type.variable_name == "R" &&
                                   Type.variable_owner ==
                                       Carrier.methods[3].reference.identity();
                          }));
  // A local sees the enclosing method's shadowing formal, just as the method
  // declaration does. It must not erase that distinct binding to Object.
  Carrier.methods[3].generic_signature =
      "<R:Ljava/lang/Object;T:Ljava/lang/String;>(Ljava/lang/Object;Ljava/util/"
      "List<TT;>;)Ljava/lang/Object;";
  auto Shadow = validateGenericSignatures(
      {{Carrier.name, Carrier}, {Local.name, Local}}, B);
  EXPECT_TRUE(
      Shadow.fields.at(Local.fields[0].reference).source_projections.empty());
  Carrier.methods[3].generic_signature =
      "<R:Ljava/lang/Object;>(Ljava/lang/Object;Ljava/util/List<TT;>;)Ljava/"
      "lang/Object;";
  Carrier.methods[1].instructions[1].registers[1] = 0;
  rejected([&] { linkClasses({Carrier, Local}, B); },
           "unbound type variable T");
}

std::vector<Class> anonymousCreatorClasses() {
  auto Value = method("value", {}, "I", 0, {});
  Value.access = {"public", "abstract"};
  Class Contract = klass("Lfixture/Creator;", {Value});
  Contract.access = {"public", "abstract", "interface"};
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"constructor"};
  auto Body = method("value", {}, "I", 2,
                     {op(0, "const/4", {0}, int64_t(7)), op(1, "return", {0})});
  Body.access = {"public"};
  Class Anonymous = klass("Lfixture/Host$1;", {Init, Body});
  Anonymous.access.clear();
  Anonymous.inner_class_present = true;
  Anonymous.inner_access = {"static"};
  Anonymous.enclosing = "Lfixture/Host;";
  Anonymous.interfaces = {Contract.name};
  FieldRef Field{"Lfixture/Host;", "CREATOR", Contract.name};
  auto Clinit =
      method("<clinit>", {}, "V", 1,
             {op(0, "new-instance", {0}, {}, Anonymous.name),
              op(1, "invoke-direct", {0}, {}, Anonymous.methods[0].reference),
              op(2, "sput-object", {0}, {}, Field), op(3, "return-void")});
  Clinit.access = {"static", "constructor"};
  Class Host = klass("Lfixture/Host;", {Clinit});
  Host.fields.push_back({Field, {"public", "static", "final"}, {}});
  return {Contract, Host, Anonymous};
}

