std::vector<Class> unusedFormalInvocationClasses(bool External, bool Generic,
                                                 bool Range) {
  auto Relay = method("relay", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 1,
                      {op(0, "return-object", {0})});
  Relay.generic_signature =
      "<T:Ljava/lang/Object;>(Ljava/lang/Object;)Ljava/lang/Object;";
  auto Provider = klass("Lfixture/Provider;", {Relay});
  if (Generic)
    Provider.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Provider.external = External;
  if (External) {
    auto &M = Provider.methods[0];
    M.instructions.clear();
    M.registers = M.code_end = 0;
  }
  auto Call =
      method("call", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 1,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {0}, {},
                 Provider.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Client;", {Call}), Provider};
}

TEST(MobileDalvikJava, UnusedMethodFormalsKeepIndependentStaticObjectSlots) {
  for (bool External : {false, true})
    for (bool Generic : {false, true})
      for (bool Range : {false, true})
        for (unsigned Route = 0; Route < 3; ++Route) {
          auto Input = unusedFormalInvocationClasses(External, Generic, Range);
          const auto Ref = Input[1].methods[0].reference;
          const auto Original = Input[1].methods[0].generic_signature;
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          ClassMap Classes;
          Budget B;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
          EXPECT_TRUE(Plans.erased_unused_formal_invocations.contains(Ref));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                    Original);
          const auto Text = source(R);
          EXPECT_NE(Text.find(".relay("), std::string::npos);
        }
}

TEST(MobileDalvikJava,
     UnusedMethodFormalsKeepClosedThrowsAndRejectInvalidContracts) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = unusedFormalInvocationClasses(External, true, true);
      auto &Relay = Input[1].methods[0];
      if (Mutation == 0)
        Relay.generic_signature =
            "<T:Ljava/lang/Number;>(Ljava/lang/Object;)Ljava/lang/Object;";
      else if (Mutation == 1)
        Relay.generic_signature = "<T:Ljava/lang/Object;U:Ljava/lang/Number;>"
                                  "(Ljava/lang/Object;)Ljava/lang/Object;";
      else if (Mutation == 2)
        Relay.generic_signature =
            "<T:Ljava/lang/Object;>(TT;)Ljava/lang/Object;";
      else if (Mutation == 3)
        Relay.access = {"private", "static"};
      else if (Mutation == 4)
        Relay.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 5)
        Relay.access.insert("bridge");
      else if (Mutation == 6) {
        Relay.access.erase("static");
        if (!External)
          Relay.registers = 2;
      } else
        Input[0].methods[0].instructions[0].opcode = "invoke-interface/range";
      Budget B;
      if (Mutation == 4) {
        // Closed checked exceptions are now accepted through the shared
        // Throwable authority; every other invalid contract stays rejected.
        const auto Ref = Relay.reference;
        const auto Signature = Relay.generic_signature;
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plans.erased_unused_formal_invocations.contains(Ref));
        EXPECT_TRUE(validatedClosedDeclaredThrows(Relay, Plans));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                  Signature);
        EXPECT_EQ(Classes.at(Ref.owner).methods[0].declared_throws,
                  Relay.declared_throws);
      } else {
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
      }
    }
}

