Class markerClass(std::string Name = "Lfixture/ZMarker;") {
  Class C = klass(std::move(Name));
  C.access = {"public", "interface", "abstract", "annotation"};
  C.interfaces = {"Ljava/lang/annotation/Annotation;"};
  return C;
}
Class memberClass(Class C, const Class &Owner, std::string Name,
                  std::string Visibility = "public") {
  C.enclosing = Owner.name;
  C.inner_class_present = true;
  C.inner_name = std::move(Name);
  C.inner_access = C.access;
  C.inner_access.erase("public");
  if (!Visibility.empty())
    C.inner_access.insert(std::move(Visibility));
  C.inner_access.insert("static");
  return C;
}
std::string sourceAt(const llvm::json::Object &Report, llvm::StringRef Path) {
  const auto *Units = Report.getArray("source_units");
  if (!Units)
    return {};
  for (const auto &Value : *Units) {
    const auto *Unit = Value.getAsObject();
    if (Unit && Unit->getString("path") == Path) {
      auto Text = Unit->getString("source");
      return Text ? Text->str() : "";
    }
  }
  return {};
}
void rejectAnnotationBoth(const std::vector<Class> &Input) {
  EXPECT_THROW(recover(Input), Error);
  Budget B;
  EXPECT_THROW(linkClasses(Input, B), Error);
}

std::vector<Class> annotatedGenericBridgeClasses() {
  auto Input = interfaceBridgeClasses();
  auto Mark = markerClass();
  Mark.annotation_metadata.retention = "RUNTIME";
  Mark.annotation_metadata.targets = {"METHOD"};
  auto Value = method("value", {}, "I", 0, {});
  Value.reference.owner = Mark.name;
  Value.access = {"public", "abstract"};
  Mark.methods.push_back(Value);
  Input[1].methods[0].annotations = {AnnotationUse{
      Mark.name, 1, {{"value", AnnotationValue{4, int64_t(11)}}}}};
  Input.push_back(Mark);
  return Input;
}

TEST(MobileDalvikJava, AnnotatedTargetsKeepOriginalGenericBridgeProofs) {
  for (bool Link : {false, true}) {
    auto Input = annotatedGenericBridgeClasses();
    Budget B;
    const auto R =
        Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 4);
    EXPECT_EQ(R.getInteger("projected_method_count"), 1);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    EXPECT_NE(
        sourceAt(R, "fixture/Core.java").find("@fixture.ZMarker(value = 0x"),
        std::string::npos);
    bool Found = false;
    for (const auto &Value : *R.getArray("methods")) {
      const auto *Row = Value.getAsObject();
      if (Row->getString("identity") !=
          Input[1].methods[1].reference.identity())
        continue;
      EXPECT_EQ(Row->getString("bridge_annotation_source"),
                Input[1].methods[0].reference.identity());
      EXPECT_TRUE(Row->getArray("metadata_differences"));
      Found = true;
    }
    EXPECT_TRUE(Found);
    EXPECT_TRUE(Input[1].methods[1].annotations.empty());
    EXPECT_EQ(Input[1].methods[0].annotations.size(), 1);
  }
}

TEST(MobileDalvikJava, AnnotatedBridgeTargetsRejectMetadataAndBodyDrift) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = annotatedGenericBridgeClasses();
      if (Mutation == 0)
        Input[1].methods[0].annotations[0].elements["value"] =
            AnnotationValue{0x17, std::string("wrong")};
      else if (Mutation == 1)
        Input[2].annotation_metadata.targets = {"FIELD"};
      else if (Mutation == 2)
        Input[1].methods[1].annotations = Input[1].methods[0].annotations;
      else if (Mutation == 3)
        Input[1].methods[1].instructions[1].registers = {1, 1};
      else
        Input[1].methods[0].parameter_annotations = {
            Input[1].methods[0].annotations};
      Budget B;
      EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                        : recover(Input),
                   std::runtime_error);
    }
}

TEST(MobileDalvikJava, AnnotationArraysDefaultsAndParameterSitesRemainExact) {
  auto Definition = markerClass();
  Definition.annotation_metadata.retention = "RUNTIME";
  Definition.annotation_metadata.targets = {"TYPE", "METHOD", "FIELD",
                                            "PARAMETER"};
  auto Element = method("value", {}, "[Ljava/lang/String;", 0, {});
  Element.reference.owner = Definition.name;
  Element.access = {"public", "abstract"};
  AnnotationValue Empty;
  Empty.kind = 0x1c;
  Element.annotation_default = Empty;
  Definition.methods.push_back(Element);
  auto Use = klass("Lfixture/Core;",
                   {method("value", {"I"}, "I", 1, {op(0, "return", {0})})});
  AnnotationValue Values = Empty;
  Values.array = {{0x17, std::string("a\n\"b")}, {0x17, std::string()}};
  AnnotationUse Applied{Definition.name, 1, {{"value", Values}}};
  Use.annotations.push_back(Applied);
  Use.methods[0].annotations.push_back(Applied);
  Use.methods[0].parameter_annotations = {{Applied}};
  Use.fields.push_back({{Use.name, "field", "I"}, {"public", "static"}, {}});
  Use.fields[0].annotations.push_back(Applied);
  auto Report = recover({Use, Definition});
  auto Text = sourceAt(Report, "fixture/Core.java");
  const std::string Expected =
      "@fixture.ZMarker(value = {\"a\\n\\\"b\", \"\"})";
  EXPECT_NE(Text.find(Expected + "\npublic class Core"), std::string::npos);
  EXPECT_NE(Text.find(Expected + " int arg0"), std::string::npos);
  EXPECT_NE(sourceAt(Report, "fixture/ZMarker.java")
                .find("java.lang.String[] value() default {};"),
            std::string::npos);
  EXPECT_EQ(Report.getInteger("declaration_only_method_count"), 1);
  Values.array[0] = AnnotationValue{4, int64_t(1)};
  Use.annotations[0].elements["value"] = Values;
  rejectAnnotationBoth({Use, Definition});
  Use.annotations.clear();
  Use.methods[0].annotations[0].elements["unknown"] = Empty;
  rejectAnnotationBoth({Use, Definition});
}

