Class enumClass() {
  auto C = klass("Lfixture/Choice;");
  C.access = {"public", "final", "enum"};
  C.superclass = "Ljava/lang/Enum;";
  C.generic_signature = "Ljava/lang/Enum<Lfixture/Choice;>;";
  const FieldRef A{C.name, "FIRST", C.name}, B{C.name, "SECOND", C.name};
  const FieldRef Values{C.name, "$VALUES", "[" + C.name};
  const FieldRef Bias{C.name, "bias", "I"};
  for (const auto &F : {A, B}) {
    Field V;
    V.reference = F;
    V.access = {"public", "static", "final", "enum"};
    C.fields.push_back(V);
  }
  Field V;
  V.reference = Values;
  V.access = {"private", "static", "final", "synthetic"};
  C.fields.push_back(V);
  V.reference = Bias;
  V.access = {"private", "final"};
  C.fields.push_back(V);
  const MethodRef Init{C.name, "<init>", {"Ljava/lang/String;", "I", "I"}, "V"};
  auto Constructor = method(
      "<init>", Init.parameters, "V", 4,
      {op(0, "invoke-direct", {0, 1, 2}, {},
          MethodRef{
              "Ljava/lang/Enum;", "<init>", {"Ljava/lang/String;", "I"}, "V"}),
       op(1, "iput", {3, 0}, {}, Bias), op(2, "return-void")});
  Constructor.access = {"private", "constructor"};
  Constructor.generic_signature = "(I)V";
  C.methods.push_back(Constructor);
  C.methods.push_back(method(
      "<clinit>", {}, "V", 4,
      {op(0, "new-instance", {0}, {}, C.name),
       op(1, "const-string", {1}, std::string("FIRST")),
       op(2, "const/4", {2}, int64_t(0)), op(3, "const/4", {3}, int64_t(3)),
       op(4, "invoke-direct", {0, 1, 2, 3}, {}, Init),
       op(5, "sput-object", {0}, {}, A), op(6, "new-instance", {0}, {}, C.name),
       op(7, "const-string", {1}, std::string("SECOND")),
       op(8, "const/4", {2}, int64_t(1)), op(9, "const/4", {3}, int64_t(7)),
       op(10, "invoke-direct", {0, 1, 2, 3}, {}, Init),
       op(11, "sput-object", {0}, {}, B), op(12, "sget-object", {1}, {}, A),
       op(13, "sget-object", {2}, {}, B),
       op(14, "filled-new-array", {1, 2}, {}, "[" + C.name),
       op(15, "move-result-object", {0}),
       op(16, "sput-object", {0}, {}, Values), op(17, "return-void")}));
  C.methods.back().access = {"static", "constructor"};
  C.methods.push_back(
      method("values", {}, "[" + C.name, 1,
             {op(0, "sget-object", {0}, {}, Values),
              op(1, "invoke-virtual", {0}, {},
                 MethodRef{"[" + C.name, "clone", {}, "Ljava/lang/Object;"}),
              op(2, "move-result-object", {0}),
              op(3, "check-cast", {0}, {}, "[" + C.name),
              op(4, "return-object", {0})}));
  C.methods.push_back(method(
      "valueOf", {"Ljava/lang/String;"}, C.name, 2,
      {op(0, "const-class", {0}, {}, C.name),
       op(1, "invoke-static", {0, 1}, {},
          MethodRef{"Ljava/lang/Enum;",
                    "valueOf",
                    {"Ljava/lang/Class;", "Ljava/lang/String;"},
                    "Ljava/lang/Enum;"}),
       op(2, "move-result-object", {0}), op(3, "check-cast", {0}, {}, C.name),
       op(4, "return-object", {0})}));
  for (auto &M : C.methods)
    M.reference.owner = C.name;
  return C;
}

std::vector<Class> checkedEnumBridgeClasses() {
  auto Input = checkedErasedBridgeClasses();
  auto Enum = enumClass();
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  Enum.interfaces = {Marker.name};
  *Enum.generic_signature += Marker.name;
  auto &Core = Input[1];
  Core.generic_signature = "Ljava/lang/Object;Lfixture/Contract<Lfixture/"
                           "Choice;Ljava/lang/String;>;";
  const FieldRef State{Core.name, "state", "I"};
  Core.fields.push_back({State, {"private"}, {}, {}});
  auto &Target = Core.methods[0];
  Target.reference.parameters = {"Ljava/lang/Enum;"};
  Target.generic_signature = "(Lfixture/Choice;)Ljava/lang/String;";
  Target.registers = 4;
  Target.instructions = {op(0, "iget", {0, 2}, {}, State),
                         op(1, "move-object", {1, 3}),
                         op(2, "check-cast", {1}, {}, Marker.name),
                         op(3, "const-string", {0}, std::string("owned")),
                         op(4, "return-object", {0})};
  Target.code_end = 5;
  auto &Bridge = Core.methods[1];
  Bridge.instructions = {
      op(0, "check-cast", {2}, {}, std::string("Ljava/lang/Enum;")),
      op(1, "invoke-virtual", {1, 2}, {}, Target.reference),
      op(2, "move-result-object", {0}), op(3, "return-object", {0})};
  Bridge.code_end = 4;
  Input.push_back(Enum);
  Input.push_back(Marker);
  return Input;
}

TEST(MobileDalvikJava, CheckedEnumParametersRetainInterfaceCastsAndFieldReads) {
  const auto Input = checkedEnumBridgeClasses();
  Budget B;
  const auto Linked = linkClasses(Input, B);
  for (bool LinkedEntry : {false, true}) {
    const auto Report = LinkedEntry ? recoverJava(Linked, B) : recover(Input);
    EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
    EXPECT_EQ(Report.getString("status"), "partial");
    const auto Text = sourceAt(Report, "fixture/Core.java");
    EXPECT_NE(Text.find("fixture.Contract<java.lang.Enum, java.lang.String>"),
              std::string::npos);
    EXPECT_NE(Text.find("java.lang.String echo(java.lang.Enum arg0)"),
              std::string::npos);
    EXPECT_NE(Text.find("(fixture.Marker) o1"), std::string::npos);
    EXPECT_LT(Text.find(".state"), Text.find("(fixture.Marker) o1"));
  }
}

TEST(MobileDalvikJava,
     CheckedEnumParameterRequiresKnownInterfaceAndSafePrefix) {
  for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = checkedEnumBridgeClasses();
    auto &Core = Input[1];
    auto &Target = Core.methods[0];
    switch (Mutation) {
    case 0:
      Input[2].interfaces.clear();
      Input[2].generic_signature = "Ljava/lang/Enum<Lfixture/Choice;>;";
      break;
    case 1:
      Target.instructions[0].registers = {0, 3};
      break;
    case 2:
      Target.instructions[1].registers = {1, 2};
      break;
    case 3:
      Core.fields[0].access.insert("static");
      break;
    case 4:
      Target.instructions[0].opcode = "invoke-static";
      Target.instructions[0].reference =
          MethodRef{"Lfixture/Effects;", "run", {}, "V"};
      Target.instructions[0].registers.clear();
      break;
    }
    rejected([&] { recover(Input); }, "parameter erasure mismatch");
  }
}

