TEST(MobileDalvikJava, EnumRejectsChangedNamesOrdinalsArraysAndSideEffects) {
  const std::vector<std::function<void(Class &)>> Mutations{
      [](Class &C) {
        C.methods[1].instructions[1].literal = std::string("MISMATCH");
      },
      [](Class &C) { C.methods[1].instructions[8].literal = int64_t(0); },
      [](Class &C) { C.methods[1].instructions[14].registers = {2, 1}; },
      [](Class &C) {
        C.methods[2].instructions.erase(C.methods[2].instructions.begin() + 1,
                                        C.methods[2].instructions.begin() + 4);
      },
      [](Class &C) {
        C.methods[1].instructions[17] =
            op(17, "invoke-static", {}, {},
               MethodRef{"Lfixture/Effects;", "run", {}, "V"});
      },
      [](Class &C) { C.methods[0].instructions[0].registers = {0, 2, 1}; },
      [](Class &C) {
        auto M = method("expose", {}, "[" + C.name, 1,
                        {op(0, "sget-object", {0}, {}, C.fields[2].reference),
                         op(1, "return-object", {0})});
        M.reference.owner = C.name;
        C.methods.push_back(M);
      },
      [](Class &C) {
        auto M = method("allocate", {}, C.name, 1,
                        {op(0, "new-instance", {0}, {}, C.name),
                         op(1, "return-object", {0})});
        M.reference.owner = C.name;
        C.methods.push_back(M);
      }};
  for (size_t I = 0; I < Mutations.size(); ++I) {
    SCOPED_TRACE(I);
    auto C = enumClass();
    Mutations[I](C);
    rejected([&] { recover({C}); }, "Android enum");
    Budget B(Limits{});
    rejected([&] { linkClasses({C}, B); }, "Android enum");
  }
}

TEST(MobileDalvikJava, EnumFieldAnnotationTargetsHaveExplicitReportProjection) {
  auto Enum = enumClass();
  auto Stamp = markerClass();
  Stamp.annotation_metadata.retention = "RUNTIME";
  Stamp.annotation_metadata.targets = {"TYPE"};
  auto Value = method("value", {}, "Ljava/lang/String;", 0, {});
  Value.access = {"public", "abstract"};
  Value.reference.owner = Stamp.name;
  Stamp.methods.push_back(Value);
  Enum.fields[0].annotations.push_back(
      {Stamp.name, 1, {{"value", {0x17, std::string("owned-note")}}}});
  auto Report = recover({Enum, Stamp});
  const auto *Bindings = Report.getArray("class_source_bindings");
  ASSERT_NE(Bindings, nullptr);
  const auto *Constant = Bindings->front()
                             .getAsObject()
                             ->getArray("constants")
                             ->front()
                             .getAsObject();
  EXPECT_EQ(Constant->getString("annotation_status"), "report-only");
  const auto *Original = Constant->getArray("original_annotations");
  ASSERT_NE(Original, nullptr);
  ASSERT_EQ(Original->size(), 1u);
  EXPECT_EQ(Original->front().getAsObject()->getString("source_declaration"),
            "@fixture.ZMarker(value = \"owned-note\")");
  EXPECT_EQ(Original->front().getAsObject()->getInteger("visibility"), 1);
  EXPECT_EQ(sourceAt(Report, "fixture/Choice.java").find("@fixture.ZMarker"),
            std::string::npos);
  EXPECT_EQ(Report.getString("status"), "partial");
  Stamp.annotation_metadata.targets = {"FIELD"};
  auto Allowed = recover({Enum, Stamp});
  EXPECT_NE(sourceAt(Allowed, "fixture/Choice.java").find("@fixture.ZMarker"),
            std::string::npos);
  Stamp.annotation_metadata.targets = {"TYPE"};
  Enum.fields[0].annotations[0].elements["value"] = {4, int64_t(7)};
  rejectAnnotationBoth({Enum, Stamp});
  Enum.fields[0].annotations[0].elements["value"] = {0x17,
                                                     std::string("owned-note")};
  auto Ordinary = klass("Lfixture/Ordinary;");
  Ordinary.fields.push_back({{Ordinary.name, "value", "I"}, {"public"}});
  Ordinary.fields[0].annotations = Enum.fields[0].annotations;
  rejected([&] { recover({Ordinary, Stamp}); },
           "annotation target excludes declaration");
}

