std::vector<Class> namedEnumClasses() {
  auto Root = enumClass();
  Root.access.erase("final");
  auto Child =
      memberClass(klass("Lfixture/Choice$Second;"), Root, "Second", "");
  Child.access = {"final"};
  Child.inner_access = {"static", "final"};
  Child.superclass = Root.name;
  const auto Primary = Root.methods[0].reference;
  auto AccessParameters = Primary.parameters;
  AccessParameters.push_back("Ljava/lang/Object;");
  auto Access = method("<init>", AccessParameters, "V", 5,
                       {op(0, "invoke-direct", {0, 1, 2, 3}, {}, Primary),
                        op(1, "return-void")});
  Access.reference.owner = Root.name;
  Access.access = {"public", "synthetic", "constructor"};
  Root.methods.push_back(Access);
  auto Constructor =
      method("<init>", Primary.parameters, "V", 5,
             {op(0, "const/4", {0}, int64_t(0)),
              op(1, "invoke-direct", {1, 2, 3, 4, 0}, {}, Access.reference),
              op(2, "return-void")});
  Constructor.access = {"constructor"};
  Constructor.generic_signature = "(I)V";
  Child.methods.push_back(Constructor);
  const MethodRef Helper{Child.name, "adjust", {"I"}, "I"};
  auto Score = method("score", {"I"}, "I", 3,
                      {op(0, "invoke-direct", {1, 2}, {}, Helper),
                       op(1, "move-result", {0}), op(2, "return", {0})});
  Score.access = {"public"};
  Child.methods.push_back(Score);
  auto Adjust = method(
      "adjust", {"I"}, "I", 2,
      {op(0, "add-int/lit8", {1, 1}, int64_t(-7)), op(1, "return", {1})});
  Adjust.access = {"private"};
  Child.methods.push_back(Adjust);
  for (auto &M : Child.methods)
    M.reference.owner = Child.name;
  Root.methods[1].instructions[6].reference = Child.name;
  Root.methods[1].instructions[10].reference = Child.methods[0].reference;
  auto Stamp = markerClass("Lfixture/Stamp;");
  Stamp.annotation_metadata.retention = "RUNTIME";
  Stamp.annotation_metadata.targets = {"TYPE"};
  auto Element = method("value", {}, "I", 0, {});
  Element.reference.owner = Stamp.name;
  Element.access = {"public", "abstract"};
  Stamp.methods.push_back(Element);
  Child.annotations = {
      {Stamp.name, 1, {{"value", AnnotationValue{4, int64_t(11)}}}}};
  return {Root, Child, Stamp};
}

TEST(MobileDalvikJava,
     NamedEnumConstantPreservesBodiesAndRecordsClassMetadata) {
  auto Classes = namedEnumClasses();
  const auto Report = recover(Classes);
  const auto Text = sourceAt(Report, "fixture/Choice.java");
  EXPECT_NE(Text.find("this.adjust("), std::string::npos);
  EXPECT_EQ(Text.find("Choice.Second"), std::string::npos);
  EXPECT_EQ(Text.find("@fixture.Stamp"), std::string::npos);
  EXPECT_EQ(Report.getInteger("class_count"), 3);
  EXPECT_EQ(Report.getInteger("method_count"), 9);
  EXPECT_EQ(Report.getString("status"), "partial");
  bool Found = false;
  for (const auto &Value : *Report.getArray("class_source_bindings")) {
    const auto &Binding = *Value.getAsObject();
    if (Binding.getString("binding_kind") != "enum-constant-body")
      continue;
    Found = true;
    EXPECT_EQ(Binding.getString("binary_name_status"), "changed");
    EXPECT_EQ(Binding.getString("class_annotation_status"), "report-only");
    const auto *Uses = Binding.getArray("original_annotations");
    ASSERT_NE(Uses, nullptr);
    ASSERT_EQ(Uses->size(), 1u);
    EXPECT_EQ(Uses->front().getAsObject()->getString("type"),
              "Lfixture/Stamp;");
    EXPECT_EQ(Uses->front().getAsObject()->getInteger("visibility"), 1);
    EXPECT_EQ(Uses->front().getAsObject()->getString("source_declaration"),
              "@fixture.Stamp(value = 0x0000000b)");
  }
  EXPECT_TRUE(Found);
  Budget B;
  EXPECT_NO_THROW(linkClasses(Classes, B));
}

TEST(MobileDalvikJava,
     EnumConstantBodiesResolveInheritedStaticFieldsWithoutSubtypeNames) {
  for (const auto &Type :
       {std::string("Lfixture/Choice;"), std::string("I"), std::string("J"),
        std::string("Z"), std::string("Ljava/lang/Object;")})
    for (bool Anonymous : {false, true})
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Type, Anonymous, Route}));
        auto Input = namedEnumClasses();
        auto &Root = Input[0];
        auto &Child = Input[1];
        if (Anonymous) {
          Child.inner_name.reset();
          Child.access.insert("enum");
          Child.inner_access = {"static", "enum"};
        }
        FieldRef Field{Root.name, Type == Root.name ? "FIRST" : "o0", Type};
        if (Type != Root.name)
          Root.fields.push_back({Field, {"public", "static", "volatile"}, {}});
        Field.owner = Child.name;
        const std::string Opcode = (Type.front() == 'L') ? "sget-object"
                                   : Type == "J"         ? "sget-wide"
                                   : Type == "Z"         ? "sget-boolean"
                                                         : "sget";
        auto Read = method("inspect", {}, Type, Type == "J" ? 3 : 2,
                           {op(0, Opcode, {0}, {}, Field),
                            op(1,
                               Type == "J"             ? "return-wide"
                               : (Type.front() == 'L') ? "return-object"
                                                       : "return",
                               {0})});
        Read.reference.owner = Child.name;
        Read.access = {"public"};
        Child.methods.push_back(Read);
        const auto Original = Input;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        ClassMap Classes;
        if (Route)
          Classes = linkClasses(Input, B);
        else
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
        const auto Report = recoverJava(Classes, B);
        const auto Text = sourceAt(Report, "fixture/Choice.java");
        EXPECT_NE(Text.find(") null)." + Field.name), std::string::npos);
        EXPECT_EQ(Text.find("Choice.Second"), std::string::npos);
        EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
        for (const auto &C : Original) {
          const auto &After = Classes.at(C.name);
          EXPECT_EQ(After.access, C.access);
          EXPECT_EQ(After.inner_name, C.inner_name);
          for (size_t I = 0; I < C.methods.size(); ++I)
            EXPECT_EQ(After.methods[I].reference, C.methods[I].reference);
        }
      }
}

TEST(MobileDalvikJava,
     EnumConstantStaticFieldBindingRejectsEscapesUnknownFieldsAndRoleChanges) {
  for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = namedEnumClasses();
    auto &Root = Input[0];
    auto &Child = Input[1];
    Child.inner_name.reset();
    Child.access.insert("enum");
    Child.inner_access = {"static", "enum"};
    FieldRef Field{Root.name, "state", "I"};
    Root.fields.push_back({Field, {"public", "static", "volatile"}, {}});
    Field.owner = Child.name;
    auto Read = method("inspect", {}, "I", 2,
                       {op(0, "sget", {0}, {}, Field), op(1, "return", {0})});
    Read.reference.owner = Child.name;
    Read.access = {"public"};
    if (Mutation == 0)
      Root.fields.back().access.erase("static");
    else if (Mutation == 1)
      std::get<FieldRef>(Read.instructions[0].reference).name = "missing";
    else if (Mutation == 2)
      Read.reference.owner = Root.name;
    else if (Mutation == 3)
      Read.reference.returns = Child.name;
    else
      Child.fields.push_back({Field, {"public", "static", "volatile"}, {}});
    (Mutation == 2 ? Root : Child).methods.push_back(Read);
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

TEST(MobileDalvikJava,
     NamedEnumConstantRejectsEscapingTypesAndUnprovenConstructors) {
  const std::vector<std::function<void(std::vector<Class> &)>> Mutations{
      [](auto &C) { C[1].methods[0].generic_signature = "()V"; },
      [](auto &C) {
        C[1].methods[0].generic_signature = "<T:Ljava/lang/Object;>(I)V";
      },
      [](auto &C) {
        C[1].methods[0].instructions[1].registers = {1, 2, 4, 3, 0};
      },
      [](auto &C) { C[1].inner_access.erase("static"); },
      [](auto &C) { C[1].access.erase("final"); },
      [](auto &C) {
        C[0].fields.push_back(
            {{C[0].name, "escape", C[1].name}, {"public"}, {}});
      }};
  for (size_t I = 0; I < Mutations.size(); ++I) {
    SCOPED_TRACE(I);
    auto Classes = namedEnumClasses();
    Mutations[I](Classes);
    rejectAnnotationBoth(Classes);
  }
}

