std::vector<Class>
containedConsumerParameterClasses(bool SourceContract = false) {
  auto Resume = method("resume", {"Ljava/lang/Object;"}, "V", 0, {});
  Resume.access = {"public", "abstract"};
  Resume.generic_signature = "(TT;)V";
  auto Consumer = klass("Lfixture/Consumer;", {Resume});
  Consumer.access = {"public", "abstract", "interface"};
  Consumer.external = true;
  Consumer.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Request = method("request", {"Lfixture/Value;", Consumer.name},
                        "Ljava/lang/Object;", 0, {});
  Request.access = {"public", "abstract"};
  Request.generic_signature = "(Lfixture/Value;Lfixture/Consumer<Ljava/lang/"
                              "Object;>;)Ljava/lang/Object;";
  auto Service = klass("Lfixture/Service;", {Request});
  Service.access = {"public", "abstract", "interface"};
  Service.external = !SourceContract;
  if (!SourceContract)
    Service.generic_signature = "Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = method("request", Request.reference.parameters,
                       "Ljava/lang/Object;", 3, {op(0, "return-object", {1})});
  Target.access = {"public"};
  Target.generic_signature =
      "(Lfixture/Value;Lfixture/Consumer<-Lfixture/Value;>;)Ljava/lang/Object;";
  auto Core = klass("Lfixture/Core;", {Init, Target});
  Core.access.insert("final");
  Core.interfaces = {Service.name};
  if (!SourceContract)
    Core.generic_signature = "Ljava/lang/Object;Lfixture/Service;";
  auto Value = klass("Lfixture/Value;", {});
  Value.external = true;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Core, Service, Consumer, Value, Object};
}

std::vector<Class> inheritedContainedConsumerParameterClasses(bool External,
                                                              bool Transitive,
                                                              bool Superclass) {
  auto Input = containedConsumerParameterClasses(true);
  auto &Core = Input[0];
  auto &Root = Input[1];
  Root.external = External;
  Root.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Root.methods[0].reference.parameters[0] = Input[2].name;
  Root.methods[0].generic_signature =
      "(Lfixture/Consumer<-TT;>;Lfixture/Consumer<-Lfixture/Value;>;)Ljava/"
      "lang/Object;";
  auto Required = Root.methods[0];
  Required.generic_signature =
      "(Lfixture/Consumer<-TM;>;Lfixture/Consumer<*>;)Ljava/lang/Object;";
  auto Middle = klass("Lfixture/MiddleConsumerApi;", {Required});
  Middle.access = {"public", "interface", "abstract"};
  Middle.interfaces = {Root.name};
  Middle.generic_signature =
      "<M:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Service<TM;>;";
  auto &Target = Core.methods[1];
  Target.reference.parameters[0] = Input[2].name;
  Target.generic_signature =
      "(Lfixture/Consumer<-TC;>;Lfixture/Consumer<*>;)Ljava/lang/Object;";
  auto Leaf = klass("Lfixture/LeafConsumerApi;");
  Leaf.access = {"public", "interface", "abstract"};
  Leaf.interfaces = {Middle.name};
  Leaf.generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/"
                           "MiddleConsumerApi<TQ;>;";
  const auto Interface = Transitive ? Leaf.name : Middle.name;
  Core.interfaces = {Interface, Root.name};
  Core.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;" +
                           Interface.substr(0, Interface.size() - 1) +
                           "<TC;>;Lfixture/Service<TC;>;";
  auto Base = klass("Lfixture/ConsumerBase;", {Input[0].methods[0]});
  Base.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Superclass) {
    Core.access.erase("final");
    Core.superclass = Base.name;
    Core.generic_signature =
        "<C:Ljava/lang/Object;>Lfixture/ConsumerBase<TC;>;" +
        Interface.substr(0, Interface.size() - 1) +
        "<TC;>;Lfixture/Service<TC;>;";
    Core.methods[0].instructions[0].reference = Base.methods[0].reference;
  }
  Input.push_back(Middle);
  Input.push_back(Leaf);
  Input.push_back(Base);
  if (Superclass) {
    auto Init = Input[0].methods[0];
    Init.instructions[0].reference = Input[0].methods[0].reference;
    auto Child = klass("Lfixture/InheritedConsumer;", {Init});
    Child.superclass = Input[0].name;
    Child.generic_signature = "<D:Ljava/lang/Object;>Lfixture/Core<TD;>;";
    Input.push_back(Child);
  }
  return Input;
}

