std::vector<Class> anonymousInheritedContractClasses(bool External) {
  auto Input = genericAnonymousMemberClasses();
  auto &Member = Input[1];
  auto &Api = Input[2];
  Api.external = External;
  auto Listen = method(
      "listen", {"Ljava/lang/Runnable;", "Ljava/util/concurrent/Executor;"},
      "V", 0, {});
  Listen.reference.owner = Api.name;
  Listen.access = {"public", "abstract"};
  Api.methods.push_back(Listen);
  auto Ready =
      method("ready", {}, "Z", 2,
             {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  Ready.reference.owner = Api.name;
  Ready.access = {"public"};
  Api.methods.push_back(Ready);
  auto Root = klass("Lfixture/Root;");
  Root.external = External;
  Root.access.insert("abstract");
  Root.interfaces = {Api.name};
  Root.generic_signature =
      "<R:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Reader<TR;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.reference.owner = Root.name;
  Init.access = {"public", "constructor"};
  auto Read =
      method("read", {}, "Ljava/lang/Object;", 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.reference.owner = Root.name;
  Read.generic_signature = "()TR;";
  Read.access = {"public", "final"};
  Listen.reference.owner = Root.name;
  Listen.access = {"public", "final"};
  Listen.registers = 3;
  Listen.instructions = {op(0, "return-void")};
  Listen.code_end = 1;
  Root.methods = {Init, Read, Listen};
  Member.superclass = Root.name;
  Member.interfaces.clear();
  Member.generic_signature = "Lfixture/Root<TT;>;";
  Member.methods[0].instructions[1].reference = Init.reference;
  Member.methods[1].reference.name = "capturedValue";
  if (External) {
    for (auto *Declaration : {&Api, &Root})
      for (auto &Method : Declaration->methods) {
        Method.instructions.clear();
        Method.registers = 0;
        Method.code_end = 0;
      }
  }
  Input.push_back(Root);
  for (const auto &Name :
       {"Ljava/lang/Runnable;", "Ljava/util/concurrent/Executor;"}) {
    auto Plain = klass(Name);
    Plain.external = true;
    Plain.access = {"public", "abstract", "interface"};
    Input.push_back(Plain);
  }
  return Input;
}

