std::vector<Class>
recursiveParentUncheckedCallbackClasses(bool External = false,
                                        bool Error = false) {
  auto Update = method("update", {"[B"}, "[B", 0, {});
  Update.access = {"public", "abstract"};
  auto Adapt = method("adapt", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
                      {op(0, "return-object", {1})});
  Adapt.access = {"public"};
  auto Root = klass("Lfixture/Updates;", {Update, Adapt});
  Root.external = External;
  Root.access = {"public", "abstract", "interface"};
  if (External) {
    Root.methods[1].instructions.clear();
    Root.methods[1].registers = Root.methods[1].code_end = 0;
  }
  const auto Init = [](const std::string &Parent) {
    auto M = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    M.access = {"public", "constructor"};
    return M;
  };
  auto Base = klass("Lfixture/Base;", {Init("Ljava/lang/Object;")});
  Base.generic_signature = "<B:Lfixture/Base<TB;>;>Ljava/lang/Object;";
  auto Parent = klass("Lfixture/Parent;", {Init(Base.name)});
  Parent.superclass = Base.name;
  Parent.access.insert("abstract");
  Parent.interfaces = {Root.name};
  Parent.generic_signature =
      "<P:Lfixture/Parent<TP;>;>Lfixture/Base<TP;>;Lfixture/Updates;";
  Update.access = {"public"};
  Update.declared_throws = std::vector<std::string>{"Lfixture/LeafFailure;"};
  Update.registers = 2;
  Update.instructions = {op(0, "return-object", {1})};
  Update.code_end = 1;
  auto Core = klass("Lfixture/ACore;", {Init(Parent.name), Update});
  Core.superclass = Parent.name;
  Core.generic_signature = "Lfixture/Parent<Lfixture/ACore;>;";
  auto Failure = klass("Lfixture/LeafFailure;");
  Failure.external = true;
  Failure.superclass = "Lfixture/MidFailure;";
  auto Mid = klass("Lfixture/MidFailure;");
  Mid.external = true;
  Mid.superclass = Error ? "Ljava/lang/Error;" : "Ljava/lang/RuntimeException;";
  return {Core, Parent, Base, Root, Failure, Mid};
}

