            auto &Provided = Input[1].methods[0];
            const auto RequiredRef = Required.reference;
            const auto ProvidedRef = Provided.reference;
            if (Mutation == 0)
              Input[4].superclass = "Ljava/lang/Exception;";
            else if (Mutation == 1)
              Provided.declared_throws->push_back("Ljava/lang/Exception;");
            else if (Mutation == 2)
              Required.generic_signature =
                  *Required.generic_signature + "^Lfixture/RequiredFailure;";
            else if (Mutation == 3)
              Provided.generic_signature =
                  *Provided.generic_signature + "^Lfixture/UncheckedLeaf;";
            else if (Mutation == 4)
              Provided.generic_signature =
                  MethodScope
                      ? "<R:Ljava/lang/Object;>(Ljava/lang/Class<*>;)TR;"
                      : "()Ljava/lang/Object;";
            else if (Mutation == 5)
              Provided.access.insert("static");
