TEST(MobileDalvikJava, FixedDefaultExceptionsRequireCompleteOriginalProofs) {
  for (bool External : {false, true})
    for (bool ReturnBridge : {false, true})
      for (bool Reverse : {false, true})
        for (unsigned Mutation = 0; Mutation < (ReturnBridge ? 15u : 11u);
             ++Mutation) {
          SCOPED_TRACE(External);
          SCOPED_TRACE(ReturnBridge);
          SCOPED_TRACE(Reverse);
          SCOPED_TRACE(Mutation);
          auto Input = fixedExceptionDefaultOverrideClasses(External, false,
                                                            ReturnBridge);
          auto &Typed = Input[0].methods[0];
          auto &Required = Input[1].methods[0];
          const auto TypedRef = Typed.reference,
                     RequiredRef = Required.reference;
          if (Mutation == 0)
            Typed.declared_throws = {"Ljava/lang/Throwable;"};
          else if (Mutation == 1)
            Typed.generic_signature =
                *Typed.generic_signature + "^Lfixture/First;";
          else if (Mutation == 2)
            Required.generic_signature =
                *Required.generic_signature + "^Lfixture/First;";
          else if (Mutation == 3)
            Typed.generic_signature =
                "(Lfixture/Carrier<Ljava/lang/String;Ljava/lang/Number;>;)" +
                Typed.reference.returns;
          else if (Mutation == 4)
            Typed.generic_signature.reset();
          else if (Mutation == 5)
            Typed.access.insert("static");
          else if (Mutation == 6)
            Typed.access = {"private"};
          else if (Mutation == 7)
            Required.declared_throws = {"Lfixture/UnknownFailure;"};
          else if (Mutation == 8)
            Typed.declared_throws = {"Lfixture/UnknownFailure;"};
          else if (Mutation == 11)
            Input[0].methods[1].declared_throws = {"Lfixture/Second;"};
          else if (Mutation == 12)
            Input[0].methods[1].access.erase("bridge");
          else if (Mutation == 13)
            Input[0].methods[1].instructions[0].opcode = "invoke-direct";
          else if (Mutation == 14)
            Input[0].methods[1].instructions[0].registers = {2, 1};
          if (Reverse) {
            std::reverse(Input.begin(), Input.end());
            for (auto &Owner : Input)
              std::reverse(Owner.methods.begin(), Owner.methods.end());
          }
          Budget B;
          if (Mutation == 9 || Mutation == 10) {
            auto Classes = linkClasses(Input, B);
            auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_EQ(Plans.closed_declared_throws.erase(
                          Mutation == 9 ? RequiredRef : TypedRef),
                      1u);
            EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                         std::runtime_error);
          } else
            EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                         std::runtime_error);
        }
}

std::vector<Class> uncheckedDefaultOverrideClasses(bool External = false,
                                                   bool Error = false) {
  auto Input = uncheckedBridgeTargetThrowsClasses(External, Error);
  auto Reset = method("reset", {}, "V", 1, {op(0, "return-void")});
  Reset.access = {"public"};
  Reset.reference.owner = Input[0].name;
  Input[0].methods.push_back(Reset);
  if (External) {
    auto &Declaration = Input[0].methods.back();
    Declaration.instructions.clear();
    Declaration.registers = Declaration.code_end = 0;
  }
  Reset.reference.owner = Input[1].name;
  Reset.declared_throws = Input[1].methods[1].declared_throws;
  Input[1].methods.push_back(Reset);
  return Input;
}

