std::vector<Class> fixedParameterizedBridgeThrowsClasses(bool External = false,
                                                         bool Empty = false) {
  const std::vector<std::string> Exceptions{"Ljava/lang/Exception;",
                                            "Ljava/lang/RuntimeException;"};
  auto Convert = method("convert", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
                        "Ljava/lang/Object;", 0, {});
  Convert.access = {"public", "abstract"};
  Convert.generic_signature = "(Ljava/lang/Object;TT;)TT;";
  Convert.declared_throws = Exceptions;
  auto Api = klass("Lfixture/ParameterizedThrowsApi;", {Convert});
  Api.external = External;
  Api.access = {"public", "abstract", "interface"};
  Api.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/ThrowsBox;");
  Box.external = true;
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Typed = method("convert", {"Ljava/lang/Object;", Box.name}, Box.name, 3,
                      {op(0, "return-object", {2})});
  Typed.access = {"public"};
  Typed.generic_signature =
      "(Ljava/lang/Object;Lfixture/ThrowsBox<*>;)Lfixture/ThrowsBox<*>;";
  if (!Empty)
    Typed.declared_throws = Exceptions;
  auto Bridge =
      method("convert", {"Ljava/lang/Object;", "Ljava/lang/Object;"},
             "Ljava/lang/Object;", 3,
             {op(0, "check-cast", {2}, {}, Box.name),
              op(2, "invoke-virtual", {0, 1, 2}, {},
                 MethodRef{"Lfixture/ParameterizedCodec;",
                           "convert",
                           {"Ljava/lang/Object;", Box.name},
                           Box.name}),
              op(5, "move-result-object", {1}), op(6, "return-object", {1})});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.declared_throws = Exceptions;
  auto Owner = klass("Lfixture/ParameterizedCodec;", {Init, Typed, Bridge});
  Owner.interfaces = {Api.name};
  Owner.generic_signature = "Ljava/lang/Object;Lfixture/"
                            "ParameterizedThrowsApi<Lfixture/ThrowsBox<*>;>;";
  return {Api, Owner, Box};
}

std::vector<Class>
emptyInheritedBridgeThrowsClasses(bool External, bool ClassParent, bool Plain) {
  auto Input = fixedParameterizedBridgeThrowsClasses(External, true);
  Input[1].methods[2].declared_throws.reset();
  if (Plain) {
    Input[2].generic_signature.reset();
    Input[1].methods[1].generic_signature.reset();
    Input[1].generic_signature = "Ljava/lang/Object;Lfixture/"
                                 "ParameterizedThrowsApi<Lfixture/ThrowsBox;>;";
  }
  if (ClassParent) {
    auto &Parent = Input[0];
    auto &Child = Input[1];
    Parent.access.erase("interface");
    auto Init = Child.methods[0];
    Init.reference.owner = Parent.name;
    if (External) {
      Init.instructions.clear();
      Init.registers = Init.code_end = 0;
    }
    Parent.methods.push_back(Init);
    Child.superclass = Parent.name;
    Child.interfaces.clear();
    Child.generic_signature =
        Plain ? "Lfixture/ParameterizedThrowsApi<Lfixture/ThrowsBox;>;"
              : "Lfixture/ParameterizedThrowsApi<Lfixture/ThrowsBox<*>;>;";
    Child.methods[0].instructions[0].reference = Init.reference;
  }
  return Input;
}

TEST(MobileDalvikJava,
     EmptyOriginalBridgesKeepClosedInheritedExceptionDifferences) {
  for (bool External : {false, true})
    for (bool ClassParent : {false, true})
      for (bool Plain : {false, true})
        for (bool Link : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input =
                emptyInheritedBridgeThrowsClasses(External, ClassParent, Plain);
            const auto Bridge = Input[1].methods[2].reference;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            bool Found = false;
            for (const auto &Value : *R.getArray("methods")) {
              const auto *Row = Value.getAsObject();
              if (Row->getString("identity") == Bridge.identity()) {
                EXPECT_EQ(Row->getString("projection_kind"),
                          ClassParent ? "generic-superclass-bridge"
                                      : "generic-interface-bridge");
                ASSERT_NE(Row->getArray("source_bridge_declared_throws"),
                          nullptr);
                EXPECT_EQ(
                    Row->getArray("source_bridge_declared_throws")->size(), 2u);
                EXPECT_NE(Row->getArray("metadata_differences"), nullptr);
                Found = true;
              }
            }
            EXPECT_TRUE(Found);
          }
}

std::vector<Class>
emptyCovariantBridgeThrowsClasses(bool External, bool ClassParent, bool Plain) {
  auto Input = emptyInheritedBridgeThrowsClasses(External, ClassParent, Plain);
  auto &Required = Input[0].methods[0];
  auto &Typed = Input[1].methods[1];
  auto &Bridge = Input[1].methods[2];
  Required.reference.parameters.clear();
  Required.generic_signature = "()TT;";
  Typed.reference.parameters.clear();
  if (!Plain)
    Typed.generic_signature = "()Lfixture/ThrowsBox<*>;";
  Typed.registers = 2;
  Typed.instructions = {op(0, "const/4", {0}, int64_t(0)),
                        op(1, "return-object", {0})};
  Typed.code_end = 2;
  Bridge.reference.parameters.clear();
  Bridge.registers = 2;
  Bridge.instructions = {op(0, "invoke-virtual", {1}, {}, Typed.reference),
                         op(3, "move-result-object", {0}),
                         op(4, "return-object", {0})};
  Bridge.code_end = 5;
  return Input;
}

TEST(MobileDalvikJava, EmptyCovariantBridgesReportInheritedExceptionMetadata) {
  for (bool External : {false, true})
    for (bool ClassParent : {false, true})
      for (bool Plain : {false, true})
        for (bool Link : {false, true}) {
          auto Input =
              emptyCovariantBridgeThrowsClasses(External, ClassParent, Plain);
          const auto Bridge = Input[1].methods[2].reference;
          if (Link) {
            std::reverse(Input.begin(), Input.end());
            for (auto &Cls : Input)
              std::reverse(Cls.methods.begin(), Cls.methods.end());
          }
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 1);
          bool Found = false;
          for (const auto &Value : *R.getArray("methods")) {
            const auto *Row = Value.getAsObject();
            if (Row->getString("identity") != Bridge.identity())
              continue;
            const auto *Throws = Row->getArray("source_bridge_declared_throws");
            ASSERT_NE(Throws, nullptr);
            EXPECT_EQ(Throws->size(), 2u);
            EXPECT_NE(Row->getArray("metadata_differences"), nullptr);
            Found = true;
          }
          EXPECT_TRUE(Found);
        }
}

