TEST(MobileDalvikJava, ParameterizedFixedThrowsRequireOriginalClosedProofs) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(Link);
      SCOPED_TRACE(Mutation);
      auto Input = fixedParameterizedBridgeThrowsClasses(true, Mutation == 11);
      auto &Required = Input[0].methods[0];
      auto &Typed = Input[1].methods[1];
      auto &Bridge = Input[1].methods[2];
      if (Mutation == 0)
        Typed.declared_throws = {"Ljava/lang/Throwable;"};
      else if (Mutation == 1)
        Typed.generic_signature =
            "(Ljava/lang/Object;Lfixture/ThrowsBox<*>;)Lfixture/"
            "ThrowsBox<*>;^Ljava/lang/Exception;";
      else if (Mutation == 2)
        Required.generic_signature =
            "(Ljava/lang/Object;TT;)TT;^Ljava/lang/Exception;";
      else if (Mutation == 3)
        Typed.declared_throws = {"Lfixture/MissingFailure;"};
      else if (Mutation == 4)
        Typed.declared_throws = {"Ljava/lang/String;"};
      else if (Mutation == 5)
        std::reverse(Bridge.declared_throws->begin(),
                     Bridge.declared_throws->end());
      else if (Mutation == 6)
        Bridge.instructions[0].reference = std::string("Ljava/lang/String;");
      else if (Mutation == 7)
        Typed.generic_signature = "(Ljava/lang/Object;Lfixture/ThrowsBox<Ljava/"
                                  "lang/String;>;)Lfixture/ThrowsBox<*>;";
      else if (Mutation == 8) {
        Input[1].generic_signature =
            "Ljava/lang/Object;Lfixture/ParameterizedThrowsApi<Lfixture/"
            "ThrowsBox<Ljava/lang/String;>;>;";
        Typed.generic_signature = "(Ljava/lang/Object;Lfixture/ThrowsBox<Ljava/"
                                  "lang/String;>;)Lfixture/ThrowsBox<*>;";
      } else if (Mutation == 11)
        Typed.generic_signature =
            "(Ljava/lang/Object;Lfixture/ThrowsBox<*>;)Lfixture/"
            "ThrowsBox<*>;^Ljava/lang/RuntimeException;";
      Budget B;
      if (Mutation == 9 || Mutation == 10) {
        auto Classes = linkClasses(Input, B);
        auto Plans = validateGenericSignatures(Classes, B);
        ASSERT_EQ(Plans.closed_declared_throws.erase(
                      Mutation == 9 ? Typed.reference : Required.reference),
                  1u);
        EXPECT_THROW(planGenericInheritance(Classes, Plans, B),
                     std::runtime_error);
      } else
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
    }
}

std::vector<Class> inheritedFixedThrowsClasses(bool External) {
  auto Input = anonymousInheritedContractClasses(External);
  const std::vector<std::string> Exceptions{
      "Ljava/io/IOException;", "Ljava/lang/ReflectiveOperationException;"};
  Input[2].methods[0].declared_throws = Exceptions;
  std::reverse(Input[2].methods[0].declared_throws->begin(),
               Input[2].methods[0].declared_throws->end());
  Input[3].methods[1].declared_throws = Exceptions;
  Input[2].methods[1].declared_throws = {"Ljava/io/IOException;"};
  Input[3].methods[2].declared_throws = {"Ljava/io/IOException;"};
  for (const auto &Name : Exceptions) {
    auto Failure = klass(Name);
    Failure.external = true;
    Failure.superclass = "Ljava/lang/Exception;";
    Input.push_back(Failure);
  }
  return Input;
}

TEST(MobileDalvikJava,
     InheritedFixedThrowsRetainOriginalSetsAndDeclarationOrder) {
  for (bool External : {false, true})
    for (bool Reverse : {false, true})
      for (bool Link : {false, true})
        for (bool Narrow : {false, true}) {
          SCOPED_TRACE(Narrow);
          auto Input = inheritedFixedThrowsClasses(External);
          if (Narrow)
            Input[3].methods[1].declared_throws = {"Ljava/io/IOException;"};
          const auto OriginalApi = Input[2].methods[0].declared_throws;
          const auto OriginalBody = Input[3].methods[1].declared_throws;
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R =
              Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("method_count"), External ? 3 : 9);
          EXPECT_EQ(R.getString("status"), "partial");
          const auto &Api =
              *std::find_if(Input.begin(), Input.end(), [](const Class &C) {
                return C.name == "Lfixture/Reader;";
              });
          const auto &Root =
              *std::find_if(Input.begin(), Input.end(), [](const Class &C) {
                return C.name == "Lfixture/Root;";
              });
          EXPECT_EQ(Api.methods[0].declared_throws, OriginalApi);
          EXPECT_EQ(Root.methods[1].declared_throws, OriginalBody);
          ClassMap Original;
          for (const auto &C : Input)
            Original.emplace(C.name, C);
          Budget Validation;
          const auto Plans = validateGenericSignatures(Original, Validation);
          EXPECT_EQ(Plans.declared_throws.at(Api.methods[0].reference),
                    *OriginalApi);
          EXPECT_EQ(Plans.declared_throws.at(Root.methods[1].reference),
                    *OriginalBody);
          const auto &RequiredThrows =
              Plans.closed_declared_throws.at(Api.methods[0].reference);
          const auto &ProvidedThrows =
              Plans.closed_declared_throws.at(Root.methods[1].reference);
          EXPECT_TRUE(
              std::includes(RequiredThrows.begin(), RequiredThrows.end(),
                            ProvidedThrows.begin(), ProvidedThrows.end()));
          EXPECT_EQ(Plans.closed_declared_throws.at(Api.methods[1].reference),
                    Plans.closed_declared_throws.at(Root.methods[2].reference));
        }
}

TEST(MobileDalvikJava, InheritedFixedThrowsRejectSetHierarchyAndGenericDrift) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = inheritedFixedThrowsClasses(External);
      auto &Api = Input[2].methods[0];
      auto &Body = Input[3].methods[1];
      if (Mutation == 0)
        Body.declared_throws = {"Ljava/lang/Throwable;"};
      else if (Mutation == 1)
        Api.declared_throws.reset();
      else if (Mutation == 2)
        Body.declared_throws->push_back("Ljava/io/IOException;");
      else if (Mutation == 3)
        Input.back().superclass = "Ljava/lang/Object;";
      else if (Mutation == 4)
        Input.back().superclass = Input.back().name;
      else if (Mutation == 5) {
        Body.generic_signature = "<E:Ljava/lang/Throwable;>()TR;^TE;";
        Api.declared_throws = Body.declared_throws = {"Ljava/lang/Throwable;"};
      } else
        Input[3].methods[2].declared_throws = {
            "Ljava/lang/ReflectiveOperationException;"};
      rejected([&] { recover(Input); }, "generic");
    }
}

// The source name is a property of the exact declaration, including callers
// whose DEX reference names a descendant. No generated-name prefix is special.
std::vector<Class> staticIdentifierClasses() {
  auto Read = method("read-value", {"Ljava/lang/Object;"}, "Ljava/lang/Object;",
                     1, {op(0, "return-object", {0})});
  Read.access.insert("synthetic");
  auto Touch = method("touch-value", {"Ljava/lang/Object;"}, "V", 1,
                      {op(0, "return-void")});
  Touch.access.insert("synthetic");
  auto Reserved =
      method("__neverdStaticMethod0", {}, "V", 0, {op(0, "return-void")});
  auto Valid = method("validSynthetic", {}, "V", 0, {op(0, "return-void")});
  Valid.access.insert("synthetic");
  auto Core = klass("Lfixture/Core;", {Touch, Read, Reserved, Valid});
  auto Child = klass("Lfixture/Child;");
  Child.superclass = Core.name;
  MethodRef ReadRef{Child.name, Read.reference.name, Read.reference.parameters,
                    Read.reference.returns};
  MethodRef TouchRef{Core.name, Touch.reference.name,
                     Touch.reference.parameters, Touch.reference.returns};
  auto Call =
      method("call", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 2,
             {op(0, "invoke-static", {1}, {}, TouchRef),
              op(1, "invoke-static", {1}, {}, ReadRef),
              op(2, "move-result-object", {0}), op(3, "return-object", {0})});
  return {Core, Child, klass("Lfixture/Caller;", {Call})};
}

// A valid retained Java identifier still loses an original synthetic flag.
// Naming projections and this independent metadata loss are separate receipts.
void expectRetainedSyntheticMethodFlag(const llvm::json::Object &Report,
                                       const MethodRef &Ref, bool Synthetic) {
  bool Found = false;
  for (const auto &Value : *Report.getArray("methods")) {
    const auto &Row = *Value.getAsObject();
    if (Row.getString("identity") != Ref.identity())
      continue;
    Found = true;
    EXPECT_EQ(Row.getString("status"),
              Synthetic ? "source-projected" : "recovered");
    EXPECT_FALSE(Row.getString("source_name"));
    if (Synthetic) {
      EXPECT_EQ(Row.getString("projection_kind"), "synthetic-method");
      EXPECT_EQ(Row.getString("source_identity"), Ref.identity());
      ASSERT_TRUE(Row.getArray("metadata_differences"));
      ASSERT_EQ(Row.getArray("metadata_differences")->size(), 1u);
      EXPECT_TRUE(Row.getArray("metadata_differences")
                      ->front()
                      .getAsString()
                      ->contains("synthetic access flag"));
    } else {
      EXPECT_FALSE(Row.getString("projection_kind"));
      EXPECT_FALSE(Row.getArray("metadata_differences"));
    }
  }
  EXPECT_TRUE(Found);
}

TEST(MobileDalvikJava, StaticIdentifierNamesMapOwnedAnonymousEnclosures) {
  for (bool Linked : {false, true}) {
    auto Input = staticIdentifierClasses();
    auto Nested = klass("Lfixture/Nested;");
    Nested.access = {"public", "final"};
    Nested.inner_class_present = true;
    Nested.inner_access = {"public", "static", "final"};
    Nested.enclosing_method = Input[0].methods[1].reference;
    auto Init = method("<init>", {}, "V", 1,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
    Init.access = {"constructor"};
    Init.reference.owner = Nested.name;
    Nested.methods = {Init};
    auto &Body = Input[0].methods[1];
    Body.registers = 2;
    Body.instructions = {op(0, "new-instance", {0}, {}, Nested.name),
                         op(1, "invoke-direct", {0}, {}, Init.reference),
                         op(2, "return-object", {1})};
    Body.code_end = 3;
    const auto Owner = Input[0].name;
    Input.push_back(std::move(Nested));
    if (Linked)
      std::reverse(Input.begin(), Input.end());
    Budget B;
    const auto R =
        Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    const auto *Bindings = R.getArray("class_source_bindings");
    ASSERT_NE(Bindings, nullptr);
    ASSERT_EQ(Bindings->size(), 1u);
    const auto *Enclosing =
        Bindings->front().getAsObject()->getObject("source_enclosing_method");
    ASSERT_NE(Enclosing, nullptr);
    EXPECT_EQ(Enclosing->getString("name"), "__neverdStaticMethod1");
    EXPECT_EQ(Enclosing->getString("owner"), Owner);
  }
}

