TEST(MobileDalvikJava, SyntheticStaticNamesShareCollisionFreeDeclarationNames) {
  for (bool Linked : {false, true})
    for (bool Reverse : {false, true}) {
      auto Input = staticIdentifierClasses();
      if (Reverse) {
        for (auto &C : Input)
          std::reverse(C.methods.begin(), C.methods.end());
        std::reverse(Input.begin(), Input.end());
      }
      Budget B;
      const auto R =
          Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(R.getString("status"), "partial");
      EXPECT_EQ(R.getInteger("projected_method_count"), 3);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      ASSERT_NE(R.getArray("generated_source_helpers"), nullptr);
      expectRetainedSyntheticMethodFlag(
          R, {"Lfixture/Core;", "validSynthetic", {}, "V"}, true);
      unsigned Count = 0;
      for (const auto &Value : *R.getArray("methods")) {
        const auto &Row = *Value.getAsObject();
        if (Row.getString("name") == "validSynthetic" ||
            Row.getString("status") != "source-projected")
          continue;
        ++Count;
        EXPECT_EQ(Row.getString("projection_kind"),
                  "synthetic-static-method-identifier");
        const auto Original = *Row.getString("name");
        EXPECT_EQ(Row.getString("source_name"), Original == "read-value"
                                                    ? "__neverdStaticMethod1"
                                                    : "__neverdStaticMethod2");
        ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
        EXPECT_EQ(Row.getArray("metadata_differences")->size(), 3);
      }
      EXPECT_EQ(Count, 2U);
      std::string Text;
      for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
        Text += source(R, I);
      EXPECT_EQ(Text.find("read-value"), std::string::npos);
      EXPECT_EQ(Text.find("touch-value"), std::string::npos);
      EXPECT_NE(Text.find("__neverdStaticMethod1("), std::string::npos);
      EXPECT_NE(Text.find("__neverdStaticMethod2("), std::string::npos);
      EXPECT_NE(Text.find("validSynthetic("), std::string::npos);
    }
}

TEST(MobileDalvikJava,
     SyntheticStaticNamesDoNotAdmitUnknownOrChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = staticIdentifierClasses();
    auto &Read = Input[0].methods[1];
    if (Mutation == 0)
      Read.access.erase("public");
    else if (Mutation == 1) {
      Read.access.erase("public");
      Read.access.insert("private");
    } else if (Mutation == 2) {
      Read.access.erase("static");
      Read.registers = 2;
    } else if (Mutation == 3)
      Input[0].external = true;
    else if (Mutation == 4)
      Input[2].methods[0].instructions[1].opcode = "invoke-virtual";
    else if (Mutation == 5)
      Read.instructions[0].opcode = "unhandled-owned-instruction";
    else {
      Read.access.insert("native");
      Read.instructions.clear();
      Read.code_end = 0;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> privateInstanceIdentifierClasses(bool Synthetic,
                                                    bool Generic, bool Range) {
  auto Read = method("read-wide", {"J", "J"}, "J", 7,
                     {op(0, "add-long", {0, 3, 5}), op(1, "return-wide", {0})});
  Read.access = {"private", "final"};
  if (Synthetic)
    Read.access.insert("synthetic");
  Read.reference.owner = "Lfixture/Core;";
  auto Call =
      method("call", {Read.reference.owner, "J", "J"}, "J", 7,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                 {2, 3, 4, 5, 6}, {}, Read.reference),
              op(1, "move-result-wide", {0}), op(2, "return-wide", {0})});
  auto Reserved =
      method("__neverdPrivateMethod0", {}, "V", 0, {op(0, "return-void")});
  auto Core = klass(Read.reference.owner, {Read, Call, Reserved});
  if (Generic)
    Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Core};
}

