TEST(MobileDalvikJava, PrivateInstanceNamesRejectForeignScopeAndDispatch) {
  for (bool Linked : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      auto Input = privateInstanceIdentifierClasses(false, false, true);
      auto &Core = Input[0];
      if (Mutation == 0) {
        auto Foreign = klass("Lother/Foreign;", {Core.methods[1]});
        Core.methods.erase(Core.methods.begin() + 1);
        Input.push_back(Foreign);
      } else if (Mutation == 1) {
        auto Facade = klass("Lfixture/Facade;");
        Facade.superclass = Core.name;
        std::get<MethodRef>(Core.methods[1].instructions[0].reference).owner =
            Facade.name;
        Input.push_back(Facade);
      } else if (Mutation == 2)
        Core.methods[1].instructions[0].opcode = "invoke-virtual";
      else if (Mutation == 3)
        Core.methods[0].access.erase("private");
      else if (Mutation == 4)
        Core.methods[0].instructions[0].opcode = "unsupported-owned-opcode";
      else if (Mutation == 5) {
        auto Metadata = klass("Lfixture/Metadata;");
        Metadata.external = true;
        Metadata.enclosing_method = Core.methods[0].reference;
        Input.push_back(Metadata);
      } else if (Mutation == 6)
        Core.methods[0].access.insert("native");
      else
        Core.methods[1].instructions[0].registers = {2, 3, 4, 6, 5};
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> privateStaticIdentifierClasses(bool Synthetic,
                                                  bool GenericOwner) {
  auto Input = staticIdentifierClasses();
  auto Call = Input[2].methods[0];
  Call.reference.owner = Input[0].name;
  std::get<MethodRef>(Call.instructions[1].reference).owner = Input[0].name;
  Input[0].methods.push_back(Call);
  Input[0].methods[1].access.erase("public");
  Input[0].methods[1].access.insert("private");
  if (!Synthetic)
    for (auto &M : Input[0].methods)
      M.access.erase("synthetic");
  if (GenericOwner) {
    Input[0].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    Input[1].superclass = "Ljava/lang/Object;";
  }
  Input.pop_back();
  return Input;
}

