            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), Mangled ? 3 : 2);
        EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
