TEST(MobileDalvikJava, PackageSyntheticIdentifiersKeepKnownVirtualFamilies) {
  for (bool Linked : {false, true})
    for (bool Reverse : {false, true})
      for (bool PublicClass : {false, true}) {
        auto Input = packageSyntheticIdentifierClasses();
        if (!PublicClass)
          for (auto &C : Input)
            C.access.erase("public");
        if (Reverse) {
          for (auto &C : Input)
            std::reverse(C.methods.begin(), C.methods.end());
          std::reverse(Input.begin(), Input.end());
        }
        Budget B;
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getString("status"), "partial");
        EXPECT_EQ(R.getInteger("method_count"), 6);
        EXPECT_EQ(R.getInteger("projected_method_count"), 2);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        unsigned Count = 0;
        for (const auto &Value : *R.getArray("methods")) {
          const auto &Row = *Value.getAsObject();
          if (Row.getString("status") != "source-projected")
            continue;
          ++Count;
          EXPECT_EQ(Row.getString("projection_kind"),
                    "virtual-method-identifier");
          EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod1");
          ASSERT_NE(Row.getArray("source_name_family"), nullptr);
          EXPECT_EQ(Row.getArray("source_name_family")->size(), 2U);
          ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
          const auto *Differences = Row.getArray("metadata_differences");
          EXPECT_EQ(Differences->size(), 3U);
          EXPECT_TRUE(std::any_of(
              Differences->begin(), Differences->end(), [](const auto &D) {
                return D.getAsString() &&
                       D.getAsString()->contains("synthetic");
              }));
        }
        EXPECT_EQ(Count, 2U);
        std::string Text;
        for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
          Text += source(R, I);
        EXPECT_EQ(Text.find("accept-value"), std::string::npos);
        EXPECT_NE(Text.find("super.__neverdVirtualMethod1("),
                  std::string::npos);
        EXPECT_NE(Text.find("((fixture.Core) o0).__neverdVirtualMethod1("),
                  std::string::npos);
      }
}

