TEST(MobileDalvikJava,
     ClosedOwnerPackageSyntheticIdentifiersRejectUnprovedScopesAndCalls) {
  for (unsigned Mutation = 0; Mutation != 9; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = closedOwnerPackageSyntheticIdentifierClasses(false);
    auto &Core = Input[0];
    auto &Send = Core.methods[0];
    if (Mutation == 0)
      Core.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/"
                               "Object;Lfixture/Scope<Ljava/lang/String;>;";
    else if (Mutation == 1)
      Send.generic_signature =
          "<T:Ljava/lang/Object;>(Ljava/lang/Object;)Ljava/lang/Object;";
    else if (Mutation == 2)
      Input.pop_back();
    else if (Mutation == 3) {
      Core.external = true;
      for (auto &M : Core.methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    } else if (Mutation == 4)
      Input[1].methods[0].access.insert("public");
    else if (Mutation == 5) {
      Input[2].name = "Lother/Caller;";
      for (auto &M : Input[2].methods)
        M.reference.owner = Input[2].name;
    } else if (Mutation == 6) {
      Core.superclass = "Lfixture/Missing;";
      Core.methods[1].instructions[0].reference =
          MethodRef{*Core.superclass, "<init>", {}, "V"};
    } else if (Mutation == 7)
      Core.generic_signature = "Ljava/lang/Object;Lfixture/Scope<TT;>;";
    else
      Send.access.insert("bridge");
    if (Mutation == 0) {
      // Keep the exact former class-formal negative as a supported case.
      // Its retained independent header does not change the package slot.
      EXPECT_NO_THROW(recover(Input));
    } else
      EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

