std::vector<Class> closedLocalCovariantClasses(bool Dependency, bool Range) {
  auto Input = statelessAnonymousCovariantClasses(false, Range, Dependency);
  auto &Local = Input[1];
  Local.enclosing.reset();
  Local.enclosing_method = Input[0].methods[0].reference;
  Local.deprecated = false;
  Local.inner_access.erase("static");
  const FieldRef State{Local.name, "state", "J"};
  Local.fields = {{State, {"private", "final"}, {}}};
  auto &Init = Local.methods[0];
  Init.reference.parameters = {"J"};
  Init.registers = 3;
  Init.instructions = {op(0, "invoke-direct", {0}, {},
                          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                       op(3, "iput-wide", {1, 0}, {}, State),
                       op(5, "return-void")};
  Init.code_end = 6;
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {"J"};
  Make.registers = 3;
  Make.instructions[1].registers = {0, 1, 2};
  Make.instructions[1].reference = Init.reference;
  Local.enclosing_method = Make.reference;
  return Input;
}

