std::vector<Class> constructorScopedLocalCovariantClasses(bool Dependency,
                                                          bool Range) {
  auto Input = closedLocalCovariantClasses(Dependency, Range);
  auto &Local = Input[1];
  auto &Make = Input[0].methods[0];
  Make.reference.parameters.insert(Make.reference.parameters.begin(),
                                   Input[3].name);
  Make.generic_signature = "<V:Lfixture/Value;>(TV;J)Lfixture/Api;";
  Make.registers = 4;
  Make.instructions[1].registers = {0, 1, 2, 3};
  auto &Init = Local.methods[0];
  Init.reference.parameters.insert(Init.reference.parameters.begin(),
                                   Input[3].name);
  Init.generic_signature = "(TV;J)V";
  Init.registers = 4;
  Init.instructions[1].registers = {2, 0};
  Make.instructions[1].reference = Init.reference;
  Local.enclosing_method = Make.reference;
  return Input;
}

