TEST(MobileDalvikJava, SyntheticInterfaceNamesKeepCompleteOwnedFamilies) {
  for (unsigned Synthetic = 1; Synthetic != 8; ++Synthetic)
    for (bool Default : {false, true})
      for (bool Generic : {false, true})
        for (bool Range : {false, true})
          for (bool ExternalMarker : {false, true})
            for (bool Reverse : {false, true}) {
              SCOPED_TRACE(::testing::Message()
                           << Synthetic << Default << Generic << Range
                           << ExternalMarker << Reverse);
              auto Input = virtualIdentifierClasses();
              if (!Generic)
                for (auto &C : Input) {
                  C.generic_signature.reset();
                  for (auto &M : C.methods)
                    M.generic_signature.reset();
                }
              if (Default) {
                auto &M = Input[0].methods[0];
                M.access.erase("abstract");
                M.instructions = {op(0, "return-object", {1})};
                M.registers = 2;
                M.code_end = 1;
              }
              if (Synthetic & 4)
                Input[0].methods[0].access.insert("synthetic");
              if (Synthetic & 1)
                Input[2].methods[0].access.insert("synthetic");
              if (Synthetic & 2)
                Input[3].methods[0].access.insert("synthetic");
              if (Range) {
                Input[3].methods[0].instructions[0].opcode =
                    "invoke-super/range";
                Input[4].methods[0].instructions[0].opcode =
                    "invoke-interface/range";
              }
              auto Marker = klass("Lfixture/Marker;");
              Marker.access = {"public", "abstract", "interface"};
              Marker.external = ExternalMarker;
              Input[2].interfaces.push_back(Marker.name);
              if (Generic)
                *Input[2].generic_signature += Marker.name;
              Input.push_back(Marker);
              const auto Root = Input[0].methods[0].reference.identity();
              if (Reverse) {
                for (auto &C : Input)
                  std::reverse(C.methods.begin(), C.methods.end());
                std::reverse(Input.begin(), Input.end());
              }
              Budget B;
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 3);
              unsigned Count = 0, SyntheticFlags = 0;
              for (const auto &V : *R.getArray("methods")) {
                const auto &Row = *V.getAsObject();
                if (Row.getString("name") != "send-value")
                  continue;
                ++Count;
                EXPECT_EQ(Row.getString("source_name"),
                          "__neverdVirtualMethod1");
                EXPECT_EQ(Row.getString("source_name_declaration"), Root);
                EXPECT_EQ(Row.getArray("source_name_family")->size(), 3u);
                for (const auto &Difference :
                     *Row.getArray("metadata_differences"))
                  SyntheticFlags += Difference.getAsString()->contains(
                      "cannot reproduce the original synthetic method flag");
              }
              EXPECT_EQ(Count, 3u);
              EXPECT_EQ(SyntheticFlags, unsigned(bool(Synthetic & 1)) +
                                            unsigned(bool(Synthetic & 2)) +
                                            unsigned(bool(Synthetic & 4)));
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
            }
}

TEST(MobileDalvikJava, SyntheticInterfaceNamesRejectIncompleteContracts) {
  for (unsigned Mutation = 0; Mutation < 11; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = virtualIdentifierClasses();
    auto &Body = Input[2].methods[0];
    Body.access.insert("synthetic");
    if (Mutation == 0)
      Input[0].external = true;
    else if (Mutation == 1)
      Input[0].methods[0].access.insert("synthetic");
    else if (Mutation == 2)
      Body.access.insert("bridge");
    else if (Mutation == 3) {
      Body.access.erase("public");
      Body.access.insert("protected");
    } else if (Mutation == 4)
      Body.access.insert("native");
    else if (Mutation == 5)
      Body.instructions.clear();
    else if (Mutation == 6)
      Body.instructions[0].opcode = "unsupported-synthetic-body";
    else if (Mutation == 7)
      Input[1].interfaces = {"Lfixture/Missing;"};
    else if (Mutation == 8) {
      Body.generic_signature = "(Lfixture/Missing;)Ljava/lang/Object;";
    } else if (Mutation == 9) {
      auto Metadata = klass("Lfixture/Metadata;");
      Metadata.external = true;
      Metadata.enclosing_method = Body.reference;
      Input.push_back(Metadata);
    } else {
      Input[0].access = {"public", "abstract"};
      Input[1].access = {"public", "abstract"};
      Input[1].interfaces.clear();
      Input[1].superclass = Input[0].name;
      Input[1].generic_signature = "<T:Ljava/lang/Object;>Lfixture/Api<TT;>;";
      Input[2].interfaces.clear();
      Input[2].superclass = Input[1].name;
      Input[2].generic_signature =
          "<T:Ljava/lang/Object;>Lfixture/Branch<TT;>;";
      Input[2].methods[1].instructions[0].reference =
          MethodRef{Input[1].name, "<init>", {}, "V"};
    }
    if (Mutation == 1) {
      // Keep the exact former negative: its owned abstract synthetic interface
      // declaration now shares the same complete family proof as its body.
      EXPECT_NO_THROW(recover(Input));
    } else
      EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

TEST(MobileDalvikJava, VirtualIdentifiersKeepOneClosedInterfaceFamilyName) {
  for (unsigned Route = 0; Route < 3; ++Route) {
    auto Input = virtualIdentifierClasses();
    const auto Root = Input[0].methods[0].reference.identity();
    if (Route == 2)
      std::reverse(Input.begin(), Input.end());
    Budget B;
    const auto R =
        Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
    EXPECT_EQ(R.getInteger("method_count"), 7);
    EXPECT_EQ(R.getInteger("projected_method_count"), 3);
    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
    EXPECT_EQ(R.getString("status"), "partial");
    unsigned Count = 0;
    for (const auto &Value : *R.getArray("methods")) {
      const auto &Row = *Value.getAsObject();
      if (Row.getString("status") != "source-projected")
        continue;
      ++Count;
      EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod1");
      EXPECT_EQ(Row.getString("projection_kind"), "virtual-method-identifier");
      EXPECT_EQ(Row.getString("source_name_declaration"), Root);
      ASSERT_NE(Row.getArray("source_name_family"), nullptr);
      EXPECT_EQ(Row.getArray("source_name_family")->size(), 3U);
      ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
      EXPECT_EQ(Row.getArray("metadata_differences")->size(), 3U);
    }
    EXPECT_EQ(Count, 3U);
    std::string Text;
    for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
      Text += source(R, I);
    EXPECT_EQ(Text.find("send-value"), std::string::npos);
    EXPECT_NE(Text.find("super.__neverdVirtualMethod1("), std::string::npos);
    EXPECT_NE(Text.find("((fixture.Branch) o0).__neverdVirtualMethod1("),
              std::string::npos);
  }
}

