TEST(MobileDalvikJava, RegisterMaskDelegationsKeepFinalInitializationReceipt) {
  for (bool Two : {false, true})
    for (bool Reverse : {false, true}) {
      auto Input = guardedDelegationChainClasses();
      auto &M = Input[0].methods[1];
      M.instructions[0] = op(0, "const/4", {0}, int64_t(2));
      for (size_t I = 1; I < M.instructions.size(); ++I) {
        ++M.instructions[I].pc;
        if (M.instructions[I].target)
          ++*M.instructions[I].target;
      }
      M.instructions.insert(M.instructions.begin() + 1,
                            op(1, Two ? "and-int/2addr" : "and-int",
                               Two ? std::vector<unsigned>{0, 13}
                                   : std::vector<unsigned>{0, 13, 0}));
      ++M.code_end;
      const auto Default = M.reference;
      const auto Primary = Input[0].methods[0].reference;
      if (Reverse) {
        std::reverse(Input[0].methods.begin(), Input[0].methods.end());
        std::reverse(Input.begin(), Input.end());
      }
      Budget B;
      const auto Classes = linkClasses(Input, B);
      const auto Plans = validateGenericSignatures(Classes, B);
      ASSERT_TRUE(Plans.constructor_delegations.contains(Default));
      EXPECT_EQ(Plans.constructor_delegations.at(Default), Primary);
      const auto R = recoverJava(Classes, B);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
    }
}

TEST(MobileDalvikJava, RegisterMaskDelegationsRejectSelfAndInvalidOperands) {
  for (unsigned Mutation = 0; Mutation < 5; ++Mutation) {
    auto Input = guardedDelegationChainClasses();
    auto &M = Input[0].methods[1];
    M.instructions[0].opcode = "and-int/2addr";
    M.instructions[0].literal = {};
    if (Mutation == 0)
      M.instructions[0].registers = {0, 8};
    else if (Mutation == 1)
      M.instructions[0].registers = {8, 13};
    else if (Mutation == 2)
      M.instructions[0].registers = {0, 13, 14};
    else if (Mutation == 3)
      M.instructions[0].registers = {0, 11};
    else
      M.instructions[0].opcode = "div-int/2addr";
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

TEST(MobileDalvikJava, GuardedDelegationsRejectEscapesAndAmbiguousSelfOrigins) {
  for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = guardedDelegationChainClasses();
    auto &C = Input[0];
    auto &Default = C.methods[1];
    auto &Code = Default.instructions;
    switch (Mutation) {
    case 0:
      Code[1].target = 9;
      break;
    case 1:
      Code[3].target = 0;
      Code[2] = op(2, "move-object", {0, 8});
      break;
    case 2:
      Code[4].registers[1] = 14;
      break;
    case 3:
      Code[5].registers[1] = 8;
      break;
    case 4:
      Code[0].registers[1] = 8;
      break;
    case 5:
      Code[7].registers[0] = 7;
      break;
    case 6:
      Code[1].target = 5;
      break;
    case 7:
      C.methods[0].instructions[2].reference = Default.reference;
      break;
    case 8:
      Code.push_back(op(10, "move-exception", {0}));
      Code.push_back(op(11, "throw", {0}));
      Default.code_end = 12;
      Default.tries = {{0, 9, {{std::nullopt, 10}}}};
      break;
    case 9:
      Code[7].registers[1] = 12;
      break;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> constructorParameterReadClasses(const std::string &Type,
                                                   bool Guarded, bool Range,
                                                   bool Direct) {
  const bool Wide = Type == "J";
  const bool Reference = Type == "Ljava/lang/Object;";
  const unsigned Words = Wide ? 2 : 1;
  const FieldRef Value{"Lfixture/Core;", "value", Type};
  auto Primary = method("<init>", {Type}, "V", Words + 1,
                        {op(0, "invoke-direct", {0}, {},
                            MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                         op(1,
                            Wide        ? "iput-wide"
                            : Reference ? "iput-object"
                                        : "iput",
                            {1, 0}, {}, Value),
                         op(2, "return-void")});
  Primary.access = {"public", "constructor"};
  auto Read =
      method("read", {}, Type, Words + 1,
             {op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
              op(1,
                 Wide        ? "return-wide"
                 : Reference ? "return-object"
                             : "return",
                 {0})});
  Read.access = {"public"};
  auto Provider = klass("Lfixture/Provider;", {Read});
  const FieldRef Shared{"Lfixture/Defaults;", "provider",
                        Direct ? Type : Provider.name};
  auto Defaults = klass(Shared.owner);
  Defaults.fields = {{Shared, {"public", "static"}, {}}};
  std::vector<unsigned> Arguments{0, 1};
  if (Wide)
    Arguments.push_back(2);
  auto Default =
      method("<init>", {Type, "I", "Ljava/lang/Object;"}, "V", Words + 3,
             {op(0, "and-int/lit8", {Words + 1, Words + 1}, int64_t(1)),
              op(1, "if-eqz", {Words + 1}, {}, {}, 5),
              op(2,
                 !Direct || Reference ? "sget-object"
                 : Wide               ? "sget-wide"
                                      : "sget",
                 {1}, {}, Shared),
              op(3, Range ? "invoke-virtual/range" : "invoke-virtual", {1}, {},
                 Provider.methods[0].reference),
              op(4,
                 Wide        ? "move-result-wide"
                 : Reference ? "move-result-object"
                             : "move-result",
                 {1}),
              op(5, Range ? "invoke-direct/range" : "invoke-direct", Arguments,
                 {}, Primary.reference),
              op(6, "return-void")});
  Default.access = {"public", "constructor", "synthetic"};
  if (Direct)
    Default.instructions.erase(Default.instructions.begin() + 3,
                               Default.instructions.begin() + 5);
  if (!Guarded)
    Default.instructions.erase(Default.instructions.begin(),
                               Default.instructions.begin() + 2);
  std::vector<unsigned> WrapperArguments;
  for (unsigned I = 0; I < Words + 3; ++I)
    WrapperArguments.push_back(I);
  auto Wrapper =
      method("<init>", {}, "V", Words + 4,
             {op(0, "move-object", {0, Words + 3}),
              op(1, Wide ? "const-wide/16" : "const/4", {1}, int64_t(0)),
              op(2, "const/4", {Words + 1}, int64_t(1)),
              op(3, "const/4", {Words + 2}, int64_t(0)),
              op(4, Range ? "invoke-direct/range" : "invoke-direct",
                 WrapperArguments, {}, Default.reference),
              op(5, "return-void")});
  Wrapper.access = Primary.access;
  auto Core = klass(Value.owner, {Primary, Default, Wrapper});
  Core.fields = {{Value, {"public", "final"}, {}}};
  return {Core, Provider, Defaults};
}

TEST(MobileDalvikJava,
     ConstructorParameterReadsRetainTypedSlotsAndDelegationChains) {
  for (const auto &Type : {"I", "J", "Ljava/lang/Object;"})
    for (bool Guarded : {false, true})
      for (bool Range : {false, true})
        for (bool Direct : {false, true})
          for (bool Dependency : {false, true})
            for (bool Linked : {false, true}) {
              SCOPED_TRACE(Type);
              SCOPED_TRACE(Guarded);
              SCOPED_TRACE(Range);
              SCOPED_TRACE(Direct);
              SCOPED_TRACE(Dependency);
              SCOPED_TRACE(Linked);
              auto Input =
                  constructorParameterReadClasses(Type, Guarded, Range, Direct);
              const auto Primary = Input[0].methods[0].reference;
              const auto Default = Input[0].methods[1].reference;
              const auto Wrapper = Input[0].methods[2].reference;
              if (Dependency) {
                Input[1].external = Input[2].external = true;
                Input[1].methods[0].instructions.clear();
                Input[1].methods[0].registers = Input[1].methods[0].code_end =
                    0;
              }
              if (Range) {
                std::reverse(Input[0].methods.begin(), Input[0].methods.end());
                std::reverse(Input.begin(), Input.end());
              }
              Budget B;
              ClassMap Classes;
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
              if (Linked)
                Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_EQ(Plans.constructor_delegations.size(), 2U);
              EXPECT_EQ(Plans.constructor_delegations.at(Default), Primary);
              EXPECT_EQ(Plans.constructor_delegations.at(Wrapper), Default);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
              const auto Text = source(R);
              EXPECT_NE(Text.find(".provider"), std::string::npos);
              if (!Direct) {
                const auto Read = Text.find(".read()");
                ASSERT_NE(Read, std::string::npos);
                EXPECT_EQ(Text.find(".read()", Read + 1), std::string::npos);
              }
            }
}

TEST(MobileDalvikJava,
     ConstructorParameterReadsRejectReceiverOverlapAndUnprovenPaths) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = constructorParameterReadClasses("J", true, false, false);
    auto &Default = Input[0].methods[1];
    auto &Code = Default.instructions;
    switch (Mutation) {
    case 0:
      Code[2].registers = {0};
      break;
    case 1:
      Code[2].registers = {4};
      break;
    case 2:
      Code[2].registers = {5};
      break;
    case 3:
      Code[2].opcode = "sget";
      break;
    case 4:
      Input[2].fields[0].access.erase("static");
      break;
    case 5:
      Input[2].fields.clear();
      break;
    case 6:
      Input[2].fields[0].value = int64_t(0);
      break;
    case 7:
      Code[3].registers = {0};
      break;
    case 8:
      Code[1].target = 3;
      break;
    case 9:
      Code[1].target = 6;
      break;
    case 10:
      Code[1].target = 0;
      Code[1].registers = {0}; // A loop cannot observe uninitialized this.
      break;
    case 11:
      Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 12:
      std::get<FieldRef>(Code[2].reference).owner = "Lfixture/Missing;";
      break;
    case 13:
      Code[4].opcode = "move-result";
      break;
    case 14:
    case 15:
      if (Mutation == 15) {
        ++Default.registers;
        for (auto &Op : Code)
          for (auto &R : Op.registers)
            ++R;
      }
      Input[2].fields[0].reference.type = "J";
      Code[2].reference = Input[2].fields[0].reference;
      Code[2].opcode = "sget-wide";
      Code[2].registers = {Mutation == 14 ? 4U : 0U};
      break;
    }
    if (std::set<unsigned>{0, 2, 3, 4, 5, 6, 12, 14, 15}.contains(Mutation)) {
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_FALSE(constructorPrefixStaticRead(Default, Code[2], Classes, B));
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> allocationArrayLengthClasses(const std::string &Array,
                                                unsigned Style,
                                                bool ReturnLength, bool Range,
                                                bool Dependency) {
  auto Init = method("<init>", {"I"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = klass("Lfixture/Target;", {Init});
  Target.external = Dependency;
  if (Dependency) {
    Target.methods[0].instructions.clear();
    Target.methods[0].registers = Target.methods[0].code_end = 0;
  }
  const FieldRef Field{"Lfixture/Holder;", "array", Array};
  auto Holder = klass(Field.owner);
  Holder.fields = {{Field, {"public", "static"}, {}}};
  Holder.external = Dependency;
  const bool Alias = Style == 1, StaticField = Style == 2, Unused = Style == 3;
  const unsigned ArrayRegister = Alias || StaticField ? 1 : 2;
  std::vector<Instruction> Code{op(0, "new-instance", {0}, {}, Target.name)};
  if (StaticField)
    Code.push_back(op(1, "sget-object", {1}, {}, Field));
  Code.push_back(op(2, "array-length", {1, ArrayRegister}));
  Code.push_back(op(3, Range ? "invoke-direct/range" : "invoke-direct",
                    {0, Unused ? 3U : 1U}, {}, Target.methods[0].reference));
  Code.push_back(op(4, ReturnLength ? "return" : "return-object",
                    {ReturnLength ? 1U : 0U}));
  // Keep a contiguous range frame while preserving the array in a local
  // before its incoming register becomes the new receiver.
  if (Range && Unused) {
    Code = {
        op(0, "move-object", {0, 2}),
        op(1, "new-instance", {2}, {}, Target.name),
        op(2, "array-length", {1, 0}),
        op(3, "invoke-direct/range", {2, 3}, {}, Target.methods[0].reference),
        op(4, ReturnLength ? "return" : "return-object",
           {ReturnLength ? 1U : 2U})};
  }
  auto Parameters = StaticField ? std::vector<std::string>{}
                                : std::vector<std::string>{Array};
  if (Unused)
    Parameters.push_back("I");
  auto Make = method("make", Parameters, ReturnLength ? "I" : Target.name,
                     Unused                 ? 4
                     : Alias || StaticField ? 2
                                            : 3,
                     Code);
  return {klass("Lfixture/Core;", {Make}), Target, Holder};
}

TEST(MobileDalvikJava, AllocationArrayLengthsKeepTypedEffectsAndLiveValues) {
  for (const auto &Array : {"[I", "[J", "[Z", "[Ljava/lang/Object;", "[[I"})
    for (unsigned Style = 0; Style < 4; ++Style)
      for (bool ReturnLength : {false, true})
        for (bool Range : {false, true})
          for (bool Dependency : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(Array);
              SCOPED_TRACE(Style);
              SCOPED_TRACE(ReturnLength);
              SCOPED_TRACE(Range);
              SCOPED_TRACE(Dependency);
              auto Input = allocationArrayLengthClasses(
                  Array, Style, ReturnLength, Range, Dependency);
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_FALSE(R.getInteger("minimum_java_release"));
              const auto Text = source(R);
              const auto New = Text.find("new fixture.Target(");
              const auto Length = Text.find(".length");
              ASSERT_NE(New, std::string::npos);
              ASSERT_NE(Length, std::string::npos);
              EXPECT_LT(New, Length);
              EXPECT_EQ(Text.find(".length", Length + 1), std::string::npos);
            }
}

TEST(MobileDalvikJava, AllocationArrayLengthsRejectUnprovedOperandsAndRegions) {
  for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = allocationArrayLengthClasses("[I", 0, false, false, false);
    auto &M = Input[0].methods[0];
    auto &Code = M.instructions;
    if (Mutation == 0)
      Code[1].registers[1] = 0;
    else if (Mutation == 1)
      Code[1].registers[0] = 0;
    else if (Mutation == 2)
      Code[1].registers.pop_back();
    else if (Mutation == 3)
      Code[1].registers[1] = M.registers;
    else if (Mutation == 4)
      Code[2].registers[1] = 2;
    else if (Mutation == 5)
      Input.erase(Input.begin() + 1);
    else if (Mutation == 6)
      M.reference.parameters[0] = "Ljava/lang/Object;";
    else if (Mutation == 7) {
      for (auto &Op : Code)
        ++Op.pc;
      Code.insert(Code.begin(), op(0, "if-eqz", {2}, {}, {}, 3));
      ++M.code_end;
    } else {
      Code.insert(Code.begin() + 2, op(3, "goto", {}, {}, {}, 4));
      Code[3].pc = 4;
      Code[4].pc = 5;
      M.code_end = 6;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> allocationArrayArgumentClasses(const std::string &Array,
                                                  bool Range = false,
                                                  bool IncomingStore = false,
                                                  bool ReturnArray = false,
                                                  bool External = false) {
  auto Init = method("<init>", {Array, "[I"}, "V", 3,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = klass("Lfixture/Target;", {Init});
  Target.external = External;
  if (External) {
    Target.methods[0].instructions.clear();
    Target.methods[0].registers = Target.methods[0].code_end = 0;
  }
  const auto Element = Array.substr(1);
  const unsigned Words = Element == "J" || Element == "D" ? 2 : 1;
  const std::string Store = Element.starts_with('L') || Element.starts_with('[')
                                ? "aput-object"
                            : Words == 2     ? "aput-wide"
                            : Element == "Z" ? "aput-boolean"
                            : Element == "B" ? "aput-byte"
                            : Element == "C" ? "aput-char"
                            : Element == "S" ? "aput-short"
                                             : "aput";
  auto Make = method(
      "make", {"I", Element, Array}, ReturnArray ? Array : Target.name,
      6 + Words,
      {op(0, "new-instance", {0}, {}, Target.name),
       op(1, "new-array", {1, 4}, {}, Array), op(2, "const/4", {3}, int64_t(0)),
       op(3, Store, {5, IncomingStore ? 5 + Words : 1, 3}),
       op(4, Range ? "filled-new-array/range" : "filled-new-array", {4}, {},
          std::string("[I")),
       op(5, "move-result-object", {2}),
       op(6, Range ? "invoke-direct/range" : "invoke-direct", {0, 1, 2}, {},
          Target.methods[0].reference),
       op(7, "return-object", {ReturnArray ? 1u : 0u})});
  return {klass("Lfixture/Core;", {Make}), Target};
}

