std::vector<Class> switchAllocationClasses(bool Wide, bool Reuse, bool Sparse,
                                           bool External, bool Range,
                                           bool Abort = true) {
  auto Input = conditionalAllocationClasses(Wide);
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.superclass = "Ljava/lang/Throwable;";
  auto RuntimeInit = method("<init>", {}, "V", 0, {});
  RuntimeInit.reference.owner = Runtime.name;
  RuntimeInit.access = {"public", "constructor"};
  Runtime.methods = {RuntimeInit};
  Runtime.external = true;
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Init = method("<init>", {"Ljava/lang/Object;"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {}, RuntimeInit.reference),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Failure = klass("Lfixture/Failure;", {Init});
  Failure.superclass = Runtime.name;
  const unsigned Value = Wide ? 9 : 7, Failed = Reuse ? 0 : 2;
  auto Switch = op(1, Sparse ? "sparse-switch" : "packed-switch", {6});
  Switch.keys = Sparse ? std::vector<int32_t>{INT32_MIN, -7, INT32_MAX}
                       : std::vector<int32_t>{0, 1, 2};
  Switch.targets = {8, 11, 14};
  const std::string Invoke = Range ? "invoke-static/range" : "invoke-static";
  auto Make = method(
      "make",
      Wide ? std::vector<std::string>{"I", "J", "Ljava/lang/Object;"}
           : std::vector<std::string>{"I", "Ljava/lang/Object;"},
      Input[1].name, Wide ? 10 : 8,
      {op(0, "new-instance", {0}, {}, Input[1].name), Switch,
       op(2, "new-instance", {Failed}, {}, Failure.name),
       op(3, "move-object", {3, Value}),
       op(4, Invoke, {3}, {}, Input[2].methods[0].reference),
       op(5, "move-result-object", {3}),
       op(6, "invoke-direct", {Failed, 3}, {}, Failure.methods[0].reference),
       op(7, "throw", {Failed}),
       op(8, Invoke, {Value}, {}, Input[2].methods[0].reference),
       op(9, "move-result-object", {3}), op(10, "goto", {}, {}, {}, 17),
       op(11, Invoke, {Value}, {}, Input[2].methods[0].reference),
       op(12, "move-result-object", {3}), op(13, "goto", {}, {}, {}, 17),
       op(14, Invoke, {Value}, {}, Input[2].methods[0].reference),
       op(15, "move-result-object", {3}), op(16, "goto", {}, {}, {}, 17),
       op(17, "invoke-direct",
          Wide ? std::vector<unsigned>{0, 7, 8, 3}
               : std::vector<unsigned>{0, 3},
          {}, Input[1].methods[0].reference),
       op(18, "return-object", {0})});
  if (!Abort) {
    Make.instructions.erase(Make.instructions.begin() + 2,
                            Make.instructions.begin() + 8);
    Make.instructions.insert(
        Make.instructions.begin() + 2,
        {op(2, "const/4", {3}, int64_t(0)), op(3, "goto", {}, {}, {}, 17)});
  }
  Input[0].methods = {Make};
  Input.push_back(Failure);
  Input.push_back(Runtime);
  Input.push_back(Throwable);
  if (External)
    for (size_t I : {1u, 2u, 3u}) {
      Input[I].external = true;
      for (auto &M : Input[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Input;
}

TEST(MobileDalvikJava, SwitchAllocationKeepsThrowArmsInsideOriginalNew) {
  for (bool Wide : {false, true})
    for (bool Reuse : {false, true})
      for (bool Sparse : {false, true})
        for (bool External : {false, true})
          for (bool Range : {false, true})
            for (bool Abort : {false, true})
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Wide, Reuse, Sparse, External, Range, Abort, Route}));
                auto Input = switchAllocationClasses(Wide, Reuse, Sparse,
                                                     External, Range, Abort);
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                     : recover(Input);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
                std::string Text;
                for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                  Text += source(R, I);
                const auto New = Text.find("new fixture.Target(switch (0)");
                ASSERT_NE(New, std::string::npos);
                EXPECT_NE(Text.find("switch (v6)", New), std::string::npos);
                if (Abort) {
                  const auto Failed = Text.find("new fixture.Failure(", New);
                  ASSERT_NE(Failed, std::string::npos);
                  EXPECT_LT(New, Failed);
                  EXPECT_NE(Text.find("throw __neverdThrow", Failed),
                            std::string::npos);
                }
              }
}

TEST(MobileDalvikJava, SwitchAllocationRejectsOriginAndControlFlowDrift) {
  for (bool Wide : {false, true})
    for (bool Reuse : {false, true})
      for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Wide, Reuse, Mutation}));
        auto Input = switchAllocationClasses(Wide, Reuse, true, false, false);
        auto &M = Input[0].methods[0];
        auto &Code = M.instructions;
        if (Mutation == 0)
          Code[1].registers = {0};
        else if (Mutation == 1)
          Code[1].registers.push_back(7);
        else if (Mutation == 2)
          Code[1].keys[1] = Code[1].keys[0];
        else if (Mutation == 3)
          Code[1].keys.pop_back();
        else if (Mutation == 4)
          Code[1].targets[0] = 0;
        else if (Mutation == 5)
          Code[1].targets[0] = 18;
        else if (Mutation == 6)
          Code[1].targets[0] = 6;
        else if (Mutation == 7)
          Code[2].registers = {3};
        else if (Mutation == 8)
          Code[3].registers[1] = 0;
        else if (Mutation == 9)
          Code[7] = op(7, "return-object", {Reuse ? 0u : 2u});
        else if (Mutation == 10) {
          // Destroy the original receiver before joining its initializer.
          // A separate, unused exception allocation would be a legal arm.
          Code[2].registers[0] = Code[6].registers[0] = 0;
          Code[7] = op(7, "goto", {}, {}, {}, 17);
        } else if (Mutation == 11)
          Input[1].methods[0].access = {"private", "constructor"};
        else if (Mutation == 12)
          Input[3].methods[0].access = {"private", "constructor"};
        else if (Mutation == 13)
          Input[2].methods.clear();
        else if (Mutation == 14) {
          for (auto &Op : Code) {
            ++Op.pc;
            if (Op.target)
              ++*Op.target;
            for (auto &PC : Op.targets)
              ++PC;
          }
          Code.insert(Code.begin(), op(0, "if-eqz", {6}, {}, {}, 9));
          ++M.code_end;
        } else if (Mutation == 15) {
          Code.push_back(op(19, "move-exception", {4}));
          Code.push_back(op(20, "throw", {4}));
          M.tries = {{0, 18, {{"Ljava/lang/RuntimeException;", 19}}}};
          M.code_end = 21;
        } else if (Mutation == 16)
          Code[1].targets[0] = 7;
        else if (Mutation == 17)
          Code[4].registers = {0};
        else if (Mutation == 18)
          Code[2].reference = Input[1].name;
        else
          Code[17].registers[0] = 2;
        Budget B;
        // An independent catch/rethrow is now a valid protected argument
        // region. Receiver identities and illegal entries still fail below.
        if (Mutation == 15)
          EXPECT_NO_THROW(recoverJava(linkClasses(Input, B), B));
        else
          EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                       std::runtime_error);
      }
}

std::vector<Class> forwardAllocationClasses(const std::string &Jump, bool Nop,
                                            bool External, bool Protected,
                                            bool SharedCleanup = false) {
  auto Input = switchAllocationClasses(false, true, false, false, false);
  auto &Init = Input[1].methods[0];
  Init.reference.parameters.clear();
  Init.registers = 1;
  if (External) {
    Input[1].external = true;
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  const FieldRef Caught{"Lfixture/Trace;", "caught",
                        "Ljava/lang/RuntimeException;"};
  auto Trace = klass(Caught.owner);
  Trace.fields.push_back({Caught, {"public", "static"}, {}});
  auto &M = Input[0].methods[0];
  auto Switch = op(0, "packed-switch", {6});
  Switch.keys = {0, 1};
  Switch.targets = {4, 6};
  M.instructions = {
      Switch,
      op(1, "new-instance", {0}, {}, Input[1].name),
      op(2, Jump, {}, {}, {}, 12),
      op(4, "const/4", {4}, int64_t(0)),
      op(5, "return-object", {4}),
      op(6, "new-instance", {0}, {}, Input[3].name),
      op(7, "move-object", {3, 7}),
      op(8, "invoke-direct", {0, 3}, {}, Input[3].methods[0].reference),
      op(9, "throw", {0}),
      op(12, "invoke-direct", {0}, {}, Init.reference),
      op(13, "return-object", {0})};
  if (Nop) {
    M.instructions[2] = op(2, "nop");
    M.instructions.insert(M.instructions.begin() + 3,
                          op(3, Jump, {}, {}, {}, 12));
  }
  if (Protected) {
    M.instructions.insert(
        M.instructions.end(),
        {op(14, "move-exception", {0}), op(15, "sput-object", {0}, {}, Caught),
         op(16, "const/4", {1}, int64_t(0)), op(17, "return-object", {1})});
    M.tries = {{1, 14, {{"Ljava/lang/RuntimeException;", 14}}}};
    if (SharedCleanup) {
      M.instructions.back() = op(17, "goto", {}, {}, {}, 4);
      M.instructions.erase(M.instructions.end() - 2);
    }
  } else
    M.tries.clear();
  M.code_end = Protected ? 18 : 14;
  Input.push_back(Trace);
  return Input;
}

TEST(MobileDalvikJava, ForwardAllocationRetainsIndependentSiblingBlocks) {
  for (const auto &Jump : {"goto", "goto/16", "goto/32"})
    for (bool Nop : {false, true})
      for (bool External : {false, true})
        for (bool Protected : {false, true})
          for (bool SharedCleanup : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              if (SharedCleanup && !Protected)
                continue;
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  Jump, Nop, External, Protected, SharedCleanup, Route}));
              auto Input = forwardAllocationClasses(Jump, Nop, External,
                                                    Protected, SharedCleanup);
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 8);
              std::string Text;
              for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                Text += source(R, I);
              const auto New = Text.find("new fixture.Target()");
              ASSERT_NE(New, std::string::npos);
              EXPECT_EQ(Text.find("new fixture.Target()", New + 1),
                        std::string::npos);
              EXPECT_NE(Text.find("new fixture.Failure("), std::string::npos);
              if (Protected)
                EXPECT_NE(Text.find(".caught ="), std::string::npos);
            }
}

TEST(MobileDalvikJava, ForwardAllocationRejectsEntriesEffectsAndCleanupDrift) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{External, Mutation}));
      auto Input = forwardAllocationClasses("goto", false, External, true);
      auto &M = Input[0].methods[0];
      auto &Code = M.instructions;
      if (Mutation == 0)
        Code[2].target = 1;
      else if (Mutation == 1)
        Code[2].target = 3;
      else if (Mutation == 2)
        Code[0].targets[0] = 2;
      else if (Mutation == 3)
        Code[0].targets[0] = 12;
      else if (Mutation == 4)
        Code[2].registers = {0};
      else if (Mutation == 5)
        Code[2].literal = int64_t(1);
      else if (Mutation == 6)
        Code[2].opcode = "goto/range";
      else if (Mutation == 7)
        Code[2] = op(2, "move-object", {3, 0});
      else if (Mutation == 8)
        Code[9].registers[0] = 2;
      else if (Mutation == 9)
        Code[9].registers.push_back(1);
      else if (Mutation == 10)
        Input[1].access.insert("abstract");
      else if (Mutation == 11)
        Input[1].methods[0].access = {"private", "constructor"};
      else if (Mutation == 12)
        M.tries[0].end = 12;
      else if (Mutation == 13) {
        Code[11].registers = {1};
        Code[12].reference =
            FieldRef{Input.back().name, "observed", "Ljava/lang/Object;"};
        Input.back().fields.push_back(
            {std::get<FieldRef>(Code[12].reference), {"public", "static"}, {}});
      } else if (Mutation == 14)
        Code[8] = op(9, "goto", {}, {}, {}, 12);
      else
        Code[12] = op(15, "goto", {}, {}, {}, 2);
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class>
conditionalTypeTestAllocationClasses(bool Wide, bool Dependency, bool Range,
                                     const std::string &Checked,
                                     bool Interface) {
  auto Input = conditionalAllocationClasses(Wide);
  auto Type = klass("Lfixture/Checked;");
  if (Interface)
    Type.access = {"public", "interface", "abstract"};
  Type.external = Dependency;
  auto &Target = Input[1];
  Target.external = Dependency;
  if (Dependency)
    Target.methods[0].instructions.clear();
  auto &Make = Input[0].methods[0];
  Make.registers = Wide ? 8 : 5;
  const unsigned Value = Wide ? 7 : 4, Result = Wide ? 3 : 1;
  Make.instructions = {op(0, "new-instance", {0}, {}, Target.name)};
  unsigned PC = 1;
  if (Wide)
    Make.instructions.push_back(op(PC++, "move-wide", {1, 5}));
  Make.instructions.push_back(
      op(PC++, "instance-of", {Wide ? 4u : 2u, Value}, {}, Checked));
  Make.instructions.push_back(
      op(PC, "if-eqz", {Wide ? 4u : 2u}, {}, {}, PC + 4));
  ++PC;
  Make.instructions.push_back(op(PC++, "move-object", {Result, Value}));
  Make.instructions.push_back(op(PC++, "check-cast", {Result}, {}, Checked));
  Make.instructions.push_back(op(PC, "goto", {}, {}, {}, PC + 2));
  ++PC;
  Make.instructions.push_back(op(PC++, "const/4", {Result}, int64_t(0)));
  Make.instructions.push_back(
      op(PC++, Range ? "invoke-direct/range" : "invoke-direct",
         Wide ? std::vector<unsigned>{0, 1, 2, 3} : std::vector<unsigned>{0, 1},
         {}, Target.methods[0].reference));
  Make.instructions.push_back(op(PC++, "return-object", {0}));
  Make.code_end = PC;
  Input.push_back(std::move(Type));
  return Input;
}

TEST(MobileDalvikJava, ConditionalTypeTestsShareOrdinaryAllocationSemantics) {
  for (const auto &[Checked, Interface] :
       std::vector<std::pair<std::string, bool>>{
           {"Lfixture/Checked;", false},
           {"Lfixture/Checked;", true},
           {"[Lfixture/Checked;", false},
           {"[I", false},
           {"[[Ljava/lang/Object;", false}})
    for (bool Wide : {false, true})
      for (bool Dependency : {false, true})
        for (bool Range : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input = conditionalTypeTestAllocationClasses(
                Wide, Dependency, Range, Checked, Interface);
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R = recoverJava(linkClasses(Input, B), B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            std::string Text;
            const auto *Units = R.getArray("source_units");
            ASSERT_NE(Units, nullptr);
            for (size_t I = 0; I < Units->size(); ++I)
              Text += source(R, I);
            EXPECT_NE(Text.find("instanceof "), std::string::npos);
            EXPECT_NE(Text.find("new fixture.Target(switch (0)"),
                      std::string::npos);
          }
}

TEST(MobileDalvikJava, ConditionalTypeTestsRetainInputAndAllocationOwnership) {
  for (bool Wide : {false, true})
    for (unsigned Mutation = 0; Mutation < 9; ++Mutation) {
      SCOPED_TRACE(Wide);
      SCOPED_TRACE(Mutation);
      auto Input = conditionalTypeTestAllocationClasses(
          Wide, false, true, "Lfixture/Checked;", true);
      auto &Make = Input[0].methods[0];
      const size_t Test = Wide ? 2 : 1;
      if (Mutation == 0)
        Make.instructions[Test].registers[0] = 0;
      else if (Mutation == 1)
        Make.instructions[Test].registers[1] = 0;
      else if (Mutation == 2)
        Make.instructions[Test].registers.resize(1);
      else if (Mutation == 3)
        Make.instructions[Test].registers[1] = Wide ? 5 : 2;
      else if (Mutation == 4)
        Make.instructions[Test + 1].target = 0;
      else if (Mutation == 5)
        Make.instructions[Test + 1].target = Make.instructions.back().pc;
      else if (Mutation == 6)
        Input[1].methods[0].access = {"private", "constructor"};
      else if (Mutation == 7) {
        Make.instructions.push_back(op(Make.code_end, "move-exception", {1}));
        Make.instructions.push_back(op(Make.code_end + 1, "throw", {0}));
        Make.tries = {{0,
                       Make.code_end,
                       {{"Ljava/lang/RuntimeException;", Make.code_end}}}};
        Make.code_end += 2;
      } else {
        for (auto &Op : Make.instructions) {
          ++Op.pc;
          if (Op.target)
            ++*Op.target;
        }
        Make.instructions.insert(Make.instructions.begin(),
                                 op(0, "goto", {}, {}, {}, Test + 1));
        ++Make.code_end;
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> protectedConditionalArgumentClasses(bool Wide,
                                                       bool Dependency,
                                                       bool Range, bool Split) {
  auto Input = conditionalTypeTestAllocationClasses(Wide, Dependency, Range,
                                                    "Lfixture/Checked;", false);
  auto &Make = Input[0].methods[0];
  const unsigned Value = Wide ? 7 : 4, Result = Wide ? 3 : 1;
  const unsigned Exception = Wide ? 4 : 2;
  const auto End = Make.code_end;
  const auto Init = Make.instructions[Make.instructions.size() - 2].pc;
  const auto Cast = Wide ? 5u : 4u;
  auto Record =
      method("record", {"Ljava/lang/Object;", "Ljava/lang/Throwable;"}, "V", 2,
             {op(0, "return-void")});
  Record.reference.owner = "Lfixture/Trace;";
  for (unsigned H = 0; H != (Split ? 3u : 1u); ++H) {
    const auto PC = End + H * 4;
    Make.instructions.push_back(op(PC, "move-exception", {Exception}));
    Make.instructions.push_back(op(PC + 1, "invoke-static",
                                   {Split && H ? Result : Value, Exception}, {},
                                   Record.reference));
    Make.instructions.push_back(op(PC + 2, "const/4", {0}, int64_t(0)));
    Make.instructions.push_back(op(PC + 3, "return-object", {0}));
  }
  if (Split)
    Make.tries = {{0, Cast, {{std::nullopt, End}}},
                  {Cast, Cast + 1, {{std::nullopt, End + 4}}},
                  {Init, Init + 1, {{std::nullopt, End + 8}}}};
  else
    Make.tries = {{0, Init + 1, {{std::nullopt, End}}}};
  Make.code_end += Split ? 12 : 4;
  Input.push_back(klass("Lfixture/Trace;", {Record}));
  return Input;
}

TEST(MobileDalvikJava, ProtectedConditionalArgumentsRetainExceptionPositions) {
  for (bool Wide : {false, true})
    for (bool Dependency : {false, true})
      for (bool Range : {false, true})
        for (bool Split : {false, true})
          for (bool Reverse : {false, true}) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Wide, Dependency, Range, Split, Reverse}));
            auto Input = protectedConditionalArgumentClasses(Wide, Dependency,
                                                             Range, Split);
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            EXPECT_NO_THROW({
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
              std::string Text;
              for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                Text += source(R, I);
              const auto Allocation = Text.find("new fixture.Target(");
              ASSERT_NE(Allocation, std::string::npos);
              EXPECT_EQ(Text.rfind("pc = 0;", Allocation),
                        Text.rfind("pc = ", Allocation));
              EXPECT_NE(Text.find("switch (0) { default -> {"),
                        std::string::npos);
              EXPECT_NE(Text.find(".record("), std::string::npos);
            });
          }
}

TEST(MobileDalvikJava, ProtectedConditionalArgumentsRejectLostOwnership) {
  for (bool Wide : {false, true})
    for (unsigned Mutation = 0; Mutation != 12; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Wide, Mutation}));
      auto Input = protectedConditionalArgumentClasses(Wide, false, true, true);
      auto &Make = Input[0].methods[0];
      auto &Code = Make.instructions;
      const auto Init = Code[Wide ? 8 : 7].pc;
      if (Mutation == 0)
        Code[Wide ? 2 : 1].registers[0] = 0;
      else if (Mutation == 1)
        Code[Wide ? 2 : 1].registers[1] = 0;
      else if (Mutation == 2)
        Code[Wide ? 3 : 2].target = 0;
      else if (Mutation == 3)
        Code[Wide ? 3 : 2].target = Init + 1;
      else if (Mutation == 4)
        Make.tries[0].handlers[0].target = Init;
      else if (Mutation == 5)
        Make.tries[1].handlers[0].target = Wide ? 5 : 4;
      else if (Mutation == 6)
        Code[Code.size() - 3].registers[0] = 0;
      else if (Mutation == 7)
        Code[Code.size() - 7].registers[0] = Wide ? 2 : 3;
      else if (Mutation == 8)
        Code[Code.size() - 4] = op(Code[Code.size() - 4].pc, "nop");
      else if (Mutation == 9)
        Code[Code.size() - 2] = op(Code[Code.size() - 2].pc, "nop");
      else if (Mutation == 10)
        Input[1].access.insert("abstract");
      else
        Input[1].methods[0].access = {"private", "constructor"};
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

std::vector<Class> nestedConditionalArgumentClasses(bool Wide, bool External) {
  auto Input = conditionalAllocationClasses(Wide);
  auto Init = method("<init>", {Input[1].name}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Outer = klass("Lfixture/Envelope;", {Init});
  Outer.external = External;
  if (External) {
    Outer.methods[0].instructions.clear();
    Outer.methods[0].registers = 0;
  }
  auto &Make = Input[0].methods[0];
  for (auto &Op : Make.instructions) {
    for (auto &R : Op.registers)
      if (R >= 2)
        ++R;
    ++Op.pc;
    if (Op.target)
      ++*Op.target;
  }
  ++Make.registers;
  // A second forward selection remains in the inner argument program.
  auto &Code = Make.instructions;
  for (size_t I = 6; I < Code.size(); ++I)
    Code[I].pc += 3;
  Code[4].target = 7;
  Code.insert(Code.begin() + 6, {op(7, "if-nez", {1}, {}, {}, 10),
                                 op(8, "invoke-static", {Wide ? 5u : 3u}, {},
                                    Input[2].methods[0].reference),
                                 op(9, "move-result-object", {1})});
  Code.insert(Code.begin(), op(0, "new-instance", {2}, {}, Outer.name));
  const auto Last = Code.back().pc;
  Code.back() = op(Last + 1, "return-object", {2});
  Code.insert(Code.end() - 1, op(Last, "invoke-direct", {2, 0}, {},
                                 Outer.methods[0].reference));
  Make.reference.returns = Outer.name;
  Make.code_end += 5;
  Input.push_back(Outer);
  return Input;
}

std::vector<Class> abortingNestedAllocationClasses(bool Wide, bool Reuse,
                                                   bool Trailing, bool SDK,
                                                   bool Range, bool Frame) {
  auto Input = switchAllocationClasses(Wide, Reuse, false, SDK, Range);
  auto &Make = Input[0].methods[0];
  auto &Code = Make.instructions;
  // The abort path discards the still-uninitialized inner value. A string
  // operand and its original provider call remain effects in that path.
  Code[3] =
      op(3, "const-string", {Reuse ? 3u : 0u}, std::string("owned abort"));
  Code[4].registers = {Reuse ? 3u : 0u};
  auto Init = method("<init>", {Input[1].name}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Outer = klass("Lfixture/Envelope;", {Init});
  Outer.external = SDK;
  if (SDK) {
    Outer.methods[0].instructions.clear();
    Outer.methods[0].registers = Outer.methods[0].code_end = 0;
  }
  Code.back() = op(18, "invoke-direct", {4, 0}, {}, Outer.methods[0].reference);
  Code.push_back(op(19, "return-object", {4}));
  if (Trailing) {
    const auto Abort =
        std::vector<Instruction>(Code.begin() + 2, Code.begin() + 8);
    Code.erase(Code.begin() + 2, Code.begin() + 8);
    // Keep the switch fallthrough as a forward jump to the physical abort
    // tail; success and all case arms still reach the original initializer.
    Code.insert(Code.begin() + 2, op(2, "goto", {}, {}, {}, 20));
    for (size_t I = 0; I < Abort.size(); ++I) {
      auto Op = Abort[I];
      Op.pc = 20 + I;
      Code.push_back(std::move(Op));
    }
  }
  Code.insert(Code.begin(), op(0, "new-instance", {4}, {}, Outer.name));
  for (size_t I = 1; I < Code.size(); ++I) {
    ++Code[I].pc;
    if (Code[I].target)
      ++*Code[I].target;
    for (auto &Target : Code[I].targets)
      ++Target;
  }
  Make.reference.returns = Outer.name;
  Make.code_end = Code.back().pc + 1;
  if (Frame) {
    Make.registers += 4;
    for (auto &Op : Code)
      for (auto &Reg : Op.registers)
        Reg += 4;
  }
  Input.push_back(Outer);
  return Input;
}

TEST(MobileDalvikJava, AbortingNestedAllocationsKeepTerminalTailOwnership) {
  for (bool Wide : {false, true})
    for (bool Reuse : {false, true})
      for (bool Trailing : {false, true})
        for (bool SDK : {false, true})
          for (bool Range : {false, true})
            for (bool Frame : {false, true})
              for (bool Reverse : {false, true}) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Wide, Reuse, Trailing, SDK, Range, Frame, Reverse}));
                auto Input = abortingNestedAllocationClasses(
                    Wide, Reuse, Trailing, SDK, Range, Frame);
                if (Reverse)
                  std::reverse(Input.begin(), Input.end());
                EXPECT_NO_THROW(([&] {
                  Budget B;
                  const auto Report = recoverJava(linkClasses(Input, B), B);
                  EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(Report.getInteger("minimum_java_release"), 14);
                  std::string Text;
                  for (size_t I = 0;
                       I < Report.getArray("source_units")->size(); ++I)
                    Text += source(Report, I);
                  EXPECT_NE(Text.find("new fixture.Envelope(switch (0)"),
                            std::string::npos);
                  EXPECT_NE(Text.find("new fixture.Target(switch (0)"),
                            std::string::npos);
                  EXPECT_NE(Text.find("owned abort"), std::string::npos);
                })());
              }
}

TEST(MobileDalvikJava, AbortingNestedAllocationsRejectReentryAndEscapes) {
  for (bool Trailing : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Trailing, Mutation}));
      auto Input = abortingNestedAllocationClasses(false, false, Trailing,
                                                   false, false, false);
      auto &Make = Input[0].methods[0];
      auto &Code = Make.instructions;
      const auto AbortPC = Trailing ? 21u : 3u;
      auto Find = [&](unsigned PC) -> Instruction & {
        return *std::find_if(Code.begin(), Code.end(),
                             [&](const auto &Op) { return Op.pc == PC; });
      };
      if (Mutation == 0)
        Find(AbortPC + 5) = op(AbortPC + 5, "goto", {}, {}, {}, 18);
      else if (Mutation == 1)
        Find(AbortPC + 1) = op(AbortPC + 1, "move-object", {3, 0});
      else if (Mutation == 2)
        Find(AbortPC + 1).registers.push_back(0);
      else if (Mutation == 3)
        Find(AbortPC + 2).registers = {4};
      else if (Mutation == 4)
        Find(AbortPC + 5) = op(AbortPC + 5, "return-object", {2});
      else if (Mutation == 5)
        Find(2).targets[0] = AbortPC + 4;
      else if (Mutation == 6)
        Find(10).registers[0] = 0;
      else if (Mutation == 7)
        Find(18).registers[0] = 4;
      else if (Mutation == 8)
        Find(19).registers[1] = 2;
      else if (Mutation == 9)
        Find(AbortPC + 4) = op(AbortPC + 4, "nop");
      else if (Mutation == 10)
        Find(AbortPC + 2) = op(AbortPC + 2, "goto", {}, {}, {}, AbortPC);
      else
        Make.tries = {{1, 18, {{"Ljava/lang/Throwable;", AbortPC + 1}}}};
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

