TEST(MobileDalvikJava, AllocationProgramsKeepProvedLiteralAnonymousBodies) {
  for (bool Conditional : {false, true})
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Conditional, Linked}));
      auto Input = anonymousCreatorClasses();
      auto Init =
          method("<init>", {Input[0].name}, "V", 2,
                 {op(0, "invoke-direct", {0}, {},
                     MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                  op(1, "return-void")});
      Init.access = {"public", "constructor"};
      auto Container = klass("Lfixture/Container;", {Init});
      auto &Host = Input[1];
      auto &Anonymous = Input[2];
      Host.fields[0].reference.type = Container.name;
      Host.fields[0].access.erase("final");
      auto &Clinit = Host.methods[0];
      Clinit.registers = 3;
      Clinit.instructions = {
          op(0, "new-instance", {0}, {}, Container.name),
          op(1, "new-instance", {1}, {}, Anonymous.name),
          op(2, "invoke-direct", {1}, {}, Anonymous.methods[0].reference)};
      if (Conditional) {
        Clinit.instructions.push_back(op(3, "if-eqz", {1}, {}, {}, 6));
        Clinit.instructions.push_back(op(4, "move-object", {2, 1}));
        Clinit.instructions.push_back(op(5, "goto", {}, {}, {}, 7));
        Clinit.instructions.push_back(op(6, "const/4", {2}, int64_t(0)));
      }
      auto &Code = Clinit.instructions;
      Code.push_back(op(Code.size(), "invoke-direct",
                        {0, Conditional ? 2u : 1u}, {},
                        Container.methods[0].reference));
      Code.push_back(
          op(Code.size(), "sput-object", {0}, {}, Host.fields[0].reference));
      Code.push_back(op(Code.size(), "return-void"));
      Clinit.code_end = Code.size();
      Input.push_back(std::move(Container));
      if (Linked)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      const auto Report =
          Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      EXPECT_EQ(Report.getInteger("class_count"), 4);
      EXPECT_EQ(Report.getInteger("method_count"), 5);
      EXPECT_EQ(Report.getInteger("projected_method_count"), 3);
      EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
      const auto *Bindings = Report.getArray("class_source_bindings");
      ASSERT_TRUE(Bindings);
      ASSERT_EQ(Bindings->size(), 1u);
      EXPECT_EQ(Bindings->front().getAsObject()->getString("allocation_method"),
                "Lfixture/Host;-><clinit>()V");
      std::string Text;
      for (size_t I = 0; I < Report.getArray("source_units")->size(); ++I)
        Text += source(Report, I);
      const auto Start = Text.find("new fixture.Creator() {");
      ASSERT_NE(Start, std::string::npos);
      EXPECT_EQ(Text.find("new fixture.Creator() {", Start + 1),
                std::string::npos);
      EXPECT_NE(Text.find("new fixture.Container("), std::string::npos);
      EXPECT_EQ(Text.find("class Host$1"), std::string::npos);
      if (Conditional)
        EXPECT_NE(Text.find("switch (0)"), std::string::npos);
    }
}

TEST(MobileDalvikJava,
     ConditionalAllocationRejectsUnknownEntriesAndReceiverUse) {
  for (unsigned Mutation = 0; Mutation < 7; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = conditionalAllocationClasses();
    auto &M = Input[0].methods[0];
    if (Mutation == 0)
      M.instructions[1].target = 0;
    else if (Mutation == 1)
      M.instructions[1].target = 7;
    else if (Mutation == 2)
      M.instructions[2].registers[0] = 0;
    else if (Mutation == 3)
      M.instructions[5].registers[0] = 2;
    else if (Mutation == 4) {
      for (auto &Op : M.instructions) {
        ++Op.pc;
        if (Op.target)
          ++*Op.target;
      }
      M.instructions.insert(M.instructions.begin(),
                            op(0, "if-eqz", {2}, {}, {}, 3));
      ++M.code_end;
    } else if (Mutation == 5) {
      Input[1].methods[0].access = {"private", "constructor"};
    } else {
      M.instructions[6].registers[1] = 0;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class>
capturedAllocationArgumentClasses(bool Conditional, bool External, bool Range) {
  auto Input = capturedInnerClasses();
  auto Read = method("read", {}, "I", 1,
                     {op(0, "const/4", {0}, int64_t(7)), op(1, "return", {0})});
  Read.access = {"public"};
  auto Provider = klass("Lfixture/Provider;", {Read});
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  std::vector<std::string> Parameters{Input[0].name, Provider.name};
  std::vector<Instruction> Code{op(0, "new-instance", {0}, {}, Input[1].name),
                                op(1, "move-object", {1, 3})};
  if (Conditional) {
    Parameters.push_back("Z");
    Code.push_back(op(2, "if-eqz", {5}, {}, {}, 6));
  }
  Code.push_back(op(Conditional ? 3 : 2,
                    Range ? "invoke-virtual/range" : "invoke-virtual", {4}, {},
                    Provider.methods[0].reference));
  Code.push_back(op(Conditional ? 4 : 3, "move-result", {2}));
  if (Conditional) {
    Code.push_back(op(5, "goto", {}, {}, {}, 7));
    Code.push_back(op(6, "const/4", {2}, int64_t(0)));
  }
  Code.push_back(op(Conditional ? 7 : 4,
                    Range ? "invoke-direct/range" : "invoke-direct", {0, 1, 2},
                    {}, Input[1].methods[0].reference));
  Code.push_back(op(Conditional ? 8 : 5, "return-object", {0}));
  Input.push_back(Provider);
  Input.push_back(klass(
      "Lfixture/Caller;",
      {method("make", Parameters, Input[1].name, Conditional ? 6 : 5, Code)}));
  return Input;
}

