        if (Mutation == 0)
          Inner.fields[0].access.erase("synthetic");
        else if (Mutation == 1)
          Ctor.instructions[0].registers = {2, 0};
        else if (Mutation == 2)
          Ctor.instructions[0] = op(0, "nop");
        else if (Mutation == 3) {
          Inner.external = true;
          Ctor.instructions.clear();
          Ctor.registers = Ctor.code_end = 0;
        } else if (Mutation == 4)
          Inner.access.insert("abstract");
        else if (Mutation == 5)
          Ctor.access = {"private", "constructor"};
        else if (Mutation == 6)
          Call.registers = {1, 0, 2};
        else if (Mutation == 7)
          Code[1].registers[1] = 4;
        else
          std::get<MethodRef>(Call.reference).owner = Input[0].name;
        if (Linked)
          std::reverse(Input.begin(), Input.end());
