TEST(MobileDalvikJava,
     PrivateStaticReifiableResultsRejectForeignScopesAndUnprovedContracts) {
  for (unsigned Mutation = 0; Mutation < 28; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = privateStaticReifiableResultClasses(1, true, true, false,
                                                       false, false);
      auto &Provider = Input[0];
      auto &Read = Provider.methods[0];
      auto &Call = Provider.methods[1];
      auto Replace = [&](std::string_view Before, std::string_view After) {
        const auto At = Read.generic_signature->find(Before);
        ASSERT_NE(At, std::string::npos);
        Read.generic_signature->replace(At, Before.size(), After);
      };
      switch (Mutation) {
      case 0:
        Replace("<T:", "<U:Ljava/lang/Object;T:");
        break;
      case 1:
        Replace(")TT;", ")TMissing;");
        break;
      case 2:
        Replace("<T:Ljava/lang/Object;>",
                "<T:Ljava/lang/Object;:Ljava/lang/Runnable;>");
        break;
      case 3:
        Replace("Class<*>", "Class<Ljava/lang/String;>");
        break;
      case 4:
        Replace("Class<*>", "Class<+Ljava/lang/String;>");
        break;
      case 5:
        Replace("Class<*>", "Class<-Ljava/lang/String;>");
        break;
      case 6:
        Replace("Class<*>", "Class<+TT;>");
        break;
      case 7:
        Read.access.insert("synthetic");
        break;
      case 8:
        Read.access.insert("native");
        break;
      case 9:
        Read.access.insert("abstract");
        break;
      case 10:
        Read.access.insert("bridge");
        break;
      case 11:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 12:
        Provider.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 13:
        Input[3].generic_signature =
            "<C:Ljava/lang/Object;D:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 14:
        Input[3].generic_signature = "<C:Lfixture/Missing;>Ljava/lang/Object;";
        break;
      case 15:
        Call.instructions[0].opcode = "invoke-virtual/range";
        break;
      case 16:
        Call.instructions[0].registers[3] = 20;
        break;
      case 17:
        Replace("Ljava/lang/String;", "TT;");
        Read.reference.parameters[0] = "Ljava/lang/Object;";
        Call.reference.parameters[0] = "Ljava/lang/Object;";
        std::get<MethodRef>(Call.instructions[0].reference) = Read.reference;
        break;
      case 18:
        Provider.access.insert("interface");
        break;
      case 19:
        Provider.access.erase("public");
        break;
      case 20:
        Replace("[Ljava/lang/Class<*>;", "Ljava/lang/Class<*>;");
        Read.reference.parameters.back() = "Ljava/lang/Class;";
        Call.reference.parameters.back() = "Ljava/lang/Class;";
        std::get<MethodRef>(Call.instructions[0].reference) = Read.reference;
        break;
      case 21:
        Read.access.erase("static");
        break;
      case 22: {
        auto Foreign = Call;
        Foreign.reference.owner = "Lfixture/Foreign;";
        Input.push_back(klass(Foreign.reference.owner, {Foreign}));
        break;
      }
      case 23: {
        auto Foreign = Call;
        Foreign.reference.owner = Input[1].name;
        Input[1].methods.push_back(Foreign);
        Provider.methods.resize(1);
        Provider.external = true;
        Read.instructions.clear();
        Read.registers = Read.code_end = 0;
        break;
      }
      case 24:
        Call.instructions[0].registers.pop_back();
        break;
      case 25:
        Read.access.erase("private");
        break;
      case 26:
        Read.access.erase("private");
        Read.access.insert("protected");
        break;
      case 27:
        Input[3].name = "Lfixture/Removed;";
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

std::vector<Class> seededCovariantAuxiliaryClasses(bool External, bool Static,
                                                   bool Range, bool SeedFirst,
                                                   bool Interface,
                                                   bool AbstractOwner,
                                                   bool Ignored, bool Renamed) {
  auto Input = staticReifiableResultClasses(External, Range, false, false,
                                            Ignored, Renamed);
  auto &Provider = Input[0];
  auto &Read = Provider.methods[0];
  const std::string Formal = Renamed ? "Result" : "T";
  const std::string Seed = "T" + Formal + ";";
  const std::string Closed =
      "Ljava/lang/Class<+" +
      std::string(Interface ? "Ljava/lang/Runnable;" : "Ljava/lang/String;") +
      ">;";
  Read.reference.parameters =
      SeedFirst
          ? std::vector<std::string>{"Ljava/lang/Object;", "Ljava/lang/Class;"}
          : std::vector<std::string>{"Ljava/lang/Class;", "Ljava/lang/Object;"};
  Read.generic_signature = "<" + Formal + ":Ljava/lang/Object;>(" +
                           (SeedFirst ? Seed + Closed : Closed + Seed) + ")" +
                           Seed;
  if (!Static)
    Read.access.erase("static");
  if (!External)
    Read.registers = Static ? 3 : 4;
  if (AbstractOwner)
    Provider.access.insert("abstract");
  Provider.interfaces = {"Ljava/io/Serializable;"};
  auto Serializable = klass("Ljava/io/Serializable;");
  Serializable.external = true;
  Serializable.access = {"public", "abstract", "interface"};
  auto Parameters = Read.reference.parameters;
  if (!Static)
    Parameters.insert(Parameters.begin(), Provider.name);
  const unsigned First = Range ? 16 : 1;
  const unsigned Count = Static ? 2 : 3;
  std::vector<unsigned> Words;
  for (unsigned I = First; I < First + Count; ++I)
    Words.push_back(I);
  std::string Opcode = Static ? "invoke-static" : "invoke-virtual";
  if (Range)
    Opcode += "/range";
  std::vector<Instruction> Code{op(0, Opcode, Words, {}, Read.reference)};
  if (Ignored)
    Code.push_back(op(3, "return-void"));
  else {
    Code.push_back(op(3, "move-result-object", {0}));
    Code.push_back(op(4, "return-object", {0}));
  }
  Input[1] =
      klass("Lfixture/Core;",
            {method("call", Parameters, Ignored ? "V" : "Ljava/lang/Object;",
                    First + Count, Code)});
  Input.push_back(Serializable);
  return Input;
}

TEST(MobileDalvikJava, SeededCovariantAuxiliariesKeepInputsResultsAndDispatch) {
  for (bool External : {false, true})
    for (bool Static : {false, true})
      for (bool Range : {false, true})
        for (bool SeedFirst : {false, true})
          for (bool Interface : {false, true})
            for (bool AbstractOwner : {false, true})
              for (bool Ignored : {false, true})
                for (bool Renamed : {false, true})
                  for (unsigned Route = 0; Route < 3; ++Route) {
                    SCOPED_TRACE(::testing::PrintToString(std::tuple{
                        External, Static, Range, SeedFirst, Interface,
                        AbstractOwner, Ignored, Renamed, Route}));
                    auto Input = seededCovariantAuxiliaryClasses(
                        External, Static, Range, SeedFirst, Interface,
                        AbstractOwner, Ignored, Renamed);
                    const auto Target = Input[0].methods[0];
                    if (Route == 2)
                      std::reverse(Input.begin(), Input.end());
                    Budget B;
                    ClassMap Classes;
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                    if (Route)
                      Classes = linkClasses(Input, B);
                    const auto Plans = validateGenericSignatures(Classes, B);
                    EXPECT_TRUE(Plans.erased_generic_invocations.contains(
                        Target.reference));
                    EXPECT_EQ(Classes.at(Target.reference.owner)
                                  .methods[0]
                                  .generic_signature,
                              Target.generic_signature);
                    EXPECT_EQ(
                        Classes.at(Target.reference.owner).methods[0].access,
                        Target.access);
                    const auto R = recoverJava(Classes, B);
                    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                    EXPECT_EQ(R.getString("status"), "recovered");
                    EXPECT_FALSE(R.getArray("generic_signature_projections"));
                    EXPECT_FALSE(R.getArray("class_source_bindings"));
                  }
}

TEST(MobileDalvikJava, SeededCovariantAuxiliariesRejectUnprovedBindings) {
  for (bool External : {false, true})
    for (bool Static : {false, true})
      for (unsigned Mutation = 0; Mutation < 25; ++Mutation)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{External, Static, Mutation, Route}));
          auto Input = seededCovariantAuxiliaryClasses(
              External, Static, true, true, true, true, false, false);
          auto &Provider = Input[0];
          auto &Read = Provider.methods[0];
          auto &Call = Input[1].methods[0];
          auto Replace = [&](std::string_view Before, std::string_view After) {
            const auto Position = Read.generic_signature->find(Before);
            ASSERT_NE(Position, std::string::npos);
            Read.generic_signature->replace(Position, Before.size(), After);
          };
          switch (Mutation) {
          case 0:
            Replace("<T:", "<U:Ljava/lang/Object;T:");
            break;
          case 1:
            Replace("(TT;", "(Ljava/lang/Object;");
            break;
          case 2:
            Replace("+Ljava/lang/Runnable;", "*");
            break;
          case 3:
            Replace("+Ljava/lang/Runnable;", "Ljava/lang/Runnable;");
            break;
          case 4:
            Replace("+Ljava/lang/Runnable;", "-Ljava/lang/Runnable;");
            break;
          case 5:
            Replace(")TT;", ")TMissing;");
            break;
          case 6:
            Replace("<T:Ljava/lang/Object;>",
                    "<T:Ljava/lang/Object;:Ljava/lang/Runnable;>");
            break;
          case 7:
            Replace("+Ljava/lang/Runnable;", "+Lfixture/Missing;");
            break;
          case 8:
            Input[3].generic_signature =
                "<C:Ljava/lang/Object;D:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 9:
            Input[3].generic_signature =
                "<C:Ljava/lang/String;>Ljava/lang/Object;";
            break;
          case 10:
            Input[5].access.erase("public");
            break;
          case 11:
            Input[5].generic_signature =
                "<E:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 12:
            Input[5].enclosing = "Lfixture/Missing;";
            break;
          case 13:
            Read.access.insert("native");
            break;
          case 14:
            Read.access.insert("abstract");
            break;
          case 15:
            Read.access.insert("synthetic");
            break;
          case 16:
            Read.access.insert("bridge");
            break;
          case 17:
            Read.declared_throws = {"Ljava/lang/Exception;"};
            break;
          case 18:
            Provider.generic_signature =
                "<X:Lfixture/Missing;>Ljava/lang/Object;Ljava/io/Serializable;";
            break;
          case 19:
            Call.instructions[0].opcode =
                Static ? "invoke-virtual/range" : "invoke-static/range";
            break;
          case 20:
            Call.instructions[0].registers.pop_back();
            break;
          case 21:
            Input[3].name = "Lfixture/Other;";
            break;
          case 22:
            Read.access.insert("varargs");
            break;
          case 23:
            Read.access.erase("public");
            Read.access.insert("private");
            break;
          case 24:
            Provider.access.insert("interface");
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          // Static inputs retain the closed nominal proof. Public virtual
          // direct seeds also admit an independent all-star context through
          // the shared instance input/result proof, without a value relation.
          if ((Static && (Mutation == 1 || Mutation == 2 || Mutation == 3 ||
                          Mutation == 17)) ||
              (!Static && Mutation == 2)) {
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(
                Plans.erased_generic_invocations.contains(Read.reference));
            EXPECT_EQ(
                recoverJava(Classes, B).getInteger("unrecovered_method_count"),
                0);
            EXPECT_EQ(
                Classes.at(Read.reference.owner).methods[0].generic_signature,
                Read.generic_signature);
            EXPECT_EQ(
                Classes.at(Read.reference.owner).methods[0].declared_throws,
                Read.declared_throws);
            EXPECT_EQ(Classes.at(Read.reference.owner).methods[0].access,
                      Read.access);
            if (Mutation == 17)
              EXPECT_TRUE(validatedClosedDeclaredThrows(Read, Plans));
            continue;
          }
          EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                       std::runtime_error);
        }
}

std::vector<Class> tokenNominalArrayClasses(bool External, bool Range,
                                            bool StandardInput,
                                            bool StandardOutput, bool Ignored,
                                            bool Renamed, unsigned Throws) {
  const std::string InputType =
      StandardInput ? "Ljava/lang/Class;" : "Lfixture/Token;";
  const std::string OutputType =
      StandardOutput ? "Ljava/lang/reflect/Constructor;" : "Lfixture/Box;";
  const std::string Formal = Renamed ? "Item" : "T";
  const std::string Variable = "T" + Formal + ";";
  auto Read =
      method("read", {InputType}, "[" + OutputType, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.reference.owner = "Lfixture/Provider;";
  Read.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(" +
      InputType.substr(0, InputType.size() - 1) + "<" + Variable + ">;)[" +
      OutputType.substr(0, OutputType.size() - 1) + "<" + Variable + ">;";
  if (Throws)
    Read.declared_throws = {"Lfixture/Failure;"};
  auto Provider = klass(Read.reference.owner, {Read});
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  const unsigned Parameter = Range ? 16 : 1;
  std::vector<Instruction> Code{
      op(0, Range ? "invoke-static/range" : "invoke-static", {Parameter}, {},
         Read.reference)};
  if (Ignored)
    Code.push_back(op(3, "return-void"));
  else {
    Code.push_back(op(3, "move-result-object", {0}));
    Code.push_back(op(4, "return-object", {0}));
  }
  auto Call =
      method("call", {InputType}, Ignored ? "V" : Read.reference.returns,
             Parameter + 1, Code);
  auto Input = klass(InputType), Output = klass(OutputType);
  Input.external = Output.external = true;
  Input.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Output.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  auto Failure = klass("Lfixture/Failure;"), Middle = klass("Lfixture/Middle;");
  Failure.external = Middle.external = true;
  Failure.superclass = Middle.name;
  Middle.superclass =
      Throws == 2 ? "Ljava/lang/Error;" : "Ljava/lang/RuntimeException;";
  return {
      Provider, klass("Lfixture/Core;", {Call}), Input, Output, Object, Failure,
      Middle};
}

TEST(MobileDalvikJava,
     TokenNominalArraysRetainScopedElementsAndUncheckedThrows) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool StandardInput : {false, true})
        for (bool StandardOutput : {false, true})
          for (bool Ignored : {false, true})
            for (bool Renamed : {false, true})
              for (unsigned Throws = 0; Throws < 3; ++Throws)
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{External, Range, StandardInput, StandardOutput,
                                 Ignored, Renamed, Throws, Route}));
                  auto Input = tokenNominalArrayClasses(
                      External, Range, StandardInput, StandardOutput, Ignored,
                      Renamed, Throws);
                  const auto Read = Input[0].methods[0];
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  if (Route)
                    Classes = linkClasses(Input, B);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(Plans.erased_generic_invocations.contains(
                      Read.reference));
                  EXPECT_EQ(validatedUncheckedDeclaredThrows(Read, Plans),
                            Throws != 0);
                  EXPECT_EQ(Classes.at(Read.reference.owner)
                                .methods[0]
                                .generic_signature,
                            Read.generic_signature);
                  EXPECT_EQ(Classes.at(Read.reference.owner)
                                .methods[0]
                                .declared_throws,
                            Read.declared_throws);
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getString("status"), "recovered");
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                  EXPECT_FALSE(R.getArray("class_source_bindings"));
                }
}

