std::vector<Class> plainInterfaceCovarianceClasses(bool External,
                                                   bool Redeclared, bool Wide,
                                                   bool Range, bool Metadata) {
  std::vector<std::string> Parameters{"I", "[Ljava/lang/Object;"};
  if (Wide)
    Parameters.insert(Parameters.end(), {"J", "D"});
  auto Required = method("update", Parameters, "Lfixture/Root;", 0, {});
  Required.access = {"public", "abstract"};
  auto Scalar = method("scalar", {}, "I", 0, {});
  Scalar.access = Required.access;
  auto Root = klass("Lfixture/Root;", {Required, Scalar});
  Root.access = {"public", "abstract", "interface"};
  Root.external = External;
  auto Api = klass("Lfixture/Api;", Redeclared ? std::vector<Method>{Required}
                                               : std::vector<Method>{});
  Api.access = Root.access;
  Api.external = External;
  Api.interfaces = {Root.name};
  const unsigned Words = Wide ? 7 : 3;
  auto Typed = method("update", Parameters, Api.name, Words,
                      {op(0, "return-object", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = "Lfixture/Worker;";
  std::vector<unsigned> Registers;
  for (unsigned I = 0; I < Words; ++I)
    Registers.push_back(I);
  auto Bridge =
      method("update", Parameters, Root.name, Words,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                 Registers, {}, Typed.reference),
              op(3, "move-result-object", {0}), op(4, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(3, "return-void")});
  Init.access = {"public", "constructor"};
  Scalar = method("scalar", {}, "I", 1,
                  {op(0, "const/4", {0}, int64_t(0)), op(1, "return", {0})});
  Scalar.access = {"public"};
  auto Worker = klass(Typed.reference.owner, {Init, Typed, Bridge, Scalar});
  Worker.interfaces = {Api.name};
  std::vector<Class> Input{Root, Api, Worker};
  if (Metadata) {
    auto Marker = klass("Lfixture/Marker;");
    Marker.access = Root.access;
    Marker.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    Input.push_back(Marker);
  }
  return Input;
}

TEST(MobileDalvikJava,
     PlainInterfaceCovarianceUsesCompleteOriginalBridgeProofs) {
  for (bool External : {false, true})
    for (bool Redeclared : {false, true})
      for (bool Wide : {false, true})
        for (bool Range : {false, true})
          for (bool Metadata : {false, true})
            for (bool Linked : {false, true}) {
              if (Wide && !Range)
                continue;
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  External, Redeclared, Wide, Range, Metadata, Linked}));
              auto Input = plainInterfaceCovarianceClasses(
                  External, Redeclared, Wide, Range, Metadata);
              const auto Bridge = Input[2].methods[2].reference;
              const auto Target = Input[2].methods[1].reference;
              const auto Required = Input[0].methods[0].reference;
              if (Linked)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Linked)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(Plans.covariant_interface_returns.contains(
                  {Target, Required}));
              const auto Inheritance =
                  planGenericInheritance(Classes, Plans, B);
              ASSERT_TRUE(Inheritance.bridges.contains(Bridge));
              EXPECT_EQ(Inheritance.bridges.at(Bridge).target, Target);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_FALSE(Classes.at(Target.owner).generic_signature);
            }
}

TEST(MobileDalvikJava,
     PlainInterfaceCovarianceRejectsLostContractsAndForwarding) {
  for (bool External : {false, true})
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Linked, Mutation}));
        auto Input =
            plainInterfaceCovarianceClasses(External, true, true, true, true);
        auto &Typed = Input[2].methods[1];
        auto &Bridge = Input[2].methods[2];
        if (Mutation == 0)
          Input[2].methods.erase(Input[2].methods.begin() + 2);
        else if (Mutation == 1)
          Bridge.instructions[0].registers[0] = 1;
        else if (Mutation == 2)
          std::swap(Bridge.instructions[0].registers[1],
                    Bridge.instructions[0].registers[2]);
        else if (Mutation == 3)
          Bridge.instructions[2].registers[0] = 2;
        else if (Mutation == 4) {
          Bridge.instructions.insert(Bridge.instructions.begin() + 2,
                                     op(4, "const/4", {0}, int64_t(0)));
          Bridge.instructions.back().pc = 5;
          Bridge.code_end = 6;
        } else if (Mutation == 5)
          Bridge.instructions[0].opcode = "invoke-interface/range";
        else if (Mutation == 6)
          std::get<MethodRef>(Bridge.instructions[0].reference).owner =
              Input[0].name;
        else if (Mutation == 7)
          Typed.generic_signature =
              "<T:Ljava/lang/Object;>(I[Ljava/lang/Object;JD)Lfixture/Api;";
        else if (Mutation == 8)
          Typed.declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
        else if (Mutation == 9)
          Input[1].interfaces.clear();
        else if (Mutation == 10)
          Bridge.access.erase("synthetic");
        else
          Bridge.instructions[0].registers[4] = 5;
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava, PlainInterfaceFieldsKeepSourceAndDependencyOwnership) {
  for (bool External : {false, true})
    for (bool Linked : {false, true})
      for (unsigned Owners = 1; Owners <= 3; ++Owners) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Linked, Owners}));
        auto Input =
            plainInterfaceCovarianceClasses(External, false, true, true, false);
        for (unsigned I = 0; I < 2; ++I) {
          if (!(Owners & (1u << I)))
            continue;
          auto &Api = Input[I];
          Api.fields = {{{Api.name, "FLAGS", "I"},
                         {"public", "static", "final"},
                         int64_t(11 + I)},
                        {{Api.name, "LABEL", "Ljava/lang/String;"},
                         {"public", "static", "final"},
                         std::string("owned-interface")}};
          if (Linked)
            std::reverse(Api.fields.begin(), Api.fields.end());
        }
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count"), 1);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        const auto *Helpers = R.getArray("generated_source_helpers");
        ASSERT_NE(Helpers, nullptr);
        const auto Initializers = std::count_if(
            Helpers->begin(), Helpers->end(), [](const auto &Row) {
              return Row.getAsObject()->getString("kind") ==
                     "field-initializer";
            });
        EXPECT_EQ(Initializers, External ? 0 : (Owners == 3 ? 2 : 1));
      }
}

TEST(MobileDalvikJava,
     PlainInterfaceFieldsRejectChangedRolesScopesAndInitialization) {
  for (bool External : {false, true})
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
        if (External && Mutation >= 6)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Linked, Mutation}));
        auto Input =
            plainInterfaceCovarianceClasses(External, true, true, true, false);
        auto &Api = Input[1];
        Api.fields = {{{Api.name, "FLAGS", "I"},
                       {"public", "static", "final"},
                       int64_t(11)}};
        auto &Field = Api.fields[0];
        if (Mutation == 0)
          Field.access.erase("public");
        else if (Mutation == 1)
          Field.access.erase("static");
        else if (Mutation == 2)
          Field.access.erase("final");
        else if (Mutation == 3)
          Field.access.insert("volatile");
        else if (Mutation == 4)
          Field.reference.owner = Input[0].name;
        else if (Mutation == 5) {
          Field.reference.type = "Lfixture/Box;";
          Field.generic_signature = "Lfixture/Box<*>;";
          Field.value = std::monostate{};
          auto Box = klass("Lfixture/Box;");
          Box.external = true;
          Box.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          Input.push_back(Box);
        } else if (Mutation == 6) {
          auto Init = method("<clinit>", {}, "V", 1,
                             {op(0, "unsupported-field-initialization"),
                              op(1, "return-void")});
          Init.reference.owner = Api.name;
          Init.access = {"static", "constructor"};
          Api.methods.push_back(Init);
        } else
          Field.value = std::string("invalid-int-value");
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class>
plainAbstractInterfaceBridgeClasses(bool ExternalRoot, bool Wide, bool Range,
                                    bool EarlyClass, bool Metadata,
                                    bool ParentDefault = false) {
  auto Input = plainInterfaceCovarianceClasses(ExternalRoot, true, Wide, Range,
                                               Metadata);
  if (ParentDefault) {
    auto &Default = Input[0].methods[0];
    Default.access = {"public"};
    if (!ExternalRoot) {
      Default.registers = Wide ? 7 : 3;
      Default.instructions = {op(0, "return-object", {0})};
      Default.code_end = 1;
    }
  }
  auto &Api = Input[1];
  Api.external = false;
  Api.methods[0].reference.returns = Api.name;
  auto Bridge = Input[2].methods[2];
  Bridge.reference.owner = Api.name;
  Bridge.instructions[0].opcode =
      Range ? "invoke-interface/range" : "invoke-interface";
  Bridge.instructions[0].reference = Api.methods[0].reference;
  Api.methods.push_back(Bridge);
  Api.fields = {
      {{Api.name, "FLAGS", "I"}, {"public", "static", "final"}, int64_t(11)}};
  if (EarlyClass) {
    auto &Worker = Input[2];
    const auto OldName = Worker.name;
    Worker.name = "Lfixture/AWorker;";
    for (auto &M : Worker.methods) {
      M.reference.owner = Worker.name;
      for (auto &I : M.instructions)
        if (auto *Call = std::get_if<MethodRef>(&I.reference);
            Call && Call->owner == OldName)
          Call->owner = Worker.name;
    }
  }
  return Input;
}

