TEST(MobileDalvikJava, InterfaceSuperGettersRejectChangedBindingAndScope) {
  for (bool External : {false, true})
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Linked, Mutation}));
        auto Input =
            interfaceSuperGetterClasses(External, false, true, false, false);
        auto &Bridge = Input[2].methods[0], &Default = Input[1].methods[0];
        if (Mutation == 0)
          Bridge.instructions[0].opcode = "invoke-interface/range";
        else if (Mutation == 1)
          Bridge.instructions[0].registers = {0};
        else if (Mutation == 2)
          Bridge.instructions[1].registers = {1};
        else if (Mutation == 3)
          Bridge.instructions[2].registers = {1};
        else if (Mutation == 4)
          Bridge.instructions[0].reference = Input[0].methods[0].reference;
        else if (Mutation == 5)
          Default.access.insert("abstract");
        else if (Mutation == 6)
          Default.access = {"private"};
        else if (Mutation == 7)
          Default.generic_signature =
              "<T:Ljava/lang/Object;>()Lfixture/Payload;";
        else if (Mutation == 8)
          Bridge.generic_signature =
              "<T:Ljava/lang/Object;>()Lfixture/Payload;";
        else if (Mutation == 9)
          Input[2].interfaces.push_back(Input[0].name);
        else if (Mutation == 10)
          Input[2].superclass = Input[3].name;
        else if (Mutation == 11)
          Bridge.reference.returns = "Ljava/lang/Object;";
        else if (Mutation == 12) {
          Bridge.instructions.insert(Bridge.instructions.begin() + 2,
                                     op(4, "const/4", {0}, int64_t(0)));
          Bridge.instructions.back().pc = 5;
          Bridge.code_end = 6;
        } else if (Mutation == 13)
          Bridge.declared_throws =
              std::vector<std::string>{"Ljava/lang/Exception;"};
        else if (Mutation == 14)
          Default.access.insert("static");
        else
          Input[1].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Root;";
        if (Linked)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> interfaceSuperScalarClasses(bool External, bool Synthetic,
                                               bool Range, bool Inherited,
                                               bool Extra,
                                               const std::string &Parameter,
                                               const std::string &Returns,
                                               bool Mangled = false) {
  auto Input = interfaceSuperGetterClasses(External, Synthetic, Range, false,
                                           false, false);
  for (unsigned I : {0U, 1U}) {
    auto &M = Input[I].methods.front();
    M.reference.parameters = {Parameter};
    M.reference.returns = Returns;
    if (!External) {
      const bool Wide = Returns == "J" || Returns == "D";
      M.registers = 6;
      M.instructions = {
          op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
          op(1, Wide ? "return-wide" : "return", {0})};
    }
  }
  auto &Wrapper = Input[2];
  auto &Bridge = Wrapper.methods.front();
  Bridge.reference.parameters = {Parameter};
  Bridge.reference.returns = Returns;
  Bridge.registers = 6;
  const bool WideInput = Parameter == "J" || Parameter == "D";
  const bool WideResult = Returns == "J" || Returns == "D";
  Bridge.instructions = {
      op(0, Range ? "invoke-super/range" : "invoke-super",
         WideInput ? std::vector<unsigned>{3, 4, 5}
                   : std::vector<unsigned>{4, 5},
         {}, Input[1].methods.front().reference),
      op(3, WideResult ? "move-result-wide" : "move-result", {0}),
      op(4, WideResult ? "return-wide" : "return", {0})};
  if (Inherited)
    Input[1].methods.clear();
  if (Extra) {
    auto Side = klass("Lfixture/Side;");
    Side.access = {"public", "abstract", "interface"};
    Wrapper.interfaces.push_back(Side.name);
    Input.push_back(std::move(Side));
  }
  if (Mangled)
    for (auto &C : Input)
      for (auto &M : C.methods) {
        if (M.reference.name == "style")
          M.reference.name = "style-name";
        for (auto &Op : M.instructions)
          if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
              Ref && Ref->name == "style")
            Ref->name = "style-name";
      }
  return Input;
}

TEST(MobileDalvikJava, InterfaceSuperScalarsKeepWordsAndInheritedDefaults) {
  const std::vector<std::pair<std::string, std::string>> Types{
      {"F", "I"}, {"I", "Z"}, {"J", "J"}, {"D", "D"}, {"Z", "F"}};
  for (const auto &[Parameter, Returns] : Types)
    for (bool External : {false, true})
      for (bool Synthetic : {false, true})
        for (bool Range : {false, true})
          for (bool Inherited : {false, true})
            for (bool Reverse : {false, true}) {
              const bool Mangled = !External;
              auto Input = interfaceSuperScalarClasses(
                  External, Synthetic, Range, Inherited, true, Parameter,
                  Returns, Mangled);
              const auto Bridge = Input[2].methods.front().reference;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
              bool Found = false;
              for (const auto &Value : *R.getArray("methods")) {
                const auto &Row = *Value.getAsObject();
                if (Row.getString("identity") == Bridge.identity()) {
                  Found = true;
                  EXPECT_EQ(Row.getString(Mangled ? "body_projection_kind"
                                                  : "projection_kind"),
                            "interface-super-scalar-forwarding-bridge");
                }
              }
              EXPECT_TRUE(Found);
            }
}

std::vector<Class> overloadedInterfaceSuperScalarClasses(bool External,
                                                         bool Synthetic,
                                                         bool Range) {
  auto Input = interfaceSuperScalarClasses(External, Synthetic, Range, true,
                                           true, "F", "F", !External);
  for (const auto &[Parameter, Returns] :
       std::vector<std::pair<std::string, std::string>>{{"I", "F"},
                                                        {"J", "D"}}) {
    auto Other = interfaceSuperScalarClasses(
        External, Synthetic, Range, true, true, Parameter, Returns, !External);
    Input[0].methods.push_back(Other[0].methods.front());
    Input[2].methods.push_back(Other[2].methods.front());
  }
  return Input;
}

TEST(MobileDalvikJava, InterfaceSuperScalarOverloadsKeepDescriptorSelection) {
  for (bool External : {false, true})
    for (bool Synthetic : {false, true})
      for (bool Range : {false, true})
        for (bool Reverse : {false, true}) {
          auto Input =
              overloadedInterfaceSuperScalarClasses(External, Synthetic, Range);
          std::set<MethodRef> Bridges;
          for (const auto &M : Input[2].methods)
            if (M.reference.name != "<init>")
              Bridges.insert(M.reference);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Classes = linkClasses(Input, B);
          const auto Signatures = validateGenericSignatures(Classes, B);
          const auto Plan = planGenericInheritance(Classes, Signatures, B);
          for (const auto &Ref : Bridges) {
            ASSERT_TRUE(Plan.retained_plain_bridges.contains(Ref));
            EXPECT_TRUE(
                Plan.retained_plain_bridges.at(Ref).interface_super_forwarder);
            EXPECT_EQ(Plan.retained_plain_bridges.at(Ref).target.parameters,
                      Ref.parameters);
          }
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
          std::set<std::string> Names;
          for (const auto &Value : *R.getArray("methods")) {
            const auto &Row = *Value.getAsObject();
            if (Row.getString("name") == "style-name") {
              ASSERT_TRUE(Row.getString("source_name"));
              Names.insert(Row.getString("source_name")->str());
              EXPECT_EQ(Row.getArray("source_name_family")->size(), 6u);
            }
          }
          EXPECT_EQ(Names.size(), External ? 0u : 1u);
        }
}

TEST(MobileDalvikJava, InterfaceSuperScalarOverloadsRejectChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = overloadedInterfaceSuperScalarClasses(false, false, false);
    auto &Other = Input[0].methods[1];
    if (Mutation == 0)
      Other.access.insert("static");
    else if (Mutation == 1)
      Other.access = {"private"};
    else if (Mutation == 2)
      Other.generic_signature = "<T:Ljava/lang/Object;>(I)F";
    else if (Mutation == 3)
      Other.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 4)
      Other.reference.parameters = {"Ljava/lang/Object;"};
    else if (Mutation == 5)
      Other.reference.parameters = {"I", "I"};
    else if (Mutation == 6)
      Other.reference.returns = "Ljava/lang/Object;";
    else if (Mutation == 7) {
      Other.reference.parameters = {"F"};
      Other.reference.returns = "I";
    } else if (Mutation == 8)
      Other.access.insert("bridge");
    else if (Mutation == 9) {
      auto Rival = Input[0];
      Rival.name = "Lfixture/Rival;";
      for (auto &M : Rival.methods)
        M.reference.owner = Rival.name;
      Input[1].interfaces.push_back(Rival.name);
      Input.push_back(std::move(Rival));
    } else if (Mutation == 10) {
      auto Abstract = Other;
      Abstract.reference.owner = Input[1].name;
      Abstract.access.insert("abstract");
      Abstract.instructions.clear();
      Abstract.registers = Abstract.code_end = 0;
      Input[1].methods.push_back(std::move(Abstract));
    } else
      Input[2].methods.back().instructions.front().registers.back() = 0;
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

TEST(MobileDalvikJava, InterfaceSuperScalarsRejectUnprovenSelectionAndWords) {
  for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = interfaceSuperScalarClasses(false, false, false, true, true,
                                             "F", "I", true);
    auto &Root = Input[0], &Api = Input[1], &Wrapper = Input[2];
    auto &Bridge = Wrapper.methods.front();
    if (Mutation == 0)
      Bridge.instructions.front().registers[0] = 0;
    else if (Mutation == 1)
      Bridge.instructions.front().registers[1] = 4;
    else if (Mutation == 2)
      Bridge.instructions.back().registers = {1};
    else if (Mutation == 3)
      Bridge.instructions.front().opcode = "invoke-interface";
    else if (Mutation == 4) {
      auto Call = Root.methods.front().reference;
      Bridge.instructions.front().reference = Call;
    } else if (Mutation == 5)
      Api.generic_signature =
          "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Root;";
    else if (Mutation == 6) {
      Root.methods.front().access.insert("abstract");
      Root.methods.front().instructions.clear();
      Root.methods.front().registers = Root.methods.front().code_end = 0;
    } else if (Mutation == 7)
      Bridge.generic_signature = "<T:Ljava/lang/Object;>(F)I";
    else if (Mutation == 8)
      Root.methods.front().access.insert("static");
    else if (Mutation == 9)
      Api.interfaces.push_back("Lfixture/Missing;");
    else if (Mutation == 10)
      Root.interfaces.push_back(Api.name);
    else if (Mutation == 11) {
      auto Rival = Root;
      Rival.name = "Lfixture/Rival;";
      Rival.methods.front().reference.owner = Rival.name;
      Api.interfaces.push_back(Rival.name);
      Input.push_back(std::move(Rival));
    } else if (Mutation == 12) {
      Api.methods = Root.methods;
      auto &Abstract = Api.methods.front();
      Abstract.reference.owner = Api.name;
      Abstract.access.insert("abstract");
      Abstract.instructions.clear();
      Abstract.registers = Abstract.code_end = 0;
    } else if (Mutation == 13)
      Input.back().interfaces.push_back(Api.name);
    else if (Mutation == 14)
      Root.methods.front().declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 15) {
      for (auto &Op : Bridge.instructions)
        ++Op.pc;
      Bridge.instructions.insert(Bridge.instructions.begin(), op(0, "nop"));
      ++Bridge.code_end;
    } else if (Mutation == 16)
      Wrapper.superclass = "Lfixture/Payload;";
    else if (Mutation == 17)
      Bridge.access.erase("bridge");
    else if (Mutation == 18)
      std::get<MethodRef>(Bridge.instructions.front().reference).parameters = {
          "D"};
    else
      Bridge.instructions[1].registers = Bridge.instructions[2].registers = {5};
    Budget B;
    if (Mutation == 17) {
      // Without ACC_BRIDGE this is an ordinary descriptor-only override.
      // Its unchanged direct-interface default call now has its own shared
      // selection receipt; no bridge projection is needed.
      EXPECT_EQ(recoverJava(linkClasses(Input, B), B)
                    .getInteger("unrecovered_method_count"),
                0);
    } else {
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
  }
}

