TEST(MobileDalvikJava,
     ConstructorEncodedDefaultsRejectConstantSDKAndNondefaultBits) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    SCOPED_TRACE(Mutation);
    const std::string Type = Mutation == 1 || Mutation == 3 || Mutation == 6
                                 ? "F"
                             : Mutation == 2 || Mutation == 4 ? "D"
                                                              : "I";
    auto Input =
        constructorEncodedDefaultClasses(Type, true, true, true, false, false);
    auto &Provider = Input[1];
    auto &Field = Provider.fields[0];
    if (Mutation == 0)
      Field.value = int64_t(1);
    else if (Mutation == 1)
      Field.value = FloatBits{UINT64_C(0x80000000), false};
    else if (Mutation == 2)
      Field.value = FloatBits{UINT64_C(0x8000000000000000), true};
    else if (Mutation == 3)
      Field.value = FloatBits{UINT64_C(0x7fc01234), false};
    else if (Mutation == 4)
      Field.value = FloatBits{UINT64_C(0x7ff8123456789abc), true};
    else if (Mutation == 5) {
      Provider.external = true;
      Provider.methods.clear();
    } else if (Mutation == 6)
      Field.value = FloatBits{0, true};
    else if (Mutation == 7)
      Input[0].methods[1].instructions[2].opcode = "sget-wide";
    else if (Mutation == 8)
      Field.access = {"private", "static", "final"};
    else if (Mutation == 9)
      Field.access.erase("static");
    else if (Mutation == 10) {
      auto &Init = Provider.methods[0];
      Init.instructions.insert(Init.instructions.begin() + 2,
                               op(2, "sput", {0}, {}, Field.reference));
      Init.instructions.back().pc = 3;
      Init.code_end = 4;
    } else if (Mutation == 11)
      Provider.methods[0].instructions[0] = op(0, "if-eqz", {0}, {}, {}, 2);
    else
      Input[0].methods[1].instructions[2].registers = {3};
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

TEST(MobileDalvikJava,
     ConstructorEncodedStaticReadsPreserveCapturesAndSnapshots) {
  for (const auto &Type : {"I", "J"})
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(Type);
      SCOPED_TRACE(Linked);
      auto Input = constructorStaticReadClasses(Type);
      Input[0].fields.back().value = int64_t(37);
      Budget B;
      const auto R =
          Linked ? recoverJava(linkClasses(Input, B), B) : recover(Input);
      const auto Text = source(R, 1);
      const auto Read = Text.find(".sharedValue");
      ASSERT_NE(Read, std::string::npos);
      const auto Super = Text.find("super(", Read);
      EXPECT_LT(Text.find("this.enclosure ="), Read);
      EXPECT_LT(Read, Super);
      EXPECT_NE(Text.find("__neverdCtorField1", Text.find(");", Super) + 2),
                std::string::npos);
      EXPECT_EQ(Text.find(".sharedValue", Read + 1), std::string::npos);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
    }
}

