TEST(MobileDalvikJava,
     ConstructorEncodedStaticReadsRejectConstantsAndInvalidCarriers) {
  for (unsigned Mutation = 0; Mutation < 9; ++Mutation)
    for (bool Dependency : {false, true}) {
      SCOPED_TRACE(Mutation);
      SCOPED_TRACE(Dependency);
      auto Input = constructorParameterReadClasses("J", true, false, true);
      auto &Field = Input[2].fields[0];
      Field.value = int64_t(37);
      Input[2].external = Dependency;
      auto &Default = Input[0].methods[1];
      auto &Read = Default.instructions[2];
      switch (Mutation) {
      case 0:
        Field.access.insert("final");
        break;
      case 1:
        Field.value = std::string("invalid integer initializer");
        break;
      case 2:
        Field.reference.type = "Ljava/lang/Object;";
        Read.reference = Field.reference;
        Read.opcode = "sget-object";
        break;
      case 3:
        Read.registers = {0};
        break;
      case 4:
        Read.registers = {Default.registers - 1};
        break;
      case 5:
        Field.access.erase("static");
        break;
      case 6:
        Read.element_width = 1;
        break;
      case 7:
        std::get<FieldRef>(Read.reference).owner = "Lfixture/Missing;";
        break;
      case 8:
        Read.opcode = "sget";
        break;
      }
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_FALSE(constructorPrefixStaticRead(Default, Read, Classes, B));
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> nominalResultInvocationClasses(bool Dependency,
                                                  bool Interface, bool Static,
                                                  bool Range) {
  auto Input =
      erasedResultInvocationClasses(Dependency, Interface, Static, Range);
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Carrier.external = Dependency;
  auto &Read = Input[1].methods[0];
  Read.reference.returns = Carrier.name;
  Read.generic_signature = std::string("<T:") + (Interface ? ":" : "") +
                           Input[2].name +
                           ">(Ljava/lang/Object;IJD)Lfixture/Carrier<TT;>;";
  auto &Call = Input[0].methods[0];
  Call.reference.returns = Carrier.name;
  Call.instructions[0].reference = Read.reference;
  Input.push_back(Carrier);
  return Input;
}

std::vector<Class> boundedSeedFactoryClasses(bool External, bool Interface,
                                             bool Range, bool ReverseSlots,
                                             bool Variance) {
  auto Bound = klass("Lfixture/Bound;");
  if (Interface)
    Bound.access = {"public", "abstract", "interface"};
  Bound.external = External;
  auto Closed = klass("Lfixture/Closed;");
  Closed.external = External;
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Carrier.external = External;
  auto Factory = klass("Lfixture/Factory;");
  Factory.generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Factory.external = External;
  std::vector<std::string> Params{Carrier.name, Factory.name, Closed.name, "J"};
  std::vector<std::string> Types{
      "Lfixture/Carrier<TT;>;",
      std::string("Lfixture/Factory<") + (Variance ? "-" : "") +
          "Lfixture/Closed;" + (Variance ? "+" : "") + "TT;>;",
      Closed.name, "J"};
  if (ReverseSlots) {
    std::reverse(Params.begin(), Params.end());
    std::reverse(Types.begin(), Types.end());
  }
  auto Read =
      method("fill", Params, Carrier.name, 6,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.generic_signature =
      std::string("<T:") + (Interface ? ":" : "") + Bound.name + ">(";
  for (const auto &Type : Types)
    *Read.generic_signature += Type;
  *Read.generic_signature += ")Lfixture/Carrier<TT;>;";
  auto Provider = klass("Lfixture/Provider;", {Read});
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Call =
      method("call", Params, Carrier.name, 6,
             {op(0, Range ? "invoke-static/range" : "invoke-static",
                 {1, 2, 3, 4, 5}, {}, Provider.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  return {klass("Lfixture/Client;", {Call}),
          Provider,
          Bound,
          Closed,
          Carrier,
          Factory};
}

