TEST(MobileDalvikJava, BoundedSeedFactoriesRejectContractAndDispatchDrift) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = boundedSeedFactoryClasses(false, true, true, false, true);
    auto &M = Input[1].methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      const auto At = M.generic_signature->find(From);
      ASSERT_NE(At, std::string::npos);
      M.generic_signature->replace(At, From.size(), To);
    };
    if (Mutation == 0)
      replace("<T::Lfixture/Bound;>",
              "<T::Lfixture/Bound;:Ljava/io/Serializable;>");
    else if (Mutation == 1)
      replace("Lfixture/Carrier<TT;>;", "Lfixture/Carrier<-TT;>;");
    else if (Mutation == 2)
      replace("-Lfixture/Closed;", "+Lfixture/Closed;");
    else if (Mutation == 3)
      replace("+TT;", "-TT;");
    else if (Mutation == 4)
      replace("+TT;", "+TUnknown;");
    else if (Mutation == 5)
      Input[4].generic_signature = "<E:Lfixture/Closed;>Ljava/lang/Object;";
    else if (Mutation == 6)
      Input[5].generic_signature =
          "<A:Lfixture/Closed;R:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 7)
      M.access.insert("synthetic");
    else if (Mutation == 8)
      M.access.insert("varargs");
    else if (Mutation == 9)
      M.declared_throws = std::vector<std::string>{"Ljava/lang/Exception;"};
    else if (Mutation == 10)
      Input[0].methods[0].instructions[0].opcode = "invoke-virtual/range";
    else if (Mutation == 11)
      M.instructions[0].opcode = "unsupported-factory-body";
    else
      Input[2].access.erase("public");
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> boundedCovariantSeedClasses(bool External, bool Interface,
                                               unsigned Count, bool Covariant) {
  auto Input =
      boundedSeedFactoryClasses(External, Interface, true, false, true);
  auto &Read = Input[1].methods[0];
  Read.reference.parameters.assign(Count, Input[4].name);
  Read.reference.parameters.insert(Read.reference.parameters.begin(), "I");
  Read.reference.parameters.push_back("J");
  Read.generic_signature =
      std::string("<T:") + (Interface ? ":" : "") + Input[2].name + ">(I";
  for (unsigned I = 0; I < Count; ++I)
    *Read.generic_signature +=
        Covariant ? "Lfixture/Carrier<+TT;>;" : "Lfixture/Carrier<TT;>;";
  *Read.generic_signature += "J)Lfixture/Carrier<TT;>;";
  if (!External)
    Read.registers = Count + 4;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  Call.registers = Count + 4;
  Call.instructions[0].reference = Read.reference;
  Call.instructions[0].registers.clear();
  for (unsigned I = 1; I < Call.registers; ++I)
    Call.instructions[0].registers.push_back(I);
  return Input;
}

