TEST(MobileDalvikJava,
     NominalResultCallsRejectUnprovenBoundsInputsAndCarriers) {
  for (bool Dependency : {false, true})
    for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
      SCOPED_TRACE(::testing::Message() << Dependency << ':' << Mutation);
      auto Input =
          nominalResultInvocationClasses(Dependency, false, false, true);
      auto &Read = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      switch (Mutation) {
      case 0:
        Read.generic_signature =
            "<T:Lfixture/Value;U:Ljava/lang/Object;>(Ljava/lang/"
            "Object;IJD)Lfixture/Carrier<TT;>;";
        break;
      case 1:
        Read.generic_signature =
            "<T:Lfixture/Value;:Ljava/io/Serializable;>(Ljava/lang/"
            "Object;IJD)Lfixture/Carrier<TT;>;";
        break;
      case 2:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)Lfixture/Carrier<+TT;>;";
        break;
      case 3:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)Lfixture/Carrier;";
        break;
      case 4:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)Lfixture/"
            "Carrier<Lfixture/Value;>;";
        break;
      case 5:
        Input[3].generic_signature =
            "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 6:
        Input[3].generic_signature = "<E:Lfixture/Value;>Ljava/lang/Object;";
        break;
      case 7:
        Read.generic_signature =
            "<T:Lfixture/Value;>(TT;IJD)Lfixture/Carrier<TT;>;";
        Read.reference.parameters[0] = Input[2].name;
        Call.reference.parameters[1] = Input[2].name;
        break;
      case 8:
        Read.generic_signature =
            "<T:Lfixture/Value;>(Ljava/lang/Object;IJD)[Lfixture/Carrier<TT;>;";
        Read.reference.returns = "[Lfixture/Carrier;";
        Call.reference.returns = Read.reference.returns;
        break;
      case 9:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 10:
        Input[3].access.erase("public");
        break;
      case 11:
        Read.access.insert("bridge");
        break;
      case 12:
        Read.access.erase("public");
        Read.access.insert("private");
        break;
      case 13:
        Read.generic_signature = "<T:Lfixture/Value;>(Lfixture/"
                                 "Carrier<TT;>;IJD)Lfixture/Carrier<TT;>;";
        Read.reference.parameters[0] = Input[3].name;
        Call.reference.parameters[1] = Input[3].name;
        break;
      }
      Call.instructions[0].reference = Read.reference;
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> capturedCovariantClasses(bool Dependency, bool Interface,
                                            bool Direct, bool Private,
                                            bool Range) {
  auto Input = capturedInnerClasses();
  auto &Inner = Input[1];
  Inner.inner_access = Private ? Access{"private"} : Access{"public"};
  if (Private)
    Inner.access.erase("public");
  Inner.methods[0].generic_signature.reset();
  auto Required = method("getItem", {"I"}, "Ljava/lang/Object;", 0, {});
  Required.access = {"public", "abstract"};
  auto Root = klass("Lfixture/Root;", {Required});
  Root.access = {"public", "abstract"};
  if (Interface)
    Root.access.insert("interface");
  Root.external = Dependency;
  auto Base = klass("Lfixture/Base;");
  Base.access = {"public", "abstract"};
  Base.external = Dependency;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  if (!Interface) {
    Init.reference.owner = Root.name;
    Root.methods.push_back(Init);
    Base.superclass = Root.name;
  } else
    Base.interfaces = {Root.name};
  Init.reference.owner = Base.name;
  std::get<MethodRef>(Init.instructions[0].reference).owner = *Base.superclass;
  Base.methods.push_back(Init);
  if (Dependency)
    for (auto *C : {&Base, &Root})
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  Inner.superclass = Direct ? "Ljava/lang/Object;" : Base.name;
  if (Direct)
    Inner.interfaces = {Root.name};
  std::get<MethodRef>(Inner.methods[0].instructions[1].reference).owner =
      *Inner.superclass;
  auto Item = klass("Lfixture/Item;");
  auto Typed =
      method("getItem", {"I"}, Item.name, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = Inner.name;
  auto Bridge =
      method("getItem", {"I"}, "Ljava/lang/Object;", 3,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2},
                 {}, Typed.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.reference.owner = Inner.name;
  Inner.methods.push_back(Typed);
  Inner.methods.push_back(Bridge);
  auto Marker = klass("Lfixture/Marker;");
  Marker.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.insert(Input.end(), {Root, Base, Item, Marker});
  return Input;
}

TEST(MobileDalvikJava,
     CapturedCovarianceSharesOriginalClassAndInterfaceProofs) {
  for (bool Dependency : {false, true})
    for (bool Interface : {false, true})
      for (bool Direct : {false, true})
        for (bool Private : {false, true})
          for (bool Range : {false, true})
            for (bool Linked : {false, true}) {
              if (Direct && !Interface)
                continue;
              SCOPED_TRACE(::testing::Message()
                           << Dependency << Interface << Direct << Private
                           << Range << Linked);
              auto Input = capturedCovariantClasses(Dependency, Interface,
                                                    Direct, Private, Range);
              const auto Target = Input[1].methods[1].reference;
              const auto Bridge = Input[1].methods[2].reference;
              const auto Required = Input[2].methods[0].reference;
              if (Range)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
              if (Linked)
                Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.captured_inner_classes.contains(Target.owner));
              EXPECT_TRUE(Plans.covariant_bridge_contracts.contains(
                  {Bridge, Required}));
              const auto Inheritance =
                  planGenericInheritance(Classes, Plans, B);
              ASSERT_TRUE(Inheritance.bridges.contains(Bridge));
              EXPECT_EQ(Inheritance.bridges.at(Bridge).target, Target);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 3);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_FALSE(Classes.at(Target.owner).generic_signature);
            }
}

TEST(MobileDalvikJava, CapturedCovarianceRejectsLostScopeAndOriginalDispatch) {
  for (bool Dependency : {false, true})
    for (unsigned Mutation = 0; Mutation < 11; ++Mutation) {
      SCOPED_TRACE(::testing::Message() << Dependency << ':' << Mutation);
      auto Input =
          capturedCovariantClasses(Dependency, true, false, true, false);
      auto &Inner = Input[1];
      switch (Mutation) {
      case 0:
        Inner.methods[0].instructions.erase(
            Inner.methods[0].instructions.begin());
        break;
      case 1:
        Inner.fields[0].access.erase("final");
        break;
      case 2:
        Inner.enclosing.reset();
        break;
      case 3:
        Inner.inner_name.reset();
        break;
      case 4:
        Inner.methods[2].instructions[0].registers[0] = 2;
        break;
      case 5:
        Inner.methods[2].instructions[0].opcode = "invoke-super";
        break;
      case 6:
        Inner.methods[2].instructions[2].registers = {1};
        break;
      case 7: {
        auto Missing = method("missing", {}, "I", 0, {});
        Missing.access = {"public", "abstract"};
        Missing.reference.owner = Input[2].name;
        Input[2].methods.push_back(Missing);
        break;
      }
      case 8:
        Inner.methods[1].generic_signature =
            "<T:Ljava/lang/Object;>(I)Lfixture/Item;";
        break;
      case 9:
        Inner.methods[2].declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 10:
        Inner.methods.pop_back();
        break;
      }
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> anonymousCovariantCaptureClasses(bool Dependency,
                                                    bool Range) {
  auto Owner = klass("Lfixture/Owner;");
  auto Menu = klass("Lfixture/Menu;");
  Menu.access = {"public", "abstract", "interface"};
  Menu.external = Dependency;
  Owner.interfaces = {Menu.name};
  auto Required = method("getItem", {}, Menu.name, 0, {});
  Required.access = {"public", "abstract"};
  auto BaseInit =
      method("<init>", {"Ljava/lang/Object;"}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  BaseInit.access = {"public", "constructor"};
  auto Base = klass("Lfixture/Base;", {BaseInit, Required});
  Base.access = {"public", "abstract"};
  Base.external = Dependency;
  if (Dependency)
    for (auto &M : Base.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto Inner = klass("Lfixture/Owner$1;");
  Inner.access.clear();
  Inner.inner_class_present = true;
  Inner.superclass = Base.name;
  const FieldRef Capture{Inner.name, "outer", Owner.name};
  Inner.fields = {{Capture, {"final", "synthetic"}, {}}};
  auto Init =
      method("<init>", {Owner.name, "Ljava/lang/Object;"}, "V", 3,
             {op(0, "iput-object", {1, 0}, {}, Capture),
              op(2, "invoke-direct", {0, 2}, {}, Base.methods[0].reference),
              op(5, "return-void")});
  Init.access = {"constructor"};
  Init.reference.owner = Inner.name;
  auto Typed = method(
      "getItem", {}, Owner.name, 2,
      {op(0, "iget-object", {0, 1}, {}, Capture), op(2, "return-object", {0})});
  Typed.access = {"public"};
  Typed.reference.owner = Inner.name;
  auto Bridge =
      method("getItem", {}, Menu.name, 2,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1}, {},
                 Typed.reference),
              op(3, "move-result-object", {0}), op(4, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.reference.owner = Inner.name;
  Inner.methods = {Init, Typed, Bridge};
  auto Make = method("make", {"Ljava/lang/Object;"}, Base.name, 3,
                     {op(0, "new-instance", {0}, {}, Inner.name),
                      op(2, "invoke-direct", {0, 1, 2}, {}, Init.reference),
                      op(5, "return-object", {0})});
  Make.access = {"public"};
  Make.reference.owner = Owner.name;
  Owner.methods = {Make};
  Inner.enclosing_method = Make.reference;
  auto Marker = klass("Lfixture/Marker;");
  Marker.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Owner, Inner, Base, Menu, Marker};
}

TEST(MobileDalvikJava, AnonymousCovarianceUsesClosedScopeAndOriginalCapture) {
  for (bool Dependency : {false, true})
    for (bool Range : {false, true})
      for (bool Linked : {false, true}) {
        auto Input = anonymousCovariantCaptureClasses(Dependency, Range);
        const auto Target = Input[1].methods[1].reference;
        const auto Bridge = Input[1].methods[2].reference;
        const auto Required = Input[2].methods[1].reference;
        if (Range)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        ClassMap Classes;
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
        if (Linked)
          Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plans.closed_anonymous_classes.contains(Target.owner));
        EXPECT_FALSE(Plans.captured_inner_classes.contains(Target.owner));
        EXPECT_FALSE(Plans.classes.contains(Target.owner));
        ASSERT_TRUE(
            Plans.covariant_bridge_contracts.contains({Bridge, Required}));
        const auto Inheritance = planGenericInheritance(Classes, Plans, B);
        ASSERT_TRUE(Inheritance.bridges.contains(Bridge));
        EXPECT_EQ(Inheritance.bridges.at(Bridge).target, Target);
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        EXPECT_EQ(R.getArray("class_source_bindings")->size(), 1u);
      }
}

