std::vector<Class> conditionalArrayAllocationClasses(
    const std::string &Branch = "if-gez",
    const std::string &Array = "[Ljava/lang/Object;", bool External = false,
    bool Range = false) {
  auto Input = conditionalAllocationClasses();
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {"I", Array, "Ljava/lang/Object;"};
  Make.registers = 6;
  Make.instructions = {op(0, "new-instance", {0}, {}, Input[1].name),
                       op(1, Branch, {3}, {}, {}, 4),
                       op(2, "move-object", {1, 5}),
                       op(3, "goto", {}, {}, {}, 5),
                       op(4, "aget-object", {1, 4, 3}),
                       op(5, Range ? "invoke-direct/range" : "invoke-direct",
                          {0, 1}, {}, Input[1].methods[0].reference),
                       op(6, "return-object", {0})};
  Make.code_end = 7;
  if (External) {
    Input[1].external = true;
    Input[1].methods[0].instructions.clear();
    Input[1].methods[0].registers = Input[1].methods[0].code_end = 0;
  }
  Input.pop_back();
  return Input;
}

std::vector<Class>
conditionalPrimitiveArrayPrivateClasses(const std::string &Type,
                                        bool PrivateRange,
                                        bool ConstructorRange, bool External) {
  const unsigned Width = Type == "J" || Type == "D" ? 2 : 1;
  const unsigned Key = 4 + Width, Flag = Key + 1;
  const std::string Load = Width == 2    ? "aget-wide"
                           : Type == "Z" ? "aget-boolean"
                           : Type == "B" ? "aget-byte"
                           : Type == "C" ? "aget-char"
                           : Type == "S" ? "aget-short"
                                         : "aget";
  const MethodRef ObjectInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Init = method(
      "<init>", {Type, "Ljava/lang/Object;", "I"}, "V", Width + 3,
      {op(0, "invoke-direct", {0}, {}, ObjectInit), op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = klass("Lfixture/Target;", {Init});
  Target.external = External;
  if (External) {
    Target.methods[0].instructions.clear();
    Target.methods[0].registers = Target.methods[0].code_end = 0;
  }
  auto Read =
      method("read", {"[" + Type, "I"}, "Ljava/lang/Object;", 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.reference.owner = "Lfixture/Core;";
  Read.access = {"private"};
  std::vector<unsigned> Arguments{3, 4};
  if (Width == 2)
    Arguments.push_back(5);
  Arguments.insert(Arguments.end(), {Key, Flag});
  auto Make = method(
      "make", {"[" + Type, "I", "I"}, Target.name, 12,
      {op(0, "new-instance", {3}, {}, Target.name), op(1, Load, {4, 9, 10}),
       op(2, PrivateRange ? "invoke-direct/range" : "invoke-direct", {8, 9, 10},
          {}, Read.reference),
       op(3, "move-result-object", {Key}), op(4, "if-eqz", {11}, {}, {}, 7),
       op(5, "const/4", {Flag}, int64_t(1)), op(6, "goto", {}, {}, {}, 9),
       op(7, Load, {4, 9, 10}), op(8, "const/4", {Flag}, int64_t(0)),
       op(9, ConstructorRange ? "invoke-direct/range" : "invoke-direct",
          Arguments, {}, Target.methods[0].reference),
       op(10, "return-object", {3})});
  Make.access = {"public"};
  auto Core = klass("Lfixture/Core;", {Make, Read});
  Core.access = {"public", "final"};
  auto RootInit = method("<init>", {}, "V", 0, {});
  RootInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {RootInit});
  Object.external = true;
  Object.superclass.reset();
  return {Core, Target, Object};
}

