            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            std::string Text;
            for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
              if (source(R, I).find("new fixture.Target(switch (0)") !=
                  std::string::npos)
                Text = source(R, I);
            const auto New = Text.find("new fixture.Target(switch (0)");
            const std::string Address =
                Array == std::string("[[I") ? "((int[][]) o4)[v3]"
                : Array == std::string("[Ljava/lang/String;")
                    ? "((java.lang.String[]) o4)[v3]"
                    : "((java.lang.Object[]) o4)[v3]";
            const auto Load = Text.find(Address);
            ASSERT_NE(New, std::string::npos);
