      SCOPED_TRACE(::testing::Message() << Link << Mutation);
      auto Input = conditionalArrayAllocationClasses();
      auto &Make = Input[0].methods[0];
      auto &Code = Make.instructions;
      if (Mutation == 0)
        Code[1].registers[0] = 4;
      else if (Mutation == 1)
        Code[4].registers[2] = 5;
      else if (Mutation == 2)
        Make.reference.parameters[1] = "[I";
      else if (Mutation == 3)
        Code[4].opcode = "aget";
      else if (Mutation == 4)
        Code[4].registers[0] = 0;
      else if (Mutation == 5)
        Code[4].registers[1] = 0;
      else if (Mutation == 6)
        Code[4].registers[2] = 0;
      else if (Mutation == 7)
        Code[1].target = 0;
      else if (Mutation == 8)
        Code[1].target = 6;
      else if (Mutation == 9)
        Code[3].target = 6;
      else if (Mutation == 10)
        Code[4].registers.pop_back();
      else if (Mutation == 11)
        Make.reference.parameters[0] = "F";
      else if (Mutation == 12)
        Input[1].methods[0].access = {"private", "constructor"};
      else if (Mutation == 13)
        std::get<MethodRef>(Code[5].reference).owner = "Ljava/lang/Object;";
      else if (Mutation == 14)
        Code[2] = op(2, "if-eqz", {5}, {}, {}, 4);
      else if (Mutation == 15) {
        for (auto &Op : Code) {
          ++Op.pc;
          if (Op.target)
            ++*Op.target;
        }
        Code.insert(Code.begin(), op(0, "if-eqz", {5}, {}, {}, 5));
        ++Make.code_end;
      } else if (Mutation == 16)
        Code[4].opcode = "aget-wide";
