            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 8);
            std::string Text;
            for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
              if (source(R, I).find("new fixture.Target(") != std::string::npos)
                Text = source(R, I);
            const auto New = Text.find("new fixture.Target(");
            const auto Call = Text.find(".read(");
