TEST(MobileDalvikJava, ProtectedAllocationCleanupJoinsLongOriginAdapters) {
  for (bool External : {false, true})
    for (bool Wide : {false, true})
      for (bool Range : {false, true})
        for (bool Wrong : {false, true}) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{External, Wide, Range, Wrong}));
          auto Input = allocationHandlerAdapterClasses(External, Wide, Range);
          auto &M = Input[0].methods[0];
          if (Wrong)
            M.instructions[8].registers[1] = Wide ? 9 : 10;
          auto relocated = [](uint32_t PC) {
            return PC + (PC >= 6 ? 512 : 0) + (PC >= 9 ? 512 : 0);
          };
          std::vector<Instruction> Code;
          for (auto Op : M.instructions) {
            const auto PC = relocated(Op.pc);
            if (Op.pc == 6 || Op.pc == 9)
              for (unsigned I = PC - 512; I < PC; ++I)
                Code.push_back(op(I, "nop"));
            Op.pc = PC;
            if (Op.target)
              Op.target = relocated(*Op.target);
            Code.push_back(std::move(Op));
          }
          M.instructions = std::move(Code);
          M.code_end = relocated(M.code_end);
          for (auto &Region : M.tries)
            for (auto &Handler : Region.handlers)
              Handler.target = relocated(Handler.target);
          Budget B;
          if (Wrong)
            rejected([&] { recoverJava(linkClasses(Input, B), B); },
                     "cleanup input");
          else
            EXPECT_EQ(recoverJava(linkClasses(Input, B), B)
                          .getInteger("unrecovered_method_count"),
                      0);
        }
}

std::vector<Class> scalarAllocationCallClasses(const std::string &Type,
                                               unsigned Style, bool External,
                                               bool Range, bool Copy,
                                               bool Protected) {
  const bool Wide = Type == "J" || Type == "D";
  const bool Static = Style == 0, Interface = Style == 2;
  auto Read =
      method("read", {}, Type, Wide ? 3 : 2,
             {op(0, Wide ? "const-wide" : "const", {0},
                 Wide ? int64_t(0x7ff8123456789abc) : int64_t(0x7fc12345)),
              op(1, Wide ? "return-wide" : "return", {0})});
  Read.reference.owner = "Lfixture/Provider;";
  Read.access = Static ? Access{"public", "static"} : Access{"public"};
  auto After =
      method("after", {}, "I", 2,
             {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  After.reference.owner = Read.reference.owner;
  After.access = Read.access;
  auto ProviderInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  ProviderInit.access = {"public", "constructor"};
  auto Provider = klass(Read.reference.owner, {Read, After, ProviderInit});
  if (Interface) {
    Provider.access = {"public", "abstract", "interface"};
    Provider.methods.pop_back();
    for (auto &M : Provider.methods) {
      M.access = {"public", "abstract"};
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  }
  Provider.external = External;
  if (External)
    for (auto &M : Provider.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto Init = method("<init>", {Type}, "V", Wide ? 3 : 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Target = klass("Lfixture/Target;", {Init});
  const std::string Invoke = Style == 0   ? "invoke-static"
                             : Style == 1 ? "invoke-virtual"
                             : Style == 2 ? "invoke-interface"
                                          : "invoke-super";
  const auto Dispatch = Invoke + (Range ? "/range" : "");
  const auto Receiver =
      Static ? std::vector<unsigned>{} : std::vector<unsigned>{8};
  const unsigned Root = Range && Copy ? 3 : 0, Argument = Copy ? 4 : 1;
  std::vector<unsigned> Words{Root, Argument};
  if (Wide)
    Words.push_back(Argument + 1);
  auto Make =
      method("make", {Provider.name}, "Ljava/lang/Object;", 9,
             {op(0, "new-instance", {Root}, {}, Target.name),
              op(1, Dispatch, Receiver, {}, Read.reference),
              op(2, Wide ? "move-result-wide" : "move-result", {1}),
              Copy ? op(3, Wide ? "move-wide" : "move", {4, 1}) : op(3, "nop"),
              op(4, Dispatch, Receiver, {}, After.reference),
              op(5, "move-result", {6}),
              op(6, Range ? "invoke-direct/range" : "invoke-direct", Words, {},
                 Target.methods[0].reference),
              op(7, "return-object", {Root})});
  if (Style == 3) {
    Make.reference.parameters.clear();
    Make.access = {"public"};
  }
  if (Protected) {
    Make.instructions.push_back(op(8, "move-exception", {6}));
    Make.instructions.push_back(op(9, "return-object", {6}));
    Make.code_end = 10;
    Make.tries = {{0, 7, {{std::nullopt, 8}}}};
  }
  auto Core = klass("Lfixture/Core;", {Make});
  if (Style == 3)
    Core.superclass = Provider.name;
  return {Core, Provider, Target};
}

TEST(MobileDalvikJava, AllocationScalarResultsKeepNativeCarriersAndCopies) {
  for (const std::string Type : {"I", "J", "D", "F", "B", "S", "C", "Z"})
    for (unsigned Style = 0; Style != 4; ++Style)
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (bool Copy : {false, true})
            for (bool Protected : {false, true}) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{Type, Style, External, Range, Copy, Protected}));
              auto Input = scalarAllocationCallClasses(Type, Style, External,
                                                       Range, Copy, Protected);
              Budget B;
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              const auto Text = source(R);
              EXPECT_NE(Text.find("new fixture.Target("), std::string::npos);
              EXPECT_NE(Text.find(".read("), std::string::npos);
              EXPECT_NE(Text.find(".after("), std::string::npos);
              EXPECT_EQ(Text.find("doubleToRawLongBits(__neverdAllocation"),
                        std::string::npos);
              EXPECT_EQ(Text.find("floatToRawIntBits(__neverdAllocation"),
                        std::string::npos);
              if (Type == "J" || Type == "D")
                EXPECT_NE(Text.find("long __neverdAllocation"),
                          std::string::npos);
              if (Type == "D")
                EXPECT_NE(Text.find("longBitsToDouble("), std::string::npos);
              if (Type == "F")
                EXPECT_NE(Text.find("intBitsToFloat("), std::string::npos);
            }
}

TEST(MobileDalvikJava, AllocationScalarResultsRejectBrokenProducersAndWords) {
  for (const std::string Type : {"J", "D"})
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation != 10; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Type, Linked, Mutation}));
        auto Input =
            scalarAllocationCallClasses(Type, 1, false, false, true, true);
        auto &M = Input[0].methods[0];
        auto &Code = M.instructions;
        if (Mutation == 0)
          Code[2].opcode = "move-result";
        else if (Mutation == 1)
          Code[2].registers = {8};
        else if (Mutation == 2)
          Code[6].registers.pop_back();
        else if (Mutation == 3)
          Code[6].registers.back() = 6;
        else if (Mutation == 4)
          Code[3].opcode = "move-result-wide";
        else if (Mutation == 5)
          Code[5].registers = {5};
        else if (Mutation == 6) {
          Code[2].opcode = "move-result";
          auto &Read = Input[1].methods[0];
          Read.reference.returns = "F";
          Read.instructions[0].opcode = "const";
          Read.instructions[1].opcode = "return";
          Code[1].reference = Read.reference;
          Code[3].opcode = "move";
        } else if (Mutation == 7)
          Input[1].methods[0].access.insert("bridge");
        else if (Mutation == 8)
          Input[1].methods[0].generic_signature = "<T:Ljava/lang/Object;>()TT;";
        else
          Code[5].opcode = "unsupported-owned-scalar-result";
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava, AllocationScalarResultsConsumeTheSharedMonitorReceipt) {
  for (const std::string Type : {"J", "D", "F"})
    for (bool External : {false, true}) {
      auto Input =
          scalarAllocationCallClasses(Type, 0, External, false, false, false);
      auto &M = Input[0].methods[0];
      M.reference.parameters.push_back("Ljava/lang/Object;");
      M.registers = 10;
      for (auto &Op : M.instructions)
        ++Op.pc;
      M.instructions.insert(M.instructions.begin(),
                            op(0, "monitor-enter", {9}));
      M.instructions.back() = op(8, "monitor-exit", {9});
      M.instructions.push_back(op(9, "return-object", {0}));
      M.instructions.push_back(op(10, "move-exception", {6}));
      M.instructions.push_back(op(11, "monitor-exit", {9}));
      M.instructions.push_back(op(12, "throw", {6}));
      M.code_end = 13;
      M.tries = {{1, 12, {{std::nullopt, 10}}}};
      Budget B;
      const auto R = recoverJava(linkClasses(Input, B), B);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_NE(source(R).find("synchronized ("), std::string::npos);
      M.instructions[11].registers = {0};
      rejected([&] { recover(Input); }, "monitor region");
    }
}

TEST(MobileDalvikJava, AllocationScalarResultsKeepAliasedMonitorReceipt) {
  for (const std::string Type : {"J", "D", "F"})
    for (bool External : {false, true})
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Type, External, Route}));
        auto Input =
            scalarAllocationCallClasses(Type, 0, External, false, false, false);
        auto &M = Input[0].methods[0];
        M.reference.parameters.push_back("Ljava/lang/Object;");
        M.registers = 10;
        for (auto &Op : M.instructions)
          Op.pc += 3;
        M.instructions.insert(M.instructions.begin(),
                              {op(0, "monitor-enter", {9}),
                               op(1, "move-object", {7, 9}),
                               op(2, "const/4", {9}, int64_t(0))});
        M.instructions.back() = op(10, "monitor-exit", {7});
        M.instructions.insert(
            M.instructions.end(),
            {op(11, "return-object", {0}), op(12, "move-exception", {6}),
             op(13, "monitor-exit", {7}), op(14, "throw", {6})});
        M.code_end = 15;
        M.tries = {{3, 14, {{std::nullopt, 12}}}};
        const auto Ref = M.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_NE(source(R).find("synchronized ("), std::string::npos);
        auto &Bad =
            std::find_if(Input.begin(), Input.end(), [&](const Class &C) {
              return C.name == Ref.owner;
            })->methods[0];
        Bad.instructions[13].registers = {0};
        rejected([&] { recover(Input); }, "monitor region");
      }
}

std::vector<Class> scalarAllocationConversionClasses(const std::string &Source,
                                                     const std::string &Dest,
                                                     const std::string &Opcode,
                                                     bool Static, bool External,
                                                     bool Copy,
                                                     bool Protected) {
  auto Input = scalarAllocationCallClasses(Dest, Static ? 0 : 1, External,
                                           false, Copy, Protected);
  auto &Provider = Input[1];
  Field Value;
  Value.reference = {Provider.name, "value", Source};
  Value.access = Static ? Access{"public", "static"} : Access{"public"};
  Provider.fields.push_back(Value);
  const std::string Suffix = Source == "J" || Source == "D" ? "-wide"
                             : Source == "Z"                ? "-boolean"
                             : Source == "B"                ? "-byte"
                             : Source == "S"                ? "-short"
                             : Source == "C"                ? "-char"
                                                            : "";
  auto &Code = Input[0].methods[0].instructions;
  Code[1] = op(1, std::string(Static ? "sget" : "iget") + Suffix,
               Static ? std::vector<unsigned>{1} : std::vector<unsigned>{1, 8},
               {}, Value.reference);
  Code[2] = Opcode.empty() ? op(2, "nop") : op(2, Opcode, {1, 1});
  return Input;
}

std::vector<Class> allocationArrayReadClasses(const std::string &Type,
                                              bool External, bool Alias,
                                              bool Protected) {
  auto Input =
      scalarAllocationCallClasses(Type, 1, External, false, true, Protected);
  auto &Provider = Input[1];
  if (Type.starts_with('L') && !External) {
    Provider.methods[0].instructions = {op(0, "const/4", {0}, int64_t(0)),
                                        op(1, "return-object", {0})};
  }
  Field Values;
  Values.reference = {Provider.name, "values", "[" + Type};
  Values.access = {"public"};
  Provider.fields.push_back(Values);
  const auto Suffix = Type == "J" || Type == "D" ? "-wide"
                      : Type.starts_with('L')    ? "-object"
                      : Type == "Z"              ? "-boolean"
                      : Type == "B"              ? "-byte"
                      : Type == "C"              ? "-char"
                      : Type == "S"              ? "-short"
                                                 : "";
  auto &Code = Input[0].methods[0].instructions;
  Code[1] = op(1, "iget-object", {1, 8}, {}, Values.reference);
  Code[2] = op(2, "aget" + std::string(Suffix), {Alias ? 1u : 4u, 1, 7});
  Code[3] = Alias ? op(3,
                       Type == "J" || Type == "D" ? "move-wide"
                       : Type.starts_with('L')    ? "move-object"
                                                  : "move",
                       {4, 1})
                  : op(3, "nop");
  Input[0].methods[0].reference.parameters.insert(
      Input[0].methods[0].reference.parameters.begin(), "I");
  return Input;
}

