TEST(MobileDalvikJava, AllocationFloatingArithmeticRejectsBrokenReceipts) {
  for (bool Conditional : {false, true})
    for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Conditional, Mutation}));
      auto Input = Conditional
                       ? conditionalConversionClasses("D", "D", "add-double",
                                                      false, false)
                       : scalarAllocationConversionClasses(
                             "D", "D", "add-double", false, false, true, true);
      auto &Code = Input[0].methods[0].instructions;
      auto &Op = Code[Conditional ? 4 : 2];
      Op.registers = {1, 1, 1};
      if (Mutation == 0)
        Op.registers = {0, 1, 1};
      else if (Mutation == 1)
        Op.registers = {1, 0, 1};
      else if (Mutation == 2)
        Op.registers = {1, 1, 0};
      else if (Mutation == 3)
        Op.registers = {1, 1};
      else if (Mutation == 4)
        Op.registers = {1, 1, 8};
      else if (Mutation == 5)
        Op.opcode = "and-double";
      else if (Mutation == 6) {
        Op.opcode = "add-double/lit8";
        Op.literal = int64_t(1);
        Op.registers = {1, 1};
      } else {
        Op.registers = {1, 1, 7};
        // The second word is the live uninitialized outer receiver.
        Code[0].registers = {8};
      }
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

