std::vector<Class>
unusedPlainFormalInvocationClasses(const std::vector<std::string> &Parameters,
                                   const std::string &Return, bool External,
                                   bool Generic, bool Range, bool Alias) {
  auto width = [](const std::string &Type) {
    return Type == "J" || Type == "D" ? 2U : 1U;
  };
  std::vector<unsigned> Words;
  unsigned Registers = 2;
  for (const auto &Type : Parameters)
    for (unsigned I = 0; I < width(Type); ++I)
      Words.push_back(Registers++);
  const std::string Result =
      Return == "V"                                        ? "return-void"
      : Return == "J" || Return == "D"                     ? "return-wide"
      : Return.starts_with('L') || Return.starts_with('[') ? "return-object"
                                                           : "return";
  std::vector<Instruction> Body;
  if (Return == "V")
    Body = {op(0, "return-void")};
  else if (!Parameters.empty() && Return == Parameters[0])
    Body = {op(0, Result, {2})};
  else
    Body = {op(0, width(Return) == 2 ? "const-wide" : "const", {0}, int64_t(0)),
            op(1, Result, {0})};
  auto Relay = method(Alias ? "carry-value" : "relay", Parameters, Return,
                      Registers, Body);
  std::string Signature = "<T:Ljava/lang/Object;>(";
  for (const auto &Type : Parameters)
    Signature += Type;
  Relay.generic_signature = Signature + ")" + Return;
  auto Provider = klass("Lfixture/Provider;", {Relay});
  if (Generic)
    Provider.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Provider.external = External;
  if (External) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  std::vector<Instruction> Code{
      op(0, Range ? "invoke-static/range" : "invoke-static", Words, {},
         Provider.methods[0].reference)};
  if (Return == "V")
    Code.push_back(op(1, "return-void"));
  else {
    Code.push_back(op(1,
                      width(Return) == 2          ? "move-result-wide"
                      : Result == "return-object" ? "move-result-object"
                                                  : "move-result",
                      {0}));
    Code.push_back(op(2, Result, {0}));
  }
  auto Call = method("call", Parameters, Return, Registers, Code);
  return {klass("Lfixture/Client;", {Call}), Provider};
}

TEST(MobileDalvikJava, UnusedFormalsKeepEveryPlainRuntimeSlot) {
  std::vector<std::pair<std::vector<std::string>, std::string>> Cases;
  for (const std::string Type :
       {"I", "J", "F", "D", "B", "S", "C", "Z", "Ljava/lang/Object;",
        "Ljava/lang/String;", "[I", "[[D", "[Ljava/lang/Object;"})
    Cases.push_back({{Type}, Type});
  Cases.push_back({{}, "I"});
  Cases.push_back({{}, "V"});
  Cases.push_back({{"I", "D", "[I"}, "J"});
  Cases.push_back({{"[I", "J"}, "V"});
  for (const auto &[Parameters, Return] : Cases)
    for (bool External : {false, true})
      for (bool Generic : {false, true})
        for (bool Range : {false, true})
          for (bool Alias : {false, true}) {
            if (External && Alias)
              continue;
            SCOPED_TRACE(::testing::PrintToString(std::tuple{
                Parameters, Return, External, Generic, Range, Alias}));
            auto Input = unusedPlainFormalInvocationClasses(
                Parameters, Return, External, Generic, Range, Alias);
            // A second unused formal has no runtime binding either. Keep
            // both scopes distinct from the owner's same-spelled formal.
            Input[1].methods[0].generic_signature->insert(
                std::string("<T:Ljava/lang/Object;").size(),
                "U:Ljava/lang/Object;");
            const auto Ref = Input[1].methods[0].reference;
            const auto Signature = Input[1].methods[0].generic_signature;
            Budget B;
            auto Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plans.erased_unused_formal_invocations.contains(Ref));
            EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                      Signature);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                      Alias ? 1 : 0);
          }
}

TEST(MobileDalvikJava, UnusedPlainFormalsDoNotAdmitUsedOrBoundedVariables) {
  for (unsigned Mutation = 0; Mutation != 5; ++Mutation) {
    auto Input = unusedPlainFormalInvocationClasses({"[Ljava/lang/Object;"},
                                                    "[Ljava/lang/Object;", true,
                                                    true, true, false);
    auto &M = Input[1].methods[0];
    if (Mutation == 0)
      M.generic_signature = "<T:Ljava/lang/Object;>([TT;)[TT;";
    else if (Mutation == 1)
      M.generic_signature =
          "<T:Ljava/lang/Number;>([Ljava/lang/Object;)[Ljava/lang/Object;";
    else if (Mutation == 2)
      M.generic_signature = "<T:Ljava/lang/Object;U:Ljava/lang/Number;>([Ljava/"
                            "lang/Object;)[Ljava/lang/Object;";
    else if (Mutation == 3)
      M.access = {"private", "static"};
    else
      M.access.insert("bridge");
    Budget B;
    auto Classes = linkClasses(Input, B);
    const auto Plans = validateGenericSignatures(Classes, B);
    EXPECT_FALSE(Plans.erased_unused_formal_invocations.contains(M.reference));
  }
}

