std::vector<Class> unseededNominalCarrierClasses(bool External, bool Range,
                                                 bool Nested) {
  auto Input = unseededScalarCarrierClasses("Z", External, Range, true, false);
  auto Result = klass("Lfixture/Result;");
  Result.external = true;
  auto &Find = Input[1].methods[0];
  Find.reference.returns = Result.name;
  Find.generic_signature = "<T:Ljava/lang/Object;>(Lfixture/Carrier<TT;>;Ljava/"
                           "lang/Object;)Lfixture/Result;";
  if (!External)
    Find.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
  if (Nested) {
    auto Pair = klass("Lfixture/Pair;");
    Pair.external = true;
    Pair.generic_signature =
        "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
    Find.reference.parameters = {Pair.name};
    Find.generic_signature = "<T:Ljava/lang/Object;>(Lfixture/Pair<+Lfixture/"
                             "Carrier<TT;>;+TT;>;)Lfixture/Result;";
    Input.push_back(Pair);
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Find.reference.parameters;
  Call.reference.returns = Result.name;
  Call.instructions[0].registers =
      Nested ? std::vector<unsigned>{3} : std::vector<unsigned>{2, 3};
  std::get<MethodRef>(Call.instructions[0].reference) = Find.reference;
  Call.instructions[1].opcode = "move-result-object";
  Call.instructions[2].opcode = "return-object";
  Input.push_back(Result);
  return Input;
}

