std::vector<Class> anchoredVoidCarrierClasses(bool External, bool Range,
                                              bool AnchorFirst) {
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Text = klass("Lfixture/Text;");
  auto Flag = klass("Lfixture/Flag;");
  const std::vector<std::string> Params =
      AnchorFirst ? std::vector<std::string>{Carrier.name, Callback.name,
                                             Callback.name, "I"}
                  : std::vector<std::string>{Callback.name, Callback.name, "I",
                                             Carrier.name};
  const std::string Anchor = "Lfixture/Carrier<TT;>;";
  const std::string Other =
      "Lfixture/Callback<-TT;Lfixture/Flag;>;"
      "Lfixture/Callback<-Lfixture/Text;Lfixture/Flag;>;I";
  auto Send = method("send", Params, "V", 4, {op(0, "return-void")});
  Send.generic_signature = "<T:Ljava/lang/Object;>(" +
                           (AnchorFirst ? Anchor + Other : Other + Anchor) +
                           ")V";
  auto Provider = klass("Lfixture/Provider;", {Send});
  Provider.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  if (External) {
    Provider.external = true;
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Call = method("call", Params, "V", 4,
                     {op(0, Range ? "invoke-static/range" : "invoke-static",
                         {0, 1, 2, 3}, {}, Provider.methods[0].reference),
                      op(1, "return-void")});
  auto Core = klass("Lfixture/Core;", {Call});
  return {Core, Provider, Carrier, Callback, Text, Flag};
}

std::vector<Class> privateAnchoredNominalClasses(bool ExternalInputs,
                                                 bool Range) {
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Flag = klass("Lfixture/Flag;");
  auto Result = klass("Lfixture/Result;");
  Result.access = {"public", "interface", "abstract"};
  const std::string Owner = "Lfixture/Provider;";
  auto Read = method("dispatch",
                     {Result.name, Carrier.name, Callback.name, "Z", "F", "J"},
                     Result.name, 8, {op(0, "return-object", {1})});
  Read.reference.owner = Owner;
  Read.access = {"private", "final"};
  Read.generic_signature =
      "<T:Ljava/lang/Object;>(Lfixture/Result;Lfixture/Carrier<TT;>;"
      "Lfixture/Callback<-TT;+Lfixture/Flag;>;ZFJ)Lfixture/Result;";
  auto Params = Read.reference.parameters;
  Params.insert(Params.begin(), Owner);
  auto Call =
      method("call", Params, Result.name, 8,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                 {0, 1, 2, 3, 4, 5, 6, 7}, {}, Read.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  auto Provider = klass(Owner, {Read, Call});
  for (auto *C : {&Carrier, &Callback, &Flag, &Result})
    C->external = ExternalInputs;
  return {Provider, Carrier, Callback, Flag, Result};
}

TEST(MobileDalvikJava, PrivateAnchoredNominalCallsRetainTheirExactScope) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true}) {
        auto Input = privateAnchoredNominalClasses(External, Range);
        const auto Ref = Input[0].methods[0].reference;
        const auto Signature = Input[0].methods[0].generic_signature;
        if (Reverse)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        EXPECT_EQ(R.getArray("generic_signature_projections"), nullptr);
        EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                  Signature);
        std::string Sources;
        for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
          Sources += source(R, I);
        EXPECT_NE(Sources.find(".dispatch("), std::string::npos);
      }
}

TEST(MobileDalvikJava, PrivateAnchoredNominalCallsRejectLostBindings) {
  for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
    auto Input = privateAnchoredNominalClasses(false, true);
    auto &Provider = Input[0];
    auto &Read = Provider.methods[0];
    if (Mutation == 0) {
      auto Call = Provider.methods[1];
      Provider.methods.pop_back();
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 1) {
      auto Alias = klass("Lfixture/Alias;");
      Alias.superclass = Provider.name;
      auto &Call = Provider.methods[1];
      auto Target = Read.reference;
      Target.owner = Alias.name;
      Call.reference.parameters[0] = Alias.name;
      Call.instructions[0].reference = Target;
      Input.push_back(Alias);
    } else if (Mutation == 2)
      Provider.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 3)
      Read.generic_signature =
          "<T:Ljava/lang/Object;>(Lfixture/Result;Lfixture/Carrier<+TT;>;"
          "Lfixture/Callback<-TT;+Lfixture/Flag;>;ZFJ)Lfixture/Result;";
    else if (Mutation == 4)
      Read.access = {"public", "final"};
    else if (Mutation == 5)
      Input[1].generic_signature = "<E:Lfixture/Flag;>Ljava/lang/Object;";
    else if (Mutation == 6)
      Input.back().generic_signature =
          "<R:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 7)
      Read.access.insert("varargs");
    else if (Mutation == 8)
      Read.declared_throws = {"Ljava/lang/Exception;"};
    else {
      auto Call = Provider.methods[1];
      Provider.external = true;
      for (auto &M : Provider.methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error)
        << Mutation;
  }
}

std::vector<Class> anchoredArrayVoidClasses(unsigned Mode, bool Range,
                                            bool ArrayFirst,
                                            unsigned Dimensions,
                                            bool Interface) {
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.external = Mode == 4;
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Interface)
    Carrier.access = {"public", "abstract", "interface"};
  const std::string Array(Dimensions, '[');
  std::vector<std::string> Params{Carrier.name, Array + "Ljava/lang/Object;"};
  if (ArrayFirst)
    std::reverse(Params.begin(), Params.end());
  const bool Instance = Mode == 2;
  auto Apply =
      method("apply", Params, "V", Instance ? 3 : 2, {op(0, "return-void")});
  Apply.access = Mode == 1 || Instance ? Access{"private"}
                 : Mode == 3           ? Access{}
                                       : Access{"public"};
  if (!Instance)
    Apply.access.insert("static");
  Apply.generic_signature =
      "<T:Ljava/lang/Object;>(" +
      (ArrayFirst ? Array + "TT;Lfixture/Carrier<TT;>;"
                  : "Lfixture/Carrier<TT;>;" + Array + "TT;") +
      ")V";
  auto Owner = klass("Lfixture/Owner;", {Apply});
  Owner.external = Mode == 4;
  if (Owner.external)
    Owner.methods[0].instructions.clear();
  const auto Ref = Owner.methods[0].reference;
  if (Instance)
    Params.insert(Params.begin(), Owner.name);
  auto Call =
      method("call", Params, "V", Instance ? 3 : 2,
             {op(0,
                 Instance ? (Range ? "invoke-direct/range" : "invoke-direct")
                          : (Range ? "invoke-static/range" : "invoke-static"),
                 Instance ? std::vector<unsigned>{0, 1, 2}
                          : std::vector<unsigned>{0, 1},
                 {}, Ref),
              op(1, "return-void")});
  Call.access = {"public", "static"};
  if (Mode == 1 || Instance) {
    Call.reference.owner = Owner.name;
    Owner.methods.push_back(std::move(Call));
    return {Owner, Carrier};
  }
  return {Owner, Carrier, klass("Lfixture/Core;", {Call})};
}

TEST(MobileDalvikJava, AnchoredArrayVoidCallsKeepScopedElementsAndAccess) {
  for (unsigned Mode = 0; Mode < 5; ++Mode)
    for (bool Range : {false, true})
      for (bool ArrayFirst : {false, true})
        for (unsigned Dimensions : {1u, 2u})
          for (bool Interface : {false, true})
            for (bool Reverse : {false, true}) {
              auto Input = anchoredArrayVoidClasses(Mode, Range, ArrayFirst,
                                                    Dimensions, Interface);
              const auto Ref = Input[0].methods[0].reference;
              const auto Signature = Input[0].methods[0].generic_signature;
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(Plans.erased_generic_invocations.contains(Ref));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                        Signature);
            }
}

TEST(MobileDalvikJava, AnchoredArrayVoidCallsRejectUnprovedRelationsAndScope) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = anchoredArrayVoidClasses(1, false, false, 1, false);
    auto &Owner = Input[0];
    auto &Apply = Owner.methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      auto &S = *Apply.generic_signature;
      const auto At = S.find(From);
      ASSERT_NE(At, std::string::npos);
      S.replace(At, From.size(), To);
    };
    if (Mutation == 0)
      replace("Carrier<TT;>", "Carrier<+TT;>");
    else if (Mutation == 1)
      replace("Carrier<TT;>", "Carrier<-TT;>");
    else if (Mutation == 2)
      replace("[TT;", "[TU;");
    else if (Mutation == 3)
      replace("T:Ljava/lang/Object;", "T:Ljava/lang/CharSequence;");
    else if (Mutation == 4)
      Input[1].generic_signature =
          "<E:Ljava/lang/CharSequence;>Ljava/lang/Object;";
    else if (Mutation == 5)
      Input[1].access.erase("public");
    else if (Mutation == 6)
      Input.pop_back();
    else if (Mutation == 7)
      Apply.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 8)
      Apply.access.insert("bridge");
    else if (Mutation == 9) {
      auto Call = Owner.methods.back();
      Owner.methods.pop_back();
      Input.push_back(klass("Lfixture/Foreign;", {Call}));
    } else if (Mutation == 10) {
      Owner.generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
    } else if (Mutation == 11)
      Owner.methods.back().instructions[0].opcode = "invoke-virtual";
    else if (Mutation == 12)
      replace("[TT;", "TT;");
    else if (Mutation == 13) {
      replace("[TT;", "[Ljava/lang/String;");
      replace(")V", ")TT;");
      Apply.reference.returns = "Ljava/lang/Object;";
    } else if (Mutation == 14) {
      auto Child = klass("Lfixture/Child;");
      Child.superclass = Owner.name;
      auto &Call = Owner.methods.back();
      std::get<MethodRef>(Call.instructions[0].reference).owner = Child.name;
      Input.push_back(std::move(Child));
    } else {
      Owner.external = true;
      Apply.instructions.clear();
      auto Call = Owner.methods.back();
      Owner.methods.pop_back();
      Input.push_back(klass("Lfixture/Core;", {Call}));
    }
    Budget B;
    EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
  }
}

