std::vector<Class> anchoredScalarCarrierClasses(const std::string &Type,
                                                bool External, bool Range,
                                                bool AnchorFirst) {
  auto Input = anchoredVoidCarrierClasses(External, Range, AnchorFirst);
  auto &Send = Input[1].methods[0];
  Send.reference.returns = Type;
  Send.generic_signature->back() = Type[0];
  const bool Wide = Type == "J" || Type == "D";
  if (!External) {
    Send.instructions = {
        op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
        op(1, Wide ? "return-wide" : "return", {0})};
    Send.code_end = 2;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.returns = Type;
  std::get<MethodRef>(Call.instructions[0].reference) = Send.reference;
  Call.instructions.resize(1);
  Call.instructions.push_back(
      op(1, Wide ? "move-result-wide" : "move-result", {0}));
  Call.instructions.push_back(op(2, Wide ? "return-wide" : "return", {0}));
  Call.code_end = 3;
  return Input;
}

