std::vector<Class> packageSeededNominalClasses(bool ExternalInputs, bool Range,
                                               bool PublicOwner,
                                               unsigned ResultUse = 0) {
  auto Input = seededNominalCarrierClasses(false, Range);
  auto &Owner = Input[1];
  Owner.access = PublicOwner ? Access{"public"} : Access{};
  auto &Find = Owner.methods[0];
  Find.access = {"static"};
  Find.reference.parameters.back() = "Lfixture/Context;";
  Find.generic_signature =
      "<T:Ljava/lang/Object;>(TT;Lfixture/Carrier<TT;Lfixture/Closed;>;"
      "Lfixture/Context;)Lfixture/Result;";
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Find.reference.parameters;
  Call.instructions[0].reference = Find.reference;
  if (ResultUse == 1)
    Call.reference.returns = "Ljava/lang/Object;";
  else if (ResultUse == 2) {
    Call.reference.returns = "V";
    Call.instructions = {Call.instructions[0], op(1, "return-void")};
    Call.code_end = 2;
  }
  for (size_t I : {2u, 3u, 4u})
    Input[I].external = ExternalInputs;
  auto Context = klass("Lfixture/Context;");
  Context.external = ExternalInputs;
  Input.push_back(Context);
  return Input;
}

