std::vector<Class> starredHeadNominalClasses(bool External, bool Range,
                                             bool Package, bool Converter) {
  auto Input = pairedConverterNominalClasses(External, Range, Package);
  auto &Find = Input[1].methods[0];
  Find.reference.parameters.erase(Find.reference.parameters.begin());
  Find.generic_signature = "<U:Ljava/lang/Object;>(Lfixture/Carrier<*TU;>;"
                           "Lfixture/Converter<Lfixture/Closed;TU;>;Lfixture/"
                           "Context;)Lfixture/Result;";
  if (!Converter) {
    Find.reference.parameters.erase(Find.reference.parameters.begin() + 1);
    Find.generic_signature = "<U:Ljava/lang/Object;>(Lfixture/"
                             "Carrier<*TU;>;Lfixture/Context;)Lfixture/Result;";
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Find.reference.parameters;
  Call.registers = static_cast<unsigned>(Call.reference.parameters.size()) + 1;
  Call.instructions[0].reference = Find.reference;
  Call.instructions[0].registers =
      Converter ? std::vector<unsigned>{1, 2, 3} : std::vector<unsigned>{1, 2};
  return Input;
}

