std::vector<Class> packageSeededCarrierClasses(bool External, bool Range,
                                               bool Nested,
                                               unsigned ResultUse) {
  const std::string Root = "Lfixture/Core;", CarrierName = "Lfixture/Carrier;";
  const std::string OwnerName =
      Nested ? "Lfixture/Core$Factory;" : "Lfixture/Factory;";
  auto Make = method("make", {CarrierName, "Ljava/lang/Object;"}, CarrierName,
                     2, {op(0, "return-object", {0})});
  Make.access = {"static"};
  Make.generic_signature =
      "<T:Ljava/lang/Object;>(Lfixture/Carrier<TT;>;TT;)Lfixture/Carrier<TT;>;";
  auto Owner = klass(OwnerName, {Make});
  Owner.access.clear();
  if (Nested) {
    Owner.enclosing = Root;
    Owner.inner_class_present = true;
    Owner.inner_name = "Factory";
    Owner.inner_access = {"private", "static"};
  }
  auto Call =
      method("call", Make.reference.parameters, CarrierName, 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Owner.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  if (ResultUse == 1)
    Call.reference.returns = "Ljava/lang/Object;";
  else if (ResultUse == 2) {
    Call.reference.returns = "V";
    Call.instructions = {Call.instructions[0], op(1, "return-void")};
    Call.code_end = 2;
  }
  auto Core = klass(Root, {Call});
  auto Carrier = klass(CarrierName);
  Carrier.external = External;
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Core, Owner, Carrier};
}

