TEST(MobileDalvikJava, PrivateSeededCarrierInputsRejectForeignAndUnboundCalls) {
  for (unsigned Mutation = 0; Mutation < 13; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = privateSeededCarrierInputClasses(false, true, 0);
    auto &Find = Input[0].methods[0];
    auto replace = [&](std::string From, std::string To) {
      auto &Text = *Find.generic_signature;
      const auto At = Text.find(From);
      ASSERT_NE(At, std::string::npos);
      Text.replace(At, From.size(), To);
    };
    switch (Mutation) {
    case 0:
      replace(";TT;Z)", ";TMissing;Z)");
      break;
    case 1:
      replace("Carrier<TT;>;TT;", "Carrier<TMissing;>;TT;");
      break;
    case 2:
      replace(")Lfixture/Carrier<TT;>;", ")Lfixture/Carrier<TMissing;>;");
      break;
    case 3:
      replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
      break;
    case 4:
      Input[1].generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
      break;
    case 5:
      Input[1].generic_signature.reset();
      break;
    case 6:
      Input[1].generic_signature =
          "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 7:
      Input[1].name = "Lfixture/Missing;";
      break;
    case 8: {
      auto Other = klass("Lfixture/Other;", {Input[0].methods[1]});
      Input.push_back(Other);
      break;
    }
    case 9:
      Find.access.insert("native");
      Find.instructions.clear();
      Find.registers = Find.code_end = 0;
      break;
    case 10:
      Find.access.insert("varargs");
      break;
    case 11:
      Find.declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 12: {
      auto Other = klass("Lfixture/Other;", {Input[0].methods[1]});
      Input[0].external = true;
      for (auto &M : Input[0].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
      Input.push_back(Other);
      break;
    }
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> protectedArrayTransferClasses(bool SDK, bool Range,
                                                 bool Copy, bool Final,
                                                 bool Alpha, unsigned Route,
                                                 bool Inherited = false) {
  const std::string Array = "[Ljava/lang/Object;";
  auto Read = method("read", {Array}, Array, 3, {op(0, "return-object", {2})});
  Read.access = Final ? Access{"protected", "final"} : Access{"protected"};
  const std::string Formal = Alpha ? "Value" : "T";
  Read.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>([T" + Formal + ";)[T" + Formal + ";";
  auto Base = klass("Lfixture/Base;", {Read});
  Base.external = SDK;
  if (SDK) {
    Base.methods[0].instructions.clear();
    Base.methods[0].registers = Base.methods[0].code_end = 0;
  }
  auto Call =
      method("call", {Base.name, Array}, Array, 3,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2},
                 {}, Base.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  auto Core = klass(Route ? "Lforeign/Child;" : "Lfixture/Core;", {Call});
  if (Route) {
    Core.superclass = Base.name;
    if (Route == 1) {
      Core.methods[0].access = {"public"};
      Core.methods[0].reference.parameters = {Array};
    } else {
      Core.methods[0].reference.parameters[0] = Core.name;
      if (Route == 3) {
        Core.methods[0].access = {"public"};
        Core.methods[0].registers = 4;
        Core.methods[0].instructions[0].registers = {2, 3};
      }
    }
    if (Inherited)
      std::get<MethodRef>(Core.methods[0].instructions[0].reference).owner =
          Core.name;
  }
  if (Copy) {
    auto &M = Core.methods[0];
    const auto Invoke = M.instructions[0];
    M.registers += 2;
    M.instructions = {op(0, "move-object", {0, Invoke.registers[0] + 2}),
                      op(1, "move-object", {1, Invoke.registers[1] + 2}),
                      op(2, Range ? "invoke-virtual/range" : "invoke-virtual",
                         {0, 1}, {}, Invoke.reference),
                      op(3, "move-result-object", {0}),
                      op(4, "return-object", {0})};
    M.code_end = 5;
  }
  return {Core, Base};
}

TEST(MobileDalvikJava, ProtectedArrayTransfersKeepScopedComponentAndReceiver) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Copy : {false, true})
        for (bool Final : {false, true})
          for (bool Alpha : {false, true})
            for (bool Reverse : {false, true})
              for (unsigned Route = 0; Route < 4; ++Route)
                for (bool Inherited : {false, true}) {
                  if (!Route && Inherited)
                    continue;
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Range, Copy, Final, Alpha, Reverse, Route,
                                 Inherited}));
                  auto Input = protectedArrayTransferClasses(
                      SDK, Range, Copy, Final, Alpha, Route, Inherited);
                  const auto Ref = Input[1].methods[0].reference;
                  const auto Signature = Input[1].methods[0].generic_signature;
                  if (Reverse)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  const auto Classes = linkClasses(Input, B);
                  EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                  .erased_generic_invocations.contains(Ref));
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                            0);
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                  EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                            Signature);
                }
  auto Input =
      protectedArrayTransferClasses(false, false, false, false, false, 0);
  auto Other =
      method("read", {}, "[Ljava/lang/Object;", 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Other.reference.owner = Input[1].name;
  Other.access = {"protected"};
  Input[1].methods.push_back(Other);
  EXPECT_NO_THROW(recover(Input));
}

