std::vector<Class> protectedMarkerResultClasses(bool SDK, bool Range,
                                                bool Final, bool AbstractOwner,
                                                unsigned Context = 0) {
  const std::string MarkerName = "Lfixture/Marker;";
  auto Read =
      method("read", {}, MarkerName, SDK ? 0 : 2,
             SDK ? std::vector<Instruction>{}
                 : std::vector<Instruction>{op(0, "const/4", {0}, int64_t(0)),
                                            op(1, "return-object", {0})});
  Read.access = {"protected"};
  if (Final)
    Read.access.insert("final");
  Read.generic_signature = "<T::Lfixture/Marker;>()TT;";
  if (Context) {
    Read.reference.parameters =
        Context == 1
            ? std::vector<std::string>{"Ljava/lang/String;", "Lfixture/Base;"}
            : std::vector<std::string>{MarkerName};
    Read.generic_signature =
        Context == 1
            ? "<T::Lfixture/Marker;>(Ljava/lang/String;Lfixture/Base;)TT;"
            : "<T::Lfixture/Marker;>(Lfixture/Marker;)TT;";
    if (!SDK)
      Read.registers = 4;
  }
  auto Base = klass("Lfixture/Base;", {Read});
  Base.external = SDK;
  if (AbstractOwner)
    Base.access.insert("abstract");
  auto Marker = klass(MarkerName);
  Marker.access = {"public", "interface", "abstract"};
  Marker.external = SDK;
  auto Call =
      method("call", {Base.name}, MarkerName, 2,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1}, {},
                 Base.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  if (Context) {
    Call.reference.parameters =
        Context == 1 ? std::vector<std::string>{Base.name, "Ljava/lang/String;",
                                                Base.name}
                     : std::vector<std::string>{Base.name, MarkerName};
    Call.registers = 4;
    Call.instructions[0].registers = Context == 1
                                         ? std::vector<unsigned>{1, 2, 3}
                                         : std::vector<unsigned>{2, 3};
  }
  auto Core = klass("Lfixture/Core;", {Call});
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  return {Core, Base, Marker, String};
}

