std::vector<Class> privateSeededNominalClasses(bool Range) {
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Flag = klass("Lfixture/Flag;");
  Flag.access.insert("final");
  auto Result = klass("Lfixture/Result;");
  auto Find = method(
      "classify", {Carrier.name, Callback.name, "Ljava/lang/Object;", "I"},
      Result.name, 4,
      {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Find.access = {"private", "static", "final"};
  Find.generic_signature =
      "<T:Ljava/lang/Object;>(Lfixture/Carrier<TT;>;Lfixture/"
      "Callback<-TT;Lfixture/Flag;>;TT;I)Lfixture/Result;";
  auto Owner = klass("Lfixture/Owner;", {Find});
  auto Call =
      method("call", Find.reference.parameters, Result.name, 4,
             {op(0, Range ? "invoke-static/range" : "invoke-static",
                 {0, 1, 2, 3}, {}, Owner.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Call.reference.owner = Owner.name;
  Owner.methods.push_back(Call);
  return {Owner, Carrier, Callback, Flag, Result};
}

