TEST(MobileDalvikJava, PrivateAllocationCallsRejectUnprovedOwnersAndFrames) {
  for (const std::string Type : {"I", "J", "D", "Ljava/lang/Object;"})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
        SCOPED_TRACE(Type);
        SCOPED_TRACE(Mutation);
        auto Input =
            privateAllocationCallClasses(Type, true, true, true, false, true);
        auto &Core = Input[0];
        auto &M = Core.methods[0];
        auto &Call = M.instructions[1];
        if (Mutation == 0)
          Call.opcode = "invoke-virtual/range";
        else if (Mutation == 1)
          Core.methods[1].access = {"public"};
        else if (Mutation == 2)
          Core.methods[1].access = {"private", "static"};
        else if (Mutation == 3)
          Call.opcode = "invoke-static/range";
        else if (Mutation == 4)
          Call.registers[0] = 0;
        else if (Mutation == 5)
          Call.registers[2] = 11;
        else if (Mutation == 6)
          Call.registers.pop_back();
        else if (Mutation == 7)
          Call.registers.push_back(11);
        else if (Mutation == 8)
          M.instructions[2].registers = {M.registers};
        else if (Mutation == 9)
          M.instructions[2].opcode = "nop";
        else if (Mutation == 10)
          M.instructions[9].registers = {0};
        else if (Mutation == 11) {
          auto Foreign = Core.methods[0];
          Core.methods.erase(Core.methods.begin());
          Input.push_back(klass("Lother/Client;", {Foreign}));
        } else if (Mutation == 12) {
          auto Child = klass("Lfixture/Child;");
          Child.superclass = Core.name;
          std::get<MethodRef>(Call.reference).owner = Child.name;
          Input.push_back(Child);
        } else
          Core.methods[1].access.insert("bridge");
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> protectedFinalStageClasses(bool External, bool Diamond,
                                              bool LaterField) {
  const std::string Owner = "Lfixture/Core;";
  const FieldRef First{Owner, "first", "I"}, Choice{Owner, "choice", "I"},
      Last{Owner, "last", "I"};
  auto Go = method("go", {}, "V", 0, {op(0, "return-void")});
  auto Recover = method("recover", {"Ljava/lang/Throwable;"}, "V", 1,
                        {op(0, "return-void")});
  auto Stage = klass("Lfixture/Stage;", {Go, Recover});
  Stage.external = External;
  if (External)
    for (auto &M : Stage.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto Init =
      method("<init>", {"I"}, "V", 4,
             {op(0, "invoke-direct", {2}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "const/4", {0}, int64_t(1)),
              op(2, "iput", {0, 2}, {}, First),
              Diamond ? op(3, "if-eqz", {3}, {}, {}, 7) : op(3, "nop"),
              op(4, "const/4", {0}, int64_t(2)),
              op(5, "iput", {0, 2}, {}, Choice),
              op(6, "goto", {}, {}, {}, 10),
              op(7, "const/4", {0}, int64_t(3)),
              Diamond ? op(8, "iput", {0, 2}, {}, Choice) : op(8, "nop"),
              op(9, "goto", {}, {}, {}, 10),
              op(10, "invoke-static", {}, {}, Stage.methods[0].reference),
              op(11, "goto", {}, {}, {}, 15),
              op(12, "move-exception", {0}),
              op(13, "invoke-static", {0}, {}, Stage.methods[1].reference),
              op(14, "goto", {}, {}, {}, 15),
              op(15, "const/4", {0}, int64_t(9)),
              LaterField ? op(16, "iput", {0, 2}, {}, Last) : op(16, "nop"),
              op(17, "return-void"),
              op(18, "move-exception", {0}),
              op(19, "throw", {0})},
             {{10, 11, {{"Ljava/lang/Exception;", 12}, {std::nullopt, 18}}},
              {13, 14, {{std::nullopt, 18}}}});
  Init.access = {"public", "constructor"};
  auto Core = klass(Owner, {Init});
  Core.fields = {{First, {"public", "final"}, {}},
                 {Choice, {"public", "final"}, {}}};
  if (LaterField)
    Core.fields.push_back({Last, {"public", "final"}, {}});
  if (!Diamond) {
    // Keep physical and ordinary reachability exact when this field has one
    // store. The single-stage route must not depend on a structured prefix.
    auto &Code = Core.methods[0].instructions;
    Code[6] = op(6, "nop");
    Code[9] = op(9, "nop");
  }
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.external = true;
  Exception.superclass = Throwable.name;
  return {Core, Stage, Throwable, Exception};
}

