TEST(MobileDalvikJava, ProtectedFinalStagesRejectCrossedWritesAndEntries) {
  for (bool Link : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(Mutation);
      auto Input = protectedFinalStageClasses(false, true, true);
      auto &M = Input[0].methods[0];
      if (Mutation == 0)
        M.tries[0].start = 5;
      else if (Mutation == 1)
        M.tries[0].end = 17;
      else if (Mutation == 2)
        M.tries[0].handlers[0].target = 7;
      else if (Mutation == 3)
        M.tries[0].handlers[1].target = 3;
      else if (Mutation == 4)
        M.instructions[14].target = 3;
      else if (Mutation == 5)
        M.instructions[11].target = 17;
      else if (Mutation == 6)
        M.instructions[8] = op(8, "nop");
      else if (Mutation == 7)
        M.instructions[6].target = 17;
      else if (Mutation == 8)
        M.instructions[14].target = 17;
      else
        M.instructions[19] = op(19, "return-void");
      Budget B;
      if (Mutation == 0) {
        // The now-protected alternative stores share one verified next field
        // event. Their exact-this assignments cannot throw; real producers
        // retain the original handlers and every later final still occurs.
        const auto R =
            Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
      } else
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
    }
}

std::vector<Class> protectedFinalSuffixClasses(bool Static, bool External,
                                               bool SplitCoverage) {
  const std::string Owner = "Lfixture/Core;";
  const FieldRef First{Owner, "first", "Ljava/lang/Object;"},
      Stamp{Owner, "stamp", "J"}, Complete{Owner, "complete", "Z"};
  auto Prepare =
      method("prepare", {}, "Ljava/lang/Object;", 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  auto Wide = method(
      "stamp", {}, "J", 2,
      {op(0, "const-wide/16", {0}, int64_t(0)), op(1, "return-wide", {0})});
  auto Recover = method("recover", {"Ljava/lang/Throwable;"}, "V", 1,
                        {op(0, "return-void")});
  auto After = method("after", {}, "V", 0, {op(0, "return-void")});
  auto Stage = klass("Lfixture/Stage;", {Prepare, Wide, Recover, After});
  Stage.external = External;
  if (External)
    for (auto &M : Stage.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const std::string Store = Static ? "sput" : "iput";
  auto regs = [&](unsigned Value) {
    return Static ? std::vector<unsigned>{Value}
                  : std::vector<unsigned>{Value, 5};
  };
  auto Init =
      method(Static ? "<clinit>" : "<init>", {}, "V", 6,
             {Static ? op(0, "nop")
                     : op(0, "invoke-direct", {5}, {},
                          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "const/4", {0}, int64_t(0)),
              op(2, "const-wide/16", {1}, int64_t(0)),
              op(3, "const/4", {3}, int64_t(0)),
              op(4, "invoke-static", {}, {}, Stage.methods[0].reference),
              op(5, "move-result-object", {0}),
              op(6, "invoke-static", {}, {}, Stage.methods[1].reference),
              op(7, "move-result-wide", {1}),
              op(8, "const/4", {3}, int64_t(1)),
              op(9, "goto", {}, {}, {}, 14),
              op(10, "move-exception", {4}),
              op(11, "invoke-static", {4}, {}, Stage.methods[2].reference),
              op(12, "goto", {}, {}, {}, 14),
              op(13, "nop"),
              op(14, "if-eqz", {3}, {}, {}, 19),
              op(15, Store + "-object", regs(0), {}, First),
              op(16, Store + "-wide", regs(1), {}, Stamp),
              op(17, Store + "-boolean", regs(3), {}, Complete),
              op(18, "goto", {}, {}, {}, 23),
              op(19, "const/4", {0}, int64_t(0)),
              op(20, Store + "-object", regs(0), {}, First),
              op(21, Store + "-wide", regs(1), {}, Stamp),
              op(22, Store + "-boolean", regs(3), {}, Complete),
              op(23, "invoke-static", {}, {}, Stage.methods[3].reference),
              op(24, "return-void")});
  Init.access = Static ? Access{"static", "constructor"}
                       : Access{"public", "constructor"};
  Init.code_end = 25;
  Init.tries = {{4, 8, {{"Ljava/lang/Exception;", 10}}}};
  if (SplitCoverage)
    Init.tries = {{4, 6, {{"Ljava/lang/Exception;", 10}}},
                  {6, 8, {{"Ljava/lang/Exception;", 10}}}};
  auto Core = klass(Owner, {Init});
  Access Flags{"public", "final"};
  if (Static)
    Flags.insert("static");
  Core.fields = {{First, Flags, {}}, {Stamp, Flags, {}}, {Complete, Flags, {}}};
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.external = true;
  Exception.superclass = Throwable.name;
  return {Core, Stage, Throwable, Exception};
}

