TEST(MobileDalvikJava, LiteralSuperclassVoidBridgesRejectUnprovedContracts) {
  for (bool External : {false, true})
    for (bool Link : {false, true})
      for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
        SCOPED_TRACE(External);
        SCOPED_TRACE(Link);
        SCOPED_TRACE(Mutation);
        auto Input = literalSuperclassVoidBridgeClasses(External, 1, false,
                                                        false, false);
        auto &Root = Input[0], &Bounded = Input[1], &Middle = Input[4],
             &Core = Input.back();
        auto &Bridge = Core.methods[2], &Target = Core.methods[1];
        if (Mutation == 0)
          Root.methods[1].generic_signature =
              "(Lfixture/Wide;JDLjava/lang/Object;)V";
        else if (Mutation == 1)
          Root.methods[1].access.insert("final");
        else if (Mutation == 2)
          Middle.superclass = "Lfixture/Missing;";
        else if (Mutation == 3)
          Middle.superclass = Core.name;
        else if (Mutation == 4)
          Middle.generic_signature = "<Q:Ljava/lang/Object;>Lfixture/Bounded;";
        else if (Mutation == 5)
          Target.access.insert("static");
        else if (Mutation == 6)
          Target.access = {"private"};
        else if (Mutation == 7)
          Bridge.instructions[0].reference = std::string("Lfixture/Wide;");
        else if (Mutation == 8)
          Bridge.instructions[1].opcode = "invoke-super";
        else if (Mutation == 9)
          Bridge.instructions[1].registers[3] = 4;
        else if (Mutation == 10)
          std::get<MethodRef>(Bridge.instructions[1].reference).owner =
              Middle.name;
        else if (Mutation == 11)
          Bounded.methods[1].access.insert("final");
        else if (Mutation == 12)
          Bridge.instructions.insert(Bridge.instructions.begin() + 2,
                                     op(2, "nop"));
        else if (Mutation == 13) {
          auto Other = klass("Lfixture/Other;");
          Other.access = {"public", "abstract", "interface"};
          auto M = Root.methods[1];
          M.reference.owner = Other.name;
          M.generic_signature.reset();
          Other.methods.push_back(M);
          Middle.interfaces.push_back(Other.name);
          Input.insert(Input.begin(), std::move(Other));
        } else if (Mutation == 14)
          Bounded.generic_signature = "Lfixture/Root<Lfixture/Wide;>;";
        else
          Middle.methods.clear();
        Budget B;
        EXPECT_THROW(Link ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava, IndependentFinalIdentifiersKeepTheirOwnDeclaringScopes) {
  for (bool Synthetic : {false, true})
    for (bool Foreign : {false, true})
      for (bool Link : {false, true})
        for (bool Reverse : {false, true})
          for (unsigned Dependencies : {1u, 300u}) {
            SCOPED_TRACE(Synthetic);
            SCOPED_TRACE(Foreign);
            SCOPED_TRACE(Link);
            SCOPED_TRACE(Reverse);
            SCOPED_TRACE(Dependencies);
            auto Input = finalIdentifierClasses(false);
            auto &Terminal = Input.back();
            if (Synthetic)
              Terminal.methods[0].access.insert("synthetic");
            if (Foreign) {
              Input[0].name = "Lother/Client;";
              for (auto &M : Input[0].methods)
                M.reference.owner = Input[0].name;
            }
            const auto OriginalMethod = Terminal.methods[0];
            const auto Original = OriginalMethod.reference;
            for (unsigned I = 0; I < Dependencies; ++I) {
              auto M = OriginalMethod;
              M.access.erase("synthetic");
              M.instructions.clear();
              M.registers = M.code_end = 0;
              auto C =
                  klass("Ldependency/Alien" + std::to_string(I) + ";", {M});
              C.external = true;
              Input.push_back(std::move(C));
            }
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Link ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            unsigned Count = 0;
            for (const auto &V : *R.getArray("methods")) {
              const auto &Row = *V.getAsObject();
              if (Row.getString("identity") != Original.identity())
                continue;
              ++Count;
              EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod1");
              EXPECT_EQ(Row.getString("source_name_declaration"),
                        Original.identity());
              ASSERT_NE(Row.getArray("source_name_family"), nullptr);
              EXPECT_EQ(Row.getArray("source_name_family")->size(), 1U);
              EXPECT_EQ(Row.getArray("metadata_differences")->size(), 3U);
            }
            EXPECT_EQ(Count, 1U);
          }
}

