namespace {
std::vector<Class> loopPrefixDelegationClasses(bool Range) {
  const std::string Object = "Ljava/lang/Object;";
  auto Next = method("next", {Object}, "Z", 2,
                     {op(0, "const/4", {0}, int64_t(0)), op(1, "return", {0})});
  auto Step = method("step", {Object}, "V", 1, {op(0, "return-void")});
  auto Guard = klass("Lfixture/Guard;", {Next, Step});
  const FieldRef Value{"Lfixture/Core;", "value", Object};
  auto Primary = method(
      "<init>", {Object}, "V", 2,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "iput-object", {1, 0}, {}, Value), op(2, "return-void")});
  Primary.access = {"public", "constructor"};
  auto Loop =
      method("<init>", {Object, "Z"}, "V", 6,
             {op(0, "move-object", {0, 3}),
              op(1, "invoke-static", {4}, {}, Guard.methods[0].reference),
              op(2, "move-result", {2}), op(3, "if-eqz", {2}, {}, {}, 6),
              op(4, "invoke-static", {4}, {}, Guard.methods[1].reference),
              op(5, "goto", {}, {}, {}, 1), op(6, "move-object", {1, 4}),
              op(7, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
                 Primary.reference),
              op(8, "return-void")});
  Loop.access = Primary.access;
  auto Core = klass(Value.owner, {Primary, Loop});
  Core.fields = {{Value, {"public", "final"}, {}}};
  return {Core, Guard};
}
} // namespace

TEST(MobileDalvikJava, ConstructorLoopPrefixesKeepExactUninitializedOrigins) {
  for (bool Range : {false, true})
    for (bool Reverse : {false, true}) {
      auto Input = loopPrefixDelegationClasses(Range);
      const auto Caller = Input[0].methods[1].reference;
      const auto Target = Input[0].methods[0].reference;
      if (Reverse) {
        std::reverse(Input[0].methods.begin(), Input[0].methods.end());
        std::reverse(Input.begin(), Input.end());
      }
      Budget B;
      const auto Classes = linkClasses(Input, B);
      const auto Plans = planConstructorDelegations(Classes, B, {});
      ASSERT_TRUE(Plans.contains(Caller));
      EXPECT_EQ(Plans.at(Caller), Target);
      const auto Report = recoverJava(Classes, B);
      EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(Report.getInteger("minimum_java_release"), 25);
      std::string Text;
      for (size_t I = 0; I < Report.getArray("source_units")->size(); ++I)
        Text += source(Report, I);
      EXPECT_NE(Text.find("__neverdCtorPc"), std::string::npos);
      EXPECT_NE(Text.find("this(__neverdCtorArg0)"), std::string::npos);
    }
}

