namespace {
std::vector<Class> retainedAllocationCallClasses(bool Repeated) {
  const std::string Object = "Ljava/lang/Object;";
  auto Read =
      method("read", {"F"}, Object, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  auto Provider = klass("Lfixture/Provider;", {Read});
  auto Init = method(
      "<init>",
      Repeated ? std::vector<std::string>{Object, Object}
               : std::vector<std::string>{"F", "F", "F", "F"},
      "V", Repeated ? 3 : 5,
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Quad = klass("Lfixture/Quad;", {Init});
  const FieldRef Saved{"Lfixture/Core;", "saved", Object};
  auto Make = method(
      "make", {"F"}, Quad.name, 7,
      {op(0, "new-instance", {0}, {}, Quad.name),
       op(1, "invoke-static", {6}, {}, Provider.methods[0].reference),
       op(2, "move-result-object", {1}),
       op(3, "invoke-direct",
          Repeated ? std::vector<unsigned>{0, 1, 1}
                   : std::vector<unsigned>{0, 6, 6, 6, 6},
          {}, Quad.methods[0].reference),
       op(4, "sput-object", {1}, {}, Saved), op(5, "return-object", {0})});
  auto Core = klass(Saved.owner, {Make});
  Core.fields = {{Saved, {"public", "static"}, {}}};
  return {Core, Quad, Provider};
}
} // namespace

