namespace {
std::vector<Class> pairedArrayCarrierClasses(bool External, bool Facade,
                                             bool Range, bool Varargs) {
  auto Input = nestedPairConsumerClasses(External, Facade, Range);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {"[Lfixture/Box;"};
  Make.generic_signature = "<K:Ljava/lang/Object;V:Ljava/lang/Object;>"
                           "([Lfixture/Box<+TK;+TV;>;)Lfixture/Box<TK;TV;>;";
  if (Varargs)
    Make.access.insert("varargs");
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  std::get<MethodRef>(Call.instructions[0].reference).parameters =
      Make.reference.parameters;
  return Input;
}
std::vector<Class> pairedArrayVoidClasses(bool ExternalTarget,
                                          bool ExternalCarriers, bool Facade,
                                          bool Range, bool ArrayFirst,
                                          bool Standard, unsigned Variances) {
  auto Input = pairedArrayCarrierClasses(ExternalTarget, Facade, Range, false);
  Input[5].external = ExternalCarriers;
  const std::string Consumer =
      Standard ? "Ljava/util/Map;" : "Lfixture/Consumer;";
  auto Sink = klass(Consumer);
  Sink.access = {"public", "abstract", "interface"};
  Sink.generic_signature =
      "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
  Sink.external = ExternalCarriers;
  Input.push_back(Sink);
  auto &Apply = Input[1].methods[0];
  Apply.reference.name = "apply";
  Apply.reference.returns = "V";
  Apply.reference.parameters =
      ArrayFirst ? std::vector<std::string>{"[Lfixture/Box;", Consumer}
                 : std::vector<std::string>{Consumer, "[Lfixture/Box;"};
  const std::string C0 = (Variances & 1 ? "-" : "");
  const std::string C1 = (Variances & 2 ? "-" : "");
  const std::string P0 = (Variances & 4 ? "+" : "");
  const std::string P1 = (Variances & 8 ? "+" : "");
  const std::string To =
      Consumer.substr(0, Consumer.size() - 1) + "<" + C0 + "TA;" + C1 + "TB;>;";
  const std::string From = "[Lfixture/Box<" + P0 + "TA;" + P1 + "TB;>;";
  Apply.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;>(" +
                            (ArrayFirst ? From + To : To + From) + ")V";
  if (!ExternalTarget) {
    Apply.registers = 2;
    Apply.instructions = {op(0, "return-void")};
    Apply.code_end = 1;
  }
  auto Ref = Apply.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, "V", 2,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {0, 1}, {}, Ref),
                     op(1, "return-void")})});
  return Input;
}
std::vector<Class>
pairedEnvelopeTransferClasses(bool ExternalTarget, bool ExternalCarriers,
                              bool Facade, bool Range, bool ProducerFirst,
                              bool Returned, bool Wrapped, unsigned Variances) {
  auto Input =
      pairedArrayVoidClasses(ExternalTarget, ExternalCarriers, Facade, Range,
                             ProducerFirst, true, Variances & 15);
  auto &Apply = Input[1].methods[0];
  if (Returned) {
    auto &Signature = *Apply.generic_signature;
    for (const auto &Formal : {std::string("TA;"), std::string("TB;")}) {
      const auto At = Signature.find("-" + Formal);
      if (At != std::string::npos)
        Signature[At] = '+';
    }
    Apply.reference.returns = "Ljava/util/Map;";
    Signature.back() = 'L';
    Signature += "java/util/Map<TA;TB;>;";
    if (!ExternalTarget) {
      Apply.registers = 3;
      Apply.instructions = {op(0, "const/4", {0}, int64_t(0)),
                            op(1, "return-object", {0})};
      Apply.code_end = 2;
    }
  }
  if (Wrapped) {
    auto &Signature = *Apply.generic_signature;
    const auto At = Signature.find("[Lfixture/Box<");
    const auto End = Signature.find(">;", At) + 2;
    const auto Pair = Signature.substr(At + 1, End - At - 1);
    Signature.replace(At, End - At,
                      std::string("Ljava/lang/Iterable<") +
                          (Variances & 16 ? "+" : "") + Pair + ">;");
    Apply.reference.parameters[ProducerFirst ? 0 : 1] = "Ljava/lang/Iterable;";
    auto Envelope = klass("Ljava/lang/Iterable;");
    Envelope.access = {"public", "abstract", "interface"};
    Envelope.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    Envelope.external = ExternalCarriers;
    Input.push_back(Envelope);
  }
  auto Ref = Input[1].methods[0].reference;
  if (Facade)
    Ref.owner = Input[3].name;
  if (Returned)
    Input[0] =
        klass("Lfixture/Client;",
              {method("call", Ref.parameters, Ref.returns, 3,
                      {op(0, Range ? "invoke-static/range" : "invoke-static",
                          {1, 2}, {}, Ref),
                       op(1, "move-result-object", {0}),
                       op(2, "return-object", {0})})});
  else
    Input[0] =
        klass("Lfixture/Client;",
              {method("call", Ref.parameters, "V", 2,
                      {op(0, Range ? "invoke-static/range" : "invoke-static",
                          {0, 1}, {}, Ref),
                       op(1, "return-void")})});
  return Input;
}
} // namespace

TEST(MobileDalvikJava, PairedEnvelopesKeepCompleteReturnAndVoidRelations) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarriers : {false, true})
      for (bool Facade : {false, true})
        for (bool Range : {false, true})
          for (bool ProducerFirst : {false, true})
            for (bool Returned : {false, true})
              for (unsigned Variances = 0; Variances < 32; ++Variances)
                for (unsigned Route = 0; Route < 3; ++Route) {
                  auto Input = pairedEnvelopeTransferClasses(
                      ExternalTarget, ExternalCarriers, Facade, Range,
                      ProducerFirst, Returned, true, Variances);
                  const auto Ref = Input[1].methods[0].reference;
                  const auto Signature = Input[1].methods[0].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                  .erased_generic_invocations.contains(Ref));
                  EXPECT_EQ(recoverJava(Classes, B)
                                .getInteger("unrecovered_method_count"),
                            0);
                  EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                            Signature);
                }
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarriers : {false, true})
      for (unsigned Variances = 0; Variances < 16; ++Variances)
        for (unsigned Route = 0; Route < 3; ++Route) {
          auto Input = pairedEnvelopeTransferClasses(
              ExternalTarget, ExternalCarriers, false, true, false, true, false,
              Variances);
          const auto Ref = Input[1].methods[0].reference;
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          EXPECT_TRUE(validateGenericSignatures(Classes, B)
                          .erased_generic_invocations.contains(Ref));
          EXPECT_EQ(
              recoverJava(Classes, B).getInteger("unrecovered_method_count"),
              0);
        }
}

TEST(MobileDalvikJava, PairedEnvelopesRejectUnprovedWrappersSlotsAndResults) {
  for (bool ExternalTarget : {false, true})
    for (bool ExternalCarriers : {false, true})
      for (bool Returned : {false, true})
        for (unsigned Mutation = 0; Mutation < 25; ++Mutation)
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Returned, Mutation, Route}));
            auto Input = pairedEnvelopeTransferClasses(
                ExternalTarget, ExternalCarriers, false, true, false, Returned,
                true, 31);
            auto &Apply = Input[1].methods[0];
            auto replace = [&](const std::string &From, const std::string &To) {
              auto &Signature = *Apply.generic_signature;
              const auto At = Signature.find(From);
              ASSERT_NE(At, std::string::npos);
              Signature.replace(At, From.size(), To);
            };
            switch (Mutation) {
            case 0:
              replace("Iterable<+Lfixture/Box", "Iterable<-Lfixture/Box");
              break;
            case 1:
              replace("Box<+TA;+TB;>", "Box<-TA;+TB;>");
              break;
            case 2:
              replace(Returned ? "Map<+TA;+TB;>" : "Map<-TA;-TB;>",
                      Returned ? "Map<-TA;+TB;>" : "Map<+TA;-TB;>");
              break;
            case 3:
              replace("Box<+TA;+TB;>", "Box<+TA;+TA;>");
              break;
            case 4:
              replace(Returned ? "Map<+TA;+TB;>" : "Map<-TA;-TB;>",
                      Returned ? "Map<+TA;+TA;>" : "Map<-TA;-TA;>");
              break;
            case 5:
              replace(Returned ? "Map<+TA;+TB;>" : "Map<-TA;-TB;>",
                      Returned ? "Map<+TB;+TA;>" : "Map<-TB;-TA;>");
              break;
            case 6:
              replace("Iterable<+Lfixture/Box<+TA;+TB;>;>", "Iterable<*>");
              break;
            case 7:
              replace("Box<+TA;+TB;>", "Box<*+TB;>");
              break;
            case 8:
              replace("A:Ljava/lang/Object;", "A:Ljava/lang/Number;");
              break;
            case 9:
              replace("B:Ljava/lang/Object;>",
                      "B:Ljava/lang/Object;C:Ljava/lang/Object;>");
              break;
            case 10:
              replace("Box<+TA;+TB;>", "Box<+TA;+TU;>");
              break;
            case 11:
              Input.back().generic_signature =
                  "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/"
                  "Object;";
              break;
            case 12:
              Input.back().generic_signature =
                  "<E:Ljava/lang/Number;>Ljava/lang/Object;";
              break;
            case 13:
              Input[5].generic_signature =
                  "<E:Ljava/lang/Object;>Ljava/lang/Object;";
              break;
            case 14:
              Input[Input.size() - 2].generic_signature =
                  "<E:Ljava/lang/Object;>Ljava/lang/Object;";
              break;
            case 15:
              Input[5].generic_signature = "<E:Ljava/lang/Number;F:Ljava/lang/"
                                           "Object;>Ljava/lang/Object;";
              break;
            case 16:
              Input[Input.size() - 2].generic_signature =
                  "<E:Ljava/lang/Number;F:Ljava/lang/Object;>Ljava/lang/"
                  "Object;";
              break;
            case 17:
              Apply.access.insert("native");
              break;
            case 18:
              Apply.access.insert("varargs");
              break;
            case 19:
              Apply.access.insert("synthetic");
              break;
            case 20:
              Apply.access.insert("bridge");
              break;
            case 21:
              Apply.access.erase("static");
              break;
            case 22:
              Apply.declared_throws = {"Ljava/lang/Exception;"};
              break;
            case 23:
              Input[0].methods[0].instructions[0].registers.pop_back();
              break;
            case 24:
              if (Returned)
                replace(")Ljava/util/Map<TA;TB;>;", ")Ljava/util/Map<TB;TA;>;");
              else
                replace(")V", ")I");
              break;
            }
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            EXPECT_THROW(
                [&] {
                  if (Route)
                    recoverJava(linkClasses(Input, B), B);
                  else {
                    ClassMap Classes;
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                    recoverJava(Classes, B);
                  }
                }(),
                std::runtime_error);
          }
}

