namespace {
std::vector<Class> conditionalPackedClasses(const std::string &Relation,
                                            const std::string &Operator,
                                            bool TwoAddress, bool References,
                                            bool External, bool Range) {
  const std::string Opcode = Operator + "-long" + (TwoAddress ? "/2addr" : "");
  auto Input = conditionalConversionClasses("J", "J", Opcode, External, Range);
  auto &M = Input[0].methods[0];
  M.reference.parameters =
      References
          ? std::vector<std::string>{"Ljava/lang/Object;", "Ljava/lang/Object;"}
          : std::vector<std::string>{"I", "I"};
  M.instructions[1] = op(1, "if-" + Relation, {8, 9}, {}, {}, 8);
  M.instructions[2] = op(2, "const-wide", {1}, int64_t(-0x123456789LL));
  const bool Shift =
      Operator == "shl" || Operator == "shr" || Operator == "ushr";
  M.instructions[3] = Shift ? op(3, "const/16", {3}, int64_t(-65))
                            : op(3, "const-wide", {3}, int64_t(0x7fffffff));
  M.instructions[4] = op(4, Opcode,
                         TwoAddress ? std::vector<unsigned>{1, 3}
                                    : std::vector<unsigned>{1, 1, 3});
  M.instructions[5] = op(5, "goto", {}, {}, {}, 9);
  M.instructions[6] = op(8, "const-wide", {1}, int64_t(0));
  M.instructions[7] =
      op(9, "invoke-direct", {0, 1, 2, 9}, {}, Input[1].methods[0].reference);
  // Keep the target's original nominal tail, independently of comparison type.
  if (!References) {
    Input[1].methods[0].reference.parameters[1] = "I";
    M.instructions[7].reference = Input[1].methods[0].reference;
  }
  M.instructions[8] = op(10, "return-object", {0});
  M.code_end = 11;
  return Input;
}
} // namespace

TEST(MobileDalvikJava, ConditionalPackedArgumentsShareRelationsAndLongTypes) {
  for (const std::string Relation : {"eq", "ne", "lt", "ge", "gt", "le"})
    for (const std::string Operator :
         {"and", "or", "xor", "shl", "shr", "ushr"})
      for (bool TwoAddress : {false, true})
        for (bool External : {false, true})
          for (bool References : {false, true}) {
            if (References && Relation != "eq" && Relation != "ne")
              continue;
            auto Input = conditionalPackedClasses(
                Relation, Operator, TwoAddress, References, External, true);
            Budget B;
            const auto R = recoverJava(linkClasses(Input, B), B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            EXPECT_NE(source(R).find("new fixture.Target(switch (0)"),
                      std::string::npos);
          }
}

