namespace {
std::vector<Class> multipleFinalExitClasses(bool Static, unsigned Exits) {
  const FieldRef A{"Lfixture/Core;", "first", "Ljava/lang/Object;"};
  const FieldRef B{A.owner, "second", A.type};
  auto M = method(
      "<init>",
      {A.type, "Ljava/lang/RuntimeException;", "Ljava/lang/RuntimeException;",
       "Ljava/lang/RuntimeException;"},
      "V", 5,
      {op(0, "invoke-direct", {0}, {},
          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
       op(1, "iput-object", {1, 0}, {}, A), op(2, "if-nez", {2}, {}, {}, 8),
       op(3, "iput-object", {1, 0}, {}, B), op(4, "if-nez", {3}, {}, {}, 10),
       op(5, "if-nez", {4}, {}, {}, 12), op(6, "return-void"), op(8, "nop"),
       op(9, "throw", {2}), op(10, "nop"), op(11, "throw", {3}), op(12, "nop"),
       op(13, "throw", {4})});
  M.access = {"public", "constructor"};
  if (Exits == 2) {
    M.instructions[5] = op(5, "nop");
    M.instructions.resize(11);
    M.code_end = 12;
  }
  if (Static) {
    M.reference.name = "<clinit>";
    M.reference.parameters.clear();
    M.access = {"static", "constructor"};
    M.instructions[0] = op(0, "nop");
    for (auto &Op : M.instructions) {
      Op.pc += 4;
      if (Op.target)
        *Op.target += 4;
      if (Op.opcode == "iput-object") {
        Op.opcode = "sput-object";
        Op.registers.pop_back();
      }
    }
    for (unsigned Reg = 1; Reg <= 4; ++Reg)
      M.instructions.insert(M.instructions.begin() + Reg - 1,
                            op(Reg - 1, "const/4", {Reg}, int64_t(0)));
    M.code_end += 4;
  }
  auto C = klass(A.owner, {M});
  Access Flags{"public", "final"};
  if (Static)
    Flags.insert("static");
  C.fields = {{A, Flags, {}}, {B, Flags, {}}};
  return {C};
}
} // namespace

