TEST(MobileDalvikJava,
     ConstructorPrivateGettersRejectUninitializedAndForeignCalls) {
  for (bool Guarded : {false, true})
    for (unsigned Mutation = 0; Mutation < 10; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Guarded, Mutation}));
      auto Input = constructorPrivateGetterClasses("I", Guarded, false, false);
      auto &Core = Input[0];
      auto &M = Core.methods[1];
      const auto Call =
          std::find_if(M.instructions.begin(), M.instructions.end(),
                       [](const Instruction &Op) {
                         const auto *Ref =
                             std::get_if<MethodRef>(&Op.reference);
                         return Ref && Ref->name == "read";
                       });
      ASSERT_NE(Call, M.instructions.end());
      if (Mutation == 0)
        Call->registers = {0};
      else if (Mutation == 1)
        Call->registers.clear();
      else if (Mutation == 2)
        Call->registers.push_back(1);
      else if (Mutation == 3)
        Call->opcode = "invoke-static";
      else if (Mutation == 4)
        Core.methods.back().declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 5)
        (Call + 1)->opcode = "move-result-object";
      else if (Mutation == 6) {
        for (auto &Op : M.instructions)
          if (Op.opcode == "sget-object")
            Op = op(Op.pc, "const/4", {1}, int64_t(3));
      } else if (Mutation == 7)
        Core.methods.pop_back();
      else if (Mutation == 8) {
        auto Foreign = Core.methods.back();
        Foreign.reference.owner = "Lfixture/Peer;";
        auto Peer = klass(Foreign.reference.owner, {Foreign});
        Call->reference = Foreign.reference;
        Input[1].fields[0].reference.type = Peer.name;
        for (auto &Op : M.instructions)
          if (std::holds_alternative<FieldRef>(Op.reference))
            Op.reference = Input[1].fields[0].reference;
        Input.push_back(std::move(Peer));
      } else
        Call->target = (Call + 1)->pc;
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

