namespace {
std::vector<Class> retainedIntegerAllocationClasses(bool Synthetic, bool Repeat,
                                                    bool Range, bool ApiSdk) {
  auto Input = plainIntegerBridgeClasses(true, Synthetic);
  Input[0].external = ApiSdk;
  const auto Counter = Input[1].name;
  const auto Bridge = Input[1].methods[0].reference;
  if (Range)
    Input[1].methods[0].instructions[0].opcode = "invoke-virtual/range";
  auto InnerCtor =
      method("<init>",
             Repeat ? std::vector<std::string>{"I", "I"}
                    : std::vector<std::string>{"I"},
             "V", Repeat ? 3 : 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  InnerCtor.access = {"public", "constructor"};
  auto Inner = klass("Lfixture/Inner;", {InnerCtor});
  auto OuterCtor =
      method("<init>", {Inner.name}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  OuterCtor.access = {"public", "constructor"};
  auto Outer = klass("Lfixture/Outer;", {OuterCtor});
  std::vector<Instruction> Code{
      op(0, "new-instance", {0}, {}, Outer.name),
      op(1, "new-instance", {1}, {}, Inner.name),
      op(2, Range ? "invoke-virtual/range" : "invoke-virtual", {4}, {}, Bridge),
      op(3, "move-result", {2})};
  if (Repeat) {
    Code.push_back(op(4, Range ? "invoke-virtual/range" : "invoke-virtual", {4},
                      {}, Bridge));
    Code.push_back(op(5, "move-result", {3}));
  }
  Code.push_back(
      op(6, "invoke-direct",
         Repeat ? std::vector<unsigned>{1, 2, 3} : std::vector<unsigned>{1, 2},
         {}, Inner.methods[0].reference));
  Code.push_back(
      op(7, "invoke-direct", {0, 1}, {}, Outer.methods[0].reference));
  Code.push_back(op(8, "return-object", {0}));
  auto Make = method("make", {Counter}, Outer.name, 5, Code);
  Input.push_back(klass("Lfixture/Core;", {Make}));
  Input.push_back(Inner);
  Input.push_back(Outer);
  return Input;
}
} // namespace

TEST(MobileDalvikJava, RetainedIntegerBridgeCallsKeepNestedAllocationOrder) {
  for (bool Synthetic : {false, true})
    for (bool Repeat : {false, true})
      for (bool Range : {false, true})
        for (bool ApiSdk : {false, true})
          for (bool Reverse : {false, true}) {
            auto Input = retainedIntegerAllocationClasses(Synthetic, Repeat,
                                                          Range, ApiSdk);
            const auto Bridge = Input[1].methods[0].reference;
            if (Reverse) {
              std::reverse(Input[1].methods.begin(), Input[1].methods.end());
              std::reverse(Input.begin(), Input.end());
            }
            Budget B;
            const auto Classes = linkClasses(Input, B);
            const auto Signatures = validateGenericSignatures(Classes, B);
            const auto Plans = planGenericInheritance(Classes, Signatures, B);
            ASSERT_TRUE(Plans.retained_plain_bridges.contains(Bridge));
            EXPECT_TRUE(
                Plans.retained_plain_bridges.at(Bridge).primitive_forwarding);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            std::string S;
            for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
              S += source(R, I);
            const auto Outer = S.find("new fixture.Outer(");
            const auto Inner = S.find("new fixture.Inner(", Outer);
            const auto Call = S.find(".size(", Inner);
            ASSERT_NE(Outer, std::string::npos);
            ASSERT_NE(Inner, std::string::npos);
            ASSERT_NE(Call, std::string::npos);
            EXPECT_LT(Outer, Inner);
            EXPECT_LT(Inner, Call);
            EXPECT_EQ(S.find(".size(", Call + 1) != std::string::npos, Repeat);
          }
}

