namespace {
std::vector<Class> privateSeededResultClasses(bool Static, bool Invariant,
                                              bool External, bool Range) {
  auto Consume =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Consume.access = {"public", "abstract"};
  Consume.generic_signature = "(TI;)TO;";
  auto Callback = klass("Lfixture/Callback;", {Consume});
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature =
      "<I:Ljava/lang/Object;O:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Get = method("get", {}, "Ljava/lang/Object;", 0, {});
  Get.access = {"public", "abstract"};
  Get.generic_signature = "()TF;";
  auto Factory = klass("Lfixture/Factory;", {Get});
  Factory.access = {"public", "abstract", "interface"};
  Factory.generic_signature = "<F:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = Factory.external = External;
  auto Read =
      method("read", {"Ljava/lang/Object;", Callback.name, Factory.name},
             "Ljava/lang/Object;", Static ? 4 : 5,
             {op(0, "invoke-interface", {Static ? 3u : 4u}, {},
                 Factory.methods[0].reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Read.access = {"private", "final"};
  if (Static)
    Read.access.insert("static");
  Read.generic_signature =
      std::string("<R:Ljava/lang/Object;S:Ljava/lang/Object;>(TS;") +
      "Lfixture/Callback<" + (Invariant ? "" : "-") +
      "TS;Lfixture/Token;>;Lfixture/Factory<" + (Invariant ? "" : "+") +
      "TR;>;)TR;";
  auto Owner = klass("Lfixture/Provider;", {Read});
  auto Call = method(
      "call", {Owner.name, "Ljava/lang/Object;", Callback.name, Factory.name},
      "Ljava/lang/Object;", 5,
      {op(0,
          std::string(Static ? "invoke-static" : "invoke-direct") +
              (Range ? "/range" : ""),
          Static ? std::vector<unsigned>{2, 3, 4}
                 : std::vector<unsigned>{1, 2, 3, 4},
          {}, Owner.methods[0].reference),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Owner.methods.push_back(Call);
  Owner.methods.back().reference.owner = Owner.name;
  return {Owner, Callback, Factory, klass("Lfixture/Token;")};
}
} // namespace

