std::vector<Class> constructorConstantAllocationClasses(bool Wide,
                                                        bool Parameter,
                                                        bool External,
                                                        bool Range) {
  auto Input = allocatingThisConstructorClasses(false, false);
  auto &Token = Input[1];
  auto &Init = Token.methods[0];
  Init.reference.parameters = {"Ljava/lang/Object;", "I", Wide ? "J" : "I"};
  Init.registers = Wide ? 5 : 4;
  Token.external = External;
  if (External) {
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
  }
  auto &Caller = Input[0].methods[1];
  Caller.registers = 8;
  const unsigned Destination = Parameter ? 7 : 4;
  Caller.instructions = {
      op(0, "new-instance", {Destination}, {}, Token.name),
      op(1, "const/4", {0}, int64_t(0)),
      op(2, "const/16", {1}, int64_t(3)),
      op(3, Wide ? "const-wide" : "const", {2},
         Wide ? int64_t(-9223372036854775807LL) : int64_t(-2147483647)),
      op(4, Range ? "invoke-direct/range" : "invoke-direct",
         Wide ? std::vector<unsigned>{Destination, 0, 1, 2, 3}
              : std::vector<unsigned>{Destination, 0, 1, 2},
         {}, Init.reference),
      op(5, "invoke-direct", {6, Destination}, {},
         Input[0].methods[0].reference),
      op(6, "return-void")};
  Caller.code_end = 7;
  return Input;
}
