TEST(MobileDalvikJava, ConstructorConstantAllocationsRejectChangedRegions) {
  for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = constructorConstantAllocationClasses(true, false, false, true);
    auto &Caller = Input[0].methods[1];
    auto &Ops = Caller.instructions;
    switch (Mutation) {
    case 0:
      Ops[1].opcode = "const/8";
      break;
    case 1:
      Ops[1].reference = std::string("Ljava/lang/Object;");
      break;
    case 2:
      Ops[1].registers = {4};
      break;
    case 3:
      Ops[3].registers = {3};
      break;
    case 4:
      Ops[1].registers = {6};
      break;
    case 5:
      Ops[1].opcode = "const-string";
      Ops[1].literal = std::string("owned");
      break;
    case 6:
      Ops[1].target = 4;
      break;
    case 7:
      std::get<MethodRef>(Ops[4].reference).owner = "Ljava/lang/Object;";
      break;
    case 8:
      Ops[4].registers[0] = 0;
      break;
    case 9:
      Ops[4].registers.back() = 4;
      break;
    case 10:
      Ops[2].opcode = "new-instance";
      Ops[2].reference = Input[1].name;
      Ops[2].literal = std::monostate{};
      break;
    case 11:
      Ops.erase(Ops.begin() + 2);
      break;
    case 12:
      Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 13:
      Ops[0].reference = std::string("[Ljava/lang/Object;");
      break;
    case 14:
      Ops[4].opcode = "invoke-static";
      break;
    case 15:
      Ops[2].element_width = 4;
      break;
    case 16:
      Ops[2].pc = 5;
      break;
    case 17:
      Ops[2].registers = {8};
      break;
    case 18:
      Ops[1].literal = int64_t(1);
      break;
    case 19:
      Ops[3].literal = std::monostate{};
      break;
    }
    if (Mutation == 5) {
      // The closed allocation now uses the ordinary operation verifier, which
      // preserves this valid string preparation as an original argument.
      const auto R = recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
    } else
      EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

