TEST(MobileDalvikJava, InheritedAllocationCallsRejectAccessAndLookupDrift) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = inheritedAllocationCallClasses("Ljava/lang/Object;", true,
                                                false, true, false);
    auto &Core = Input[0];
    auto &Read = Input[1].methods[1];
    auto &Code = Core.methods[0].instructions;
    switch (Mutation) {
    case 0: {
      Core.access = {"public"};
      auto Call = Core.methods[0];
      Call.access = {"public", "static"};
      Call.reference.parameters = {Core.name};
      Input.push_back(klass("Lother/Caller;", {Call}));
      break;
    }
    case 1: {
      auto &Middle = Input[3];
      Middle.name = "Lother/Middle;";
      Middle.methods[0].reference.owner = Middle.name;
      Core.superclass = Middle.name;
      std::get<MethodRef>(Core.methods[1].instructions[0].reference).owner =
          Middle.name;
      break;
    }
    case 2:
      Read.access = {"private", "final"};
      break;
    case 3:
      Read.access.insert("static");
      break;
    case 4:
      Input[1].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 5:
      Input[3].generic_signature = "<T:Ljava/lang/Object;>Lfixture/Base;";
      break;
    case 6:
      Input.pop_back();
      break;
    case 7:
      Input[3].superclass = Core.name;
      break;
    case 8:
      Code[2].opcode = "invoke-direct/range";
      break;
    case 9:
      Code[3].opcode = "move-result";
      break;
    case 10:
      Code[2].registers = {0};
      break;
    case 11:
      Read.reference.returns = "Ljava/lang/String;";
      break;
    case 12:
      std::get<MethodRef>(Code[2].reference).name = "missing";
      break;
    case 13:
      Read.access.insert("native");
      Read.instructions.clear();
      Read.registers = Read.code_end = 0;
      Read.generic_signature = "<T:Ljava/lang/Object;>()TT;";
      break;
    case 14:
      Read.access.insert("bridge");
      break;
    case 15:
      Input[3].access = {"public", "abstract", "interface"};
      break;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

namespace {
std::vector<Class> integerPrefixArrayLengthClasses(const std::string &Array,
                                                   unsigned Style, bool Keep,
                                                   bool External, bool Range) {
  auto Input = allocationArrayLengthClasses(Array, 0, false, false, External);
  auto &Init = Input[1].methods[0];
  Init.reference.parameters = {"I", "I"};
  if (!External)
    Init.registers = 3;
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {Array, "I"};
  Make.reference.returns = Keep ? "I" : Input[1].name;
  Make.registers = 6;
  std::vector<Instruction> Code{op(0, "new-instance", {0}, {}, Input[1].name)};
  if (Style == 0)
    Code.push_back(op(1, "add-int/lit8", {2, 5}, int64_t(17)));
  else if (Style == 1)
    Code.push_back(op(1, "sub-int", {2, 5, 5}));
  else if (Style == 2) {
    Code.push_back(op(1, "move", {2, 5}));
    Code.push_back(op(2, "mul-int/lit8", {2, 2}, int64_t(-7)));
  } else {
    Code.push_back(op(1, "const/16", {2}, int64_t(1)));
    Code.push_back(op(2, "add-int/2addr", {2, 5}));
  }
  Code.push_back(op(Code.size(), "array-length", {1, 4}));
  Code.push_back(op(Code.size(),
                    Range ? "invoke-direct/range" : "invoke-direct", {0, 2, 1},
                    {}, Init.reference));
  Code.push_back(
      op(Code.size(), Keep ? "return" : "return-object", {Keep ? 2u : 0u}));
  Make.instructions = std::move(Code);
  Make.code_end = Make.instructions.size();
  return Input;
}
} // namespace

