namespace {
std::vector<Class> constructorChoiceClasses(bool Protected, bool External,
                                            bool Range, bool Copy,
                                            bool IfNull) {
  const std::string Type = "Lfixture/Widget;";
  auto init = [&](bool Copy) {
    auto M = method("<init>",
                    Copy ? std::vector<std::string>{Type}
                         : std::vector<std::string>{},
                    "V", Copy ? 2 : 1,
                    {op(0, "invoke-direct", {0}, {},
                        MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                     op(1, "return-void")});
    M.access = {"public", "constructor"};
    return M;
  };
  auto Widget = klass(Type, {init(false), init(true)});
  Widget.external = External;
  if (External)
    for (auto &M : Widget.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const unsigned Input = Copy ? 1 : 3;
  auto Branch = op(2, IfNull ? "if-eqz" : "if-nez", {Input});
  Branch.target = 5;
  auto Jump = op(4, "goto");
  Jump.target = 6;
  auto Make = method(
      "make", {Type}, Type, 4,
      {Copy ? op(0, "move-object", {1, 3}) : op(0, "const/4", {0}, int64_t(0)),
       op(1, "new-instance", {0}, {}, Type), Branch,
       op(3, Range ? "invoke-direct/range" : "invoke-direct", {0}, {},
          Widget.methods[0].reference),
       Jump,
       op(5, Range ? "invoke-direct/range" : "invoke-direct", {0, Input}, {},
          Widget.methods[1].reference),
       op(6, "return-object", {0})});
  if (Protected) {
    Make.instructions.push_back(op(7, "move-exception", {0}));
    Make.instructions.push_back(op(8, "const/4", {0}, int64_t(0)));
    Make.instructions.push_back(op(9, "return-object", {0}));
    Make.code_end = 10;
    Make.tries = {{1, 6, {{std::string("Ljava/lang/Exception;"), 7}}}};
  }
  return {klass("Lfixture/Core;", {Make}), Widget};
}
} // namespace

