TEST(MobileDalvikJava,
     ConstructorChoicesKeepReferenceOverloadsAndRejectChangedBoundaries) {
  for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = constructorChoiceClasses(true, false, false, false, false);
    auto &Make = Input[0].methods[0];
    auto &Code = Make.instructions;
    switch (Mutation) {
    case 0:
      std::get<MethodRef>(Code[5].reference).owner = "Ljava/lang/Object;";
      break;
    case 1:
      Input[1].methods[1].reference.parameters = {"Ljava/lang/Object;"};
      Code[5].reference = Input[1].methods[1].reference;
      break;
    case 2:
      Code[5].reference = Input[1].methods[0].reference;
      Code[5].registers = {0};
      break;
    case 3:
      Code[2].registers = {0};
      break;
    case 4:
      Code[5].registers[1] = 0;
      break;
    case 5:
      Code[5].registers[0] = 1;
      break;
    case 6:
      Code[3].opcode = "invoke-virtual";
      break;
    case 7:
      Code[2].target = 6;
      break;
    case 8:
      Code[4].target = 5;
      break;
    case 9:
      Code[0] = op(0, "if-eqz", {3});
      Code[0].target = 5;
      break;
    case 10:
      Make.tries[0].start = 2;
      break;
    case 11:
      Code[7].registers = {2};
      Code[8] = op(8, "nop");
      break;
    case 12:
      Input[1].methods[1].generic_signature =
          "<S:Ljava/lang/Object;>(Lfixture/Widget;)V";
      break;
    case 13:
      Input[1].methods[1].access.insert("varargs");
      break;
    case 14:
      Input[1].methods[1].declared_throws = {"Ljava/lang/Exception;"};
      break;
    case 15:
      Input[1].generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 16:
      Code[2].literal = int64_t(1);
      break;
    case 17:
      Make.reference.parameters = {"I"};
      break;
    case 18:
      Make.reference.parameters.clear();
      break;
    case 19:
      Code[2].opcode = "if-gtz";
      break;
    }
    if (Mutation == 1 || Mutation == 15) {
      // A reference overload and an unused class formal both retain exact
      // constructor erasures. Neither requires a narrower input or projection.
      const auto R = recover(Input);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_FALSE(R.getArray("generic_signature_projections"));
    } else {
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
  }
}

std::vector<Class> monitorCopyCleanupClasses(unsigned Form, bool ProtectedExit,
                                             bool CopyTail) {
  auto Input = monitorRegionClasses();
  auto &M = Input[0].methods[0];
  M.reference.parameters = {"Ljava/lang/Object;", Input[1].name, "I", "J",
                            "Ljava/lang/Object;"};
  M.registers = 14;
  const std::string Suffix = Form == 0 ? "" : Form == 1 ? "/from16" : "/16";
  const auto Call = Input[1].methods[0].reference;
  M.instructions = {op(0, "monitor-enter", {8}),
                    op(1, "move-object" + Suffix, {0, 13}),
                    op(2, "invoke-interface", {9}, {}, Call),
                    op(3, "move" + Suffix, {1, 10}),
                    op(4, "invoke-interface", {9}, {}, Call),
                    op(5, "move-wide" + Suffix, {2, 11}),
                    op(6, "invoke-interface", {9}, {}, Call),
                    op(7, "monitor-exit", {8}),
                    op(8, "return-void"),
                    op(9, "move-exception", {4}),
                    op(10, "move-object" + Suffix, {5, 0}),
                    op(11, "goto", {}, {}, {}, 18),
                    op(12, "move-exception", {4}),
                    op(13, "move" + Suffix, {6, 1}),
                    op(14, "goto/16", {}, {}, {}, 18),
                    op(15, "move-exception", {4}),
                    op(16, "move-wide" + Suffix, {6, 2}),
                    CopyTail ? op(17, "move-object" + Suffix, {5, 0})
                             : op(17, "nop"),
                    op(18, "monitor-exit", {8}),
                    op(19, "throw", {4}),
                    op(20, "nop")};
  M.code_end = 21;
  M.tries = {{2, 3, {{std::nullopt, 9}}},
             {4, 5, {{std::nullopt, 12}}},
             {6, ProtectedExit ? 8u : 7u, {{std::nullopt, 15}}}};
  return Input;
}

std::vector<Class> monitorBackwardCleanupClasses(unsigned Form,
                                                 bool ProtectedExit,
                                                 bool CopyTail) {
  auto Input = monitorCopyCleanupClasses(Form, false, CopyTail);
  auto &M = Input[0].methods[0];
  const auto Original = M.instructions;
  M.instructions.assign(Original.begin(), Original.begin() + 15);
  M.instructions[11].target = 15;
  M.instructions[14].target = 15;
  M.instructions.push_back(op(15, "monitor-exit", {8}));
  M.instructions.push_back(op(16, "throw", {4}));
  M.instructions.push_back(op(17, "move-exception", {4}));
  auto Wide = Original[16];
  Wide.pc = 18;
  Wide.registers[1] = 11;
  M.instructions.push_back(Wide);
  auto Tail = Original[17];
  Tail.pc = 19;
  M.instructions.push_back(Tail);
  M.instructions.push_back(op(20, "goto", {}, {}, {}, 15));
  M.instructions.push_back(op(21, "nop"));
  M.code_end = 22;
  M.tries.back() = {6, ProtectedExit ? 16u : 7u, {{std::nullopt, 17}}};
  return Input;
}

