std::vector<Class> monitorReleaseHandlerClasses(unsigned Form, bool CopyTail,
                                                bool Outer = false,
                                                bool CopiedException = false) {
  auto Input = monitorCopyCleanupClasses(Form, false, CopyTail);
  auto &M = Input[0].methods[0];
  M.instructions.back() = op(20, "move-exception", {4});
  M.instructions.push_back(op(21, "goto", {}, {}, {}, 18));
  M.instructions.push_back(op(22, "nop"));
  M.code_end = 23;
  M.tries.push_back({7, 8, {{std::nullopt, 20}}});
  M.tries.push_back({18, 19, {{std::nullopt, 20}}});
  if (CopiedException) {
    for (size_t At : {size_t(10), size_t(13), size_t(16)})
      M.instructions[At] = op(At, "move-object", {5, 4});
    if (CopyTail)
      M.instructions[17] = op(17, "move-object", {6, 5});
    M.instructions[19].registers = {5};
    M.instructions[21] = op(21, "move-object", {5, 4});
    M.instructions[22] = op(22, "goto", {}, {}, {}, 18);
    M.instructions.push_back(op(23, "nop"));
    M.code_end = 24;
  }
  if (Outer) {
    M.instructions.pop_back();
    M.instructions.push_back(op(23, "move-exception", {4}));
    M.instructions.push_back(op(24, "throw", {4}));
    M.instructions.push_back(op(25, "nop"));
    M.code_end = 26;
    M.tries.back() = {18, 20, {{std::nullopt, 23}}};
  }
  return Input;
}

