TEST(MobileDalvikJava,
     MonitorNestedCleanupKeepsExplicitRethrowsAndRejectsEscapes) {
  for (bool Range : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Range, Mutation}));
      auto Input = nestedMonitorCleanupClasses(Range, false);
      auto &M = Input[0].methods[0];
      auto &Code = M.instructions;
      if (Mutation == 0)
        M.tries.erase(M.tries.begin());
      else if (Mutation == 1)
        M.tries.erase(M.tries.begin() + 2);
      else if (Mutation == 2)
        Code[18].registers = {4};
      else if (Mutation == 3)
        Code[19].registers = {1};
      else if (Mutation == 4)
        Code[5] = op(5, "move-object", {3, 4});
      else if (Mutation == 5)
        Code[1] = op(1, "goto", {}, {}, {}, 4);
      else if (Mutation == 6)
        Code[9] = op(9, "nop");
      else if (Mutation == 7)
        Code[17].registers = {3};
      else if (Mutation == 8)
        Code[14] = op(14, "return-void");
      else if (Mutation == 9)
        Code[14] = op(14, "goto", {}, {}, {}, 18);
      else if (Mutation == 10)
        Code[14].registers = {2};
      else
        Code[3] = op(3, "goto", {}, {}, {}, 5);
      Budget B;
      if (Mutation == 9) {
        // The bytecode explicitly ignores the newer captured failure and
        // rethrows its original value after release. Preserve that choice.
        const auto R = recoverJava(linkClasses(Input, B), B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_NE(source(R, 1).find("case 14:"), std::string::npos);
        EXPECT_NE(source(R, 1).find("case 19:"), std::string::npos);
      } else
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

