std::vector<Class> typedMonitorContinuationClasses(bool Range, bool Multiple) {
  auto Input = outerMonitorCleanupClasses(Range, false);
  auto &M = Input[0].methods[0];
  for (unsigned I : {0u, 2u, 4u})
    M.tries[I].handlers[0].type = "Ljava/lang/Exception;";
  if (Multiple) {
    M.instructions.pop_back();
    const auto Callback = Input[1].methods[0].reference;
    M.instructions.push_back(op(14, "move-exception", {2}));
    M.instructions.push_back(
        op(15, Range ? "invoke-interface/range" : "invoke-interface", {4}, {},
           Callback));
    M.instructions.push_back(op(16, "throw", {2}));
    M.instructions.push_back(op(17, "nop"));
    M.code_end = 18;
    for (unsigned I : {0u, 2u, 4u})
      M.tries[I].handlers.push_back({"Ljava/lang/Error;", 14});
  }
  return Input;
}

