    case 13:
      Bridge.instructions[6].registers[0] = 5;
      break;
    case 14:
      Bridge.instructions.insert(
          Bridge.instructions.begin() + 4,
          op(3, "invoke-virtual", {0}, {}, Carrier.methods[0].reference));
      break;
    case 15:
      Target.generic_signature =
          "(JLfixture/Sink<+Lfixture/Token;>;)Ljava/lang/Object;";
      break;
    case 16:
      Target.generic_signature =
          "(JLfixture/Sink<-Lfixture/Payload;>;)Ljava/lang/Object;";
