std::vector<Class> nestedConditionalTailClasses(const std::string &Type,
                                                bool Wide, bool External,
                                                bool Range, bool Flipped) {
  auto Input = nestedConditionalArgumentClasses(Wide, External);
  const bool WideTail = Type == "J" || Type == "D";
  const unsigned Words = WideTail ? 2 : 1;
  auto &Outer = Input[3].methods[0];
  Outer.reference.parameters =
      Flipped
          ? std::vector<std::string>{Input[1].name, "Ljava/lang/Object;", Type}
          : std::vector<std::string>{Input[1].name, Type, "Ljava/lang/Object;"};
  if (!External)
    Outer.registers = Words + 3;
  auto Tail = method("tail", {}, Type, WideTail ? 2 : 1,
                     {WideTail ? op(0, "const-wide/16", {0}, int64_t(0))
                               : op(0, "const/4", {0}, int64_t(0)),
                      op(1,
                         Type.starts_with('L') ? "return-object"
                         : WideTail            ? "return-wide"
                                               : "return",
                         {0})});
  Tail.reference.owner = Input[2].name;
  Input[2].methods.push_back(Tail);
  Input[2].external = External;
  if (External)
    for (auto &M : Input[2].methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  auto &Make = Input[0].methods[0];
  const unsigned Extra = Words + 2;
  for (auto &Op : Make.instructions)
    for (auto &R : Op.registers)
      if (R >= 3)
        R += Extra;
  Make.registers += Extra;
  if (Range && !Wide)
    Make.instructions[10].opcode = "invoke-direct/range";
  auto &Code = Make.instructions;
  uint32_t PC = Code[Code.size() - 2].pc;
  Code.resize(Code.size() - 2);
  const unsigned Value = Flipped ? 5 : 4;
  const unsigned Object = Flipped ? 4 : 4 + Words;
  Code.push_back(op(PC++, "move-object", {3, 0}));
  Code.push_back(op(PC++, "invoke-static", {}, {}, Tail.reference));
  Code.push_back(op(PC++,
                    Type.starts_with('L') ? "move-result-object"
                    : WideTail            ? "move-result-wide"
                                          : "move-result",
                    {Value}));
  Code.push_back(op(PC++, "invoke-static", {Make.registers - 1}, {},
                    Input[2].methods[0].reference));
  Code.push_back(op(PC++, "move-result-object", {Object}));
  std::vector<unsigned> Frame;
  for (unsigned R = 2; R < 5 + Words; ++R)
    Frame.push_back(R);
  Code.push_back(op(PC++, Range ? "invoke-direct/range" : "invoke-direct",
                    std::move(Frame), {}, Outer.reference));
  Code.push_back(op(PC++, "return-object", {2}));
  Make.code_end = PC;
  return Input;
}

TEST(MobileDalvikJava, NestedConditionalTailsKeepClosedOuterArgumentOrder) {
  for (const std::string Type :
       {"Z", "B", "C", "S", "I", "J", "F", "D", "Ljava/lang/Object;"})
    for (bool Wide : {false, true})
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (bool Flipped : {false, true})
            for (bool Reverse : {false, true}) {
              auto Input = nestedConditionalTailClasses(Type, Wide, External,
                                                        Range, Flipped);
              if (Reverse)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              const auto R = recoverJava(linkClasses(Input, B), B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
              std::string Text;
              for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                Text += source(R, I);
              for (const auto &Name : {"Envelope", "Target"}) {
                const auto Needle = std::string("new fixture.") + Name + "(";
                const auto At = Text.find(Needle);
                ASSERT_NE(At, std::string::npos);
                EXPECT_EQ(Text.find(Needle, At + 1), std::string::npos);
              }
              const auto Child = Text.find("new fixture.Target(");
              const auto Tail = Text.find(".tail(");
              ASSERT_NE(Tail, std::string::npos);
              EXPECT_GT(Tail, Child);
              EXPECT_EQ(Text.find(".tail(", Tail + 1), std::string::npos);
            }
}

TEST(MobileDalvikJava, NestedConditionalTailsRejectEscapesAndMalformedFrames) {
  for (unsigned Mutation = 0; Mutation < 32; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = nestedConditionalTailClasses("J", false, false, true, false);
    auto &M = Input[0].methods[0];
    auto &C = M.instructions;
    switch (Mutation) {
    case 0:
      C[3].registers[0] = 2;
      break;
    case 1:
      C[4].registers[0] = 2;
      break;
    case 2:
      C[2].target = C.back().pc;
      break;
    case 3:
      C[7].target = 0;
      break;
    case 4:
      for (auto &Op : C) {
        ++Op.pc;
        if (Op.target)
          ++*Op.target;
      }
      C.insert(C.begin(), op(0, "goto", {}, {}, {}, 4));
      ++M.code_end;
      break;
    case 5:
      M.tries = {{1, 10, {{std::nullopt, C.back().pc}}}};
      break;
    case 6:
      C[6].target = 10;
      break;
    case 7:
      C[0].target = 1;
      break;
    case 8:
      Input[1].methods[0].access = {"private", "constructor"};
      break;
    case 9:
      Input[3].methods[0].access = {"private", "constructor"};
      break;
    case 10:
      Input[2].methods[1].access.erase("static");
      break;
    case 11:
      C[13].opcode = "move-result";
      break;
    case 12:
      C[16].registers[3] = 4;
      break;
    case 13:
      C[16].registers[0] = 0;
      break;
    case 14:
      C[16].registers[1] = 7;
      break;
    case 15:
      C[11].registers[1] = 2;
      break;
    case 16:
      C[13].registers[0] = 1;
      break;
    case 17:
      std::get<MethodRef>(C[12].reference).returns = "I";
      break;
    case 18:
      C[14].registers[0] = 2;
      break;
    case 19:
      C[15].registers[0] = 2;
      break;
    case 20:
      C[2].target = C[4].pc;
      break;
    case 21:
      C[6].element_width = 1;
      break;
    case 22:
      C[1].literal = int64_t(1);
      break;
    case 23:
      C[2].target = 999;
      break;
    case 24:
      C[10].reference = Input[3].methods[0].reference;
      break;
    case 25:
      C[11] = op(C[11].pc, "goto", {}, {}, {}, C[2].pc);
      break;
    case 26:
      Input[3].access.insert("abstract");
      break;
    case 27:
      Input[2].methods[1].generic_signature = "<T:Ljava/lang/Object;>()TT;";
      break;
    case 28:
      C[6] = op(C[6].pc, "const-wide/16", {1}, int64_t(0));
      break;
    case 29:
      C[7].target = C[11].pc;
      break;
    case 30:
      C[12].opcode = "vendor-unknown";
      break;
    case 31:
      C[1].keys = {1};
      break;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> covariantPlainInputClasses(const std::string &Type,
                                              bool External, bool Range,
                                              bool ReverseParameters,
                                              bool UnaryConsumer, bool Nested) {
  auto Input = comparisonCarrierClasses(External, Range, false, false, 0);
  Input[4].name = "Ljava/lang/Boolean;";
  if (UnaryConsumer)
    Input[3].generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Work = Input[1].methods[0];
  const std::string Producer = Nested ? "Lfixture/Values<+Lfixture/Box<TT;>;>;"
                                      : "Lfixture/Values<+TT;>;";
  const std::string Consumer =
      UnaryConsumer ? "Lfixture/Comparison<-TT;>;"
                    : "Lfixture/Comparison<-TT;+Ljava/lang/Boolean;>;";
  Work.reference.parameters =
      ReverseParameters
          ? std::vector<std::string>{Input[3].name, Input[2].name}
          : std::vector<std::string>{Input[2].name, Input[3].name};
  Work.reference.returns = Type;
  Work.generic_signature =
      "<T:Ljava/lang/Object;>(" +
      (ReverseParameters ? Consumer + Producer : Producer + Consumer) + ")" +
      Type;
  const bool Wide = Type == "J" || Type == "D";
  Work.registers = Wide ? 4 : 3;
  const auto Return = Type.starts_with('L') ? "return-object"
                      : Wide                ? "return-wide"
                                            : "return";
  Work.instructions = {Wide ? op(0, "const-wide/16", {0}, int64_t(0))
                            : op(0, "const/4", {0}, int64_t(0)),
                       op(1, Return, {0})};
  Work.code_end = 2;
  if (External) {
    Work.instructions.clear();
    Work.registers = Work.code_end = 0;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Work.reference.parameters;
  Call.reference.returns = Type;
  Call.registers = Wide ? 4 : 3;
  Call.instructions = {
      op(0, Range ? "invoke-static/range" : "invoke-static",
         Wide ? std::vector<unsigned>{2, 3} : std::vector<unsigned>{1, 2}, {},
         Work.reference),
      op(1,
         Type.starts_with('L') ? "move-result-object"
         : Wide                ? "move-result-wide"
                               : "move-result",
         {0}),
      op(2, Return, {0})};
  Call.code_end = 3;
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  Object.external = true;
  Input.push_back(Object);
  if (Nested) {
    auto Box = klass("Lfixture/Box;");
    Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    Box.external = External;
    Input.push_back(Box);
  }
  return Input;
}

TEST(MobileDalvikJava, CovariantPlainInputsKeepCompleteStaticObjectBinding) {
  for (const std::string Type :
       {"Z", "B", "C", "S", "I", "J", "F", "D", "Ljava/lang/Object;"})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool ReverseParameters : {false, true})
          for (bool UnaryConsumer : {false, true})
            for (bool Nested : {false, true})
              for (bool Reverse : {false, true}) {
                auto Input = covariantPlainInputClasses(Type, External, Range,
                                                        ReverseParameters,
                                                        UnaryConsumer, Nested);
                const auto Ref = Input[1].methods[0].reference;
                const auto Signature = Input[1].methods[0].generic_signature;
                if (Reverse)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                const auto Classes = linkClasses(Input, B);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Signature);
              }
}

TEST(MobileDalvikJava, CovariantPlainInputsRejectUnknownOrChangedContracts) {
  for (unsigned Mutation = 0; Mutation < 32; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        covariantPlainInputClasses("Z", false, true, false, false, false);
    auto &Owner = Input[1];
    auto &Work = Owner.methods[0];
    auto &Signature = *Work.generic_signature;
    auto Replace = [&](const std::string &From, const std::string &To) {
      const auto Position = Signature.find(From);
      ASSERT_NE(Position, std::string::npos);
      Signature.replace(Position, From.size(), To);
    };
    switch (Mutation) {
    case 0:
      Replace("Values<+TT;>", "Values<-TT;>");
      break;
    case 1:
      Replace("Lfixture/Values<+TT;>;", "Lfixture/Values;");
      break;
    case 2:
      Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
      break;
    case 3:
      Replace("<T:Ljava/lang/Object;>",
              "<T:Ljava/lang/Object;U:Ljava/lang/Object;>");
      break;
    case 4:
      Replace("Values<+TT;>", "Values<+TUnknown;>");
      break;
    case 5:
      Replace("Comparison<-TT;", "Comparison<-TUnknown;");
      break;
    case 6:
      Input[3].generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 7:
      Input[2].generic_signature = "<E:Ljava/lang/Number;>Ljava/lang/Object;";
      break;
    case 8:
      Input[3].generic_signature =
          "<A:Ljava/lang/Number;R:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 9:
      Input[2].access.erase("public");
      break;
    case 10:
      Input[3].access.erase("public");
      break;
    case 11:
      Input.erase(Input.begin() + 2);
      break;
    case 12:
      Input[2].generic_signature.reset();
      break;
    case 13:
      Input[3].generic_signature.reset();
      break;
    case 14:
      Work.declared_throws = {"Ljava/lang/RuntimeException;"};
      break;
    case 15:
      Work.access.insert("varargs");
      break;
    case 16:
      Work.access.erase("static");
      break;
    case 17:
      Work.access = {"private", "static"};
      break;
    case 18:
      Replace(")Z", ")TT;");
      break;
    case 19:
      Signature.insert(Signature.find(")"), "I");
      break;
    case 20: {
      Replace("Values<+TT;>", "Values<+Lfixture/Box<+TT;>;>");
      auto Box = klass("Lfixture/Box;");
      Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      Input.push_back(Box);
      break;
    }
    case 21:
      Owner.generic_signature = "<T:Ljava/lang/Number;>Ljava/lang/Object;";
      Replace("<T:Ljava/lang/Object;>", "<U:Ljava/lang/Object;>");
      break;
    case 22:
      Input.erase(Input.begin() + 4);
      break;
    case 23:
      Input[4].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
      break;
    case 24:
      Replace("+Ljava/lang/Boolean;", "*");
      break;
    case 25:
      Owner.enclosing = "Lfixture/Unknown;";
      break;
    case 26:
      Work.access.insert("native");
      break;
    case 27:
      Input[0].methods[0].instructions[0].opcode = "invoke-polymorphic";
      break;
    case 28:
      Input[0].methods[0].instructions[0].registers[0] = 0;
      break;
    case 29:
      Work.reference.parameters[1] = "Ljava/lang/Object;";
      break;
    case 30: {
      Signature.insert(Signature.find(")"), "I");
      Work.reference.parameters.push_back("I");
      Work.registers = 4;
      auto &Call = Input[0].methods[0];
      Call.reference.parameters = Work.reference.parameters;
      Call.registers = 4;
      Call.instructions[0].registers = {1, 2, 3};
      Call.instructions[0].reference = Work.reference;
      break;
    }
    case 31:
      Work.instructions[0].opcode = "vendor-unknown";
      break;
    }
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

std::vector<Class> conditionalComparisonClasses(const std::string &Type,
                                                const std::string &Opcode,
                                                const std::string &Relation,
                                                unsigned Destination,
                                                bool External, bool Range) {
  auto Input = conditionalConversionClasses(Type, "I", Opcode, External, Range);
  auto &M = Input[0].methods[0];
  const bool Wide = Type == "J" || Type == "D";
  M.instructions = {op(0, "new-instance", {0}, {}, Input[1].name),
                    op(1, Wide ? "const-wide" : "const", {1}, int64_t(-1)),
                    op(2, Wide ? "const-wide" : "const", {3}, int64_t(0)),
                    op(3, Opcode, {Destination, 1, 3}),
                    op(4, "if-" + Relation + "z", {Destination}, {}, {}, 8),
                    op(5, "const/4", {1}, int64_t(1)),
                    op(6, "goto", {}, {}, {}, 9),
                    op(8, "const/4", {1}, int64_t(0)),
                    op(9, "move-object", {2, 9}),
                    op(10, Range ? "invoke-direct/range" : "invoke-direct",
                       {0, 1, 2}, {}, Input[1].methods[0].reference),
                    op(11, "return-object", {0})};
  M.code_end = 12;
  return Input;
}

