TEST(MobileDalvikJava, PublicProducedElementsRejectUnprovenTreesAndDispatch) {
  for (bool Static : {false, true})
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Static, Mutation, Route}));
        auto Input =
            publicProducedElementClasses(Static, false, false, false, true, 0);
        auto &Read = Input[0].methods[0];
        auto &Call = Input[4].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &Text = *Read.generic_signature;
          const auto At = Text.find(From);
          ASSERT_NE(At, std::string::npos);
          Text.replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Read.access.erase("public");
          Read.access.insert("protected");
          break;
        case 1:
          replace("<+TR;>", "<-TR;>");
          break;
        case 2:
          replace("R:Ljava/lang/Object;>",
                  "R:Ljava/lang/Object;U:Ljava/lang/Object;>");
          break;
        case 3:
          replace(")TR;", ")TUnknown;");
          break;
        case 4:
          Input[2].generic_signature =
              "<F:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 5:
          Input[1].generic_signature =
              "<I:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 6:
          replace("Callback<Ljava/lang/Object;Lfixture/Token;>",
                  "Callback<*Lfixture/Token;>");
          break;
        case 7:
          replace("Lfixture/Token;>", "Lfixture/Missing;>");
          break;
        case 8:
          Input[3].access.erase("public");
          Input[3].access.insert("private");
          break;
        case 9:
          Read.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 10:
          Read.access.insert("native");
          Read.instructions.clear();
          Read.registers = Read.code_end = 0;
          break;
        case 11:
          Read.access.insert("varargs");
          break;
        case 12:
          Read.access.insert("bridge");
          break;
        case 13:
          Call.instructions[0].opcode =
              Static ? "invoke-virtual/range" : "invoke-static/range";
          break;
        case 14:
          Call.instructions[0].registers.pop_back();
          break;
        case 15:
          Read.reference.parameters[0] = "Ljava/lang/Object;";
          Call.instructions[0].reference = Read.reference;
          break;
        case 16:
          replace("Lfixture/Factory<+TR;>;", "Lfixture/Factory;");
          break;
        case 17:
          replace("Lfixture/Token;>", "TUnknown;>");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Route)
          EXPECT_THROW(recoverJava(linkClasses(Input, B), B),
                       std::runtime_error);
        else
          EXPECT_THROW(recover(Input), std::runtime_error);
      }
}

std::vector<Class> reifiableInputCarrierClasses(bool Static, bool ExternalAPI,
                                                bool ExternalTarget,
                                                bool Facade, bool Range,
                                                unsigned ResultUse,
                                                unsigned Shape) {
  auto Input = publicProducedElementClasses(Static, ExternalAPI, ExternalTarget,
                                            Facade, Range, ResultUse);
  auto Property = klass("Lfixture/Property;");
  Property.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Property.external = ExternalAPI;
  auto &Read = Input[0].methods[0];
  const std::string Closed =
      "Lfixture/Callback<Ljava/lang/Object;Lfixture/Token;>;";
  const auto First = Read.generic_signature->find(Closed);
  const auto Second =
      Read.generic_signature->find(Closed, First + Closed.size());
  const std::string Auxiliary =
      Shape == 0 ? "Lfixture/Property<*>;"
      : Shape == 1
          ? "Lfixture/Callback<**>;"
          : "Lfixture/Callback<Ljava/lang/Object;Lfixture/Property<*>;>;";
  Read.generic_signature->replace(Second, Closed.size(), Auxiliary);
  if (Shape == 0)
    Read.reference.parameters[1] = Property.name;
  auto Client = std::find_if(Input.begin(), Input.end(), [](const Class &C) {
    return C.name == "Lfixture/Client;";
  });
  auto &Call = Client->methods[0];
  Call.reference.parameters[2] = Read.reference.parameters[1];
  auto &Ref = std::get<MethodRef>(Call.instructions[0].reference);
  Ref.parameters = Read.reference.parameters;
  Input.push_back(Property);
  return Input;
}

