std::vector<Class>
literalDivisionPreparationClasses(const std::string &Opcode, int64_t Divisor,
                                  unsigned Shape, bool External, bool Range) {
  if (Shape >= 3) {
    auto Input =
        linearIntegerPrefixClasses(Opcode, Shape == 4, External, Range);
    for (auto &I : Input[0].methods[0].instructions)
      if (I.opcode == Opcode)
        I.literal = Divisor;
    return Input;
  }
  auto Input = integerArithmeticAllocationClasses(
      Opcode.ends_with("/lit8") ? 2 : 3, External, Range);
  auto &M = Input[0].methods[0];
  if (Shape == 0) {
    for (auto &I : M.instructions)
      if (I.opcode.starts_with("add-int/") ||
          I.opcode.starts_with("sub-int/")) {
        I.opcode = Opcode;
        I.literal = Divisor;
      }
    return Input;
  }
  const bool Static = Shape == 1;
  const FieldRef Field{Input[0].name, "value", "I"};
  Input[0].fields.push_back(
      {Field, Static ? Access{"public", "static"} : Access{"public"}, {}});
  if (!Static)
    M.reference.parameters[0] = Input[0].name;
  M.instructions = {op(0, "new-instance", {0}, {}, Input[1].name),
                    Static ? op(1, "sget", {1}, {}, Field)
                           : op(1, "iget", {1, 5}, {}, Field),
                    op(2, Opcode, {1, 1}, Divisor),
                    op(3, "move", {2, 1}),
                    op(4, "move", {3, 1}),
                    op(5, "move", {4, 1}),
                    op(6, Range ? "invoke-direct/range" : "invoke-direct",
                       {0, 1, 2, 3, 4}, {}, Input[1].methods[0].reference),
                    op(7, "return-object", {0})};
  M.code_end = 8;
  return Input;
}

TEST(MobileDalvikJava,
     NonzeroLiteralDivisionKeepsSharedAllocationAndConstructorReceipts) {
  for (const std::string Operation : {"div-int", "rem-int"})
    for (bool WideLiteral : {false, true})
      for (int64_t Divisor :
           WideLiteral ? std::vector<int64_t>{-32768, -257, -1, 1, 257, 32767}
                       : std::vector<int64_t>{-128, -1, 1, 5, 127})
        for (unsigned Shape = 0; Shape < 5; ++Shape)
          for (bool External : {false, true})
            for (bool Range : {false, true})
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{Operation, WideLiteral, Divisor, Shape, External,
                               Range, Route}));
                auto Input = literalDivisionPreparationClasses(
                    Operation + (WideLiteral ? "/lit16" : "/lit8"), Divisor,
                    Shape, External, Range);
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                     : recover(Input);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              }
}

TEST(MobileDalvikJava,
     NonzeroLiteralDivisionRejectsMissingWitnessWidthsAndOrigins) {
  for (unsigned Shape = 0; Shape < 5; ++Shape)
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Shape, Mutation, Route}));
        auto Input = literalDivisionPreparationClasses("div-int/lit8", 5, Shape,
                                                       true, false);
        auto &M = Input[0].methods[0];
        auto &Arithmetic = *std::find_if(
            M.instructions.begin(), M.instructions.end(),
            [](const auto &I) { return I.opcode == "div-int/lit8"; });
        switch (Mutation) {
        case 0:
          Arithmetic.literal = int64_t(0);
          break;
        case 1:
          Arithmetic.literal = int64_t(128);
          break;
        case 2:
          Arithmetic.literal = int64_t(-129);
          break;
        case 3:
          Arithmetic.opcode = "rem-int/lit16";
          Arithmetic.literal = int64_t(32768);
          break;
        case 4:
          Arithmetic.opcode = "div-int/lit16";
          Arithmetic.literal = int64_t(-32769);
          break;
        case 5:
          Arithmetic.literal = {};
          break;
        case 6:
          Arithmetic.literal = std::string("missing integer");
          break;
        case 7:
          Arithmetic.registers.pop_back();
          break;
        case 8:
          Arithmetic.registers[0] = M.registers;
          break;
        case 9:
          Arithmetic.reference = "Ljava/lang/Object;";
          break;
        case 10:
          Arithmetic.opcode = "div-int/2addr";
          break;
        case 11:
          Arithmetic.opcode = "rem-long/lit8";
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Mutation == 0 && Shape >= 3) {
          // Preserve both original linear-prefix inputs and every dependency
          // order. Other allocation surfaces retain their total-only policy.
          const auto Report =
              Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(Report.getInteger("minimum_java_release"), 25);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          continue;
        }
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

std::vector<Class> localVoidSetterClasses(bool Public, bool First,
                                          bool External, bool Range) {
  const std::string Variable = First ? "A" : "B";
  const std::string Parameter = "T" + Variable + ";";
  const FieldRef Field{"Lfixture/Entry;", "value", "Ljava/lang/Object;"};
  auto Write =
      method("replace", {Field.type}, "V", 2,
             {op(0, "iput-object", {1, 0}, {}, Field), op(1, "return-void")});
  Write.access = {"public"};
  Write.generic_signature = "(" + Parameter + ")V";
  auto Update =
      method("replace", {Field.type}, Field.type, 3,
             {op(0, "iget-object", {0, 1}, {}, Field),
              op(1, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2},
                 {}, MethodRef{Field.owner, "replace", {Field.type}, "V"}),
              op(2, "return-object", {0})});
  Update.access = {"public"};
  Update.generic_signature = "(" + Parameter + ")" + Parameter;
  const MethodRef RootInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Init =
      method("<init>", {Field.type}, "V", 2,
             {op(0, "invoke-direct", {0}, {}, RootInit),
              op(1, "iput-object", {1, 0}, {}, Field), op(2, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(" + Parameter + ")V";
  auto Entry = klass(Field.owner, {Init, Write, Update});
  Entry.access = Public ? Access{"public", "final"} : Access{"final"};
  Entry.interfaces = {"Lfixture/Contract;", "Lfixture/Marker;"};
  Entry.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;" +
      std::string(First ? "Lfixture/Contract<TB;TA;>;"
                        : "Lfixture/Contract<TA;TB;>;") +
      "Lfixture/Marker;";
  Entry.fields = {{Field, {"private"}, {}}};
  Entry.fields[0].generic_signature = Parameter;
  auto Required = method("replace", {Field.type}, Field.type, 0, {});
  Required.access = {"public", "abstract"};
  Required.generic_signature = "(TY;)TY;";
  auto Contract = klass("Lfixture/Contract;", {Required});
  Contract.access = {"public", "abstract", "interface"};
  Contract.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Ljava/lang/Object;";
  Contract.external = External;
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = Contract.access;
  Marker.external = External;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = Init.access;
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Entry, Contract, Marker, Object};
}

std::vector<Class> capturedLocalVoidSetterClasses(bool Public, bool First,
                                                  bool External, bool Range) {
  auto Input = localVoidSetterClasses(Public, First, External, Range);
  auto &Entry = Input[0];
  const std::string Value = First ? "TA;" : "TB;";
  const std::string OuterName = "Lfixture/Owner;";
  auto Make = method(
      "make", {"Ljava/lang/Object;"}, "Lfixture/Contract;", 4,
      {op(0, "new-instance", {0}, {}, Entry.name),
       op(1, "invoke-direct", {0, 2, 3}, {},
          MethodRef{
              Entry.name, "<init>", {OuterName, "Ljava/lang/Object;"}, "V"}),
       op(2, "return-object", {0})});
  Make.reference.owner = OuterName;
  Make.access = {"public"};
  Make.generic_signature = "(" + Value + ")Lfixture/Contract<" +
                           (First ? "TB;TA;" : "TA;TB;") + ">;";
  auto Outer = klass(OuterName, {Make});
  Outer.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  Entry.inner_class_present = true;
  Entry.inner_access = Public ? Access{"public", "static", "final"} : Access{};
  Entry.enclosing_method = Make.reference;
  Entry.generic_signature =
      Entry.generic_signature->substr(Entry.generic_signature->find(">") + 1);
  const FieldRef Capture{Entry.name, "this$0", OuterName};
  Entry.fields.push_back({Capture, {"final", "synthetic"}, {}});
  Entry.fields.back().generic_signature = "Lfixture/Owner<TA;TB;>;";
  auto &Init = Entry.methods[0];
  Init.reference.parameters = {OuterName, "Ljava/lang/Object;"};
  Init.access = {"constructor"};
  Init.registers = 3;
  Init.instructions = {
      op(0, "iput-object", {1, 0}, {}, Capture),
      op(1, "invoke-direct", {0}, {},
         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
      op(2, "iput-object", {2, 0}, {}, Entry.fields[0].reference),
      op(3, "return-void")};
  Init.code_end = 4;
  Input.push_back(std::move(Outer));
  return Input;
}

TEST(MobileDalvikJava, CapturedLocalVoidSettersKeepOriginalFormalScope) {
  for (bool Public : {false, true})
    for (bool First : {false, true})
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (unsigned Route = 0; Route != 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Public, First, External, Range, Route}));
            auto Input =
                capturedLocalVoidSetterClasses(Public, First, External, Range);
            const auto Void = Input[0].methods[1].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            EXPECT_NO_THROW({
              const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                   : recover(Input);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              bool Found = false;
              for (const auto &Row : *R.getArray("methods"))
                if (Row.getAsObject()->getString("identity") ==
                    Void.identity()) {
                  Found = true;
                  EXPECT_EQ(Row.getAsObject()->getString("projection_kind"),
                            "incompatible-local-return-slot");
                  EXPECT_TRUE(Row.getAsObject()->getString("source_identity"));
                }
              EXPECT_TRUE(Found);
              std::string Text;
              for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
                Text += source(R, I);
              const std::string Variable = First ? "A" : "B";
              EXPECT_NE(Text.find(".value = ((" + Variable + ") "),
                        std::string::npos);
              const auto Call =
                  Text.find(".__neverdReturnSlot(((" + Variable + ") ");
              EXPECT_NE(Call, std::string::npos);
            });
          }
}

TEST(MobileDalvikJava, CapturedLocalVoidSettersRejectScopeAndCaptureDrift) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation != 18; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{External, Mutation}));
      auto Input = capturedLocalVoidSetterClasses(false, false, External, true);
      auto &Entry = Input[0];
      auto &Write = Entry.methods[1];
      auto &Update = Entry.methods[2];
      if (Mutation == 0)
        Write.generic_signature = "(TA;)V";
      else if (Mutation == 1)
        Update.generic_signature = "(TA;)TB;";
      else if (Mutation == 2)
        Update.generic_signature = "(TB;)TA;";
      else if (Mutation == 3)
        Entry.fields[0].generic_signature = "TA;";
      else if (Mutation == 4)
        Write.generic_signature = "<B:Ljava/lang/Object;>(TB;)V";
      else if (Mutation == 5)
        Input.back().methods[0].access.insert("static");
      else if (Mutation == 6)
        Entry.enclosing_method->owner = "Lfixture/Missing;";
      else if (Mutation == 7)
        Entry.access.erase("final");
      else if (Mutation == 8)
        Entry.fields.back().access.erase("synthetic");
      else if (Mutation == 9)
        Entry.fields.back().access.erase("final");
      else if (Mutation == 10)
        Entry.methods[0].instructions[0].registers = {2, 0};
      else if (Mutation == 11)
        Update.instructions[1].registers = {2, 1};
      else if (Mutation == 12)
        Write.access.insert("static");
      else if (Mutation == 13)
        Input.erase(Input.begin() + 2);
      else if (Mutation == 14) {
        auto Required = Input[1].methods[0];
        Required.reference.returns = "V";
        Required.generic_signature = "(TY;)V";
        Input[1].methods.push_back(Required);
      } else if (Mutation == 15)
        Write.instructions[0].registers = {0, 1};
      else if (Mutation == 16)
        Entry.fields[0].access.insert("final");
      else
        Update.access.insert("synthetic");
      Budget B;
      EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

