std::vector<Class> scopedGetterSuperClasses(unsigned Arity, bool Reordered,
                                            bool Range, bool External) {
  const auto formals = [](const std::string &Prefix, unsigned Count) {
    std::string S = "<";
    for (unsigned I = 0; I < Count; ++I)
      S += Prefix + std::to_string(I) + ":Ljava/lang/Object;";
    return S + ">";
  };
  const auto use = [](const std::string &Name, const std::string &Prefix,
                      unsigned Count) {
    std::string S = Name.substr(0, Name.size() - 1) + "<";
    for (unsigned I = 0; I < Count; ++I)
      S += "T" + Prefix + std::to_string(I) + ";";
    return S + ">;";
  };
  auto Node = klass("Lfixture/Node;");
  Node.generic_signature = formals("N", Arity) + "Ljava/lang/Object;";
  Node.external = External;
  auto Path = klass("Lfixture/Path;");
  Path.generic_signature = formals("L", Arity + 1) + "Ljava/lang/Object;";
  Path.external = External;
  auto Fetch =
      method("fetch", {}, Node.name, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Fetch.access = {"public"};
  Fetch.generic_signature = "()" + use(Node.name, "P", Arity);
  auto Provider = klass("Lfixture/Provider;", {Fetch});
  Provider.generic_signature = formals("P", Arity) + "Ljava/lang/Object;";
  Provider.external = External;
  const MethodRef RootInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Init =
      method("<init>", {Node.name, "[" + Path.name}, "V", 3,
             {op(0, "invoke-direct", {0}, {}, RootInit), op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(" + use(Node.name, "B", Arity) + "[" +
                           use(Path.name, "B", Arity + 1) + ")V";
  auto Other = Init;
  Other.reference.parameters = {"Ljava/lang/Object;", "[Ljava/lang/Object;"};
  Other.generic_signature.reset();
  auto Parent = klass("Lfixture/Parent;", {Init, Other});
  Parent.generic_signature = formals("B", Arity + 1) + "Ljava/lang/Object;";
  Parent.external = External;
  const unsigned Self = Range ? 3 : 1;
  const unsigned Receiver = Self + (Reordered ? 2 : 1);
  const unsigned Array = Self + (Reordered ? 1 : 2);
  std::vector<Instruction> Code{
      op(0, "nop"),
      op(1, Range ? "invoke-virtual/range" : "invoke-virtual", {Receiver}, {},
         Provider.methods[0].reference),
      op(2, "move-result-object", {Range ? 1u : 0u})};
  if (Range) {
    Code.push_back(op(3, "move-object", {0, Self}));
    Code.push_back(op(4, "move-object", {2, Array}));
  }
  Code.push_back(op(Code.size(),
                    Range ? "invoke-direct/range" : "invoke-direct",
                    Range ? std::vector<unsigned>{0, 1, 2}
                          : std::vector<unsigned>{Self, 0, Array},
                    {}, Parent.methods[0].reference));
  Code.push_back(op(Code.size(), "return-void"));
  auto ChildInit = method(
      "<init>",
      Reordered ? std::vector<std::string>{"[" + Path.name, Provider.name}
                : std::vector<std::string>{Provider.name, "[" + Path.name},
      "V", Self + 3, Code);
  ChildInit.access = Init.access;
  const auto ReceiverType = use(Provider.name, "C", Arity);
  const auto ArrayType = "[" + use(Path.name, "C", Arity + 1);
  ChildInit.generic_signature =
      "(" + (Reordered ? ArrayType + ReceiverType : ReceiverType + ArrayType) +
      ")V";
  auto Child = klass("Lfixture/Child;", {ChildInit});
  Child.superclass = Parent.name;
  Child.generic_signature =
      formals("C", Arity + 1) + use(Parent.name, "C", Arity + 1);
  if (External)
    for (auto *C : {&Parent, &Provider})
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = Init.access;
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  return {Child, Parent, Provider, Node, Path, Object};
}

TEST(MobileDalvikJava, ScopedGetterSuperCallsKeepFullReceiverResultAndArray) {
  for (unsigned Arity = 1; Arity <= 3; ++Arity)
    for (bool Reordered : {false, true})
      for (bool Range : {false, true})
        for (bool External : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Arity, Reordered, Range, External, Route}));
            auto Input =
                scopedGetterSuperClasses(Arity, Reordered, Range, External);
            const auto Caller = Input[0].methods[0].reference;
            const auto Target = Input[1].methods[0].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            if (Route)
              Classes = linkClasses(Input, B);
            else
              for (auto &C : Input) {
                const auto Name = C.name;
                Classes.emplace(Name, std::move(C));
              }
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
          }
}

