std::vector<Class> linearFinalThrowConstructorClasses(bool Two, bool Reversed) {
  const FieldRef Value{"Lfixture/Aborting;", "value", "I"};
  const FieldRef Failure{Value.owner, "failure", "Ljava/lang/Throwable;"};
  auto Init = method("<init>", {Failure.type, "I"}, "V", 3,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "iput", {2, 0}, {}, Value)});
  Init.access = {"public", "constructor"};
  if (Two)
    Init.instructions.push_back(op(2, "iput-object", {1, 0}, {}, Failure));
  if (Two && Reversed)
    std::swap(Init.instructions[1], Init.instructions[2]);
  Init.instructions.push_back(op(Init.instructions.size(), "throw", {1}));
  for (size_t i = 0; i < Init.instructions.size(); ++i)
    Init.instructions[i].pc = i;
  Init.code_end = Init.instructions.size();
  auto Owner = klass(Value.owner, {Init});
  Owner.fields = {{Value, {"public", "final"}, {}}};
  if (Two)
    Owner.fields.push_back({Failure, {"public", "final"}, {}});
  auto RootInit = method("<init>", {}, "V", 0, {});
  RootInit.access = Init.access;
  auto Object = klass("Ljava/lang/Object;", {RootInit});
  Object.external = true;
  Object.superclass.reset();
  return {Owner, Object};
}

