namespace {
std::vector<Class> covariantArraySuperClasses(unsigned Arity, bool Reordered,
                                              bool Range, bool External,
                                              unsigned Mask, bool Nested) {
  auto Input = referenceArraySuperClasses(Arity, Reordered, Range, External);
  const std::string EntryName = "Lfixture/ArrayEntry;";
  auto entry = [&](const std::string &Left, const std::string &Right) {
    return std::string("Lfixture/ArrayEntry<") + ((Mask & 1) ? "+" : "") +
           Left + ((Mask & 2) ? "+" : "") + Right + ">;";
  };
  auto tail = [&](const std::string &Prefix) {
    auto First = "T" + Prefix + "0;";
    const auto Last = "T" + Prefix + std::to_string(Arity - 1) + ";";
    if (Nested)
      First = entry(First, Last);
    return entry(First, Last);
  };
  for (auto [Index, Prefix] :
       {std::pair<size_t, std::string>{0, "CallerC"}, {2, "ElementE"}}) {
    auto &Signature = *Input[Index].generic_signature;
    const auto Last = Signature.rfind("T" + Prefix + "0;");
    if (Last == std::string::npos)
      throw std::runtime_error("owned covariant array fixture lost tail");
    Signature.replace(Last, Prefix.size() + 3, tail(Prefix));
  }
  auto Entry = klass(EntryName);
  Entry.access = {"public", "interface", "abstract"};
  Entry.generic_signature = "<EntryA0:Ljava/lang/Object;EntryA1:Ljava/lang/"
                            "Object;>Ljava/lang/Object;";
  Entry.external = External;
  Input.push_back(std::move(Entry));
  return Input;
}
} // namespace

