namespace {
std::vector<Class> inheritedFinalArgumentClasses(const std::string &Type,
                                                 bool Protected, bool External,
                                                 bool Range, bool Constructor) {
  auto Input = inheritedGenericAllocationClasses(Type, Protected, External,
                                                 Range, false, true);
  const std::vector<std::string> Parameters{Type, "Ljava/lang/String;"};
  auto &Read = Input[1].methods[1];
  Read.reference.parameters = Parameters;
  if (!External) {
    Read.registers = 3;
    Read.instructions = {op(0, Type == "I" ? "return" : "return-object", {1})};
    Read.code_end = 1;
  }
  auto &Caller = Input[0].methods[0];
  Caller.reference.parameters = Parameters;
  Caller.registers = 6;
  Caller.instructions = {
      Constructor ? op(0, "invoke-direct", {3}, {},
                       MethodRef{Input[3].name, "<init>", {}, "V"})
                  : op(0, "nop"),
      op(1, "new-instance", {0}, {}, Input[2].name),
      op(2, Range ? "invoke-virtual/range" : "invoke-virtual", {3, 4, 5}, {},
         MethodRef{Input[0].name, "read", Parameters, Type}),
      op(3, Type == "I" ? "move-result" : "move-result-object", {1}),
      op(4, "invoke-direct", {0, 1}, {}, Input[2].methods[0].reference),
      Constructor ? op(5, "return-void") : op(5, "return-object", {0})};
  Caller.code_end = 6;
  if (Constructor) {
    Caller.reference.name = "<init>";
    Caller.reference.returns = "V";
    Caller.access = {"public", "constructor"};
    Input[0].methods.resize(1);
  }
  return Input;
}
} // namespace

