TEST(MobileDalvikJava,
     InheritedFinalArgumentAllocationsKeepFinalAssignmentProgramCounter) {
  for (const std::string Type :
       {"I", "Ljava/lang/Object;", "[Ljava/lang/Object;", "[I"})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Before : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Type, External, Range, Before, Route}));
            auto Input = inheritedFinalArgumentClasses(Type, true, External,
                                                       Range, true);
            const FieldRef Value{Input[0].name, "value", Type};
            Input[0].fields.push_back({Value, {"public", "final"}, {}});
            auto &Caller = Input[0].methods[0];
            Caller.instructions.insert(
                Caller.instructions.begin() + (Before ? 1 : 5),
                op(0, Type == "I" ? "iput" : "iput-object", {4, 3}, {}, Value));
            for (size_t I = 0; I < Caller.instructions.size(); ++I)
              Caller.instructions[I].pc = I;
            Caller.code_end = Caller.instructions.size();
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            const auto Text = source(R, External ? 0 : 1);
            const auto Declaration = Text.find("int pc = ");
            const auto Allocation = Text.find(Before ? "pc = 2;" : "pc = 1;");
            ASSERT_NE(Declaration, std::string::npos);
            ASSERT_NE(Allocation, std::string::npos);
            EXPECT_LT(Declaration, Allocation);
            EXPECT_EQ(Text.find("int pc = ", Declaration + 1),
                      std::string::npos);
          }
}

TEST(MobileDalvikJava, InheritedFinalArgumentCallsRejectUnprovedSlots) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = inheritedFinalArgumentClasses("Ljava/lang/Object;", true,
                                                   External, true, true);
        auto &Read = Input[1].methods[1];
        auto &Caller = Input[0].methods[0];
        auto &Call = Caller.instructions[2];
        switch (Mutation) {
        case 0:
          Input[0].generic_signature =
              "<CallerA:Ljava/lang/Object;CallerB:Ljava/lang/Object;>Lfixture/"
              "Middle;";
          break;
        case 1:
          Input[3].generic_signature =
              "<MiddleA:Ljava/lang/Object;MiddleB:Ljava/lang/"
              "Object;MiddleC:Ljava/lang/Object;>Lfixture/Base;";
          break;
        case 2:
          Read.generic_signature =
              "(TBaseA;Ljava/lang/String;)Ljava/lang/Object;";
          break;
        case 3:
          Read.access.erase("final");
          break;
        case 4:
          Read.access = {"private", "final"};
          break;
        case 5:
          Read.access.insert("static");
          break;
        case 6:
          Call.opcode = "invoke-direct/range";
          break;
        case 7:
          Call.registers.pop_back();
          break;
        case 8:
          Caller.instructions[3].opcode = "move-result";
          break;
        case 9:
          Input.pop_back();
          break;
        case 10:
          Input[3].superclass = Input[0].name;
          break;
        case 11:
          Input[3].enclosing_method = Caller.reference;
          break;
        case 12:
          Input[3].access = {"public", "abstract", "interface"};
          break;
        case 13:
          Read.access.insert("bridge");
          break;
        case 14:
          Caller.reference.parameters[1] = "Ljava/lang/Object;";
          break;
        case 15:
          Read.generic_signature =
              "<MethodX:Ljava/lang/Object;>(Ljava/lang/Object;Ljava/lang/"
              "String;)Ljava/lang/Object;";
          break;
        }
        if (Mutation == 3) {
          const auto Original = Input;
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto Classes = linkClasses(Input, B);
          for (const auto &C : Original) {
            const auto &After = Classes.at(C.name);
            EXPECT_EQ(After.access, C.access);
            EXPECT_EQ(After.generic_signature, C.generic_signature);
            for (size_t I = 0; I < C.methods.size(); ++I) {
              EXPECT_EQ(After.methods[I].reference, C.methods[I].reference);
              EXPECT_EQ(After.methods[I].access, C.methods[I].access);
              EXPECT_EQ(After.methods[I].generic_signature,
                        C.methods[I].generic_signature);
              EXPECT_EQ(After.methods[I].declared_throws,
                        C.methods[I].declared_throws);
            }
          }
          const auto R = Route ? recoverJava(Classes, B) : recover(Input);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
        } else {
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input),
                       std::runtime_error);
        }
      }
}

