namespace {
std::vector<Class> concreteClassMethodClasses(const std::string &Type,
                                              unsigned Depth, bool External,
                                              bool Range,
                                              bool ReverseInterfaces) {
  const std::string Object = "Ljava/lang/Object;",
                    Ancestor = "Lfixture/ConcreteAncestor;";
  const bool Reference = Type.starts_with('L') || Type.starts_with('[');
  auto init = [&](const std::string &Parent) {
    auto M = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    M.access = {"public", "constructor"};
    return M;
  };
  auto Read = method("read", {Object}, Type, 4, {});
  Read.access = {"public"};
  if (Type == "V")
    Read.instructions = {op(0, "return-void")};
  else if (width(Type) == 2)
    Read.instructions = {op(0, "const-wide", {0}, int64_t(0)),
                         op(1, "return-wide", {0})};
  else
    Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, Reference ? "return-object" : "return", {0})};
  Read.code_end = Read.instructions.back().pc + 1;
  auto Base = klass(Ancestor, {init(Object), Read});
  Base.generic_signature = "<AncestorA:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Abstract = Read;
  Abstract.access = {"public", "abstract"};
  Abstract.instructions.clear();
  Abstract.registers = Abstract.code_end = 0;
  auto Slot = klass("Lfixture/ConcreteSlot;", {Abstract});
  Slot.access = {"public", "interface", "abstract"};
  auto Alias = klass("Lfixture/ConcreteAlias;");
  Alias.access = {"public", "interface", "abstract"};
  Alias.interfaces = {Slot.name};
  std::vector<Class> Input{Base, Slot, Alias};
  std::string Parent = Ancestor;
  for (unsigned I = 0; I < Depth; ++I) {
    auto Node = klass("Lfixture/ConcreteNode" + std::to_string(I) + ";",
                      {init(Parent)});
    Node.access.insert("abstract");
    Node.superclass = Parent;
    Node.interfaces = ReverseInterfaces
                          ? std::vector<std::string>{Alias.name, Slot.name}
                          : std::vector<std::string>{Slot.name, Alias.name};
    const auto Formal = "NodeA" + std::to_string(I);
    Node.generic_signature = "<" + Formal + ":Ljava/lang/Object;>" +
                             Parent.substr(0, Parent.size() - 1) + "<T" +
                             Formal + ";>;";
    for (const auto &Interface : Node.interfaces)
      *Node.generic_signature += Interface;
    Parent = Node.name;
    Input.push_back(std::move(Node));
  }
  auto Caller = Read;
  Caller.instructions = {op(0, Range ? "invoke-super/range" : "invoke-super",
                            {2, 3}, {},
                            MethodRef{Parent, "read", {Object}, Type})};
  if (Type != "V")
    Caller.instructions.push_back(op(1,
                                     Reference          ? "move-result-object"
                                     : width(Type) == 2 ? "move-result-wide"
                                                        : "move-result",
                                     {0}));
  Caller.instructions.push_back(
      op(Caller.instructions.size(),
         Type == "V"        ? "return-void"
         : Reference        ? "return-object"
         : width(Type) == 2 ? "return-wide"
                            : "return",
         Type == "V" ? std::vector<unsigned>{} : std::vector<unsigned>{0}));
  Caller.code_end = Caller.instructions.back().pc + 1;
  auto Core = klass("Lfixture/ConcreteChild;", {init(Parent), Caller});
  Core.access.insert("final");
  Core.superclass = Parent;
  Core.generic_signature = "<CallerA:Ljava/lang/Object;>" +
                           Parent.substr(0, Parent.size() - 1) + "<TCallerA;>;";
  if (External)
    for (auto &C : Input) {
      C.external = true;
      for (auto &M : C.methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  Input.insert(Input.begin(), std::move(Core));
  return Input;
}
} // namespace

