TEST(MobileDalvikJava,
     ClassMethodResolutionRetainsNearestAbstractAndInvalidEdges) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = concreteClassMethodClasses("Z", 2, External, false, false);
        auto &Core = Input[0];
        auto &Base = Input[1];
        auto &Near = Input.back();
        auto Override = Base.methods[1];
        Override.reference.owner = Near.name;
        switch (Mutation) {
        case 0:
          Override.access = {"public", "abstract"};
          Override.instructions.clear();
          Override.registers = Override.code_end = 0;
          Near.methods.push_back(Override);
          break;
        case 1:
          Override.reference.returns = "I";
          Near.methods.push_back(Override);
          break;
        case 2:
          Override.access = {"private"};
          Near.methods.push_back(Override);
          break;
        case 3:
          Override.access = {"public", "static"};
          Near.methods.push_back(Override);
          break;
        case 4:
          Base.methods.pop_back();
          break;
        case 5:
          Core.methods[1].instructions[0].registers = {3, 2};
          break;
        case 6:
          std::get<MethodRef>(Core.methods[1].instructions[0].reference).owner =
              "Lfixture/Missing;";
          break;
        case 7:
          Near.superclass = Core.name;
          break;
        case 8:
          Near.methods.erase(Near.methods.begin());
          break;
        case 9:
          Near.superclass = "Lfixture/Missing;";
          break;
        case 10:
          Base.access.insert("interface");
          break;
        case 11:
          Core.methods[1].instructions[1].opcode = "move-result-object";
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class>
independentPlainArraySeedClasses(unsigned Seeds, unsigned Scalars,
                                 const std::string &Scalar, unsigned Order,
                                 unsigned Provider, bool Range) {
  const std::string Object = "Ljava/lang/Object;",
                    Array = "[Ljava/lang/Object;";
  std::vector<std::pair<std::string, std::string>> Slots{{Array, Array}};
  std::string Signature = "<";
  for (unsigned I = 0; I < Seeds; ++I) {
    const auto Name = "Seed" + std::to_string(I);
    Signature += Name + ":" + Object;
    Slots.emplace_back(Object, "T" + Name + ";");
  }
  for (unsigned I = 0; I < Scalars; ++I)
    Slots.emplace_back(Scalar, Scalar);
  if (Order == 1)
    std::reverse(Slots.begin(), Slots.end());
  else if (Order == 2)
    std::rotate(Slots.begin(), Slots.begin() + 1, Slots.end());
  Signature += ">(";
  std::vector<std::string> Params;
  unsigned Words = 0, ArrayReg = 0;
  for (const auto &[Erased, Full] : Slots) {
    Params.push_back(Erased);
    Signature += Full;
    if (Erased == Array)
      ArrayReg = Words;
    Words += width(Erased);
  }
  Signature += ")" + Array;
  auto Join = method("join", Params, Array, Words,
                     {op(0, "return-object", {ArrayReg})});
  Join.access = {Provider == 0 ? "private" : "public", "static", "final"};
  Join.generic_signature = Signature;
  auto Owner =
      klass(Provider == 0 ? "Lfixture/Core;" : "Lfixture/Provider;", {Join});
  auto Caller = method("make", Params, Array, Words + 1, {});
  std::vector<unsigned> Frame;
  for (unsigned I = 1; I <= Words; ++I)
    Frame.push_back(I);
  Caller.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                            Frame, {}, Owner.methods[0].reference),
                         op(1, "move-result-object", {0}),
                         op(2, "return-object", {0})};
  Caller.code_end = 3;
  if (Provider == 0) {
    Caller.reference.owner = Owner.name;
    Owner.methods.push_back(Caller);
    return {Owner};
  }
  auto Core = klass("Lfixture/Core;", {Caller});
  if (Provider == 2) {
    Owner.external = true;
    Owner.methods[0].instructions.clear();
    Owner.methods[0].registers = Owner.methods[0].code_end = 0;
  }
  return {Core, Owner};
}
} // namespace

