namespace {
std::vector<Class> scopedStaticConstructorClasses(unsigned Seeds,
                                                  const std::string &FieldType,
                                                  bool Upcast, bool External,
                                                  bool ReverseReads,
                                                  bool Range) {
  const std::string Object = "Ljava/lang/Object;";
  const auto Context = Upcast ? Object : FieldType;
  const unsigned FieldWords = width(FieldType);
  std::vector<std::string> Inputs(Seeds, Object), Params = Inputs;
  Params.push_back(Context);
  Params.push_back(Context);
  const unsigned Words = 1 + Seeds + 2 * FieldWords;
  auto Target = method(
      "<init>", Params, "V", 1 + Seeds + 2 * width(Context),
      {op(0, "invoke-direct", {0}, {}, MethodRef{Object, "<init>", {}, "V"}),
       op(1, "return-void")});
  Target.access = {"public", "constructor"};
  std::string Full = "(", Header = "<";
  for (unsigned I = 0; I < Seeds; ++I) {
    Full += "TSeed" + std::to_string(I) + ";";
    Header += "Seed" + std::to_string(I) + ":" + Object;
  }
  Target.generic_signature = Full + Context + Context + ")V";
  auto Caller = method("<init>", Inputs, "V", Words + 1 + Seeds, {});
  Caller.access = {"public", "constructor"};
  Caller.generic_signature = Full + ")V";
  auto Core = klass("Lfixture/Core;", {Target});
  Core.generic_signature = Header + ">" + Object;
  Caller.reference.owner = Core.name;
  auto Provider = klass("Lfixture/Provider;");
  Provider.external = External;
  for (const auto *Name : {"first", "second"})
    Provider.fields.push_back(
        {{Provider.name, Name, FieldType}, {"public", "static"}, {}});
  unsigned Pc = 0;
  Caller.instructions.push_back(op(Pc++, "move-object", {0, Words}));
  for (unsigned I = 0; I < Seeds; ++I)
    Caller.instructions.push_back(
        op(Pc++, "move-object", {1 + I, Words + 1 + I}));
  const auto Opcode = FieldType.starts_with('L') || FieldType.starts_with('[')
                          ? "sget-object"
                      : FieldWords == 2  ? "sget-wide"
                      : FieldType == "Z" ? "sget-boolean"
                      : FieldType == "B" ? "sget-byte"
                      : FieldType == "C" ? "sget-char"
                      : FieldType == "S" ? "sget-short"
                                         : "sget";
  for (unsigned J = 0; J < 2; ++J) {
    const unsigned I = ReverseReads ? 1 - J : J;
    Caller.instructions.push_back(op(Pc++, Opcode, {1 + Seeds + I * FieldWords},
                                     {}, Provider.fields[I].reference));
  }
  std::vector<unsigned> Frame;
  for (unsigned I = 0; I < Words; ++I)
    Frame.push_back(I);
  Caller.instructions.push_back(
      op(Pc++, Range ? "invoke-direct/range" : "invoke-direct", Frame, {},
         Core.methods[0].reference));
  Caller.instructions.push_back(op(Pc++, "return-void"));
  Caller.code_end = Pc;
  Core.methods.push_back(Caller);
  std::vector<Class> Result{Core, Provider};
  if (FieldType == "Lfixture/Token;") {
    auto Token = klass(FieldType);
    Token.external = External;
    Result.push_back(Token);
  }
  return Result;
}
} // namespace

TEST(MobileDalvikJava, ScopedConstructorSeedsKeepClosedStaticReadSnapshots) {
  for (unsigned Seeds : {1u, 2u, 3u})
    for (const std::string Type :
         {"I", "J", "D", "Z", "B", "C", "S", "Ljava/lang/Object;",
          "[Ljava/lang/Object;", "Lfixture/Token;"})
      for (bool Upcast : {false, true}) {
        if (Upcast && (!Type.starts_with('L') || Type == "Ljava/lang/Object;"))
          continue;
        for (bool External : {false, true})
          for (bool ReverseReads : {false, true})
            for (bool Range : {false, true})
              for (unsigned Route = 0; Route < 3; ++Route) {
                if (!Range && 1 + Seeds + 2 * width(Type) > 5)
                  continue;
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{Seeds, Type, Upcast, External, ReverseReads,
                               Range, Route}));
                auto Input = scopedStaticConstructorClasses(
                    Seeds, Type, Upcast, External, ReverseReads, Range);
                const auto Target = Input[0].methods[0].reference,
                           Caller = Input[0].methods[1].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                auto Classes = Route ? linkClasses(Input, B) : ClassMap{};
                if (!Route)
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                const auto Plans = validateGenericSignatures(Classes, B);
                ASSERT_TRUE(Plans.constructor_calls.contains({Caller, Target}));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              }
      }
}

TEST(MobileDalvikJava,
     ScopedStaticConstructorContextsCannotSupplyOwnerFormals) {
  for (unsigned Seeds : {1u, 2u})
    for (bool External : {false, true})
      for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Seeds, External, Mutation, Route}));
          auto Input = scopedStaticConstructorClasses(
              Seeds, "Ljava/lang/Object;", false, External, false, true);
          auto &Core = Input[0];
          auto &Target = Core.methods[0];
          auto &Caller = Core.methods[1];
          auto &Field = Input[1].fields[0];
          const unsigned Read = Seeds + 1, Call = Read + 2;
          switch (Mutation) {
          case 0:
            Field.access.erase("static");
            break;
          case 1:
            Input[1].fields.erase(Input[1].fields.begin());
            break;
          case 2:
            Field.generic_signature = "TUnknown;";
            break;
          case 3:
            Caller.instructions[Read].opcode = "sget-wide";
            break;
          case 4: {
            auto &Sig = *Target.generic_signature;
            const auto At = Sig.find("Ljava/lang/Object;");
            Sig.replace(At, 18, "TSeed0;");
            break;
          }
          case 5: {
            auto &Sig = *Caller.generic_signature;
            const auto At = Sig.find("TSeed0;");
            Sig.replace(At, 7, "Ljava/lang/Object;");
            break;
          }
          case 6:
            Target.generic_signature =
                "<Method:Ljava/lang/Object;>" + *Target.generic_signature;
            break;
          case 7:
            Target.access.insert("varargs");
            break;
          case 8:
            Target.access.insert("static");
            break;
          case 9:
            Caller.instructions[Call].opcode = "invoke-virtual/range";
            break;
          case 10:
            Caller.instructions[Call].registers[0] = 1;
            break;
          case 11:
            Caller.instructions[Read].registers[0] =
                Caller.registers - Caller.incomingWords();
            break;
          case 12:
            Field.access.erase("public");
            Field.access.insert("private");
            break;
          case 13:
            Input.pop_back();
            break;
          case 14:
            Core.generic_signature->replace(
                Core.generic_signature->find("Ljava/lang/Object;"), 18,
                "Ljava/lang/Number;");
            break;
          case 15:
            Target.declared_throws =
                std::vector<std::string>{"Ljava/lang/Exception;"};
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input),
                       std::runtime_error);
        }
}

namespace {
std::vector<Class> formalGetterSuperClasses(unsigned Arity, unsigned Selected,
                                            bool Reordered, bool Range,
                                            bool External) {
  auto Input = scopedGetterSuperClasses(Arity, Reordered, Range, External);
  auto &Getter = Input[2].methods[0];
  Getter.reference.returns = "Ljava/lang/Object;";
  Getter.generic_signature = "()TP" + std::to_string(Selected) + ";";
  Getter.access.insert("final");
  auto &Parent = Input[1].methods[0];
  Parent.reference.parameters[0] = "Ljava/lang/Object;";
  auto &Sig = *Parent.generic_signature;
  const auto End = Sig.find(';', Sig.find("Lfixture/Node<"));
  const auto Close = Sig.find(">;", End);
  Sig.replace(1, Close + 2 - 1, "TB" + std::to_string(Selected) + ";");
  auto &Child = Input[0].methods[0];
  Child.instructions[1].reference = Getter.reference;
  for (auto &Op : Child.instructions)
    if (const auto *Ref = std::get_if<MethodRef>(&Op.reference);
        Ref && Ref->name == "<init>" && Ref->owner == Input[1].name)
      Op.reference = Parent.reference;
  return Input;
}
} // namespace

