namespace {
std::vector<Class> closedGetterUpcastClasses(unsigned Arity, unsigned Selected,
                                             unsigned Depth, bool ReverseReads,
                                             bool External, bool Range) {
  const std::string Object = "Ljava/lang/Object;",
                    TokenName = "Lfixture/Token;",
                    MappingName = "Lfixture/Mapping;",
                    LeafName = "Lfixture/Leaf;";
  const auto formals = [](const std::string &Prefix, unsigned Count) {
    std::string S = "<";
    for (unsigned I = 0; I < Count; ++I)
      S += Prefix + std::to_string(I) + ":Ljava/lang/Object;";
    return S + ">";
  };
  const auto use = [](const std::string &Name, const std::string &Prefix,
                      unsigned Count) {
    std::string S = Name.substr(0, Name.size() - 1) + "<";
    for (unsigned I = 0; I < Count; ++I)
      S += "T" + Prefix + std::to_string(I) + ";";
    return S + ">;";
  };
  const auto mixed = [&](const std::string &Name, const std::string &Prefix) {
    return Name.substr(0, Name.size() - 1) + "<T" + Prefix +
           std::to_string(Selected) + ";" + TokenName + ">;";
  };
  auto First =
      method("first", {}, Object, 2,
             {op(0, "const/4", {0}, int64_t{0}), op(1, "return-object", {0})});
  First.access = {"public", "final"};
  auto Fetch = First;
  Fetch.reference.name = "mapping";
  Fetch.reference.returns = LeafName;
  Fetch.generic_signature = "()" + mixed(LeafName, "P");
  auto Provider = klass("Lfixture/Provider;", {First, Fetch});
  Provider.generic_signature = formals("P", Arity) + Object;
  const MethodRef RootInit{Object, "<init>", {}, "V"};
  auto Init =
      method("<init>", {Object, MappingName}, "V", 3,
             {op(0, "invoke-direct", {0}, {}, RootInit), op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(" + Object + mixed(MappingName, "B") + ")V";
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.generic_signature = formals("B", Arity) + Object;
  auto Ctor = method("<init>", {Provider.name}, "V", 5, {});
  Ctor.access = Init.access;
  Ctor.generic_signature = "(" + use(Provider.name, "C", Arity) + ")V";
  uint32_t Pc = 0;
  Ctor.instructions.push_back(op(Pc++, "nop"));
  for (unsigned J = 0; J < 2; ++J) {
    const auto I = ReverseReads ? 1 - J : J;
    Ctor.instructions.push_back(
        op(Pc++, Range ? "invoke-virtual/range" : "invoke-virtual", {4}, {},
           Provider.methods[I].reference));
    Ctor.instructions.push_back(op(Pc++, "move-result-object", {I ? 2u : 1u}));
    if (I)
      Ctor.instructions.push_back(op(Pc++, "check-cast", {2}, {}, MappingName));
  }
  Ctor.instructions.push_back(op(Pc++, "move-object", {0, 3}));
  Ctor.instructions.push_back(op(
      Pc++, Range ? "invoke-direct/range" : "invoke-direct",
      Range ? std::vector<unsigned>{0, 1, 2} : std::vector<unsigned>{3, 1, 2},
      {}, Parent.methods[0].reference));
  Ctor.instructions.push_back(op(Pc++, "return-void"));
  Ctor.code_end = Pc;
  auto Child = klass("Lfixture/Child;", {Ctor});
  Child.superclass = Parent.name;
  Child.generic_signature = formals("C", Arity) + use(Parent.name, "C", Arity);
  auto Mapping = klass(MappingName);
  Mapping.access = {"public", "interface", "abstract"};
  Mapping.generic_signature = formals("M", 2) + Object;
  std::vector<Class> Result{Child, Parent, Provider, Mapping, klass(TokenName)};
  for (unsigned I = 0; I <= Depth; ++I) {
    const auto Name =
        I ? "Lfixture/Middle" + std::to_string(I) + ";" : LeafName;
    const auto Next = "Lfixture/Middle" + std::to_string(I + 1) + ";";
    auto Node = klass(Name);
    Node.generic_signature = formals("L", 2);
    if (I == Depth) {
      Node.interfaces = {MappingName};
      Node.generic_signature =
          *Node.generic_signature + Object + use(MappingName, "L", 2);
    } else {
      Node.superclass = Next;
      Node.generic_signature = *Node.generic_signature + use(Next, "L", 2);
    }
    auto Constructor = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {},
            MethodRef{Node.superclass.value_or(Object), "<init>", {}, "V"}),
         op(1, "return-void")});
    Constructor.access = {"public", "constructor"};
    Constructor.reference.owner = Node.name;
    Node.methods = {Constructor};
    Result.push_back(Node);
  }
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = Init.access;
  auto Root = klass(Object, {ObjectInit});
  Root.external = true;
  Root.superclass.reset();
  Result.push_back(Root);
  if (External)
    for (size_t I = 1; I < Result.size(); ++I) {
      Result[I].external = true;
      for (auto &M : Result[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Result;
}
} // namespace

