        case 16:
          Ctor.instructions[3].registers[0] = 0;
          break;
        case 17:
          Ctor.instructions[4].opcode = "move-result";
          break;
        case 18:
          Input[4].access.erase("public");
          Input[4].access.insert("private");
          break;
