namespace {
std::vector<Class> scalarSuperclassGetterClasses(const std::string &Scalar,
                                                 bool PlainHeader, bool Range,
                                                 bool ReverseMethods) {
  auto Input = superclassIntegerGetterClasses();
  Input.resize(2);
  for (auto &C : Input) {
    if (PlainHeader)
      C.generic_signature.reset();
    for (auto &M : C.methods) {
      if (M.reference.name == "<init>")
        continue;
      M.reference.returns = Scalar;
      if (C.external)
        continue;
      const unsigned Words = width(Scalar), Self = Words;
      M.registers = Words + 1;
      for (auto &Op : M.instructions) {
        if (auto *Call = std::get_if<MethodRef>(&Op.reference)) {
          Call->returns = Scalar;
          Op.registers = {Self};
          if (Range)
            Op.opcode += "/range";
        }
        if (Op.opcode == "move-result")
          Op.opcode = Words == 2 ? "move-result-wide" : "move-result";
        if (Op.opcode == "return")
          Op.opcode = Words == 2 ? "return-wide" : "return";
      }
    }
  }
  for (auto &M : Input[1].methods)
    for (auto &Op : M.instructions)
      if (auto *Call = std::get_if<MethodRef>(&Op.reference);
          Call && Call->owner == Input[0].name && Call->name != "<init>")
        *Call = Input[0].methods[1].reference;
  if (ReverseMethods)
    for (auto &C : Input)
      std::reverse(C.methods.begin(), C.methods.end());
  return Input;
}
} // namespace

