TEST(MobileDalvikJava,
     ScalarSuperBridgesRejectUnknownTargetsFlagsAndBrokenWords) {
  for (const std::string Scalar : {"I", "J"})
    for (bool PlainHeader : {false, true})
      for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Scalar, PlainHeader, Mutation, Route}));
          auto Input =
              scalarSuperclassGetterClasses(Scalar, PlainHeader, false, false);
          auto &Getter = Input[1].methods[1];
          auto &Wrapper = Input[1].methods[2];
          switch (Mutation) {
          case 0:
            Getter.instructions[0].opcode = "invoke-virtual";
            break;
          case 1:
            Getter.instructions[0].registers = {0};
            break;
          case 2:
            Getter.instructions[1].registers = {Getter.registers -
                                                (Scalar == "I" ? 1u : 2u)};
            Getter.instructions[2].registers = Getter.instructions[1].registers;
            break;
          case 3:
            Getter.instructions[1].opcode = "move-result-object";
            break;
          case 4:
            Getter.instructions[2].opcode = "return-object";
            break;
          case 5:
            Input[0].methods[1].access.insert("abstract");
            break;
          case 6:
            Input[0].methods[1].access.insert("static");
            break;
          case 7:
            Input[0].methods[1].generic_signature = "()" + Scalar;
            break;
          case 8:
            Wrapper.access.erase("final");
            break;
          case 9:
            Wrapper.instructions[0].opcode = "invoke-super";
            break;
          case 10:
            Wrapper.instructions[1].registers = {Wrapper.registers - 1};
            break;
          case 11:
            Getter.generic_signature = "()" + Scalar;
            break;
          case 12:
            Getter.declared_throws =
                std::vector<std::string>{"Ljava/lang/Exception;"};
            break;
          case 13:
            Input[1].enclosing_method =
                MethodRef{"Lfixture/Outer;", "host", {}, "V"};
            break;
          case 14:
            Input[0].methods[1].reference.returns = Scalar == "I" ? "J" : "I";
            break;
          case 15:
            Getter.instructions[0].reference =
                MethodRef{"Lfixture/Missing;", "items", {}, Scalar};
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input),
                       std::runtime_error);
        }
}

TEST(MobileDalvikJava, PlainScalarFamiliesRetainOrdinaryNarrowingBridgeSlots) {
  for (const std::string Scalar : {"B", "C", "S", "I", "J", "F", "D"})
    for (bool Range : {false, true})
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Scalar, Range, Route}));
        auto Input = scalarSuperclassGetterClasses("I", true, Range, false);
        auto Contract = method("narrow", {}, Scalar, 0, {});
        Contract.access = {"public"};
        Contract.reference.owner = Input[0].name;
        Input[0].methods.push_back(Contract);
        const unsigned Words = width(Scalar), Self = Words;
        auto Getter = method("getNarrow", {}, Scalar, Words + 1, {});
        Getter.access = {"public"};
        Getter.reference.owner = Input[1].name;
        Getter.instructions = {
            op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {Self}, {},
               Input[1].methods[2].reference),
            op(1, "move-result", {0})};
        if (Scalar != "I")
          Getter.instructions.push_back(op(2,
                                           Scalar == "B"   ? "int-to-byte"
                                           : Scalar == "C" ? "int-to-char"
                                           : Scalar == "S" ? "int-to-short"
                                           : Scalar == "J" ? "int-to-long"
                                           : Scalar == "F" ? "int-to-float"
                                                           : "int-to-double",
                                           {0, 0}));
        Getter.instructions.push_back(op(Getter.instructions.size(),
                                         Words == 2 ? "return-wide" : "return",
                                         {0}));
        Getter.code_end = Getter.instructions.size();
        auto Bridge =
            method("narrow", {}, Scalar, Words + 1,
                   {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                       {Self}, {}, Getter.reference),
                    op(1, Words == 2 ? "move-result-wide" : "move-result", {0}),
                    op(2, Words == 2 ? "return-wide" : "return", {0})});
        Bridge.reference.owner = Input[1].name;
        Bridge.access = {"public", "final", "bridge"};
        Input[1].methods.push_back(Getter);
        Input[1].methods.push_back(Bridge);
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        const auto R =
            Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("method_count"), 5);
        EXPECT_EQ(R.getInteger("projected_method_count"), 3);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      }
}

std::vector<Class> closedContextArrayFactoryClasses(bool External, bool Facade,
                                                    bool Range, bool ArrayFirst,
                                                    unsigned Contexts,
                                                    const std::string &Scalar) {
  auto Input = arraySeedFactoryClasses(External, Facade, Range);
  auto Context = klass("Lfixture/RangeContext;");
  Context.external = true;
  Input.push_back(Context);
  auto &Make = Input[1].methods[0];
  std::vector<std::string> Slots(Contexts, Context.name);
  Slots.push_back(Scalar);
  Slots.insert(ArrayFirst ? Slots.begin() : Slots.end(), "[TT;");
  Make.reference.parameters.clear();
  Make.generic_signature = "<T:Ljava/lang/Object;>(";
  unsigned Words = 0;
  for (const auto &Slot : Slots) {
    *Make.generic_signature += Slot;
    Make.reference.parameters.push_back(Slot == "[TT;" ? "[Ljava/lang/Object;"
                                                       : Slot);
    Words += width(Make.reference.parameters.back());
  }
  *Make.generic_signature += ")Lfixture/Box<TT;>;";
  if (!External) {
    Make.registers = Words + 1;
    Make.instructions = {op(0, "const/4", {0}, int64_t{0}),
                         op(1, "return-object", {0})};
    Make.code_end = 2;
  }
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  std::vector<unsigned> Arguments;
  for (unsigned I = 1; I <= Words; ++I)
    Arguments.push_back(I);
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, Words + 1,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        Arguments, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return Input;
}

