TEST(MobileDalvikJava,
     ArrayContextFactoriesRejectOpenScopesAndChangedContracts) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 14; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = closedContextArrayFactoryClasses(External, true, true,
                                                      true, 1, "J");
        auto &Make = Input[1].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &S = *Make.generic_signature;
          const auto I = S.find(From);
          if (I == std::string::npos)
            throw std::runtime_error(
                "closed array context fixture anchor missing");
          S.replace(I, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          replace("[TT;", "[TU;");
          break;
        case 1:
          replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 2:
          replace(";>(", ";U:Ljava/lang/Object;>(");
          break;
        case 3:
          replace("Lfixture/RangeContext;", "TT;");
          break;
        case 4:
          Input.back().generic_signature =
              "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 5:
          Input.back().access.erase("public");
          break;
        case 6:
          Input.pop_back();
          break;
        case 7:
          replace("Box<TT;>", "Box<+TT;>");
          break;
        case 8:
          replace("Box<TT;>", "Box<Ljava/lang/Object;>");
          break;
        case 9:
          Make.access.insert("bridge");
          break;
        case 10:
          Make.access = {"private", "static"};
          break;
        case 11:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 12:
          replace("[TT;", "[[TT;");
          break;
        case 13:
          replace("Lfixture/RangeContext;", "Lfixture/RangeContext<TT;>;");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

