std::vector<Class> closedMapBuilderClasses(bool ExternalRoot,
                                           bool ExternalBuilder, bool Projected,
                                           bool Range, bool Nested) {
  auto Input = Projected ? guardedDefaultResultClasses(ExternalRoot, true)
                         : checkedReferenceSuperAdapterClasses(ExternalRoot);
  auto &Snapshot = Input[1];
  const std::string Prefix = "<T:Ljava/lang/Object;>";
  Snapshot.generic_signature->erase(0, Prefix.size());
  auto close = [](std::string &Text) {
    for (size_t At = 0; (At = Text.find("TT;", At)) != std::string::npos;)
      Text.replace(At, 3, "Ljava/lang/Object;");
  };
  close(*Snapshot.generic_signature);
  for (auto &M : Snapshot.methods)
    if (M.generic_signature)
      close(*M.generic_signature);
  // A declaration-only SDK builder must have its SDK ancestor declarations
  // in the same boundary, just as the separately compiled runtime provider.
  if (ExternalBuilder)
    for (const auto I : {0u, 4u, 5u}) {
      Input[I].external = true;
      for (auto &M : Input[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  const auto SnapshotName = Snapshot.name;
  const auto CarrierName = Input[5].name;
  const std::string Value = "Lfixture/Holder<Ljava/lang/Object;>;";
  const MethodRef ObjectInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Init = method("<init>", {CarrierName}, "V", ExternalBuilder ? 0 : 2, {});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Lfixture/GuardMiddle<TB;>;)V";
  if (!ExternalBuilder) {
    Init.instructions = {op(0, "invoke-direct", {0}, {},
                            MethodRef{CarrierName, "<init>", {}, "V"}),
                         op(1, "return-void")};
    Init.code_end = 2;
  }
  auto Parent = klass("Lfixture/MapBuilder;", {Init});
  Parent.external = ExternalBuilder;
  Parent.superclass = CarrierName;
  Parent.generic_signature = "<B:Ljava/lang/Object;>Lfixture/GuardMiddle<TB;>;";
  const auto ParentInit = Parent.methods[0].reference;
  if (Projected) {
    auto Get = Input[4].methods[1];
    Get.reference.owner = Parent.name;
    auto &Sig = *Get.generic_signature;
    for (size_t At = 0; (At = Sig.find("TR;", At)) != std::string::npos;)
      Sig.replace(At, 3, "TB;");
    if (ExternalBuilder) {
      Get.instructions.clear();
      Get.registers = Get.code_end = 0;
    } else {
      Get.registers = 4;
      Get.instructions = {op(0, "return-object", {3})};
      Get.code_end = 1;
    }
    Parent.methods.push_back(Get);
  }
  const auto BuilderName =
      Nested ? SnapshotName.substr(0, SnapshotName.size() - 1) + "$Builder;"
             : "Lfixture/ClosedBuilder;";
  const FieldRef Saved{BuilderName, "snapshot", SnapshotName};
  auto Build =
      method("<init>", {SnapshotName}, "V", 3,
             {op(0, "nop"), op(1, "move-object", {0, 2}),
              op(2, "check-cast", {0}, {}, CarrierName),
              op(4, Range ? "invoke-direct/range" : "invoke-direct", {1, 0}, {},
                 ParentInit),
              op(7, "iput-object", {2, 1}, {}, Saved), op(9, "return-void")});
  Build.access = {"public", "constructor"};
  if (Range) {
    Build.registers = 4;
    Build.instructions = {op(0, "nop"),
                          op(1, "move-object", {0, 2}),
                          op(2, "move-object", {1, 3}),
                          op(3, "check-cast", {1}, {}, CarrierName),
                          op(5, "invoke-direct/range", {0, 1}, {}, ParentInit),
                          op(8, "iput-object", {3, 2}, {}, Saved),
                          op(10, "return-void")};
    Build.code_end = 11;
  }
  auto Builder = klass(BuilderName, {Build});
  Builder.access = {"public", "final"};
  Builder.superclass = Parent.name;
  Builder.generic_signature = "Lfixture/MapBuilder<" + Value + ">;";
  Builder.fields.push_back({Saved, {"public", "final"}, {}});
  if (Nested) {
    Builder.enclosing = SnapshotName;
    Builder.inner_class_present = true;
    Builder.inner_name = "Builder";
    Builder.inner_access = {"public", "static", "final"};
  }
  if (Projected) {
    Builder.interfaces = Input[1].interfaces;
    *Builder.generic_signature += "Lfixture/CountView<" + Value + ">;";
    for (auto M : Input[1].methods) {
      if (M.reference.name != "getOrDefault")
        continue;
      M.reference.owner = BuilderName;
      for (auto &I : M.instructions)
        if (auto *Ref = std::get_if<MethodRef>(&I.reference)) {
          if (Ref->owner == SnapshotName)
            Ref->owner = BuilderName;
          if (I.opcode == "invoke-super")
            Ref->owner = Parent.name;
        }
      Builder.methods.push_back(std::move(M));
    }
  }
  Input.push_back(Parent);
  Input.push_back(Builder);
  return Input;
}

