TEST(MobileDalvikJava, NullaryClosedTailFactoriesRejectUnprovedResultSlots) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input =
            nullaryClosedTailFactoryClasses(External, true, true, false);
        auto &Make = Input[1].methods[0];
        auto replace = [&](const std::string &From, const std::string &To) {
          auto &S = *Make.generic_signature;
          const auto At = S.find(From);
          if (At == std::string::npos)
            throw std::runtime_error("closed-tail model anchor missing");
          S.replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 1:
          replace(";>()", ";U:Ljava/lang/Object;>()");
          break;
        case 2:
          replace("Box<TT;", "Box<+TT;");
          break;
        case 3:
          replace("Box<TT;", "Box<-TT;");
          break;
        case 4:
          replace("Box<TT;", "Box<Ljava/lang/Object;");
          break;
        case 5:
          replace("TT;Ljava/lang/Object;", "TT;TT;");
          break;
        case 6:
          replace("TT;Ljava/lang/Object;", "TT;+Ljava/lang/Object;");
          break;
        case 7:
          replace("TT;Ljava/lang/Object;", "TT;Ljava/lang/String;");
          break;
        case 8:
          replace("TT;Ljava/lang/Object;", "Ljava/lang/Object;TT;");
          break;
        case 9:
          Input[5].generic_signature =
              "<A:Ljava/lang/Object;B:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 10:
          Input[5].generic_signature =
              "<A:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 11:
          Input[5].access.erase("public");
          break;
        case 12:
          Make.access.insert("varargs");
          break;
        case 13:
          Make.access.insert("native");
          Make.instructions.clear();
          break;
        case 14:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 15:
          Make.access = {"private", "static"};
          break;
        }
        const auto Original = Make;
        const auto ResultHeader = Input[5].generic_signature;
        const auto ResultName = Input[5].name;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Mutation == 5) {
          // The newly supported exact pair repeats this method's own formal.
          // Keep every original declaration and the other rejection variants.
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          EXPECT_TRUE(
              validateGenericSignatures(Classes, B)
                  .erased_generic_invocations.contains(Original.reference));
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          const auto &After = Classes.at(Original.reference.owner).methods[0];
          EXPECT_EQ(After.generic_signature, Original.generic_signature);
          EXPECT_EQ(After.access, Original.access);
          EXPECT_EQ(After.declared_throws, Original.declared_throws);
          EXPECT_EQ(Classes.at(ResultName).generic_signature, ResultHeader);
          continue;
        }
        EXPECT_THROW(
            [&] {
              if (Route)
                recoverJava(linkClasses(Input, B), B);
              else
                recover(Input);
            }(),
            std::runtime_error);
      }
}

std::vector<Class> contextualClosedTailClasses(bool External, bool Facade,
                                               bool Range, bool Swapped,
                                               bool TailInterface) {
  auto Input = erasedFactoryInvocationClasses(External, Facade, true);
  Input[1].access.insert("public");
  auto Context = klass("Lfixture/Context;");
  auto Tail = klass("Lfixture/Tail;");
  if (TailInterface)
    Tail.access = {"public", "abstract", "interface"};
  Context.external = Tail.external = External;
  Input.push_back(Context);
  Input.push_back(Tail);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters =
      Swapped ? std::vector<std::string>{Context.name, Input[4].name}
              : std::vector<std::string>{Input[4].name, Context.name};
  const std::string Producer = "Lfixture/Factory<TT;>;";
  Make.generic_signature =
      std::string("<T:Ljava/lang/Object;>(") +
      (Swapped ? Context.name + Producer : Producer + Context.name) +
      ")Lfixture/Box<TT;Lfixture/Tail;>;";
  if (!External)
    Make.registers = 3;
  Input[5].generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] =
      klass("Lfixture/Client;",
            {method("call", Ref.parameters, Ref.returns, 3,
                    {op(0, Range ? "invoke-static/range" : "invoke-static",
                        {1, 2}, {}, Ref),
                     op(1, "move-result-object", {0}),
                     op(2, "return-object", {0})})});
  return Input;
}

