TEST(MobileDalvikJava,
     AnchoredClosedHeadFactoriesRejectLostAnchorsAndOpenResultSlots) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
      SCOPED_TRACE(External);
      SCOPED_TRACE(Mutation);
      auto Input = anchoredClosedHeadFactoryClasses(External, true, true, true);
      auto &Make = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Make.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("Factory<TT;>", "Factory<+TT;>");
      else if (Mutation == 1)
        replace("Factory<TT;>", "Factory<*>");
      else if (Mutation == 2)
        replace("Box<Ljava/lang/Object;TT;>", "Box<Ljava/lang/Object;+TT;>");
      else if (Mutation == 3)
        replace("Box<Ljava/lang/Object;TT;>", "Box<+Ljava/lang/Object;TT;>");
      else if (Mutation == 4) {
        Input[7].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
        replace("Box<Ljava/lang/Object;", "Box<Lfixture/Tail<*>;");
      } else if (Mutation == 5)
        replace("Box<Ljava/lang/Object;TT;>", "Box<Ljava/lang/Object;*>");
      else if (Mutation == 6) {
        replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        replace("Box<Ljava/lang/Object;TT;>", "Box<Ljava/lang/Object;TU;>");
      } else if (Mutation == 7) {
        Input[1].generic_signature = "<C:Lfixture/Tail;>Ljava/lang/Object;";
        replace("Lfixture/Tail;Lfixture/Context;", "TC;Lfixture/Context;");
      } else if (Mutation == 8)
        Input.pop_back();
      else if (Mutation == 9)
        Input[8].generic_signature = "<E:Lfixture/Tail;>Ljava/lang/Object;";
      else if (Mutation == 10)
        Input[5].generic_signature =
            "<A:Ljava/lang/Object;B:Lfixture/Tail;>Ljava/lang/Object;";
      else if (Mutation == 11)
        Make.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 12)
        Make.access.insert("varargs");
      else
        Make.access = {"private", "static"};
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

TEST(MobileDalvikJava, StaticSyntheticReturnSlotsKeepBodiesAndReportBothFlags) {
  for (bool Generic : {false, true})
    for (bool Range : {false, true})
      for (unsigned Mask = 1; Mask < 4; ++Mask)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Generic, Range, Mask, Route}));
          auto Input = staticReturnOverloadClasses(Generic, Range, false);
          for (unsigned I = 0; I < 2; ++I)
            if (Mask & (1u << I))
              Input[0].methods[I].access.insert("synthetic");
          if (Route == 2) {
            std::reverse(Input[0].methods.begin(), Input[0].methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), (Mask & 1) ? 2 : 1);
          unsigned Named = 0, Flags = 0;
          for (const auto &Row : *R.getArray("methods")) {
            const auto &M = *Row.getAsObject();
            const auto Ref = M.getString("identity")->str();
            const bool GenericSlot =
                Ref.ends_with("select(Lfixture/Box;J)Ljava/lang/Object;");
            const bool NominalSlot =
                Ref.ends_with("select(Lfixture/Box;J)Lfixture/Box;");
            if (M.getString("source_name")) {
              ++Named;
              EXPECT_TRUE(NominalSlot);
              EXPECT_EQ(M.getString("projection_kind"),
                        "incompatible-static-return-slot");
              EXPECT_EQ(M.getString("source_name"),
                        "__neverdStaticReturnSlot_");
            }
            if ((GenericSlot && (Mask & 1)) || (NominalSlot && (Mask & 2))) {
              ++Flags;
              EXPECT_EQ(M.getString("status"), "source-projected");
              const auto *Differences = M.getArray("metadata_differences");
              ASSERT_NE(Differences, nullptr);
              EXPECT_TRUE(std::any_of(Differences->begin(), Differences->end(),
                                      [](const auto &Value) {
                                        return Value.getAsString()->contains(
                                            "synthetic access flag");
                                      }));
              if (GenericSlot)
                EXPECT_EQ(M.getString("projection_kind"),
                          "synthetic-static-return-slot");
            }
          }
          EXPECT_EQ(Named, 1u);
          EXPECT_EQ(Flags, Mask == 3 ? 2u : 1u);
        }
}

std::vector<Class> privatePairTransferClasses(bool CarrierSDK, bool Range,
                                              unsigned Variance, bool Final) {
  auto Input = flatPairTransferClasses(false, false, Range);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  Make.access = {"private", "static"};
  if (Final)
    Make.access.insert("final");
  Make.generic_signature =
      std::string(
          "<K:Ljava/lang/Object;V:Ljava/lang/Object;>(Lfixture/Input<") +
      (Variance & 1 ? "+TK;" : "TK;") + (Variance & 2 ? "+TV;" : "TV;") +
      ">;)Lfixture/Box<TK;TV;>;";
  auto Wrapper = Input[0].methods[0];
  Wrapper.reference.owner = Owner.name;
  Wrapper.reference.name = "call";
  Owner.methods.push_back(Wrapper);
  std::get<MethodRef>(Input[0].methods[0].instructions[0].reference) =
      Wrapper.reference;
  for (auto &C : Input)
    if (C.name == "Lfixture/Input;" || C.name == "Lfixture/Box;")
      C.external = CarrierSDK;
  return Input;
}

