std::vector<Class> allocatedBinaryCallbackClasses(bool ExternalParent,
                                                  bool ExternalCarrier,
                                                  bool Graph, unsigned Style) {
  auto Input = allocatedScopedCallbackClasses(ExternalParent, ExternalCarrier,
                                              true, true, false, 0);
  auto &Base = Input[0];
  auto &Child = Input[1];
  auto &Callback = Input[2];
  auto &Adapter = Input[3];
  const auto &Marker = Input[4];
  Callback.generic_signature =
      "<T:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Graph) {
    Callback.interfaces = {Marker.name};
    *Callback.generic_signature += "Lfixture/Marker<TR;>;";
  }
  auto Token = klass("Lfixture/Token;");
  auto State = klass("Lfixture/State;");
  Token.external = State.external = ExternalCarrier;
  const bool Wide = Style == 2;
  const bool Range = Style != 0;
  const std::string Scalar = Wide ? "J" : "I";
  const unsigned Words = Wide ? 2 : 1;
  auto &ParentInit = Base.methods[0];
  Base.generic_signature.reset();
  ParentInit.reference.parameters = {Scalar, State.name, Callback.name,
                                     Callback.name};
  ParentInit.generic_signature =
      "(" + Scalar + State.name +
      "Lfixture/Callback<Ljava/lang/Object;Lfixture/Token;>;"
      "Lfixture/Callback<Ljava/lang/Object;Lfixture/Token;>;)V";
  if (!ExternalParent)
    ParentInit.registers = Words + 4;
  const unsigned Self = Words + 4;
  const unsigned Alloc = Self - 1, Null = Self - 2;
  std::vector<unsigned> Arguments;
  for (unsigned I = 0; I < Self; ++I)
    Arguments.push_back(I);
  auto Init = method(
      "<init>", {Scalar, State.name}, "V", Self + Words + 2,
      {op(0, "nop"), op(1, "new-instance", {Alloc}, {}, Adapter.name),
       op(2, Range ? "invoke-direct/range" : "invoke-direct", {Alloc}, {},
          Adapter.methods[0].reference),
       op(3, "const/4", {Null}, int64_t{0}), op(4, "move-object", {0, Self}),
       op(5, Wide ? "move-wide" : "move", {1, Self + 1}),
       op(6, "move-object", {1 + Words, Self + 1 + Words}),
       op(7, Range ? "invoke-direct/range" : "invoke-direct", Arguments, {},
          ParentInit.reference),
       op(8, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Child.name;
  Child.generic_signature.reset();
  Child.methods = {Init};
  Input.push_back(Token);
  Input.push_back(State);
  return Input;
}

TEST(MobileDalvikJava,
     AllocatedBinaryCallbacksKeepClosedSlotsAndSubsetParents) {
  for (bool ExternalParent : {false, true})
    for (bool ExternalCarrier : {false, true})
      for (bool Graph : {false, true})
        for (unsigned Style = 0; Style < 3; ++Style)
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(std::tuple{
                ExternalParent, ExternalCarrier, Graph, Style, Route}));
            auto Input = allocatedBinaryCallbackClasses(
                ExternalParent, ExternalCarrier, Graph, Style);
            const auto Caller = Input[1].methods[0].reference;
            const auto Target = Input[0].methods[0].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            if (Route)
              Classes = linkClasses(Input, B);
            else
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_FALSE(Classes.at(Caller.owner).generic_signature);
            EXPECT_FALSE(Classes.at(Caller.owner).methods[0].generic_signature);
          }
}

TEST(MobileDalvikJava, AllocatedBinaryCallbacksRejectUnknownGraphsAndOrigins) {
  for (unsigned Mutation = 0; Mutation < 14; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = allocatedBinaryCallbackClasses(false, false, true, 2);
      auto &Callback = Input[2];
      auto &Adapter = Input[3];
      auto &Marker = Input[4];
      switch (Mutation) {
      case 0:
        Callback.generic_signature =
            "<T:Ljava/lang/Number;R:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Marker<TR;>;";
        break;
      case 1:
        Marker.generic_signature = "<M:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 2:
        Callback.generic_signature =
            "<T:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Marker;";
        break;
      case 3:
        Callback.generic_signature =
            "<T:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Marker<Ljava/lang/Object;>;";
        break;
      case 4:
        Callback.generic_signature =
            "<T:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Marker<+TR;>;";
        break;
      case 5:
        Callback.access.erase("public");
        break;
      case 6:
        Adapter.generic_signature = "Ljava/lang/Object;Lfixture/Callback;";
        break;
      case 7:
        Adapter.interfaces.clear();
        break;
      case 8:
        Adapter.methods[0].access = {"private", "constructor"};
        break;
      case 9:
        Adapter.methods[0].generic_signature = "<X:Ljava/lang/Object;>()V";
        break;
      case 10: {
        auto Other = Input[0].methods[0];
        Other.reference.parameters.back() = "Ljava/lang/Object;";
        Other.generic_signature.reset();
        Input[0].methods.push_back(Other);
        break;
      }
      case 11:
        Marker.interfaces = {Callback.name};
        Marker.generic_signature = "<M:Ljava/lang/Object;>Ljava/lang/"
                                   "Object;Lfixture/Callback<TM;TM;>;";
        break;
      case 12:
        Input[1].methods[0].instructions[2] = op(2, "nop");
        break;
      case 13:
        Input[1].methods[0].instructions[5].opcode = "move-object";
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      EXPECT_THROW(
          [&] {
            if (Route)
              recoverJava(linkClasses(Input, B), B);
            else
              recover(Input);
          }(),
          std::runtime_error);
    }
}

std::vector<Class> privateSeededVoidClasses(bool SDK, bool Range, bool Aux,
                                            bool Contra, bool Covariant) {
  auto Input = seededVoidCarrierClasses(false, false, Range, 0);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  Make.access = {"private", "static", "final"};
  if (!Aux) {
    auto Context = klass("Lfixture/Context;");
    Context.access = {"public", "abstract", "interface"};
    Context.external = SDK;
    Input.push_back(Context);
    Make.reference.parameters = {Context.name, "Ljava/lang/Object;",
                                 Input[4].name};
    Make.generic_signature =
        std::string(
            "<T:Ljava/lang/Object;>(Lfixture/Context;TT;Lfixture/Factory<") +
        (Contra ? "-TT;" : "TT;") +
        (Covariant ? "+Lfixture/Token;" : "Lfixture/Token;") + ">;)V";
    Make.registers = 3;
  }
  for (auto &C : Input)
    if (C.name == "Lfixture/Factory;" || C.name == "Lfixture/Box;" ||
        C.name == "Lfixture/Token;")
      C.external = SDK;
  auto Ref = Make.reference;
  auto Wrapper = method("call", Ref.parameters, "V", Ref.parameters.size(), {});
  std::vector<unsigned> Args;
  for (unsigned I = 0; I < Ref.parameters.size(); ++I)
    Args.push_back(I);
  Wrapper.instructions = {
      op(0, Range ? "invoke-static/range" : "invoke-static", Args, {}, Ref),
      op(1, "return-void")};
  Wrapper.code_end = 2;
  Wrapper.reference.owner = Owner.name;
  Owner.methods.push_back(Wrapper);
  auto Call = Wrapper;
  Call.reference.owner = Input[0].name;
  Call.instructions[0].reference = Wrapper.reference;
  Input[0].methods = {Call};
  return Input;
}

