std::vector<Class> producerCallbackNominalClasses(bool SDKInputs, bool SDKOwner,
                                                  bool Range, unsigned Aux,
                                                  bool Rotate, bool Covariant) {
  auto Input =
      privateInterfaceResultClasses(SDKInputs, Range, Aux, Rotate, Covariant);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  Make.access = {"public", "static", "final"};
  auto At = std::find(Make.reference.parameters.begin(),
                      Make.reference.parameters.end(), "Lfixture/Target;");
  Make.reference.parameters.erase(At);
  Make.reference.returns = "Lfixture/Text;";
  auto &S = *Make.generic_signature;
  auto Replace = [&](const std::string &A, const std::string &B) {
    auto P = S.find(A);
    if (P == std::string::npos)
      throw std::runtime_error("nominal model anchor missing");
    S.replace(P, A.size(), B);
  };
  Replace("A::Lfixture/Target;>", ">");
  Replace("TA;", "");
  Replace(")TA;", ")Lfixture/Text;");
  Make.registers = Make.reference.parameters.size() + 1;
  auto Ref = Make.reference;
  std::vector<unsigned> Args;
  for (unsigned I = 1; I <= Ref.parameters.size(); ++I)
    Args.push_back(I);
  auto Wrapper = method(
      "call", Ref.parameters, Ref.returns, Ref.parameters.size() + 1,
      {op(0, Range ? "invoke-static/range" : "invoke-static", Args, {}, Ref),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Wrapper.reference.owner = Owner.name;
  Owner.methods[1] = Wrapper;
  auto Client = Wrapper;
  Client.reference.owner = Input[0].name;
  Client.instructions[0].reference = Wrapper.reference;
  if (SDKOwner) {
    Owner.external = true;
    Owner.methods.resize(1);
    Owner.methods[0].instructions.clear();
    Client.instructions[0].reference = Ref;
  }
  Input[0].methods = {Client};
  return Input;
}

