std::vector<Class> contextCallbackElementClasses(bool SDK, bool Range,
                                                 unsigned Aux, bool Rotate,
                                                 bool Consumes, bool Produces) {
  auto Input = privateCallbackElementClasses(SDK, Range, Consumes, Produces);
  auto Frame = klass("Lfixture/Frame;");
  Frame.external = SDK;
  Input.push_back(Frame);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  auto Original = *Make.generic_signature;
  auto Begin = Original.find('(') + 1, End = Original.find(')');
  std::vector<std::string> Types(Aux, Frame.name), Trees(Aux, Frame.name);
  Types.push_back("Lfixture/Factory;");
  Trees.push_back(Original.substr(Begin, End - Begin));
  if (Rotate) {
    std::reverse(Types.begin(), Types.end());
    std::reverse(Trees.begin(), Trees.end());
  }
  if (Aux == 4) {
    Types.push_back("I");
    Trees.push_back("I");
  }
  Make.reference.parameters = Types;
  Make.registers = Types.size() + 1;
  Make.generic_signature = "<T:Ljava/lang/Object;>(";
  for (const auto &Tree : Trees)
    *Make.generic_signature += Tree;
  *Make.generic_signature += ")TT;";
  std::vector<unsigned> Args;
  for (unsigned I = 1; I <= Types.size(); ++I)
    Args.push_back(I);
  auto Wrapper =
      method("call", Types, "Ljava/lang/Object;", Types.size() + 1,
             {op(0, Range ? "invoke-static/range" : "invoke-static", Args, {},
                 Make.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Wrapper.reference.owner = Owner.name;
  Owner.methods[1] = Wrapper;
  auto Client = Wrapper;
  Client.reference.owner = Input[0].name;
  Client.instructions[0].reference = Wrapper.reference;
  Input[0].methods = {Client};
  return Input;
}

