std::vector<Class> boundedCallbackElementClasses(bool SDK, bool Range, bool Aux,
                                                 bool Consumes, bool Produces) {
  auto Input = privateCallbackElementClasses(SDK, Range, Consumes, Produces);
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = SDK;
  Input.push_back(Bound);
  auto &Owner = Input[1];
  auto &Make = Owner.methods[0];
  auto &S = *Make.generic_signature;
  auto P = S.find("<T:Ljava/lang/Object;>");
  S.replace(P, std::string("<T:Ljava/lang/Object;>").size(),
            "<T:Lfixture/Bound;>");
  Make.reference.returns = Bound.name;
  if (Aux) {
    Make.reference.parameters.push_back("Lfixture/Context;");
    P = S.find(')');
    S.insert(P, "Lfixture/Context;");
  }
  Make.registers = Make.reference.parameters.size() + 1;
  std::vector<unsigned> Args;
  for (unsigned I = 1; I <= Make.reference.parameters.size(); ++I)
    Args.push_back(I);
  auto Wrapper =
      method("call", Make.reference.parameters, Bound.name, Make.registers,
             {op(0, Range ? "invoke-static/range" : "invoke-static", Args, {},
                 Make.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Wrapper.reference.owner = Owner.name;
  Owner.methods[1] = Wrapper;
  auto Client = Wrapper;
  Client.reference.owner = Input[0].name;
  Client.instructions[0].reference = Wrapper.reference;
  Input[0].methods = {Client};
  return Input;
}

std::vector<Class> interfaceSeedVisitorClasses(bool SDK, bool Range, bool Frame,
                                               bool Consumes, bool Produces,
                                               bool Rename,
                                               bool Private = false) {
  const std::string Object = "Ljava/lang/Object;";
  const std::string NodeName = "Lfixture/Node;";
  const std::string ActionName = "Lfixture/Contract$Action;";
  const std::string FnName = "Lfixture/Fn;";
  auto Apply = method("apply", {Object}, Object, 0, {});
  Apply.access = {"public", "abstract"};
  Apply.generic_signature = "(TA;)TR;";
  auto Fn = klass(FnName, {Apply});
  Fn.access = {"public", "interface", "abstract"};
  Fn.generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  Fn.external = SDK;
  auto Node = klass(NodeName);
  Node.access = {"public", "interface", "abstract"};
  Node.external = SDK;
  auto Contract = klass("Lfixture/Contract;");
  Contract.access.insert("final");
  Contract.external = SDK;
  auto Action = klass(ActionName);
  Action.access.insert("final");
  Action.enclosing = Contract.name;
  Action.inner_class_present = true;
  Action.inner_name = "Action";
  Action.inner_access = {"public", "static", "final"};
  Action.external = SDK;
  auto Visit =
      method("visit", {NodeName, FnName}, "V", 3,
             {op(0, Range ? "invoke-interface/range" : "invoke-interface",
                 {2, 1}, {}, MethodRef{FnName, "apply", {Object}, Object}),
              op(1, "move-result-object", {0}),
              op(2, "check-cast", {0}, {}, ActionName), op(3, "return-void")});
  // Interface receiver and argument words are contiguous in the range form.
  if (Range) {
    Visit.registers = 5;
    Visit.instructions = {op(0, "move-object", {0, 4}),
                          op(1, "move-object", {1, 3}),
                          op(2, "invoke-interface/range", {0, 1}, {},
                             MethodRef{FnName, "apply", {Object}, Object}),
                          op(3, "move-result-object", {2}),
                          op(4, "check-cast", {2}, {}, ActionName),
                          op(5, "return-void")};
    Visit.code_end = 6;
  }
  const std::string Formal = Rename ? "Element" : "T";
  Visit.generic_signature = "<" + Formal + "::" + NodeName + ">(T" + Formal +
                            ";" + FnName.substr(0, FnName.size() - 1) + "<" +
                            (Consumes ? "-" : "") + "T" + Formal + ";" +
                            (Produces ? "+" : "") + ActionName + ">;)V";
  auto Provider = klass("Lfixture/Provider;", {Visit});
  Provider.external = SDK;
  if (SDK) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Call = method("call", {NodeName, FnName}, "V", 2,
                     {op(0, Range ? "invoke-static/range" : "invoke-static",
                         {0, 1}, {}, Provider.methods[0].reference),
                      op(1, "return-void")});
  auto Client = klass("Lfixture/Client;", {Call});
  if (Frame)
    for (auto *Method : {&Client.methods[0], &Provider.methods[0]}) {
      if (Method->instructions.empty())
        continue;
      Method->registers += 5;
      for (auto &Op : Method->instructions)
        for (auto &Reg : Op.registers)
          Reg += 5;
    }
  if (Private) {
    Provider.methods[0].access.erase("public");
    Provider.methods[0].access.insert("private");
    auto Forward = Client.methods[0];
    Forward.reference.owner = Provider.name;
    Forward.reference.name = "forward";
    Client.methods[0].instructions[0].reference = Forward.reference;
    Provider.methods.push_back(std::move(Forward));
  }
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "interface", "abstract"};
  Marker.external = SDK;
  return {Client, Provider, Node, Fn, Contract, Action, Marker};
}

TEST(MobileDalvikJava, InterfaceSeedVisitorsRetainCompleteBoundAndCallback) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Frame : {false, true})
        for (bool Consumes : {false, true})
          for (bool Produces : {false, true})
            for (bool Rename : {false, true})
              for (bool Reverse : {false, true})
                for (bool Private : {false, true}) {
                  if (SDK && Private)
                    continue;
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Range, Frame, Consumes, Produces, Rename,
                                 Reverse, Private}));
                  auto Input = interfaceSeedVisitorClasses(
                      SDK, Range, Frame, Consumes, Produces, Rename, Private);
                  const auto Target = Input[1].methods[0].reference;
                  if (Reverse) {
                    for (auto &Class : Input)
                      std::reverse(Class.methods.begin(), Class.methods.end());
                    std::reverse(Input.begin(), Input.end());
                  }
                  EXPECT_NO_THROW(([&] {
                    Budget B;
                    const auto Classes = linkClasses(Input, B);
                    const auto Plans = validateGenericSignatures(Classes, B);
                    EXPECT_TRUE(
                        Plans.erased_generic_invocations.contains(Target));
                    const auto Report = recoverJava(Classes, B);
                    EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                    EXPECT_EQ(
                        Report.getInteger("projected_method_count").value_or(0),
                        0);
                  })());
                }
}

TEST(MobileDalvikJava, InterfaceSeedVisitorsRejectIncompleteRelationsAndWords) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 23; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{SDK, Mutation}));
      auto Input =
          interfaceSeedVisitorClasses(SDK, false, false, true, true, false);
      auto &Visit = Input[1].methods[0];
      auto &S = *Visit.generic_signature;
      auto Replace = [&](std::string_view Before, std::string_view After) {
        const auto P = S.find(Before);
        ASSERT_NE(P, std::string::npos);
        S.replace(P, Before.size(), After);
      };
      switch (Mutation) {
      case 0:
        Replace("<T::Lfixture/Node;>", "<T::Lfixture/Missing;>");
        break;
      case 1:
        Replace("<T::", "<T:");
        break;
      case 2:
        Replace("<T::Lfixture/Node;>", "<T::Lfixture/Node;:Lfixture/Marker;>");
        break;
      case 3:
        Replace("<T::Lfixture/Node;>",
                "<T::Lfixture/Node;U:Ljava/lang/Object;>");
        break;
      case 4:
        Replace("<-TT;", "<+TT;");
        break;
      case 5:
        Replace("+Lfixture/Contract$Action;", "-Lfixture/Contract$Action;");
        break;
      case 6:
        Replace("<-TT;", "<-Ljava/lang/Object;");
        break;
      case 7:
        Replace("Lfixture/Fn<-TT;+Lfixture/Contract$Action;>;", "Lfixture/Fn;");
        break;
      case 8:
        Replace("+Lfixture/Contract$Action;", "+TT;");
        break;
      case 9:
        Input.erase(Input.begin() + 5);
        break;
      case 10:
        Input[5].generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 11:
        Input[2].generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 12:
        Input[3].generic_signature =
            "<A:Lfixture/Node;R:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 13:
        Input.erase(Input.begin() + 3);
        break;
      case 14:
        Visit.access.insert("varargs");
        break;
      case 15:
        Visit.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 16:
        Visit.access.erase("public");
        Visit.access.insert("private");
        break;
      case 17:
        Visit.access.erase("static");
        break;
      case 18:
        Input[0].methods[0].instructions[0].registers[1] = 2;
        break;
      case 19:
        Input[0].methods[0].instructions[0].opcode = "invoke-interface";
        break;
      case 20:
        Input[2].access.erase("public");
        break;
      case 21:
        Input[5].inner_access.erase("static");
        break;
      case 22:
        Input[5].access.erase("public");
        Input[5].inner_access.erase("public");
        break;
      }
      Budget B;
      if (Mutation == 7) {
        // A raw callback adds no generic callback relation. Keep this original
        // input as the pre-existing direct-bound seed path's valid control.
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plans.erased_generic_invocations.contains(Visit.reference));
        EXPECT_EQ(
            recoverJava(Classes, B).getInteger("unrecovered_method_count"), 0);
      } else
        EXPECT_THROW(recoverJava(linkClasses(Input, B), B), std::runtime_error);
    }
}

