std::vector<Class> rawFactoryDelegationClasses(bool SDK, bool Range, bool Alias,
                                               bool Covariant, bool Sibling) {
  auto Core = klass("Lfixture/Core;");
  Core.access = {"public", "final"};
  Core.interfaces = {"Lfixture/Marker;"};
  Core.generic_signature =
      "<T:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Marker<TT;>;";
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Box.external = SDK;
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  Marker.generic_signature = Box.generic_signature;
  Marker.external = SDK;
  auto Provider = klass("Lfixture/Provider;");
  Provider.external = SDK;
  auto Factory =
      method("make", {}, Box.name, 1,
             SDK ? std::vector<Instruction>{}
                 : std::vector<Instruction>{op(0, "const/4", {0}, int64_t(0)),
                                            op(1, "return-object", {0})});
  Factory.reference.owner = Provider.name;
  Factory.generic_signature = "<U:Ljava/lang/Object;>()Lfixture/Box<TU;>;";
  Provider.methods = {Factory};
  auto Typed = method("<init>", {Box.name}, "V", 3,
                      {op(0, "invoke-direct", {1}, {},
                          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                       op(1, "return-void", {})});
  Typed.access = {"public", "constructor"};
  Typed.reference.owner = Core.name;
  Typed.generic_signature =
      std::string("(Lfixture/Box<") + (Covariant ? "+TT;" : "TT;") + ">;)V";
  std::vector<Instruction> Code;
  if (Alias)
    Code.push_back(op(0, "move-object", {1, 4}));
  Code.push_back(op(0, Range ? "invoke-static/range" : "invoke-static", {}, {},
                    Factory.reference));
  Code.push_back(op(0, "move-result-object", {0}));
  unsigned Receiver = Alias ? 1 : 4;
  if (Range) {
    Code.push_back(op(0, "move-object", {2, Receiver}));
    Code.push_back(op(0, "move-object", {3, 0}));
    Receiver = 2;
  }
  Code.push_back(op(0, Range ? "invoke-direct/range" : "invoke-direct",
                    {Receiver, Range ? 3u : 0u}, {}, Typed.reference));
  Code.push_back(op(0, "return-void", {}));
  for (size_t I = 0; I < Code.size(); ++I)
    Code[I].pc = I;
  auto Default = method("<init>", {}, "V", 5, Code);
  Default.access = {"public", "constructor"};
  Default.reference.owner = Core.name;
  Core.methods = {Default, Typed};
  if (Sibling) {
    auto Other = Typed;
    Other.reference.parameters = {Marker.name};
    Other.generic_signature = "(Lfixture/Marker<TT;>;)V";
    Core.methods.push_back(Other);
  }
  return {Core, Provider, Box, Marker};
}

