std::vector<Class> nestedLockScopesClasses(bool SDK, bool Range, bool Alias,
                                           bool Reuse) {
  auto Input = monitorRegionClasses();
  Input[1].external = SDK;
  auto &M = Input[0].methods[0];
  M.reference.parameters = {"Ljava/lang/Object;", "Ljava/lang/Object;",
                            Input[1].name};
  M.registers = 10;
  unsigned Outer = Alias ? 1 : 7, Inner = Alias ? 2 : 8;
  const auto Callback = Input[1].methods[0].reference;
  std::vector<Instruction> Code;
  auto add = [&](Instruction I) {
    I.pc = Code.size();
    Code.push_back(std::move(I));
    return Code.size() - 1;
  };
  auto call = [&]() {
    return add(op(0, Range ? "invoke-interface/range" : "invoke-interface", {9},
                  {}, Callback));
  };
  add(op(0, "move-object", {1, 7}));
  add(op(0, "move-object", {2, 8}));
  add(op(0, "monitor-enter", {Outer}));
  if (Reuse) {
    add(op(0, "move-object", {3, Outer}));
    add(op(0, "const/4", {Outer}, int64_t(0)));
    Outer = 3;
  }
  auto OuterStart = call();
  add(op(0, "monitor-enter", {Inner}));
  auto InnerStart = Code.size();
  if (Reuse) {
    add(op(0, "move-object", {4, Inner}));
    add(op(0, "const/4", {Inner}, int64_t(0)));
    Inner = 4;
  }
  call();
  auto InnerExit = add(op(0, "monitor-exit", {Inner}));
  call();
  auto OuterExit = add(op(0, "monitor-exit", {Outer}));
  add(op(0, "return-void", {}));
  auto InnerHandler = add(op(0, "move-exception", {0}));
  auto InnerCleanup = add(op(0, "monitor-exit", {Inner}));
  auto InnerThrow = add(op(0, "throw", {0}));
  auto OuterHandler = add(op(0, "move-exception", {0}));
  add(op(0, "monitor-exit", {Outer}));
  add(op(0, "throw", {0}));
  M.instructions = std::move(Code);
  M.code_end = M.instructions.size();
  M.tries = {{uint32_t(OuterStart),
              uint32_t(InnerStart),
              {{std::nullopt, uint32_t(OuterHandler)}}},
             {uint32_t(InnerStart),
              uint32_t(InnerExit),
              {{std::nullopt, uint32_t(InnerHandler)}}},
             {uint32_t(InnerExit),
              uint32_t(OuterExit + 1),
              {{std::nullopt, uint32_t(OuterHandler)}}},
             {uint32_t(InnerCleanup),
              uint32_t(InnerThrow + 1),
              {{std::nullopt, uint32_t(OuterHandler)}}}};
  return Input;
}

