namespace {
std::vector<Class> linearScalarConversionClasses(const std::string &From,
                                                 const std::string &To,
                                                 const std::string &Opcode,
                                                 bool External, bool Range) {
  auto Input =
      guardedScalarConversionClasses(From, To, Opcode, External, Range);
  auto &M = Input[0].methods[1];
  const auto Old = M.instructions;
  M.instructions = {Old[2], Old[3], Old[4], Old[7], Old[8], Old[9]};
  for (size_t I = 0; I < M.instructions.size(); ++I)
    M.instructions[I].pc = I;
  M.code_end = M.instructions.size();
  return Input;
}
} // namespace

TEST(MobileDalvikJava, LinearScalarConversionsUseOrdinaryCastSemantics) {
  std::vector<std::tuple<std::string, std::string, std::string>> Cases{
      {"I", "J", "int-to-long"},     {"I", "F", "int-to-float"},
      {"I", "D", "int-to-double"},   {"J", "I", "long-to-int"},
      {"J", "F", "long-to-float"},   {"J", "D", "long-to-double"},
      {"F", "I", "float-to-int"},    {"F", "J", "float-to-long"},
      {"F", "D", "float-to-double"}, {"D", "I", "double-to-int"},
      {"D", "J", "double-to-long"},  {"D", "F", "double-to-float"},
      {"I", "B", "int-to-byte"},     {"I", "C", "int-to-char"},
      {"I", "S", "int-to-short"}};
  for (const auto *Narrow : {"Z", "B", "C", "S"})
    for (const auto &[To, Opcode] :
         std::vector<std::pair<std::string, std::string>>{
             {"J", "int-to-long"},
             {"F", "int-to-float"},
             {"D", "int-to-double"}})
      Cases.emplace_back(Narrow, To, Opcode);
  for (const auto &[From, To, Opcode] : Cases)
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{From, To, Opcode, External, Range, Reverse}));
          auto Input =
              linearScalarConversionClasses(From, To, Opcode, External, Range);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R = recoverJava(linkClasses(Input, B), B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
          std::string Text;
          for (size_t I = 0; I < R.getArray("source_units")->size(); ++I)
            Text += source(R, I);
          EXPECT_NE(Text.find("__neverdCtorConvert0"), std::string::npos);
        }
}

TEST(MobileDalvikJava, LinearScalarConversionsRejectUnprovedWordsAndMetadata) {
  for (unsigned Mutation = 0; Mutation != 18; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        linearScalarConversionClasses("F", "D", "float-to-double", true, true);
    auto &M = Input[0].methods[1];
    auto &Op = M.instructions[0];
    const auto Self = M.registers - M.incomingWords();
    if (Mutation == 0)
      Op.registers[0] = Self;
    else if (Mutation == 1)
      Op.registers[1] = Self;
    else if (Mutation == 2)
      Op.registers.resize(1);
    else if (Mutation == 3)
      Op.opcode = "long-to-char";
    else if (Mutation == 4)
      Op.registers[0] = M.registers - 1;
    else if (Mutation == 5)
      Op.registers[1] = Self + 2;
    else if (Mutation == 6)
      Op.literal = int64_t(1);
    else if (Mutation == 7)
      Op.reference = std::string("Ljava/lang/Object;");
    else if (Mutation == 8)
      Op.target = 1;
    else if (Mutation == 9)
      Op.targets = {1};
    else if (Mutation == 10)
      Op.keys = {1};
    else if (Mutation == 11)
      Op.data = {1};
    else if (Mutation == 12)
      Op.element_width = 1;
    else if (Mutation == 13) {
      Op.opcode = "double-to-float";
      Op.registers[1] = Self - 1;
    } else if (Mutation == 14)
      Op.registers[0] = Self - 1;
    else if (Mutation == 15)
      Op.opcode = "long-to-double";
    else if (Mutation == 16)
      Op.registers[1] = 0;
    else
      M.reference.parameters[0] = "Ljava/lang/Object;";
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

namespace {
std::vector<Class> floatingConstructorClasses(const std::string &Type,
                                              const std::string &Opcode,
                                              bool Two, bool External,
                                              bool Range, bool High) {
  auto Input =
      linearScalarConversionClasses(Type, Type, Opcode, External, Range);
  auto &M = Input[0].methods[1];
  const auto Self = M.registers - M.incomingWords();
  const auto A = Self + 1, B = A + width(Type);
  M.instructions[0] =
      op(0, Opcode + (Two ? "/2addr" : ""),
         Two ? std::vector<unsigned>{4, B} : std::vector<unsigned>{4, A, B});
  if (Two)
    M.instructions.insert(M.instructions.begin(),
                          op(0, Type == "D" ? "move-wide" : "move", {4, A}));
  for (size_t I = 0; I < M.instructions.size(); ++I) {
    M.instructions[I].pc = I;
    if (High)
      for (auto &Reg : M.instructions[I].registers)
        if (Reg >= Self)
          Reg += 24;
  }
  if (High)
    M.registers += 24;
  M.code_end = M.instructions.size();
  return Input;
}
} // namespace

TEST(MobileDalvikJava, FloatingConstructorPrefixesKeepEveryTypedOperation) {
  for (const auto *Type : {"F", "D"})
    for (const auto *Base : {"add", "sub", "mul", "div", "rem"})
      for (bool Two : {false, true})
        for (bool External : {false, true})
          for (bool Range : {false, true})
            for (bool High : {false, true})
              for (bool Reverse : {false, true})
                for (bool Linked : {false, true}) {
                  const auto Opcode =
                      std::string(Base) +
                      (std::string(Type) == "D" ? "-double" : "-float");
                  SCOPED_TRACE(::testing::PrintToString(std::tuple{
                      Opcode, Two, External, Range, High, Reverse, Linked}));
                  auto Input = floatingConstructorClasses(
                      Type, Opcode, Two, External, Range, High);
                  const auto Caller = Input[0].methods[1].reference;
                  if (Reverse)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  const auto Classes = linkClasses(Input, B);
                  EXPECT_TRUE(planConstructorDelegations(Classes, B, {})
                                  .contains(Caller));
                  const auto R =
                      Linked ? recoverJava(Classes, B) : recover(Input);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                }
  auto Input =
      floatingConstructorClasses("F", "add-float", false, false, true, false);
  auto &M = Input[0].methods[1];
  const auto Self = M.registers - M.incomingWords();
  M.instructions[0].registers[1] = Self - 1;
  M.instructions.insert(M.instructions.begin(),
                        op(0, "move", {Self - 1, Self + 1}));
  for (size_t I = 0; I < M.instructions.size(); ++I)
    M.instructions[I].pc = I;
  M.code_end = M.instructions.size();
  EXPECT_NO_THROW(recover(Input)); // A float adjacent to self has no high word.
}

TEST(MobileDalvikJava, FloatingConstructorPrefixesRejectHiddenWordsAndDrift) {
  for (unsigned Mutation = 0; Mutation != 22; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        floatingConstructorClasses("D", "add-double", false, true, true, false);
    auto &M = Input[0].methods[1];
    auto &Op = M.instructions[0];
    const auto Self = M.registers - M.incomingWords();
    if (Mutation == 0)
      Op.registers.resize(2);
    else if (Mutation == 1)
      Op.registers.push_back(0);
    else if (Mutation == 2)
      Op.opcode = "add-double/invented";
    else if (Mutation == 3)
      Op.opcode = "div-int";
    else if (Mutation == 4)
      Op.literal = int64_t(1);
    else if (Mutation == 5)
      Op.reference = std::string("Ljava/lang/Object;");
    else if (Mutation == 6)
      Op.target = 1;
    else if (Mutation == 7)
      Op.targets = {1};
    else if (Mutation == 8)
      Op.keys = {1};
    else if (Mutation == 9)
      Op.data = {1};
    else if (Mutation == 10)
      Op.element_width = 1;
    else if (Mutation == 11)
      Op.registers[0] = M.registers - 1;
    else if (Mutation == 12)
      Op.registers[1] = M.registers - 1;
    else if (Mutation == 13)
      Op.registers[2] = M.registers - 1;
    else if (Mutation == 14)
      Op.registers[0] = Self - 1;
    else if (Mutation == 15)
      Op.registers[1] = Self - 1;
    else if (Mutation == 16)
      Op.registers[2] = Self - 1;
    else if (Mutation == 17)
      Op.opcode = "add-float";
    else if (Mutation >= 18 && Mutation <= 20) {
      Op.registers[Mutation - 18] = 6;
      M.instructions.insert(M.instructions.begin(),
                            op(0, "move-object", {7, Self}));
      for (size_t I = 0; I < M.instructions.size(); ++I)
        M.instructions[I].pc = I;
      M.code_end = M.instructions.size();
    } else
      Op.registers[1] = 0;
    Budget B;
    const auto Classes = linkClasses(Input, B);
    if (Mutation >= 14 && Mutation <= 16 || Mutation >= 18 && Mutation <= 20)
      EXPECT_FALSE(
          planConstructorDelegations(Classes, B, {}).contains(M.reference));
    EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
  }
  for (unsigned Operand = 0; Operand != 3; ++Operand) {
    auto M =
        method("<init>", {"D", "D"}, "V", 14,
               {op(0, "new-instance", {5}, {}, std::string("Lfixture/Target;")),
                op(1, "add-double", {0, 10, 12}),
                op(2, "invoke-direct", {5}, {},
                   MethodRef{"Lfixture/Target;", "<init>", {}, "V"}),
                op(3, "return-void")});
    M.access = {"public", "constructor"};
    M.instructions[1].registers[Operand] = 4;
    Budget B;
    EXPECT_FALSE(constructorPrefixAllocationEnd(M, 0, B));
  }
}

TEST(MobileDalvikJava, SyntheticInterfaceRootsRejectUnknownScopesAndBodies) {
  for (bool Default : {false, true})
    for (unsigned Mutation = 0; Mutation != 18; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Default, Mutation}));
      auto Input = virtualIdentifierClasses();
      for (auto Index : {0u, 2u, 3u})
        Input[Index].methods[0].access.insert("synthetic");
      auto &Root = Input[0];
      auto &M = Root.methods[0];
      if (Default) {
        M.access.erase("abstract");
        M.instructions = {op(0, "return-object", {1})};
        M.registers = 2;
        M.code_end = 1;
      }
      if (Mutation == 0)
        Root.external = true;
      else if (Mutation == 1)
        M.access.insert("bridge");
      else if (Mutation == 2) {
        M.access.erase("public");
        M.access.insert("private");
      } else if (Mutation == 3) {
        M.access.erase("public");
        M.access.insert("protected");
      } else if (Mutation == 4)
        M.access.insert("native");
      else if (Mutation == 5)
        M.access.insert("static");
      else if (Mutation == 6)
        Root.access.erase("interface");
      else if (Mutation == 7)
        Root.generic_signature = "<T:Lfixture/Missing;>Ljava/lang/Object;";
      else if (Mutation == 8)
        M.generic_signature = "(Lfixture/Missing;)Ljava/lang/Object;";
      else if (Mutation == 9) {
        auto Alien = klass("Lfixture/Alien;", {M});
        Alien.external = true;
        Alien.access = {"public", "abstract", "interface"};
        Alien.generic_signature = Root.generic_signature;
        Input.push_back(Alien);
      } else if (Mutation == 10) {
        auto Meta = klass("Lfixture/Metadata;");
        Meta.external = true;
        Meta.enclosing_method = M.reference;
        Input.push_back(Meta);
      } else if (Mutation == 11)
        Input[1].interfaces = {"Lfixture/Missing;"};
      else if (Mutation == 12)
        Input[2].methods[0].access.insert("bridge");
      else if (Mutation == 13)
        Input[2].methods[0].access.insert("abstract");
      else if (Mutation == 14) {
        M.access.erase("abstract");
        M.instructions.clear();
      } else if (Mutation == 15) {
        M.access.erase("abstract");
        M.instructions = {op(0, "unsupported-synthetic-default")};
        M.registers = 2;
        M.code_end = 1;
      } else if (Mutation == 16) {
        M.access.insert("abstract");
        M.instructions = {op(0, "return-object", {1})};
        M.registers = 2;
        M.code_end = 1;
      } else
        Root.enclosing = "Lfixture/Missing;";
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

namespace {
std::vector<Class> longConstructorClasses(const std::string &Opcode, bool Two,
                                          bool External, bool Range,
                                          bool Guarded, bool High) {
  // Frame expectations are independent of the operation descriptor under test.
  const std::string RightType =
      Opcode == "shl-long" || Opcode == "shr-long" || Opcode == "ushr-long"
          ? "I"
          : "J";
  const FieldRef Value{"Lfixture/Core;", "value", "J"};
  auto Primary =
      method("<init>", {"J"}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "iput-wide", {1, 0}, {}, Value), op(2, "return-void")});
  Primary.access = {"public", "constructor"};
  auto Consume = method("consume", {"J"}, "J", 2, {op(0, "return-wide", {0})});
  auto Provider = klass("Lfixture/Source;", {Consume});
  Provider.access = {"public", "final"};
  if (External) {
    Provider.external = true;
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Copy = method("<init>", {"J", RightType, "Z"}, "V", 16, {});
  Copy.access = {"public", "constructor"};
  const auto Self = Copy.registers - Copy.incomingWords();
  const auto Left = Self + 1, Right = Self + 3;
  Copy.instructions.push_back(op(0, "move-wide", {0, Left}));
  if (Guarded)
    Copy.instructions.push_back(
        op(1, "if-eqz", {Right + width(RightType)}, {}, {}, 3));
  Copy.instructions.push_back(op(Copy.instructions.size(),
                                 Opcode + (Two ? "/2addr" : ""),
                                 Two ? std::vector<unsigned>{0, Right}
                                     : std::vector<unsigned>{0, Left, Right}));
  Copy.instructions.push_back(op(Copy.instructions.size(),
                                 "invoke-static/range", {0, 1}, {},
                                 Provider.methods[0].reference));
  Copy.instructions.push_back(
      op(Copy.instructions.size(), "move-result-wide", {0}));
  if (Range) {
    Copy.instructions.push_back(
        op(Copy.instructions.size(), "move-wide", {6, 0}));
    Copy.instructions.push_back(
        op(Copy.instructions.size(), "move-object", {5, Self}));
  }
  Copy.instructions.push_back(op(
      Copy.instructions.size(), Range ? "invoke-direct/range" : "invoke-direct",
      Range ? std::vector<unsigned>{5, 6, 7}
            : std::vector<unsigned>{Self, 0, 1},
      {}, Primary.reference));
  Copy.instructions.push_back(op(Copy.instructions.size(), "return-void"));
  Copy.code_end = Copy.instructions.size();
  auto Core = klass(Value.owner, {Primary, Copy});
  Core.access = {"public", "final"};
  Core.fields.push_back({Value, {"private", "final"}, {}});
  if (High)
    for (auto &M : Core.methods) {
      M.registers += 24;
      for (auto &Op : M.instructions)
        for (auto &Reg : Op.registers)
          Reg += 24;
    }
  return {Core, Provider};
}
} // namespace

TEST(MobileDalvikJava, LongConstructorPrefixesShareTotalTypedWordReceipts) {
  for (const auto *Base :
       {"add", "sub", "mul", "and", "or", "xor", "shl", "shr", "ushr"})
    for (bool Two : {false, true})
      for (bool External : {false, true})
        for (bool Range : {false, true})
          for (bool Guarded : {false, true})
            for (bool High : {false, true})
              for (bool Linked : {false, true}) {
                const auto Opcode = std::string(Base) + "-long";
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Opcode, Two, External, Range, Guarded, High, Linked}));
                auto Input = longConstructorClasses(Opcode, Two, External,
                                                    Range, Guarded, High);
                const auto Caller = Input[0].methods[1].reference;
                if (Linked) {
                  std::reverse(Input[0].methods.begin(),
                               Input[0].methods.end());
                  std::reverse(Input.begin(), Input.end());
                }
                Budget B;
                const auto Classes = linkClasses(Input, B);
                ASSERT_TRUE(planConstructorDelegations(Classes, B, {})
                                .contains(Caller));
                const auto R =
                    Linked ? recoverJava(Classes, B) : recover(Input);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                if (!Guarded)
                  EXPECT_NE(source(R).find("__neverdCtorLong"),
                            std::string::npos);
              }
  for (const auto *Opcode : {"shl-long", "shr-long", "ushr-long"})
    for (bool Two : {false, true}) {
      auto Input =
          longConstructorClasses(Opcode, Two, false, false, false, false);
      auto &M = Input[0].methods[1];
      const auto Self = M.registers - M.incomingWords();
      const auto Distance = M.instructions[1].registers.back();
      M.instructions[1].registers.back() = Self - 1;
      M.instructions.insert(M.instructions.begin() + 1,
                            op(1, "move", {Self - 1, Distance}));
      for (size_t I = 0; I < M.instructions.size(); ++I)
        M.instructions[I].pc = I;
      M.code_end = M.instructions.size();
      EXPECT_NO_THROW(recover(Input)); // The shift distance has no high word.
    }
}

TEST(MobileDalvikJava,
     LongConstructorPrefixesRejectHiddenWordsAndThrowingForms) {
  for (unsigned Mutation = 0; Mutation != 25; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        longConstructorClasses("add-long", false, true, true, false, false);
    auto &M = Input[0].methods[1];
    auto &Op = M.instructions[1];
    const auto Self = M.registers - M.incomingWords();
    if (Mutation == 0)
      Op.registers.pop_back();
    else if (Mutation == 1)
      Op.registers.push_back(0);
    else if (Mutation == 2)
      Op.opcode += "/invented";
    else if (Mutation == 3)
      Op.literal = int64_t(1);
    else if (Mutation == 4)
      Op.reference = std::string("Ljava/lang/Object;");
    else if (Mutation == 5)
      Op.target = 2;
    else if (Mutation == 6)
      Op.targets = {2};
    else if (Mutation == 7)
      Op.keys = {1};
    else if (Mutation == 8)
      Op.data = {1};
    else if (Mutation == 9)
      Op.element_width = 1;
    else if (Mutation >= 10 && Mutation <= 12)
      Op.registers[Mutation - 10] = M.registers - 1;
    else if (Mutation >= 13 && Mutation <= 15)
      Op.registers[Mutation - 13] = Self - 1;
    else if (Mutation == 16)
      M.reference.parameters[0] = "Ljava/lang/Object;";
    else if (Mutation == 17)
      Op.registers[1] = Self + 2;
    else if (Mutation == 18)
      Op.registers[1] = 2;
    else if (Mutation == 19)
      Op.opcode = "add-long/lit8";
    else if (Mutation == 20)
      Op.opcode = "div-long";
    else if (Mutation == 21)
      Op.opcode = "rem-long";
    else {
      Op.registers[Mutation - 22] = 6;
      M.instructions.insert(M.instructions.begin(),
                            op(0, "move-object", {7, Self}));
      for (size_t I = 0; I < M.instructions.size(); ++I)
        M.instructions[I].pc = I;
      M.code_end = M.instructions.size();
    }
    Budget B;
    const auto Classes = linkClasses(Input, B);
    if (Mutation >= 10 && Mutation <= 15 || Mutation >= 22)
      EXPECT_FALSE(
          planConstructorDelegations(Classes, B, {}).contains(M.reference));
    EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
  }
  for (unsigned Operand = 0; Operand != 3; ++Operand) {
    auto M =
        method("<init>", {"J", "J"}, "V", 14,
               {op(0, "new-instance", {5}, {}, std::string("Lfixture/Target;")),
                op(1, "add-long", {0, 10, 12}),
                op(2, "invoke-direct", {5}, {},
                   MethodRef{"Lfixture/Target;", "<init>", {}, "V"}),
                op(3, "return-void")});
    M.access = {"public", "constructor"};
    M.instructions[1].registers[Operand] = 4;
    Budget B;
    EXPECT_FALSE(constructorPrefixAllocationEnd(M, 0, B));
  }
  auto M =
      method("<init>", {"J", "I"}, "V", 14,
             {op(0, "new-instance", {5}, {}, std::string("Lfixture/Target;")),
              op(1, "move", {4, 13}), op(2, "shl-long", {0, 11, 4}),
              op(3, "invoke-direct", {5}, {},
                 MethodRef{"Lfixture/Target;", "<init>", {}, "V"}),
              op(4, "return-void")});
  M.access = {"public", "constructor"};
  Budget B;
  const auto End = constructorPrefixAllocationEnd(M, 0, B);
  ASSERT_TRUE(End); // Adjacent int distances do not touch the fresh receiver.
  EXPECT_EQ(*End, 3u);
}

std::vector<Class> protectedOverloadIdentifierClasses(bool External, bool Range,
                                                      bool Symbolic) {
  auto Input =
      genericAbstractIdentifierClasses(External, Range, Symbolic, false, 2);
  for (auto &C : Input)
    for (auto &M : C.methods)
      if (M.reference.name == "choose-value") {
        M.access.erase("public");
        M.access.insert("protected");
      }
  auto Concrete = Input[1].methods[0];
  Concrete.reference.owner = Input[0].name;
  Concrete.reference.parameters[0] = "Ljava/lang/Object;";
  Concrete.generic_signature.reset();
  Concrete.access.erase("final");
  Input[0].methods.push_back(Concrete);
  auto Run = Input[0].methods[1];
  Run.reference.name = "tagged";
  Run.reference.parameters[0] = "Ljava/lang/Object;";
  Run.instructions[0].reference = Concrete.reference;
  Input[0].methods.push_back(Run);
  auto Override = Concrete;
  Override.reference.owner = Input[2].name;
  Override.instructions = {op(0, Range ? "invoke-super/range" : "invoke-super",
                              {1, 2, 3, 4}, {}, Concrete.reference),
                           op(1, "move-result", {0}), op(2, "return", {0})};
  Override.code_end = 3;
  Input[2].methods.push_back(Override);
  return Input;
}

TEST(MobileDalvikJava, ProtectedOverloadsRetainFixedGenericDeclaringRoots) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Symbolic : {false, true})
        for (bool Reverse : {false, true}) {
          SCOPED_TRACE(::testing::Message()
                       << External << Range << Symbolic << Reverse);
          auto Input =
              protectedOverloadIdentifierClasses(External, Range, Symbolic);
          const auto Abstract = Input[0].methods[0].reference;
          const auto Concrete = Input[0].methods[2].reference;
          std::set<std::string> Family;
          for (const auto &C : Input)
            for (const auto &M : C.methods)
              if (M.reference.name == Abstract.name)
                Family.insert(M.reference.identity());
          ASSERT_EQ(Family.size(), 5u);
          if (Reverse)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          const auto R = recoverJava(linkClasses(Input, B), B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"), 5);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          unsigned Count = 0;
          for (const auto &V : *R.getArray("methods")) {
            const auto &Row = *V.getAsObject();
            if (Row.getString("name") != Abstract.name)
              continue;
            ++Count;
            EXPECT_EQ(Row.getString("source_name"), "__neverdVirtualMethod0");
            const bool Typed = Row.getString("prototype") == "(Lapi/Box;J)Z";
            EXPECT_EQ(Row.getString("source_name_declaration"),
                      (Typed ? Abstract : Concrete).identity());
            ASSERT_NE(Row.getArray("source_name_family"), nullptr);
            std::set<std::string> Actual;
            for (const auto &F : *Row.getArray("source_name_family"))
              Actual.insert(F.getAsString()->str());
            EXPECT_EQ(Actual, Family);
          }
          EXPECT_EQ(Count, 5u);
        }
}

TEST(MobileDalvikJava, ProtectedOverloadNamesRejectUnanchoredOrOpenComponents) {
  for (bool Linked : {false, true})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
      SCOPED_TRACE(::testing::Message() << Linked << Mutation);
      auto Input = protectedOverloadIdentifierClasses(true, true, true);
      auto &Root = Input[0];
      if (Mutation == 0)
        Root.external = true;
      else if (Mutation == 1)
        Root.methods[0].generic_signature =
            "<T:Ljava/lang/Object;>(Lapi/Box<TT;>;J)Z";
      else if (Mutation == 2) {
        Root.generic_signature = "<T:Ljava/lang/Object;>Lapi/Base;";
        Root.methods[0].generic_signature = "(Lapi/Box<TT;>;J)Z";
      } else if (Mutation == 3)
        Root.methods[0].access.insert("final");
      else if (Mutation == 4)
        Root.methods[0].access.erase("abstract");
      else if (Mutation == 5)
        Root.methods[2].access.insert("static");
      else if (Mutation == 6)
        Root.methods[2].access.insert("private");
      else if (Mutation == 7)
        Root.methods[2].access.insert("native");
      else if (Mutation == 8)
        Root.methods[2].access.insert("synthetic");
      else if (Mutation == 9)
        Root.methods[2].reference.parameters.pop_back();
      else if (Mutation == 10) {
        auto Other = Root.methods[2];
        Other.reference.owner = "Lother/Unrelated;";
        Input.push_back(klass(Other.reference.owner, {Other}));
      } else if (Mutation == 11)
        Input[2].superclass = "Lmissing/Parent;";
      else if (Mutation == 12)
        Input[1].interfaces.push_back("Lmissing/Contract;");
      else if (Mutation == 13)
        Input[1].external = true;
      else if (Mutation == 14) {
        auto Metadata = klass("Lapi/Metadata;");
        Metadata.external = true;
        Metadata.enclosing_method = Root.methods[0].reference;
        Input.push_back(Metadata);
      } else if (Mutation == 15)
        Root.methods[0].generic_signature = "(Lapi/Box<+TMissing;>;J)Z";
      else if (Mutation == 16)
        Input[5].generic_signature.reset();
      else if (Mutation == 17)
        Root.methods[2].generic_signature = "<T:Ljava/lang/Object;>(TT;J)Z";
      else if (Mutation == 18)
        Root.methods[0].access = {"public", "abstract"};
      else {
        auto Extra = Root.methods[0];
        Extra.reference.owner = "Lother/External;";
        auto SDK = klass(Extra.reference.owner, {Extra});
        SDK.external = true;
        Input.push_back(SDK);
      }
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

TEST(MobileDalvikJava, PackageConstructorOwnersKeepExactStaticReadAccess) {
  for (const std::string Type : {"I", "J", "Ljava/lang/Object;"})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool PackageField : {false, true})
          for (bool Linked : {false, true}) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Type, External, Range, PackageField, Linked}));
            auto Input = capturedParameterReuseClasses(Type, External, Range);
            auto &Provider = Input.back();
            Provider.access.erase("public");
            if (PackageField)
              Provider.fields[0].access.erase("public");
            const auto Constructor = Input[1].methods[0];
            const auto Read = Constructor.instructions[1];
            Budget B;
            ClassMap Classes;
            if (Linked)
              Classes = linkClasses(Input, B);
            else
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            ASSERT_EQ(
                constructorPrefixStaticRead(Constructor, Read, Classes, B),
                Provider.fields[0].reference);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
          }
}

TEST(MobileDalvikJava, PackageConstructorOwnersRejectForeignAndNestedScopes) {
  for (bool Linked : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Linked, Mutation}));
      auto Input = capturedParameterReuseClasses("J", true, true);
      auto &Provider = Input.back();
      Provider.access.erase("public");
      auto &Ctor = Input[1].methods[0];
      auto &Read = Ctor.instructions[1];
      if (Mutation == 0)
        Provider.access.insert("private");
      else if (Mutation == 1)
        Provider.access.insert("protected");
      else if (Mutation == 2) {
        Provider.name = "Lother/Provider;";
        Provider.fields[0].reference.owner = Provider.name;
        Read.reference = Provider.fields[0].reference;
      } else if (Mutation == 3) {
        Provider.inner_class_present = true;
        Provider.enclosing = Input[0].name;
        Provider.inner_name = "Provider";
        Provider.inner_access = {"static"};
      } else if (Mutation == 4) {
        Provider.inner_class_present = true;
        Provider.enclosing_method = Ctor.reference;
        Provider.inner_name = "Named";
      } else if (Mutation == 5)
        Provider.fields[0].access = {"private", "static"};
      else if (Mutation == 6)
        Provider.fields[0].access.erase("static");
      else if (Mutation == 7)
        Read.opcode = "sget-object";
      else if (Mutation == 8) {
        Provider.fields[0].access.insert("final");
        Provider.fields[0].value = int64_t(7);
      } else if (Mutation == 9)
        Read.registers = {Ctor.registers};
      else if (Mutation == 10)
        Read.registers = {2};
      else
        Provider.fields.clear();
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_FALSE(constructorPrefixStaticRead(Ctor, Read, Classes, B));
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recoverJava(Classes, B),
                   std::runtime_error);
    }
}

std::vector<Class> genericTerminalVoidClasses(bool External, bool Range,
                                              bool Alpha, bool RawParent,
                                              bool Direct) {
  const std::string Object = "Ljava/lang/Object;",
                    String = "Ljava/lang/String;";
  auto ObjectType = klass(Object);
  ObjectType.superclass.reset();
  ObjectType.external = true;
  auto ToString = method("toString", {}, String, 0, {});
  ToString.access = {"public"};
  ToString.reference.owner = Object;
  ObjectType.methods.push_back(ToString);
  auto StringType = klass(String);
  StringType.access.insert("final");
  StringType.external = true;
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto InitException = method("<init>", {String}, "V", 0, {});
  InitException.access = {"public", "constructor"};
  auto Exception = klass("Ljava/lang/IllegalStateException;", {InitException});
  Exception.superclass = Throwable.name;
  Exception.external = true;
  auto Void = klass("Ljava/lang/Void;");
  Void.access.insert("final");
  Void.external = true;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  ObjectInit.reference.owner = Object;
  ObjectType.methods.push_back(ObjectInit);
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {}, ObjectInit.reference),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Key = klass("Lfixture/Key;", {Init});
  Key.access.insert("final");
  Key.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Key.external = External;
  auto Contract = method("write", {Key.name, Object}, "V", 0, {});
  Contract.access = {"public", "abstract"};
  const std::string Formal = Alpha ? "U" : "T";
  auto Signature = [&](std::string Name, std::string Result) {
    return "<" + Name + ":Ljava/lang/Object;>(Lfixture/Key<T" + Name + ";>;T" +
           Name + ";)" + Result;
  };
  if (!RawParent)
    Contract.generic_signature = Signature(Formal, "V");
  auto Base = klass("Lfixture/Base;", {Init, Contract});
  Base.access.insert("abstract");
  Base.external = External;
  auto Target =
      method("write", {Key.name, Object}, Void.name, 5,
             {op(0, "new-instance", {0}, {}, Exception.name),
              op(1, "const-string", {1}, std::string("owned message")),
              op(2, Range ? "invoke-virtual/range" : "invoke-virtual", {1}, {},
                 ToString.reference),
              op(3, "move-result-object", {1}),
              op(4, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
                 Exception.methods[0].reference),
              op(5, "throw", {0})});
  Target.access = {"public"};
  Target.generic_signature = Signature("T", Void.name);
  auto Core = klass("Lfixture/Core;", {Target});
  Core.access.insert("final");
  Core.superclass = Base.name;
  auto Bridge = method("write", {Key.name, Object}, "V", 3,
                       {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                           {0, 1, 2}, {}, Core.methods[0].reference),
                        op(1, "return-void")});
  Bridge.reference.owner = Core.name;
  Bridge.access = {"public", "bridge", "synthetic"};
  Core.methods.push_back(Bridge);
  Init.reference.owner = Core.name;
  Init.instructions[0].reference = Base.methods[0].reference;
  Core.methods.push_back(Init);
  auto Call = method(
      "call", {Core.name, Key.name, Object}, "V", 4,
      {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2, 3}, {},
          Direct ? Core.methods[0].reference : Bridge.reference),
       op(1, "return-void")});
  if (External)
    for (auto *C : {&Base, &Key})
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  return {Core,       Base,       Key,       klass("Lfixture/Client;", {Call}),
          ObjectType, StringType, Throwable, Exception,
          Void};
}

TEST(MobileDalvikJava, GenericTerminalVoidBridgesKeepRawOwnFormalContracts) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Alpha : {false, true})
        for (bool RawParent : {false, true})
          for (bool Direct : {false, true})
            for (bool Linked : {false, true})
              for (bool Reverse : {false, true}) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{External, Range, Alpha, RawParent, Direct,
                               Linked, Reverse}));
                auto Input = genericTerminalVoidClasses(External, Range, Alpha,
                                                        RawParent, Direct);
                const auto Typed = Input[0].methods[0].reference;
                const auto Bridge = Input[0].methods[1].reference;
                const auto Contract = Input[1].methods[1].reference;
                const auto Original = Input[0].methods[0].generic_signature;
                if (Reverse)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Linked)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                const auto Plans = validateGenericSignatures(Classes, B);
                ASSERT_TRUE(Plans.nonreturning_void_bridges.contains(Bridge));
                EXPECT_TRUE(Plans.nonreturning_void_bridges.at(Bridge)
                                .erased_method_formals);
                EXPECT_FALSE(Plans.nonreturning_void_bridges.at(Bridge)
                                 .source_signature);
                EXPECT_EQ(
                    Plans.nonreturning_void_bridges.at(Bridge).erased_contracts,
                    std::set<MethodRef>{Contract});
                EXPECT_TRUE(Plans.erased_generic_invocations.contains(Typed));
                EXPECT_EQ(Classes.at(Typed.owner).methods[0].generic_signature,
                          Original);
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count"), 2);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                bool Found = false;
                for (const auto &V : *R.getArray("methods")) {
                  const auto &Row = *V.getAsObject();
                  if (Row.getString("identity") != Bridge.identity())
                    continue;
                  Found = true;
                  EXPECT_EQ(Row.getString("projection_kind"),
                            "nonreturning-void-forwarding-bridge");
                  EXPECT_FALSE(Row.getString("source_generic_signature"));
                }
                EXPECT_TRUE(Found);
              }
}

TEST(MobileDalvikJava, GenericTerminalVoidBridgesRejectBodyScopeAndWordDrift) {
  for (bool Linked : {false, true})
    for (unsigned Mutation = 0; Mutation < 27; ++Mutation) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Linked, Mutation}));
      auto Input = genericTerminalVoidClasses(true, true, true, false, true);
      auto &Core = Input[0];
      auto &Target = Core.methods[0];
      auto &Bridge = Core.methods[1];
      if (Mutation == 0)
        Core.access.erase("final");
      else if (Mutation == 1)
        Core.external = true;
      else if (Mutation == 2)
        Core.generic_signature = "<C:Ljava/lang/Object;>Lfixture/Base;";
      else if (Mutation == 3)
        Target.generic_signature = "<T:Ljava/lang/CharSequence;>(Lfixture/"
                                   "Key<TT;>;TT;)Ljava/lang/Void;";
      else if (Mutation == 4)
        Input[2].generic_signature =
            "<A:Ljava/lang/CharSequence;>Ljava/lang/Object;";
      else if (Mutation == 5)
        Target.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Key<+TT;>;TT;)Ljava/lang/Void;";
      else if (Mutation == 6)
        Target.generic_signature = "<T:Ljava/lang/Object;U:Ljava/lang/Object;>"
                                   "(Lfixture/Key<TT;>;TU;)Ljava/lang/Void;";
      else if (Mutation == 7)
        Target.instructions.back() = op(5, "return-object", {0});
      else if (Mutation == 8)
        Target.instructions[1] = op(1, "const/4", {1}, int64_t(0));
      else if (Mutation == 9)
        Target.instructions[1].registers = {2};
      else if (Mutation == 10)
        Target.instructions[2].registers = {0};
      else if (Mutation == 11)
        Target.instructions[3].registers = {0};
      else if (Mutation == 12)
        Target.instructions[4].registers = {1, 0};
      else if (Mutation == 13)
        Target.instructions[5].registers = {1};
      else if (Mutation == 14)
        Bridge.instructions[0].registers = {0, 2, 1};
      else if (Mutation == 15)
        Bridge.instructions[0].registers.pop_back();
      else if (Mutation == 16)
        Bridge.instructions[0].opcode = "invoke-static/range";
      else if (Mutation == 17)
        Bridge.instructions[1] = op(1, "return", {0});
      else if (Mutation == 18)
        Target.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 19)
        Input[1].methods[1].access.insert("final");
      else if (Mutation == 20)
        Input[1].methods[1].access.insert("static");
      else if (Mutation == 21)
        Input[1].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 22)
        Input[1].superclass = "Lmissing/Parent;";
      else if (Mutation == 23)
        Target.instructions[2].reference =
            MethodRef{"Ljava/lang/Object;", "hashCode", {}, "I"};
      else if (Mutation == 24)
        Input[1].methods[1].generic_signature =
            "<U:Ljava/lang/Object;>(Lfixture/Key<+TU;>;TU;)V";
      else if (Mutation == 25)
        Input[1].methods[1].generic_signature =
            "<U:Ljava/lang/Object;>(Lfixture/Key<TU;>;Ljava/lang/Object;)V";
      else {
        auto Other = Input[1].methods[1];
        Other.reference.name = "other";
        Input[1].methods.push_back(Other);
      }
      Budget B;
      EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                          : recover(Input),
                   std::runtime_error);
    }
}

std::vector<Class> allocationVoidReceiverClasses(unsigned Dispatch,
                                                 bool External, bool Range,
                                                 std::string Visibility) {
  auto Input = discardedAllocationCallClasses("I", false, Range);
  auto Before = Input[3].methods.back();
  Before.reference.returns = "V";
  Before.access = {Visibility};
  Before.registers = 1;
  Before.instructions = {op(0, "return-void")};
  Before.code_end = 1;
  Input[3].methods = {Before};
  auto &Make = Input[0].methods[0];
  if (Dispatch == 1) {
    Input[3].access = {"public", "interface", "abstract"};
    Input[3].methods[0].access = {"public", "abstract"};
    Input[3].methods[0].instructions.clear();
    Input[3].methods[0].registers = Input[3].methods[0].code_end = 0;
  } else if (Dispatch == 2) {
    Before.reference.owner = Input[0].name;
    Before.access = {"private"};
    Make.reference.parameters = {Input[0].name};
  } else if (Dispatch == 3) {
    Input[0].superclass = Input[3].name;
    Make.access = {"public"};
    Make.reference.parameters = {"Ljava/lang/Object;"};
    Make.registers = 3;
    Make.instructions[2].registers = {0, 2};
  }
  Make.instructions[1].opcode =
      std::string(Dispatch == 1   ? "invoke-interface"
                  : Dispatch == 2 ? "invoke-direct"
                  : Dispatch == 3 ? "invoke-super"
                                  : "invoke-virtual") +
      (Range ? "/range" : "");
  Make.instructions[1].reference = Before.reference;
  if (External) {
    Input[3].external = true;
    Input[3].methods[0].instructions.clear();
    Input[3].methods[0].registers = Input[3].methods[0].code_end = 0;
  }
  if (Dispatch == 2) {
    Input[0].methods.push_back(Before);
    Input[3].methods.clear();
  }
  return Input;
}

TEST(MobileDalvikJava, AllocationVoidReceiversRetainAllCheckedDispatchKinds) {
  for (unsigned Dispatch = 0; Dispatch < 4; ++Dispatch)
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (const std::string Visibility : {"public", "protected", "package"})
          for (unsigned Route = 0; Route < 3; ++Route) {
            if ((Dispatch == 1 || Dispatch == 2) && Visibility != "public")
              continue;
            if (Dispatch == 2 && External)
              continue;
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Dispatch, External, Range, Visibility, Route}));
            auto Input = allocationVoidReceiverClasses(
                Dispatch, External, Range,
                Visibility == "package" ? "" : Visibility);
            if (Visibility == "package" && Dispatch != 2)
              Input[3].methods[0].access.erase("");
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            const auto Text = source(R);
            const auto New = Text.find("new fixture.Inner(");
            const auto Call = Text.find(".before(");
            ASSERT_NE(New, std::string::npos);
            ASSERT_NE(Call, std::string::npos);
            EXPECT_LT(New, Call);
            EXPECT_EQ(Text.find(".before(", Call + 1), std::string::npos);
            EXPECT_NE(Text.find(".before();"), std::string::npos);
          }
}

TEST(MobileDalvikJava, AllocationVoidReceiversKeepWordsAccessAndResultGuards) {
  for (unsigned Dispatch = 0; Dispatch < 4; ++Dispatch)
    for (bool Linked : {false, true})
      for (unsigned Mutation = 0; Mutation < 8; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Dispatch, Linked, Mutation}));
        auto Input =
            allocationVoidReceiverClasses(Dispatch, false, true, "public");
        auto &Make = Input[0].methods[0];
        auto &Declaration =
            Dispatch == 2 ? Input[0].methods[1] : Input[3].methods[0];
        auto &Call = Make.instructions[1];
        if (Mutation == 0)
          Declaration.access.insert("static");
        else if (Mutation == 1)
          Call.registers.clear();
        else if (Mutation == 2) {
          Make.instructions.insert(Make.instructions.begin() + 2,
                                   op(0, "move-result-object", {1}));
          for (size_t I = 0; I < Make.instructions.size(); ++I)
            Make.instructions[I].pc = I;
          Make.code_end = Make.instructions.size();
        } else if (Mutation == 3)
          std::get<MethodRef>(Call.reference).returns = "I";
        else if (Mutation == 4)
          Call.opcode = "invoke-static/range";
        else if (Mutation == 5)
          Declaration.access.insert("bridge");
        else if (Mutation == 6)
          Call.registers = {0};
        else if (Dispatch == 2)
          Input[0].methods.pop_back();
        else
          Input[3].methods.clear();
        Budget B;
        EXPECT_THROW(Linked ? recoverJava(linkClasses(Input, B), B)
                            : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> inheritedClosedScalarClasses(std::string Type, bool Range,
                                                bool Intermediate, bool SDK,
                                                unsigned Formals) {
  auto Input = namedInheritedDefaultClasses(Type == "Z" ? "I" : Type, Range,
                                            Intermediate, false);
  Input.erase(Input.begin() + 1); // Concrete receivers belong to the observer.
  for (auto &C : Input)
    for (auto &M : C.methods) {
      if (M.reference.name == "work-slot") {
        M.reference.parameters[1] = "Lfixture/Callback;";
        M.reference.returns = Type;
        M.generic_signature =
            "(JLfixture/Callback<-Lfixture/DefaultApi;>;)" + Type;
        if (Type == "Z")
          M.instructions[0].literal = int64_t(1);
      } else if (M.reference.name == "access$work-slot$jd") {
        M.reference.parameters[2] = "Lfixture/Callback;";
        M.reference.returns = Type;
      }
      for (auto &Op : M.instructions)
        if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
            Ref && Ref->name == "work-slot") {
          Ref->parameters[1] = "Lfixture/Callback;";
          Ref->returns = Type;
        }
    }
  auto Accept = method("accept", {"Ljava/lang/Object;"}, "V", 0, {});
  Accept.access = {"public", "abstract"};
  Accept.generic_signature = "(TT;)V";
  auto Callback = klass("Lfixture/Callback;", {Accept});
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = SDK;
  auto &Child = Input.back();
  Child.generic_signature =
      "<C:Ljava/lang/Object;" +
      std::string(Formals == 2 ? "D:Ljava/lang/Object;" : "") +
      ">Ljava/lang/Object;" + Child.interfaces[0];
  Input.insert(Input.end() - 1, Callback);
  return Input;
}

TEST(MobileDalvikJava, InheritedClosedScalarsKeepUnusedOwnerFormalsAndDefault) {
  for (const std::string Type : {"Z", "I", "J"})
    for (bool Range : {false, true})
      for (bool Intermediate : {false, true})
        for (bool SDK : {false, true})
          for (unsigned Formals : {1u, 2u})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{Type, Range, Intermediate, SDK, Formals, Route}));
              auto Input = inheritedClosedScalarClasses(
                  Type, Range, Intermediate, SDK, Formals);
              const auto Access = Input.back().methods[0].reference;
              const auto Dispatch = std::get<MethodRef>(
                  Input.back().methods[0].instructions[0].reference);
              const auto Target = Input[0].methods[0].reference;
              const auto Original = Input.back().generic_signature;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              const auto P = planGenericInheritance(Classes, Plans, B);
              ASSERT_EQ(P.scoped_interface_super_calls.at({Access, Dispatch}),
                        Target);
              EXPECT_EQ(Classes.at(Access.owner).generic_signature, Original);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 9);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
            }
}

