      auto &Access = Child.methods[0];
      if (Mutation == 0)
        Target.generic_signature =
            "<T:Ljava/lang/Object;>(JLfixture/Callback<TT;>;)Z";
      else if (Mutation == 1)
        Target.generic_signature = "(JLfixture/Callback<-Lmissing/Type;>;)Z";
      else if (Mutation == 2)
        Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 3)
        Child.generic_signature =
            "<C:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/DefaultApi<TC;>;";
      else if (Mutation == 4)
        Child.interfaces.push_back("Lmissing/Other;");
      else if (Mutation == 5)
        Parent.methods.clear();
      else if (Mutation == 6)
        Target.access.insert("abstract");
      else if (Mutation == 7)
        Target.access.insert("static");
      else if (Mutation == 8)
        Access.instructions[0].registers = {1, 3, 2, 4};
      else if (Mutation == 9)
        Access.instructions[1].opcode = "move-result-object";
      else if (Mutation == 10)
        Access.access.erase("synthetic");
      else if (Mutation == 11)
        Target.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 12)
        Child.enclosing_method = Target.reference;
      else if (Mutation == 13)
        Parent.interfaces = {Child.name};
