std::vector<Class> inheritedSeededDefaultClasses(bool ReverseInputs, bool Range,
                                                 bool Middle, bool SDK,
                                                 bool Shadow) {
  const std::string Object = "Ljava/lang/Object;";
  auto Apply = method("invoke", {Object, Object}, Object, 0, {});
  Apply.access = {"public", "abstract"};
  Apply.generic_signature = "(TA;TB;)TC;";
  auto Callback = klass("Lfixture/Callback;", {Apply});
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;"
                               "C:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = SDK;
  auto Step = method("step", {Object, Callback.name}, Object, 3,
                     {op(0, "return-object", {1})});
  Step.access = {"public"};
  Step.generic_signature =
      "<R:Ljava/lang/Object;>(TR;Lfixture/Callback<" +
      std::string(ReverseInputs ? "-Lfixture/Parent;-TR;"
                                : "-TR;-Lfixture/Parent;") +
      "+TR;>;)TR;";
  auto Parent = klass("Lfixture/Parent;", {Step});
  Parent.access = {"public", "interface", "abstract"};
  auto Intermediate = klass("Lfixture/Middle;");
  Intermediate.access = Parent.access;
  Intermediate.interfaces = {Parent.name};
  auto Child = klass("Lfixture/Child;");
  Child.access = Parent.access;
  Child.interfaces = {Middle ? Intermediate.name : Parent.name};
  Child.generic_signature = std::string(Shadow ? "<R:Ljava/lang/Number;>"
                                               : "<T:Ljava/lang/Object;>") +
                            "Ljava/lang/Object;" + Child.interfaces[0];
  auto Dispatch = Parent.methods[0].reference;
  Dispatch.owner = Child.name;
  auto Access =
      method("access$step$jd", {Child.name, Object, Callback.name}, Object, 4,
             {op(0, Range ? "invoke-super/range" : "invoke-super", {1, 2, 3},
                 {}, Dispatch),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Access.reference.owner = Child.name;
  Access.access = {"public", "static", "synthetic"};
  Child.methods.push_back(Access);
  auto ObjectType = klass(Object);
  ObjectType.external = true;
  ObjectType.superclass.reset();
  auto Number = klass("Ljava/lang/Number;");
  Number.access.insert("abstract");
  Number.external = true;
  std::vector<Class> Input{Child, Parent, Callback, ObjectType, Number};
  if (Middle)
    Input.push_back(Intermediate);
  return Input;
}

TEST(MobileDalvikJava, InheritedSeededDefaultsConsumeCanonicalMethodErasure) {
  for (bool ReverseInputs : {false, true})
    for (bool Range : {false, true})
      for (bool Middle : {false, true})
        for (bool SDK : {false, true})
          for (bool Shadow : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  ReverseInputs, Range, Middle, SDK, Shadow, Route}));
              auto Input = inheritedSeededDefaultClasses(ReverseInputs, Range,
                                                         Middle, SDK, Shadow);
              const auto Access = Input[0].methods[0].reference;
              const auto Dispatch = std::get<MethodRef>(
                  Input[0].methods[0].instructions[0].reference);
              const auto Target = Input[1].methods[0].reference;
              const auto Original = Input[1].methods[0].generic_signature;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.erased_generic_invocations.contains(Target));
              EXPECT_EQ(sourceMethodSignature(Target, Plans),
                        &Plans.methods.at(Target));
              const auto P = planGenericInheritance(Classes, Plans, B);
              ASSERT_EQ(P.scoped_interface_super_calls.at({Access, Dispatch}),
                        Target);
              EXPECT_EQ(Classes.at(Target.owner).methods[0].generic_signature,
                        Original);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 9);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              for (const auto &Unit : *R.getArray("source_units"))
                if (Unit.getAsObject()->getString("class") == Access.owner)
                  EXPECT_EQ(
                      Unit.getAsObject()->getString("source")->find("((R)"),
                      llvm::StringRef::npos);
            }
}

