std::vector<Class> inheritedFluentDefaultClasses(bool Range, bool Middle,
                                                 bool Shadow) {
  auto Input =
      inheritedSeededDefaultClasses(false, Range, Middle, true, Shadow);
  auto &Parent = Input[1];
  auto &Target = Parent.methods[0];
  Target.reference.parameters = {Parent.name};
  Target.reference.returns = Parent.name;
  Target.generic_signature.reset();
  Target.registers = 2;
  auto &Access = Input[0].methods[0];
  Access.reference.parameters = {Input[0].name, Parent.name};
  Access.reference.returns = Parent.name;
  Access.registers = 3;
  auto Dispatch = Target.reference;
  Dispatch.owner = Input[0].name;
  Access.instructions[0].reference = Dispatch;
  Access.instructions[0].registers = {1, 2};
  return Input;
}

