namespace {
std::vector<Class> binaryMergeFactoryClasses(bool SDKTarget, bool SDKTypes,
                                             bool Range, bool Frame, bool Alpha,
                                             bool Shadow, unsigned Variance) {
  const std::string T = Alpha ? "Element" : "T";
  auto Make =
      method("build", {"Lfixture/Name;", "Lfixture/Label;", "Lfixture/Merge;"},
             "Lfixture/Box;", 4,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.reference.owner = "Lfixture/Provider;";
  Make.generic_signature = "<" + T +
                           ":Ljava/lang/Object;>(Lfixture/Name;Lfixture/Label;"
                           "Lfixture/Merge<" +
                           (Variance & 1 ? "" : "-") + "T" + T + ";" +
                           (Variance & 2 ? "" : "-") + "T" + T + ";" +
                           (Variance & 4 ? "" : "+") + "T" + T +
                           ";>;)Lfixture/Box<T" + T + ";>;";
  auto Call =
      method("call", Make.reference.parameters, Make.reference.returns, 4,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2, 3},
                 {}, Make.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  if (Frame)
    for (auto *M : {&Make, &Call}) {
      M->registers += 3;
      for (auto &I : M->instructions)
        for (auto &R : I.registers)
          R += 3;
    }
  auto Provider = klass(Make.reference.owner, {Make});
  if (Shadow)
    Provider.generic_signature =
        "<" + T + ":Ljava/lang/Object;>Ljava/lang/Object;";
  Provider.external = SDKTarget;
  if (SDKTarget) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Merge = klass("Lfixture/Merge;");
  Merge.access = {"public", "abstract", "interface"};
  Merge.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;"
                            "R:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Merge.external = Box.external = SDKTypes;
  auto Name = klass("Lfixture/Name;");
  auto Label = klass("Lfixture/Label;");
  Name.external = Label.external = true;
  return {klass("Lfixture/Core;", {Call}), Provider, Merge, Box, Name, Label};
}
} // namespace

