TEST(MobileDalvikJava,
     CovariantContextListVoidsRejectIncompleteCarriersContextsAndScopes) {
  for (unsigned Mutation = 0; Mutation != 14; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input = covariantContextListVoidClasses(true, false, false, true, 1);
    auto &Write = Input[1].methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      auto &Text = *Write.generic_signature;
      const auto At = Text.find(From);
      ASSERT_NE(At, std::string::npos);
      Text.replace(At, From.size(), To);
    };
    if (Mutation == 0)
      replace("<+TT;>", "<+TMissing;>");
    else if (Mutation == 1)
      replace("T::Lfixture/Mark;>", "T::Lfixture/Missing;>");
    else if (Mutation == 2)
      replace("<+TT;>", "<+TT;+TT;>");
    else if (Mutation == 3)
      replace("T::Lfixture/Mark;>", "T::Lfixture/Mark;U::Lfixture/Mark;>");
    else if (Mutation == 4)
      replace("T::Lfixture/Mark;>", "T:Ljava/lang/Object;:Lfixture/Mark;>");
    else if (Mutation == 5)
      Write.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 6)
      Write.access = {"private", "static"};
    else if (Mutation == 7)
      Write.access.insert("varargs");
    else if (Mutation == 8)
      Input[1].generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    else if (Mutation == 9) {
      for (auto &C : Input)
        if (C.name == "Lfixture/Context;")
          C.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
    } else if (Mutation == 10)
      Input.back().generic_signature =
          "<B:Ljava/lang/Number;>Ljava/lang/Object;";
    else if (Mutation == 11)
      Input.back().access = {"private", "abstract", "interface"};
    else if (Mutation == 12) {
      replace("Ljava/lang/String;", "I");
      Write.reference.parameters[1] = "I";
      auto &Call = Input[0].methods[0];
      Call.reference.parameters = Write.reference.parameters;
      Call.instructions[0].reference = Write.reference;
    } else
      replace("<+TT;>", "<Lfixture/Missing<TT;>;>");
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

