TEST(MobileDalvikJava,
     ContextualTokenCarriersRejectUnboundResultsVariantTokensAndOpenContexts) {
  for (unsigned Mutation = 0; Mutation != 12; ++Mutation) {
    SCOPED_TRACE(Mutation);
    auto Input =
        contextualTokenCarrierClasses(true, false, false, true, true, true);
    auto &Read = Input[1].methods[0];
    auto replace = [&](const std::string &From, const std::string &To) {
      auto &Text = *Read.generic_signature;
      const auto At = Text.find(From);
      ASSERT_NE(At, std::string::npos);
      Text.replace(At, From.size(), To);
    };
    if (Mutation == 0)
      replace("Token<TT;>", "Token<+TT;>");
    else if (Mutation == 1)
      replace("Token<TT;>", "Token<-TT;>");
    else if (Mutation == 2)
      replace("Result<TT;>", "Result");
    else if (Mutation == 3)
      replace("Result<TT;>", "Result<Lfixture/Mark;>");
    else if (Mutation == 4)
      replace("Result<TT;>", "Result<+TT;>");
    else if (Mutation == 5) {
      replace("T::Lfixture/Mark;>", "T::Lfixture/Mark;U::Lfixture/Mark;>");
      replace("Result<TT;>", "Result<TU;>");
    } else if (Mutation == 6)
      replace("T::Lfixture/Mark;>", "T:Ljava/lang/Object;:Lfixture/Mark;>");
    else if (Mutation == 7)
      Read.declared_throws = {"Ljava/lang/Exception;"};
    else if (Mutation == 8)
      Read.access.insert("abstract");
    else if (Mutation == 9)
      Read.access = {"private", "static"};
    else if (Mutation == 10)
      Input.back().generic_signature = "<E:Lfixture/Mark;>Ljava/lang/Object;";
    else
      Input[3].generic_signature = "<U:Ljava/lang/Object;>Ljava/lang/Object;";
    EXPECT_THROW(recover(Input), std::runtime_error);
  }
}

