TEST(MobileDalvikJava, ContextArrayTokensRejectOpenContextsAndForeignAccess) {
  for (unsigned Mutation = 0; Mutation < 27; ++Mutation)
    for (unsigned Route : {0u, 1u, 2u}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      unsigned Kind = Mutation >= 24                     ? 3
                      : Mutation >= 20 && Mutation <= 22 ? 2
                                                         : 1;
      auto Input = contextArrayResultClasses(Kind, 0, false, true, false, true);
      auto &Read = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      const std::string Prefix =
          "<T:Ljava/lang/Object;>(Lfixture/Context;Ljava/lang/String;";
      switch (Mutation) {
      case 0:
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 1:
        Input[3].name = "Lfixture/Missing;";
        break;
      case 2:
        Input[3].access = {"private"};
        break;
      case 3:
        Input[2].name = "Lfixture/MissingToken;";
        break;
      case 4:
        Input[2].generic_signature = "<V:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 5:
        Read.generic_signature = Prefix + "Ljava/lang/Class;)[TT;";
        break;
      case 6:
        Read.generic_signature = Prefix + "Ljava/lang/Class<+TT;>;)[TT;";
        break;
      case 7:
        Read.generic_signature = Prefix + "Ljava/lang/Class<-TT;>;)[TT;";
        break;
      case 8:
        Read.generic_signature =
            "<T:Ljava/lang/Number;>(Lfixture/Context;Ljava/lang/String;Ljava/"
            "lang/Class<TT;>;)[TT;";
        break;
      case 9:
        Read.generic_signature = Prefix + "Ljava/lang/Class<TT;>;)[[TT;";
        break;
      case 10:
        Read.generic_signature = Prefix + "Ljava/lang/Class<TU;>;)[TT;";
        break;
      case 11:
        Read.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Context;Ljava/lang/String;)[TT;";
        break;
      case 12:
        Read.access.insert("varargs");
        break;
      case 13:
        Read.access.insert("native");
        break;
      case 14:
        Read.access.insert("bridge");
        break;
      case 15:
        Read.access.erase("public");
        Read.access.insert("protected");
        break;
      case 16:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 17:
        Call.instructions[0].opcode = "invoke-virtual";
        break;
      case 18:
        Call.instructions[0].registers[1] = Call.registers;
        break;
      case 19:
        Call.instructions[1].opcode = "move-result";
        break;
      case 20:
        Input[0].name = "Loutside/Client;";
        Call.reference.owner = Input[0].name;
        break;
      case 21:
        Read.access.erase("static");
        break;
      case 22:
        Read.access.insert("private");
        break;
      case 23:
        Read.reference.parameters[0] = "Ljava/lang/Object;";
        Call.reference.parameters[0] = "Ljava/lang/Object;";
        break;
      case 24:
        Input[1].inner_access.clear();
        break;
      case 25:
        Input[1].enclosing_method =
            MethodRef{"Lfixture/Outer;", "run", {}, "V"};
        break;
      case 26:
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        Read.generic_signature =
            "<T:Ljava/lang/Object;>(Lfixture/Context<TT;>;Ljava/lang/"
            "String;Ljava/lang/Class<TT;>;)[TT;";
        break;
      }
      Call.instructions[0].reference = Read.reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

namespace {
std::vector<Class> contextCarrierTokenClasses(unsigned Kind, bool Range,
                                              bool Standard, bool Alpha,
                                              bool Used, bool Producer) {
  auto Input = contextArrayResultClasses(Kind, 0, Range, Standard, Alpha, Used);
  auto Box = klass("Lfixture/Box;");
  Box.generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
  Box.external = Kind == 1;
  auto &Read = Input[1].methods[0];
  const std::string T = Alpha ? "Item" : "T";
  Read.reference.returns = Box.name;
  Read.generic_signature =
      "<" + T + ":Ljava/lang/Object;>(Lfixture/Context;Ljava/lang/String;" +
      Input[2].name.substr(0, Input[2].name.size() - 1) + "<" +
      (Producer ? "+" : "") + "T" + T + ";>;)Lfixture/Box<T" + T + ";>;";
  auto &Call = Input[0].methods[0];
  Call.instructions[0].reference = Read.reference;
  if (Used)
    Call.reference.returns = Box.name;
  Input.push_back(Box);
  return Input;
}
} // namespace

