namespace {
std::vector<Class> fluentTokenConsumerClasses(bool SDK, bool Range, bool Alpha,
                                              bool Used, bool Self,
                                              bool Nested) {
  auto Input = carrierArrayResultClasses(SDK, 1, Range, false, true);
  auto &Provider = Input[1];
  auto &Read = Provider.methods[0];
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  auto Predicate = klass("Lfixture/Predicate;");
  Predicate.external = SDK;
  Predicate.access = {"public", "abstract", "interface"};
  Predicate.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Result = klass("Lfixture/Result;");
  Result.external = SDK;
  if (Nested) {
    Provider.name = "Lfixture/Outer$Entry;";
    Provider.access.insert("final");
    Provider.enclosing = "Lfixture/Outer;";
    Provider.inner_name = "Entry";
    Provider.inner_class_present = true;
    Provider.inner_access = {"public", "static", "final"};
    Read.reference.owner = Provider.name;
  }
  Read.reference.parameters = {String.name, Input[2].name, Predicate.name};
  Read.reference.returns = Self ? Provider.name : Result.name;
  const std::string T = Alpha ? "Item" : "T";
  Read.generic_signature =
      "<" + T + ":Ljava/lang/Object;>(Ljava/lang/String;Ljava/lang/Class<T" +
      T + ";>;Lfixture/Predicate<T" + T + ";>;)" + Read.reference.returns;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = {Provider.name, String.name, Input[2].name,
                               Predicate.name};
  Call.reference.returns = Used ? Read.reference.returns : "V";
  Call.instructions[0].reference = Read.reference;
  if (!Used) {
    Call.instructions = {Call.instructions[0], op(3, "return-void", {})};
    Call.code_end = 4;
  }
  Input.push_back(String);
  Input.push_back(Predicate);
  Input.push_back(Result);
  if (Nested) {
    auto Outer = klass("Lfixture/Outer;");
    Outer.external = SDK;
    Input.push_back(Outer);
  }
  return Input;
}
} // namespace

