namespace {
std::vector<Class> pairedInstanceNominalClasses(bool SDK, bool Range,
                                                bool Alpha, bool Used,
                                                bool FirstCallback,
                                                unsigned Variance) {
  auto Input =
      fluentTokenConsumerClasses(SDK, Range, Alpha, Used, false, false);
  auto &Read = Input[1].methods[0];
  auto &Call = Input[0].methods[0];
  auto &Callback = Input[4];
  Callback.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/"
                               "Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
  const std::string A = Alpha ? "Left" : "A", B = Alpha ? "Right" : "B";
  const std::string Left = "Ljava/lang/Class<T" + A + ";>;";
  const std::string Right = "Ljava/lang/Class<T" + B + ";>;";
  const std::string Direction = Variance == 1 ? "-" : Variance == 2 ? "+" : "";
  const std::string Slots =
      Variance == 3 ? Left + Right
                    : Direction + "T" + A + ";" + Direction + "T" + B + ";";
  const std::string Function =
      "Lfixture/Predicate<" + Slots + "Lfixture/Result;>;";
  Read.generic_signature =
      "<" + A + ":Ljava/lang/Object;" + B + ":Ljava/lang/Object;>(" +
      (FirstCallback ? Function + Left + Right : Left + Right + Function) +
      ")Ljava/lang/Object;";
  Read.reference.parameters =
      FirstCallback ? std::vector<std::string>{Callback.name, Input[2].name,
                                               Input[2].name}
                    : std::vector<std::string>{Input[2].name, Input[2].name,
                                               Callback.name};
  Read.reference.returns = "Ljava/lang/Object;";
  Call.reference.parameters = Read.reference.parameters;
  Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                   Input[1].name);
  Call.reference.returns = Used ? "Ljava/lang/Object;" : "V";
  Call.instructions[0].reference = Read.reference;
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  Input.push_back(Object);
  return Input;
}
} // namespace

