TEST(MobileDalvikJava,
     PairedInstanceNominalsRejectUnboundScopesAndIncompleteTrees) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 21; ++Mutation)
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            pairedInstanceNominalClasses(SDK, true, false, true, false, 1);
        auto &Read = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto change = [&](std::string_view Before, std::string_view After) {
          auto &Text = *Read.generic_signature;
          const auto At = Text.find(Before);
          ASSERT_NE(At, std::string::npos);
          Text.replace(At, Before.size(), After);
        };
        switch (Mutation) {
        case 0:
          change("Class<TB;>", "Class<+TB;>");
          break;
        case 1:
          change("Class<TB;>", "Class<TA;>");
          break;
        case 2:
          change("-TB;", "-TMissing;");
          break;
        case 3:
          change("B:Ljava/lang/Object;", "B:Ljava/lang/Number;");
          break;
        case 4:
          change("-TA;-TB;", "-TA;");
          break;
        case 5:
          change("-TA;-TB;", "*-TB;");
          break;
        case 6:
          Input[4].generic_signature =
              "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 7:
          Input[4].access = {"private", "interface", "abstract"};
          break;
        case 8:
          Input[4].name = "Lfixture/MissingCallback;";
          break;
        case 9:
          Input[5].name = "Lfixture/MissingResult;";
          break;
        case 10:
          Input[2].generic_signature =
              "<A:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 11:
          Read.access.insert("synthetic");
          break;
        case 12:
          Read.access.insert("varargs");
          break;
        case 13:
          Read.access.insert("bridge");
          break;
        case 14:
          Read.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 15:
          Call.instructions[0].registers.pop_back();
          break;
        case 16:
          Call.instructions[0].registers[1] = Call.registers;
          break;
        case 17:
          Call.instructions[1].opcode = "move-result";
          break;
        case 18:
          Read.access.insert("static");
          break;
        case 19:
          change(")Ljava/lang/Object;", ")TForeign;");
          break;
        case 20:
          Input[1].generic_signature = "<C:TMissing;>Ljava/lang/Object;";
          break;
        }
        Call.instructions[0].reference = Read.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        ClassMap Classes;
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
        EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> instancePlainResultClasses(bool SDK, bool Range, bool Paired,
                                              std::string Returns, bool Used) {
  auto Input =
      Paired
          ? pairedInstanceNominalClasses(SDK, Range, false, true, false, 1)
          : fluentTokenConsumerClasses(SDK, Range, false, true, false, false);
  auto &Read = Input[1].methods[0];
  auto &Call = Input[0].methods[0];
  auto &Signature = *Read.generic_signature;
  Signature = Signature.substr(0, Signature.rfind(')') + 1) + Returns;
  Read.reference.returns = Returns;
  const bool Void = Returns == "V", Wide = width(Returns) == 2;
  if (!SDK) {
    Read.registers = Read.incomingWords() + 2;
    Read.instructions =
        Void ? std::vector<Instruction>{op(0, "return-void", {})}
             : std::vector<Instruction>{
                   op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
                   op(1, Wide ? "return-wide" : "return", {0})};
    Read.code_end = Read.instructions.back().pc + 1;
  }
  Call.reference.returns = Used && !Void ? Returns : "V";
  Call.instructions[0].reference = Read.reference;
  const auto Invoke = Call.instructions[0];
  Call.instructions =
      Used && !Void
          ? std::vector<Instruction>{Invoke,
                                     op(3,
                                        Wide ? "move-result-wide"
                                             : "move-result",
                                        {0}),
                                     op(4, Wide ? "return-wide" : "return",
                                        {0})}
          : std::vector<Instruction>{Invoke, op(3, "return-void", {})};
  Call.code_end = Call.instructions.back().pc + 1;
  return Input;
}
} // namespace

