namespace {
std::vector<Class>
typedVisibilityBridgeClasses(bool SDK, bool Range, bool Key,
                             std::string Returns = "Ljava/lang/Object;") {
  const std::string Input = Key ? "Ljava/lang/Class;" : "Ljava/util/List;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void", {})});
  Init.access = {"constructor"};
  bool Void = Returns == "V", Wide = width(Returns) == 2,
       Ref = Returns.starts_with('L') || Returns.starts_with('[');
  auto Read =
      method("read", {"Ljava/lang/Object;", "Ljava/lang/Object;", Input, "I"},
             Returns, 7, {});
  Read.access = {"public"};
  Read.generic_signature =
      "(Ljava/lang/Object;Ljava/lang/Object;" +
      (Key ? std::string("Ljava/lang/Class<*>;")
           : std::string("Ljava/util/List<[Ljava/lang/String;>;")) +
      "I)" + Returns;
  Read.instructions =
      Void ? std::vector<Instruction>{op(0, "return-void", {})}
           : std::vector<Instruction>{
                 op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
                 op(1,
                    Ref    ? "return-object"
                    : Wide ? "return-wide"
                           : "return",
                    {0})};
  Read.code_end = Void ? 1 : 2;
  auto Root = klass("Lfixture/Root;", {Init, Read});
  Root.access.clear();
  auto Mid = klass("Lfixture/Mid;", {Init});
  Mid.access.clear();
  Mid.superclass = Root.name;
  Mid.methods[0].instructions[0].reference = Root.methods[0].reference;
  auto Bridge = Read;
  Bridge.generic_signature.reset();
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.parameter_metadata = std::vector<ParameterMetadata>(
      4, ParameterMetadata{std::nullopt, 0x1000});
  Bridge.registers = Range ? 25 : 5;
  const unsigned Start = Bridge.registers - 5;
  auto Target = Root.methods[1].reference;
  Target.owner = Mid.name;
  Bridge.instructions = {op(0, Range ? "invoke-super/range" : "invoke-super",
                            {Start, Start + 1, Start + 2, Start + 3, Start + 4},
                            {}, Target)};
  if (!Void)
    Bridge.instructions.push_back(op(3,
                                     Ref    ? "move-result-object"
                                     : Wide ? "move-result-wide"
                                            : "move-result",
                                     {0}));
  Bridge.instructions.push_back(
      op(Void ? 3 : 4,
         Void   ? "return-void"
         : Ref  ? "return-object"
         : Wide ? "return-wide"
                : "return",
         Void ? std::vector<unsigned>{} : std::vector<unsigned>{0}));
  Bridge.code_end = Void ? 4 : 5;
  auto Core = klass("Lfixture/Core;", {Init, Bridge});
  Core.superclass = Mid.name;
  Core.methods[0].access = {"public", "constructor"};
  Core.methods[0].instructions[0].reference = Mid.methods[0].reference;
  auto Call = Read;
  Call.reference.name = "call";
  Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                   Core.name);
  Call.generic_signature.reset();
  Call.access = {"public", "static"};
  Call.registers = 7;
  Call.instructions = {
      op(0, "invoke-virtual", {2, 3, 4, 5, 6}, {}, Core.methods[1].reference)};
  if (!Void)
    Call.instructions.push_back(op(3,
                                   Ref    ? "move-result-object"
                                   : Wide ? "move-result-wide"
                                          : "move-result",
                                   {0}));
  Call.instructions.push_back(
      op(Void ? 3 : 4,
         Void   ? "return-void"
         : Ref  ? "return-object"
         : Wide ? "return-wide"
                : "return",
         Void ? std::vector<unsigned>{} : std::vector<unsigned>{0}));
  Call.code_end = Void ? 4 : 5;
  auto Caller = klass("Loutside/Caller;", {Call});
  auto Carrier = klass(Input);
  Carrier.external = true;
  Carrier.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  if (!Key)
    Carrier.access = {"public", "abstract", "interface"};
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  if (SDK)
    for (auto *C : {&Root, &Mid}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return {Root, Mid, Core, Caller, Carrier, String};
}
} // namespace

