namespace {
std::vector<Class> typedVisibilitySuperClasses(bool SDK, bool Range, bool Key,
                                               std::string Returns) {
  auto Input = typedVisibilityBridgeClasses(SDK, Range, Key, Returns);
  auto Parent = Input[2].methods[1];
  Parent.reference.name = "parent";
  Parent.access = {"public"};
  Parent.parameter_metadata.reset();
  Parent.instructions[0].reference = Input[2].methods[1].reference;
  auto Sub = klass("Loutside/Sub;", {Parent});
  Sub.superclass = Input[2].name;
  Input.push_back(std::move(Sub));
  return Input;
}
} // namespace

TEST(MobileDalvikJava, TypedVisibilityBridgesKeepExactSuperclassDispatch) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Key : {false, true})
        for (const std::string Returns : {"V", "Z", "J", "Ljava/lang/Object;"})
          for (unsigned Route : {0u, 1u, 2u}) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Key, Returns, Route}));
            auto Input = typedVisibilitySuperClasses(SDK, Range, Key, Returns);
            const auto Caller = Input.back().methods[0].reference;
            const auto Entry = Input[2].methods[1].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Entry}));
            EXPECT_EQ(Plans.superclass_call_declarations.at({Caller, Entry}),
                      Entry);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            bool Found = false;
            for (const auto &Unit : *R.getArray("source_units"))
              if (Unit.getAsObject()->getString("path") == "outside/Sub.java") {
                Found = true;
                const auto Text =
                    Unit.getAsObject()->getString("source")->str();
                EXPECT_NE(Text.find("super.read("), std::string::npos);
                EXPECT_EQ(Text.find(") super)"), std::string::npos);
                EXPECT_EQ(Text.find("this.read("), std::string::npos);
              }
            EXPECT_TRUE(Found);
          }
}

