            auto Input = arrayElementSelectorClasses(Mode, Extra, Range, Lower);
            const auto Entry = Input[0].methods[0].reference;
            const auto Signature = Input[0].methods[0].generic_signature;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
