          recoverJava(packageMetadataClasses({Package, C}, Route, B), B);
      EXPECT_EQ(R.getInteger("class_count"), Owned ? 2 : 1);
      EXPECT_EQ(R.getInteger("method_count"), 1);
      EXPECT_EQ(R.getInteger("recovered_method_count"), 1);
      EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
      EXPECT_EQ(R.getArray("java_compiler_options") != nullptr, Owned);
      EXPECT_EQ(R.getArray("package_metadata_classes") != nullptr, Owned);
