          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
          const auto Text = source(R, 1);
          EXPECT_NE(Text.find("synchronized (((java.lang.Object) o8))"),
                    std::string::npos);
          EXPECT_NE(Text.find("case 9:"), std::string::npos);
