namespace {
std::vector<Class> pairedContextTokenClasses(unsigned Kind, unsigned Dispatch,
                                             bool Range, bool Standard,
                                             bool Alpha, bool Used,
                                             bool Producer) {
  auto Input =
      contextArrayResultClasses(Kind, Dispatch, Range, Standard, Alpha, Used);
  auto Box = klass("Lfixture/Pair;");
  Box.generic_signature = "<Left:Ljava/lang/Object;Right:Ljava/lang/Object;>"
                          "Ljava/lang/Object;";
  Box.external = Kind == 1;
  auto &Read = Input[1].methods[0];
  const std::string First = Alpha ? "Key" : "A";
  const std::string Second = Alpha ? "Value" : "B";
  const std::string Carrier = Input[2].name;
  const auto token = [&](const std::string &Formal) {
    return Carrier.substr(0, Carrier.size() - 1) + "<" + (Producer ? "+" : "") +
           "T" + Formal + ";>;";
  };
  Read.reference.parameters = {"Lfixture/Context;", "Ljava/lang/String;",
                               Carrier, Carrier};
  Read.reference.returns = Box.name;
  Read.generic_signature = "<" + (Alpha ? Second : First) +
                           ":Ljava/lang/Object;" + (Alpha ? First : Second) +
                           ":Ljava/lang/Object;>(Lfixture/Context;"
                           "Ljava/lang/String;" +
                           token(First) + token(Second) + ")Lfixture/Pair<T" +
                           First + ";T" + Second + ";>;";
  if (!Input[1].external) {
    Read.registers = Read.incomingWords() + 1;
    Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Read.code_end = 2;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  if (Dispatch)
    Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                     Input[1].name);
  Call.reference.returns = Used ? Box.name : "V";
  Call.registers = Call.incomingWords() + 1;
  std::vector<unsigned> Words;
  for (unsigned I = 1; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {
      op(0,
         std::string(Dispatch ? "invoke-virtual" : "invoke-static") +
             (Range ? "/range" : ""),
         Words, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
    Call.code_end = 5;
  } else {
    Call.instructions.push_back(op(3, "return-void", {}));
    Call.code_end = 4;
  }
  Input.push_back(Box);
  return Input;
}
} // namespace

TEST(MobileDalvikJava, PairedContextTokensKeepDistinctScopedResultSlots) {
  for (unsigned Kind = 0; Kind < 4; ++Kind)
    for (unsigned Dispatch = 0; Dispatch < (Kind < 2 ? 2u : 1u); ++Dispatch)
      for (bool Range : {false, true})
        for (bool Standard : {false, true})
          for (bool Alpha : {false, true})
            for (bool Used : {false, true})
              for (bool Producer : {false, true})
                for (unsigned Route : {0u, 1u, 2u}) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{Kind, Dispatch, Range, Standard, Alpha, Used,
                                 Producer, Route}));
                  auto Input = pairedContextTokenClasses(
                      Kind, Dispatch, Range, Standard, Alpha, Used, Producer);
                  const auto Target = Input[1].methods[0].reference;
                  const auto Original = Input[1].methods[0].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  if (Route)
                    Classes = linkClasses(Input, B);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(
                      Plans.erased_generic_invocations.contains(Target));
                  EXPECT_EQ(
                      Classes.at(Target.owner).methods[0].generic_signature,
                      Original);
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                }
}

TEST(MobileDalvikJava, PairedContextTokensRejectIncompleteAndForeignContracts) {
  for (unsigned Mutation = 0; Mutation < 30; ++Mutation)
    for (unsigned Route : {0u, 1u, 2u}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          pairedContextTokenClasses(3, 0, false, true, false, true, true);
      auto &Read = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto Replace = [&](std::string_view From, std::string_view To) {
        auto &Signature = *Read.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        Replace("Class<+TA;>", "Class<-TA;>");
        break;
      case 1:
        Replace("Class<+TA;>", "Class<*>");
        break;
      case 2:
        Replace("Class<+TA;>", "Class");
        break;
      case 3:
        Replace("Class<+TB;>", "Class<+TA;>");
        break;
      case 4:
        Replace("Pair<TA;TB;>", "Pair<TA;TA;>");
        break;
      case 5:
        Replace("Pair<TA;TB;>", "Pair<+TA;TB;>");
        break;
      case 6:
        Replace("Pair<TA;TB;>", "Pair");
        break;
      case 7:
        Replace("Class<+TA;>", "Class<+TX;>");
        break;
      case 8:
        Replace("B:Ljava/lang/Object;>",
                "B:Ljava/lang/Object;C:Ljava/lang/Object;>");
        break;
      case 9:
        Input[2].generic_signature = "<V:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 10:
        Input[2].name = "Lfixture/MissingToken;";
        break;
      case 11:
        Input.back().generic_signature =
            "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 12:
        Input.back().generic_signature =
            "<A:Ljava/lang/Number;B:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 13:
        Input.back().name = "Lfixture/MissingPair;";
        break;
      case 14:
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 15:
        Input[3].access = {"private"};
        break;
      case 16:
        Read.access.insert("private");
        break;
      case 17:
        Read.access.insert("protected");
        break;
      case 18:
        Read.access.insert("synthetic");
        break;
      case 19:
        Read.access.insert("bridge");
        break;
      case 20:
        Read.access.insert("native");
        break;
      case 21:
        Read.access.insert("varargs");
        break;
      case 22:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 23:
        Input[1].inner_access.clear();
        break;
      case 24:
        Input[1].enclosing_method =
            MethodRef{"Lfixture/Outer;", "run", {}, "V"};
        break;
      case 25:
        Input[0].name = "Loutside/Client;";
        Call.reference.owner = Input[0].name;
        break;
      case 26:
        Call.instructions[0].opcode = "invoke-virtual";
        break;
      case 27:
        Call.instructions[0].registers[3] = Call.registers;
        break;
      case 28:
        Call.instructions[1].opcode = "move-result";
        break;
      case 29:
        Replace("Lfixture/Context;", "Lfixture/Context<*>;");
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      }
      Call.instructions[0].reference = Read.reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

