std::vector<Class> contextTokenTransferClasses(unsigned Kind, unsigned Dispatch,
                                               bool Range, bool Standard,
                                               bool Alpha, bool Used,
                                               bool Producer) {
  auto Input =
      contextCarrierTokenClasses(Kind, Range, Standard, Alpha, Used, Producer);
  auto &Carrier = Input.back();
  Carrier.name = Standard ? "Ljava/util/List;" : "Lfixture/Box;";
  if (Standard) {
    Carrier.external = true;
    Carrier.access = {"public", "abstract", "interface"};
  }
  auto &Read = Input[1].methods[0];
  const std::string T = Alpha ? "Item" : "T";
  const std::string Token = Input[2].name;
  const std::string Applied =
      Carrier.name.substr(0, Carrier.name.size() - 1) + "<T" + T + ";>;";
  const std::string Context = Dispatch ? "" : "Lfixture/Context;";
  Read.reference.parameters = {Carrier.name, "Ljava/lang/String;", Token};
  if (Dispatch)
    Read.access = {"public"};
  else
    Read.reference.parameters.insert(Read.reference.parameters.begin(),
                                     "Lfixture/Context;");
  Read.reference.returns = Carrier.name;
  Read.generic_signature = "<" + T + ":Ljava/lang/Object;>(" + Context +
                           Applied + "Ljava/lang/String;" +
                           Token.substr(0, Token.size() - 1) + "<" +
                           (Producer ? "+" : "") + "T" + T + ";>;)" + Applied;
  if (!Input[1].external) {
    Read.registers = Read.incomingWords() + 1;
    Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Read.code_end = 2;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  if (Dispatch)
    Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                     Input[1].name);
  Call.reference.returns = Used ? Carrier.name : "V";
  Call.registers = Call.incomingWords() + 1;
  std::vector<unsigned> Words;
  for (unsigned I = 1; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {
      op(0,
         std::string(Dispatch ? "invoke-virtual" : "invoke-static") +
             (Range ? "/range" : ""),
         Words, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
    Call.code_end = 5;
  } else {
    Call.instructions.push_back(op(3, "return-void"));
    Call.code_end = 4;
  }
  return Input;
}
