        Replace(";)Ljava/util/List<TT;>", ";)Ljava/util/List");
        break;
      case 6:
        Replace("Class<TT;>", "Class<-TT;>");
        break;
      case 7:
        Replace("Class<TT;>", "Class<*>");
        break;
      case 8:
        Replace("Class<TT;>", "Class");
        break;
      case 9:
        Replace("Class<TT;>", "Class<TU;>");
        break;
      case 10:
        Replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        break;
      case 11:
        Input[2].generic_signature = "<V:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 12:
        Input[2].name = "Lfixture/MissingToken;";
        break;
      case 13:
        Input.back().generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 14:
        Input.back().generic_signature =
            "<V:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 15:
        Input.back().name = "Lfixture/MissingCarrier;";
        break;
      case 16:
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 17:
        Input[3].access = {"private"};
        break;
      case 18:
        Read.access.insert("private");
        break;
      case 19:
        Read.access.insert("protected");
        break;
      case 20:
        Read.access.insert("synthetic");
        break;
      case 21:
        Read.access.insert("bridge");
        break;
      case 22:
        Read.access.insert("native");
        break;
      case 23:
        Read.access.insert("varargs");
        break;
      case 24:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 25:
        Input[1].inner_access.clear();
        break;
      case 26:
        Input[1].enclosing_method =
            MethodRef{"Lfixture/Outer;", "run", {}, "V"};
        break;
      case 27:
        Input[0].name = "Loutside/Client;";
        Call.reference.owner = Input[0].name;
        break;
      case 28:
        Call.instructions[0].registers[3] = Call.registers;
        break;
      case 29:
        Call.instructions[1].opcode = "move-result";
