namespace {
std::vector<Class> unaryTokenSinkClasses(unsigned Kind, unsigned Dispatch,
                                         bool Range, bool Standard,
                                         bool Alpha) {
  auto Input =
      pairedContextSinkClasses(Kind, Dispatch, Range, Standard, Alpha, 1);
  auto &Sink = Input.back();
  Sink.name = Standard ? "Ljava/util/List;" : "Lfixture/Sink;";
  Sink.generic_signature = "<Element:Ljava/lang/Object;>Ljava/lang/Object;";
  const std::string T = Alpha ? "Item" : "T";
  const std::string Token = Input[2].name;
  auto &Read = Input[1].methods[0];
  const std::string Context = Dispatch ? "" : "Lfixture/Context;";
  const std::string Consumer =
      Sink.name.substr(0, Sink.name.size() - 1) + "<-T" + T + ";>;";
  Read.reference.parameters = {Sink.name, "Ljava/lang/String;", Token};
  if (!Dispatch)
    Read.reference.parameters.insert(Read.reference.parameters.begin(),
                                     "Lfixture/Context;");
  Read.generic_signature = "<" + T + ":Ljava/lang/Object;>(" + Context +
                           Consumer + "Ljava/lang/String;" +
                           Token.substr(0, Token.size() - 1) + "<T" + T +
                           ";>;)V";
  if (!Input[1].external)
    Read.registers = Read.incomingWords();
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  if (Dispatch)
    Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                     Input[1].name);
  Call.registers = Call.incomingWords();
  Call.instructions[0].registers.clear();
  for (unsigned I = 0; I < Call.registers; ++I)
    Call.instructions[0].registers.push_back(I);
  Call.instructions[0].reference = Read.reference;
  return Input;
}
} // namespace

