TEST(MobileDalvikJava,
     ContextProducerThrowsRejectOpenContractsAndUnknownExceptions) {
  for (unsigned Mutation = 0; Mutation < 28; ++Mutation)
    for (unsigned Route : {0u, 1u, 2u}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = contextProducerThrowsClasses(3, false, true, false, true,
                                                false, false);
      auto &Read = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto Replace = [&](std::string_view From, std::string_view To) {
        auto &S = *Read.generic_signature;
        const auto At = S.find(From);
        ASSERT_NE(At, std::string::npos);
        S.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        Replace("Callable<TT;>", "Callable<+TT;>");
        break;
      case 1:
        Replace("Callable<TT;>", "Callable<-TT;>");
        break;
      case 2:
        Replace("Callable<TT;>", "Callable<*>");
        break;
      case 3:
        Replace("Callable<TT;>", "Callable");
        break;
      case 4:
        Replace("Callable<TT;>", "Callable<TU;>");
        break;
      case 5:
        Replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        break;
      case 6:
        Replace(")TT;", ")Ljava/lang/Object;");
        break;
      case 7:
        Input[2].generic_signature = "<V:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 8:
        Input[2].name = "Lfixture/MissingProducer;";
        break;
      case 9:
        Input[3].generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 10:
        Input[3].access = {"private"};
        break;
      case 11:
        Read.declared_throws = {"Lfixture/MissingFailure;"};
        break;
      case 12:
        Read.declared_throws = {"Ljava/lang/String;"};
        break;
      case 13:
        Input.back().superclass = "Ljava/lang/Object;";
        break;
      case 14:
        Replace("TT;", "TT;^Ljava/lang/InterruptedException;");
        break;
      case 15:
        Read.access.insert("private");
        break;
      case 16:
        Read.access.insert("protected");
        break;
      case 17:
        Read.access.insert("synthetic");
        break;
      case 18:
        Read.access.insert("bridge");
        break;
      case 19:
        Read.access.insert("native");
        break;
      case 20:
        Read.access.insert("varargs");
        break;
      case 21:
        Read.access.erase("static");
        break;
      case 22:
        Input[1].inner_access.clear();
        break;
      case 23:
        Input[1].enclosing_method =
            MethodRef{"Lfixture/Outer;", "run", {}, "V"};
        break;
      case 24:
        Input[0].name = "Loutside/Client;";
        Call.reference.owner = Input[0].name;
        break;
      case 25:
        Call.instructions[0].registers[2] = Call.registers;
        break;
      case 26:
        Call.instructions[1].opcode = "move-result";
        break;
      case 27:
        Replace("Lfixture/Context;", "I");
        Read.reference.parameters[0] = "I";
        Call.reference.parameters = Read.reference.parameters;
        break;
      }
      Call.instructions[0].reference = Read.reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      if (Mutation == 27) {
        // Closed scalars bind no formal and retain the same producer/result
        // relation and declared exceptions as a nominal context.
        const auto Original = Read;
        if (Route)
          Classes = linkClasses(Input, B);
        EXPECT_TRUE(
            validateGenericSignatures(Classes, B)
                .erased_generic_invocations.contains(Original.reference));
        const auto Report = recoverJava(Classes, B);
        EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(Report.getArray("generic_signature_projections"));
        const auto &After = Classes.at(Original.reference.owner).methods[0];
        EXPECT_EQ(After.generic_signature, Original.generic_signature);
        EXPECT_EQ(After.access, Original.access);
        EXPECT_EQ(After.declared_throws, Original.declared_throws);
      } else {
        EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                     std::runtime_error);
      }
    }
}

std::vector<Class> closedAllocatedCallbackClasses(bool SDK, bool Range,
                                                  bool Wide, bool Member,
                                                  bool Copy) {
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = SDK;
  auto Init = method("<init>", {Callback.name}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Lfixture/Callback<TP;>;)V";
  auto Other = Init;
  Other.reference.parameters = {"Ljava/lang/Object;"};
  Other.generic_signature.reset();
  auto Base = klass("Lfixture/Base;", {Init, Other});
  Base.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.external = SDK;
  if (SDK)
    for (auto &M : Base.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const std::vector<std::string> Parameters{"Lfixture/Value;",
                                            Wide ? "J" : "Ljava/lang/Object;"};
  auto AdapterInit =
      method("<init>", Parameters, "V", Wide ? 4 : 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  AdapterInit.access =
      Member ? Access{"constructor"} : Access{"public", "constructor"};
  auto Adapter = klass(Member ? "Lfixture/Scope$Adapter;" : "Lfixture/Adapter;",
                       {AdapterInit});
  Adapter.interfaces = {Callback.name};
  Adapter.generic_signature =
      "Ljava/lang/Object;Lfixture/Callback<Lfixture/Value;>;";
  const unsigned Self = Range ? 6 : Copy ? 4 : 1;
  std::vector<Instruction> Code;
  auto Append = [&](Instruction Op) {
    Op.pc = Code.size();
    Code.push_back(std::move(Op));
  };
  if (Range || Copy) {
    Append(op(0, "move-object/from16", {1, Self + 1}));
    Append(
        op(0, Wide ? "move-wide/from16" : "move-object/from16", {2, Self + 2}));
  }
  Append(op(0, "new-instance", {0}, {}, Adapter.name));
  const unsigned First = Range || Copy ? 1 : Self + 1;
  const unsigned Second = Range || Copy ? 2 : Self + 2;
  std::vector<unsigned> Arguments{0, First, Second};
  if (Wide)
    Arguments.push_back(Second + 1);
  Append(op(0, Range ? "invoke-direct/range" : "invoke-direct", Arguments, {},
            Adapter.methods[0].reference));
  if (Range) {
    Append(op(0, "move-object/from16", {4, Self}));
    Append(op(0, "move-object", {5, 0}));
  } else if (Copy)
    Append(op(0, "move-object", {1, 0}));
  Append(op(0, Range ? "invoke-direct/range" : "invoke-direct",
            Range ? std::vector<unsigned>{4, 5}
                  : std::vector<unsigned>{Self, Copy ? 1u : 0u},
            {}, Base.methods[0].reference));
  Append(op(0, "return-void"));
  auto ChildInit =
      method("<init>", Parameters, "V", Self + (Wide ? 4 : 3), Code);
  ChildInit.access = {"public", "constructor"};
  auto Child =
      klass(Member ? "Lfixture/Scope$Child;" : "Lfixture/Child;", {ChildInit});
  Child.superclass = Base.name;
  Child.generic_signature = "Lfixture/Base<Lfixture/Value;>;";
  auto Value = klass("Lfixture/Value;");
  auto Scope = klass("Lfixture/Scope;");
  if (Member)
    for (auto *C : {&Child, &Adapter}) {
      C->enclosing = Scope.name;
      C->inner_name = C == &Child ? "Child" : "Adapter";
      C->inner_class_present = true;
      C->access.erase("public");
      C->inner_access = {C == &Child ? "public" : "private", "static"};
    }
  return {Base, Child, Callback, Adapter, Value, Scope};
}

TEST(MobileDalvikJava, ClosedAllocatedCallbacksKeepInputsAndOriginalInterface) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Wide : {false, true})
        for (bool Member : {false, true})
          for (bool Copy : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Range, Wide, Member, Copy, Route}));
              auto Input = closedAllocatedCallbackClasses(SDK, Range, Wide,
                                                          Member, Copy);
              const auto Parent = Input[0].methods[0].reference;
              const auto Caller = Input[1].methods[0].reference;
              const auto Original = Input[3].generic_signature;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              EXPECT_NO_THROW(([&] {
                Budget B;
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                if (Route)
                  Classes = linkClasses(Input, B);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .superclass_calls.contains({Caller, Parent}));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8), 25);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes
                              .at(Member ? "Lfixture/Scope$Adapter;"
                                         : "Lfixture/Adapter;")
                              .generic_signature,
                          Original);
              })());
            }
}

TEST(MobileDalvikJava,
     ClosedAllocatedCallbacksRejectMissingBindingsAndOrigins) {
  for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          closedAllocatedCallbackClasses(false, false, true, false, false);
      auto &Child = Input[1].methods[0];
      auto &Adapter = Input[3];
      auto &Init = Adapter.methods[0];
      auto &Call = Child.instructions[1];
      switch (Mutation) {
      case 0:
        Adapter.generic_signature =
            "Ljava/lang/Object;Lfixture/Callback<Ljava/lang/Object;>;";
        break;
      case 1:
        Adapter.generic_signature.reset();
        break;
      case 2:
        Adapter.generic_signature =
            "<X:Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Callback<TX;>;";
        break;
      case 3:
        Adapter.interfaces.clear();
        break;
      case 4:
        Input[4].generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 5:
        Init.generic_signature = "<X:Ljava/lang/Object;>(Lfixture/Value;J)V";
        break;
      case 6:
        Init.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 7:
        Init.access.insert("static");
        break;
      case 8:
        Init.access.erase("public");
        Init.access.insert("private");
        break;
      case 9:
        Adapter.external = true;
        Init.instructions.clear();
        Init.registers = Init.code_end = 0;
        break;
      case 10:
        Call.registers[1] = 1;
        break;
      case 11:
        Call.registers[1] = 0;
        break;
      case 12:
        Call.registers.back() = Call.registers[2];
        break;
      case 13:
        Init.reference.parameters[0] = "Ljava/lang/Object;";
        Call.reference = Init.reference;
        break;
      case 14:
        Child.instructions.insert(Child.instructions.begin(),
                                  op(0, "const-wide/16", {3}, int64_t(0)));
        for (size_t I = 0; I < Child.instructions.size(); ++I)
          Child.instructions[I].pc = I;
        Child.code_end = Child.instructions.size();
        break;
      case 15:
        Call.registers.push_back(2);
        break;
      case 16:
        Call.literal = int64_t(0);
        break;
      case 17:
        Input[2].generic_signature = "<R:Lfixture/Value;>Ljava/lang/Object;";
        break;
      case 18:
        Adapter.superclass = Input[4].name;
        break;
      case 19:
        Adapter.enclosing = Input[5].name;
        Adapter.inner_class_present = true;
        Adapter.inner_name = "Adapter";
        Adapter.inner_access = {"public"};
        break;
      case 20:
        Input[0].methods[0].access.insert("varargs");
        break;
      case 21:
        *Adapter.generic_signature += "Lfixture/Missing;";
        Adapter.interfaces.push_back("Lfixture/Missing;");
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

std::vector<Class> closedLocalConstructorClasses(bool SDK, bool Range,
                                                 bool Wide, bool Token,
                                                 bool Rename) {
  const std::string CarrierName =
      Token ? "Lfixture/Token;" : "Ljava/lang/Class;";
  auto Carrier = klass(CarrierName);
  Carrier.generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
  Carrier.external = SDK || !Token;
  const std::string Formal = Rename ? "Element" : "T";
  const std::vector<std::string> Parameters{Wide ? "J" : "I", CarrierName, "I"};
  const unsigned Words = Wide ? 5 : 4;
  auto Init = method("<init>", Parameters, "V", Words,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = std::string("(") + (Wide ? "J" : "I") +
                           CarrierName.substr(0, CarrierName.size() - 1) +
                           "<T" + Formal + ";>;I)V";
  auto Base = klass("Lfixture/Base;", {Init});
  Base.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>Ljava/lang/Object;";
  Base.external = SDK;
  if (SDK) {
    Base.methods[0].instructions.clear();
    Base.methods[0].registers = Base.methods[0].code_end = 0;
  }
  auto Make =
      method("make", {}, Base.name, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature = "()Lfixture/Base<Ljava/lang/String;>;";
  auto Core = klass("Lfixture/Core;", {Make});
  std::vector<unsigned> Registers;
  for (unsigned R = 0; R < Words; ++R)
    Registers.push_back(R);
  auto Forward = method("<init>", Parameters, "V", Words,
                        {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                            Registers, {}, Base.methods[0].reference),
                         op(1, "return-void")});
  Forward.access = {"constructor"};
  auto Local = klass("Lfixture/Core$1;", {Forward});
  Local.access.clear();
  Local.inner_class_present = true;
  Local.enclosing_method = Core.methods[0].reference;
  Local.superclass = Base.name;
  Local.generic_signature = "Lfixture/Base<Ljava/lang/String;>;";
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  String.access.insert("final");
  return {Base, Core, Local, Carrier, String};
}

std::vector<Class>
closedArrayConstructorTokenClasses(bool Named, bool SDK, bool Range,
                                   const std::string &Array) {
  auto Input =
      Named ? namedAnonymousAllocationClasses(false, SDK)
            : closedLocalConstructorClasses(SDK, Range, false, false, false);
  auto &Child = Input[Named ? 1 : 2];
  Child.generic_signature = Named
                                ? "Lfixture/Base<Lfixture/Core;" + Array + ">;"
                                : "Lfixture/Base<" + Array + ">;";
  if (Range)
    Child.methods[0].instructions[0].opcode = "invoke-direct/range";
  if (!Named)
    Input[1].methods[0].generic_signature = "()Lfixture/Base<" + Array + ">;";
  return Input;
}

