TEST(MobileDalvikJava,
     ClosedLocalConstructorsRejectOpenScopesAndChangedForwarding) {
  for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          closedLocalConstructorClasses(false, true, true, true, false);
      auto &Base = Input[0];
      auto &Core = Input[1];
      auto &Local = Input[2];
      auto &Forward = Local.methods[0];
      switch (Mutation) {
      case 0:
        Core.methods.clear();
        break;
      case 1:
        Core.external = true;
        break;
      case 2:
        Core.methods[0].access.erase("static");
        break;
      case 3:
        Local.inner_name = "Named";
        break;
      case 4:
        Local.enclosing = Core.name;
        break;
      case 5:
        Local.fields.push_back({{Local.name, "state", "I"}, {}, {}});
        break;
      case 6:
        Local.generic_signature = "Lfixture/Base;";
        break;
      case 7:
        Core.methods[0].generic_signature =
            "<X:Ljava/lang/Object;>()Lfixture/Base<TX;>;";
        Local.generic_signature = "Lfixture/Base<TX;>;";
        break;
      case 8:
        Forward.generic_signature = "(JLfixture/Token<Ljava/lang/String;>;I)V";
        break;
      case 9:
        ++Forward.registers;
        break;
      case 10:
        Forward.instructions[0].registers = {0, 1, 2, 4, 3};
        break;
      case 11:
        Forward.instructions[0].registers[2] = 1;
        break;
      case 12:
        Forward.instructions.insert(Forward.instructions.begin(), op(0, "nop"));
        for (size_t I = 0; I < Forward.instructions.size(); ++I)
          Forward.instructions[I].pc = I;
        Forward.code_end = Forward.instructions.size();
        break;
      case 13:
        Forward.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 14:
        Base.methods[0].declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 15:
        Base.methods[0].access.insert("varargs");
        break;
      case 16:
        Base.methods[0].generic_signature =
            "<X:Ljava/lang/Object;>(JLfixture/Token<TT;>;I)V";
        break;
      case 17:
        Base.methods[0].generic_signature = "(JLfixture/Token<+TT;>;I)V";
        break;
      case 18:
        Input[3].generic_signature = "<Q:Ljava/lang/String;>Ljava/lang/Object;";
        break;
      case 19:
        Input[3].generic_signature =
            "<Q:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 20:
        Input[4].generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 21: {
        auto Other = Base.methods[0];
        Other.reference.parameters[1] = "Ljava/lang/Object;";
        Other.generic_signature.reset();
        Base.methods.push_back(std::move(Other));
        break;
      }
      case 22: {
        auto Other = Forward;
        Other.reference.parameters[2] = "J";
        ++Other.registers;
        Local.methods.push_back(std::move(Other));
        break;
      }
      case 23:
        Forward.instructions[0].registers[0] = 1;
        break;
      }
      const auto Caller = Input[2].methods[0].reference;
      const auto Target = Input[0].methods[0].reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      try {
        Budget B;
        ClassMap Classes;
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
        const auto Plans = validateGenericSignatures(
            Route ? linkClasses(Input, B) : Classes, B);
        if (Mutation == 8) {
          // A complete original constructor Signature already proves this
          // valid call through the existing typed forwarding path.
          EXPECT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
        } else
          EXPECT_FALSE(Plans.superclass_calls.contains({Caller, Target}));
      } catch (const std::runtime_error &) {
        // Malformed declarations and words may fail before planning a call.
      }
    }
}

std::vector<Class> typedConstructorIntegerDefaultClasses(bool SDK, bool Range,
                                                         bool Wide, bool Member,
                                                         bool Copy, bool Rename,
                                                         int64_t Value) {
  const std::string Name = Member ? "Lfixture/Scope$Owner;" : "Lfixture/Owner;";
  const std::string Formal = Rename ? "Element" : "T";
  const std::string CarrierName = SDK ? "Ljava/lang/Class;" : "Lfixture/Token;";
  const std::string Integer = Wide ? "J" : "I";
  const std::vector<std::string> Parameters{"I", CarrierName, Integer, "I"};
  const std::string CarrierUse =
      CarrierName.substr(0, CarrierName.size() - 1) + "<T" + Formal + ";>;";
  auto Target = method("<init>", Parameters, "V", Wide ? 6 : 5,
                       {op(0, "invoke-direct", {0}, {},
                           MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                        op(1, "return-void")});
  Target.access =
      Member ? Access{"constructor"} : Access{"public", "constructor"};
  Target.generic_signature = "(I" + CarrierUse + Integer + "I)V";
  auto Owner = klass(Name, {Target});
  Owner.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>Ljava/lang/Object;";
  const unsigned Self = Range ? 8 : Copy ? 4 : Wide ? 2 : 1;
  const unsigned Definition = Range ? (Copy ? 6 : 3) : 0;
  const unsigned Constant = Range ? 3 : Copy ? (Wide ? 2 : 1) : 0;
  std::vector<Instruction> Code;
  auto Append = [&](Instruction Op) {
    Op.pc = Code.size();
    Code.push_back(std::move(Op));
  };
  Append(op(0, Wide ? "const-wide" : "const", {Definition}, Value));
  if (Copy)
    Append(op(0, Wide ? "move-wide" : "move", {Constant, Definition}));
  if (Range) {
    Append(op(0, "move-object/from16", {0, Self}));
    Append(op(0, "move/from16", {1, Self + 1}));
    Append(op(0, "move-object/from16", {2, Self + 2}));
    Append(op(0, "move/from16", {Wide ? 5u : 4u, Self + 3}));
  }
  std::vector<unsigned> Arguments{Range ? 0u : Self, Range ? 1u : Self + 1,
                                  Range ? 2u : Self + 2, Constant};
  if (Wide)
    Arguments.push_back(Constant + 1);
  Arguments.push_back(Range ? (Wide ? 5u : 4u) : Self + 3);
  Append(op(0, Range ? "invoke-direct/range" : "invoke-direct", Arguments, {},
            Owner.methods[0].reference));
  Append(op(0, "return-void"));
  auto Forward = method("<init>", {"I", CarrierName, "I"}, "V", Self + 4, Code);
  Forward.reference.owner = Owner.name;
  Forward.access = Target.access;
  Forward.generic_signature = "(I" + CarrierUse + "I)V";
  Owner.methods.push_back(Forward);
  auto CarrierInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  CarrierInit.access = {"public", "constructor"};
  auto Carrier = klass(CarrierName, SDK ? std::vector<Method>{}
                                        : std::vector<Method>{CarrierInit});
  Carrier.generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
  Carrier.external = SDK;
  auto Scope = klass("Lfixture/Scope;", {CarrierInit});
  if (Member) {
    Owner.access = {"abstract"};
    Owner.enclosing = Scope.name;
    Owner.inner_name = "Owner";
    Owner.inner_class_present = true;
    Owner.inner_access = {"private", "static", "abstract"};
  }
  return {Owner, Carrier, Scope};
}

