TEST(MobileDalvikJava, TypedConstructorIntegerDefaultsRejectLostTypesAndWords) {
  for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = typedConstructorIntegerDefaultClasses(
          false, false, Mutation != 8, false, false, false, 0);
      auto &Owner = Input[0];
      auto &Target = Owner.methods[0];
      auto &Caller = Owner.methods[1];
      auto &Constant = Caller.instructions[0];
      auto &Call = Caller.instructions[1];
      switch (Mutation) {
      case 0:
        Constant.opcode = "const-unknown";
        break;
      case 1:
        Constant.reference = std::string("Ljava/lang/Object;");
        break;
      case 2:
        Constant.literal = std::string("owned malformed constant");
        break;
      case 3:
        Constant.registers[0] = Caller.registers - Caller.incomingWords();
        break;
      case 4:
        Constant.opcode = "const";
        break;
      case 5:
        Call.registers[4] = Call.registers[3];
        break;
      case 6:
        Caller.instructions.insert(Caller.instructions.begin() + 1,
                                   op(1, "move", {1, 0}));
        for (size_t I = 0; I < Caller.instructions.size(); ++I)
          Caller.instructions[I].pc = I;
        Caller.code_end = Caller.instructions.size();
        break;
      case 7:
      case 8: {
        // A decoded bit pattern now retains its same-width floating view.
        // Keep these controls unproved by requiring the opposite word width.
        const std::string Type = Mutation == 7 ? "F" : "D";
        Target.reference.parameters[2] = Type;
        Target.generic_signature = "(ILfixture/Token<TT;>;" + Type + "I)V";
        Call.reference = Target.reference;
        break;
      }
      case 9:
        Caller.generic_signature = "(ILfixture/Token<Ljava/lang/Object;>;I)V";
        break;
      case 10:
        Target.generic_signature =
            "<X:Ljava/lang/Object;>(ILfixture/Token<TT;>;JI)V";
        break;
      case 11:
        Target.access.insert("varargs");
        break;
      case 12:
        Caller.generic_signature =
            "<X:Ljava/lang/Object;>(ILfixture/Token<TT;>;I)V";
        break;
      case 13:
        Target.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 14:
        Constant.target = 1;
        break;
      case 15:
        Caller.generic_signature = "(ILfixture/Token<TU;>;I)V";
        break;
      case 16:
        Constant.registers[0] = Caller.registers - 2;
        break;
      case 17:
        Caller.instructions.insert(Caller.instructions.begin() + 1,
                                   op(1, "move-wide", {0, 1}));
        for (size_t I = 0; I < Caller.instructions.size(); ++I)
          Caller.instructions[I].pc = I;
        Caller.code_end = Caller.instructions.size();
        break;
      case 18:
        Call.registers[2] = Call.registers[0];
        break;
      case 19:
        Call.registers.push_back(0);
        break;
      case 20:
        Constant.targets = {1};
        break;
      case 21:
        Constant.pc = Caller.code_end;
        break;
      case 22:
        Caller.access.insert("synthetic");
        break;
      case 23:
        Target.access.insert("static");
        break;
      }
      const auto CallerRef = Input[0].methods[1].reference;
      const auto TargetRef = Input[0].methods[0].reference;
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      try {
        Budget B;
        ClassMap Classes;
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
        const auto Plans = validateGenericSignatures(
            Route ? linkClasses(Input, B) : Classes, B);
        EXPECT_FALSE(Plans.constructor_calls.contains({CallerRef, TargetRef}));
      } catch (const std::runtime_error &) {
        // Malformed declarations and physical words fail before call planning.
      }
    }
}

std::vector<Class> interfaceBooleanInitializerClasses(bool SDK, bool Calls,
                                                      bool Zero, bool Invert,
                                                      bool Copy, bool Frame,
                                                      unsigned Relation) {
  const std::string Owner = "Lfixture/Policy;", Source = "Lfixture/Source;";
  const FieldRef Flag{Owner, "enabled", "Z"}, Left{Source, "left", "I"},
      Right{Source, "right", "I"};
  auto ReadLeft = method("left", {}, "I", 1,
                         {op(0, "sget", {0}, {}, Left), op(1, "return", {0})});
  auto ReadRight =
      method("right", {}, "I", 1,
             {op(0, "sget", {0}, {}, Right), op(1, "return", {0})});
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Provider = klass(Source, {Init, ReadLeft, ReadRight});
  Provider.fields = {{Left, {"public", "static", "volatile"}, {}},
                     {Right, {"public", "static", "volatile"}, {}}};
  Provider.external = SDK;
  if (SDK)
    for (auto &M : Provider.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const unsigned Offset = Frame ? 32 : 0;
  std::vector<Instruction> Code;
  auto Append = [&](Instruction Op) {
    Op.pc = Code.size();
    for (auto &R : Op.registers)
      R += Offset;
    Code.push_back(std::move(Op));
  };
  if (Calls) {
    Append(op(0, "invoke-static", {}, {}, Provider.methods[1].reference));
    Append(op(0, "move-result", {0}));
    if (!Zero) {
      Append(op(0, "invoke-static", {}, {}, Provider.methods[2].reference));
      Append(op(0, "move-result", {1}));
    }
  } else {
    Append(op(0, "sget", {0}, {}, Left));
    if (!Zero)
      Append(op(0, "const/16", {1}, int64_t(27)));
  }
  const auto Branch = Code.size();
  const std::vector<std::string> Binary{"if-lt", "if-ge", "if-eq",
                                        "if-ne", "if-gt", "if-le"};
  const auto Conditional = Binary.at(Relation) + (Zero ? "z" : "");
  Append(op(0, Conditional,
            Zero ? std::vector<unsigned>{0} : std::vector<unsigned>{0, 1}, {},
            {}, Branch + 3));
  Append(op(0, "const/4", {0}, int64_t(Invert ? 0 : 1)));
  Append(op(0, "goto", {}, {}, {}, Branch + 4));
  Append(op(0, "const/4", {0}, int64_t(Invert ? 1 : 0)));
  if (Copy)
    Append(op(0, "move", {2, 0}));
  Append(op(0, "sput-boolean", {Copy ? 2u : 0u}, {}, Flag));
  Append(op(0, "return-void"));
  auto Clinit = method("<clinit>", {}, "V", Offset + 3, Code);
  Clinit.access = {"static", "constructor"};
  auto Policy = klass(Owner, {Clinit});
  Policy.access = {"public", "abstract", "interface"};
  Policy.fields = {{Flag, {"public", "static", "final"}, {}}};
  return {Policy, Provider};
}

