namespace {
std::vector<Class> pairedAdapterInputClasses(unsigned Kind, unsigned Shape,
                                             bool Alpha, bool Flipped,
                                             bool Range, bool Used) {
  const std::string A = Alpha ? "Owner" : "A";
  const std::string T = Alpha ? "Value" : "T";
  const auto Seed = "T" + A + ";", Value = "T" + T + ";";
  auto Read = method("read",
                     {"Ljava/lang/Object;", "Lfixture/Provider$Pair;",
                      "Lfixture/Provider$Single;", "Ljava/lang/Object;"},
                     "Ljava/lang/Object;", 0, {});
  std::string Parameters = Seed + "Lfixture/Provider$Pair<" +
                           (Flipped ? Value + Seed : Seed + Value) +
                           ">;Lfixture/Provider$Single<" + Value + ">;" + Value;
  if (Shape == 1 || Shape == 2) {
    Read.reference.parameters.push_back("Lfixture/Context;");
    Parameters += "Lfixture/Context;";
  }
  if (Shape == 2) {
    Read.reference.parameters.push_back("I");
    Parameters += "I";
  }
  if (Shape == 3) {
    Read.reference.parameters.insert(Read.reference.parameters.end(),
                                     {"J", "I", "Z", "Z"});
    Parameters += "JIZZ";
  }
  Read.generic_signature = "<" + A + ":Ljava/lang/Object;" + T +
                           ":Ljava/lang/Object;>(" + Parameters + ")" + Value;
  Read.registers = Read.incomingWords() + 1;
  if (Kind != 1) {
    Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Read.code_end = 2;
  }
  auto Provider = klass("Lfixture/Provider;", {Read});
  Provider.external = Kind == 1;
  if (Kind == 2)
    Provider.access.clear();
  const auto Target = Provider.methods[0].reference;
  auto Call =
      method("run", Target.parameters, Used ? Target.returns : "V", 0, {});
  Call.registers = Call.incomingWords() + 1;
  std::vector<unsigned> Words;
  for (unsigned I = 1; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          Words, {}, Target)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
    Call.code_end = 5;
  } else {
    Call.instructions.push_back(op(3, "return-void"));
    Call.code_end = 4;
  }
  auto Pair = klass("Lfixture/Provider$Pair;");
  auto Single = klass("Lfixture/Provider$Single;");
  Pair.generic_signature =
      "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Ljava/lang/Object;";
  Single.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
  for (auto *Carrier : {&Pair, &Single}) {
    Carrier->access = {"public", "abstract", "interface"};
    Carrier->external = Kind == 1;
    Carrier->enclosing = Provider.name;
    Carrier->inner_class_present = true;
    Carrier->inner_name = Carrier == &Pair ? "Pair" : "Single";
    Carrier->inner_access = {"public", "abstract", "interface", "static"};
  }
  auto Context = klass("Lfixture/Context;");
  Context.external = Kind == 1;
  return {klass("Lfixture/Core;", {Call}), Provider, Pair, Single, Context};
}
} // namespace

TEST(MobileDalvikJava, PairedAdapterInputsRetainEverySeedAndCompleteSlot) {
  for (unsigned Kind : {0u, 1u, 2u})
    for (unsigned Shape = 0; Shape < 4; ++Shape)
      for (bool Alpha : {false, true})
        for (bool Flipped : {false, true})
          for (bool Range : {false, true}) {
            if (Shape >= 2 && !Range)
              continue;
            for (bool Used : {false, true})
              for (unsigned Route : {0u, 1u, 2u}) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Kind, Shape, Alpha, Flipped, Range, Used, Route}));
                auto Input = pairedAdapterInputClasses(Kind, Shape, Alpha,
                                                       Flipped, Range, Used);
                const auto Target = Input[1].methods[0].reference;
                const auto Original = Input[1].methods[0].generic_signature;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                if (Route)
                  Classes = linkClasses(Input, B);
                const auto Plans = validateGenericSignatures(Classes, B);
                EXPECT_TRUE(Plans.erased_generic_invocations.contains(Target));
                EXPECT_EQ(Classes.at(Target.owner).methods[0].generic_signature,
                          Original);
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              }
          }
}

TEST(MobileDalvikJava, PairedAdapterInputsRejectIncompleteOrForeignRelations) {
  for (unsigned Mutation = 0; Mutation < 27; ++Mutation)
    for (unsigned Route : {0u, 1u, 2u}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = pairedAdapterInputClasses(0, 2, false, false, true, true);
      auto &Read = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto Replace = [&](std::string_view From, std::string_view To) {
        auto &Signature = *Read.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        Replace("Pair<TA;TT;>", "Pair<TA;TA;>");
        break;
      case 1:
        Replace("Pair<TA;TT;>", "Pair<+TA;TT;>");
        break;
      case 2:
        Replace("Pair<TA;TT;>", "Pair<-TA;TT;>");
        break;
      case 3:
        Replace("Pair<TA;TT;>", "Pair<*TT;>");
        break;
      case 4:
        Replace("Pair<TA;TT;>", "Pair");
        break;
      case 5:
        Replace("Single<TT;>", "Single<TA;>");
        break;
      case 6:
        Replace("Single<TT;>", "Single<+TT;>");
        break;
      case 7:
        Replace("Single<TT;>", "Single<-TT;>");
        break;
      case 8:
        Replace("Single<TT;>", "Single<*>");
        break;
      case 9:
        Replace("Single<TT;>", "Single");
        break;
      case 10:
        Replace(">(TA;", ">(TT;");
        break;
      case 11:
        Replace(";>;TT;", ";>;TA;");
        break;
      case 12:
        Replace("A:Ljava/lang/Object;", "A:Ljava/lang/Number;");
        break;
      case 13:
        Replace("T:Ljava/lang/Object;>",
                "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
        break;
      case 14:
        Replace(")TT;", ")TU;");
        break;
      case 15:
        Input[2].generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 16:
        Input[3].generic_signature = "<X:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 17:
        Input[2].name = "Lfixture/MissingPair;";
        break;
      case 18:
        Input[3].name = "Lfixture/MissingSingle;";
        break;
      case 19:
        Input[4].generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 20:
        Read.access.insert("synthetic");
        break;
      case 21:
        Read.access.insert("bridge");
        break;
      case 22:
        Read.access.insert("native");
        break;
      case 23:
        Read.access.insert("varargs");
        break;
      case 24:
        Read.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 25:
        Call.instructions[0].registers[0] = Call.registers;
        break;
      case 26:
        Replace("Context;I)", "Context;J)");
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

namespace {
std::vector<Class> literalSuperclassScalarBridgeClasses(std::string Type,
                                                        bool External,
                                                        unsigned Depth,
                                                        bool Range, bool Copy,
                                                        bool Anonymous) {
  auto Input =
      literalSuperclassVoidBridgeClasses(External, Depth, Range, Copy, false);
  const bool Wide = Type == "J" || Type == "D";
  const std::string Load = Type == "Z"   ? "sget-boolean"
                           : Type == "B" ? "sget-byte"
                           : Type == "C" ? "sget-char"
                           : Type == "S" ? "sget-short"
                           : Wide        ? "sget-wide"
                                         : "sget";
  const FieldRef Value{"Lfixture/Values;", "result", Type};
  for (auto &C : Input)
    for (auto &M : C.methods) {
      if (M.reference.name != "accept")
        continue;
      M.reference.returns = Type;
      if (M.generic_signature)
        *M.generic_signature = "(TT;JDLjava/lang/Object;)" + Type;
      if (M.instructions.empty())
        continue;
      if (!has(M.access, "bridge")) {
        M.instructions = {op(0, Load, {0}, {}, Value),
                          op(1, Wide ? "return-wide" : "return", {0})};
        M.code_end = 2;
        continue;
      }
      for (auto &I : M.instructions)
        if (auto *Call = std::get_if<MethodRef>(&I.reference))
          Call->returns = Type;
      auto PC = M.instructions.back().pc;
      M.instructions.back() =
          op(PC, Wide ? "move-result-wide" : "move-result", {0});
      M.instructions.push_back(
          op(PC + 1, Wide ? "return-wide" : "return", {0}));
      M.code_end = PC + 2;
    }
  if (Anonymous) {
    auto &Core = Input.back();
    const auto Original = Core.name;
    Core.name = "Lfixture/Outer$7;";
    Core.enclosing = "Lfixture/Outer;";
    Core.inner_class_present = true;
    Core.inner_name.reset();
    Core.access = {"final"};
    Core.inner_access = {"static"};
    for (auto &M : Core.methods) {
      M.reference.owner = Core.name;
      for (auto &I : M.instructions)
        if (auto *Call = std::get_if<MethodRef>(&I.reference);
            Call && Call->owner == Original)
          Call->owner = Core.name;
    }
    Input.push_back(klass("Lfixture/Outer;"));
  }
  auto Values = klass(Value.owner);
  Values.external = true;
  Values.fields.push_back({Value, {"public", "static"}, {}});
  Input.push_back(Values);
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     LiteralSuperclassScalarBridgesKeepExactPrimitiveResults) {
  for (const auto *Type : {"Z", "B", "C", "S", "I", "J", "F", "D"})
    for (bool External : {false, true})
      for (unsigned Depth : {0u, 2u})
        for (bool Range : {false, true})
          for (bool Copy : {false, true})
            for (bool Anonymous : {false, true})
              for (unsigned Route : {0u, 1u, 2u}) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Type, External, Depth, Range, Copy, Anonymous, Route}));
                auto Input = literalSuperclassScalarBridgeClasses(
                    Type, External, Depth, Range, Copy, Anonymous);
                const auto Owner =
                    Anonymous ? "Lfixture/Outer$7;" : "Lfixture/Core;";
                auto Target = Input[1].methods[1].reference;
                Target.owner = Owner;
                auto Bridge = Input[1].methods[2].reference;
                Bridge.owner = Owner;
                const auto Dispatch = Input[0].methods[1].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                if (Route)
                  Classes = linkClasses(Input, B);
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                bool Found = false;
                for (const auto &Value : *R.getArray("methods")) {
                  const auto &Row = *Value.getAsObject();
                  if (Row.getString("identity") != Bridge.identity())
                    continue;
                  Found = true;
                  EXPECT_EQ(Row.getString("bridge_target"), Target.identity());
                  EXPECT_EQ(Row.getString("bridge_dispatch"),
                            Dispatch.identity());
                }
                EXPECT_TRUE(Found);
              }
}

