namespace {
std::vector<Class> scopedSuperConstructorClasses(bool External, bool SelfBound,
                                                 bool Shadow, bool Range,
                                                 unsigned Padding) {
  const std::string Root = "Lfixture/Root;", Child = "Lfixture/Child;";
  const std::string Formal = Shadow ? "S" : "K";
  const auto Applied = "Lfixture/Carrier<T" + Formal + ";>;";
  auto Constructor =
      method("<init>", {"Ljava/lang/Object;", "Lfixture/Carrier;"}, "V", 3,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  Constructor.access = {"constructor"};
  Constructor.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(T" + Formal + ";" + Applied + ")V";
  auto Parent = klass(Root, {Constructor});
  Parent.generic_signature = SelfBound
                                 ? "<S:Lfixture/Root<TS;>;>Ljava/lang/Object;"
                                 : "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  Parent.external = External;
  if (External) {
    Parent.methods[0].instructions.clear();
    Parent.methods[0].registers = Parent.methods[0].code_end = 0;
  }
  auto Init = method(
      "<init>", Constructor.reference.parameters, "V", Padding + 3,
      {op(0, Range ? "invoke-direct/range" : "invoke-direct",
          {Padding, Padding + 1, Padding + 2}, {}, Parent.methods[0].reference),
       op(3, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "<V:Ljava/lang/Object;>(TV;Lfixture/Carrier<TV;>;)V";
  auto C = klass(Child, {Init});
  C.superclass = Root;
  C.generic_signature = "Lfixture/Root<Lfixture/Child;>;";
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.external = External;
  Carrier.access = {"public", "abstract", "interface"};
  Carrier.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  return {Parent, C, Carrier};
}
} // namespace

