namespace {
std::vector<Class> privateMemberConstructorClasses(bool Dependency,
                                                   unsigned CallerAccess,
                                                   unsigned TargetAccess) {
  auto Input = closedAllocatingConstructorClasses(Dependency);
  auto &Member = Input[0];
  const auto Old = Member.name;
  Member.name = "Lfixture/Outer$Hidden;";
  Member.access.clear();
  Member.enclosing = "Lfixture/Outer;";
  Member.inner_class_present = true;
  Member.inner_name = "Hidden";
  Member.inner_access = {"private", "static"};
  for (auto &M : Member.methods) {
    M.reference.owner = Member.name;
    for (auto &I : M.instructions) {
      if (auto *Call = std::get_if<MethodRef>(&I.reference);
          Call && Call->owner == Old)
        Call->owner = Member.name;
      if (auto *Field = std::get_if<FieldRef>(&I.reference);
          Field && Field->owner == Old)
        Field->owner = Member.name;
    }
  }
  for (auto &F : Member.fields)
    F.reference.owner = Member.name;
  auto access = [](unsigned Kind) {
    return Kind == 0   ? Access{"public", "constructor"}
           : Kind == 1 ? Access{"private", "constructor"}
                       : Access{"constructor"};
  };
  Member.methods[0].access = access(TargetAccess);
  Member.methods[1].access = access(CallerAccess);
  Input.push_back(klass("Lfixture/Outer;"));
  return Input;
}
} // namespace

