namespace {
std::vector<Class> contextCallbackResultClasses(unsigned Kind, unsigned Shape,
                                                bool PublicOwner, bool Alpha,
                                                bool Range, bool Used) {
  const std::string Owner = "Lfixture/Provider;";
  const std::string Callback =
      Kind == 2 ? "Lfixture/Callback;" : "Lfixture/Provider$Callback;";
  const std::string T = Alpha ? "Item" : "T";
  std::vector<std::string> Parameters{"Ljava/lang/CharSequence;"};
  const std::string Scalars = Shape == 0 ? "" : Shape == 1 ? "I" : "IIIZ";
  for (char Type : Scalars)
    Parameters.emplace_back(1, Type);
  Parameters.push_back(Callback);
  auto Read = method("read", Parameters, "Ljava/lang/Object;", 0, {});
  Read.access = {"private"};
  Read.registers = Read.incomingWords() + 1;
  Read.instructions = {op(0, "const/4", {0}, int64_t(0)),
                       op(1, "return-object", {0})};
  Read.code_end = 2;
  Read.generic_signature =
      "<" + T + ":Ljava/lang/Object;>(Ljava/lang/CharSequence;" + Scalars +
      Callback.substr(0, Callback.size() - 1) + "<T" + T + ";>;)T" + T + ";";
  auto Provider = klass(Owner, {Read});
  Provider.access = PublicOwner ? Access{"public", "final"} : Access{"final"};
  const auto Target = Provider.methods[0].reference;
  auto Run = method("run", Parameters, Used ? Target.returns : "V", 0, {});
  Run.reference.owner = Owner;
  Run.access = {"public"};
  Run.registers = Run.incomingWords() + 1;
  std::vector<unsigned> Words;
  for (unsigned I = 1; I < Run.registers; ++I)
    Words.push_back(I);
  Run.instructions = {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                         Words, {}, Target)};
  if (Used) {
    Run.instructions.push_back(op(3, "move-result-object", {0}));
    Run.instructions.push_back(op(4, "return-object", {0}));
    Run.code_end = 5;
  } else {
    Run.instructions.push_back(op(3, "return-void"));
    Run.code_end = 4;
  }
  Provider.methods.push_back(Run);
  auto Carrier = klass(Callback);
  Carrier.external = Kind == 2;
  Carrier.access = Kind == 0 ? Access{"abstract", "interface"}
                             : Access{"public", "abstract", "interface"};
  Carrier.generic_signature = "<V:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Kind != 2) {
    Carrier.enclosing = Owner;
    Carrier.inner_class_present = true;
    Carrier.inner_name = "Callback";
    Carrier.inner_access = {Kind == 0 ? "private" : "public", "static",
                            "abstract", "interface"};
  }
  auto Context = klass("Ljava/lang/CharSequence;");
  Context.external = true;
  Context.access = {"public", "abstract", "interface"};
  return {Provider, Carrier, Context};
}
} // namespace

