std::vector<Class> intersectionFactoryResultClasses(bool SDK, bool ErasedSelf,
                                                    bool Range, bool Used,
                                                    bool Alpha,
                                                    bool SeparateResult,
                                                    bool Alias) {
  auto Input = intersectionVoidInvocationClasses(SDK, ErasedSelf, Range);
  auto &Target = Input[1].methods[0];
  const auto Old = Target.reference;
  const std::string Result =
      SeparateResult ? "Lfixture/Result;" : Input[1].name;
  const std::string Formal = Alpha ? "Item" : "T";
  Target.reference.returns = Result;
  Target.generic_signature = "<" + Formal +
                             "::Lfixture/First;:Lfixture/Second;>(T" + Formal +
                             ";)" + Result;
  if (!SDK) {
    Target.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
    Target.code_end = 2;
  }
  Input[1].access.insert("abstract");
  Input[2].external = Input[3].external = SDK;
  auto Call = Target.reference;
  if (Alias)
    Call.owner = "Lfixture/FactoryAlias;";
  auto &Run = Input[0].methods[0];
  for (auto &Op : Run.instructions)
    if (Op.reference == Reference{Old})
      Op.reference = Call;
  if (Used) {
    Run.reference.returns = Result;
    Run.instructions.pop_back();
    auto PC = uint32_t(Run.instructions.size());
    Run.instructions.push_back(op(PC++, "move-result-object", {0}));
    Run.instructions.push_back(op(PC++, "return-object", {0}));
    Run.code_end = PC;
  }
  if (SeparateResult) {
    auto Value = klass(Result);
    Value.access.insert("abstract");
    Value.external = SDK;
    Input.push_back(std::move(Value));
  }
  if (Alias) {
    auto Qualifier = klass(Call.owner);
    Qualifier.superclass = Input[1].name;
    Qualifier.external = SDK;
    Input.push_back(std::move(Qualifier));
  }
  return Input;
}

