TEST(MobileDalvikJava,
     IntersectionFactoryResultsRejectLooseResultsAndWitnesses) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = intersectionFactoryResultClasses(false, true, false, true,
                                                    false, true, false);
      auto &Target = Input[1].methods[0];
      auto &Run = Input[0].methods[0];
      auto ReplaceResult = [&](const std::string &Descriptor,
                               const std::string &Generic) {
        const auto Old = Target.reference;
        Target.reference.returns = Descriptor;
        Target.generic_signature =
            "<T::Lfixture/First;:Lfixture/Second;>(TT;)" + Generic;
        Run.reference.returns = Descriptor;
        for (auto &Op : Run.instructions)
          if (Op.reference == Reference{Old})
            Op.reference = Target.reference;
      };
      switch (Mutation) {
      case 0:
        ReplaceResult("Lfixture/First;", "TT;");
        break;
      case 1:
        ReplaceResult("[Lfixture/Result;", "[Lfixture/Result;");
        break;
      case 2:
        Input.back().generic_signature =
            "<Value:Ljava/lang/Object;>Ljava/lang/Object;";
        ReplaceResult("Lfixture/Result;",
                      "Lfixture/Result<Ljava/lang/Object;>;");
        break;
      case 3:
        Input.pop_back();
        break;
      case 4:
        Target.access.insert("native");
        Target.instructions.clear();
        Target.registers = Target.code_end = 0;
        break;
      case 5:
        Target.access.insert("synthetic");
        break;
      case 6:
        Target.access.insert("varargs");
        break;
      case 7:
        Target.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 8:
        Target.generic_signature =
            "<T::Lfixture/First;:Lfixture/Second;U:Ljava/lang/Object;>(TT;)"
            "Lfixture/Result;";
        break;
      case 9:
        Input[3].access.erase("interface");
        break;
      case 10:
        Input[0].interfaces.pop_back();
        break;
      case 11:
        Run.instructions[0] = op(0, "const/4", {0}, int64_t(0));
        break;
      case 12:
        Input.back().access.erase("public");
        Input.back().external = true;
        break;
      case 13: {
        auto Other = Target;
        Other.reference.parameters = {"Lfixture/Second;"};
        Other.generic_signature.reset();
        Input[1].methods.push_back(std::move(Other));
        break;
      }
      case 14:
        Run.instructions[2].opcode = "invoke-super";
        break;
      case 15:
        Target.access.erase("public");
        Target.access.insert("private");
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

std::vector<Class> pairedCallbackFactoryClasses(bool SDK, bool GenericCaller,
                                                bool PublicOwner, bool Alpha,
                                                bool ResultFirst, bool Permute,
                                                bool Range, bool Used) {
  const std::string Host = "Lfixture/Host;", Pair = "Lfixture/Pair;",
                    Context = "Lfixture/Context;",
                    Callback = "Lfixture/Callback;", Box = "Lfixture/Box;",
                    Left = "Lfixture/Left;", Right = "Lfixture/Right;";
  const std::string A = Alpha ? "Input" : "A", B = Alpha ? "Value" : "B";
  auto Signature = [&](const std::string &X, const std::string &Y,
                       bool Returns) {
    const auto Output = ResultFirst ? X : Y, Other = ResultFirst ? Y : X;
    std::vector<std::string> Types{
        "Lfixture/Pair<T" + X + ";T" + Y + ";>;",
        "Lfixture/Context<Lfixture/Left;Lfixture/Right;>;",
        "Lfixture/Callback<T" + Other + ";>;"};
    if (Permute)
      std::rotate(Types.begin(), Types.begin() + 1, Types.end());
    return "<" + X + ":Ljava/lang/Object;" + Y + ":Ljava/lang/Object;>(" +
           Types[0] + Types[1] + Types[2] + ")" +
           (Returns ? "Lfixture/Box<T" + Output + ";>;" : "V");
  };
  std::vector<std::string> Parameters{Pair, Context, Callback};
  if (Permute)
    std::rotate(Parameters.begin(), Parameters.begin() + 1, Parameters.end());
  auto Target =
      method("make", Parameters, Box, 5,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.reference.owner = Host;
  Target.access = {"private"};
  Target.generic_signature = Signature(A, B, true);
  std::vector<Instruction> Ops{
      op(0, Range ? "invoke-direct/range" : "invoke-direct", {1, 2, 3, 4}, {},
         Target.reference)};
  if (Used) {
    Ops.push_back(op(1, "move-result-object", {0}));
    Ops.push_back(op(2, "return-object", {0}));
  } else
    Ops.push_back(op(1, "return-void"));
  auto Caller = method("run", Parameters, Used ? Box : "V", 5, Ops);
  Caller.access = {"public"};
  if (GenericCaller)
    Caller.generic_signature = Signature("CallerLeft", "CallerRight", Used);
  auto Owner = klass(Host, {Target, Caller});
  Owner.access = PublicOwner ? Access{"public"} : Access{};
  std::vector<Class> Input{Owner};
  for (const auto &Name : {Pair, Context, Callback, Box}) {
    auto C = klass(Name);
    C.generic_signature = Name == Pair || Name == Context
                              ? "<First:Ljava/lang/Object;Second:Ljava/lang/"
                                "Object;>Ljava/lang/Object;"
                              : "<Value:Ljava/lang/Object;>Ljava/lang/Object;";
    C.external = SDK;
    if (Name == Context || Name == Callback)
      C.access = {"public", "interface", "abstract"};
    Input.push_back(std::move(C));
  }
  Input.push_back(klass(Left));
  Input.push_back(klass(Right));
  Input[5].external = Input[6].external = SDK;
  return Input;
}

