            "<Owner:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 17:
        Replace("T:Lfixture/Bound;", "T::Lfixture/Producer<TT;>;");
        break;
      case 18:
        Replace("T:Lfixture/Bound;", "T:Lfixture/Bound;U:Ljava/lang/Object;");
        Replace("Result<TT;>", "Result<TU;>");
