TEST(MobileDalvikJava,
     BoundedTokenCallbackVoidsRejectUnboundDirectionsAndOriginalScopes) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input =
          boundedTokenCallbackVoidClasses(SDK, true, false, false, false, true);
      auto &Create = Input[1].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Create.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("Token<TT;>", "Token<+TT;>");
      else if (Mutation == 1)
        replace("Token<TT;>", "Token<*>");
      else if (Mutation == 2)
        replace("Callback<-Lfixture/Context;", "Callback<+Lfixture/Context;");
      else if (Mutation == 3)
        replace(";+TT;>", ";-TT;>");
      else if (Mutation == 4)
        replace(";+TT;>", ";*>");
      else if (Mutation == 5) {
        replace("T:Lfixture/Bound;>", "T:Lfixture/Bound;U:Lfixture/Bound;>");
        replace(";+TT;>", ";+TU;>");
      } else if (Mutation == 6)
        replace(";+TT;>", ";+Lfixture/Bound;>");
      else if (Mutation == 7)
        Input[5].generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 8)
        Input[5].generic_signature =
            "<I:Ljava/lang/Object;R:Lfixture/Bound;>Ljava/lang/Object;";
      else if (Mutation == 9)
        Input.erase(Input.begin() + 4);
      else if (Mutation == 10)
        Input[5].access.erase("public");
      else if (Mutation == 11)
        Create.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 12)
        Create.access.insert("varargs");
      else if (Mutation == 13)
        Create.access.insert("static");
      else if (Mutation == 14)
        Create.access = {"private"};
      else
        replace("Token<TT;>", "Token<TMissing;>");
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> closedWildcardSuperClasses(bool SDK, bool Range, bool Member,
                                              bool Invariant) {
  auto Init = method("<init>", {"Lfixture/Carrier;"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.generic_signature = "(Lfixture/Carrier<+Lfixture/Base;>;)V";
  auto Other = Init;
  Other.reference.parameters = {"Ljava/lang/String;"};
  Other.generic_signature.reset();
  auto Base = klass("Lfixture/Base;", {Init, Other});
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature = "<T:Lfixture/Base;>Ljava/lang/Object;";
  auto Child = klass(Member ? "Lfixture/Outer$Child;" : "Lfixture/Child;");
  Child.superclass = Base.name;
  auto Caller = method("<init>", {Carrier.name}, "V", Range ? 4 : 2, {});
  Caller.access = {"public", "constructor"};
  Caller.generic_signature = "(Lfixture/Carrier<" +
                             std::string(Invariant ? "" : "+") + Child.name +
                             ">;)V";
  if (Range) {
    Caller.instructions.push_back(op(0, "move-object", {0, 2}));
    Caller.instructions.push_back(op(1, "move-object", {1, 3}));
  }
  const auto PC = static_cast<uint32_t>(Caller.instructions.size());
  Caller.instructions.push_back(
      op(PC, Range ? "invoke-direct/range" : "invoke-direct", {0, 1}, {},
         Base.methods[0].reference));
  Caller.instructions.push_back(op(PC + 1, "return-void"));
  Caller.code_end = PC + 2;
  Caller.reference.owner = Child.name;
  Child.methods.push_back(Caller);
  if (Member) {
    Child.enclosing = "Lfixture/Outer;";
    Child.inner_class_present = true;
    Child.inner_name = "Child";
    Child.inner_access = {"public", "static"};
  }
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  if (SDK) {
    Base.external = Carrier.external = true;
    for (auto &M : Base.methods) {
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  }
  std::vector<Class> Input{Base, Carrier, Child, Object};
  if (Member)
    Input.push_back(klass("Lfixture/Outer;"));
  return Input;
}

TEST(MobileDalvikJava,
     ClosedWildcardSupersKeepBoundContainmentAndOriginalInputOrigins) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Member : {false, true})
        for (bool Invariant : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Member, Invariant, Route}));
            auto Input =
                closedWildcardSuperClasses(SDK, Range, Member, Invariant);
            const auto Caller = Input[2].methods[0].reference;
            const auto Target = Input[0].methods[0].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
            EXPECT_EQ(Plans.superclass_call_declarations.at({Caller, Target}),
                      Target);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_FALSE(R.getArray("class_source_bindings"));
          }
}

TEST(MobileDalvikJava,
     ClosedWildcardSupersRejectVarianceBoundAndPrefixMismatches) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input = closedWildcardSuperClasses(SDK, false, true, false);
      auto &Caller = Input[2].methods[0];
      if (Mutation == 0)
        Caller.generic_signature = "(Lfixture/Carrier;)V";
      else if (Mutation == 1)
        Caller.generic_signature =
            "(Lfixture/Carrier<-Lfixture/Outer$Child;>;)V";
      else if (Mutation == 2)
        Input[0].methods[0].generic_signature =
            "(Lfixture/Carrier<Lfixture/Base;>;)V";
      else if (Mutation == 3)
        Input[0].methods[0].generic_signature =
            "(Lfixture/Carrier<-Lfixture/Base;>;)V";
      else if (Mutation == 4)
        Caller.generic_signature = "(Lfixture/Carrier<+Lfixture/Missing;>;)V";
      else if (Mutation == 5)
        Input[1].generic_signature = "<T:Lfixture/Missing;>Ljava/lang/Object;";
      else if (Mutation == 6)
        Input[1].generic_signature =
            "<T:Lfixture/Base;U:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 7)
        Input.erase(Input.begin() + 1);
      else if (Mutation == 8)
        Caller.instructions[0].registers[1] = 0;
      else if (Mutation == 9)
        Caller.instructions[0].opcode = "invoke-static";
      else if (Mutation == 10)
        Caller.instructions[0].registers[0] = 1;
      else if (Mutation == 11) {
        Caller.instructions[0].pc = 1;
        Caller.instructions[1].pc = 2;
        Caller.instructions.insert(
            Caller.instructions.begin(),
            op(0, "const-string", {1}, std::string("wrong")));
        Caller.code_end = 3;
      } else if (Mutation == 12) {
        auto Other = Input[0].methods[1];
        Other.reference.parameters = {"[Ljava/lang/Object;"};
        Other.access.insert("varargs");
        Input[0].methods.push_back(Other);
      } else if (Mutation == 13)
        Input[0].methods[0].access = {"private", "constructor"};
      else if (Mutation == 14)
        Caller.generic_signature = "(Lfixture/Carrier<+TMissing;>;)V";
      else if (Mutation == 15)
        Caller.generic_signature =
            "(Lfixture/Carrier<+[Lfixture/Outer$Child;>;)V";
      else if (Mutation == 16)
        Input[2].inner_access = {"private", "static"};
      else
        Input[1].access = {"private"};
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> covariantDescriptorSuperClasses(bool SDK, bool Range,
                                                   bool Checked, bool Prefix) {
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Carrier = klass("Lfixture/Carrier;", {Init});
  Carrier.generic_signature = "<E:Lfixture/Bound;>Ljava/lang/Object;";
  auto LeafInit = Init;
  LeafInit.instructions[0].reference = Carrier.methods[0].reference;
  auto Leaf = klass("Lfixture/Leaf;", {LeafInit});
  Leaf.superclass = Carrier.name;
  Leaf.generic_signature = "Lfixture/Carrier<Lfixture/Payload;>;";
  auto BuilderInit =
      method("<init>", {Carrier.name, "I"}, "V", 3, Init.instructions);
  BuilderInit.access = {"public", "constructor"};
  BuilderInit.generic_signature = "(Lfixture/Carrier<+TT;>;I)V";
  auto Builder = klass("Lfixture/Builder;", {BuilderInit});
  Builder.generic_signature = "<T:Lfixture/Bound;>Ljava/lang/Object;";
  auto Check = method("check", {"Ljava/lang/Object;", "Ljava/lang/String;"},
                      "V", 2, {op(0, "return-void")});
  auto Guard = klass("Lfixture/Guard;", {Check});
  auto Caller = method("<init>", {Leaf.name, "I"}, "V", Range ? 8 : 5, {});
  Caller.access = {"public", "constructor"};
  const unsigned Self = Range ? 5 : 2, Input = Self + 1, Id = Self + 2;
  auto append = [&](Instruction Op) {
    Op.pc = Caller.instructions.size();
    Caller.instructions.push_back(std::move(Op));
  };
  if (Prefix) {
    append(op(0, "const-string", {0}, std::string("source")));
    append(op(0, "invoke-static", {Input, 0}, {}, Guard.methods[0].reference));
    append(op(0, "nop"));
  }
  const unsigned Value = Range ? 1 : 0;
  append(op(0, "move-object", {Value, Input}));
  if (Checked)
    append(op(0, "check-cast", {Value}, {}, Carrier.name));
  if (Range) {
    append(op(0, "move-object", {0, Self}));
    append(op(0, "move", {2, Id}));
  }
  append(op(0, Range ? "invoke-direct/range" : "invoke-direct",
            {Range ? 0u : Self, Value, Range ? 2u : Id}, {},
            Builder.methods[0].reference));
  append(op(0, "return-void"));
  Caller.code_end = Caller.instructions.size();
  auto Core = klass("Lfixture/Core;", {Caller});
  Core.superclass = Builder.name;
  Core.generic_signature = "Lfixture/Builder<Lfixture/Payload;>;";
  auto Bound = klass("Lfixture/Bound;");
  auto Payload = klass("Lfixture/Payload;");
  Payload.superclass = Bound.name;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.superclass.reset();
  Object.external = true;
  std::vector<Class> Classes{Core,  Builder, Carrier, Leaf,
                             Bound, Payload, Guard,   Object};
  if (SDK)
    for (size_t I = 1; I < Classes.size(); ++I) {
      Classes[I].external = true;
      for (auto &M : Classes[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Classes;
}

std::vector<Class> tokenSuperResultClasses(bool SDK, bool Range, bool Prefix,
                                           bool Alias) {
  auto Input = covariantDescriptorSuperClasses(SDK, Range, false, Prefix);
  auto Get =
      method("get", {"Ljava/lang/Class;"}, "Lfixture/Carrier;", 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Get.access = {"public", "final"};
  Get.generic_signature = "<T:Lfixture/Carrier<*>;>(Ljava/lang/Class<TT;>;)TT;";
  auto Factory = klass("Lfixture/Factory;", {Get});
  Factory.external = SDK;
  if (SDK) {
    Factory.methods[0].instructions.clear();
    Factory.methods[0].registers = Factory.methods[0].code_end = 0;
  }
  auto Token = klass("Ljava/lang/Class;");
  Token.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Token.external = true;
  auto &Caller = Input[0].methods[0];
  Caller.reference.parameters = {Factory.name, "I", "I"};
  Caller.registers = 9;
  Caller.instructions.clear();
  auto append = [&](Instruction I) {
    I.pc = Caller.instructions.size();
    Caller.instructions.push_back(std::move(I));
  };
  if (Prefix) {
    append(op(0, "const-string", {4}, std::string("factory")));
    append(op(0, "invoke-static", {6, 4}, {}, Input[6].methods[0].reference));
    append(op(0, "nop"));
  }
  append(op(0, "const-class", {1}, {}, Input[3].name));
  append(op(0, "move-object", {0, 6}));
  append(op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {0, 1}, {},
            Factory.methods[0].reference));
  append(op(0, "move-result-object", {Alias ? 1u : 3u}));
  if (Alias)
    append(op(0, "move-object", {3, 1}));
  if (Prefix)
    append(op(0, "invoke-static", {3, 4}, {}, Input[6].methods[0].reference));
  if (Range) {
    append(op(0, "move-object", {0, 5}));
    append(op(0, "move-object", {1, 3}));
    append(op(0, "move", {2, 7}));
  }
  append(op(0, Range ? "invoke-direct/range" : "invoke-direct",
            {Range ? 0u : 5u, Range ? 1u : 3u, Range ? 2u : 7u}, {},
            Input[1].methods[0].reference));
  append(op(0, "return-void"));
  Caller.code_end = Caller.instructions.size();
  Input.push_back(Factory);
  Input.push_back(Token);
  return Input;
}

TEST(MobileDalvikJava,
     TokenSuperResultsKeepClosedAncestryAndActualErasedFactoryResult) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Prefix : {false, true})
        for (bool Alias : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Prefix, Alias, Route}));
            auto Input = tokenSuperResultClasses(SDK, Range, Prefix, Alias);
            const auto Caller = Input[0].methods[0].reference;
            const auto Target = Input[1].methods[0].reference;
            const auto Get = Input[8].methods[0].reference;
            const auto Header = Input[0].generic_signature;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plans.erased_generic_invocations.contains(Get));
            EXPECT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_EQ(Classes.at(Caller.owner).generic_signature, Header);
          }
}

TEST(MobileDalvikJava,
     TokenSuperResultsRejectIncompleteLiteralAndFactoryContracts) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input = tokenSuperResultClasses(SDK, true, true, true);
      auto &Caller = Input[0].methods[0];
      auto &Get = Input[8].methods[0];
      auto Token =
          std::find_if(Caller.instructions.begin(), Caller.instructions.end(),
                       [](const auto &I) { return I.opcode == "const-class"; });
      auto Call = std::find_if(Caller.instructions.begin(),
                               Caller.instructions.end(), [&](const auto &I) {
                                 return I.reference == Reference(Get.reference);
                               });
      if (Mutation == 0)
        Input[3].generic_signature = "Lfixture/Carrier;";
      else if (Mutation == 1)
        Input[3].generic_signature = "Lfixture/Carrier<*>;";
      else if (Mutation == 2)
        Input[3].generic_signature = "Lfixture/Carrier<Lfixture/Bound;>;";
      else if (Mutation == 3)
        Input[3].generic_signature = "Lfixture/Carrier<Lfixture/Missing;>;";
      else if (Mutation == 4)
        Input[3].generic_signature =
            "<X:Ljava/lang/Object;>Lfixture/Carrier<Lfixture/Payload;>;";
      else if (Mutation == 5)
        Get.generic_signature =
            "<T:Lfixture/Carrier<*>;>(Ljava/lang/Class<+TT;>;)TT;";
      else if (Mutation == 6)
        Get.generic_signature =
            "<T:Lfixture/Carrier<*>;>(Ljava/lang/Class<TT;>;)TMissing;";
      else if (Mutation == 7)
        Get.access.erase("final");
      else if (Mutation == 8)
        Token->reference = Input[4].name;
      else if (Mutation == 9)
        Call->registers[0] = 5;
      else if (Mutation == 10)
        Get.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 11)
        Input[1].methods[0].access.insert("varargs");
      else if (Mutation == 12)
        Input[1].methods[0].declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 13)
        Input[2].generic_signature = "<E:Lfixture/Missing;>Ljava/lang/Object;";
      else if (Mutation == 14)
        Input[2].generic_signature =
            "<E:Lfixture/Bound;F:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 15)
        Input.erase(Input.begin() + 3);
      else if (Mutation == 16)
        Caller.generic_signature =
            "<X:Ljava/lang/Object;>(Lfixture/Factory;II)V";
      else
        std::next(Call)->opcode = "move-result";
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

