std::vector<Class> tokenPrefixDelegationClasses(bool SDK, bool Range,
                                                bool Member, bool Alpha) {
  auto Input = closedWildcardSuperClasses(SDK, Range, Member, false);
  auto Get =
      method("get", {"Ljava/lang/Class;"}, Input[1].name, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Get.access = {"public", "final"};
  const std::string Formal = Alpha ? "Element" : "T";
  Get.generic_signature = "<" + Formal +
                          ":Lfixture/Carrier<*>;>(Ljava/lang/Class<T" + Formal +
                          ";>;)T" + Formal + ";";
  auto Factory = klass("Lfixture/Factory;", {Get});
  Factory.external = SDK;
  if (SDK) {
    Factory.methods[0].instructions.clear();
    Factory.methods[0].registers = Factory.methods[0].code_end = 0;
  }
  auto Leaf = klass("Lfixture/Leaf;");
  Leaf.superclass = Input[1].name;
  Leaf.generic_signature = "Lfixture/Carrier<" + Input[2].name + ">;";
  Leaf.external = SDK;
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.reference.owner = Input[1].name;
  auto LeafInit = Init;
  LeafInit.reference.owner = Leaf.name;
  LeafInit.instructions[0].reference = Init.reference;
  if (SDK) {
    Init.instructions.clear();
    LeafInit.instructions.clear();
    Init.registers = Init.code_end = LeafInit.registers = LeafInit.code_end = 0;
  }
  Input[1].methods.push_back(Init);
  Leaf.methods.push_back(LeafInit);
  auto Caller = method("<init>", {Factory.name}, "V", Range ? 8 : 3, {});
  Caller.reference.owner = Input[2].name;
  Caller.access = {"public", "constructor"};
  if (Range)
    Caller.instructions = {
        op(0, "const-class", {1}, {}, Leaf.name),
        op(1, "move-object", {0, 7}),
        op(2, "invoke-virtual/range", {0, 1}, {}, Factory.methods[0].reference),
        op(3, "move-result-object", {1}),
        op(4, "move-object", {2, 6}),
        op(5, "move-object", {3, 1}),
        op(6, "invoke-direct/range", {2, 3}, {}, Input[2].methods[0].reference),
        op(7, "return-void")};
  else
    Caller.instructions = {
        op(0, "const-class", {0}, {}, Leaf.name),
        op(1, "invoke-virtual", {2, 0}, {}, Factory.methods[0].reference),
        op(2, "move-result-object", {0}),
        op(3, "invoke-direct", {1, 0}, {}, Input[2].methods[0].reference),
        op(4, "return-void")};
  Caller.code_end = Caller.instructions.size();
  Input[2].methods.push_back(Caller);
  auto ClassToken = klass("Ljava/lang/Class;");
  ClassToken.external = true;
  ClassToken.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Factory);
  Input.push_back(Leaf);
  Input.push_back(ClassToken);
  return Input;
}

