std::vector<Class> capturedRawSuperClasses(bool SDK, bool Range, bool Anonymous,
                                           bool Scoped) {
  auto Input = capturedInnerClasses();
  auto &Outer = Input[0];
  auto &Child = Input[1];
  if (Scoped)
    Outer.generic_signature = "<Result:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "interface", "abstract"};
  Callback.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = SDK;
  auto BaseInit =
      method("<init>", {Callback.name}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  BaseInit.access = {"public", "constructor"};
  BaseInit.generic_signature = "(Lfixture/Callback<TT;>;)V";
  auto Base = klass("Lfixture/Base;", {BaseInit});
  Base.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  Base.external = SDK;
  if (SDK) {
    Base.methods[0].instructions.clear();
    Base.methods[0].registers = Base.methods[0].code_end = 0;
  }
  if (Anonymous) {
    Child.name = "Lfixture/Outer$1;";
    Child.access.clear();
    Child.enclosing.reset();
    Child.inner_name.reset();
    Child.inner_access.clear();
    Child.fields[0].reference.owner = Child.name;
  }
  Child.superclass = Base.name;
  Child.generic_signature = Scoped ? "Lfixture/Base<TResult;>;"
                                   : "Lfixture/Base<Ljava/lang/Object;>;";
  auto &Ctor = Child.methods[0];
  Ctor.reference.owner = Child.name;
  Ctor.reference.parameters = {Outer.name, Callback.name};
  Ctor.generic_signature.reset();
  Ctor.registers = Range ? 6 : 3;
  Ctor.instructions = {op(0, "iput-object", {Range ? 4u : 1u, Range ? 3u : 0u},
                          {}, Child.fields[0].reference)};
  if (Range) {
    Ctor.instructions.push_back(op(1, "move-object", {0, 3}));
    Ctor.instructions.push_back(op(2, "move-object", {1, 5}));
  }
  const auto PC = static_cast<uint32_t>(Ctor.instructions.size());
  Ctor.instructions.push_back(
      op(PC, Range ? "invoke-direct/range" : "invoke-direct",
         {0, Range ? 1u : 2u}, {}, Base.methods[0].reference));
  Ctor.instructions.push_back(op(PC + 1, "return-void"));
  Ctor.code_end = PC + 2;
  auto OuterInit =
      method("<init>", {Callback.name}, "V", 3,
             {op(0, "invoke-direct", {1}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "new-instance", {0}, {}, Child.name),
              op(2, "invoke-direct", {0, 1, 2}, {}, Ctor.reference),
              op(3, "return-void")});
  OuterInit.access = {"public", "constructor"};
  OuterInit.reference.owner = Outer.name;
  Outer.methods.push_back(OuterInit);
  if (Anonymous)
    Child.enclosing_method = OuterInit.reference;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.superclass.reset();
  Object.external = true;
  Input.push_back(Base);
  Input.push_back(Callback);
  Input.push_back(Object);
  return Input;
}

TEST(MobileDalvikJava,
     CapturedRawSupersKeepEnclosingScopeAndOrderedCarrierOrigins) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Anonymous : {false, true})
        for (bool Scoped : {false, true})
          for (bool Reverse : {false, true}) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Anonymous, Scoped, Reverse}));
            auto Input = capturedRawSuperClasses(SDK, Range, Anonymous, Scoped);
            const auto Caller = Input[1].methods[0].reference;
            const auto Target = Input[2].methods[0].reference;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            EXPECT_NO_THROW(([&] {
              Budget B;
              const auto Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(Plans.superclass_calls.contains({Caller, Target}));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            })());
          }
  // The former capture negative is now a complete closed carrier proof.
  // Keep it as a positive case with its original hidden input and field store.
  for (bool External : {false, true})
    for (bool Linked : {false, true}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{External, Linked}));
      auto Input = namedAnonymousAllocationClasses(false, External);
      Input[0].methods.clear();
      auto &Member = Input[1];
      auto &Caller = Member.methods[0];
      const FieldRef Capture{Member.name, "owner", Input[0].name};
      Member.fields.push_back({Capture, {"final", "synthetic"}, {}});
      Caller.reference.parameters.insert(Caller.reference.parameters.begin(),
                                         Input[0].name);
      Caller.registers = 4;
      Caller.instructions = {
          op(0, "iput-object", {1, 0}, {}, Capture),
          op(1, "invoke-direct", {0, 2, 3}, {}, Input[2].methods[0].reference),
          op(2, "return-void")};
      Caller.code_end = 3;
      const auto CallerRef = Caller.reference;
      const auto TargetRef = Input[2].methods[0].reference;
      Budget B;
      ClassMap Classes;
      if (Linked)
        Classes = linkClasses(Input, B);
      else
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
      EXPECT_TRUE(validateGenericSignatures(Classes, B)
                      .superclass_calls.contains({CallerRef, TargetRef}));
      EXPECT_NO_THROW(recoverJava(Classes, B));
    }
}

