std::vector<Class> closedSuperParameterClasses(bool SDK, bool Range,
                                               unsigned Chain, unsigned Shape) {
  auto Input = genericSuperclassCallClasses(false);
  auto &Base = Input[0];
  auto &Target = Base.methods[1];
  Target.reference.returns = "V";
  Target.generic_signature = "(TP;)V";
  Target.instructions = {op(0, "return-void")};
  Target.code_end = 1;
  const auto BaseName = Base.name;
  const auto BaseInit = Base.methods[0];
  auto Payload = klass("Lfixture/Payload;");
  Payload.external = SDK;
  Input.push_back(Payload);
  std::string Parent = BaseName;
  for (unsigned I = 0; I < Chain; ++I) {
    auto Middle = klass(I ? "Lfixture/Near;" : "Lfixture/Middle;", {BaseInit});
    Middle.superclass = Parent;
    Middle.generic_signature = "<M:Ljava/lang/Object;>" +
                               Parent.substr(0, Parent.size() - 1) + "<TM;>;";
    Middle.methods[0].instructions[0].reference =
        MethodRef{Parent, "<init>", {}, "V"};
    Parent = Middle.name;
    Input.push_back(Middle);
  }
  auto &Child = Input[1];
  Child.superclass = Parent;
  Child.generic_signature =
      Parent.substr(0, Parent.size() - 1) + "<Lfixture/Payload;>;";
  Child.methods[0].instructions[0].reference =
      MethodRef{Parent, "<init>", {}, "V"};
  auto &Caller = Child.methods[1];
  Caller.generic_signature.reset();
  Caller.reference.parameters = {Shape == 1 || Shape == 2 ? "Ljava/lang/Object;"
                                                          : Payload.name};
  Caller.reference.returns = "V";
  MethodRef Call{Parent, "echo", {"Ljava/lang/Object;"}, "V"};
  Caller.instructions.clear();
  if (Shape == 1)
    Caller.instructions.push_back(op(0, "check-cast", {2}, {}, Payload.name));
  else if (Shape == 2)
    Caller.instructions.push_back(op(0, "const/4", {2}, int64_t(0)));
  else if (Shape == 3) {
    Caller.instructions.push_back(op(0, "move-object", {0, 1}));
    Caller.instructions.push_back(op(1, "move-object", {1, 2}));
  } else
    Caller.instructions.push_back(op(0, "const/4", {0}, int64_t(3)));
  const auto PC = static_cast<uint32_t>(Caller.instructions.size());
  Caller.instructions.push_back(
      op(PC, Range ? "invoke-super/range" : "invoke-super",
         {Shape == 3 ? 0u : 1u, Shape == 3 ? 1u : 2u}, {}, Call));
  Caller.instructions.push_back(op(PC + 1, "const/4", {0}, int64_t(4)));
  Caller.instructions.push_back(op(PC + 2, "return-void"));
  Caller.code_end = PC + 3;
  for (auto &C : Input)
    if (SDK && C.name != Child.name) {
      C.external = true;
      for (auto &M : C.methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  Object.external = true;
  auto ObjectInit = BaseInit;
  ObjectInit.reference.owner = Object.name;
  ObjectInit.instructions.clear();
  ObjectInit.registers = ObjectInit.code_end = 0;
  Object.methods.push_back(ObjectInit);
  Input.push_back(Object);
  return Input;
}

TEST(MobileDalvikJava,
     ClosedSuperParametersKeepTransitiveScopeAndOriginalWordProof) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (unsigned Chain = 0; Chain < 3; ++Chain)
        for (unsigned Shape = 0; Shape < 4; ++Shape)
          for (bool Reverse : {false, true}) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Chain, Shape, Reverse}));
            auto Input = closedSuperParameterClasses(SDK, Range, Chain, Shape);
            const auto Caller = Input[1].methods[1].reference;
            const auto &Ops = Input[1].methods[1].instructions;
            const auto Found =
                std::find_if(Ops.begin(), Ops.end(), [](const auto &Op) {
                  return Op.opcode == "invoke-super" ||
                         Op.opcode == "invoke-super/range";
                });
            ASSERT_NE(Found, Ops.end());
            const auto Call = std::get<MethodRef>(Found->reference);
            const auto Target = Input[0].methods[1].reference;
            if (Reverse)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_TRUE(Plans.superclass_calls.contains({Caller, Call}));
            EXPECT_EQ(Plans.superclass_call_declarations.at({Caller, Call}),
                      Target);
            const auto &Contract = Plans.superclass_calls.at({Caller, Call});
            EXPECT_EQ(Contract.types.at(Contract.parameters[0]).erasure,
                      "Lfixture/Payload;");
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
          }
}

TEST(MobileDalvikJava,
     ClosedSuperParametersRejectUnprovedWordsAndIncompleteHierarchy) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 14; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input = closedSuperParameterClasses(SDK, true, 1, 0);
      auto &Caller = Input[1].methods[1];
      if (Mutation == 0)
        Caller.reference.parameters = {"Ljava/lang/Object;"};
      else if (Mutation == 1)
        Caller.instructions[0] =
            op(0, "const-string", {2}, std::string("wrong"));
      else if (Mutation == 2)
        Input[1].generic_signature = "Lfixture/Middle<*>;";
      else if (Mutation == 3)
        Input[1].generic_signature = "Lfixture/Middle<+Lfixture/Payload;>;";
      else if (Mutation == 4)
        Input[1].generic_signature = "Lfixture/Middle<Lfixture/Missing;>;";
      else if (Mutation == 5)
        Input[1].generic_signature = "Lfixture/Middle<TMissing;>;";
      else if (Mutation == 6)
        Input.erase(Input.begin());
      else if (Mutation == 7)
        Input[3].generic_signature =
            "<M:Ljava/lang/Object;>Lfixture/CallParent<*>;";
      else if (Mutation == 8)
        Input[1].generic_signature = "Lfixture/Middle<[Lfixture/Payload;>;";
      else if (Mutation == 9)
        Caller.instructions[1].registers[0] = 2;
      else if (Mutation == 10)
        Caller.instructions[1].opcode = "invoke-static/range";
      else if (Mutation == 11) {
        auto Nearer = Input[0].methods[1];
        Nearer.access.insert("abstract");
        Nearer.instructions.clear();
        Nearer.registers = Nearer.code_end = 0;
        Nearer.reference.owner = Input[3].name;
        Input[3].access.insert("abstract");
        Input[3].methods.push_back(Nearer);
      } else if (Mutation == 12)
        Input.erase(Input.begin() + 2);
      else
        Input[1].generic_signature = "Lfixture/Middle;";
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> privateContextualCarrierClasses(bool SDK, bool Range,
                                                   bool Used,
                                                   bool GenericCaller,
                                                   bool Swapped, bool Alpha) {
  auto Input = privateBinaryCarrierClasses(false, 3, SDK, Range, false, false);
  auto Callback = klass("Lfixture/Callback;");
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Callback.external = SDK;
  auto Context = klass("Lfixture/Context;");
  Context.external = SDK;
  auto &Read = Input[0].methods[0];
  Read.reference.parameters =
      Swapped ? std::vector<std::string>{"I", Context.name, Input[1].name,
                                         Callback.name}
              : std::vector<std::string>{"I", Context.name, Callback.name,
                                         Input[1].name};
  Read.generic_signature =
      std::string("<T:Ljava/lang/Object;>(ILfixture/Context;") +
      (Swapped ? "Lfixture/Carrier<TT;>;Lfixture/Callback<TT;>;"
               : "Lfixture/Callback<TT;>;Lfixture/Carrier<TT;>;") +
      ")Lfixture/Carrier<TT;>;";
  if (Alpha) {
    auto &Signature = *Read.generic_signature;
    Signature.replace(0, 3, "<Value:");
    for (size_t At = Signature.find("TT;"); At != std::string::npos;
         At = Signature.find("TT;"))
      Signature.replace(At, 3, "TValue;");
  }
  Read.registers = 6;
  Read.instructions = {op(0, "return-object", {Swapped ? 4u : 5u})};
  Read.code_end = 1;
  auto &Call = Input[0].methods[1];
  Call.reference.parameters = Read.reference.parameters;
  Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                   Input[0].name);
  Call.reference.returns = Used ? Input[1].name : "V";
  Call.registers = 6;
  Call.instructions = {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                          {1, 2, 3, 4, 5}, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(1, "move-result-object", {0}));
    Call.instructions.push_back(op(2, "return-object", {0}));
  } else
    Call.instructions.push_back(op(1, "return-void"));
  Call.code_end = Call.instructions.size();
  if (GenericCaller)
    Call.generic_signature =
        std::string(
            "<R:Ljava/lang/Object;>(Lfixture/Provider;ILfixture/Context;") +
        (Swapped ? "Lfixture/Carrier<TR;>;Lfixture/Callback<TR;>;"
                 : "Lfixture/Callback<TR;>;Lfixture/Carrier<TR;>;") +
        (Used ? ")Lfixture/Carrier<TR;>;" : ")V");
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  Object.external = true;
  Input.push_back(Callback);
  Input.push_back(Context);
  Input.push_back(Object);
  return Input;
}

TEST(MobileDalvikJava,
     PrivateContextualCarriersKeepBothAnchorsAndIndependentContext) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Used : {false, true})
        for (bool GenericCaller : {false, true})
          for (bool Swapped : {false, true})
            for (bool Alpha : {false, true})
              for (bool Reverse : {false, true}) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    SDK, Range, Used, GenericCaller, Swapped, Alpha, Reverse}));
                auto Input = privateContextualCarrierClasses(
                    SDK, Range, Used, GenericCaller, Swapped, Alpha);
                const auto Ref = Input[0].methods[0].reference;
                const auto Signature = Input[0].methods[0].generic_signature;
                if (Reverse)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                const auto Classes = linkClasses(Input, B);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Ref));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
                EXPECT_EQ(Classes.at(Ref.owner).methods[0].generic_signature,
                          Signature);
              }
}

TEST(MobileDalvikJava,
     PrivateContextualCarriersRejectScopeVarianceAndIncompleteDeclarations) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation) {
      SCOPED_TRACE(SDK);
      SCOPED_TRACE(Mutation);
      auto Input =
          privateContextualCarrierClasses(SDK, true, true, true, false, false);
      auto &Read = Input[0].methods[0];
      auto replace = [&](const std::string &From, const std::string &To) {
        auto &Signature = *Read.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      if (Mutation == 0)
        replace("Callback<TT;>", "Callback<+TT;>");
      else if (Mutation == 1)
        replace("Callback<TT;>", "Callback<-TT;>");
      else if (Mutation == 2)
        replace("Callback<TT;>", "Callback<*>");
      else if (Mutation == 3)
        replace(")Lfixture/Carrier<TT;>", ")Lfixture/Carrier<+TT;>");
      else if (Mutation == 4)
        replace("<T:Ljava/lang/Object;>",
                "<T:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 5)
        replace("<T:Ljava/lang/Object;>", "<T:Lfixture/Missing;>");
      else if (Mutation == 6)
        Input.erase(Input.begin() + 2);
      else if (Mutation == 7)
        Input[2].generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 8)
        Input.erase(Input.begin() + 3);
      else if (Mutation == 9)
        Input[0].generic_signature = "<Q:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 10)
        Read.declared_throws = {"Ljava/lang/Exception;"};
      else if (Mutation == 11)
        Read.access.insert("varargs");
      else if (Mutation == 12)
        Read.access.insert("static");
      else if (Mutation == 13)
        Input.push_back(klass("Lfixture/Foreign;", {Input[0].methods[1]}));
      else if (Mutation == 14)
        replace(")Lfixture/Carrier<TT;>", ")Lfixture/Carrier<-TT;>");
      else
        replace("Callback<TT;>", "Callback<TMissing;>");
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

std::vector<Class> packageNominalSelectorClasses(bool SDK, bool Range,
                                                 bool Used, bool GenericCaller,
                                                 bool PublicCarrier = false) {
  const std::string Carrier = "Lfixture/Outer$Item;";
  auto Select =
      method("select", {"I"}, Carrier, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Select.access.clear();
  Select.generic_signature =
      "<T:Ljava/lang/Object;>(I)Lfixture/Outer$Item<TT;>;";
  auto Provider = klass("Lfixture/Outer$Provider;", {Select});
  Provider.access.clear();
  Provider.enclosing = "Lfixture/Outer;";
  Provider.inner_name = "Provider";
  Provider.inner_class_present = true;
  Provider.inner_access = {"static"};
  Provider.external = SDK;
  if (SDK) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Item = klass(Carrier);
  Item.access.clear();
  Item.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Item.enclosing = Provider.enclosing;
  Item.inner_name = "Item";
  Item.inner_class_present = true;
  Item.inner_access = {"static"};
  if (PublicCarrier) {
    Item.access.insert("public");
    Item.inner_access.insert("public");
  }
  Item.external = SDK;
  std::vector<Instruction> Ops{
      op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1, 2}, {},
         Provider.methods[0].reference)};
  if (Used) {
    Ops.push_back(op(1, "move-result-object", {0}));
    Ops.push_back(op(2, "return-object", {0}));
  } else
    Ops.push_back(op(1, "return-void"));
  auto Call =
      method("call", {Provider.name, "I"}, Used ? Carrier : "V", 3, Ops);
  if (GenericCaller)
    Call.generic_signature =
        std::string("<R:Ljava/lang/Object;>(Lfixture/Outer$Provider;I)") +
        (Used ? "Lfixture/Outer$Item<TR;>;" : "V");
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  Object.external = true;
  return {klass("Lfixture/Core;", {Call}), Provider, Item,
          klass("Lfixture/Outer;"), Object};
}

