std::vector<Class> boundedCovariantConsumerClasses(bool SDK, bool Range,
                                                   bool Inherited,
                                                   bool Invariant,
                                                   bool GenericCaller,
                                                   bool Alpha) {
  const std::string Formal = Alpha ? "P" : "T";
  auto Accept =
      method("accept", {"Lfixture/Carrier;"}, "V", 2, {op(0, "return-void")});
  Accept.access = {"public", "final"};
  Accept.generic_signature = "<" + Formal +
                             ":Lfixture/Bound;>(Lfixture/Carrier<" +
                             (Invariant ? "" : "+") + "T" + Formal + ";>;)V";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Consumer = klass("Lfixture/Consumer;", {Accept, Init});
  auto Carrier = klass("Lfixture/Carrier;", {Init});
  Carrier.generic_signature = "<E:Lfixture/Bound;>Ljava/lang/Object;";
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Inherited) {
    Consumer.superclass = Parent.name;
    Consumer.generic_signature = "Lfixture/Parent<Lfixture/Payload;>;";
    Consumer.methods[1].instructions[0].reference = Parent.methods[0].reference;
  }
  auto Call = method("call", {Consumer.name, Carrier.name}, "V", 2,
                     {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                         {0, 1}, {}, Consumer.methods[0].reference),
                      op(1, "return-void")});
  if (GenericCaller)
    Call.generic_signature =
        std::string("<R:Lfixture/Bound;>(Lfixture/Consumer;Lfixture/Carrier<") +
        (Invariant ? "" : "+") + "TR;>;)V";
  auto Bound = klass("Lfixture/Bound;");
  auto Payload = klass("Lfixture/Payload;");
  Payload.superclass = Bound.name;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.superclass.reset();
  Object.external = true;
  std::vector<Class> Classes{klass("Lfixture/Core;", {Call}),
                             Consumer,
                             Carrier,
                             Bound,
                             Payload,
                             Parent,
                             Object};
  if (SDK)
    for (size_t I = 1; I < Classes.size(); ++I) {
      Classes[I].external = true;
      for (auto &M : Classes[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Classes;
}

TEST(MobileDalvikJava,
     BoundedCovariantConsumersKeepIndependentFormalScopesAndVoidCalls) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Inherited : {false, true})
        for (bool Invariant : {false, true})
          for (bool GenericCaller : {false, true})
            for (bool Alpha : {false, true})
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{SDK, Range, Inherited, Invariant, GenericCaller,
                               Alpha, Route}));
                auto Input = boundedCovariantConsumerClasses(
                    SDK, Range, Inherited, Invariant, GenericCaller, Alpha);
                const auto Target = Input[1].methods[0].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                if (Route)
                  Classes = linkClasses(Input, B);
                EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                .erased_generic_invocations.contains(Target));
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              }
  // An unrelated owner formal already has its own raw-receiver permission.
  // Keep that complete original input as a compatibility positive; the new
  // method-formal proof must not narrow an existing independently proven path.
  for (bool SDK : {false, true}) {
    auto Input =
        boundedCovariantConsumerClasses(SDK, true, true, false, true, false);
    Input[1].generic_signature =
        "<X:Lfixture/Bound;>Lfixture/Parent<Lfixture/Payload;>;";
    EXPECT_EQ(recover(Input).getInteger("unrecovered_method_count"), 0);
  }
}

