std::vector<Class> reifiableContextResultClasses(bool SDK, bool Range,
                                                 bool Used, bool GenericCaller,
                                                 bool StringContext, bool Final,
                                                 bool Alias) {
  auto Input =
      boundedStarTokenClasses(SDK, Range, Used, GenericCaller, !StringContext);
  const std::string Context =
      StringContext ? "Ljava/lang/String;" : "Lfixture/Context;";
  const std::string Formal = StringContext ? "T" : "Element";
  auto &Get = Input[1].methods[0];
  Get.reference.parameters = {Context};
  if (!Final)
    Get.access.erase("final");
  Get.generic_signature =
      "<" + Formal + ":Lfixture/Carrier<*>;>(" + Context + ")T" + Formal + ";";
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = {Input[1].name, Context};
  Call.instructions[0].reference = Get.reference;
  if (GenericCaller)
    Call.generic_signature = "<R:Lfixture/Carrier<*>;>(Lfixture/Factory;" +
                             Context + ")" + (Used ? "TR;" : "V");
  if (Alias) {
    Call.registers = 5;
    Call.code_end += 2;
    for (auto &I : Call.instructions)
      I.pc += 2;
    Call.instructions.insert(
        Call.instructions.begin(),
        {op(0, "move-object", {1, 3}), op(1, "move-object", {2, 4})});
  }
  auto ContextClass = klass(Context);
  ContextClass.external = SDK || StringContext;
  Input.push_back(ContextClass);
  return Input;
}

