TEST(MobileDalvikJava,
     BoundedTokenElementsRejectOpenBindingsAndForeignMemberAccess) {
  for (unsigned Mutation = 0; Mutation < 21; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = boundedTokenElementClasses(false, false, true, false, true,
                                              false, true, false);
      auto &Target = Input[0].methods[0];
      auto &Caller = Input[1].methods[0];
      auto Replace = [&](const std::string &From, const std::string &To) {
        auto &S = *Target.generic_signature;
        const auto At = S.find(From);
        ASSERT_NE(At, std::string::npos);
        S.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        Replace("Token<TT;>", "Token<+TT;>");
        break;
      case 1:
        Replace("Token<TT;>", "Token<*>");
        break;
      case 2:
        Replace(")TT;", ")Lfixture/Bound;");
        break;
      case 3:
        Replace("T:Lfixture/Bound;", "T:Lfixture/Bound;U:Ljava/lang/Object;");
        break;
      case 4:
        Input[3].generic_signature.reset();
        break;
      case 5:
        Input[3].generic_signature =
            "<Value:Lfixture/Bound;>Ljava/lang/Object;";
        break;
      case 6:
        Input[2].generic_signature =
            "<Open:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 7:
        Input[2].access.erase("public");
        break;
      case 8:
        Target.declared_throws = {"Ljava/lang/Exception;"};
        break;
      case 9:
        Target.access.insert("synthetic");
        break;
      case 10:
        Target.access.insert("varargs");
        break;
      case 11:
        Target.access.insert("native");
        break;
      case 12:
        Replace(")TT;", ")TQ;");
        break;
      case 13:
        Target.access = {"private", "final"};
        Target.registers = Target.reference.parameters.size() + 2;
        Target.instructions = {op(0, "const/4", {0}, int64_t(0)),
                               op(1, "return-object", {0})};
        Target.code_end = 2;
        Caller.instructions[0].opcode = "invoke-direct";
        break;
      case 14:
        Input[1].name = "Lother/Caller;";
        for (auto &M : Input[1].methods)
          M.reference.owner = Input[1].name;
        Caller.reference.parameters[0] = Input[0].name;
        break;
      case 15:
        Caller.instructions[0].opcode = "invoke-static";
        break;
      case 16:
        Caller.instructions[0].registers.pop_back();
        break;
      case 17:
        Input.erase(Input.begin() + 2);
        break;
      case 18:
        Target.access.erase("abstract");
        break;
      case 19: {
        auto Other = method(
            "create",
            {"Ljava/lang/Object;", "Lfixture/Token;", "Lfixture/Context;"},
            "Lfixture/Bound;", 4,
            {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
        Other.reference.owner = Input[0].name;
        Input[0].methods.push_back(std::move(Other));
        break;
      }
      case 20: {
        auto Other = method(
            "create", {"[Ljava/lang/Object;"}, "Lfixture/Bound;", 2,
            {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
        Other.access.insert("varargs");
        Other.reference.owner = Input[0].name;
        Input[0].methods.push_back(std::move(Other));
        break;
      }
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

std::vector<Class> scopedParentChainClasses(bool External, bool Range,
                                            unsigned Depth, bool Alpha) {
  auto Input = scopedMaskConstructorClasses(External, Range);
  std::vector<Class> Parents;
  for (unsigned I = 0; I < Depth; ++I) {
    const std::string Name = "Lfixture/Parent" + std::to_string(I) + ";";
    const std::string Parent =
        I + 1 == Depth ? "Ljava/lang/Object;"
                       : "Lfixture/Parent" + std::to_string(I + 1) + ";";
    const std::string Formal = Alpha ? "Element" + std::to_string(I) : "P";
    auto Init = method(
        "<init>", {}, "V", 1,
        {op(0, "invoke-direct", {0}, {}, MethodRef{Parent, "<init>", {}, "V"}),
         op(1, "return-void")});
    Init.access = {"protected", "constructor"};
    auto C = klass(Name, {Init});
    C.superclass = Parent;
    C.generic_signature =
        "<" + Formal + ":Ljava/lang/Object;>" +
        (I + 1 == Depth
             ? Parent
             : Parent.substr(0, Parent.size() - 1) + "<T" + Formal + ";>;");
    C.external = External;
    if (External) {
      C.methods[0].instructions.clear();
      C.methods[0].registers = C.methods[0].code_end = 0;
    }
    Parents.push_back(std::move(C));
  }
  auto &C = Input[0];
  C.interfaces.clear();
  C.superclass = Parents[0].name;
  C.generic_signature = "<T:Ljava/lang/Object;>Lfixture/Parent0<TT;>;";
  C.methods[0].instructions[0].reference = Parents[0].methods[0].reference;
  Input.insert(Input.end(), Parents.begin(), Parents.end());
  return Input;
}

TEST(MobileDalvikJava,
     ScopedParentChainsRetainRawMaskAndCompleteAncestorContracts) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (unsigned Depth : {1u, 2u, 4u})
        for (bool Alpha : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{External, Range, Depth, Alpha, Route}));
            auto Input =
                scopedParentChainClasses(External, Range, Depth, Alpha);
            const auto Caller = Input[0].methods[1].reference,
                       Target = Input[0].methods[0].reference;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            EXPECT_NO_THROW(([&] {
              Budget B;
              ClassMap Classes;
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
              if (Route)
                Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.constructor_calls.contains({Caller, Target}));
              const auto &Contract =
                  Plans.constructor_calls.at({Caller, Target});
              EXPECT_TRUE(Contract.type_parameters.empty());
              EXPECT_TRUE(Contract.source_projections.empty());
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 1);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_FALSE(R.getArray("class_source_bindings"));
            })());
          }
}

TEST(MobileDalvikJava,
     ScopedParentChainsRejectMissingCyclicOrDivergentAncestry) {
  for (unsigned Mutation = 0; Mutation < 12; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input = scopedParentChainClasses(false, true, 3, true);
      auto &Owner = Input[0];
      const size_t First = Input.size() - 3, Last = Input.size() - 1;
      switch (Mutation) {
      case 0:
        Input[Last].superclass = "Lfixture/Missing;";
        Input[Last].generic_signature =
            "<Element2:Ljava/lang/Object;>Lfixture/Missing;";
        break;
      case 1:
        Input[Last].superclass = Input[First].name;
        Input[Last].generic_signature =
            "<Element2:Ljava/lang/Object;>Lfixture/Parent0<TElement2;>;";
        break;
      case 2:
        Input[Last].access.erase("public");
        break;
      case 3:
        Input[First + 1].generic_signature =
            "<Element1:Ljava/lang/Object;>Lfixture/Parent2<TUnknown;>;";
        break;
      case 4:
        Owner.generic_signature =
            "<T:Ljava/lang/Object;>Lfixture/Parent0<Ljava/lang/Object;>;";
        break;
      case 5:
        Owner.generic_signature =
            "<T:Ljava/lang/Object;>Lfixture/Parent0<+TT;>;";
        break;
      case 6:
        Input[Last].generic_signature =
            "<Element2:Ljava/lang/Object;Other:Ljava/lang/Object;>"
            "Ljava/lang/Object;";
        break;
      case 7:
        Input[First + 1].access.insert("interface");
        break;
      case 8:
        Input[First + 1].enclosing_method = Owner.methods[1].reference;
        break;
      case 9:
        Owner.methods[1].instructions[6].registers[0] = 7;
        break;
      case 10:
        Owner.methods[0].access.insert("varargs");
        break;
      case 11:
        Owner.methods[0].declared_throws = {"Ljava/lang/Exception;"};
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      ClassMap Classes;
      for (const auto &C : Input)
        Classes.emplace(C.name, C);
      EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                   std::runtime_error);
    }
}

namespace {
std::vector<Class> closedConstructorExceptionClasses(bool SDK, bool Range,
                                                     bool Generic,
                                                     unsigned Declaration) {
  auto Init = method("<init>", {"I"}, "V", 2,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  Init.declared_throws = {"Lfixture/OtherFailure;",
                          "Lfixture/UncheckedFailure;", "Lfixture/LeafFailure;",
                          "Lfixture/FatalFailure;"};
  if (Declaration >= 2)
    Init.declared_throws = {"Lfixture/UncheckedFailure;",
                            "Lfixture/FatalFailure;"};
  auto Base = klass("Lfixture/Base;", {Init});
  Base.external = SDK;
  if (SDK) {
    Base.methods[0].instructions.clear();
    Base.methods[0].registers = Base.methods[0].code_end = 0;
  }
  auto Forward = method("<init>", {"I"}, "V", 2,
                        {op(0, Range ? "invoke-direct/range" : "invoke-direct",
                            {0, 1}, {}, Base.methods[0].reference),
                         op(1, "return-void")});
  Forward.access = {"public", "constructor"};
  if (Declaration < 2)
    Forward.declared_throws =
        Declaration == 0 ? std::vector<std::string>{"Lfixture/RootFailure;",
                                                    "Lfixture/OtherFailure;"}
                         : std::vector<std::string>{"Lfixture/OtherFailure;",
                                                    "Lfixture/RootFailure;"};
  else if (Declaration == 3)
    Forward.declared_throws = std::vector<std::string>{};
  auto Child = klass("Lfixture/Child;", {Forward});
  Child.superclass = Base.name;
  if (Generic) {
    Base.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
    Base.methods[0].generic_signature = "(I)V";
    Child.generic_signature = "Lfixture/Base<Ljava/lang/Object;>;";
    Child.methods[0].generic_signature = "(I)V";
  }
  std::vector<Class> Input{Base, Child};
  const std::pair<std::string, std::string> Hierarchy[] = {
      {"Ljava/lang/Throwable;", "Ljava/lang/Object;"},
      {"Ljava/lang/Exception;", "Ljava/lang/Throwable;"},
      {"Ljava/lang/RuntimeException;", "Ljava/lang/Exception;"},
      {"Ljava/lang/Error;", "Ljava/lang/Throwable;"},
      {"Lfixture/RootFailure;", "Ljava/lang/Exception;"},
      {"Lfixture/LeafFailure;", "Lfixture/RootFailure;"},
      {"Lfixture/OtherFailure;", "Ljava/lang/Exception;"},
      {"Lfixture/UncheckedFailure;", "Ljava/lang/RuntimeException;"},
      {"Lfixture/FatalFailure;", "Ljava/lang/Error;"}};
  for (const auto &[Name, Parent] : Hierarchy) {
    auto Failure = klass(Name);
    Failure.superclass = Parent;
    Failure.external = true;
    Input.push_back(std::move(Failure));
  }
  return Input;
}

std::vector<Class> localConstructorExceptionClasses(bool SDK, bool Range,
                                                    bool Empty) {
  auto Input = closedConstructorExceptionClasses(SDK, Range, false, 0);
  auto &Local = Input[1];
  Local.name = "Lfixture/Host$1;";
  Local.access = {"final"};
  Local.inner_class_present = true;
  Local.inner_access = {"final"};
  auto &Init = Local.methods[0];
  Init.reference.owner = Local.name;
  Init.access = {"constructor"};
  Init.declared_throws.reset();
  if (Empty)
    Init.declared_throws = std::vector<std::string>{};
  const FieldRef Capture{Local.name, "captured", "I"};
  Local.fields.push_back({Capture, {"final", "synthetic"}, {}});
  Init.instructions = {op(0, "iput", {1, 0}, {}, Capture),
                       op(1, Range ? "invoke-direct/range" : "invoke-direct",
                          {0, 1}, {}, Input[0].methods[0].reference),
                       op(2, "return-void")};
  Init.code_end = 3;
  auto Make = method("make", {"I"}, Input[0].name, 2,
                     {op(0, "new-instance", {0}, {}, Local.name),
                      op(1, "invoke-direct", {0, 1}, {}, Init.reference),
                      op(2, "return-object", {0})});
  auto Host = klass("Lfixture/Host;", {Make});
  Local.enclosing_method = Host.methods[0].reference;
  Input.push_back(std::move(Host));
  return Input;
}

std::string constructorExceptionSources(const llvm::json::Object &Report) {
  std::string Text;
  const auto *Units = Report.getArray("source_units");
  if (Units)
    for (size_t I = 0; I < Units->size(); ++I)
      Text += source(Report, I);
  return Text;
}
} // namespace

