TEST(MobileDalvikJava, AllocationLongDivisionRejectsMalformedWordsAndRegions) {
  for (const std::string Opcode :
       {"div-long", "rem-long", "div-long/2addr", "rem-long/2addr"})
    for (unsigned Mutation = 0; Mutation != 20; ++Mutation)
      for (bool Nested : {false, true})
        for (unsigned Route = 0; Route != 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{Opcode, Mutation, Nested, Route}));
          auto Input = allocationLongBitwiseClasses(Opcode, false, true, true);
          if (!Nested) {
            auto M = method("divide", {"J", "J"}, "J", 6,
                            {op(0, "move-wide", {0, 2}),
                             op(1, Opcode,
                                Opcode.ends_with("/2addr")
                                    ? std::vector<unsigned>{0, 4}
                                    : std::vector<unsigned>{0, 2, 4}),
                             op(2, "return-wide", {0})});
            Input = {klass("Lfixture/Core;", {M})};
          }
          auto &M = Input[0].methods[0];
          auto &Arithmetic = M.instructions[Nested ? 6 : 1];
          if (Mutation == 0)
            Arithmetic.registers.pop_back();
          else if (Mutation == 1)
            Arithmetic.registers.push_back(0);
          else if (Mutation == 2)
            Arithmetic.opcode += "/invented";
          else if (Mutation == 3)
            Arithmetic.literal = int64_t(1);
          else if (Mutation == 4)
            Arithmetic.reference = std::string("Ljava/lang/Object;");
          else if (Mutation == 5)
            Arithmetic.target = 2;
          else if (Mutation == 6)
            Arithmetic.targets = {2};
          else if (Mutation == 7)
            Arithmetic.keys = {1};
          else if (Mutation == 8)
            Arithmetic.data = {1};
          else if (Mutation == 9)
            Arithmetic.element_width = 1;
          else if (Mutation == 10)
            Arithmetic.registers[0] = M.registers - 1;
          else if (Mutation == 11)
            Arithmetic.registers.back() = M.registers - 1;
          else if (Mutation == 12)
            Arithmetic.registers.back() = Nested ? 5 : 3;
          else if (Mutation == 13)
            Arithmetic.registers[0] = M.registers;
          else if (Mutation == 14)
            Arithmetic.opcode = "div-long/lit8";
          else if (Mutation == 15)
            Arithmetic.opcode = "rem-long/lit16";
          else if (Mutation == 16)
            Arithmetic.opcode = "div-int";
          else if (Mutation == 17)
            Arithmetic.registers.back() = M.registers;
          else if (Mutation == 18) {
            if (Nested)
              Arithmetic.registers[0] =
                  2; // High word aliases the fresh receiver.
            else
              M.instructions[0] = op(0, "const/4", {0}, int64_t(1));
            if (!Nested && !Opcode.ends_with("/2addr"))
              Arithmetic.registers[1] = 0;
          } else {
            Arithmetic.registers.back() = Nested ? 2 : 1;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(
              [&] {
                if (Route)
                  recoverJava(linkClasses(Input, B), B);
                else
                  recover(Input);
              }(),
              std::runtime_error);
        }
  for (const std::string Opcode : {"div-long", "rem-long"}) {
    auto Conditional =
        conditionalPackedClasses("ne", "and", false, true, false, false);
    Conditional[0].methods[0].instructions[4].opcode = Opcode;
    EXPECT_THROW(recover(Conditional), std::runtime_error);
    auto Prefix =
        longConstructorClasses(Opcode, false, false, true, false, false);
    EXPECT_THROW(recover(Prefix), std::runtime_error);
    auto M =
        method("<init>", {"J", "J"}, "V", 14,
               {op(0, "new-instance", {5}, {}, std::string("Lfixture/Target;")),
                op(1, Opcode, {0, 10, 12}),
                op(2, "invoke-direct", {5}, {},
                   MethodRef{"Lfixture/Target;", "<init>", {}, "V"}),
                op(3, "return-void")});
    M.access = {"public", "constructor"};
    Budget B;
    EXPECT_FALSE(constructorPrefixAllocationEnd(M, 0, B));
  }
}

namespace {
std::vector<Class> inheritedStaticPrefixClasses(const std::string &Type,
                                                bool External, bool Range,
                                                bool This, bool High,
                                                unsigned Symbolic,
                                                bool ForeignMiddle = false) {
  const auto Words = width(Type);
  auto RootInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  RootInit.access = {"public", "constructor"};
  auto Ancestor = klass("Lfixture/Ancestor;", {RootInit});
  Ancestor.fields.push_back(
      {{Ancestor.name, "sharedValue", Type},
       {"protected", "static"},
       Type == "I" || Type == "J" ? FieldValue(int64_t(37)) : FieldValue{}});
  auto MidInit =
      method("<init>", {Type}, "V", Words + 1,
             {op(0, "invoke-direct", {0}, {}, Ancestor.methods[0].reference),
              op(1, "return-void")});
  MidInit.access = {"public", "constructor"};
  auto Middle =
      klass(ForeignMiddle ? "Lother/Middle;" : "Lfixture/Middle;", {MidInit});
  Middle.superclass = Ancestor.name;
  std::vector<unsigned> Arguments{0, 1};
  if (Words == 2)
    Arguments.push_back(2);
  auto Primary = method(
      "<init>", {Type}, "V", Words + 1,
      {op(0, "invoke-direct", Arguments, {}, Middle.methods[0].reference),
       op(1, "return-void")});
  Primary.access = {"public", "constructor"};
  const std::string Owner = "Lfixture/Core;";
  Primary.reference.owner = Owner;
  const FieldRef Ref{Symbolic == 0   ? Owner
                     : Symbolic == 1 ? Middle.name
                                     : Ancestor.name,
                     "sharedValue", Type};
  const auto Suffix = Type.starts_with('L') || Type.starts_with('[') ? "-object"
                      : Words == 2                                   ? "-wide"
                      : Type == "Z" ? "-boolean"
                      : Type == "B" ? "-byte"
                      : Type == "C" ? "-char"
                      : Type == "S" ? "-short"
                                    : "";
  Arguments = {Range ? 1u : 7u, 2};
  if (Words == 2)
    Arguments.push_back(3);
  auto Default =
      method("<init>", {}, "V", 8,
             {op(0, std::string("sget") + Suffix, {2}, {}, Ref),
              Range ? op(1, "move-object", {1, 7}) : op(1, "nop"),
              op(2, Range ? "invoke-direct/range" : "invoke-direct", Arguments,
                 {}, This ? Primary.reference : Middle.methods[0].reference),
              op(3, "return-void")});
  Default.access = {"public", "constructor"};
  if (High) {
    Default.registers += 24;
    for (auto &Instruction : Default.instructions)
      for (auto &Register : Instruction.registers)
        Register += 24;
  }
  auto Read = method(
      "read", {}, Type, Words,
      {op(0, std::string("sget") + Suffix, {0}, {}, Ref),
       op(1,
          Type.starts_with('L') || Type.starts_with('[') ? "return-object"
          : Words == 2                                   ? "return-wide"
                                                         : "return",
          {0})});
  auto Core = klass(Owner, {Primary, Default, Read});
  Core.superclass = Middle.name;
  if (External)
    for (auto *C : {&Ancestor, &Middle}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return {Core, Middle, Ancestor};
}
} // namespace

TEST(MobileDalvikJava,
     InheritedStaticPrefixesKeepSymbolicOwnersAndDeclarations) {
  for (const std::string Type :
       {"I", "J", "F", "D", "Z", "B", "C", "S", "Ljava/lang/Object;", "[I"})
    for (bool External : {false, true})
      for (bool Range : {false, true})
        for (bool This : {false, true})
          for (bool High : {false, true})
            for (unsigned Symbolic = 0; Symbolic != 3; ++Symbolic)
              for (unsigned Route = 0; Route != 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    Type, External, Range, This, High, Symbolic, Route}));
                auto Input = inheritedStaticPrefixClasses(Type, External, Range,
                                                          This, High, Symbolic);
                const auto Default = Input[0].methods[1];
                const auto Read = Default.instructions[0];
                const auto Ref = std::get<FieldRef>(Read.reference);
                const auto Declaration = Input[2].fields[0].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                const auto Lookup = lookupField(Ref, Classes, B);
                ASSERT_EQ(Lookup.status, FieldLookupStatus::Found);
                ASSERT_NE(Lookup.declaration, nullptr);
                EXPECT_EQ(Lookup.declaration->reference, Declaration);
                EXPECT_EQ(
                    constructorPrefixStaticRead(Default, Read, Classes, B),
                    Ref);
                const auto R = recoverJava(Classes, B);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                          0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              }
}

TEST(MobileDalvikJava, InheritedStaticPrefixesRejectHiddenFieldsAndOpenScopes) {
  for (unsigned Mutation = 0; Mutation != 22; ++Mutation)
    for (bool External : {false, true})
      for (unsigned Route = 0; Route != 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Mutation, External, Route}));
        auto Input = inheritedStaticPrefixClasses("J", External, true, true,
                                                  false, 0, Mutation == 20);
        auto &Core = Input[0];
        auto &Middle = Input[1];
        auto &Ancestor = Input[2];
        auto &Default = Core.methods[1];
        auto &Read = Default.instructions[0];
        auto &Field = Ancestor.fields[0];
        if (Mutation == 0)
          Ancestor.fields.clear();
        else if (Mutation == 1)
          Middle.fields.push_back(
              {{Middle.name, "sharedValue", "I"}, {"public", "static"}, {}});
        else if (Mutation == 2)
          Field.access = {"private", "static"};
        else if (Mutation == 3)
          Field.access.erase("static");
        else if (Mutation == 4)
          Field.access.insert("final");
        else if (Mutation == 5) {
          Field.access.insert("final");
          Field.value = int64_t(0);
          Ancestor.external = true;
          Ancestor.methods[0].instructions.clear();
          Ancestor.methods[0].registers = Ancestor.methods[0].code_end = 0;
        } else if (Mutation == 6)
          Middle.superclass = "Lfixture/Missing;";
        else if (Mutation == 7)
          Middle.superclass = Core.name;
        else if (Mutation == 8)
          Core.interfaces.push_back("Lfixture/UnknownInterface;");
        else if (Mutation == 9)
          Read.registers = {7};
        else if (Mutation == 10)
          Read.registers = {6};
        else if (Mutation == 11)
          Read.registers = {8};
        else if (Mutation == 12)
          Read.literal = int64_t(1);
        else if (Mutation == 13)
          Read.target = 2;
        else if (Mutation == 14)
          Read.targets = {2};
        else if (Mutation == 15)
          Read.keys = {1};
        else if (Mutation == 16)
          Read.data = {1};
        else if (Mutation == 17)
          Read.element_width = 1;
        else if (Mutation == 18)
          Read.opcode = "sget";
        else if (Mutation == 19)
          Read.registers.push_back(4);
        else if (Mutation == 20)
          Field.access.erase("protected");
        else
          Middle.fields.push_back(
              {{Middle.name, "sharedValue", "J"}, {"public"}, {}});
        const auto Constructor = Default;
        const auto Operation = Read;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        ClassMap Classes;
        for (const auto &C : Input)
          Classes.emplace(C.name, C);
        EXPECT_FALSE(
            constructorPrefixStaticRead(Constructor, Operation, Classes, B));
        EXPECT_THROW(recoverJava(Route ? linkClasses(Input, B) : Classes, B),
                     std::runtime_error);
      }
}

TEST(MobileDalvikJava, SharedFieldLookupKeepsOrdinarySelectionAndFailureFacts) {
  auto Input = inheritedStaticPrefixClasses("I", false, false, false, false, 0);
  ClassMap Classes;
  for (const auto &C : Input)
    Classes.emplace(C.name, C);
  const FieldRef Ref{Input[0].name, "sharedValue", "I"};
  Budget B;
  EXPECT_EQ(
      lookupField({"Lfixture/Missing;", Ref.name, Ref.type}, Classes, B).status,
      FieldLookupStatus::UnknownOwner);
  EXPECT_EQ(lookupField({Ref.owner, "missing", Ref.type}, Classes, B).status,
            FieldLookupStatus::Missing);
  Classes.at(Input[1].name)
      .fields.push_back(
          {{Input[1].name, Ref.name, "J"}, {"public", "static"}, {}});
  EXPECT_EQ(lookupField(Ref, Classes, B).status,
            FieldLookupStatus::TypeMismatch);
  Classes.at(Input[1].name).fields.back().reference.type = "I";
  const auto Selected = lookupField(Ref, Classes, B);
  ASSERT_EQ(Selected.status, FieldLookupStatus::Found);
  ASSERT_NE(Selected.declaration, nullptr);
  EXPECT_EQ(Selected.declaration->reference.owner, Input[1].name);
  auto Instance = Input[0].methods[1];
  Instance.reference.parameters = {Input[0].name};
  Instance.instructions[0] = op(0, "iget", {0, 7}, {}, Ref);
  Classes.at(Input[1].name).fields.back().access.erase("static");
  EXPECT_FALSE(constructorPrefixInstanceRead(Instance, Instance.instructions[0],
                                             Classes, B));
}

