std::vector<Class> genericPackageIdentifierClasses(bool SDK, bool Alpha,
                                                   bool Range, unsigned Gap,
                                                   bool FinalChild) {
  auto Input = closedOwnerPackageSyntheticIdentifierClasses(SDK);
  const std::string Key = Alpha ? "Key" : "K";
  const std::string Value = Alpha ? "Value" : "V";
  Input[0].generic_signature =
      "<" + Key + ":Ljava/lang/Object;" + Value +
      ":Ljava/lang/Object;>Ljava/lang/Object;Lfixture/Scope<T" + Value + ";>;";
  Input[1].generic_signature =
      "<" + Value + ":Ljava/lang/Object;>Lfixture/Core<Ljava/lang/String;T" +
      Value + ";>;";
  if (FinalChild)
    Input[1].access.insert("final");
  for (auto &C : Input)
    for (auto &M : C.methods) {
      if (M.instructions.empty())
        continue;
      M.registers += Gap;
      for (auto &Op : M.instructions) {
        for (auto &R : Op.registers)
          R += Gap;
        if (Range && Op.opcode.starts_with("invoke-"))
          Op.opcode += "/range";
      }
    }
  return Input;
}

TEST(MobileDalvikJava, GenericPackageIdentifiersKeepRetainedOwnerScopes) {
  for (bool SDK : {false, true})
    for (bool Alpha : {false, true})
      for (bool Range : {false, true})
        for (unsigned Gap : {0, 8})
          for (bool FinalChild : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Alpha, Range, Gap, FinalChild, Route}));
              auto Input = genericPackageIdentifierClasses(SDK, Alpha, Range,
                                                           Gap, FinalChild);
              const auto Core = Input[0].name, Child = Input[1].name;
              const auto CoreSignature = Input[0].generic_signature;
              const auto ChildSignature = Input[1].generic_signature;
              if (Route == 2) {
                for (auto &C : Input)
                  std::reverse(C.methods.begin(), C.methods.end());
                std::reverse(Input.begin(), Input.end());
              }
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count"), 2);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_EQ(Classes.at(Core).generic_signature, CoreSignature);
              EXPECT_EQ(Classes.at(Child).generic_signature, ChildSignature);
              unsigned Count = 0;
              for (const auto &Value : *R.getArray("methods")) {
                const auto &Row = *Value.getAsObject();
                if (Row.getString("name") != "accept-value")
                  continue;
                ++Count;
                EXPECT_EQ(Row.getString("projection_kind"),
                          "virtual-method-identifier");
                EXPECT_EQ(Row.getString("source_name"),
                          "__neverdVirtualMethod1");
                ASSERT_NE(Row.getArray("source_name_family"), nullptr);
                EXPECT_EQ(Row.getArray("source_name_family")->size(), 2U);
                ASSERT_NE(Row.getArray("metadata_differences"), nullptr);
                EXPECT_EQ(Row.getArray("metadata_differences")->size(), 3U);
              }
              EXPECT_EQ(Count, 2U);
              std::string Text;
              for (const auto &Unit : *R.getArray("source_units"))
                Text += Unit.getAsObject()->getString("source")->str();
              EXPECT_NE(Text.find("super.__neverdVirtualMethod1("),
                        std::string::npos);
              EXPECT_EQ(Text.find("accept-value"), std::string::npos);
            }
}

TEST(MobileDalvikJava, GenericPackageIdentifiersRejectUnprovedScopesAndAccess) {
  for (unsigned Mutation = 0; Mutation < 21; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          genericPackageIdentifierClasses(false, false, true, 8, false);
      auto &Core = Input[0];
      auto &Send = Core.methods[0];
      switch (Mutation) {
      case 0:
        Core.generic_signature =
            "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Scope<TMissing;>;";
        break;
      case 1:
        Send.generic_signature =
            "<T:Ljava/lang/Object;>(Ljava/lang/Object;)Ljava/lang/Object;";
        break;
      case 2:
        Send.generic_signature = "(Ljava/lang/Object;)Ljava/lang/Object;";
        break;
      case 3:
        Input.pop_back();
        break;
      case 4:
        Core.external = true;
        for (auto &M : Core.methods) {
          M.instructions.clear();
          M.registers = M.code_end = 0;
        }
        break;
      case 5:
        Input[1].methods[0].access.insert("public");
        break;
      case 6:
        Input[2].name = "Lother/Caller;";
        for (auto &M : Input[2].methods)
          M.reference.owner = Input[2].name;
        break;
      case 7:
        Core.superclass = "Lfixture/Missing;";
        Core.methods[1].instructions[0].reference =
            MethodRef{*Core.superclass, "<init>", {}, "V"};
        break;
      case 8:
        Send.access.insert("bridge");
        break;
      case 9:
        Send.access.erase("synthetic");
        break;
      case 10:
        Send.access.insert("private");
        break;
      case 11:
        Send.access.insert("protected");
        break;
      case 12:
        Send.access.insert("native");
        Send.instructions.clear();
        break;
      case 13:
        Send.access.insert("abstract");
        Send.instructions.clear();
        break;
      case 14:
        Send.instructions[0].opcode = "unsupported-owned-instruction";
        break;
      case 15:
        Input[2].methods[0].instructions[0].registers = {8};
        break;
      case 16:
        Input[1].methods.erase(Input[1].methods.begin());
        std::get<MethodRef>(Input[2].methods[0].instructions[0].reference)
            .owner = Input[1].name;
        break;
      case 17:
        Core.generic_signature =
            "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Scope<+TV;>;";
        break;
      case 18:
        Core.enclosing_method = Input[2].methods[0].reference;
        Core.inner_class_present = true;
        Core.inner_name = "Local";
        break;
      case 19:
        Input.push_back(klass("Lother/Independent;", {Send}));
        break;
      case 20:
        Input[3].generic_signature.reset();
        break;
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      EXPECT_THROW(
          [&] {
            if (Route)
              recoverJava(linkClasses(Input, B), B);
            else
              recover(Input);
          }(),
          std::runtime_error);
    }
}

std::vector<Class> allocatedNestedCarrierDelegationClasses(bool SDK, bool Range,
                                                           bool Copy,
                                                           bool Rename,
                                                           unsigned Reuse = 0) {
  const std::string Key = Rename ? "Key" : "K";
  const std::string Value = Rename ? "Value" : "V";
  const std::string Formals =
      "<" + Key + ":Ljava/lang/Object;" + Value + ":Ljava/lang/Object;>";
  const std::string Pair = "T" + Key + ";T" + Value + ";";
  const std::string Carrier = "Lfixture/Carrier<Lfixture/Wrap<T" + Key +
                              ";>;Lfixture/Pair<" + Pair + ">;>;";
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.access = {"public", "constructor"};
  auto Base = klass("Lfixture/Base;", {Init});
  Base.generic_signature = Formals + "Ljava/lang/Object;";
  auto Target =
      method("<init>", {"J", "Lfixture/Carrier;"}, "V", 4,
             {op(0, "invoke-direct", {0}, {}, Base.methods[0].reference),
              op(1, "return-void")});
  Target.access = Init.access;
  Target.generic_signature = "(J" + Carrier + ")V";
  auto Core = klass("Lfixture/Core;", {Target});
  Core.superclass = Base.name;
  Core.generic_signature = Formals + "Lfixture/Base<" + Pair + ">;";
  auto Map = klass("Lfixture/Carrier;");
  Map.access = {"public", "abstract", "interface"};
  Map.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Middle = klass("Lfixture/Middle;", {Init});
  Middle.interfaces = {Map.name};
  Middle.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/"
                             "lang/Object;Lfixture/Carrier<TA;TB;>;";
  auto Store = klass("Lfixture/Store;", {Init});
  Store.superclass = Middle.name;
  Store.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Lfixture/Middle<TA;TB;>;";
  Store.methods[0].instructions[0].reference = Middle.methods[0].reference;
  auto Wrap = klass("Lfixture/Wrap;", {Init});
  Wrap.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  auto PairClass = klass("Lfixture/Pair;", {Init});
  PairClass.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  const unsigned Self = Range ? 8 : Copy ? 3 : 1;
  const unsigned Allocation = Reuse   ? Self + (Reuse == 3 ? 2 : 1)
                              : Range ? 6
                                      : 0;
  const unsigned Incoming = Self + (Reuse ? Reuse == 1 ? 2 : 3 : 1);
  std::vector<std::string> Parameters{"J"};
  if (Reuse)
    Parameters.insert(Parameters.begin(), Reuse == 1 ? "I" : "J");
  std::vector<Instruction> Code;
  auto Append = [&](Instruction I) {
    I.pc = Code.size();
    Code.push_back(std::move(I));
  };
  Append(op(0, "new-instance", {Allocation}, {}, Store.name));
  Append(op(0, Range ? "invoke-direct/range" : "invoke-direct", {Allocation},
            {}, Store.methods[0].reference));
  if (Copy)
    Append(op(0, "move-object", {Range ? 7u : 1u, Allocation}));
  unsigned Receiver = Self, Wide = Incoming,
           Object = Copy ? (Range ? 7u : 1u) : Allocation;
  if (Range) {
    Append(op(0, "move-object/from16", {0, Self}));
    Append(op(0, "move-wide/from16", {1, Incoming}));
    Append(op(0, "move-object", {3, Object}));
    Receiver = 0;
    Wide = 1;
    Object = 3;
  }
  Append(op(0, Range ? "invoke-direct/range" : "invoke-direct",
            {Receiver, Wide, Wide + 1, Object}, {}, Core.methods[0].reference));
  Append(op(0, "return-void"));
  auto Caller = method("<init>", Parameters, "V", Incoming + 2, Code);
  Caller.reference.owner = Core.name;
  Caller.access = Init.access;
  Core.methods.push_back(Caller);
  auto Sibling = Target;
  Sibling.reference.parameters[1] = "Ljava/lang/Object;";
  Sibling.reference.owner = Core.name;
  Sibling.generic_signature.reset();
  Core.methods.push_back(Sibling);
  std::vector<Class> Result{Core, Store, Map, Wrap, PairClass, Middle, Base};
  if (SDK)
    for (size_t I = 1; I < Result.size(); ++I) {
      Result[I].external = true;
      for (auto &M : Result[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Result;
}

TEST(MobileDalvikJava,
     AllocatedNestedCarriersKeepScopedDelegationAndOriginalAllocation) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Copy : {false, true})
        for (bool Rename : {false, true})
          for (unsigned Reuse = 0; Reuse < 4; ++Reuse)
            for (unsigned Covariance : {0u, 1u, 2u})
              for (unsigned Route = 0; Route < 3; ++Route) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    SDK, Range, Copy, Rename, Reuse, Covariance, Route}));
                auto Input = allocatedNestedCarrierDelegationClasses(
                    SDK, Range, Copy, Rename, Reuse);
                if (Covariance) {
                  auto &Signature = *Input[0].methods[0].generic_signature;
                  const std::string Marker =
                      Covariance == 1 ? "Lfixture/Carrier<" : "Lfixture/Wrap<";
                  Signature.insert(Signature.find(Marker) + Marker.size(), "+");
                }
                const auto Caller = Input[0].methods[1].reference;
                const auto Target = Input[0].methods[0].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                EXPECT_NO_THROW(([&] {
                  Budget B;
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  if (Route)
                    Classes = linkClasses(Input, B);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(
                      Plans.constructor_calls.contains({Caller, Target}));
                  EXPECT_FALSE(Plans.methods.contains(Caller));
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                            0);
                  EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8),
                            25);
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                  EXPECT_FALSE(
                      Classes.at(Caller.owner).methods[1].generic_signature);
                  std::string Text;
                  const auto *Units = R.getArray("source_units");
                  ASSERT_NE(Units, nullptr);
                  for (size_t I = 0; I < Units->size(); ++I)
                    Text += source(R, I);
                  EXPECT_NE(Text.find("new fixture.Store"), std::string::npos);
                })());
              }
}

TEST(MobileDalvikJava, AllocatedNestedCarriersRejectUnprovedTypesAndOrigins) {
  for (unsigned Mutation = 0; Mutation < 27; ++Mutation)
    for (unsigned Route = 0; Route < 3; ++Route) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{Mutation, Route}));
      auto Input =
          allocatedNestedCarrierDelegationClasses(false, false, false, false);
      auto &Core = Input[0];
      auto &Target = Core.methods[0];
      auto &Caller = Core.methods[1];
      auto &Store = Input[1];
      const std::string Original = *Target.generic_signature;
      auto Replace = [&](std::string From, std::string To) {
        auto &Signature = *Target.generic_signature;
        const auto At = Signature.find(From);
        ASSERT_NE(At, std::string::npos);
        Signature.replace(At, From.size(), To);
      };
      switch (Mutation) {
      case 0:
        Target.generic_signature = "<M:Ljava/lang/Object;>" + Original;
        break;
      case 1:
        Replace("Carrier<Lfixture/Wrap", "Carrier<-Lfixture/Wrap");
        break;
      case 2:
        Replace("Wrap<TK;", "Wrap<-TK;");
        break;
      case 3:
        Core.generic_signature =
            "<K:Ljava/lang/Number;V:Ljava/lang/Object;>Lfixture/Base<TK;TV;>;";
        break;
      case 4:
        Input[3].generic_signature = "<A:Ljava/lang/Number;>Ljava/lang/Object;";
        break;
      case 5:
        Input[4].generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 6:
        Replace("Lfixture/Pair<", "Lfixture/Missing<");
        break;
      case 7:
        Replace("Wrap<TK;", "Wrap<TUnknown;");
        break;
      case 8:
        Store.methods.clear();
        break;
      case 9:
        Store.methods[0].access = {"private", "constructor"};
        break;
      case 10:
        Store.access.insert("abstract");
        break;
      case 11:
        Store.access.insert("interface");
        break;
      case 12:
        std::get<MethodRef>(Caller.instructions[1].reference).owner =
            Input[3].name;
        break;
      case 13:
        Caller.instructions[1].registers.push_back(2);
        break;
      case 14:
        Caller.instructions[0].literal = int64_t(4);
        break;
      case 15:
        Caller.instructions[0].registers = {1};
        break;
      case 16:
        Caller.instructions[2].registers = {1, 3, 2, 0};
        break;
      case 17:
        Core.methods[2].generic_signature = "<M:Ljava/lang/Object;>(JTM;)V";
        break;
      case 18:
        Core.methods[2].access.insert("varargs");
        break;
      case 19:
        Target.access.insert("synthetic");
        break;
      case 20:
        Caller.access.insert("synthetic");
        break;
      case 21:
        Store.methods[0].generic_signature = "<M:Ljava/lang/Object;>()V";
        break;
      case 22:
        Input[5].interfaces.clear();
        Input[5].generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
        break;
      case 23:
        Replace("Wrap<TK;>", "Wrap");
        break;
      case 24: {
        std::string Deep = "TK;";
        for (unsigned I = 0; I < 10; ++I)
          Deep = "Lfixture/Wrap<" + Deep + ">;";
        Replace("TK;", Deep);
        break;
      }
      case 25:
      case 26: {
        // Either original wide word is overwritten by the initialized object.
        // No later delegation may reuse that stale primitive value.
        const unsigned Destination = Mutation == 25 ? 1 : 2;
        Caller.reference.parameters = {"J", "J"};
        Caller.registers = 5;
        Caller.instructions[0].registers = {Destination};
        Caller.instructions[1].registers = {Destination};
        Caller.instructions[2].registers = {0, 1, 2, Destination};
        break;
      }
      }
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      EXPECT_THROW(([&] {
                     Budget B;
                     if (Route)
                       recoverJava(linkClasses(Input, B), B);
                     else
                       recover(Input);
                   })(),
                   std::runtime_error);
    }
}

std::vector<Class> allocatedNestedCarrierSuperclassClasses(
    bool SDK, bool Range, bool Copy, bool Rename, unsigned Reuse, bool Swap) {
  auto Input = allocatedNestedCarrierDelegationClasses(false, Range, Copy,
                                                       Rename, Reuse);
  auto Caller = Input[0].methods[1];
  Input[0].methods.erase(Input[0].methods.begin() + 1);
  const std::string Key = Rename ? "ChildKey" : "X";
  const std::string Value = Rename ? "ChildValue" : "Y";
  auto Child = klass("Lfixture/Child;", {Caller});
  Child.superclass = Input[0].name;
  Child.generic_signature = "<" + Key + ":Ljava/lang/Object;" + Value +
                            ":Ljava/lang/Object;>Lfixture/Core<T" +
                            (Swap ? Value : Key) + ";T" + (Swap ? Key : Value) +
                            ";>;";
  if (SDK)
    for (auto &C : Input) {
      C.external = true;
      for (auto &M : C.methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  Input.push_back(std::move(Child));
  return Input;
}

