namespace {
std::vector<Class> seedContextThrowsClasses(unsigned Kind, unsigned Shape,
                                            bool Range, bool Alpha, bool Used,
                                            bool Wide, bool Varargs,
                                            unsigned Throws) {
  const unsigned ArrayShape = Shape == 1 ? 2 : Shape == 2 ? 1 : 0;
  auto Input = throwingTokenArrayClasses(Kind, ArrayShape, Range, Shape == 1,
                                         Alpha, Used, Wide, Varargs, Throws);
  auto &Read = Input[1].methods[0];
  const auto Array = Read.reference.parameters.back();
  const std::string Formal = Alpha ? "Item" : "T";
  Read.reference.parameters = {"Ljava/lang/Object;", "Ljava/lang/String;"};
  if (Wide)
    Read.reference.parameters.push_back("J");
  Read.reference.parameters.push_back(Array);
  Read.generic_signature = "<" + Formal + ":Ljava/lang/Object;>(T" + Formal +
                           ";Ljava/lang/String;" + (Wide ? "J" : "") +
                           (Shape == 1 ? "[Ljava/lang/Class<*>;" : Array) +
                           ")T" + Formal + ";";
  if (!Input[1].external)
    Read.registers = Read.incomingWords() + 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  const unsigned First = Range ? 16 : 1;
  Call.registers = First + Read.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions[0] = op(0, Range ? "invoke-static/range" : "invoke-static",
                            Words, {}, Read.reference);
  return Input;
}
} // namespace

TEST(MobileDalvikJava, DirectContextSeedsKeepOriginalResultsArraysAndThrows) {
  for (unsigned Kind = 0; Kind < 2; ++Kind)
    for (unsigned Shape = 0; Shape < 3; ++Shape)
      for (unsigned Mode = 0; Mode < 8; ++Mode)
        for (unsigned Route = 0; Route < 3; ++Route) {
          const bool Range = Mode & 1, Varargs = Mode & 2, Used = Mode & 4;
          SCOPED_TRACE(
              ::testing::PrintToString(std::tuple{Kind, Shape, Mode, Route}));
          auto Input = seedContextThrowsClasses(
              Kind, Shape, Range, (Shape + Mode) & 1, Used, Range != Varargs,
              Varargs, Mode % 3);
          const auto Original = Input[1].methods[0];
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(
              Plans.erased_generic_invocations.contains(Original.reference));
          EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
          EXPECT_EQ(
              Classes.at(Original.reference.owner).methods[0].generic_signature,
              Original.generic_signature);
          EXPECT_EQ(
              Classes.at(Original.reference.owner).methods[0].declared_throws,
              Original.declared_throws);
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
        }
}

TEST(MobileDalvikJava, DirectContextSeedsRejectOpenSlotsExceptionsAndFrames) {
  for (unsigned Kind : {0u, 1u})
    for (unsigned Mutation = 0; Mutation < 29; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        // Complete array results now reuse the shared static input proof.
        if (Mutation == 4)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Kind, Mutation, Route}));
        auto Input =
            seedContextThrowsClasses(Kind, 1, true, false, true, true, true, 1);
        auto &Read = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](std::string_view Before, std::string_view After) {
          const auto At = Read.generic_signature->find(Before);
          ASSERT_NE(At, std::string::npos);
          Read.generic_signature->replace(At, Before.size(), After);
        };
        switch (Mutation) {
        case 0:
          Replace("<T:", "<U:Ljava/lang/Object;T:");
          break;
        case 1:
          Replace(")TT;", ")TMissing;");
          break;
        case 2:
          Replace(")TT;", ")Ljava/lang/Object;");
          break;
        case 3:
          Replace(">(TT;", ">([TT;");
          Read.reference.parameters[0] = "[Ljava/lang/Object;";
          Call.reference.parameters = Read.reference.parameters;
          break;
        case 4:
          Replace(")TT;", ")[TT;");
          Read.reference.returns = "[Ljava/lang/Object;";
          Call.reference.returns = Read.reference.returns;
          break;
        case 5:
          Replace("Class<*>", "Class<TT;>");
          break;
        case 6:
          Replace("[Ljava/lang/Class<*>;", "Ljava/lang/Class<*>;");
          Read.reference.parameters.back() = "Ljava/lang/Class;";
          Call.reference.parameters = Read.reference.parameters;
          break;
        case 7:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 8:
          Input[1].generic_signature =
              "<T:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 9:
          Input[1].enclosing_method =
              MethodRef{"Lfixture/Outer;", "run", {}, "V"};
          break;
        case 10:
          Input[2].generic_signature =
              "<C:Lfixture/Missing;>Ljava/lang/Object;";
          break;
        case 11:
          Read.access.insert("native");
          break;
        case 12:
          Read.access.insert("abstract");
          break;
        case 13:
          Read.access.insert("synthetic");
          break;
        case 14:
          Read.access.insert("bridge");
          break;
        case 15:
          Read.access = {"protected", "static", "varargs"};
          break;
        case 16:
          Read.access = {"private", "static", "varargs"};
          break;
        case 17:
          Read.access.erase("static");
          break;
        case 18:
          Read.declared_throws = {"Lfixture/Missing;"};
          break;
        case 19:
          Read.declared_throws = {"Ljava/lang/String;"};
          break;
        case 20:
          Read.declared_throws->push_back(Read.declared_throws->front());
          break;
        case 21:
          Input.back().superclass = Input.back().name;
          break;
        case 22:
          *Read.generic_signature += "^TT;";
          break;
        case 23:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 24:
          Call.instructions[0].registers.pop_back();
          break;
        case 25:
          Call.instructions[0].registers[3] = Call.instructions[0].registers[2];
          break;
        case 26:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 27:
          Read.access = {"static", "varargs"};
          Input[0].name = "Loutside/Client;";
          Call.reference.owner = Input[0].name;
          break;
        case 28:
          // Public direct seeds do not widen the existing package profile.
          Read.access = {"static", "varargs"};
          break;
        }
        Call.instructions[0].reference = Read.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        try {
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
        } catch (const std::runtime_error &) {
          // Malformed original declarations may fail before call planning.
        }
      }
}

namespace {
std::vector<Class> recursiveSelectorFactoryClasses(unsigned Kind,
                                                   unsigned Style,
                                                   unsigned Variance,
                                                   bool Range, bool Used,
                                                   bool Shadow, bool Alpha) {
  const bool ExternalTarget = Kind & 1, ExternalCarriers = Kind & 2;
  const bool Facade = Style == 1, Interface = Style == 2;
  auto Input = comparableSelectorCarrierClasses(
      ExternalTarget, ExternalCarriers, Facade, Range, false, Variance);
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[4].name};
  auto &Signature = *Make.generic_signature;
  const std::string Before = "(Lfixture/Box<TT;>;";
  Signature.replace(Signature.find(Before), Before.size(), "(");
  if (Alpha) {
    for (const auto &[From, To] :
         {std::pair{std::string("T:Ljava/lang/Object;"),
                    std::string("Element:Ljava/lang/Object;")},
          {"K::", "Key::"},
          {"TT;", "TElement;"},
          {"TK;", "TKey;"}}) {
      size_t At = 0;
      while ((At = Signature.find(From, At)) != std::string::npos) {
        Signature.replace(At, From.size(), To);
        At += To.size();
      }
    }
  }
  if (Shadow)
    Input[1].generic_signature =
        Alpha ? "<Element:Ljava/lang/Number;>Ljava/lang/Object;"
              : "<T:Ljava/lang/Number;>Ljava/lang/Object;";
  if (!ExternalTarget)
    Make.registers = 2;
  if (Interface)
    Input[1].access = {"public", "abstract", "interface"};
  if ((Style + unsigned(Range)) & 1)
    Input[5].access = {"public", "abstract", "interface"};
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  const unsigned First = Range ? 16 : 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.reference.returns = Used ? Ref.returns : "V";
  Call.registers = First + 1;
  Call.instructions = {
      op(0, Range ? "invoke-static/range" : "invoke-static", {First}, {}, Ref)};
  if (Used) {
    Call.instructions.push_back(op(1, "move-result-object", {0}));
    Call.instructions.push_back(op(2, "return-object", {0}));
  } else
    Call.instructions.push_back(op(1, "return-void"));
  Call.code_end = Call.instructions.size();
  auto Root = klass("Ljava/lang/Object;");
  Root.superclass.reset();
  Root.external = true;
  auto Number = klass("Ljava/lang/Number;");
  Number.access = {"public", "abstract"};
  Number.external = true;
  Input.push_back(Root);
  Input.push_back(Number);
  if (Interface)
    Input.erase(Input.begin() + 2, Input.begin() + 4);
  return Input;
}
} // namespace

TEST(MobileDalvikJava, RecursiveSelectorFactoriesKeepScopedElementAndKey) {
  for (unsigned Kind = 0; Kind < 4; ++Kind)
    for (unsigned Style = 0; Style < 3; ++Style)
      for (unsigned Variance = 0; Variance < 4; ++Variance)
        for (bool Range : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Kind, Style, Variance, Range, Route}));
            auto Input = recursiveSelectorFactoryClasses(
                Kind, Style, Variance, Range, Variance & 1, Variance & 2,
                (Style + Variance) & 1);
            const auto Original = Input[1].methods[0];
            const auto Owner = Input[1].generic_signature;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(
                Plans.erased_generic_invocations.contains(Original.reference));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            const auto &Retained = Classes.at(Original.reference.owner);
            EXPECT_EQ(Retained.generic_signature, Owner);
            EXPECT_EQ(Retained.methods[0].generic_signature,
                      Original.generic_signature);
            EXPECT_EQ(Retained.methods[0].declared_throws,
                      Original.declared_throws);
          }
}

TEST(MobileDalvikJava,
     RecursiveSelectorFactoriesRejectUnprovedContractsAndFrames) {
  for (unsigned Kind : {0u, 3u})
    for (unsigned Mutation = 0; Mutation < 36; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Kind, Mutation, Route}));
        auto Input = recursiveSelectorFactoryClasses(Kind, 0, 0, true, true,
                                                     false, false);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](std::string_view From, std::string_view To) {
          const auto At = Make.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Make.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Comparable<-TK;>", "Comparable<+TK;>");
          break;
        case 1:
          Replace("Comparable<-TK;>", "Comparable<-TT;>");
          break;
        case 2:
          Replace("Factory<-TT;+TK;>", "Factory<+TT;+TK;>");
          break;
        case 3:
          Replace("Factory<-TT;+TK;>", "Factory<-TT;-TK;>");
          break;
        case 4:
          Replace(")Lfixture/Box<TT;>;", ")Lfixture/Box<TK;>;");
          break;
        case 5:
          Replace(")Lfixture/Box<TT;>;", ")Lfixture/Box<+TT;>;");
          break;
        case 6:
          Replace("T:Ljava/lang/Object;K::",
                  "T:Ljava/lang/Object;Extra:Ljava/lang/Object;K::");
          break;
        case 7:
          Replace(")Lfixture/Box<TT;>;", ")Lfixture/Box<TMissing;>;");
          break;
        case 8:
          Input[4].generic_signature =
              "<R:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 9:
          Input[5].generic_signature =
              "<B:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 10:
          Input[6].methods[0].generic_signature = "(Ljava/lang/Object;)I";
          break;
        case 11:
          Input[6].access.erase("public");
          break;
        case 12:
          Make.access.insert("varargs");
          break;
        case 13:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 14:
          Make.access.insert("native");
          Make.instructions.clear();
          Make.registers = Make.code_end = 0;
          break;
        case 15:
          Make.access.insert("bridge");
          break;
        case 16:
          Make.access.insert("synthetic");
          break;
        case 17:
          Make.access = {"private", "static"};
          break;
        case 18:
          Make.access = {"protected", "static"};
          break;
        case 19:
          Make.access.insert("abstract");
          Make.instructions.clear();
          Make.registers = Make.code_end = 0;
          break;
        case 20:
          Input[1].enclosing_method =
              MethodRef{"Lfixture/Outer;", "call", {}, "V"};
          break;
        case 21:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 22:
          Make.reference.parameters[0] = "Ljava/lang/Object;";
          break;
        case 23:
          Make.reference.returns = "Ljava/lang/Object;";
          break;
        case 24:
          *Make.generic_signature += "^TT;";
          break;
        case 25:
          Replace("Factory<-TT;+TK;>", "Factory<-TT;+TT;>");
          break;
        case 26:
          Replace("K::Ljava/lang/Comparable<-TK;>;", "K:Ljava/lang/Object;");
          break;
        case 27:
          Replace("(Lfixture/Factory<-TT;+TK;>;",
                  "(Lfixture/Factory<-TT;+TK;>;Lfixture/Factory<-TT;+TK;>;");
          Make.reference.parameters.push_back(Input[4].name);
          break;
        case 28:
          Replace(")Lfixture/Box<TT;>;", ")V");
          Make.reference.returns = "V";
          break;
        case 29:
          Replace(")Lfixture/Box<TT;>;", ")Z");
          Make.reference.returns = "Z";
          break;
        case 30:
          Replace("Factory<-TT;+TK;>", "Factory<*+TK;>");
          break;
        case 31:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 32:
          Call.instructions[0].registers.clear();
          break;
        case 33:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 34:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 35:
          Call.reference.parameters = {"J"};
          break;
        }
        Call.instructions[0].reference = Make.reference;
        const auto Ref = Make.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        try {
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          if (Mutation <= 30)
            EXPECT_FALSE(Plans.erased_generic_invocations.contains(Ref));
          EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
        } catch (const std::runtime_error &) {
          // Invalid original declarations may fail before call planning.
        }
      }
}

namespace {
std::vector<Class> scopedInterfaceTokenClasses(unsigned Kind, unsigned Style,
                                               unsigned Mode,
                                               bool InterfaceBound,
                                               bool Context) {
  const bool SDK = Kind & 1, Generic = Kind < 4;
  const bool Numeric = Generic && (Kind & 2), Private = Style == 0;
  const bool Alpha = (Kind + Style + Mode) & 1;
  const std::string Formal = Alpha ? "Element" : "T";
  auto Input =
      boundedTokenElementClasses(SDK, Private, Style == 2, Alpha, Context,
                                 Mode & 1, Mode & 2, Style == 1 && (Mode & 2));
  if (Generic) {
    const std::string Bound =
        Numeric ? "Ljava/lang/Number;" : "Ljava/lang/Object;";
    Input[0].generic_signature =
        "<" + Formal + ":" + Bound + ">Ljava/lang/Object;";
    Input[1].generic_signature = "Lfixture/Factory<" + Bound + ">;";
  }
  if (InterfaceBound) {
    Input[2].access = {"public", "abstract", "interface"};
    auto &Signature = *Input[0].methods[0].generic_signature;
    const auto At = Signature.find(Formal + ":Lfixture/Bound;");
    Signature.replace(At, Formal.size() + 1, Formal + "::");
  }
  if (Mode & 1) {
    Input[3].name = "Ljava/lang/Class;";
    Input[3].external = true;
    for (auto &C : Input)
      for (auto &M : C.methods) {
        for (auto &P : M.reference.parameters)
          if (P == "Lfixture/Token;")
            P = Input[3].name;
        if (M.generic_signature) {
          size_t At = 0;
          while ((At = M.generic_signature->find("Lfixture/Token<", At)) !=
                 std::string::npos) {
            M.generic_signature->replace(At, 15, "Ljava/lang/Class<");
            At += 17;
          }
        }
        for (auto &I : M.instructions)
          if (auto *Ref = std::get_if<MethodRef>(&I.reference))
            for (auto &P : Ref->parameters)
              if (P == "Lfixture/Token;")
                P = Input[3].name;
      }
  }
  auto &Call = Private ? Input[0].methods.back() : Input[1].methods[0];
  if (Mode & 1) {
    Call.registers += 15;
    for (auto &I : Call.instructions)
      for (auto &R : I.registers)
        if (R)
          R += 15;
  }
  auto Entry = klass("Lfixture/Entry;");
  Entry.access = {"public", "abstract", "interface"};
  Entry.external = SDK;
  Input[0].interfaces.push_back(Entry.name);
  if (!Input[0].generic_signature)
    Input[0].generic_signature = "Ljava/lang/Object;";
  *Input[0].generic_signature += Entry.name;
  auto Number = klass("Ljava/lang/Number;");
  Number.access = {"public", "abstract"};
  Number.external = true;
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.superclass.reset();
  Object.external = true;
  Input.push_back(Entry);
  Input.push_back(Number);
  Input.push_back(Object);
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ScopedInterfaceTokensKeepIndependentOwnerAndMethodBindings) {
  for (unsigned Kind = 0; Kind < 6; ++Kind)
    for (unsigned Style = 0; Style < 3; ++Style)
      for (unsigned Mode = 0; Mode < 4; ++Mode)
        for (bool InterfaceBound : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            if ((Kind & 1) && Style == 0)
              continue;
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Kind, Style, Mode, InterfaceBound, Route}));
            auto Input = scopedInterfaceTokenClasses(
                Kind, Style, Mode, InterfaceBound, (Kind + Mode) & 1);
            const auto Original = Input[0].methods[0];
            const auto Owner = Input[0].generic_signature;
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
            if (Route)
              Classes = linkClasses(Input, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(
                Plans.erased_generic_invocations.contains(Original.reference));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            const auto &Retained = Classes.at(Original.reference.owner);
            EXPECT_EQ(Retained.generic_signature, Owner);
            EXPECT_EQ(Retained.methods[0].generic_signature,
                      Original.generic_signature);
            EXPECT_EQ(Retained.methods[0].access, Original.access);
          }
}

TEST(MobileDalvikJava,
     ScopedInterfaceTokensRejectOuterBindingsAndUnprovedCalls) {
  for (unsigned Kind : {0u, 1u})
    for (unsigned Mutation = 0; Mutation < 32; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        // An external concrete method legitimately has no supplied body.
        // The SDK concrete positives above retain that declaration contract.
        if (Kind && Mutation == 17)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Kind, Mutation, Route}));
        auto Input = scopedInterfaceTokenClasses(Kind, 2, 3, true, true);
        auto &Target = Input[0].methods[0];
        auto &Call = Input[1].methods[0];
        const std::string Formal = Kind ? "T" : "Element";
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Target.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Target.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Class<T" + Formal + ";>", "Class<+T" + Formal + ";>");
          break;
        case 1:
          Replace("Class<T" + Formal + ";>", "Class<*>");
          break;
        case 2:
          Replace("Class<T" + Formal + ";>", "Class<TMissing;>");
          break;
        case 3:
          Replace("<" + Formal + "::", "<Own::");
          Replace(")T" + Formal + ";", ")TOwn;");
          break;
        case 4:
          Replace("<" + Formal + "::",
                  "<Extra:Ljava/lang/Object;" + Formal + "::");
          break;
        case 5:
          Replace("<" + Formal + "::", "<" + Formal + ":");
          break;
        case 6:
          Input[2].generic_signature =
              "<X:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 7:
          Input[2].access.erase("public");
          break;
        case 8:
          Input[3].generic_signature.reset();
          break;
        case 9:
          Input[3].generic_signature = "<X:Lfixture/Bound;>Ljava/lang/Object;";
          break;
        case 10:
          Target.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 11:
          Target.access.insert("synthetic");
          break;
        case 12:
          Target.access.insert("native");
          break;
        case 13:
          Target.access.insert("bridge");
          break;
        case 14:
          Target.access.insert("varargs");
          break;
        case 15:
          Target.access = {"private", "abstract"};
          break;
        case 16:
          Target.access = {"protected", "abstract", "static"};
          break;
        case 17:
          Target.access.erase("abstract");
          break;
        case 18:
          Input[0].access.erase("abstract");
          break;
        case 19:
          Input[0].generic_signature =
              "<" + Formal +
              ":Lfixture/Missing;>Ljava/lang/Object;Lfixture/Entry;";
          break;
        case 20:
          Input[0].enclosing_method =
              MethodRef{"Lfixture/Outer;", "call", {}, "V"};
          break;
        case 21:
          Input[4].generic_signature =
              "<X:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 22:
          Replace(")T" + Formal + ";", ")Lfixture/Bound;");
          break;
        case 23:
          *Target.generic_signature += "^T" + Formal + ";";
          break;
        case 24:
          Target.reference.parameters[1] = "Ljava/lang/Object;";
          break;
        case 25:
          Target.reference.returns = "Ljava/lang/Object;";
          break;
        case 26:
          Call.instructions[0].opcode = "invoke-static/range";
          break;
        case 27:
          Call.instructions[0].registers.pop_back();
          break;
        case 28:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 29:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 30:
          Input[1].name = "Lother/Proxy;";
          for (auto &M : Input[1].methods)
            M.reference.owner = Input[1].name;
          break;
        case 31:
          Input.erase(Input.begin() + 2);
          break;
        }
        Call.instructions[0].reference = Target.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        try {
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
        } catch (const std::runtime_error &) {
          // Invalid original declarations may fail before call planning.
        }
      }
}

namespace {
std::vector<Class> reifiableContextThrowsClasses(bool External, unsigned Shape,
                                                 bool Range, bool Used,
                                                 bool Varargs, bool Alpha,
                                                 unsigned Throws) {
  auto Input =
      staticReifiableResultClasses(External, Range, false, false, !Used, Alpha);
  auto &Read = Input[0].methods[0];
  const std::string Formal = Alpha ? "Result" : "T";
  std::string Parameters;
  switch (Shape) {
  case 0:
    Read.reference.parameters = {"Ljava/lang/Object;",
                                 "Ljava/lang/reflect/Method;",
                                 "[Ljava/lang/Object;"};
    Parameters =
        "Ljava/lang/Object;Ljava/lang/reflect/Method;[Ljava/lang/Object;";
    break;
  case 1:
    Parameters = "Ljava/lang/String;Ljava/lang/Runnable;J[Ljava/lang/Class<*>;";
    break;
  case 2:
    Read.reference.parameters = {"Ljava/lang/Class;"};
    Parameters = "Ljava/lang/Class<*>;";
    break;
  case 3:
    Read.reference.parameters.clear();
    break;
  case 4:
    Read.reference.parameters = {"J", "D", "I"};
    Parameters = "JDI";
    break;
  case 5:
    Read.reference.parameters = {"[[Ljava/lang/Class;"};
    Parameters = "[[Ljava/lang/Class<*>;";
    break;
  case 6:
    Read.reference.parameters = {"[I"};
    Parameters = "[I";
    break;
  }
  Read.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(" + Parameters + ")T" + Formal + ";";
  if (Varargs)
    Read.access.insert("varargs");
  else
    Read.access.erase("varargs");
  Read.declared_throws =
      Throws == 0 ? std::vector<std::string>{"Lfixture/Failure;"}
      : Throws == 1
          ? std::vector<std::string>{"Ljava/lang/InterruptedException;",
                                     "Lfixture/Failure;"}
          : std::vector<std::string>{"Ljava/lang/Error;"};
  if (!External)
    Read.registers = Read.incomingWords() + 1;
  auto &Call = Input[1].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  Call.declared_throws = Read.declared_throws;
  const unsigned First = Range ? 16 : 1;
  Call.registers = First + Read.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          Words, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(1, "move-result-object", {0}));
    Call.instructions.push_back(op(2, "return-object", {0}));
  } else
    Call.instructions.push_back(op(1, "return-void"));
  Call.code_end = Call.instructions.size();
  auto Context = klass("Ljava/lang/reflect/Method;");
  Context.external = true;
  Input.push_back(Context);
  for (const auto &[Name, Parent] :
       {std::pair{"Ljava/lang/Throwable;", "Ljava/lang/Object;"},
        {"Ljava/lang/Exception;", "Ljava/lang/Throwable;"},
        {"Ljava/lang/RuntimeException;", "Ljava/lang/Exception;"},
        {"Ljava/lang/InterruptedException;", "Ljava/lang/Exception;"},
        {"Ljava/lang/Error;", "Ljava/lang/Throwable;"},
        {"Lfixture/Failure;", "Ljava/lang/RuntimeException;"}}) {
    auto C = klass(Name);
    C.superclass = Parent;
    C.external = true;
    Input.push_back(C);
  }
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ReifiableContextThrowsKeepResultOnlyFormalsAndOriginalCalls) {
  for (bool External : {false, true})
    for (unsigned Shape = 0; Shape < 7; ++Shape)
      for (unsigned Mode = 0; Mode < 4; ++Mode)
        for (unsigned Route = 0; Route < 3; ++Route) {
          const bool Array =
              Shape == 0 || Shape == 1 || Shape == 5 || Shape == 6;
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{External, Shape, Mode, Route}));
          auto Input = reifiableContextThrowsClasses(
              External, Shape, Mode & 1, Mode & 2,
              Array && ((Shape + Mode) & 1), (Shape + Mode) & 1,
              (Shape + Mode) % 3);
          const auto Original = Input[0].methods[0];
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(
              Plans.erased_generic_invocations.contains(Original.reference));
          EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          EXPECT_EQ(
              Classes.at(Original.reference.owner).methods[0].generic_signature,
              Original.generic_signature);
          EXPECT_EQ(
              Classes.at(Original.reference.owner).methods[0].declared_throws,
              Original.declared_throws);
        }
}

TEST(MobileDalvikJava,
     ReifiableContextThrowsRejectOpenTypesExceptionsAndFrames) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 30; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        if (External && Mutation == 17)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = reifiableContextThrowsClasses(External, 0, true, true,
                                                   true, false, 1);
        auto &Read = Input[0].methods[0];
        auto &Call = Input[1].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Read.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Read.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("<T:", "<Extra:Ljava/lang/Object;T:");
          break;
        case 1:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 2:
          Replace(")TT;", ")TMissing;");
          break;
        case 3:
          Replace(")TT;", ")Ljava/lang/Object;");
          break;
        case 4:
          Replace("[Ljava/lang/Object;", "[TT;");
          break;
        case 5:
          Replace("Ljava/lang/reflect/Method;", "Ljava/lang/Class<TT;>;");
          break;
        case 6:
          Read.declared_throws = {"Lfixture/Missing;"};
          break;
        case 7:
          Read.declared_throws = {"Ljava/lang/String;"};
          break;
        case 8:
          Read.declared_throws->push_back(Read.declared_throws->front());
          break;
        case 9:
          *Read.generic_signature += "^TT;";
          break;
        case 10:
          Input.back().superclass = Input.back().name;
          break;
        case 11:
          Read.access.insert("native");
          break;
        case 12:
          Read.access.insert("abstract");
          break;
        case 13:
          Read.access.insert("synthetic");
          break;
        case 14:
          Read.access.insert("bridge");
          break;
        case 15:
          Read.access = {"private", "static", "varargs"};
          break;
        case 16:
          Read.access = {"static", "varargs"};
          break;
        case 17:
          Read.instructions.clear();
          Read.registers = Read.code_end = 0;
          break;
        case 18:
          Input[0].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 19:
          Input[0].enclosing_method =
              MethodRef{"Lfixture/Outer;", "call", {}, "V"};
          break;
        case 20:
          Replace("[Ljava/lang/Object;", "Ljava/lang/Object;");
          Read.reference.parameters.back() = "Ljava/lang/Object;";
          break;
        case 21:
          Read.reference.returns = "Ljava/lang/String;";
          break;
        case 22:
          Read.reference.parameters[1] = "Ljava/lang/Object;";
          break;
        case 23:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 24:
          Call.instructions[0].registers.pop_back();
          break;
        case 25:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 26:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 27:
          Input.back().access.insert("interface");
          break;
        case 28:
          Input[0].access.insert("interface");
          break;
        case 29:
          Read.access = {"protected", "static", "varargs"};
          break;
        }
        Call.instructions[0].reference = Read.reference;
        const auto Original = Read;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        try {
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          if (Mutation == 3) {
            // An original Object result leaves the formal unused. Keep the
            // full closed input and exception contracts without inferring a
            // return relation from that now-unused variable.
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(Plans.erased_unused_formal_invocations.contains(
                Original.reference));
            EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            const auto &After = Classes.at(Original.reference.owner).methods[0];
            EXPECT_EQ(After.generic_signature, Original.generic_signature);
            EXPECT_EQ(After.access, Original.access);
            EXPECT_EQ(After.declared_throws, Original.declared_throws);
          } else {
            EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
          }
        } catch (const std::runtime_error &Error) {
          if (Mutation == 3)
            ADD_FAILURE() << Error.what();
          // Malformed original declarations may fail before call planning.
        }
      }
}

namespace {
std::vector<Class> wildcardCarrierNominalClasses(unsigned Kind, unsigned Shape,
                                                 unsigned Mode) {
  auto Input = erasedFactoryInvocationClasses(Kind & 1, false, true);
  Input[4].external = Input[5].external = Kind & 2;
  Input[4].generic_signature =
      "<I:Ljava/lang/Object;O:Ljava/lang/Object;>Ljava/lang/Object;";
  if (!(Shape & 1))
    Input[4].access = {"public"};
  Input[5].generic_signature.reset();
  const bool Reverse = Shape & 2, Range = Mode & 1, Used = Mode & 2;
  const bool Alpha = (Kind + Shape + Mode) & 1;
  const std::string Formal = Alpha ? "Element" : "T";
  const std::string Any = Mode & 2 ? "+Ljava/lang/Object;" : "*";
  if (Reverse) {
    Input[5].name = "Ljava/lang/invoke/SerializedLambda;";
    Input[5].external = true;
  }
  auto &Make = Input[1].methods[0];
  Make.reference.parameters = {Input[4].name};
  Make.reference.returns = Input[5].name;
  Make.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(Lfixture/Factory<" +
      (Reverse ? Any + "T" + Formal + ";" : "T" + Formal + ";" + Any) + ">;)" +
      Input[5].name;
  if (!Input[1].external)
    Make.registers = 2;
  auto Ref = Make.reference;
  if (Shape & 1)
    Ref.owner = Input[3].name;
  const unsigned First = Range ? 16 : 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.reference.returns = Used ? Ref.returns : "V";
  Call.registers = First + 1;
  Call.instructions = {
      op(0, Range ? "invoke-static/range" : "invoke-static", {First}, {}, Ref)};
  if (Used) {
    Call.instructions.push_back(op(1, "move-result-object", {0}));
    Call.instructions.push_back(op(2, "return-object", {0}));
  } else
    Call.instructions.push_back(op(1, "return-void"));
  Call.code_end = Call.instructions.size();
  return Input;
}
} // namespace

