namespace {
std::vector<Class> closedCovariantResultContextClasses(unsigned Kind,
                                                       unsigned Shape,
                                                       unsigned Mode) {
  const bool External = Kind & 1, Range = Mode & 1, Used = Mode & 2;
  const bool Alpha = (Kind + Shape + Mode) & 1;
  auto Input = reifiableContextThrowsClasses(External, 0, Range, Used,
                                             Shape == 1 && (Mode & 1), Alpha,
                                             (Shape + Mode) % 3);
  auto Annotation = klass("Ljava/lang/annotation/Annotation;");
  Annotation.external = true;
  Annotation.access = {"public", "abstract", "interface"};
  Input.push_back(Annotation);
  auto Element = klass("Ljava/lang/reflect/AnnotatedElement;");
  Element.external = true;
  Element.access = {"public", "abstract", "interface"};
  Input.push_back(Element);
  auto Token = klass("Lfixture/Token;");
  Token.external = Kind & 2;
  Token.generic_signature = "<C:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Token);
  auto &Read = Input[0].methods[0];
  std::string Parameters;
  switch (Shape) {
  case 0:
    Read.reference.parameters = {"Ljava/lang/reflect/AnnotatedElement;",
                                 "Ljava/lang/Class;", "Ljava/lang/String;"};
    Parameters = "Ljava/lang/reflect/AnnotatedElement;"
                 "Ljava/lang/Class<+Ljava/lang/annotation/Annotation;>;"
                 "Ljava/lang/String;";
    break;
  case 1:
    Read.reference.parameters = {"Ljava/lang/Object;", "Ljava/lang/Class;",
                                 "[Ljava/lang/Object;"};
    Parameters = "Ljava/lang/Object;"
                 "Ljava/lang/Class<+Ljava/lang/annotation/Annotation;>;"
                 "[Ljava/lang/Object;";
    break;
  case 2:
    Read.reference.parameters = {"Lfixture/Token;"};
    Parameters = "Lfixture/Token<+Ljava/lang/String;>;";
    break;
  case 3:
    Read.reference.parameters = {"Ljava/lang/Class;", "Ljava/lang/Class;", "J"};
    Parameters = "Ljava/lang/Class<+Ljava/lang/annotation/Annotation;>;"
                 "Ljava/lang/Class<+Ljava/lang/String;>;J";
    break;
  }
  const std::string Formal = Alpha ? "Result" : "T";
  Read.generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>(" + Parameters + ")T" + Formal + ";";
  if ((Kind + Shape + Mode) % 4 == 0)
    Read.declared_throws.reset();
  if (!External)
    Read.registers = Read.incomingWords() + 1;
  auto &Call = Input[1].methods[0];
  Call.reference.parameters = Read.reference.parameters;
  Call.declared_throws = Read.declared_throws;
  const unsigned First = Range ? 16 : 1;
  Call.registers = First + Read.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          Words, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(1, "move-result-object", {0}));
    Call.instructions.push_back(op(2, "return-object", {0}));
  } else
    Call.instructions.push_back(op(1, "return-void"));
  Call.code_end = Call.instructions.size();
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ClosedCovariantResultContextsRetainIndependentResultsAndExceptions) {
  for (unsigned Kind = 0; Kind < 4; ++Kind)
    for (unsigned Shape = 0; Shape < 4; ++Shape)
      for (unsigned Mode = 0; Mode < 4; ++Mode)
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(
              ::testing::PrintToString(std::tuple{Kind, Shape, Mode, Route}));
          auto Input = closedCovariantResultContextClasses(Kind, Shape, Mode);
          const auto Original = Input[0].methods[0];
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          ClassMap Classes;
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
          if (Route)
            Classes = linkClasses(Input, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(
              Plans.erased_generic_invocations.contains(Original.reference));
          if (Original.declared_throws && !Original.declared_throws->empty())
            EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          EXPECT_FALSE(R.getArray("class_source_bindings"));
          const auto &After = Classes.at(Original.reference.owner).methods[0];
          EXPECT_EQ(After.generic_signature, Original.generic_signature);
          EXPECT_EQ(After.declared_throws, Original.declared_throws);
          EXPECT_EQ(After.access, Original.access);
        }
}

