          Replace(")TT;", ")Ljava/lang/Object;");
          break;
        case 3:
          Replace("(TT;)", "(TT;TT;)");
          break;
        case 4:
          Replace("(TT;)", "([TT;)");
          Target.reference.parameters[0] = "[Ljava/lang/Object;";
          Call.reference.parameters = Target.reference.parameters;
          break;
        case 5:
          Replace(")TT;", ")[TT;");
          Target.reference.returns = "[Ljava/lang/Object;";
          Call.reference.returns = Target.reference.returns;
          break;
