TEST(MobileDalvikJava,
     BinaryCarrierArrayTransfersRejectIncompleteBindingsAndFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 39; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        if (SDK && Mutation == 36)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = binaryCarrierArrayTransferClasses(SDK, false, true, false,
                                                       false, 0, 3);
        auto &Target = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Target.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Target.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("A:Ljava/lang/Object;", "A:Ljava/lang/Number;");
          break;
        case 1:
          Replace("<A:", "<U:Ljava/lang/Object;A:");
          break;
        case 2:
          Replace("[TA;)", "[TU;)");
          break;
        case 3:
          Replace("[TA;)", "[[TA;)");
          Target.reference.parameters[1] = "[[Ljava/lang/Object;";
          Call.reference.parameters = Target.reference.parameters;
          break;
        case 4:
          Replace("(Lfixture/Box<TA;TB;>;", "(Lfixture/Box<+TA;TB;>;");
          break;
        case 5:
          Replace(")Lfixture/Box<TA;TB;>;", ")Lfixture/Box<TB;TA;>;");
          break;
        case 6:
          Replace("(Lfixture/Box<TA;TB;>;", "(Lfixture/Box<TA;TA;>;");
          break;
        case 7:
          Replace(")Lfixture/Box<TA;TB;>;", ")Lfixture/Box<TA;TA;>;");
          break;
        case 8:
          Replace(")Lfixture/Box<TA;TB;>;", ")Lfixture/Box<TU;TB;>;");
          break;
        case 9:
          Replace("(Lfixture/Box<", "(Lmissing/Other<");
          break;
        case 10:
          Replace(")Lfixture/Box<", ")Lmissing/Other<");
          break;
        case 11:
          Replace("(Lfixture/Box<TA;TB;>;",
                  "(Lfixture/Box<Ljava/lang/Object;TB;>;");
          break;
        case 12:
          Replace("(Lfixture/Box<TA;TB;>;", "(Lfixture/Box;");
          break;
        case 13:
          Target.access = {"private", "static", "varargs"};
          break;
        case 14:
          Target.access = {"protected", "static", "varargs"};
          break;
        case 15:
          Target.access = {"static", "varargs"};
          break;
        case 16:
          Target.access.erase("static");
          break;
        case 17:
          Target.access.insert("native");
          break;
        case 18:
          Target.access.insert("abstract");
          break;
        case 19:
          Target.access.insert("synthetic");
          break;
        case 20:
          Target.access.insert("bridge");
          break;
        case 21:
          Input[1].access.insert("interface");
          break;
        case 22:
          Input[1].access.erase("public");
          break;
        case 23:
          Input[1].generic_signature =
              "<U:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 24:
          Input[1].enclosing = "Lmissing/Outer;";
          break;
        case 25:
          Target.declared_throws = {"Ljava/lang/IllegalArgumentException;"};
          break;
        case 26:
          *Target.generic_signature += "^TA;";
          break;
        case 27:
          Input.erase(Input.begin() + 2);
          break;
        case 28:
          Input[2].generic_signature =
              "<X:Ljava/lang/Object;Y:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 29:
          Input[2].generic_signature =
              "<X:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 30:
          Input[2].access.erase("public");
          break;
        case 31:
          Call.instructions[0].registers.pop_back();
          break;
        case 32:
          Call.instructions[0].registers.push_back(1);
          break;
        case 33:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 34:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 35:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 36:
          Target.instructions.clear();
          Target.registers = Target.code_end = 0;
          break;
        case 37:
          Target.reference.parameters[1] = "[Ljava/lang/Number;";
          break;
        case 38:
          Target.reference.returns = "Ljava/lang/Object;";
          break;
        }
        Call.instructions[0].reference = Target.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        try {
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
        } catch (const std::runtime_error &) {
          // Invalid original declarations may fail before invocation planning.
        }
      }
}

namespace {
std::vector<Class> scalarArrayFactoryClasses(bool SDK, unsigned Kind,
                                             bool Varargs, bool Alpha,
                                             bool Element, bool Facade,
                                             unsigned Mode) {
  const std::string T = Alpha ? "Element" : "T";
  std::vector<std::string> Parameters;
  std::string Prefix;
  if (Kind == 2) {
    Parameters.push_back("Ljava/lang/String;");
    Prefix += "Ljava/lang/String;";
  }
  Parameters.push_back("Z");
  Prefix += "Z";
  if (Kind) {
    Parameters.push_back("J");
    Prefix += "J";
  }
  if (Kind == 3) {
    Parameters.push_back("D");
    Prefix += "D";
  }
  Parameters.push_back("[Ljava/lang/Object;");
  const std::string Return = Element ? "Ljava/lang/Object;" : "Lfixture/Box;";
  auto Target =
      method("create", Parameters, Return, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.reference.owner = "Lfixture/Provider;";
  Target.registers = Target.incomingWords() + 1;
  Target.generic_signature =
      "<" + T + ":Ljava/lang/Object;>(" + Prefix + "[T" + T + ";)" +
      (Element ? "T" + T + ";" : "Lfixture/Box<T" + T + ";>;");
  if (Varargs)
    Target.access.insert("varargs");
  auto Invoked = Target.reference;
  if (Facade)
    Invoked.owner = "Lfixture/Facade;";
  const bool Range = Mode & 1, Used = Mode & 2;
  const unsigned First = Range ? 16 : 1;
  std::vector<unsigned> Words;
  for (unsigned I = 0; I < Target.incomingWords(); ++I)
    Words.push_back(First + I);
  std::vector<Instruction> Code{op(
      0, Range ? "invoke-static/range" : "invoke-static", Words, {}, Invoked)};
  if (Used) {
    Code.push_back(op(1, "move-result-object", {0}));
    Code.push_back(op(2, "return-object", {0}));
  } else
    Code.push_back(op(1, "return-void"));
  auto Call = method("call", Parameters, Used ? Return : "V",
                     First + Words.size(), Code);
  if (Alpha)
    for (auto *M : {&Target, &Call}) {
      M->registers += 5;
      for (auto &I : M->instructions)
        for (auto &R : I.registers)
          R += 5;
    }
  auto Provider = klass(Target.reference.owner, {Target});
  Provider.external = SDK;
  if (SDK) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Box = klass("Lfixture/Box;");
  Box.external = true;
  Box.generic_signature = "<X:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Number = klass("Ljava/lang/Number;");
  Number.external = true;
  Number.access = {"public", "abstract"};
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  auto Alias = klass("Lfixture/Facade;");
  Alias.external = true;
  Alias.superclass = Provider.name;
  return {
      klass("Lfixture/Core;", {Call}), Provider, Box, Number, String, Alias};
}
} // namespace

