namespace {
std::vector<Class> reifiableSeedContextClasses(bool SDK, unsigned Arity,
                                               unsigned Rank, unsigned Seed,
                                               bool Alpha, bool ArrayResult,
                                               unsigned Mode) {
  const std::string T = Alpha ? "Element" : "T";
  const std::string Arrays(Rank, '[');
  const std::string Context = Arrays + "Lfixture/Context;";
  const std::string ContextSignature =
      Arrays + "Lfixture/Context<" + std::string(Arity, '*') + ">;";
  std::vector<std::pair<std::string, std::string>> Inputs{
      {Context, ContextSignature},
      {"Z", "Z"},
      {"Lfixture/Config;", "Lfixture/Config;"}};
  Inputs.insert(Inputs.begin() + Seed, {"Ljava/lang/Object;", "T" + T + ";"});
  std::vector<std::string> Parameters;
  std::string ParameterSignature;
  for (const auto &[Erasure, Signature] : Inputs) {
    Parameters.push_back(Erasure);
    ParameterSignature += Signature;
  }
  const std::string Result =
      ArrayResult ? "[Ljava/lang/Object;" : "Ljava/lang/Object;";
  auto Target =
      method("read", Parameters, Result, 5,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Target.reference.owner = "Lfixture/Provider;";
  Target.generic_signature = "<" + T + ":Ljava/lang/Object;>(" +
                             ParameterSignature + ")" +
                             (ArrayResult ? "[" : "") + "T" + T + ";";
  const bool Range = Mode & 1, Used = Mode & 2;
  const unsigned First = Range ? 16 : 1;
  std::vector<unsigned> Words;
  for (unsigned I = 0; I < Parameters.size(); ++I)
    Words.push_back(First + I);
  std::vector<Instruction> Code{
      op(0, Range ? "invoke-static/range" : "invoke-static", Words, {},
         Target.reference)};
  if (Used) {
    Code.push_back(op(1, "move-result-object", {0}));
    Code.push_back(op(2, "return-object", {0}));
  } else
    Code.push_back(op(1, "return-void"));
  auto Call = method("call", Parameters, Used ? Result : "V",
                     First + Parameters.size(), Code);
  if (Alpha)
    for (auto *M : {&Target, &Call}) {
      M->registers += 5;
      for (auto &I : M->instructions)
        for (auto &R : I.registers)
          R += 5;
    }
  auto Provider = klass(Target.reference.owner, {Target});
  Provider.external = SDK;
  if (SDK) {
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Carrier = klass("Lfixture/Context;");
  Carrier.external = true;
  Carrier.generic_signature =
      Arity == 1
          ? "<A:Ljava/lang/Object;>Ljava/lang/Object;"
          : "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Config = klass("Lfixture/Config;");
  Config.external = true;
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  auto Number = klass("Ljava/lang/Number;");
  Number.external = true;
  Number.access = {"public", "abstract"};
  return {klass("Lfixture/Core;", {Call}),
          Provider,
          Carrier,
          Config,
          Object,
          Number};
}
} // namespace

