TEST(MobileDalvikJava, ClosedInvariantSeedsKeepCompleteNominalContexts) {
  for (bool SDK : {false, true})
    for (bool Interface : {false, true})
      for (unsigned Seed = 0; Seed < 4; ++Seed)
        for (bool Alpha : {false, true})
          for (bool ArrayResult : {false, true})
            for (unsigned Mode = 0; Mode < 4; ++Mode)
              for (bool ObjectArgument : {false, true})
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Interface, Seed, Alpha, ArrayResult, Mode,
                                 ObjectArgument, Route}));
                  auto Input = closedInvariantSeedClasses(SDK, Interface, Seed,
                                                          Alpha, ArrayResult,
                                                          Mode, ObjectArgument);
                  const auto Original = Input[1].methods[0];
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(Plans.erased_generic_invocations.contains(
                      Original.reference));
                  const auto Report = recoverJava(Classes, B);
                  EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                  EXPECT_FALSE(
                      Report.getArray("generic_signature_projections"));
                  EXPECT_FALSE(Report.getArray("class_source_bindings"));
                  const auto &After =
                      Classes.at(Original.reference.owner).methods[0];
                  EXPECT_EQ(After.generic_signature,
                            Original.generic_signature);
                  EXPECT_EQ(After.declared_throws, Original.declared_throws);
                  EXPECT_EQ(After.access, Original.access);
                }
}

