namespace {
std::vector<Class> uncheckedConstructorGetterClasses(const std::string &Type,
                                                     bool Guarded, bool Range,
                                                     bool SDK, unsigned Kind) {
  auto Input = constructorParameterReadClasses(Type, Guarded, Range, false);
  auto &Getter = Input[1].methods[0];
  Getter.declared_throws =
      Kind == 3   ? std::vector<std::string>{"Ljava/lang/RuntimeException;"}
      : Kind == 4 ? std::vector<std::string>{"Ljava/lang/Error;"}
      : Kind == 2 ? std::vector<std::string>{"Lfixture/LeafFailure;",
                                             "Lfixture/FatalFailure;"}
                  : std::vector<std::string>{"Lfixture/LeafFailure;"};
  Input[1].external = Input[2].external = SDK;
  if (SDK) {
    Getter.instructions.clear();
    Getter.registers = Getter.code_end = 0;
  }
  auto ObjectInit = method("<init>", {}, "V", 0, {});
  ObjectInit.access = {"public", "constructor"};
  auto Object = klass("Ljava/lang/Object;", {ObjectInit});
  Object.external = true;
  Object.superclass.reset();
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.external = true;
  Exception.superclass = Throwable.name;
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.external = true;
  Runtime.superclass = Exception.name;
  auto Error = klass("Ljava/lang/Error;");
  Error.external = true;
  Error.superclass = Throwable.name;
  auto Mid = klass("Lfixture/MidFailure;");
  Mid.external = true;
  Mid.superclass = Kind == 1 ? Error.name : Runtime.name;
  auto Leaf = klass("Lfixture/LeafFailure;");
  Leaf.external = true;
  Leaf.superclass = Mid.name;
  auto Fatal = klass("Lfixture/FatalFailure;");
  Fatal.external = true;
  Fatal.superclass = Error.name;
  auto Checked = klass("Lfixture/CheckedFailure;");
  Checked.external = true;
  Checked.superclass = Exception.name;
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  Input.insert(Input.end(), {Object, Throwable, Exception, Runtime, Error, Mid,
                             Leaf, Fatal, Checked, String});
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     UncheckedConstructorGettersRetainCanonicalThrowsAndOrigins) {
  for (const std::string Type : {"I", "J", "Ljava/lang/Object;"})
    for (bool Guarded : {false, true})
      for (bool Range : {false, true})
        for (bool SDK : {false, true})
          for (unsigned Kind = 0; Kind < 5; ++Kind)
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{Type, Guarded, Range, SDK, Kind, Route}));
              auto Input = uncheckedConstructorGetterClasses(Type, Guarded,
                                                             Range, SDK, Kind);
              const auto Original = Input[1].methods[0];
              const auto Constructor = Input[0].methods[1].reference;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(validatedUncheckedDeclaredThrows(Original, Plans));
              EXPECT_TRUE(Plans.constructor_delegations.contains(Constructor));
              const auto Report = recoverJava(Classes, B);
              EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(Report.getInteger("minimum_java_release"), 25);
              EXPECT_FALSE(Report.getArray("generic_signature_projections"));
              const auto &After =
                  Classes.at(Original.reference.owner).methods[0];
              EXPECT_EQ(After.declared_throws, Original.declared_throws);
              EXPECT_EQ(After.generic_signature, Original.generic_signature);
              EXPECT_EQ(After.access, Original.access);
            }
}

