TEST(MobileDalvikJava,
     UncheckedWildcardCarrierNominalsRejectCheckedOpenAndChangedContracts) {
  for (unsigned Kind : {0u, 3u})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Kind, Mutation, Route}));
        auto Input = uncheckedWildcardCarrierNominalClasses(Kind, 0, 3, 1);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        const std::string Formal = Kind ? "T" : "Element";
        const auto Leaf = Input.size() - 3;
        switch (Mutation) {
        case 0:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 1:
          Input[Leaf].superclass = "Ljava/lang/Exception;";
          break;
        case 2:
          Make.declared_throws = {"Ljava/lang/Throwable;"};
          break;
        case 3:
          Make.declared_throws = {"Ljava/lang/String;"};
          break;
        case 4:
          Make.declared_throws = {"Lfixture/Missing;"};
          break;
        case 5:
          Make.declared_throws->push_back(Make.declared_throws->front());
          break;
        case 6:
          Input[Leaf].superclass = Input[Leaf].name;
          break;
        case 7:
          *Make.generic_signature += "^T" + Formal + ";";
          break;
        case 8:
          Input[Leaf].superclass = "Lfixture/Missing;";
          break;
        case 9:
          Make.access.insert("native");
          break;
        case 10:
          Make.access.insert("synthetic");
          break;
        case 11:
          Make.access.insert("varargs");
          break;
        case 12:
          Input[1].generic_signature =
              "<Owner:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 13:
          Make.reference.returns = "Ljava/lang/String;";
          break;
        case 14:
          Make.reference.parameters[0] = "Ljava/lang/Object;";
          break;
        case 15:
          Call.instructions[0].opcode = "invoke-virtual";
          break;
        case 16:
          Call.instructions[0].registers.clear();
          break;
        case 17:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 18:
          Make.access = {"private", "static"};
          break;
        case 19:
          Make.access = {"protected", "static"};
          break;
        }
        Call.instructions[0].reference = Make.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> arrayMappedCarrierClasses(bool SDK, bool Range, bool Facade,
                                             bool CallbackFirst, bool Alpha,
                                             unsigned Scalars, bool Used) {
  auto Input =
      invariantMappedCarrierClasses(SDK, 0, Range, Facade, CallbackFirst, Alpha,
                                    Scalars ? Scalars - 1 : 0, Used);
  auto &Target = Input[1].methods[0];
  auto &Call = Input[0].methods[0];
  const std::string Seed = Alpha ? "Seed" : "I";
  const std::string Producer = "Lfixture/Callback<T" + Seed + ";>;";
  const auto At = Target.generic_signature->find(Producer);
  Target.generic_signature->replace(At, Producer.size(), "[T" + Seed + ";");
  const unsigned Slot = CallbackFirst ? 1 : 0;
  Target.reference.parameters[Slot] = "[Ljava/lang/Object;";
  Call.reference.parameters[Slot] = "[Ljava/lang/Object;";
  auto &Ref = std::get<MethodRef>(Call.instructions[0].reference);
  Ref.parameters = Target.reference.parameters;
  if (!Scalars) {
    const auto Tail = Target.generic_signature->find("Z)");
    Target.generic_signature->erase(Tail, 1);
    Target.reference.parameters.resize(2);
    Call.reference.parameters.resize(2);
    Ref.parameters.resize(2);
    Call.instructions[0].registers.resize(2);
    Call.registers = (Range ? 16 : 1) + 2;
    if (!SDK)
      Target.registers = 3;
  }
  if (Alpha) {
    auto Parent = klass("Lfixture/Parent;");
    Parent.external = true;
    Input[1].superclass = Parent.name;
    Input.push_back(Parent);
  }
  if (SDK != Facade)
    for (auto &C : Input)
      if (C.name == "Lfixture/Box;")
        C.access = {"public", "abstract", "interface"};
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ArrayMappedCarriersKeepOriginalComponentsAndMappedResults) {
  for (bool SDK : {false, true})
    for (bool Facade : {false, true})
      for (bool CallbackFirst : {false, true})
        for (bool Alpha : {false, true})
          for (unsigned Scalars : {0u, 3u})
            for (unsigned Mode = 0; Mode < 4; ++Mode)
              for (unsigned Route = 0; Route < 3; ++Route) {
                const bool Range = Mode & 1, Used = Mode & 2;
                if (Scalars == 3 && !Range)
                  continue;
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    SDK, Facade, CallbackFirst, Alpha, Scalars, Mode, Route}));
                auto Input = arrayMappedCarrierClasses(
                    SDK, Range, Facade, CallbackFirst, Alpha, Scalars, Used);
                const auto Original = Input[1].methods[0];
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                const auto Plans = validateGenericSignatures(Classes, B);
                EXPECT_TRUE(Plans.erased_generic_invocations.contains(
                    Original.reference));
                const auto Report = recoverJava(Classes, B);
                EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(Report.getInteger("minimum_java_release").value_or(8),
                          8);
                EXPECT_FALSE(Report.getArray("generic_signature_projections"));
                EXPECT_FALSE(Report.getArray("class_source_bindings"));
                const auto &After =
                    Classes.at(Original.reference.owner).methods[0];
                EXPECT_EQ(After.reference, Original.reference);
                EXPECT_EQ(After.generic_signature, Original.generic_signature);
                EXPECT_EQ(After.declared_throws, Original.declared_throws);
                EXPECT_EQ(After.access, Original.access);
              }
}

TEST(MobileDalvikJava,
     ArrayMappedCarriersRejectCrossedResultsScopesAndArrayFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 31; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        if (SDK && Mutation == 28)
          continue;
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            arrayMappedCarrierClasses(SDK, true, false, false, false, 0, true);
        auto &Target = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Target.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Target.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("<I:", "<Unused:Ljava/lang/Object;I:");
          break;
        case 1:
          Replace("I:Ljava/lang/Object;", "I:Ljava/lang/Number;");
          break;
        case 2:
          Replace("[TI;", "[TMissing;");
          break;
        case 3:
          Replace("[TI;", "[[TI;");
          break;
        case 4:
          Replace("Transform<-TI;+TO;>", "Transform<+TI;+TO;>");
          break;
        case 5:
          Replace("Transform<-TI;+TO;>", "Transform<-TI;-TO;>");
          break;
        case 6:
          Replace("Transform<-TI;+TO;>", "Transform<-TI;+TI;>");
          break;
        case 7:
          Replace("Box<TO;>", "Box<TI;>");
          break;
        case 8:
          Replace("Box<TO;>", "Box<+TO;>");
          break;
        case 9:
          Target.reference.parameters[0] = "Ljava/lang/Object;";
          break;
        case 10:
          Target.reference.returns = "Ljava/lang/Object;";
          break;
        case 11:
          for (auto &C : Input)
            if (C.name == "Lfixture/Transform;")
              C.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 12:
          for (auto &C : Input)
            if (C.name == "Lfixture/Box;")
              C.generic_signature = "<T:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 13:
          Target.access.insert("native");
          break;
        case 14:
          Target.access.insert("synthetic");
          break;
        case 15:
          Target.access.insert("varargs");
          break;
        case 16:
          Target.access = {"private", "static"};
          break;
        case 17:
          Target.access = {"protected", "static"};
          break;
        case 18:
          Target.access.erase("static");
          break;
        case 19:
          Input[1].access = {"public", "abstract", "interface"};
          break;
        case 20:
          Input[1].generic_signature =
              "<Owner:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 21:
          Target.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 22:
          *Target.generic_signature += "^TI;";
          break;
        case 23:
          Call.instructions[0].registers.clear();
          break;
        case 24:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 25:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 26:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 27:
          Replace("Box<TO;>", "Box<TMissing;>");
          break;
        case 28:
          Target.instructions.clear();
          Target.registers = Target.code_end = 0;
          break;
        case 29:
          Replace("Lfixture/Transform<-TI;+TO;>;", "[TO;");
          Target.reference.parameters[1] = "[Ljava/lang/Object;";
          break;
        case 30:
          Replace("Transform<-TI;+TO;>", "Transform");
          break;
        }
        Call.instructions[0].reference = Target.reference;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> wildcardSuperclassClasses(bool SDK, bool Interface,
                                             unsigned Arity, bool Swapped,
                                             bool Range, bool Alpha,
                                             unsigned Kind) {
  auto Input = rawNominalSuperclassClasses(SDK, Interface, Arity, Range, Alpha);
  const std::string Formal = Alpha ? "Left" : "B";
  std::string Arguments;
  for (unsigned I = 0; I < Arity; ++I)
    Arguments += Kind == 1         ? "+Ljava/lang/String;"
                 : Kind == 2       ? "-Ljava/lang/String;"
                 : Kind == 3 && !I ? "Ljava/lang/String;"
                                   : "*";
  const std::string Carrier = "Lfixture/Carrier<" + Arguments + ">;";
  const std::string Variable = "T" + Formal + ";";
  Input[1].generic_signature =
      "<" + Formal + ":Ljava/lang/Object;>Lfixture/Base<" +
      (Swapped ? Carrier + Variable : Variable + Carrier) + ">;";
  auto &Caller = Input[1].methods[0];
  Caller.reference.parameters[Swapped ? 0 : 1] = Input[2].name;
  Caller.reference.parameters[Swapped ? 1 : 0] = "Ljava/lang/Object;";
  Caller.generic_signature =
      "(" + (Swapped ? Carrier + Variable : Variable + Carrier) +
      "Ljava/lang/reflect/Type;Lfixture/Config;)V";
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  Input.push_back(String);
  auto Number = klass("Ljava/lang/Number;");
  Number.external = true;
  Input.push_back(Number);
  if (Kind == 4) {
    auto &Header = *Input[2].generic_signature;
    const auto At = Header.find("P0:Ljava/lang/Object;");
    Header.replace(At, std::string("P0:Ljava/lang/Object;").size(),
                   "P0:Ljava/lang/Number;");
  }
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     WildcardSuperclassConstructorsKeepClosedSlotsAndScopedOrigins) {
  for (bool SDK : {false, true})
    for (bool Interface : {false, true})
      for (unsigned Arity = 1; Arity <= 3; ++Arity)
        for (bool Swapped : {false, true})
          for (bool Range : {false, true})
            for (bool Alpha : {false, true})
              for (unsigned Kind = 0; Kind < 5; ++Kind)
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Interface, Arity, Swapped, Range, Alpha,
                                 Kind, Route}));
                  auto Input = wildcardSuperclassClasses(
                      SDK, Interface, Arity, Swapped, Range, Alpha, Kind);
                  const auto Caller = Input[1].methods[0];
                  const auto Target = Input[0].methods[0];
                  const auto Header = Input[1].generic_signature;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  if (Route)
                    Classes = linkClasses(Input, B);
                  else
                    for (const auto &C : Input)
                      Classes.emplace(C.name, C);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  EXPECT_TRUE(Plans.superclass_calls.contains(
                      {Caller.reference, Target.reference}));
                  const auto Report = recoverJava(Classes, B);
                  EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(
                      Report.getInteger("minimum_java_release").value_or(8), 8);
                  EXPECT_FALSE(
                      Report.getArray("generic_signature_projections"));
                  EXPECT_EQ(
                      Classes.at(Caller.reference.owner).generic_signature,
                      Header);
                  const auto &After =
                      Classes.at(Caller.reference.owner).methods[0];
                  EXPECT_EQ(After.reference, Caller.reference);
                  EXPECT_EQ(After.generic_signature, Caller.generic_signature);
                  EXPECT_EQ(After.access, Caller.access);
                  EXPECT_EQ(Classes.at(Target.reference.owner)
                                .methods[0]
                                .generic_signature,
                            Target.generic_signature);
                }
}

