          Input[1].generic_signature = "<B:Ljava/lang/Object;>Lfixture/"
                                       "Base<TMissing;Lfixture/Carrier<**>;>;";
          break;
        case 1:
          Caller.generic_signature =
              "<C:Ljava/lang/Object;>(TC;Lfixture/Carrier<**>;Ljava/lang/"
              "reflect/Type;Lfixture/Config;)V";
          break;
        case 2:
          Input[1].generic_signature =
              "<B:Ljava/lang/Object;>Lfixture/Base<TB;Lfixture/Carrier<*>;>;";
          break;
        case 3:
          Input[1].generic_signature =
              "<B:Ljava/lang/Object;>Lfixture/Base<TB;Lfixture/Missing;>;";
          break;
        case 4:
          Caller.generic_signature = "(TB;Lfixture/Carrier<TMissing;*>;Ljava/"
                                     "lang/reflect/Type;Lfixture/Config;)V";
          break;
        case 5:
          Target.generic_signature =
              "<C:Ljava/lang/Object;>(TC;TB;Lfixture/Config;)V";
          break;
        case 6:
          Target.reference.parameters[0] = "Lfixture/Carrier;";
          Caller.instructions[0].reference = Target.reference;
          break;
        case 7:
          Target.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 8:
          *Target.generic_signature += "^Ljava/lang/RuntimeException;";
          break;
        case 9:
          Target.access = {"private", "constructor"};
          break;
        case 10:
          Target.access.insert("varargs");
