          Caller.instructions[0].registers[0] = 1;
          break;
        case 14:
          Caller.instructions[0].registers[2] = Caller.registers;
          break;
        case 15:
          Caller.instructions[0].opcode = "invoke-virtual";
          break;
        case 16:
          Input[1].generic_signature =
              "<B:Ljava/lang/Number;>Lfixture/Base<TB;Lfixture/Carrier<**>;>;";
