namespace {
std::vector<Class> mappedCollectorCarrierClasses(unsigned Kind, unsigned Shape,
                                                 unsigned Mode,
                                                 unsigned Style) {
  auto Input = erasedFactoryInvocationClasses(Kind & 1, false, true);
  Input[4].external = Input[5].external = Kind & 2;
  Input[4].generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[5].generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/"
                               "Object;C:Ljava/lang/Object;>Ljava/lang/Object;";
  Input[4].access =
      Shape & 1 ? Access{"public", "abstract", "interface"} : Access{"public"};
  Input[5].access =
      Shape & 2 ? Access{"public", "abstract", "interface"} : Access{"public"};
  const bool Alpha = (Kind + Mode) & 1, Swapped = Mode & 4, Range = Mode & 1,
             Used = Mode & 2;
  std::vector<std::string> Names =
      Alpha ? std::vector<std::string>{"Input", "Mapped", "State", "Value"}
            : std::vector<std::string>{"T", "U", "A", "R"};
  const auto Variable = [](const std::string &N) { return "T" + N + ";"; };
  const auto T = Variable(Names[0]), U = Variable(Names[1]),
             A = Variable(Names[2]), R = Variable(Names[3]);
  if (Shape & 1)
    std::rotate(Names.begin(), Names.begin() + 1, Names.end());
  std::string Formals = "<";
  for (const auto &N : Names)
    Formals += N + ":Ljava/lang/Object;";
  Formals += ">";
  const std::string Mapper = "Lfixture/Factory<" +
                             std::string(Style & 1 ? "" : "-") + T +
                             (Style & 2 ? "" : "+") + U + ">;";
  const std::string Downstream =
      "Lfixture/Box<" + std::string(Shape & 1 ? "" : "-") + U + A + R + ">;";
  auto &Make = Input[1].methods[0];
  Make.reference.parameters =
      Swapped ? std::vector<std::string>{Input[5].name, Input[4].name}
              : std::vector<std::string>{Input[4].name, Input[5].name};
  Make.generic_signature =
      Formals + "(" + (Swapped ? Downstream + Mapper : Mapper + Downstream) +
      ")Lfixture/Box<" + T + (Shape & 2 ? "+Ljava/lang/Object;" : "*") + R +
      ">;";
  if (!Input[1].external)
    Make.registers = 3;
  auto Ref = Make.reference;
  if ((Kind + Shape + Mode) & 1)
    Ref.owner = Input[3].name;
  const unsigned First = Range ? 16 : 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.reference.returns = Used ? Ref.returns : "V";
  Call.registers = First + 2;
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          {First, First + 1}, {}, Ref)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
  } else
    Call.instructions.push_back(op(3, "return-void"));
  Call.code_end = Used ? 5 : 4;
  if (Alpha) {
    auto Parent = klass("Lfixture/Parent;");
    Parent.external = true;
    Input[1].superclass = Parent.name;
    Input.push_back(Parent);
  }
  return Input;
}
} // namespace

