namespace {
std::vector<Class> groupedCollectorCarrierClasses(unsigned Kind, unsigned Shape,
                                                  unsigned Mode,
                                                  unsigned Style) {
  auto Input = mappedCollectorCarrierClasses(Kind, Shape, Mode, Style);
  const bool Alpha = (Kind + Mode) & 1;
  const std::string T = Alpha ? "TInput;" : "TT;",
                    K = Alpha ? "TMapped;" : "TU;",
                    A = Alpha ? "TState;" : "TA;",
                    D = Alpha ? "TValue;" : "TR;";
  const std::string Nested = Shape & 1 ? "Lfixture/Pair;" : "Ljava/util/Map;";
  auto &Signature = *Input[1].methods[0].generic_signature;
  const auto From =
      "Lfixture/Box<" + std::string(Shape & 1 ? "" : "-") + K + A + D + ">;";
  const auto At = Signature.find(From);
  Signature.replace(At, From.size(),
                    "Lfixture/Box<" + std::string(Shape & 1 ? "" : "-") + T +
                        A + D + ">;");
  const auto End = Signature.rfind(D + ">;");
  Signature.replace(End, D.size(),
                    Nested.substr(0, Nested.size() - 1) + "<" + K + D + ">;");
  auto Pair = klass(Nested);
  Pair.generic_signature =
      "<Key:Ljava/lang/Object;Value:Ljava/lang/Object;>Ljava/lang/Object;";
  Pair.external = !(Shape & 1) || Kind & 2;
  if (!(Shape & 1))
    Pair.access = {"public", "abstract", "interface"};
  Input.push_back(Pair);
  return Input;
}
} // namespace

