        case 11:
          Primary.generic_signature =
              "<U:Ljava/lang/Object;>(FFLjava/lang/Object;)V";
          break;
        case 12:
          Caller.instructions[0].registers.pop_back();
          break;
        case 13:
          Caller.instructions[0].registers.back() = Caller.registers;
          break;
