TEST(MobileDalvikJava,
     GuardedIntegerDivisionRejectsUninitializedOriginsAndHandlers) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 12; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = guardedIntegerDivisionClasses(External, false, true, 0, 0);
        auto &M = Input[0].methods[0];
        switch (Mutation) {
        case 0:
          M.instructions[5].registers[0] = 4;
          break;
        case 1:
          M.instructions[5].registers[1] = 4;
          break;
        case 2:
          M.instructions[5].registers[2] = 4;
          break;
        case 3:
          M.instructions[5].registers[2] = M.registers;
          break;
        case 4:
          M.instructions[5].registers.pop_back();
          break;
        case 5:
          M.instructions[5].literal = int64_t(1);
          break;
        case 6:
          M.instructions[5].reference = std::string("I");
          break;
        case 7:
          M.instructions[1].target = M.instructions[7].pc;
          break;
        case 8:
          M.instructions[6].registers[0] = 0;
          break;
        case 9:
          M.instructions[4].registers[0] = 6;
          break;
        case 10:
          M.instructions[5].opcode = "div-int/lit8";
          break;
        case 11: {
          const auto Catch = M.code_end;
          M.instructions.push_back(op(Catch, "move-exception", {0}));
          M.instructions.push_back(op(Catch + 1, "throw", {0}));
          M.code_end = Catch + 2;
          M.tries = {
              {M.instructions[5].pc,
               M.instructions[6].pc,
               {{std::string("Ljava/lang/ArithmeticException;"), Catch}}}};
          break;
        }
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> guardedIntegerDivisionScopedClasses(bool External,
                                                       bool Range, bool Guarded,
                                                       unsigned Form,
                                                       unsigned Suffix) {
  auto Input =
      guardedIntegerDivisionClasses(External, Range, Guarded, Form, Suffix);
  auto &Caller = Input[0].methods[0];
  auto &Parent = Input[1];
  auto &Init = Parent.methods[0];
  const auto Before = Init.reference;
  const std::string Carrier = "Lfixture/Carrier;";
  Input[0].generic_signature = "<T:Ljava/lang/Object;>Lfixture/Base<TT;>;";
  Parent.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Init.reference.parameters.insert(Init.reference.parameters.begin(), Carrier);
  Init.generic_signature = "(Lfixture/Carrier<TA;>;I)V";
  if (!External)
    ++Init.registers;
  ++Caller.registers;
  Caller.reference.parameters.insert(Caller.reference.parameters.begin(),
                                     Carrier);
  Caller.generic_signature = "(Lfixture/Carrier<TT;>;II)V";
  for (auto &Op : Caller.instructions) {
    for (auto &R : Op.registers)
      if (R >= 5)
        ++R;
    if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
        Ref && *Ref == Before) {
      *Ref = Init.reference;
      Op.registers.insert(Op.registers.begin() + 1, 5);
    }
  }
  auto Wrapper = klass(Carrier);
  Wrapper.external = External;
  Wrapper.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Wrapper);
  return Input;
}
} // namespace

