namespace {
std::vector<Class> scopedNullConstructorClasses(bool Copy, bool External,
                                                unsigned Variance, bool Wide,
                                                bool Alpha, bool Cast = false) {
  const bool Copies = Copy || Cast;
  auto Input = nullConstructorArgumentClasses(false, Copies);
  auto &Owner = Input[0];
  const std::string E = Alpha ? "Element" : "E";
  Owner.generic_signature = "<" + E + ":Ljava/lang/Object;>Ljava/lang/Object;";
  const std::string Arg = Variance == 3 ? "*"
                                        : std::string(Variance == 1   ? "-"
                                                      : Variance == 2 ? "+"
                                                                      : "") +
                                              "T" + E + ";";
  auto &Target = Owner.methods[0];
  Target.generic_signature =
      "(" + std::string(Wide ? "J" : "I") + "Lfixture/Sink<" + Arg + ">;)V";
  Input[1].external = External;
  if (Wide) {
    for (auto &M : Owner.methods) {
      M.reference.parameters[0] = "J";
      ++M.registers;
    }
    auto &Caller = Owner.methods.back();
    const unsigned Self = Copies ? 2 : 1, Value = Self + 1, Null = Copy ? 1 : 0;
    Caller.instructions = {op(0, "const/4", {0}, int64_t(0))};
    if (Copies)
      Caller.instructions.push_back(op(1, "move-object", {1, 0}));
    const auto PC = Caller.instructions.size();
    Caller.instructions.push_back(op(PC, "invoke-direct",
                                     {Self, Value, Value + 1, Null}, {},
                                     Target.reference));
    Caller.instructions.push_back(op(PC + 1, "return-void"));
    Caller.code_end = PC + 2;
  } else if (Cast && !Copy) {
    Owner.methods.back().instructions[2].registers.back() = 0;
  }
  if (Cast) {
    auto &Caller = Owner.methods.back();
    Caller.instructions.insert(Caller.instructions.begin() + 2,
                               op(2, "check-cast", {1}, {}, Input[1].name));
    for (size_t I = 0; I < Caller.instructions.size(); ++I)
      Caller.instructions[I].pc = I;
    Caller.code_end = Caller.instructions.size();
  }
  return Input;
}

} // namespace

