namespace {
std::vector<Class> rawBinaryCarrierAllocationClasses(bool External, bool Range,
                                                     bool Wide, bool Copy,
                                                     unsigned Variance) {
  auto Input =
      closedAllocatedCallbackClasses(External, Range, Wide, false, Copy);
  auto &Base = Input[0];
  Base.methods.resize(1);
  Base.methods[0].generic_signature = "(Lfixture/Callback<-TP;>;)V";
  auto &Owner = Input[1];
  Owner.generic_signature = "<E:Ljava/lang/Object;>Lfixture/Base<TE;>;";
  auto &Caller = Owner.methods[0];
  Caller.reference.parameters[0] = Input[2].name;
  const std::string Element = Variance == 3
                                  ? "*"
                                  : std::string(Variance == 1   ? "-"
                                                : Variance == 2 ? "+"
                                                                : "") +
                                        "TE;";
  Caller.generic_signature = "(Lfixture/Callback<" + Element + ">;" +
                             (Wide ? "J" : "Ljava/lang/Object;") + ")V";
  auto &Adapter = Input[3];
  Adapter.generic_signature.reset();
  Adapter.methods[0].reference.parameters[0] = Input[2].name;
  for (auto &Op : Caller.instructions)
    if (auto *Ref = std::get_if<MethodRef>(&Op.reference);
        Ref && Ref->owner == Adapter.name)
      Op.reference = Adapter.methods[0].reference;
  return Input;
}
} // namespace

