TEST(MobileDalvikJava,
     KeyedMapCarriersRejectCrossedRolesAndIncompleteDeclarations) {
  for (unsigned Dependencies = 0; Dependencies < 4; ++Dependencies)
    for (unsigned Mutation = 0; Mutation < 18; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(::testing::PrintToString(
            std::tuple{Dependencies, Mutation, Route}));
        auto Input = keyedMapCarrierClasses(Dependencies, 2, 3, false, 1);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Make.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Make.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Sequence<TT;>", "Sequence<TK;>");
          break;
        case 1:
          Replace("Mapper<TT;TK;>", "Mapper<TV;TK;>");
          break;
        case 2:
          Replace("Mapper<TT;TV;>", "Mapper<TK;TV;>");
          break;
        case 3:
          Replace("Bucket<TK;", "Bucket<TV;");
          break;
        case 4:
          Replace("Pair<TV;TT;>", "Pair<TK;TT;>");
          break;
        case 5:
          Replace("Pair<TV;TT;>", "Pair<+TV;TT;>");
          break;
        case 6:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 7:
          Replace("Mapper<TT;TK;>", "Mapper<TT;TMissing;>");
          break;
        case 8:
          Replace(">(", "W:Ljava/lang/Object;>(");
          break;
        case 9:
          Make.access.insert("varargs");
          break;
        case 10:
          Make.access.erase("static");
          break;
        case 11:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 12:
          Input.back().generic_signature =
              "<A:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 13:
          Input[4].generic_signature =
              "<A:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 14:
          Call.instructions[0].registers.pop_back();
          break;
        case 15:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 16:
          Make.reference.parameters.back() = "I";
          Call.reference.parameters.back() = "I";
          Call.instructions[0].reference = Make.reference;
          Replace(";Z)", ";I)");
          break;
        case 17:
          Input.pop_back();
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> nullaryBinaryFormalClasses(bool External, bool Range,
                                              bool Used, bool Alpha,
                                              bool Interface) {
  const std::string Owner = "Lfixture/Mirror;",
                    Formal = Alpha ? "Element" : "A";
  auto Make =
      method("build", {}, Owner, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.reference.owner = Owner;
  Make.generic_signature = "<" + Formal +
                           ":Ljava/lang/Object;>()Lfixture/Mirror<T" + Formal +
                           ";T" + Formal + ";>;";
  if (External) {
    Make.instructions.clear();
    Make.registers = Make.code_end = 0;
  }
  auto Apply =
      method("apply", {"Ljava/lang/Object;"}, "Ljava/lang/Object;", 0, {});
  Apply.reference.owner = Owner;
  Apply.access = {"public", "abstract"};
  Apply.generic_signature = "(TA;)TB;";
  auto Provider = klass(Owner, {Make, Apply});
  Provider.access = {"public", "abstract"};
  if (Interface)
    Provider.access.insert("interface");
  Provider.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  Provider.external = External;
  std::vector<Instruction> Code{
      op(0, Range ? "invoke-static/range" : "invoke-static", {}, {},
         Make.reference)};
  if (Used) {
    Code.push_back(op(1, "move-result-object", {0}));
    Code.push_back(op(2, "return-object", {0}));
  } else
    Code.push_back(op(1, "return-void"));
  auto Call = method("call", {}, Used ? Owner : "V", 1, Code);
  return {klass("Lfixture/Core;", {Call}), Provider};
}
} // namespace

