TEST(MobileDalvikJava,
     NullaryBinaryFormalsKeepRawUnusedFormalsAndRejectBorrowedSlots) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 15; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input =
            nullaryBinaryFormalClasses(External, true, true, false, true);
        auto &Owner = Input[1];
        auto &Make = Owner.methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Make.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Make.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Mirror<TA;TA;>", "Mirror<TA;TB;>");
          break;
        case 1:
          Replace("Mirror<TA;TA;>", "Mirror<+TA;TA;>");
          break;
        case 2:
          Replace("Mirror<TA;TA;>", "Mirror<TA;-TA;>");
          break;
        case 3:
          Replace("Mirror<TA;TA;>", "Mirror<TA;TMissing;>");
          break;
        case 4:
          Replace("A:Ljava/lang/Object;>", "A:Ljava/lang/Number;>");
          break;
        case 5:
          Replace(">(", "U:Ljava/lang/Object;>(");
          break;
        case 6:
          Make.access.insert("varargs");
          break;
        case 7:
          Make.access.erase("static");
          break;
        case 8:
          Make.access.erase("public");
          Make.access.insert("private");
          break;
        case 9:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 10:
          Owner.generic_signature =
              "<A:Ljava/lang/Object;B:Ljava/lang/Number;>Ljava/lang/Object;";
          Owner.methods[1].generic_signature.reset();
          break;
        case 11:
          Owner.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
          Owner.methods[1].generic_signature.reset();
          break;
        case 12:
          Call.instructions[0].registers.push_back(0);
          break;
        case 13:
          Call.instructions[1].opcode = "move-result";
          break;
        case 14:
          Replace("Mirror<TA;TA;>", "Mirror");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        if (Mutation == 14) {
          // An unused formal beside a raw result needs no element binding.
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(Report.getInteger("minimum_java_release").value_or(8),
                    External ? 8 : 9);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          const auto &After = Classes.at("Lfixture/Mirror;");
          EXPECT_EQ(
              After.generic_signature,
              "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;");
          EXPECT_EQ(After.methods[0].generic_signature,
                    "<A:Ljava/lang/Object;>()Lfixture/Mirror;");
          continue;
        }
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> mergedMapperCollectorClasses(unsigned Dependencies,
                                                unsigned Shape, unsigned Mode,
                                                unsigned Style) {
  auto Input = pairedMapperCollectorClasses(Dependencies, Shape, Mode, Style);
  auto &Make = Input[1].methods[0];
  const std::string V = Shape & 1 ? "Right" : "V", Op = "Lfixture/ValueOp;";
  const auto At = Make.generic_signature->find(')');
  Make.generic_signature->insert(At, "Lfixture/ValueOp<T" + V + ";>;");
  Make.reference.parameters.push_back(Op);
  if (!Input[1].external)
    ++Make.registers;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters.push_back(Op);
  ++Call.registers;
  auto &Invoke = Call.instructions[0];
  Invoke.reference = Make.reference;
  Invoke.registers.push_back(Invoke.registers.back() + 1);
  auto Operator = klass(Op);
  Operator.access = {"public", "abstract", "interface"};
  Operator.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Operator.external = Dependencies & 2;
  Input.push_back(Operator);
  return Input;
}
} // namespace

