namespace {
std::vector<Class> groupedMapContextClasses(unsigned Dependencies,
                                            unsigned Mode, bool Alpha,
                                            bool Variant, bool ObjectAny) {
  auto Input =
      keyedMapCarrierClasses(Dependencies, 0, Mode, Alpha, Variant ? 0 : 1);
  const std::string T = Alpha ? "Input" : "T", V = Alpha ? "Right" : "V";
  auto formal = [](const std::string &Name) { return "T" + Name + ";"; };
  auto &Make = Input[1].methods[0];
  const auto OldOwner = Make.reference.parameters[2];
  const std::string Old = OldOwner.substr(0, OldOwner.size() - 1) + "<" +
                          (Variant ? "-" : "") + formal(T) +
                          (Variant ? "+" : "") + formal(V) + ">;";
  const std::string Downstream = "Lfixture/Downstream;";
  const std::string New =
      "Lfixture/Downstream<" + std::string(Variant ? "-" : "") + formal(T) +
      (ObjectAny ? "+Ljava/lang/Object;" : "*") + formal(V) + ">;";
  const auto At = Make.generic_signature->find(Old);
  if (At == std::string::npos)
    throw std::runtime_error("grouped context model anchor missing");
  Make.generic_signature->replace(At, Old.size(), New);
  Make.reference.parameters[2] = Downstream;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters[2] = Downstream;
  Call.instructions[0].reference = Make.reference;
  auto Header = klass(Downstream);
  Header.access = {"public", "abstract", "interface"};
  Header.external = Dependencies & 2;
  Header.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;C:Ljava/"
                             "lang/Object;>Ljava/lang/Object;";
  Input.push_back(Header);
  return Input;
}
} // namespace

