namespace {
std::vector<Class> classifiedMapContextClasses(unsigned Dependencies,
                                               unsigned Mode, bool Alpha,
                                               bool Variant, bool Unary,
                                               bool Scalar) {
  auto Input =
      keyedMapCarrierClasses(Dependencies, 0, Mode, Alpha, Variant ? 0 : 1);
  const std::string E = Alpha ? "Element" : "E", K = Alpha ? "Key" : "K";
  auto Formal = [](const std::string &Name) { return "T" + Name + ";"; };
  auto &Make = Input[1].methods[0];
  const auto Sequence = Make.reference.parameters[0],
             Mapper = Make.reference.parameters[1];
  Make.reference.parameters.resize(Scalar ? 3 : 2);
  if (Scalar)
    Make.reference.parameters[2] = "Z";
  const auto Seq =
      Sequence.substr(0, Sequence.size() - 1) + "<" + Formal(E) + ">;";
  const auto Fn = Mapper.substr(0, Mapper.size() - 1) + "<" +
                  (Variant ? "-" : "") + Formal(E) + (Variant ? "+" : "") +
                  Formal(K) + ">;";
  Make.generic_signature = "<" + E + ":Ljava/lang/Object;" + K +
                           ":Ljava/lang/Object;>(" + Seq + Fn +
                           (Scalar ? "Z" : "") + ")Lfixture/Bucket<" +
                           Formal(K) + (Unary ? Seq : Formal(E)) + ">;";
  if (!Input[1].external)
    Make.registers = Make.reference.parameters.size() + 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.registers = Call.reference.parameters.size() + 1;
  std::vector<unsigned> Args;
  for (unsigned I = 1; I <= Call.reference.parameters.size(); ++I)
    Args.push_back(I);
  Call.instructions[0].registers = Args;
  Call.instructions[0].reference = Make.reference;
  return Input;
}
} // namespace

