std::vector<Class> enumTokenFactoryClasses(bool External, bool Range,
                                           unsigned OwnerScope, bool Alpha,
                                           bool Used) {
  auto Input = enumArrayFactoryClasses(External, false, Range);
  auto Make = Input[1].methods[0];
  const std::string T = Alpha ? "Element" : "E";
  Make.reference.parameters = {"Ljava/lang/Class;"};
  Make.generic_signature = "<" + T + ":Ljava/lang/Enum<T" + T +
                           ";>;>(Ljava/lang/Class<T" + T +
                           ";>;)Lfixture/Box<T" + T + ";>;";
  if (OwnerScope == 1)
    Input[1].generic_signature = "<E:Ljava/lang/Enum<TE;>;>Ljava/lang/Object;";
  if (OwnerScope == 2)
    Input[1].generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  if (OwnerScope == 3) {
    Make.reference.owner = Input[5].name;
    Input[1].methods.clear();
    Input[5].methods.push_back(Make);
  } else
    Input[1].methods[0] = Make;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.instructions[0].reference = Make.reference;
  if (!Used) {
    Call.reference.returns = "V";
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  auto Token = klass("Ljava/lang/Class;");
  Token.external = true;
  Token.access = {"public", "final"};
  Token.generic_signature = "<Type:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.push_back(Token);
  return Input;
}
