TEST(MobileDalvikJava, EnumTokenFactoriesRejectBrokenBoundsAndTypeTokens) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = enumTokenFactoryClasses(External, true, 1, false, true);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Make.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Make.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Class<TE;>", "Class<+TE;>");
          break;
        case 1:
          Replace("Class<TE;>", "Class<TMissing;>");
          break;
        case 2:
          Replace("Box<TE;>", "Box<+TE;>");
          break;
        case 3:
          Replace("Enum<TE;>", "Enum");
          break;
        case 4:
          Replace("Enum<TE;>", "Enum<+TE;>");
          break;
        case 5:
          Replace("Box<TE;>", "Box");
          break;
        case 6:
          Replace("Box<TE;>", "Box<Ljava/lang/Object;>");
          break;
        case 7:
          Input[6].generic_signature =
              "<S:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 8:
          Input[5].generic_signature =
              "<P:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 9:
          Input[7].generic_signature.reset();
          break;
        case 10:
          Input.pop_back();
          break;
        case 11:
          Input[7].access.erase("public");
          Input[7].access.insert("private");
          break;
        case 12:
          Input[7].generic_signature =
              "<T:Ljava/lang/Object;U:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 13:
          Make.access.insert("bridge");
          break;
        case 14:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 15:
          Make.access.erase("static");
          if (!External)
            ++Make.registers;
          Call.reference.parameters.insert(Call.reference.parameters.begin(),
                                           Input[1].name);
          Call.registers = 3;
          Call.instructions[0].opcode = "invoke-virtual/range";
          Call.instructions[0].registers = {1, 2};
          break;
        case 16:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 17:
          Call.instructions[0].registers.clear();
          break;
        case 18: {
          Input[7].generic_signature =
              "<T:Ljava/lang/Number;>Ljava/lang/Object;";
          auto Number = klass("Ljava/lang/Number;");
          Number.external = true;
          Number.access = {"public"};
          Input.push_back(Number);
          break;
        }
        case 19:
          Input[5].generic_signature = "<P:Ljava/lang/Enum;>Ljava/lang/Object;";
          break;
        case 20:
          Replace("Enum<TE;>;>", "Enum<TE;>;U:Ljava/lang/Object;>");
          break;
        case 21:
          Input[5].access.erase("public");
          Input[5].access.insert("private");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        if (Mutation == 15) {
          // The existing instance-call authority already supports this complete
          // recursive contract. Keep it as a positive contrast to the static
          // token proof, with the original receiver and method metadata.
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Original = Make;
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          const auto &After = Classes.at(Original.reference.owner).methods[0];
          EXPECT_EQ(After.generic_signature, Original.generic_signature);
          EXPECT_EQ(After.access, Original.access);
          EXPECT_EQ(After.declared_throws, Original.declared_throws);
        } else {
          EXPECT_THROW(
              {
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                recoverJava(Classes, B);
              },
              std::runtime_error);
        }
      }
}

namespace {
std::vector<Class> unboundPairContextClasses(bool SDK, bool Facade, bool Range,
                                             unsigned Contexts,
                                             unsigned InputAt, bool Pair,
                                             bool Alpha, bool Used) {
  auto Input = reifiableCarrierFactoryClasses(SDK, Facade, Range);
  auto &Make = Input[1].methods[0];
  auto Context = klass("Lfixture/Context;");
  Context.external = SDK;
  Make.reference.parameters.assign(Contexts, Context.name);
  Make.reference.parameters.insert(Make.reference.parameters.begin() + InputAt,
                                   Input[4].name);
  const std::string K = Alpha ? "Key" : "K", V = Alpha ? "Value" : "V";
  std::string Sig = "<" + K + ":Ljava/lang/Object;" +
                    (Pair ? V + ":Ljava/lang/Object;" : "") + ">(";
  for (unsigned I = 0; I < Make.reference.parameters.size(); ++I)
    Sig += I == InputAt ? "Lfixture/Factory<*>;" : Context.name;
  Make.generic_signature =
      Sig + ")Lfixture/Box<T" + K + ";" + (Pair ? "T" + V + ";" : "") + ">;";
  Input[5].generic_signature =
      Pair ? "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;"
           : "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  if (!SDK)
    Make.registers = Make.reference.parameters.size() + 1;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.registers = Ref.parameters.size() + 1;
  Call.instructions[0].reference = Ref;
  Call.instructions[0].registers.clear();
  for (unsigned I = 1; I < Call.registers; ++I)
    Call.instructions[0].registers.push_back(I);
  if (!Used) {
    Call.reference.returns = "V";
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  Input.push_back(Context);
  return Input;
}
} // namespace

