namespace {
std::vector<Class> iterableCallbackForwarderClasses(bool SDK, bool Range,
                                                    bool Swapped, bool Alpha,
                                                    bool Reorder, bool Used) {
  auto Input = privateBoundCarrierTransferClasses(SDK, Range, false, Alpha,
                                                  Reorder, false, false);
  auto Select = Input[0].methods[0];
  const std::string E = Alpha ? "Element" : "T", S = Alpha ? "Selected" : "S";
  auto Callback = klass("Lfixture/Matcher;");
  Callback.external = SDK;
  Callback.access = {"public", "abstract", "interface"};
  Callback.generic_signature = "<P:Ljava/lang/Object;>Ljava/lang/Object;";
  Select.access = {"public", "static"};
  Select.reference.parameters =
      Swapped ? std::vector<std::string>{Callback.name, Input[1].name}
              : std::vector<std::string>{Input[1].name, Callback.name};
  auto &Sig = *Select.generic_signature;
  const auto At = Sig.find("(T" + S + ";)");
  const std::string C = "Lfixture/Matcher<T" + E + ";>;";
  Sig.replace(At, S.size() + 4,
              "(" + (Swapped ? C + "T" + S + ";" : "T" + S + ";" + C) + ")");
  Select.registers = 3;
  Select.instructions = SDK ? std::vector<Instruction>{}
                            : std::vector<Instruction>{
                                  op(0, "return-object", {Swapped ? 2U : 1U})};
  Select.code_end = SDK ? 0 : 1;
  Input[0].external = SDK;
  Input[0].methods = {Select};
  auto Call =
      method("call", Select.reference.parameters, Select.reference.returns, 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Select.reference),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  if (!Used) {
    Call.reference.returns = "V";
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  Input.push_back(Callback);
  Input.push_back(klass("Lfixture/Caller;", {Call}));
  return Input;
}
} // namespace

