TEST(MobileDalvikJava,
     IteratorIndexedResultsRejectLostBindingsExceptionsAndFrames) {
  for (unsigned Kind : {0U, 1U})
    for (unsigned Mutation = 0; Mutation < 17; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{Kind, Mutation, Route}));
        auto Input = iteratorIndexedResultClasses(Kind, true, false, false,
                                                  true, "I", true, false);
        auto &Read = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Read.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Read.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Producer<TT;>", "Producer<+TT;>");
          break;
        case 1:
          Replace("Producer<TT;>", "Producer<-TT;>");
          break;
        case 2:
          Replace("Producer<TT;>", "Producer<*>");
          break;
        case 3:
          Replace("Producer<TT;>", "Producer<TMissing;>");
          break;
        case 4:
          Replace(")TT;", ")TMissing;");
          break;
        case 5:
          Replace("T:Ljava/lang/Object;>",
                  "T:Ljava/lang/Object;U:Ljava/lang/Object;>");
          break;
        case 6:
          Input[2].generic_signature =
              "<P:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 7:
          Input[2].generic_signature.reset();
          break;
        case 8:
          Read.declared_throws = {"Lfixture/MissingFailure;"};
          break;
        case 9:
          Read.declared_throws = {"Ljava/lang/String;"};
          break;
        case 10:
          Input.back().superclass = "Ljava/lang/Object;";
          break;
        case 11:
          Read.access.insert("synthetic");
          break;
        case 12:
          Read.access.insert("bridge");
          break;
        case 13:
          Read.access.insert("native");
          Read.instructions.clear();
          break;
        case 14:
          Read.access.insert("varargs");
          break;
        case 15:
          Call.instructions[0].registers.pop_back();
          break;
        case 16:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        if (Mutation == 2) {
          // An all-star input already supports an independent result-only
          // formal with closed exceptions. Keep that existing positive case.
          const auto Original = Read;
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          const auto &After = Classes.at(Original.reference.owner).methods[0];
          EXPECT_EQ(After.generic_signature, Original.generic_signature);
          EXPECT_EQ(After.access, Original.access);
          EXPECT_EQ(After.declared_throws, Original.declared_throws);
        } else {
          EXPECT_THROW(
              {
                Budget B;
                ClassMap Classes;
                if (Route)
                  Classes = linkClasses(Input, B);
                else
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                recoverJava(Classes, B);
              },
              std::runtime_error);
        }
      }
}

