TEST(MobileDalvikJava, CollectionFilterCollectorsRejectLostScopesAndFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = collectionFilterCollectorClasses(SDK, true, false, false,
                                                      false, true, true);
        auto &Select = Input[0].methods[0];
        auto &Call = Input[3].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Select.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Select.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Carrier<TT;>", "Carrier<+TT;>");
          break;
        case 1:
          Replace("Carrier<TT;>", "Carrier");
          break;
        case 2:
          Replace("Carrier<TT;>", "Carrier<TMissing;>");
          break;
        case 3:
          Replace("Matcher<-TT;>", "Matcher<+TT;>");
          break;
        case 4:
          Replace("Matcher<-TT;>", "Matcher<-TS;>");
          break;
        case 5:
          Replace("Matcher<-TT;>", "Matcher<*>");
          break;
        case 6:
          Replace("Matcher<-TT;>", "Matcher<-TMissing;>");
          break;
        case 7: {
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          auto Number = klass("Ljava/lang/Number;");
          Number.external = true;
          Input.push_back(Number);
          break;
        }
        case 8:
          Replace(";>(", ";U:Ljava/lang/Object;>(");
          break;
        case 9: {
          Replace("Carrier<TT;>;>", "Carrier<TT;>;:Lfixture/Other;>");
          auto Other = klass("Lfixture/Other;");
          Other.access = {"public", "abstract", "interface"};
          Other.external = true;
          Input.push_back(Other);
          break;
        }
        case 10:
          Replace(")TS;", ")TT;");
          break;
        case 11:
          Replace("(TS;", "(Lfixture/Carrier;");
          break;
        case 12:
          Replace("Matcher<-TT;>", "Matcher");
          break;
        case 13:
          Input[2].generic_signature =
              "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 14:
          Input[2].generic_signature =
              "<P:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 15:
          Input[1].generic_signature =
              "<P:Ljava/lang/Object;Q:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 16:
          Input[1].access.erase("interface");
          break;
        case 17:
          Select.access.erase("static");
          break;
        case 18:
          Select.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 19:
          Select.access.insert("bridge");
          break;
        case 20:
          Call.instructions[0].registers.pop_back();
          break;
        case 21:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 22:
          Input.erase(Input.begin() + 2);
          break;
        case 23:
          Select.access.insert("synthetic");
          break;
        }
        const auto Original = Select;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        auto Recover = [&] {
          Budget B;
          ClassMap Classes;
          if (Route)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          // The common bounded transfer proof now accepts complete closed
          // exceptions for the original carrier inputs; none of their effects
          // change.
          if (Mutation == 18) {
            const auto Plans = validateGenericSignatures(Classes, B);
            EXPECT_TRUE(
                Plans.erased_generic_invocations.contains(Original.reference));
            EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
          }
          const auto Report = recoverJava(Classes, B);
          if (Mutation == 18) {
            EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
            EXPECT_FALSE(Report.getArray("generic_signature_projections"));
            EXPECT_EQ(Classes.at(Original.reference.owner)
                          .methods[0]
                          .generic_signature,
                      Original.generic_signature);
            EXPECT_EQ(
                Classes.at(Original.reference.owner).methods[0].declared_throws,
                Original.declared_throws);
          }
        };
        if (Mutation == 18)
          EXPECT_NO_THROW(Recover());
        else
          EXPECT_THROW(Recover(), std::runtime_error);
      }
}

namespace {
std::vector<Class> sortedEntryMapClasses(bool SDK, bool Facade, bool Range,
                                         bool Swapped, bool Alpha, bool Used,
                                         bool Lower, bool Covariant) {
  auto Input = nestedPairConsumerClasses(SDK, Facade, Range);
  Input[1].access = {"public"};
  auto Entry = klass("Lfixture/Entry;");
  Entry.external = SDK;
  Entry.access = {"public", "abstract", "interface"};
  Entry.generic_signature =
      "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Compare = klass("Lfixture/Compare;");
  Compare.external = SDK;
  Compare.access = {"public", "abstract", "interface"};
  Compare.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Make = Input[1].methods[0];
  const std::string K = Alpha ? "Key" : "K", V = Alpha ? "Value" : "V";
  const std::string Pair = "Lfixture/Entry<T" + K + ";T" + V + ";>;";
  const std::string From =
      std::string(Swapped ? "Lfixture/Compare<" : "Lfixture/Input<") +
      std::string(Covariant ? "+" : "") + Pair + ">;";
  const std::string Callback =
      std::string(Swapped ? "Lfixture/Input<" : "Lfixture/Compare<") +
      std::string(Lower ? "-" : "") + Pair + ">;";
  Make.generic_signature = "<" + K + ":Ljava/lang/Object;" + V +
                           ":Ljava/lang/Object;>(" + (From + Callback) +
                           ")Lfixture/Box<T" + K + ";T" + V + ";>;";
  Make.reference.parameters =
      Swapped ? std::vector<std::string>{Compare.name, "Lfixture/Input;"}
              : std::vector<std::string>{"Lfixture/Input;", Compare.name};
  if (!SDK) {
    Make.registers = 3;
    Make.instructions = {op(0, "const/4", {0}, int64_t(0)),
                         op(1, "return-object", {0})};
    Make.code_end = 2;
  }
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  Input[0] = klass(
      "Lfixture/Client;",
      {method("call", Ref.parameters, Used ? Ref.returns : "V", 3,
              Used ? std::vector<Instruction>{op(0,
                                                 Range ? "invoke-static/range"
                                                       : "invoke-static",
                                                 {1, 2}, {}, Ref),
                                              op(1, "move-result-object", {0}),
                                              op(2, "return-object", {0})}
                   : std::vector<Instruction>{
                         op(0, Range ? "invoke-static/range" : "invoke-static",
                            {1, 2}, {}, Ref),
                         op(1, "return-void")})});
  Input.push_back(Entry);
  Input.push_back(Compare);
  return Input;
}
} // namespace

