namespace {
std::vector<Class> indexedListTransferClasses(bool SDK, bool Facade, bool Range,
                                              bool Alpha, bool Swapped,
                                              bool Used,
                                              const std::string &Scalar) {
  auto Input = nestedInvariantFactoryClasses(SDK, Facade, Range, Alpha);
  auto &Make = Input[1].methods[0];
  const std::string T = Alpha ? "Item" : "T";
  const std::string Seed = "Lfixture/Box<T" + T + ";>;";
  Make.reference.parameters =
      Swapped ? std::vector<std::string>{Scalar, "Lfixture/Box;"}
              : std::vector<std::string>{"Lfixture/Box;", Scalar};
  std::string Parameters = Swapped ? Scalar + Seed : Seed + Scalar;
  if (Scalar == "Z") {
    Make.reference.parameters.push_back("I");
    Parameters += "I";
  }
  Make.generic_signature = "<" + T + ":Ljava/lang/Object;>(" + Parameters +
                           ")Lfixture/Box<Lfixture/Inner<T" + T + ";>;>;";
  Make.deprecated = true;
  if (!SDK)
    Make.registers = Make.incomingWords() + 1;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  std::vector<unsigned> Arguments;
  for (unsigned I = 1; I <= Make.incomingWords(); ++I)
    Arguments.push_back(I);
  const auto Name = Input[0].name;
  Input[0] = klass(
      Name,
      {method("call", Ref.parameters, Used ? Ref.returns : "V",
              Make.incomingWords() + 1,
              Used ? std::vector<Instruction>{op(0,
                                                 Range ? "invoke-static/range"
                                                       : "invoke-static",
                                                 Arguments, {}, Ref),
                                              op(1, "move-result-object", {0}),
                                              op(2, "return-object", {0})}
                   : std::vector<Instruction>{
                         op(0, Range ? "invoke-static/range" : "invoke-static",
                            Arguments, {}, Ref),
                         op(1, "return-void")})});
  return Input;
}
} // namespace

