namespace {
std::vector<Class> iteratorMapCallbackClasses(unsigned Dependencies,
                                              bool Mapped, unsigned Mode,
                                              bool Alpha, bool Variant,
                                              bool Flag, bool Used) {
  auto Input = Mapped ? keyedMapCarrierClasses(Dependencies, 0, Mode, Alpha,
                                               Variant ? 0 : 1)
                      : classifiedMapContextClasses(Dependencies, Mode, Alpha,
                                                    Variant, false, Flag);
  const std::string K = Alpha ? (Mapped ? "Left" : "Key") : "K";
  const std::string V =
      Alpha ? (Mapped ? "Right" : "Element") : (Mapped ? "V" : "E");
  auto &Make = Input[1].methods[0];
  auto &Sig = *Make.generic_signature;
  if (Mapped && !Flag) {
    Make.reference.parameters.pop_back();
    Sig.erase(Sig.find(')') - 1, 1);
  }
  const std::string Seed = "Lfixture/Bucket<T" + K + ";T" + V + ";>;";
  const auto Begin = Sig.find('('), End = Sig.find(">;", Begin) + 2;
  Sig.insert(End, Seed);
  Make.reference.parameters.insert(Make.reference.parameters.begin() + 1,
                                   Make.reference.returns);
  if (!Input[1].external)
    Make.registers = Make.incomingWords() + 1;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.registers = Make.incomingWords() + 1;
  Call.instructions[0].reference = Make.reference;
  Call.instructions[0].registers.clear();
  for (unsigned I = 1; I <= Make.incomingWords(); ++I)
    Call.instructions[0].registers.push_back(I);
  if (!Used) {
    Call.reference.returns = "V";
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  return Input;
}
} // namespace

