namespace {
std::vector<Class> mapUnaryResultClasses(bool SDK, bool Facade, bool Range,
                                         bool Alpha, bool Used,
                                         unsigned Variances, unsigned Wrapped) {
  auto Input = nestedPairFactoryClasses(SDK, Facade, Range);
  auto Layer = klass("Lfixture/Layer;");
  Layer.external = SDK;
  Layer.access = {"public", "abstract", "interface"};
  Layer.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto &Make = Input[1].methods[0];
  const std::string K = Alpha ? "Key" : "K", V = Alpha ? "Value" : "V";
  auto Slot = [&](const std::string &Formal, unsigned Bit) {
    const std::string Variable = "T" + Formal + ";";
    return std::string(Variances & 1 ? "+" : "") +
           ((Wrapped & Bit)
                ? "Lfixture/Layer<" + std::string(Variances & 2 ? "+" : "") +
                      Variable + ">;"
                : Variable);
  };
  Make.reference.parameters = {"Lfixture/Box;"};
  Make.generic_signature =
      "<" +
      (Alpha ? V + ":Ljava/lang/Object;" + K : K + ":Ljava/lang/Object;" + V) +
      ":Ljava/lang/Object;>(Lfixture/Box<" + Slot(K, 1) + Slot(V, 2) +
      ">;)Lfixture/Outer<Lfixture/Box<T" + K + ";T" + V + ";>;>;";
  if (!SDK)
    Make.registers = 2;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  const auto Caller = Input[0].name;
  Input[0] = klass(
      Caller,
      {method("call", Ref.parameters, Used ? Ref.returns : "V", 2,
              Used ? std::vector<Instruction>{op(0,
                                                 Range ? "invoke-static/range"
                                                       : "invoke-static",
                                                 {1}, {}, Ref),
                                              op(1, "move-result-object", {0}),
                                              op(2, "return-object", {0})}
                   : std::vector<Instruction>{
                         op(0, Range ? "invoke-static/range" : "invoke-static",
                            {1}, {}, Ref),
                         op(1, "return-void")})});
  Input.push_back(Layer);
  return Input;
}
} // namespace

