TEST(MobileDalvikJava, PairedArrayMapsRejectLostComponentsSlotsAndFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            pairedArrayMapClasses(SDK, true, true, false, false, false, true);
        auto &Make = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          const auto At = Make.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Make.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("[TK;[TV;", "[TK;[TK;");
          break;
        case 1:
          Replace("Box<TK;TV;>", "Box<TV;TK;>");
          break;
        case 2:
          Replace("[TV;", "[TMissing;");
          break;
        case 3:
          Replace("V:Ljava/lang/Object;>",
                  "V:Ljava/lang/Object;W:Ljava/lang/Object;>");
          break;
        case 4:
          Replace("Box<TK;TV;>", "Box<+TK;TV;>");
          break;
        case 5:
          Replace("Box<TK;TV;>", "Box<TK;TK;>");
          break;
        case 6:
          Replace("([TK;", "([[TK;");
          break;
        case 7:
          Replace("K:Ljava/lang/Object;", "K:Ljava/lang/Number;");
          break;
        case 8:
          Input[5].generic_signature =
              "<A:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 9:
          Input[5].generic_signature =
              "<A:Ljava/lang/Number;B:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 10:
          Input[5].access = {"private"};
          break;
        case 11:
          Replace("Lfixture/Box<TK;TV;>", "Lfixture/Missing<TK;TV;>");
          break;
        case 12:
          Make.access.insert("varargs");
          break;
        case 13:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 14:
          Make.access.insert("native");
          break;
        case 15:
          Make.access.insert("synthetic");
          break;
        case 16:
          Make.access.erase("static");
          break;
        case 17:
          Make.access = {"private", "static"};
          break;
        case 18:
          Replace(";Z)", ";I)");
          break;
        case 19:
          Call.instructions[0].registers.pop_back();
          break;
        case 20:
          Call.instructions[0].registers[0] = Call.registers;
          break;
        case 21:
          Input[1].generic_signature =
              "<O:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 22:
          Replace("Box<TK;TV;>", "Box<TK;[TV;>");
          break;
        case 23:
          Replace("[TK;[TV;", "[TV;[TK;");
          break;
        }
        if (Mutation == 7) {
          auto Number = klass("Ljava/lang/Number;");
          Number.external = true;
          Input.push_back(Number);
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        EXPECT_THROW(
            {
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              recoverJava(Classes, B);
            },
            std::runtime_error);
      }
}

namespace {
std::vector<Class> tailLoopFinalClasses(bool SDK, bool Range, bool Offset,
                                        const std::string &Type) {
  const std::string Owner = "Lfixture/Core;";
  const FieldRef Data{Owner, "data", Type};
  auto Observe = method("observe", {Owner}, "V", 1, {op(0, "return-void")});
  auto Tap = klass("Lfixture/Tap;", {Observe});
  Tap.external = SDK;
  if (SDK) {
    Tap.methods[0].instructions.clear();
    Tap.methods[0].registers = Tap.methods[0].code_end = 0;
  }
  const std::string Store = Type == "J"   ? "iput-wide"
                            : Type == "I" ? "iput"
                                          : "iput-object";
  auto Init =
      method("<init>", {"Z", "I", Type}, "V", Type == "J" ? 7 : 6,
             {op(0, Range ? "invoke-direct/range" : "invoke-direct", {2}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "if-eqz", {3}, {}, {}, 5), op(2, Store, {5, 2}, {}, Data),
              op(3, Range ? "invoke-static/range" : "invoke-static", {2}, {},
                 Tap.methods[0].reference),
              op(4, "goto", {}, {}, {}, 11), op(5, Store, {5, 2}, {}, Data),
              op(6, "if-lez", {4}, {}, {}, 11),
              op(7, Range ? "invoke-static/range" : "invoke-static", {2}, {},
                 Tap.methods[0].reference),
              op(8, "add-int/lit8", {4, 4}, int64_t(-1)),
              op(9, "goto", {}, {}, {}, 6), op(11, "return-void")});
  Init.access = {"public", "constructor"};
  if (Offset) {
    for (auto &I : Init.instructions) {
      I.pc += 7;
      if (I.target)
        *I.target += 7;
    }
    Init.code_end += 7;
  }
  auto Core = klass(Owner, {Init});
  Core.fields = {{Data, {"public", "final"}, {}}};
  return {Core, Tap};
}
} // namespace

