namespace {
std::vector<Class> sdkCovariantInheritanceClasses(bool External, bool Range) {
  auto Required = method("view", {}, "Lfixture/View;", 0, {});
  Required.access = {"public", "abstract"};
  Required.generic_signature = "()Lfixture/View<TT;>;";
  auto Catalog = klass("Lfixture/Catalog;", {Required});
  Catalog.access = {"public", "interface", "abstract"};
  Catalog.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto View = klass("Lfixture/View;");
  View.access = {"public", "interface", "abstract"};
  View.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Slice = klass("Lfixture/Slice;");
  Slice.interfaces = {View.name};
  Slice.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;>"
                            "Ljava/lang/Object;Lfixture/View<TA;>;";
  auto Ctor = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Ctor.access = {"public", "constructor"};
  auto Typed =
      method("view", {}, Slice.name, 2,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Typed.access = {"public"};
  Typed.generic_signature = "()Lfixture/Slice<TA;TB;>;";
  MethodRef TypedRef{"Lfixture/Provider;", "view", {}, Slice.name};
  auto Bridge =
      method("view", {}, View.name, 2,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual", {1}, {},
                 TypedRef),
              op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  Bridge.access = {"public", "bridge", "synthetic"};
  auto Provider = klass(TypedRef.owner, {Ctor, Typed, Bridge});
  Provider.interfaces = {Catalog.name};
  Provider.generic_signature = "<A:Ljava/lang/Object;B:Ljava/lang/Object;>"
                               "Ljava/lang/Object;Lfixture/Catalog<TA;>;";
  Ctor.instructions[0].reference = MethodRef{Provider.name, "<init>", {}, "V"};
  auto Core = klass("Lfixture/Core;", {Ctor});
  Core.superclass = Provider.name;
  Core.generic_signature = "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>"
                           "Lfixture/Provider<TX;TY;>;";
  if (External)
    for (auto *C : {&Provider, &Slice, &View, &Catalog}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return {Core, Provider, Slice, View, Catalog};
}
} // namespace

TEST(MobileDalvikJava, SDKCovariantInheritanceKeepsCompleteProviderScope) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Reverse : {false, true})
        for (bool Linked : {false, true}) {
          SCOPED_TRACE(::testing::Message()
                       << External << Range << Reverse << Linked);
          auto Input = sdkCovariantInheritanceClasses(External, Range);
          const auto Typed = Input[1].methods[1].reference;
          const auto Required = Input[4].methods[0].reference;
          if (Reverse) {
            for (auto &C : Input)
              std::reverse(C.methods.begin(), C.methods.end());
            std::reverse(Input.begin(), Input.end());
          }
          Budget B;
          ClassMap Classes;
          if (Linked)
            Classes = linkClasses(Input, B);
          else
            for (const auto &C : Input)
              Classes.emplace(C.name, C);
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_EQ(Plans.external_class_covariant_contracts.contains(
                        {Typed, Required}),
                    External);
          const auto Report = recoverJava(Classes, B);
          EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(Report.getInteger("projected_method_count").value_or(0),
                    External ? 0 : 1);
          EXPECT_FALSE(Report.getArray("generic_signature_projections"));
          std::string Text;
          for (size_t I = 0; I < Report.getArray("source_units")->size(); ++I)
            Text += source(Report, I);
          EXPECT_NE(Text.find("fixture.Provider<X, Y>"), std::string::npos);
        }
}

TEST(MobileDalvikJava, SDKCovariantInheritanceRejectsIncompleteOrChangedSlots) {
  for (unsigned Mutation = 0; Mutation < 14; ++Mutation)
    for (bool Reverse : {false, true}) {
      SCOPED_TRACE(::testing::Message() << Mutation << ':' << Reverse);
      auto Input = sdkCovariantInheritanceClasses(true, false);
      if (Mutation == 0)
        Input[2].generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/View<TB;>;";
      else if (Mutation == 1)
        Input[1].generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/"
            "Object;Lfixture/Catalog<TB;>;";
      else if (Mutation == 2)
        Input[1].methods[1].generic_signature = "()Lfixture/Slice<TB;TA;>;";
      else if (Mutation == 3)
        Input[1].methods[1].generic_signature = "()Lfixture/Slice<+TA;TB;>;";
      else if (Mutation == 4)
        Input[1].methods.pop_back();
      else if (Mutation == 5)
        Input[1].methods[2].access.erase("synthetic");
      else if (Mutation == 6)
        Input[1].methods[2].access.insert("static");
      else if (Mutation == 7)
        Input[1].methods[1].access = {"protected"};
      else if (Mutation == 8)
        Input[1].methods[1].access.insert("abstract");
      else if (Mutation == 9)
        Input[1].methods[1].reference.parameters = {"I"};
      else if (Mutation == 10)
        Input[1].generic_signature.reset();
      else if (Mutation == 11) {
        Input[0].interfaces = {Input[4].name};
        Input[0].generic_signature =
            "<X:Ljava/lang/Object;Y:Ljava/lang/Object;>Lfixture/"
            "Provider<TY;TX;>;Lfixture/Catalog<TX;>;";
      } else if (Mutation == 12) {
        auto Other = Input[2];
        Other.name = "Lfixture/Other;";
        auto Competitor = Input[1].methods[1];
        Competitor.reference.returns = Other.name;
        Competitor.generic_signature = "()Lfixture/Other<TA;TB;>;";
        Input[1].methods.push_back(Competitor);
        Input.push_back(Other);
      }
      if (Reverse) {
        for (auto &C : Input)
          std::reverse(C.methods.begin(), C.methods.end());
        std::reverse(Input.begin(), Input.end());
      }
      EXPECT_THROW(
          {
            Budget B;
            auto Classes = linkClasses(Input, B);
            auto Plans = validateGenericSignatures(Classes, B);
            if (Mutation == 13)
              Plans.external_class_covariant_contracts.clear();
            planGenericInheritance(Classes, Plans, B);
          },
          std::runtime_error);
    }
}

namespace {
std::vector<Class> closedTokenNominalClasses(bool External, bool Standard,
                                             bool Range, bool Used, bool Swap) {
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  Object.external = true;
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  auto Input = klass(Standard ? "Ljava/util/Iterator;" : "Lfixture/Input;");
  Input.generic_signature = "<Item:Ljava/lang/Object;>Ljava/lang/Object;";
  Input.external = Standard;
  auto Result = klass(Standard ? "Ljava/util/List;" : "Lfixture/Result;");
  Result.generic_signature = "<Value:Ljava/lang/Object;>Ljava/lang/Object;";
  Result.external = Standard;
  if (Standard)
    for (auto *C : {&Input, &Result})
      C->access = {"public", "interface", "abstract"};
  const auto Applied = Input.name.substr(0, Input.name.size() - 1) + "<TE;>;";
  const auto Fixed =
      Result.name.substr(0, Result.name.size() - 1) + "<Ljava/lang/Object;>;";
  auto Make =
      method("make",
             Swap ? std::vector<std::string>{String.name, Input.name}
                  : std::vector<std::string>{Input.name, String.name},
             Result.name, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature =
      "<E:Ljava/lang/Object;>(" +
      (Swap ? String.name + Applied : Applied + String.name) + ")" + Fixed;
  auto Provider = klass("Lfixture/Provider;", {Make});
  if (External) {
    Provider.external = true;
    Provider.methods[0].instructions.clear();
    Provider.methods[0].registers = Provider.methods[0].code_end = 0;
  }
  auto Call =
      method("run", Make.reference.parameters, Used ? Result.name : "V", 3,
             {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {},
                 Provider.methods[0].reference)});
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
  } else
    Call.instructions.push_back(op(3, "return-void"));
  Call.code_end = Call.instructions.back().pc + 1;
  return {
      klass("Lfixture/Core;", {Call}), Provider, Input, Result, String, Object};
}
} // namespace

