TEST(MobileDalvikJava,
     ClosedTokenNominalResultsKeepUnusedFormalsAndRejectIncompleteTypes) {
  for (unsigned Mutation = 0; Mutation < 15; ++Mutation)
    for (bool External : {false, true}) {
      SCOPED_TRACE(::testing::Message() << Mutation << ':' << External);
      auto Input =
          closedTokenNominalClasses(External, true, false, true, false);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto Replace = [&](std::string_view A, std::string_view B) {
        auto &S = *Make.generic_signature;
        const auto At = S.find(A);
        ASSERT_NE(At, std::string::npos);
        S.replace(At, A.size(), B);
      };
      if (Mutation == 0)
        Replace("Iterator<TE;>", "Iterator<+TE;>");
      else if (Mutation == 1)
        Replace("Iterator<TE;>", "Iterator<-TE;>");
      else if (Mutation == 2)
        Replace("Iterator<TE;>", "Iterator<*>");
      else if (Mutation == 3)
        Replace("Iterator<TE;>", "Iterator");
      else if (Mutation == 4)
        Replace("Iterator<TE;>", "Iterator<TMissing;>");
      else if (Mutation == 5)
        Replace("E:Ljava/lang/Object;>",
                "E:Ljava/lang/Object;U:Ljava/lang/Object;>");
      else if (Mutation == 6)
        Replace("List<Ljava/lang/Object;>", "List<+Ljava/lang/Object;>");
      else if (Mutation == 7)
        Replace("List<Ljava/lang/Object;>", "List<*>");
      else if (Mutation == 8)
        Replace("List<Ljava/lang/Object;>", "List<TMissing;>");
      else if (Mutation == 9)
        Input[2].generic_signature =
            "<Item:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 10)
        Input[3].generic_signature =
            "<Value:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 11)
        Make.access = {"private", "static"};
      else if (Mutation == 12) {
        Make.reference.parameters[1] = Input[2].name;
        Replace("Ljava/lang/String;", "Ljava/util/Iterator<TE;>;");
      } else if (Mutation == 13) {
        Make.reference.parameters[1] = "Lfixture/MissingContext;";
        Replace("Ljava/lang/String;", "Lfixture/MissingContext;");
      } else {
        Make.reference.returns = "Ljava/lang/Object;";
        Call.reference.returns = Make.reference.returns;
      }
      Call.reference.parameters = Make.reference.parameters;
      Call.instructions[0].reference = Make.reference;
      if (Mutation == 3) {
        // The raw input leaves E completely unused. Preserve the existing
        // unused-formal invocation instead of demanding a new seed relation.
        Budget B;
        const auto Classes = linkClasses(Input, B);
        const auto Plans = validateGenericSignatures(Classes, B);
        EXPECT_TRUE(Plans.erased_generic_invocations.contains(Make.reference));
        const auto R = recoverJava(Classes, B);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
        EXPECT_EQ(Classes.at(Make.reference.owner).methods[0].generic_signature,
                  Make.generic_signature);
      } else
        EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

namespace {
std::vector<Class> seededIterableMapClasses(unsigned Dependencies, bool Mapped,
                                            bool Grouped, bool First,
                                            bool Alpha, bool Flag, bool Used) {
  auto Input = iteratorMapCallbackClasses(Dependencies, Mapped, 3, Alpha, false,
                                          Flag, Used);
  auto &Make = Input[1].methods[0];
  auto &Sig = *Make.generic_signature;
  if (Grouped) {
    const std::string K = Alpha ? (Mapped ? "Left" : "Key") : "K";
    const std::string V =
        Alpha ? (Mapped ? "Right" : "Element") : (Mapped ? "V" : "E");
    const std::string Pair = "Bucket<T" + K + ";T" + V + ";>";
    const std::string Nested =
        "Bucket<T" + K + ";Lfixture/Grouped<T" + V + ";>;>";
    size_t Pos = 0;
    unsigned Replaced = 0;
    while ((Pos = Sig.find(Pair, Pos)) != std::string::npos) {
      Sig.replace(Pos, Pair.size(), Nested);
      Pos += Nested.size();
      ++Replaced;
    }
    if (Replaced != 2)
      throw std::runtime_error("owned complete grouped seed/result changed");
  }
  if (First) {
    const auto Start = Sig.find('(') + 1;
    const auto Seed = Sig.find(
        Make.reference.returns.substr(0, Make.reference.returns.size() - 1) +
            "<",
        Start);
    const auto Callback =
        Sig.find(Make.reference.parameters[2].substr(
                     0, Make.reference.parameters[2].size() - 1) +
                     "<",
                 Seed);
    Sig = Sig.substr(0, Start) + Sig.substr(Seed, Callback - Seed) +
          Sig.substr(Start, Seed - Start) + Sig.substr(Callback);
    std::swap(Make.reference.parameters[0], Make.reference.parameters[1]);
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.instructions[0].reference = Make.reference;
  auto Group = klass("Lfixture/Grouped;");
  Group.generic_signature = "<Item:Ljava/lang/Object;>Ljava/lang/Object;";
  Group.external = true;
  Input.push_back(Group);
  return Input;
}
} // namespace

