TEST(MobileDalvikJava,
     SeededIterableMapsRejectChangedNestedSeedsAndCallbackScopes) {
  for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
    for (unsigned Dependencies : {0u, 3u}) {
      SCOPED_TRACE(::testing::Message() << Mutation << ':' << Dependencies);
      auto Input = seededIterableMapClasses(Dependencies, true, true, true,
                                            false, false, true);
      auto &Make = Input[1].methods[0];
      auto &Call = Input[0].methods[0];
      auto Replace = [&](std::string_view A, std::string_view B) {
        auto &S = *Make.generic_signature;
        const auto At = S.find(A);
        ASSERT_NE(At, std::string::npos);
        S.replace(At, A.size(), B);
      };
      if (Mutation == 0)
        Replace("Bucket<TK;Lfixture/Grouped<TV;>;>",
                "Bucket<TV;Lfixture/Grouped<TV;>;>");
      else if (Mutation == 1)
        Replace("Grouped<TV;>", "Grouped<TK;>");
      else if (Mutation == 2)
        Replace("Grouped<TV;>", "Grouped<+TV;>");
      else if (Mutation == 3)
        Replace("Grouped<TV;>", "Grouped<*>");
      else if (Mutation == 4)
        Replace("Grouped<TV;>", "Grouped<TMissing;>");
      else if (Mutation == 5)
        Replace("Grouped<TV;>", "Grouped");
      else if (Mutation == 6)
        Replace("Sequence<TT;>", "Sequence<+TT;>");
      else if (Mutation == 7)
        Replace("Sequence<TT;>", "Sequence<TV;>");
      else if (Mutation == 8)
        Replace(";>(", ";Unused:Ljava/lang/Object;>(");
      else if (Mutation == 9)
        Replace("K:Ljava/lang/Object;", "K:Ljava/lang/Number;");
      else if (Mutation == 10)
        Input.back().generic_signature =
            "<A:Ljava/lang/Object;B:Ljava/lang/Object;>Ljava/lang/Object;";
      else if (Mutation == 11)
        Input.back().generic_signature =
            "<Item:Ljava/lang/Number;>Ljava/lang/Object;";
      else if (Mutation == 12)
        Input.pop_back();
      else if (Mutation == 13)
        Make.access = {"private", "static"};
      else if (Mutation == 14) {
        const auto Fn = Make.reference.parameters[2].substr(
            0, Make.reference.parameters[2].size() - 1);
        Replace(Fn + "<TT;TK;>", Fn + "<TK;TK;>");
      } else {
        const auto Fn = Make.reference.parameters[3].substr(
            0, Make.reference.parameters[3].size() - 1);
        Replace(Fn + "<TT;TV;>", Fn + "<TT;TK;>");
      }
      Call.instructions[0].reference = Make.reference;
      EXPECT_THROW(recover(Input), std::runtime_error);
    }
}

namespace {
std::vector<Class> flagPairFactoryClasses(bool SDK, bool Facade, bool Range,
                                          bool Swapped, unsigned Mode,
                                          bool Used) {
  auto Input = scalarPairFactoryClasses(SDK, Facade, Range, Swapped);
  const std::vector<std::vector<std::string>> Contexts = {
      {"Z"}, {"I", "Z"}, {"Z", "I"}, {"I", "I", "Z"}, {"Z", "Z"}};
  auto &Make = Input[1].methods[0];
  std::string Encoded;
  for (const auto &Type : Contexts.at(Mode))
    Encoded += Type;
  auto &Sig = *Make.generic_signature;
  const auto At = Sig.find(">(I)");
  Sig.replace(At, 4, ">(" + Encoded + ")");
  Make.reference.parameters = Contexts.at(Mode);
  if (!SDK)
    Make.registers = Make.incomingWords() + 1;
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Make.reference.parameters;
  Call.registers = Call.incomingWords() + 1;
  Call.instructions[0].reference = Ref;
  Call.instructions[0].registers.clear();
  for (unsigned I = 1; I < Call.registers; ++I)
    Call.instructions[0].registers.push_back(I);
  if (!Used) {
    Call.reference.returns = "V";
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  return Input;
}
} // namespace

