namespace {
std::vector<Class> collectionPrimitiveResultClasses(bool SDK, bool Facade,
                                                    bool Range, bool Alpha,
                                                    bool Used,
                                                    const std::string &Type) {
  const std::string Formal = Alpha ? "Element" : "T";
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.access = {"public", "abstract", "interface"};
  Carrier.generic_signature = "<A:Ljava/lang/Object;>Ljava/lang/Object;";
  Carrier.external = SDK;
  auto Accept = method("accept", {"Ljava/lang/Object;"}, "Z", 0, {});
  Accept.access = {"public", "abstract"};
  Accept.generic_signature = "(TB;)Z";
  auto Test = klass("Lfixture/Test;", {Accept});
  Test.access = {"public", "abstract", "interface"};
  Test.generic_signature = "<B:Ljava/lang/Object;>Ljava/lang/Object;";
  Test.external = SDK;
  auto Make =
      method("locate", {Carrier.name, Test.name}, "[" + Type, 3,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.generic_signature = "<" + Formal +
                           ":Ljava/lang/Object;>(Lfixture/Carrier<T" + Formal +
                           ";>;Lfixture/Test<T" + Formal + ";>;)[" + Type;
  auto Factory = klass("Lfixture/Factory;", {Make});
  Factory.external = SDK;
  if (SDK) {
    Factory.methods[0].instructions.clear();
    Factory.methods[0].registers = 0;
    Factory.methods[0].code_end = 0;
  }
  auto Alias = klass("Lfixture/Facade;");
  Alias.superclass = Factory.name;
  Alias.external = SDK;
  auto Ref = Factory.methods[0].reference;
  if (Facade)
    Ref.owner = Alias.name;
  auto Call = method(
      "call", Ref.parameters, Used ? Ref.returns : "V", 3,
      {op(0, Range ? "invoke-static/range" : "invoke-static", {1, 2}, {}, Ref),
       op(1, "move-result-object", {0}), op(2, "return-object", {0})});
  if (!Used) {
    Call.instructions.resize(2);
    Call.instructions[1] = op(1, "return-void");
    Call.code_end = 2;
  }
  return {klass("Lfixture/Client;", {Call}), Factory, Carrier, Test, Alias};
}
} // namespace

