  Ctor.generic_signature = "(Lfixture/Carrier<+T" + E + ";>;)V";
  auto &Make = Input[0].methods[0];
  Make.reference.parameters = {Carrier.name};
  Make.generic_signature = "<T:Ljava/lang/Object;>(Lfixture/Carrier<TT;>;)" +
                           std::string(Used ? "Lfixture/Widget<TT;>;" : "V");
  Make.instructions[5].reference = Ctor.reference;
