std::vector<Class> scopedScalarPairFactoryClasses(bool SDK, bool Facade,
                                                  bool Range, bool Self,
                                                  bool Swapped, unsigned Mode) {
  auto Input = flagPairFactoryClasses(SDK, Facade, Range, Swapped, Mode, true);
  Input[1].generic_signature =
      "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;";
  if (Self) {
    Input[1].access.insert("public");
    auto &Make = Input[1].methods[0];
    auto &S = *Make.generic_signature;
    const auto At = S.find(")Lfixture/Box<");
    S.replace(At + 1, std::string("Lfixture/Box").size(),
              Input[1].name.substr(0, Input[1].name.size() - 1));
    Make.reference.returns = Input[1].name;
    Input[0].methods[0].reference.returns = Make.reference.returns;
    std::get<MethodRef>(Input[0].methods[0].instructions[0].reference).returns =
        Make.reference.returns;
  }
  return Input;
}
