          break;
        case 6:
          Target.access = {"private"};
          break;
        case 7:
          Parent.methods.back().access.insert("final");
          break;
        case 8:
          Parent.methods.back().access.insert("static");
          break;
        case 9:
          Bridge.instructions[0].registers.pop_back();
          break;
        case 10:
          std::swap(Bridge.instructions[0].registers[0],
                    Bridge.instructions[0].registers[1]);
          break;
        case 11:
          Bridge.instructions[0].registers[3] = 2;
