// Inherited parameter bridges retain the typed provider's own generic scope.
namespace {
std::vector<Class>
inheritedMethodParameterBridgeFixture(bool SDK, bool Range, bool Alpha,
                                      bool Recursive, bool Wide,
                                      bool OwnerFirst, bool Final) {
  auto Input = inheritedFixedParameterBridgeFixture(
      SDK, Range, Alpha, true, true, OwnerFirst, false, Final);
  const std::string Token = "Ljava/lang/Class;";
  const std::string Result =
      Recursive ? "Ljava/lang/Enum;" : "Ljava/lang/Object;";
  const std::string RequiredFormal = Alpha ? "Element" : "E";
  const std::string ProvidedFormal = Alpha ? "Value" : "U";
  auto &Required = Input[0].methods[1];
  auto &Typed = Input[1].methods[4];
  auto &Bridge = Input[1].methods[5];
  for (auto *Member : {&Required, &Typed, &Bridge}) {
    Member->reference.parameters.insert(Member->reference.parameters.begin(),
                                        Token);
    if (Wide)
      Member->reference.parameters.push_back("J");
    Member->reference.returns = Result;
  }
  const auto Signature = [&](const std::string &Formal,
                             const std::string &Key) {
    const std::string Bound =
        Recursive ? "Ljava/lang/Enum<T" + Formal + ";>;" : "Ljava/lang/Object;";
    return "<" + Formal + ":" + Bound + ">(Ljava/lang/Class<T" + Formal +
           ";>;" + Key + (Wide ? "J" : "") + ")T" + Formal + ";";
  };
  Required.generic_signature = Signature(
      RequiredFormal, "T" + std::string(Alpha ? "Item" : "Element") + ";");
  Typed.generic_signature = Signature(ProvidedFormal, "Lfixture/Leaf;");
  if (!SDK) {
    Typed.registers += Wide ? 3 : 1;
    const unsigned Receiver = Range ? 16 : 0;
    std::vector<unsigned> Words{Receiver, Receiver + 1, Receiver + 2};
    if (Wide) {
      Words.push_back(Receiver + 3);
      Words.push_back(Receiver + 4);
    }
    Bridge.registers = Receiver + Words.size();
    Bridge.instructions = {
        op(0, "check-cast", {Receiver + 2}, {}, std::string("Lfixture/Leaf;")),
        op(2, Range ? "invoke-virtual/range" : "invoke-virtual", Words, {},
           Typed.reference),
        op(5, "move-result-object", {Receiver + 2}),
        op(6, "return-object", {Receiver + 2})};
    Bridge.code_end = 7;
  }
  auto TokenClass = klass(Token);
  TokenClass.external = true;
  TokenClass.generic_signature = "<T:Ljava/lang/Object;>Ljava/lang/Object;";
  auto EnumClass = klass("Ljava/lang/Enum;");
  EnumClass.access = {"public", "abstract"};
  EnumClass.external = true;
  EnumClass.generic_signature =
      "<Self:Ljava/lang/Enum<TSelf;>;>Ljava/lang/Object;";
  auto Root = klass("Ljava/lang/Object;");
  Root.external = true;
  Root.superclass.reset();
  auto RootInit = Input[1].methods[1];
  RootInit.reference.owner = Root.name;
  RootInit.instructions.clear();
  RootInit.registers = RootInit.code_end = 0;
  Root.methods = {std::move(RootInit)};
  Input.push_back(std::move(TokenClass));
  Input.push_back(std::move(EnumClass));
  Input.push_back(std::move(Root));
  return Input;
}
} // namespace

