// Null superclass arguments retain an already proven complete generic view.
namespace {
std::vector<Class> closedNullSuperBindingFixture(bool SDK, bool Range,
                                                 bool Interface, bool Alias,
                                                 bool Wide, bool ForwardLabel,
                                                 unsigned Variance) {
  auto Input = literalTokenConstructorFixture(SDK, Range, Interface, Alias,
                                              Wide, ForwardLabel, Variance);
  for (auto &I : Input[0].methods[0].instructions)
    if (I.opcode == "const-class") {
      I.opcode = "const/4";
      I.reference = std::monostate{};
      I.literal = int64_t(0);
    }
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ClosedNullSuperArgumentsRetainCompleteContractsWithoutCallerSignatures) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Interface : {false, true})
        for (bool Alias : {false, true})
          for (bool Wide : {false, true})
            for (bool ForwardLabel : {false, true})
              for (unsigned Variance : {0u, 1u, 2u, 3u})
                for (unsigned Route : {0u, 1u, 2u}) {
                  if (Wide && !Range)
                    continue;
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Range, Interface, Alias, Wide,
                                 ForwardLabel, Variance, Route}));
                  ASSERT_NO_THROW(([&] {
                    Budget B;
                    auto Classes = literalTokenConstructorInput(
                        closedNullSuperBindingFixture(SDK, Range, Interface,
                                                      Alias, Wide, ForwardLabel,
                                                      Variance),
                        Route, B);
                    const auto Caller =
                        Classes.at("Lfixture/Child;").methods[0];
                    const auto Target =
                        Classes.at("Lfixture/Parent;").methods[0];
                    ASSERT_FALSE(Caller.generic_signature);
                    const auto Plans = validateGenericSignatures(Classes, B);
                    EXPECT_TRUE(Plans.superclass_calls.contains(
                        {Caller.reference, Target.reference}));
                    const auto R = recoverJava(Classes, B);
                    EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                    EXPECT_EQ(R.getInteger("minimum_java_release").value_or(8),
                              8);
                    EXPECT_FALSE(R.getArray("generic_signature_projections"));
                    for (const auto &Row : *R.getArray("source_units"))
                      EXPECT_EQ(Row.getAsObject()->getString("source")->find(
                                    "Leaf.class"),
                                llvm::StringRef::npos);
                    EXPECT_EQ(Classes.at("Lfixture/Parent;")
                                  .methods[0]
                                  .generic_signature,
                              Target.generic_signature);
                    EXPECT_EQ(Classes.at("Lfixture/Child;")
                                  .methods[0]
                                  .generic_signature,
                              Caller.generic_signature);
                  })());
                }
}

