// Closed interface seed bindings retain independently checked exceptions.
namespace {
std::vector<Class> closedInterfaceSeedThrowsClasses(bool SDK, bool Range,
                                                    bool SeedFirst, bool Wide,
                                                    unsigned Throws) {
  auto Input = closedCarrierSeedResultClasses(SDK, SDK, false, Range, SeedFirst,
                                              false, 1);
  auto &Target = Input[1].methods[0];
  Target.reference.parameters.push_back("Z");
  if (Wide)
    Target.reference.parameters.insert(Target.reference.parameters.begin(),
                                       "J");
  Target.generic_signature =
      "<R::Lfixture/Carrier<Lfixture/Element;>;>(" +
      std::string(Wide ? "J" : "") +
      (SeedFirst ? "TR;Lfixture/Context;" : "Lfixture/Context;TR;") + "Z)TR;";
  if (!SDK) {
    Target.registers = Target.incomingWords();
    Target.instructions = {
        op(0, "return-object", {(Wide ? 2u : 0u) + (SeedFirst ? 0u : 1u)})};
  }
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.superclass = Throwable.name;
  Exception.external = true;
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.superclass = Exception.name;
  Runtime.external = true;
  auto Checked = klass("Lfixture/Checked;");
  Checked.superclass = Exception.name;
  Checked.external = SDK;
  switch (Throws) {
  case 0:
    Target.declared_throws.reset();
    break;
  case 1:
    Target.declared_throws = std::vector<std::string>{};
    break;
  case 2:
    Target.declared_throws = {Runtime.name};
    break;
  case 3:
    Target.declared_throws = {Checked.name};
    break;
  case 4:
    Target.declared_throws = {Runtime.name, Checked.name};
    break;
  }
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Target.reference.parameters;
  const unsigned First = Range ? 16 : 1;
  Call.registers = First + Target.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions[0] = op(0, Range ? "invoke-static/range" : "invoke-static",
                            Words, {}, Target.reference);
  Input.insert(Input.end(), {Throwable, Exception, Runtime, Checked});
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     ClosedInterfaceSeedsKeepCompleteCheckedThrowsAndOriginalCarriers) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool SeedFirst : {false, true})
        for (bool Wide : {false, true})
          for (unsigned Throws = 0; Throws < 5; ++Throws)
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Range, SeedFirst, Wide, Throws, Route}));
              auto Input = closedInterfaceSeedThrowsClasses(
                  SDK, Range, SeedFirst, Wide, Throws);
              const auto Original = Input[1].methods[0];
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(Plans.erased_generic_invocations.contains(
                  Original.reference));
              if (Original.declared_throws &&
                  !Original.declared_throws->empty())
                EXPECT_TRUE(validatedClosedDeclaredThrows(Original, Plans));
              if (Throws >= 3)
                EXPECT_FALSE(validatedUncheckedDeclaredThrows(Original, Plans));
              const auto Report = recoverJava(Classes, B);
              EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
              EXPECT_FALSE(Report.getArray("generic_signature_projections"));
              EXPECT_FALSE(Report.getArray("class_source_bindings"));
              const auto &After =
                  Classes.at(Original.reference.owner).methods[0];
              EXPECT_EQ(After.generic_signature, Original.generic_signature);
              EXPECT_EQ(After.declared_throws, Original.declared_throws);
              EXPECT_EQ(After.access, Original.access);
            }
}

