// Direct class-bounded seed results retain complete closed throws contracts.
namespace {
std::vector<Class> closedClassSeedThrowsClasses(bool SDK, bool Range,
                                                bool SeedFirst, bool Wide,
                                                unsigned Throws, bool Parent) {
  auto Input =
      closedInterfaceSeedThrowsClasses(SDK, Range, SeedFirst, Wide, Throws);
  auto &Bound = Input[2];
  Bound.access = {"public"};
  Bound.generic_signature.reset();
  auto &Signature = *Input[1].methods[0].generic_signature;
  const std::string Before = "<R::Lfixture/Carrier<Lfixture/Element;>;>";
  Signature.replace(0, Before.size(), "<R:Lfixture/Carrier;>");
  if (Parent) {
    const auto Constructor = [&](const std::string &Owner,
                                 const std::string &ParentName) {
      auto Init = method("<init>", {}, "V", 1,
                         {op(0, "invoke-direct", {0}, {},
                             MethodRef{ParentName, "<init>", {}, "V"}),
                          op(1, "return-void")});
      Init.reference.owner = Owner;
      Init.access = {"public", "constructor"};
      if (SDK) {
        Init.instructions.clear();
        Init.registers = Init.code_end = 0;
      }
      return Init;
    };
    auto Root = klass("Lfixture/Root;",
                      {Constructor("Lfixture/Root;", "Ljava/lang/Object;")});
    Root.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
    Root.external = SDK;
    Bound.superclass = Root.name;
    Bound.generic_signature = "Lfixture/Root<Lfixture/Element;>;";
    Bound.methods.push_back(Constructor(Bound.name, Root.name));
    Input.push_back(Root);
    auto Object = klass("Ljava/lang/Object;");
    Object.superclass.reset();
    Object.external = true;
    auto Init = Constructor(Object.name, Object.name);
    Init.instructions.clear();
    Init.registers = Init.code_end = 0;
    Object.methods.push_back(Init);
    Input.push_back(Object);
  }
  return Input;
}
} // namespace

