namespace {
std::vector<Class> closedCovariantBoundResultClasses(bool SDK, bool Static,
                                                     bool InterfaceBound,
                                                     bool Range, bool Throws) {
  auto Element = klass("Lfixture/Element;");
  if (InterfaceBound)
    Element.access = {"public", "interface", "abstract"};
  auto Carrier = klass("Lfixture/Carrier;");
  Carrier.generic_signature =
      std::string("<E:") + (InterfaceBound ? ":" : "") +
      "Lfixture/Element;>Ljava/lang/Object;";
  auto Make = method("make", {"Ljava/lang/String;", "Ljava/io/OutputStream;"},
                     Carrier.name, Static ? 3 : 4,
                     {op(0, "const/4", {0}, int64_t(0)),
                      op(1, "return-object", {0})});
  Make.access = Static ? Access{"public", "static"} : Access{"public"};
  Make.generic_signature =
      "<R:Lfixture/Carrier<+Lfixture/Element;>;>"
      "(Ljava/lang/String;Ljava/io/OutputStream;)TR;";
  if (Throws)
    Make.declared_throws = {"Ljava/io/IOException;"};
  auto Factory = klass("Lfixture/Factory;", {Make});
  auto Maker = klass("Lfixture/Maker;", {Make});
  Maker.access = {"public", "interface", "abstract"};
  Maker.methods[0].access = {"public", "abstract"};
  Maker.methods[0].instructions.clear();
  Maker.methods[0].registers = Maker.methods[0].code_end = 0;
  if (!Static)
    Factory.interfaces = {Maker.name};
  const auto Parameters = Static
                              ? std::vector<std::string>{"Ljava/lang/String;",
                                                         "Ljava/io/OutputStream;"}
                              : std::vector<std::string>{Factory.name,
                                                         "Ljava/lang/String;",
                                                         "Ljava/io/OutputStream;"};
  auto Run = method(
      "run", Parameters, Carrier.name, Static ? 3 : 4,
      {op(0, std::string(Static ? "invoke-static" : "invoke-virtual") +
                 (Range ? "/range" : ""),
          Static ? std::vector<unsigned>{1, 2}
                 : std::vector<unsigned>{1, 2, 3},
          {}, Factory.methods[0].reference),
       op(3, "move-result-object", {0}), op(4, "return-object", {0})});
  auto Core = klass("Lfixture/Core;", {Run});
  auto String = klass("Ljava/lang/String;");
  auto Sink = klass("Ljava/io/OutputStream;");
  auto Throwable = klass("Ljava/lang/Throwable;");
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.superclass = Throwable.name;
  auto Checked = klass("Ljava/io/IOException;");
  Checked.superclass = Exception.name;
  std::vector<Class> Input{Core, Factory, Carrier, Element, Maker,
                           String, Sink, Throwable, Exception, Checked};
  for (size_t I = 1; I < Input.size(); ++I)
    if (SDK || I >= 5) {
      Input[I].external = true;
      for (auto &M : Input[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Input;
}
} // namespace

TEST(MobileDalvikJava, ClosedCovariantBoundResultsKeepNominalContextsAndThrows) {
  for (bool SDK : {false, true})
    for (bool Static : {false, true})
      for (bool InterfaceBound : {false, true})
        for (bool Range : {false, true})
          for (bool Throws : {false, true})
            for (unsigned Route : {0u, 1u, 2u}) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Static, InterfaceBound, Range, Throws, Route}));
              auto Input = closedCovariantBoundResultClasses(
                  SDK, Static, InterfaceBound, Range, Throws);
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              EXPECT_NO_THROW({
                const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                                     : recover(Input);
                EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
                EXPECT_FALSE(R.getArray("generic_signature_projections"));
              });
            }
  // A covariant result also keeps a caller's independent all-star formal.
  // This previously unsupported reifiable-context variant is now a complete
  // result-only contract; its caller does not supply a narrower substitution.
  for (bool SDK : {false, true})
    for (unsigned Route : {0u, 1u, 2u}) {
      SCOPED_TRACE(::testing::PrintToString(std::tuple{SDK, Route}));
      auto Input = reifiableContextResultClasses(SDK, true, true, true, false,
                                                 false, false);
      auto &Signature = *Input[1].methods[0].generic_signature;
      const auto At = Signature.find("Carrier<*>");
      ASSERT_NE(At, std::string::npos);
      Signature.replace(At, std::string("Carrier<*>").size(),
                        "Carrier<+Lfixture/Bound;>");
      if (Route == 2)
        std::reverse(Input.begin(), Input.end());
      Budget B;
      EXPECT_NO_THROW({
        const auto R = Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input);
        EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
        EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
        EXPECT_FALSE(R.getArray("generic_signature_projections"));
      });
    }
}

TEST(MobileDalvikJava, ClosedCovariantBoundResultsRejectUnprovedContracts) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = closedCovariantBoundResultClasses(SDK, false, true, true,
                                                       true);
        auto &Factory = Input[1];
        auto &Make = Factory.methods[0];
        auto &Signature = *Make.generic_signature;
        switch (Mutation) {
        case 0:
          Signature.replace(Signature.find('+'), 1, "-");
          break;
        case 1:
          Signature.replace(Signature.find('+'), 1, "");
          break;
        case 2:
          Signature.replace(Signature.find("TR;"), 3, "TX;");
          break;
        case 3:
          Signature.replace(Signature.find("Ljava/lang/String;"), 18, "TR;");
          break;
        case 4:
          Signature.insert(Signature.find(">(Ljava/lang/String;"),
                           "X:Ljava/lang/Object;");
          break;
        case 5:
          Make.declared_throws = {"Ljava/lang/Object;"};
          break;
        case 6:
          Make.access = {"private"};
          Input[0].methods[0].instructions[0].opcode = "invoke-direct/range";
          break;
        case 7:
          Make.access.insert("native");
          Make.instructions.clear();
          Make.registers = Make.code_end = 0;
          break;
        case 8:
          Make.access.insert("synthetic");
          break;
        case 9:
          Make.access.insert("varargs");
          break;
        case 10:
          Input[2].generic_signature =
              "<E::Lfixture/Missing;>Ljava/lang/Object;";
          break;
        case 11:
          Input[2].generic_signature =
              "<E::Lfixture/Element;F:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 12:
          Input[3].access = {"private", "interface", "abstract"};
          break;
        case 13:
          Signature.replace(Signature.find("+Lfixture/Element;"),
                            std::string("+Lfixture/Element;").size(), "*");
          break;
        case 14:
          Signature.insert(Signature.find(">(Ljava/lang/String;"),
                           ":Ljava/io/Serializable;");
          break;
        case 15:
          Make.generic_signature =
              "<R:Lfixture/Carrier<+Lfixture/Missing;>;>"
              "(Ljava/lang/String;Ljava/io/OutputStream;)TR;";
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> closedContextResultClasses(bool SDK, bool Static,
                                              bool Binary, bool Range,
                                              unsigned Throws,
                                              bool GenericCaller) {
  auto Carrier = klass("Lfixture/Context;");
  Carrier.generic_signature =
      Binary ? "<K:Ljava/lang/Object;V:Ljava/lang/Object;>Ljava/lang/Object;"
             : "<K:Ljava/lang/Object;>Ljava/lang/Object;";
  const std::string Context =
      Binary ? "Lfixture/Context<Ljava/lang/String;Ljava/lang/Object;>;"
             : "Lfixture/Context<Ljava/lang/String;>;";
  auto Make =
      method("make", {Carrier.name, "J"}, "Ljava/lang/Object;", Static ? 4 : 5,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Make.access = Static ? Access{"public", "static"} : Access{"public"};
  Make.generic_signature = "<R:Ljava/lang/Object;>(" + Context + "J)TR;";
  if (Throws == 1)
    Make.declared_throws = std::vector<std::string>{};
  else if (Throws == 2)
    Make.declared_throws = {"Ljava/io/IOException;"};
  else if (Throws == 3)
    Make.declared_throws = {"Ljava/io/IOException;",
                            "Ljava/lang/RuntimeException;"};
  auto Factory = klass("Lfixture/Factory;", {Make});
  const auto Parameters =
      Static ? std::vector<std::string>{Carrier.name, "J"}
             : std::vector<std::string>{Factory.name, Carrier.name, "J"};
  auto Run =
      method("run", Parameters, "Ljava/lang/Object;", Static ? 4 : 5,
             {op(0,
                 std::string(Static ? "invoke-static" : "invoke-virtual") +
                     (Range ? "/range" : ""),
                 Static ? std::vector<unsigned>{1, 2, 3}
                        : std::vector<unsigned>{1, 2, 3, 4},
                 {}, Factory.methods[0].reference),
              op(3, "move-result-object", {0}), op(4, "return-object", {0})});
  if (GenericCaller)
    Run.generic_signature = "<Q:Ljava/lang/Object;>(" +
                            std::string(Static ? "" : "Lfixture/Factory;") +
                            Context + "J)TQ;";
  auto Core = klass("Lfixture/Core;", {Run});
  auto String = klass("Ljava/lang/String;");
  auto Throwable = klass("Ljava/lang/Throwable;");
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.superclass = Throwable.name;
  auto Checked = klass("Ljava/io/IOException;");
  Checked.superclass = Exception.name;
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.superclass = Exception.name;
  auto Object = klass("Ljava/lang/Object;");
  Object.superclass.reset();
  std::vector<Class> Input{Core,      Factory, Carrier, String, Throwable,
                           Exception, Checked, Runtime, Object};
  for (size_t I = 1; I < Input.size(); ++I)
    if (SDK || I >= 3) {
      Input[I].external = true;
      for (auto &M : Input[I].methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return Input;
}
} // namespace

TEST(MobileDalvikJava, ClosedContextResultsKeepIndependentFormalsAndThrows) {
  for (bool SDK : {false, true})
    for (bool Static : {false, true})
      for (bool Binary : {false, true})
        for (bool Range : {false, true})
          for (unsigned Throws : {0u, 1u, 2u, 3u})
            for (bool GenericCaller : {false, true})
              for (unsigned Route : {0u, 1u, 2u}) {
                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    SDK, Static, Binary, Range, Throws, GenericCaller, Route}));
                auto Input = closedContextResultClasses(
                    SDK, Static, Binary, Range, Throws, GenericCaller);
                const auto Target = Input[1].methods[0].reference;
                if (Route == 2)
                  std::reverse(Input.begin(), Input.end());
                Budget B;
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                if (Route)
                  Classes = linkClasses(Input, B);
                EXPECT_NO_THROW({
                  EXPECT_TRUE(validateGenericSignatures(Classes, B)
                                  .erased_generic_invocations.contains(Target));
                  const auto R = recoverJava(Classes, B);
                  EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(R.getInteger("projected_method_count").value_or(0),
                            0);
                  EXPECT_FALSE(R.getArray("generic_signature_projections"));
                });
              }
  // These complete input contracts were formerly unsupported negatives.
  // Retain each original owner/header and prove its independent result scope.
  for (bool SDK : {false, true})
    for (bool Token : {false, true})
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(::testing::PrintToString(std::tuple{SDK, Token, Route}));
        auto Input = Token ? publicInstanceReifiableResultClasses(
                                 0, SDK, true, false, false, 1)
                           : closedInvariantSeedClasses(SDK, true, 1, false,
                                                        false, 3, false);
        auto &Target = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        if (Token) {
          Target.reference.parameters = {"Ljava/lang/Class;"};
          Call.reference.parameters[1] = "Ljava/lang/Class;";
          Target.generic_signature = "<T:Ljava/lang/Object;>(Ljava/lang/"
                                     "Class<Ljava/lang/String;>;)TT;";
        } else {
          auto &Signature = *Target.generic_signature;
          const auto At = Signature.find(">;TT;Z");
          ASSERT_NE(At, std::string::npos);
          Signature.replace(At, std::string(">;TT;Z").size(),
                            ">;Ljava/lang/Object;Z");
        }
        Call.instructions[0].reference = Target.reference;
        const auto Original = Target;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        ClassMap Classes;
        if (Route)
          Classes = linkClasses(Input, B);
        else
          for (const auto &C : Input)
            Classes.emplace(C.name, C);
        EXPECT_NO_THROW({
          const auto Plans = validateGenericSignatures(Classes, B);
          EXPECT_TRUE(
              Plans.erased_generic_invocations.contains(Original.reference));
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_FALSE(R.getArray("generic_signature_projections"));
          const auto &After = Classes.at(Original.reference.owner).methods[0];
          EXPECT_EQ(After.reference, Original.reference);
          EXPECT_EQ(After.generic_signature, Original.generic_signature);
          EXPECT_EQ(After.declared_throws, Original.declared_throws);
          EXPECT_EQ(After.access, Original.access);
        });
      }
}

TEST(MobileDalvikJava, ClosedContextResultsRejectIncompleteBindings) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 17; ++Mutation)
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            closedContextResultClasses(SDK, false, true, true, 2, false);
        auto &Make = Input[1].methods[0];
        auto &Signature = *Make.generic_signature;
        switch (Mutation) {
        case 0:
          Signature.replace(Signature.find("TR;"), 3, "TX;");
          break;
        case 1:
          Signature.insert(Signature.find(">("), "X:Ljava/lang/Object;");
          break;
        case 2:
          Signature.replace(Signature.find("Ljava/lang/String;"), 18,
                            "Ljava/lang/String;Ljava/lang/String;");
          break;
        case 3:
          Signature.insert(Signature.find("Ljava/lang/String;"), "+");
          break;
        case 4:
          Signature.replace(Signature.find("Ljava/lang/String;"), 18,
                            "Lfixture/Missing;");
          break;
        case 5:
          Input[2].generic_signature =
              "<K:Ljava/lang/Object;V:Ljava/lang/String;>Ljava/lang/Object;";
          break;
        case 6:
          Signature.insert(Signature.find("Lfixture/Context<"), "[");
          break;
        case 7:
          Make.declared_throws = {"Ljava/lang/Object;"};
          break;
        case 8:
          Make.access = {"private"};
          Input[0].methods[0].instructions[0].opcode = "invoke-direct/range";
          break;
        case 9:
          Make.access.insert("native");
          Make.instructions.clear();
          Make.registers = Make.code_end = 0;
          break;
        case 10:
          Make.access.insert("abstract");
          Input[1].access.insert("abstract");
          Make.instructions.clear();
          Make.registers = Make.code_end = 0;
          break;
        case 11:
          Make.access.insert("synthetic");
          break;
        case 12:
          Make.access.insert("varargs");
          break;
        case 13:
          Input.erase(Input.begin() + 2);
          break;
        case 14:
          Signature += "^TR;";
          break;
        case 15:
          Input[0].methods[0].instructions[0].registers = {1, 2, 3, 3};
          break;
        case 16:
          Input.pop_back();
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

std::vector<Class> conditionalArrayLengthClasses(const std::string &Array,
                                                 bool Range, bool External,
                                                 bool ReturnLength = false) {
  auto Input =
      allocationArrayLengthClasses(Array, 0, ReturnLength, Range, External);
  auto &Make = Input[0].methods[0];
  Make.registers = 4;
  Make.instructions = {op(0, "new-instance", {0}, {}, Input[1].name),
                       op(1, "array-length", {1, 3}),
                       op(2, "add-int/lit8", {1, 1}, int64_t(-2)),
                       op(3, "if-gtz", {1}, {}, {}, 7),
                       op(4, "array-length", {1, 3}),
                       op(5, "goto", {}, {}, {}, 9),
                       op(7, "array-length", {1, 3}),
                       op(8, "add-int/lit8", {1, 1}, int64_t(-2)),
                       op(9, Range ? "invoke-direct/range" : "invoke-direct",
                          {0, 1}, {}, Input[1].methods[0].reference),
                       op(10, ReturnLength ? "return" : "return-object",
                          {ReturnLength ? 1u : 0u})};
  Make.code_end = 11;
  return Input;
}

TEST(MobileDalvikJava, ConditionalArrayLengthsUseOrdinaryTypedOperations) {
  for (const auto &Array : {"[Z", "[B", "[C", "[S", "[I", "[F", "[J", "[D",
                            "[Ljava/lang/Object;", "[[I"})
    for (bool Range : {false, true})
      for (bool External : {false, true})
        for (bool ReturnLength : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Array, Range, External, ReturnLength, Route}));
            auto Input = conditionalArrayLengthClasses(Array, Range, External,
                                                       ReturnLength);
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            const auto R =
                Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            const auto Text = source(R);
            const auto New = Text.find("new fixture.Target(switch (0)");
            ASSERT_NE(New, std::string::npos);
            size_t At = 0;
            for (unsigned I = 0; I < 3; ++I) {
              At = Text.find(".length", At);
              ASSERT_NE(At, std::string::npos);
              EXPECT_LT(New, At);
              ++At;
            }
            EXPECT_EQ(Text.find(".length", At), std::string::npos);
          }
}

TEST(MobileDalvikJava,
     ConditionalArrayLengthsRejectUnprovedFramesAndReceiverExposure) {
  for (bool External : {false, true})
    for (unsigned Mutation = 0; Mutation < 21; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Mutation, Route}));
        auto Input = conditionalArrayLengthClasses("[I", true, External);
        auto &Make = Input[0].methods[0];
        auto &Code = Make.instructions;
        switch (Mutation) {
        case 0:
          Code[1].registers[1] = 0;
          break;
        case 1:
          Code[1].registers[0] = 0;
          break;
        case 2:
          Code[1].registers.pop_back();
          break;
        case 3:
          Code[1].registers.push_back(2);
          break;
        case 4:
          Code[1].registers[1] = Make.registers;
          break;
        case 5:
          Code[1].registers[0] = Make.registers;
          break;
        case 6:
          Make.reference.parameters[0] = "Ljava/lang/Object;";
          break;
        case 7:
          Make.reference.parameters[0] = "I";
          break;
        case 8:
          Code[1].registers[0] = 3;
          break;
        case 9:
          Code[3].target = 1;
          break;
        case 10:
          Code[3].target = 10;
          break;
        case 11:
          Code[8].registers[1] = 3;
          break;
        case 12:
          Code[8].registers[0] = 2;
          break;
        case 13:
          Code[1].target = 9;
          break;
        case 14:
          Code[1].targets = {9};
          break;
        case 15:
          Code[1].keys = {0};
          break;
        case 16:
          Code[1].data = {0};
          break;
        case 17:
          Code[1].element_width = 1;
          break;
        case 18:
          Input.erase(Input.begin() + 1);
          break;
        case 19:
          for (auto &Op : Code) {
            ++Op.pc;
            if (Op.target)
              ++*Op.target;
          }
          Code.insert(Code.begin(), op(0, "if-eqz", {3}, {}, {}, 2));
          ++Make.code_end;
          break;
        case 20:
          for (auto &Op : Code) {
            if (Op.pc)
              ++Op.pc;
            if (Op.target)
              ++*Op.target;
          }
          Code[1].registers[1] = 2;
          Code.insert(Code.begin() + 1, op(1, "move-object", {2, 0}));
          ++Make.code_end;
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

