TEST(MobileDalvikJava, ClosedHeadMembersRejectIncompleteContractsAndCalls) {
  for (bool SDK : {false, true})
    for (bool Interface : {false, true})
      for (unsigned Mutation = 0; Mutation < 25; ++Mutation)
        for (unsigned Route : {0u, 1u, 2u}) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{SDK, Interface, Mutation, Route}));
          auto Input =
              closedHeadMemberClasses(SDK, Interface, true, false, 2, 2);
          auto &Target = Input[1].methods[0];
          auto &Signature = *Target.generic_signature;
          auto replace = [&](std::string_view From, std::string_view To) {
            const auto At = Signature.find(From);
            ASSERT_NE(At, std::string::npos);
            Signature.replace(At, From.size(), To);
          };
          switch (Mutation) {
          case 0:
            replace("Token<TT;>", "Token<+TT;>");
            break;
          case 1:
            replace("Token<TT;>", "Token<-TT;>");
            break;
          case 2:
            replace("Key;TT;>", "Key;+TT;>");
            break;
          case 3:
            replace("Pair<Lfixture/Key;", "Pair<+Lfixture/Key;");
            break;
          case 4:
            replace("Key;TT;>", "Key;TX;>");
            break;
          case 5:
            replace("Key;TT;>", "Key;*>");
            break;
          case 6:
            replace("Lfixture/Key;TT;", "TT;TT;");
            break;
          case 7:
            Signature.insert(Signature.find(">("), "X:Ljava/lang/Object;");
            break;
          case 8:
            Input[2].generic_signature = "<E:Lfixture/Key;>Ljava/lang/Object;";
            break;
          case 9:
            Input[3].generic_signature =
                "<K:Ljava/lang/Object;V:Lfixture/Key;>Ljava/lang/Object;";
            break;
          case 10:
            Input[4].generic_signature =
                "<K:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 11:
            Input.erase(Input.begin() + 4);
            break;
          case 12:
            Input[4].access = {"private"};
            break;
          case 13:
            Input[1].generic_signature =
                "<T:Ljava/lang/Object;>Ljava/lang/Object;";
            break;
          case 14:
            Target.declared_throws = {"Lfixture/Key;"};
            break;
          case 15:
            Input[9].superclass = "Lfixture/Missing;";
            break;
          case 16:
            Target.access.insert("native");
            Target.instructions.clear();
            Target.registers = Target.code_end = 0;
            break;
          case 17:
            Target.access.insert("synthetic");
            break;
          case 18:
            Target.access.insert("varargs");
            break;
          case 19:
            Target.access.erase("public");
            Target.access.insert("protected");
            break;
          case 20:
            Signature += "^TT;";
            break;
          case 21:
            Input[0].methods[0].instructions[0].registers = {2, 2};
            break;
          case 22:
            Input[0].methods[0].instructions[0].opcode = "invoke-static/range";
            break;
          case 23:
            Input.erase(Input.begin() + 3);
            break;
          case 24:
            replace("Lfixture/Key;TT;", "Lfixture/Key;");
            break;
          }
          if (Route == 2)
            std::reverse(Input.begin(), Input.end());
          Budget B;
          EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input),
                       std::runtime_error);
        }
}

namespace {
std::vector<Class> staticFinalResourceClasses(bool SDK, bool Nested, bool Range,
                                              std::string Type,
                                              bool TwoFields) {
  auto Get = method("get", {}, Type, 0, {});
  auto Close = method("close", {}, "V", 0, {});
  Get.access = Close.access = {"public", "abstract"};
  auto Provider = klass("Lfixture/Provider;", {Get, Close});
  Provider.access = {"public", "interface", "abstract"};
  Provider.external = SDK;
  auto Factory =
      klass("Lfixture/Factory;", {method("open", {}, Provider.name, 1,
                                         {op(0, "const/4", {0}, int64_t(0)),
                                          op(1, "return-object", {0})})});
  Factory.external = SDK;
  if (SDK) {
    Factory.methods[0].instructions.clear();
    Factory.methods[0].registers = Factory.methods[0].code_end = 0;
  }
  const FieldRef Value{"Lfixture/Core;", "VALUE", Type};
  const std::string Suffix = Type == "J"   ? "-wide"
                             : Type == "I" ? ""
                                           : "-object";
  const auto Invoke = std::string("invoke-interface") + (Range ? "/range" : "");
  const MethodRef Suppress{
      "Ljava/lang/Throwable;", "addSuppressed", {"Ljava/lang/Throwable;"}, "V"};
  auto Init = method("<clinit>", {}, "V", 4,
                     {op(0, Range ? "invoke-static/range" : "invoke-static", {},
                         {}, Factory.methods[0].reference),
                      op(3, "move-result-object", {0}),
                      op(4, Invoke, {0}, {}, Provider.methods[0].reference),
                      op(7, "move-result" + Suffix, {1}),
                      op(8, "sput" + Suffix, {1}, {}, Value),
                      op(10, "if-eqz", {0}, {}, {}, 15),
                      op(12, Invoke, {0}, {}, Provider.methods[1].reference),
                      op(15, "return-void"), op(16, "move-exception", {1})});
  Init.access = {"static", "constructor"};
  if (Nested) {
    const std::vector<Instruction> Tail{
        op(17, "throw", {1}),
        op(18, "move-exception", {2}),
        op(19, "if-eqz", {0}, {}, {}, 29),
        op(21, Invoke, {0}, {}, Provider.methods[1].reference),
        op(24, "goto", {}, {}, {}, 29),
        op(25, "move-exception", {3}),
        op(26, "invoke-virtual", {1, 3}, {}, Suppress),
        op(29, "throw", {2})};
    Init.instructions.insert(Init.instructions.end(), Tail.begin(), Tail.end());
    Init.tries = {{4, 10, {{std::nullopt, 16}}},
                  {17, 18, {{std::nullopt, 18}}},
                  {21, 24, {{std::nullopt, 25}}}};
  } else {
    const std::vector<Instruction> Tail{
        op(17, "if-eqz", {0}, {}, {}, 27),
        op(19, Invoke, {0}, {}, Provider.methods[1].reference),
        op(22, "goto", {}, {}, {}, 27),
        op(23, "move-exception", {0}),
        op(24, "invoke-virtual", {1, 0}, {}, Suppress),
        op(27, "throw", {1})};
    Init.instructions.insert(Init.instructions.end(), Tail.begin(), Tail.end());
    Init.tries = {{4, 10, {{std::nullopt, 16}}},
                  {19, 22, {{std::nullopt, 23}}}};
  }
  if (TwoFields) {
    for (auto &Instruction : Init.instructions) {
      if (Instruction.pc >= 10)
        Instruction.pc += 2;
      if (Instruction.target && *Instruction.target >= 10)
        *Instruction.target += 2;
    }
    for (auto &Region : Init.tries) {
      if (Region.start >= 10)
        Region.start += 2;
      if (Region.end >= 10)
        Region.end += 2;
      for (auto &Handler : Region.handlers)
        Handler.target += 2;
    }
    Init.instructions.insert(Init.instructions.begin() + 5,
                             op(10, "sput" + Suffix, {1}, {},
                                FieldRef{Value.owner, "SECOND", Type}));
  }
  Init.code_end = Init.instructions.back().pc + 1;
  auto Core = klass(Value.owner, {Init});
  Core.fields.push_back({Value, {"public", "static", "final"}});
  if (TwoFields)
    Core.fields.push_back(
        {{Value.owner, "SECOND", Type}, {"public", "static", "final"}});
  auto Throwable = klass("Ljava/lang/Throwable;");
  auto Attach = method("addSuppressed", {Throwable.name}, "V", 0, {});
  Attach.reference = Suppress;
  Attach.access = {"public", "final"};
  Throwable.methods.push_back(Attach);
  Throwable.external = true;
  auto Object = klass("Ljava/lang/Object;");
  Object.external = true;
  Object.superclass.reset();
  return {Core, Provider, Factory, Throwable, Object};
}
} // namespace

