namespace {
std::vector<Class> arrayStarNestedMemberClasses(bool SDK, bool Interface,
                                                bool Range, bool Platform,
                                                bool Varargs, bool Context,
                                                unsigned Throws) {
  auto Input =
      closedHeadMemberClasses(SDK, Interface, Range, Platform, 0, Throws);
  auto &Factory = Input[1];
  auto &Token = Input[2];
  auto &Outer = Input[3];
  auto &Inner = Input[4];
  Outer.name = Platform ? "Ljava/util/Set;" : "Lfixture/Outer;";
  Outer.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Inner.name = "Lfixture/Box;";
  Inner.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto parameterized = [](const std::string &Owner, std::string Arguments) {
    return Owner.substr(0, Owner.size() - 1) + "<" + Arguments + ">;";
  };
  auto &Query = Factory.methods[0];
  Query.reference.parameters = {"Ljava/lang/Object;", "[" + Token.name};
  Query.reference.returns = Outer.name;
  Query.generic_signature =
      "<T:Ljava/lang/Object;>(TT;[" + parameterized(Token.name, "*") + ")" +
      parameterized(Outer.name, parameterized(Inner.name, "TT;"));
  if (Varargs)
    Query.access.insert("varargs");
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = {Factory.name, "Ljava/lang/Object;",
                               "[" + Token.name};
  Call.reference.returns = Outer.name;
  Call.instructions[0].reference = Query.reference;
  Call.instructions[0].registers = {0, 1, 2};
  Call.generic_signature =
      "<Q:Ljava/lang/Object;>(" + Factory.name + "TQ;[" +
      parameterized(Token.name, "*") + ")" +
      parameterized(Outer.name, parameterized(Inner.name, "TQ;"));
  if (Context) {
    Query.reference.parameters.insert(Query.reference.parameters.begin() + 1,
                                      "Ljava/lang/String;");
    Query.generic_signature->insert(Query.generic_signature->find("TT;[") + 3,
                                    "Ljava/lang/String;");
    if (!Query.instructions.empty())
      Query.registers = 4;
    Call.reference.parameters.insert(Call.reference.parameters.begin() + 2,
                                     "Ljava/lang/String;");
    Call.generic_signature->insert(Call.generic_signature->find("TQ;[") + 3,
                                   "Ljava/lang/String;");
    Call.instructions[0].reference = Query.reference;
    Call.instructions[0].registers = {0, 1, 2, 3};
    Call.registers = 4;
  }
  return Input;
}
} // namespace

