std::vector<Class> staticArrayStarNestedClasses(bool SDK, bool Range,
                                                bool Platform, bool Varargs,
                                                bool Context, unsigned Throws) {
  auto Input = arrayStarNestedMemberClasses(SDK, false, Range, Platform,
                                            Varargs, Context, Throws);
  auto &Query = Input[1].methods[0];
  Query.access.insert("static");
  auto &Call = Input[0].methods[0];
  Call.reference.parameters.erase(Call.reference.parameters.begin());
  const auto At = Call.generic_signature->find(Input[1].name);
  Call.generic_signature->erase(At, Input[1].name.size());
  Call.instructions[0].opcode = Range ? "invoke-static/range" : "invoke-static";
  Call.instructions[0].reference = Query.reference;
  Call.instructions[0].registers.clear();
  for (unsigned I = 0; I < Call.reference.parameters.size(); ++I)
    Call.instructions[0].registers.push_back(I + 1);
  Call.registers = Call.reference.parameters.size() + 1;
  return Input;
}
