namespace {
std::vector<Class> protectedStaticResultClasses(bool SDK, unsigned Shape,
                                                bool Range, bool Used,
                                                unsigned Scope,
                                                unsigned Throws) {
  auto Input = reifiableContextThrowsClasses(SDK, Shape % 7, Range, Used, false,
                                             false, Throws % 3);
  auto &Read = Input[0].methods[0];
  auto &Call = Input[1].methods[0];
  Read.access = {"protected", "static"};
  if (Shape == 7) {
    Read.reference.parameters = {"Ljava/lang/reflect/Type;",
                                 "Ljava/lang/Object;", "Lfixture/Config;"};
    Read.generic_signature =
        "<T:Ljava/lang/Object;>(Ljava/lang/reflect/Type;Ljava/lang/Object;"
        "Lfixture/Config;)TT;";
    if (!SDK)
      Read.registers = Read.incomingWords() + 1;
  }
  if (Throws == 3)
    Read.declared_throws.reset();
  else if (Throws == 4)
    Read.declared_throws = std::vector<std::string>{};
  Call.declared_throws = Read.declared_throws;
  Call.reference.parameters = Read.reference.parameters;
  if (Scope == 1) {
    Input[1].name = "Lother/Derived;";
    Input[1].superclass = Input[0].name;
    Call.reference.owner = Input[1].name;
  } else if (Scope == 2) {
    Input[1].access = {"public", "abstract", "interface"};
    Call.access = {"public"};
  }
  if (Used) {
    std::string Parameters;
    for (const auto &Type : Call.reference.parameters)
      Parameters += Type;
    Call.generic_signature = "<R:Ljava/lang/Object;>(" + Parameters + ")TR;";
  }
  const unsigned First = (Range ? 16 : 1) + (Scope == 2 ? 1 : 0);
  Call.registers = First + Read.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  Call.instructions = {op(0, Range ? "invoke-static/range" : "invoke-static",
                          Words, {}, Read.reference)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
  } else
    Call.instructions.push_back(op(3, "return-void"));
  Call.code_end = Call.instructions.back().pc + 1;
  if (Shape == 7) {
    auto Type = klass("Ljava/lang/reflect/Type;");
    Type.access = {"public", "abstract", "interface"};
    Type.external = true;
    auto Config = klass("Lfixture/Config;");
    Config.external = true;
    Input.push_back(Type);
    Input.push_back(Config);
  }
  return Input;
}
} // namespace

