TEST(MobileDalvikJava,
     ProtectedCarrierTokensRejectMissingRelationsRolesAccessAndFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 24; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = protectedCarrierTokenClasses(SDK, true, false, false, true,
                                                  false, false, 0, true);
        auto &Read = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &Before,
                           const std::string &After) {
          const auto At = Read.generic_signature->find(Before);
          ASSERT_NE(At, std::string::npos);
          Read.generic_signature->replace(At, Before.size(), After);
        };
        switch (Mutation) {
        case 0:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 1:
          Replace("<T:", "<U:Ljava/lang/Object;T:");
          break;
        case 2:
          Replace("Lfixture/Token<TT;>", "Lfixture/Token<TMissing;>");
          break;
        case 3:
          Replace("Lfixture/Token<TT;>", "Lfixture/Token<-TT;>");
          break;
        case 4:
          Replace("Lfixture/Token<TT;>", "Lfixture/Token<*>");
          break;
        case 5:
          Replace("Lfixture/Token<TT;>", "Lfixture/Token");
          break;
        case 6:
          Replace("Lfixture/Box<TT;>", "Lfixture/Box<+TT;>");
          break;
        case 7:
          Replace("Lfixture/Box<TT;>", "Lfixture/Box<Ljava/lang/Object;>");
          break;
        case 8:
          Input[1].generic_signature =
              "<C:Ljava/lang/Object;>Ljava/lang/Object;"
              "Lfixture/Marker<Ljava/lang/String;>;";
          break;
        case 9:
          Input[3].generic_signature =
              "<C:Ljava/lang/Object;>Ljava/lang/Object;"
              "Lfixture/Marker<Ljava/lang/String;>;";
          break;
        case 10:
          Read.access.insert("varargs");
          break;
        case 11:
          Read.access.insert("native");
          break;
        case 12:
          Read.access.insert("synthetic");
          break;
        case 13:
          Read.access = {"private", "static"};
          break;
        case 14:
          Input[0].name = "Lother/Foreign;";
          Call.reference.owner = Input[0].name;
          break;
        case 15:
          Input[1].access = {"public", "abstract", "interface"};
          break;
        case 16:
          Read.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 17:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 18:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 19: {
          Input[0].superclass = Input[1].name;
          auto Alias = Read.reference;
          Alias.owner = Input[0].name;
          Call.instructions[0].reference = Alias;
          break;
        }
        case 20:
          Call.instructions[0].registers.back() = Call.registers;
          break;
        case 21:
          Input[2].generic_signature =
              "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 22:
          Input[5].generic_signature =
              "<E:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 23:
          Input[3].superclass = "Lfixture/Missing;";
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> scopedInterfaceTokenThrowsClasses(bool SDK, bool Range,
                                                     bool Alpha, bool Abstract,
                                                     unsigned Tail,
                                                     unsigned Throws,
                                                     bool Alias, bool Used) {
  const std::string Object = "Ljava/lang/Object;", Token = "Ljava/lang/Class;",
                    K = Alpha ? "Context" : "K", T = Alpha ? "Value" : "T";
  std::vector<std::string> Parameters{Object, Token};
  std::string Suffix;
  if (Tail == 1) {
    Parameters.push_back("Z");
    Suffix = "Z";
  }
  if (Tail == 2) {
    Parameters.insert(Parameters.end(), {"Ljava/lang/String;", "J"});
    Suffix = "Ljava/lang/String;J";
  }
  auto Target = method("fetch", Parameters, Object, 0, {});
  Target.access = {"public"};
  if (Abstract)
    Target.access.insert("abstract");
  Target.generic_signature = "<" + T + ":" + Object + ">(T" + K +
                             ";Ljava/lang/Class<T" + T + ";>;" + Suffix + ")T" +
                             T + ";";
  if (Throws) {
    Target.declared_throws = std::vector<std::string>{};
    if (Throws == 2 || Throws == 4)
      Target.declared_throws->push_back("Ljava/io/IOException;");
    if (Throws == 3)
      Target.declared_throws->push_back("Ljava/lang/RuntimeException;");
    if (Throws == 4)
      Target.declared_throws->push_back("Ljava/lang/Error;");
  }
  if (!SDK && !Abstract) {
    Target.registers = Target.incomingWords() + 1;
    Target.instructions = {op(0, "const/4", {0}, int64_t(0)),
                           op(1, "return-object", {0})};
    Target.code_end = 2;
  }
  auto Api = klass("Lfixture/Api;", {Target});
  Api.access = {"public", "abstract", "interface"};
  Api.external = SDK;
  Api.interfaces = {"Lfixture/Base;"};
  Api.generic_signature =
      "<" + K + ":" + Object + ">" + Object + "Lfixture/Base<T" + K + ";>;";
  auto Call = method("read", Parameters, Used ? Object : "V", 0, {});
  Call.access = {"public"};
  Call.generic_signature = "<R:" + Object + ">(TC;Ljava/lang/Class<TR;>;" +
                           Suffix + ")" + (Used ? "TR;" : "V");
  Call.declared_throws = Target.declared_throws;
  const bool UseRange = Range || Tail == 2;
  const unsigned First = UseRange ? 16 : 1;
  Call.registers = First + Call.incomingWords();
  std::vector<unsigned> Words;
  for (unsigned I = First; I < Call.registers; ++I)
    Words.push_back(I);
  auto Ref = Api.methods[0].reference;
  if (Alias)
    Ref.owner = "Lfixture/DerivedApi;";
  Call.instructions = {
      op(0, UseRange ? "invoke-interface/range" : "invoke-interface", Words, {},
         Ref)};
  if (Used) {
    Call.instructions.push_back(op(3, "move-result-object", {0}));
    Call.instructions.push_back(op(4, "return-object", {0}));
  } else
    Call.instructions.push_back(op(3, "return-void"));
  Call.code_end = Call.instructions.back().pc + 1;
  auto Derived = klass("Lfixture/DerivedApi;", {Call});
  Derived.access = Api.access;
  Derived.interfaces = {Api.name};
  Derived.generic_signature =
      "<C:" + Object + ">" + Object + "Lfixture/Api<TC;>;";
  auto Base = klass("Lfixture/Base;");
  Base.external = true;
  Base.access = Api.access;
  Base.generic_signature = "<P:" + Object + ">" + Object;
  auto ClassClass = klass(Token);
  ClassClass.external = true;
  ClassClass.generic_signature = "<E:" + Object + ">" + Object;
  auto Root = klass(Object);
  Root.external = true;
  Root.superclass.reset();
  auto Throwable = klass("Ljava/lang/Throwable;");
  Throwable.external = true;
  auto Exception = klass("Ljava/lang/Exception;");
  Exception.external = true;
  Exception.superclass = Throwable.name;
  auto IO = klass("Ljava/io/IOException;");
  IO.external = true;
  IO.superclass = Exception.name;
  auto Runtime = klass("Ljava/lang/RuntimeException;");
  Runtime.external = true;
  Runtime.superclass = Exception.name;
  auto Error = klass("Ljava/lang/Error;");
  Error.external = true;
  Error.superclass = Throwable.name;
  auto String = klass("Ljava/lang/String;");
  String.external = true;
  return {Derived,   Api, Base,    ClassClass, Root,  Throwable,
          Exception, IO,  Runtime, Error,      String};
}
} // namespace

TEST(MobileDalvikJava,
     ScopedInterfaceTokensKeepOwnerContextMethodResultAndClosedThrows) {
  for (bool SDK : {false, true})
    for (bool Abstract : {false, true})
      for (unsigned Mode = 0; Mode < 4; ++Mode)
        for (unsigned Tail = 0; Tail < 3; ++Tail)
          for (unsigned Throws = 0; Throws < 5; ++Throws)
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Abstract, Mode, Tail, Throws, Route}));
              auto Input = scopedInterfaceTokenThrowsClasses(
                  SDK, Mode & 1, Mode & 1, Abstract, Tail, Throws, Mode & 2,
                  Mode & 2);
              const auto Original = Input;
              const auto Target = Input[1].methods[0];
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              const auto Plans = validateGenericSignatures(Classes, B);
              EXPECT_TRUE(
                  Plans.erased_generic_invocations.contains(Target.reference));
              if (Throws >= 2)
                EXPECT_TRUE(validatedClosedDeclaredThrows(
                    Classes.at(Target.reference.owner).methods[0], Plans));
              const auto Report = recoverJava(Classes, B);
              EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(Report.getInteger("projected_method_count").value_or(0),
                        0);
              EXPECT_FALSE(Report.getArray("generic_signature_projections"));
              for (const auto &C : Original) {
                const auto &After = Classes.at(C.name);
                EXPECT_EQ(After.generic_signature, C.generic_signature);
                EXPECT_EQ(After.access, C.access);
                for (size_t I = 0; I < C.methods.size(); ++I) {
                  EXPECT_EQ(After.methods[I].generic_signature,
                            C.methods[I].generic_signature);
                  EXPECT_EQ(After.methods[I].access, C.methods[I].access);
                  EXPECT_EQ(After.methods[I].declared_throws,
                            C.methods[I].declared_throws);
                }
              }
            }
}

TEST(MobileDalvikJava,
     ScopedInterfaceTokensRejectUnprovedScopesDeclarationsAndFrames) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 25; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = scopedInterfaceTokenThrowsClasses(SDK, true, false, false,
                                                       1, 2, true, true);
        auto &Read = Input[1].methods[0];
        auto &Call = Input[0].methods[0];
        auto Replace = [&](const std::string &From, const std::string &To) {
          auto At = Read.generic_signature->find(From);
          ASSERT_NE(At, std::string::npos);
          Read.generic_signature->replace(At, From.size(), To);
        };
        switch (Mutation) {
        case 0:
          Replace("Class<TT;>", "Class<TK;>");
          break;
        case 1:
          Replace(")TT;", ")TK;");
          break;
        case 2:
          Replace("(TK;", "(TMissing;");
          break;
        case 3:
          Replace("Class<TT;>", "Class<+TT;>");
          break;
        case 4:
          Replace("Class<TT;>", "Class<-TT;>");
          break;
        case 5:
          Replace("Class<TT;>", "Class<*>");
          break;
        case 6:
          Replace("Class<TT;>", "Class");
          break;
        case 7:
          Replace("<T:", "<Unused:Ljava/lang/Object;T:");
          break;
        case 8:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 9:
          Input[1].generic_signature =
              "<K:Ljava/lang/Number;>Ljava/lang/Object;Lfixture/Base<TK;>;";
          break;
        case 10:
          Input[1].generic_signature = "<K:Ljava/lang/Object;>Ljava/lang/"
                                       "Object;Lfixture/Base<TMissing;>;";
          break;
        case 11:
          Input[3].generic_signature =
              "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 12:
          Read.access.insert("static");
          break;
        case 13:
          Read.access = {"private"};
          break;
        case 14:
          Read.access.insert("native");
          break;
        case 15:
          Read.access.insert("varargs");
          break;
        case 16:
          Read.access.insert("synthetic");
          break;
        case 17:
          Read.access.insert("bridge");
          break;
        case 18:
          Read.declared_throws = {"Lfixture/Missing;"};
          break;
        case 19:
          Input[7].superclass = "Lfixture/Missing;";
          break;
        case 20:
          Input[7].superclass = Input[7].name;
          break;
        case 21:
          Call.instructions[0].opcode = "invoke-static/range";
          break;
        case 22:
          Call.instructions[0].registers.pop_back();
          break;
        case 23:
          Call.instructions[1].opcode = "move-result-wide";
          break;
        case 24:
          Replace("(TK;", "(TT;");
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

