TEST(MobileDalvikJava, ConditionalArrayArgumentsShareOrdinaryArraySemantics) {
  for (const auto &Array :
       {"[Z", "[B", "[C", "[S", "[I", "[F", "[J", "[D", "[Ljava/lang/Object;",
        "[Ljava/lang/String;", "[[I", "[[Ljava/lang/String;"})
    for (bool Range : {false, true})
      for (bool SDK : {false, true})
        for (bool ReuseLength : {false, true})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{Array, Range, SDK, ReuseLength, Route}));
            auto Input =
                conditionalArrayArgumentClasses(Array, Range, SDK, ReuseLength);
            const auto Original = Input[0].methods[0];
            if (Route == 2)
              std::reverse(Input.begin(), Input.end());
            Budget B;
            ClassMap Classes;
            if (Route)
              Classes = linkClasses(Input, B);
            else
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
            const auto R = recoverJava(Classes, B);
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_EQ(R.getInteger("minimum_java_release"), 14);
            const auto Text = source(R);
            const auto New = Text.find("new fixture.Target(switch (0)");
            ASSERT_NE(New, std::string::npos);
            const auto Call = Text.find("((fixture.Provider) null).observe(", New);
            ASSERT_NE(Call, std::string::npos);
            if ((Array[1] == 'L' || Array[1] == '[')) {
              const auto Store = Text.find("] = ", New);
              ASSERT_NE(Store, std::string::npos);
              EXPECT_LT(Store, Call);
              EXPECT_EQ(Text.find("java.lang.reflect.Array.set"),
                        std::string::npos);
            }
            const auto &After = Classes.at(Original.reference.owner).methods[0];
            EXPECT_EQ(After.reference, Original.reference);
            EXPECT_EQ(After.access, Original.access);
            EXPECT_EQ(After.declared_throws, Original.declared_throws);
          }
}

TEST(MobileDalvikJava, ConditionalArrayArgumentsRejectReceiverAndOperandDrift) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 32; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = conditionalArrayArgumentClasses("[Ljava/lang/String;",
                                                     false, SDK, false);
        auto &Make = Input[0].methods[0];
        auto &Code = Make.instructions;
        switch (Mutation) {
        case 0:
          Code[5].registers[0] = 0;
          break;
        case 1:
          Code[5].registers[1] = 0;
          break;
        case 2:
          Code[7].registers[0] = 0;
          break;
        case 3:
          Code[7].registers[1] = 0;
          break;
        case 4:
          Code[7].registers[2] = 0;
          break;
        case 5:
          Code[5].registers.pop_back();
          break;
        case 6:
          Code[5].registers.push_back(5);
          break;
        case 7:
          Code[5].reference = std::string("Ljava/lang/Object;");
          break;
        case 8:
          Code[5].literal = int64_t(7);
          break;
        case 9:
          Code[5].reference = Input[2].methods[0].reference;
          break;
        case 10:
          Code[5].registers[0] = Make.registers;
          break;
        case 11:
          Code[7].registers.pop_back();
          break;
        case 12:
          Code[7].registers.push_back(5);
          break;
        case 13:
          Code[7].reference = std::string("[Ljava/lang/String;");
          break;
        case 14:
          Code[7].literal = int64_t(1);
          break;
        case 15:
          Code[7].registers[0] = 7;
          break;
        case 16:
          Code[7].registers[1] = 8;
          break;
        case 17:
          Code[7].registers[2] = 8;
          break;
        case 18:
          Code[5].reference = std::string("[I");
          break;
        case 19:
          Code[5].target = 12;
          break;
        case 20:
          Code[7].keys = {0};
          break;
        case 21:
          Code[7].data = {0};
          break;
        case 22:
          Code[7].element_width = 1;
          break;
        case 23:
          Code[1].target = 13;
          break;
        case 24:
          Code[1].target = 1;
          break;
        case 25:
          Code[12] = op(12, "nop");
          break;
        case 26:
          for (auto &Op : Code) {
            ++Op.pc;
            if (Op.target)
              ++*Op.target;
          }
          Code.insert(Code.begin(), op(0, "if-eqz", {6}, {}, {}, 6));
          ++Make.code_end;
          break;
        case 27:
          Code[11].registers[0] = 0;
          break;
        case 28:
          Code[2].registers[1] = 0;
          break;
        case 29:
          Code[7].target = 12;
          break;
        case 30:
          Input.erase(Input.begin() + 1);
          break;
        case 31:
          Code[7].targets = {12};
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> unaryFixedCallbackCarrierClasses(bool SDK, bool Range,
                                                    unsigned Variance,
                                                    bool CustomResult,
                                                    bool Facade) {
  auto Input = binaryCallbackCarrierClasses(SDK, Range, 0, CustomResult);
  auto &Provider = Input[1];
  auto &Select = Provider.methods[0];
  const std::string Result =
      CustomResult ? "Lfixture/Token;" : "Ljava/lang/Boolean;";
  Select.generic_signature =
      std::string("<T:Ljava/lang/Object;>(Lfixture/Carrier<") +
      (Variance & 1 ? "" : "+") + "TT;>;Lfixture/Comparison<" +
      (Variance & 8   ? "+"
       : Variance & 2 ? ""
                      : "-") +
      "TT;" + (Variance & 4 ? "+" : "") + Result + ">;)Lfixture/Carrier<TT;>;";
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  Marker.generic_signature = "<R:Ljava/lang/Object;>Ljava/lang/Object;";
  Marker.external = SDK;
  Input[3].interfaces = {Marker.name};
  Input[3].generic_signature =
      "<A:Ljava/lang/Object;R:Ljava/lang/Object;>Ljava/lang/Object;"
      "Lfixture/Marker<TR;>;";
  auto &Call = Input[0].methods[0];
  if (Range) {
    Call.reference.parameters.insert(Call.reference.parameters.begin(), "J");
    Call.registers = 80;
    Call.instructions[0].registers = {78, 79};
  }
  if (Facade) {
    Provider.access.clear();
    auto Public = klass("Lfixture/Facade;");
    Public.superclass = Provider.name;
    Public.external = SDK;
    std::get<MethodRef>(Call.instructions[0].reference).owner = Public.name;
    Input.push_back(Public);
  }
  Input.push_back(Marker);
  return Input;
}
} // namespace

TEST(MobileDalvikJava, UnaryFixedCallbacksKeepInputResultAndClosedCompletion) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (unsigned Variance = 0; Variance < 16; ++Variance)
        for (bool CustomResult : {false, true})
          for (bool Facade : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              // Covariant callback inputs retain the existing recursive
              // producer proof; skip its duplicate invariant flag setting.
              if ((Variance & 8) && (Variance & 2))
                continue;
              SCOPED_TRACE(::testing::PrintToString(std::tuple{
                  SDK, Range, Variance, CustomResult, Facade, Route}));
              auto Input = unaryFixedCallbackCarrierClasses(
                  SDK, Range, Variance, CustomResult, Facade);
              const auto Original = Input[1].methods[0];
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              if (Route)
                Classes = linkClasses(Input, B);
              else
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
              EXPECT_TRUE(
                  validateGenericSignatures(Classes, B)
                      .erased_generic_invocations.contains(Original.reference));
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("projected_method_count").value_or(0), 0);
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              EXPECT_FALSE(R.getArray("class_source_bindings"));
              const auto &After =
                  Classes.at(Original.reference.owner).methods.front();
              EXPECT_EQ(After.reference, Original.reference);
              EXPECT_EQ(After.generic_signature, Original.generic_signature);
              EXPECT_EQ(After.declared_throws, Original.declared_throws);
              EXPECT_EQ(After.access, Original.access);
              const auto *Units = R.getArray("source_units");
              ASSERT_NE(Units, nullptr);
              std::string Text;
              for (size_t Index = 0; Index < Units->size(); ++Index)
                Text += source(R, Index);
              EXPECT_NE(Text.find(".select("), std::string::npos);
            }
}

TEST(MobileDalvikJava, UnaryFixedCallbacksRejectIncompleteScopedRelations) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 32; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            unaryFixedCallbackCarrierClasses(SDK, true, 0, true, false);
        auto &Call = Input[0].methods[0];
        auto &Provider = Input[1];
        auto &Select = Provider.methods[0];
        auto &Signature = *Select.generic_signature;
        auto Replace = [&](const std::string &Before,
                           const std::string &After) {
          const auto At = Signature.find(Before);
          ASSERT_NE(At, std::string::npos);
          Signature.replace(At, Before.size(), After);
        };
        switch (Mutation) {
        case 0:
          Replace("T:Ljava/lang/Object;", "T:Ljava/lang/Number;");
          break;
        case 1:
          Replace("<T:Ljava/lang/Object;>",
                  "<T:Ljava/lang/Object;U:Ljava/lang/Object;>");
          break;
        case 2:
          Replace("Carrier<+TT;", "Carrier<+TUnknown;");
          break;
        case 3:
          Replace("Carrier<+TT;", "Carrier<-TT;");
          break;
        case 4:
          Replace("Comparison<-TT;", "Comparison<[TT;");
          break;
        case 5:
          Replace(")Lfixture/Carrier<TT;>;", ")Lfixture/Carrier<+TT;>;");
          break;
        case 6:
          Replace(")Lfixture/Carrier<TT;>;", ")Lfixture/Carrier<*>;");
          break;
        case 7:
          Replace("Lfixture/Token;", "TT;");
          break;
        case 8:
          Replace("Lfixture/Token;", "-Lfixture/Token;");
          break;
        case 9:
          Replace("Lfixture/Token;", "Lfixture/Carrier;");
          break;
        case 10:
          Replace("Comparison<-TT;", "Comparison<*");
          break;
        case 11:
          Replace("Comparison<-TT;", "Comparison<-TT;-TT;");
          break;
        case 12:
          Replace("Comparison<-TT;", "Comparison<");
          break;
        case 13:
          Input[3].generic_signature =
              "<A:Ljava/lang/Number;R:Ljava/lang/Object;>Ljava/lang/Object;"
              "Lfixture/Marker<TR;>;";
          break;
        case 14:
          Input[2].generic_signature =
              "<E:Ljava/lang/Number;>Ljava/lang/Object;";
          break;
        case 15:
          Input[3].generic_signature.reset();
          break;
        case 16:
          Input[2].generic_signature.reset();
          break;
        case 17:
          Input.erase(Input.begin() + 4);
          break;
        case 18:
          Input[4].generic_signature =
              "<E:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 19:
          Input[4].access.erase("public");
          break;
        case 20:
          Input[3].access.erase("public");
          break;
        case 21:
          Select.access.insert("varargs");
          break;
        case 22:
          Select.access = {"private", "static"};
          break;
        case 23:
          Select.access.insert("abstract");
          Select.instructions.clear();
          Select.registers = Select.code_end = 0;
          break;
        case 24:
          Select.access.insert("native");
          Select.instructions.clear();
          Select.registers = Select.code_end = 0;
          break;
        case 25:
          Provider.generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 26:
          Replace("Lfixture/Token;", "Lfixture/Missing;");
          break;
        case 27:
          Call.instructions[0].registers[1] = Call.registers;
          break;
        case 28:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        case 29:
          Signature.insert(Signature.find(')'), "I");
          break;
        case 30:
          Select.reference.parameters[0] = "Ljava/lang/Object;";
          Call.instructions[0].reference = Select.reference;
          break;
        case 31:
          Call.instructions[0].registers[0] = 77;
          break;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

