namespace {
std::vector<Class> boundedStaticSelfResultClasses(bool SDK, bool High,
                                                  bool Shadow, bool Inherit,
                                                  bool Used, bool Facade) {
  auto Bound = klass("Lfixture/Bound;");
  auto ParentCtor = method(
      "<init>", {}, "V", 1,
      {op(0, "invoke-direct", {0}, {},
          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
       op(1, "return-void")});
  ParentCtor.access = {"public"};
  auto Parent = klass("Lfixture/Outer$Base;", {ParentCtor});
  Parent.access = {"public", "abstract"};
  Parent.enclosing = "Lfixture/Outer;";
  Parent.inner_class_present = true;
  Parent.inner_name = "Base";
  Parent.inner_access = {"public", "static", "abstract"};
  Parent.generic_signature = "<B:Lfixture/Bound;>Ljava/lang/Object;";
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  auto Outer = klass("Lfixture/Outer;");
  const std::string Formal = Shadow ? "T" : "MethodElement";
  auto Make = method("select", {Bound.name}, "Lfixture/Factory;", 2,
                     {op(0, "const/4", {0}, int64_t(0)),
                      op(1, "return-object", {0})});
  Make.generic_signature = "<" + Formal + ":Lfixture/Bound;>(T" + Formal +
                           ";)Lfixture/Factory<T" + Formal + ";>;";
  auto FactoryCtor = ParentCtor;
  if (Inherit)
    std::get<MethodRef>(FactoryCtor.instructions[0].reference).owner = Parent.name;
  auto Factory = klass("Lfixture/Factory;", {Make, FactoryCtor});
  Factory.interfaces = {Marker.name};
  Factory.generic_signature =
      "<T:Lfixture/Bound;>" +
      std::string(Inherit ? "Lfixture/Outer$Base<TT;>;" : "Ljava/lang/Object;") +
      "Lfixture/Marker;";
  if (Inherit)
    Factory.superclass = Parent.name;
  if (SDK)
    for (auto *C : {&Factory, &Parent})
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  auto Public = klass("Lfixture/Facade;");
  Public.superclass = Factory.name;
  for (auto *C : {&Factory, &Bound, &Parent, &Outer, &Marker, &Public})
    C->external = SDK;
  auto Ref = Factory.methods[0].reference;
  if (Facade)
    Ref.owner = Public.name;
  std::vector<Instruction> Ops{
      op(0, High ? "invoke-static/range" : "invoke-static",
         {High ? 79u : 1u}, {}, Ref)};
  if (Used) {
    Ops.push_back(op(1, "move-result-object", {0}));
    Ops.push_back(op(2, "return-object", {0}));
  } else
    Ops.push_back(op(1, "return-void"));
  auto Call = method("call", High ? std::vector<std::string>{"J", Bound.name}
                                  : std::vector<std::string>{Bound.name},
                     Used ? Factory.name : "V", High ? 80 : 2, Ops);
  return {klass("Lfixture/Core;", {Call}), Factory, Bound,
          Parent, Outer, Marker, Public};
}
} // namespace

