std::vector<Class> recursiveArrayCarrierResultClasses(bool SDK, bool Facade,
                                                      bool Range, bool Alpha,
                                                      bool Used) {
  auto Input =
      recursiveComparableExtremaClasses(SDK, Facade, Range, Alpha, false, Used);
  auto &Provider = Input[1];
  auto &Make = Provider.methods[0];
  const std::string T = Alpha ? "Element" : "T";
  Make.reference.parameters = {"[Ljava/lang/Comparable;"};
  Make.reference.returns = Input[5].name;
  Make.generic_signature = "<" + T + "::Ljava/lang/Comparable<-T" + T +
                           ";>;>([T" + T + ";)Lfixture/Box<T" + T + ";>;";
  if (!SDK)
    Make.registers = 2;
  if (Facade)
    Provider.access.clear();
  auto Ref = Make.reference;
  if (Facade)
    Ref.owner = Input[3].name;
  auto &Call = Input[0].methods[0];
  Call.reference.parameters = Ref.parameters;
  Call.reference.returns = Used ? Ref.returns : "V";
  Call.registers = Range ? 80 : 2;
  if (Range)
    Call.reference.parameters.insert(Call.reference.parameters.begin(), "J");
  Call.instructions[0] =
      op(0, Range ? "invoke-static/range" : "invoke-static",
         Range ? std::vector<unsigned>{79} : std::vector<unsigned>{1}, {}, Ref);
  return Input;
}
