namespace {
std::vector<Class> boundedFormalSuperCallClasses(bool SDK, bool Range,
                                                 bool Alpha, bool Used,
                                                 bool Null, bool Indirect) {
  const MethodRef ObjectInit{"Ljava/lang/Object;", "<init>", {}, "V"};
  auto Ctor = [&](const MethodRef &Super) {
    auto M =
        method("<init>", {}, "V", 1,
               {op(0, "invoke-direct", {0}, {}, Super), op(1, "return-void")});
    M.access = {"public", "constructor"};
    return M;
  };
  auto Object = klass(ObjectInit.owner, {Ctor(ObjectInit)});
  Object.superclass.reset();
  Object.external = true;
  Object.methods[0].instructions.clear();
  Object.methods[0].registers = Object.methods[0].code_end = 0;
  auto Bound = klass("Lfixture/Bound;", {Ctor(ObjectInit)});
  auto Leaf = klass("Lfixture/Leaf;", {Ctor(Bound.methods[0].reference)});
  Leaf.superclass = Bound.name;
  auto Context = klass("Lfixture/Context;", {Ctor(ObjectInit)});
  const std::string V = Alpha ? "Input" : "V", P = Alpha ? "Element" : "P",
                    T = Alpha ? "Value" : "T";
  auto Run = method("run", {Context.name, Bound.name, "I"}, "Z", 5,
                    {op(0, "const/4", {0}, int64_t(1)), op(1, "return", {0})});
  Run.access = {"public"};
  Run.generic_signature = "(" + Context.name + "T" + V + ";I)Z";
  auto Base = klass("Lfixture/Base;", {Ctor(ObjectInit), Run});
  Base.generic_signature = "<" + V + ":" + Bound.name + ">Ljava/lang/Object;";
  auto Parent = klass("Lfixture/Parent;", {Ctor(Base.methods[0].reference)});
  Parent.access = {"abstract"};
  Parent.superclass = Base.name;
  Parent.generic_signature =
      "<" + P + ":" + Bound.name + ">Lfixture/Base<T" + P + ";>;";
  const unsigned Self = Range ? 74 : 2;
  auto Call = method("call", {Context.name, Leaf.name, "I"}, Used ? "Z" : "V",
                     Range ? 80 : 6, {});
  Call.access = {"public"};
  Call.generic_signature = std::string("(") + (Range ? "J" : "") +
                           Context.name + "T" + T + ";I)" + (Used ? "Z" : "V");
  if (Range)
    Call.reference.parameters.insert(Call.reference.parameters.begin(), "J");
  auto Ref = Base.methods[1].reference;
  if (Indirect)
    Ref.owner = Parent.name;
  auto append = [&](Instruction I) {
    I.pc = Call.instructions.size();
    Call.instructions.push_back(std::move(I));
  };
  if (Range)
    append(op(0, "move-object/from16", {76, Self}));
  if (Null)
    append(op(0, "const/4", {Range ? 78u : 4u}, int64_t(0)));
  append(op(0, Range ? "invoke-super/range" : "invoke-super",
            Range ? std::vector<unsigned>{76, 77, 78, 79}
                  : std::vector<unsigned>{Self, 3, 4, 5},
            {}, Ref));
  if (Used)
    append(op(0, "move-result", {0}));
  append(op(0, "nop"));
  append(op(0, Used ? "return" : "return-void",
            Used ? std::vector<unsigned>{0} : std::vector<unsigned>{}));
  Call.code_end = Call.instructions.size();
  auto Child =
      klass("Lfixture/Child;", {Ctor(Parent.methods[0].reference), Call});
  Child.superclass = Parent.name;
  Child.generic_signature =
      "<" + T + ":" + Leaf.name + ">Lfixture/Parent<T" + T + ";>;";
  if (SDK)
    for (auto *C : {&Base, &Parent}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  return {Child, Parent, Base, Leaf, Bound, Context, Object};
}
} // namespace

