namespace {
std::vector<Class> packageCarrierFactoryClasses(unsigned Dependencies,
                                                bool High, bool Shadow,
                                                bool Used, bool Short) {
  auto Input = independentCarrierFactoryClasses(Dependencies, High, High,
                                                Shadow, Used, High ? 2 : 0);
  auto &Make = Input[1].methods[0];
  auto &Call = Input[0].methods[0];
  Make.access = {"static"};
  if (Short) {
    Make.reference.parameters.pop_back();
    auto &Signature = *Make.generic_signature;
    Signature.erase(Signature.find("Lfixture/Extra;"),
                    std::string("Lfixture/Extra;").size());
    if (!Input[1].external)
      --Make.registers;
    Call.reference.parameters.pop_back();
    --Call.registers;
    Call.instructions[0].registers.pop_back();
    Call.instructions[0].reference = Make.reference;
  }
  return Input;
}
} // namespace

