TEST(MobileDalvikJava,
     PackageCarrierFactoriesRejectForeignCallsAndUnprovedRoles) {
  for (unsigned Dependencies : {0u, 1u})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(::testing::PrintToString(
            std::tuple{Dependencies, Mutation, Route}));
        auto Input =
            packageCarrierFactoryClasses(Dependencies, true, false, true, true);
        auto &Factory = Input[1];
        auto &Make = Factory.methods[0];
        auto &Call = Input[0].methods[0];
        switch (Mutation) {
        case 0:
          Input[0].name = "Lforeign/Client;";
          Call.reference.owner = Input[0].name;
          break;
        case 1:
          Factory.access.clear();
          break;
        case 2:
          Make.access.insert("private");
          break;
        case 3:
          Make.access.insert("protected");
          break;
        case 4:
          Make.access.clear();
          break;
        case 5:
          Make.access.insert("native");
          break;
        case 6:
          Make.access.insert("bridge");
          break;
        case 7:
          Make.access.insert("synthetic");
          break;
        case 8:
          Make.access.insert("varargs");
          break;
        case 9:
          Make.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 10:
          Make.generic_signature->insert(1, "Unused:Ljava/lang/Object;");
          break;
        case 11:
          Make.generic_signature->replace(
              Make.generic_signature->find("Seed<TElement;>"),
              std::string("Seed<TElement;>").size(), "Seed<TS;>");
          break;
        case 12:
          Factory.generic_signature =
              "<S:Ljava/lang/Number;>Lfixture/Base<TS;>;";
          break;
        case 13:
          Input.erase(Input.begin() + 2);
          break;
        case 14:
          std::swap(Call.instructions[0].registers[1],
                    Call.instructions[0].registers[2]);
          break;
        case 15:
          Call.instructions[0].opcode = "invoke-virtual/range";
          break;
        }
        if (Mutation == 0) {
          Budget B;
          auto Classes = literalTokenConstructorInput(Input, Route, B);
          EXPECT_TRUE(validateGenericSignatures(Classes, B)
                          .erased_generic_invocations.contains(Make.reference));
          EXPECT_THROW(recoverJava(Classes, B), std::runtime_error);
        } else {
          EXPECT_THROW(([&] {
                         Budget B;
                         recoverJava(
                             literalTokenConstructorInput(Input, Route, B), B);
                       })(),
                       std::runtime_error);
        }
      }
}

namespace {
std::vector<Class> anonymousClosedParentBridgeClasses(bool SDK, bool Range,
                                                      bool Copy, bool Capture,
                                                      bool Alpha, bool Base) {
  auto Input =
      closedClassInterfaceBridgeFixture(SDK, Range, Alpha, Base, true, false);
  auto &Contract = Input[0];
  auto &Parent = Input[1];
  auto &Child = Input[2];
  const std::string Value = Input[3].name;
  const std::string Formal = Alpha ? "Item" : "Element";
  Contract.methods[0].reference.parameters = {"F", "Ljava/lang/Object;",
                                              "Ljava/lang/Object;"};
  Contract.methods[0].reference.returns = "Ljava/lang/Object;";
  Contract.methods[0].generic_signature =
      "(FT" + Formal + ";T" + Formal + ";)T" + Formal + ";";
  Child.name = "Lfixture/Host$1;";
  Child.access.clear();
  Child.inner_class_present = true;
  Child.inner_name.reset();
  Child.inner_access.clear();
  for (auto &M : Child.methods)
    M.reference.owner = Child.name;
  for (Class *Owner : {&Parent, &Child}) {
    auto &Typed = Owner->methods[Owner == &Parent ? 2 : 1];
    Typed.reference.parameters = {"F", Value, Value};
    Typed.reference.returns = Value;
    Typed.registers = 4;
    Typed.instructions = {op(0, "const/4", {0}, int64_t(0)),
                          op(1, "return-object", {0})};
    Typed.code_end = 2;
    auto &Bridge = Owner->methods[3];
    Bridge.reference.parameters = Contract.methods[0].reference.parameters;
    Bridge.reference.returns = "Ljava/lang/Object;";
    Bridge.registers = (Range ? 304 : 4) + (Copy ? 4 : 0);
    const unsigned Incoming = Bridge.registers - 4;
    const unsigned Receiver = Copy ? 0 : Incoming;
    unsigned PC = 0;
    Bridge.instructions.clear();
    if (Copy) {
      Bridge.instructions.push_back(
          op(PC++, "move-object/from16", {0, Incoming}));
      Bridge.instructions.push_back(op(PC++, "move/from16", {1, Incoming + 1}));
      Bridge.instructions.push_back(
          op(PC++, "move-object/from16", {2, Incoming + 2}));
      Bridge.instructions.push_back(
          op(PC++, "move-object/from16", {3, Incoming + 3}));
    }
    Bridge.instructions.push_back(
        op(PC++, "check-cast", {Receiver + 2}, {}, Value));
    Bridge.instructions.push_back(
        op(PC++, "check-cast", {Receiver + 3}, {}, Value));
    Bridge.instructions.push_back(
        op(PC++, Range ? "invoke-virtual/range" : "invoke-virtual",
           {Receiver, Receiver + 1, Receiver + 2, Receiver + 3}, {},
           Typed.reference));
    Bridge.instructions.push_back(op(PC++, "move-result-object", {0}));
    Bridge.instructions.push_back(op(PC++, "return-object", {0}));
    Bridge.code_end = PC;
    if (Owner->external)
      for (auto &M : Owner->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  }
  auto &Init = Child.methods[0];
  Init.access = {"constructor"};
  Init.reference.parameters = Capture
                                  ? std::vector<std::string>{"Lfixture/Host;"}
                                  : std::vector<std::string>{};
  Init.registers = Capture ? 2 : 1;
  Init.instructions.clear();
  unsigned PC = 0;
  if (Capture) {
    Field CaptureField{
        {Child.name, "this$0", "Lfixture/Host;"}, {"final", "synthetic"}, {}};
    Child.fields.push_back(CaptureField);
    Init.instructions.push_back(
        op(PC++, "iput-object", {1, 0}, {}, CaptureField.reference));
  }
  Init.instructions.push_back(op(PC++, "invoke-direct", {0}, {},
                                 MethodRef{Parent.name, "<init>", {}, "V"}));
  Init.instructions.push_back(op(PC++, "return-void"));
  Init.code_end = PC;
  auto Make = method(
      "make", {}, Parent.name, Capture ? 2 : 1,
      {op(0, "new-instance", {0}, {}, Child.name),
       op(1, "invoke-direct",
          Capture ? std::vector<unsigned>{0, 1} : std::vector<unsigned>{0}, {},
          Init.reference),
       op(2, "return-object", {0})});
  Make.reference.owner = "Lfixture/Host;";
  Make.access = Capture ? Access{"public"} : Access{"public", "static"};
  Child.enclosing_method = Make.reference;
  auto HostInit =
      method("<init>", {}, "V", 1,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
              op(1, "return-void")});
  HostInit.access = {"public", "constructor"};
  Input.push_back(klass("Lfixture/Host;", {HostInit, Make}));
  return Input;
}
} // namespace

TEST(MobileDalvikJava, AnonymousClosedParentsKeepOriginalGenericBridgeProofs) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Copy : {false, true})
        for (bool Capture : {false, true})
          for (bool Alpha : {false, true})
            for (bool Base : {false, true})
              for (unsigned Route : {0u, 1u, 2u}) {
                SCOPED_TRACE(::testing::PrintToString(
                    std::tuple{SDK, Range, Copy, Capture, Alpha, Base, Route}));
                auto Input = anonymousClosedParentBridgeClasses(
                    SDK, Range, Copy, Capture, Alpha, Base);
                const auto Target = Input[2].methods[1].reference;
                const auto Bridge = Input[2].methods[3].reference;
                const auto Dispatch = Input[0].methods[0].reference;
                if (Route == 2) {
                  std::reverse(Input.begin(), Input.end());
                  for (auto &C : Input)
                    std::reverse(C.methods.begin(), C.methods.end());
                }
                ClassMap Classes;
                for (const auto &C : Input)
                  Classes.emplace(C.name, C);
                Budget B;
                if (Route)
                  Classes = linkClasses(Input, B);
                const auto Signatures = validateGenericSignatures(Classes, B);
                ASSERT_TRUE(
                    Signatures.closed_anonymous_classes.contains(Bridge.owner));
                const auto Plan =
                    planGenericInheritance(Classes, Signatures, B);
                ASSERT_TRUE(Plan.bridges.contains(Bridge));
                EXPECT_EQ(Plan.bridges.at(Bridge).target, Target);
                EXPECT_EQ(Plan.bridges.at(Bridge).dispatch, Dispatch);
                llvm::json::Object Report;
                ASSERT_NO_THROW(Report = recoverJava(Classes, B));
                EXPECT_EQ(Report.getInteger("unrecovered_method_count"), 0);
                EXPECT_FALSE(Report.getArray("generic_signature_projections"));
              }
}

TEST(MobileDalvikJava,
     AnonymousClosedParentsRejectUnprovedScopesAndForwarders) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 20; ++Mutation)
      for (unsigned Route : {0u, 1u, 2u}) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = anonymousClosedParentBridgeClasses(SDK, false, false, true,
                                                        false, true);
        auto &Parent = Input[1];
        auto &Child = Input[2];
        auto &Bridge = Child.methods[3];
        if (Mutation == 0)
          Bridge.instructions[0].reference = std::string("Ljava/lang/Object;");
        else if (Mutation == 1)
          Bridge.instructions.erase(Bridge.instructions.begin());
        else if (Mutation == 2)
          std::swap(Bridge.instructions[2].registers[2],
                    Bridge.instructions[2].registers[3]);
        else if (Mutation == 3)
          Bridge.instructions[2].opcode = "invoke-static";
        else if (Mutation == 4)
          Bridge.instructions[2].registers.pop_back();
        else if (Mutation == 5)
          Bridge.instructions[3].opcode = "move-result";
        else if (Mutation == 6)
          Bridge.instructions.back().registers = {1};
        else if (Mutation == 7)
          Bridge.access.erase("synthetic");
        else if (Mutation == 8)
          Bridge.access.insert("static");
        else if (Mutation == 9)
          Input[0].methods[0].generic_signature =
              "(FTMissing;TMissing;)TMissing;";
        else if (Mutation == 10)
          Parent.generic_signature =
              "Lfixture/Base<Ljava/lang/String;Ljava/lang/Object;>;Lfixture/"
              "Contract<Ljava/lang/String;>;";
        else if (Mutation == 11)
          Parent.generic_signature =
              "Lfixture/Base<Ljava/lang/String;Ljava/lang/Object;>;Lfixture/"
              "Contract<+Lfixture/Leaf;>;";
        else if (Mutation == 12)
          Parent.methods[2].access.insert("final");
        else if (Mutation == 13)
          Parent.methods[2].access.insert("static");
        else if (Mutation == 14)
          Child.enclosing_method->owner = "Lfixture/Missing;";
        else if (Mutation == 15)
          Child.inner_class_present = false;
        else if (Mutation == 16) {
          Input.back().methods[1].generic_signature =
              "<Scope:Lfixture/Leaf;>()Lfixture/Fixed;";
          Child.methods[1].generic_signature = "(FTScope;TScope;)TScope;";
        } else if (Mutation == 17)
          std::get<MethodRef>(Bridge.instructions[2].reference).returns =
              "Ljava/lang/Object;";
        else if (Mutation == 18)
          Bridge.instructions[1].registers = {1};
        else
          Bridge.instructions[2].registers[1] = 2;
        EXPECT_THROW(recoverFixedSDKInterfaceBridge(std::move(Input), Route),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> intersectionConstructorWitnessClasses(bool SDK, bool Self,
                                                         bool Erased,
                                                         bool Range, bool High,
                                                         bool Nested,
                                                         bool Alpha) {
  auto Input = intersectionVoidInvocationClasses(SDK, false, false);
  auto &Host = Input[0];
  auto &Provider = Input[1];
  auto &First = Input[2];
  First.access = {"public"};
  First.external = Input[3].external = SDK;
  Host.superclass = First.name;
  Host.interfaces = {Input[3].name};
  auto Constructor =
      method("<init>", {First.name}, "V", 2,
             {op(0, "invoke-direct", {0}, {},
                 MethodRef{"Lfixture/Ancestor;", "<init>", {}, "V"}),
              op(1, "return-void")});
  Constructor.reference.owner = Provider.name;
  Constructor.access = {"public", "constructor"};
  Constructor.generic_signature =
      Alpha ? "<U:Lfixture/First;:Lfixture/Second;>(TU;)V"
            : "<T:Lfixture/First;:Lfixture/Second;>(TT;)V";
  auto Other = Constructor;
  Other.reference.parameters = {Input[3].name, First.name};
  Other.generic_signature.reset();
  Other.registers = 3;
  Provider.methods = {Constructor, Other};
  Provider.superclass = "Lfixture/Ancestor;";
  if (SDK)
    for (auto &M : Provider.methods) {
      M.access.erase("constructor"); // JVM classfiles identify it by <init>.
      M.instructions.clear();
      M.registers = M.code_end = 0;
    }
  const auto Target = Constructor.reference;
  auto AncestorInit = Constructor;
  AncestorInit.reference.parameters.clear();
  AncestorInit.generic_signature.reset();
  AncestorInit.instructions.clear();
  AncestorInit.registers = AncestorInit.code_end = 0;
  auto AncestorOther = AncestorInit;
  AncestorOther.reference.parameters = {Host.name};
  auto Ancestor = klass("Lfixture/Ancestor;", {AncestorInit, AncestorOther});
  Ancestor.external = true;
  auto SinkInit = AncestorInit;
  SinkInit.reference.parameters = {Provider.name};
  auto Sink = klass("Lfixture/Sink;", {SinkInit});
  Sink.external = true;
  auto &Run = Host.methods[0];
  Run.access = {"public"};
  if (!Self)
    Run.access.insert("static");
  Run.reference.parameters =
      Self ? std::vector<std::string>{} : std::vector<std::string>{Host.name};
  Run.reference.returns = Nested ? Sink.name : Provider.name;
  const unsigned Base = High ? 80 : 0;
  Run.registers = Base + 6;
  Run.instructions.clear();
  if (Nested)
    Run.instructions.push_back(
        op(0, "new-instance", {Base + 2}, {}, Sink.name));
  Run.instructions.push_back(op(0, "new-instance", {Base}, {}, Provider.name));
  Run.instructions.push_back(op(0, "move-object", {Base + 1, Base + 5}));
  if (Erased)
    Run.instructions.push_back(op(0, "check-cast", {Base + 1}, {}, First.name));
  Run.instructions.push_back(op(0,
                                Range ? "invoke-direct/range" : "invoke-direct",
                                {Base, Base + 1}, {}, Target));
  if (Nested) {
    Run.instructions.push_back(op(0, "move-object", {Base + 3, Base}));
    Run.instructions.push_back(
        op(0, Range ? "invoke-direct/range" : "invoke-direct",
           {Base + 2, Base + 3}, {}, Sink.methods[0].reference));
  }
  Run.instructions.push_back(
      op(0, "return-object", {Nested ? Base + 2 : Base}));
  for (size_t I = 0; I < Run.instructions.size(); ++I)
    Run.instructions[I].pc = I;
  Run.code_end = Run.instructions.size();
  Input.push_back(std::move(Ancestor));
  Input.push_back(std::move(Sink));
  return Input;
}
} // namespace

TEST(MobileDalvikJava,
     IntersectionConstructorsKeepOriginalWitnessAndAllocation) {
  for (bool SDK : {false, true})
    for (bool Self : {false, true})
      for (bool Erased : {false, true})
        for (bool Range : {false, true})
          for (bool High : {false, true})
            for (bool Nested : {false, true})
              for (bool Alpha : {false, true})
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(std::tuple{
                      SDK, Self, Erased, Range, High, Nested, Alpha, Route}));
                  auto Input = intersectionConstructorWitnessClasses(
                      SDK, Self, Erased, Range, High, Nested, Alpha);
                  const auto Ref = Input[1].methods[0].reference;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  Budget B;
                  ClassMap Classes;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  if (Route)
                    Classes = linkClasses(Input, B);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  ASSERT_TRUE(Plans.intersection_invocations.contains(Ref));
                  const auto &Proof = Plans.intersection_invocations.at(Ref);
                  EXPECT_EQ(Proof.parameter_index, 0u);
                  EXPECT_EQ(Proof.bounds,
                            (std::vector<std::string>{"Lfixture/First;",
                                                      "Lfixture/Second;"}));
                  EXPECT_FALSE(Plans.erased_generic_invocations.contains(Ref));
                  const auto Result = recoverJava(Classes, B);
                  EXPECT_EQ(Result.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(
                      Result.getInteger("projected_method_count").value_or(0),
                      0);
                  std::string Source;
                  for (const auto &Unit : *Result.getArray("source_units"))
                    if (Unit.getAsObject()->getString("class") ==
                        "Lfixture/Host;")
                      Source = Unit.getAsObject()->getString("source")->str();
                  EXPECT_NE(Source.find("((fixture.Host)"), std::string::npos);
                  EXPECT_NE(Source.find("new fixture.Provider("),
                            std::string::npos);
                }
}

TEST(MobileDalvikJava,
     IntersectionConstructorsRejectUnprovedWordsAndOverloads) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 19; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = intersectionConstructorWitnessClasses(
            SDK, false, Mutation != 18, true, true, Mutation != 18, false);
        auto &Run = Input[0].methods[0];
        auto &Constructor = Input[1].methods[0];
        auto &Call = Run.instructions[Mutation == 18 ? 2 : 4];
        if (Mutation == 0)
          Input[0].interfaces.clear();
        else if (Mutation == 1)
          Run.reference.parameters[0] = "Lfixture/First;";
        else if (Mutation == 2)
          Constructor.generic_signature =
              "<T:Lfixture/First;:Lfixture/Missing;>(TT;)V";
        else if (Mutation == 3)
          Constructor.generic_signature =
              "<T:Lfixture/First;:Lfixture/Second;>(TMissing;)V";
        else if (Mutation == 4)
          Constructor.generic_signature =
              "<T:Lfixture/First;:Lfixture/Second;U:Ljava/lang/Object;>(TT;)V";
        else if (Mutation == 5)
          Constructor.access.insert("varargs");
        else if (Mutation == 6)
          Constructor.declared_throws = {"Ljava/lang/Exception;"};
        else if (Mutation == 7)
          Call.registers[1] = Call.registers[0];
        else if (Mutation == 8)
          Call.registers.pop_back();
        else if (Mutation == 9) {
          auto Other = Input[1].methods[1];
          Other.reference.parameters = {Input[0].name};
          if (!SDK)
            Other.registers = 2;
          Input[1].methods.push_back(Other);
        } else if (Mutation == 10) {
          Input[1].methods[1].reference.parameters[1] = "[Lfixture/First;";
          Input[1].methods[1].access.insert("varargs");
        } else if (Mutation == 11)
          Call.opcode = "invoke-virtual/range";
        else if (Mutation == 12)
          Constructor.generic_signature =
              "<T:Lfixture/First<Ljava/lang/String;>;:Lfixture/Second;>(TT;)V";
        else if (Mutation == 13)
          Constructor.generic_signature =
              "<T:Lfixture/First;:Lfixture/Second;>(TT;)V^TT;";
        else if (Mutation == 14)
          Constructor.access.erase("public");
        else if (Mutation == 15)
          Input[3].access.erase("public");
        else if (Mutation == 16)
          Input[0].enclosing = "Lfixture/Ancestor;";
        else if (Mutation == 17)
          Constructor.access.insert("static");
        else {
          auto Init = method("<init>", {}, "V", 0, {});
          Init.reference.owner = Input[2].name;
          Init.access = {"public", "constructor"};
          Input[2].external = true;
          Input[2].methods.push_back(Init);
          Run.reference.name = "<init>";
          Run.reference.returns = "V";
          Run.access = {"public", "constructor"};
          Run.instructions.pop_back();
          Run.instructions.push_back(
              op(3, "invoke-direct", {84}, {}, Init.reference));
          Run.instructions.push_back(op(4, "return-void"));
          Run.code_end = 5;
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        if (Mutation == 18) {
          try {
            Route ? recoverJava(linkClasses(Input, B), B) : recover(Input);
            ADD_FAILURE() << "Unproved constructor prefix was accepted";
          } catch (const std::runtime_error &Error) {
            EXPECT_NE(std::string(Error.what())
                          .find("constructor prefix allocation lacks its "
                                "intersection argument witness"),
                      std::string::npos);
          }
        } else
          EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                             : recover(Input),
                       std::runtime_error);
      }
}

namespace {
std::vector<Class> seededCarrierConstructorClasses(bool SDK, bool Self,
                                                   bool SeedFirst,
                                                   unsigned Scalar, bool Range,
                                                   bool Recursive, bool Nested,
                                                   bool Alpha) {
  auto Token = klass("Lfixture/Token;");
  Token.access = {"public", "abstract"};
  Token.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  Token.external = SDK;
  const std::string ScalarType = Scalar == 2 ? "D" : "F";
  std::vector<std::string> Parameters{"Ljava/lang/Object;", Token.name};
  std::string Arguments = "TT;Lfixture/Token<TT;>;";
  if (!SeedFirst) {
    std::reverse(Parameters.begin(), Parameters.end());
    Arguments = "Lfixture/Token<TT;>;TT;";
  }
  if (Scalar) {
    Parameters.push_back(ScalarType);
    Arguments += ScalarType;
  }
  unsigned Words = 0;
  for (const auto &P : Parameters)
    Words += width(P);
  auto Init = method("<init>", Parameters, "V", Words + 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(1, "return-void")});
  Init.generic_signature = "<T:Ljava/lang/Object;>(" + Arguments + ")V";
  Init.access = {"public", "constructor"};
  auto Provider = klass("Lfixture/Provider;", {Init});
  auto Parent = klass("Lfixture/Parent;", {Init});
  Parent.access = {"public", "abstract"};
  Parent.methods[0].access.erase("public");
  if (Recursive) {
    Parent.generic_signature = "<P:Lfixture/Parent<TP;>;>Ljava/lang/Object;";
    Provider.generic_signature = "Lfixture/Parent<Lfixture/Provider;>;";
    Provider.superclass = Parent.name;
    std::vector<unsigned> Forward;
    for (unsigned I = 0; I <= Words; ++I)
      Forward.push_back(I);
    Provider.methods[0].instructions[0] =
        op(0, "invoke-direct/range", Forward, {}, Parent.methods[0].reference);
  }
  if (Alpha) {
    std::string Text = *Provider.methods[0].generic_signature;
    for (size_t At = 0; (At = Text.find("TT;", At)) != std::string::npos;)
      Text.replace(At, 3, "TU;");
    Text.replace(1, 1, "U");
    Provider.methods[0].generic_signature = Text;
  }
  auto Other = method("<init>", {}, "V", 1,
                      {op(0, "invoke-direct", {0}, {},
                          MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                       op(1, "return-void")});
  Other.access = {"public", "constructor"};
  Other.reference.owner = Parent.name;
  Parent.methods.push_back(Other);
  Other.reference.owner = Provider.name;
  if (Recursive)
    Other.instructions[0].reference = Parent.methods.back().reference;
  Provider.methods.push_back(Other);
  Provider.external = Parent.external = SDK;
  if (SDK)
    for (auto *C : {&Provider, &Parent})
      for (auto &M : C->methods) {
        M.access.erase("constructor");
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
  auto SinkInit = Other;
  SinkInit.reference.parameters = {Provider.name};
  SinkInit.instructions.clear();
  SinkInit.registers = SinkInit.code_end = 0;
  auto Sink = klass("Lfixture/Sink;", {SinkInit});
  Sink.external = true;
  auto Host = klass("Lfixture/Host;");
  Host.generic_signature = "<S:Ljava/lang/Object;>Ljava/lang/Object;";
  Field Current;
  Current.reference = {Host.name, "current", Token.name};
  Current.access = {"public", "static"};
  Host.fields.push_back(Current);
  std::vector<std::string> Inputs;
  if (!Self)
    Inputs = {"Ljava/lang/Object;", Token.name};
  if (Scalar)
    Inputs.push_back(ScalarType);
  const unsigned Base = Range ? 80 : 0;
  auto Run =
      method("run", Inputs, Nested ? Sink.name : Provider.name, Base + 16, {});
  if (Self)
    Run.access.erase("static");
  const auto First = Run.registers - Run.incomingWords();
  const auto Seed = Base + (SeedFirst ? 1 : 2);
  const auto Carrier = Base + (SeedFirst ? 2 : 1);
  if (Nested)
    Run.instructions.push_back(
        op(0, "new-instance", {Base + 5}, {}, Sink.name));
  Run.instructions.push_back(op(0, "new-instance", {Base}, {}, Provider.name));
  Run.instructions.push_back(op(0, "move-object", {Seed, First}));
  Run.instructions.push_back(
      Self ? op(0, "sget-object", {Carrier}, {}, Current.reference)
           : op(0, "move-object", {Carrier, First + 1}));
  if (Scalar)
    Run.instructions.push_back(op(0, Scalar == 2 ? "move-wide" : "move",
                                  {Base + 3, First + (Self ? 1u : 2u)}));
  std::vector<unsigned> Registers;
  for (unsigned I = 0; I <= Words; ++I)
    Registers.push_back(Base + I);
  Run.instructions.push_back(op(0,
                                Range ? "invoke-direct/range" : "invoke-direct",
                                Registers, {}, Provider.methods[0].reference));
  if (Nested) {
    Run.instructions.push_back(op(0, "move-object", {Base + 6, Base}));
    Run.instructions.push_back(
        op(0, Range ? "invoke-direct/range" : "invoke-direct",
           {Base + 5, Base + 6}, {}, Sink.methods[0].reference));
  }
  Run.instructions.push_back(
      op(0, "return-object", {Base + (Nested ? 5u : 0u)}));
  for (size_t I = 0; I < Run.instructions.size(); ++I)
    Run.instructions[I].pc = I;
  Run.reference.owner = Host.name;
  Run.code_end = Run.instructions.size();
  Host.methods.push_back(Run);
  return {Host, Provider, Token, Parent, Sink};
}
} // namespace

TEST(MobileDalvikJava, SeededCarrierConstructorsKeepMethodScopeAndArguments) {
  for (bool SDK : {false, true})
    for (bool Self : {false, true})
      for (bool SeedFirst : {false, true})
        for (unsigned Scalar = 0; Scalar < 3; ++Scalar)
          for (bool Range : {false, true})
            for (bool Recursive : {false, true})
              for (bool Nested : {false, true})
                for (unsigned Route = 0; Route < 3; ++Route) {
                  SCOPED_TRACE(::testing::PrintToString(
                      std::tuple{SDK, Self, SeedFirst, Scalar, Range, Recursive,
                                 Nested, Route}));
                  auto Input = seededCarrierConstructorClasses(
                      SDK, Self, SeedFirst, Scalar, Range, Recursive, Nested,
                      Route == 2);
                  const auto Ref = Input[1].methods[0].reference;
                  if (Route == 2)
                    std::reverse(Input.begin(), Input.end());
                  ClassMap Classes;
                  Budget B;
                  for (const auto &C : Input)
                    Classes.emplace(C.name, C);
                  if (Route)
                    Classes = linkClasses(Input, B);
                  const auto Plans = validateGenericSignatures(Classes, B);
                  ASSERT_TRUE(Plans.erased_generic_invocations.contains(Ref));
                  EXPECT_FALSE(Plans.intersection_invocations.contains(Ref));
                  const auto Result = recoverJava(Classes, B);
                  EXPECT_EQ(Result.getInteger("unrecovered_method_count"), 0);
                  EXPECT_EQ(
                      Result.getInteger("projected_method_count").value_or(0),
                      0);
                }
}

TEST(MobileDalvikJava,
     SeededCarrierConstructorsRejectIncompleteInputContracts) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 16; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input = seededCarrierConstructorClasses(SDK, false, true, 2, true,
                                                     true, true, false);
        auto &Init = Input[1].methods[0];
        auto Signature = *Init.generic_signature;
        if (Mutation == 0)
          Signature = "<T:Ljava/lang/Object;>(TMissing;Lfixture/Token<TT;>;D)V";
        else if (Mutation == 1)
          Signature = "<T:Ljava/lang/Object;>(TT;Lfixture/Token<+TT;>;D)V";
        else if (Mutation == 2)
          Signature = "<T:Ljava/lang/Object;>(TT;Lfixture/Token<-TT;>;D)V";
        else if (Mutation == 3)
          Signature = "<T:Ljava/lang/Object;>(TT;Lfixture/Token<*>;D)V";
        else if (Mutation == 4)
          Signature = "<T:Ljava/lang/Object;>(TT;Lfixture/Token<Ljava/lang/"
                      "Object;>;D)V";
        else if (Mutation == 5)
          Signature = "<T:Ljava/lang/String;>(TT;Lfixture/Token<TT;>;D)V";
        else if (Mutation == 6)
          Input[2].generic_signature =
              "<E:Ljava/lang/String;>Ljava/lang/Object;";
        else if (Mutation == 7)
          Input[1].generic_signature =
              "<T:Ljava/lang/Object;>Lfixture/Parent<Lfixture/Provider<TT;>;>;";
        else if (Mutation == 8)
          Init.access.erase("public");
        else if (Mutation == 9)
          Init.declared_throws = {"Ljava/io/IOException;"};
        else if (Mutation == 10)
          Signature += "^TT;";
        else if (Mutation == 11)
          Signature = "<T:Ljava/lang/Object;U:Ljava/lang/Object;>(TT;Lfixture/"
                      "Token<TU;>;D)V";
        else if (Mutation == 12)
          Init.access.insert("static");
        else if (Mutation == 13)
          Init.access.insert("varargs");
        else if (Mutation == 14)
          Input[2].generic_signature.reset();
        else {
          auto &Run = Input[0].methods[0];
          auto Call =
              std::find_if(Run.instructions.begin(), Run.instructions.end(),
                           [&](const Instruction &I) {
                             const auto *Ref =
                                 std::get_if<MethodRef>(&I.reference);
                             return Ref && *Ref == Init.reference;
                           });
          ASSERT_NE(Call, Run.instructions.end());
          Call->registers.back() = Call->registers[Call->registers.size() - 2];
        }
        Init.generic_signature = Signature;
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class> packageBoundScalarClasses(bool SDK, bool Public,
                                             const std::string &Result,
                                             bool Range, bool Inherited,
                                             bool Alpha) {
  auto Bound = klass("Lfixture/Bound;");
  Bound.external = SDK;
  auto Read = method("read", {Bound.name}, Result, 0, {});
  Read.access = {"abstract"};
  if (Public)
    Read.access.insert("public");
  const std::string Formal = Alpha ? "U" : "T";
  Read.generic_signature =
      "<" + Formal + ":Lfixture/Bound;>(T" + Formal + ";)" + Result;
  auto Provider = klass("Lfixture/Provider;", {Read});
  Provider.access = {"abstract"};
  if (Public)
    Provider.access.insert("public");
  Provider.external = SDK;
  auto Child = klass("Lfixture/Child;");
  Child.access = {"public", "abstract"};
  Child.superclass = Provider.name;
  Child.external = SDK;
  auto Ref = Provider.methods[0].reference;
  if (Inherited)
    Ref.owner = Child.name;
  const unsigned Base = Range ? 80 : 0;
  const bool Wide = width(Result) == 2;
  auto Run =
      method("run", {Ref.owner, Bound.name}, Result, Base + 10,
             {op(0, Range ? "invoke-virtual/range" : "invoke-virtual",
                 {Base + 8, Base + 9}, {}, Ref),
              op(1, Wide ? "move-result-wide" : "move-result", {Base + 2}),
              op(2, Wide ? "return-wide" : "return", {Base + 2})});
  Run.access.erase("static");
  Run.generic_signature = "(" + Ref.owner + "TT;)" + Result;
  auto Host = klass("Lfixture/Host;", {Run});
  Host.generic_signature = "<T:Lfixture/Bound;>Ljava/lang/Object;";
  return {Host, Provider, Bound, Child};
}
} // namespace

TEST(MobileDalvikJava, PackageBoundScalarCallsKeepAbstractDispatchAndScope) {
  for (bool SDK : {false, true})
    for (bool Public : {false, true})
      for (const std::string Result : {"Z", "B", "S", "C", "I", "J", "F", "D"})
        for (bool Range : {false, true})
          for (bool Inherited : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{SDK, Public, Result, Range, Inherited, Route}));
              auto Input = packageBoundScalarClasses(SDK, Public, Result, Range,
                                                     Inherited, Route == 2);
              const auto Ref = Input[1].methods[0].reference;
              if (Route == 2)
                std::reverse(Input.begin(), Input.end());
              Budget B;
              ClassMap Classes;
              for (const auto &C : Input)
                Classes.emplace(C.name, C);
              if (Route)
                Classes = linkClasses(Input, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.erased_generic_invocations.contains(Ref));
              const auto Recovery = recoverJava(Classes, B);
              EXPECT_EQ(Recovery.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(
                  Recovery.getInteger("projected_method_count").value_or(0), 0);
              for (const auto &M : *Recovery.getArray("methods"))
                if (M.getAsObject()->getString("identity") == Ref.identity())
                  EXPECT_EQ(M.getAsObject()->getString("status"),
                            "declaration-only");
            }
}

TEST(MobileDalvikJava, PackageBoundScalarCallsRejectUnprovedDeclarations) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 17; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            packageBoundScalarClasses(SDK, false, "I", true, false, false);
        auto &Read = Input[1].methods[0];
        if (Mutation == 0)
          Read.generic_signature = "<T:Lfixture/Bound;>(TMissing;)I";
        else if (Mutation == 1)
          Read.generic_signature = "<T:Ljava/lang/Object;>(TT;)I";
        else if (Mutation == 2)
          Read.generic_signature =
              "<T:Lfixture/Bound;U:Ljava/lang/Object;>(TT;)I";
        else if (Mutation == 3)
          Read.generic_signature =
              "<T:Lfixture/Bound;:Ljava/io/Serializable;>(TT;)I";
        else if (Mutation == 4)
          Read.generic_signature = "<T:Lfixture/Bound;>(TT;)V";
        else if (Mutation == 5)
          Read.generic_signature = "<T:Lfixture/Bound;>(TT;)I^TT;";
        else if (Mutation == 6)
          Read.generic_signature = "<T:Lfixture/Missing;>(TT;)I";
        else if (Mutation == 7)
          Input[1].generic_signature =
              "<T:Ljava/lang/Object;>Ljava/lang/Object;";
        else if (Mutation == 8)
          Read.access.insert("native");
        else if (Mutation == 9)
          Read.access.insert("static");
        else if (Mutation == 10)
          Read.access.insert("final");
        else if (Mutation == 11)
          Read.access.insert("varargs");
        else if (Mutation == 12)
          Read.access.insert("synthetic");
        else if (Mutation == 13)
          Read.access.insert("private");
        else if (Mutation == 14) {
          Input[0].name = "Lother/Host;";
          Input[0].methods[0].reference.owner = Input[0].name;
        } else if (Mutation == 15)
          Input[0].methods[0].instructions[0].registers.pop_back();
        else {
          auto Foreign = Input[0];
          Foreign.name = "Lother/Host;";
          Foreign.methods[0].reference.owner = Foreign.name;
          Input.push_back(std::move(Foreign));
        }
        if (Route == 2)
          std::reverse(Input.begin(), Input.end());
        Budget B;
        EXPECT_THROW(Route ? recoverJava(linkClasses(Input, B), B)
                           : recover(Input),
                     std::runtime_error);
      }
}

namespace {
std::vector<Class>
closedVisibilityParameterBridgeClasses(bool SDK, bool Range, bool Context,
                                       const std::string &Returns, bool Alpha) {
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(3, "return-void", {})});
  Init.access = {"public", "constructor"};
  auto Root = klass("Lfixture/Root;", {Init});
  auto First = klass("Lfixture/First;");
  First.access = {"public", "interface", "abstract"};
  First.generic_signature = "<E:Ljava/lang/Object;>Ljava/lang/Object;";
  auto Second = First;
  Second.name = "Lfixture/Second;";
  auto Left = klass("Lfixture/Child$Left;");
  Left.access = {"public", "interface", "abstract"};
  Left.enclosing = "Lfixture/Child;";
  Left.inner_class_present = true;
  Left.inner_name = "Left";
  Left.inner_access = {"public", "static", "interface", "abstract"};
  Left.interfaces = {First.name};
  Left.generic_signature = "Ljava/lang/Object;Lfixture/First<Lfixture/Child;>;";
  auto Right = Left;
  Right.name = "Lfixture/Child$Right;";
  Right.inner_name = "Right";
  Right.interfaces = {Second.name};
  Right.generic_signature =
      "Ljava/lang/Object;Lfixture/Second<Lfixture/Child;>;";
  const bool Void = Returns == "V", Wide = width(Returns) == 2;
  const bool Reference = Returns.starts_with('L');
  std::vector<std::string> Parameters{First.name};
  if (Context)
    Parameters.push_back("J");
  auto Read = method("read", Parameters, Returns, 6, {});
  Read.access = {"public"};
  Read.generic_signature =
      std::string("(TA;") + (Context ? "J" : "") + ")" + Returns;
  Read.instructions =
      Void ? std::vector<Instruction>{op(0, "return-void")}
           : std::vector<Instruction>{
                 op(0, Wide ? "const-wide/16" : "const/4", {0}, int64_t(0)),
                 op(1,
                    Reference ? "return-object"
                    : Wide    ? "return-wide"
                              : "return",
                    {0})};
  Read.code_end = Void ? 1 : 2;
  auto Base = klass("Lfixture/Base;", {Read, Init});
  Base.access = {"abstract"};
  Base.superclass = Root.name;
  Base.methods[1].instructions[0].reference = Root.methods[0].reference;
  Base.generic_signature = "<S:Lfixture/Base<TS;TA;TB;>;A::Lfixture/First<TS;>;"
                           "B::Lfixture/Second<TS;>;>Lfixture/Root;";
  auto Bridge = Base.methods[0];
  Bridge.generic_signature.reset();
  Bridge.access = {"public", "bridge", "synthetic"};
  Bridge.registers = Range ? 80 : 5;
  Bridge.parameter_metadata = std::vector<ParameterMetadata>(
      Parameters.size(), ParameterMetadata{std::nullopt, 0x1000});
  std::vector<unsigned> Words;
  for (unsigned R = Bridge.registers - Bridge.incomingWords();
       R < Bridge.registers; ++R)
    Words.push_back(R);
  Bridge.instructions = {op(0, Range ? "invoke-super/range" : "invoke-super",
                            Words, {}, Base.methods[0].reference)};
  if (!Void)
    Bridge.instructions.push_back(op(3,
                                     Reference ? "move-result-object"
                                     : Wide    ? "move-result-wide"
                                               : "move-result",
                                     {0}));
  Bridge.instructions.push_back(
      op(Void ? 3 : 4,
         Void        ? "return-void"
         : Reference ? "return-object"
         : Wide      ? "return-wide"
                     : "return",
         Void ? std::vector<unsigned>{} : std::vector<unsigned>{0}));
  Bridge.code_end = Void ? 4 : 5;
  auto Child = klass("Lfixture/Child;", {Bridge, Init});
  Child.superclass = Base.name;
  Child.methods[1].instructions[0].reference = Base.methods[1].reference;
  Child.generic_signature = "Lfixture/Base<Lfixture/Child;Lfixture/"
                            "Child$Left;Lfixture/Child$Right;>;";
  if (Alpha) {
    auto Rename = [](std::string Text) {
      for (const auto &[From, To] :
           std::vector<std::pair<std::string, std::string>>{{"TS;", "TX;"},
                                                            {"TA;", "TY;"},
                                                            {"TB;", "TZ;"},
                                                            {"S:", "X:"},
                                                            {"A:", "Y:"},
                                                            {"B:", "Z:"}})
        for (size_t At = 0; (At = Text.find(From, At)) != std::string::npos;
             At += To.size())
          Text.replace(At, From.size(), To);
      return Text;
    };
    Base.generic_signature = Rename(*Base.generic_signature);
    Base.methods[0].generic_signature =
        Rename(*Base.methods[0].generic_signature);
  }
  if (SDK)
    for (auto *C : {&Root, &First, &Second, &Base}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  auto Inputs = Parameters;
  Inputs[0] = Left.name;
  Inputs.insert(Inputs.begin(), Child.name);
  auto Invoke = Child.methods[0];
  Invoke.reference.parameters = Inputs;
  Invoke.reference.name = "call";
  Invoke.access = {"public", "static"};
  Invoke.parameter_metadata.reset();
  Invoke.instructions[0].opcode =
      Range ? "invoke-virtual/range" : "invoke-virtual";
  Invoke.instructions[0].reference = Child.methods[0].reference;
  auto Caller = klass("Lfixture/Caller;", {Invoke});
  return {Child, Base, Root, First, Second, Left, Right, Caller};
}
} // namespace

TEST(MobileDalvikJava,
     ClosedVisibilityParameterBridgesReuseCompleteClassScope) {
  for (bool SDK : {false, true})
    for (bool Range : {false, true})
      for (bool Context : {false, true})
        for (const std::string Returns :
             {"V", "Z", "I", "J", "D", "Ljava/lang/Object;"})
          for (unsigned Route = 0; Route < 3; ++Route) {
            SCOPED_TRACE(::testing::PrintToString(
                std::tuple{SDK, Range, Context, Returns, Route}));
            auto Input = closedVisibilityParameterBridgeClasses(
                SDK, Range, Context, Returns, Route == 2);
            const auto Ref = Input[0].methods[0].reference;
            const auto Target = Input[1].methods[0].reference;
            Budget B;
            auto Classes = literalTokenConstructorInput(Input, Route, B);
            const auto Plans = validateGenericSignatures(Classes, B);
            ASSERT_TRUE(Plans.public_superclass_access_bridges.contains(Ref));
            const auto &Proof = Plans.public_superclass_access_bridges.at(Ref);
            EXPECT_TRUE(Proof.regenerate_public_access);
            EXPECT_EQ(Proof.target, Target);
            llvm::json::Object R;
            ASSERT_NO_THROW(R = recoverJava(Classes, B));
            EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
            EXPECT_EQ(R.getInteger("projected_method_count"), 1);
            EXPECT_FALSE(R.getArray("generic_signature_projections"));
            EXPECT_FALSE(R.getArray("class_source_bindings"));
          }
}

TEST(MobileDalvikJava,
     ClosedVisibilityParameterBridgesRejectChangedBridgeContracts) {
  for (bool SDK : {false, true})
    for (unsigned Mutation = 0; Mutation < 22; ++Mutation)
      for (unsigned Route = 0; Route < 3; ++Route) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{SDK, Mutation, Route}));
        auto Input =
            closedVisibilityParameterBridgeClasses(SDK, true, true, "V", false);
        auto &Child = Input[0];
        auto &Base = Input[1];
        auto &Bridge = Child.methods[0];
        if (Mutation == 0)
          Child.generic_signature = "Lfixture/Base<Lfixture/Child;Lfixture/"
                                    "Child$Right;Lfixture/Child$Right;>;";
        else if (Mutation == 1)
          Child.generic_signature = "Lfixture/Base<Lfixture/Child;Lfixture/"
                                    "Missing;Lfixture/Child$Right;>;";
        else if (Mutation == 2)
          Child.generic_signature = "Lfixture/Base<Lfixture/Child;+Lfixture/"
                                    "Child$Left;Lfixture/Child$Right;>;";
        else if (Mutation == 3)
          Child.generic_signature = "Lfixture/Base;";
        else if (Mutation == 4)
          Child.generic_signature =
              "<U:Ljava/lang/Object;>" + *Child.generic_signature;
        else if (Mutation == 5)
          Bridge.instructions[0].opcode = "invoke-virtual/range";
        else if (Mutation == 6)
          Bridge.instructions[0].registers.front() =
              Bridge.instructions[0].registers.back();
        else if (Mutation == 7)
          Bridge.instructions.insert(
              Bridge.instructions.begin(),
              op(0, "check-cast", {77}, {}, Input[5].name));
        else if (Mutation == 8)
          Bridge.deprecated = true;
        else if (Mutation == 9)
          Bridge.parameter_metadata->front().access = 0;
        else if (Mutation == 10)
          Base.methods[0].access = {"private"};
        else if (Mutation == 11)
          Base.methods[0].declared_throws = {"Ljava/io/IOException;"};
        else if (Mutation == 12)
          Bridge.instructions[0].registers.back() =
              Bridge.instructions[0]
                  .registers[Bridge.instructions[0].registers.size() - 2];
        else if (Mutation == 13) {
          auto Other = Base.methods[0];
          Other.reference.returns = "Ljava/lang/Object;";
          Base.methods.push_back(Other);
        } else if (Mutation == 14)
          Base.access.insert("public");
        else if (Mutation == 15)
          Base.methods[0].generic_signature =
              "<U:Ljava/lang/Object;>" + *Base.methods[0].generic_signature;
        else if (Mutation == 16)
          Input[4].generic_signature =
              "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
        else if (Mutation == 17) {
          auto Final = Base.methods[0];
          Final.reference.owner = Input[2].name;
          Final.generic_signature.reset();
          Final.access.insert("final");
          Input[2].methods.push_back(Final);
        } else if (Mutation == 18) {
          auto Missing = method("missing", {}, "V", 0, {});
          Missing.access = {"public", "abstract"};
          Missing.reference.owner = Input[2].name;
          Input[2].methods.push_back(Missing);
          Input[2].access.insert("abstract");
        } else if (Mutation == 19)
          Input[2].superclass = Base.name;
        else if (Mutation == 20)
          Input[2].generic_signature =
              "<U:Ljava/lang/Object;>Ljava/lang/Object;";
        else
          Input[7].methods[0].reference.parameters[1] = Input[3].name;
        Budget B;
        EXPECT_THROW(
            recoverJava(literalTokenConstructorInput(Input, Route, B), B),
            std::runtime_error);
      }
}

namespace {
std::vector<Class> nestedAnonymousAllocationClasses(bool SDK, bool Range,
                                                    bool Wide, bool Reverse,
                                                    bool Generic,
                                                    unsigned Prefix) {
  auto Input = anonymousCreatorClasses();
  auto &Contract = Input[0];
  auto &Host = Input[1];
  auto &Anonymous = Input[2];
  auto Init = method("<init>", {}, "V", 1,
                     {op(0, "invoke-direct", {0}, {},
                         MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
                      op(3, "return-void")});
  Init.access = {"public", "constructor"};
  auto Context = klass("Lfixture/Context;", {Init});
  std::vector<std::string> Parameters{Context.name, Contract.name};
  if (Reverse)
    std::reverse(Parameters.begin(), Parameters.end());
  if (Wide)
    Parameters.push_back("J");
  auto TargetInit = Init;
  TargetInit.reference.parameters = Parameters;
  TargetInit.registers = Wide ? 5 : 3;
  auto Target = klass("Lfixture/Target;", {TargetInit});
  auto Read =
      method("context", {}, Context.name, 1,
             {op(0, "const/4", {0}, int64_t(0)), op(1, "return-object", {0})});
  Read.reference.owner = Host.name;
  Host.methods.push_back(Read);
  Init.reference.owner = Host.name;
  Host.methods.push_back(Init);
  Host.fields[0].reference.type = Target.name;
  Host.fields[0].access = {"public", "static"};
  FieldRef Current{Host.name, "current", Context.name};
  if (Prefix == 1)
    Host.fields.push_back({Current, {"public", "static"}, {}});
  if (Generic) {
    Host.access.insert("abstract");
    Host.generic_signature = "<S:Lfixture/Host<TS;>;>Ljava/lang/Object;";
  }
  // The original anonymous constructor remains adjacent and uses its unique
  // low-register allocation. Outer range calls retain their exact word frame.
  const unsigned ContextReg = Reverse ? 2 : 1;
  const unsigned AnonymousReg = Reverse ? 1 : 2;
  std::vector<Instruction> Code{op(0, "new-instance", {0}, {}, Target.name)};
  unsigned PC = 2;
  if (Prefix == 0) {
    Code.push_back(op(PC, "invoke-static", {}, {}, Host.methods[1].reference));
    PC += 3;
    Code.push_back(op(PC++, "move-result-object", {ContextReg}));
  } else if (Prefix == 1) {
    Code.push_back(op(PC, "sget-object", {ContextReg}, {}, Current));
    PC += 2;
  } else
    Code.push_back(op(PC++, "const/4", {ContextReg}, int64_t(0)));
  Code.push_back(op(PC, "new-instance", {AnonymousReg}, {}, Anonymous.name));
  PC += 2;
  Code.push_back(op(PC, "invoke-direct", {AnonymousReg}, {},
                    Anonymous.methods[0].reference));
  PC += 3;
  if (Wide) {
    Code.push_back(op(PC, "const-wide/16", {3}, int64_t(9)));
    PC += 2;
  }
  Code.push_back(op(PC, Range ? "invoke-direct/range" : "invoke-direct",
                    Wide ? std::vector<unsigned>{0, 1, 2, 3, 4}
                         : std::vector<unsigned>{0, 1, 2},
                    {}, Target.methods[0].reference));
  PC += 3;
  Code.push_back(op(PC, "sput-object", {0}, {}, Host.fields[0].reference));
  PC += 2;
  Code.push_back(op(PC++, "return-void"));
  Host.methods[0].instructions = std::move(Code);
  Host.methods[0].registers = Wide ? 5 : 3;
  Host.methods[0].code_end = PC;
  if (SDK)
    for (auto *C : {&Contract, &Context, &Target}) {
      C->external = true;
      for (auto &M : C->methods) {
        M.instructions.clear();
        M.registers = M.code_end = 0;
      }
    }
  Input.push_back(std::move(Context));
  Input.push_back(std::move(Target));
  return Input;
}
} // namespace

