          Facade.enclosing = Input[7].name;
          for (auto &M : Facade.methods)
            M.reference.owner = Facade.name;
          break;
        case 10:
          Hidden.access.insert("final");
          break;
        case 11:
          Input[2].access = {"private"};
          break;
        case 12:
          Target.access = {"private"};
          break;
        case 13:
          Target.access.insert("static");
          break;
        case 14:
          Target.access.insert("final");
          break;
        case 15:
          Target.access.insert("native");
