std::vector<Class>
instanceArrayCarrierVoidClasses(bool SDK, bool Range, bool ArrayFirst,
                                unsigned Rank, bool CarrierInterface,
                                bool Member, bool Interface) {
  auto Input =
      anchoredArrayVoidClasses(2, Range, ArrayFirst, Rank, CarrierInterface);
  auto &Owner = Input[0];
  auto Call = Owner.methods.back();
  Owner.methods.pop_back();
  Owner.methods[0].access = {"public"};
  if (Interface) {
    Owner.access = {"public", "abstract", "interface"};
    Owner.methods[0].access.insert("abstract");
  }
  Call.instructions[0].opcode =
      Interface ? (Range ? "invoke-interface/range" : "invoke-interface")
                : (Range ? "invoke-virtual/range" : "invoke-virtual");
  Owner.external = SDK;
  Input[1].external = SDK;
  if (SDK || Interface) {
    Owner.methods[0].instructions.clear();
    Owner.methods[0].registers = Owner.methods[0].code_end = 0;
  }
  Input.push_back(klass("Lfixture/Core;", {Call}));
  if (Member) {
    const auto Old = Input[1].name;
    const std::string Name = "Lfixture/Contract$Carrier;";
    Input[1].name = Name;
    Input[1].inner_class_present = true;
    Input[1].inner_name = "Carrier";
    Input[1].enclosing = "Lfixture/Contract;";
    Input[1].inner_access = Input[1].access;
    Input[1].inner_access.insert("static");
    for (auto &C : Input)
      for (auto &M : C.methods) {
        for (auto &P : M.reference.parameters)
          if (P == Old)
            P = Name;
        if (M.generic_signature) {
          auto &S = *M.generic_signature;
          const auto At = S.find("Lfixture/Carrier<");
          if (At != std::string::npos)
            S.replace(At, std::string("Lfixture/Carrier<").size(),
                      "Lfixture/Contract$Carrier<");
        }
        for (auto &I : M.instructions)
          if (auto *Ref = std::get_if<MethodRef>(&I.reference))
            for (auto &P : Ref->parameters)
              if (P == Old)
                P = Name;
      }
    auto Contract = klass("Lfixture/Contract;");
    Contract.external = SDK;
    Input.push_back(std::move(Contract));
  }
  return Input;
}

