          Input[1].generic_signature =
              "<E:Ljava/lang/CharSequence;>Ljava/lang/Object;";
          break;
        case 6:
          Input[1].generic_signature =
              "<E:Ljava/lang/Object;F:Ljava/lang/Object;>Ljava/lang/Object;";
          break;
        case 7:
          Input[1].access.erase("public");
          Input[1].inner_access.erase("public");
          break;
        case 8:
          Input[1].inner_access.erase("static");
          break;
        case 9:
          Input.pop_back();
          break;
        case 10:
          Apply.declared_throws = {"Ljava/lang/Exception;"};
          break;
        case 11:
          Apply.access.insert("bridge");
          break;
        case 12:
          Apply.access.insert("native");
          break;
        case 13:
          Apply.access.insert("abstract");
