        case 14:
          Apply.generic_signature =
              "<T:Ljava/lang/Object;>([TQ;Lfixture/Contract$Carrier<TT;>;)V";
          Owner.generic_signature =
              "<Q:Ljava/lang/CharSequence;>Ljava/lang/Object;";
          break;
        case 15:
          Call.instructions[0].opcode = "invoke-static";
          break;
        case 16:
          Call.instructions[0].opcode = "invoke-interface";
          break;
        case 17:
          Call.instructions[0].registers[0] = 1;
          break;
        case 18:
          std::swap(Call.instructions[0].registers[1],
                    Call.instructions[0].registers[2]);
          break;
        case 19:
          Call.instructions[0].registers.pop_back();
          break;
        case 20:
          replace("[TT;", "[[TT;");
          break;
        case 21:
          replace(")V", ")TT;");
