namespace {
std::vector<Class> objectPrefixDefaultClasses(bool External, bool Range,
                                              bool Alias, bool Package,
                                              bool Nested) {
  const std::string Name = Nested ? "Lfixture/Host$Owner;" : "Lfixture/Owner;";
  const FieldRef Flag{Name, "zeroFlag", "Z"}, Bits{Name, "zeroBits", "J"},
      Cache{Name, "zeroArray", "[Ljava/lang/Object;"},
      Payload{Name, "payload", "Ljava/lang/Object;"};
  auto Check = method("check", {"Ljava/lang/Object;", "Ljava/lang/String;"},
                      "V", 2, {op(0, "return-void")});
  auto Guard = klass("Lfixture/Guard;", {Check});
  Guard.external = External;
  if (External) {
    Guard.methods[0].instructions.clear();
    Guard.methods[0].registers = Guard.methods[0].code_end = 0;
  }
  auto Init = method(
      "<init>", {"Ljava/lang/Object;"}, "V", 5,
      {Alias ? op(0, "move-object", {2, 3}) : op(0, "nop"),
       op(1, "move-object", {0, 4}),
       op(2, "const-string", {1}, std::string("owned")),
       op(3, Range ? "invoke-static/range" : "invoke-static", {0, 1}, {},
          Guard.methods[0].reference),
       op(4, Range ? "invoke-direct/range" : "invoke-direct", {Alias ? 2u : 3u},
          {}, MethodRef{"Ljava/lang/Object;", "<init>", {}, "V"}),
       op(5, "iput-object", {4, 3}, {}, Payload), op(6, "return-void")});
  Init.access = {"public", "constructor"};
  auto Read =
      method("flag", {}, "Z", 2,
             {op(0, "iget-boolean", {0, 1}, {}, Flag), op(1, "return", {0})});
  Read.access = {"public"};
  auto Owner = klass(Name, {Init, Read});
  Owner.access = {"final"};
  if (!Package)
    Owner.access.insert("public");
  Owner.fields = {{Flag, {"private", "final"}, {}},
                  {Bits, {"private", "final"}, {}},
                  {Cache, {"private", "final"}, {}},
                  {Payload, {"private", "final"}, {}}};
  std::vector<Class> Input{Owner, Guard};
  if (Nested) {
    auto &C = Input[0];
    C.enclosing = "Lfixture/Host;";
    C.inner_class_present = true;
    C.inner_name = "Owner";
    C.inner_access = C.access;
    C.inner_access.insert("static");
    Input.push_back(klass("Lfixture/Host;"));
  }
  return Input;
}
} // namespace

TEST(MobileDalvikJava, ObjectPrefixDefaultsReuseLinearUnobservedReceiverProof) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool Alias : {false, true})
        for (bool Package : {false, true})
          for (bool Nested : {false, true})
            for (unsigned Route = 0; Route < 3; ++Route) {
              SCOPED_TRACE(::testing::PrintToString(
                  std::tuple{External, Range, Alias, Package, Nested, Route}));
              auto Input = objectPrefixDefaultClasses(External, Range, Alias,
                                                      Package, Nested);
              const auto Ref = Input[0].methods[0].reference;
              Budget B;
              const auto Classes =
                  literalTokenConstructorInput(Input, Route, B);
              const auto Plans = validateGenericSignatures(Classes, B);
              ASSERT_TRUE(Plans.constructor_super_prologues.contains(Ref));
              const auto &Proof = Plans.constructor_super_prologues.at(Ref);
              const MethodRef Object{"Ljava/lang/Object;", "<init>", {}, "V"};
              EXPECT_EQ(Proof.target, Object);
              EXPECT_EQ(Proof.call_pc, 4u);
              EXPECT_FALSE(Proof.requires_dispatch);
              const auto R = recoverJava(Classes, B);
              EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
              EXPECT_EQ(R.getInteger("minimum_java_release"), 25);
              EXPECT_FALSE(R.getArray("class_source_bindings"));
              EXPECT_FALSE(R.getArray("field_source_bindings"));
              EXPECT_FALSE(R.getArray("generic_signature_projections"));
              const auto *Rows =
                  R.getArray("default_instance_final_initializers");
              ASSERT_NE(Rows, nullptr);
              ASSERT_EQ(Rows->size(), 3u);
              std::set<std::string> Seen;
              for (const auto &Value : *Rows) {
                const auto &Row = *Value.getAsObject();
                EXPECT_EQ(Row.getString("class"), Ref.owner);
                EXPECT_EQ(Row.getInteger("original_write_count"), 0);
                EXPECT_EQ(Row.getString("ConstantValue"), "absent");
                EXPECT_EQ(Row.getString("initialization_point"),
                          "after-Object-constructor-before-original-body");
                const auto Field = Row.getString("field");
                ASSERT_TRUE(Field);
                Seen.insert(Field->str());
                const std::string Literal = *Field == "zeroFlag"   ? "false"
                                            : *Field == "zeroBits" ? "0L"
                                                                   : "null";
                EXPECT_EQ(Row.getString("source_initializer"),
                          "(null == null ? " + Literal + " : " + Literal + ")");
              }
              EXPECT_EQ(Seen, (std::set<std::string>{"zeroFlag", "zeroBits",
                                                     "zeroArray"}));
            }
}

TEST(MobileDalvikJava,
     ObjectPrefixDefaultsRejectEscapesStoresAndInvalidPrefixes) {
  for (bool External : {false, true})
    for (unsigned Route = 0; Route < 3; ++Route)
      for (unsigned Mutation = 0; Mutation < 20; ++Mutation) {
        SCOPED_TRACE(
            ::testing::PrintToString(std::tuple{External, Route, Mutation}));
        auto Input =
            objectPrefixDefaultClasses(External, false, true, true, false);
        auto &C = Input[0];
        auto &M = C.methods[0];
        auto &Code = M.instructions;
        switch (Mutation) {
        case 0:
          Code[3].registers[0] = 3;
          break;
        case 1:
          Code[3].registers[0] = 2;
          break;
        case 2:
          Code[1].registers[0] = 3;
          break;
        case 3:
          std::get<MethodRef>(Code[4].reference).owner = "Lfixture/Missing;";
          break;
        case 4:
          Code[4].opcode = "invoke-virtual";
          break;
        case 5:
          Code[4].registers = {4};
          break;
        case 6:
          Input[1].methods[0].access = {"private", "static"};
          break;
        case 7:
          Input[1].methods[0].access.erase("static");
          break;
        case 8:
          Input[1].methods.clear();
          break;
        case 9:
        case 10:
        case 11: {
          auto Field = C.fields[0].reference;
          if (Mutation == 10) {
            auto Child = klass("Lfixture/Child;");
            Child.superclass = C.name;
            C.access.erase("final");
            C.fields[0].access = {"public", "final"};
            Field.owner = Child.name;
            Input.push_back(Child);
          } else if (Mutation == 11)
            Field.owner = "Lfixture/Missing;";
          auto Write = method(
              "write", {Field.owner, "Z"}, "V", 2,
              {op(0, "iput-boolean", {1, 0}, {}, Field), op(1, "return-void")});
          Input.push_back(klass("Lfixture/Writer;", {Write}));
          break;
        }
        case 12:
          Code[0] = op(0, "goto", {}, {}, {}, 1);
          Code[4].registers = {3};
          break;
        case 13:
          M.tries = {{1, 4, {{std::nullopt, 7}}}};
          Code.push_back(op(7, "move-exception", {0}));
          Code.push_back(op(8, "throw", {0}));
          M.code_end = 9;
          break;
        case 14:
          Code.back().opcode = "return-object";
          Code.back().registers = {4};
          break;
        case 15:
          C.methods.erase(C.methods.begin());
          break;
        case 16:
          C.fields[0].reference.type = "V";
          break;
        case 17:
          C.enclosing = "Lfixture/Host;";
          C.inner_class_present = true;
          C.inner_name = "Owner";
          C.inner_access = {"final"};
          Input.push_back(klass("Lfixture/Host;"));
          break;
        case 18: {
          auto Call = std::get<MethodRef>(Code[3].reference);
          Call.parameters = {"J"};
          Input[1].methods[0].reference = Call;
          Code[3] = op(3, "invoke-static", {1, 2}, {}, Call);
          break;
        }
        case 19:
          M.generic_signature = "(TUnknown;)V";
          break;
        }
        Budget B;
        EXPECT_THROW(
            recoverJava(literalTokenConstructorInput(Input, Route, B), B),
            std::runtime_error);
      }
}

