TEST(MobileDalvikJava, DoubleComparisonCarriersRetainTypedWideDispatch) {
  for (bool External : {false, true})
    for (bool Range : {false, true})
      for (bool NamedAccessor : {false, true})
        for (unsigned Route = 0; Route < 3; ++Route) {
          SCOPED_TRACE(::testing::PrintToString(
              std::tuple{External, Range, NamedAccessor, Route}));
          auto Input =
              doubleComparisonCarrierClasses(External, Range, NamedAccessor);
          const auto Bridge = Input[0].methods[0].reference;
          const auto Target = Input[0].methods[1].reference;
          const auto Unbox = Input[0].methods[2].reference;
          const auto Original = Input[0].generic_signature;
          Budget B;
          const auto Classes =
              wideCarrierAccessorMap(std::move(Input), Route, B);
          const auto Plans = validateGenericSignatures(Classes, B);
          ASSERT_TRUE(Plans.value_carrier_bridges.contains(Bridge));
          const auto &Proof = Plans.value_carrier_bridges.at(Bridge);
          EXPECT_EQ(Proof.target, Target);
          EXPECT_EQ(Proof.unbox, std::vector<MethodRef>{Unbox});
          const auto R = recoverJava(Classes, B);
          EXPECT_EQ(R.getInteger("unrecovered_method_count"), 0);
          EXPECT_EQ(R.getInteger("projected_method_count"),
                    NamedAccessor ? 2 : 1);
          EXPECT_EQ(Classes.at(Bridge.owner).generic_signature, Original);
          unsigned Seen = 0;
          for (const auto &V : *R.getArray("methods")) {
            const auto &Row = *V.getAsObject();
            if (Row.getString("identity") != Bridge.identity())
              continue;
            ++Seen;
            EXPECT_EQ(Row.getString("projection_kind"),
                      "value-carrier-interface-bridge");
            EXPECT_EQ(Row.getString("bridge_target"), Target.identity());
            ASSERT_NE(Row.getArray("unbox_methods"), nullptr);
            ASSERT_EQ(Row.getArray("unbox_methods")->size(), 1u);
            EXPECT_EQ(Row.getArray("unbox_methods")->front().getAsString(),
                      Unbox.identity());
          }
          EXPECT_EQ(Seen, 1u);
        }
}

