namespace {
std::vector<Class> inlinedAccessorNameClasses(const std::string &Type,
                                              bool External, bool Collision) {
  auto Input = inlinedCheckedInterfaceClasses(External, true, "I", true);
  auto &Core = Input[1];
  const bool Wide = Type == "J" || Type == "D";
  const unsigned Words = Wide ? 2 : 1;
  const std::string Read = Type == "B"   ? "iget-byte"
                           : Type == "S" ? "iget-short"
                           : Type == "C" ? "iget-char"
                           : Type == "Z" ? "iget-boolean"
                           : Wide        ? "iget-wide"
                                         : "iget";
  const FieldRef Value{Core.name, "payload", Type};
  Core.fields.push_back({Value, {"private"}, {}});
  auto Getter = method("read-owned-inlined", {}, Type, Words + 1,
                       {op(0, Read, {0, Words}, {}, Value),
                        op(1, Wide ? "return-wide" : "return", {0})});
  Getter.reference.owner = Core.name;
  Getter.access = {"public", "final", "synthetic"};
  Core.methods.push_back(Getter);
  const auto Owner = Core.name;
  if (Collision) {
    auto Other = klass("Ldependency/Other;", {Getter});
    Other.external = true;
    Other.methods[0].instructions.clear();
    Other.methods[0].registers = Other.methods[0].code_end = 0;
    Input.push_back(std::move(Other));
  }
  auto ReadGetter =
      method("read", {Owner}, Type, Words + 1,
             {op(0, "invoke-virtual", {Words}, {}, Getter.reference),
              op(1, Wide ? "move-result-wide" : "move-result", {0}),
              op(2, Wide ? "return-wide" : "return", {0})});
  Input.push_back(klass("Lfixture/Reader;", {ReadGetter}));
  return Input;
}
} // namespace

