namespace {
std::vector<Class> boxedResultEntryNameClasses(const std::string &Type,
                                               bool External, bool Effects,
                                               unsigned Scope, bool Collision) {
  auto Input = boxedGenericResultClasses(Type, External, Effects);
  auto &Core = Input[1];
  const std::string Read = Type == "Z"                  ? "iget-boolean"
                           : Type == "B"                ? "iget-byte"
                           : Type == "S"                ? "iget-short"
                           : Type == "C"                ? "iget-char"
                           : Type == "J" || Type == "D" ? "iget-wide"
                                                        : "iget";
  Core.methods[0].instructions[Effects ? 3 : 0].opcode = Read;
  Core.methods[3].instructions[1].opcode = "iput" + Read.substr(4);
  Core.methods[0].reference.name = "read-owned-result";
  Core.methods[1].instructions[0].reference = Core.methods[0].reference;
  auto Marker = klass("Lfixture/Marker;");
  Marker.access = {"public", "abstract", "interface"};
  Marker.external = External;
  Core.interfaces.push_back(Marker.name);
  *Core.generic_signature += Marker.name;
  if (Scope)
    Core.access = {"final"};
  if (Scope == 2) {
    const auto Before = Core.name;
    Core.name = "Lfixture/Host$Entry;";
    Core.enclosing = "Lfixture/Host;";
    Core.inner_name = "Entry";
    Core.inner_class_present = true;
    Core.inner_access = {"private", "static", "final"};
    for (auto &C : Input) {
      for (auto &F : C.fields)
        if (F.reference.owner == Before)
          F.reference.owner = Core.name;
      for (auto &M : C.methods) {
        if (M.reference.owner == Before)
          M.reference.owner = Core.name;
        for (auto &O : M.instructions) {
          if (auto *F = std::get_if<FieldRef>(&O.reference);
              F && F->owner == Before)
            F->owner = Core.name;
          if (auto *R = std::get_if<MethodRef>(&O.reference);
              R && R->owner == Before)
            R->owner = Core.name;
        }
      }
    }
  }
  auto OtherEntry = Core.methods[0];
  Input.push_back(Marker);
  if (Scope == 2)
    Input.push_back(klass("Lfixture/Host;"));
  if (Collision) {
    auto Other = klass("Ldependency/Other;", {OtherEntry});
    Other.external = true;
    Other.methods[0].instructions.clear();
    Other.methods[0].registers = Other.methods[0].code_end = 0;
    Input.push_back(std::move(Other));
  }
  return Input;
}
} // namespace

