                SCOPED_TRACE(::testing::PrintToString(std::tuple{
                    External, Facade, Range, Package, Text, Scalar, Route}));
                auto Input = arrayFixedReferenceResultClasses(
                    External, Facade, Range, Package, Text, Scalar);
                const auto Ref = Input[1].methods[0].reference;
